-- Feature References: THREAT01 (Threat Management), SEC01 (Security), RISK01 (Risk Management)
--================================================================================================
CREATE TYPE socialcandor_schema.threat_level AS ENUM (
    'LOW',                   -- Low threat level
    'MEDIUM',                -- Medium threat level
    'HIGH',                  -- High threat level
    'SEVERE',                -- Severe threat level
    'CRITICAL'               -- Critical threat level
);
COMMENT ON TYPE socialcandor_schema.threat_level IS 'Defines security threat severity levels';

--==================================================================================================================================


--================================================================================================
-- Table: 1 - users
-- Description: Core user accounts with authentication and profile management
-- Business Case: Central identity management for all platform users with GDPR-compliant data
-- handling, multi-factor authentication support, and comprehensive audit trails. Enables secure
-- user lifecycle management from registration through deletion with privacy-by-design principles.
-- KPIs: User registration completion rate, authentication success rate, account recovery time,
-- GDPR DSAR fulfillment time, authentication latency at p99
-- Feature Reference: USER01 (User Management), SEC01 (Authentication), PRV01 (GDPR Compliance)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.users (
    -- Primary key with cryptographic-grade uniqueness
    user_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identity attributes with strict validation
    username VARCHAR(50) NOT NULL,
    email VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,

    -- Profile information
    first_name VARCHAR(100),
    last_name VARCHAR(100),
    display_name VARCHAR(100),
    avatar_url VARCHAR(500),
    cover_image_url VARCHAR(500),
    bio TEXT,
    website VARCHAR(255),

    -- Demographic information
    date_of_birth DATE,
    gender VARCHAR(20),
    preferred_language VARCHAR(10) DEFAULT 'en',
    timezone VARCHAR(50) DEFAULT 'UTC',

    -- Contact information
    phone_number VARCHAR(20),
    registration_country VARCHAR(3),
    registration_ip INET,

    -- Account status and security
    status socialcandor_schema.user_status NOT NULL DEFAULT 'PENDING_ACTIVATION',
    email_verified BOOLEAN DEFAULT FALSE,
    phone_verified BOOLEAN DEFAULT FALSE,
    mfa_enabled BOOLEAN DEFAULT FALSE,
    mfa_secret VARCHAR(255),
    mfa_backup_codes TEXT[],

    -- Authentication tracking
    last_login_at TIMESTAMP WITH TIME ZONE,
    last_active_at TIMESTAMP WITH TIME ZONE,
    last_password_change_at TIMESTAMP WITH TIME ZONE,
    login_count INTEGER DEFAULT 0,
    failed_login_attempts INTEGER DEFAULT 0,
    account_locked_until TIMESTAMP WITH TIME ZONE,

    -- Trust and reputation
    trust_score NUMERIC(5,2) DEFAULT 0 CHECK (trust_score >= 0 AND trust_score <= 100),
    verification_level VARCHAR(20) DEFAULT 'NONE',
    reputation_score INTEGER DEFAULT 0,

    -- Privacy and preferences
    privacy_settings JSONB DEFAULT '{}',
    preferences JSONB DEFAULT '{}',
    notification_settings JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID DEFAULT uuid_nil(),
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,

    -- Additional metadata
    metadata JSONB DEFAULT '{}',
    tags TEXT[]
);

--================================================================================================
-- Table: 2 - users_sessions
-- Description: User session tracking with security and analytics capabilities
-- Business Case: Enables secure session management with device fingerprinting, location tracking,
-- and anomaly detection. Supports concurrent session limits, automatic timeout, and security
-- alerts for suspicious login patterns. Critical for account security and user experience.
-- KPIs: Session success rate, average session duration, concurrent session count, security
-- incident detection rate, session timeout compliance
-- Feature Reference: SEC02 (Session Management), ANL01 (User Analytics), MON01 (Security Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.users_sessions (
    -- Primary session identifier
    session_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User reference
    user_id UUID NOT NULL,

    -- Token management
    session_token VARCHAR(255) NOT NULL,
    refresh_token VARCHAR(255),
    token_expires_at TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Device information
    device_type VARCHAR(50),
    device_name VARCHAR(100),
    device_fingerprint VARCHAR(255),
    browser VARCHAR(100),
    browser_version VARCHAR(50),
    os VARCHAR(100),
    os_version VARCHAR(50),

    -- Location and network
    ip_address INET NOT NULL,
    ip_country VARCHAR(3),
    ip_city VARCHAR(100),
    latitude NUMERIC(10,8),
    longitude NUMERIC(11,8),
    user_agent TEXT,

    -- Authentication details
    login_method VARCHAR(50),
    login_provider VARCHAR(50),
    authentication_timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Session state
    is_active BOOLEAN DEFAULT TRUE,
    is_current BOOLEAN DEFAULT FALSE,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    last_activity_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_reason VARCHAR(100),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 3 - posts
-- Description: Primary content repository for user-generated content with rich metadata
-- Business Case: Centralized content storage supporting rich media, privacy controls, engagement
-- tracking, and algorithmic feed ranking. Enables content monetization, viral detection, and
-- creator economy features through trending scores and engagement velocity metrics.
-- KPIs: Post creation rate, engagement rate per post, content moderation accuracy, viral content
-- detection rate, content discovery success rate
-- Feature Reference: CNT01 (Content Management), ENG01 (Engagement), REC01 (Recommendations)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.posts (
    -- Primary content identifier
    post_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Author reference
    user_id UUID NOT NULL,

    -- Content data
    content_text TEXT,
    content_type socialcandor_schema.content_type NOT NULL DEFAULT 'TEXT',
    content_language VARCHAR(10) DEFAULT 'en',

    -- Visibility and privacy
    visibility VARCHAR(20) DEFAULT 'PUBLIC',
    audience_list UUID[],

    -- Location context
    location_coordinates GEOGRAPHY(POINT, 4326),
    location_name VARCHAR(255),
    location_privacy VARCHAR(20) DEFAULT 'PUBLIC',

    -- Scheduling and publishing
    is_scheduled BOOLEAN DEFAULT FALSE,
    scheduled_for TIMESTAMP WITH TIME ZONE,
    published_at TIMESTAMP WITH TIME ZONE,
    edited_at TIMESTAMP WITH TIME ZONE,
    edit_count INTEGER DEFAULT 0,

    -- Post state
    is_pinned BOOLEAN DEFAULT FALSE,
    pinned_until TIMESTAMP WITH TIME ZONE,
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,
    is_deleted BOOLEAN DEFAULT FALSE,
    deleted_at TIMESTAMP WITH TIME ZONE,

    -- Engagement metrics
    like_count INTEGER DEFAULT 0,
    comment_count INTEGER DEFAULT 0,
    share_count INTEGER DEFAULT 0,
    view_count INTEGER DEFAULT 0,
    trending_score NUMERIC(10,4) DEFAULT 0,
    engagement_velocity NUMERIC(10,4) DEFAULT 0,
    impression_count INTEGER DEFAULT 0,
    reach_count INTEGER DEFAULT 0,

    -- Moderation
    moderation_status VARCHAR(20) DEFAULT 'PENDING',
    moderation_reason TEXT,
    moderated_at TIMESTAMP WITH TIME ZONE,
    moderated_by UUID,

    -- Content integrity
    content_hash VARCHAR(64),
    duplicate_check_status VARCHAR(20),

    -- Social features
    tags TEXT[],
    mentions UUID[],
    hashtags TEXT[],

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 4 - posts_media
-- Description: Multimedia attachments with format normalization and CDN integration
-- Business Case: Stores media files linked to posts with automatic thumbnail generation, format
-- optimization, and CDN delivery. Ensures media integrity, accessibility compliance, and cross-
-- platform rendering consistency while optimizing delivery performance.
-- KPIs: Media upload success rate, processing time per file, CDN cache hit rate, accessibility
-- compliance rate, storage optimization ratio
-- Feature Reference: MED01 (Media Processing), ACC01 (Accessibility), CDN01 (Content Delivery)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.posts_media (
    -- Primary media identifier
    media_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    post_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Media classification
    media_type VARCHAR(50) NOT NULL,
    media_subtype VARCHAR(50),

    -- File information
    file_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(500) NOT NULL,
    file_size_bytes BIGINT NOT NULL,
    mime_type VARCHAR(100) NOT NULL,

    -- Dimensions and duration
    width INTEGER,
    height INTEGER,
    duration_seconds NUMERIC(10,2),

    -- CDN and delivery
    thumbnail_url VARCHAR(500),
    cdn_url VARCHAR(500),
    original_url VARCHAR(500),

    -- Accessibility
    alt_text TEXT,
    generated_alt_text VARCHAR(500),
    alt_text_confidence NUMERIC(5,2),
    caption TEXT,

    -- Media state
    is_primary BOOLEAN DEFAULT FALSE,
    display_order INTEGER DEFAULT 0,
    processing_status VARCHAR(20) DEFAULT 'PENDING',
    processing_error TEXT,

    -- Metadata
    exif_data JSONB DEFAULT '{}',
    keywords VARCHAR(100)[],

    -- Copyright and licensing
    copyright_holder VARCHAR(255),
    license_type VARCHAR(50),
    is_stock_media BOOLEAN DEFAULT FALSE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 5 - posts_comments
-- Description: Hierarchical comment system with threaded conversations and moderation
-- Business Case: Enables rich discussion threads with nested replies, voting, and moderation.
-- Supports toxic content detection, sentiment analysis, and conversation quality scoring.
-- Critical for community engagement and content discovery through comment activity.
-- KPIs: Comment rate per post, reply depth average, toxic content detection rate, comment
-- engagement rate, moderation response time
-- Feature Reference: ENG02 (Comments), MOD01 (Content Moderation), ANL03 (Sentiment Analysis)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.posts_comments (
    -- Primary comment identifier
    comment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    post_id UUID NOT NULL,
    user_id UUID NOT NULL,
    parent_comment_id UUID,

    -- Comment content
    comment_text TEXT NOT NULL,
    comment_language VARCHAR(10) DEFAULT 'en',

    -- Threading structure
    comment_depth INTEGER DEFAULT 0,
    thread_path LTREE,
    sibling_order INTEGER DEFAULT 0,

    -- Engagement metrics
    like_count INTEGER DEFAULT 0,
    reply_count INTEGER DEFAULT 0,
    report_count INTEGER DEFAULT 0,

    -- Edit history
