    moderation_reason TEXT,
    moderated_at TIMESTAMP WITH TIME ZONE,
    moderated_by UUID,

    -- Content analysis
    sentiment_score NUMERIC(3,2),
    toxicity_score NUMERIC(3,2),
    spam_score NUMERIC(3,2),

    -- Social features
    mentions UUID[],
    hashtags TEXT[],

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 6 - friends
-- Description: Bidirectional friend relationships with status lifecycle management
-- Business Case: Manages mutual friendship connections with request/approval workflow. Supports
-- friendship strength calculation, interaction tracking, and relationship decay modeling.
-- Enables social graph analysis and "People You May Know" recommendations.
-- KPIs: Friend request acceptance rate, mutual friendship rate, relationship strength accuracy,
-- friend suggestion click-through rate, friendship retention rate
-- Feature Reference: REL01 (Friendships), NET01 (Social Graph), REC02 (Friend Recommendations)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.friends (
    -- Primary friendship identifier
    friendship_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User references (bidirectional)
    user_id UUID NOT NULL,
    friend_user_id UUID NOT NULL,

    -- Relationship status
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    is_mutual BOOLEAN DEFAULT FALSE,

    -- Request lifecycle
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    requested_by UUID,
    accepted_at TIMESTAMP WITH TIME ZONE,
    accepted_by UUID,
    rejected_at TIMESTAMP WITH TIME ZONE,
    cancelled_at TIMESTAMP WITH TIME ZONE,
    blocked_at TIMESTAMP WITH TIME ZONE,

    -- Interaction tracking
    last_interaction_at TIMESTAMP WITH TIME ZONE,
    interaction_count INTEGER DEFAULT 0,

    -- Relationship metrics
    strength_score NUMERIC(5,2) DEFAULT 0,
    mutual_friends_count INTEGER DEFAULT 0,
    relationship_source VARCHAR(50),

    -- Friendship features
    is_favorite BOOLEAN DEFAULT FALSE,
    friend_list VARCHAR(50),
    custom_nickname VARCHAR(100),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 7 - followings
