    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 8 - conversations
-- Description: Unified messaging container for 1:1 and group chats
-- Business Case: Supports both individual and group conversations with rich metadata and
-- synchronization capabilities. Provides foundation for real-time messaging infrastructure
-- with end-to-end encryption key management and message delivery tracking.
-- KPIs: Message delivery rate, conversation response time, active conversation rate, encryption
-- compliance rate, message read rate
-- Feature Reference: MSG01 (Messaging), ENC01 (Encryption), SYNC01 (Synchronization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.conversations (
    -- Primary conversation identifier
    conversation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Conversation type
