    conversation_name VARCHAR(255),

    -- Ownership
    creator_user_id UUID NOT NULL,
    is_group BOOLEAN DEFAULT FALSE,
    max_participants INTEGER DEFAULT 2,
    current_participant_count INTEGER DEFAULT 0,

    -- Security
    encryption_enabled BOOLEAN DEFAULT TRUE,
    encryption_key_id UUID,
    encryption_algorithm VARCHAR(50),

    -- Last message preview
    last_message_at TIMESTAMP WITH TIME ZONE,
    last_message_preview TEXT,
    last_message_sender_id UUID,

    -- Conversation state
    unread_count INTEGER DEFAULT 0,
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,
    archived_by UUID,
    is_muted BOOLEAN DEFAULT FALSE,
    muted_until TIMESTAMP WITH TIME ZONE,
    is_pinned BOOLEAN DEFAULT FALSE,
    pinned_at TIMESTAMP WITH TIME ZONE,

    -- Group features
    group_avatar_url VARCHAR(500),
    group_description TEXT,
    join_approval_required BOOLEAN DEFAULT FALSE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    metadata JSONB DEFAULT '{}',
    settings JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 9 - conversations_messages
-- Description: Message content storage with delivery and read receipt tracking
-- Business Case: Stores message content with delivery/read receipts, edit history, and media
-- attachments. Supports message searchability through full-text indexing while maintaining
-- GDPR-compliant deletion capabilities and end-to-end encryption support.
-- KPIs: Message delivery success rate, read receipt rate, message edit rate, search success
-- rate, encryption compliance rate
-- Feature Reference: MSG02 (Message Storage), SRCH01 (Search), GDPR01 (Data Deletion)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.conversations_messages (
    -- Primary message identifier
    message_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    conversation_id UUID NOT NULL,
    sender_user_id UUID NOT NULL,

    -- Message content
    message_type VARCHAR(20) NOT NULL DEFAULT 'TEXT',
    content_text TEXT,
    content_json JSONB DEFAULT '{}',

    -- Attachments
    media_attachments UUID[],
    file_attachments UUID[],

    -- Threading
    reply_to_message_id UUID,
    forwarded_from_message_id UUID,

    -- Edit history
    is_edited BOOLEAN DEFAULT FALSE,
    edited_at TIMESTAMP WITH TIME ZONE,
    edit_history JSONB DEFAULT '[]',

    -- Message state
    is_deleted BOOLEAN DEFAULT FALSE,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    is_starred BOOLEAN DEFAULT FALSE,

    -- Delivery tracking
    delivery_status VARCHAR(20) DEFAULT 'SENT',
    delivered_at TIMESTAMP WITH TIME ZONE,
    read_at TIMESTAMP WITH TIME ZONE,
    read_by UUID[],

    -- Security
    encryption_key_id UUID,
    encrypted_content BYTEA,
    message_hash VARCHAR(64),

    -- Reliability
    idempotency_key VARCHAR(64),
    retry_count INTEGER DEFAULT 0,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 10 - conversations_users
-- Description: Conversation participant tracking with role and status management
-- Business Case: Manages conversation membership with granular permissions and status tracking.
