    can_remove BOOLEAN DEFAULT FALSE,
    can_edit_settings BOOLEAN DEFAULT FALSE,
    can_add_members BOOLEAN DEFAULT FALSE,
    can_delete_messages BOOLEAN DEFAULT FALSE,

    -- Personalization
    custom_nickname VARCHAR(100),
    notifications_enabled BOOLEAN DEFAULT TRUE,
    mention_notifications BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 11 - notifications
-- Description: User notification system with delivery tracking and preferences
-- Business Case: Centralized notification management supporting multiple channels (push, email,
-- in-app). Enables notification batching, scheduling, and user preference compliance. Critical
-- for user engagement and platform communication.
-- KPIs: Notification delivery rate, open rate, click-through rate, preference compliance rate,
-- user satisfaction score
-- Feature Reference: NTFC01 (Notifications), ENG03 (User Engagement), PRF01 (User Preferences)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.notifications (
