    digest_frequency VARCHAR(20),
    digest_time TIME,
    digest_day_of_week INTEGER,

    -- Category-specific settings
    category_preferences JSONB DEFAULT '{}',

    -- Preference state
    is_active BOOLEAN DEFAULT TRUE,
    last_updated_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 13 - groups
-- Description: User group management with membership and content features
-- Business Case: Enables community formation around interests, locations, or purposes. Supports
-- group administration, content moderation, and member management. Critical for community
-- building and user retention through social connections.
-- KPIs: Group creation rate, member retention rate, group activity rate, content engagement
-- rate, admin response time
-- Feature Reference: GRP01 (Groups), COM01 (Community), MOD01 (Moderation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.groups (
    -- Primary group identifier
    group_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Group identification
    group_name VARCHAR(255) NOT NULL,
    group_slug VARCHAR(255) UNIQUE NOT NULL,
    group_tagline VARCHAR(500),

    -- Group classification
    group_type VARCHAR(20) NOT NULL DEFAULT 'PUBLIC',
    group_category VARCHAR(100),
    primary_category VARCHAR(100),
    subcategories VARCHAR(100)[],

    -- Content
    description TEXT,
    rules TEXT[],
    guidelines_url VARCHAR(500),

    -- Ownership
    owner_user_id UUID NOT NULL,
    admin_user_ids UUID[],
    moderator_user_ids UUID[],

    -- Membership metrics
    member_count INTEGER DEFAULT 0,
    pending_member_count INTEGER DEFAULT 0,
    max_members INTEGER,

    -- Activity metrics
    post_count INTEGER DEFAULT 0,
    comment_count INTEGER DEFAULT 0,
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Location
    location_coordinates GEOGRAPHY(POINT, 4326),
    location_name VARCHAR(255),
    is_location_based BOOLEAN DEFAULT FALSE,

    -- Visual identity
    cover_image_url VARCHAR(500),
    avatar_url VARCHAR(500),
    banner_color VARCHAR(7),

    -- Verification
    is_verified BOOLEAN DEFAULT FALSE,
    verification_status VARCHAR(20) DEFAULT 'UNVERIFIED',
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Privacy and access
    privacy_level VARCHAR(20) DEFAULT 'PUBLIC',
    join_approval_required BOOLEAN DEFAULT FALSE,
    post_approval_required BOOLEAN DEFAULT FALSE,
    member_invite_enabled BOOLEAN DEFAULT TRUE,

    -- Features
    messaging_enabled BOOLEAN DEFAULT TRUE,
    events_enabled BOOLEAN DEFAULT TRUE,
    files_enabled BOOLEAN DEFAULT TRUE,
    polls_enabled BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    metadata JSONB DEFAULT '{}',
    settings JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 14 - groups_members
-- Description: Group membership tracking with role and status management
-- Business Case: Manages group membership lifecycle with role-based permissions. Supports
-- member approval workflows, role assignments, and activity tracking. Enables group
-- governance and member engagement analytics.
-- KPIs: Membership acceptance rate, member activity rate, role distribution, member retention
-- rate, group health score
-- Feature Reference: GRP02 (Membership), GOV01 (Group Governance), ENG03 (Member Engagement)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.groups_members (
    -- Primary membership identifier
    membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    group_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Role and permissions
    role VARCHAR(20) NOT NULL DEFAULT 'MEMBER',
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',

    -- Membership lifecycle
    joined_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,
    left_at TIMESTAMP WITH TIME ZONE,
    left_reason VARCHAR(100),

    -- Ban management
    banned_at TIMESTAMP WITH TIME ZONE,
    banned_by UUID,
    ban_reason TEXT,
    ban_expires_at TIMESTAMP WITH TIME ZONE,
    ban_appeal_status VARCHAR(20),

    -- Activity tracking
    post_count INTEGER DEFAULT 0,
    comment_count INTEGER DEFAULT 0,
    reaction_count INTEGER DEFAULT 0,
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Engagement metrics
    engagement_score NUMERIC(5,2) DEFAULT 0,
    contribution_score NUMERIC(5,2) DEFAULT 0,

    -- Notification settings
    notification_settings JSONB DEFAULT '{}',
    email_notifications BOOLEAN DEFAULT TRUE,
    push_notifications BOOLEAN DEFAULT TRUE,

    -- Member features
    is_founding_member BOOLEAN DEFAULT FALSE,
    is_featured BOOLEAN DEFAULT FALSE,
    custom_title VARCHAR(100),
    member_badges UUID[],

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    metadata JSONB DEFAULT '{}'
);

--================================================================================================
-- Table: 15 - pages
-- Description: Business/organization profiles with verification and public content
-- Business Case: Enables businesses and organizations to establish presence on platform.
-- Supports verification workflows, public-facing content streams, and analytics. Critical
-- for monetization and brand engagement features.
-- KPIs: Page creation rate, verification completion rate, follower growth rate, engagement
-- rate, monetization conversion rate
-- Feature Reference: PAG01 (Pages), MON01 (Monetization), VER01 (Verification)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.pages (
    -- Primary page identifier
    page_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    owner_user_id UUID NOT NULL,
    organization_id UUID,

    -- Page identification
    page_name VARCHAR(200) NOT NULL,
    page_slug VARCHAR(200) UNIQUE NOT NULL,
    page_username VARCHAR(100) UNIQUE,

    -- Page classification
    page_type VARCHAR(30) NOT NULL DEFAULT 'BUSINESS',
    category VARCHAR(100),
    subcategory VARCHAR(100),

    -- Basic information
