    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    metadata JSONB DEFAULT '{}',
    settings JSONB DEFAULT '{}'
);


--================================================================================================
-- Table: roles
-- Description: Defines roles that group permissions for users
-- Business Case: Provides a logical grouping of permissions for efficient assignment
--                to users, supporting hierarchical and system-level roles.
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.roles (
    -- Primary key
    role_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Role identification
    role_name VARCHAR(100) NOT NULL,
    role_code VARCHAR(50) UNIQUE NOT NULL,
    role_description TEXT,

    -- Role classification
    role_type VARCHAR(30) DEFAULT 'CUSTOM' CHECK (
        role_type IN ('SYSTEM', 'BUILTIN', 'CUSTOM', 'TEMPLATE')
    ),
    role_scope VARCHAR(30) DEFAULT 'GLOBAL' CHECK (
        role_scope IN ('GLOBAL', 'ORGANIZATION', 'TEAM', 'PROJECT')
    ),

    -- Hierarchy
    parent_role_id UUID,
    hierarchy_level INTEGER DEFAULT 0 CHECK (hierarchy_level >= 0),

    -- System flags
    is_system_role BOOLEAN DEFAULT FALSE,
    is_deprecated BOOLEAN DEFAULT FALSE,
    is_default BOOLEAN DEFAULT FALSE,

    -- Metadata
    tags VARCHAR(50)[] DEFAULT '{}',
    metadata JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: permissions
-- Description: Defines granular permissions for actions on resources
-- Business Case: Enables fine-grained authorization by defining specific actions
--                on resources, supporting complex policy enforcement.
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.permissions (
    -- Primary key
    permission_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Permission identification
    permission_name VARCHAR(200) NOT NULL,
    permission_code VARCHAR(100) UNIQUE NOT NULL,
    permission_description TEXT,

    -- Resource specification
    resource_type VARCHAR(100) NOT NULL,
    resource_action VARCHAR(50) NOT NULL CHECK (
        resource_action IN ('CREATE', 'READ', 'UPDATE', 'DELETE', 'MANAGE', 'EXECUTE', 'APPROVE', 'EXPORT')
    ),
    resource_scope VARCHAR(30) DEFAULT 'GLOBAL' CHECK (
        resource_scope IN ('GLOBAL', 'OWN', 'TEAM', 'ORGANIZATION', 'PROJECT')
    ),

    -- Classification
    permission_category VARCHAR(50) CHECK (
        permission_category IN ('DATA', 'SYSTEM', 'USER', 'CONTENT', 'ADMIN', 'REPORTING')
    ),
    permission_domain VARCHAR(50),

    -- Dependencies
    depends_on_permission_ids UUID[] DEFAULT '{}',

    -- System flags
    is_system_permission BOOLEAN DEFAULT FALSE,
    is_deprecated BOOLEAN DEFAULT FALSE,

    -- Metadata
    tags VARCHAR(50)[] DEFAULT '{}',
    metadata JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: role_assignments
-- Description: Maps users to roles with optional time bounds and context
-- Business Case: Tracks which roles are assigned to which users, supporting
--                temporary assignments, delegation, and audit trails.
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.role_assignments (
    -- Primary key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    role_id UUID NOT NULL,
    assigned_by UUID,

    -- Assignment type
    assignment_type VARCHAR(30) DEFAULT 'DIRECT' CHECK (
        assignment_type IN ('DIRECT', 'INHERITED', 'TEMPORARY', 'DELEGATED', 'SYSTEM')
    ),
    inherited_from_role_id UUID,

    -- Time bounds
    assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (
        CASE WHEN expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP THEN TRUE ELSE FALSE END
    ) STORED,

    -- Context
    assignment_reason TEXT,
    resource_scope_id UUID, -- Optional specific resource this assignment applies to
    resource_scope_type VARCHAR(50), -- e.g., 'organization', 'project'

    -- Delegation
    delegated_by UUID,
    delegation_depth INTEGER DEFAULT 0 CHECK (delegation_depth >= 0),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_by UUID,
    revocation_reason TEXT,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

