--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================

-- Enable RLS
ALTER TABLE socialcandor_schema.roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.role_assignments ENABLE ROW LEVEL SECURITY;

-- Roles policies
CREATE POLICY roles_read_policy ON socialcandor_schema.roles
    FOR SELECT
    USING (TRUE); -- All authenticated users can see roles (but not modify)

CREATE POLICY roles_write_policy ON socialcandor_schema.roles
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND (u.is_admin = TRUE OR u.user_id IN (
                SELECT user_id FROM socialcandor_schema.role_assignments ra
                JOIN socialcandor_schema.roles r ON ra.role_id = r.role_id
                WHERE r.role_name IN ('SYSTEM_ADMIN', 'ROLE_MANAGER')
                AND ra.is_active = TRUE
            ))
        )
    );

-- Permissions policies
CREATE POLICY permissions_read_policy ON socialcandor_schema.permissions
    FOR SELECT
    USING (TRUE); -- All authenticated users can view permissions

CREATE POLICY permissions_write_policy ON socialcandor_schema.permissions
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND (u.is_admin = TRUE OR u.user_id IN (
                SELECT user_id FROM socialcandor_schema.role_assignments ra
                JOIN socialcandor_schema.roles r ON ra.role_id = r.role_id
                WHERE r.role_name IN ('SYSTEM_ADMIN', 'PERMISSION_MANAGER')
                AND ra.is_active = TRUE
            ))
        )
    );

-- Role assignments policies
CREATE POLICY role_assignments_self_policy ON socialcandor_schema.role_assignments
    FOR SELECT
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY role_assignments_admin_policy ON socialcandor_schema.role_assignments
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND (u.is_admin = TRUE OR u.user_id IN (
                SELECT user_id FROM socialcandor_schema.role_assignments ra
                JOIN socialcandor_schema.roles r ON ra.role_id = r.role_id
                WHERE r.role_name IN ('SYSTEM_ADMIN', 'USER_ADMIN', 'ROLE_MANAGER')
                AND ra.is_active = TRUE
            ))
        )
    );

--================================================================================================
-- TRIGGERS FOR UPDATED_AT
--================================================================================================

CREATE TRIGGER trg_roles_updated_at
    BEFORE UPDATE ON socialcandor_schema.roles
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_permissions_updated_at
    BEFORE UPDATE ON socialcandor_schema.permissions
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_role_assignments_updated_at
    BEFORE UPDATE ON socialcandor_schema.role_assignments
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

