CREATE INDEX IF NOT EXISTS idx_groups_members_pending ON socialcandor_schema.groups_members(status) WHERE status = 'PENDING';

-- Pages indexes
CREATE INDEX IF NOT EXISTS idx_pages_owner ON socialcandor_schema.pages(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_pages_slug ON socialcandor_schema.pages(page_slug);
CREATE INDEX IF NOT EXISTS idx_pages_type ON socialcandor_schema.pages(page_type);
CREATE INDEX IF NOT EXISTS idx_pages_industry ON socialcandor_schema.pages(industry);
CREATE INDEX IF NOT EXISTS idx_pages_verification ON socialcandor_schema.pages(verification_status);
CREATE INDEX IF NOT EXISTS idx_pages_location ON socialcandor_schema.pages USING GIST(location_coordinates);
CREATE INDEX IF NOT EXISTS idx_pages_follower_count ON socialcandor_schema.pages(follower_count DESC);
CREATE INDEX IF NOT EXISTS idx_pages_created_at ON socialcandor_schema.pages(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pages_search ON socialcandor_schema.pages USING gin(
    to_tsvector('english', page_name || ' ' || COALESCE(description, '') || ' ' || COALESCE(tagline, ''))
);
CREATE INDEX IF NOT EXISTS idx_pages_monetized ON socialcandor_schema.pages(is_monetized) WHERE is_monetized = TRUE;
CREATE INDEX IF NOT EXISTS idx_pages_active ON socialcandor_schema.pages(is_active) WHERE is_active = TRUE;

--================================================================================================
-- ROW LEVEL SECURITY POLICIES ( tables  1-15)
--================================================================================================

-- Enable RLS on sensitive tables
ALTER TABLE socialcandor_schema.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.users_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.conversations_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.conversations_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.notification_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.friends ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.followings ENABLE ROW LEVEL SECURITY;

-- Users table policies
CREATE POLICY users_self_access_policy ON socialcandor_schema.users
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

CREATE POLICY users_public_profile_policy ON socialcandor_schema.users
    FOR SELECT USING (status = 'ACTIVE' AND
                      jsonb_extract_path_text(privacy_settings, 'profile_visibility') != 'PRIVATE');

-- Users sessions table policies
CREATE POLICY users_sessions_owner_policy ON socialcandor_schema.users_sessions
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Friends table policies
CREATE POLICY friends_visibility_policy ON socialcandor_schema.friends
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID OR
                      friend_user_id = current_setting('app.current_user_id')::UUID OR
                      current_setting('app.is_admin')::BOOLEAN = true);

CREATE POLICY friends_modification_policy ON socialcandor_schema.friends
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Followings table policies
CREATE POLICY followings_visibility_policy ON socialcandor_schema.followings
    FOR SELECT USING (follower_user_id = current_setting('app.current_user_id')::UUID OR
                      following_user_id = current_setting('app.current_user_id')::UUID OR
                      current_setting('app.is_admin')::BOOLEAN = true);

CREATE POLICY followings_modification_policy ON socialcandor_schema.followings
    FOR ALL USING (follower_user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Conversations table policies
CREATE POLICY conversations_participant_policy ON socialcandor_schema.conversations
    FOR ALL USING (conversation_id IN (
        SELECT conversation_id FROM socialcandor_schema.conversations_users
        WHERE user_id = current_setting('app.current_user_id')::UUID
    ) OR current_setting('app.is_admin')::BOOLEAN = true);

-- Conversations messages table policies
CREATE POLICY conversations_messages_participant_policy ON socialcandor_schema.conversations_messages
    FOR ALL USING (conversation_id IN (
        SELECT conversation_id FROM socialcandor_schema.conversations_users
        WHERE user_id = current_setting('app.current_user_id')::UUID
    ) OR current_setting('app.is_admin')::BOOLEAN = true);

-- Conversations users table policies
CREATE POLICY conversations_users_self_policy ON socialcandor_schema.conversations_users
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   conversation_id IN (
                       SELECT conversation_id FROM socialcandor_schema.conversations_users
                       WHERE user_id = current_setting('app.current_user_id')::UUID
                   ) OR current_setting('app.is_admin')::BOOLEAN = true);

-- Notifications table policies
CREATE POLICY notifications_owner_policy ON socialcandor_schema.notifications
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Notification preferences table policies
CREATE POLICY notification_preferences_owner_policy ON socialcandor_schema.notification_preferences
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Groups table policies
CREATE POLICY groups_member_access_policy ON socialcandor_schema.groups
    FOR SELECT USING (privacy_level = 'PUBLIC' OR
                      group_id IN (
                          SELECT group_id FROM socialcandor_schema.groups_members
                          WHERE user_id = current_setting('app.current_user_id')::UUID AND status = 'ACTIVE'
                      ) OR current_setting('app.is_admin')::BOOLEAN = true);

-- Groups members table policies
CREATE POLICY groups_members_visibility_policy ON socialcandor_schema.groups_members
    FOR SELECT USING (group_id IN (
        SELECT group_id FROM socialcandor_schema.groups_members
        WHERE user_id = current_setting('app.current_user_id')::UUID AND status = 'ACTIVE'
    ) OR current_setting('app.is_admin')::BOOLEAN = true);

CREATE POLICY groups_members_modification_policy ON socialcandor_schema.groups_members
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

-- Pages table policies
CREATE POLICY pages_public_access_policy ON socialcandor_schema.pages
    FOR SELECT USING (is_active = TRUE OR current_setting('app.is_admin')::BOOLEAN = true);

CREATE POLICY pages_owner_modification_policy ON socialcandor_schema.pages
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR
                   current_setting('app.is_admin')::BOOLEAN = true);

--================================================================================================
-- TABLE COMMENTS (All tables 1-15)
--================================================================================================

COMMENT ON TABLE socialcandor_schema.users IS 'Core user accounts with authentication and profile management';
COMMENT ON TABLE socialcandor_schema.users_sessions IS 'User session tracking with security and analytics capabilities';
COMMENT ON TABLE socialcandor_schema.posts IS 'Primary content repository for user-generated content with rich metadata';
COMMENT ON TABLE socialcandor_schema.posts_media IS 'Multimedia attachments with format normalization and CDN integration';
COMMENT ON TABLE socialcandor_schema.posts_comments IS 'Hierarchical comment system with threaded conversations and moderation';
COMMENT ON TABLE socialcandor_schema.friends IS 'Bidirectional friend relationships with status lifecycle management';
COMMENT ON TABLE socialcandor_schema.followings IS 'Asymmetric follower relationships for creator-audience dynamics';
COMMENT ON TABLE socialcandor_schema.conversations IS 'Unified messaging container for 1:1 and group chats';
COMMENT ON TABLE socialcandor_schema.conversations_messages IS 'Message content storage with delivery and read receipt tracking';
COMMENT ON TABLE socialcandor_schema.conversations_users IS 'Conversation participant tracking with role and status management';
COMMENT ON TABLE socialcandor_schema.notifications IS 'User notification system with delivery tracking and preferences';
COMMENT ON TABLE socialcandor_schema.notification_preferences IS 'User notification preference management with granular controls';
COMMENT ON TABLE socialcandor_schema.groups IS 'User group management with membership and content features';
COMMENT ON TABLE socialcandor_schema.groups_members IS 'Group membership tracking with role and status management';
COMMENT ON TABLE socialcandor_schema.pages IS 'Business/organization profiles with verification and public content';

--================================================================================================
-- Table: 16 - photos
-- Description: Dedicated photo storage with EXIF metadata preservation and geotagging
-- Business Case: Supports photo-centric experiences (albums, galleries) with geotagging and
--                privacy controls distinct from post attachments. Maintains metadata integrity
--                for accessibility compliance and copyright attribution while enabling advanced
--                photo management features.
-- KPIs: Photo upload success rate, EXIF preservation rate, geotag accuracy, accessibility compliance
-- Feature Reference: MED02 (Photo Management), GEO01 (Geotagging), ACC02 (Accessibility)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.photos (
    -- Primary key with UUID for security and distributed systems
    photo_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership and organization
    user_id UUID NOT NULL,
    album_id UUID,

    -- Photo information
    photo_type VARCHAR(20) DEFAULT 'PHOTO' CHECK (
        photo_type IN ('PHOTO', 'PANORAMA', 'PORTRAIT', 'LANDSCAPE', 'MACRO', 'SPHERICAL')
    ),
    original_filename VARCHAR(255),
    file_extension VARCHAR(10),
    mime_type VARCHAR(100),

    -- Storage information
    storage_provider VARCHAR(50) DEFAULT 'S3' CHECK (
        storage_provider IN ('S3', 'GCS', 'AZURE', 'CDN', 'LOCAL')
    ),
    storage_key VARCHAR(500) NOT NULL,
    storage_bucket VARCHAR(255),
    storage_region VARCHAR(50),

    -- Image metadata
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    width_pixels INTEGER CHECK (width_pixels >= 0),
    height_pixels INTEGER CHECK (height_pixels >= 0),
    aspect_ratio NUMERIC(5,2),
    resolution_dpi INTEGER,
    color_space VARCHAR(50),
    bit_depth INTEGER CHECK (bit_depth IN (8, 16, 24, 32)),

    -- EXIF metadata (preserved from camera)
    exif_data JSONB DEFAULT '{}',
    camera_make VARCHAR(100),
    camera_model VARCHAR(100),
    lens_model VARCHAR(100),
    focal_length NUMERIC(5,1),
    aperture VARCHAR(10),
    shutter_speed VARCHAR(20),
    iso_speed INTEGER,
    exposure_bias VARCHAR(10),
    flash_used BOOLEAN,
    metering_mode VARCHAR(50),

    -- Geolocation data
    geotag_enabled BOOLEAN DEFAULT FALSE,
    latitude NUMERIC(10,8),
    longitude NUMERIC(11,8),
    altitude NUMERIC(8,2),
    location_accuracy INTEGER,
    location_name VARCHAR(255),
    location_address TEXT,
    location_coordinates GEOGRAPHY(POINT, 4326),

    -- Date and time
    taken_at TIMESTAMP WITH TIME ZONE,
    digitized_at TIMESTAMP WITH TIME ZONE,
    timezone_offset VARCHAR(10),

    -- Processing information
    processing_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'OPTIMIZED')
    ),
    processing_attempts INTEGER DEFAULT 0,
    processing_error TEXT,
    optimized_version_url VARCHAR(500),
    thumbnail_url VARCHAR(500),
    preview_url VARCHAR(500),
    watermark_applied BOOLEAN DEFAULT FALSE,

    -- Accessibility features
    alt_text VARCHAR(500),
    generated_alt_text VARCHAR(500),
    alt_text_confidence NUMERIC(5,2) CHECK (alt_text_confidence >= 0 AND alt_text_confidence <= 100),
    caption TEXT,
    keywords VARCHAR(100)[] DEFAULT '{}',

    -- Copyright and licensing
    copyright_notice TEXT,
    copyright_holder VARCHAR(255),
    usage_rights VARCHAR(50) CHECK (
        usage_rights IN ('ALL_RIGHTS_RESERVED', 'CREATIVE_COMMONS', 'PUBLIC_DOMAIN', 'ROYALTY_FREE', 'RIGHTS_MANAGED')
    ),
    license_type VARCHAR(100),
    attribution_required BOOLEAN DEFAULT FALSE,
    commercial_use_allowed BOOLEAN DEFAULT FALSE,
    modification_allowed BOOLEAN DEFAULT FALSE,

    -- Content safety
    nsfw_score NUMERIC(5,2) DEFAULT 0.0 CHECK (nsfw_score >= 0 AND nsfw_score <= 100),
    explicit_content_detected BOOLEAN DEFAULT FALSE,
    blur_hash VARCHAR(100),

    -- Privacy and sharing
    visibility socialcandor_schema.content_visibility DEFAULT 'PRIVATE',
    sharing_enabled BOOLEAN DEFAULT FALSE,
    download_enabled BOOLEAN DEFAULT TRUE,
    can_be_shared BOOLEAN DEFAULT TRUE,

    -- Engagement metrics
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    download_count INTEGER DEFAULT 0 CHECK (download_count >= 0),
    like_count INTEGER DEFAULT 0 CHECK (like_count >= 0),
    share_count INTEGER DEFAULT 0 CHECK (share_count >= 0),

    -- Organization
    sort_order INTEGER DEFAULT 0 CHECK (sort_order >= 0),
    is_favorite BOOLEAN DEFAULT FALSE,
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: 17 - photo_albums
-- Description: Logical grouping of photos with cover image selection and collaborative capabilities
-- Business Case: Enables memory ("On This Day") social sharing workflows supporting bulk
--                operations (download/delete) and user data portability compliance. Supports
--                collaborative shared experiences.
-- KPIs: Album creation rate, collaboration adoption, photo organization efficiency
-- Feature Reference: ALB01 (Album Management), COL01 (Collaboration), DPP01 (Data Portability)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.photo_albums (
    -- Primary key
    album_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL,

    -- Album information
    album_name VARCHAR(200) NOT NULL,
    album_slug VARCHAR(200) UNIQUE,
    description TEXT,
    album_type VARCHAR(30) DEFAULT 'PERSONAL' CHECK (
        album_type IN ('PERSONAL', 'EVENT', 'TRIP', 'PROJECT', 'MEMORY', 'COLLABORATIVE')
    ),

    -- Cover and appearance
    cover_photo_id UUID,
    cover_color VARCHAR(7),
    layout_style VARCHAR(20) DEFAULT 'GRID' CHECK (
        layout_style IN ('GRID', 'MASONRY', 'CAROUSEL', 'STACK', 'TIMELINE')
    ),

    -- Privacy and sharing
    visibility socialcandor_schema.content_visibility DEFAULT 'PRIVATE',
    sharing_enabled BOOLEAN DEFAULT FALSE,
    invite_link VARCHAR(500),
    invite_link_expires_at TIMESTAMP WITH TIME ZONE,
    download_enabled BOOLEAN DEFAULT TRUE,
    allow_comments BOOLEAN DEFAULT TRUE,
    allow_reactions BOOLEAN DEFAULT TRUE,

    -- Organization
    sort_order INTEGER DEFAULT 0 CHECK (sort_order >= 0),
    is_featured BOOLEAN DEFAULT FALSE,
    is_pinned BOOLEAN DEFAULT FALSE,
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Time-based features
    start_date DATE,
    end_date DATE,
    is_time_bound BOOLEAN DEFAULT FALSE,
    recurrence_pattern VARCHAR(100),
    memory_notification_enabled BOOLEAN DEFAULT FALSE,

    -- Collaborative features
    is_collaborative BOOLEAN DEFAULT FALSE,
    collaboration_mode VARCHAR(20) DEFAULT 'VIEW_ONLY' CHECK (
        collaboration_mode IN ('VIEW_ONLY', 'CAN_ADD', 'CAN_EDIT', 'CAN_MANAGE')
    ),
    collaborator_count INTEGER DEFAULT 0 CHECK (collaborator_count >= 0),

    -- Statistics
    photo_count INTEGER DEFAULT 0 CHECK (photo_count >= 0),
    total_views INTEGER DEFAULT 0 CHECK (total_views >= 0),
    total_downloads INTEGER DEFAULT 0 CHECK (total_downloads >= 0),
    total_size_bytes BIGINT DEFAULT 0 CHECK (total_size_bytes >= 0),
    last_photo_added_at TIMESTAMP WITH TIME ZONE,

    -- Location context
    location_name VARCHAR(255),
    location_coordinates GEOGRAPHY(POINT, 4326),
    location_radius_km INTEGER,

    -- Metadata and tags
    tags VARCHAR(50)[] DEFAULT '{}',
    categories VARCHAR(50)[] DEFAULT '{}',
    custom_metadata JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

--================================================================================================
-- Table: 18 - videos
-- Description: Video content repository with streaming metadata and adaptive bitrate support
-- Business Case: Optimizes video delivery through adaptive bitrate selection while enabling
--                creator monetization via view-based revenue and content ID matching for
--                copyright protection. Supports rich video analytics and engagement tracking.
-- KPIs: Video upload success rate, streaming quality score, monetization revenue, copyright match rate
-- Feature Reference: VID01 (Video Management), STR01 (Streaming), MON04 (Video Monetization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.videos (
    -- Primary key
    video_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL,

    -- Video information
    title VARCHAR(255) NOT NULL,
    description TEXT,
    video_type VARCHAR(30) DEFAULT 'USER_UPLOADED' CHECK (
        video_type IN ('USER_UPLOADED', 'LIVE_STREAM', 'STORY', 'REEL', 'SHORT', 'PREMIUM')
    ),

    -- Storage information
    storage_provider VARCHAR(50) DEFAULT 'S3' CHECK (
        storage_provider IN ('S3', 'GCS', 'AZURE', 'CDN', 'LOCAL')
    ),
    storage_key VARCHAR(500) NOT NULL,
    storage_bucket VARCHAR(255),
    storage_region VARCHAR(50),

    -- Technical specifications
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    duration_seconds INTEGER CHECK (duration_seconds >= 0),
    width_pixels INTEGER CHECK (width_pixels >= 0),
    height_pixels INTEGER CHECK (height_pixels >= 0),
    aspect_ratio VARCHAR(20),
    frame_rate NUMERIC(5,2),
    bitrate_kbps INTEGER,
    codec VARCHAR(50),
    container_format VARCHAR(50),

    -- Streaming configuration
    streaming_enabled BOOLEAN DEFAULT TRUE,
    adaptive_bitrate_enabled BOOLEAN DEFAULT TRUE,
    available_resolutions VARCHAR(20)[] DEFAULT '{}',
    hls_manifest_url VARCHAR(500),
    dash_manifest_url VARCHAR(500),

    -- Processing information
    processing_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'OPTIMIZED')
    ),
    processing_attempts INTEGER DEFAULT 0,
    processing_error TEXT,
    thumbnail_url VARCHAR(500),
    preview_url VARCHAR(500),
    optimized_url VARCHAR(500),
    original_url VARCHAR(500),

    -- CDN information
    cdn_url VARCHAR(500),
    cdn_path VARCHAR(500),
    cdn_cache_key VARCHAR(255),

    -- Accessibility features
    alt_text VARCHAR(500),
    caption TEXT,
    transcript TEXT,
    language_code VARCHAR(10) DEFAULT 'en',

    -- Copyright and licensing
    copyright_holder VARCHAR(255),
    license_type VARCHAR(50),
    attribution_required BOOLEAN DEFAULT FALSE,
    commercial_use_allowed BOOLEAN DEFAULT FALSE,

    -- Content safety
    nsfw_score NUMERIC(5,2) DEFAULT 0.0 CHECK (nsfw_score >= 0 AND nsfw_score <= 100),
    explicit_content_detected BOOLEAN DEFAULT FALSE,

    -- Privacy and sharing
    visibility socialcandor_schema.content_visibility DEFAULT 'PUBLIC',
    sharing_enabled BOOLEAN DEFAULT TRUE,
    download_enabled BOOLEAN DEFAULT FALSE,
    embed_enabled BOOLEAN DEFAULT TRUE,

    -- Engagement metrics
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    like_count INTEGER DEFAULT 0 CHECK (like_count >= 0),
    comment_count INTEGER DEFAULT 0 CHECK (comment_count >= 0),
    share_count INTEGER DEFAULT 0 CHECK (share_count >= 0),
    download_count INTEGER DEFAULT 0 CHECK (download_count >= 0),
    screenshot_count INTEGER DEFAULT 0 CHECK (screenshot_count >= 0),

    -- Analytics
    completion_rate NUMERIC(5,2) CHECK (completion_rate >= 0 AND completion_rate <= 100),
    avg_view_time_seconds NUMERIC(10,2),
    drop_off_point_seconds NUMERIC(10,2),

    -- Moderation
    moderation_status VARCHAR(20) DEFAULT 'PENDING_REVIEW' CHECK (
        moderation_status IN ('PENDING_REVIEW', 'APPROVED', 'REJECTED', 'FLAGGED')
    ),
    moderation_score NUMERIC(5,2) DEFAULT 0.0 CHECK (moderation_score >= 0 AND moderation_score <= 100),

    -- Highlight management
    is_featured BOOLEAN DEFAULT FALSE,
    is_premium BOOLEAN DEFAULT FALSE,
    is_monetized BOOLEAN DEFAULT FALSE,

    -- Organization
    sort_order INTEGER DEFAULT 0 CHECK (sort_order >= 0),
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: 19 - events
-- Description: Event management system with geocoding, capacity limits, and ticketing support
-- Business Case: Drives real-world IRL meetups generating promoted events and ticketing
--                integrations. Critical platform differentiation beyond digital-only interactions
--                with comprehensive event lifecycle management.
-- KPIs: Event creation rate, attendance rate, ticket sales conversion, event completion rate
-- Feature Reference: EVT01 (Event Management), COM02 (Community Events), MON05 (Event Monetization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.events (
    -- Primary key
    event_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Organization
    organizer_user_id UUID NOT NULL,
    host_group_id UUID,
    host_page_id UUID,

    -- Event information
    event_name VARCHAR(255) NOT NULL,
    event_slug VARCHAR(255) UNIQUE,
    description TEXT,
    event_type VARCHAR(50) DEFAULT 'GENERAL' CHECK (
        event_type IN ('GENERAL', 'MEETUP', 'CONFERENCE', 'WORKSHOP', 'WEBINAR', 'CONCERT', 'SPORTS', 'COMMUNITY')
    ),
    event_category VARCHAR(100),

    -- Timing
    start_datetime TIMESTAMP WITH TIME ZONE NOT NULL,
    end_datetime TIMESTAMP WITH TIME ZONE,
    timezone VARCHAR(50) DEFAULT 'UTC',
    is_all_day BOOLEAN DEFAULT FALSE,
    is_recurring BOOLEAN DEFAULT FALSE,
    recurrence_pattern VARCHAR(100),
    recurrence_end_date DATE,

    -- Location
    location_type VARCHAR(20) DEFAULT 'PHYSICAL' CHECK (
        location_type IN ('PHYSICAL', 'VIRTUAL', 'HYBRID')
    ),
    venue_name VARCHAR(255),
    venue_address TEXT,
    city VARCHAR(100),
    state_province VARCHAR(100),
    country_code VARCHAR(3),
    postal_code VARCHAR(20),
    location_coordinates GEOGRAPHY(POINT, 4326),
    virtual_meeting_url VARCHAR(500),
    virtual_meeting_platform VARCHAR(50),

    -- Capacity and registration
    max_participants INTEGER DEFAULT 100 CHECK (max_participants >= 1),
    current_participant_count INTEGER DEFAULT 0 CHECK (current_participant_count >= 0),
    registration_enabled BOOLEAN DEFAULT TRUE,
    registration_start_datetime TIMESTAMP WITH TIME ZONE,
    registration_end_datetime TIMESTAMP WITH TIME ZONE,
    allow_waitlist BOOLEAN DEFAULT FALSE,
    waitlist_count INTEGER DEFAULT 0 CHECK (waitlist_count >= 0),

    -- Ticketing and pricing
    is_ticketed BOOLEAN DEFAULT FALSE,
    ticket_types JSONB DEFAULT '[]',
    currency_code CHAR(3) DEFAULT 'USD',
    price_min NUMERIC(10,2),
    price_max NUMERIC(10,2),
    total_revenue NUMERIC(15,2) DEFAULT 0 CHECK (total_revenue >= 0),

    -- Promotion and discovery
    is_promoted BOOLEAN DEFAULT FALSE,
    promotion_budget NUMERIC(15,2),
    promotion_starts_at TIMESTAMP WITH TIME ZONE,
    promotion_ends_at TIMESTAMP WITH TIME ZONE,

    -- Event status
    event_status VARCHAR(20) DEFAULT 'DRAFT' CHECK (
        event_status IN ('DRAFT', 'PUBLISHED', 'CANCELLED', 'POSTPONED', 'COMPLETED', 'ARCHIVED')
    ),
    cancellation_reason TEXT,
    postponed_to TIMESTAMP WITH TIME ZONE,

    -- Media and branding
    cover_image_url VARCHAR(500),
    banner_image_url VARCHAR(500),
    logo_url VARCHAR(500),
    color_scheme VARCHAR(100),
    custom_css TEXT,

    -- Features and options
    chat_enabled BOOLEAN DEFAULT TRUE,
    qa_enabled BOOLEAN DEFAULT TRUE,
    networking_enabled BOOLEAN DEFAULT TRUE,
    recording_consent_required BOOLEAN DEFAULT FALSE,
    age_restriction INTEGER CHECK (age_restriction >= 0),
    dress_code VARCHAR(50),

    -- Social features
    allow_sharing BOOLEAN DEFAULT TRUE,
    allow_invites BOOLEAN DEFAULT TRUE,
    allow_rsvp_changes BOOLEAN DEFAULT TRUE,
    reminder_enabled BOOLEAN DEFAULT TRUE,
    reminder_days_before INTEGER[] DEFAULT ARRAY[1, 7],

    -- Analytics and engagement
    total_views INTEGER DEFAULT 0 CHECK (total_views >= 0),
    total_shares INTEGER DEFAULT 0 CHECK (total_shares >= 0),
    total_rsvps INTEGER DEFAULT 0 CHECK (total_rsvps >= 0),
    attendance_rate NUMERIC(5,2),

    -- Moderation and safety
    moderation_enabled BOOLEAN DEFAULT TRUE,
    content_guidelines TEXT,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: 20 - events_members
-- Description: Event attendance tracking with RSVP management and participation analytics
-- Business Case: Enables comprehensive event participation tracking with RSVP states,
--                attendance verification, and engagement analytics for event optimization.
-- KPIs: RSVP conversion rate, attendance rate, no-show rate, participant engagement score
-- Feature Reference: EVT02 (Attendance Tracking), ENG02 (Event Engagement), ANL04 (Event Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.events_members (
    -- Primary key
    membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    event_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- RSVP information
    rsvp_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        rsvp_status IN ('PENDING', 'GOING', 'NOT_GOING', 'MAYBE', 'WAITLIST', 'CANCELLED')
    ),
    rsvp_datetime TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    rsvp_source VARCHAR(20) DEFAULT 'WEB' CHECK (
        rsvp_source IN ('WEB', 'MOBILE', 'API', 'EMAIL', 'INVITE')
    ),

    -- Ticket information
    ticket_id UUID,
    ticket_type VARCHAR(50),
    ticket_price NUMERIC(10,2),
    payment_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        payment_status IN ('PENDING', 'PAID', 'REFUNDED', 'FAILED', 'WAIVED')
    ),
    payment_datetime TIMESTAMP WITH TIME ZONE,

    -- Attendance tracking
    check_in_status VARCHAR(20) DEFAULT 'NOT_CHECKED_IN' CHECK (
        check_in_status IN ('NOT_CHECKED_IN', 'CHECKED_IN', 'CHECKED_OUT', 'NO_SHOW')
    ),
    check_in_datetime TIMESTAMP WITH TIME ZONE,
    check_out_datetime TIMESTAMP WITH TIME ZONE,
    attendance_verified BOOLEAN DEFAULT FALSE,
    verification_method VARCHAR(20),

    -- Participation metrics
    engagement_score NUMERIC(5,2) DEFAULT 0 CHECK (engagement_score >= 0 AND engagement_score <= 100),
    sessions_attended INTEGER DEFAULT 0 CHECK (sessions_attended >= 0),
    questions_asked INTEGER DEFAULT 0 CHECK (questions_asked >= 0),
    connections_made INTEGER DEFAULT 0 CHECK (connections_made >= 0),

    -- Communication preferences
    receive_updates BOOLEAN DEFAULT TRUE,
    receive_reminders BOOLEAN DEFAULT TRUE,
    share_attendance BOOLEAN DEFAULT TRUE,

    -- Role in event
    member_role VARCHAR(30) DEFAULT 'ATTENDEE' CHECK (
        member_role IN ('ATTENDEE', 'SPEAKER', 'SPONSOR', 'VOLUNTEER', 'STAFF', 'ORGANIZER')
    ),
    permissions JSONB DEFAULT '{}',

    -- Notes and feedback
    dietary_restrictions VARCHAR(100)[] DEFAULT '{}',
    accessibility_requirements TEXT,
    special_requests TEXT,
    feedback_submitted BOOLEAN DEFAULT FALSE,
    feedback_rating INTEGER CHECK (feedback_rating >= 1 AND feedback_rating <= 5),
    feedback_text TEXT,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    cancelled_at TIMESTAMP WITH TIME ZONE,
    cancelled_by UUID,
    cancellation_reason TEXT
);

--================================================================================================
-- Table: 21 - user_wallets
-- Description: Digital wallet management for platform currency and payment processing
-- Business Case: Enables in-platform transactions, creator monetization, and premium feature
--                purchases while maintaining PCI-DSS compliance and fraud detection capabilities.
-- KPIs: Wallet activation rate, transaction success rate, fraud detection accuracy, balance accuracy
-- Feature Reference: PAY01 (Wallet Management), PAY02 (Transaction Processing), SEC07 (Fraud Detection)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_wallets (
    -- Primary key
    wallet_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL UNIQUE,

    -- Wallet information
    wallet_number VARCHAR(50) GENERATED ALWAYS AS (
        'WLT-' || LPAD(EXTRACT(YEAR FROM created_at)::VARCHAR, 4, '0') || '-' ||
        LPAD(wallet_id::VARCHAR, 8, '0')
    ) STORED,
    wallet_type VARCHAR(20) DEFAULT 'STANDARD' CHECK (
        wallet_type IN ('STANDARD', 'PREMIUM', 'BUSINESS', 'CREATOR', 'MERCHANT')
    ),

    -- Balance information
    currency_code CHAR(3) NOT NULL DEFAULT 'USD',
    available_balance NUMERIC(15,2) DEFAULT 0 CHECK (available_balance >= 0),
    pending_balance NUMERIC(15,2) DEFAULT 0 CHECK (pending_balance >= 0),
    total_deposits NUMERIC(15,2) DEFAULT 0 CHECK (total_deposits >= 0),
    total_withdrawals NUMERIC(15,2) DEFAULT 0 CHECK (total_withdrawals >= 0),
    total_spent NUMERIC(15,2) DEFAULT 0 CHECK (total_spent >= 0),
    total_earned NUMERIC(15,2) DEFAULT 0 CHECK (total_earned >= 0),

    -- Limits and restrictions
    daily_transaction_limit NUMERIC(15,2),
    monthly_transaction_limit NUMERIC(15,2),
    single_transaction_limit NUMERIC(15,2),
    withdrawal_limit_daily NUMERIC(15,2),
    withdrawal_limit_monthly NUMERIC(15,2),

    -- Security
    pin_hash VARCHAR(255),
    two_factor_enabled BOOLEAN DEFAULT FALSE,
    biometric_enabled BOOLEAN DEFAULT FALSE,
    last_pin_change_at TIMESTAMP WITH TIME ZONE,
    failed_pin_attempts INTEGER DEFAULT 0 CHECK (failed_pin_attempts >= 0),
    locked_until TIMESTAMP WITH TIME ZONE,

    -- Status
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (
        status IN ('ACTIVE', 'SUSPENDED', 'FROZEN', 'CLOSED', 'VERIFICATION_PENDING')
    ),
    verification_level VARCHAR(20) DEFAULT 'BASIC' CHECK (
        verification_level IN ('BASIC', 'INTERMEDIATE', 'ADVANCED', 'FULL')
    ),
    verification_documents JSONB DEFAULT '[]',

    -- Compliance
    kyc_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        kyc_status IN ('PENDING', 'VERIFIED', 'REJECTED', 'EXPIRED')
    ),
    kyc_verified_at TIMESTAMP WITH TIME ZONE,
    kyc_expiry_date DATE,
    aml_check_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        aml_check_status IN ('PENDING', 'CLEARED', 'FLAGGED', 'BLOCKED')
    ),
    last_aml_check_at TIMESTAMP WITH TIME ZONE,

    -- Banking information
    linked_bank_accounts JSONB DEFAULT '[]',
    default_bank_account_id UUID,
    linked_cards JSONB DEFAULT '[]',
    default_card_id UUID,

    -- Preferences
    auto_reload_enabled BOOLEAN DEFAULT FALSE,
    auto_reload_threshold NUMERIC(15,2),
    auto_reload_amount NUMERIC(15,2),
    notification_preferences JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    last_transaction_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,
    closed_by UUID,
    closure_reason TEXT
);

--================================================================================================
-- Table: 22 - wallet_transactions
-- Description: Comprehensive transaction ledger for wallet operations with audit trail
-- Business Case: Provides complete financial audit trail for all wallet operations supporting
--                regulatory compliance, dispute resolution, and financial reporting requirements.
-- KPIs: Transaction processing time, success rate, dispute rate, reconciliation accuracy
-- Feature Reference: PAY02 (Transaction Processing), AUD04 (Financial Audit), COMP08 (Financial Compliance)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.wallet_transactions (
    -- Primary key
    transaction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Transaction identification
    transaction_number VARCHAR(50) GENERATED ALWAYS AS (
        'TXN-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' ||
        LPAD(nextval('wallet_transaction_sequence')::VARCHAR, 8, '0')
    ) STORED,

    -- Wallet references
    wallet_id UUID NOT NULL,
    counterparty_wallet_id UUID,

    -- Transaction details
    transaction_type VARCHAR(30) NOT NULL CHECK (
        transaction_type IN ('DEPOSIT', 'WITHDRAWAL', 'TRANSFER', 'PAYMENT', 'REFUND', 'FEE', 'ADJUSTMENT', 'REVERSAL')
    ),
    transaction_category VARCHAR(50),
    amount NUMERIC(15,2) NOT NULL,
    currency_code CHAR(3) NOT NULL DEFAULT 'USD',
    fee_amount NUMERIC(15,2) DEFAULT 0 CHECK (fee_amount >= 0),
    net_amount NUMERIC(15,2) GENERATED ALWAYS AS (amount - fee_amount) STORED,

    -- Balance impact
    balance_before NUMERIC(15,2) NOT NULL,
    balance_after NUMERIC(15,2) NOT NULL,

    -- Status
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'CANCELLED', 'REVERSED', 'DISPUTED')
    ),
    status_reason TEXT,

    -- Payment method
    payment_method_type VARCHAR(30) CHECK (
        payment_method_type IN ('BANK_TRANSFER', 'CARD', 'WALLET_BALANCE', 'CRYPTO', 'THIRD_PARTY')
    ),
    payment_method_id VARCHAR(100),
    payment_processor VARCHAR(50),
    processor_transaction_id VARCHAR(100),

    -- Related entities
    related_entity_type VARCHAR(50),
    related_entity_id UUID,
    reference_number VARCHAR(100),
    invoice_id UUID,
    order_id UUID,

    -- Description and metadata
    description TEXT,
    merchant_name VARCHAR(255),
    merchant_category_code VARCHAR(10),
    metadata JSONB DEFAULT '{}',

    -- Timing
    initiated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Security and compliance
    ip_address INET,
    device_fingerprint VARCHAR(255),
    risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
    fraud_check_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        fraud_check_status IN ('PENDING', 'CLEARED', 'FLAGGED', 'BLOCKED')
    ),
    aml_check_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        aml_check_status IN ('PENDING', 'CLEARED', 'FLAGGED', 'BLOCKED')
    ),

    -- Reconciliation
    reconciliation_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        reconciliation_status IN ('PENDING', 'RECONCILED', 'DISCREPANCY', 'EXCEPTION')
    ),
    reconciliation_date DATE,
    reconciled_by UUID,

    -- Dispute management
    dispute_id UUID,
    dispute_status VARCHAR(20),
    dispute_resolved_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_by UUID NOT NULL,
    updated_by UUID,
    approved_by UUID,
    approval_datetime TIMESTAMP WITH TIME ZONE,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

--================================================================================================
-- Table: 23 - payment_methods
-- Description: Stored payment method information with tokenization and security features
-- Business Case: Enables secure storage of payment methods with PCI-DSS compliance through
--                tokenization, supporting seamless checkout experiences while maintaining
--                security and regulatory compliance.
-- KPIs: Payment method success rate, tokenization coverage, security incident rate
-- Feature Reference: PAY03 (Payment Methods), SEC08 (Payment Security), COMP08 (PCI Compliance)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.payment_methods (
    -- Primary key
    payment_method_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL,
    wallet_id UUID,

    -- Payment method information
    payment_method_type VARCHAR(30) NOT NULL CHECK (
        payment_method_type IN ('CREDIT_CARD', 'DEBIT_CARD', 'BANK_ACCOUNT', 'DIGITAL_WALLET', 'CRYPTOCURRENCY', 'BUY_NOW_PAY_LATER')
    ),
    payment_method_name VARCHAR(100),

    -- Card information (tokenized)
    card_token VARCHAR(255),
    card_last_four VARCHAR(4),
    card_brand VARCHAR(50),
    card_exp_month INTEGER CHECK (card_exp_month >= 1 AND card_exp_month <= 12),
    card_exp_year INTEGER,
    card_holder_name VARCHAR(255),
    card_billing_address TEXT,
    card_billing_city VARCHAR(100),
    card_billing_state VARCHAR(100),
    card_billing_postal_code VARCHAR(20),
    card_billing_country VARCHAR(3),

    -- Bank account information (tokenized)
    bank_token VARCHAR(255),
    bank_last_four VARCHAR(4),
    bank_name VARCHAR(255),
    bank_account_type VARCHAR(20) CHECK (
        bank_account_type IN ('CHECKING', 'SAVINGS', 'BUSINESS')
    ),
    bank_routing_number_hash VARCHAR(255),

    -- Digital wallet information
    digital_wallet_provider VARCHAR(50),
    digital_wallet_id VARCHAR(255),

    -- Cryptocurrency information
    crypto_currency VARCHAR(20),
    crypto_wallet_address VARCHAR(255),
    crypto_network VARCHAR(50),

    -- Status and verification
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        status IN ('PENDING', 'ACTIVE', 'VERIFIED', 'SUSPENDED', 'EXPIRED', 'REVOKED')
    ),
    is_default BOOLEAN DEFAULT FALSE,
    is_verified BOOLEAN DEFAULT FALSE,
    verification_method VARCHAR(50),
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Security
    encryption_key_id UUID,
    tokenization_provider VARCHAR(50),
    tokenization_reference VARCHAR(255),
    cvv_stored BOOLEAN DEFAULT FALSE,
    three_d_secure_enabled BOOLEAN DEFAULT FALSE,

    -- Usage tracking
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    last_used_at TIMESTAMP WITH TIME ZONE,
    total_amount_processed NUMERIC(15,2) DEFAULT 0 CHECK (total_amount_processed >= 0),

    -- Limits
    single_transaction_limit NUMERIC(15,2),
    daily_limit NUMERIC(15,2),
    monthly_limit NUMERIC(15,2),

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    expiry_notification_sent BOOLEAN DEFAULT FALSE,

    -- Preferences
    allow_recurring_payments BOOLEAN DEFAULT TRUE,
    allow_international_transactions BOOLEAN DEFAULT TRUE,
    allow_online_transactions BOOLEAN DEFAULT TRUE,
    allow_contactless_payments BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    deletion_reason TEXT
);

--================================================================================================
-- Table: 24 - system_countries
-- Description: Country reference data with compliance and regulatory information
-- Business Case: Provides standardized country data for compliance, tax calculation, and
--                regulatory requirements while supporting multi-jurisdiction operations.
-- KPIs: Data accuracy, compliance coverage, tax calculation accuracy
-- Feature Reference: SYS01 (System Configuration), COMP09 (Regulatory Compliance), TAX01 (Tax Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_countries (
    -- Primary key
    country_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Country identification
    country_code VARCHAR(3) NOT NULL UNIQUE,
    country_code_alpha2 VARCHAR(2) UNIQUE,
    country_name VARCHAR(100) NOT NULL,
    official_name VARCHAR(255),
    native_name VARCHAR(100),

    -- Geographic information
    region VARCHAR(50),
    subregion VARCHAR(50),
    continent VARCHAR(50),
    capital_city VARCHAR(100),
    latitude NUMERIC(10,8),
    longitude NUMERIC(11,8),
    area_km2 NUMERIC(10,2),
    landlocked BOOLEAN DEFAULT FALSE,

    -- Demographic information
    population BIGINT,
    population_density NUMERIC(10,2),
    official_languages VARCHAR(100)[],
    currency_code CHAR(3),
    currency_name VARCHAR(100),
    currency_symbol VARCHAR(10),

    -- Telecommunications
    calling_code VARCHAR(20),
    tld VARCHAR(10),

    -- Compliance and regulatory
    gdpr_applicable BOOLEAN DEFAULT FALSE,
    data_residency_required BOOLEAN DEFAULT FALSE,
    data_transfer_restrictions TEXT,
    privacy_law_framework VARCHAR(100),
    retention_requirements JSONB,

    -- Tax information
    vat_enabled BOOLEAN DEFAULT FALSE,
    vat_rate NUMERIC(5,2),
    tax_id_format VARCHAR(100),
    tax_reporting_requirements TEXT,

    -- Business operations
    business_registration_required BOOLEAN DEFAULT FALSE,
    supported_payment_methods VARCHAR(50)[],
    supported_currencies VARCHAR(3)[],

    -- Content and moderation
    content_restrictions JSONB,
    age_of_consent INTEGER,
    censorship_level VARCHAR(20) CHECK (
        censorship_level IN ('NONE', 'LOW', 'MEDIUM', 'HIGH', 'COMPLETE')
    ),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_eu_member BOOLEAN DEFAULT FALSE,
    is_eea_member BOOLEAN DEFAULT FALSE,
    sanctions_status VARCHAR(20) DEFAULT 'NONE' CHECK (
        sanctions_status IN ('NONE', 'PARTIAL', 'COMPREHENSIVE', 'EMBARGO')
    ),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    version INTEGER DEFAULT 1 CHECK (version >= 1),
    last_reviewed_at TIMESTAMP WITH TIME ZONE
);

--================================================================================================
-- Table: 25 - system_languages
-- Description: Language reference data with localization and translation support
-- Business Case: Enables comprehensive localization support for global platform operations
--                with language-specific content moderation, UI translation, and compliance requirements.
-- KPIs: Translation coverage, localization accuracy, user language preference adoption
-- Feature Reference: SYS02 (Localization), LOC01 (Language Support), CNT05 (Content Localization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_languages (
    -- Primary key
    language_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Language identification
    language_code VARCHAR(10) NOT NULL UNIQUE,
    language_name VARCHAR(100) NOT NULL,
    native_name VARCHAR(100),
    iso_639_1 VARCHAR(2),
    iso_639_2 VARCHAR(3),
    iso_639_3 VARCHAR(3),

    -- Script and direction
    script VARCHAR(50),
    writing_direction VARCHAR(10) DEFAULT 'LTR' CHECK (
        writing_direction IN ('LTR', 'RTL', 'TTB')
    ),

    -- Geographic distribution
    primary_countries VARCHAR(3)[],
    spoken_countries VARCHAR(3)[],
    official_countries VARCHAR(3)[],

    -- Platform support
    ui_translation_coverage NUMERIC(5,2) DEFAULT 0 CHECK (ui_translation_coverage >= 0 AND ui_translation_coverage <= 100),
    content_moderation_supported BOOLEAN DEFAULT FALSE,
    auto_translation_available BOOLEAN DEFAULT FALSE,
    speech_to_text_supported BOOLEAN DEFAULT FALSE,
    text_to_speech_supported BOOLEAN DEFAULT FALSE,

    -- Content settings
    default_content_language BOOLEAN DEFAULT FALSE,
    requires_translation_for_posting BOOLEAN DEFAULT FALSE,
    content_filtering_rules JSONB,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_beta BOOLEAN DEFAULT FALSE,
    maturity_level VARCHAR(20) DEFAULT 'STABLE' CHECK (
        maturity_level IN ('BETA', 'STABLE', 'DEPRECATED', 'ARCHIVED')
    ),

    -- Locale information
    date_format VARCHAR(50),
    time_format VARCHAR(50),
    number_format VARCHAR(50),
    currency_format VARCHAR(50),
    first_day_of_week INTEGER DEFAULT 1 CHECK (first_day_of_week >= 0 AND first_day_of_week <= 6),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    version INTEGER DEFAULT 1 CHECK (version >= 1),
    last_reviewed_at TIMESTAMP WITH TIME ZONE
);

--================================================================================================
-- Table: 26 - system_settings
-- Description: Centralized system configuration with versioning and audit trail
-- Business Case: Enables dynamic system configuration without code deployments while maintaining
--                audit trail, versioning, and role-based access control for configuration changes.
-- KPIs: Configuration change success rate, rollback frequency, configuration drift incidents
-- Feature Reference: SYS03 (System Configuration), GOV04 (Configuration Management), AUD05 (Config Audit)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_settings (
    -- Primary key
    setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Setting identification
    setting_key VARCHAR(255) NOT NULL UNIQUE,
    setting_group VARCHAR(100) NOT NULL,
    setting_category VARCHAR(100),
    setting_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Value and type
    value_type VARCHAR(30) NOT NULL CHECK (
        value_type IN ('STRING', 'INTEGER', 'BOOLEAN', 'FLOAT', 'JSON', 'ARRAY', 'ENCRYPTED')
    ),
    value_text TEXT,
    value_integer BIGINT,
    value_boolean BOOLEAN,
    value_float NUMERIC(15,6),
    value_json JSONB,
    value_array TEXT[],

    -- Validation
    validation_rules JSONB,
    allowed_values TEXT[],
    min_value NUMERIC(15,6),
    max_value NUMERIC(15,6),
    pattern_regex VARCHAR(500),

    -- Scope and environment
    scope_type VARCHAR(20) DEFAULT 'GLOBAL' CHECK (
        scope_type IN ('GLOBAL', 'TENANT', 'USER', 'REGION', 'ENVIRONMENT')
    ),
    scope_id UUID,
    environment VARCHAR(20) DEFAULT 'PRODUCTION' CHECK (
        environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'DR')
    ),

    -- Versioning
    version INTEGER DEFAULT 1 CHECK (version >= 1),
    previous_value TEXT,
    change_reason TEXT,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_sensitive BOOLEAN DEFAULT FALSE,
    is_encrypted BOOLEAN DEFAULT FALSE,
    encryption_key_id UUID,

    -- Access control
    read_roles VARCHAR(50)[],
    write_roles VARCHAR(50)[],
    requires_approval BOOLEAN DEFAULT FALSE,
    approval_workflow_id UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    approved_by UUID,
    approved_at TIMESTAMP WITH TIME ZONE,
    last_accessed_at TIMESTAMP WITH TIME ZONE,
    access_count INTEGER DEFAULT 0 CHECK (access_count >= 0),

    -- Metadata
    tags VARCHAR(50)[],
    documentation_url VARCHAR(500),
    owner_team VARCHAR(100),
    review_frequency_days INTEGER DEFAULT 90 CHECK (review_frequency_days >= 30),
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE
);

--================================================================================================
-- SEQUENCE CREATION
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.wallet_transaction_sequence START 1000;

--================================================================================================
-- COMMENTS FOR TABLES
--================================================================================================
COMMENT ON TABLE socialcandor_schema.photos IS 'Dedicated photo storage with EXIF metadata preservation and geotagging';
COMMENT ON TABLE socialcandor_schema.photo_albums IS 'Logical grouping of photos with cover image selection and collaborative capabilities';
COMMENT ON TABLE socialcandor_schema.videos IS 'Video content repository with streaming metadata and adaptive bitrate support';
COMMENT ON TABLE socialcandor_schema.events IS 'Event management system with geocoding, capacity limits, and ticketing support';
COMMENT ON TABLE socialcandor_schema.events_members IS 'Event attendance tracking with RSVP management and participation analytics';
COMMENT ON TABLE socialcandor_schema.user_wallets IS 'Digital wallet management for platform currency and payment processing';
COMMENT ON TABLE socialcandor_schema.wallet_transactions IS 'Comprehensive transaction ledger for wallet operations with audit trail';
COMMENT ON TABLE socialcandor_schema.payment_methods IS 'Stored payment method information with tokenization and security features';
COMMENT ON TABLE socialcandor_schema.system_countries IS 'Country reference data with compliance and regulatory information';
COMMENT ON TABLE socialcandor_schema.system_languages IS 'Language reference data with localization and translation support';
COMMENT ON TABLE socialcandor_schema.system_settings IS 'Centralized system configuration with versioning and audit trail';

--================================================================================================
-- INDEXES FOR ALL TABLES
--================================================================================================
-- Photos indexes
CREATE INDEX IF NOT EXISTS idx_photos_user_id ON socialcandor_schema.photos(user_id);
CREATE INDEX IF NOT EXISTS idx_photos_album_id ON socialcandor_schema.photos(album_id);
CREATE INDEX IF NOT EXISTS idx_photos_taken_at ON socialcandor_schema.photos(taken_at DESC);
CREATE INDEX IF NOT EXISTS idx_photos_location ON socialcandor_schema.photos USING GIST(location_coordinates);
CREATE INDEX IF NOT EXISTS idx_photos_visibility ON socialcandor_schema.photos(visibility);
CREATE INDEX IF NOT EXISTS idx_photos_created_at ON socialcandor_schema.photos(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_photos_exif_data ON socialcandor_schema.photos USING GIN(exif_data);

-- Photo albums indexes
CREATE INDEX IF NOT EXISTS idx_photo_albums_user_id ON socialcandor_schema.photo_albums(user_id);
CREATE INDEX IF NOT EXISTS idx_photo_albums_album_type ON socialcandor_schema.photo_albums(album_type);
CREATE INDEX IF NOT EXISTS idx_photo_albums_visibility ON socialcandor_schema.photo_albums(visibility);
CREATE INDEX IF NOT EXISTS idx_photo_albums_created_at ON socialcandor_schema.photo_albums(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_photo_albums_collaborative ON socialcandor_schema.photo_albums(is_collaborative) WHERE is_collaborative = TRUE;
CREATE INDEX IF NOT EXISTS idx_photo_albums_location ON socialcandor_schema.photo_albums USING GIST(location_coordinates);

-- Videos indexes
CREATE INDEX IF NOT EXISTS idx_videos_user_id ON socialcandor_schema.videos(user_id);
CREATE INDEX IF NOT EXISTS idx_videos_processing_status ON socialcandor_schema.videos(processing_status);
CREATE INDEX IF NOT EXISTS idx_videos_visibility ON socialcandor_schema.videos(visibility);
CREATE INDEX IF NOT EXISTS idx_videos_created_at ON socialcandor_schema.videos(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_videos_moderation ON socialcandor_schema.videos(moderation_status);

-- Events indexes
CREATE INDEX IF NOT EXISTS idx_events_organizer ON socialcandor_schema.events(organizer_user_id);
CREATE INDEX IF NOT EXISTS idx_events_start_datetime ON socialcandor_schema.events(start_datetime);
CREATE INDEX IF NOT EXISTS idx_events_location ON socialcandor_schema.events USING GIST(location_coordinates);
CREATE INDEX IF NOT EXISTS idx_events_status ON socialcandor_schema.events(event_status);
CREATE INDEX IF NOT EXISTS idx_events_type ON socialcandor_schema.events(event_type);

-- Events members indexes
CREATE INDEX IF NOT EXISTS idx_events_members_event ON socialcandor_schema.events_members(event_id);
CREATE INDEX IF NOT EXISTS idx_events_members_user ON socialcandor_schema.events_members(user_id);
CREATE INDEX IF NOT EXISTS idx_events_members_rsvp ON socialcandor_schema.events_members(rsvp_status);
CREATE INDEX IF NOT EXISTS idx_events_members_checkin ON socialcandor_schema.events_members(check_in_status);

-- Wallets indexes
CREATE INDEX IF NOT EXISTS idx_user_wallets_user ON socialcandor_schema.user_wallets(user_id);
CREATE INDEX IF NOT EXISTS idx_user_wallets_status ON socialcandor_schema.user_wallets(status);
CREATE INDEX IF NOT EXISTS idx_user_wallets_kyc ON socialcandor_schema.user_wallets(kyc_status);

-- Wallet transactions indexes
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_wallet ON socialcandor_schema.wallet_transactions(wallet_id);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_type ON socialcandor_schema.wallet_transactions(transaction_type);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_status ON socialcandor_schema.wallet_transactions(status);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_created ON socialcandor_schema.wallet_transactions(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_reconciliation ON socialcandor_schema.wallet_transactions(reconciliation_status);

-- Payment methods indexes
CREATE INDEX IF NOT EXISTS idx_payment_methods_user ON socialcandor_schema.payment_methods(user_id);
CREATE INDEX IF NOT EXISTS idx_payment_methods_type ON socialcandor_schema.payment_methods(payment_method_type);
CREATE INDEX IF NOT EXISTS idx_payment_methods_status ON socialcandor_schema.payment_methods(status);
CREATE INDEX IF NOT EXISTS idx_payment_methods_default ON socialcandor_schema.payment_methods(is_default) WHERE is_default = TRUE;

-- System countries indexes
CREATE INDEX IF NOT EXISTS idx_system_countries_code ON socialcandor_schema.system_countries(country_code);
CREATE INDEX IF NOT EXISTS idx_system_countries_region ON socialcandor_schema.system_countries(region);
CREATE INDEX IF NOT EXISTS idx_system_countries_gdpr ON socialcandor_schema.system_countries(gdpr_applicable);

