CREATE INDEX IF NOT EXISTS idx_system_languages_active ON socialcandor_schema.system_languages(is_active) WHERE is_active = TRUE;

-- System settings indexes
CREATE INDEX IF NOT EXISTS idx_system_settings_key ON socialcandor_schema.system_settings(setting_key);
CREATE INDEX IF NOT EXISTS idx_system_settings_group ON socialcandor_schema.system_settings(setting_group);
CREATE INDEX IF NOT EXISTS idx_system_settings_environment ON socialcandor_schema.system_settings(environment);

--================================================================================================
-- ALTER TABLE CONSTRAINTS
--================================================================================================
-- Photos constraints
ALTER TABLE socialcandor_schema.photos
    ADD CONSTRAINT chk_photo_dimensions CHECK (width_pixels > 0 AND height_pixels > 0),
    ADD CONSTRAINT chk_file_size_limit CHECK (file_size_bytes <= 5368709120),
    ADD CONSTRAINT chk_latitude_range CHECK (latitude IS NULL OR (latitude >= -90 AND latitude <= 90)),
    ADD CONSTRAINT chk_longitude_range CHECK (longitude IS NULL OR (longitude >= -180 AND longitude <= 180));

-- Photo albums constraints
ALTER TABLE socialcandor_schema.photo_albums
    ADD CONSTRAINT chk_album_dates CHECK (
        (start_date IS NULL AND end_date IS NULL) OR
        (start_date IS NOT NULL AND (end_date IS NULL OR end_date >= start_date))
    ),
    ADD CONSTRAINT chk_album_slug_format CHECK (
        album_slug IS NULL OR album_slug ~ '^[a-z0-9-]{3,200}$'
    );

-- Events constraints
ALTER TABLE socialcandor_schema.events
    ADD CONSTRAINT chk_event_dates CHECK (
        end_datetime IS NULL OR end_datetime >= start_datetime
    ),
    ADD CONSTRAINT chk_event_capacity CHECK (
        current_participant_count <= max_participants
    );

-- Events members constraints
ALTER TABLE socialcandor_schema.events_members
    ADD CONSTRAINT chk_events_members_unique UNIQUE (event_id, user_id),
    ADD CONSTRAINT chk_feedback_rating CHECK (feedback_rating IS NULL OR (feedback_rating >= 1 AND feedback_rating <= 5));

-- Wallets constraints
ALTER TABLE socialcandor_schema.user_wallets
    ADD CONSTRAINT chk_wallet_balance CHECK (available_balance >= 0),
    ADD CONSTRAINT chk_wallet_limits CHECK (
        daily_transaction_limit IS NULL OR daily_transaction_limit >= 0
    );

-- Wallet transactions constraints
ALTER TABLE socialcandor_schema.wallet_transactions
    ADD CONSTRAINT chk_transaction_amount CHECK (amount != 0),
    ADD CONSTRAINT chk_balance_calculation CHECK (balance_after = balance_before + amount);

-- Payment methods constraints
ALTER TABLE socialcandor_schema.payment_methods
    ADD CONSTRAINT chk_card_expiry CHECK (
        card_exp_year IS NULL OR card_exp_year >= EXTRACT(YEAR FROM CURRENT_DATE)
    );

-- System settings constraints
ALTER TABLE socialcandor_schema.system_settings
    ADD CONSTRAINT chk_setting_value CHECK (
        (value_type = 'STRING' AND value_text IS NOT NULL) OR
        (value_type = 'INTEGER' AND value_integer IS NOT NULL) OR
        (value_type = 'BOOLEAN' AND value_boolean IS NOT NULL) OR
        (value_type = 'FLOAT' AND value_float IS NOT NULL) OR
        (value_type = 'JSON' AND value_json IS NOT NULL) OR
        (value_type = 'ARRAY' AND value_array IS NOT NULL)
    );

--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================
-- Enable RLS on sensitive tables
ALTER TABLE socialcandor_schema.photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.photo_albums ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_wallets ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.wallet_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.payment_methods ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.system_settings ENABLE ROW LEVEL SECURITY;

-- Photos RLS policy
CREATE POLICY photos_user_isolation_policy ON socialcandor_schema.photos
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        ) OR
        visibility IN ('PUBLIC', 'UNLISTED')
    );

-- Photo albums RLS policy
CREATE POLICY photo_albums_user_isolation_policy ON socialcandor_schema.photo_albums
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        ) OR
        visibility = 'PUBLIC'
    );

-- Videos RLS policy
CREATE POLICY videos_user_isolation_policy ON socialcandor_schema.videos
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        ) OR
        visibility = 'PUBLIC'
    );

-- Wallets RLS policy
CREATE POLICY wallets_user_isolation_policy ON socialcandor_schema.user_wallets
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- Wallet transactions RLS policy
CREATE POLICY wallet_transactions_user_isolation_policy ON socialcandor_schema.wallet_transactions
    FOR ALL
    USING (
        wallet_id IN (
            SELECT wallet_id FROM socialcandor_schema.user_wallets
            WHERE user_id = current_setting('app.current_user_id')::UUID
        ) OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- Payment methods RLS policy
CREATE POLICY payment_methods_user_isolation_policy ON socialcandor_schema.payment_methods
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- System settings RLS policy
CREATE POLICY system_settings_read_policy ON socialcandor_schema.system_settings
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            JOIN socialcandor_schema.role_assignments ra ON u.user_id = ra.user_id
            JOIN socialcandor_schema.roles r ON ra.role_id = r.role_id
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND r.role_name IN ('ADMIN', 'SYSTEM_ADMIN', 'CONFIG_MANAGER')
        )
    );

CREATE POLICY system_settings_write_policy ON socialcandor_schema.system_settings
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            JOIN socialcandor_schema.role_assignments ra ON u.user_id = ra.user_id
            JOIN socialcandor_schema.roles r ON ra.role_id = r.role_id
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND r.role_name IN ('SYSTEM_ADMIN', 'CONFIG_MANAGER')
        )
    );

--================================================================================================
-- TRIGGERS FOR UPDATED_AT
--================================================================================================
CREATE OR REPLACE FUNCTION socialcandor_schema.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    NEW.updated_by = current_setting('app.current_user_id')::UUID;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_photos_updated_at
    BEFORE UPDATE ON socialcandor_schema.photos
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_photo_albums_updated_at
    BEFORE UPDATE ON socialcandor_schema.photo_albums
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_videos_updated_at
    BEFORE UPDATE ON socialcandor_schema.videos
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_events_updated_at
    BEFORE UPDATE ON socialcandor_schema.events
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_events_members_updated_at
    BEFORE UPDATE ON socialcandor_schema.events_members
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_user_wallets_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_wallets
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_wallet_transactions_updated_at
    BEFORE UPDATE ON socialcandor_schema.wallet_transactions
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_payment_methods_updated_at
    BEFORE UPDATE ON socialcandor_schema.payment_methods
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_system_settings_updated_at
    BEFORE UPDATE ON socialcandor_schema.system_settings
    FOR EACH ROW
    EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



--================================================================================================
-- Table: 32 - data_quality_rules
-- Description: Data validation rules for automated quality monitoring and enforcement
-- Business Case: Enables proactive data quality management through rule-based validation,
--                preventing bad data from entering production systems. Supports compliance
--                with data governance requirements and reduces downstream data issues.
-- KPIs: Rule coverage rate, validation success rate, data quality score improvement
-- Feature Reference: DQ01 (Data Quality), GOV01 (Data Governance), VAL01 (Validation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_rules (
    -- Primary key
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rule identification
    rule_name VARCHAR(200) NOT NULL,
    rule_code VARCHAR(100) UNIQUE NOT NULL,
    rule_description TEXT,
    rule_category VARCHAR(50) NOT NULL CHECK (
        rule_category IN ('COMPLETENESS', 'ACCURACY', 'CONSISTENCY', 'TIMELINESS', 'VALIDITY', 'UNIQUENESS', 'INTEGRITY')
    ),

    -- Target specification
    target_entity_type VARCHAR(50) NOT NULL CHECK (
        target_entity_type IN ('TABLE', 'COLUMN', 'VIEW', 'PIPELINE', 'DATASET')
    ),
    target_schema VARCHAR(100),
    target_table_name VARCHAR(100),
    target_column_name VARCHAR(100),
    target_filter_condition TEXT,

    -- Rule definition
    rule_type VARCHAR(50) NOT NULL CHECK (
        rule_type IN ('NULL_CHECK', 'RANGE_CHECK', 'PATTERN_CHECK', 'REFERENTIAL_CHECK', 'UNIQUENESS_CHECK', 'CUSTOM_SQL')
    ),
    rule_expression TEXT NOT NULL,
    rule_parameters JSONB DEFAULT '{}',
    expected_data_type VARCHAR(50),
    expected_pattern VARCHAR(500),
    min_value NUMERIC(15,6),
    max_value NUMERIC(15,6),
    allowed_values TEXT[],

    -- Severity and enforcement
    severity_level VARCHAR(20) DEFAULT 'MEDIUM' CHECK (
        severity_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')
    ),
    enforcement_level VARCHAR(20) DEFAULT 'WARNING' CHECK (
        enforcement_level IN ('INFO', 'WARNING', 'ERROR', 'BLOCK')
    ),
    auto_remediation_enabled BOOLEAN DEFAULT FALSE,
    remediation_script TEXT,

    -- Scheduling
    evaluation_frequency VARCHAR(20) DEFAULT 'DAILY' CHECK (
        evaluation_frequency IN ('REALTIME', 'HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'ON_DEMAND')
    ),
    evaluation_schedule_cron VARCHAR(100),
    timezone VARCHAR(50) DEFAULT 'UTC',

    -- Thresholds
    warning_threshold NUMERIC(5,2) DEFAULT 80.0 CHECK (warning_threshold >= 0 AND warning_threshold <= 100),
    critical_threshold NUMERIC(5,2) DEFAULT 95.0 CHECK (critical_threshold >= 0 AND critical_threshold <= 100),
    sample_size INTEGER DEFAULT 10000 CHECK (sample_size >= 100),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_system_managed BOOLEAN DEFAULT FALSE,
    version INTEGER DEFAULT 1 CHECK (version >= 1),

    -- Ownership
    owner_user_id UUID,
    owner_team VARCHAR(100),
    steward_user_id UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    last_evaluated_at TIMESTAMP WITH TIME ZONE,
    last_modified_at TIMESTAMP WITH TIME ZONE,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: 45 - role_permissions
-- Description: Role-to-permission mappings with conditional and time-bound assignments
-- Business Case: Enables fine-grained access control through role-permission relationships
--                supporting conditional permissions, time-bound access, and inheritance.
--                Critical for RBAC compliance and audit requirements.
-- KPIs: Permission assignment accuracy, access violation rate, audit compliance score
-- Feature Reference: RBAC02 (Permission Management), SEC06 (Authorization), AUD03 (Permission Audit)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.role_permissions (
    -- Primary key
    role_permission_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    role_id UUID NOT NULL,
    permission_id UUID NOT NULL,

    -- Assignment details
    assignment_type VARCHAR(20) DEFAULT 'DIRECT' CHECK (
        assignment_type IN ('DIRECT', 'INHERITED', 'CONDITIONAL', 'DELEGATED', 'TEMPORARY')
    ),
    inherited_from_role_id UUID,

    -- Conditional permissions
    condition_logic TEXT,
    condition_parameters JSONB DEFAULT '{}',
    condition_validity JSONB DEFAULT '{
        "valid_from": null,
        "valid_to": null,
        "recurrence": null
    }',

    -- Delegation details
    delegated_by UUID,
    delegated_at TIMESTAMP WITH TIME ZONE,
    delegation_depth INTEGER DEFAULT 0 CHECK (delegation_depth >= 0),
    max_delegation_depth INTEGER DEFAULT 3 CHECK (max_delegation_depth >= 0),

    -- Time-bound access
    valid_from TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    valid_to TIMESTAMP WITH TIME ZONE,
    is_permanent BOOLEAN DEFAULT FALSE,

    -- Scope restrictions
    resource_scope VARCHAR(50) DEFAULT 'ALL' CHECK (
        resource_scope IN ('ALL', 'OWN', 'TEAM', 'DEPARTMENT', 'ORGANIZATION')
    ),
    scope_filters JSONB DEFAULT '{}',

    -- Override capabilities
    can_override BOOLEAN DEFAULT FALSE,
    override_reason_required BOOLEAN DEFAULT TRUE,
    max_override_duration_days INTEGER CHECK (max_override_duration_days >= 0),

    -- Exclusion rules
    exclusion_rules JSONB DEFAULT '{}',
    conflicting_assignments UUID[] DEFAULT '{}',

    -- Performance optimization
    caching_enabled BOOLEAN DEFAULT TRUE,
    cache_ttl_seconds INTEGER DEFAULT 3600 CHECK (cache_ttl_seconds >= 0),
    precomputed_flag BOOLEAN DEFAULT FALSE,

    -- Custom attributes
    tags VARCHAR(50)[] DEFAULT '{}',
    metadata JSONB DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    reviewed_at TIMESTAMP WITH TIME ZONE,
    reviewed_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,

    -- Constraints
    CONSTRAINT uk_role_permission_unique UNIQUE (role_id, permission_id, valid_from),
    CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE CASCADE,
    CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id)
        REFERENCES socialcandor_schema.permissions(permission_id) ON DELETE CASCADE,
    CONSTRAINT chk_validity_dates CHECK (
        (valid_to IS NULL) OR (valid_to > valid_from)
    ),
    CONSTRAINT chk_delegation_depth CHECK (delegation_depth <= max_delegation_depth)
);

--================================================================================================
-- Table: 46 - permission_assignments
-- Description: Direct user-to-permission assignments for exceptional access cases
-- Business Case: Supports just-in-time access grants and emergency access scenarios
--                while maintaining audit trail for compliance. Enables temporary
--                privilege elevation with automatic expiration.
-- KPIs: Assignment accuracy, expiration compliance, audit trail completeness
-- Feature Reference: RBAC03 (Direct Assignment), SEC07 (Emergency Access), AUD04 (Access Audit)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.permission_assignments (
    -- Primary key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    permission_id UUID NOT NULL,

    -- Assignment type
    assignment_type VARCHAR(20) NOT NULL CHECK (
        assignment_type IN ('DIRECT', 'TEMPORARY', 'EMERGENCY', 'DELEGATED', 'SERVICE_ACCOUNT')
    ),

    -- Justification
    justification TEXT NOT NULL,
    approval_required BOOLEAN DEFAULT TRUE,
    approved_by UUID,
    approved_at TIMESTAMP WITH TIME ZONE,
    approval_workflow_id UUID,

    -- Time bounds
    granted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,
    auto_revoke_enabled BOOLEAN DEFAULT TRUE,

    -- Usage tracking
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    last_used_at TIMESTAMP WITH TIME ZONE,
    max_usage_count INTEGER CHECK (max_usage_count >= 0),

    -- Scope
    resource_scope VARCHAR(50) DEFAULT 'ALL' CHECK (
        resource_scope IN ('ALL', 'SPECIFIC', 'OWN', 'TEAM')
    ),
    resource_filters JSONB DEFAULT '{}',

    -- Security context
    requires_mfa BOOLEAN DEFAULT FALSE,
    session_timeout_minutes INTEGER DEFAULT 60 CHECK (session_timeout_minutes >= 5),
    ip_restrictions VARCHAR(100)[] DEFAULT '{}',

    -- Compliance and auditing
    is_privileged BOOLEAN DEFAULT FALSE,
    requires_approval BOOLEAN DEFAULT FALSE,
    approval_workflow_id UUID,
    review_frequency_days INTEGER DEFAULT 90 CHECK (review_frequency_days >= 30),
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE,

    -- Customization
    custom_properties JSONB DEFAULT '{}',
    tags VARCHAR(50)[] DEFAULT '{}',

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_by UUID,
    revocation_reason TEXT,

    -- Constraints
    CONSTRAINT uk_user_permission_unique UNIQUE (user_id, permission_id, granted_at),
    CONSTRAINT fk_permission_assignments_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_permission_assignments_permission FOREIGN KEY (permission_id)
        REFERENCES socialcandor_schema.permissions(permission_id) ON DELETE CASCADE,
    CONSTRAINT chk_expiration CHECK (
        (expires_at IS NULL) OR (expires_at > granted_at)
    )
);

--================================================================================================
-- Table: 47 - content_preferences
-- Description: User content consumption preferences for personalization
-- Business Case: Enables personalized content delivery based on user preferences,
--                improving engagement and satisfaction. Supports content filtering
--                and recommendation optimization.
-- KPIs: Preference adoption rate, engagement improvement, content relevance score
-- Feature Reference: REC01 (Recommendations), PER01 (Personalization), ENG01 (Engagement)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.content_preferences (
    -- Primary key
    preference_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL,

    -- Content type preferences
    preferred_content_types VARCHAR(50)[] DEFAULT '{}',
    excluded_content_types VARCHAR(50)[] DEFAULT '{}',
    content_type_weights JSONB DEFAULT '{}',

    -- Topic preferences
    preferred_topics VARCHAR(100)[] DEFAULT '{}',
    excluded_topics VARCHAR(100)[] DEFAULT '{}',
    topic_weights JSONB DEFAULT '{}',

    -- Creator preferences
    preferred_creators UUID[] DEFAULT '{}',
    muted_creators UUID[] DEFAULT '{}',
    creator_weights JSONB DEFAULT '{}',

    -- Format preferences
    preferred_formats VARCHAR(50)[] DEFAULT '{}',
    preferred_languages VARCHAR(10)[] DEFAULT '{}',
    preferred_duration_range VARCHAR(20),

    -- Quality settings
    minimum_quality_score NUMERIC(5,2) DEFAULT 0 CHECK (minimum_quality_score >= 0 AND minimum_quality_score <= 100),
    prefer_verified_content BOOLEAN DEFAULT FALSE,
    prefer_original_content BOOLEAN DEFAULT TRUE,

    -- Sensitivity settings
    nsfw_tolerance VARCHAR(20) DEFAULT 'STRICT' CHECK (
        nsfw_tolerance IN ('STRICT', 'MODERATE', 'RELAXED', 'UNRESTRICTED')
    ),
    sensitive_topic_filter BOOLEAN DEFAULT TRUE,
    spoiler_filter_enabled BOOLEAN DEFAULT TRUE,

    -- Engagement preferences
    auto_play_videos BOOLEAN DEFAULT TRUE,
    show_reactions BOOLEAN DEFAULT TRUE,
    show_view_counts BOOLEAN DEFAULT TRUE,
    show_share_counts BOOLEAN DEFAULT TRUE,

    -- Notification preferences
    content_update_notifications BOOLEAN DEFAULT TRUE,
    trending_notifications BOOLEAN DEFAULT FALSE,
    recommendation_notifications BOOLEAN DEFAULT TRUE,

    -- Algorithm settings
    diversity_factor NUMERIC(5,2) DEFAULT 0.3 CHECK (diversity_factor >= 0 AND diversity_factor <= 1),
    novelty_factor NUMERIC(5,2) DEFAULT 0.2 CHECK (novelty_factor >= 0 AND novelty_factor <= 1),
    recency_weight NUMERIC(5,2) DEFAULT 0.5 CHECK (recency_weight >= 0 AND recency_weight <= 1),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    last_updated_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT uk_user_content_preferences UNIQUE (user_id),
    CONSTRAINT fk_content_preferences_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

--================================================================================================
-- Table: 48 - content_similarity
-- Description: Content similarity scores for duplicate detection and recommendations
-- Business Case: Enables content deduplication, plagiarism detection, and similar
--                content recommendations. Supports content quality management and
--                copyright protection.
-- KPIs: Duplicate detection accuracy, similarity score precision, recommendation CTR
-- Feature Reference: REC02 (Similar Content), DQ02 (Duplicate Detection), CPY01 (Copyright)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.content_similarity (
    -- Primary key
    similarity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Content references
    content_id_1 UUID NOT NULL,
    content_id_2 UUID NOT NULL,
    content_type VARCHAR(50) NOT NULL CHECK (
        content_type IN ('POST', 'ARTICLE', 'VIDEO', 'IMAGE', 'AUDIO', 'DOCUMENT')
    ),

    -- Similarity scores
    overall_similarity_score NUMERIC(5,2) NOT NULL CHECK (overall_similarity_score >= 0 AND overall_similarity_score <= 100),
    text_similarity_score NUMERIC(5,2) CHECK (text_similarity_score >= 0 AND text_similarity_score <= 100),
    image_similarity_score NUMERIC(5,2) CHECK (image_similarity_score >= 0 AND image_similarity_score <= 100),
    semantic_similarity_score NUMERIC(5,2) CHECK (semantic_similarity_score >= 0 AND semantic_similarity_score <= 100),
    structural_similarity_score NUMERIC(5,2) CHECK (structural_similarity_score >= 0 AND structural_similarity_score <= 100),

    -- Detection method
    detection_method VARCHAR(50) DEFAULT 'HASH' CHECK (
        detection_method IN ('HASH', 'FINGERPRINT', 'EMBEDDING', 'NLP', 'COMPUTER_VISION', 'HYBRID')
    ),
    algorithm_version VARCHAR(20),
    model_id UUID,

    -- Match details
    matching_segments JSONB DEFAULT '[]',
    matching_percentage NUMERIC(5,2) CHECK (matching_percentage >= 0 AND matching_percentage <= 100),
    matched_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Classification
    similarity_type VARCHAR(30) DEFAULT 'DUPLICATE' CHECK (
        similarity_type IN ('DUPLICATE', 'NEAR_DUPLICATE', 'SIMILAR', 'RELATED', 'DERIVATIVE')
    ),
    is_confirmed_duplicate BOOLEAN DEFAULT FALSE,
    confirmed_by UUID,
    confirmed_at TIMESTAMP WITH TIME ZONE,

    -- Action taken
    action_taken VARCHAR(30) CHECK (
        action_taken IN ('NONE', 'FLAGGED', 'MERGED', 'HIDDEN', 'REMOVED', 'ATTRIBUTED')
    ),
    action_taken_at TIMESTAMP WITH TIME ZONE,
    action_taken_by UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT uk_content_pair_unique UNIQUE (content_id_1, content_id_2, detection_method),
    CONSTRAINT chk_content_order CHECK (content_id_1 < content_id_2)
);

--================================================================================================
-- Table: 49 - user_segments
-- Description: User segmentation definitions for targeted campaigns and personalization
-- Business Case: Enables precise user targeting for marketing, content delivery, and
--                feature rollouts. Supports dynamic and static segments with complex
--                criteria definitions.
-- KPIs: Segment accuracy, targeting effectiveness, conversion rate by segment
-- Feature Reference: SEG01 (User Segmentation), MKT01 (Targeting), PER02 (Personalization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_segments (
    -- Primary key
    segment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Segment identification
    segment_name VARCHAR(200) NOT NULL,
    segment_code VARCHAR(100) UNIQUE NOT NULL,
    segment_description TEXT,

    -- Segment type
    segment_type VARCHAR(30) DEFAULT 'STATIC' CHECK (
        segment_type IN ('STATIC', 'DYNAMIC', 'HYBRID', 'ML_BASED', 'BEHAVIORAL')
    ),
    segment_category VARCHAR(50) CHECK (
        segment_category IN ('DEMOGRAPHIC', 'BEHAVIORAL', 'PSYCHOGRAPHIC', 'GEOGRAPHIC', 'ENGAGEMENT', 'VALUE')
    ),

    -- Criteria definition
    criteria_definition JSONB NOT NULL DEFAULT '{}',
    criteria_logic VARCHAR(10) DEFAULT 'AND' CHECK (criteria_logic IN ('AND', 'OR')),

    -- Population
    estimated_size INTEGER,
    actual_size INTEGER DEFAULT 0 CHECK (actual_size >= 0),
    last_calculated_at TIMESTAMP WITH TIME ZONE,

    -- Refresh settings
    refresh_frequency VARCHAR(20) DEFAULT 'DAILY' CHECK (
        refresh_frequency IN ('REALTIME', 'HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'MANUAL')
    ),
    auto_refresh_enabled BOOLEAN DEFAULT TRUE,
    last_refresh_at TIMESTAMP WITH TIME ZONE,
    next_refresh_at TIMESTAMP WITH TIME ZONE,

    -- Usage
    is_active BOOLEAN DEFAULT TRUE,
    is_system_managed BOOLEAN DEFAULT FALSE,
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Ownership
    owner_user_id UUID,
    owner_team VARCHAR(100),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID
);

--================================================================================================
-- Table: 50 - segment_members
-- Description: User-to-segment membership tracking
-- Business Case: Tracks which users belong to which segments for efficient targeting
--                and personalization. Supports historical membership tracking for
--                trend analysis.
-- KPIs: Membership accuracy, segment coverage, churn rate by segment
-- Feature Reference: SEG02 (Membership Tracking), ANL01 (Segment Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.segment_members (
    -- Primary key
    membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    segment_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Membership details
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    added_reason VARCHAR(100),
    added_by VARCHAR(50) DEFAULT 'SYSTEM' CHECK (
        added_by IN ('SYSTEM', 'MANUAL', 'API', 'IMPORT', 'ML_MODEL')
    ),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    removed_at TIMESTAMP WITH TIME ZONE,
    removed_reason VARCHAR(100),

    -- Membership metadata
    membership_score NUMERIC(5,2) CHECK (membership_score >= 0 AND membership_score <= 100),
    confidence_level NUMERIC(5,2) CHECK (confidence_level >= 0 AND confidence_level <= 100),

    -- Historical tracking
    version INTEGER DEFAULT 1 CHECK (version >= 1),
    previous_segment_id UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT uk_segment_user_unique UNIQUE (segment_id, user_id, is_active),
    CONSTRAINT fk_segment_members_segment FOREIGN KEY (segment_id)
        REFERENCES socialcandor_schema.user_segments(segment_id) ON DELETE CASCADE,
    CONSTRAINT fk_segment_members_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

--================================================================================================
-- Table: 51 - segment_criteria
-- Description: Detailed criteria definitions for user segments
-- Business Case: Enables complex segment definitions with multiple conditions,
--                operators, and nested logic. Supports reusable criteria components.
-- KPIs: Criteria execution time, segment accuracy, criteria reuse rate
-- Feature Reference: SEG03 (Criteria Management), QUE01 (Query Builder)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.segment_criteria (
    -- Primary key
    criterion_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    segment_id UUID NOT NULL,
    parent_criterion_id UUID,

    -- Criterion definition
    criterion_name VARCHAR(200) NOT NULL,
    attribute_path VARCHAR(500) NOT NULL,
    attribute_type VARCHAR(50) NOT NULL CHECK (
        attribute_type IN ('STRING', 'NUMBER', 'DATE', 'BOOLEAN', 'ARRAY', 'OBJECT')
    ),

    -- Operator and value
    operator VARCHAR(30) NOT NULL CHECK (
        operator IN ('EQUALS', 'NOT_EQUALS', 'CONTAINS', 'NOT_CONTAINS', 'STARTS_WITH', 'ENDS_WITH',
                    'GREATER_THAN', 'LESS_THAN', 'GREATER_EQUALS', 'LESS_EQUALS',
                    'BETWEEN', 'IN', 'NOT_IN', 'IS_NULL', 'IS_NOT_NULL', 'REGEX')
    ),
    value_text TEXT,
    value_number NUMERIC(15,6),
    value_date TIMESTAMP WITH TIME ZONE,
    value_boolean BOOLEAN,
    value_array TEXT[],
    value_range JSONB,

    -- Logic
    logic_operator VARCHAR(10) DEFAULT 'AND' CHECK (logic_operator IN ('AND', 'OR', 'NOT')),
    precedence INTEGER DEFAULT 0 CHECK (precedence >= 0),
    is_negated BOOLEAN DEFAULT FALSE,

    -- Metadata
    is_required BOOLEAN DEFAULT FALSE,
    weight NUMERIC(5,2) DEFAULT 1.0 CHECK (weight >= 0),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_segment_criteria_segment FOREIGN KEY (segment_id)
        REFERENCES socialcandor_schema.user_segments(segment_id) ON DELETE CASCADE,
    CONSTRAINT fk_segment_criteria_parent FOREIGN KEY (parent_criterion_id)
        REFERENCES socialcandor_schema.segment_criteria(criterion_id) ON DELETE CASCADE
);

--================================================================================================
-- Table: 52 - ad_campaigns
-- Description: Advertising campaign configuration and management
-- Business Case: Enables comprehensive campaign management from creation through
--                completion with budget tracking, targeting, and performance analytics.
-- KPIs: Campaign ROI, CTR, conversion rate, budget utilization
-- Feature Reference: AD01 (Campaign Management), ANL02 (Ad Analytics), MON01 (Monetization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_campaigns (
    -- Primary key
    campaign_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    advertiser_id UUID NOT NULL,

    -- Campaign identification
    campaign_name VARCHAR(200) NOT NULL,
    campaign_code VARCHAR(100) UNIQUE NOT NULL,
    campaign_description TEXT,

    -- Campaign type and objectives
    campaign_type VARCHAR(50) NOT NULL DEFAULT 'AWARENESS' CHECK (
        campaign_type IN ('AWARENESS', 'CONSIDERATION', 'CONVERSION', 'RETENTION', 'REENGAGEMENT')
    ),
    primary_objective VARCHAR(50) NOT NULL CHECK (
        primary_objective IN ('BRAND_AWARENESS', 'REACH', 'TRAFFIC', 'ENGAGEMENT', 'APP_INSTALLS', 'VIDEO_VIEWS', 'LEAD_GENERATION', 'CONVERSIONS', 'SALES')
    ),

    -- Budget and bidding
    budget_type VARCHAR(20) DEFAULT 'LIFETIME' CHECK (budget_type IN ('DAILY', 'LIFETIME', 'ACCELERATED')),
    total_budget NUMERIC(15,2) NOT NULL CHECK (total_budget >= 0),
    daily_budget NUMERIC(15,2) CHECK (daily_budget >= 0),
    spent_amount NUMERIC(15,2) DEFAULT 0 CHECK (spent_amount >= 0),
    bid_strategy VARCHAR(30) DEFAULT 'AUTOMATIC' CHECK (
        bid_strategy IN ('AUTOMATIC', 'MANUAL', 'TARGET_CPA', 'TARGET_ROAS', 'MAXIMIZE_CONVERSIONS')
    ),
    bid_amount NUMERIC(15,6),
    currency_code CHAR(3) DEFAULT 'USD',

    -- Scheduling
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    end_date TIMESTAMP WITH TIME ZONE,
    timezone VARCHAR(50) DEFAULT 'UTC',
    delivery_type VARCHAR(20) DEFAULT 'STANDARD' CHECK (delivery_type IN ('STANDARD', 'ACCELERATED')),

    -- Targeting summary
    target_audience_summary JSONB DEFAULT '{}',
    geo_targeting JSONB DEFAULT '{}',
    device_targeting JSONB DEFAULT '{}',
    placement_targeting JSONB DEFAULT '{}',

    -- Status
    campaign_status VARCHAR(20) DEFAULT 'DRAFT' CHECK (
        campaign_status IN ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELLED', 'REJECTED')
    ),
    rejection_reason TEXT,

    -- Performance metrics
    impressions BIGINT DEFAULT 0 CHECK (impressions >= 0),
    clicks BIGINT DEFAULT 0 CHECK (clicks >= 0),
    conversions BIGINT DEFAULT 0 CHECK (conversions >= 0),
    ctr NUMERIC(5,4) CHECK (ctr >= 0 AND ctr <= 100),
    conversion_rate NUMERIC(5,4) CHECK (conversion_rate >= 0 AND conversion_rate <= 100),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Constraints
    CONSTRAINT fk_ad_campaigns_advertiser FOREIGN KEY (advertiser_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT chk_campaign_dates CHECK (
        (end_date IS NULL) OR (end_date > start_date)
    ),
    CONSTRAINT chk_budget_spent CHECK (spent_amount <= total_budget)
);

--================================================================================================
-- Table: 53 - ad_groups
-- Description: Ad group organization within campaigns for granular targeting
-- Business Case: Enables campaign structure optimization through ad group organization,
--                allowing different targeting and creative strategies within campaigns.
-- KPIs: Ad group performance, targeting efficiency, creative variation success
-- Feature Reference: AD02 (Ad Group Management), TAR01 (Targeting)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_groups (
    -- Primary key
    ad_group_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    campaign_id UUID NOT NULL,

    -- Ad group identification
    ad_group_name VARCHAR(200) NOT NULL,
    ad_group_description TEXT,

    -- Targeting
    audience_segment_ids UUID[] DEFAULT '{}',
    demographic_targeting JSONB DEFAULT '{}',
    interest_targeting JSONB DEFAULT '{}',
    behavior_targeting JSONB DEFAULT '{}',
    keyword_targeting TEXT[] DEFAULT '{}',
    exclusion_targeting JSONB DEFAULT '{}',

    -- Placements
    placement_types VARCHAR(50)[] DEFAULT '{}',
    placement_ids UUID[] DEFAULT '{}',
    automatic_placements BOOLEAN DEFAULT TRUE,

    -- Budget allocation
    budget_allocation_percentage NUMERIC(5,2) CHECK (budget_allocation_percentage >= 0 AND budget_allocation_percentage <= 100),
    bid_multiplier NUMERIC(5,2) DEFAULT 1.0 CHECK (bid_multiplier >= 0),

    -- Scheduling
    ad_schedule JSONB DEFAULT '{}',

    -- Status
    ad_group_status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (
        ad_group_status IN ('ACTIVE', 'PAUSED', 'ARCHIVED', 'DRAFT')
    ),

    -- Performance
    impressions BIGINT DEFAULT 0 CHECK (impressions >= 0),
    clicks BIGINT DEFAULT 0 CHECK (clicks >= 0),
    spent_amount NUMERIC(15,2) DEFAULT 0 CHECK (spent_amount >= 0),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_ad_groups_campaign FOREIGN KEY (campaign_id)
        REFERENCES socialcandor_schema.ad_campaigns(campaign_id) ON DELETE CASCADE,
    CONSTRAINT uk_ad_group_name UNIQUE (campaign_id, ad_group_name)
);

--================================================================================================
-- Table: 54 - ad_creatives
-- Description: Ad creative assets with multi-format support and brand safety
-- Business Case: Manages ad creative lifecycle from upload through approval with
--                brand safety checks and automatic resizing for placement requirements.
-- KPIs: Creative approval rate, brand safety score, creative performance
-- Feature Reference: AD03 (Creative Management), MOD04 (Brand Safety), TEST01 (A/B Testing)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_creatives (
    -- Primary key
    creative_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    campaign_id UUID NOT NULL,
    ad_group_id UUID,
    advertiser_id UUID NOT NULL,

    -- Creative identification
    creative_name VARCHAR(200) NOT NULL,
    creative_description TEXT,

    -- Creative type
    creative_type VARCHAR(30) NOT NULL CHECK (
        creative_type IN ('IMAGE', 'VIDEO', 'CAROUSEL', 'COLLECTION', 'STORY', 'PLAYABLE', 'HTML5')
    ),

    -- Media assets
    primary_image_url VARCHAR(500),
    secondary_image_urls VARCHAR(500)[],
    video_url VARCHAR(500),
    thumbnail_url VARCHAR(500),
    html5_bundle_url VARCHAR(500),

    -- Copy
    headline VARCHAR(200),
    body_text TEXT,
    call_to_action VARCHAR(50),
    cta_url VARCHAR(500),
    display_url VARCHAR(255),

    -- Specifications
    width_pixels INTEGER CHECK (width_pixels >= 0),
    height_pixels INTEGER CHECK (height_pixels >= 0),
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    duration_seconds NUMERIC(10,2) CHECK (duration_seconds >= 0),
    aspect_ratio VARCHAR(20),

    -- Variants
    is_variant BOOLEAN DEFAULT FALSE,
    variant_of_creative_id UUID,
    variant_weight INTEGER DEFAULT 100 CHECK (variant_weight >= 0 AND variant_weight <= 100),
    variant_test_id UUID,

    -- Brand safety
    brand_safety_score NUMERIC(5,2) CHECK (brand_safety_score >= 0 AND brand_safety_score <= 100),
    brand_safety_reviewed BOOLEAN DEFAULT FALSE,
    brand_safety_reviewed_at TIMESTAMP WITH TIME ZONE,

    -- Compliance
    compliance_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        compliance_status IN ('PENDING', 'APPROVED', 'REJECTED', 'REQUIRES_CHANGES')
    ),
    compliance_notes TEXT,
    regulatory_approvals JSONB DEFAULT '{}',

    -- Performance
    impressions BIGINT DEFAULT 0 CHECK (impressions >= 0),
    clicks BIGINT DEFAULT 0 CHECK (clicks >= 0),
    ctr NUMERIC(5,4) CHECK (ctr >= 0 AND ctr <= 100),

    -- Status
    creative_status VARCHAR(20) DEFAULT 'DRAFT' CHECK (
        creative_status IN ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'REJECTED', 'ACTIVE', 'PAUSED', 'ARCHIVED')
    ),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Constraints
    CONSTRAINT fk_ad_creatives_campaign FOREIGN KEY (campaign_id)
        REFERENCES socialcandor_schema.ad_campaigns(campaign_id) ON DELETE CASCADE,
    CONSTRAINT fk_ad_creatives_ad_group FOREIGN KEY (ad_group_id)
        REFERENCES socialcandor_schema.ad_groups(ad_group_id) ON DELETE SET NULL,
    CONSTRAINT chk_creative_dates CHECK (
        (end_date IS NULL) OR (end_date > start_date)
    ),
    CONSTRAINT chk_variant_weight CHECK (
        (is_variant = FALSE AND variant_weight = 100) OR is_variant = TRUE
    ),
    CONSTRAINT chk_media_requirements CHECK (
        (creative_type != 'IMAGE' OR primary_image_url IS NOT NULL) AND
        (creative_type != 'VIDEO' OR video_url IS NOT NULL)
    )
);

--================================================================================================
-- Table: 55 - ad_targeting
-- Description: Detailed targeting configurations for ad delivery optimization
-- Business Case: Enables precise audience targeting with demographic, behavioral,
--                and contextual signals for optimal ad delivery and ROI.
-- KPIs: Targeting accuracy, audience reach, conversion rate by target
-- Feature Reference: AD04 (Targeting Optimization), AUD01 (Audience Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_targeting (
    -- Primary key
    targeting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    ad_group_id UUID NOT NULL,
    campaign_id UUID NOT NULL,

    -- Targeting type
    targeting_type VARCHAR(30) NOT NULL CHECK (
        targeting_type IN ('DEMOGRAPHIC', 'GEOGRAPHIC', 'INTEREST', 'BEHAVIORAL', 'CONTEXTUAL', 'RETARGETING', 'LOOKALIKE', 'CUSTOM_AUDIENCE')
    ),

    -- Targeting values
    targeting_values JSONB NOT NULL DEFAULT '{}',
    inclusion_criteria JSONB DEFAULT '{}',
    exclusion_criteria JSONB DEFAULT '{}',

    -- Demographic
    age_min INTEGER CHECK (age_min >= 13),
    age_max INTEGER CHECK (age_max <= 100),
    genders VARCHAR(20)[] DEFAULT '{}',
    languages VARCHAR(10)[] DEFAULT '{}',
    education_levels VARCHAR(50)[] DEFAULT '{}',
    relationship_statuses VARCHAR(50)[] DEFAULT '{}',

    -- Geographic
    countries VARCHAR(3)[] DEFAULT '{}',
    regions VARCHAR(100)[] DEFAULT '{}',
    cities VARCHAR(100)[] DEFAULT '{}',
    postal_codes VARCHAR(20)[] DEFAULT '{}',
    radius_km INTEGER,
    location_coordinates GEOGRAPHY(POINT, 4326),

    -- Behavioral
    purchase_behaviors VARCHAR(100)[] DEFAULT '{}',
    device_types VARCHAR(50)[] DEFAULT '{}',
    connection_types VARCHAR(50)[] DEFAULT '{}',

    -- Interest
    interest_categories VARCHAR(100)[] DEFAULT '{}',
    interest_keywords TEXT[] DEFAULT '{}',

    -- Custom audiences
    custom_audience_ids UUID[] DEFAULT '{}',
    lookalike_source_id UUID,
    lookalike_percentage NUMERIC(5,2) CHECK (lookalike_percentage >= 1 AND lookalike_percentage <= 10),

    -- Optimization
    bid_adjustment NUMERIC(5,2) DEFAULT 1.0 CHECK (bid_adjustment >= 0),
    priority INTEGER DEFAULT 0 CHECK (priority >= 0),

    -- Performance
    estimated_reach INTEGER,
    actual_reach INTEGER DEFAULT 0 CHECK (actual_reach >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_ad_targeting_ad_group FOREIGN KEY (ad_group_id)
        REFERENCES socialcandor_schema.ad_groups(ad_group_id) ON DELETE CASCADE,
    CONSTRAINT fk_ad_targeting_campaign FOREIGN KEY (campaign_id)
        REFERENCES socialcandor_schema.ad_campaigns(campaign_id) ON DELETE CASCADE
);

--================================================================================================
-- Table: 56 - ad_performance
-- Description: Ad performance metrics and analytics tracking
-- Business Case: Provides comprehensive performance tracking for ads across all
--                dimensions enabling optimization and ROI analysis.
-- KPIs: ROAS, CPA, CTR, conversion rate, impression share
-- Feature Reference: AD05 (Performance Analytics), ANL03 (Ad Reporting)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_performance (
    -- Primary key
    performance_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    campaign_id UUID NOT NULL,
    ad_group_id UUID,
    creative_id UUID,

    -- Time dimension
    metric_date DATE NOT NULL DEFAULT CURRENT_DATE,
    metric_hour INTEGER CHECK (metric_hour >= 0 AND metric_hour <= 23),
    aggregation_level VARCHAR(20) DEFAULT 'DAILY' CHECK (
        aggregation_level IN ('HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'CAMPAIGN_LIFETIME')
    ),

    -- Delivery metrics
    impressions BIGINT DEFAULT 0 CHECK (impressions >= 0),
    reach INTEGER DEFAULT 0 CHECK (reach >= 0),
    frequency NUMERIC(5,2) CHECK (frequency >= 0),

    -- Engagement metrics
    clicks BIGINT DEFAULT 0 CHECK (clicks >= 0),
    ctr NUMERIC(5,4) CHECK (ctr >= 0 AND ctr <= 100),
    likes BIGINT DEFAULT 0 CHECK (likes >= 0),
    comments BIGINT DEFAULT 0 CHECK (comments >= 0),
    shares BIGINT DEFAULT 0 CHECK (shares >= 0),
    video_views BIGINT DEFAULT 0 CHECK (video_views >= 0),
    video_completion_rate NUMERIC(5,2) CHECK (video_completion_rate >= 0 AND video_completion_rate <= 100),

    -- Conversion metrics
    conversions BIGINT DEFAULT 0 CHECK (conversions >= 0),
    conversion_rate NUMERIC(5,4) CHECK (conversion_rate >= 0 AND conversion_rate <= 100),
    conversion_value NUMERIC(15,2) DEFAULT 0 CHECK (conversion_value >= 0),

    -- Cost metrics
    spent_amount NUMERIC(15,2) DEFAULT 0 CHECK (spent_amount >= 0),
    cpc NUMERIC(15,6) CHECK (cpc >= 0),
    cpm NUMERIC(15,6) CHECK (cpm >= 0),
    cpa NUMERIC(15,6) CHECK (cpa >= 0),
    roas NUMERIC(10,4) CHECK (roas >= 0),

    -- Quality metrics
    quality_score NUMERIC(5,2) CHECK (quality_score >= 0 AND quality_score <= 100),
    relevance_score NUMERIC(5,2) CHECK (relevance_score >= 0 AND relevance_score <= 100),
    engagement_rate NUMERIC(5,4) CHECK (engagement_rate >= 0 AND engagement_rate <= 100),

    -- Attribution
    attribution_model VARCHAR(30) DEFAULT 'LAST_CLICK' CHECK (
        attribution_model IN ('FIRST_CLICK', 'LAST_CLICK', 'LINEAR', 'TIME_DECAY', 'POSITION_BASED', 'DATA_DRIVEN')
    ),
    view_through_conversions BIGINT DEFAULT 0,
    click_through_conversions BIGINT DEFAULT 0,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_ad_performance_campaign FOREIGN KEY (campaign_id)
        REFERENCES socialcandor_schema.ad_campaigns(campaign_id) ON DELETE CASCADE,
    CONSTRAINT uk_ad_performance_unique UNIQUE (campaign_id, ad_group_id, creative_id, metric_date, metric_hour)
);

--================================================================================================
-- Table: 57 - moderation_queues
-- Description: Content moderation queue management for review workflows
-- Business Case: Enables efficient content moderation through intelligent queue
--                prioritization and moderator assignment. Supports multiple
--                moderation workflows and SLA tracking.
-- KPIs: Queue processing time, SLA compliance, moderator efficiency
-- Feature Reference: MOD01 (Moderation Queue), WF01 (Workflow Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.moderation_queues (
    -- Primary key
    queue_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Queue identification
    queue_name VARCHAR(200) NOT NULL,
    queue_code VARCHAR(100) UNIQUE NOT NULL,
    queue_description TEXT,

    -- Queue type
    queue_type VARCHAR(30) DEFAULT 'STANDARD' CHECK (
        queue_type IN ('STANDARD', 'PRIORITY', 'ESCALATION', 'APPEAL', 'AUTO_MODERATED', 'MANUAL_REVIEW')
    ),
    queue_category VARCHAR(50) CHECK (
        queue_category IN ('CONTENT', 'USER', 'REPORT', 'APPEAL', 'PRE_PUBLICATION', 'POST_PUBLICATION')
    ),

    -- Content types
    content_types VARCHAR(50)[] DEFAULT '{}',
    priority_content_types VARCHAR(50)[] DEFAULT '{}',

    -- Prioritization
    priority_algorithm VARCHAR(50) DEFAULT 'FIFO' CHECK (
        priority_algorithm IN ('FIFO', 'PRIORITY_SCORE', 'SEVERITY', 'SLA_URGENCY', 'CUSTOM')
    ),
    auto_prioritization_enabled BOOLEAN DEFAULT TRUE,

    -- Assignment
    assignment_mode VARCHAR(30) DEFAULT 'AUTOMATIC' CHECK (
        assignment_mode IN ('AUTOMATIC', 'MANUAL', 'ROUND_ROBIN', 'SKILL_BASED', 'LOAD_BALANCED')
    ),
    moderator_pool_ids UUID[] DEFAULT '{}',

    -- SLA configuration
    sla_response_time_minutes INTEGER CHECK (sla_response_time_minutes >= 0),
    sla_resolution_time_minutes INTEGER CHECK (sla_resolution_time_minutes >= 0),
    escalation_threshold_minutes INTEGER,

    -- Capacity
    max_queue_size INTEGER CHECK (max_queue_size >= 0),
    current_queue_size INTEGER DEFAULT 0 CHECK (current_queue_size >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_default BOOLEAN DEFAULT FALSE,

    -- Performance
    avg_processing_time_minutes NUMERIC(10,2),
    items_processed_today INTEGER DEFAULT 0,
    items_pending INTEGER DEFAULT 0,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

--================================================================================================
-- Table: 58 - moderation_actions
-- Description: Moderation action tracking and audit trail
-- Business Case: Provides complete audit trail of all moderation decisions
--                supporting compliance, appeals, and moderator performance tracking.
-- KPIs: Action accuracy, appeal success rate, moderator consistency
-- Feature Reference: MOD02 (Action Tracking), AUD05 (Moderation Audit)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.moderation_actions (
    -- Primary key
    action_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    content_id UUID NOT NULL,
    content_type VARCHAR(50) NOT NULL CHECK (
        content_type IN ('POST', 'COMMENT', 'MESSAGE', 'PROFILE', 'GROUP', 'PAGE', 'MEDIA', 'USER')
    ),
    content_owner_id UUID NOT NULL,

    -- Queue reference
    queue_id UUID,

    -- Action details
    action_type VARCHAR(50) NOT NULL CHECK (
        action_type IN ('APPROVE', 'REJECT', 'REMOVE', 'WARN', 'SUSPEND', 'BAN', 'EDIT', 'ESCALATE', 'OVERRIDE', 'FLAG')
    ),
    action_reason VARCHAR(200),
    action_notes TEXT,

    -- Policy reference
    policy_id UUID,
    policy_violation_type VARCHAR(100),
    severity_level VARCHAR(20) CHECK (
        severity_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')
    ),

    -- Moderator
    moderator_user_id UUID NOT NULL,
    moderator_action_time TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- AI assistance
    ai_recommendation VARCHAR(50),
    ai_confidence_score NUMERIC(5,2),
    ai_overridden BOOLEAN DEFAULT FALSE,
    override_reason TEXT,

    -- User notification
    notify_user BOOLEAN DEFAULT TRUE,
    notification_sent BOOLEAN DEFAULT FALSE,
    notification_template_id UUID,

    -- Appeal
    is_appealable BOOLEAN DEFAULT TRUE,
    appeal_deadline TIMESTAMP WITH TIME ZONE,
    appeal_status VARCHAR(20) CHECK (
        appeal_status IN ('PENDING', 'APPROVED', 'REJECTED', 'EXPIRED')
    ),

    -- Reversal
    is_reversible BOOLEAN DEFAULT TRUE,
    reversed_at TIMESTAMP WITH TIME ZONE,
    reversed_by UUID,
    reversal_reason TEXT,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_moderation_actions_content FOREIGN KEY (content_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_moderation_actions_moderator FOREIGN KEY (moderator_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_moderation_actions_queue FOREIGN KEY (queue_id)
        REFERENCES socialcandor_schema.moderation_queues(queue_id) ON DELETE SET NULL
);

--================================================================================================
-- Table: 59 - moderation_appeals
-- Description: Content moderation appeal management workflow
-- Business Case: Enables users to appeal moderation decisions with structured
--                review process ensuring fair treatment and compliance.
-- KPIs: Appeal resolution time, overturn rate, user satisfaction
-- Feature Reference: MOD03 (Appeal Management), USR01 (User Rights)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.moderation_appeals (
    -- Primary key
    appeal_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    moderation_action_id UUID NOT NULL,
    content_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Appeal details
    appeal_reason TEXT NOT NULL,
    appeal_category VARCHAR(50) CHECK (
        appeal_category IN ('WRONGFUL_REMOVAL', 'INCORRECT_CLASSIFICATION', 'CONTEXT_MISSED', 'POLICY_ERROR', 'TECHNICAL_ERROR', 'OTHER')
    ),
    supporting_evidence JSONB DEFAULT '[]',
    additional_comments TEXT,

    -- Status
    appeal_status VARCHAR(20) DEFAULT 'SUBMITTED' CHECK (
        appeal_status IN ('SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'ESCALATED', 'WITHDRAWN')
    ),
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Review
    reviewer_user_id UUID,
    review_started_at TIMESTAMP WITH TIME ZONE,
    review_completed_at TIMESTAMP WITH TIME ZONE,
    review_notes TEXT,
    review_decision VARCHAR(20) CHECK (
        review_decision IN ('UPHOLD', 'OVERTURN', 'PARTIAL', 'REQUIRES_MORE_INFO')
    ),

    -- Escalation
    escalation_level INTEGER DEFAULT 0 CHECK (escalation_level >= 0),
    escalated_at TIMESTAMP WITH TIME ZONE,
    escalated_to UUID,

    -- Resolution
    resolution VARCHAR(20) CHECK (
        resolution IN ('CONTENT_RESTORED', 'WARNING_ISSUED', 'NO_ACTION', 'PERMANENT_ACTION', 'COMPENSATION')
    ),
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolved_by UUID,

    -- User communication
    user_notified BOOLEAN DEFAULT FALSE,
    notification_sent_at TIMESTAMP WITH TIME ZONE,
    user_response TEXT,

    -- Metrics
    time_to_resolution_hours NUMERIC(10,2),
    was_successful BOOLEAN,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_moderation_appeals_action FOREIGN KEY (moderation_action_id)
        REFERENCES socialcandor_schema.moderation_actions(action_id) ON DELETE CASCADE,
    CONSTRAINT fk_moderation_appeals_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_content_appeal UNIQUE (user_id, content_id, appeal_status)
);

--================================================================================================
-- Table: 60 - dashboards
-- Description: Analytics dashboard definitions with layout and access control
-- Business Case: Enables personalized executive dashboards while supporting data
--                freshness SLAs through intelligent refresh scheduling.
-- KPIs: Dashboard adoption, data freshness, user satisfaction
-- Feature Reference: DASH01 (Dashboard Management), VIZ01 (Visualization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dashboards (
    -- Primary key
    dashboard_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    owner_user_id UUID NOT NULL,

    -- Dashboard identification
    dashboard_name VARCHAR(200) NOT NULL,
    dashboard_description TEXT,
    dashboard_code VARCHAR(100) UNIQUE,

    -- Classification
    dashboard_type VARCHAR(50) DEFAULT 'PERSONAL' CHECK (
        dashboard_type IN ('PERSONAL', 'SHARED', 'TEAM', 'EXECUTIVE', 'ANALYTICS', 'OPERATIONAL', 'PUBLIC')
    ),
    dashboard_category VARCHAR(100),

    -- Layout
    layout_template VARCHAR(50),
    layout_config JSONB DEFAULT '{}',
    grid_columns INTEGER DEFAULT 12 CHECK (grid_columns >= 1 AND grid_columns <= 24),

    -- Theme
    theme VARCHAR(50) DEFAULT 'LIGHT' CHECK (theme IN ('LIGHT', 'DARK', 'CUSTOM')),
    color_scheme VARCHAR(50),

    -- Sharing
    is_shared BOOLEAN DEFAULT FALSE,
    share_with_team BOOLEAN DEFAULT FALSE,
    share_with_organization BOOLEAN DEFAULT FALSE,
    public_url VARCHAR(500),
    public_url_expires_at TIMESTAMP WITH TIME ZONE,

    -- Access control
    access_level VARCHAR(20) DEFAULT 'PRIVATE' CHECK (
        access_level IN ('PRIVATE', 'TEAM', 'ORGANIZATION', 'PUBLIC')
    ),
    allowed_user_ids UUID[] DEFAULT '{}',
    allowed_role_ids UUID[] DEFAULT '{}',

    -- Refresh
    auto_refresh_enabled BOOLEAN DEFAULT TRUE,
    refresh_interval_seconds INTEGER DEFAULT 300 CHECK (refresh_interval_seconds >= 60),
    last_refreshed_at TIMESTAMP WITH TIME ZONE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_favorite BOOLEAN DEFAULT FALSE,
    is_default BOOLEAN DEFAULT FALSE,

    -- Usage
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    last_viewed_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_dashboards_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_default_dashboard UNIQUE (owner_user_id) WHERE is_default = TRUE
);

--================================================================================================
-- Table: 61 - dashboard_widgets
-- Description: Configurable analytics dashboard components with refresh intervals
-- Business Case: Enables drag-and-drop dashboard customization while maintaining
--                responsive layouts across device types.
-- KPIs: Widget usage, data freshness, render performance
-- Feature Reference: DASH02 (Widget Management), UI01 (User Interface)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dashboard_widgets (
    -- Primary key
    widget_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Widget identification
    widget_name VARCHAR(200) NOT NULL,
    widget_code VARCHAR(100) UNIQUE NOT NULL,
    widget_description TEXT,

    -- Classification
    widget_type VARCHAR(50) NOT NULL CHECK (
        widget_type IN ('CHART', 'TABLE', 'METRIC', 'MAP', 'LIST', 'FORM', 'CUSTOM', 'EMBEDDED')
    ),
    widget_category VARCHAR(100),

    -- Data source
    data_source_type VARCHAR(50) CHECK (
        data_source_type IN ('QUERY', 'API', 'STREAM', 'CACHE', 'STATIC')
    ),
    data_source_config JSONB DEFAULT '{}',
    query_definition TEXT,

    -- Visualization
    visualization_type VARCHAR(50),
    visualization_config JSONB DEFAULT '{}',

    -- Refresh
    refresh_interval_seconds INTEGER DEFAULT 300 CHECK (refresh_interval_seconds >= 0),
    cache_enabled BOOLEAN DEFAULT TRUE,
    cache_ttl_seconds INTEGER DEFAULT 300 CHECK (cache_ttl_seconds >= 0),
    last_refreshed_at TIMESTAMP WITH TIME ZONE,
    data_freshness_score NUMERIC(5,2) CHECK (data_freshness_score >= 0 AND data_freshness_score <= 100),

    -- Appearance
    width_cells INTEGER DEFAULT 4 CHECK (width_cells >= 1 AND width_cells <= 12),
    height_cells INTEGER DEFAULT 2 CHECK (height_cells >= 1),
    min_width_cells INTEGER DEFAULT 2,
    min_height_cells INTEGER DEFAULT 1,

    -- Interactivity
    is_filterable BOOLEAN DEFAULT TRUE,
    is_exportable BOOLEAN DEFAULT TRUE,
    is_downloadable BOOLEAN DEFAULT TRUE,
    drill_down_enabled BOOLEAN DEFAULT FALSE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_template BOOLEAN DEFAULT FALSE,
    template_of UUID,

    -- Performance
    avg_render_time_ms INTEGER,
    error_count INTEGER DEFAULT 0 CHECK (error_count >= 0),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT chk_template_inheritance CHECK (
        (is_template = TRUE AND template_of IS NULL) OR
        (is_template = FALSE AND template_of IS NOT NULL) OR
        (is_template = FALSE AND template_of IS NULL)
    )
);

--================================================================================================
-- Table: 62 - dashboard_widget_assignments
-- Description: Widget positioning within dashboards using grid coordinates
-- Business Case: Enables drag-and-drop dashboard customization while maintaining
--                responsive layouts across device types through coordinate normalization.
-- KPIs: Layout consistency, widget load time, user customization rate
-- Feature Reference: DASH03 (Widget Assignment), UI02 (Layout Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dashboard_widget_assignments (
    -- Primary key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    dashboard_id UUID NOT NULL,
    widget_id UUID NOT NULL,

    -- Positioning and layout
    grid_row INTEGER NOT NULL CHECK (grid_row >= 0),
    grid_column INTEGER NOT NULL CHECK (grid_column >= 0),
    width_cells INTEGER NOT NULL CHECK (width_cells >= 1 AND width_cells <= 12),
    height_cells INTEGER NOT NULL CHECK (height_cells >= 1 AND height_cells <= 12),
    z_index INTEGER DEFAULT 0 CHECK (z_index >= 0),

    -- Responsive behavior
    responsive_config JSONB DEFAULT '{}',
    mobile_grid_row INTEGER,
    mobile_grid_column INTEGER,
    mobile_width_cells INTEGER,
    mobile_height_cells INTEGER,

    -- Widget configuration
    widget_config JSONB DEFAULT '{}',
    widget_title_override VARCHAR(200),
    widget_filters JSONB DEFAULT '{}',

    -- Visibility
    is_visible BOOLEAN DEFAULT TRUE,
    visibility_conditions JSONB DEFAULT '{}',

    -- Status
    is_active BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_dashboard_assignments_dashboard FOREIGN KEY (dashboard_id)
        REFERENCES socialcandor_schema.dashboards(dashboard_id) ON DELETE CASCADE,
    CONSTRAINT fk_dashboard_assignments_widget FOREIGN KEY (widget_id)
        REFERENCES socialcandor_schema.dashboard_widgets(widget_id) ON DELETE CASCADE,
    CONSTRAINT uk_dashboard_widget_unique UNIQUE (dashboard_id, widget_id)
);

--================================================================================================
-- Table: 63 - widget_data_cache
-- Description: Cached widget data with expiration timestamps
-- Business Case: Reduces database load during dashboard access spikes while ensuring
--                data freshness through TTL-based invalidation.
-- KPIs: Cache hit rate, data freshness, query reduction
-- Feature Reference: CACHE01 (Data Caching), PERF01 (Performance Optimization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.widget_data_cache (
    -- Primary key
    cache_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    widget_id UUID NOT NULL,
    dashboard_id UUID,

    -- Cache identification
    cache_key VARCHAR(500) NOT NULL,
    cache_version INTEGER DEFAULT 1,

    -- Cached data
    cached_data JSONB NOT NULL,
    data_size_bytes INTEGER GENERATED ALWAYS AS (octet_length(cached_data::text)) STORED,
    compression_type VARCHAR(20) DEFAULT 'NONE' CHECK (
        compression_type IN ('NONE', 'GZIP', 'LZ4', 'SNAPPY')
    ),
    compressed_data BYTEA,

    -- Expiration and freshness
    cached_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    is_expired BOOLEAN GENERATED ALWAYS AS (expires_at < CURRENT_TIMESTAMP) STORED,
    ttl_seconds INTEGER NOT NULL CHECK (ttl_seconds >= 0),

    -- Metadata
    cache_hit_count INTEGER DEFAULT 0 CHECK (cache_hit_count >= 0),
    last_accessed_at TIMESTAMP WITH TIME ZONE,
    query_parameters_hash VARCHAR(100),
    data_source_signature VARCHAR(100),

    -- Status
    is_valid BOOLEAN DEFAULT TRUE,
    invalidation_reason VARCHAR(200),
    invalidated_at TIMESTAMP WITH TIME ZONE,
    invalidated_by UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT fk_widget_cache_widget FOREIGN KEY (widget_id)
        REFERENCES socialcandor_schema.dashboard_widgets(widget_id) ON DELETE CASCADE,
    CONSTRAINT uk_cache_key_unique UNIQUE (cache_key, cache_version)
);

--================================================================================================
-- Table: 64 - notification_templates
-- Description: Versioned notification copy with parameterized placeholders
-- Business Case: Enables consistent notification delivery across channels with
--                template versioning and localization support.
-- KPIs: Template usage, delivery success rate, user engagement
-- Feature Reference: NOTIFY01 (Template Management), LOC02 (Localization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.notification_templates (
    -- Primary key
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Template identification
    template_code VARCHAR(100) UNIQUE NOT NULL,
    template_name VARCHAR(200) NOT NULL,
    template_version VARCHAR(20) NOT NULL,
    is_current_version BOOLEAN DEFAULT TRUE,

    -- Classification
    template_type VARCHAR(50) NOT NULL CHECK (
        template_type IN ('SYSTEM', 'MARKETING', 'TRANSACTIONAL', 'SECURITY', 'SOCIAL', 'PROMOTIONAL')
    ),
    notification_category VARCHAR(100),

    -- Content
    subject_template TEXT,
    body_template TEXT NOT NULL,
    body_html_template TEXT,
    body_text_template TEXT,

    -- Variables
    required_variables VARCHAR(100)[] DEFAULT '{}',
    optional_variables VARCHAR(100)[] DEFAULT '{}',
    variable_defaults JSONB DEFAULT '{}',

    -- Localization
    language_code VARCHAR(10) DEFAULT 'en',
    locale_specific BOOLEAN DEFAULT FALSE,
    fallback_template_id UUID,

    -- Channel configuration
    channels VARCHAR(50)[] DEFAULT ARRAY['EMAIL']::VARCHAR(50)[],
    channel_configs JSONB DEFAULT '{}',

    -- Styling
    style_template_id UUID,
    branding_enabled BOOLEAN DEFAULT TRUE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_system_managed BOOLEAN DEFAULT FALSE,

    -- Usage
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    published_at TIMESTAMP WITH TIME ZONE,
    published_by UUID,

    -- Constraints
    CONSTRAINT uk_template_code_version UNIQUE (template_code, template_version)
);

--================================================================================================
-- Table: 65 - notification_delivery
-- Description: Notification delivery tracking with channel-specific status
-- Business Case: Provides complete delivery audit trail for notifications across
--                all channels with retry logic and delivery optimization.
-- KPIs: Delivery success rate, open rate, click-through rate
-- Feature Reference: NOTIFY02 (Delivery Tracking), ANL04 (Notification Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.notification_delivery (
    -- Primary key
    delivery_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    notification_id UUID NOT NULL,
    template_id UUID,
    user_id UUID NOT NULL,

    -- Channel
    channel VARCHAR(30) NOT NULL CHECK (
        channel IN ('EMAIL', 'SMS', 'PUSH', 'IN_APP', 'WEBHOOK', 'SLACK', 'TEAMS')
    ),

    -- Recipient
    recipient_address VARCHAR(500),
    recipient_device_id VARCHAR(255),

    -- Content
    subject TEXT,
    body TEXT,
    body_html TEXT,
    attachments JSONB DEFAULT '[]',

    -- Delivery status
    delivery_status VARCHAR(20) DEFAULT 'PENDING' CHECK (
        delivery_status IN ('PENDING', 'QUEUED', 'SENT', 'DELIVERED', 'OPENED', 'CLICKED', 'BOUNCED', 'FAILED', 'SUPPRESSED')
    ),
    status_reason TEXT,

    -- Timing
    queued_at TIMESTAMP WITH TIME ZONE,
    sent_at TIMESTAMP WITH TIME ZONE,
    delivered_at TIMESTAMP WITH TIME ZONE,
    opened_at TIMESTAMP WITH TIME ZONE,
    clicked_at TIMESTAMP WITH TIME ZONE,

    -- Retry logic
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),
    max_retries INTEGER DEFAULT 3 CHECK (max_retries >= 0),
    next_retry_at TIMESTAMP WITH TIME ZONE,
    last_error TEXT,

    -- Provider
    provider_name VARCHAR(50),
    provider_message_id VARCHAR(255),
    provider_response JSONB,

    -- Engagement
    open_count INTEGER DEFAULT 0 CHECK (open_count >= 0),
    click_count INTEGER DEFAULT 0 CHECK (click_count >= 0),
    click_urls TEXT[] DEFAULT '{}',

    -- Suppression
    is_suppressed BOOLEAN DEFAULT FALSE,
    suppression_reason VARCHAR(100),
    suppressed_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_notification_delivery_notification FOREIGN KEY (notification_id)
        REFERENCES socialcandor_schema.notifications(notification_id) ON DELETE CASCADE,
    CONSTRAINT fk_notification_delivery_template FOREIGN KEY (template_id)
        REFERENCES socialcandor_schema.notification_templates(template_id) ON DELETE SET NULL,
    CONSTRAINT fk_notification_delivery_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

--================================================================================================
-- INDEXES FOR ALL TABLES
--================================================================================================
-- data_quality_rules indexes
CREATE INDEX IF NOT EXISTS idx_data_quality_rules_category ON socialcandor_schema.data_quality_rules(rule_category);
CREATE INDEX IF NOT EXISTS idx_data_quality_rules_target ON socialcandor_schema.data_quality_rules(target_schema, target_table_name);
CREATE INDEX IF NOT EXISTS idx_data_quality_rules_active ON socialcandor_schema.data_quality_rules(is_active) WHERE is_active = TRUE;

-- role_permissions indexes
CREATE INDEX IF NOT EXISTS idx_role_permissions_role ON socialcandor_schema.role_permissions(role_id);
CREATE INDEX IF NOT EXISTS idx_role_permissions_permission ON socialcandor_schema.role_permissions(permission_id);
CREATE INDEX IF NOT EXISTS idx_role_permissions_active ON socialcandor_schema.role_permissions(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_role_permissions_validity ON socialcandor_schema.role_permissions(valid_from, valid_to);

-- permission_assignments indexes
CREATE INDEX IF NOT EXISTS idx_permission_assignments_user ON socialcandor_schema.permission_assignments(user_id);
CREATE INDEX IF NOT EXISTS idx_permission_assignments_permission ON socialcandor_schema.permission_assignments(permission_id);
CREATE INDEX IF NOT EXISTS idx_permission_assignments_expires ON socialcandor_schema.permission_assignments(expires_at) WHERE expires_at IS NOT NULL;

-- content_preferences indexes
CREATE INDEX IF NOT EXISTS idx_content_preferences_user ON socialcandor_schema.content_preferences(user_id);
CREATE INDEX IF NOT EXISTS idx_content_preferences_types ON socialcandor_schema.content_preferences USING GIN(preferred_content_types);

-- content_similarity indexes
CREATE INDEX IF NOT EXISTS idx_content_similarity_content1 ON socialcandor_schema.content_similarity(content_id_1);
CREATE INDEX IF NOT EXISTS idx_content_similarity_content2 ON socialcandor_schema.content_similarity(content_id_2);
CREATE INDEX IF NOT EXISTS idx_content_similarity_score ON socialcandor_schema.content_similarity(overall_similarity_score DESC);

-- user_segments indexes
CREATE INDEX IF NOT EXISTS idx_user_segments_type ON socialcandor_schema.user_segments(segment_type);
CREATE INDEX IF NOT EXISTS idx_user_segments_active ON socialcandor_schema.user_segments(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_user_segments_criteria ON socialcandor_schema.user_segments USING GIN(criteria_definition);

-- segment_members indexes
CREATE INDEX IF NOT EXISTS idx_segment_members_segment ON socialcandor_schema.segment_members(segment_id);
CREATE INDEX IF NOT EXISTS idx_segment_members_user ON socialcandor_schema.segment_members(user_id);
CREATE INDEX IF NOT EXISTS idx_segment_members_active ON socialcandor_schema.segment_members(is_active) WHERE is_active = TRUE;

-- segment_criteria indexes
CREATE INDEX IF NOT EXISTS idx_segment_criteria_segment ON socialcandor_schema.segment_criteria(segment_id);
CREATE INDEX IF NOT EXISTS idx_segment_criteria_parent ON socialcandor_schema.segment_criteria(parent_criterion_id);
CREATE INDEX IF NOT EXISTS idx_segment_criteria_attribute ON socialcandor_schema.segment_criteria(attribute_path);

-- ad_campaigns indexes
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_advertiser ON socialcandor_schema.ad_campaigns(advertiser_id);
