CREATE INDEX IF NOT EXISTS idx_notification_delivery_status ON socialcandor_schema.notification_delivery(delivery_status);
CREATE INDEX IF NOT EXISTS idx_notification_delivery_sent ON socialcandor_schema.notification_delivery(sent_at DESC);

--================================================================================================
-- ALTER TABLE CONSTRAINTS
--================================================================================================
-- data_quality_rules constraints
ALTER TABLE socialcandor_schema.data_quality_rules
    ADD CONSTRAINT chk_thresholds CHECK (warning_threshold <= critical_threshold),
    ADD CONSTRAINT chk_sample_size CHECK (sample_size >= 100);

-- ad_campaigns constraints
ALTER TABLE socialcandor_schema.ad_campaigns
    ADD CONSTRAINT chk_campaign_budget CHECK (daily_budget IS NULL OR daily_budget <= total_budget);

-- ad_creatives constraints
ALTER TABLE socialcandor_schema.ad_creatives
    ADD CONSTRAINT chk_file_size CHECK (file_size_bytes <= 10737418240); -- 10GB limit

-- moderation_appeals constraints
ALTER TABLE socialcandor_schema.moderation_appeals
    ADD CONSTRAINT chk_appeal_timing CHECK (
        (review_completed_at IS NULL) OR (review_completed_at >= review_started_at)
    ),
    ADD CONSTRAINT chk_resolution_timing CHECK (
        (resolved_at IS NULL) OR (resolved_at >= submitted_at)
    );

-- notification_delivery constraints
ALTER TABLE socialcandor_schema.notification_delivery
    ADD CONSTRAINT chk_delivery_timing CHECK (
        (delivered_at IS NULL) OR (delivered_at >= sent_at)
    ),
    ADD CONSTRAINT chk_open_timing CHECK (
        (opened_at IS NULL) OR (opened_at >= delivered_at)
    );

--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================
-- Enable RLS on sensitive tables
ALTER TABLE socialcandor_schema.data_quality_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.permission_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.content_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_segments ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.segment_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ad_campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ad_groups ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ad_creatives ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.moderation_queues ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.moderation_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.moderation_appeals ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.dashboards ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.dashboard_widgets ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.notification_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.notification_delivery ENABLE ROW LEVEL SECURITY;

-- Content preferences RLS policy
CREATE POLICY content_preferences_user_isolation ON socialcandor_schema.content_preferences
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

-- User segments RLS policy
CREATE POLICY user_segments_team_access ON socialcandor_schema.user_segments
    FOR ALL
    USING (
        owner_user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- Ad campaigns RLS policy
CREATE POLICY ad_campaigns_owner_access ON socialcandor_schema.ad_campaigns
    FOR ALL
    USING (
        advertiser_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- Moderation actions RLS policy
CREATE POLICY moderation_actions_moderator_access ON socialcandor_schema.moderation_actions
    FOR SELECT
    USING (
        moderator_user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_moderator = TRUE
        )
    );

-- Dashboards RLS policy
CREATE POLICY dashboards_owner_access ON socialcandor_schema.dashboards
    FOR ALL
    USING (
        owner_user_id = current_setting('app.current_user_id')::UUID OR
        is_shared = TRUE OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- Notification delivery RLS policy
CREATE POLICY notification_delivery_user_access ON socialcandor_schema.notification_delivery
    FOR SELECT
    USING (user_id = current_setting('app.current_user_id')::UUID);

