--================================================================================================
-- Table: post_reactions
-- Description: Tracks user reactions (like, love, laugh, etc.) to posts and comments
-- Business Case: Enables engagement metrics and personalized content feeds through reaction data.
--                Supports content ranking and user sentiment analysis.
-- KPIs: Reaction rate per post, reaction distribution, user reaction frequency
-- Feature Reference: SOC01 (Reactions)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.post_reactions (
    -- Primary key
    reaction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    post_id UUID,
    comment_id UUID,

    -- Reaction type
    reaction_type VARCHAR(30) NOT NULL CHECK (
        reaction_type IN ('LIKE', 'LOVE', 'HAHA', 'WOW', 'SAD', 'ANGRY', 'CARE', 'SUPPORT')
    ),

    -- Timestamps
    reacted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT chk_post_reaction_target CHECK (
        (post_id IS NOT NULL AND comment_id IS NULL) OR
        (post_id IS NULL AND comment_id IS NOT NULL)
    ),
    CONSTRAINT fk_post_reactions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_post_reactions_post FOREIGN KEY (post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_post_reactions_comment FOREIGN KEY (comment_id)
        REFERENCES socialcandor_schema.posts_comments(comment_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_post_reaction UNIQUE (user_id, post_id, comment_id, reaction_type)
);

--================================================================================================
-- Table: shares
-- Description: Records which user shared a post and with whom/where
-- Business Case: Tracks content virality, enables share analytics, and supports social graph expansion.
-- KPIs: Share rate, viral coefficient, share reach, share-to-engagement ratio
-- Feature Reference: SOC02 (Sharing)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.shares (
    -- Primary key
    share_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    post_id UUID NOT NULL,

    -- Sharing details
    share_type VARCHAR(30) NOT NULL CHECK (
        share_type IN ('PUBLIC', 'FRIENDS', 'PRIVATE', 'GROUP', 'PAGE', 'EXTERNAL')
    ),
    share_platform VARCHAR(30) DEFAULT 'INTERNAL' CHECK (
        share_platform IN ('INTERNAL', 'FACEBOOK', 'TWITTER', 'LINKEDIN', 'WHATSAPP', 'EMAIL', 'COPY_LINK')
    ),

    -- Target (if internal)
    target_group_id UUID,
    target_page_id UUID,
    target_user_id UUID,

    -- Metrics
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    click_count INTEGER DEFAULT 0 CHECK (click_count >= 0),

    -- Timestamps
    shared_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_shares_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_shares_post FOREIGN KEY (post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_shares_target_group FOREIGN KEY (target_group_id)
        REFERENCES socialcandor_schema.groups(group_id) ON DELETE SET NULL,
    CONSTRAINT fk_shares_target_page FOREIGN KEY (target_page_id)
        REFERENCES socialcandor_schema.pages(page_id) ON DELETE SET NULL,
    CONSTRAINT fk_shares_target_user FOREIGN KEY (target_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_share_target CHECK (
        (share_type = 'GROUP' AND target_group_id IS NOT NULL) OR
        (share_type = 'PAGE' AND target_page_id IS NOT NULL) OR
        (share_type = 'PRIVATE' AND target_user_id IS NOT NULL) OR
        (share_type IN ('PUBLIC', 'FRIENDS', 'EXTERNAL') AND
         target_group_id IS NULL AND target_page_id IS NULL AND target_user_id IS NULL)
    )
);

--================================================================================================
-- Table: user_reports
-- Description: Stores reports of content or users for moderation
-- Business Case: Enables community moderation by allowing users to report inappropriate content or behavior.
--                Supports review queues and automated action triggers.
-- KPIs: Report resolution time, false positive rate, reporter satisfaction
-- Feature Reference: SOC03 (Reporting), MOD01 (Moderation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_reports (
    -- Primary key
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    reporter_user_id UUID NOT NULL,
    reported_user_id UUID,
    reported_post_id UUID,
    reported_comment_id UUID,
    reported_message_id UUID,

    -- Report details
    report_category VARCHAR(50) NOT NULL CHECK (
        report_category IN ('SPAM', 'HARASSMENT', 'HATE_SPEECH', 'VIOLENCE', 'NUDITY',
  'FALSE_INFORMATION', 'IMPERSONATION', 'COPYRIGHT', 'OTHER')
    ),
    report_reason TEXT,
    report_priority VARCHAR(20) DEFAULT 'NORMAL' CHECK (
        report_priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')
    ),

    -- Evidence
    evidence_attachments JSONB DEFAULT '[]',

    -- Status
    report_status VARCHAR(30) DEFAULT 'PENDING' CHECK (
        report_status IN ('PENDING', 'IN_REVIEW', 'RESOLVED', 'DISMISSED', 'ESCALATED')
    ),
    resolution_notes TEXT,

    -- Moderation action reference
    moderation_action_id UUID,

    -- Timestamps
    reported_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    reviewed_by UUID,
    resolved_by UUID,

    -- Constraints
    CONSTRAINT fk_user_reports_reporter FOREIGN KEY (reporter_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_reports_reported_user FOREIGN KEY (reported_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_reports_post FOREIGN KEY (reported_post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_reports_comment FOREIGN KEY (reported_comment_id)
        REFERENCES socialcandor_schema.posts_comments(comment_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_reports_message FOREIGN KEY (reported_message_id)
        REFERENCES socialcandor_schema.conversations_messages(message_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_reports_moderation_action FOREIGN KEY (moderation_action_id)
        REFERENCES socialcandor_schema.moderation_actions(action_id) ON DELETE SET NULL,
    CONSTRAINT chk_report_target CHECK (
        (reported_user_id IS NOT NULL AND reported_post_id IS NULL AND reported_comment_id IS NULL AND reported_message_id IS NULL) OR
        (reported_user_id IS NULL AND reported_post_id IS NOT NULL AND reported_comment_id IS NULL AND reported_message_id IS NULL) OR
        (reported_user_id IS NULL AND reported_post_id IS NULL AND reported_comment_id IS NOT NULL AND reported_message_id IS NULL) OR
        (reported_user_id IS NULL AND reported_post_id IS NULL AND reported_comment_id IS NULL AND reported_message_id IS NOT NULL)
    )
);

--================================================================================================
-- Table: user_blocks
-- Description: Allows users to block other users
-- Business Case: Provides user control over their experience by preventing unwanted interactions.
--                Blocks are applied to messaging, comments, and visibility.
-- KPIs: Block rate, block removal rate, user satisfaction post-block
-- Feature Reference: SOC04 (Blocking)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_blocks (
    -- Primary key
    block_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    blocking_user_id UUID NOT NULL,
    blocked_user_id UUID NOT NULL,

    -- Block details
    block_reason VARCHAR(50) CHECK (
        block_reason IN ('HARASSMENT', 'SPAM', 'ABUSE', 'UNWANTED_CONTACT', 'OTHER')
    ),
    block_notes TEXT,

    -- Block scope (what interactions are blocked)
    block_messages BOOLEAN DEFAULT TRUE,
    block_comments BOOLEAN DEFAULT TRUE,
    block_follows BOOLEAN DEFAULT TRUE,
    block_mentions BOOLEAN DEFAULT TRUE,
    block_view_profile BOOLEAN DEFAULT FALSE, -- whether they can see profile

    -- Timestamps
    blocked_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE, -- NULL means permanent
    unblocked_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_user_blocks_blocking FOREIGN KEY (blocking_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_blocks_blocked FOREIGN KEY (blocked_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_block UNIQUE (blocking_user_id, blocked_user_id, unblocked_at),
    CONSTRAINT chk_block_self CHECK (blocking_user_id != blocked_user_id),
    CONSTRAINT chk_block_expiry CHECK (expires_at IS NULL OR expires_at > blocked_at)
);

--================================================================================================
-- Table: follow_requests
-- Description: Manages pending follow requests for private accounts
-- Business Case: Enables privacy controls by requiring approval for followers on private accounts.
--                Supports follow request lifecycle (pending, approved, rejected).
-- KPIs: Request approval rate, average response time, follow-through rate
-- Feature Reference: SOC05 (Follow Requests)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.follow_requests (
    -- Primary key
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    requester_user_id UUID NOT NULL,
    target_user_id UUID NOT NULL,

    -- Request details
    request_status VARCHAR(30) DEFAULT 'PENDING' CHECK (
        request_status IN ('PENDING', 'APPROVED', 'REJECTED', 'EXPIRED', 'WITHDRAWN')
    ),
    request_message TEXT,

    -- Timestamps
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    responded_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (requested_at + INTERVAL '30 days') STORED,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_follow_requests_requester FOREIGN KEY (requester_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_follow_requests_target FOREIGN KEY (target_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_follow_request UNIQUE (requester_user_id, target_user_id, request_status),
    CONSTRAINT chk_follow_request_self CHECK (requester_user_id != target_user_id)
);

--================================================================================================
-- Table: page_followers
-- Description: Tracks followers of business/organization pages
-- Business Case: Enables page analytics, content targeting, and notification preferences.
-- KPIs: Follower growth rate, engagement rate by follower, follower churn
-- Feature Reference: SOC06 (Page Following), PAG02 (Page Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.page_followers (
    -- Primary key
    page_follower_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    page_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Follower details
    followed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    unfollowed_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (unfollowed_at IS NULL) STORED,

    -- Notification preferences
    notifications_enabled BOOLEAN DEFAULT TRUE,
    notification_types VARCHAR(50)[] DEFAULT ARRAY['ALL'],

    -- Engagement metrics
    engagement_score NUMERIC(5,2) DEFAULT 0 CHECK (engagement_score >= 0 AND engagement_score <= 100),
    last_engaged_at TIMESTAMP WITH TIME ZONE,

    -- Source
    follow_source VARCHAR(30) DEFAULT 'PAGE' CHECK (
        follow_source IN ('PAGE', 'SUGGESTION', 'SEARCH', 'INVITE', 'AD')
    ),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_page_followers_page FOREIGN KEY (page_id)
        REFERENCES socialcandor_schema.pages(page_id) ON DELETE CASCADE,
    CONSTRAINT fk_page_followers_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_page_follower UNIQUE (page_id, user_id, unfollowed_at)
);

--================================================================================================
-- Table: hashtags
-- Description: Normalized table for hashtags with usage counts and trending
-- Business Case: Enables hashtag discovery, trending topics, and content categorization.
--                Supports search and recommendation algorithms.
-- KPIs: Hashtag usage growth, trending accuracy, search success rate
-- Feature Reference: SOC07 (Hashtags), SRCH02 (Search)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.hashtags (
    -- Primary key
    hashtag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Hashtag identification
    hashtag VARCHAR(100) NOT NULL UNIQUE,
    normalized_hashtag VARCHAR(100) GENERATED ALWAYS AS (LOWER(hashtag)) STORED UNIQUE,

    -- Usage metrics
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    unique_users INTEGER DEFAULT 0 CHECK (unique_users >= 0),

    -- Trending data
    trending_score NUMERIC(10,4) DEFAULT 0,
    trending_rank INTEGER,
    trending_since TIMESTAMP WITH TIME ZONE,

    -- Time-series aggregates (simplified, could be separate table for historical)
    last_hour_count INTEGER DEFAULT 0,
    last_24h_count INTEGER DEFAULT 0,
    last_7d_count INTEGER DEFAULT 0,

    -- First seen
    first_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_seen_at TIMESTAMP WITH TIME ZONE,

    -- Status
    is_banned BOOLEAN DEFAULT FALSE,
    ban_reason TEXT,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Indexes will be created separately
    CONSTRAINT chk_hashtag_format CHECK (hashtag ~ '^[a-zA-Z0-9_]{1,100}$')
);

--================================================================================================
-- Table: mentions
-- Description: Normalized table for user mentions in posts/comments
-- Business Case: Enables notification triggers, user discovery, and content linking.
--                Supports mention analytics and social graph expansion.
-- KPIs: Mention rate, mention engagement, mention-to-interaction conversion
-- Feature Reference: SOC08 (Mentions), NOTIFY03 (Mention Notifications)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.mentions (
    -- Primary key
    mention_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    mentioned_user_id UUID NOT NULL,
    mentioning_user_id UUID NOT NULL,
    post_id UUID,
    comment_id UUID,

    -- Mention details
    mention_context TEXT, -- surrounding text snippet
    mention_position INTEGER, -- character position in content

    -- Timestamps
    mentioned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Notification status
    notification_sent BOOLEAN DEFAULT FALSE,
    notification_sent_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_mentions_mentioned_user FOREIGN KEY (mentioned_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_mentions_mentioning_user FOREIGN KEY (mentioning_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_mentions_post FOREIGN KEY (post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_mentions_comment FOREIGN KEY (comment_id)
        REFERENCES socialcandor_schema.posts_comments(comment_id) ON DELETE CASCADE,
    CONSTRAINT chk_mention_target CHECK (
        (post_id IS NOT NULL AND comment_id IS NULL) OR
        (post_id IS NULL AND comment_id IS NOT NULL)
    ),
    CONSTRAINT uk_mention UNIQUE (mentioned_user_id, post_id, comment_id)
);

--================================================================================================
-- Table: stories
-- Description: Dedicated table for ephemeral content with expiration and view tracking
-- Business Case: Enables 24-hour stories feature with engagement metrics and privacy controls.
--                Supports story reactions, replies, and highlights.
-- KPIs: Story creation rate, completion rate, view-to-reply ratio, retention
-- Feature Reference: SOC09 (Stories), MED03 (Ephemeral Media)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.stories (
    -- Primary key
    story_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- Content
    media_type VARCHAR(20) NOT NULL CHECK (
        media_type IN ('IMAGE', 'VIDEO', 'TEXT', 'LINK', 'POLL')
    ),
    media_url VARCHAR(500),
    thumbnail_url VARCHAR(500),
    content_text TEXT,

    -- Story metadata
    duration_seconds INTEGER DEFAULT 5 CHECK (duration_seconds > 0 AND duration_seconds <= 60),
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    is_highlight BOOLEAN DEFAULT FALSE,
    highlight_cover_url VARCHAR(500),

    -- Privacy
    visibility VARCHAR(20) DEFAULT 'PUBLIC' CHECK (
        visibility IN ('PUBLIC', 'FRIENDS', 'CLOSE_FRIENDS', 'CUSTOM')
    ),
    allowed_user_ids UUID[],
    excluded_user_ids UUID[],

    -- Metrics
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    reply_count INTEGER DEFAULT 0 CHECK (reply_count >= 0),
    reaction_count INTEGER DEFAULT 0 CHECK (reaction_count >= 0),
    screenshot_count INTEGER DEFAULT 0 CHECK (screenshot_count >= 0),

    -- Interaction tracking
    allow_replies BOOLEAN DEFAULT TRUE,
    allow_reactions BOOLEAN DEFAULT TRUE,
    allow_sharing BOOLEAN DEFAULT TRUE,
    allow_screenshots BOOLEAN DEFAULT TRUE,

    -- Status
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_stories_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

--================================================================================================
-- Table: story_views
-- Description: Tracks who viewed stories and when
-- Business Case: Enables story analytics and viewer lists for story owners.
-- KPIs: Unique viewers per story, completion rate per viewer
-- Feature Reference: SOC10 (Story Views)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.story_views (
    -- Primary key
    view_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    story_id UUID NOT NULL,
    viewer_user_id UUID NOT NULL,

    -- View details
    viewed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    view_duration_seconds INTEGER CHECK (view_duration_seconds >= 0),
    completed BOOLEAN DEFAULT FALSE,

    -- Reaction
    reaction_type VARCHAR(20) CHECK (
        reaction_type IN ('LIKE', 'LOVE', 'HAHA', 'WOW', 'SAD', 'ANGRY')
    ),

    -- Reply
    reply_text TEXT,

    -- Screenshot detection
    screenshot_taken BOOLEAN DEFAULT FALSE,
    screenshot_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_story_views_story FOREIGN KEY (story_id)
        REFERENCES socialcandor_schema.stories(story_id) ON DELETE CASCADE,
    CONSTRAINT fk_story_views_viewer FOREIGN KEY (viewer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_story_view UNIQUE (story_id, viewer_user_id)
);

--================================================================================================
-- Table: polls
-- Description: Stores poll questions and configuration
-- Business Case: Enables interactive polls within posts, stories, or standalone.
--                Supports multiple choice, multiple answers, and voting deadlines.
-- KPIs: Poll participation rate, voting distribution, engagement time
-- Feature Reference: SOC11 (Polls)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.polls (
    -- Primary key
    poll_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    post_id UUID,
    story_id UUID,

    -- Poll configuration
    question TEXT NOT NULL,
    poll_type VARCHAR(20) DEFAULT 'SINGLE_CHOICE' CHECK (
        poll_type IN ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'RANKING', 'YES_NO')
    ),
    allow_multiple_answers BOOLEAN DEFAULT FALSE,
    allow_anonymous_votes BOOLEAN DEFAULT FALSE,
    allow_vote_changes BOOLEAN DEFAULT TRUE,
    hide_results_until_closed BOOLEAN DEFAULT FALSE,

    -- Timing
    start_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    end_at TIMESTAMP WITH TIME ZONE,
    is_closed BOOLEAN GENERATED ALWAYS AS (end_at < CURRENT_TIMESTAMP) STORED,

    -- Results summary (updated via triggers)
    total_votes INTEGER DEFAULT 0 CHECK (total_votes >= 0),
    unique_voters INTEGER DEFAULT 0 CHECK (unique_voters >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_polls_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_polls_post FOREIGN KEY (post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT fk_polls_story FOREIGN KEY (story_id)
        REFERENCES socialcandor_schema.stories(story_id) ON DELETE CASCADE,
    CONSTRAINT chk_poll_target CHECK (
        (post_id IS NOT NULL AND story_id IS NULL) OR
        (post_id IS NULL AND story_id IS NOT NULL) OR
        (post_id IS NULL AND story_id IS NULL) -- standalone poll
    )
);

--================================================================================================
-- Table: poll_options
-- Description: Options/choices for polls
-- Business Case: Supports multiple poll options with vote counts and ordering.
-- KPIs: Option selection distribution, vote share
-- Feature Reference: SOC12 (Poll Options)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.poll_options (
    -- Primary key
    option_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    poll_id UUID NOT NULL,

    -- Option details
    option_text TEXT NOT NULL,
    option_order INTEGER NOT NULL CHECK (option_order >= 0),

    -- Vote counts (updated via triggers)
    vote_count INTEGER DEFAULT 0 CHECK (vote_count >= 0),
    vote_percentage NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN (SELECT total_votes FROM socialcandor_schema.polls WHERE poll_id = poll_id) > 0
             THEN (vote_count * 100.0 / (SELECT total_votes FROM socialcandor_schema.polls WHERE poll_id = poll_id))
             ELSE 0
        END
    ) STORED,

    -- Media attachment
    image_url VARCHAR(500),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_poll_options_poll FOREIGN KEY (poll_id)
        REFERENCES socialcandor_schema.polls(poll_id) ON DELETE CASCADE,
    CONSTRAINT uk_poll_option_order UNIQUE (poll_id, option_order)
);

--================================================================================================
-- Table: poll_votes
-- Description: Records individual votes on poll options
-- Business Case: Enables detailed voting analytics and prevents duplicate votes.
--                Supports vote changes and anonymous voting.
-- KPIs: Vote distribution, voter demographics, vote change frequency
-- Feature Reference: SOC13 (Poll Votes)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.poll_votes (
    -- Primary key
    vote_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    poll_id UUID NOT NULL,
    option_id UUID NOT NULL,
    user_id UUID, -- NULL if anonymous

    -- Vote details
    voted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    ip_address INET, -- for anonymous vote uniqueness
    user_agent TEXT,

    -- Vote change tracking
    is_current BOOLEAN DEFAULT TRUE,
    previous_vote_id UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_poll_votes_poll FOREIGN KEY (poll_id)
        REFERENCES socialcandor_schema.polls(poll_id) ON DELETE CASCADE,
    CONSTRAINT fk_poll_votes_option FOREIGN KEY (option_id)
        REFERENCES socialcandor_schema.poll_options(option_id) ON DELETE CASCADE,
    CONSTRAINT fk_poll_votes_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_poll_votes_previous FOREIGN KEY (previous_vote_id)
        REFERENCES socialcandor_schema.poll_votes(vote_id) ON DELETE SET NULL,
    CONSTRAINT uk_poll_vote_user_current UNIQUE (poll_id, user_id) WHERE is_current = TRUE AND user_id IS NOT NULL,
    CONSTRAINT uk_poll_vote_ip UNIQUE (poll_id, ip_address) WHERE is_current = TRUE AND user_id IS NULL
);

--================================================================================================
-- Table: user_verification_documents
-- Description: For user identity verification requests and documents
-- Business Case: Enables identity verification for badges, age-restricted features, or compliance.
--                Supports secure document storage with review workflow.
-- KPIs: Verification success rate, processing time, fraud detection rate
-- Feature Reference: SOC14 (User Verification), VER01 (Identity Verification)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_verification_documents (
    -- Primary key
    document_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- Document type
    document_type VARCHAR(50) NOT NULL CHECK (
        document_type IN ('PASSPORT', 'DRIVERS_LICENSE', 'NATIONAL_ID', 'VISA', 'BIRTH_CERTIFICATE',
                          'PROOF_OF_ADDRESS', 'COMPANY_REGISTRATION', 'TAX_ID', 'OTHER')
    ),
    document_subtype VARCHAR(50),

    -- File information
    file_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(500) NOT NULL,
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    mime_type VARCHAR(100),

    -- Document metadata
    document_number VARCHAR(100),
    issuing_country VARCHAR(3),
    issue_date DATE,
    expiry_date DATE,
    date_of_birth DATE,
    full_name VARCHAR(255),

    -- Verification details
    verification_status VARCHAR(30) DEFAULT 'PENDING' CHECK (
        verification_status IN ('PENDING', 'IN_REVIEW', 'VERIFIED', 'REJECTED', 'EXPIRED', 'REVOKED')
    ),
    verification_notes TEXT,
    verification_method VARCHAR(50) CHECK (
        verification_method IN ('MANUAL', 'AUTOMATIC', 'THIRD_PARTY')
    ),
    confidence_score NUMERIC(5,2) CHECK (confidence_score >= 0 AND confidence_score <= 100),

    -- Rejection reasons
    rejection_reasons JSONB DEFAULT '[]',

    -- Workflow
    assigned_reviewer_id UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Security
    encryption_key_id UUID,
    access_log JSONB DEFAULT '[]',

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    renewal_required BOOLEAN DEFAULT FALSE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    deletion_reason TEXT,

    -- Constraints
    CONSTRAINT fk_verification_documents_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_verification_documents_reviewer FOREIGN KEY (assigned_reviewer_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_verification_dates CHECK (
        (issue_date IS NULL OR expiry_date IS NULL) OR expiry_date >= issue_date
    )
);

--================================================================================================
-- INDEXES
--================================================================================================

-- post_reactions indexes
CREATE INDEX IF NOT EXISTS idx_post_reactions_user ON socialcandor_schema.post_reactions(user_id);
CREATE INDEX IF NOT EXISTS idx_post_reactions_post ON socialcandor_schema.post_reactions(post_id);
CREATE INDEX IF NOT EXISTS idx_post_reactions_comment ON socialcandor_schema.post_reactions(comment_id);
CREATE INDEX IF NOT EXISTS idx_post_reactions_type ON socialcandor_schema.post_reactions(reaction_type);

-- shares indexes
CREATE INDEX IF NOT EXISTS idx_shares_user ON socialcandor_schema.shares(user_id);
CREATE INDEX IF NOT EXISTS idx_shares_post ON socialcandor_schema.shares(post_id);
CREATE INDEX IF NOT EXISTS idx_shares_type ON socialcandor_schema.shares(share_type);
CREATE INDEX IF NOT EXISTS idx_shares_platform ON socialcandor_schema.shares(share_platform);

-- user_reports indexes
CREATE INDEX IF NOT EXISTS idx_user_reports_reporter ON socialcandor_schema.user_reports(reporter_user_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_reported_user ON socialcandor_schema.user_reports(reported_user_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_post ON socialcandor_schema.user_reports(reported_post_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_comment ON socialcandor_schema.user_reports(reported_comment_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_message ON socialcandor_schema.user_reports(reported_message_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_status ON socialcandor_schema.user_reports(report_status);
CREATE INDEX IF NOT EXISTS idx_user_reports_category ON socialcandor_schema.user_reports(report_category);

-- user_blocks indexes
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocking ON socialcandor_schema.user_blocks(blocking_user_id);
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocked ON socialcandor_schema.user_blocks(blocked_user_id);
CREATE INDEX IF NOT EXISTS idx_user_blocks_active ON socialcandor_schema.user_blocks(unblocked_at) WHERE unblocked_at IS NULL;

-- follow_requests indexes
CREATE INDEX IF NOT EXISTS idx_follow_requests_requester ON socialcandor_schema.follow_requests(requester_user_id);
CREATE INDEX IF NOT EXISTS idx_follow_requests_target ON socialcandor_schema.follow_requests(target_user_id);
CREATE INDEX IF NOT EXISTS idx_follow_requests_status ON socialcandor_schema.follow_requests(request_status);
CREATE INDEX IF NOT EXISTS idx_follow_requests_expires ON socialcandor_schema.follow_requests(expires_at);

-- page_followers indexes
CREATE INDEX IF NOT EXISTS idx_page_followers_page ON socialcandor_schema.page_followers(page_id);
CREATE INDEX IF NOT EXISTS idx_page_followers_user ON socialcandor_schema.page_followers(user_id);
CREATE INDEX IF NOT EXISTS idx_page_followers_active ON socialcandor_schema.page_followers(is_active) WHERE is_active = TRUE;

-- hashtags indexes
CREATE INDEX IF NOT EXISTS idx_hashtags_hashtag ON socialcandor_schema.hashtags(hashtag);
CREATE INDEX IF NOT EXISTS idx_hashtags_normalized ON socialcandor_schema.hashtags(normalized_hashtag);
CREATE INDEX IF NOT EXISTS idx_hashtags_trending ON socialcandor_schema.hashtags(trending_score DESC);
CREATE INDEX IF NOT EXISTS idx_hashtags_usage ON socialcandor_schema.hashtags(usage_count DESC);

-- mentions indexes
CREATE INDEX IF NOT EXISTS idx_mentions_mentioned_user ON socialcandor_schema.mentions(mentioned_user_id);
CREATE INDEX IF NOT EXISTS idx_mentions_mentioning_user ON socialcandor_schema.mentions(mentioning_user_id);
CREATE INDEX IF NOT EXISTS idx_mentions_post ON socialcandor_schema.mentions(post_id);
CREATE INDEX IF NOT EXISTS idx_mentions_comment ON socialcandor_schema.mentions(comment_id);

-- stories indexes
CREATE INDEX IF NOT EXISTS idx_stories_user ON socialcandor_schema.stories(user_id);
CREATE INDEX IF NOT EXISTS idx_stories_expires ON socialcandor_schema.stories(expires_at) WHERE expires_at > CURRENT_TIMESTAMP;
CREATE INDEX IF NOT EXISTS idx_stories_highlights ON socialcandor_schema.stories(is_highlight) WHERE is_highlight = TRUE;

-- story_views indexes
CREATE INDEX IF NOT EXISTS idx_story_views_story ON socialcandor_schema.story_views(story_id);
CREATE INDEX IF NOT EXISTS idx_story_views_viewer ON socialcandor_schema.story_views(viewer_user_id);

-- polls indexes
CREATE INDEX IF NOT EXISTS idx_polls_user ON socialcandor_schema.polls(user_id);
CREATE INDEX IF NOT EXISTS idx_polls_post ON socialcandor_schema.polls(post_id);
CREATE INDEX IF NOT EXISTS idx_polls_story ON socialcandor_schema.polls(story_id);
CREATE INDEX IF NOT EXISTS idx_polls_end_at ON socialcandor_schema.polls(end_at);

-- poll_options indexes
CREATE INDEX IF NOT EXISTS idx_poll_options_poll ON socialcandor_schema.poll_options(poll_id);
CREATE INDEX IF NOT EXISTS idx_poll_options_order ON socialcandor_schema.poll_options(poll_id, option_order);

-- poll_votes indexes
CREATE INDEX IF NOT EXISTS idx_poll_votes_poll ON socialcandor_schema.poll_votes(poll_id);
CREATE INDEX IF NOT EXISTS idx_poll_votes_option ON socialcandor_schema.poll_votes(option_id);
CREATE INDEX IF NOT EXISTS idx_poll_votes_user ON socialcandor_schema.poll_votes(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_poll_votes_ip ON socialcandor_schema.poll_votes(ip_address) WHERE user_id IS NULL;

-- user_verification_documents indexes
CREATE INDEX IF NOT EXISTS idx_verification_docs_user ON socialcandor_schema.user_verification_documents(user_id);
CREATE INDEX IF NOT EXISTS idx_verification_docs_status ON socialcandor_schema.user_verification_documents(verification_status);
CREATE INDEX IF NOT EXISTS idx_verification_docs_expiry ON socialcandor_schema.user_verification_documents(expiry_date);

--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================

-- Enable RLS on tables
ALTER TABLE socialcandor_schema.post_reactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.shares ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_blocks ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.follow_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.page_followers ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.hashtags ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.mentions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.stories ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.story_views ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.polls ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.poll_options ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.poll_votes ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_verification_documents ENABLE ROW LEVEL SECURITY;

-- post_reactions policy: users can manage their own reactions; others can view
CREATE POLICY post_reactions_self_policy ON socialcandor_schema.post_reactions
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY post_reactions_read_policy ON socialcandor_schema.post_reactions
    FOR SELECT
    USING (TRUE); -- anyone can see reactions (for counts)

-- shares policy: users can manage their own shares
CREATE POLICY shares_self_policy ON socialcandor_schema.shares
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

-- user_reports policy: users can create reports; admins/moderators can manage all
CREATE POLICY user_reports_create_policy ON socialcandor_schema.user_reports
    FOR INSERT
    WITH CHECK (reporter_user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY user_reports_self_policy ON socialcandor_schema.user_reports
    FOR SELECT
    USING (reporter_user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY user_reports_moderator_policy ON socialcandor_schema.user_reports
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND (u.is_moderator = TRUE OR u.is_admin = TRUE)
        )
    );

-- user_blocks policy: users can manage their own blocks
CREATE POLICY user_blocks_self_policy ON socialcandor_schema.user_blocks
    FOR ALL
    USING (blocking_user_id = current_setting('app.current_user_id')::UUID);

-- follow_requests policy: users see their own requests; target user can respond
CREATE POLICY follow_requests_requester_policy ON socialcandor_schema.follow_requests
    FOR ALL
    USING (requester_user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY follow_requests_target_policy ON socialcandor_schema.follow_requests
    FOR SELECT, UPDATE
    USING (target_user_id = current_setting('app.current_user_id')::UUID);

-- page_followers policy: users manage their follows; page owners see followers
CREATE POLICY page_followers_self_policy ON socialcandor_schema.page_followers
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY page_followers_page_owner_policy ON socialcandor_schema.page_followers
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.pages p
            WHERE p.page_id = page_followers.page_id
            AND p.owner_user_id = current_setting('app.current_user_id')::UUID
        )
    );

-- hashtags policy: public read, admin write
CREATE POLICY hashtags_read_policy ON socialcandor_schema.hashtags
    FOR SELECT
    USING (TRUE);

CREATE POLICY hashtags_admin_policy ON socialcandor_schema.hashtags
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- mentions policy: mentioned user can see; others can see in context of posts they can access
CREATE POLICY mentions_mentioned_policy ON socialcandor_schema.mentions
    FOR SELECT
    USING (mentioned_user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY mentions_context_policy ON socialcandor_schema.mentions
    FOR SELECT
    USING (
        (post_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM socialcandor_schema.posts p
            WHERE p.post_id = mentions.post_id
            AND (p.visibility = 'PUBLIC' OR p.user_id = current_setting('app.current_user_id')::UUID)
        )) OR
        (comment_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM socialcandor_schema.posts_comments c
            WHERE c.comment_id = mentions.comment_id
        ))
    );

-- stories policy: users manage own stories; viewers can view if allowed
CREATE POLICY stories_self_policy ON socialcandor_schema.stories
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY stories_view_policy ON socialcandor_schema.stories
    FOR SELECT
    USING (
        visibility = 'PUBLIC' OR
        user_id = current_setting('app.current_user_id')::UUID OR
        (visibility = 'FRIENDS' AND EXISTS (
            SELECT 1 FROM socialcandor_schema.friends f
            WHERE f.user_id = stories.user_id
            AND f.friend_user_id = current_setting('app.current_user_id')::UUID
            AND f.status = 'ACCEPTED'
        )) OR
        (visibility = 'CLOSE_FRIENDS' AND EXISTS (
            SELECT 1 FROM socialcandor_schema.followings f
            WHERE f.following_user_id = stories.user_id
            AND f.follower_user_id = current_setting('app.current_user_id')::UUID
            AND f.is_close_friend = TRUE
        )) OR
        (visibility = 'CUSTOM' AND current_setting('app.current_user_id')::UUID = ANY(allowed_user_ids))
    );

-- story_views policy: story owner can see views; viewer can see their own view
CREATE POLICY story_views_owner_policy ON socialcandor_schema.story_views
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.stories s
            WHERE s.story_id = story_views.story_id
            AND s.user_id = current_setting('app.current_user_id')::UUID
        )
    );

CREATE POLICY story_views_self_policy ON socialcandor_schema.story_views
    FOR SELECT
    USING (viewer_user_id = current_setting('app.current_user_id')::UUID);

-- polls policy: owner manages; others vote/see if allowed
CREATE POLICY polls_owner_policy ON socialcandor_schema.polls
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY polls_view_policy ON socialcandor_schema.polls
    FOR SELECT
    USING (
        (post_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM socialcandor_schema.posts p WHERE p.post_id = polls.post_id
            AND (p.visibility = 'PUBLIC' OR p.user_id = current_setting('app.current_user_id')::UUID)
        )) OR
        (story_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM socialcandor_schema.stories s WHERE s.story_id = polls.story_id
            AND (s.visibility = 'PUBLIC' OR s.user_id = current_setting('app.current_user_id')::UUID)
        )) OR
        (post_id IS NULL AND story_id IS NULL) -- standalone poll, assume public? adjust as needed
    );

-- poll_options policy: inherits from poll
CREATE POLICY poll_options_poll_policy ON socialcandor_schema.poll_options
    FOR SELECT
    USING (EXISTS (SELECT 1 FROM socialcandor_schema.polls p WHERE p.poll_id = poll_options.poll_id));

-- poll_votes policy: users can insert/update their own votes; poll owner can see all
CREATE POLICY poll_votes_self_policy ON socialcandor_schema.poll_votes
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID AND user_id IS NOT NULL);

CREATE POLICY poll_votes_owner_policy ON socialcandor_schema.poll_votes
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.polls p
            WHERE p.poll_id = poll_votes.poll_id
            AND p.user_id = current_setting('app.current_user_id')::UUID
        )
    );

-- user_verification_documents policy: user sees own; admins see all
CREATE POLICY verification_docs_self_policy ON socialcandor_schema.user_verification_documents
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY verification_docs_admin_policy ON socialcandor_schema.user_verification_documents
    FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND (u.is_admin = TRUE OR u.is_moderator = TRUE)
        )
    );

