--================================================================================================
-- ENUMS FOR MISSING TABLES
--================================================================================================

-- Object: 97 - mute_target_type
-- Description: Defines types of entities that can be muted (users, posts, comments, etc.)
-- Business Case: Enables flexible muting functionality separate from blocking, allowing users to
--                silence specific content or users without severing relationships.
-- KPIs: Mute accuracy, user satisfaction, mute-to-block ratio
-- Feature Reference: ENG05 (Muting)
--================================================================================================
CREATE TYPE socialcandor_schema.mute_target_type AS ENUM (
    'USER',      -- Mute another user
    'POST',      -- Mute a specific post
    'COMMENT',   -- Mute a comment thread
    'GROUP',     -- Mute a group
    'PAGE',      -- Mute a page
    'KEYWORD'    -- Mute by keyword (future)
);
COMMENT ON TYPE socialcandor_schema.mute_target_type IS 'Defines types of entities that can be muted';

-- Object: 98 - collection_visibility
-- Description: Visibility levels for user-created collections/playlists
-- Business Case: Allows users to control who can see their curated content collections,
--                supporting private, shared, or public discovery.
-- KPIs: Collection creation rate, sharing adoption, privacy preference distribution
-- Feature Reference: COL01 (Collections)
--================================================================================================
CREATE TYPE socialcandor_schema.collection_visibility AS ENUM (
    'PRIVATE',   -- Only owner can view
    'SHARED',    -- Owner and selected users/groups
    'PUBLIC',    -- Anyone can view
    'UNLISTED'   -- Access via direct link only
);
COMMENT ON TYPE socialcandor_schema.collection_visibility IS 'Defines visibility levels for user collections';

-- Object: 99 - collection_item_type
-- Description: Types of content that can be added to a collection
-- Business Case: Supports heterogeneous collections containing posts, videos, photos, etc.
-- KPIs: Content type distribution, collection engagement
-- Feature Reference: COL02 (Collection Items)
--================================================================================================
CREATE TYPE socialcandor_schema.collection_item_type AS ENUM (
    'POST',      -- Regular post
    'VIDEO',     -- Video content
    'PHOTO',     -- Photo
    'ARTICLE',   -- Long-form article
    'LINK',      -- External link
    'POLL'       -- Poll
);
COMMENT ON TYPE socialcandor_schema.collection_item_type IS 'Defines types of content that can be added to a collection';

-- Object: 100 - job_status
-- Description: Status of background jobs
-- Business Case: Enables tracking of asynchronous tasks with retry and error handling
-- KPIs: Job success rate, average completion time, failure rate by type
-- Feature Reference: SYS04 (Background Jobs)
--================================================================================================
CREATE TYPE socialcandor_schema.job_status AS ENUM (
    'PENDING',    -- Queued, not started
    'RUNNING',    -- Currently executing
    'COMPLETED',  -- Successfully finished
    'FAILED',     -- Failed, may be retried
    'RETRYING',   -- Being retried after failure
    'CANCELLED',  -- Manually cancelled
    'TIMEOUT'     -- Exceeded time limit
);
COMMENT ON TYPE socialcandor_schema.job_status IS 'Defines status of background jobs';

-- Object: 101 - job_priority
-- Description: Priority levels for background job scheduling
-- Business Case: Allows critical jobs to be processed before lower-priority ones
-- KPIs: Time-to-completion by priority, resource allocation efficiency
-- Feature Reference: SYS04 (Background Jobs)
--================================================================================================
CREATE TYPE socialcandor_schema.job_priority AS ENUM (
    'LOW',        -- Can be delayed
    'MEDIUM',     -- Normal priority
    'HIGH',       -- Important, process soon
    'CRITICAL'    -- Process immediately
);
COMMENT ON TYPE socialcandor_schema.job_priority IS 'Defines priority levels for background job scheduling';

-- Object: 102 - audit_action
-- Description: Types of actions logged in the central audit log
-- Business Case: Provides granular classification of audit events for compliance and security
-- KPIs: Audit completeness, incident detection rate, compliance coverage
-- Feature Reference: AUD06 (Audit Logging)
--================================================================================================
CREATE TYPE socialcandor_schema.audit_action AS ENUM (
    'CREATE',    -- Entity creation
    'UPDATE',    -- Entity modification
    'DELETE',    -- Entity deletion
    'VIEW',      -- Data access/read
    'LOGIN',     -- User login
    'LOGOUT',    -- User logout
    'EXPORT',    -- Data export
    'IMPORT',    -- Data import
    'APPROVE',   -- Approval action
    'REJECT',    -- Rejection action
    'ASSIGN',    -- Assignment of role/permission
    'REVOKE',    -- Revocation of access
    'SYSTEM'     -- System-level event
);
COMMENT ON TYPE socialcandor_schema.audit_action IS 'Defines types of actions logged in the central audit log';

-- Object: 103 - audit_target_type
-- Description: Types of entities that can be targeted by audit events
-- Business Case: Enables consistent referencing of audited objects across the platform
-- KPIs: Audit trail completeness, query efficiency
-- Feature Reference: AUD06 (Audit Logging)
--================================================================================================
CREATE TYPE socialcandor_schema.audit_target_type AS ENUM (
    'USER',          -- User account
    'POST',          -- Post
    'COMMENT',       -- Comment
    'MESSAGE',       -- Message
    'GROUP',         -- Group
    'PAGE',          -- Page
    'MEDIA',         -- Media asset
    'ROLE',          -- Role
    'PERMISSION',    -- Permission
    'SETTING',       -- System setting
    'REPORT',        -- User report
    'MOD_ACTION',    -- Moderation action
    'API_KEY'        -- API key
);
COMMENT ON TYPE socialcandor_schema.audit_target_type IS 'Defines types of entities that can be targeted by audit events';

--================================================================================================
-- TABLE: saved_posts
-- Description: Allows users to bookmark posts for later viewing
-- Business Case: Enables users to save interesting content for future reference, increasing engagement
--                and return visits. Supports personal content curation.
-- KPIs: Save rate per post, saved post return rate, user engagement with saved content
-- Feature Reference: ENG06 (Saved Content)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.saved_posts (
    -- Primary key
    saved_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    post_id UUID NOT NULL,

    -- Additional metadata
    saved_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    notes TEXT,    -- Optional user note about why saved
    tags TEXT[],   -- User-defined tags for organization

    -- Collection grouping (optional, can link to collections table later)
    collection_id UUID,

    -- Status
    is_archived BOOLEAN DEFAULT FALSE,       -- User can archive without removing
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_saved_posts_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_posts_post FOREIGN KEY (post_id)
        REFERENCES socialcandor_schema.posts(post_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_post_saved UNIQUE (user_id, post_id)
);

COMMENT ON TABLE socialcandor_schema.saved_posts IS 'Allows users to bookmark posts for later viewing';

--================================================================================================
-- TABLE: user_mutes
-- Description: Allows users to mute specific entities (users, posts, comments, etc.) without blocking
-- Business Case: Provides granular control over content visibility while maintaining social relationships.
--                Users can silence annoying content without severing connections.
-- KPIs: Mute frequency, unmute rate, user satisfaction with content feed
-- Feature Reference: ENG07 (Muting)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_mutes (
    -- Primary key
    mute_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    muting_user_id UUID NOT NULL,            -- User who is muting

    -- Polymorphic target (can mute different entity types)
    target_type socialcandor_schema.mute_target_type NOT NULL,
    target_id UUID NOT NULL,                  -- ID of the muted entity (user, post, etc.)

    -- Mute details
    muted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,      -- Optional expiration for temporary mute
    reason VARCHAR(50),                        -- Optional reason (e.g., 'SPAM', 'OFFENSIVE')
    notes TEXT,

    -- Scope (if applicable)
    mute_comments BOOLEAN DEFAULT TRUE,       -- For user mutes: mute comments from that user
    mute_posts BOOLEAN DEFAULT TRUE,          -- For user mutes: mute posts from that user
    mute_mentions BOOLEAN DEFAULT TRUE,       -- For user mutes: mute mentions

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    unmuted_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_user_mutes_muting_user FOREIGN KEY (muting_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_muting_user_target UNIQUE (muting_user_id, target_type, target_id, is_active)
        WHERE is_active = TRUE
);

COMMENT ON TABLE socialcandor_schema.user_mutes IS 'Allows users to mute specific entities (users, posts, comments) without blocking';

--================================================================================================
-- TABLE: user_badges
-- Description: Tracks achievements, reputation badges, and verification badges for users
-- Business Case: Gamification and reputation system that encourages positive behavior and content creation.
--                Badges can be awarded for milestones, verified status, or community contributions.
-- KPIs: Badge acquisition rate, user engagement by badge tier, badge influence on retention
-- Feature Reference: GAM01 (Gamification), REP01 (Reputation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_badges (
    -- Primary key
    badge_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Badge definition (could be normalized into a badge_definitions table, but simplified here)
    badge_code VARCHAR(50) NOT NULL,           -- e.g., 'VERIFIED', 'TOP_CONTRIBUTOR', 'EARLY_ADOPTER'
    badge_name VARCHAR(100) NOT NULL,
    badge_description TEXT,
    badge_category VARCHAR(50) CHECK (
        badge_category IN ('VERIFICATION', 'ACHIEVEMENT', 'REPUTATION', 'MODERATION', 'SPECIAL')
    ),
    badge_icon_url VARCHAR(500),
    badge_color VARCHAR(7),                     -- Hex color for UI

    -- User reference
    user_id UUID NOT NULL,

    -- Award details
    awarded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    awarded_by UUID,  -- User or system that awarded the badge
    awarded_reason TEXT,

    -- Badge level/tier
    badge_tier INTEGER DEFAULT 1 CHECK (badge_tier >= 1),
    badge_score NUMERIC(5,2) DEFAULT 0,         -- Optional score component

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    is_permanent BOOLEAN DEFAULT TRUE,

    -- Display settings
    is_visible_on_profile BOOLEAN DEFAULT TRUE,
    display_order INTEGER DEFAULT 0,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_user_badges_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_badges_awarded_by FOREIGN KEY (awarded_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_user_badge_code UNIQUE (user_id, badge_code)
);

COMMENT ON TABLE socialcandor_schema.user_badges IS 'Tracks achievements, reputation badges, and verification badges for users';

--================================================================================================
-- TABLE: user_interests
-- Description: Stores user-selected topics, categories, or keywords for content personalization
-- Business Case: Enables personalized content feeds, recommendations, and targeted notifications.
--                Users can explicitly indicate interests to improve relevance.
-- KPIs: Interest selection rate, recommendation CTR, feed satisfaction score
-- Feature Reference: PER03 (Personalization), REC03 (Recommendations)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_interests (
    -- Primary key
    interest_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- Interest definition
    interest_type VARCHAR(30) NOT NULL CHECK (
        interest_type IN ('TOPIC', 'CATEGORY', 'KEYWORD', 'HASHTAG', 'AUTHOR')
    ),
    interest_value VARCHAR(255) NOT NULL,      -- e.g., 'technology', 'photography', 'user123'

    -- Weight/preference
    weight NUMERIC(5,2) DEFAULT 1.0 CHECK (weight >= 0 AND weight <= 10), -- 0 = excluded, 1=normal, >1 = boosted
    source VARCHAR(30) DEFAULT 'MANUAL' CHECK (
        source IN ('MANUAL', 'IMPLICIT', 'RECOMMENDED', 'IMPORTED')
    ),

    -- Timestamps
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_updated_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,       -- For temporary interests (e.g., trending)

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deleted BOOLEAN DEFAULT FALSE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_user_interests_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_interest UNIQUE (user_id, interest_type, interest_value)
);

COMMENT ON TABLE socialcandor_schema.user_interests IS 'Stores user-selected topics, categories, or keywords for content personalization';

--================================================================================================
-- TABLE: collections
-- Description: User-created collections (playlists/boards) to group content
-- Business Case: Enables users to curate content into custom collections (e.g., "Travel Bucket List",
--                "Favorite Recipes"). Supports sharing and collaborative collections.
-- KPIs: Collection creation rate, collection engagement, sharing adoption
-- Feature Reference: COL01 (Collections)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.collections (
    -- Primary key
    collection_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Ownership
    user_id UUID NOT NULL,

    -- Collection details
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(200) UNIQUE,                  -- URL-friendly name
    description TEXT,
    cover_image_url VARCHAR(500),

    -- Type and visibility
    collection_type VARCHAR(30) DEFAULT 'PERSONAL' CHECK (
        collection_type IN ('PERSONAL', 'COLLABORATIVE', 'CURATED', 'THEMED')
    ),
    visibility socialcandor_schema.collection_visibility DEFAULT 'PRIVATE',

    -- Sharing settings
    allow_collaborators BOOLEAN DEFAULT FALSE,
    collaborator_ids UUID[],                    -- Users who can add items (if collaborative)
    share_link VARCHAR(500),                     -- For unlisted sharing
    share_link_expires_at TIMESTAMP WITH TIME ZONE,

    -- Metrics
    item_count INTEGER DEFAULT 0 CHECK (item_count >= 0),
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    like_count INTEGER DEFAULT 0 CHECK (like_count >= 0),
    share_count INTEGER DEFAULT 0 CHECK (share_count >= 0),

    -- Status
    is_featured BOOLEAN DEFAULT FALSE,
    is_archived BOOLEAN DEFAULT FALSE,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,

    -- Constraints (to be added later)
    CONSTRAINT fk_collections_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.collections IS 'User-created collections (playlists/boards) to group content';

--================================================================================================
-- TABLE: collection_items
-- Description: Items belonging to a collection
-- Business Case: Links content items (posts, videos, photos, etc.) to collections, allowing ordering and notes.
--                Supports heterogeneous collections.
-- KPIs: Item addition rate, collection completion, engagement per item
-- Feature Reference: COL02 (Collection Items)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.collection_items (
    -- Primary key
    collection_item_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    collection_id UUID NOT NULL,

    -- Polymorphic item
    item_type socialcandor_schema.collection_item_type NOT NULL,
    item_id UUID NOT NULL,                      -- ID of the content (post, video, etc.)

    -- Ordering
    item_order INTEGER NOT NULL CHECK (item_order >= 0),
    added_by_user_id UUID NOT NULL,              -- Who added this item

    -- Optional notes
    user_note TEXT,

    -- Timestamps
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    removed_at TIMESTAMP WITH TIME ZONE,
    removed_by UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_collection_items_collection FOREIGN KEY (collection_id)
        REFERENCES socialcandor_schema.collections(collection_id) ON DELETE CASCADE,
    CONSTRAINT fk_collection_items_added_by FOREIGN KEY (added_by_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_collection_item UNIQUE (collection_id, item_type, item_id)
);

COMMENT ON TABLE socialcandor_schema.collection_items IS 'Items belonging to a collection';

--================================================================================================
-- TABLE: user_devices
-- Description: Manages user devices for push notifications and session management
-- Business Case: Enables reliable push notification delivery across multiple devices,
--                supports device-specific preferences and security features.
-- KPIs: Notification delivery success rate by device, active device count per user
-- Feature Reference: NOTIFY03 (Push Notifications), SEC08 (Device Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_devices (
    -- Primary key
    device_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- Device identification
    device_type VARCHAR(30) NOT NULL CHECK (
        device_type IN ('IOS', 'ANDROID', 'WEB', 'DESKTOP', 'TABLET', 'OTHER')
    ),
    device_name VARCHAR(255),
    device_model VARCHAR(100),
    device_os VARCHAR(50),
    os_version VARCHAR(50),
    app_version VARCHAR(20),

    -- Push notification tokens
    push_token VARCHAR(255),
    push_token_type VARCHAR(20) CHECK (
        push_token_type IN ('FCM', 'APNS', 'WEB_PUSH', 'HMS')
    ),
    push_token_expires_at TIMESTAMP WITH TIME ZONE,

    -- Web push specific (for VAPID)
    web_push_endpoint VARCHAR(500),
    web_push_keys JSONB,                         -- p256dh, auth keys

    -- Security
    device_fingerprint VARCHAR(255),             -- Unique device identifier
    last_ip_address INET,
    last_user_agent TEXT,
    trusted_device BOOLEAN DEFAULT FALSE,

    -- Session linking (optional)
    current_session_id UUID,

    -- Preferences
    notifications_enabled BOOLEAN DEFAULT TRUE,
    silent_notifications BOOLEAN DEFAULT FALSE,
    notification_sound_enabled BOOLEAN DEFAULT TRUE,
    do_not_disturb_until TIMESTAMP WITH TIME ZONE,

    -- Timestamps
    first_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_seen_at TIMESTAMP WITH TIME ZONE,
    last_notification_sent_at TIMESTAMP WITH TIME ZONE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    deactivation_reason VARCHAR(100),

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_user_devices_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_devices_session FOREIGN KEY (current_session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT uk_user_device_push UNIQUE (user_id, push_token)
);

COMMENT ON TABLE socialcandor_schema.user_devices IS 'Manages user devices for push notifications and session management';

--================================================================================================
-- TABLE: api_clients
-- Description: OAuth2 client applications (first-party and third-party)
-- Business Case: Supports API access control for mobile apps, third-party integrations, and developer ecosystem.
--                Manages client credentials, redirect URIs, and permissions.
-- KPIs: API adoption rate, third-party app usage, security compliance
-- Feature Reference: API01 (API Management), SEC09 (OAuth2)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_clients (
    -- Primary key
    client_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Client identification
    client_name VARCHAR(200) NOT NULL,
    client_description TEXT,
    client_logo_url VARCHAR(500),

    -- Credentials
    client_secret_hash VARCHAR(255) NOT NULL,    -- Hashed secret (bcrypt recommended)
    client_id_issued_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    client_secret_expires_at TIMESTAMP WITH TIME ZONE,

    -- Type
    client_type VARCHAR(30) NOT NULL CHECK (
        client_type IN ('CONFIDENTIAL', 'PUBLIC', 'FIRST_PARTY')
    ),
    application_type VARCHAR(30) CHECK (
        application_type IN ('WEB', 'NATIVE', 'MOBILE', 'SERVICE')
    ),

    -- Owner (user or organization that registered the client)
    owner_user_id UUID,
    owner_organization_id UUID,                  -- Could link to pages/groups later

    -- Redirect URIs (for authorization code flow)
    redirect_uris TEXT[] NOT NULL,
    allowed_grant_types VARCHAR(50)[] NOT NULL DEFAULT ARRAY['authorization_code', 'refresh_token'],

    -- Permissions (scopes)
    allowed_scopes TEXT[] DEFAULT '{}',
    default_scopes TEXT[] DEFAULT '{}',

    -- Rate limiting
    rate_limit_per_second INTEGER DEFAULT 10,
    rate_limit_per_day INTEGER DEFAULT 10000,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_confidential BOOLEAN DEFAULT TRUE,
    requires_consent BOOLEAN DEFAULT TRUE,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,

    -- Constraints (to be added later)
    CONSTRAINT fk_api_clients_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_api_clients_name UNIQUE (client_name)
);

COMMENT ON TABLE socialcandor_schema.api_clients IS 'OAuth2 client applications for API access control';

--================================================================================================
-- TABLE: api_keys
-- Description: API keys issued to users or clients for authentication
-- Business Case: Provides simple key-based API authentication for users, complements OAuth2.
--                Enables per-key rate limiting and permissions.
-- KPIs: Key usage, revocation rate, security incident rate
-- Feature Reference: API02 (API Keys), SEC10 (Key Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_keys (
    -- Primary key
    api_key_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Key value (store hashed)
    key_hash VARCHAR(255) NOT NULL UNIQUE,
    key_prefix VARCHAR(10) GENERATED ALWAYS AS (substring(encode(api_key_id::bytea, 'hex') from 1 for 8)) STORED,

    -- Owner (user or client)
    user_id UUID,       -- If owned by a user
    client_id UUID,     -- If owned by a client app

    -- Key metadata
    name VARCHAR(200) NOT NULL,                    -- User-friendly name
    description TEXT,

    -- Permissions
    scopes TEXT[] DEFAULT '{}',                    -- Allowed scopes (empty = all)
    allowed_ips INET[],
    allowed_referrers TEXT[],

    -- Rate limits (override defaults)
    rate_limit_per_second INTEGER,
    rate_limit_per_day INTEGER,

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_reason TEXT,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_api_keys_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_api_keys_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT chk_api_key_owner CHECK (
        (user_id IS NOT NULL AND client_id IS NULL) OR
        (user_id IS NULL AND client_id IS NOT NULL)
    )
);

COMMENT ON TABLE socialcandor_schema.api_keys IS 'API keys issued to users or clients for authentication';

--================================================================================================
-- TABLE: api_usage_logs
-- Description: Tracks API requests per user/client for rate limiting, billing, and analytics
-- Business Case: Enables monitoring, throttling, and metering of API usage. Supports audit and
--                capacity planning.
-- KPIs: API call volume, error rate, latency, rate limit enforcement
-- Feature Reference: API03 (API Analytics), MON03 (Usage Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_usage_logs (
    -- Primary key
    log_id BIGSERIAL PRIMARY KEY,                  -- Sequential for performance

    -- Requestor identification
    user_id UUID,
    client_id UUID,
    api_key_id UUID,

    -- Request details
    endpoint VARCHAR(500) NOT NULL,
    method VARCHAR(10) NOT NULL CHECK (
        method IN ('GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS')
    ),
    http_status INTEGER NOT NULL,
    response_time_ms INTEGER NOT NULL CHECK (response_time_ms >= 0),

    -- Request metadata
    ip_address INET,
    user_agent TEXT,
    referer TEXT,

    -- Rate limiting info
    rate_limit_bucket VARCHAR(100),

    -- Timestamp
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Partition key (for time-based partitioning, e.g., by month)
    request_date DATE GENERATED ALWAYS AS (requested_at::DATE) STORED,

    -- Constraints (to be added later)
    CONSTRAINT fk_api_usage_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_usage_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_usage_key FOREIGN KEY (api_key_id)
        REFERENCES socialcandor_schema.api_keys(api_key_id) ON DELETE SET NULL
)
PARTITION BY RANGE (request_date);

COMMENT ON TABLE socialcandor_schema.api_usage_logs IS 'Tracks API requests for rate limiting, billing, and analytics';

--================================================================================================
-- TABLE: background_jobs
-- Description: Queue for asynchronous tasks (video processing, email sending, data exports)
-- Business Case: Enables reliable processing of time-consuming tasks with retry logic and monitoring.
--                Supports prioritization and worker scaling.
-- KPIs: Job completion rate, average queue time, failure rate, processing throughput
-- Feature Reference: SYS04 (Background Jobs), QUEUE01 (Job Queue)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.background_jobs (
    -- Primary key
    job_id BIGSERIAL PRIMARY KEY,

    -- Job identification
    job_type VARCHAR(100) NOT NULL,                -- e.g., 'video_transcoding', 'email_delivery', 'data_export'
    job_name VARCHAR(255),

    -- Payload
    payload JSONB NOT NULL,                         -- Arguments for the job
    metadata JSONB DEFAULT '{}',

    -- Scheduling
    priority socialcandor_schema.job_priority DEFAULT 'MEDIUM',
    scheduled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    available_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, -- For delayed jobs
    expires_at TIMESTAMP WITH TIME ZONE,            -- Drop job if not started by this time

    -- Execution
    status socialcandor_schema.job_status DEFAULT 'PENDING',
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    failed_at TIMESTAMP WITH TIME ZONE,
    cancelled_at TIMESTAMP WITH TIME ZONE,

    -- Retry handling
    attempts INTEGER DEFAULT 0 CHECK (attempts >= 0),
    max_attempts INTEGER DEFAULT 3 CHECK (max_attempts >= 1),
    last_error TEXT,
    retry_delay_seconds INTEGER DEFAULT 60,        -- Delay before next retry

    -- Worker assignment
    worker_id VARCHAR(100),                         -- Identifier of worker processing the job
    worker_host VARCHAR(255),

    -- Result
    result JSONB,         -- Job result (if any)
    error_details JSONB,

    -- Dependencies
    depends_on_job_id BIGINT,                       -- Job that must complete first
    dependent_jobs_count INTEGER DEFAULT 0,         -- Number of jobs waiting on this one

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,       -- User who triggered the job (optional)
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (to be added later)
    CONSTRAINT fk_background_jobs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_background_jobs_depends FOREIGN KEY (depends_on_job_id)
        REFERENCES socialcandor_schema.background_jobs(job_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.background_jobs IS 'Queue for asynchronous tasks with retry and prioritization';

--================================================================================================
-- TABLE: feature_flags
-- Description: Controls rollout of new features per user/environment
-- Business Case: Enables safe feature deployment with targeted rollouts, A/B testing, and kill switches.
--                Supports gradual percentage rollouts and user-specific overrides.
-- KPIs: Feature adoption rate, rollback frequency, deployment success rate
-- Feature Reference: SYS05 (Feature Management), EXP01 (Experimentation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_flags (
    -- Primary key
    flag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Flag identification
    flag_key VARCHAR(100) UNIQUE NOT NULL,
    flag_name VARCHAR(200) NOT NULL,
    flag_description TEXT,

    -- Flag type
    flag_type VARCHAR(30) NOT NULL CHECK (
        flag_type IN ('BOOLEAN', 'PERCENTAGE', 'USER_LIST', 'AUDIENCE_SEGMENT')
    ),

    -- Value (for boolean flags)
    enabled BOOLEAN DEFAULT FALSE,

    -- Percentage rollout (0-100)
    rollout_percentage INTEGER DEFAULT 0 CHECK (rollout_percentage >= 0 AND rollout_percentage <= 100),

    -- User list overrides
    enabled_for_user_ids UUID[],                    -- Users who always see the feature
    disabled_for_user_ids UUID[],                    -- Users who never see the feature

    -- Segment targeting
    target_segment_id UUID,                          -- Link to user_segments table

    -- Environment
    environment VARCHAR(20) DEFAULT 'PRODUCTION' CHECK (
        environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'TEST')
    ),

    -- Scheduling
    start_date TIMESTAMP WITH TIME ZONE,
    end_date TIMESTAMP WITH TIME ZONE,

    -- Metadata
    owner_team VARCHAR(100),
    jira_ticket VARCHAR(100),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deprecated BOOLEAN DEFAULT FALSE,
    deprecated_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,

    -- Constraints (to be added later)
    CONSTRAINT fk_feature_flags_segment FOREIGN KEY (target_segment_id)
        REFERENCES socialcandor_schema.user_segments(segment_id) ON DELETE SET NULL,
    CONSTRAINT chk_feature_flag_rollout CHECK (
        (flag_type = 'PERCENTAGE' AND rollout_percentage IS NOT NULL) OR
        (flag_type != 'PERCENTAGE' OR (rollout_percentage IS NOT NULL))
    )
);

COMMENT ON TABLE socialcandor_schema.feature_flags IS 'Controls rollout of new features per user/environment';

--================================================================================================
-- TABLE: audit_logs
-- Description: Central audit log for high-value events across the platform
-- Business Case: Provides a single source of truth for compliance, security investigations, and forensic analysis.
--                Supplements per-table audit fields with detailed context.
-- KPIs: Audit completeness, query performance, incident investigation time
-- Feature Reference: AUD06 (Audit Logging), COMP10 (Compliance)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.audit_logs (
    -- Primary key
    audit_id BIGSERIAL PRIMARY KEY,

    -- Actor (who performed the action)
    actor_user_id UUID,
    actor_ip INET,
    actor_user_agent TEXT,

    -- Action details
    action socialcandor_schema.audit_action NOT NULL,
    target_type socialcandor_schema.audit_target_type NOT NULL,
    target_id UUID,        -- ID of the target entity

    -- Context
    before_state JSONB,     -- Snapshot before change
    after_state JSONB,      -- Snapshot after change
    changes JSONB,          -- Specific field changes

    -- Metadata
    reason TEXT,            -- Optional reason for action
    metadata JSONB DEFAULT '{}',

    -- Timestamp
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Partition key
    occurred_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,

    -- Constraints (to be added later)
    CONSTRAINT fk_audit_logs_actor FOREIGN KEY (actor_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
)
PARTITION BY RANGE (occurred_date);

COMMENT ON TABLE socialcandor_schema.audit_logs IS 'Central audit log for high-value events across the platform';

--================================================================================================
-- CREATE SEQUENCES (if needed)
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.api_usage_logs_log_id_seq START 1;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.background_jobs_job_id_seq START 1;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.audit_logs_audit_id_seq START 1;

--================================================================================================
-- ALTER TABLE CONSTRAINTS (Additional constraints not added inline)
--================================================================================================

-- saved_posts: collection_id foreign key (to be added after collections table)
ALTER TABLE socialcandor_schema.saved_posts
    ADD CONSTRAINT fk_saved_posts_collection FOREIGN KEY (collection_id)
        REFERENCES socialcandor_schema.collections(collection_id) ON DELETE SET NULL;

-- user_mutes: ensure target_type + target_id references appropriate tables (but we cannot have polymorphic FK, handled application-side)
-- Instead, we add a check constraint that target_id is not null; referential integrity is application-enforced.

-- user_badges: ensure badge_code format
ALTER TABLE socialcandor_schema.user_badges
    ADD CONSTRAINT chk_badge_code_format CHECK (badge_code ~ '^[A-Z][A-Z0-9_]{2,49}$');

-- user_interests: ensure interest_value not empty
ALTER TABLE socialcandor_schema.user_interests
    ADD CONSTRAINT chk_interest_value CHECK (LENGTH(TRIM(interest_value)) > 0);

-- collections: slug uniqueness already defined, but ensure format
ALTER TABLE socialcandor_schema.collections
    ADD CONSTRAINT chk_collection_slug_format CHECK (slug ~ '^[a-z0-9-]{3,200}$');

-- collection_items: ensure item_id exists (can't have FK due to polymorphism, but check not null)
ALTER TABLE socialcandor_schema.collection_items
    ADD CONSTRAINT chk_item_id_not_null CHECK (item_id IS NOT NULL);

-- user_devices: ensure push_token is present if push_token_type is set
ALTER TABLE socialcandor_schema.user_devices
    ADD CONSTRAINT chk_push_token_required CHECK (
        (push_token_type IS NULL AND push_token IS NULL) OR
        (push_token_type IS NOT NULL AND push_token IS NOT NULL)
    );

-- api_clients: ensure redirect_uris is not empty for web apps
ALTER TABLE socialcandor_schema.api_clients
    ADD CONSTRAINT chk_redirect_uris_required CHECK (
        (application_type = 'WEB' AND array_length(redirect_uris, 1) > 0) OR
        (application_type != 'WEB')
    );

-- api_keys: ensure key_hash is not null and unique (already)
ALTER TABLE socialcandor_schema.api_keys
    ADD CONSTRAINT chk_key_hash_not_empty CHECK (LENGTH(key_hash) > 0);

-- background_jobs: ensure available_at is not in the past
ALTER TABLE socialcandor_schema.background_jobs
    ADD CONSTRAINT chk_available_at_future CHECK (available_at >= scheduled_at);

-- feature_flags: ensure start_date <= end_date
ALTER TABLE socialcandor_schema.feature_flags
    ADD CONSTRAINT chk_feature_flag_dates CHECK (
        (start_date IS NULL AND end_date IS NULL) OR
        (start_date IS NOT NULL AND end_date IS NULL) OR
        (start_date IS NOT NULL AND end_date IS NOT NULL AND start_date <= end_date)
    );

-- audit_logs: ensure either actor_user_id is present or reason is system
ALTER TABLE socialcandor_schema.audit_logs
    ADD CONSTRAINT chk_audit_actor CHECK (
        (actor_user_id IS NOT NULL) OR
        (actor_user_id IS NULL AND reason = 'SYSTEM')
    );

--================================================================================================
-- INDEXES
--================================================================================================

-- saved_posts indexes
CREATE INDEX IF NOT EXISTS idx_saved_posts_user ON socialcandor_schema.saved_posts(user_id);
CREATE INDEX IF NOT EXISTS idx_saved_posts_post ON socialcandor_schema.saved_posts(post_id);
CREATE INDEX IF NOT EXISTS idx_saved_posts_collection ON socialcandor_schema.saved_posts(collection_id);
CREATE INDEX IF NOT EXISTS idx_saved_posts_tags ON socialcandor_schema.saved_posts USING GIN(tags);

-- user_mutes indexes
CREATE INDEX IF NOT EXISTS idx_user_mutes_muting_user ON socialcandor_schema.user_mutes(muting_user_id);
CREATE INDEX IF NOT EXISTS idx_user_mutes_target ON socialcandor_schema.user_mutes(target_type, target_id);
CREATE INDEX IF NOT EXISTS idx_user_mutes_active ON socialcandor_schema.user_mutes(is_active) WHERE is_active = TRUE;

-- user_badges indexes
CREATE INDEX IF NOT EXISTS idx_user_badges_user ON socialcandor_schema.user_badges(user_id);
CREATE INDEX IF NOT EXISTS idx_user_badges_code ON socialcandor_schema.user_badges(badge_code);
CREATE INDEX IF NOT EXISTS idx_user_badges_category ON socialcandor_schema.user_badges(badge_category);

-- user_interests indexes
CREATE INDEX IF NOT EXISTS idx_user_interests_user ON socialcandor_schema.user_interests(user_id);
CREATE INDEX IF NOT EXISTS idx_user_interests_value ON socialcandor_schema.user_interests(interest_value);
CREATE INDEX IF NOT EXISTS idx_user_interests_active ON socialcandor_schema.user_interests(is_active) WHERE is_active = TRUE;

-- collections indexes
CREATE INDEX IF NOT EXISTS idx_collections_user ON socialcandor_schema.collections(user_id);
CREATE INDEX IF NOT EXISTS idx_collections_slug ON socialcandor_schema.collections(slug);
CREATE INDEX IF NOT EXISTS idx_collections_visibility ON socialcandor_schema.collections(visibility);

-- collection_items indexes
CREATE INDEX IF NOT EXISTS idx_collection_items_collection ON socialcandor_schema.collection_items(collection_id);
CREATE INDEX IF NOT EXISTS idx_collection_items_item ON socialcandor_schema.collection_items(item_type, item_id);
CREATE INDEX IF NOT EXISTS idx_collection_items_order ON socialcandor_schema.collection_items(collection_id, item_order);

-- user_devices indexes
CREATE INDEX IF NOT EXISTS idx_user_devices_user ON socialcandor_schema.user_devices(user_id);
CREATE INDEX IF NOT EXISTS idx_user_devices_push_token ON socialcandor_schema.user_devices(push_token) WHERE push_token IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_user_devices_active ON socialcandor_schema.user_devices(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_user_devices_last_seen ON socialcandor_schema.user_devices(last_seen_at DESC);

-- api_clients indexes
CREATE INDEX IF NOT EXISTS idx_api_clients_owner ON socialcandor_schema.api_clients(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_api_clients_type ON socialcandor_schema.api_clients(client_type);

-- api_keys indexes
CREATE INDEX IF NOT EXISTS idx_api_keys_user ON socialcandor_schema.api_keys(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_api_keys_client ON socialcandor_schema.api_keys(client_id) WHERE client_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_api_keys_expires ON socialcandor_schema.api_keys(expires_at) WHERE expires_at IS NOT NULL;

-- api_usage_logs indexes (on partitioned table, indexes need to be created on each partition)
-- We'll create indexes on the parent table, but they won't be used unless partitions inherit them.
-- For simplicity, we'll create the indexes after partitions are created (omitted here, but in practice you'd create partitions and then indexes).
CREATE INDEX IF NOT EXISTS idx_api_usage_user ON socialcandor_schema.api_usage_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_api_usage_client ON socialcandor_schema.api_usage_logs(client_id);
CREATE INDEX IF NOT EXISTS idx_api_usage_endpoint ON socialcandor_schema.api_usage_logs(endpoint);
CREATE INDEX IF NOT EXISTS idx_api_usage_requested_at ON socialcandor_schema.api_usage_logs(requested_at DESC);

-- background_jobs indexes
CREATE INDEX IF NOT EXISTS idx_background_jobs_status ON socialcandor_schema.background_jobs(status);
CREATE INDEX IF NOT EXISTS idx_background_jobs_priority ON socialcandor_schema.background_jobs(priority, available_at) WHERE status = 'PENDING';
CREATE INDEX IF NOT EXISTS idx_background_jobs_type ON socialcandor_schema.background_jobs(job_type);
CREATE INDEX IF NOT EXISTS idx_background_jobs_depends ON socialcandor_schema.background_jobs(depends_on_job_id);

-- feature_flags indexes
CREATE INDEX IF NOT EXISTS idx_feature_flags_key ON socialcandor_schema.feature_flags(flag_key);
CREATE INDEX IF NOT EXISTS idx_feature_flags_active ON socialcandor_schema.feature_flags(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_feature_flags_environment ON socialcandor_schema.feature_flags(environment);

-- audit_logs indexes (on parent table, similar partition handling)
CREATE INDEX IF NOT EXISTS idx_audit_logs_actor ON socialcandor_schema.audit_logs(actor_user_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_target ON socialcandor_schema.audit_logs(target_type, target_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_action ON socialcandor_schema.audit_logs(action);
CREATE INDEX IF NOT EXISTS idx_audit_logs_occurred_at ON socialcandor_schema.audit_logs(occurred_at DESC);

--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================

-- Enable RLS on all new tables
ALTER TABLE socialcandor_schema.saved_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_mutes ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_badges ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_interests ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.collections ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.collection_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.api_clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.api_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.api_usage_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.background_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.feature_flags ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.audit_logs ENABLE ROW LEVEL SECURITY;

-- saved_posts policies
CREATE POLICY saved_posts_self_policy ON socialcandor_schema.saved_posts
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

-- user_mutes policies
CREATE POLICY user_mutes_self_policy ON socialcandor_schema.user_mutes
    FOR ALL
    USING (muting_user_id = current_setting('app.current_user_id')::UUID);

-- user_badges policies: user can see own badges; admins can manage all
CREATE POLICY user_badges_self_policy ON socialcandor_schema.user_badges
    FOR SELECT
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY user_badges_admin_policy ON socialcandor_schema.user_badges
    FOR ALL
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

-- user_interests policies: user can manage own interests
CREATE POLICY user_interests_self_policy ON socialcandor_schema.user_interests
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

-- collections policies: owner manages, others can view based on visibility
CREATE POLICY collections_owner_policy ON socialcandor_schema.collections
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY collections_read_policy ON socialcandor_schema.collections
    FOR SELECT
    USING (
        visibility IN ('PUBLIC', 'UNLISTED') OR
        user_id = current_setting('app.current_user_id')::UUID OR
        (visibility = 'SHARED' AND current_setting('app.current_user_id')::UUID = ANY(collaborator_ids))
    );

-- collection_items policies: inherit from collection visibility
CREATE POLICY collection_items_owner_policy ON socialcandor_schema.collection_items
    FOR ALL
    USING (collection_id IN (
        SELECT collection_id FROM socialcandor_schema.collections
        WHERE user_id = current_setting('app.current_user_id')::UUID
    ));

CREATE POLICY collection_items_read_policy ON socialcandor_schema.collection_items
    FOR SELECT
    USING (collection_id IN (
        SELECT collection_id FROM socialcandor_schema.collections
        WHERE visibility IN ('PUBLIC', 'UNLISTED') OR
              user_id = current_setting('app.current_user_id')::UUID OR
              (visibility = 'SHARED' AND current_setting('app.current_user_id')::UUID = ANY(collaborator_ids))
    ));

-- user_devices policies: user manages own devices
CREATE POLICY user_devices_self_policy ON socialcandor_schema.user_devices
    FOR ALL
    USING (user_id = current_setting('app.current_user_id')::UUID);

-- api_clients policies: owner manages, admins see all
CREATE POLICY api_clients_owner_policy ON socialcandor_schema.api_clients
    FOR ALL
    USING (owner_user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY api_clients_admin_policy ON socialcandor_schema.api_clients
    FOR ALL
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

-- api_keys policies: owner (user) manages, or client owner manages
CREATE POLICY api_keys_user_policy ON socialcandor_schema.api_keys
    FOR ALL
    USING (
        user_id = current_setting('app.current_user_id')::UUID OR
        client_id IN (
            SELECT client_id FROM socialcandor_schema.api_clients
            WHERE owner_user_id = current_setting('app.current_user_id')::UUID
        ) OR
        EXISTS (
            SELECT 1 FROM socialcandor_schema.users u
            WHERE u.user_id = current_setting('app.current_user_id')::UUID
            AND u.is_admin = TRUE
        )
    );

-- api_usage_logs policies: only admins can view full logs; users can see their own
CREATE POLICY api_usage_logs_self_policy ON socialcandor_schema.api_usage_logs
    FOR SELECT
    USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY api_usage_logs_admin_policy ON socialcandor_schema.api_usage_logs
    FOR SELECT
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

-- background_jobs policies: admins can manage; users can view jobs they created
CREATE POLICY background_jobs_self_policy ON socialcandor_schema.background_jobs
    FOR SELECT
    USING (created_by = current_setting('app.current_user_id')::UUID);

CREATE POLICY background_jobs_admin_policy ON socialcandor_schema.background_jobs
    FOR ALL
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

-- feature_flags policies: only admins can manage; all authenticated users can view flags (for client-side checks)
CREATE POLICY feature_flags_read_policy ON socialcandor_schema.feature_flags
    FOR SELECT
    USING (TRUE); -- All authenticated users can see feature flag definitions (but not modify)

CREATE POLICY feature_flags_admin_policy ON socialcandor_schema.feature_flags
    FOR ALL
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

-- audit_logs policies: only admins can view audit logs
CREATE POLICY audit_logs_admin_policy ON socialcandor_schema.audit_logs
    FOR SELECT
    USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users u
        WHERE u.user_id = current_setting('app.current_user_id')::UUID
        AND u.is_admin = TRUE
    ));

