    'POST_CREATE', 'POST_LIKE', 'POST_COMMENT', 'POST_SHARE',
    'FRIEND_ADD', 'FRIEND_REMOVE', 'FOLLOW', 'UNFOLLOW',
    'GROUP_JOIN', 'GROUP_LEAVE', 'PAGE_FOLLOW', 'PAGE_UNFOLLOW',
    'PROFILE_UPDATE', 'ACCOUNT_SETTING_CHANGE'
);

-- Object: 105 - ticket_status
CREATE TYPE socialcandor_schema.ticket_status AS ENUM (
    'OPEN', 'IN_PROGRESS', 'WAITING_ON_CUSTOMER', 'RESOLVED', 'CLOSED', 'ESCALATED'
