);

--================================================================================================
-- Table: user_levels
-- Description: Defines user levels/ranks based on activity points or achievements
-- Business Case: Gamification of user engagement; rewards active users with higher levels
-- KPIs: Level distribution, promotion rate, engagement by level
-- Feature Reference: GAM02 (Gamification Levels)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_levels (
    level_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    level_name VARCHAR(100) NOT NULL,
    level_number INTEGER NOT NULL CHECK (level_number >= 1),
    points_required INTEGER NOT NULL CHECK (points_required >= 0),
    benefits JSONB DEFAULT '{}',                     -- e.g., {"storage": "10GB", "badge": "gold"}
    badge_image_url VARCHAR(500),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT uk_user_levels_number UNIQUE (level_number)
);

COMMENT ON TABLE socialcandor_schema.user_levels IS 'Defines user levels/ranks based on activity points';

--================================================================================================
-- Table: privacy_settings
-- Description: Dedicated table for user privacy preferences (replacing JSONB column)
-- Business Case: Granular control over data visibility, required for GDPR compliance and user trust
-- KPIs: Privacy setting adoption, user satisfaction
-- Feature Reference: PRV02 (Privacy Controls)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.privacy_settings (
    privacy_setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,

    -- Visibility levels for different aspects
    profile_visibility VARCHAR(20) DEFAULT 'PUBLIC' CHECK (profile_visibility IN ('PUBLIC', 'FRIENDS', 'ONLY_ME')),
    post_visibility_default VARCHAR(20) DEFAULT 'PUBLIC' CHECK (post_visibility_default IN ('PUBLIC', 'FRIENDS', 'ONLY_ME')),
    story_visibility VARCHAR(20) DEFAULT 'FRIENDS' CHECK (story_visibility IN ('PUBLIC', 'FRIENDS', 'CLOSE_FRIENDS', 'ONLY_ME')),
    message_privacy VARCHAR(20) DEFAULT 'EVERYONE' CHECK (message_privacy IN ('EVERYONE', 'FRIENDS_ONLY', 'NO_ONE')),

    -- Data sharing consents
    data_sharing_analytics BOOLEAN DEFAULT TRUE,
    data_sharing_marketing BOOLEAN DEFAULT FALSE,
    data_sharing_partners BOOLEAN DEFAULT FALSE,

    -- Additional custom settings stored as JSON
    custom_settings JSONB DEFAULT '{}',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT uk_privacy_settings_user UNIQUE (user_id),
    CONSTRAINT fk_privacy_settings_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.privacy_settings IS 'Granular privacy settings per user';

--================================================================================================
-- Table: user_activity_logs
-- Description: Raw activity logs for analytics and audit
-- Business Case: Track user behavior for product decisions, anomaly detection, and personalization
-- KPIs: Activity volume, feature adoption, user retention patterns
-- Feature Reference: ANL05 (Activity Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_activity_logs (
    log_id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL,
    activity_type VARCHAR(100) NOT NULL,   -- Could use an ENUM, but free-form for flexibility
    activity_data JSONB DEFAULT '{}',
    ip_address INET,
    user_agent TEXT,
    session_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_user_activity_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_activity_logs_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.user_activity_logs IS 'Raw activity logs for analytics and audit';

--================================================================================================
-- Table: oauth_tokens
-- Description: OAuth2 access and refresh tokens for API authentication
-- Business Case: Secure API access with token-based authentication; required for OAuth2 compliance
-- KPIs: Token usage, revocation rate, security incidents
-- Feature Reference: API03 (OAuth2 Tokens)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.oauth_tokens (
    token_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    client_id UUID NOT NULL,
    user_id UUID,         -- NULL for client credentials grant
    access_token_hash VARCHAR(255) NOT NULL UNIQUE,
    refresh_token_hash VARCHAR(255) UNIQUE,
    scope TEXT[] DEFAULT '{}',
    token_type VARCHAR(20) DEFAULT 'Bearer',
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    refresh_expires_at TIMESTAMP WITH TIME ZONE,
    issued_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_reason TEXT,

    CONSTRAINT fk_oauth_tokens_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_oauth_tokens_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT chk_oauth_tokens_expiry CHECK (expires_at > issued_at)
);

COMMENT ON TABLE socialcandor_schema.oauth_tokens IS 'OAuth2 access and refresh tokens';

--================================================================================================
-- Table: breached_credentials
-- Description: Stores hashes of known compromised passwords (from HaveIBeenPwned, etc.)
-- Business Case: Prevent users from using breached passwords; enhance account security
-- KPIs: Breached password detection rate, account takeover prevention
-- Feature Reference: SEC11 (Password Security)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.breached_credentials (
    breach_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    password_hash VARCHAR(255) NOT NULL UNIQUE,
    source VARCHAR(100) DEFAULT 'HIBP',
    discovered_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE socialcandor_schema.breached_credentials IS 'Known compromised password hashes';

--================================================================================================
-- Table: organizations
-- Description: Multi-tenant organizational units (companies, teams, etc.)
-- Business Case: Support for enterprise features, organization-based access control
-- KPIs: Organization adoption, collaboration metrics
-- Feature Reference: ORG02 (Organization Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.organizations (
    organization_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    org_name VARCHAR(255) NOT NULL,
    legal_name VARCHAR(255),
    tax_id VARCHAR(50),
    tax_id_type VARCHAR(20) CHECK (tax_id_type IN ('EIN', 'VAT', 'GST', 'OTHER')),
    address TEXT,
    city VARCHAR(100),
    state_province VARCHAR(100),
    country_code VARCHAR(3),
    postal_code VARCHAR(20),
    phone VARCHAR(50),
    website VARCHAR(255),
    settings JSONB DEFAULT '{}',
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

COMMENT ON TABLE socialcandor_schema.organizations IS 'Multi-tenant organizational units';

--================================================================================================
-- Table: user_activities (structured activity feed)
-- Description: User-facing activity stream (e.g., "John liked your post")
-- Business Case: Display recent activities to users; power the activity feed
-- KPIs: Feed engagement, activity density
-- Feature Reference: SOC15 (Activity Feed)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_activities (
    activity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    activity_type socialcandor_schema.user_activity_type NOT NULL,
    target_type VARCHAR(50) NOT NULL CHECK (target_type IN ('POST', 'COMMENT', 'USER', 'GROUP', 'PAGE')),
    target_id UUID NOT NULL,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_user_activities_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.user_activities IS 'Structured activity feed entries';

--================================================================================================
-- Table: user_similarity
-- Description: Precomputed similarity scores between users for recommendations
-- Business Case: Enable friend suggestions, content recommendations based on similar users
-- KPIs: Recommendation click-through rate, similarity accuracy
-- Feature Reference: REC04 (Collaborative Filtering)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_similarity (
    similarity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id_1 UUID NOT NULL,
    user_id_2 UUID NOT NULL,
    similarity_score NUMERIC(5,4) NOT NULL CHECK (similarity_score >= 0 AND similarity_score <= 1),
    algorithm VARCHAR(50) DEFAULT 'COSINE',
    computed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_user_similarity_user1 FOREIGN KEY (user_id_1)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_similarity_user2 FOREIGN KEY (user_id_2)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_similarity_pair UNIQUE (user_id_1, user_id_2),
    CONSTRAINT chk_user_similarity_order CHECK (user_id_1 < user_id_2)
);

COMMENT ON TABLE socialcandor_schema.user_similarity IS 'Precomputed similarity scores between users';

--================================================================================================
-- Table: subscription_plans
-- Description: Available subscription plans for premium features
-- Business Case: Monetization through tiered subscriptions
-- KPIs: Plan adoption, conversion rate, revenue per plan
-- Feature Reference: SUB01 (Subscription Plans)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.subscription_plans (
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    plan_name VARCHAR(200) NOT NULL,
    plan_code VARCHAR(50) UNIQUE NOT NULL,
    description TEXT,
    price NUMERIC(10,2) NOT NULL CHECK (price >= 0),
    currency CHAR(3) DEFAULT 'USD',
    billing_cycle socialcandor_schema.billing_cycle NOT NULL,
    features JSONB DEFAULT '{}',                     -- e.g., {"storage": "100GB", "ads": false}
    is_active BOOLEAN DEFAULT TRUE,
    trial_days INTEGER DEFAULT 0 CHECK (trial_days >= 0),
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

COMMENT ON TABLE socialcandor_schema.subscription_plans IS 'Available subscription plans';

--================================================================================================
-- Table: user_subscriptions
-- Description: Tracks user subscriptions to plans
-- Business Case: Manage user premium access, billing, and renewals
-- KPIs: Active subscriptions, churn rate, MRR
-- Feature Reference: SUB02 (User Subscriptions)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_subscriptions (
    subscription_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    plan_id UUID NOT NULL,
    status socialcandor_schema.subscription_status NOT NULL DEFAULT 'TRIALING',
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    end_date TIMESTAMP WITH TIME ZONE,
    cancel_at_period_end BOOLEAN DEFAULT FALSE,
    payment_method_id UUID,
    auto_renew BOOLEAN DEFAULT TRUE,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_user_subscriptions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_subscriptions_plan FOREIGN KEY (plan_id)
        REFERENCES socialcandor_schema.subscription_plans(plan_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_subscriptions_payment_method FOREIGN KEY (payment_method_id)
        REFERENCES socialcandor_schema.payment_methods(payment_method_id) ON DELETE SET NULL,
    CONSTRAINT chk_user_subscription_dates CHECK (end_date IS NULL OR end_date > start_date)
);

COMMENT ON TABLE socialcandor_schema.user_subscriptions IS 'User subscriptions to plans';

--================================================================================================
-- Table: user_feedback_tickets
-- Description: User support and feedback tickets
-- Business Case: Centralized user support system with tracking and SLAs
-- KPIs: Resolution time, customer satisfaction, ticket volume
-- Feature Reference: SUP01 (Support Tickets)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_feedback_tickets (
    ticket_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    ticket_number VARCHAR(50) GENERATED ALWAYS AS (
        'TKT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,
    subject VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    category socialcandor_schema.ticket_category NOT NULL,
    priority socialcandor_schema.ticket_priority DEFAULT 'MEDIUM',
    status socialcandor_schema.ticket_status DEFAULT 'OPEN',
    assigned_to UUID,     -- staff user ID
    attachments JSONB DEFAULT '[]',
    resolution_notes TEXT,
    resolved_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_tickets_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_tickets_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.user_feedback_tickets IS 'User support and feedback tickets';

--================================================================================================
-- Table: live_streams
-- Description: Live streaming sessions
-- Business Case: Enable real-time video engagement with viewers
-- KPIs: Concurrent viewers, stream completion rate, engagement
-- Feature Reference: LIVE01 (Live Streaming)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.live_streams (
    stream_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    scheduled_start TIMESTAMP WITH TIME ZONE,
    actual_start TIMESTAMP WITH TIME ZONE,
    actual_end TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.stream_status DEFAULT 'SCHEDULED',
    stream_key VARCHAR(255),                         -- secret for ingesting
    playback_url VARCHAR(500),
    viewer_count INTEGER DEFAULT 0 CHECK (viewer_count >= 0),
    max_viewers INTEGER,
    recording_url VARCHAR(500),
    chat_enabled BOOLEAN DEFAULT TRUE,
    monetization_enabled BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_live_streams_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.live_streams IS 'Live streaming sessions';

--================================================================================================
-- Table: virtual_gifts (catalog)
-- Description: Catalog of virtual gifts users can send
-- Business Case: Monetization through virtual goods; enhance user interaction
-- KPIs: Gift purchase rate, revenue from gifts
-- Feature Reference: VG01 (Virtual Gifts)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.virtual_gifts (
    gift_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    gift_name VARCHAR(100) NOT NULL,
    gift_code VARCHAR(50) UNIQUE NOT NULL,
    description TEXT,
    image_url VARCHAR(500) NOT NULL,
    animation_url VARCHAR(500),                       -- optional animated version
    price NUMERIC(10,2) NOT NULL CHECK (price >= 0),
    currency CHAR(3) DEFAULT 'USD',
    is_active BOOLEAN DEFAULT TRUE,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

COMMENT ON TABLE socialcandor_schema.virtual_gifts IS 'Catalog of virtual gifts';

--================================================================================================
-- Table: user_gifts (sent gifts)
-- Description: Records gifts sent between users
-- Business Case: Track gift transactions for analytics and user history
-- KPIs: Gifts sent per user, gift popularity
-- Feature Reference: VG02 (Gift Transactions)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_gifts (
    user_gift_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    gift_id UUID NOT NULL,
    sender_id UUID NOT NULL,
    receiver_id UUID NOT NULL,
    message TEXT,
    status socialcandor_schema.gift_send_status DEFAULT 'SENT',
    transaction_id UUID,     -- link to wallet_transaction if paid
    sent_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    delivered_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_user_gifts_gift FOREIGN KEY (gift_id)
        REFERENCES socialcandor_schema.virtual_gifts(gift_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_gifts_sender FOREIGN KEY (sender_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_gifts_receiver FOREIGN KEY (receiver_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_gifts_transaction FOREIGN KEY (transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.user_gifts IS 'Records of gifts sent between users';

--================================================================================================
-- Table: knowledge_base
-- Description: Categories/sections for knowledge base articles
-- Business Case: Organize help content into a browsable structure
-- KPIs: Article views, search success rate
-- Feature Reference: KB01 (Knowledge Base)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.knowledge_base (
    kb_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(200) UNIQUE NOT NULL,
    description TEXT,
    parent_kb_id UUID,       -- for nested categories
    icon_url VARCHAR(500),
    sort_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_knowledge_base_parent FOREIGN KEY (parent_kb_id)
        REFERENCES socialcandor_schema.knowledge_base(kb_id) ON DELETE CASCADE,
    CONSTRAINT uk_knowledge_base_slug UNIQUE (slug)
);

COMMENT ON TABLE socialcandor_schema.knowledge_base IS 'Categories/sections for knowledge base articles';

--================================================================================================
-- Table: knowledge_articles
-- Description: Help articles and documentation
-- Business Case: Self-service support to reduce ticket volume and empower users
-- KPIs: Article helpfulness rating, view count, search ranking
-- Feature Reference: KB02 (Articles)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.knowledge_articles (
    article_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    kb_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    slug VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    excerpt TEXT,
    author_id UUID NOT NULL,
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    helpful_count INTEGER DEFAULT 0 CHECK (helpful_count >= 0),
    not_helpful_count INTEGER DEFAULT 0 CHECK (not_helpful_count >= 0),
    tags TEXT[],
    is_featured BOOLEAN DEFAULT FALSE,
    published_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_articles_kb FOREIGN KEY (kb_id)
        REFERENCES socialcandor_schema.knowledge_base(kb_id) ON DELETE CASCADE,
    CONSTRAINT fk_articles_author FOREIGN KEY (author_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_articles_slug UNIQUE (slug)
);

COMMENT ON TABLE socialcandor_schema.knowledge_articles IS 'Help articles and documentation';

--================================================================================================
-- Table: document_versions
-- Description: Version tracking for documents (media files, posts, etc.)
-- Business Case: Maintain history of document changes; enable rollback and audit
-- KPIs: Version usage, rollback frequency
-- Feature Reference: DOC01 (Document Versioning)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.document_versions (
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    document_type VARCHAR(50) NOT NULL CHECK (document_type IN ('POST', 'MEDIA', 'PAGE', 'ARTICLE')),
    document_id UUID NOT NULL,
    version_number INTEGER NOT NULL CHECK (version_number >= 1),
    file_url VARCHAR(500),   -- if document is a file
    content_snapshot JSONB,   -- snapshot of relevant data
    changes_summary TEXT,
    created_by UUID NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_document_versions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_document_version UNIQUE (document_type, document_id, version_number)
);

COMMENT ON TABLE socialcandor_schema.document_versions IS 'Version tracking for documents';

--================================================================================================
-- Table: collaboration_spaces
-- Description: Team/project spaces for collaborative work (similar to groups but focused on content)
-- Business Case: Facilitate team collaboration with shared documents, tasks, etc.
-- KPIs: Space creation rate, active members, collaboration activity
-- Feature Reference: COL03 (Collaboration Spaces)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.collaboration_spaces (
    space_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    slug VARCHAR(200) UNIQUE NOT NULL,
    description TEXT,
    owner_id UUID NOT NULL,
    space_type VARCHAR(30) DEFAULT 'PROJECT' CHECK (space_type IN ('PROJECT', 'TEAM', 'WORKSPACE')),
    visibility VARCHAR(20) DEFAULT 'PRIVATE' CHECK (visibility IN ('PRIVATE', 'ORGANIZATION', 'PUBLIC')),
    settings JSONB DEFAULT '{}',
    member_count INTEGER DEFAULT 0 CHECK (member_count >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_collaboration_spaces_owner FOREIGN KEY (owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.collaboration_spaces IS 'Team/project spaces for collaborative work';

--================================================================================================
-- Table: content_recommendations
-- Description: Precomputed content recommendations for users
-- Business Case: Personalize user feeds with relevant content
-- KPIs: Click-through rate, engagement lift
-- Feature Reference: REC05 (Content Recommendations)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.content_recommendations (
    recommendation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    content_type VARCHAR(30) NOT NULL CHECK (content_type IN ('POST', 'VIDEO', 'ARTICLE', 'PRODUCT')),
    content_id UUID NOT NULL,
    score NUMERIC(5,4) NOT NULL CHECK (score >= 0 AND score <= 1),
    reason VARCHAR(100),      -- e.g., "similar_users", "collaborative"
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_recommendations_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_recommendation UNIQUE (user_id, content_type, content_id)
);

COMMENT ON TABLE socialcandor_schema.content_recommendations IS 'Precomputed content recommendations';

--================================================================================================
-- Table: search_history
-- Description: User search queries history
-- Business Case: Improve search relevance, personalize results, and enable "recent searches"
-- KPIs: Search volume, result click rate, query trends
-- Feature Reference: SRCH03 (Search History)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.search_history (
    search_id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL,
    query TEXT NOT NULL,
    filters JSONB DEFAULT '{}',
    result_count INTEGER DEFAULT 0 CHECK (result_count >= 0),
    clicked_result_id UUID,  -- ID of content clicked (if any)
    clicked_result_type VARCHAR(30),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_search_history_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.search_history IS 'User search queries history';

--================================================================================================
-- Table: trending_topics
-- Description: Tracks trending hashtags, keywords, and topics over time
-- Business Case: Discover what's popular; power trending sections
-- KPIs: Trending accuracy, user engagement with trending content
-- Feature Reference: TREND01 (Trending Topics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.trending_topics (
    trend_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    topic VARCHAR(255) NOT NULL,
    topic_type VARCHAR(20) NOT NULL CHECK (topic_type IN ('HASHTAG', 'KEYWORD', 'LOCATION')),
    score NUMERIC(10,4) NOT NULL CHECK (score >= 0),
    rank INTEGER,
    period VARCHAR(20) DEFAULT 'DAY' CHECK (period IN ('HOUR', 'DAY', 'WEEK')),
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uk_trending_topic_period UNIQUE (topic, topic_type, period, calculated_at)
);

COMMENT ON TABLE socialcandor_schema.trending_topics IS 'Tracks trending hashtags, keywords, and topics';

--================================================================================================
-- Table: creator_monetization_settings
-- Description: Monetization settings for creators (e.g., tip amounts, subscription tiers)
-- Business Case: Enable creators to earn revenue from their content
-- KPIs: Creator earnings, payout frequency, monetization adoption
-- Feature Reference: MON06 (Creator Monetization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.creator_monetization_settings (
    setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL UNIQUE,
    tips_enabled BOOLEAN DEFAULT FALSE,
    default_tip_amounts NUMERIC(10,2)[] DEFAULT '{}',
    subscriptions_enabled BOOLEAN DEFAULT FALSE,
    subscription_tiers JSONB DEFAULT '[]',              -- array of {name, price, benefits}
    payout_method VARCHAR(50) CHECK (payout_method IN ('BANK', 'PAYPAL', 'WALLET')),
    payout_schedule VARCHAR(20) DEFAULT 'MONTHLY',
    minimum_payout NUMERIC(10,2) DEFAULT 10.00,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_monetization_settings_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.creator_monetization_settings IS 'Monetization settings for creators';

--================================================================================================
-- Table: creator_earnings
-- Description: Tracks creator earnings from tips, subscriptions, etc.
-- Business Case: Financial tracking for creator payouts
-- KPIs: Total earnings, average revenue per creator
-- Feature Reference: MON07 (Earnings Tracking)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.creator_earnings (
    earning_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    amount NUMERIC(15,2) NOT NULL CHECK (amount >= 0),
    currency CHAR(3) DEFAULT 'USD',
    source_type VARCHAR(30) NOT NULL CHECK (source_type IN ('TIP', 'SUBSCRIPTION', 'AD_REVENUE', 'GIFT')),
    source_id UUID,            -- link to transaction, subscription, etc.
    description TEXT,
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PAID', 'CANCELED')),
    paid_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_creator_earnings_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_creator_earnings_source FOREIGN KEY (source_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.creator_earnings IS 'Tracks creator earnings';

--================================================================================================
-- INDEXES
--================================================================================================

-- user_levels
CREATE INDEX IF NOT EXISTS idx_user_levels_active ON socialcandor_schema.user_levels(is_active) WHERE is_active = TRUE;

-- privacy_settings
CREATE INDEX IF NOT EXISTS idx_privacy_settings_user ON socialcandor_schema.privacy_settings(user_id);

-- user_activity_logs
CREATE INDEX IF NOT EXISTS idx_activity_logs_user ON socialcandor_schema.user_activity_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_activity_logs_created ON socialcandor_schema.user_activity_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_logs_type ON socialcandor_schema.user_activity_logs(activity_type);

-- oauth_tokens
CREATE INDEX IF NOT EXISTS idx_oauth_tokens_client ON socialcandor_schema.oauth_tokens(client_id);
CREATE INDEX IF NOT EXISTS idx_oauth_tokens_user ON socialcandor_schema.oauth_tokens(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_oauth_tokens_access_hash ON socialcandor_schema.oauth_tokens(access_token_hash);
CREATE INDEX IF NOT EXISTS idx_oauth_tokens_refresh_hash ON socialcandor_schema.oauth_tokens(refresh_token_hash) WHERE refresh_token_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_oauth_tokens_expires ON socialcandor_schema.oauth_tokens(expires_at) WHERE expires_at > CURRENT_TIMESTAMP;

-- breached_credentials
CREATE INDEX IF NOT EXISTS idx_breached_credentials_hash ON socialcandor_schema.breached_credentials(password_hash);

-- organizations
CREATE INDEX IF NOT EXISTS idx_organizations_name ON socialcandor_schema.organizations(org_name);
CREATE INDEX IF NOT EXISTS idx_organizations_country ON socialcandor_schema.organizations(country_code);

-- user_activities
CREATE INDEX IF NOT EXISTS idx_user_activities_user ON socialcandor_schema.user_activities(user_id);
CREATE INDEX IF NOT EXISTS idx_user_activities_target ON socialcandor_schema.user_activities(target_type, target_id);
CREATE INDEX IF NOT EXISTS idx_user_activities_created ON socialcandor_schema.user_activities(created_at DESC);

-- user_similarity
CREATE INDEX IF NOT EXISTS idx_user_similarity_user1 ON socialcandor_schema.user_similarity(user_id_1);
CREATE INDEX IF NOT EXISTS idx_user_similarity_user2 ON socialcandor_schema.user_similarity(user_id_2);
CREATE INDEX IF NOT EXISTS idx_user_similarity_score ON socialcandor_schema.user_similarity(similarity_score DESC);

-- subscription_plans
CREATE INDEX IF NOT EXISTS idx_subscription_plans_active ON socialcandor_schema.subscription_plans(is_active) WHERE is_active = TRUE;

-- user_subscriptions
CREATE INDEX IF NOT EXISTS idx_user_subscriptions_user ON socialcandor_schema.user_subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_user_subscriptions_plan ON socialcandor_schema.user_subscriptions(plan_id);
CREATE INDEX IF NOT EXISTS idx_user_subscriptions_status ON socialcandor_schema.user_subscriptions(status);
CREATE INDEX IF NOT EXISTS idx_user_subscriptions_end ON socialcandor_schema.user_subscriptions(end_date) WHERE end_date IS NOT NULL;

-- user_feedback_tickets
CREATE INDEX IF NOT EXISTS idx_tickets_user ON socialcandor_schema.user_feedback_tickets(user_id);
CREATE INDEX IF NOT EXISTS idx_tickets_assigned ON socialcandor_schema.user_feedback_tickets(assigned_to);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON socialcandor_schema.user_feedback_tickets(status);
CREATE INDEX IF NOT EXISTS idx_tickets_created ON socialcandor_schema.user_feedback_tickets(created_at DESC);

-- live_streams
CREATE INDEX IF NOT EXISTS idx_live_streams_user ON socialcandor_schema.live_streams(user_id);
CREATE INDEX IF NOT EXISTS idx_live_streams_status ON socialcandor_schema.live_streams(status);
CREATE INDEX IF NOT EXISTS idx_live_streams_scheduled ON socialcandor_schema.live_streams(scheduled_start) WHERE scheduled_start IS NOT NULL;

-- virtual_gifts
CREATE INDEX IF NOT EXISTS idx_virtual_gifts_active ON socialcandor_schema.virtual_gifts(is_active) WHERE is_active = TRUE;

-- user_gifts
CREATE INDEX IF NOT EXISTS idx_user_gifts_sender ON socialcandor_schema.user_gifts(sender_id);
CREATE INDEX IF NOT EXISTS idx_user_gifts_receiver ON socialcandor_schema.user_gifts(receiver_id);
CREATE INDEX IF NOT EXISTS idx_user_gifts_sent ON socialcandor_schema.user_gifts(sent_at DESC);

-- knowledge_base
CREATE INDEX IF NOT EXISTS idx_knowledge_base_parent ON socialcandor_schema.knowledge_base(parent_kb_id);
CREATE INDEX IF NOT EXISTS idx_knowledge_base_slug ON socialcandor_schema.knowledge_base(slug);

-- knowledge_articles
CREATE INDEX IF NOT EXISTS idx_knowledge_articles_kb ON socialcandor_schema.knowledge_articles(kb_id);
CREATE INDEX IF NOT EXISTS idx_knowledge_articles_status ON socialcandor_schema.knowledge_articles(status);
CREATE INDEX IF NOT EXISTS idx_knowledge_articles_tags ON socialcandor_schema.knowledge_articles USING GIN(tags);
CREATE INDEX IF NOT EXISTS idx_knowledge_articles_search ON socialcandor_schema.knowledge_articles USING GIN(to_tsvector('english', title || ' ' || content));

-- document_versions
CREATE INDEX IF NOT EXISTS idx_document_versions_document ON socialcandor_schema.document_versions(document_type, document_id);
CREATE INDEX IF NOT EXISTS idx_document_versions_created ON socialcandor_schema.document_versions(created_at DESC);

-- collaboration_spaces
CREATE INDEX IF NOT EXISTS idx_collab_spaces_owner ON socialcandor_schema.collaboration_spaces(owner_id);
CREATE INDEX IF NOT EXISTS idx_collab_spaces_slug ON socialcandor_schema.collaboration_spaces(slug);
CREATE INDEX IF NOT EXISTS idx_collab_spaces_type ON socialcandor_schema.collaboration_spaces(space_type);

-- content_recommendations
CREATE INDEX IF NOT EXISTS idx_content_recommendations_user ON socialcandor_schema.content_recommendations(user_id);
CREATE INDEX IF NOT EXISTS idx_content_recommendations_expires ON socialcandor_schema.content_recommendations(expires_at) WHERE expires_at IS NOT NULL;

-- search_history
CREATE INDEX IF NOT EXISTS idx_search_history_user ON socialcandor_schema.search_history(user_id);
