CREATE INDEX IF NOT EXISTS idx_trending_topics_topic ON socialcandor_schema.trending_topics(topic);
CREATE INDEX IF NOT EXISTS idx_trending_topics_score ON socialcandor_schema.trending_topics(score DESC);
CREATE INDEX IF NOT EXISTS idx_trending_topics_period ON socialcandor_schema.trending_topics(period, calculated_at DESC);

-- creator_monetization_settings
CREATE INDEX IF NOT EXISTS idx_creator_settings_user ON socialcandor_schema.creator_monetization_settings(user_id);

-- creator_earnings
