-- Enable RLS on tables that hold user-specific data
ALTER TABLE socialcandor_schema.privacy_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_activity_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_activities ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_similarity ENABLE ROW LEVEL SECURITY;
