-- Privacy settings: user can manage own; admins see all
CREATE POLICY privacy_settings_self_policy ON socialcandor_schema.privacy_settings
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY privacy_settings_admin_policy ON socialcandor_schema.privacy_settings
    FOR SELECT USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Activity logs: only user self or admin
CREATE POLICY activity_logs_self_policy ON socialcandor_schema.user_activity_logs
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY activity_logs_admin_policy ON socialcandor_schema.user_activity_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- User activities (feed): user can see own; others can see if public?
CREATE POLICY user_activities_self_policy ON socialcandor_schema.user_activities
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
-- Additional policies can be added for public activities (e.g., friends) later.

-- User similarity: user can see scores involving them; admin see all
CREATE POLICY user_similarity_self_policy ON socialcandor_schema.user_similarity
    FOR SELECT USING (user_id_1 = current_setting('app.current_user_id')::UUID OR user_id_2 = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_similarity_admin_policy ON socialcandor_schema.user_similarity
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Subscriptions: user sees own; admin see all
CREATE POLICY user_subscriptions_self_policy ON socialcandor_schema.user_subscriptions
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_subscriptions_admin_policy ON socialcandor_schema.user_subscriptions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Tickets: user sees own; staff sees assigned; admin all
CREATE POLICY tickets_self_policy ON socialcandor_schema.user_feedback_tickets
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY tickets_staff_policy ON socialcandor_schema.user_feedback_tickets
    FOR ALL USING (assigned_to = current_setting('app.current_user_id')::UUID);
CREATE POLICY tickets_admin_policy ON socialcandor_schema.user_feedback_tickets
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Live streams: owner manages; others can view if public/scheduled
CREATE POLICY live_streams_owner_policy ON socialcandor_schema.live_streams
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY live_streams_view_policy ON socialcandor_schema.live_streams
    FOR SELECT USING (status = 'LIVE' OR status = 'SCHEDULED' OR user_id = current_setting('app.current_user_id')::UUID);

-- Gifts: sender and receiver can see; admin all
CREATE POLICY user_gifts_self_policy ON socialcandor_schema.user_gifts
    FOR SELECT USING (sender_id = current_setting('app.current_user_id')::UUID OR receiver_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_gifts_admin_policy ON socialcandor_schema.user_gifts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Search history: user sees own; admin all
CREATE POLICY search_history_self_policy ON socialcandor_schema.search_history
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY search_history_admin_policy ON socialcandor_schema.search_history
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Recommendations: user sees own; admin all
CREATE POLICY content_recommendations_self_policy ON socialcandor_schema.content_recommendations
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY content_recommendations_admin_policy ON socialcandor_schema.content_recommendations
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Creator settings: user manages own; admin all
CREATE POLICY creator_settings_self_policy ON socialcandor_schema.creator_monetization_settings
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY creator_settings_admin_policy ON socialcandor_schema.creator_monetization_settings
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Earnings: user sees own; admin all
CREATE POLICY creator_earnings_self_policy ON socialcandor_schema.creator_earnings
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY creator_earnings_admin_policy ON socialcandor_schema.creator_earnings
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

