-- Object: 112 - job_status
CREATE TYPE socialcandor_schema.job_status AS ENUM (
    'DRAFT', 'PUBLISHED', 'CLOSED', 'EXPIRED', 'FILLED', 'ON_HOLD'
);
COMMENT ON TYPE socialcandor_schema.job_status IS 'Lifecycle status of a job posting';

-- Object: 113 - application_status
CREATE TYPE socialcandor_schema.application_status AS ENUM (
    'DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'INTERVIEWING', 'OFFERED', 'HIRED', 'REJECTED', 'WITHDRAWN'
);
COMMENT ON TYPE socialcandor_schema.application_status IS 'Status of a job application';

-- Object: 114 - course_level
CREATE TYPE socialcandor_schema.course_level AS ENUM (
    'BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT'
);
COMMENT ON TYPE socialcandor_schema.course_level IS 'Difficulty level of a course';

-- Object: 115 - enrollment_status
CREATE TYPE socialcandor_schema.enrollment_status AS ENUM (
    'ACTIVE', 'COMPLETED', 'DROPPED', 'EXPIRED', 'PENDING'
);
COMMENT ON TYPE socialcandor_schema.enrollment_status IS 'Status of a user’s enrollment in a course';

-- Object: 116 - quiz_type
CREATE TYPE socialcandor_schema.quiz_type AS ENUM (
    'PRACTICE', 'GRADED', 'FINAL', 'SURVEY', 'ASSESSMENT'
);
COMMENT ON TYPE socialcandor_schema.quiz_type IS 'Type of quiz';

-- Object: 117 - attempt_status
CREATE TYPE socialcandor_schema.attempt_status AS ENUM (
    'IN_PROGRESS', 'COMPLETED', 'TIMED_OUT', 'ABANDONED'
);
COMMENT ON TYPE socialcandor_schema.attempt_status IS 'Status of a quiz attempt';

-- Object: 118 - question_type
CREATE TYPE socialcandor_schema.question_type AS ENUM (
    'MULTIPLE_CHOICE', 'SINGLE_CHOICE', 'TRUE_FALSE', 'TEXT', 'NUMERIC', 'MATCHING'
);
COMMENT ON TYPE socialcandor_schema.question_type IS 'Type of question in a quiz or survey';

--================================================================================================
-- SEQUENCES (for human‑readable identifiers)
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.job_posting_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.certificate_seq START 1000;

--================================================================================================
-- TABLE: job_postings
-- Description: Job listings posted by companies or users
-- Business Case: Enable job marketplace within the platform
-- KPIs: Number of postings, application rate, time‑to‑fill
-- Feature Reference: JOB01 (Job Postings)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.job_postings (
    -- Primary key
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'JOB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.job_posting_seq')::TEXT, 6, '0')
    ) STORED,

    -- Who posted the job (user or organization)
    poster_user_id UUID,
    poster_org_id UUID,          -- Reference to organizations table (if exists)
    company_name VARCHAR(255) NOT NULL,
    company_logo_url VARCHAR(500),

    -- Job details
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    requirements TEXT,
    responsibilities TEXT,
    benefits TEXT,

    -- Employment type
    employment_type VARCHAR(30) CHECK (employment_type IN ('FULL_TIME', 'PART_TIME', 'CONTRACT', 'INTERNSHIP', 'FREELANCE', 'TEMPORARY')),
    work_location VARCHAR(30) CHECK (work_location IN ('ONSITE', 'REMOTE', 'HYBRID')),

    -- Location
    location_country VARCHAR(3),
    location_city VARCHAR(100),
    location_address TEXT,

    -- Compensation
    salary_min NUMERIC(10,2),
    salary_max NUMERIC(10,2),
    currency CHAR(3) DEFAULT 'USD',
    compensation_description TEXT,

    -- Experience & education
    experience_min_years INTEGER CHECK (experience_min_years >= 0),
    experience_max_years INTEGER CHECK (experience_max_years >= 0),
    education_level VARCHAR(30) CHECK (education_level IN ('HIGH_SCHOOL', 'ASSOCIATE', 'BACHELOR', 'MASTER', 'DOCTORATE', 'ANY')),

    -- Skills required (array of skill IDs or names)
    required_skills TEXT[],
    preferred_skills TEXT[],

    -- Application method
    application_method VARCHAR(30) CHECK (application_method IN ('INTERNAL', 'EXTERNAL_URL', 'EMAIL')),
    external_application_url VARCHAR(500),
    application_email VARCHAR(255),

    -- Dates
    posted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    published_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,

    -- Counters
    views_count INTEGER DEFAULT 0 CHECK (views_count >= 0),
    applications_count INTEGER DEFAULT 0 CHECK (applications_count >= 0),

    -- Status
    status socialcandor_schema.job_status NOT NULL DEFAULT 'DRAFT',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (inline)
    CONSTRAINT fk_job_postings_poster_user FOREIGN KEY (poster_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_job_postings_poster_org FOREIGN KEY (poster_org_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE SET NULL,
    CONSTRAINT chk_job_salary CHECK (salary_max IS NULL OR salary_min IS NULL OR salary_max >= salary_min),
    CONSTRAINT chk_job_experience CHECK (experience_max_years IS NULL OR experience_min_years IS NULL OR experience_max_years >= experience_min_years),
    CONSTRAINT chk_job_poster CHECK (poster_user_id IS NOT NULL OR poster_org_id IS NOT NULL)
);

COMMENT ON TABLE socialcandor_schema.job_postings IS 'Job listings posted by companies or users';

--================================================================================================
-- TABLE: job_applications
-- Description: User applications to job postings
-- Business Case: Track applications, manage hiring workflow
-- KPIs: Application conversion rate, time‑in‑status
-- Feature Reference: JOB02 (Job Applications)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.job_applications (
    -- Primary key
    application_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    job_id UUID NOT NULL,
    applicant_user_id UUID NOT NULL,

    -- Application details
    cover_letter TEXT,
    resume_url VARCHAR(500),
    portfolio_url VARCHAR(500),
    additional_documents JSONB DEFAULT '[]',

    -- User‑provided answers (e.g., to custom questions)
    answers JSONB DEFAULT '{}',

    -- Status
    status socialcandor_schema.application_status NOT NULL DEFAULT 'SUBMITTED',
    status_history JSONB DEFAULT '[]',          -- Audit trail of status changes

    -- Dates
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    interviewed_at TIMESTAMP WITH TIME ZONE,
    offered_at TIMESTAMP WITH TIME ZONE,
    hired_at TIMESTAMP WITH TIME ZONE,
    rejected_at TIMESTAMP WITH TIME ZONE,

    -- Hiring manager notes (internal)
    internal_notes TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_job_applications_job FOREIGN KEY (job_id)
        REFERENCES socialcandor_schema.job_postings(job_id) ON DELETE CASCADE,
    CONSTRAINT fk_job_applications_applicant FOREIGN KEY (applicant_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_job_application UNIQUE (job_id, applicant_user_id)
);

COMMENT ON TABLE socialcandor_schema.job_applications IS 'User applications to job postings';

--================================================================================================
-- TABLE: learning_courses
-- Description: Educational courses offered on the platform
-- Business Case: Enable learning and development features
-- KPIs: Course enrollments, completion rate, average rating
-- Feature Reference: EDU01 (Courses)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.learning_courses (
    -- Primary key
    course_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Course identification
    course_code VARCHAR(50) UNIQUE,
    title VARCHAR(255) NOT NULL,
    slug VARCHAR(255) UNIQUE NOT NULL,
    description TEXT,
    short_description VARCHAR(500),

    -- Categorization
    category VARCHAR(100),
    subcategory VARCHAR(100),
    level socialcandor_schema.course_level DEFAULT 'BEGINNER',
    language VARCHAR(10) DEFAULT 'en',

    -- Ownership
    instructor_user_id UUID,                -- User who created the course
    instructor_org_id UUID,                  -- Organization offering the course

    -- Media
    thumbnail_url VARCHAR(500),
    preview_video_url VARCHAR(500),

    -- Content summary
    duration_hours NUMERIC(5,2),             -- Estimated total duration
    modules_count INTEGER DEFAULT 0,
    lessons_count INTEGER DEFAULT 0,
    quizzes_count INTEGER DEFAULT 0,

    -- Pricing
    is_paid BOOLEAN DEFAULT FALSE,
    price NUMERIC(10,2) CHECK (price >= 0),
    currency CHAR(3) DEFAULT 'USD',
    discount_percent INTEGER CHECK (discount_percent >= 0 AND discount_percent <= 100),

    -- Enrollment stats
    total_enrollments INTEGER DEFAULT 0 CHECK (total_enrollments >= 0),
    completions INTEGER DEFAULT 0 CHECK (completions >= 0),
    average_rating NUMERIC(3,2) CHECK (average_rating >= 0 AND average_rating <= 5),
    review_count INTEGER DEFAULT 0 CHECK (review_count >= 0),

    -- Dates
    published_at TIMESTAMP WITH TIME ZONE,
    last_updated_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED')),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_learning_courses_instructor_user FOREIGN KEY (instructor_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_learning_courses_instructor_org FOREIGN KEY (instructor_org_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE SET NULL,
    CONSTRAINT chk_course_instructor CHECK (instructor_user_id IS NOT NULL OR instructor_org_id IS NOT NULL)
);

COMMENT ON TABLE socialcandor_schema.learning_courses IS 'Educational courses offered on the platform';

--================================================================================================
-- TABLE: enrollments
-- Description: Tracks user enrollments in courses
-- Business Case: Manage learner progress and access
-- KPIs: Enrollment rate, progress, completion
-- Feature Reference: EDU02 (Enrollments)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.enrollments (
    -- Primary key
    enrollment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    course_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Enrollment details
    enrolled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    start_date TIMESTAMP WITH TIME ZONE,
    completion_date TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Progress tracking
    progress_percent INTEGER DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    last_accessed_at TIMESTAMP WITH TIME ZONE,
    completed_modules INTEGER DEFAULT 0,
    completed_lessons INTEGER DEFAULT 0,

    -- Status
    status socialcandor_schema.enrollment_status DEFAULT 'ACTIVE',

    -- Payment info (if paid)
    payment_transaction_id UUID,
    payment_amount NUMERIC(10,2),

    -- Certificates issued (link to certificates table)
    certificate_id UUID,                     -- Will be updated when certificate is issued

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_enrollments_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE,
    CONSTRAINT fk_enrollments_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_enrollments_payment FOREIGN KEY (payment_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
    CONSTRAINT uk_enrollment UNIQUE (course_id, user_id)
);

COMMENT ON TABLE socialcandor_schema.enrollments IS 'Tracks user enrollments in courses';

--================================================================================================
-- TABLE: certificates
-- Description: Certificates issued to users upon course completion
-- Business Case: Provide verifiable credentials; gamification
-- KPIs: Certificate issuance rate, sharing rate
-- Feature Reference: EDU03 (Certificates)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.certificates (
    -- Primary key
    certificate_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    certificate_number VARCHAR(50) GENERATED ALWAYS AS (
        'CERT-' || TO_CHAR(issued_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.certificate_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    enrollment_id UUID NOT NULL,
    course_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Certificate details
    issue_date DATE NOT NULL DEFAULT CURRENT_DATE,
    expiry_date DATE,                         -- If the certificate expires
    certificate_url VARCHAR(500),               -- PDF or image of the certificate
    verification_hash VARCHAR(64) UNIQUE,       -- Unique hash for public verification

    -- Metadata
    grade VARCHAR(20), -- e.g., "Pass", "Distinction"
    score_percent INTEGER CHECK (score_percent >= 0 AND score_percent <= 100),
    metadata JSONB DEFAULT '{}',

    -- Sharing
    is_public BOOLEAN DEFAULT FALSE,            -- Whether certificate is publicly visible

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_certificates_enrollment FOREIGN KEY (enrollment_id)
        REFERENCES socialcandor_schema.enrollments(enrollment_id) ON DELETE CASCADE,
    CONSTRAINT fk_certificates_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE,
    CONSTRAINT fk_certificates_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_certificate_enrollment UNIQUE (enrollment_id)
);

COMMENT ON TABLE socialcandor_schema.certificates IS 'Certificates issued to users upon course completion';

--================================================================================================
-- TABLE: quizzes
-- Description: Quizzes associated with courses (or standalone)
-- Business Case: Assess learner knowledge; interactive learning
-- KPIs: Quiz attempts, pass rate, average score
-- Feature Reference: QUIZ01 (Quizzes)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.quizzes (
    -- Primary key
    quiz_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Course association (optional)
    course_id UUID,
    module_id VARCHAR(100),                    -- Could link to a course module; simplified as string for now

    -- Quiz identification
    title VARCHAR(255) NOT NULL,
    description TEXT,
    quiz_type socialcandor_schema.quiz_type NOT NULL DEFAULT 'PRACTICE',

    -- Configuration
    time_limit_minutes INTEGER CHECK (time_limit_minutes >= 0),  -- NULL means no limit
    passing_score_percent INTEGER CHECK (passing_score_percent >= 0 AND passing_score_percent <= 100),
    max_attempts INTEGER DEFAULT 1 CHECK (max_attempts >= 0),    -- 0 = unlimited
    shuffle_questions BOOLEAN DEFAULT FALSE,
    show_results_immediately BOOLEAN DEFAULT TRUE,

    -- Questions count (denormalized)
    question_count INTEGER DEFAULT 0 CHECK (question_count >= 0),

    -- Status
    is_published BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_quizzes_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.quizzes IS 'Quizzes associated with courses (or standalone)';

--================================================================================================
-- TABLE: quiz_questions
-- Description: Questions belonging to a quiz
-- Business Case: Store question bank with answers and explanations
-- KPIs: Question difficulty, discrimination index
-- Feature Reference: QUIZ02 (Questions)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.quiz_questions (
    -- Primary key
    question_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Quiz reference
    quiz_id UUID NOT NULL,

    -- Question content
    question_text TEXT NOT NULL,
    question_type socialcandor_schema.question_type NOT NULL,
    points INTEGER DEFAULT 1 CHECK (points >= 0),

    -- Options (for multiple choice)
    options JSONB,         -- e.g., ["Option A", "Option B", ...]

    -- Correct answer(s)
    correct_answer JSONB,  -- For multiple choice: index(es) or value(s)

    -- Explanation shown after answering
    explanation TEXT,

    -- Metadata
    difficulty NUMERIC(3,2) CHECK (difficulty >= 0 AND difficulty <= 1), -- 0=easy, 1=hard
    tags TEXT[],

    -- Order within quiz
    display_order INTEGER DEFAULT 0 CHECK (display_order >= 0),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_quiz_questions_quiz FOREIGN KEY (quiz_id)
        REFERENCES socialcandor_schema.quizzes(quiz_id) ON DELETE CASCADE,
    CONSTRAINT uk_quiz_question_order UNIQUE (quiz_id, display_order)
);

COMMENT ON TABLE socialcandor_schema.quiz_questions IS 'Questions belonging to a quiz';

--================================================================================================
-- TABLE: quiz_attempts
-- Description: User attempts at quizzes
-- Business Case: Track learner performance, grading, and time taken
-- KPIs: Attempt count, average score, completion rate
-- Feature Reference: QUIZ03 (Attempts)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.quiz_attempts (
    -- Primary key
    attempt_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    quiz_id UUID NOT NULL,
    user_id UUID NOT NULL,
    enrollment_id UUID,    -- Optional, if part of a course enrollment

    -- Attempt details
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE,
    time_taken_seconds INTEGER CHECK (time_taken_seconds >= 0),

    -- Status
    status socialcandor_schema.attempt_status DEFAULT 'IN_PROGRESS',

    -- Results (denormalized)
    score INTEGER CHECK (score >= 0),                 -- Points earned
    max_score INTEGER CHECK (max_score >= 0),         -- Total possible points
    score_percent INTEGER GENERATED ALWAYS AS (
        CASE WHEN max_score > 0 THEN (score * 100 / max_score) ELSE 0 END
    ) STORED,
    passed BOOLEAN GENERATED ALWAYS AS (
        CASE WHEN max_score > 0 AND (score * 100 / max_score) >= (
            SELECT passing_score_percent FROM socialcandor_schema.quizzes WHERE quiz_id = quiz_attempts.quiz_id
        ) THEN TRUE ELSE FALSE END
    ) STORED,

    -- Detailed answers
    answers JSONB DEFAULT '[]',                       -- Array of {question_id, answer, is_correct, time_spent}

    -- Review
    reviewed BOOLEAN DEFAULT FALSE,
    reviewed_by UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_quiz_attempts_quiz FOREIGN KEY (quiz_id)
        REFERENCES socialcandor_schema.quizzes(quiz_id) ON DELETE CASCADE,
    CONSTRAINT fk_quiz_attempts_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_quiz_attempts_enrollment FOREIGN KEY (enrollment_id)
        REFERENCES socialcandor_schema.enrollments(enrollment_id) ON DELETE SET NULL,
    CONSTRAINT fk_quiz_attempts_reviewed_by FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_attempt_dates CHECK (completed_at IS NULL OR completed_at >= started_at),
    CONSTRAINT chk_attempt_scores CHECK (score IS NULL OR max_score IS NULL OR score <= max_score)
);

COMMENT ON TABLE socialcandor_schema.quiz_attempts IS 'User attempts at quizzes';

--================================================================================================
-- TABLE: surveys
-- Description: Surveys for user feedback, market research, etc.
-- Business Case: Collect structured feedback from users
-- KPIs: Response rate, completion rate
-- Feature Reference: SRV01 (Surveys)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.surveys (
    -- Primary key
    survey_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Survey identification
    title VARCHAR(255) NOT NULL,
    description TEXT,
    survey_type VARCHAR(30) CHECK (survey_type IN ('FEEDBACK', 'NPS', 'CUSTOMER_SATISFACTION', 'MARKET_RESEARCH', 'OTHER')),

    -- Target audience (could be user segments, but simplified)
    target_audience VARCHAR(30) CHECK (target_audience IN ('ALL', 'SPECIFIC_USERS', 'RANDOM_SAMPLE')),

    -- Configuration
    is_anonymous BOOLEAN DEFAULT FALSE,
    allow_multiple_responses BOOLEAN DEFAULT FALSE,
    show_results_after_submission BOOLEAN DEFAULT FALSE,

    -- Dates
    published_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PUBLISHED', 'CLOSED', 'ARCHIVED')),

    -- Counters
    responses_count INTEGER DEFAULT 0 CHECK (responses_count >= 0),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints (inline)
    CONSTRAINT fk_surveys_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);

COMMENT ON TABLE socialcandor_schema.surveys IS 'Surveys for user feedback, market research, etc.';

--================================================================================================
-- TABLE: survey_responses
-- Description: Individual responses to surveys
-- Business Case: Store survey answers for analysis
-- KPIs: Response quality, drop‑off rate
-- Feature Reference: SRV02 (Survey Responses)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.survey_responses (
    -- Primary key
    response_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    survey_id UUID NOT NULL,
    user_id UUID,           -- NULL if anonymous

    -- Response details
    answers JSONB NOT NULL,  -- Key‑value pairs: question_id -> answer
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    time_spent_seconds INTEGER CHECK (time_spent_seconds >= 0),

    -- IP and user agent (for anonymous tracking)
    ip_address INET,
    user_agent TEXT,

    -- Completion status
    is_complete BOOLEAN DEFAULT TRUE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_survey_responses_survey FOREIGN KEY (survey_id)
        REFERENCES socialcandor_schema.surveys(survey_id) ON DELETE CASCADE,
    CONSTRAINT fk_survey_responses_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_survey_response UNIQUE (survey_id, user_id) WHERE user_id IS NOT NULL
);

COMMENT ON TABLE socialcandor_schema.survey_responses IS 'Individual responses to surveys';

