--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================

-- Enable RLS on all new tables (where user data is sensitive)
ALTER TABLE socialcandor_schema.job_applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.certificates ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.quiz_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.survey_responses ENABLE ROW LEVEL SECURITY;

-- job_applications: applicants see their own; job posters see applications for their jobs
CREATE POLICY job_applications_self_policy ON socialcandor_schema.job_applications
    FOR SELECT USING (applicant_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY job_applications_poster_policy ON socialcandor_schema.job_applications
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.job_postings jp
        WHERE jp.job_id = job_applications.job_id
        AND (jp.poster_user_id = current_setting('app.current_user_id')::UUID)
    ));
CREATE POLICY job_applications_admin_policy ON socialcandor_schema.job_applications
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- enrollments: user sees own; instructors see enrollments for their courses
CREATE POLICY enrollments_self_policy ON socialcandor_schema.enrollments
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY enrollments_instructor_policy ON socialcandor_schema.enrollments
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.learning_courses lc
        WHERE lc.course_id = enrollments.course_id
        AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY enrollments_admin_policy ON socialcandor_schema.enrollments
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- certificates: user sees own; instructors see certificates for their courses
CREATE POLICY certificates_self_policy ON socialcandor_schema.certificates
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY certificates_instructor_policy ON socialcandor_schema.certificates
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.learning_courses lc
        WHERE lc.course_id = certificates.course_id
        AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY certificates_admin_policy ON socialcandor_schema.certificates
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- quiz_attempts: user sees own; instructors see attempts for their quizzes
CREATE POLICY quiz_attempts_self_policy ON socialcandor_schema.quiz_attempts
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY quiz_attempts_instructor_policy ON socialcandor_schema.quiz_attempts
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.quizzes q
        JOIN socialcandor_schema.learning_courses lc ON q.course_id = lc.course_id
        WHERE q.quiz_id = quiz_attempts.quiz_id
        AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY quiz_attempts_admin_policy ON socialcandor_schema.quiz_attempts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- survey_responses: users see own (if non‑anonymous); survey creators see all responses
CREATE POLICY survey_responses_self_policy ON socialcandor_schema.survey_responses
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY survey_responses_creator_policy ON socialcandor_schema.survey_responses
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.surveys s
        WHERE s.survey_id = survey_responses.survey_id
        AND s.created_by = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY survey_responses_admin_policy ON socialcandor_schema.survey_responses
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

