--================================================================================================
-- ENUMS (for new tables, reusing existing ones where applicable)
--================================================================================================

-- Object: 119 - dsar_request_type
-- Description: Types of Data Subject Access Requests under GDPR
-- Business Case: Categorize DSAR types for proper handling workflows
-- Feature Reference: GDPR01 (Data Subject Rights)
--================================================================================================
CREATE TYPE socialcandor_schema.dsar_request_type AS ENUM (
    'ACCESS',           -- Right to access (Art. 15)
    'RECTIFICATION',    -- Right to rectification (Art. 16)
    'ERASURE',          -- Right to erasure / 'right to be forgotten' (Art. 17)
    'RESTRICTION',      -- Right to restriction of processing (Art. 18)
    'PORTABILITY',      -- Right to data portability (Art. 20)
    'OBJECTION',        -- Right to object (Art. 21)
    'AUTOMATED_DECISION' -- Rights related to automated decision making (Art. 22)
);
COMMENT ON TYPE socialcandor_schema.dsar_request_type IS 'Types of Data Subject Access Requests under GDPR';

-- Object: 120 - dsar_status
-- Description: Lifecycle status of a Data Subject Access Request
-- Business Case: Track DSAR progress and meet response deadlines
-- Feature Reference: GDPR01 (Data Subject Rights)
--================================================================================================
CREATE TYPE socialcandor_schema.dsar_status AS ENUM (
    'SUBMITTED',        -- Request received
    'VERIFYING',        -- Verifying requester identity
    'PROCESSING',       -- Gathering data / performing action
    'AWAITING_INFO',    -- Need more information from requester
    'COMPLETED',        -- Request fulfilled
    'REJECTED',         -- Request rejected (with reason)
    'EXPIRED',          -- Deadline passed without completion
    'EXTENDED'          -- Deadline extended (complex request)
);
COMMENT ON TYPE socialcandor_schema.dsar_status IS 'Lifecycle status of a Data Subject Access Request';

-- Object: 121 - breach_severity
-- Description: Severity classification for data breaches
-- Business Case: Prioritize response and notification efforts
-- Feature Reference: GDPR02 (Breach Management)
--================================================================================================
CREATE TYPE socialcandor_schema.breach_severity AS ENUM (
    'LOW',              -- Minimal impact, unlikely to risk rights
    'MEDIUM',           -- Some risk, may require notification
    'HIGH',             -- Significant risk, notification likely required
    'CRITICAL'          -- Severe risk, immediate action required
);
COMMENT ON TYPE socialcandor_schema.breach_severity IS 'Severity classification for data breaches';

-- Object: 122 - pia_status
-- Description: Status of a Privacy Impact Assessment (DPIA)
-- Business Case: Track DPIA workflow from initiation to approval
-- Feature Reference: GDPR03 (Privacy Impact Assessment)
--================================================================================================
CREATE TYPE socialcandor_schema.pia_status AS ENUM (
    'DRAFT',            -- Initial draft
    'SCREENING',        -- Initial screening to determine if DPIA needed
    'IN_PROGRESS',      -- Assessment underway
    'UNDER_REVIEW',     -- Submitted for review
    'APPROVED',         -- Formally approved
    'REJECTED',         -- Rejected, requires revision
    'OBSOLETE'          -- No longer applicable
);
COMMENT ON TYPE socialcandor_schema.pia_status IS 'Status of a Privacy Impact Assessment (DPIA)';

-- Object: 123 - agreement_type
-- Description: Types of data processing agreements
-- Business Case: Categorize agreements for compliance reporting
-- Feature Reference: GDPR04 (Data Processing Agreements)
--================================================================================================
CREATE TYPE socialcandor_schema.agreement_type AS ENUM (
    'DPA',              -- Data Processing Agreement
    'SCC',              -- Standard Contractual Clauses
    'BCR',              -- Binding Corporate Rules
    'JOINT_CONTROLLER', -- Joint controller agreement
    'ADEQUACY'          -- Adequacy decision basis
);
COMMENT ON TYPE socialcandor_schema.agreement_type IS 'Types of data processing agreements';

-- Object: 124 - retention_scope
-- Description: Scope of a data retention policy
-- Business Case: Define which data assets a policy applies to
-- Feature Reference: GDPR05 (Data Retention)
--================================================================================================
CREATE TYPE socialcandor_schema.retention_scope AS ENUM (
    'GLOBAL',           -- Applies to entire platform
    'DATA_CATEGORY',    -- Applies to a specific data category (PII, PHI, etc.)
    'TABLE',            -- Applies to a specific database table
    'COLUMN',           -- Applies to a specific column
    'PROCESS',          -- Applies to a specific processing activity
    'JURISDICTION'      -- Applies to users in a specific jurisdiction
);
COMMENT ON TYPE socialcandor_schema.retention_scope IS 'Scope of a data retention policy';

-- Object: 125 - anonymization_job_status
-- Description: Status of an anonymization/pseudonymization job
-- Business Case: Track job execution and completion
-- Feature Reference: PRV05 (Anonymization)
--================================================================================================
CREATE TYPE socialcandor_schema.anonymization_job_status AS ENUM (
    'PENDING',          -- Job created, not started
    'RUNNING',          -- Currently executing
    'COMPLETED',        -- Successfully finished
    'FAILED',           -- Failed, requires investigation
    'CANCELLED'         -- Manually cancelled
);
COMMENT ON TYPE socialcandor_schema.anonymization_job_status IS 'Status of an anonymization/pseudonymization job';

--================================================================================================
-- SEQUENCES (for human‑readable identifiers)
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.dsar_request_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.breach_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.pia_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.agreement_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.anonymization_job_seq START 1000;

--================================================================================================
-- TABLE: consent_records
-- Description: Stores user consent for data processing (marketing, cookies, third‑party sharing)
-- Business Case: Required by GDPR Article 7 – proof of consent, withdrawal tracking
-- KPIs: Consent rate, withdrawal rate, consent freshness
-- Feature Reference: GDPR06 (Consent Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.consent_records (
    -- Primary key
    consent_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User reference
    user_id UUID NOT NULL,

    -- Consent details (reusing existing consent_type enum)
    consent_type socialcandor_schema.consent_type NOT NULL,
    purpose VARCHAR(255),                     -- Optional specific purpose description

    -- Consent version (for policy versioning)
    policy_version VARCHAR(50),
    policy_url VARCHAR(500),

    -- Timestamps
    given_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_from TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    valid_until TIMESTAMP WITH TIME ZONE,     -- NULL = ongoing until withdrawn

    -- Consent metadata
    ip_address INET,
    user_agent TEXT,
    consent_method VARCHAR(50) CHECK (consent_method IN ('CHECKBOX', 'BUTTON', 'API', 'BULK_IMPORT')),

    -- Withdrawal tracking
    withdrawn_at TIMESTAMP WITH TIME ZONE,
    withdrawal_ip INET,
    withdrawal_reason TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_consent_records_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_consent_active UNIQUE (user_id, consent_type) WHERE withdrawn_at IS NULL
);

COMMENT ON TABLE socialcandor_schema.consent_records IS 'Stores user consent for data processing activities (GDPR Art. 7)';

--================================================================================================
-- TABLE: data_subject_requests
-- Description: Tracks DSAR (access, deletion, portability) requests and fulfillment progress
-- Business Case: Meet GDPR response deadlines (Art. 12-22); audit trail
-- KPIs: Request volume, average response time, SLA compliance rate
-- Feature Reference: GDPR01 (Data Subject Rights)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_subject_requests (
    -- Primary key
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    request_number VARCHAR(50) GENERATED ALWAYS AS (
        'DSAR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dsar_request_seq')::TEXT, 6, '0')
    ) STORED,

    -- Requester information
    user_id UUID,       -- NULL if request from non‑user (e.g., potential customer)
    requester_email VARCHAR(255) NOT NULL,
    requester_name VARCHAR(255),

    -- Request details
    request_type socialcandor_schema.dsar_request_type NOT NULL,
    request_details TEXT,
    supporting_documents JSONB DEFAULT '[]',      -- URLs of uploaded identity documents

    -- Verification
    identity_verified BOOLEAN DEFAULT FALSE,
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID,
    verification_method VARCHAR(100),

    -- Status
    status socialcandor_schema.dsar_status NOT NULL DEFAULT 'SUBMITTED',
    status_history JSONB DEFAULT '[]',            -- Audit trail of status changes

    -- Dates (for SLA tracking)
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    deadline_date DATE NOT NULL,                  -- 1 month default, extendable to 2 months
    extended_deadline_date DATE,                   -- If complexity requires extension
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Fulfillment details
    data_package_url VARCHAR(500),                 -- For access requests
    deletion_confirmation_sent BOOLEAN DEFAULT FALSE,
    portability_format VARCHAR(50) CHECK (portability_format IN ('JSON', 'CSV', 'XML')),

    -- Rejection reason (if status = 'REJECTED')
    rejection_reason TEXT,

    -- Internal notes
    internal_notes TEXT,
    assigned_to UUID,    -- Staff user handling the request

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_dsar_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_dsar_verified_by FOREIGN KEY (verified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_dsar_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.data_subject_requests IS 'Tracks DSAR requests and fulfillment progress (GDPR Art. 12-22)';

--================================================================================================
-- TABLE: data_breaches
-- Description: Logs security incidents and breach details for GDPR Article 33 compliance
-- Business Case: Mandatory breach register; enables timely notification to authorities and affected individuals
-- KPIs: Detection time, containment time, notification timeliness
-- Feature Reference: GDPR02 (Breach Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_breaches (
    -- Primary key
    breach_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    breach_number VARCHAR(50) GENERATED ALWAYS AS (
        'BR-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.breach_seq')::TEXT, 6, '0')
    ) STORED,

    -- Breach details
    breach_name VARCHAR(255),
    description TEXT NOT NULL,
    root_cause TEXT,
    breach_type socialcandor_schema.breach_type NOT NULL,   -- existing enum
    severity socialcandor_schema.breach_severity NOT NULL,

    -- Dates
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL,
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    contained_at TIMESTAMP WITH TIME ZONE,

    -- Affected data
    affected_data_categories TEXT[],                         -- e.g., ['PII', 'FINANCIAL']
    affected_records_count INTEGER CHECK (affected_records_count >= 0),
    affected_users_count INTEGER CHECK (affected_users_count >= 0),

    -- Affected subjects (can be large; kept as JSON summary)
    affected_subjects_summary JSONB,

    -- Risk assessment
    risk_to_rights TEXT,            -- Description of potential consequences
    likelihood_of_risk VARCHAR(20) CHECK (likelihood_of_risk IN ('LOW', 'MEDIUM', 'HIGH')),

    -- Notification status (reusing existing notification_status enum)
    supervisory_authority_notification socialcandor_schema.notification_status DEFAULT 'NOT_STARTED',
    supervisory_authority_notified_at TIMESTAMP WITH TIME ZONE,
    affected_users_notification socialcandor_schema.notification_status DEFAULT 'NOT_STARTED',
    affected_users_notified_at TIMESTAMP WITH TIME ZONE,

    -- Public communication
    public_disclosure_required BOOLEAN DEFAULT FALSE,
    public_disclosure_date DATE,
    public_statement_url VARCHAR(500),

    -- Remediation
    remediation_actions TEXT,
    remediation_completed_at TIMESTAMP WITH TIME ZONE,
    lessons_learned TEXT,

    -- Investigators / responsible parties
    reported_by UUID,
    investigated_by UUID[],

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_breaches_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.data_breaches IS 'Logs security incidents and breach details for GDPR Article 33 compliance';

--================================================================================================
-- TABLE: privacy_impact_assessments
-- Description: Records DPIAs for high‑risk processing activities
-- Business Case: Mandatory under GDPR Article 35; demonstrates accountability
-- KPIs: DPIA completion rate, risk identification, mitigation effectiveness
-- Feature Reference: GDPR03 (Privacy Impact Assessment)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.privacy_impact_assessments (
    -- Primary key
    pia_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    pia_number VARCHAR(50) GENERATED ALWAYS AS (
        'PIA-' || TO_CHAR(initiated_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.pia_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic information
    title VARCHAR(255) NOT NULL,
    description TEXT,

    -- Processing activity
    processing_activity VARCHAR(500) NOT NULL,
    processing_purpose TEXT,
    legal_basis VARCHAR(100),                     -- e.g., 'consent', 'contract', 'legal obligation'

    -- Data involved
    data_categories TEXT[],
    data_subjects TEXT[],                          -- e.g., ['customers', 'employees', 'website visitors']
    data_volume_estimate VARCHAR(100),

    -- Risk assessment (reusing existing risk_level enum)
    inherent_risk socialcandor_schema.risk_level NOT NULL,
    residual_risk socialcandor_schema.risk_level,
    risk_factors JSONB,   -- Detailed risk breakdown

    -- Mitigations
    mitigation_measures TEXT,
    safeguards_description TEXT,

    -- Consultation
    dpo_consulted BOOLEAN DEFAULT FALSE,
    dpo_opinion TEXT,
    supervisory_authority_consulted BOOLEAN DEFAULT FALSE,
    consultation_date DATE,
    consultation_response TEXT,

    -- Status (using custom pia_status)
    status socialcandor_schema.pia_status NOT NULL DEFAULT 'DRAFT',

    -- Dates
    initiated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    submitted_for_review_at TIMESTAMP WITH TIME ZONE,
    approved_at TIMESTAMP WITH TIME ZONE,
    review_date DATE,     -- Next scheduled review
    expiry_date DATE,     -- When assessment becomes obsolete

    -- Responsible parties
    owner_id UUID,        -- Who owns this processing activity
    reviewer_id UUID,     -- Who reviewed/approved the DPIA

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_pia_owner FOREIGN KEY (owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_pia_reviewer FOREIGN KEY (reviewer_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.privacy_impact_assessments IS 'Records DPIAs for high‑risk processing activities (GDPR Art. 35)';

--================================================================================================
-- TABLE: data_processing_agreements
-- Description: Manages third‑party data sharing agreements and transfer mechanisms
-- Business Case: Required for GDPR Chapter V (international transfers) and vendor compliance
-- KPIs: Agreement coverage, renewal rate, transfer mechanism compliance
-- Feature Reference: GDPR04 (Data Processing Agreements)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_processing_agreements (
    -- Primary key
    agreement_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    agreement_number VARCHAR(50) GENERATED ALWAYS AS (
        'DPA-' || TO_CHAR(effective_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.agreement_seq')::TEXT, 6, '0')
    ) STORED,

    -- Agreement type
    agreement_type socialcandor_schema.agreement_type NOT NULL,
    agreement_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Parties involved
    controller_id UUID,   -- Our organization (or link to organizations table)
    processor_name VARCHAR(255) NOT NULL,           -- Third‑party name
    processor_id UUID,    -- Optional link to vendor/organization table
    subprocessors TEXT[],  -- List of sub‑processors, if any

    -- Transfer details (reusing existing transfer_mechanism enum)
    transfer_mechanism socialcandor_schema.transfer_mechanism,
    transfer_countries VARCHAR(3)[],                 -- Destination countries

    -- Dates
    effective_date DATE NOT NULL,
    expiration_date DATE,
    renewal_date DATE,
    notice_period_days INTEGER CHECK (notice_period_days >= 0),

    -- Document storage
    agreement_document_url VARCHAR(500),
    signed_copy_url VARCHAR(500),

    -- Status (reusing existing transfer_status enum)
    status socialcandor_schema.transfer_status NOT NULL DEFAULT 'ACTIVE',

    -- Compliance flags
    gdpr_compliant BOOLEAN DEFAULT TRUE,
    safeguards_description TEXT,
    additional_measures TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    reviewed_at TIMESTAMP WITH TIME ZONE,
    reviewed_by UUID,

    -- Constraints
    CONSTRAINT fk_dpa_controller FOREIGN KEY (controller_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE SET NULL,
    CONSTRAINT fk_dpa_processor FOREIGN KEY (processor_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE SET NULL,
    CONSTRAINT fk_dpa_reviewed_by FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.data_processing_agreements IS 'Manages third‑party data sharing agreements and transfer mechanisms (GDPR Ch. V)';

--================================================================================================
-- TABLE: data_retention_policies
-- Description: Defines retention periods for different data categories, with automated enforcement rules
-- Business Case: GDPR Article 5(1)(e) – storage limitation; operational data lifecycle management
-- KPIs: Policy coverage, deletion compliance rate, storage savings
-- Feature Reference: GDPR05 (Data Retention)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_retention_policies (
    -- Primary key
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Policy identification
    policy_name VARCHAR(255) NOT NULL,
    policy_description TEXT,
    policy_version VARCHAR(50),

    -- Scope (using custom retention_scope enum)
    scope_type socialcandor_schema.retention_scope NOT NULL,
    scope_value VARCHAR(255),                       -- e.g., table name, data category, jurisdiction

    -- Retention rules
    retention_period_days INTEGER NOT NULL CHECK (retention_period_days >= 0),
    retention_unit VARCHAR(20) DEFAULT 'DAYS' CHECK (retention_unit IN ('DAYS', 'MONTHS', 'YEARS')),
    retention_basis VARCHAR(100),                    -- e.g., 'legal', 'contractual', 'operational'

    -- Action after expiry
    action_on_expiry VARCHAR(50) CHECK (action_on_expiry IN ('DELETE', 'ANONYMIZE', 'ARCHIVE', 'REVIEW')),
    archive_location VARCHAR(500),

    -- Legal basis
    legal_reference TEXT,  -- e.g., 'GDPR Art. 5', 'Tax law § 147'

    -- Exceptions
    exceptions JSONB DEFAULT '[]',                   -- Conditions where retention may differ

    -- Enforcement
    is_active BOOLEAN DEFAULT TRUE,
    enforced_by_system BOOLEAN DEFAULT TRUE,        -- Whether automated deletion is enabled

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE,

    -- Constraints
    CONSTRAINT uk_retention_policy_scope UNIQUE (scope_type, scope_value, policy_version)
);

COMMENT ON TABLE socialcandor_schema.data_retention_policies IS 'Defines retention periods for data categories (GDPR storage limitation)';

--================================================================================================
-- TABLE: data_minimization_rules
-- Description: Stores rules to enforce data minimization (collection limits, masking requirements)
-- Business Case: GDPR Article 5(1)(c) – data minimization; privacy by design
-- KPIs: Rule coverage, violation reduction, false positive rate
-- Feature Reference: PRV04 (Data Minimization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_minimization_rules (
    -- Primary key
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rule identification
    rule_name VARCHAR(255) NOT NULL,
    rule_description TEXT,

    -- Scope (reusing existing rule_scope and minimization_type enums)
    rule_scope socialcandor_schema.rule_scope NOT NULL,
    minimization_type socialcandor_schema.minimization_type NOT NULL,
    target_entity VARCHAR(255) NOT NULL,             -- e.g., table name, column name, process name

    -- Rule conditions
    conditions JSONB,       -- Optional conditions under which rule applies

    -- Enforcement (reusing existing enforcement_level enum)
    enforcement_level socialcandor_schema.enforcement_level NOT NULL DEFAULT 'WARNING',

    -- Exceptions
    exceptions JSONB DEFAULT '[]',

    -- Effectiveness
    is_active BOOLEAN DEFAULT TRUE,
    violation_count INTEGER DEFAULT 0 CHECK (violation_count >= 0),
    last_violation_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    last_reviewed_at TIMESTAMP WITH TIME ZONE,

    -- Constraints
    CONSTRAINT uk_minimization_rule UNIQUE (rule_scope, minimization_type, target_entity)
);

COMMENT ON TABLE socialcandor_schema.data_minimization_rules IS 'Stores rules to enforce data minimization (GDPR Art. 5(1)(c))';

--================================================================================================
-- TABLE: anonymization_jobs
-- Description: Tasks for anonymizing or pseudonymizing data, with execution logs and technique metadata
-- Business Case: GDPR compliance; enable safe use of data for analytics/testing
-- KPIs: Job success rate, data anonymized volume, re‑identification risk reduction
-- Feature Reference: PRV05 (Anonymization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.anonymization_jobs (
    -- Primary key
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'ANON-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.anonymization_job_seq')::TEXT, 6, '0')
    ) STORED,

    -- Job details
    job_name VARCHAR(255) NOT NULL,
    job_description TEXT,

    -- Target data
    target_schema VARCHAR(100),
    target_table VARCHAR(100),
    target_columns TEXT[], -- Columns to anonymize
    filter_condition TEXT,  -- Optional WHERE clause

    -- Technique (reusing existing anonymization_technique enum)
    technique socialcandor_schema.anonymization_technique NOT NULL,
    technique_params JSONB, -- Parameters for the technique (e.g., noise level)

    -- Schedule
    scheduled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Status (using custom anonymization_job_status)
    status socialcandor_schema.anonymization_job_status DEFAULT 'PENDING',

    -- Execution details
    rows_processed INTEGER DEFAULT 0 CHECK (rows_processed >= 0),
    error_details TEXT,
    logs TEXT,

    -- Output
    output_summary JSONB,

    -- Trigger (reusing existing execution_trigger enum)
    trigger_type socialcandor_schema.execution_trigger DEFAULT 'SCHEDULED',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT chk_anonymization_job_target CHECK (target_table IS NOT NULL OR target_columns IS NOT NULL)
);

COMMENT ON TABLE socialcandor_schema.anonymization_jobs IS 'Tasks for anonymizing or pseudonymizing data, with execution logs';

--================================================================================================
-- INDEXES
--================================================================================================

-- consent_records
CREATE INDEX IF NOT EXISTS idx_consent_records_user ON socialcandor_schema.consent_records(user_id);
CREATE INDEX IF NOT EXISTS idx_consent_records_type ON socialcandor_schema.consent_records(consent_type);
CREATE INDEX IF NOT EXISTS idx_consent_records_valid ON socialcandor_schema.consent_records(valid_from, valid_until);
CREATE INDEX IF NOT EXISTS idx_consent_records_withdrawn ON socialcandor_schema.consent_records(withdrawn_at) WHERE withdrawn_at IS NOT NULL;

-- data_subject_requests
CREATE INDEX IF NOT EXISTS idx_dsar_user ON socialcandor_schema.data_subject_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_dsar_status ON socialcandor_schema.data_subject_requests(status);
CREATE INDEX IF NOT EXISTS idx_dsar_deadline ON socialcandor_schema.data_subject_requests(deadline_date);
CREATE INDEX IF NOT EXISTS idx_dsar_type ON socialcandor_schema.data_subject_requests(request_type);
CREATE INDEX IF NOT EXISTS idx_dsar_assigned ON socialcandor_schema.data_subject_requests(assigned_to) WHERE assigned_to IS NOT NULL;

-- data_breaches
CREATE INDEX IF NOT EXISTS idx_data_breaches_detected ON socialcandor_schema.data_breaches(detected_at DESC);
CREATE INDEX IF NOT EXISTS idx_data_breaches_severity ON socialcandor_schema.data_breaches(severity);
CREATE INDEX IF NOT EXISTS idx_data_breaches_type ON socialcandor_schema.data_breaches(breach_type);
CREATE INDEX IF NOT EXISTS idx_data_breaches_notification ON socialcandor_schema.data_breaches(supervisory_authority_notification);

-- privacy_impact_assessments
CREATE INDEX IF NOT EXISTS idx_pia_status ON socialcandor_schema.privacy_impact_assessments(status);
CREATE INDEX IF NOT EXISTS idx_pia_owner ON socialcandor_schema.privacy_impact_assessments(owner_id);
CREATE INDEX IF NOT EXISTS idx_pia_review_date ON socialcandor_schema.privacy_impact_assessments(review_date) WHERE review_date IS NOT NULL;

-- data_processing_agreements
CREATE INDEX IF NOT EXISTS idx_dpa_processor ON socialcandor_schema.data_processing_agreements(processor_name);
CREATE INDEX IF NOT EXISTS idx_dpa_status ON socialcandor_schema.data_processing_agreements(status);
CREATE INDEX IF NOT EXISTS idx_dpa_effective ON socialcandor_schema.data_processing_agreements(effective_date);
CREATE INDEX IF NOT EXISTS idx_dpa_expiration ON socialcandor_schema.data_processing_agreements(expiration_date) WHERE expiration_date IS NOT NULL;

-- data_retention_policies
CREATE INDEX IF NOT EXISTS idx_retention_policies_scope ON socialcandor_schema.data_retention_policies(scope_type, scope_value);
CREATE INDEX IF NOT EXISTS idx_retention_policies_active ON socialcandor_schema.data_retention_policies(is_active) WHERE is_active = TRUE;

-- data_minimization_rules
CREATE INDEX IF NOT EXISTS idx_minimization_rules_scope ON socialcandor_schema.data_minimization_rules(rule_scope, target_entity);
CREATE INDEX IF NOT EXISTS idx_minimization_rules_active ON socialcandor_schema.data_minimization_rules(is_active) WHERE is_active = TRUE;

-- anonymization_jobs
CREATE INDEX IF NOT EXISTS idx_anon_jobs_status ON socialcandor_schema.anonymization_jobs(status);
CREATE INDEX IF NOT EXISTS idx_anon_jobs_scheduled ON socialcandor_schema.anonymization_jobs(scheduled_at) WHERE status = 'PENDING';

--================================================================================================
-- ROW LEVEL SECURITY POLICIES
--================================================================================================

-- Enable RLS on tables containing sensitive personal data
ALTER TABLE socialcandor_schema.consent_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_subject_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_breaches ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.privacy_impact_assessments ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_processing_agreements ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_retention_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_minimization_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.anonymization_jobs ENABLE ROW LEVEL SECURITY;

-- consent_records: user sees own; admin sees all
CREATE POLICY consent_records_self_policy ON socialcandor_schema.consent_records
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY consent_records_admin_policy ON socialcandor_schema.consent_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- data_subject_requests: user sees own; assigned staff and admin see relevant ones
CREATE POLICY dsar_self_policy ON socialcandor_schema.data_subject_requests
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY dsar_staff_policy ON socialcandor_schema.data_subject_requests
    FOR ALL USING (assigned_to = current_setting('app.current_user_id')::UUID);
CREATE POLICY dsar_admin_policy ON socialcandor_schema.data_subject_requests
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- data_breaches: only admin and security team can view
CREATE POLICY data_breaches_admin_policy ON socialcandor_schema.data_breaches
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
-- Optionally add a policy for security team role

-- privacy_impact_assessments: only admin and data protection team
CREATE POLICY pia_admin_policy ON socialcandor_schema.privacy_impact_assessments
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- data_processing_agreements: admin and procurement/legal team
CREATE POLICY dpa_admin_policy ON socialcandor_schema.data_processing_agreements
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- data_retention_policies: admin and data governance team
CREATE POLICY retention_policies_admin_policy ON socialcandor_schema.data_retention_policies
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- data_minimization_rules: admin and data governance team
CREATE POLICY minimization_rules_admin_policy ON socialcandor_schema.data_minimization_rules
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- anonymization_jobs: admin and data engineering team
CREATE POLICY anon_jobs_admin_policy ON socialcandor_schema.anonymization_jobs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

