--================================================================================================
-- ENUMS
--================================================================================================

-- Enum: DQE01 - data_quality_check_status
-- Description: Status of a data quality check execution
-- Business Case: Track the state of each data quality check run
-- Feature Reference: DQ01 (Data Quality Management)
--================================================================================================
CREATE TYPE socialcandor_schema.data_quality_check_status AS ENUM (
    'PENDING',      -- Check created, not yet run
    'RUNNING',      -- Currently executing
    'PASSED',       -- Check passed
    'FAILED',       -- Check failed
    'WARNING',      -- Check passed with warnings
    'ERROR',        -- Error during execution
    'CANCELLED'     -- Manually cancelled
);
COMMENT ON TYPE socialcandor_schema.data_quality_check_status IS 'Status of a data quality check execution';

-- Enum: DQE02 - certification_status
-- Description: Status of a data asset certification
-- Business Case: Indicate whether a dataset is certified for use
-- Feature Reference: DQ02 (Data Certification)
--================================================================================================
CREATE TYPE socialcandor_schema.certification_status AS ENUM (
    'DRAFT',                -- Certification in progress
    'CERTIFIED',            -- Fully certified
    'EXPIRED',              -- Certification expired
    'REVOKED',              -- Certification revoked
    'PENDING_REVIEW'        -- Awaiting review
);
COMMENT ON TYPE socialcandor_schema.certification_status IS 'Status of a data asset certification';

-- Enum: DQE03 - data_classification_level
-- Description: Sensitivity classification levels (aligns with existing data_classification enum)
-- Business Case: Standardize data sensitivity across the platform
-- Feature Reference: GOV01 (Data Governance)
--================================================================================================
-- (Reusing existing data_classification enum, so no new type needed)

-- Enum: DQE04 - lifecycle_stage
-- Description: Stages in data asset lifecycle
-- Business Case: Track data from creation to deletion
-- Feature Reference: LCM01 (Lifecycle Management)
--================================================================================================
CREATE TYPE socialcandor_schema.lifecycle_stage AS ENUM (
    'CREATED',          -- Asset created
    'ACTIVE',           -- In active use
    'ARCHIVED',         -- Moved to archive
    'DELETED',          -- Permanently deleted
    'PURGED'            -- Removed from all systems
);
COMMENT ON TYPE socialcandor_schema.lifecycle_stage IS 'Stages in data asset lifecycle';

-- Enum: DQE05 - archival_job_status
-- Description: Status of data archival jobs
-- Business Case: Track execution of automated archival tasks
-- Feature Reference: ARC01 (Archival)
--================================================================================================
CREATE TYPE socialcandor_schema.archival_job_status AS ENUM (
    'PENDING',
    'RUNNING',
    'COMPLETED',
    'FAILED',
    'CANCELLED'
);
COMMENT ON TYPE socialcandor_schema.archival_job_status IS 'Status of data archival jobs';

-- Enum: SIE01 - incident_priority
-- Description: Priority levels for system incidents
-- Business Case: Prioritize incident response based on impact
-- Feature Reference: SYS06 (Incident Management)
--================================================================================================
CREATE TYPE socialcandor_schema.incident_priority AS ENUM (
    'P1',   -- Critical
    'P2',   -- High
    'P3',   -- Medium
    'P4',   -- Low
    'P5'    -- Cosmetic
);
COMMENT ON TYPE socialcandor_schema.incident_priority IS 'Priority levels for system incidents';

-- Enum: SIE02 - incident_status
-- Description: Lifecycle status of an incident
-- Business Case: Track incident from detection to resolution
-- Feature Reference: SYS06 (Incident Management)
--================================================================================================
CREATE TYPE socialcandor_schema.incident_status AS ENUM (
    'DETECTED',
    'INVESTIGATING',
    'MITIGATING',
    'RESOLVED',
    'CLOSED',
    'FALSE_POSITIVE'
);
COMMENT ON TYPE socialcandor_schema.incident_status IS 'Lifecycle status of an incident';

-- Enum: SIE03 - sla_status
-- Description: Status of SLA compliance
-- Business Case: Monitor adherence to service level agreements
-- Feature Reference: SYS07 (SLA Management)
--================================================================================================
CREATE TYPE socialcandor_schema.sla_status AS ENUM (
    'COMPLIANT',
    'AT_RISK',
    'BREACHED',
    'NOT_APPLICABLE'
);
COMMENT ON TYPE socialcandor_schema.sla_status IS 'Status of SLA compliance';

-- Enum: SIE04 - experiment_status
-- Description: Status of an A/B test or experiment
-- Business Case: Manage experiment lifecycle from design to analysis
-- Feature Reference: EXP01 (Experimentation)
--================================================================================================
CREATE TYPE socialcandor_schema.experiment_status AS ENUM (
    'DRAFT',
    'RUNNING',
    'PAUSED',
    'COMPLETED',
    'ARCHIVED'
);
COMMENT ON TYPE socialcandor_schema.experiment_status IS 'Status of an A/B test or experiment';

-- Enum: SIE05 - workflow_status
-- Description: Status of a workflow instance
-- Business Case: Track progress of automated workflows
-- Feature Reference: WF01 (Workflow Engine)
--================================================================================================
CREATE TYPE socialcandor_schema.workflow_status AS ENUM (
    'PENDING',
    'RUNNING',
    'COMPLETED',
    'FAILED',
    'CANCELLED',
    'PAUSED'
);
COMMENT ON TYPE socialcandor_schema.workflow_status IS 'Status of a workflow instance';

-- Enum: AWE01 - conversion_funnel_type
-- Description: Types of conversion funnels
-- Business Case: Categorize funnels for different user journeys
-- Feature Reference: ANL06 (Conversion Funnels)
--================================================================================================
CREATE TYPE socialcandor_schema.conversion_funnel_type AS ENUM (
    'USER_ONBOARDING',
    'CONTENT_CREATION',
    'PURCHASE',
    'SUBSCRIPTION',
    'ENGAGEMENT'
);
COMMENT ON TYPE socialcandor_schema.conversion_funnel_type IS 'Types of conversion funnels';

