--================================================================================================
-- DATA QUALITY & GOVERNANCE TABLES
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: DQ01 - data_quality_checks_ingestion
-- Description: Defines data quality checks to be performed during data ingestion
-- Business Case: Ensures that incoming data meets quality standards before entering the system,
--                preventing bad data from polluting downstream processes. This table stores
--                the configuration of each check, including severity, thresholds, and actions.
-- KPIs:
--   1. Check pass rate
--   2. Average check execution time
--   3. Number of failed records prevented from ingestion
--   4. Check coverage percentage across data sources
--   5. Time to detect data quality issues
-- Feature Reference: DQ01 (Data Quality Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_checks_ingestion (
    check_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    check_name VARCHAR(255) NOT NULL,
    check_description TEXT,
    check_type VARCHAR(50) NOT NULL CHECK (check_type IN ('SCHEMA_VALIDATION', 'NULL_CHECK', 'UNIQUENESS', 'RANGE_CHECK', 'PATTERN_MATCH', 'REFERENTIAL_INTEGRITY', 'CUSTOM_SQL')),
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

    -- Target data
    source_system VARCHAR(100),
    source_table VARCHAR(100),
    source_column VARCHAR(100),

    -- Check logic
    check_expression TEXT,
    expected_value VARCHAR(500),
    threshold_warning NUMERIC(5,2) CHECK (threshold_warning >= 0 AND threshold_warning <= 100),
    threshold_failure NUMERIC(5,2) CHECK (threshold_failure >= 0 AND threshold_failure <= 100),

    -- Execution settings
    is_active BOOLEAN DEFAULT TRUE,
    run_on_ingestion BOOLEAN DEFAULT TRUE,
    run_frequency VARCHAR(20) CHECK (run_frequency IN ('REAL_TIME', 'HOURLY', 'DAILY', 'WEEKLY')),

    -- Owner
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.data_quality_checks_ingestion IS 'Defines data quality checks to be performed during data ingestion';

------------------------------------------------------------------------------------------------
-- Table: DQ02 - data_quality_rules
-- Description: Business rules for ongoing data quality monitoring (reused from earlier, but ensure exists)
-- Business Case: Maintains rules for continuous data quality assessment across all tables
-- Feature Reference: DQ01
-- Note: This table already exists in a previous script. We'll include IF NOT EXISTS to avoid duplication.
------------------------------------------------------------------------------------------------
-- (Assumed already created, but include IF NOT EXISTS for completeness)
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_rules (
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    rule_name VARCHAR(200) NOT NULL,
    rule_code VARCHAR(100) UNIQUE NOT NULL,
    rule_description TEXT,
    rule_category VARCHAR(50) CHECK (rule_category IN ('COMPLETENESS','ACCURACY','CONSISTENCY','TIMELINESS','VALIDITY','UNIQUENESS','INTEGRITY')),
    target_entity_type VARCHAR(50),
    target_schema VARCHAR(100),
    target_table_name VARCHAR(100),
    target_column_name VARCHAR(100),
    rule_type VARCHAR(50),
    rule_expression TEXT,
    severity_level VARCHAR(20) DEFAULT 'MEDIUM',
    enforcement_level VARCHAR(20) DEFAULT 'WARNING',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: DQ03 - data_quality_scorecard
-- Description: Aggregated scores and metrics for data quality across domains
-- Business Case: Provides a high-level view of data health to stakeholders; drives improvement initiatives
-- KPIs:
--   1. Overall data quality score (0-100)
--   2. Score trend over time
--   3. Percentage of datasets meeting quality targets
--   4. Number of critical issues
--   5. Time to remediation
-- Feature Reference: DQ02 (Data Quality Scorecard)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_scorecard (
    scorecard_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    scorecard_date DATE NOT NULL,
    domain VARCHAR(100) NOT NULL,           -- e.g., 'User Data', 'Content Data'
    overall_score NUMERIC(5,2) CHECK (overall_score >= 0 AND overall_score <= 100),
    completeness_score NUMERIC(5,2) CHECK (completeness_score >= 0 AND completeness_score <= 100),
    accuracy_score NUMERIC(5,2) CHECK (accuracy_score >= 0 AND accuracy_score <= 100),
    consistency_score NUMERIC(5,2) CHECK (consistency_score >= 0 AND consistency_score <= 100),
    timeliness_score NUMERIC(5,2) CHECK (timeliness_score >= 0 AND timeliness_score <= 100),

    -- Metrics
    total_datasets INTEGER CHECK (total_datasets >= 0),
    datasets_meeting_target INTEGER CHECK (datasets_meeting_target >= 0),
    critical_issues INTEGER DEFAULT 0 CHECK (critical_issues >= 0),
    high_issues INTEGER DEFAULT 0 CHECK (high_issues >= 0),
    medium_issues INTEGER DEFAULT 0 CHECK (medium_issues >= 0),
    low_issues INTEGER DEFAULT 0 CHECK (low_issues >= 0),

    -- Calculated automatically
    target_achievement_rate NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN total_datasets > 0 THEN (datasets_meeting_target * 100.0 / total_datasets) ELSE 0 END
    ) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT uk_scorecard_date_domain UNIQUE (scorecard_date, domain)
);
COMMENT ON TABLE socialcandor_schema.data_quality_scorecard IS 'Aggregated scores and metrics for data quality across domains';

------------------------------------------------------------------------------------------------
-- Table: DQ04 - data_quality_logs
-- Description: Detailed log of all data quality check executions
-- Business Case: Provides audit trail for data quality checks; enables root cause analysis
-- KPIs:
--   1. Check execution volume
--   2. Pass/fail ratio over time
--   3. Average execution time
--   4. Most frequently failing checks
--   5. Time to detect regression
-- Feature Reference: DQ03 (Data Quality Logging)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_logs (
    log_id BIGSERIAL PRIMARY KEY,

    check_id UUID,
    check_name VARCHAR(255),
    execution_time TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    status socialcandor_schema.data_quality_check_status NOT NULL,

    -- Results
    records_checked INTEGER CHECK (records_checked >= 0),
    records_passed INTEGER CHECK (records_passed >= 0),
    records_failed INTEGER CHECK (records_failed >= 0),
    error_message TEXT,
    details JSONB,

    -- Performance
    execution_duration_ms INTEGER CHECK (execution_duration_ms >= 0),

    -- Source context
    source_system VARCHAR(100),
    source_table VARCHAR(100),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_dq_logs_check FOREIGN KEY (check_id)
        REFERENCES socialcandor_schema.data_quality_checks_ingestion(check_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_quality_logs IS 'Detailed log of all data quality check executions';

------------------------------------------------------------------------------------------------
-- Table: DQ05 - data_quality_certification
-- Description: Certification records for data assets
-- Business Case: Formally certifies that a dataset meets quality standards, building trust with consumers
-- KPIs:
--   1. Number of certified assets
--   2. Certification coverage
--   3. Average time to certification
--   4. Certification expiry rate
--   5. Consumer satisfaction with certified data
-- Feature Reference: DQ04 (Data Certification)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_certification (
    certification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    asset_type VARCHAR(50) NOT NULL CHECK (asset_type IN ('TABLE', 'VIEW', 'DATASET', 'REPORT', 'DASHBOARD')),
    asset_id UUID NOT NULL,                         -- Could link to various tables, but simplified as generic UUID
    asset_name VARCHAR(255),

    certification_status socialcandor_schema.certification_status NOT NULL DEFAULT 'DRAFT',
    certification_level VARCHAR(20) CHECK (certification_level IN ('BRONZE', 'SILVER', 'GOLD', 'PLATINUM')),

    -- Criteria met
    criteria_met JSONB,

    -- Dates
    certified_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    renewed_at TIMESTAMP WITH TIME ZONE,

    -- Certifier
    certified_by UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_certification_certified_by FOREIGN KEY (certified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_quality_certification IS 'Certification records for data assets';

------------------------------------------------------------------------------------------------
-- Table: DQ06 - data_dictionary
-- Description: Technical metadata for database objects (tables, columns)
-- Business Case: Central repository of data definitions, improving discoverability and understanding
-- KPIs:
--   1. Dictionary coverage (percentage of tables documented)
--   2. Documentation freshness
--   3. User search success rate
--   4. Number of data stewards updating
--   5. Time to onboard new data assets
-- Feature Reference: GOV02 (Data Catalog)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_dictionary (
    entry_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    schema_name VARCHAR(100) NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    column_name VARCHAR(100),

    -- If column is NULL, this entry describes the table
    is_table_level BOOLEAN GENERATED ALWAYS AS (column_name IS NULL) STORED,

    -- Description
    description TEXT NOT NULL,
    business_definition TEXT,

    -- Technical details
    data_type VARCHAR(50),
    is_nullable BOOLEAN,
    is_primary_key BOOLEAN DEFAULT FALSE,
    is_foreign_key BOOLEAN DEFAULT FALSE,
    foreign_key_reference VARCHAR(255),

    -- Example values
    example_values TEXT[],

    -- Stewardship
    data_steward_id UUID,
    last_reviewed_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT uk_dictionary_schema_table_column UNIQUE (schema_name, table_name, column_name)
);
COMMENT ON TABLE socialcandor_schema.data_dictionary IS 'Technical metadata for database objects';

------------------------------------------------------------------------------------------------
-- Table: DQ07 - business_glossary
-- Description: Business terms and definitions
-- Business Case: Aligns business and technical teams with consistent terminology
-- KPIs:
--   1. Glossary coverage
--   2. Term usage in documentation
--   3. User satisfaction with definitions
--   4. Number of terms approved
--   5. Time to define new terms
-- Feature Reference: GOV03 (Business Glossary)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.business_glossary (
    term_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    term_name VARCHAR(255) NOT NULL UNIQUE,
    definition TEXT NOT NULL,
    abbreviation VARCHAR(50),
    synonyms TEXT[],
    category VARCHAR(100),
    data_type VARCHAR(50),
    allowed_values TEXT[],
    examples TEXT,

    -- Stewardship
    steward_id UUID,
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'UNDER_REVIEW', 'APPROVED', 'DEPRECATED')),

    -- Related terms
    parent_term_id UUID,
    related_term_ids UUID[],

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    CONSTRAINT fk_glossary_parent FOREIGN KEY (parent_term_id)
        REFERENCES socialcandor_schema.business_glossary(term_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.business_glossary IS 'Business terms and definitions';

------------------------------------------------------------------------------------------------
-- Table: DQ08 - data_classification
-- Description: Sensitivity classification of data assets
-- Business Case: Ensures proper handling of sensitive data; aligns with data_classification enum
-- KPIs:
--   1. Classification coverage
--   2. Accuracy of classification
--   3. Number of reclassifications
--   4. Compliance with regulations
--   5. Time to classify new assets
-- Feature Reference: GOV04 (Data Classification)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_classification (
    classification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    asset_type VARCHAR(50) NOT NULL CHECK (asset_type IN ('TABLE', 'COLUMN', 'DATASET', 'FILE')),
    asset_schema VARCHAR(100),
    asset_table VARCHAR(100),
    asset_column VARCHAR(100),

    classification_level socialcandor_schema.data_classification NOT NULL,  -- PUBLIC, INTERNAL, CONFIDENTIAL, RESTRICTED, SECRET, PII, PHI, FINANCIAL

    justification TEXT,
    classification_date DATE NOT NULL DEFAULT CURRENT_DATE,
    expires_at DATE, -- If temporary classification
    is_automated BOOLEAN DEFAULT FALSE,

    -- Approver
    classified_by UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT uk_classification_asset UNIQUE (asset_type, asset_schema, asset_table, asset_column)
);
COMMENT ON TABLE socialcandor_schema.data_classification IS 'Sensitivity classification of data assets';

------------------------------------------------------------------------------------------------
-- Table: DQ09 - data_classification_catalog
-- Description: Catalog of classification categories and their handling requirements
-- Business Case: Defines what each classification level means in terms of security controls
-- KPIs:
--   1. Catalog completeness
--   2. Alignment with regulatory frameworks
--   3. Usage in classification decisions
-- Feature Reference: GOV04 (Data Classification)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_classification_catalog (
    catalog_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    classification_level socialcandor_schema.data_classification NOT NULL UNIQUE,
    description TEXT NOT NULL,
    handling_requirements TEXT,
    encryption_required BOOLEAN DEFAULT FALSE,
    masking_required BOOLEAN DEFAULT FALSE,
    access_restrictions TEXT,
    retention_period_days INTEGER,
    regulatory_frameworks TEXT[],                -- e.g., {'GDPR','HIPAA','PCI-DSS'}

    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.data_classification_catalog IS 'Catalog of classification categories and their handling requirements';

------------------------------------------------------------------------------------------------
-- Table: DQ10 - data_ownership
-- Description: Defines owners and stewards for data assets
-- Business Case: Establishes accountability for data quality and governance
-- KPIs:
--   1. Owner assignment coverage
--   2. Steward responsiveness
--   3. Time to resolve data issues
--   4. Owner turnover rate
-- Feature Reference: GOV05 (Data Ownership)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_ownership (
    ownership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    asset_type VARCHAR(50) NOT NULL CHECK (asset_type IN ('TABLE', 'COLUMN', 'DATASET', 'DOMAIN')),
    asset_schema VARCHAR(100),
    asset_table VARCHAR(100),
    asset_column VARCHAR(100),

    owner_type VARCHAR(20) CHECK (owner_type IN ('USER', 'TEAM')),
    owner_id UUID NOT NULL,                      -- Can be user_id or team_id (if teams table exists)
    owner_role VARCHAR(50) CHECK (owner_role IN ('DATA_OWNER', 'DATA_STEWARD', 'TECHNICAL_STEWARD', 'BUSINESS_STEWARD')),

    valid_from DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.data_ownership IS 'Defines owners and stewards for data assets';

------------------------------------------------------------------------------------------------
-- Table: DQ11 - data_lifecycle_policies
-- Description: Policies governing the lifecycle of data assets (creation, retention, deletion)
-- Business Case: Ensures data is managed consistently throughout its life; supports compliance
-- KPIs:
--   1. Policy coverage
--   2. Adherence to retention periods
--   3. Number of policy violations
--   4. Time to implement policy changes
-- Feature Reference: LCM02 (Lifecycle Policies)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_lifecycle_policies (
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    policy_name VARCHAR(255) NOT NULL,
    description TEXT,
    asset_type VARCHAR(50) CHECK (asset_type IN ('TABLE', 'COLUMN', 'DATASET', 'DOMAIN', 'ALL')),

    -- Stages
    retention_period_days INTEGER CHECK (retention_period_days >= 0),
    archive_after_days INTEGER CHECK (archive_after_days >= 0),
    delete_after_days INTEGER CHECK (delete_after_days >= 0),

    -- Actions
    on_archive_action VARCHAR(100),
    on_delete_action VARCHAR(100),

    -- Exceptions
    can_override BOOLEAN DEFAULT FALSE,
    requires_approval_for_override BOOLEAN DEFAULT TRUE,

    is_active BOOLEAN DEFAULT TRUE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.data_lifecycle_policies IS 'Policies governing the lifecycle of data assets';

------------------------------------------------------------------------------------------------
-- Table: DQ12 - data_archival_jobs
-- Description: Tracks automated archival of data based on lifecycle policies
-- Business Case: Automates movement of old data to cheaper storage, reducing costs and improving performance
-- KPIs:
--   1. Archival success rate
--   2. Data volume archived
--   3. Storage cost savings
--   4. Time to complete archival
--   5. Number of archival failures
-- Feature Reference: ARC02 (Data Archival)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_archival_jobs (
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'ARC-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.archival_job_seq')::TEXT, 6, '0')
    ) STORED,

    policy_id UUID,
    target_schema VARCHAR(100),
    target_table VARCHAR(100),
    filter_condition TEXT,

    status socialcandor_schema.archival_job_status DEFAULT 'PENDING',

    scheduled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    rows_archived INTEGER DEFAULT 0,
    archive_location VARCHAR(500),
    error_details TEXT,

    triggered_by UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_archival_jobs_policy FOREIGN KEY (policy_id)
        REFERENCES socialcandor_schema.data_lifecycle_policies(policy_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_archival_jobs IS 'Tracks automated archival of data based on lifecycle policies';

------------------------------------------------------------------------------------------------
-- Table: DQ13 - data_deletion_audit
-- Description: Audit trail of all data deletions (for compliance and recovery)
-- Business Case: Required for GDPR right to erasure and internal audits
-- KPIs:
--   1. Deletion volume
--   2. Compliance with retention policies
--   3. Time to complete deletion requests
--   4. Number of unauthorized deletion attempts
-- Feature Reference: AUD07 (Deletion Audit)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_deletion_audit (
    deletion_id BIGSERIAL PRIMARY KEY,

    deletion_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_by UUID NOT NULL,
    deletion_reason VARCHAR(100) CHECK (deletion_reason IN ('RETENTION_EXPIRED', 'USER_REQUEST', 'DATA_CLEANUP', 'MANUAL', 'OTHER')),

    asset_type VARCHAR(50) NOT NULL,
    asset_identifier VARCHAR(500),                -- e.g., table name or record ID

    records_deleted INTEGER CHECK (records_deleted >= 0),
    deletion_method VARCHAR(50) CHECK (deletion_method IN ('SOFT_DELETE', 'HARD_DELETE', 'ANONYMIZE')),

    -- For audit trail
    before_snapshot JSONB,
    after_snapshot JSONB,

    ip_address INET,
    user_agent TEXT,

    CONSTRAINT fk_deletion_audit_user FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_deletion_audit IS 'Audit trail of all data deletions';

------------------------------------------------------------------------------------------------
-- Table: DQ14 - data_retention_exceptions
-- Description: Exceptions to standard retention policies (e.g., legal hold)
-- Business Case: Allows overriding normal retention for specific records under legal or business requirements
-- KPIs:
--   1. Number of active exceptions
--   2. Exception duration
--   3. Compliance with hold orders
-- Feature Reference: LCM03 (Retention Exceptions)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_retention_exceptions (
    exception_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    asset_type VARCHAR(50) NOT NULL,
    asset_identifier VARCHAR(500) NOT NULL,       -- e.g., user_id, post_id, etc.
    reason VARCHAR(100) NOT NULL CHECK (reason IN ('LEGAL_HOLD', 'REGULATORY', 'INVESTIGATION', 'DISPUTE', 'OTHER')),
    description TEXT,

    granted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,
    granted_by UUID NOT NULL,

    is_active BOOLEAN GENERATED ALWAYS AS (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP) STORED,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_exception_granted_by FOREIGN KEY (granted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_retention_exceptions IS 'Exceptions to standard retention policies (e.g., legal hold)';

------------------------------------------------------------------------------------------------
-- Table: DQ15 - data_profiling_results
-- Description: Results of data profiling activities (column statistics)
-- Business Case: Provides insights into data characteristics; helps identify anomalies and guide quality rules
-- KPIs:
--   1. Profiling coverage
--   2. Data distribution shifts
--   3. Number of anomalies detected
--   4. Time to profile new data
-- Feature Reference: DQ05 (Data Profiling)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_profiling_results (
    profile_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    profile_date DATE NOT NULL DEFAULT CURRENT_DATE,
    schema_name VARCHAR(100) NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    column_name VARCHAR(100) NOT NULL,

    row_count INTEGER CHECK (row_count >= 0),
    null_count INTEGER CHECK (null_count >= 0),
    distinct_count INTEGER CHECK (distinct_count >= 0),
    min_value VARCHAR(500),
    max_value VARCHAR(500),
    avg_value NUMERIC,
    stddev_value NUMERIC,

    data_type VARCHAR(50),
    min_length INTEGER CHECK (min_length >= 0),
    max_length INTEGER CHECK (max_length >= 0),
    frequent_values JSONB,                         -- Top N values with frequencies

    profiling_time_ms INTEGER CHECK (profiling_time_ms >= 0),
    profiled_by UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uk_profiling_result UNIQUE (profile_date, schema_name, table_name, column_name)
);
COMMENT ON TABLE socialcandor_schema.data_profiling_results IS 'Results of data profiling activities (column statistics)';

------------------------------------------------------------------------------------------------
-- Table: DQ16 - metadata_technical
-- Description: Technical metadata about data sources, schemas, ETL jobs, etc.
-- Business Case: Central repository for technical metadata to aid operations and impact analysis
-- KPIs:
--   1. Metadata completeness
--   2. Lineage coverage
--   3. Time to discover dependencies
-- Feature Reference: MDM01 (Technical Metadata)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.metadata_technical (
    metadata_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    source_system VARCHAR(100),
    object_type VARCHAR(50) CHECK (object_type IN ('TABLE', 'VIEW', 'COLUMN', 'INDEX', 'CONSTRAINT', 'JOB', 'PIPELINE')),
    object_name VARCHAR(255) NOT NULL,

    -- Technical attributes
    schema_name VARCHAR(100),
    data_type VARCHAR(50),
    created_ddl TEXT,
    last_ddl_time TIMESTAMP WITH TIME ZONE,

    -- Lineage (simplified)
    upstream_dependencies TEXT[],
    downstream_dependencies TEXT[],

    -- Additional attributes
    attributes JSONB,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.metadata_technical IS 'Technical metadata about data sources, schemas, ETL jobs, etc.';

------------------------------------------------------------------------------------------------
-- Table: DQ17 - metadata_business
-- Description: Business metadata linking technical assets to business concepts
-- Business Case: Helps business users find and understand data relevant to them
-- KPIs:
--   1. Business metadata coverage
--   2. User search effectiveness
--   3. Time to market for new reports
-- Feature Reference: MDM02 (Business Metadata)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.metadata_business (
    business_metadata_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    asset_type VARCHAR(50) NOT NULL,
    asset_id UUID NOT NULL,                         -- Could link to various tables
    asset_name VARCHAR(255),

    business_term_id UUID, -- Link to business_glossary
    business_description TEXT,
    business_owner_id UUID,
    business_priority VARCHAR(20) CHECK (business_priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    data_sensitivity VARCHAR(50),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_business_metadata_term FOREIGN KEY (business_term_id)
        REFERENCES socialcandor_schema.business_glossary(term_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.metadata_business IS 'Business metadata linking technical assets to business concepts';

------------------------------------------------------------------------------------------------
-- Table: DQ18 - metadata_operational
-- Description: Operational metadata about data processing runs (pipelines, jobs)
-- Business Case: Monitor and troubleshoot data pipelines
-- KPIs:
--   1. Pipeline success rate
--   2. Average execution time
--   3. Data freshness
--   4. Error frequency
-- Feature Reference: OPS02 (Operational Metadata)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.metadata_operational (
    op_metadata_id BIGSERIAL PRIMARY KEY,

    pipeline_id UUID,
    job_name VARCHAR(255),
    execution_id UUID,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE,
    status VARCHAR(20) CHECK (status IN ('STARTED', 'RUNNING', 'COMPLETED', 'FAILED', 'ABORTED')),

    records_processed INTEGER CHECK (records_processed >= 0),
    records_inserted INTEGER CHECK (records_inserted >= 0),
    records_updated INTEGER CHECK (records_updated >= 0),
    records_deleted INTEGER CHECK (records_deleted >= 0),

    error_message TEXT,
    log_summary TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE socialcandor_schema.metadata_operational IS 'Operational metadata about data processing runs';

------------------------------------------------------------------------------------------------
-- Table: DQ19 - ingestion_pipelines
-- Description: Configuration of data ingestion pipelines
-- Business Case: Manage and monitor data ingestion from various sources
-- KPIs:
--   1. Ingestion success rate
--   2. Data latency
--   3. Number of active pipelines
--   4. Pipeline failure rate
-- Feature Reference: ING01 (Data Ingestion)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.ingestion_pipelines (
    pipeline_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    pipeline_number VARCHAR(50) GENERATED ALWAYS AS (
        'ING-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ingestion_pipeline_seq')::TEXT, 6, '0')
    ) STORED,

    pipeline_name VARCHAR(255) NOT NULL,
    description TEXT,

    source_type VARCHAR(50) CHECK (source_type IN ('DATABASE', 'API', 'FILE', 'STREAM', 'MESSAGE_QUEUE')),
    source_config JSONB NOT NULL,

    destination_type VARCHAR(50) CHECK (destination_type IN ('DATABASE', 'DATA_LAKE', 'WAREHOUSE')),
    destination_config JSONB NOT NULL,

    schedule_type VARCHAR(20) CHECK (schedule_type IN ('REAL_TIME', 'BATCH', 'ON_DEMAND')),
    schedule_expression VARCHAR(100),

    transformation_logic TEXT,

    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    owner_team VARCHAR(100),
    owner_user_id UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.ingestion_pipelines IS 'Configuration of data ingestion pipelines';

------------------------------------------------------------------------------------------------
-- Table: DQ20 - pipeline_executions
-- Description: Execution history of ingestion pipelines
-- Business Case: Monitor pipeline runs, detect failures, measure performance
-- KPIs:
--   1. Execution success rate
--   2. Average execution time
--   3. Data volume processed
--   4. Error rate
-- Feature Reference: ING02 (Pipeline Monitoring)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.pipeline_executions (
    execution_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    pipeline_id UUID NOT NULL,
    execution_start TIMESTAMP WITH TIME ZONE NOT NULL,
    execution_end TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.execution_status NOT NULL,  -- Using existing enum

    records_read INTEGER CHECK (records_read >= 0),
    records_written INTEGER CHECK (records_written >= 0),
    bytes_processed BIGINT CHECK (bytes_processed >= 0),

    error_message TEXT,
    retry_count INTEGER DEFAULT 0,

    triggered_by UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_pipeline_executions_pipeline FOREIGN KEY (pipeline_id)
        REFERENCES socialcandor_schema.ingestion_pipelines(pipeline_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.pipeline_executions IS 'Execution history of ingestion pipelines';

--================================================================================================
-- SYSTEM, INFRASTRUCTURE & SECURITY TABLES
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: SYS01 - system_countries
-- Description: Reference data for countries (ISO codes, names, regions)
-- Business Case: Standardize country information across the platform; used in many features
-- KPIs:
--   1. Data accuracy
--   2. Coverage (all UN member states)
-- Feature Reference: SYS01 (System Configuration)
-- Note: This table already exists in previous batches; including IF NOT EXISTS.
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_countries (
    country_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    country_code CHAR(3) NOT NULL UNIQUE,
    country_code_alpha2 CHAR(2) UNIQUE,
    country_name VARCHAR(100) NOT NULL,
    official_name VARCHAR(255),
    region VARCHAR(50),
    subregion VARCHAR(50),
    continent VARCHAR(50),
    calling_code VARCHAR(20),
    currency_code CHAR(3),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: SYS02 - system_languages
-- Description: Reference data for languages
-- Business Case: Support multilingual content and UI
-- Feature Reference: SYS01
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_languages (
    language_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    language_code CHAR(10) NOT NULL UNIQUE,
    language_name VARCHAR(100) NOT NULL,
    native_name VARCHAR(100),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: SYS03 - system_settings
-- Description: Central configuration for the platform
-- Business Case: Manage system-wide settings without code changes
-- Feature Reference: SYS03
-- (Already created earlier; include IF NOT EXISTS)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.system_settings (
    setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    setting_key VARCHAR(255) NOT NULL UNIQUE,
    setting_value TEXT,
    data_type VARCHAR(20),
    description TEXT,
    is_encrypted BOOLEAN DEFAULT FALSE,
    category VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: SYS04 - feature_flags
-- Description: Feature toggles for controlled rollouts
-- Business Case: Enable gradual feature releases and A/B testing
-- Feature Reference: EXP01
-- (Already created earlier; include IF NOT EXISTS)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_flags (
    flag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    flag_key VARCHAR(100) UNIQUE NOT NULL,
    flag_name VARCHAR(200) NOT NULL,
    description TEXT,
    enabled BOOLEAN DEFAULT FALSE,
    rollout_percentage INTEGER CHECK (rollout_percentage BETWEEN 0 AND 100),
    environment VARCHAR(20) CHECK (environment IN ('DEV','STAGING','PRODUCTION')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: SYS05 - incident_management
-- Description: Tracks system incidents and their resolution
-- Business Case: Ensure timely response to outages and issues; post-mortem analysis
-- KPIs:
--   1. Mean time to detect (MTTD)
--   2. Mean time to resolve (MTTR)
--   3. Incident frequency
--   4. SLA compliance rate
--   5. Number of recurring incidents
-- Feature Reference: SYS06 (Incident Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.incident_management (
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'INC-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.incident_seq')::TEXT, 6, '0')
    ) STORED,

    title VARCHAR(255) NOT NULL,
    description TEXT,
    severity socialcandor_schema.incident_priority NOT NULL,
    status socialcandor_schema.incident_status NOT NULL DEFAULT 'DETECTED',

    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    mitigated_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,

    root_cause TEXT,
    resolution_notes TEXT,
    action_items JSONB,

    affected_services TEXT[],
    impacted_users_count INTEGER CHECK (impacted_users_count >= 0),

    reported_by UUID,
    assigned_to UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_incident_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_incident_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.incident_management IS 'Tracks system incidents and their resolution';

------------------------------------------------------------------------------------------------
-- Table: SYS06 - sla_definitions
-- Description: Defines Service Level Agreements for various services
-- Business Case: Set clear expectations for system performance and availability
-- KPIs:
--   1. Number of SLAs defined
--   2. SLA attainment rate
--   3. Time to breach
-- Feature Reference: SYS07 (SLA Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.sla_definitions (
    sla_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    sla_name VARCHAR(255) NOT NULL,
    description TEXT,
    service_name VARCHAR(100) NOT NULL,
    metric_name VARCHAR(100) NOT NULL,          -- e.g., 'uptime', 'response_time'

    target_value NUMERIC NOT NULL,
    target_unit VARCHAR(20) CHECK (target_unit IN ('PERCENT', 'MILLISECONDS', 'SECONDS', 'MINUTES', 'HOURS', 'DAYS')),
    comparison_operator VARCHAR(10) CHECK (comparison_operator IN ('>', '<', '>=', '<=', '=')),

    measurement_window VARCHAR(20) CHECK (measurement_window IN ('HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY')),

    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    owner_team VARCHAR(100),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.sla_definitions IS 'Defines Service Level Agreements for various services';

------------------------------------------------------------------------------------------------
-- Table: SYS07 - sla_compliance_tracking
-- Description: Tracks compliance with SLAs over time
-- Business Case: Monitor performance against targets; generate reports
-- KPIs:
--   1. SLA compliance percentage
--   2. Number of breaches
--   3. Trend over time
-- Feature Reference: SYS07
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.sla_compliance_tracking (
    tracking_id BIGSERIAL PRIMARY KEY,

    sla_id UUID NOT NULL,
    measurement_date DATE NOT NULL,
    measurement_value NUMERIC NOT NULL,
    status socialcandor_schema.sla_status NOT NULL,

    breach_time TIMESTAMP WITH TIME ZONE,        -- When breach first occurred
    breach_duration_minutes INTEGER CHECK (breach_duration_minutes >= 0),

    notes TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_sla_tracking_sla FOREIGN KEY (sla_id)
        REFERENCES socialcandor_schema.sla_definitions(sla_id) ON DELETE CASCADE,
    CONSTRAINT uk_sla_measurement UNIQUE (sla_id, measurement_date)
);
COMMENT ON TABLE socialcandor_schema.sla_compliance_tracking IS 'Tracks compliance with SLAs over time';

------------------------------------------------------------------------------------------------
-- Table: SYS08 - api_rate_limits
-- Description: Defines rate limits for API endpoints per user/client
-- Business Case: Protect API resources; ensure fair usage
-- KPIs:
--   1. Rate limit violations
--   2. Average API usage per client
-- Feature Reference: API04 (Rate Limiting)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_rate_limits (
    limit_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    endpoint_pattern VARCHAR(500) NOT NULL,      -- e.g., '/api/v1/posts/*'
    http_method VARCHAR(10) CHECK (http_method IN ('GET','POST','PUT','DELETE','PATCH','ALL')),

    -- Scope (user, client, IP, or global)
    scope_type VARCHAR(20) CHECK (scope_type IN ('USER', 'CLIENT', 'IP', 'GLOBAL')),
    scope_id UUID,       -- user_id, client_id, or NULL for global

    requests_per_second INTEGER CHECK (requests_per_second >= 0),
    requests_per_minute INTEGER CHECK (requests_per_minute >= 0),
    requests_per_hour INTEGER CHECK (requests_per_hour >= 0),
    requests_per_day INTEGER CHECK (requests_per_day >= 0),

    is_active BOOLEAN DEFAULT TRUE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.api_rate_limits IS 'Defines rate limits for API endpoints per user/client';

------------------------------------------------------------------------------------------------
-- Table: SYS09 - api_usage_billing
-- Description: Tracks API usage for billing purposes (for paid tiers)
-- Business Case: Enable metered billing for API access
-- KPIs:
--   1. API call volume by client
--   2. Billable events
--   3. Revenue per API
-- Feature Reference: API05 (API Billing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_usage_billing (
    billing_id BIGSERIAL PRIMARY KEY,

    client_id UUID NOT NULL,
    user_id UUID,
    api_endpoint VARCHAR(500),
    call_count INTEGER NOT NULL CHECK (call_count >= 0),
    billing_period_start DATE NOT NULL,
    billing_period_end DATE NOT NULL,
    tier VARCHAR(50),
    rate_per_call NUMERIC(10,6),
    total_charge NUMERIC(15,2),

    invoice_id UUID,     -- Link to invoice when generated

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_api_billing_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_api_billing_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.api_usage_billing IS 'Tracks API usage for billing purposes';

------------------------------------------------------------------------------------------------
-- Table: SYS10 - audit_logs
-- Description: Central audit log for critical actions
-- Business Case: Compliance and security investigations
-- Feature Reference: AUD06 (Audit Logging)
-- (Already created earlier; include IF NOT EXISTS with minimal structure)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.audit_logs (
    audit_id BIGSERIAL PRIMARY KEY,
    actor_user_id UUID,
    action VARCHAR(100) NOT NULL,
    target_type VARCHAR(50),
    target_id UUID,
    before_state JSONB,
    after_state JSONB,
    ip_address INET,
    user_agent TEXT,
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
) PARTITION BY RANGE (occurred_at);

------------------------------------------------------------------------------------------------
-- Table: SYS11 - audit_trail_extended
