------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.audit_trail_extended (
    extended_id BIGSERIAL PRIMARY KEY,

    audit_id BIGINT,       -- Link to core audit_logs

    session_id UUID,
    request_id UUID,       -- For tracing across services
    trace_id VARCHAR(100),

    additional_context JSONB,
    data_hashes JSONB,     -- Hashes of sensitive fields for integrity

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_extended_audit FOREIGN KEY (audit_id)
        REFERENCES socialcandor_schema.audit_logs(audit_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.audit_trail_extended IS 'Extended audit trail with more detailed context';

------------------------------------------------------------------------------------------------
-- Table: SYS12 - disaster_recovery_plan
-- Description: Stores disaster recovery plans and test results
-- Business Case: Ensure business continuity; comply with regulations
-- KPIs:
--   1. RTO (Recovery Time Objective) achievement
--   2. RPO (Recovery Point Objective) achievement
--   3. Number of DR tests passed
-- Feature Reference: BCP01 (Business Continuity)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.disaster_recovery_plan (
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    plan_name VARCHAR(255) NOT NULL,
    plan_version VARCHAR(20) NOT NULL,
    description TEXT,
    scope TEXT,

    rto_minutes INTEGER CHECK (rto_minutes >= 0),    -- Recovery Time Objective
    rpo_minutes INTEGER CHECK (rpo_minutes >= 0),    -- Recovery Point Objective

    documentation_url VARCHAR(500),
    approval_date DATE,
    approved_by UUID,

    last_test_date DATE,
    last_test_result VARCHAR(20) CHECK (last_test_result IN ('PASS','FAIL','PARTIAL')),
    next_test_date DATE,

    is_active BOOLEAN DEFAULT TRUE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.disaster_recovery_plan IS 'Stores disaster recovery plans and test results';

------------------------------------------------------------------------------------------------
-- Table: SYS13 - business_continuity_plan
-- Description: Business continuity plans for various scenarios
-- Business Case: Prepare for disruptions; maintain operations
-- KPIs:
--   1. Plan coverage
--   2. Employee awareness
--   3. Time to activate plan
-- Feature Reference: BCP02
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.business_continuity_plan (
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    plan_name VARCHAR(255) NOT NULL,
    scenario VARCHAR(100) CHECK (scenario IN ('NATURAL_DISASTER','POWER_OUTAGE','CYBER_ATTACK','PANDEMIC','OTHER')),
    description TEXT,

    activation_procedure TEXT,
    communication_plan TEXT,
    recovery_steps TEXT[],
    responsible_team VARCHAR(100),

    last_review_date DATE,
    next_review_date DATE,
    is_active BOOLEAN DEFAULT TRUE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.business_continuity_plan IS 'Business continuity plans for various scenarios';

------------------------------------------------------------------------------------------------
-- Table: SYS14 - penetration_test_results
-- Description: Stores results of security penetration tests
-- Business Case: Track security vulnerabilities and remediation
-- KPIs:
--   1. Number of critical findings
--   2. Time to remediate
--   3. Recurring vulnerabilities
-- Feature Reference: SEC12 (Security Testing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.penetration_test_results (
    test_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    test_name VARCHAR(255) NOT NULL,
    test_date DATE NOT NULL,
    tester VARCHAR(255),
    methodology VARCHAR(100),

    findings JSONB,       -- List of findings with severity, description, etc.
    critical_findings INTEGER DEFAULT 0,
    high_findings INTEGER DEFAULT 0,
    medium_findings INTEGER DEFAULT 0,
    low_findings INTEGER DEFAULT 0,

    remediation_plan TEXT,
    remediation_deadline DATE,
    remediation_status VARCHAR(20) CHECK (remediation_status IN ('OPEN','IN_PROGRESS','COMPLETED','ACCEPTED_RISK')),

    report_url VARCHAR(500),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.penetration_test_results IS 'Stores results of security penetration tests';

------------------------------------------------------------------------------------------------
-- Table: SYS15 - roles
-- Description: Role definitions for RBAC
-- Business Case: Manage user permissions
-- (Already created; include IF NOT EXISTS with basic structure)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.roles (
    role_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    role_name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    is_system BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);

------------------------------------------------------------------------------------------------
-- Table: SYS16 - role_hierarchies
-- Description: Defines parent-child relationships between roles (inheritance)
-- Business Case: Enable role hierarchies where higher roles inherit permissions
-- KPIs:
--   1. Hierarchy complexity
--   2. Number of inherited permissions
-- Feature Reference: RBAC04 (Role Hierarchy)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.role_hierarchies (
    hierarchy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    parent_role_id UUID NOT NULL,
    child_role_id UUID NOT NULL,

    inheritance_depth INTEGER GENERATED ALWAYS AS (
        WITH RECURSIVE cte AS (
            SELECT parent_role_id, child_role_id, 1 AS depth
            FROM socialcandor_schema.role_hierarchies
            WHERE parent_role_id = role_hierarchies.parent_role_id AND child_role_id = role_hierarchies.child_role_id
            UNION ALL
            SELECT rh.parent_role_id, rh.child_role_id, cte.depth + 1
            FROM socialcandor_schema.role_hierarchies rh
            JOIN cte ON rh.parent_role_id = cte.child_role_id
        ) SELECT MAX(depth) FROM cte
    ) STORED,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_role_hierarchy_parent FOREIGN KEY (parent_role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE CASCADE,
    CONSTRAINT fk_role_hierarchy_child FOREIGN KEY (child_role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE CASCADE,
    CONSTRAINT uk_role_hierarchy UNIQUE (parent_role_id, child_role_id),
    CONSTRAINT chk_no_self_reference CHECK (parent_role_id != child_role_id)
);
COMMENT ON TABLE socialcandor_schema.role_hierarchies IS 'Defines parent-child relationships between roles (inheritance)';

------------------------------------------------------------------------------------------------
-- Table: SYS17 - system_health_logs
-- Description: Periodic health metrics of system components
-- Business Case: Proactive monitoring; detect anomalies early
-- KPIs:
