------------------------------------------------------------------------------------------------
-- Table: SYS19 - support_ticketing
-- Description: Customer support tickets (different from user_feedback_tickets, more formal)
-- Business Case: Manage customer support requests with SLAs
-- KPIs:
--   1. Ticket volume
--   2. First response time
--   3. Resolution time
--   4. Customer satisfaction score
-- Feature Reference: SUP02 (Support Tickets)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_ticketing (
    ticket_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    ticket_number VARCHAR(50) GENERATED ALWAYS AS (
        'SUP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    user_id UUID NOT NULL,
    subject VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(50) CHECK (category IN ('TECHNICAL','BILLING','ACCOUNT','GENERAL','FEATURE_REQUEST')),
    priority socialcandor_schema.incident_priority DEFAULT 'P3',
    status socialcandor_schema.ticket_status DEFAULT 'OPEN',  -- reuse existing enum

    assigned_to UUID,
    sla_due_at TIMESTAMP WITH TIME ZONE,

    resolution_notes TEXT,
    resolved_at TIMESTAMP WITH TIME ZONE,

    satisfaction_score INTEGER CHECK (satisfaction_score BETWEEN 1 AND 5),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_support_ticket_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_support_ticket_assigned FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.support_ticketing IS 'Customer support tickets';

------------------------------------------------------------------------------------------------
-- Table: SYS20 - roadmap_visibility
