    title VARCHAR(255) NOT NULL,
    description TEXT,
    category VARCHAR(50) CHECK (category IN ('FEATURE','IMPROVEMENT','BUG_FIX','INFRASTRUCTURE')),
    status VARCHAR(30) CHECK (status IN ('IDEA','PLANNED','IN_PROGRESS','COMPLETED','CANCELLED')),

    target_release VARCHAR(100),
    release_date DATE,

    visibility VARCHAR(20) CHECK (visibility IN ('PUBLIC','INTERNAL','STAKEHOLDER_ONLY')),

    owner_id UUID,

    upvotes INTEGER DEFAULT 0,
    comments INTEGER DEFAULT 0,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
