    start_date TIMESTAMP WITH TIME ZONE,
    end_date TIMESTAMP WITH TIME ZONE,

    target_audience JSONB,                         -- Segmentation criteria
    variants JSONB NOT NULL,                        -- Array of variant definitions

    primary_metric VARCHAR(100),
    secondary_metrics TEXT[],

    results JSONB,        -- Summary of results

    owner_id UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.experiment_catalog IS 'Catalog of A/B tests and experiments';

------------------------------------------------------------------------------------------------
-- Table: SYS22 - experiment_assignments
-- Description: Records which user/session was assigned to which experiment variant
-- Business Case: Track exposure and ensure consistent assignment
-- KPIs:
--   1. Sample size per variant
--   2. Exposure count
-- Feature Reference: EXP03
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.experiment_assignments (
    assignment_id BIGSERIAL PRIMARY KEY,

    experiment_id UUID NOT NULL,
    user_id UUID,
    session_id UUID,
    variant_name VARCHAR(100) NOT NULL,
    assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Ensure either user_id or session_id is present
    CONSTRAINT chk_experiment_subject CHECK (user_id IS NOT NULL OR session_id IS NOT NULL),
    CONSTRAINT fk_experiment_assignments_exp FOREIGN KEY (experiment_id)
        REFERENCES socialcandor_schema.experiment_catalog(experiment_id) ON DELETE CASCADE,
    CONSTRAINT fk_experiment_assignments_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.experiment_assignments IS 'Records user/session assignment to experiment variants';

------------------------------------------------------------------------------------------------
-- Table: SYS23 - workflow_definitions
-- Description: Defines workflows (states, transitions, actions)
