-- KPIs:
--   1. Number of defined workflows
--   2. Workflow usage
-- Feature Reference: WF02 (Workflow Engine)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.workflow_definitions (
    workflow_def_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    name VARCHAR(255) NOT NULL,
    description TEXT,
    entity_type VARCHAR(50) NOT NULL,               -- e.g., 'POST', 'COMMENT', 'USER'

    states JSONB NOT NULL, -- Array of state definitions
    transitions JSONB NOT NULL,                       -- Array of transition rules

    initial_state VARCHAR(100) NOT NULL,

    version INTEGER DEFAULT 1,
    is_active BOOLEAN DEFAULT TRUE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
