------------------------------------------------------------------------------------------------
-- Table: SYS24 - workflow_instances
-- Description: Tracks instances of workflows for specific entities
-- Business Case: Monitor progress of each entity through a workflow
-- KPIs:
--   1. Average time in each state
--   2. Workflow completion rate
-- Feature Reference: WF03
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.workflow_instances (
    instance_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    workflow_def_id UUID NOT NULL,
    entity_id UUID NOT NULL,
    current_state VARCHAR(100) NOT NULL,

    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.workflow_status DEFAULT 'RUNNING',

    context JSONB,         -- Additional data for the workflow

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_workflow_instances_def FOREIGN KEY (workflow_def_id)
        REFERENCES socialcandor_schema.workflow_definitions(workflow_def_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.workflow_instances IS 'Tracks instances of workflows for specific entities';

------------------------------------------------------------------------------------------------
-- Table: SYS25 - data_consumer_feedback
