);
COMMENT ON TABLE socialcandor_schema.data_consumer_feedback IS 'Feedback from data consumers on data quality and usability';

--================================================================================================
-- ANALYTICS & DATA WAREHOUSE TABLES
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: DW01 - dim_users
-- Description: User dimension for analytics (denormalized copy of user attributes)
-- Business Case: Provide a stable, slowly changing dimension for user analysis
-- KPIs:
--   1. User count trends
--   2. User attribute completeness
-- Feature Reference: DWH01 (Data Warehouse)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.dim_users (
    user_key BIGSERIAL PRIMARY KEY,                -- Surrogate key

    user_id UUID NOT NULL,                          -- Natural key from source

    -- Attributes (denormalized)
    username VARCHAR(50),
    email VARCHAR(255),
    display_name VARCHAR(100),
    registration_date DATE,
    registration_country VARCHAR(3),
    user_status VARCHAR(30),
    verification_level VARCHAR(20),
    trust_score NUMERIC(5,2),

    -- Slowly changing dimension tracking
    effective_date DATE NOT NULL DEFAULT CURRENT_DATE,
    end_date DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (end_date IS NULL) STORED,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE socialcandor_schema.dim_users IS 'User dimension for analytics (denormalized copy)';

------------------------------------------------------------------------------------------------
-- Table: DW02 - dim_content
