-- Business Case: Enable time-series analysis with standard attributes
-- KPIs: N/A (supporting table)
-- Feature Reference: DWH03
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.dim_time (
    date_key INTEGER PRIMARY KEY,                   -- Format: YYYYMMDD
    full_date DATE NOT NULL UNIQUE,
    year INTEGER NOT NULL,
