    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE socialcandor_schema.dim_time IS 'Time dimension for date-based analysis';

------------------------------------------------------------------------------------------------
-- Table: DW04 - dim_geography
-- Description: Geography dimension for location-based analysis
