    country_code CHAR(3) NOT NULL,
    country_name VARCHAR(100) NOT NULL,
    region VARCHAR(50),
    subregion VARCHAR(50),
    continent VARCHAR(50),

    -- Additional attributes
    population BIGINT,
    timezone VARCHAR(50),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uk_dim_geography_country UNIQUE (country_code)
);
COMMENT ON TABLE socialcandor_schema.dim_geography IS 'Geography dimension for location-based analysis';

------------------------------------------------------------------------------------------------
-- Table: DW05 - fact_user_engagement
-- Description: Fact table for user engagement events
-- Business Case: Measure user activity and engagement over time
-- KPIs:
--   1. Daily active users (DAU)
--   2. Monthly active users (MAU)
--   3. Session duration
--   4. Actions per user
