    CONSTRAINT fk_fact_engagement_date FOREIGN KEY (date_key)
        REFERENCES socialcandor_schema.dim_time(date_key),
    CONSTRAINT fk_fact_engagement_user FOREIGN KEY (user_key)
        REFERENCES socialcandor_schema.dim_users(user_key),
    CONSTRAINT fk_fact_engagement_geo FOREIGN KEY (geo_key)
        REFERENCES socialcandor_schema.dim_geography(geo_key)
);
COMMENT ON TABLE socialcandor_schema.fact_user_engagement IS 'Fact table for user engagement events';

------------------------------------------------------------------------------------------------
