------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.fact_content_performance (
    fact_id BIGSERIAL PRIMARY KEY,

    date_key INTEGER NOT NULL,
    content_key BIGINT NOT NULL,
    author_user_key BIGINT,
