    CONSTRAINT fk_fact_content_date FOREIGN KEY (date_key)
        REFERENCES socialcandor_schema.dim_time(date_key),
    CONSTRAINT fk_fact_content_content FOREIGN KEY (content_key)
        REFERENCES socialcandor_schema.dim_content(content_key),
    CONSTRAINT fk_fact_content_author FOREIGN KEY (author_user_key)
        REFERENCES socialcandor_schema.dim_users(user_key),
    CONSTRAINT fk_fact_content_geo FOREIGN KEY (geo_key)
        REFERENCES socialcandor_schema.dim_geography(geo_key)
);
COMMENT ON TABLE socialcandor_schema.fact_content_performance IS 'Fact table for content performance metrics';

------------------------------------------------------------------------------------------------
-- Table: DW07 - session_replay_data
-- Description: User session replays for UX analysis
-- Business Case: Understand user behavior at a granular level
-- KPIs:
--   1. Session replay coverage
--   2. User frustration signals
-- Feature Reference: ANL08 (Session Replay)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.session_replay_data (
    replay_id BIGSERIAL PRIMARY KEY,

    session_id UUID NOT NULL,
    user_id UUID,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE,
    events JSONB NOT NULL, -- Array of user interactions
    page_urls TEXT[],
    device_info JSONB,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_session_replay_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.session_replay_data IS 'User session replays for UX analysis';

------------------------------------------------------------------------------------------------
-- Table: DW08 - conversion_funnel_definitions
-- Description: Definitions of conversion funnels (steps, criteria)
-- Business Case: Track user progression through key journeys
-- KPIs:
--   1. Funnel completion rate
--   2. Drop-off points
-- Feature Reference: ANL09 (Conversion Funnels)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.conversion_funnel_definitions (
    funnel_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    funnel_name VARCHAR(255) NOT NULL,
    funnel_type socialcandor_schema.conversion_funnel_type NOT NULL,
    description TEXT,

    steps JSONB NOT NULL,  -- Array of step definitions (event, conditions)

    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.conversion_funnel_definitions IS 'Definitions of conversion funnels';

------------------------------------------------------------------------------------------------
-- Table: DW09 - kpi_definitions
-- Description: Definitions of KPIs and their calculation logic
-- Business Case: Centralize KPI definitions for consistency across reports
-- KPIs:
--   1. KPI coverage
--   2. Calculation accuracy
-- Feature Reference: ANL10 (KPI Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.kpi_definitions (
    kpi_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    kpi_name VARCHAR(255) NOT NULL,
    kpi_code VARCHAR(100) UNIQUE NOT NULL,
    description TEXT,
    category VARCHAR(50) CHECK (category IN ('USER','CONTENT','REVENUE','ENGAGEMENT','PERFORMANCE')),

    formula TEXT NOT NULL,
    data_source VARCHAR(100),
    frequency VARCHAR(20) CHECK (frequency IN ('REAL_TIME','HOURLY','DAILY','WEEKLY','MONTHLY')),

    unit VARCHAR(20),
    target_value NUMERIC,
    warning_threshold NUMERIC,
    critical_threshold NUMERIC,

    owner_id UUID,

    is_active BOOLEAN DEFAULT TRUE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.kpi_definitions IS 'Definitions of KPIs and their calculation logic';

------------------------------------------------------------------------------------------------
-- Table: DW10 - agg_daily_user_metrics (Materialized View)
-- Description: Pre-aggregated daily user metrics for fast queries
-- Business Case: Improve dashboard performance; reduce load on fact tables
-- KPIs: (Derived from underlying data)
-- Feature Reference: DWH07 (Aggregations)
------------------------------------------------------------------------------------------------
-- Drop if exists (for idempotency)
DROP MATERIALIZED VIEW IF EXISTS socialcandor_schema.agg_daily_user_metrics;

CREATE MATERIALIZED VIEW socialcandor_schema.agg_daily_user_metrics AS
SELECT
    d.date_key,
    d.full_date,
    u.geo_key,
    COUNT(DISTINCT f.user_key) AS daily_active_users,
    SUM(f.session_count) AS total_sessions,
    SUM(f.total_session_duration_seconds) AS total_session_duration,
    SUM(f.posts_created) AS total_posts,
    SUM(f.comments_made) AS total_comments,
    SUM(f.reactions_given) AS total_reactions,
    SUM(f.shares) AS total_shares,
    SUM(f.messages_sent) AS total_messages
FROM socialcandor_schema.fact_user_engagement f
JOIN socialcandor_schema.dim_time d ON f.date_key = d.date_key
JOIN socialcandor_schema.dim_users u ON f.user_key = u.user_key
GROUP BY d.date_key, d.full_date, u.geo_key;

COMMENT ON MATERIALIZED VIEW socialcandor_schema.agg_daily_user_metrics IS 'Pre-aggregated daily user metrics for fast queries';

CREATE UNIQUE INDEX IF NOT EXISTS idx_agg_daily_user_metrics_unique
    ON socialcandor_schema.agg_daily_user_metrics (date_key, geo_key);

