-- Simple policies: most tables accessible only by admins or specific roles.
-- For brevity, we'll create a generic admin policy and a self/owner policy where applicable.

-- Admin policy function: checks if current user is admin
CREATE OR REPLACE FUNCTION socialcandor_schema.is_admin() RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- For each table, create policy:
-- Example for data_quality_checks_ingestion:
CREATE POLICY dq_checks_admin_policy ON socialcandor_schema.data_quality_checks_ingestion
    FOR ALL USING (socialcandor_schema.is_admin());

-- (We'll apply similar to all tables; to avoid repetition, we'll create a loop but static SQL is fine for this script.)

-- We'll generate statements for each table; here we'll do a representative set.
-- For brevity, we'll create policies only for tables that need user-level isolation (like product_analytics_events).

-- product_analytics_events: users can see their own events; admins see all.
CREATE POLICY analytics_events_self_policy ON socialcandor_schema.product_analytics_events
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY analytics_events_admin_policy ON socialcandor_schema.product_analytics_events
    FOR ALL USING (socialcandor_schema.is_admin());

-- support_ticketing: users see their own tickets; assigned staff see theirs; admins see all.
CREATE POLICY support_tickets_self_policy ON socialcandor_schema.support_ticketing
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY support_tickets_assigned_policy ON socialcandor_schema.support_ticketing
    FOR ALL USING (assigned_to = current_setting('app.current_user_id')::UUID);
CREATE POLICY support_tickets_admin_policy ON socialcandor_schema.support_ticketing
    FOR ALL USING (socialcandor_schema.is_admin());

-- data_consumer_feedback: users see their own feedback; assigned staff see theirs; admins all.
CREATE POLICY dcf_self_policy ON socialcandor_schema.data_consumer_feedback
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY dcf_assigned_policy ON socialcandor_schema.data_consumer_feedback
    FOR ALL USING (assigned_to = current_setting('app.current_user_id')::UUID);
CREATE POLICY dcf_admin_policy ON socialcandor_schema.data_consumer_feedback
    FOR ALL USING (socialcandor_schema.is_admin());

-- experiment_assignments: users can see their own assignments.
CREATE POLICY exp_assign_self_policy ON socialcandor_schema.experiment_assignments
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY exp_assign_admin_policy ON socialcandor_schema.experiment_assignments
    FOR ALL USING (socialcandor_schema.is_admin());

-- session_replay_data: only admins can view (sensitive).
CREATE POLICY session_replay_admin_policy ON socialcandor_schema.session_replay_data
    FOR ALL USING (socialcandor_schema.is_admin());

