--================================================================================================
-- ENUMS (for new tables)
--================================================================================================

-- Enum: DPE01 - data_product_status
-- Description: Lifecycle status of a data product in the catalog
-- Business Case: Track data product from development to retirement
-- Feature Reference: DPT01 (Data Product Management)
--================================================================================================
CREATE TYPE socialcandor_schema.data_product_status AS ENUM (
    'DRAFT',              -- In development, not yet available
    'PUBLISHED',          -- Available for discovery/use
    'DEPRECATED',         -- Still available but not recommended
    'RETIRED',            -- No longer available
    'ARCHIVED'            -- Removed from active catalog
);
COMMENT ON TYPE socialcandor_schema.data_product_status IS 'Lifecycle status of a data product in the catalog';

-- Enum: DPE02 - marketplace_listing_status
-- Description: Status of a listing in the marketplace
-- Business Case: Manage listing lifecycle from draft to sold/expired
-- Feature Reference: MPL01 (Marketplace)
--================================================================================================
CREATE TYPE socialcandor_schema.marketplace_listing_status AS ENUM (
    'DRAFT',
    'ACTIVE',
    'PENDING_REVIEW',
    'SOLD',
    'EXPIRED',
    'CANCELLED',
    'ARCHIVED'
);
COMMENT ON TYPE socialcandor_schema.marketplace_listing_status IS 'Status of a listing in the marketplace';

-- Enum: DPE03 - billing_period
-- Description: Billing cycles for usage-based pricing
-- Business Case: Support different billing models
-- Feature Reference: BIL01 (Usage Billing)
--================================================================================================
CREATE TYPE socialcandor_schema.billing_period AS ENUM (
    'HOURLY',
    'DAILY',
    'MONTHLY',
    'QUARTERLY',
    'YEARLY'
);
COMMENT ON TYPE socialcandor_schema.billing_period IS 'Billing cycles for usage-based pricing';

-- Enum: DPE04 - license_type
-- Description: Types of data licenses
-- Business Case: Define permitted usage of data products
-- Feature Reference: LIC01 (Data Licensing)
--================================================================================================
CREATE TYPE socialcandor_schema.license_type AS ENUM (
    'OPEN_DATA',          -- Free to use, share, modify
    'COMMERCIAL',         -- Paid, restricted commercial use
    'RESEARCH_ONLY',      -- Only for non-commercial research
    'INTERNAL_USE',       -- Internal company use only
    'RESTRICTED'          -- Custom restrictions
);
COMMENT ON TYPE socialcandor_schema.license_type IS 'Types of data licenses';

-- Enum: DPE05 - deployment_status
-- Description: Status of an ML model deployment
-- Business Case: Track deployment pipeline stages
-- Feature Reference: MLOP01 (MLOps)
--================================================================================================
CREATE TYPE socialcandor_schema.deployment_status AS ENUM (
    'PENDING',
    'DEPLOYING',
    'RUNNING',
    'STOPPED',
    'FAILED',
    'ROLLED_BACK'
);
COMMENT ON TYPE socialcandor_schema.deployment_status IS 'Status of an ML model deployment';

-- Enum: DPE06 - assessment_outcome
-- Description: Outcome of an AI impact assessment
-- Business Case: Record ethics review results
-- Feature Reference: AIETH01 (AI Ethics)
--================================================================================================
CREATE TYPE socialcandor_schema.assessment_outcome AS ENUM (
    'APPROVED',
    'REJECTED',
    'CONDITIONAL_APPROVAL',
    'NEEDS_REVISION',
    'IN_REVIEW'
);
COMMENT ON TYPE socialcandor_schema.assessment_outcome IS 'Outcome of an AI impact assessment';

