CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.data_product_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.marketplace_listing_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.ml_model_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.assessment_seq START 1000;

--================================================================================================
-- TABLE: advertisers
-- Description: Advertiser accounts (business entities that run ads)
-- Business Case: Separate advertiser profile from user account for billing, compliance, and analytics
-- KPIs:
--   1. Number of active advertisers
--   2. Advertiser retention rate
--   3. Average campaign spend per advertiser
--   4. Advertiser churn rate
--   5. Time to first campaign
-- Feature Reference: ADV01 (Advertiser Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.advertisers (
    advertiser_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Core identification
    advertiser_number VARCHAR(50) GENERATED ALWAYS AS (
        'ADV-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Owner (user or organization)
    owner_user_id UUID,                -- Individual user
    owner_organization_id UUID,         -- Organization (if exists)

    company_name VARCHAR(255) NOT NULL,
    display_name VARCHAR(255),
    tax_id VARCHAR(50),
    vat_number VARCHAR(50),

    -- Contact
    contact_email VARCHAR(255) NOT NULL,
    contact_phone VARCHAR(50),
    website VARCHAR(255),

    -- Billing
    billing_address TEXT,
    billing_contact VARCHAR(255),
    payment_method_id UUID,             -- Default payment method

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    verification_status VARCHAR(20) DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING', 'VERIFIED', 'REJECTED')),

    -- Account manager (internal)
    account_manager_id UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_advertisers_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_advertisers_owner_org FOREIGN KEY (owner_organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_advertisers_payment_method FOREIGN KEY (payment_method_id)
        REFERENCES socialcandor_schema.payment_methods(payment_method_id) ON DELETE SET NULL,
    CONSTRAINT fk_advertisers_account_manager FOREIGN KEY (account_manager_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_advertiser_owner CHECK (owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL)
);
COMMENT ON TABLE socialcandor_schema.advertisers IS 'Advertiser accounts for running ad campaigns';

--================================================================================================
-- TABLE: ad_campaigns
-- Description: Advertising campaigns (may already exist; we include with IF NOT EXISTS and extend)
-- Business Case: Manage ad campaigns, budgets, targeting, and performance
-- KPIs:
--   1. Campaign ROI
--   2. CTR (Click-Through Rate)
--   3. Conversion rate
--   4. Budget utilization
--   5. Campaign reach
-- Feature Reference: ADV02 (Campaign Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ad_campaigns (
    campaign_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Core
    campaign_name VARCHAR(255) NOT NULL,
    advertiser_id UUID NOT NULL,

    -- Budget & Schedule
    total_budget NUMERIC(15,2) NOT NULL CHECK (total_budget >= 0),
    daily_budget NUMERIC(15,2) CHECK (daily_budget >= 0),
    currency CHAR(3) DEFAULT 'USD',
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    end_date TIMESTAMP WITH TIME ZONE,

    -- Targeting (simplified)
    target_audience JSONB,
    geo_targeting JSONB,
    device_targeting JSONB,

    -- Status
    status VARCHAR(30) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PENDING_REVIEW', 'ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELLED')),

    -- Performance (denormalized)
    impressions BIGINT DEFAULT 0,
    clicks BIGINT DEFAULT 0,
    conversions BIGINT DEFAULT 0,
    spend NUMERIC(15,2) DEFAULT 0,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_ad_campaigns_advertiser FOREIGN KEY (advertiser_id)
        REFERENCES socialcandor_schema.advertisers(advertiser_id) ON DELETE CASCADE,
    CONSTRAINT chk_campaign_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
COMMENT ON TABLE socialcandor_schema.ad_campaigns IS 'Advertising campaigns with budgets, targeting, and performance tracking';

--================================================================================================
-- TABLE: creatives
-- Description: Ad creatives (images, videos, text) – may overlap with ad_creatives but we create if not exists
-- Business Case: Store and manage ad creative assets with versioning
-- KPIs:
--   1. Creative approval rate
--   2. Creative performance by type
--   3. Creative turnover
-- Feature Reference: ADV03 (Creative Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.creatives (
    creative_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    creative_name VARCHAR(255) NOT NULL,
    campaign_id UUID NOT NULL,
    advertiser_id UUID NOT NULL,

    creative_type VARCHAR(30) CHECK (creative_type IN ('IMAGE', 'VIDEO', 'TEXT', 'HTML5', 'CAROUSEL')),
    creative_format VARCHAR(30),

    -- Assets
    asset_urls JSONB,                          -- { "main": "url", "thumbnail": "url" }
    headline VARCHAR(255),
    body TEXT,
    call_to_action VARCHAR(100),
    destination_url VARCHAR(500),

    -- Dimensions
    width INTEGER CHECK (width >= 0),
    height INTEGER CHECK (height >= 0),

    -- Status
    approval_status VARCHAR(20) DEFAULT 'PENDING' CHECK (approval_status IN ('PENDING', 'APPROVED', 'REJECTED')),
    rejection_reason TEXT,

    is_active BOOLEAN DEFAULT TRUE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_creatives_campaign FOREIGN KEY (campaign_id)
        REFERENCES socialcandor_schema.ad_campaigns(campaign_id) ON DELETE CASCADE,
    CONSTRAINT fk_creatives_advertiser FOREIGN KEY (advertiser_id)
        REFERENCES socialcandor_schema.advertisers(advertiser_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.creatives IS 'Ad creative assets';

--================================================================================================
-- TABLE: data_product_catalog
-- Description: Catalog of data products available for internal or external use
-- Business Case: Monetize data assets; enable data marketplace
-- KPIs:
--   1. Number of data products
--   2. Product adoption rate
--   3. Revenue per product
--   4. Product freshness
--   5. User satisfaction score
-- Feature Reference: DPT02 (Data Product Catalog)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_product_catalog (
    product_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    product_number VARCHAR(50) GENERATED ALWAYS AS (
        'DP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_product_seq')::TEXT, 6, '0')
    ) STORED,

    product_name VARCHAR(255) NOT NULL,
    product_code VARCHAR(100) UNIQUE,
    description TEXT,
    category VARCHAR(100),
    tags TEXT[],

    -- Data source
    source_schema VARCHAR(100),
    source_table VARCHAR(100),
    source_query TEXT,

    -- Schema/description of data
    data_dictionary JSONB,                  -- Column-level metadata

    -- Licensing & pricing
    default_license socialcandor_schema.license_type,
    pricing_model VARCHAR(50) CHECK (pricing_model IN ('FREE', 'ONE_TIME', 'SUBSCRIPTION', 'USAGE_BASED')),
    price NUMERIC(15,2),
    currency CHAR(3) DEFAULT 'USD',

    -- Ownership
    owner_team VARCHAR(100),
    data_steward_id UUID,
    technical_contact_id UUID,

    -- Quality
    quality_score NUMERIC(5,2) CHECK (quality_score >= 0 AND quality_score <= 100),
    certification_status VARCHAR(20),

    -- Status
    status socialcandor_schema.data_product_status DEFAULT 'DRAFT',

    -- Metrics
    download_count INTEGER DEFAULT 0,
    view_count INTEGER DEFAULT 0,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_dp_steward FOREIGN KEY (data_steward_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_dp_technical_contact FOREIGN KEY (technical_contact_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_product_catalog IS 'Catalog of data products available for internal or external use';

--================================================================================================
-- TABLE: marketplace_listings
-- Description: Listings in a marketplace (could be for data products, services, etc.)
-- Business Case: Enable buying/selling of data or other digital assets
-- KPIs:
--   1. Listing volume
--   2. Conversion rate
--   3. Average listing price
--   4. Time to sell
--   5. Buyer/seller satisfaction
-- Feature Reference: MPL02 (Marketplace Listings)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.marketplace_listings (
    listing_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    listing_number VARCHAR(50) GENERATED ALWAYS AS (
        'LST-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.marketplace_listing_seq')::TEXT, 6, '0')
    ) STORED,

    seller_id UUID NOT NULL,                 -- user or organization
    seller_type VARCHAR(10) CHECK (seller_type IN ('USER', 'ORGANIZATION')),

    product_id UUID,                          -- If linked to data product catalog
    title VARCHAR(255) NOT NULL,
    description TEXT,
    category VARCHAR(100),
    images TEXT[],

    price NUMERIC(15,2),
    currency CHAR(3) DEFAULT 'USD',
    price_model VARCHAR(30) CHECK (price_model IN ('FIXED', 'NEGOTIABLE', 'SUBSCRIPTION', 'USAGE_BASED')),

    status socialcandor_schema.marketplace_listing_status DEFAULT 'DRAFT',

    view_count INTEGER DEFAULT 0,
    inquiry_count INTEGER DEFAULT 0,

    start_date TIMESTAMP WITH TIME ZONE,
    end_date TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_ml_product FOREIGN KEY (product_id)
        REFERENCES socialcandor_schema.data_product_catalog(product_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_seller_user FOREIGN KEY (seller_id) REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    -- Note: if seller_type = 'ORGANIZATION', seller_id references organizations, but we can't have polymorphic FK; handled application-side.
    CONSTRAINT chk_ml_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
COMMENT ON TABLE socialcandor_schema.marketplace_listings IS 'Listings in a marketplace (data products, services, etc.)';

--================================================================================================
-- TABLE: data_marketplace_listings
-- Description: Specialized view or extension for data-specific marketplace listings
-- Business Case: Separate data marketplace from general marketplace for clarity
-- KPIs: Similar to marketplace_listings but focused on data
-- Feature Reference: DPT03 (Data Marketplace)
--================================================================================================
-- This could be a view on marketplace_listings filtered by category, but we'll create a separate table for extensibility.
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_marketplace_listings (
    data_listing_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    listing_id UUID UNIQUE NOT NULL,          -- Link to base marketplace listing
    product_id UUID NOT NULL,

    sample_data_url VARCHAR(500),
    documentation_url VARCHAR(500),
    update_frequency VARCHAR(50),
    data_volume_estimate VARCHAR(100),

    -- Additional data-specific fields
    contains_pii BOOLEAN DEFAULT FALSE,
    data_sensitivity VARCHAR(50),
    geographic_coverage TEXT[],

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_dml_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
    CONSTRAINT fk_dml_product FOREIGN KEY (product_id)
        REFERENCES socialcandor_schema.data_product_catalog(product_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.data_marketplace_listings IS 'Data-specific extensions for marketplace listings';

--================================================================================================
-- TABLE: data_usage_billing
-- Description: Tracks usage of data products for billing purposes
-- Business Case: Enable pay-per-use models; generate invoices
-- KPIs:
--   1. Usage volume per customer
--   2. Revenue per usage period
--   3. Number of active subscribers
--   4. Average revenue per user (ARPU)
--   5. Churn rate
-- Feature Reference: BIL02 (Usage Billing)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_usage_billing (
    usage_id BIGSERIAL PRIMARY KEY,

    product_id UUID NOT NULL,
    consumer_id UUID NOT NULL,                 -- user or organization ID
    consumer_type VARCHAR(10) CHECK (consumer_type IN ('USER', 'ORGANIZATION')),

    usage_date DATE NOT NULL,
    quantity INTEGER CHECK (quantity >= 0),    -- e.g., API calls, rows retrieved
    unit_price NUMERIC(15,6),
    total_charge NUMERIC(15,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,

    billing_period socialcandor_schema.billing_period,
    invoice_id UUID,  -- link to invoice when generated

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_usage_product FOREIGN KEY (product_id)
        REFERENCES socialcandor_schema.data_product_catalog(product_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.data_usage_billing IS 'Tracks usage of data products for billing';

--================================================================================================
-- TABLE: data_licensing_agreements
-- Description: Formal agreements for data usage between provider and consumer
-- Business Case: Legal compliance; define terms of use
-- KPIs:
--   1. Number of active agreements
--   2. Agreement renewal rate
--   3. Time to sign
--   4. Compliance rate
-- Feature Reference: LIC02 (Data Licensing)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_licensing_agreements (
    agreement_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    agreement_number VARCHAR(50) GENERATED ALWAYS AS (
        'LIC-' || TO_CHAR(effective_date, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    product_id UUID NOT NULL,
    licensee_id UUID NOT NULL,                 -- user or organization
    licensee_type VARCHAR(10) CHECK (licensee_type IN ('USER', 'ORGANIZATION')),

    license_type socialcandor_schema.license_type NOT NULL,
    terms TEXT,
    restrictions TEXT,
    permitted_uses TEXT[],

    effective_date DATE NOT NULL,
    expiration_date DATE,
    auto_renew BOOLEAN DEFAULT FALSE,

    signed_by_provider UUID,
    signed_by_licensee UUID,
    signed_at TIMESTAMP WITH TIME ZONE,

    document_url VARCHAR(500),

    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PENDING_SIGNATURE', 'ACTIVE', 'EXPIRED', 'TERMINATED')),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_lic_agreement_product FOREIGN KEY (product_id)
        REFERENCES socialcandor_schema.data_product_catalog(product_id) ON DELETE CASCADE,
    CONSTRAINT fk_lic_signed_provider FOREIGN KEY (signed_by_provider)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_lic_signed_licensee FOREIGN KEY (signed_by_licensee)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_lic_dates CHECK (expiration_date IS NULL OR expiration_date >= effective_date)
);
COMMENT ON TABLE socialcandor_schema.data_licensing_agreements IS 'Formal agreements for data usage';

--================================================================================================
-- TABLE: ml_models
-- Description: Machine learning model metadata
-- Business Case: Manage ML models throughout their lifecycle; enable MLOps
-- KPIs:
--   1. Number of models in production
--   2. Model performance metrics
--   3. Time to deploy
--   4. Model drift frequency
--   5. Number of model versions
-- Feature Reference: MLOP02 (Model Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_models (
    model_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    model_number VARCHAR(50) GENERATED ALWAYS AS (
        'ML-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_seq')::TEXT, 6, '0')
    ) STORED,

    model_name VARCHAR(255) NOT NULL,
    model_description TEXT,
    model_type VARCHAR(100),                     -- e.g., 'classification', 'regression'
    algorithm_family VARCHAR(100),
    framework VARCHAR(50),                        -- e.g., 'tensorflow', 'pytorch'

    -- Ownership
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Training data source
    training_data_source TEXT,
    training_data_version VARCHAR(100),

    -- Governance
    requires_ethics_review BOOLEAN DEFAULT FALSE,
    ethics_review_id UUID,
    compliance_status VARCHAR(20),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    lifecycle_stage VARCHAR(30) CHECK (lifecycle_stage IN ('DEVELOPMENT', 'TESTING', 'PRODUCTION', 'DEPRECATED')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_ml_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ml_models IS 'Machine learning model metadata';

--================================================================================================
-- TABLE: model_versions
-- Description: Versions of ML models, tracking changes and performance
-- Business Case: Version control for models; rollback capability
-- KPIs:
--   1. Number of versions per model
--   2. Version performance delta
--   3. Deployment frequency
-- Feature Reference: MLOP03 (Model Versioning)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_versions (
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    model_id UUID NOT NULL,
    version_number INTEGER NOT NULL CHECK (version_number >= 1),
    version_tag VARCHAR(50),

    -- Artifacts
    model_artifact_url VARCHAR(500),
    model_metadata JSONB,                        -- hyperparameters, config
    model_size_bytes BIGINT,

    -- Performance metrics (from testing)
    accuracy NUMERIC(5,4),
    precision NUMERIC(5,4),
    recall NUMERIC(5,4),
    f1_score NUMERIC(5,4),
    other_metrics JSONB,

    -- Training details
    trained_by UUID,
    trained_at TIMESTAMP WITH TIME ZONE,
    training_duration_seconds INTEGER,
    training_data_version VARCHAR(100),

    -- Validation
    validation_status VARCHAR(20) CHECK (validation_status IN ('PENDING', 'PASSED', 'FAILED')),
    validation_report TEXT,

    -- Deployment info
    deployed_at TIMESTAMP WITH TIME ZONE,
    deployment_id UUID, -- current deployment, if any

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_model_versions_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_model_versions_trained_by FOREIGN KEY (trained_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_model_version UNIQUE (model_id, version_number)
);
COMMENT ON TABLE socialcandor_schema.model_versions IS 'Versions of ML models';

--================================================================================================
-- TABLE: ml_model_deployment_log
-- Description: Log of model deployments and status changes
-- Business Case: Audit trail for model deployments; troubleshooting
-- KPIs:
--   1. Deployment success rate
--   2. Mean time to deploy
--   3. Rollback frequency
--   4. Deployment count per model
-- Feature Reference: MLOP04 (Deployment Logging)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_deployment_log (
    log_id BIGSERIAL PRIMARY KEY,

    model_id UUID NOT NULL,
    version_id UUID NOT NULL,

    deployment_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deployed_by UUID NOT NULL,

    environment VARCHAR(30) CHECK (environment IN ('DEV', 'TEST', 'STAGING', 'PRODUCTION')),
    status socialcandor_schema.deployment_status NOT NULL,

    endpoint_url VARCHAR(500),
    infrastructure_details JSONB,

    duration_seconds INTEGER,
    error_message TEXT,

    rollback_time TIMESTAMP WITH TIME ZONE,
    rollback_reason TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_deployment_log_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_deployment_log_version FOREIGN KEY (version_id)
        REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_deployment_log_deployed_by FOREIGN KEY (deployed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ml_model_deployment_log IS 'Log of model deployments and status changes';

--================================================================================================
-- TABLE: ai_ethics_review_board
-- Description: Members and meetings of the AI ethics review board
-- Business Case: Formal oversight of AI models; compliance with ethical standards
-- KPIs:
--   1. Number of reviews per month
--   2. Average review time
--   3. Board member participation
-- Feature Reference: AIETH02 (Ethics Board)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ai_ethics_review_board (
    member_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    user_id UUID NOT NULL,
    role VARCHAR(50) CHECK (role IN ('CHAIR', 'VICE_CHAIR', 'MEMBER', 'OBSERVER')),
    expertise_area TEXT[],

    term_start DATE NOT NULL,
    term_end DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (term_end IS NULL OR term_end > CURRENT_DATE) STORED,

    -- Audit
    appointed_by UUID,
    appointed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_ethics_board_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ethics_board_appointed_by FOREIGN KEY (appointed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ai_ethics_review_board IS 'Members of the AI ethics review board';

--================================================================================================
-- TABLE: ai_impact_assessment
-- Description: Ethics and impact assessments for AI models
-- Business Case: Document ethical considerations, risks, and mitigations
-- KPIs:
--   1. Number of assessments
--   2. Time to complete assessment
--   3. Risk level distribution
--   4. Model approval rate
-- Feature Reference: AIETH03 (Impact Assessment)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ai_impact_assessment (
    assessment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    assessment_number VARCHAR(50) GENERATED ALWAYS AS (
        'AIA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.assessment_seq')::TEXT, 6, '0')
    ) STORED,

    model_id UUID NOT NULL,
    version_id UUID,

    assessor_id UUID NOT NULL,
    assessment_date DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Impact areas
    fairness_analysis TEXT,
    bias_analysis TEXT,
    transparency_analysis TEXT,
    accountability_analysis TEXT,
    privacy_impact TEXT,
    safety_analysis TEXT,

    identified_risks JSONB,                 -- Array of risk objects
    mitigation_measures TEXT,
    residual_risks TEXT,

    outcome socialcandor_schema.assessment_outcome NOT NULL,
    conditions TEXT,
    review_notes TEXT,

    review_date DATE,
    reviewed_by UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    CONSTRAINT fk_ai_assessment_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_assessment_version FOREIGN KEY (version_id)
        REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_assessment_assessor FOREIGN KEY (assessor_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ai_assessment_reviewed_by FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ai_impact_assessment IS 'Ethics and impact assessments for AI models';

--================================================================================================
-- FOREIGN KEY CONSTRAINTS (additional)
-- Some foreign keys were defined inline; add any missing ones here.
--================================================================================================

-- data_usage_billing: consumer_id can be user or org; we can't enforce FK for both, but we can add a check that either exists.
-- We'll skip FK for consumer_id and handle in app.

-- marketplace_listings: seller_id polymorphic – handled in app.

-- data_marketplace_listings: listing_id and product_id FKs already done.

-- ml_models: ethics_review_id references ai_impact_assessment? Not yet; we'll add later if needed.

-- Add FK from ml_models to ai_impact_assessment (ethics_review_id)
ALTER TABLE socialcandor_schema.ml_models
    ADD CONSTRAINT fk_ml_ethics_review FOREIGN KEY (ethics_review_id)
        REFERENCES socialcandor_schema.ai_impact_assessment(assessment_id) ON DELETE SET NULL;

-- Add FK from model_versions to ml_model_deployment_log (deployment_id)
ALTER TABLE socialcandor_schema.model_versions
    ADD CONSTRAINT fk_model_versions_deployment FOREIGN KEY (deployment_id)
        REFERENCES socialcandor_schema.ml_model_deployment_log(log_id) ON DELETE SET NULL;

--================================================================================================
-- INDEXES
--================================================================================================

-- advertisers
CREATE INDEX IF NOT EXISTS idx_advertisers_owner_user ON socialcandor_schema.advertisers(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_advertisers_owner_org ON socialcandor_schema.advertisers(owner_organization_id) WHERE owner_organization_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_advertisers_active ON socialcandor_schema.advertisers(is_active) WHERE is_active = TRUE;

-- ad_campaigns
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_advertiser ON socialcandor_schema.ad_campaigns(advertiser_id);
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_status ON socialcandor_schema.ad_campaigns(status);
CREATE INDEX IF NOT EXISTS idx_ad_campaigns_dates ON socialcandor_schema.ad_campaigns(start_date, end_date);

-- creatives
CREATE INDEX IF NOT EXISTS idx_creatives_campaign ON socialcandor_schema.creatives(campaign_id);
CREATE INDEX IF NOT EXISTS idx_creatives_advertiser ON socialcandor_schema.creatives(advertiser_id);
CREATE INDEX IF NOT EXISTS idx_creatives_status ON socialcandor_schema.creatives(approval_status);

-- data_product_catalog
CREATE INDEX IF NOT EXISTS idx_dp_category ON socialcandor_schema.data_product_catalog(category);
CREATE INDEX IF NOT EXISTS idx_dp_status ON socialcandor_schema.data_product_catalog(status);
CREATE INDEX IF NOT EXISTS idx_dp_steward ON socialcandor_schema.data_product_catalog(data_steward_id) WHERE data_steward_id IS NOT NULL;

-- marketplace_listings
CREATE INDEX IF NOT EXISTS idx_ml_seller ON socialcandor_schema.marketplace_listings(seller_id, seller_type);
CREATE INDEX IF NOT EXISTS idx_ml_status ON socialcandor_schema.marketplace_listings(status);
CREATE INDEX IF NOT EXISTS idx_ml_product ON socialcandor_schema.marketplace_listings(product_id) WHERE product_id IS NOT NULL;

-- data_marketplace_listings
CREATE INDEX IF NOT EXISTS idx_dml_listing ON socialcandor_schema.data_marketplace_listings(listing_id);
CREATE INDEX IF NOT EXISTS idx_dml_product ON socialcandor_schema.data_marketplace_listings(product_id);

-- data_usage_billing
CREATE INDEX IF NOT EXISTS idx_usage_product ON socialcandor_schema.data_usage_billing(product_id);
CREATE INDEX IF NOT EXISTS idx_usage_consumer ON socialcandor_schema.data_usage_billing(consumer_id, consumer_type);
CREATE INDEX IF NOT EXISTS idx_usage_date ON socialcandor_schema.data_usage_billing(usage_date DESC);

-- data_licensing_agreements
CREATE INDEX IF NOT EXISTS idx_lic_product ON socialcandor_schema.data_licensing_agreements(product_id);
CREATE INDEX IF NOT EXISTS idx_lic_licensee ON socialcandor_schema.data_licensing_agreements(licensee_id, licensee_type);
CREATE INDEX IF NOT EXISTS idx_lic_status ON socialcandor_schema.data_licensing_agreements(status);
CREATE INDEX IF NOT EXISTS idx_lic_dates ON socialcandor_schema.data_licensing_agreements(effective_date, expiration_date);

-- ml_models
CREATE INDEX IF NOT EXISTS idx_ml_models_name ON socialcandor_schema.ml_models(model_name);
CREATE INDEX IF NOT EXISTS idx_ml_models_owner ON socialcandor_schema.ml_models(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ml_models_stage ON socialcandor_schema.ml_models(lifecycle_stage);

-- model_versions
CREATE INDEX IF NOT EXISTS idx_model_versions_model ON socialcandor_schema.model_versions(model_id);
CREATE INDEX IF NOT EXISTS idx_model_versions_version ON socialcandor_schema.model_versions(model_id, version_number);
CREATE INDEX IF NOT EXISTS idx_model_versions_deployed ON socialcandor_schema.model_versions(deployment_id) WHERE deployment_id IS NOT NULL;

-- ml_model_deployment_log
CREATE INDEX IF NOT EXISTS idx_deployment_log_model ON socialcandor_schema.ml_model_deployment_log(model_id);
