-- Enable RLS on tables that hold sensitive or multi-tenant data
ALTER TABLE socialcandor_schema.advertisers ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ad_campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.creatives ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_product_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.marketplace_listings ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_marketplace_listings ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_usage_billing ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.data_licensing_agreements ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ml_models ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.model_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ml_model_deployment_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ai_ethics_review_board ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.ai_impact_assessment ENABLE ROW LEVEL SECURITY;

-- Create admin check function if not exists
CREATE OR REPLACE FUNCTION socialcandor_schema.is_admin() RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Advertisers: owners can manage; admins all
CREATE POLICY advertisers_owner_policy ON socialcandor_schema.advertisers
    FOR ALL USING (
        owner_user_id = current_setting('app.current_user_id')::UUID OR
        EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE)
    );
CREATE POLICY advertisers_self_policy ON socialcandor_schema.advertisers
    FOR SELECT USING (owner_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY advertisers_admin_policy ON socialcandor_schema.advertisers
    FOR ALL USING (socialcandor_schema.is_admin());

-- Ad campaigns: advertisers see their own; admins all
CREATE POLICY ad_campaigns_owner_policy ON socialcandor_schema.ad_campaigns
    FOR ALL USING (
        advertiser_id IN (SELECT advertiser_id FROM socialcandor_schema.advertisers WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
        OR socialcandor_schema.is_admin()
    );

-- Creatives: similar to campaigns
CREATE POLICY creatives_owner_policy ON socialcandor_schema.creatives
    FOR ALL USING (
        campaign_id IN (SELECT campaign_id FROM socialcandor_schema.ad_campaigns WHERE advertiser_id IN (
            SELECT advertiser_id FROM socialcandor_schema.advertisers WHERE owner_user_id = current_setting('app.current_user_id')::UUID
        )) OR socialcandor_schema.is_admin()
    );

-- Data product catalog: owners (data steward) can manage; all users can view if published
CREATE POLICY dp_catalog_view_policy ON socialcandor_schema.data_product_catalog
    FOR SELECT USING (status = 'PUBLISHED' OR data_steward_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY dp_catalog_manage_policy ON socialcandor_schema.data_product_catalog
    FOR ALL USING (data_steward_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());

-- Marketplace listings: sellers manage; buyers view; admins all
CREATE POLICY ml_seller_policy ON socialcandor_schema.marketplace_listings
    FOR ALL USING (
        (seller_type = 'USER' AND seller_id = current_setting('app.current_user_id')::UUID)
        OR socialcandor_schema.is_admin()
    );
CREATE POLICY ml_buyer_policy ON socialcandor_schema.marketplace_listings
    FOR SELECT USING (status = 'ACTIVE' OR socialcandor_schema.is_admin());

-- Data usage billing: consumers see own; admins all
CREATE POLICY usage_consumer_policy ON socialcandor_schema.data_usage_billing
    FOR SELECT USING (
        (consumer_type = 'USER' AND consumer_id = current_setting('app.current_user_id')::UUID)
        OR socialcandor_schema.is_admin()
    );

-- Licensing agreements: licensee sees own; admins all
CREATE POLICY lic_licensee_policy ON socialcandor_schema.data_licensing_agreements
    FOR SELECT USING (
        (licensee_type = 'USER' AND licensee_id = current_setting('app.current_user_id')::UUID)
        OR socialcandor_schema.is_admin()
    );
CREATE POLICY lic_manage_policy ON socialcandor_schema.data_licensing_agreements
    FOR ALL USING (socialcandor_schema.is_admin());

-- ML models: owners (owner_user_id) can manage; others view if published? Not needed; admins all
CREATE POLICY ml_models_owner_policy ON socialcandor_schema.ml_models
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY ml_models_view_policy ON socialcandor_schema.ml_models
    FOR SELECT USING (TRUE);  -- maybe restrict later

-- Model versions: similar to models
CREATE POLICY model_versions_owner_policy ON socialcandor_schema.model_versions
    FOR ALL USING (
        model_id IN (SELECT model_id FROM socialcandor_schema.ml_models WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
        OR socialcandor_schema.is_admin()
    );

-- Deployment log: admins only
CREATE POLICY deployment_log_admin_policy ON socialcandor_schema.ml_model_deployment_log
    FOR ALL USING (socialcandor_schema.is_admin());

-- Ethics board: members can view; admins manage
CREATE POLICY ethics_board_member_policy ON socialcandor_schema.ai_ethics_review_board
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY ethics_board_admin_policy ON socialcandor_schema.ai_ethics_review_board
    FOR ALL USING (socialcandor_schema.is_admin());

-- Impact assessments: assessor sees own; admins all
CREATE POLICY ai_assessment_self_policy ON socialcandor_schema.ai_impact_assessment
    FOR SELECT USING (assessor_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY ai_assessment_admin_policy ON socialcandor_schema.ai_impact_assessment
    FOR ALL USING (socialcandor_schema.is_admin());

