-- Enum: 1 - moderation_rule_type
-- Description: Defines the types of rules used in automated content moderation.
-- Business Case: Categorize rules for efficient management and execution.
-- Feature Reference: MOD04 (Automated Moderation)
-- =================================================================================================
CREATE TYPE socialcandor_schema.moderation_rule_type AS ENUM (
    'KEYWORD',           -- Simple keyword or phrase matching
    'REGEX',             -- Regular expression pattern matching
    'ML_SCORE',          -- Machine learning model score threshold (e.g., toxicity)
    'USER_REPUTATION',   -- Based on user's trust/reputation score
    'IMAGE_HASH',        -- Image fingerprint matching (e.g., CSAM)
    'DOMAIN_BLACKLIST',  -- Blocked URL domains
    'BEHAVIORAL'         -- User behavior patterns (e.g., rapid posting)
);
COMMENT ON TYPE socialcandor_schema.moderation_rule_type IS 'Types of rules used in automated content moderation.';

-- Enum: 2 - moderation_action
-- Description: Actions that can be taken by a moderation rule.
-- Business Case: Define the consequence when a rule is triggered.
-- Feature Reference: MOD04 (Automated Moderation)
-- =================================================================================================
CREATE TYPE socialcandor_schema.moderation_action AS ENUM (
    'FLAG',              -- Flag for manual review
    'HIDE',              -- Hide from public view (soft delete)
    'BLOCK',             -- Prevent publishing
    'WARN_USER',         -- Send warning to user
    'ESCALATE',          -- Escalate to senior moderator
    'NOTIFY_ADMIN',      -- Notify administrators
    'LOG_ONLY'           -- Only log, no further action
);
COMMENT ON TYPE socialcandor_schema.moderation_action IS 'Actions that can be taken by a moderation rule.';

