-- =================================================================================================
-- TABLE: 1 - moderation_rules
-- Description: Defines automated content moderation rules.
-- Business Case: Automate content moderation by defining rules (keyword matching, pattern detection,
--                ML score thresholds) that trigger actions (flag, hide, escalate). Reduces manual
--                review load and ensures consistent policy enforcement across the platform.
-- KPIs:
--   1. Rule pass/fail rate
--   2. Average rule execution time
--   3. Number of content items flagged by rules per day
--   4. False positive rate of automated rules
--   5. Time saved in manual moderation (hours per week)
-- Feature References: MOD04 (Automated Moderation), SAFETY03 (Proactive Safety)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.moderation_rules (
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    rule_name VARCHAR(255) NOT NULL,
    rule_description TEXT,
    rule_type socialcandor_schema.moderation_rule_type NOT NULL,
    -- Rule configuration
    conditions JSONB NOT NULL,  -- Flexible JSON structure for rule parameters (e.g., keywords, regex, threshold)
    action socialcandor_schema.moderation_action NOT NULL,
    severity VARCHAR(20) NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    priority INTEGER NOT NULL DEFAULT 0 CHECK (priority >= 0),  -- Higher priority rules evaluated first
    is_active BOOLEAN DEFAULT TRUE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_moderation_rules_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_moderation_rules_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.moderation_rules IS 'Defines automated content moderation rules.';

-- =================================================================================================
-- TABLE: 2 - content_warnings
-- Description: Stores warnings applied to content (posts, comments, media) for sensitive material.
-- Business Case: Allow content creators to tag posts with sensitive content warnings that users
--                can optionally view. Also supports automated flagging for user safety.
-- KPIs:
--   1. Percentage of content with warnings
--   2. User engagement with warned content (click‑through rate on "show anyway")
--   3. Accuracy of automated warnings vs. user‑reported issues
--   4. Reduction in user complaints about unexpected sensitive content
--   5. Most common warning types
-- Feature References: SAFETY02 (Content Warnings), PRV06 (User Controls)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.content_warnings (
    warning_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    -- Polymorphic content reference
    content_type VARCHAR(20) NOT NULL CHECK (content_type IN ('POST', 'COMMENT', 'MEDIA')),
    content_id UUID NOT NULL,
    warning_type socialcandor_schema.content_warning_type NOT NULL,
    is_automated BOOLEAN DEFAULT FALSE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,  -- Could be user (if manual) or system (if automated)
    -- Constraints
    CONSTRAINT fk_content_warnings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_content_warning UNIQUE (content_type, content_id, warning_type)
);
COMMENT ON TABLE socialcandor_schema.content_warnings IS 'Stores warnings applied to content for sensitive material.';

-- =================================================================================================
-- TABLE: 3 - message_reactions
-- Description: Allows users to react to individual messages with emojis.
-- Business Case: Enable users to react to individual messages with emojis (like, love, laugh),
--                enhancing engagement and expressiveness in chats.
-- KPIs:
--   1. Reactions per message
--   2. Most used reaction types
--   3. User engagement lift in conversations with reactions
--   4. Reaction rate (reactions per 100 messages)
--   5. Time to first reaction on a message
-- Feature References: MSG04 (Message Reactions), ENG04 (Chat Engagement)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.message_reactions (
    reaction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    message_id UUID NOT NULL,
    user_id UUID NOT NULL,
    reaction_type socialcandor_schema.message_reaction_type NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_message_reactions_message FOREIGN KEY (message_id)
        REFERENCES socialcandor_schema.conversations_messages(message_id) ON DELETE CASCADE,
    CONSTRAINT fk_message_reactions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_message_reaction UNIQUE (message_id, user_id)
);
COMMENT ON TABLE socialcandor_schema.message_reactions IS 'Allows users to react to individual messages with emojis.';

-- =================================================================================================
-- TABLE: 4 - user_presence
-- Description: Tracks online/offline status and last activity of users for real‑time features.
-- Business Case: Track online/offline status and last active time for real‑time features
--                (chat indicators, friend lists). Can be updated via heartbeat from clients.
-- KPIs:
--   1. Concurrent online users (peak/avg)
--   2. Average session duration
--   3. User return rate (based on presence)
--   4. Presence update frequency
--   5. Device distribution of online users
-- Feature References: PRESENCE01 (User Presence), CHAT01 (Real‑time Chat)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_presence (
    presence_id BIGSERIAL PRIMARY KEY,  -- Using serial for high‑frequency updates
    user_id UUID NOT NULL UNIQUE,
    status socialcandor_schema.user_presence_status NOT NULL DEFAULT 'OFFLINE',
    last_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    device_type VARCHAR(50),  -- e.g., 'web', 'ios', 'android'
    session_id UUID,
    -- Constraints
    CONSTRAINT fk_user_presence_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_presence_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.user_presence IS 'Tracks online/offline status and last activity of users.';

-- =================================================================================================
-- TABLE: 5 - invoices
-- Description: Generates and tracks invoices for payments (subscriptions, marketplace purchases).
-- Business Case: Generate and track invoices for payments (subscriptions, marketplace purchases).
--                Needed for accounting, customer records, and tax compliance.
-- KPIs:
--   1. Number of invoices issued per month
--   2. Average invoice amount
--   3. Payment on‑time rate
--   4. Aging of unpaid invoices (days overdue)
--   5. Tax collected per jurisdiction
-- Feature References: BIL03 (Invoicing), FIN02 (Accounts Receivable)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.invoices (
    invoice_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    invoice_number VARCHAR(50) GENERATED ALWAYS AS (
        'INV-' || TO_CHAR(issue_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.invoice_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    subscription_id UUID,  -- Optional, if invoice is for a subscription
    -- Amounts
    amount NUMERIC(15,2) NOT NULL CHECK (amount >= 0),
    tax_amount NUMERIC(15,2) DEFAULT 0 CHECK (tax_amount >= 0),
    total_amount NUMERIC(15,2) GENERATED ALWAYS AS (amount + tax_amount) STORED,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    -- Dates
    issue_date DATE NOT NULL DEFAULT CURRENT_DATE,
    due_date DATE NOT NULL,
    paid_at TIMESTAMP WITH TIME ZONE,
    -- Status
    status socialcandor_schema.invoice_status NOT NULL DEFAULT 'DRAFT',
    -- Links
    payment_transaction_id UUID,  -- optional, when paid via wallet
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_invoices_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_invoices_subscription FOREIGN KEY (subscription_id)
        REFERENCES socialcandor_schema.user_subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_invoices_payment FOREIGN KEY (payment_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
    CONSTRAINT chk_invoice_dates CHECK (due_date >= issue_date)
);
COMMENT ON TABLE socialcandor_schema.invoices IS 'Generates and tracks invoices for payments.';

-- =================================================================================================
-- TABLE: 6 - payouts
-- Description: Manages payments to creators/advertisers from their earnings.
-- Business Case: Manage payments to creators/advertisers from their earnings. Tracks payout
--                requests, processing, and settlement.
-- KPIs:
--   1. Total payout amount per period
--   2. Average payout per user
--   3. Payout processing time (from request to completion)
--   4. Payout failure rate
--   5. Method distribution (bank, PayPal, etc.)
-- Feature References: PAY04 (Payouts), CRE02 (Creator Payments)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.payouts (
    payout_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    payout_number VARCHAR(50) GENERATED ALWAYS AS (
        'PO-' || TO_CHAR(requested_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.payout_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    amount NUMERIC(15,2) NOT NULL CHECK (amount >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    payout_method socialcandor_schema.payout_method NOT NULL,
    status socialcandor_schema.payout_status NOT NULL DEFAULT 'PENDING',
    -- References
    wallet_transaction_id UUID,  -- when paid out
    -- Dates
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMP WITH TIME ZONE,
    -- Details
    payout_details JSONB,  -- e.g., bank account last4, PayPal email
    failure_reason TEXT,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_payouts_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_payouts_transaction FOREIGN KEY (wallet_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.payouts IS 'Manages payments to creators/advertisers from their earnings.';

-- =================================================================================================
-- TABLE: 7 - tax_rates
-- Description: Stores tax rates by jurisdiction for automatic calculation on purchases.
-- Business Case: Store tax rates by jurisdiction (country, state) for automatic calculation
--                of sales tax/VAT on purchases.
-- KPIs:
--   1. Number of active tax jurisdictions
--   2. Tax rate change frequency
--   3. Coverage of tax jurisdictions (vs. customer locations)
--   4. Tax calculation accuracy (audit)
--   5. Time to update rates when regulations change
-- Feature References: TAX02 (Tax Management), FIN03 (Tax Compliance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tax_rates (
    tax_rate_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    jurisdiction_type VARCHAR(20) NOT NULL CHECK (jurisdiction_type IN ('COUNTRY', 'STATE', 'PROVINCE', 'CITY', 'COUNTY')),
    jurisdiction_code VARCHAR(10) NOT NULL,  -- e.g., 'US', 'CA', 'DE', 'NYC'
    jurisdiction_name VARCHAR(100),
    tax_rate_percent NUMERIC(5,2) NOT NULL CHECK (tax_rate_percent >= 0 AND tax_rate_percent <= 100),
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL OR effective_to >= CURRENT_DATE) STORED,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT uk_tax_rate_jurisdiction UNIQUE (jurisdiction_type, jurisdiction_code, effective_from)
);
COMMENT ON TABLE socialcandor_schema.tax_rates IS 'Stores tax rates by jurisdiction for automatic calculation on purchases.';

-- =================================================================================================
-- TABLE: 8 - marketplace_orders
-- Description: Tracks orders placed in the marketplace.
-- Business Case: Track orders placed in the marketplace, linking listings to buyers,
--                with payment and fulfillment status.
-- KPIs:
--   1. Order volume per day/week/month
--   2. Average order value
--   3. Conversion rate (listings to orders)
--   4. Fulfillment time (from order to delivery)
--   5. Cancellation/refund rate
-- Feature References: MPL03 (Order Management), FIN04 (Order Revenue)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.marketplace_orders (
    order_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    order_number VARCHAR(50) GENERATED ALWAYS AS (
        'ORD-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.marketplace_order_seq')::TEXT, 6, '0')
    ) STORED,
    listing_id UUID NOT NULL,
    buyer_user_id UUID NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(15,2) NOT NULL CHECK (unit_price >= 0),
    total_price NUMERIC(15,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    order_status socialcandor_schema.order_status NOT NULL DEFAULT 'PENDING',
    -- Payment
    payment_transaction_id UUID,
    paid_at TIMESTAMP WITH TIME ZONE,
    -- Fulfillment
    shipping_address TEXT,
    tracking_number VARCHAR(100),
    delivered_at TIMESTAMP WITH TIME ZONE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_orders_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE RESTRICT,
    CONSTRAINT fk_orders_buyer FOREIGN KEY (buyer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_orders_payment FOREIGN KEY (payment_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.marketplace_orders IS 'Tracks orders placed in the marketplace.';

-- =================================================================================================
-- TABLE: 9 - marketplace_reviews
-- Description: Allows buyers to review products/sellers.
-- Business Case: Allow buyers to review products/sellers, building trust and reputation
--                in the marketplace.
-- KPIs:
--   1. Average rating per product/seller
--   2. Review volume over time
--   3. Percentage of orders with reviews
--   4. Verified purchase review rate
--   5. Helpfulness score of reviews
-- Feature References: MPL04 (Reviews & Ratings), REP02 (Seller Reputation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.marketplace_reviews (
    review_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    order_id UUID NOT NULL,
    listing_id UUID NOT NULL,
    reviewer_user_id UUID NOT NULL,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    review_text TEXT,
    is_verified_purchase BOOLEAN DEFAULT FALSE,
    helpful_count INTEGER DEFAULT 0 CHECK (helpful_count >= 0),
    not_helpful_count INTEGER DEFAULT 0 CHECK (not_helpful_count >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_reviews_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE CASCADE,
    CONSTRAINT fk_reviews_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
    CONSTRAINT fk_reviews_reviewer FOREIGN KEY (reviewer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_review_order UNIQUE (order_id)  -- one review per order
);
COMMENT ON TABLE socialcandor_schema.marketplace_reviews IS 'Allows buyers to review products/sellers.';

-- =================================================================================================
-- TABLE: 10 - course_modules
-- Description: Modules within an educational course.
-- Business Case: Structure educational content into modules, enabling better organization and
--                progress tracking.
-- KPIs:
--   1. Number of modules per course
--   2. Average module completion rate
--   3. Time spent per module
--   4. Module drop‑off rate
--   5. Correlation between module order and completion
-- Feature References: EDU05 (Course Structure)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.course_modules (
    module_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    course_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_modules_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE,
    CONSTRAINT uk_module_order UNIQUE (course_id, sort_order)
);
COMMENT ON TABLE socialcandor_schema.course_modules IS 'Modules within an educational course.';

-- =================================================================================================
-- TABLE: 11 - course_lessons
-- Description: Lessons within a course module.
-- Business Case: Provide granular learning units with different content types.
-- KPIs:
--   1. Lesson completion rate
--   2. Average time spent per lesson
--   3. Most engaged content types
--   4. Quiz pass rate (for quiz lessons)
--   5. Drop‑off rate by lesson position
-- Feature References: EDU06 (Lesson Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.course_lessons (
    lesson_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    module_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    content_type socialcandor_schema.course_content_type NOT NULL,
    content_url VARCHAR(500),  -- for video, pdf, etc.
    content_text TEXT,          -- for text lessons
    duration_minutes INTEGER CHECK (duration_minutes >= 0),
    sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_lessons_module FOREIGN KEY (module_id)
        REFERENCES socialcandor_schema.course_modules(module_id) ON DELETE CASCADE,
    CONSTRAINT uk_lesson_order UNIQUE (module_id, sort_order)
);
COMMENT ON TABLE socialcandor_schema.course_lessons IS 'Lessons within a course module.';

-- =================================================================================================
-- TABLE: 12 - event_sessions
-- Description: Individual sessions within a multi‑session event.
-- Business Case: For multi‑session events (conferences, workshops), track individual sessions
--                with speakers, times, and locations.
-- KPIs:
--   1. Average attendance per session
--   2. Session engagement (questions, feedback)
--   3. Speaker popularity
--   4. Session drop‑off rate (for virtual)
--   5. Session capacity utilization
-- Feature References: EVT03 (Event Sessions), ENG05 (Session Engagement)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.event_sessions (
    session_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    event_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE NOT NULL,
    location_type socialcandor_schema.event_session_location_type NOT NULL,
    location_details JSONB,  -- e.g., room name, virtual meeting URL
    speaker_user_id UUID,    -- could be multiple; for simplicity one main speaker
    max_attendees INTEGER CHECK (max_attendees >= 0),
    current_attendees INTEGER DEFAULT 0 CHECK (current_attendees >= 0),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_sessions_event FOREIGN KEY (event_id)
        REFERENCES socialcandor_schema.events(event_id) ON DELETE CASCADE,
    CONSTRAINT fk_sessions_speaker FOREIGN KEY (speaker_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_session_times CHECK (end_time > start_time)
);
COMMENT ON TABLE socialcandor_schema.event_sessions IS 'Individual sessions within a multi‑session event.';

-- =================================================================================================
-- TABLE: 13 - data_lineage
-- Description: Documents the flow of data from source to destination for impact analysis.
-- Business Case: Document the flow of data from source to destination (tables, pipelines, reports)
--                to support impact analysis, debugging, and compliance.
-- KPIs:
--   1. Lineage coverage (percentage of assets with lineage)
--   2. Depth of lineage (average number of hops)
--   3. Number of upstream/downstream dependencies per asset
--   4. Time to discover impact of a change
--   5. Accuracy of lineage (verification rate)
-- Feature References: DQL01 (Data Lineage), GOV06 (Data Governance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_lineage (
    lineage_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    source_asset_id UUID NOT NULL,
    source_asset_type socialcandor_schema.data_lineage_asset_type NOT NULL,
    target_asset_id UUID NOT NULL,
    target_asset_type socialcandor_schema.data_lineage_asset_type NOT NULL,
    transformation_description TEXT,
    pipeline_id UUID,  -- optional, if via a pipeline
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    -- Constraints
    CONSTRAINT fk_lineage_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT uk_lineage UNIQUE (source_asset_id, source_asset_type, target_asset_id, target_asset_type)
);
COMMENT ON TABLE socialcandor_schema.data_lineage IS 'Documents the flow of data from source to destination for impact analysis.';

-- =================================================================================================
-- TABLE: 14 - feature_definitions
-- Description: Defines features used in machine learning models.
-- Business Case: Manage features used in machine learning models, storing definitions and
--                metadata for feature engineering and model training.
-- KPIs:
--   1. Number of defined features
--   2. Feature usage across models
--   3. Feature freshness (last update)
--   4. Feature stability over time
--   5. Coverage of feature definitions (documentation)
-- Feature References: MLOP05 (Feature Store)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_definitions (
    feature_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    feature_code VARCHAR(100) GENERATED ALWAYS AS (
        'FTR-' || LPAD(nextval('socialcandor_schema.feature_definition_seq')::TEXT, 6, '0')
    ) STORED,
    feature_name VARCHAR(255) NOT NULL,
    feature_type socialcandor_schema.feature_type NOT NULL,
    description TEXT,
    owner_user_id UUID,
    data_source VARCHAR(500),  -- e.g., SQL query, table name
    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_feature_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.feature_definitions IS 'Defines features used in machine learning models.';

-- =================================================================================================
-- TABLE: 15 - feature_values
-- Description: Stores time‑series values for features, used for training and inference.
-- Business Case: Store feature values over time for model training and online inference.
-- KPIs:
--   1. Number of feature records
--   2. Data volume per feature
--   3. Feature value freshness (lag from source)
--   4. Coverage of feature values (missing rate)
--   5. Query performance for feature retrieval
-- Feature References: MLOP06 (Feature Values)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_values (
    value_id BIGSERIAL PRIMARY KEY,
    feature_id UUID NOT NULL,
    entity_id UUID NOT NULL,  -- e.g., user_id, post_id
    value NUMERIC,            -- for numeric features
    value_string TEXT,        -- for categorical/text
    value_boolean BOOLEAN,
    value_json JSONB,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_feature_values_feature FOREIGN KEY (feature_id)
        REFERENCES socialcandor_schema.feature_definitions(feature_id) ON DELETE CASCADE,
    CONSTRAINT chk_feature_value CHECK (
        (value IS NOT NULL) OR (value_string IS NOT NULL) OR (value_boolean IS NOT NULL) OR (value_json IS NOT NULL)
    )
);
COMMENT ON TABLE socialcandor_schema.feature_values IS 'Stores time‑series values for features, used for training and inference.';

-- =================================================================================================
-- TABLE: 16 - model_predictions
-- Description: Logs every prediction made by a machine learning model.
-- Business Case: Log every prediction made by a model, enabling audit, drift detection,
--                and performance monitoring.
-- KPIs:
--   1. Prediction volume per model/version
--   2. Average prediction latency
--   3. Model drift over time (compared to actuals)
--   4. Prediction accuracy (when ground truth available)
--   5. Number of predictions per user
-- Feature References: MLOP07 (Prediction Logging)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_predictions (
    prediction_id BIGSERIAL PRIMARY KEY,
    model_version_id UUID NOT NULL,
    user_id UUID,  -- optional, if prediction is for a user
    input_data JSONB NOT NULL,
    output_data JSONB NOT NULL,
    prediction_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    latency_ms INTEGER CHECK (latency_ms >= 0),
    -- For drift/performance tracking
    actual_outcome JSONB,  -- to be filled later when ground truth known
    is_correct BOOLEAN,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_predictions_model_version FOREIGN KEY (model_version_id)
        REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_predictions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.model_predictions IS 'Logs every prediction made by a machine learning model.';

-- =================================================================================================
-- TABLE: 17 - processing_activities
-- Description: Record of processing activities (RoPA) as required by GDPR Article 30.
-- Business Case: Maintain a record of processing activities (RoPA) as required by GDPR Article 30,
--                documenting purpose, data categories, recipients, etc.
-- KPIs:
--   1. Number of processing activities documented
--   2. Coverage of data processing (percentage of data assets covered)
--   3. Timeliness of reviews (activities reviewed on time)
--   4. Number of activities with high risk
--   5. Compliance rate with legal basis documentation
-- Feature References: GDPR07 (Record of Processing), COMP11 (Registrar Compliance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.processing_activities (
    activity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    activity_number VARCHAR(50) GENERATED ALWAYS AS (
        'ROPA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.processing_activity_seq')::TEXT, 6, '0')
    ) STORED,
    activity_name VARCHAR(255) NOT NULL,
    purpose TEXT NOT NULL,
    legal_basis socialcandor_schema.processing_activity_legal_basis NOT NULL,
    data_categories TEXT[] NOT NULL,
    data_subjects TEXT[] NOT NULL,
    recipients TEXT[],
    transfers_outside_eea BOOLEAN DEFAULT FALSE,
    transfer_safeguards TEXT,
    retention_period_days INTEGER CHECK (retention_period_days >= 0),
    security_measures TEXT,
    dpia_reference UUID,  -- link to privacy_impact_assessments
    dpo_review_date DATE,
    next_review_date DATE,
    is_active BOOLEAN DEFAULT TRUE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_processing_dpia FOREIGN KEY (dpia_reference)
        REFERENCES socialcandor_schema.privacy_impact_assessments(pia_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.processing_activities IS 'Record of processing activities (RoPA) as required by GDPR Article 30.';

-- =================================================================================================
-- TABLE: 18 - vendor_assessments
-- Description: Evaluates risks associated with third‑party vendors who process data.
-- Business Case: Evaluate and track risks associated with third‑party vendors who process data,
--                ensuring compliance with privacy and security standards.
-- KPIs:
--   1. Number of vendors assessed
--   2. Vendor risk distribution (low/medium/high)
--   3. Assessment completion rate
--   4. Time to remediate findings
--   5. Number of vendors with expired assessments
-- Feature References: VND01 (Vendor Management), COMP12 (Third‑Party Risk)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.vendor_assessments (
    assessment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    assessment_number VARCHAR(50) GENERATED ALWAYS AS (
        'VAS-' || TO_CHAR(assessment_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.vendor_assessment_seq')::TEXT, 6, '0')
    ) STORED,
    vendor_name VARCHAR(255) NOT NULL,
    vendor_type socialcandor_schema.vendor_type NOT NULL,
    assessment_date DATE NOT NULL,
    risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
    findings JSONB,
    remediation_plan TEXT,
    next_review_date DATE,
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'EXPIRED', 'OBSOLETE')),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.vendor_assessments IS 'Evaluates risks associated with third‑party vendors.';

-- =================================================================================================
-- TABLE: 19 - backup_logs
-- Description: Logs database and file backups for disaster recovery.
-- Business Case: Log database and file backups for disaster recovery, including status,
--                size, and location. Helps meet RPO/RTO requirements.
-- KPIs:
--   1. Backup success rate
--   2. Backup duration trend
--   3. Backup size growth
--   4. Recovery time from backups (tested)
--   5. Backup coverage (frequency)
-- Feature References: BCP03 (Backup Management), OPS04 (Disaster Recovery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.backup_logs (
    log_id BIGSERIAL PRIMARY KEY,
    backup_type socialcandor_schema.backup_type NOT NULL,
    backup_start TIMESTAMP WITH TIME ZONE NOT NULL,
    backup_end TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.backup_status NOT NULL,
    size_bytes BIGINT CHECK (size_bytes >= 0),
    location_url VARCHAR(500),
    error_message TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Metadata
    backup_server VARCHAR(255),
    backup_script_version VARCHAR(50)
);
COMMENT ON TABLE socialcandor_schema.backup_logs IS 'Logs database and file backups for disaster recovery.';

-- =================================================================================================
-- TABLE: 20 - capacity_forecasts
-- Description: Forecasts resource usage to plan infrastructure upgrades.
-- Business Case: Forecast resource usage (storage, compute, API calls) to plan infrastructure
--                upgrades and avoid outages.
-- KPIs:
--   1. Forecast accuracy (actual vs predicted)
--   2. Resource utilization trend
--   3. Time to capacity exhaustion based on forecast
--   4. Number of capacity incidents (outages due to capacity)
--   5. Forecast coverage (percentage of resources forecasted)
-- Feature References: OPS03 (Capacity Planning), SYS08 (Infrastructure Monitoring)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.capacity_forecasts (
    forecast_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    resource_type socialcandor_schema.capacity_resource_type NOT NULL,
    forecast_date DATE NOT NULL,
    predicted_value NUMERIC NOT NULL,
    actual_value NUMERIC,  -- to be filled later for accuracy tracking
    unit VARCHAR(20),      -- e.g., 'GB', 'cores', 'requests'
    model_used VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    -- Constraints
    CONSTRAINT fk_forecasts_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT
);
COMMENT ON TABLE socialcandor_schema.capacity_forecasts IS 'Forecasts resource usage to plan infrastructure upgrades.';

-- =================================================================================================
-- TABLE: 21 - security_incidents
-- Description: Specialized incident tracking for security‑related events.
-- Business Case: Specialized incident tracking for security‑related events (breaches, intrusions,
--                policy violations), extending general incident management.
-- KPIs:
--   1. Mean time to detect (MTTD)
--   2. Mean time to respond (MTTR)
--   3. Incident volume by type/severity
--   4. Number of incidents closed vs. open
--   5. Recurring incident rate
-- Feature References: SEC13 (Security Incident Management), INC02 (Incident Response)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.security_incidents (
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'SEC-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.security_incident_seq')::TEXT, 6, '0')
    ) STORED,
    incident_type socialcandor_schema.security_incident_type NOT NULL,
    severity socialcandor_schema.security_incident_severity NOT NULL,
    description TEXT NOT NULL,
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    contained_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    root_cause TEXT,
    affected_systems TEXT[],
    affected_users_count INTEGER CHECK (affected_users_count >= 0),
    data_breach BOOLEAN DEFAULT FALSE,  -- link to data_breaches if applicable
    lessons_learned TEXT,
    status VARCHAR(20) DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    reported_by UUID,
    assigned_to UUID,
    -- Constraints
    CONSTRAINT fk_security_incidents_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_security_incidents_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.security_incidents IS 'Specialized incident tracking for security‑related events.';

-- =================================================================================================
-- TABLE: 22 - general_ledger
-- Description: Records double‑entry accounting entries for all financial transactions.
-- Business Case: Record double‑entry accounting entries for all financial transactions,
--                supporting audit trails and financial reporting.
-- KPIs:
--   1. Number of ledger entries per period
--   2. Total debits/credits per account
--   3. Trial balance accuracy
--   4. Time to close books
--   5. Audit trail completeness
-- Feature References: FIN01 (General Ledger), AUD08 (Financial Audit)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.general_ledger (
    entry_id BIGSERIAL PRIMARY KEY,
    entry_number VARCHAR(50) GENERATED ALWAYS AS (
        'GL-' || TO_CHAR(entry_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.general_ledger_seq')::TEXT, 6, '0')
    ) STORED,
    transaction_id UUID,  -- link to source transaction (wallet_transactions, invoices, etc.)
    account_code VARCHAR(50) NOT NULL,
    account_type socialcandor_schema.ledger_account_type NOT NULL,
    debit_amount NUMERIC(15,2) DEFAULT 0 CHECK (debit_amount >= 0),
    credit_amount NUMERIC(15,2) DEFAULT 0 CHECK (credit_amount >= 0),
    entry_date DATE NOT NULL,
    description TEXT,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    -- Constraints
    CONSTRAINT fk_ledger_transaction FOREIGN KEY (transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
    CONSTRAINT chk_debit_credit CHECK (
        (debit_amount > 0 AND credit_amount = 0) OR
        (credit_amount > 0 AND debit_amount = 0)
    )
);
COMMENT ON TABLE socialcandor_schema.general_ledger IS 'Records double‑entry accounting entries for all financial transactions.';

