    FOR SELECT USING (TRUE);  -- anyone can see presence status (or restrict to friends)

-- =================================================================================================
-- TRIGGERS FOR UPDATED_AT
-- =================================================================================================

-- Create trigger function if not exists
CREATE OR REPLACE FUNCTION socialcandor_schema.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    NEW.updated_by = current_setting('app.current_user_id')::UUID;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply to tables with updated_at column
CREATE TRIGGER trg_moderation_rules_updated_at
    BEFORE UPDATE ON socialcandor_schema.moderation_rules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_content_warnings_updated_at
    BEFORE UPDATE ON socialcandor_schema.content_warnings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

CREATE TRIGGER trg_message_reactions_updated_at
    BEFORE UPDATE ON socialcandor_schema.message_reactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

