-- Enum: DPE01 - moderation_rule_action
-- Description: Possible actions triggered by a moderation rule
-- Business Case: Defines what happens when a rule matches content (flag, hide, block)
-- Feature Reference: MOD04 (Automated Moderation)
--================================================================================================
CREATE TYPE socialcandor_schema.moderation_rule_action AS ENUM (
    'FLAG',        -- Mark for human review
    'HIDE',        -- Hide from public view (user can still see)
    'BLOCK',       -- Prevent publication entirely
    'WARN_USER',   -- Send warning to content creator
    'ESCALATE'     -- Immediately escalate to senior moderator
);
COMMENT ON TYPE socialcandor_schema.moderation_rule_action IS 'Actions triggered by automated moderation rules';

-- Enum: DPE02 - content_warning_type
-- Description: Types of sensitive content warnings
-- Business Case: Allow users to tag content with appropriate warnings (violence, nudity, etc.)
-- Feature Reference: MOD05 (Content Warnings)
--================================================================================================
CREATE TYPE socialcandor_schema.content_warning_type AS ENUM (
    'VIOLENCE',
    'NUDITY',
    'SPOILER',
    'SELF_HARM',
    'HATE_SPEECH',
    'GRAPHIC_CONTENT',
    'DRUGS',
    'OTHER'
);
COMMENT ON TYPE socialcandor_schema.content_warning_type IS 'Types of sensitive content warnings';

-- Enum: DPE03 - flag_reason
-- Description: Reasons users can flag content for moderation
-- Business Case: Standardize flagging reasons for better moderation triage
-- Feature Reference: MOD06 (Flagging)
--================================================================================================
CREATE TYPE socialcandor_schema.flag_reason AS ENUM (
    'SPAM',
    'HARASSMENT',
    'HATE_SPEECH',
    'VIOLENCE',
    'NUDITY',
    'FALSE_INFORMATION',
    'IMPERSONATION',
    'COPYRIGHT',
    'OTHER'
);
COMMENT ON TYPE socialcandor_schema.flag_reason IS 'Reasons users can flag content';

-- Enum: DPE04 - invoice_status
-- Description: Lifecycle status of an invoice
-- Business Case: Track invoice from creation to payment/refund
-- Feature Reference: BIL03 (Invoicing)
--================================================================================================
CREATE TYPE socialcandor_schema.invoice_status AS ENUM (
    'DRAFT',
    'PENDING',
    'PAID',
    'OVERDUE',
    'CANCELLED',
    'REFUNDED',
    'PARTIALLY_PAID'
);
COMMENT ON TYPE socialcandor_schema.invoice_status IS 'Lifecycle status of an invoice';

-- Enum: DPE05 - refund_status
-- Description: Status of a refund request
-- Business Case: Manage refund workflow from request to completion
-- Feature Reference: BIL04 (Refunds)
--================================================================================================
CREATE TYPE socialcandor_schema.refund_status AS ENUM (
    'REQUESTED',
    'APPROVED',
    'REJECTED',
    'PROCESSED',
    'CANCELLED'
);
COMMENT ON TYPE socialcandor_schema.refund_status IS 'Status of a refund request';

-- Enum: DPE06 - payout_status
