--================================================================================================
-- 1. SOCIAL & MESSAGING ENHANCEMENTS
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: message_reactions
-- Description: Allows users to react to individual messages with emojis
-- Business Case: Enhances engagement in chats by enabling quick emotional responses (like, love, laugh)
--                without cluttering the conversation with extra messages. Provides valuable engagement
--                analytics and helps users express themselves more naturally.
-- KPIs:
--   1. Number of reactions per message
--   2. Reaction distribution by type (popular emojis)
--   3. User reaction frequency
--   4. Impact on conversation retention
--   5. Time to first reaction after message sent
-- Feature Reference: MSG04 (Message Reactions)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.message_reactions (
    reaction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    message_id UUID NOT NULL,
    user_id UUID NOT NULL,
    reaction_type VARCHAR(30) NOT NULL CHECK (reaction_type IN ('LIKE', 'LOVE', 'LAUGH', 'WOW', 'SAD', 'ANGRY')),
    reacted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_message_reactions_message FOREIGN KEY (message_id)
        REFERENCES socialcandor_schema.conversations_messages(message_id) ON DELETE CASCADE,
    CONSTRAINT fk_message_reactions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_message_reaction UNIQUE (user_id, message_id)
);
COMMENT ON TABLE socialcandor_schema.message_reactions IS 'User reactions to individual messages';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_message_reactions_message ON socialcandor_schema.message_reactions(message_id);
CREATE INDEX IF NOT EXISTS idx_message_reactions_user ON socialcandor_schema.message_reactions(user_id);

-- RLS
ALTER TABLE socialcandor_schema.message_reactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_reactions_self_policy ON socialcandor_schema.message_reactions
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY message_reactions_admin_policy ON socialcandor_schema.message_reactions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger for updated_at
CREATE TRIGGER trg_message_reactions_updated_at
    BEFORE UPDATE ON socialcandor_schema.message_reactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: user_presence
-- Description: Tracks user online/offline status and last activity
-- Business Case: Enables real‑time features like “online” indicators in chat and friend lists,
--                improving user experience and facilitating instant communication. Also helps
--                in capacity planning for real‑time services.
-- KPIs:
--   1. Concurrent online users
--   2. Average session duration
--   3. User idle time distribution
--   4. Peak online times
--   5. Presence update frequency
-- Feature Reference: SOC16 (User Presence)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_presence (
    presence_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL UNIQUE,
    status VARCHAR(20) NOT NULL CHECK (status IN ('ONLINE', 'OFFLINE', 'AWAY', 'DO_NOT_DISTURB')),
    last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    current_device_id UUID,
    current_session_id UUID,
    custom_status TEXT,
    status_emoji VARCHAR(10),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_user_presence_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_presence_device FOREIGN KEY (current_device_id)
        REFERENCES socialcandor_schema.user_devices(device_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_presence_session FOREIGN KEY (current_session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.user_presence IS 'Real‑time user presence status';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_user_presence_status ON socialcandor_schema.user_presence(status, last_seen_at);
CREATE INDEX IF NOT EXISTS idx_user_presence_last_seen ON socialcandor_schema.user_presence(last_seen_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.user_presence ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_presence_self_policy ON socialcandor_schema.user_presence
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_presence_friends_policy ON socialcandor_schema.user_presence
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.friends f
        WHERE f.user_id = current_setting('app.current_user_id')::UUID
          AND f.friend_user_id = user_presence.user_id
          AND f.status = 'ACCEPTED'
    ));
CREATE POLICY user_presence_admin_policy ON socialcandor_schema.user_presence
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_user_presence_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_presence
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: message_drafts
-- Description: Stores unsent message drafts for later completion
-- Business Case: Allows users to compose messages across sessions without losing progress,
--                reducing friction and improving user experience in messaging.
-- KPIs:
--   1. Number of drafts created per user
--   2. Draft completion rate (conversion to sent messages)
--   3. Average time between draft creation and sending
--   4. Draft abandonment rate
--   5. Most common draft content types (text, media)
-- Feature Reference: MSG05 (Message Drafts)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.message_drafts (
    draft_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    conversation_id UUID,
    recipient_user_id UUID,  -- For new conversations not yet created
    content_text TEXT,
    content_json JSONB,
    media_attachments UUID[],  -- Could link to media tables
    reply_to_message_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,  -- Optional auto‑delete after some days
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_message_drafts_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_message_drafts_conversation FOREIGN KEY (conversation_id)
        REFERENCES socialcandor_schema.conversations(conversation_id) ON DELETE CASCADE,
    CONSTRAINT fk_message_drafts_recipient FOREIGN KEY (recipient_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_message_drafts_reply FOREIGN KEY (reply_to_message_id)
        REFERENCES socialcandor_schema.conversations_messages(message_id) ON DELETE SET NULL,
    CONSTRAINT chk_draft_target CHECK (
        (conversation_id IS NOT NULL) OR (recipient_user_id IS NOT NULL)
    )
);
COMMENT ON TABLE socialcandor_schema.message_drafts IS 'User drafts for unsent messages';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_message_drafts_user ON socialcandor_schema.message_drafts(user_id);
CREATE INDEX IF NOT EXISTS idx_message_drafts_conversation ON socialcandor_schema.message_drafts(conversation_id) WHERE conversation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_message_drafts_expires ON socialcandor_schema.message_drafts(expires_at) WHERE expires_at IS NOT NULL;

-- RLS
ALTER TABLE socialcandor_schema.message_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_drafts_self_policy ON socialcandor_schema.message_drafts
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY message_drafts_admin_policy ON socialcandor_schema.message_drafts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_message_drafts_updated_at
    BEFORE UPDATE ON socialcandor_schema.message_drafts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: relationship_categories
-- Description: Allows users to categorize friends (e.g., family, close friends, work)
-- Business Case: Enables finer privacy controls and content targeting (e.g., share posts only with “family”).
--                Improves user experience by letting users organize their social graph.
-- KPIs:
--   1. Number of categories created per user
--   2. Average friends per category
--   3. Usage of category‑based privacy settings
--   4. Category edit frequency
--   5. User satisfaction with privacy controls
-- Feature Reference: SOC17 (Relationship Categories)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.relationship_categories (
    category_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    category_name VARCHAR(50) NOT NULL,
    description VARCHAR(200),
    color_hex CHAR(7) CHECK (color_hex ~ '^#[0-9A-Fa-f]{6}$'),
    icon_name VARCHAR(50),
    sort_order INTEGER DEFAULT 0 CHECK (sort_order >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_relationship_categories_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_category UNIQUE (user_id, category_name)
);
COMMENT ON TABLE socialcandor_schema.relationship_categories IS 'User‑defined categories for organizing friends';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_relationship_categories_user ON socialcandor_schema.relationship_categories(user_id);

-- RLS
ALTER TABLE socialcandor_schema.relationship_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY rel_categories_self_policy ON socialcandor_schema.relationship_categories
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY rel_categories_admin_policy ON socialcandor_schema.relationship_categories
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_relationship_categories_updated_at
    BEFORE UPDATE ON socialcandor_schema.relationship_categories
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: message_search_index
-- Description: Pre‑computed search tokens for messages to improve search performance
-- Business Case: Offloads heavy text search processing from main message table, enabling fast,
--                full‑text search across messages with minimal impact on real‑time messaging.
-- KPIs:
--   1. Search query latency
--   2. Index freshness (time from message creation to indexing)
--   3. Search result relevance (click‑through rate)
--   4. Storage overhead
--   5. Index update frequency
-- Feature Reference: SRCH04 (Message Search)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.message_search_index (
    index_id BIGSERIAL PRIMARY KEY,
    message_id UUID NOT NULL UNIQUE,
    conversation_id UUID NOT NULL,
    sender_user_id UUID NOT NULL,
    content_text TEXT,  -- The original message text (or stripped)
    search_vector TSVECTOR,  -- Pre‑computed tsvector for full‑text search
    language VARCHAR(10) DEFAULT 'english',
    indexed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_search_index_message FOREIGN KEY (message_id)
        REFERENCES socialcandor_schema.conversations_messages(message_id) ON DELETE CASCADE,
    CONSTRAINT fk_search_index_conversation FOREIGN KEY (conversation_id)
        REFERENCES socialcandor_schema.conversations(conversation_id) ON DELETE CASCADE,
    CONSTRAINT fk_search_index_sender FOREIGN KEY (sender_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.message_search_index IS 'Pre‑computed search tokens for fast message search';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_search_index_vector ON socialcandor_schema.message_search_index USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS idx_search_index_conversation ON socialcandor_schema.message_search_index(conversation_id);

-- RLS (users can only search messages they are part of)
ALTER TABLE socialcandor_schema.message_search_index ENABLE ROW LEVEL SECURITY;
CREATE POLICY search_index_participant_policy ON socialcandor_schema.message_search_index
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM socialcandor_schema.conversations_users cu
            WHERE cu.conversation_id = message_search_index.conversation_id
              AND cu.user_id = current_setting('app.current_user_id')::UUID
        )
    );
CREATE POLICY search_index_admin_policy ON socialcandor_schema.message_search_index
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger to update search_vector on content change (simplified; in practice you'd use a trigger on messages)
-- This assumes a separate process populates this table.

--================================================================================================
-- 2. PAYMENTS & MONETIZATION
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: tax_rates
-- Description: Stores tax rates by jurisdiction for automatic calculation of sales tax/VAT
-- Business Case: Ensures accurate tax collection at point of sale, adapts to different regions,
--                and simplifies compliance with local tax laws. Supports dynamic rate changes.
-- KPIs:
--   1. Tax calculation accuracy (error rate)
--   2. Jurisdiction coverage
--   3. Time to update rates when laws change
--   4. Number of tax overrides/exceptions
--   5. Audit trail completeness
-- Feature Reference: TAX01 (Tax Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.tax_rates (
    tax_rate_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    jurisdiction_type VARCHAR(20) NOT NULL CHECK (jurisdiction_type IN ('COUNTRY', 'STATE', 'COUNTY', 'CITY', 'OTHER')),
    jurisdiction_code VARCHAR(10) NOT NULL,  -- e.g., 'US', 'CA', 'NY'
    jurisdiction_name VARCHAR(100) NOT NULL,
    tax_type VARCHAR(20) NOT NULL CHECK (tax_type IN ('SALES', 'VAT', 'GST', 'PST', 'HST', 'OTHER')),
    rate_percent NUMERIC(7,4) NOT NULL CHECK (rate_percent >= 0 AND rate_percent <= 100),
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_compound BOOLEAN DEFAULT FALSE,  -- Whether tax is applied after other taxes
    applies_to VARCHAR(20) CHECK (applies_to IN ('ALL', 'DIGITAL', 'PHYSICAL', 'SERVICE')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT chk_tax_rate_dates CHECK (effective_to IS NULL OR effective_to >= effective_from)
);
COMMENT ON TABLE socialcandor_schema.tax_rates IS 'Tax rates by jurisdiction for automatic tax calculation';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_tax_rates_jurisdiction ON socialcandor_schema.tax_rates(jurisdiction_type, jurisdiction_code, effective_from);
CREATE INDEX IF NOT EXISTS idx_tax_rates_active ON socialcandor_schema.tax_rates(effective_from, effective_to) WHERE effective_to IS NULL OR effective_to >= CURRENT_DATE;

-- RLS (admin only)
ALTER TABLE socialcandor_schema.tax_rates ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_rates_admin_policy ON socialcandor_schema.tax_rates
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_tax_rates_updated_at
    BEFORE UPDATE ON socialcandor_schema.tax_rates
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: promo_codes
-- Description: Manages promotional codes for discounts on subscriptions, marketplace items, or services
-- Business Case: Drives user acquisition, retention, and revenue through targeted discounts.
--                Enables marketing campaigns with limited‑time offers and usage limits.
-- KPIs:
--   1. Redemption rate
--   2. Revenue impact (incremental revenue)
--   3. Customer acquisition cost reduction
--   4. Code usage by channel
--   5. Fraud attempts (multiple uses)
-- Feature Reference: MKT02 (Promotions)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.promo_codes (
    promo_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    promo_code VARCHAR(50) UNIQUE NOT NULL,
    promo_number VARCHAR(50) GENERATED ALWAYS AS (
        'PROMO-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.promo_code_seq')::TEXT, 6, '0')
    ) STORED,
    description TEXT,
    discount_type VARCHAR(20) NOT NULL CHECK (discount_type IN ('PERCENTAGE', 'FIXED_AMOUNT', 'FREE_SHIPPING')),
    discount_value NUMERIC(10,2) NOT NULL CHECK (discount_value >= 0),
    minimum_purchase_amount NUMERIC(10,2) CHECK (minimum_purchase_amount >= 0),
    max_discount_amount NUMERIC(10,2) CHECK (max_discount_amount >= 0),
    valid_from TIMESTAMP WITH TIME ZONE NOT NULL,
    valid_to TIMESTAMP WITH TIME ZONE NOT NULL,
    usage_limit INTEGER CHECK (usage_limit >= 0),  -- NULL = unlimited
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    per_user_limit INTEGER DEFAULT 1 CHECK (per_user_limit >= 0),
    applicable_products TEXT[],  -- e.g., ['subscription_plan:pro', 'marketplace_category:electronics']
    applicable_users TEXT[],      -- e.g., 'all', 'new', segment IDs
    is_active BOOLEAN DEFAULT TRUE,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_promo_dates CHECK (valid_to >= valid_from)
);
COMMENT ON TABLE socialcandor_schema.promo_codes IS 'Promotional codes for discounts';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_promo_codes_code ON socialcandor_schema.promo_codes(promo_code);
CREATE INDEX IF NOT EXISTS idx_promo_codes_valid ON socialcandor_schema.promo_codes(valid_from, valid_to) WHERE is_active = TRUE;

-- RLS (admin only; users can see applicable codes via views)
ALTER TABLE socialcandor_schema.promo_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY promo_codes_admin_policy ON socialcandor_schema.promo_codes
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_promo_codes_updated_at
    BEFORE UPDATE ON socialcandor_schema.promo_codes
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: invoices
-- Description: Generates and tracks invoices for payments (subscriptions, marketplace purchases)
-- Business Case: Essential for accounting, customer records, and tax compliance. Provides a
--                formal record of transactions that can be sent to customers or used internally.
-- KPIs:
--   1. Number of invoices generated per period
--   2. Average invoice amount
--   3. Payment on‑time rate
--   4. Overdue invoice percentage
--   5. Dispute rate
-- Feature Reference: BIL03 (Invoicing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.invoices (
    invoice_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    invoice_number VARCHAR(50) UNIQUE NOT NULL,
    invoice_number_display VARCHAR(50) GENERATED ALWAYS AS (
        'INV-' || TO_CHAR(issue_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.invoice_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    subscription_id UUID,
    order_id UUID,
    invoice_type VARCHAR(20) NOT NULL CHECK (invoice_type IN ('SUBSCRIPTION', 'MARKETPLACE', 'MANUAL')),
    issue_date DATE NOT NULL DEFAULT CURRENT_DATE,
    due_date DATE NOT NULL,
    paid_date DATE,
    currency CHAR(3) NOT NULL,
    subtotal NUMERIC(15,2) NOT NULL CHECK (subtotal >= 0),
    tax_amount NUMERIC(15,2) DEFAULT 0 CHECK (tax_amount >= 0),
    discount_amount NUMERIC(15,2) DEFAULT 0 CHECK (discount_amount >= 0),
    total_amount NUMERIC(15,2) GENERATED ALWAYS AS (subtotal + tax_amount - discount_amount) STORED,
    amount_paid NUMERIC(15,2) DEFAULT 0 CHECK (amount_paid >= 0),
    status socialcandor_schema.invoice_status NOT NULL DEFAULT 'DRAFT',
    payment_method_id UUID,
    billing_address TEXT,
    tax_details JSONB,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_invoices_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_invoices_subscription FOREIGN KEY (subscription_id)
        REFERENCES socialcandor_schema.user_subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_invoices_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_invoices_payment_method FOREIGN KEY (payment_method_id)
        REFERENCES socialcandor_schema.payment_methods(payment_method_id) ON DELETE SET NULL,
    CONSTRAINT chk_invoice_dates CHECK (due_date >= issue_date)
);
COMMENT ON TABLE socialcandor_schema.invoices IS 'Invoices for payments';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_invoices_user ON socialcandor_schema.invoices(user_id);
CREATE INDEX IF NOT EXISTS idx_invoices_number ON socialcandor_schema.invoices(invoice_number);
CREATE INDEX IF NOT EXISTS idx_invoices_status ON socialcandor_schema.invoices(status);
CREATE INDEX IF NOT EXISTS idx_invoices_due_date ON socialcandor_schema.invoices(due_date) WHERE status NOT IN ('PAID', 'CANCELLED');

-- RLS
ALTER TABLE socialcandor_schema.invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoices_self_policy ON socialcandor_schema.invoices
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY invoices_admin_policy ON socialcandor_schema.invoices
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_invoices_updated_at
    BEFORE UPDATE ON socialcandor_schema.invoices
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: refund_requests
-- Description: Handles user‑initiated refund requests and tracks their approval status
-- Business Case: Provides a structured workflow for refunds, ensuring consistent handling,
--                auditability, and customer satisfaction. Helps track refund reasons and
--                identify potential abuse.
-- KPIs:
--   1. Refund request volume
--   2. Approval rate
--   3. Average time to process
--   4. Most common refund reasons
--   5. Refund amount as percentage of revenue
-- Feature Reference: BIL04 (Refunds)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.refund_requests (
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    invoice_id UUID NOT NULL,
    subscription_id UUID,
    order_id UUID,
    amount NUMERIC(15,2) NOT NULL CHECK (amount > 0),
    currency CHAR(3) NOT NULL,
    reason VARCHAR(500) NOT NULL,
    detailed_reason TEXT,
    status socialcandor_schema.refund_status NOT NULL DEFAULT 'REQUESTED',
    reviewed_by UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    review_notes TEXT,
    processed_at TIMESTAMP WITH TIME ZONE,
    refund_transaction_id UUID,  -- Link to wallet_transaction once processed
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_refund_requests_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_refund_requests_invoice FOREIGN KEY (invoice_id)
        REFERENCES socialcandor_schema.invoices(invoice_id) ON DELETE CASCADE,
    CONSTRAINT fk_refund_requests_subscription FOREIGN KEY (subscription_id)
        REFERENCES socialcandor_schema.user_subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_refund_requests_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_refund_requests_reviewed_by FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_refund_requests_transaction FOREIGN KEY (refund_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
    CONSTRAINT chk_refund_amount CHECK (amount <= (SELECT total_amount FROM socialcandor_schema.invoices WHERE invoice_id = refund_requests.invoice_id))
);
COMMENT ON TABLE socialcandor_schema.refund_requests IS 'User‑initiated refund requests';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_refund_requests_user ON socialcandor_schema.refund_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_refund_requests_invoice ON socialcandor_schema.refund_requests(invoice_id);
CREATE INDEX IF NOT EXISTS idx_refund_requests_status ON socialcandor_schema.refund_requests(status);

-- RLS
ALTER TABLE socialcandor_schema.refund_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY refund_requests_self_policy ON socialcandor_schema.refund_requests
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY refund_requests_staff_policy ON socialcandor_schema.refund_requests
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND (is_admin = TRUE OR is_moderator = TRUE)));
CREATE POLICY refund_requests_admin_policy ON socialcandor_schema.refund_requests
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_refund_requests_updated_at
    BEFORE UPDATE ON socialcandor_schema.refund_requests
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: payouts
-- Description: Manages payments to creators/advertisers from their earnings
-- Business Case: Automates the settlement of earnings to bank accounts or wallets, ensuring
--                timely and accurate payments. Tracks payout lifecycle and integrates with
--                financial systems.
-- KPIs:
--   1. Payout volume and value
--   2. Average time from request to completion
--   3. Payout failure rate
--   4. Most common payout methods
--   5. Creator satisfaction with payouts
-- Feature Reference: PAY04 (Payouts)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.payouts (
    payout_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    payout_number VARCHAR(50) GENERATED ALWAYS AS (
        'PAYOUT-' || TO_CHAR(requested_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.payout_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    amount NUMERIC(15,2) NOT NULL CHECK (amount > 0),
    currency CHAR(3) NOT NULL,
    payout_method VARCHAR(20) NOT NULL CHECK (payout_method IN ('BANK_TRANSFER', 'PAYPAL', 'WALLET', 'CRYPTO')),
    payout_destination_id VARCHAR(255),  -- e.g., bank account ID, PayPal email
    status socialcandor_schema.payout_status NOT NULL DEFAULT 'PENDING',
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    failure_reason TEXT,
    transaction_reference VARCHAR(255),
    fee_amount NUMERIC(15,2) DEFAULT 0 CHECK (fee_amount >= 0),
    net_amount NUMERIC(15,2) GENERATED ALWAYS AS (amount - fee_amount) STORED,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_payouts_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT chk_payout_positive CHECK (amount > 0)
);
COMMENT ON TABLE socialcandor_schema.payouts IS 'Payments to creators/advertisers';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_payouts_user ON socialcandor_schema.payouts(user_id);
CREATE INDEX IF NOT EXISTS idx_payouts_status ON socialcandor_schema.payouts(status);
CREATE INDEX IF NOT EXISTS idx_payouts_requested ON socialcandor_schema.payouts(requested_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.payouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY payouts_self_policy ON socialcandor_schema.payouts
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY payouts_admin_policy ON socialcandor_schema.payouts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_payouts_updated_at
    BEFORE UPDATE ON socialcandor_schema.payouts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 3. MARKETPLACE
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: seller_profiles
-- Description: Extends user profiles with seller‑specific information
-- Business Case: Separates seller identity from regular user profile, allowing businesses to
--                manage their marketplace presence, policies, and ratings.
-- KPIs:
--   1. Number of active sellers
--   2. Average seller rating
--   3. Seller verification completion rate
--   4. Time to first sale after profile creation
--   5. Seller churn rate
-- Feature Reference: MPL04 (Seller Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.seller_profiles (
    seller_profile_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL UNIQUE,
    business_name VARCHAR(255) NOT NULL,
    business_registration_number VARCHAR(100),
    tax_id VARCHAR(50),
    business_address TEXT,
    business_phone VARCHAR(50),
    business_email VARCHAR(255),
    website VARCHAR(255),
    description TEXT,
    logo_url VARCHAR(500),
    banner_url VARCHAR(500),
    policies JSONB,  -- e.g., return policy, shipping policy
    payment_terms VARCHAR(100),
    payout_method VARCHAR(20) CHECK (payout_method IN ('BANK_TRANSFER', 'PAYPAL', 'WALLET')),
    payout_details JSONB,  -- encrypted
    average_rating NUMERIC(3,2) DEFAULT 0 CHECK (average_rating >= 0 AND average_rating <= 5),
    total_reviews INTEGER DEFAULT 0 CHECK (total_reviews >= 0),
    total_sales INTEGER DEFAULT 0 CHECK (total_sales >= 0),
    verification_status VARCHAR(20) DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING', 'VERIFIED', 'REJECTED')),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_seller_profiles_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.seller_profiles IS 'Marketplace seller information';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_seller_profiles_user ON socialcandor_schema.seller_profiles(user_id);
CREATE INDEX IF NOT EXISTS idx_seller_profiles_verification ON socialcandor_schema.seller_profiles(verification_status);

-- RLS
ALTER TABLE socialcandor_schema.seller_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY seller_profiles_self_policy ON socialcandor_schema.seller_profiles
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY seller_profiles_admin_policy ON socialcandor_schema.seller_profiles
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_seller_profiles_updated_at
    BEFORE UPDATE ON socialcandor_schema.seller_profiles
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: marketplace_orders
-- Description: Tracks orders placed in the marketplace, linking listings to buyers
-- Business Case: Manages the entire order lifecycle from placement to fulfillment, integrating
--                with payments, inventory, and shipping. Essential for marketplace operations.
-- KPIs:
--   1. Order volume and value
--   2. Conversion rate (views to orders)
--   3. Average order value
--   4. Order fulfillment time
--   5. Cancellation/return rate
-- Feature Reference: MPL03 (Order Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.marketplace_orders (
    order_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    order_number VARCHAR(50) GENERATED ALWAYS AS (
        'ORD-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.order_seq')::TEXT, 6, '0')
    ) STORED,
    buyer_user_id UUID NOT NULL,
    seller_profile_id UUID NOT NULL,
    listing_id UUID,  -- Can be NULL for custom orders
    order_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    status socialcandor_schema.order_status NOT NULL DEFAULT 'PENDING',
    subtotal NUMERIC(15,2) NOT NULL CHECK (subtotal >= 0),
    shipping_cost NUMERIC(15,2) DEFAULT 0 CHECK (shipping_cost >= 0),
    tax_amount NUMERIC(15,2) DEFAULT 0 CHECK (tax_amount >= 0),
    discount_amount NUMERIC(15,2) DEFAULT 0 CHECK (discount_amount >= 0),
    total_amount NUMERIC(15,2) GENERATED ALWAYS AS (subtotal + shipping_cost + tax_amount - discount_amount) STORED,
    currency CHAR(3) NOT NULL,
    payment_status VARCHAR(20) CHECK (payment_status IN ('PENDING', 'PAID', 'REFUNDED', 'PARTIALLY_REFUNDED')),
    payment_transaction_id UUID,
    promo_code_id UUID,
    shipping_address_id UUID,
    tracking_number VARCHAR(100),
    carrier VARCHAR(50),
    estimated_delivery_date DATE,
    delivered_at TIMESTAMP WITH TIME ZONE,
    cancelled_at TIMESTAMP WITH TIME ZONE,
    cancellation_reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_marketplace_orders_buyer FOREIGN KEY (buyer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_marketplace_orders_seller FOREIGN KEY (seller_profile_id)
        REFERENCES socialcandor_schema.seller_profiles(seller_profile_id) ON DELETE CASCADE,
    CONSTRAINT fk_marketplace_orders_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE SET NULL,
    CONSTRAINT fk_marketplace_orders_payment FOREIGN KEY (payment_transaction_id)
        REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
    CONSTRAINT fk_marketplace_orders_promo FOREIGN KEY (promo_code_id)
        REFERENCES socialcandor_schema.promo_codes(promo_id) ON DELETE SET NULL,
    CONSTRAINT fk_marketplace_orders_shipping FOREIGN KEY (shipping_address_id)
        REFERENCES socialcandor_schema.shipping_addresses(address_id) ON DELETE SET NULL,
    CONSTRAINT chk_order_amounts CHECK (subtotal >= 0 AND total_amount >= 0)
);
COMMENT ON TABLE socialcandor_schema.marketplace_orders IS 'Marketplace orders';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_marketplace_orders_buyer ON socialcandor_schema.marketplace_orders(buyer_user_id);
CREATE INDEX IF NOT EXISTS idx_marketplace_orders_seller ON socialcandor_schema.marketplace_orders(seller_profile_id);
CREATE INDEX IF NOT EXISTS idx_marketplace_orders_status ON socialcandor_schema.marketplace_orders(status);
CREATE INDEX IF NOT EXISTS idx_marketplace_orders_date ON socialcandor_schema.marketplace_orders(order_date DESC);

-- RLS
ALTER TABLE socialcandor_schema.marketplace_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_buyer_policy ON socialcandor_schema.marketplace_orders
    FOR ALL USING (buyer_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY orders_seller_policy ON socialcandor_schema.marketplace_orders
    FOR ALL USING (seller_profile_id IN (
        SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY orders_admin_policy ON socialcandor_schema.marketplace_orders
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_marketplace_orders_updated_at
    BEFORE UPDATE ON socialcandor_schema.marketplace_orders
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: shipping_addresses
-- Description: Stores user shipping addresses for marketplace orders
-- Business Case: Centralizes address management, allowing users to save multiple addresses and
--                reuse them across orders. Reduces data entry and improves checkout experience.
-- KPIs:
--   1. Number of saved addresses per user
--   2. Address usage frequency
--   3. Address validation success rate
--   4. Most common countries/states
--   5. Address update frequency
-- Feature Reference: MPL05 (Shipping)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.shipping_addresses (
    address_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    address_name VARCHAR(100),  -- e.g., "Home", "Work"
    recipient_name VARCHAR(255) NOT NULL,
    address_line1 VARCHAR(255) NOT NULL,
    address_line2 VARCHAR(255),
    city VARCHAR(100) NOT NULL,
    state_province VARCHAR(100),
    postal_code VARCHAR(20) NOT NULL,
    country_code CHAR(3) NOT NULL,
    phone VARCHAR(50),
    is_default BOOLEAN DEFAULT FALSE,
    delivery_instructions TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_shipping_addresses_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_shipping_addresses_country FOREIGN KEY (country_code)
        REFERENCES socialcandor_schema.system_countries(country_code) ON DELETE RESTRICT
);
COMMENT ON TABLE socialcandor_schema.shipping_addresses IS 'User shipping addresses';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_shipping_addresses_user ON socialcandor_schema.shipping_addresses(user_id);
CREATE INDEX IF NOT EXISTS idx_shipping_addresses_default ON socialcandor_schema.shipping_addresses(user_id, is_default) WHERE is_default = TRUE;

-- RLS
ALTER TABLE socialcandor_schema.shipping_addresses ENABLE ROW LEVEL SECURITY;
CREATE POLICY shipping_addresses_self_policy ON socialcandor_schema.shipping_addresses
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY shipping_addresses_admin_policy ON socialcandor_schema.shipping_addresses
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_shipping_addresses_updated_at
    BEFORE UPDATE ON socialcandor_schema.shipping_addresses
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: marketplace_reviews
-- Description: Allows buyers to review products/sellers
-- Business Case: Builds trust and reputation in the marketplace, helping buyers make informed
--                decisions and encouraging sellers to provide quality products and service.
-- KPIs:
--   1. Review volume
--   2. Average rating
--   3. Verified purchase percentage
--   4. Review helpfulness votes
--   5. Seller response rate
-- Feature Reference: MPL06 (Reviews)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.marketplace_reviews (
    review_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    order_id UUID NOT NULL,
    listing_id UUID,
    seller_profile_id UUID NOT NULL,
    reviewer_user_id UUID NOT NULL,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    title VARCHAR(255),
    review_text TEXT,
    pros TEXT,
    cons TEXT,
    images TEXT[],
    is_verified_purchase BOOLEAN DEFAULT TRUE,
    helpful_votes INTEGER DEFAULT 0 CHECK (helpful_votes >= 0),
    not_helpful_votes INTEGER DEFAULT 0 CHECK (not_helpful_votes >= 0),
    seller_response TEXT,
    seller_responded_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_marketplace_reviews_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE CASCADE,
    CONSTRAINT fk_marketplace_reviews_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE SET NULL,
    CONSTRAINT fk_marketplace_reviews_seller FOREIGN KEY (seller_profile_id)
        REFERENCES socialcandor_schema.seller_profiles(seller_profile_id) ON DELETE CASCADE,
    CONSTRAINT fk_marketplace_reviews_reviewer FOREIGN KEY (reviewer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_order_review UNIQUE (order_id)  -- One review per order
);
COMMENT ON TABLE socialcandor_schema.marketplace_reviews IS 'Reviews of marketplace items and sellers';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_marketplace_reviews_seller ON socialcandor_schema.marketplace_reviews(seller_profile_id);
CREATE INDEX IF NOT EXISTS idx_marketplace_reviews_listing ON socialcandor_schema.marketplace_reviews(listing_id) WHERE listing_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_marketplace_reviews_rating ON socialcandor_schema.marketplace_reviews(rating);
CREATE INDEX IF NOT EXISTS idx_marketplace_reviews_created ON socialcandor_schema.marketplace_reviews(created_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.marketplace_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_self_policy ON socialcandor_schema.marketplace_reviews
    FOR SELECT USING (reviewer_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY reviews_seller_policy ON socialcandor_schema.marketplace_reviews
    FOR SELECT USING (seller_profile_id IN (
        SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY reviews_admin_policy ON socialcandor_schema.marketplace_reviews
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_marketplace_reviews_updated_at
    BEFORE UPDATE ON socialcandor_schema.marketplace_reviews
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 4. LEARNING & EDUCATION
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: course_modules
-- Description: Structures courses into modules, enabling organized content delivery
-- Business Case: Breaks down courses into manageable chunks, improving learner navigation and
--                progress tracking. Supports modular course design.
-- KPIs:
--   1. Average modules per course
--   2. Module completion rate
--   3. Time spent per module
--   4. Module dropout points
--   5. Module popularity
-- Feature Reference: EDU04 (Course Structure)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.course_modules (
    module_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    course_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
    estimated_duration_minutes INTEGER CHECK (estimated_duration_minutes >= 0),
    is_optional BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_course_modules_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE,
    CONSTRAINT uk_course_module_order UNIQUE (course_id, sort_order)
);
COMMENT ON TABLE socialcandor_schema.course_modules IS 'Modules within a course';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_course_modules_course ON socialcandor_schema.course_modules(course_id);

-- RLS (same as courses)
ALTER TABLE socialcandor_schema.course_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY course_modules_admin_policy ON socialcandor_schema.course_modules
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY course_modules_instructor_policy ON socialcandor_schema.course_modules
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.learning_courses lc
        WHERE lc.course_id = course_modules.course_id
          AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));

-- Trigger
CREATE TRIGGER trg_course_modules_updated_at
    BEFORE UPDATE ON socialcandor_schema.course_modules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: course_lessons
-- Description: Defines individual lessons within modules
-- Business Case: Provides granular content items (videos, text, quizzes) that learners consume.
--                Enables progress tracking at the lesson level.
-- KPIs:
--   1. Average lessons per module
--   2. Lesson completion rate
--   3. Most viewed lesson types
--   4. Lesson engagement (time spent)
--   5. Lesson difficulty rating
-- Feature Reference: EDU05 (Lesson Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.course_lessons (
    lesson_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    module_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    lesson_type socialcandor_schema.lesson_type NOT NULL,
    content_url VARCHAR(500),  -- For video/audio/downloadable
    content_text TEXT,         -- For text lessons
    duration_seconds INTEGER CHECK (duration_seconds >= 0),
    sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
    is_free_preview BOOLEAN DEFAULT FALSE,  -- Allow preview without enrollment
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_course_lessons_module FOREIGN KEY (module_id)
        REFERENCES socialcandor_schema.course_modules(module_id) ON DELETE CASCADE,
    CONSTRAINT uk_module_lesson_order UNIQUE (module_id, sort_order)
);
COMMENT ON TABLE socialcandor_schema.course_lessons IS 'Lessons within a course module';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_course_lessons_module ON socialcandor_schema.course_lessons(module_id);

-- RLS (similar to modules)
ALTER TABLE socialcandor_schema.course_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY course_lessons_admin_policy ON socialcandor_schema.course_lessons
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY course_lessons_instructor_policy ON socialcandor_schema.course_lessons
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.course_modules cm
        JOIN socialcandor_schema.learning_courses lc ON cm.course_id = lc.course_id
        WHERE cm.module_id = course_lessons.module_id
          AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));

-- Trigger
CREATE TRIGGER trg_course_lessons_updated_at
    BEFORE UPDATE ON socialcandor_schema.course_lessons
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: lesson_progress
-- Description: Tracks user progress through lessons per enrollment
-- Business Case: Enables learners to resume where they left off, and provides analytics on
--                completion and engagement. Essential for certification and progress tracking.
-- KPIs:
--   1. Lesson completion rate per user
--   2. Average time to complete lesson
--   3. Most abandoned lessons
--   4. Re‑watch frequency
--   5. Correlation with quiz scores
-- Feature Reference: EDU06 (Progress Tracking)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.lesson_progress (
    progress_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    enrollment_id UUID NOT NULL,
    lesson_id UUID NOT NULL,
    status VARCHAR(20) NOT NULL CHECK (status IN ('NOT_STARTED', 'IN_PROGRESS', 'COMPLETED')),
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    last_position_seconds INTEGER CHECK (last_position_seconds >= 0),  -- For video/audio
    time_spent_seconds INTEGER DEFAULT 0 CHECK (time_spent_seconds >= 0),
    attempts_count INTEGER DEFAULT 0 CHECK (attempts_count >= 0),
    score INTEGER,  -- For quizzes
    max_score INTEGER,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_lesson_progress_enrollment FOREIGN KEY (enrollment_id)
        REFERENCES socialcandor_schema.enrollments(enrollment_id) ON DELETE CASCADE,
    CONSTRAINT fk_lesson_progress_lesson FOREIGN KEY (lesson_id)
        REFERENCES socialcandor_schema.course_lessons(lesson_id) ON DELETE CASCADE,
    CONSTRAINT uk_enrollment_lesson UNIQUE (enrollment_id, lesson_id),
    CONSTRAINT chk_progress_dates CHECK (completed_at IS NULL OR completed_at >= started_at)
);
COMMENT ON TABLE socialcandor_schema.lesson_progress IS 'User progress per lesson';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_lesson_progress_enrollment ON socialcandor_schema.lesson_progress(enrollment_id);
CREATE INDEX IF NOT EXISTS idx_lesson_progress_lesson ON socialcandor_schema.lesson_progress(lesson_id);
CREATE INDEX IF NOT EXISTS idx_lesson_progress_status ON socialcandor_schema.lesson_progress(status);

-- RLS
ALTER TABLE socialcandor_schema.lesson_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY lesson_progress_self_policy ON socialcandor_schema.lesson_progress
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.enrollments e
        WHERE e.enrollment_id = lesson_progress.enrollment_id
          AND e.user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY lesson_progress_instructor_policy ON socialcandor_schema.lesson_progress
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.enrollments e
        JOIN socialcandor_schema.learning_courses lc ON e.course_id = lc.course_id
        WHERE e.enrollment_id = lesson_progress.enrollment_id
          AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY lesson_progress_admin_policy ON socialcandor_schema.lesson_progress
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_lesson_progress_updated_at
    BEFORE UPDATE ON socialcandor_schema.lesson_progress
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: course_reviews
-- Description: Allows enrolled users to rate and review courses
-- Business Case: Provides social proof and feedback for course creators, helping learners choose
--                quality courses. Also informs platform improvements.
-- KPIs:
--   1. Review volume per course
--   2. Average rating per course
--   3. Verified enrollment percentage
--   4. Review helpfulness votes
--   5. Instructor response rate
-- Feature Reference: EDU07 (Course Reviews)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.course_reviews (
    review_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    course_id UUID NOT NULL,
    user_id UUID NOT NULL,
    enrollment_id UUID NOT NULL,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    title VARCHAR(255),
    review_text TEXT,
    pros TEXT,
    cons TEXT,
    helpful_votes INTEGER DEFAULT 0 CHECK (helpful_votes >= 0),
    not_helpful_votes INTEGER DEFAULT 0 CHECK (not_helpful_votes >= 0),
    instructor_response TEXT,
    instructor_responded_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_course_reviews_course FOREIGN KEY (course_id)
        REFERENCES socialcandor_schema.learning_courses(course_id) ON DELETE CASCADE,
    CONSTRAINT fk_course_reviews_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_course_reviews_enrollment FOREIGN KEY (enrollment_id)
        REFERENCES socialcandor_schema.enrollments(enrollment_id) ON DELETE CASCADE,
    CONSTRAINT uk_user_course_review UNIQUE (user_id, course_id)
);
COMMENT ON TABLE socialcandor_schema.course_reviews IS 'User reviews for courses';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_course_reviews_course ON socialcandor_schema.course_reviews(course_id);
CREATE INDEX IF NOT EXISTS idx_course_reviews_user ON socialcandor_schema.course_reviews(user_id);
CREATE INDEX IF NOT EXISTS idx_course_reviews_rating ON socialcandor_schema.course_reviews(rating);

-- RLS
ALTER TABLE socialcandor_schema.course_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY course_reviews_self_policy ON socialcandor_schema.course_reviews
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY course_reviews_instructor_policy ON socialcandor_schema.course_reviews
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.learning_courses lc
        WHERE lc.course_id = course_reviews.course_id
          AND lc.instructor_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY course_reviews_admin_policy ON socialcandor_schema.course_reviews
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_course_reviews_updated_at
    BEFORE UPDATE ON socialcandor_schema.course_reviews
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 5. EVENTS
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: event_sessions
-- Description: For multi‑session events, tracks individual sessions with speakers, times, locations
-- Business Case: Enables complex event scheduling (conferences with parallel tracks), allowing
--                attendees to choose sessions and organizers to manage logistics.
-- KPIs:
--   1. Number of sessions per event
--   2. Session attendance rate
--   3. Most popular sessions
--   4. Speaker performance (ratings)
--   5. Session duration variance
-- Feature Reference: EVT03 (Session Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.event_sessions (
    session_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    event_id UUID NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    speaker_user_id UUID,
    speaker_name VARCHAR(255),  -- For external speakers not in system
    speaker_bio TEXT,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE NOT NULL,
    timezone VARCHAR(50),
    location_physical VARCHAR(255),  -- Room, hall, etc.
    virtual_meeting_url VARCHAR(500),
    capacity INTEGER CHECK (capacity >= 0),
    status socialcandor_schema.event_session_status DEFAULT 'SCHEDULED',
    materials_url VARCHAR(500),
    recording_url VARCHAR(500),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_event_sessions_event FOREIGN KEY (event_id)
        REFERENCES socialcandor_schema.events(event_id) ON DELETE CASCADE,
    CONSTRAINT fk_event_sessions_speaker FOREIGN KEY (speaker_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_session_times CHECK (end_time >= start_time)
);
COMMENT ON TABLE socialcandor_schema.event_sessions IS 'Sessions within a multi‑session event';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_event_sessions_event ON socialcandor_schema.event_sessions(event_id);
CREATE INDEX IF NOT EXISTS idx_event_sessions_time ON socialcandor_schema.event_sessions(start_time);

-- RLS
ALTER TABLE socialcandor_schema.event_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_sessions_organizer_policy ON socialcandor_schema.event_sessions
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.events e
        WHERE e.event_id = event_sessions.event_id
          AND e.organizer_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY event_sessions_public_policy ON socialcandor_schema.event_sessions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.events e
        WHERE e.event_id = event_sessions.event_id AND e.event_status = 'PUBLISHED'
    ));
CREATE POLICY event_sessions_admin_policy ON socialcandor_schema.event_sessions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_event_sessions_updated_at
    BEFORE UPDATE ON socialcandor_schema.event_sessions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: event_tickets
-- Description: Manages ticket types, pricing, and availability for events
-- Business Case: Supports monetization of events through ticket sales, with different tiers,
--                early bird pricing, and capacity management.
-- KPIs:
--   1. Ticket sales volume
--   2. Revenue per ticket type
--   3. Sell‑out rate
--   4. Average ticket price
--   5. Attendee upgrade/downgrade rate
-- Feature Reference: EVT04 (Ticketing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.event_tickets (
    ticket_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    event_id UUID NOT NULL,
    ticket_type socialcandor_schema.ticket_type NOT NULL,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    price NUMERIC(15,2) NOT NULL CHECK (price >= 0),
    currency CHAR(3) DEFAULT 'USD',
    quantity_total INTEGER CHECK (quantity_total >= 0),  -- NULL = unlimited
    quantity_sold INTEGER DEFAULT 0 CHECK (quantity_sold >= 0),
    max_per_user INTEGER DEFAULT 1 CHECK (max_per_user >= 1),
    sales_start TIMESTAMP WITH TIME ZONE,
    sales_end TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_event_tickets_event FOREIGN KEY (event_id)
        REFERENCES socialcandor_schema.events(event_id) ON DELETE CASCADE,
    CONSTRAINT chk_ticket_quantity CHECK (quantity_sold <= quantity_total)
);
COMMENT ON TABLE socialcandor_schema.event_tickets IS 'Ticket types and inventory for events';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_event_tickets_event ON socialcandor_schema.event_tickets(event_id);

-- RLS (similar to events)
ALTER TABLE socialcandor_schema.event_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_tickets_organizer_policy ON socialcandor_schema.event_tickets
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.events e
        WHERE e.event_id = event_tickets.event_id
          AND e.organizer_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY event_tickets_public_policy ON socialcandor_schema.event_tickets
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.events e
        WHERE e.event_id = event_tickets.event_id AND e.event_status = 'PUBLISHED'
    ));
CREATE POLICY event_tickets_admin_policy ON socialcandor_schema.event_tickets
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_event_tickets_updated_at
    BEFORE UPDATE ON socialcandor_schema.event_tickets
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: event_checkins
-- Description: Logs attendee check‑ins for on‑site events
-- Business Case: Verifies attendance, enables capacity monitoring, and provides data for
--                post‑event analytics and certification.
-- KPIs:
--   1. Check‑in rate (percentage of registered)
--   2. On‑time vs. late check‑ins
--   3. No‑show rate
--   4. Average check‑in time per session
--   5. Duplicate check‑in attempts
-- Feature Reference: EVT05 (Check‑in)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.event_checkins (
    checkin_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    event_id UUID NOT NULL,
    session_id UUID,
    user_id UUID NOT NULL,
    ticket_id UUID,
    checkin_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status socialcandor_schema.checkin_status DEFAULT 'CHECKED_IN',
    verified_by UUID,  -- Staff who verified (optional)
    method VARCHAR(20) CHECK (method IN ('QR_CODE', 'MANUAL', 'API')),
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_event_checkins_event FOREIGN KEY (event_id)
        REFERENCES socialcandor_schema.events(event_id) ON DELETE CASCADE,
    CONSTRAINT fk_event_checkins_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.event_sessions(session_id) ON DELETE CASCADE,
    CONSTRAINT fk_event_checkins_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_event_checkins_ticket FOREIGN KEY (ticket_id)
        REFERENCES socialcandor_schema.event_tickets(ticket_id) ON DELETE SET NULL,
    CONSTRAINT fk_event_checkins_verified_by FOREIGN KEY (verified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_event_user_checkin UNIQUE (event_id, user_id, session_id)  -- One check‑in per (user, session)
);
COMMENT ON TABLE socialcandor_schema.event_checkins IS 'Attendee check‑ins for events and sessions';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_event_checkins_event ON socialcandor_schema.event_checkins(event_id);
CREATE INDEX IF NOT EXISTS idx_event_checkins_user ON socialcandor_schema.event_checkins(user_id);
CREATE INDEX IF NOT EXISTS idx_event_checkins_time ON socialcandor_schema.event_checkins(checkin_time DESC);

-- RLS
ALTER TABLE socialcandor_schema.event_checkins ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_checkins_self_policy ON socialcandor_schema.event_checkins
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY event_checkins_organizer_policy ON socialcandor_schema.event_checkins
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.events e
        WHERE e.event_id = event_checkins.event_id
          AND e.organizer_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY event_checkins_admin_policy ON socialcandor_schema.event_checkins
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_event_checkins_updated_at
    BEFORE UPDATE ON socialcandor_schema.event_checkins
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 6. CONTENT & MODERATION
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: moderation_rules
-- Description: Defines automated rules to flag or hide content based on keywords, patterns, or ML scores
-- Business Case: Reduces manual moderation workload by automatically catching common violations,
--                ensuring consistent enforcement and faster response times.
-- KPIs:
--   1. Rule hit rate
--   2. False positive rate
--   3. Time saved in moderation
--   4. Rule coverage of reported content
--   5. Rule update frequency
-- Feature Reference: MOD04 (Automated Moderation)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.moderation_rules (
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    rule_name VARCHAR(255) NOT NULL,
    description TEXT,
    rule_type VARCHAR(50) NOT NULL CHECK (rule_type IN ('KEYWORD', 'REGEX', 'ML_SCORE', 'PATTERN', 'IMAGE_HASH')),
    rule_config JSONB NOT NULL,  -- e.g., keywords list, regex pattern, ML threshold
    target_content_type VARCHAR(50) CHECK (target_content_type IN ('POST', 'COMMENT', 'MESSAGE', 'PROFILE', 'ALL')),
    action socialcandor_schema.moderation_rule_action NOT NULL,
    priority INTEGER DEFAULT 1 CHECK (priority >= 1),  -- Lower number = higher priority
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    last_triggered_at TIMESTAMP WITH TIME ZONE,
    trigger_count INTEGER DEFAULT 0 CHECK (trigger_count >= 0)
);
COMMENT ON TABLE socialcandor_schema.moderation_rules IS 'Automated rules for content moderation';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_moderation_rules_active ON socialcandor_schema.moderation_rules(is_active) WHERE is_active = TRUE;
CREATE INDEX IF NOT EXISTS idx_moderation_rules_type ON socialcandor_schema.moderation_rules(rule_type);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.moderation_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY moderation_rules_admin_policy ON socialcandor_schema.moderation_rules
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_moderation_rules_updated_at
    BEFORE UPDATE ON socialcandor_schema.moderation_rules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: content_warnings
-- Description: Allows creators or automated systems to tag posts with sensitive content warnings
-- Business Case: Empowers users to avoid distressing content and helps platform comply with
--                content labeling requirements. Also supports automated flagging.
-- KPIs:
--   1. Percentage of content with warnings
--   2. User opt‑in/out rates for warnings
--   3. Most common warning types
--   4. Automated vs. manual warning ratio
--   5. User satisfaction with warning system
-- Feature Reference: MOD05 (Content Warnings)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.content_warnings (
    warning_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    content_type VARCHAR(30) NOT NULL CHECK (content_type IN ('POST', 'COMMENT', 'MEDIA', 'MESSAGE')),
    content_id UUID NOT NULL,
    warning_type socialcandor_schema.content_warning_type NOT NULL,
    is_automated BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    -- Optionally link to moderation action that triggered it
    moderation_action_id UUID,
    CONSTRAINT fk_content_warnings_mod_action FOREIGN KEY (moderation_action_id)
        REFERENCES socialcandor_schema.moderation_actions(action_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.content_warnings IS 'Sensitive content warnings attached to posts, comments, etc.';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_content_warnings_content ON socialcandor_schema.content_warnings(content_type, content_id);

-- RLS (similar to content)
ALTER TABLE socialcandor_schema.content_warnings ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_warnings_public_policy ON socialcandor_schema.content_warnings
    FOR SELECT USING (TRUE);  -- Anyone can see warnings, but they are metadata
CREATE POLICY content_warnings_admin_policy ON socialcandor_schema.content_warnings
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

------------------------------------------------------------------------------------------------
-- Table: flagging_metadata
-- Description: Stores additional context for user‑generated flags (reason, evidence)
-- Business Case: Enriches flag data to help moderators make informed decisions faster,
--                and to detect patterns of abuse.
-- KPIs:
--   1. Flag reason distribution
--   2. Average evidence attachments per flag
--   3. Flag resolution time by reason
--   4. False flag rate by reason
--   5. User satisfaction with flag outcome
-- Feature Reference: MOD06 (Flagging)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.flagging_metadata (
    flag_metadata_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    report_id UUID NOT NULL,  -- Links to user_reports
    reason socialcandor_schema.flag_reason NOT NULL,
    evidence_urls TEXT[],
    additional_context JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    CONSTRAINT fk_flagging_metadata_report FOREIGN KEY (report_id)
        REFERENCES socialcandor_schema.user_reports(report_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.flagging_metadata IS 'Additional context for user flags';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_flagging_metadata_report ON socialcandor_schema.flagging_metadata(report_id);
CREATE INDEX IF NOT EXISTS idx_flagging_metadata_reason ON socialcandor_schema.flagging_metadata(reason);

-- RLS (similar to reports)
ALTER TABLE socialcandor_schema.flagging_metadata ENABLE ROW LEVEL SECURITY;
CREATE POLICY flagging_metadata_self_policy ON socialcandor_schema.flagging_metadata
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.user_reports ur
        WHERE ur.report_id = flagging_metadata.report_id
          AND ur.reporter_user_id = current_setting('app.current_user_id')::UUID
    ));
CREATE POLICY flagging_metadata_moderator_policy ON socialcandor_schema.flagging_metadata
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

--================================================================================================
-- 7. COMPLIANCE & DATA GOVERNANCE
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: processing_activities
-- Description: Record of processing activities (RoPA) as required by GDPR Article 30
-- Business Case: Documents all data processing operations, including purpose, categories, recipients,
--                and security measures. Essential for compliance and demonstrating accountability.
-- KPIs:
--   1. Number of processing activities
--   2. Coverage of all data flows
--   3. Review frequency
--   4. Completeness of documentation
--   5. Time to update when processes change
-- Feature Reference: GDPR07 (Processing Activities)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.processing_activities (
    activity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    activity_name VARCHAR(255) NOT NULL,
    activity_description TEXT,
    controller_name VARCHAR(255) NOT NULL,
    controller_contact TEXT,
    dp_officer_name VARCHAR(255),
    dp_officer_contact TEXT,
    purpose TEXT NOT NULL,
    legal_basis VARCHAR(100) NOT NULL,
    data_categories TEXT[] NOT NULL,
    data_subjects TEXT[] NOT NULL,
    recipients TEXT[],
    international_transfers BOOLEAN DEFAULT FALSE,
    transfer_countries TEXT[],
    transfer_safeguards TEXT,
    retention_period VARCHAR(255),
    security_measures TEXT,
    risk_assessment TEXT,
    last_reviewed DATE,
    next_review_date DATE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT chk_review_dates CHECK (next_review_date IS NULL OR next_review_date >= last_reviewed)
);
COMMENT ON TABLE socialcandor_schema.processing_activities IS 'Record of processing activities (GDPR Art. 30)';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_processing_activities_review ON socialcandor_schema.processing_activities(next_review_date) WHERE is_active = TRUE;

-- RLS (admin only)
ALTER TABLE socialcandor_schema.processing_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY processing_activities_admin_policy ON socialcandor_schema.processing_activities
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_processing_activities_updated_at
    BEFORE UPDATE ON socialcandor_schema.processing_activities
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: transfer_impact_assessments
-- Description: Records assessments for international data transfers
-- Business Case: Required under GDPR Chapter V to document risks and safeguards when transferring
--                personal data outside the EEA. Helps ensure compliance with transfer mechanisms.
-- KPIs:
--   1. Number of transfer assessments
--   2. Transfer mechanism used (SCC, BCR, etc.)
--   3. Risk level distribution
--   4. Review frequency
--   5. Time to update after regulatory changes
-- Feature Reference: GDPR08 (Transfer Impact Assessments)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.transfer_impact_assessments (
    assessment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    transfer_name VARCHAR(255) NOT NULL,
    transferring_controller VARCHAR(255) NOT NULL,
    recipient_controller VARCHAR(255) NOT NULL,
    recipient_country VARCHAR(3) NOT NULL,
    transfer_mechanism socialcandor_schema.transfer_mechanism NOT NULL,
    data_categories TEXT[] NOT NULL,
    data_subjects TEXT[] NOT NULL,
    purpose TEXT NOT NULL,
    risk_assessment TEXT,
    risk_level socialcandor_schema.risk_level,
    safeguards_description TEXT,
    additional_measures TEXT,
    assessment_date DATE NOT NULL DEFAULT CURRENT_DATE,
    reviewed_by UUID,
    review_notes TEXT,
    next_review_date DATE,
    document_url VARCHAR(500),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_tia_reviewed_by FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.transfer_impact_assessments IS 'Assessments for international data transfers';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_tia_country ON socialcandor_schema.transfer_impact_assessments(recipient_country);
CREATE INDEX IF NOT EXISTS idx_tia_next_review ON socialcandor_schema.transfer_impact_assessments(next_review_date) WHERE next_review_date IS NOT NULL;

-- RLS (admin only)
ALTER TABLE socialcandor_schema.transfer_impact_assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY tia_admin_policy ON socialcandor_schema.transfer_impact_assessments
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_tia_updated_at
    BEFORE UPDATE ON socialcandor_schema.transfer_impact_assessments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: vendor_assessments
-- Description: Evaluates third‑party vendors for privacy and security risks
-- Business Case: Helps manage vendor risk, ensure contractual compliance, and meet regulatory
--                requirements for data processors.
-- KPIs:
--   1. Number of vendors assessed
--   2. Average risk score
--   3. Remediation time for high‑risk vendors
--   4. Assessment completion rate
--   5. Vendor compliance with DPAs
-- Feature Reference: GDPR09 (Vendor Risk Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.vendor_assessments (
    assessment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    vendor_name VARCHAR(255) NOT NULL,
    vendor_type VARCHAR(50) CHECK (vendor_type IN ('PROCESSOR', 'SUBPROCESSOR', 'CONTROLLER')),
    contact_name VARCHAR(255),
    contact_email VARCHAR(255),
    services_provided TEXT,
    data_accessed TEXT[],
    data_categories TEXT[],
    data_subjects TEXT[],
    dpa_signed BOOLEAN DEFAULT FALSE,
    dpa_date DATE,
    dpa_document_url VARCHAR(500),
    assessment_date DATE NOT NULL DEFAULT CURRENT_DATE,
    assessor_id UUID,
    security_questionnaire JSONB,
    risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
    risk_level socialcandor_schema.risk_level,
    findings TEXT,
    remediation_plan TEXT,
    remediation_deadline DATE,
    remediation_status VARCHAR(20) CHECK (remediation_status IN ('OPEN', 'IN_PROGRESS', 'COMPLETED', 'ACCEPTED')),
    next_assessment_date DATE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_vendor_assessments_assessor FOREIGN KEY (assessor_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.vendor_assessments IS 'Privacy and security assessments for third‑party vendors';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_vendor_assessments_risk ON socialcandor_schema.vendor_assessments(risk_level);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.vendor_assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY vendor_assessments_admin_policy ON socialcandor_schema.vendor_assessments
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_vendor_assessments_updated_at
    BEFORE UPDATE ON socialcandor_schema.vendor_assessments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: data_lineage
-- Description: Documents the flow of data from source to destination (tables, pipelines, reports)
-- Business Case: Enables impact analysis, debugging, and regulatory inquiries about data origins.
--                Supports data governance by mapping data movement.
-- KPIs:
--   1. Lineage coverage of critical data assets
--   2. Time to trace data origin
--   3. Number of lineage updates per pipeline change
--   4. Accuracy of lineage (confirmed by users)
--   5. Adoption in data impact assessments
-- Feature Reference: GOV06 (Data Lineage)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_lineage (
    lineage_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    source_asset_type VARCHAR(50) NOT NULL,
    source_asset_id UUID NOT NULL,
    source_asset_name VARCHAR(255),
    target_asset_type VARCHAR(50) NOT NULL,
    target_asset_id UUID NOT NULL,
    target_asset_name VARCHAR(255),
    transformation_description TEXT,
    pipeline_id UUID,  -- Link to pipeline if applicable
    job_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    CONSTRAINT fk_data_lineage_pipeline FOREIGN KEY (pipeline_id)
        REFERENCES socialcandor_schema.ingestion_pipelines(pipeline_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_lineage_job FOREIGN KEY (job_id)
        REFERENCES socialcandor_schema.background_jobs(job_id) ON DELETE SET NULL,
    CONSTRAINT chk_lineage_different CHECK (source_asset_id != target_asset_id OR source_asset_type != target_asset_type)
);
COMMENT ON TABLE socialcandor_schema.data_lineage IS 'Data lineage from source to destination';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_data_lineage_source ON socialcandor_schema.data_lineage(source_asset_type, source_asset_id);
CREATE INDEX IF NOT EXISTS idx_data_lineage_target ON socialcandor_schema.data_lineage(target_asset_type, target_asset_id);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.data_lineage ENABLE ROW LEVEL SECURITY;
CREATE POLICY data_lineage_admin_policy ON socialcandor_schema.data_lineage
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

------------------------------------------------------------------------------------------------
-- Table: data_contracts
-- Description: Formal agreements between data producers and consumers, specifying schema, quality, SLAs
-- Business Case: Improves data reliability by setting expectations between teams. Helps prevent
--                data incidents and fosters trust in data products.
-- KPIs:
--   1. Number of active contracts
--   2. Contract compliance rate
--   3. Breach frequency
--   4. Time to resolve contract violations
--   5. Consumer satisfaction with data
-- Feature Reference: DQ08 (Data Contracts)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_contracts (
    contract_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    contract_name VARCHAR(255) NOT NULL,
    contract_version VARCHAR(20),
    producer_team VARCHAR(100),
    producer_contact UUID,
    consumer_team VARCHAR(100),
    consumer_contact UUID,
    data_asset_type VARCHAR(50) NOT NULL,
    data_asset_id UUID NOT NULL,
    schema_definition JSONB,
    quality_requirements JSONB,
    sla_response_time_minutes INTEGER,
    sla_availability_percent NUMERIC(5,2) CHECK (sla_availability_percent >= 0 AND sla_availability_percent <= 100),
    effective_date DATE NOT NULL,
    expiry_date DATE,
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'TERMINATED')),
    breach_count INTEGER DEFAULT 0,
    last_breach_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_data_contracts_producer FOREIGN KEY (producer_contact)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_contracts_consumer FOREIGN KEY (consumer_contact)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_contracts IS 'Formal agreements between data producers and consumers';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_data_contracts_asset ON socialcandor_schema.data_contracts(data_asset_type, data_asset_id);
CREATE INDEX IF NOT EXISTS idx_data_contracts_status ON socialcandor_schema.data_contracts(status);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.data_contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY data_contracts_admin_policy ON socialcandor_schema.data_contracts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_data_contracts_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_contracts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: data_quality_incidents
-- Description: Tracks specific data quality failures beyond routine check logs
-- Business Case: Provides a structured way to manage data quality incidents, from detection
--                to resolution, and to analyze root causes.
-- KPIs:
--   1. Incident volume by severity
--   2. Mean time to detect (MTTD)
--   3. Mean time to resolve (MTTR)
--   4. Recurrence rate
--   5. Most common incident types
-- Feature Reference: DQ07 (Data Quality Incidents)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_incidents (
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    incident_title VARCHAR(255) NOT NULL,
    description TEXT,
    severity socialcandor_schema.data_quality_severity NOT NULL,
    affected_assets JSONB,  -- List of tables/datasets affected
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    detected_by UUID,
    detection_method VARCHAR(100),
    root_cause TEXT,
    impact_analysis TEXT,
    resolution_notes TEXT,
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolved_by UUID,
    status VARCHAR(20) DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'INVESTIGATING', 'RESOLVED', 'CLOSED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_dqi_detected_by FOREIGN KEY (detected_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_dqi_resolved_by FOREIGN KEY (resolved_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_quality_incidents IS 'Tracks data quality incidents';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_dqi_severity ON socialcandor_schema.data_quality_incidents(severity);
CREATE INDEX IF NOT EXISTS idx_dqi_status ON socialcandor_schema.data_quality_incidents(status);
CREATE INDEX IF NOT EXISTS idx_dqi_detected ON socialcandor_schema.data_quality_incidents(detected_at DESC);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.data_quality_incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY dqi_admin_policy ON socialcandor_schema.data_quality_incidents
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

