--================================================================================================
-- 8. SYSTEM & INFRASTRUCTURE
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: backup_logs
-- Description: Logs database and file backups for disaster recovery
-- Business Case: Provides audit trail of backups, ensuring recovery capabilities are tested and
--                compliant with SLAs. Helps meet RPO/RTO objectives.
-- KPIs:
--   1. Backup success rate
--   2. Backup size trend
--   3. Backup duration
--   4. Recovery test success rate
--   5. Time since last successful backup
-- Feature Reference: BCP03 (Backup Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.backup_logs (
    log_id BIGSERIAL PRIMARY KEY,
    backup_number VARCHAR(50) GENERATED ALWAYS AS (
        'BCK-' || TO_CHAR(start_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.backup_log_seq')::TEXT, 6, '0')
    ) STORED,
    backup_type socialcandor_schema.backup_type NOT NULL,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE,
    status VARCHAR(20) CHECK (status IN ('RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    size_bytes BIGINT,
    location_url VARCHAR(500),
    verification_status VARCHAR(20) CHECK (verification_status IN ('PENDING', 'VERIFIED', 'FAILED')),
    verified_at TIMESTAMP WITH TIME ZONE,
    error_message TEXT,
    initiated_by UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_backup_logs_initiated_by FOREIGN KEY (initiated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.backup_logs IS 'Logs of database and file backups';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_backup_logs_start ON socialcandor_schema.backup_logs(start_time DESC);
CREATE INDEX IF NOT EXISTS idx_backup_logs_status ON socialcandor_schema.backup_logs(status);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.backup_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY backup_logs_admin_policy ON socialcandor_schema.backup_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

------------------------------------------------------------------------------------------------
-- Table: capacity_forecasts
-- Description: Forecasts resource usage (storage, compute, API calls) to plan infrastructure upgrades
-- Business Case: Proactively avoids capacity shortages by predicting future usage based on trends.
--                Supports cost optimization and performance management.
-- KPIs:
--   1. Forecast accuracy (vs. actuals)
--   2. Number of capacity incidents avoided
--   3. Resource utilization trends
--   4. Time to provision new capacity
--   5. Cost savings from accurate planning
-- Feature Reference: OPS03 (Capacity Planning)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.capacity_forecasts (
    forecast_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    resource_type VARCHAR(50) NOT NULL CHECK (resource_type IN ('STORAGE', 'CPU', 'MEMORY', 'API_CALLS', 'DATABASE_CONNECTIONS')),
    forecast_date DATE NOT NULL,
    predicted_value NUMERIC NOT NULL,
    actual_value NUMERIC,
    forecast_model VARCHAR(100),
    confidence_interval_lower NUMERIC,
    confidence_interval_upper NUMERIC,
    forecast_period VARCHAR(20) CHECK (forecast_period IN ('DAY', 'WEEK', 'MONTH', 'QUARTER')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.capacity_forecasts IS 'Resource usage forecasts for capacity planning';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_capacity_forecasts_date ON socialcandor_schema.capacity_forecasts(forecast_date DESC);
CREATE INDEX IF NOT EXISTS idx_capacity_forecasts_resource ON socialcandor_schema.capacity_forecasts(resource_type);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.capacity_forecasts ENABLE ROW LEVEL SECURITY;
CREATE POLICY capacity_forecasts_admin_policy ON socialcandor_schema.capacity_forecasts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_capacity_forecasts_updated_at
    BEFORE UPDATE ON socialcandor_schema.capacity_forecasts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: cost_allocation
-- Description: Tracks infrastructure costs by team, project, or feature
-- Business Case: Enables chargebacks, showbacks, and cost optimization by attributing expenses
--                to the responsible units. Improves financial transparency.
-- KPIs:
--   1. Cost per team/project
--   2. Cost per feature
--   3. Cost trend over time
--   4. Budget vs. actual variance
--   5. Cost savings from optimizations
-- Feature Reference: FIN02 (Cost Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.cost_allocation (
    allocation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    cost_center VARCHAR(100) NOT NULL,
    project VARCHAR(100),
    team VARCHAR(100),
    feature VARCHAR(100),
    resource_type VARCHAR(50),
    cost_date DATE NOT NULL,
    amount NUMERIC(15,2) NOT NULL CHECK (amount >= 0),
    currency CHAR(3) DEFAULT 'USD',
    source VARCHAR(100),  -- e.g., 'AWS', 'GCP', 'internal'
    usage_quantity NUMERIC,
    unit VARCHAR(50),
    tags JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.cost_allocation IS 'Infrastructure costs attributed to teams/projects/features';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_cost_allocation_cost_center ON socialcandor_schema.cost_allocation(cost_center, cost_date);
CREATE INDEX IF NOT EXISTS idx_cost_allocation_project ON socialcandor_schema.cost_allocation(project, cost_date);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.cost_allocation ENABLE ROW LEVEL SECURITY;
CREATE POLICY cost_allocation_admin_policy ON socialcandor_schema.cost_allocation
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_cost_allocation_updated_at
    BEFORE UPDATE ON socialcandor_schema.cost_allocation
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 9. SECURITY
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: security_incidents
-- Description: Specialized incident tracking for security‑related events
-- Business Case: Extends general incident management with security‑specific fields,
--                ensuring proper handling, forensics, and compliance reporting.
-- KPIs:
--   1. Number of security incidents
--   2. Mean time to detect (MTTD)
--   3. Mean time to contain (MTTC)
--   4. Mean time to resolve (MTTR)
--   5. Incident severity distribution
-- Feature Reference: SEC13 (Security Incidents)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.security_incidents (
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'SEC-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.security_incident_seq')::TEXT, 6, '0')
    ) STORED,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    incident_type VARCHAR(50) CHECK (incident_type IN ('PHISHING', 'MALWARE', 'UNAUTHORIZED_ACCESS', 'DATA_BREACH', 'INSIDER_THREAT', 'DDOS', 'OTHER')),
    severity socialcandor_schema.security_incident_severity NOT NULL,
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    reported_by UUID,
    assigned_to UUID,
    containment_time TIMESTAMP WITH TIME ZONE,
    eradication_time TIMESTAMP WITH TIME ZONE,
    recovery_time TIMESTAMP WITH TIME ZONE,
    closure_time TIMESTAMP WITH TIME ZONE,
    root_cause TEXT,
    indicators_of_compromise JSONB,
    affected_systems TEXT[],
    affected_data TEXT[],
    affected_users_count INTEGER,
    remediation_actions TEXT,
    lessons_learned TEXT,
    status VARCHAR(20) DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'INVESTIGATING', 'CONTAINED', 'ERADICATED', 'RECOVERED', 'CLOSED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_security_incidents_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_security_incidents_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.security_incidents IS 'Security incident tracking';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_security_incidents_detected ON socialcandor_schema.security_incidents(detected_at DESC);
CREATE INDEX IF NOT EXISTS idx_security_incidents_severity ON socialcandor_schema.security_incidents(severity);
CREATE INDEX IF NOT EXISTS idx_security_incidents_status ON socialcandor_schema.security_incidents(status);

-- RLS (admin and security team only)
ALTER TABLE socialcandor_schema.security_incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_incidents_admin_policy ON socialcandor_schema.security_incidents
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_security_incidents_updated_at
    BEFORE UPDATE ON socialcandor_schema.security_incidents
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: vulnerability_scans
-- Description: Stores results of vulnerability scans (internal/external)
-- Business Case: Tracks security weaknesses over time, prioritizes remediation,
--                and demonstrates compliance with security standards.
-- KPIs:
--   1. Number of vulnerabilities by severity
--   2. Mean time to remediate
--   3. Recurring vulnerabilities
--   4. Scan coverage (percentage of assets)
--   5. False positive rate
-- Feature Reference: SEC14 (Vulnerability Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.vulnerability_scans (
    scan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    scan_number VARCHAR(50) GENERATED ALWAYS AS (
        'VULN-' || TO_CHAR(scan_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.vulnerability_scan_seq')::TEXT, 6, '0')
    ) STORED,
    scan_name VARCHAR(255) NOT NULL,
    scan_type VARCHAR(50) CHECK (scan_type IN ('INTERNAL', 'EXTERNAL', 'DAST', 'SAST', 'CONTAINER', 'CLOUD')),
    scanner VARCHAR(100),
    scan_date DATE NOT NULL,
    scan_end_date DATE,
    asset_scope TEXT,
    total_vulnerabilities INTEGER DEFAULT 0,
    critical_count INTEGER DEFAULT 0,
    high_count INTEGER DEFAULT 0,
    medium_count INTEGER DEFAULT 0,
    low_count INTEGER DEFAULT 0,
    info_count INTEGER DEFAULT 0,
    findings JSONB,
    report_url VARCHAR(500),
    remediation_summary TEXT,
    next_scan_due DATE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.vulnerability_scans IS 'Results of vulnerability scans';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_vulnerability_scans_date ON socialcandor_schema.vulnerability_scans(scan_date DESC);
CREATE INDEX IF NOT EXISTS idx_vulnerability_scans_next ON socialcandor_schema.vulnerability_scans(next_scan_due) WHERE next_scan_due IS NOT NULL;

-- RLS (admin only)
ALTER TABLE socialcandor_schema.vulnerability_scans ENABLE ROW LEVEL SECURITY;
CREATE POLICY vulnerability_scans_admin_policy ON socialcandor_schema.vulnerability_scans
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_vulnerability_scans_updated_at
    BEFORE UPDATE ON socialcandor_schema.vulnerability_scans
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: security_training_records
-- Description: Tracks employee completion of security awareness training
-- Business Case: Ensures all employees meet mandatory training requirements, reducing human‑error
--                risks and supporting compliance audits.
-- KPIs:
--   1. Training completion rate
--   2. Average time to complete
--   3. Pass/fail rate
--   4. Re‑training rate
--   5. Correlation with security incidents
-- Feature Reference: SEC15 (Security Training)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.security_training_records (
    record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    training_name VARCHAR(255) NOT NULL,
    training_module VARCHAR(100),
    assigned_date DATE NOT NULL,
    due_date DATE,
    completed_date DATE,
    status socialcandor_schema.training_status DEFAULT 'NOT_STARTED',
    score INTEGER CHECK (score >= 0 AND score <= 100),
    passed BOOLEAN,
    certificate_url VARCHAR(500),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_security_training_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.security_training_records IS 'Employee security training completion records';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_security_training_user ON socialcandor_schema.security_training_records(user_id);
CREATE INDEX IF NOT EXISTS idx_security_training_status ON socialcandor_schema.security_training_records(status, due_date);

-- RLS
ALTER TABLE socialcandor_schema.security_training_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_training_self_policy ON socialcandor_schema.security_training_records
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY security_training_admin_policy ON socialcandor_schema.security_training_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_security_training_updated_at
    BEFORE UPDATE ON socialcandor_schema.security_training_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

--================================================================================================
-- 10. AI/ML OPERATIONS
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: feature_definitions
-- Description: Manages features used in machine learning models, storing definitions and metadata
-- Business Case: Centralizes feature documentation, ensuring consistency across models and
--                enabling feature reuse. Supports ML governance and model debugging.
-- KPIs:
--   1. Number of features defined
--   2. Feature reuse across models
--   3. Feature freshness
--   4. Data type distribution
--   5. Feature ownership coverage
-- Feature Reference: MLOP05 (Feature Store)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_definitions (
    feature_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    feature_name VARCHAR(255) NOT NULL UNIQUE,
    description TEXT,
    data_type socialcandor_schema.feature_data_type NOT NULL,
    source_system VARCHAR(100),
    source_table VARCHAR(100),
    source_column VARCHAR(100),
    transformation_logic TEXT,
    owner_team VARCHAR(100),
    owner_user_id UUID,
    is_pii BOOLEAN DEFAULT FALSE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_feature_definitions_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.feature_definitions IS 'Definitions of features used in ML models';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_feature_definitions_name ON socialcandor_schema.feature_definitions(feature_name);
CREATE INDEX IF NOT EXISTS idx_feature_definitions_owner ON socialcandor_schema.feature_definitions(owner_user_id) WHERE owner_user_id IS NOT NULL;

-- RLS (admin and ML team)
ALTER TABLE socialcandor_schema.feature_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY feature_definitions_admin_policy ON socialcandor_schema.feature_definitions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_feature_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.feature_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

------------------------------------------------------------------------------------------------
-- Table: feature_values
-- Description: Stores time‑series feature values for training and inference
-- Business Case: Provides historical feature data for model training and real‑time values for inference.
--                Enables feature monitoring and drift detection.
-- KPIs:
--   1. Number of feature values stored
--   2. Data volume per feature
--   3. Latency of feature retrieval
--   4. Completeness of feature history
--   5. Feature value anomalies
-- Feature Reference: MLOP05 (Feature Store)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_values (
    value_id BIGSERIAL PRIMARY KEY,
    feature_id UUID NOT NULL,
    entity_id VARCHAR(255) NOT NULL,  -- e.g., user_id, post_id
    value_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    value_numeric NUMERIC,
    value_string TEXT,
    value_boolean BOOLEAN,
    value_json JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_feature_values_feature FOREIGN KEY (feature_id)
        REFERENCES socialcandor_schema.feature_definitions(feature_id) ON DELETE CASCADE,
    CONSTRAINT chk_feature_value_type CHECK (
        (value_numeric IS NOT NULL) OR (value_string IS NOT NULL) OR (value_boolean IS NOT NULL) OR (value_json IS NOT NULL)
    )
) PARTITION BY RANGE (value_timestamp);
COMMENT ON TABLE socialcandor_schema.feature_values IS 'Time‑series values of features';

-- Indexes (on each partition, but we can create on parent)
CREATE INDEX IF NOT EXISTS idx_feature_values_feature_time ON socialcandor_schema.feature_values(feature_id, value_timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_feature_values_entity ON socialcandor_schema.feature_values(entity_id, feature_id, value_timestamp DESC);

-- RLS (admin only, or ML service)
ALTER TABLE socialcandor_schema.feature_values ENABLE ROW LEVEL SECURITY;
CREATE POLICY feature_values_admin_policy ON socialcandor_schema.feature_values
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

------------------------------------------------------------------------------------------------
-- Table: model_predictions
-- Description: Logs every prediction made by a model, enabling audit, drift detection, and performance monitoring
-- Business Case: Provides a complete audit trail of model decisions, supports debugging,
--                and enables continuous monitoring for drift or bias.
-- KPIs:
--   1. Prediction volume
--   2. Prediction latency
--   3. Drift detection alerts
--   4. Model performance degradation
--   5. Compliance with explainability requirements
-- Feature Reference: MLOP06 (Model Monitoring)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_predictions (
    prediction_id BIGSERIAL PRIMARY KEY,
    model_version_id UUID NOT NULL,
    request_id UUID,  -- For correlation
    input_data JSONB NOT NULL,
    output_data JSONB NOT NULL,
    confidence NUMERIC(5,4) CHECK (confidence >= 0 AND confidence <= 1),
    prediction_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    latency_ms INTEGER CHECK (latency_ms >= 0),
    user_id UUID,  -- Who/what triggered the prediction
    metadata JSONB,
    CONSTRAINT fk_model_predictions_version FOREIGN KEY (model_version_id)
        REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_model_predictions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
) PARTITION BY RANGE (prediction_time);
COMMENT ON TABLE socialcandor_schema.model_predictions IS 'Logs of ML model predictions';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_model_predictions_version_time ON socialcandor_schema.model_predictions(model_version_id, prediction_time DESC);
CREATE INDEX IF NOT EXISTS idx_model_predictions_request ON socialcandor_schema.model_predictions(request_id) WHERE request_id IS NOT NULL;

-- RLS (admin only)
ALTER TABLE socialcandor_schema.model_predictions ENABLE ROW LEVEL SECURITY;
CREATE POLICY model_predictions_admin_policy ON socialcandor_schema.model_predictions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

------------------------------------------------------------------------------------------------
-- Table: model_drift_metrics
-- Description: Tracks model drift over time (e.g., data drift, concept drift)
-- Business Case: Alerts data scientists when model performance may degrade due to changes in
--                input data or relationships, triggering retraining.
-- KPIs:
--   1. Drift detection frequency
--   2. Drift magnitude
--   3. Time to retrain after drift
--   4. False positive rate of drift alerts
--   5. Model stability over time
-- Feature Reference: MLOP06 (Model Monitoring)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_drift_metrics (
    metric_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    model_id UUID NOT NULL,
    metric_type socialcandor_schema.drift_metric_type NOT NULL,
    computation_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    drift_score NUMERIC(10,6) CHECK (drift_score >= 0),
    threshold NUMERIC(10,6),
    alert_triggered BOOLEAN DEFAULT FALSE,
    details JSONB,  -- e.g., features with highest drift
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_drift_metrics_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.model_drift_metrics IS 'Drift metrics for ML models';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_drift_metrics_model_time ON socialcandor_schema.model_drift_metrics(model_id, computation_time DESC);

-- RLS (admin only)
ALTER TABLE socialcandor_schema.model_drift_metrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY drift_metrics_admin_policy ON socialcandor_schema.model_drift_metrics
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

--================================================================================================
-- 11. FINANCIAL & ACCOUNTING
--================================================================================================

------------------------------------------------------------------------------------------------
-- Table: general_ledger
-- Description: Records double‑entry accounting entries for all financial transactions
-- Business Case: Provides a complete, auditable record of all financial movements, supporting
--                financial reporting, tax filing, and audit trails.
-- KPIs:
--   1. Number of journal entries
--   2. Reconciliation rate
--   3. Time to close books
--   4. Audit adjustments count
--   5. Data integrity (balanced entries)
-- Feature Reference: FIN01 (General Ledger)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.general_ledger (
    entry_id BIGSERIAL PRIMARY KEY,
    transaction_id UUID,  -- Link to source transaction (wallet_transactions, etc.)
    entry_date DATE NOT NULL,
    account_code VARCHAR(50) NOT NULL,
    account_name VARCHAR(255),
    account_type socialcandor_schema.account_type NOT NULL,
    debit_amount NUMERIC(15,2) DEFAULT 0 CHECK (debit_amount >= 0),
    credit_amount NUMERIC(15,2) DEFAULT 0 CHECK (credit_amount >= 0),
    description TEXT,
    reference VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT chk_debit_credit CHECK (
        (debit_amount > 0 AND credit_amount = 0) OR (debit_amount = 0 AND credit_amount > 0)
    )
);
COMMENT ON TABLE socialcandor_schema.general_ledger IS 'Double‑entry general ledger';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_general_ledger_date ON socialcandor_schema.general_ledger(entry_date DESC);
CREATE INDEX IF NOT EXISTS idx_general_ledger_account ON socialcandor_schema.general_ledger(account_code, entry_date);
CREATE INDEX IF NOT EXISTS idx_general_ledger_transaction ON socialcandor_schema.general_ledger(transaction_id) WHERE transaction_id IS NOT NULL;

-- RLS (admin and finance team only)
ALTER TABLE socialcandor_schema.general_ledger ENABLE ROW LEVEL SECURITY;
