-- Table: tax_reports
-- Description: Aggregates tax‑related data for periodic reporting (e.g., VAT returns)
-- Business Case: Simplifies tax filing by pre‑calculating taxable amounts per jurisdiction
--                and period, reducing manual work and errors.
-- KPIs:
--   1. Report generation time
--   2. Accuracy of tax calculations
--   3. Number of reports generated
--   4. Tax authority queries resolved
--   5. Compliance with filing deadlines
-- Feature Reference: TAX02 (Tax Reporting)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.tax_reports (
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    report_period VARCHAR(20) NOT NULL CHECK (report_period IN ('MONTHLY', 'QUARTERLY', 'YEARLY')),
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    jurisdiction_code VARCHAR(10) NOT NULL,
    tax_type VARCHAR(20) NOT NULL,
    taxable_sales NUMERIC(15,2) DEFAULT 0,
    tax_collected NUMERIC(15,2) DEFAULT 0,
    taxable_purchases NUMERIC(15,2) DEFAULT 0,
    tax_paid NUMERIC(15,2) DEFAULT 0,
    net_tax_due NUMERIC(15,2) GENERATED ALWAYS AS (tax_collected - tax_paid) STORED,
    currency CHAR(3) DEFAULT 'USD',
    report_data JSONB,
    filed_at TIMESTAMP WITH TIME ZONE,
    filed_by UUID,
    confirmation_number VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_tax_reports_filed_by FOREIGN KEY (filed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_tax_report_dates CHECK (end_date >= start_date)
);
COMMENT ON TABLE socialcandor_schema.tax_reports IS 'Aggregated tax reports for filing';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_tax_reports_jurisdiction ON socialcandor_schema.tax_reports(jurisdiction_code, start_date, end_date);

-- RLS (admin and finance)
ALTER TABLE socialcandor_schema.tax_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_reports_admin_policy ON socialcandor_schema.tax_reports
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_tax_reports_updated_at
    BEFORE UPDATE ON socialcandor_schema.tax_reports
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

