-- Table: retention_cohorts
-- Description: Pre‑computes user retention cohorts for historical analysis
-- Business Case: Provides fast access to retention metrics without recalculating from raw events,
--                enabling product managers to quickly assess user engagement over time.
-- KPIs:
--   1. Retention rates by cohort
--   2. Cohort size
--   3. Churn rate per cohort
--   4. Revenue per cohort
--   5. Feature adoption by cohort
-- Feature Reference: ANL11 (Retention Analysis)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.retention_cohorts (
    cohort_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    cohort_date DATE NOT NULL,  -- e.g., registration date
    cohort_size INTEGER NOT NULL CHECK (cohort_size >= 0),
    period_type VARCHAR(10) CHECK (period_type IN ('DAY', 'WEEK', 'MONTH')),
    periods JSONB NOT NULL,  -- e.g., { "0": 100, "1": 75, "2": 60, ... } period index -> retained count
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil()
);
COMMENT ON TABLE socialcandor_schema.retention_cohorts IS 'Pre‑computed user retention cohorts';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_retention_cohorts_date ON socialcandor_schema.retention_cohorts(cohort_date DESC);

-- RLS (admin only)
