CREATE POLICY retention_cohorts_admin_policy ON socialcandor_schema.retention_cohorts
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_retention_cohorts_updated_at
    BEFORE UPDATE ON socialcandor_schema.retention_cohorts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

