-- Table: funnel_steps
-- Description: Stores step‑level data for conversion funnels, allowing detailed drop‑off analysis
-- Business Case: Enables product teams to identify where users abandon key flows (e.g., signup,
--                purchase) and optimize those steps.
-- KPIs:
--   1. Step completion rates
--   2. Drop‑off points
--   3. Time between steps
--   4. Funnel conversion rate
--   5. Step abandonment reasons (from surveys)
-- Feature Reference: ANL09 (Conversion Funnels)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.funnel_steps (
    step_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    funnel_id UUID NOT NULL,
    step_name VARCHAR(255) NOT NULL,
    step_order INTEGER NOT NULL CHECK (step_order >= 0),
    step_event VARCHAR(255),  -- e.g., 'page_view', 'button_click'
    step_conditions JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_funnel_steps_funnel FOREIGN KEY (funnel_id)
        REFERENCES socialcandor_schema.conversion_funnel_definitions(funnel_id) ON DELETE CASCADE,
    CONSTRAINT uk_funnel_step_order UNIQUE (funnel_id, step_order)
);
COMMENT ON TABLE socialcandor_schema.funnel_steps IS 'Steps within a conversion funnel';

-- Indexes
CREATE INDEX IF NOT EXISTS idx_funnel_steps_funnel ON socialcandor_schema.funnel_steps(funnel_id);

-- RLS (admin only, or product team)
ALTER TABLE socialcandor_schema.funnel_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY funnel_steps_admin_policy ON socialcandor_schema.funnel_steps
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

