CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.export_files_seq START 1000;

-- =================================================================================================
-- TABLE: user_tokens
-- Description: Stores one‑time tokens for email verification, password reset, magic links, etc.
-- Business Case: Centralized token management with expiration, ensuring secure account actions.
--                Prevents replay attacks and provides audit trail for critical operations.
-- KPIs:
--   1. Token usage rate (percentage of tokens used before expiry)
--   2. Average time between token creation and usage
--   3. Token expiry breach rate (attempts to use expired tokens)
--   4. Distribution of token types (verification vs. reset)
--   5. Failed token usage attempts (invalid/expired)
-- Feature References: SEC16 (User Authentication), GDPR01 (Account Security)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_tokens (
    token_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID NOT NULL,
    token VARCHAR(255) NOT NULL UNIQUE,
    token_type socialcandor_schema.user_token_type NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    used_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil(),
    -- Additional metadata
    ip_address INET,
    user_agent TEXT,
    metadata JSONB DEFAULT '{}',
    -- Constraints
    CONSTRAINT fk_user_tokens_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_tokens_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_tokens_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_user_tokens_expiry CHECK (expires_at > created_at),
    CONSTRAINT chk_user_tokens_used CHECK (used_at IS NULL OR used_at >= created_at)
);
COMMENT ON TABLE socialcandor_schema.user_tokens IS 'One‑time tokens for account verification, password reset, etc.';
CREATE INDEX idx_user_tokens_token ON socialcandor_schema.user_tokens(token);
CREATE INDEX idx_user_tokens_user ON socialcandor_schema.user_tokens(user_id);
CREATE INDEX idx_user_tokens_expires ON socialcandor_schema.user_tokens(expires_at) WHERE used_at IS NULL;

-- RLS
ALTER TABLE socialcandor_schema.user_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_tokens_self_policy ON socialcandor_schema.user_tokens
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_tokens_admin_policy ON socialcandor_schema.user_tokens
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: user_login_history
-- Description: Historical log of all login attempts (success/failure) with device and location details.
-- Business Case: Enables security monitoring, anomaly detection, and forensic analysis of account access.
--                Required for compliance (GDPR, SOC2) to demonstrate access audits.
-- KPIs:
--   1. Success rate of logins over time
--   2. Number of failed attempts per user per day
--   3. Unique IP addresses per user
--   4. Login geo‑distribution
--   5. Time between successive logins from new devices
-- Feature References: SEC18 (Login Monitoring), AUD09 (Access Audit)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_login_history (
    login_id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL,
    login_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ip_address INET,
    user_agent TEXT,
    device_fingerprint VARCHAR(255),
    login_method VARCHAR(50) CHECK (login_method IN ('PASSWORD', 'MFA', 'SSO', 'TOKEN', 'MAGIC_LINK')),
    successful BOOLEAN NOT NULL,
    failure_reason TEXT,
    session_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_login_history_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_login_history_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_login_history_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_login_history_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
) PARTITION BY RANGE (login_time);
COMMENT ON TABLE socialcandor_schema.user_login_history IS 'Complete history of user login attempts.';
CREATE INDEX idx_login_history_user ON socialcandor_schema.user_login_history(user_id, login_time DESC);
CREATE INDEX idx_login_history_ip ON socialcandor_schema.user_login_history(ip_address);
CREATE INDEX idx_login_history_successful ON socialcandor_schema.user_login_history(successful, login_time DESC);

-- RLS
ALTER TABLE socialcandor_schema.user_login_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY login_history_self_policy ON socialcandor_schema.user_login_history
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY login_history_admin_policy ON socialcandor_schema.user_login_history
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: user_password_history
-- Description: Stores hashed passwords to enforce password rotation and prevent reuse.
-- Business Case: Security best practice and compliance requirement (e.g., NIST 800-63B).
--                Ensures users cannot cycle back to recent passwords.
-- KPIs:
--   1. Password change frequency
--   2. Number of password reuse attempts
--   3. Average time between password changes
--   4. Password strength compliance rate
--   5. Users with expired passwords
-- Feature References: SEC19 (Password Policy), COMP13 (NIST Compliance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_password_history (
    history_id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    changed_by UUID,  -- can be user or admin
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_password_history_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_password_history_changed_by FOREIGN KEY (changed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_password_history_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_password_history_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.user_password_history IS 'Historical password hashes to prevent reuse.';
CREATE INDEX idx_password_history_user ON socialcandor_schema.user_password_history(user_id, changed_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.user_password_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY password_history_self_policy ON socialcandor_schema.user_password_history
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY password_history_admin_policy ON socialcandor_schema.user_password_history
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: user_anonymization_queue
-- Description: Asynchronously processes GDPR right‑to‑be‑forgotten requests.
-- Business Case: Decouples erasure from request handling, allowing retry and monitoring.
--                Prevents performance impact on main application.
-- KPIs:
--   1. Average time from request to completion
--   2. Queue backlog size
--   3. Job failure rate
--   4. Data volume anonymized per job
--   5. Percentage of requests completed within legal deadline
-- Feature References: GDPR10 (Right to Erasure), BATCH01 (Batch Processing)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_anonymization_queue (
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'ANON-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.anonymization_queue_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    request_id UUID,  -- link to data_subject_requests
    status socialcandor_schema.anonymization_queue_status NOT NULL DEFAULT 'PENDING',
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    error_message TEXT,
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_anon_queue_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_anon_queue_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
    CONSTRAINT fk_anon_queue_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_anon_queue_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.user_anonymization_queue IS 'Queue for asynchronous GDPR erasure jobs.';
CREATE INDEX idx_anon_queue_user ON socialcandor_schema.user_anonymization_queue(user_id);
CREATE INDEX idx_anon_queue_status ON socialcandor_schema.user_anonymization_queue(status, created_at);
CREATE INDEX idx_anon_queue_request ON socialcandor_schema.user_anonymization_queue(request_id) WHERE request_id IS NOT NULL;

-- RLS
ALTER TABLE socialcandor_schema.user_anonymization_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY anon_queue_admin_policy ON socialcandor_schema.user_anonymization_queue
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: user_export_files
-- Description: Stores generated DSAR export files for data portability requests.
-- Business Case: Provides permanent record of data exports; allows user to re‑download.
--                Supports audit trail of data access.
-- KPIs:
--   1. Number of exports per month
--   2. Average file size
--   3. Download frequency
--   4. Export format popularity
--   5. Time between request and file generation
-- Feature References: GDPR11 (Data Portability), DPP01 (Data Portability)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_export_files (
    export_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    export_number VARCHAR(50) GENERATED ALWAYS AS (
        'EXPORT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.export_files_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    request_id UUID,  -- link to data_subject_requests
    file_name VARCHAR(255) NOT NULL,
    file_url VARCHAR(500) NOT NULL,
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    format VARCHAR(20) CHECK (format IN ('JSON', 'CSV', 'XML')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,  -- auto‑delete after retention period
    download_count INTEGER DEFAULT 0 CHECK (download_count >= 0),
    metadata JSONB DEFAULT '{}',
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_export_files_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_export_files_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
    CONSTRAINT fk_export_files_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_export_files_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_export_files_expiry CHECK (expires_at IS NULL OR expires_at > created_at)
);
COMMENT ON TABLE socialcandor_schema.user_export_files IS 'Generated DSAR export files for data portability.';
CREATE INDEX idx_export_files_user ON socialcandor_schema.user_export_files(user_id);
CREATE INDEX idx_export_files_request ON socialcandor_schema.user_export_files(request_id) WHERE request_id IS NOT NULL;
CREATE INDEX idx_export_files_expires ON socialcandor_schema.user_export_files(expires_at) WHERE expires_at IS NOT NULL;

