-- TABLE: user_security_events
-- Description: Logs security‑sensitive events for SIEM integration and user monitoring.
-- Business Case: Centralised repository for all security‑relevant actions, enabling threat detection,
--                forensic analysis, and compliance reporting.
-- KPIs:
--   1. Event volume by type
--   2. Time between related events (e.g., password change after MFA disable)
--   3. Number of events per user
--   4. Anomalous event detection rate
--   5. Correlation with failed logins
-- Feature References: SEC20 (Security Information and Event Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_security_events (
    event_id BIGSERIAL PRIMARY KEY,
    event_number VARCHAR(50) GENERATED ALWAYS AS (
        'SECEV-' || TO_CHAR(event_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_security_event_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID,
    event_type socialcandor_schema.user_security_event_type NOT NULL,
    event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ip_address INET,
    user_agent TEXT,
    details JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_security_events_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_security_events_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_security_events_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
) PARTITION BY RANGE (event_time);
COMMENT ON TABLE socialcandor_schema.user_security_events IS 'Security‑sensitive events for monitoring and SIEM.';
CREATE INDEX idx_security_events_user ON socialcandor_schema.user_security_events(user_id, event_time DESC);
CREATE INDEX idx_security_events_type ON socialcandor_schema.user_security_events(event_type, event_time DESC);
CREATE INDEX idx_security_events_ip ON socialcandor_schema.user_security_events(ip_address) WHERE ip_address IS NOT NULL;

-- RLS
