-- =================================================================================================
-- AUDIT TRIGGERS
-- =================================================================================================

-- Function to write to audit_logs
CREATE OR REPLACE FUNCTION socialcandor_schema.audit_trigger_function()
RETURNS TRIGGER AS $$
DECLARE
    v_actor UUID;
    v_action socialcandor_schema.audit_action;
    v_target_type socialcandor_schema.audit_target_type;
    v_target_id UUID;
    v_before JSONB;
    v_after JSONB;
    v_audit_id BIGINT;
BEGIN
    -- Determine actor (use updated_by if available, else created_by)
    IF TG_OP = 'DELETE' THEN
        v_actor := OLD.updated_by;
        IF v_actor IS NULL THEN
            v_actor := OLD.created_by;
        END IF;
        v_before := to_jsonb(OLD);
        v_after := NULL;
        v_target_id := OLD.user_id;  -- assume most audited tables have user_id; adjust per table
    ELSIF TG_OP = 'UPDATE' THEN
        v_actor := NEW.updated_by;
        v_before := to_jsonb(OLD);
        v_after := to_jsonb(NEW);
        v_target_id := NEW.user_id;
    ELSE  -- INSERT
        v_actor := NEW.created_by;
        v_before := NULL;
        v_after := to_jsonb(NEW);
        v_target_id := NEW.user_id;
    END IF;

    -- Map operation to audit_action
    v_action := CASE TG_OP
        WHEN 'INSERT' THEN 'CREATE'::socialcandor_schema.audit_action
        WHEN 'UPDATE' THEN 'UPDATE'::socialcandor_schema.audit_action
        WHEN 'DELETE' THEN 'DELETE'::socialcandor_schema.audit_action
    END;

    -- Map table name to target_type
    v_target_type := CASE TG_TABLE_NAME
        WHEN 'users' THEN 'USER'::socialcandor_schema.audit_target_type
        WHEN 'users_sessions' THEN 'SESSION'::socialcandor_schema.audit_target_type
        WHEN 'user_wallets' THEN 'WALLET'::socialcandor_schema.audit_target_type
        WHEN 'wallet_transactions' THEN 'TRANSACTION'::socialcandor_schema.audit_target_type
        WHEN 'payment_methods' THEN 'PAYMENT_METHOD'::socialcandor_schema.audit_target_type
        WHEN 'user_subscriptions' THEN 'SUBSCRIPTION'::socialcandor_schema.audit_target_type
        WHEN 'invoices' THEN 'INVOICE'::socialcandor_schema.audit_target_type
        WHEN 'payouts' THEN 'PAYOUT'::socialcandor_schema.audit_target_type
        WHEN 'data_subject_requests' THEN 'DSAR'::socialcandor_schema.audit_target_type
        WHEN 'consent_records' THEN 'CONSENT'::socialcandor_schema.audit_target_type
        WHEN 'data_breaches' THEN 'BREACH'::socialcandor_schema.audit_target_type
        WHEN 'privacy_impact_assessments' THEN 'PIA'::socialcandor_schema.audit_target_type
        WHEN 'ad_campaigns' THEN 'AD_CAMPAIGN'::socialcandor_schema.audit_target_type
        WHEN 'marketplace_orders' THEN 'ORDER'::socialcandor_schema.audit_target_type
        WHEN 'refund_requests' THEN 'REFUND'::socialcandor_schema.audit_target_type
        ELSE 'SYSTEM'::socialcandor_schema.audit_target_type
    END;

    -- Insert into audit_logs
    INSERT INTO socialcandor_schema.audit_logs (
        actor_user_id, action, target_type, target_id, before_state, after_state, occurred_at
    ) VALUES (
        v_actor, v_action, v_target_type, v_target_id, v_before, v_after, NOW()
    ) RETURNING audit_id INTO v_audit_id;

    RETURN NULL;  -- for AFTER triggers
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Apply triggers to each critical table (only if they exist)
DO $$
DECLARE
    tbl TEXT;
    tables TEXT[] := ARRAY[
        'users', 'users_sessions', 'user_wallets', 'wallet_transactions', 'payment_methods',
        'user_subscriptions', 'invoices', 'payouts', 'data_subject_requests', 'consent_records',
        'data_breaches', 'privacy_impact_assessments', 'ad_campaigns', 'marketplace_orders',
        'refund_requests'
    ];
BEGIN
    FOREACH tbl IN ARRAY tables LOOP
        EXECUTE format('
            DROP TRIGGER IF EXISTS trg_audit_%I ON socialcandor_schema.%I;
            CREATE TRIGGER trg_audit_%I
            AFTER INSERT OR UPDATE OR DELETE ON socialcandor_schema.%I
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.audit_trigger_function();',
            tbl, tbl, tbl, tbl);
    END LOOP;
END $$;

