-- =================================================================================================
-- 1. MULTI‑TENANCY & ORGANISATIONAL HIERARCHY
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: org_hierarchy
-- Description: Defines parent‑child relationships between organizations.
-- Business Case: Enables hierarchical organization structures (parent‑subsidiary, departments)
--                with depth‑based queries and reporting.
-- KPIs: Hierarchy depth distribution, number of child orgs per parent
-- Feature Reference: ORG04 (Organizational Hierarchy)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.org_hierarchy (
    hierarchy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    hierarchy_number VARCHAR(50) GENERATED ALWAYS AS (
        'OH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_hierarchy_seq')::TEXT, 6, '0')
    ) STORED,
    parent_org_id UUID NOT NULL,
    child_org_id UUID NOT NULL,
    depth INTEGER NOT NULL CHECK (depth >= 1),  -- Computed via application
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_org_hierarchy_parent FOREIGN KEY (parent_org_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_hierarchy_child FOREIGN KEY (child_org_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_hierarchy_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_org_hierarchy_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_org_hierarchy_pair UNIQUE (parent_org_id, child_org_id),
    CONSTRAINT chk_org_hierarchy_no_self CHECK (parent_org_id != child_org_id)
);
COMMENT ON TABLE socialcandor_schema.org_hierarchy IS 'Parent‑child relationships between organizations.';
CREATE INDEX idx_org_hierarchy_parent ON socialcandor_schema.org_hierarchy(parent_org_id);
CREATE INDEX idx_org_hierarchy_child ON socialcandor_schema.org_hierarchy(child_org_id);

------------------------------------------------------------------------------------------------
-- Table: org_members
-- Description: Associates users with organizations and defines their role.
-- Business Case: Manages membership and permissions at the organization level.
-- KPIs: Member count per org, role distribution, active vs. inactive members
-- Feature Reference: ORG05 (Organization Members)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.org_members (
    membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    membership_number VARCHAR(50) GENERATED ALWAYS AS (
        'OM-' || TO_CHAR(joined_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_members_seq')::TEXT, 6, '0')
    ) STORED,
    organization_id UUID NOT NULL,
    user_id UUID NOT NULL,
    role socialcandor_schema.organization_member_role NOT NULL DEFAULT 'MEMBER',
    joined_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    left_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_org_members_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_members_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_members_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_org_members_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_org_members_active UNIQUE (organization_id, user_id) WHERE is_active = TRUE
);
COMMENT ON TABLE socialcandor_schema.org_members IS 'Membership of users in organizations.';
CREATE INDEX idx_org_members_org ON socialcandor_schema.org_members(organization_id);
CREATE INDEX idx_org_members_user ON socialcandor_schema.org_members(user_id);
CREATE INDEX idx_org_members_active ON socialcandor_schema.org_members(is_active) WHERE is_active = TRUE;

------------------------------------------------------------------------------------------------
-- Table: org_settings
-- Description: Stores configuration settings per organization (e.g., branding, security policies).
-- Business Case: Allows per‑tenant customization without affecting others.
-- KPIs: Settings change frequency, most common overrides
-- Feature Reference: ORG06 (Organization Settings)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.org_settings (
    setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    setting_number VARCHAR(50) GENERATED ALWAYS AS (
        'OS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_settings_seq')::TEXT, 6, '0')
    ) STORED,
    organization_id UUID NOT NULL UNIQUE,
    settings JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_org_settings_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_settings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_org_settings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.org_settings IS 'Per‑organization configuration settings.';
CREATE INDEX idx_org_settings_org ON socialcandor_schema.org_settings(organization_id);

------------------------------------------------------------------------------------------------
-- Table: org_billing
-- Description: Tracks consolidated invoicing and billing for organizations.
-- Business Case: Supports enterprise billing with multiple payment methods and invoice history.
-- KPIs: Total billed per org, payment status, overdue amounts
-- Feature Reference: ORG07 (Organization Billing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.org_billing (
    billing_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    billing_number VARCHAR(50) GENERATED ALWAYS AS (
        'OB-' || TO_CHAR(billing_period_start, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_billing_seq')::TEXT, 6, '0')
    ) STORED,
    organization_id UUID NOT NULL,
    billing_period_start DATE NOT NULL,
    billing_period_end DATE NOT NULL,
    total_amount NUMERIC(15,2) NOT NULL CHECK (total_amount >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    invoice_id UUID,  -- link to invoices table (if exists)
    payment_status VARCHAR(20) CHECK (payment_status IN ('PENDING', 'PAID', 'OVERDUE', 'PARTIALLY_PAID')),
    paid_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_org_billing_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_org_billing_invoice FOREIGN KEY (invoice_id)
        REFERENCES socialcandor_schema.invoices(invoice_id) ON DELETE SET NULL,
    CONSTRAINT fk_org_billing_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_org_billing_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_org_billing_dates CHECK (billing_period_end >= billing_period_start)
);
COMMENT ON TABLE socialcandor_schema.org_billing IS 'Consolidated billing records for organizations.';
CREATE INDEX idx_org_billing_org ON socialcandor_schema.org_billing(organization_id, billing_period_start DESC);
CREATE INDEX idx_org_billing_invoice ON socialcandor_schema.org_billing(invoice_id) WHERE invoice_id IS NOT NULL;

-- =================================================================================================
-- 2. EXTERNAL INTEGRATIONS & WEBHOOKS
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: webhook_endpoints
-- Description: Stores registered webhook endpoints for external systems.
-- Business Case: Enables event‑driven architecture, notifying partners of platform events.
-- KPIs: Number of active endpoints, events per endpoint, failure rate
-- Feature Reference: INT02 (Webhooks)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.webhook_endpoints (
    endpoint_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    endpoint_number VARCHAR(50) GENERATED ALWAYS AS (
        'WH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.webhook_endpoint_seq')::TEXT, 6, '0')
    ) STORED,
    url VARCHAR(500) NOT NULL,
    secret VARCHAR(255),  -- for HMAC signing
    events TEXT[] NOT NULL,  -- e.g., {'user.created', 'post.published'}
    is_active BOOLEAN DEFAULT TRUE,
    owner_user_id UUID,
    owner_organization_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_webhook_endpoints_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_webhook_endpoints_owner_org FOREIGN KEY (owner_organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_webhook_endpoints_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_webhook_endpoints_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_webhook_owner CHECK (owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL)
);
COMMENT ON TABLE socialcandor_schema.webhook_endpoints IS 'Registered webhook endpoints for external systems.';
CREATE INDEX idx_webhook_endpoints_owner ON socialcandor_schema.webhook_endpoints(owner_user_id, owner_organization_id);
CREATE INDEX idx_webhook_endpoints_active ON socialcandor_schema.webhook_endpoints(is_active) WHERE is_active = TRUE;

------------------------------------------------------------------------------------------------
-- Table: webhook_delivery_logs
-- Description: Records every delivery attempt of a webhook, including response and retries.
-- Business Case: Provides audit trail and debugging for webhook failures.
-- KPIs: Success rate, average latency, retry count distribution
-- Feature Reference: INT03 (Webhook Logging)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.webhook_delivery_logs (
    log_id BIGSERIAL PRIMARY KEY,
    endpoint_id UUID NOT NULL,
    event_name VARCHAR(255) NOT NULL,
    payload JSONB NOT NULL,
    response_status INTEGER,
    response_body TEXT,
    attempt_number INTEGER DEFAULT 1 CHECK (attempt_number >= 1),
    success BOOLEAN,
    error_message TEXT,
    delivered_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_webhook_delivery_logs_endpoint FOREIGN KEY (endpoint_id)
        REFERENCES socialcandor_schema.webhook_endpoints(endpoint_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.webhook_delivery_logs IS 'Logs of webhook delivery attempts.';
CREATE INDEX idx_webhook_logs_endpoint ON socialcandor_schema.webhook_delivery_logs(endpoint_id, delivered_at DESC);
CREATE INDEX idx_webhook_logs_event ON socialcandor_schema.webhook_delivery_logs(event_name);

------------------------------------------------------------------------------------------------
-- Table: integrations
-- Description: Stores OAuth tokens and configuration for third‑party services.
-- Business Case: Manages connections to external platforms like Salesforce, HubSpot, Slack.
-- KPIs: Number of active integrations, refresh success rate
-- Feature Reference: INT04 (Third‑Party Integrations)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.integrations (
    integration_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    integration_number VARCHAR(50) GENERATED ALWAYS AS (
        'INT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.integration_seq')::TEXT, 6, '0')
    ) STORED,
    integration_type socialcandor_schema.integration_type NOT NULL,
    name VARCHAR(255) NOT NULL,
    owner_user_id UUID,
    owner_organization_id UUID,
    access_token_encrypted TEXT,
    refresh_token_encrypted TEXT,
    token_expires_at TIMESTAMP WITH TIME ZONE,
    scopes TEXT[],
    config JSONB DEFAULT '{}',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_integrations_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_integrations_owner_org FOREIGN KEY (owner_organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_integrations_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_integrations_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_integrations_owner CHECK (owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL)
);
COMMENT ON TABLE socialcandor_schema.integrations IS 'Third‑party service integrations with OAuth tokens.';
CREATE INDEX idx_integrations_owner ON socialcandor_schema.integrations(owner_user_id, owner_organization_id);
CREATE INDEX idx_integrations_type ON socialcandor_schema.integrations(integration_type);

-- =================================================================================================
-- 3. ADVANCED ENCRYPTION & KEY MANAGEMENT
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: encryption_keys
-- Description: Manages encryption keys with lifecycle states and metadata.
-- Business Case: Centralised key management for envelope encryption, key rotation, and compliance.
-- KPIs: Number of active keys, rotation frequency, key age
-- Feature Reference: ENC02 (Key Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.encryption_keys (
    key_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    key_number VARCHAR(50) GENERATED ALWAYS AS (
        'KEY-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.encryption_key_seq')::TEXT, 6, '0')
    ) STORED,
    key_alias VARCHAR(100) UNIQUE,
    key_type VARCHAR(20) CHECK (key_type IN ('AES', 'RSA', 'ECC')),
    key_length INTEGER CHECK (key_length IN (128, 192, 256, 2048, 3072, 4096)),
    wrapped_key BYTEA,  -- if using envelope encryption
    key_state socialcandor_schema.encryption_key_state NOT NULL DEFAULT 'ACTIVE',
    activated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    rotation_schedule_days INTEGER CHECK (rotation_schedule_days >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_encryption_keys_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_encryption_keys_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_encryption_key_dates CHECK (deactivated_at IS NULL OR deactivated_at >= activated_at)
);
COMMENT ON TABLE socialcandor_schema.encryption_keys IS 'Encryption key metadata and wrapped keys.';
CREATE INDEX idx_encryption_keys_state ON socialcandor_schema.encryption_keys(key_state);

------------------------------------------------------------------------------------------------
-- Table: key_rotation_jobs
-- Description: Tracks scheduled and executed key rotation tasks.
-- Business Case: Automates key rotation, ensures compliance with security policies.
-- KPIs: Rotation success rate, average rotation time
-- Feature Reference: ENC03 (Key Rotation)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.key_rotation_jobs (
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'ROT-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.key_rotation_job_seq')::TEXT, 6, '0')
    ) STORED,
    key_id UUID NOT NULL,
    scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.key_rotation_status NOT NULL DEFAULT 'PENDING',
    new_key_id UUID,  -- the newly created key
    error_message TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_key_rotation_jobs_key FOREIGN KEY (key_id)
        REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE CASCADE,
    CONSTRAINT fk_key_rotation_jobs_new_key FOREIGN KEY (new_key_id)
        REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
    CONSTRAINT fk_key_rotation_jobs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_key_rotation_jobs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.key_rotation_jobs IS 'Jobs for automated encryption key rotation.';
CREATE INDEX idx_key_rotation_jobs_key ON socialcandor_schema.key_rotation_jobs(key_id);
CREATE INDEX idx_key_rotation_jobs_status ON socialcandor_schema.key_rotation_jobs(status);

------------------------------------------------------------------------------------------------
-- Table: data_encryption_config
-- Description: Defines which columns/tables are encrypted and with which key.
-- Business Case: Central configuration for data‑at‑rest encryption.
-- KPIs: Encryption coverage, compliance with data classification
-- Feature Reference: ENC04 (Data Encryption Configuration)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_encryption_config (
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    config_number VARCHAR(50) GENERATED ALWAYS AS (
        'DEC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_encryption_config_seq')::TEXT, 6, '0')
    ) STORED,
    schema_name VARCHAR(100) NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    column_name VARCHAR(100) NOT NULL,
    key_id UUID NOT NULL,
    encryption_algorithm VARCHAR(50) DEFAULT 'AES-256-GCM',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_data_encryption_config_key FOREIGN KEY (key_id)
        REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_encryption_config_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_encryption_config_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_data_encryption_config UNIQUE (schema_name, table_name, column_name)
);
COMMENT ON TABLE socialcandor_schema.data_encryption_config IS 'Configuration of encrypted columns.';
CREATE INDEX idx_data_encryption_config_key ON socialcandor_schema.data_encryption_config(key_id);

-- =================================================================================================
-- 4. DATA RETENTION ENFORCEMENT ENGINE
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: retention_enforcement_jobs
-- Description: Tracks execution of data retention policies (deletion/archival).
-- Business Case: Automates enforcement, provides audit trail.
-- KPIs: Job success rate, data volume processed, average runtime
-- Feature Reference: RET02 (Retention Enforcement)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.retention_enforcement_jobs (
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'REJ-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.retention_enforcement_job_seq')::TEXT, 6, '0')
    ) STORED,
    policy_id UUID NOT NULL,  -- references data_retention_policies
    scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    status socialcandor_schema.enforcement_job_status NOT NULL DEFAULT 'PENDING',
    rows_affected INTEGER CHECK (rows_affected >= 0),
    archived_location VARCHAR(500),
    error_message TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_retention_enforcement_jobs_policy FOREIGN KEY (policy_id)
        REFERENCES socialcandor_schema.data_retention_policies(policy_id) ON DELETE CASCADE,
    CONSTRAINT fk_retention_enforcement_jobs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_retention_enforcement_jobs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.retention_enforcement_jobs IS 'Jobs executing data retention policies.';
CREATE INDEX idx_retention_enforcement_jobs_policy ON socialcandor_schema.retention_enforcement_jobs(policy_id);
CREATE INDEX idx_retention_enforcement_jobs_status ON socialcandor_schema.retention_enforcement_jobs(status);

------------------------------------------------------------------------------------------------
-- Table: archived_data_catalog
-- Description: Metadata of archived data (where, what, when).
-- Business Case: Enables retrieval of archived data for compliance or legal hold.
-- KPIs: Archived data volume, retrieval requests
-- Feature Reference: RET03 (Archival Management)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.archived_data_catalog (
    archive_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    archive_number VARCHAR(50) GENERATED ALWAYS AS (
        'ARC-' || TO_CHAR(archived_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.archived_data_catalog_seq')::TEXT, 6, '0')
    ) STORED,
    original_schema VARCHAR(100) NOT NULL,
    original_table VARCHAR(100) NOT NULL,
    archived_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archived_by UUID NOT NULL,
    archive_location VARCHAR(500) NOT NULL,
    row_count INTEGER CHECK (row_count >= 0),
    size_bytes BIGINT CHECK (size_bytes >= 0),
    retention_policy_id UUID,
    legal_hold_until TIMESTAMP WITH TIME ZONE,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_archived_data_catalog_archived_by FOREIGN KEY (archived_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_archived_data_catalog_policy FOREIGN KEY (retention_policy_id)
        REFERENCES socialcandor_schema.data_retention_policies(policy_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.archived_data_catalog IS 'Metadata of archived data for later retrieval.';
CREATE INDEX idx_archived_data_catalog_table ON socialcandor_schema.archived_data_catalog(original_schema, original_table);
CREATE INDEX idx_archived_data_catalog_archived_at ON socialcandor_schema.archived_data_catalog(archived_at DESC);

-- =================================================================================================
-- 5. DATA VERSIONING & REPRODUCIBILITY
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: dataset_versions
-- Description: Tracks snapshots of datasets used for training or analysis.
-- Business Case: Enables reproducibility of ML experiments and compliance audits.
-- KPIs: Number of versions per dataset, version size
-- Feature Reference: MLOP08 (Dataset Versioning)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.dataset_versions (
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    version_number VARCHAR(50) GENERATED ALWAYS AS (
        'DSV-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dataset_version_seq')::TEXT, 6, '0')
    ) STORED,
    dataset_name VARCHAR(255) NOT NULL,
    dataset_description TEXT,
    source_query TEXT,  -- SQL or other query used
    snapshot_time TIMESTAMP WITH TIME ZONE NOT NULL,
    row_count INTEGER CHECK (row_count >= 0),
    file_url VARCHAR(500),  -- location of the exported dataset
    checksum VARCHAR(64),   -- for integrity
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_dataset_versions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dataset_versions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.dataset_versions IS 'Snapshots of datasets for reproducibility.';
CREATE INDEX idx_dataset_versions_name ON socialcandor_schema.dataset_versions(dataset_name, snapshot_time DESC);

------------------------------------------------------------------------------------------------
-- Table: model_training_runs
-- Description: Detailed logs of ML model training runs.
-- Business Case: Tracks hyperparameters, metrics, and data versions for experiment tracking.
-- KPIs: Number of runs per model, average run time, success rate
-- Feature Reference: MLOP09 (Training Run Tracking)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_training_runs (
    run_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    run_number VARCHAR(50) GENERATED ALWAYS AS (
        'MTR-' || TO_CHAR(start_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_training_run_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    version_id UUID,  -- may be created after run
    run_name VARCHAR(255),
    git_commit_hash VARCHAR(64),
    training_data_version_id UUID,  -- links to dataset_versions
    validation_data_version_id UUID,
    parameters JSONB,
    metrics JSONB,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE,
    status VARCHAR(20) CHECK (status IN ('RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_model_training_runs_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_model_training_runs_version FOREIGN KEY (version_id)
        REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE SET NULL,
    CONSTRAINT fk_model_training_runs_training_data FOREIGN KEY (training_data_version_id)
        REFERENCES socialcandor_schema.dataset_versions(version_id) ON DELETE SET NULL,
    CONSTRAINT fk_model_training_runs_validation_data FOREIGN KEY (validation_data_version_id)
        REFERENCES socialcandor_schema.dataset_versions(version_id) ON DELETE SET NULL,
    CONSTRAINT fk_model_training_runs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_model_training_runs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.model_training_runs IS 'Detailed logs of model training runs.';
CREATE INDEX idx_model_training_runs_model ON socialcandor_schema.model_training_runs(model_id, start_time DESC);
CREATE INDEX idx_model_training_runs_status ON socialcandor_schema.model_training_runs(status);

------------------------------------------------------------------------------------------------
-- Table: api_response_snapshots
-- Description: Stores snapshots of API responses for debugging and audit.
-- Business Case: Helps troubleshoot issues and provides evidence in regulated industries.
-- KPIs: Snapshot frequency, retrieval requests
-- Feature Reference: API08 (API Audit)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_response_snapshots (
    snapshot_id BIGSERIAL PRIMARY KEY,
    snapshot_number VARCHAR(50) GENERATED ALWAYS AS (
        'ARS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.api_response_snapshot_seq')::TEXT, 6, '0')
    ) STORED,
    request_id UUID,  -- if you have request tracking
    endpoint VARCHAR(500) NOT NULL,
    request_payload JSONB,
    response_payload JSONB,
    http_status INTEGER,
    user_id UUID,
    api_key_id UUID,
    client_ip INET,
    user_agent TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_api_response_snapshots_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_response_snapshots_api_key FOREIGN KEY (api_key_id)
        REFERENCES socialcandor_schema.api_keys(api_key_id) ON DELETE SET NULL
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE socialcandor_schema.api_response_snapshots IS 'Snapshots of API responses for audit.';
CREATE INDEX idx_api_response_snapshots_endpoint ON socialcandor_schema.api_response_snapshots(endpoint, created_at DESC);
CREATE INDEX idx_api_response_snapshots_user ON socialcandor_schema.api_response_snapshots(user_id) WHERE user_id IS NOT NULL;

-- =================================================================================================
-- 6. ADVANCED ACCESS CONTROL – ATTRIBUTE‑BASED ACCESS CONTROL (ABAC)
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: policy_definitions
-- Description: Stores ABAC rules in a structured format.
-- Business Case: Enables fine‑grained access decisions based on user and resource attributes.
-- KPIs: Number of policies, complexity score, evaluation time
-- Feature Reference: ABAC01 (Attribute‑Based Access Control)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.policy_definitions (
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    policy_number VARCHAR(50) GENERATED ALWAYS AS (
        'POL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.policy_definition_seq')::TEXT, 6, '0')
    ) STORED,
    policy_name VARCHAR(255) NOT NULL,
    description TEXT,
    effect socialcandor_schema.policy_effect NOT NULL,
    subject_attributes JSONB NOT NULL,   -- e.g., {"role": "manager", "department": "sales"}
    resource_attributes JSONB NOT NULL,  -- e.g., {"type": "report", "owner": "current_user"}
    environment_attributes JSONB,         -- e.g., {"time": "business_hours"}
    priority INTEGER DEFAULT 1 CHECK (priority >= 1),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_policy_definitions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_policy_definitions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.policy_definitions IS 'ABAC policy definitions.';
CREATE INDEX idx_policy_definitions_active ON socialcandor_schema.policy_definitions(is_active) WHERE is_active = TRUE;

------------------------------------------------------------------------------------------------
-- Table: policy_evaluation_logs
-- Description: Records every ABAC policy evaluation for audit.
-- Business Case: Provides evidence of access decisions for compliance.
-- KPIs: Evaluation count, most evaluated policies, decision distribution
-- Feature Reference: ABAC02 (Policy Audit)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.policy_evaluation_logs (
    log_id BIGSERIAL PRIMARY KEY,
    evaluation_number VARCHAR(50) GENERATED ALWAYS AS (
        'PEL-' || TO_CHAR(evaluated_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.policy_evaluation_log_seq')::TEXT, 6, '0')
    ) STORED,
    policy_id UUID,
    user_id UUID,
    resource_type VARCHAR(100),
    resource_id UUID,
    decision socialcandor_schema.policy_effect,
    reason TEXT,
    evaluated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_policy_evaluation_logs_policy FOREIGN KEY (policy_id)
        REFERENCES socialcandor_schema.policy_definitions(policy_id) ON DELETE SET NULL,
    CONSTRAINT fk_policy_evaluation_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.policy_evaluation_logs IS 'Logs of ABAC policy evaluations.';
CREATE INDEX idx_policy_evaluation_logs_policy ON socialcandor_schema.policy_evaluation_logs(policy_id);
CREATE INDEX idx_policy_evaluation_logs_user ON socialcandor_schema.policy_evaluation_logs(user_id);
CREATE INDEX idx_policy_evaluation_logs_evaluated_at ON socialcandor_schema.policy_evaluation_logs(evaluated_at DESC);

-- =================================================================================================
-- 7. CUSTOMER SUPPORT & KNOWLEDGE MANAGEMENT ENHANCEMENT
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: csat_surveys
-- Description: Post‑ticket customer satisfaction surveys.
-- Business Case: Measures user satisfaction, identifies areas for improvement.
-- KPIs: Average CSAT score, response rate, trend over time
-- Feature Reference: SUP03 (CSAT)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.csat_surveys (
    survey_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    survey_number VARCHAR(50) GENERATED ALWAYS AS (
        'CSAT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.csat_survey_seq')::TEXT, 6, '0')
    ) STORED,
    ticket_id UUID NOT NULL,
    user_id UUID NOT NULL,
    rating INTEGER CHECK (rating >= 1 AND rating <= 5),
    comment TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_csat_surveys_ticket FOREIGN KEY (ticket_id)
        REFERENCES socialcandor_schema.support_ticketing(ticket_id) ON DELETE CASCADE,
    CONSTRAINT fk_csat_surveys_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_csat_surveys_ticket UNIQUE (ticket_id)
);
COMMENT ON TABLE socialcandor_schema.csat_surveys IS 'Post‑ticket customer satisfaction surveys.';
CREATE INDEX idx_csat_surveys_ticket ON socialcandor_schema.csat_surveys(ticket_id);
CREATE INDEX idx_csat_surveys_rating ON socialcandor_schema.csat_surveys(rating);

------------------------------------------------------------------------------------------------
-- Table: sla_violations
-- Description: Tracks when support SLAs are breached.
-- Business Case: Monitors compliance, triggers escalation, and supports reporting.
-- KPIs: Number of violations, average response time, time to resolve
-- Feature Reference: SUP04 (SLA Monitoring)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.sla_violations (
    violation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    violation_number VARCHAR(50) GENERATED ALWAYS AS (
        'SLAV-' || TO_CHAR(violation_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.sla_violation_seq')::TEXT, 6, '0')
    ) STORED,
    ticket_id UUID NOT NULL,
    sla_id UUID,  -- references sla_definitions
    violation_type VARCHAR(50) CHECK (violation_type IN ('RESPONSE', 'RESOLUTION')),
    violation_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    target_minutes INTEGER,
    actual_minutes INTEGER,
    notified BOOLEAN DEFAULT FALSE,
    escalated_to UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_sla_violations_ticket FOREIGN KEY (ticket_id)
        REFERENCES socialcandor_schema.support_ticketing(ticket_id) ON DELETE CASCADE,
    CONSTRAINT fk_sla_violations_sla FOREIGN KEY (sla_id)
        REFERENCES socialcandor_schema.sla_definitions(sla_id) ON DELETE SET NULL,
    CONSTRAINT fk_sla_violations_escalated_to FOREIGN KEY (escalated_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.sla_violations IS 'Records of SLA breaches for support tickets.';
CREATE INDEX idx_sla_violations_ticket ON socialcandor_schema.sla_violations(ticket_id);
CREATE INDEX idx_sla_violations_time ON socialcandor_schema.sla_violations(violation_time DESC);

------------------------------------------------------------------------------------------------
-- Table: knowledge_base_feedback
-- Description: User ratings on knowledge base articles.
-- Business Case: Improves content quality, identifies gaps.
-- KPIs: Average rating per article, helpfulness percentage, feedback volume
-- Feature Reference: KB03 (Article Feedback)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.knowledge_base_feedback (
    feedback_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    feedback_number VARCHAR(50) GENERATED ALWAYS AS (
        'KBF-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.kb_feedback_seq')::TEXT, 6, '0')
    ) STORED,
    article_id UUID NOT NULL,
    user_id UUID NOT NULL,
    helpful BOOLEAN NOT NULL,
    comment TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_kb_feedback_article FOREIGN KEY (article_id)
        REFERENCES socialcandor_schema.knowledge_articles(article_id) ON DELETE CASCADE,
    CONSTRAINT fk_kb_feedback_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_kb_feedback_user_article UNIQUE (user_id, article_id)
);
COMMENT ON TABLE socialcandor_schema.knowledge_base_feedback IS 'User feedback on knowledge base articles.';
CREATE INDEX idx_kb_feedback_article ON socialcandor_schema.knowledge_base_feedback(article_id);
CREATE INDEX idx_kb_feedback_helpful ON socialcandor_schema.knowledge_base_feedback(helpful);

-- =================================================================================================
-- 8. B2B / ENTERPRISE COLLABORATION
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: workspace_templates
-- Description: Pre‑defined structures for new projects or workspaces.
-- Business Case: Accelerates onboarding of new teams with consistent setups.
-- KPIs: Template usage count, most popular templates
-- Feature Reference: COL04 (Workspace Templates)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.workspace_templates (
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    template_number VARCHAR(50) GENERATED ALWAYS AS (
        'WST-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.workspace_template_seq')::TEXT, 6, '0')
    ) STORED,
    template_name VARCHAR(255) NOT NULL,
    description TEXT,
    template_data JSONB NOT NULL,  -- e.g., folder structure, default permissions
    is_public BOOLEAN DEFAULT FALSE,
    owner_user_id UUID,
    owner_organization_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_workspace_templates_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_workspace_templates_owner_org FOREIGN KEY (owner_organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_workspace_templates_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_workspace_templates_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_workspace_templates_owner CHECK (owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL)
);
COMMENT ON TABLE socialcandor_schema.workspace_templates IS 'Templates for creating new workspaces.';
CREATE INDEX idx_workspace_templates_owner ON socialcandor_schema.workspace_templates(owner_user_id, owner_organization_id);

------------------------------------------------------------------------------------------------
-- Table: document_collaborators
-- Description: Manages permissions for collaborative document editing.
-- Business Case: Enables real‑time co‑editing with fine‑grained access.
-- KPIs: Number of collaborators per document, permission changes
-- Feature Reference: COL05 (Document Collaboration)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.document_collaborators (
    collaborator_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    collaborator_number VARCHAR(50) GENERATED ALWAYS AS (
        'DOC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.document_collaborator_seq')::TEXT, 6, '0')
    ) STORED,
    document_id UUID NOT NULL,  -- could reference a document table; we assume a generic ID
    document_type VARCHAR(50) CHECK (document_type IN ('PAGE', 'FILE', 'NOTE')),
    user_id UUID NOT NULL,
    permission_level VARCHAR(20) CHECK (permission_level IN ('VIEW', 'COMMENT', 'EDIT', 'ADMIN')),
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    added_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_document_collaborators_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_document_collaborators_added_by FOREIGN KEY (added_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_document_collaborators_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_document_collaborator UNIQUE (document_id, document_type, user_id)
);
COMMENT ON TABLE socialcandor_schema.document_collaborators IS 'Collaborators and permissions for documents.';
CREATE INDEX idx_document_collaborators_document ON socialcandor_schema.document_collaborators(document_id, document_type);
CREATE INDEX idx_document_collaborators_user ON socialcandor_schema.document_collaborators(user_id);

------------------------------------------------------------------------------------------------
-- Table: approval_workflow_templates
-- Description: Reusable templates for content approval workflows.
-- Business Case: Standardises approval processes across teams.
-- KPIs: Template usage, average approval time
-- Feature Reference: WF04 (Approval Workflows)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.approval_workflow_templates (
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    template_number VARCHAR(50) GENERATED ALWAYS AS (
        'AWT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.approval_workflow_template_seq')::TEXT, 6, '0')
    ) STORED,
    template_name VARCHAR(255) NOT NULL,
    description TEXT,
    workflow_steps JSONB NOT NULL,  -- e.g., [{step: 1, approver_role: 'MANAGER'}, ...]
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_approval_workflow_templates_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_approval_workflow_templates_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.approval_workflow_templates IS 'Templates for content approval workflows.';
CREATE INDEX idx_approval_workflow_templates_active ON socialcandor_schema.approval_workflow_templates(is_active) WHERE is_active = TRUE;

-- =================================================================================================
-- 9. DATA SHARING & DATA ROOMS
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: data_rooms
-- Description: Virtual rooms with access controls for secure data sharing with external parties.
-- Business Case: Enables secure collaboration with auditors, partners, customers.
-- KPIs: Number of active rooms, external user count, asset count
-- Feature Reference: SHR01 (Data Rooms)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_rooms (
    room_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    room_number VARCHAR(50) GENERATED ALWAYS AS (
        'DR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_room_seq')::TEXT, 6, '0')
    ) STORED,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    owner_id UUID NOT NULL,
    access_scope VARCHAR(20) CHECK (access_scope IN ('INTERNAL', 'EXTERNAL')),
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_data_rooms_owner FOREIGN KEY (owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_rooms_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_rooms_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_rooms IS 'Secure virtual rooms for data sharing.';
CREATE INDEX idx_data_rooms_owner ON socialcandor_schema.data_rooms(owner_id);
CREATE INDEX idx_data_rooms_expires ON socialcandor_schema.data_rooms(expires_at) WHERE expires_at IS NOT NULL;

-- Table: data_room_assets (join table between rooms and assets)
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_room_assets (
    asset_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    room_id UUID NOT NULL,
    asset_type VARCHAR(50) NOT NULL,  -- e.g., 'TABLE', 'FILE', 'DASHBOARD'
    asset_identifier VARCHAR(500) NOT NULL,
    added_by UUID NOT NULL,
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_data_room_assets_room FOREIGN KEY (room_id)
        REFERENCES socialcandor_schema.data_rooms(room_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_room_assets_added_by FOREIGN KEY (added_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT uk_data_room_assets UNIQUE (room_id, asset_type, asset_identifier)
);
COMMENT ON TABLE socialcandor_schema.data_room_assets IS 'Assets linked to a data room.';
CREATE INDEX idx_data_room_assets_room ON socialcandor_schema.data_room_assets(room_id);

------------------------------------------------------------------------------------------------
-- Table: shared_links
-- Description: Time‑limited, revocable links to specific data.
-- Business Case: Enables secure, temporary sharing without authentication.
-- KPIs: Link usage count, expiry adherence, revocation rate
-- Feature Reference: SHR02 (Shared Links)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.shared_links (
    link_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    link_number VARCHAR(50) GENERATED ALWAYS AS (
        'SL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.shared_link_seq')::TEXT, 6, '0')
    ) STORED,
    token VARCHAR(255) UNIQUE NOT NULL,
    owner_id UUID NOT NULL,
    asset_type VARCHAR(50) NOT NULL,
    asset_id UUID NOT NULL,
    password_hash VARCHAR(255),  -- optional password protection
    max_uses INTEGER CHECK (max_uses >= 0),
    current_uses INTEGER DEFAULT 0 CHECK (current_uses >= 0),
    expires_at TIMESTAMP WITH TIME ZONE,
    revoked_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_shared_links_owner FOREIGN KEY (owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_shared_links_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_shared_links_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_shared_links_uses CHECK (max_uses IS NULL OR current_uses <= max_uses),
    CONSTRAINT chk_shared_links_expiry CHECK (expires_at IS NULL OR expires_at > created_at)
);
COMMENT ON TABLE socialcandor_schema.shared_links IS 'Time‑limited, revocable links to data.';
CREATE INDEX idx_shared_links_token ON socialcandor_schema.shared_links(token);
CREATE INDEX idx_shared_links_owner ON socialcandor_schema.shared_links(owner_id);

------------------------------------------------------------------------------------------------
-- Table: data_export_packages
-- Description: Pre‑packaged exports for sharing or archiving.
-- Business Case: Allows creation of portable data packages with metadata.
-- KPIs: Export size, download count, package age
-- Feature Reference: SHR03 (Data Exports)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_export_packages (
    package_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    package_number VARCHAR(50) GENERATED ALWAYS AS (
        'DEP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_export_package_seq')::TEXT, 6, '0')
    ) STORED,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    owner_id UUID NOT NULL,
    file_url VARCHAR(500) NOT NULL,
    file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
    format VARCHAR(20) CHECK (format IN ('CSV', 'JSON', 'PARQUET', 'AVRO')),
    checksum VARCHAR(64),
    expires_at TIMESTAMP WITH TIME ZONE,
    download_count INTEGER DEFAULT 0 CHECK (download_count >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_data_export_packages_owner FOREIGN KEY (owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_export_packages_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_export_packages_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.data_export_packages IS 'Pre‑packaged data exports for sharing.';
CREATE INDEX idx_data_export_packages_owner ON socialcandor_schema.data_export_packages(owner_id);
CREATE INDEX idx_data_export_packages_expires ON socialcandor_schema.data_export_packages(expires_at) WHERE expires_at IS NOT NULL;

-- =================================================================================================
-- 10. OBSERVABILITY & SELF‑HEALING
-- =================================================================================================

------------------------------------------------------------------------------------------------
-- Table: auto_remediation_actions
-- Description: Defines automated actions to take when anomalies are detected.
-- Business Case: Enables self‑healing infrastructure, reducing manual intervention.
-- KPIs: Action success rate, time to resolution, number of incidents avoided
-- Feature Reference: OBS01 (Auto‑Remediation)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.auto_remediation_actions (
    action_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    action_number VARCHAR(50) GENERATED ALWAYS AS (
        'ARA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.auto_remediation_action_seq')::TEXT, 6, '0')
    ) STORED,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    trigger_condition JSONB NOT NULL,  -- e.g., {"metric": "cpu_usage", "threshold": 90}
    action_type VARCHAR(50) CHECK (action_type IN ('RESTART_SERVICE', 'SCALE_UP', 'CLEAR_CACHE', 'NOTIFY_ADMIN')),
    action_params JSONB,
    cooldown_minutes INTEGER DEFAULT 10 CHECK (cooldown_minutes >= 0),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_auto_remediation_actions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_auto_remediation_actions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.auto_remediation_actions IS 'Automated actions for system self‑healing.';
CREATE INDEX idx_auto_remediation_actions_active ON socialcandor_schema.auto_remediation_actions(is_active) WHERE is_active = TRUE;

------------------------------------------------------------------------------------------------
-- Table: anomaly_alerts
-- Description: Stores alerts generated by anomaly detection systems.
-- Business Case: Centralised alerting with severity, assignment, and resolution tracking.
-- KPIs: Alert volume, mean time to acknowledge, mean time to resolve
-- Feature Reference: OBS02 (Anomaly Alerting)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.anomaly_alerts (
    alert_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    alert_number VARCHAR(50) GENERATED ALWAYS AS (
        'ALA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.anomaly_alert_seq')::TEXT, 6, '0')
    ) STORED,
    alert_name VARCHAR(255) NOT NULL,
    severity socialcandor_schema.alert_severity NOT NULL,
    source_system VARCHAR(100),
    metric_name VARCHAR(100),
    metric_value NUMERIC,
    threshold NUMERIC,
    description TEXT,
    assigned_to UUID,
    status VARCHAR(20) CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED', 'IGNORED')),
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolution_notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_anomaly_alerts_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_anomaly_alerts_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_anomaly_alerts_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.anomaly_alerts IS 'Alerts from anomaly detection systems.';
CREATE INDEX idx_anomaly_alerts_severity ON socialcandor_schema.anomaly_alerts(severity);
CREATE INDEX idx_anomaly_alerts_status ON socialcandor_schema.anomaly_alerts(status);
CREATE INDEX idx_anomaly_alerts_created ON socialcandor_schema.anomaly_alerts(created_at DESC);

