-- Table: model_bias_tests
-- Description: Results of fairness and bias testing on models.
-- Business Case: Ensures models are fair, meets ethical standards.
-- KPIs: Number of tests, pass rate, most common bias types
-- Feature Reference: AIETH04 (Bias Testing)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS socialcandor_schema.model_bias_tests (
    test_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    test_number VARCHAR(50) GENERATED ALWAYS AS (
        'MBT-' || TO_CHAR(test_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_bias_test_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    version_id UUID,
    test_date DATE NOT NULL DEFAULT CURRENT_DATE,
    test_type VARCHAR(50) CHECK (test_type IN ('RACIAL_BIAS', 'GENDER_BIAS', 'FAIRNESS', 'DISPARATE_IMPACT')),
    outcome socialcandor_schema.bias_test_outcome NOT NULL,
    metrics JSONB,  -- e.g., disparate impact ratio
    report_url VARCHAR(500),
    tested_by UUID NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
