        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_regulatory_approvals_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
