-- =================================================================================================
-- ROW LEVEL SECURITY POLICIES (simplified – many require admin‑only or owner access)
-- =================================================================================================

-- Enable RLS on all new tables
DO $$
DECLARE
    tbl text;
    tables text[] := ARRAY[
        'org_hierarchy', 'org_members', 'org_settings', 'org_billing',
        'webhook_endpoints', 'webhook_delivery_logs', 'integrations',
        'encryption_keys', 'key_rotation_jobs', 'data_encryption_config',
        'retention_enforcement_jobs', 'archived_data_catalog',
        'dataset_versions', 'model_training_runs', 'api_response_snapshots',
        'policy_definitions', 'policy_evaluation_logs',
        'csat_surveys', 'sla_violations', 'knowledge_base_feedback',
        'workspace_templates', 'document_collaborators', 'approval_workflow_templates',
        'data_rooms', 'data_room_assets', 'shared_links', 'data_export_packages',
        'auto_remediation_actions', 'anomaly_alerts', 'runbooks',
        'model_bias_tests', 'explainability_records', 'regulatory_approvals',
        'wallet_addresses', 'nft_metadata', 'smart_contract_interactions'
    ];
BEGIN
    FOREACH tbl IN ARRAY tables LOOP
        EXECUTE format('ALTER TABLE socialcandor_schema.%I ENABLE ROW LEVEL SECURITY;', tbl);
    END LOOP;
END $$;

-- Admin policy (simplified – assumes an is_admin function exists)
CREATE OR REPLACE FUNCTION socialcandor_schema.is_admin() RETURNS BOOLEAN AS $$
    SELECT EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE);
$$ LANGUAGE sql STABLE SECURITY DEFINER;

-- Apply admin‑only policies to most tables (customize as needed)
DO $$
DECLARE
    tbl text;
    tables text[] := ARRAY[
        'org_hierarchy', 'org_settings', 'org_billing',
        'webhook_endpoints', 'webhook_delivery_logs', 'integrations',
        'encryption_keys', 'key_rotation_jobs', 'data_encryption_config',
        'retention_enforcement_jobs', 'archived_data_catalog',
        'dataset_versions', 'model_training_runs', 'api_response_snapshots',
        'policy_definitions', 'policy_evaluation_logs',
        'sla_violations',
        'workspace_templates', 'approval_workflow_templates',
        'data_rooms', 'data_room_assets', 'shared_links', 'data_export_packages',
        'auto_remediation_actions', 'anomaly_alerts', 'runbooks',
        'model_bias_tests', 'explainability_records', 'regulatory_approvals',
        'wallet_addresses', 'nft_metadata', 'smart_contract_interactions'
    ];
BEGIN
    FOREACH tbl IN ARRAY tables LOOP
        EXECUTE format('
            DROP POLICY IF EXISTS %I_admin_policy ON socialcandor_schema.%I;
            CREATE POLICY %I_admin_policy ON socialcandor_schema.%I
                FOR ALL USING (socialcandor_schema.is_admin());
        ', tbl, tbl, tbl, tbl);
    END LOOP;
END $$;

-- Additional policies for user‑owned tables
-- org_members: users can see their own memberships
DROP POLICY IF EXISTS org_members_self_policy ON socialcandor_schema.org_members;
CREATE POLICY org_members_self_policy ON socialcandor_schema.org_members
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

-- csat_surveys: users can see surveys they submitted
DROP POLICY IF EXISTS csat_surveys_self_policy ON socialcandor_schema.csat_surveys;
CREATE POLICY csat_surveys_self_policy ON socialcandor_schema.csat_surveys
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

-- knowledge_base_feedback: users can see their own feedback
DROP POLICY IF EXISTS kb_feedback_self_policy ON socialcandor_schema.knowledge_base_feedback;
CREATE POLICY kb_feedback_self_policy ON socialcandor_schema.knowledge_base_feedback
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

-- document_collaborators: users can see documents they have access to
DROP POLICY IF EXISTS document_collaborators_self_policy ON socialcandor_schema.document_collaborators;
CREATE POLICY document_collaborators_self_policy ON socialcandor_schema.document_collaborators
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

