    FOR ALL USING (assigned_to = current_setting('app.current_user_id')::UUID);

-- =================================================================================================
-- TRIGGERS FOR UPDATED_AT
-- =================================================================================================

-- Apply updated_at triggers to all tables that have an updated_at column
DO $$
DECLARE
    tbl text;
    tables text[] := ARRAY[
        'org_hierarchy', 'org_members', 'org_settings', 'org_billing',
        'webhook_endpoints', 'integrations',
        'encryption_keys', 'key_rotation_jobs', 'data_encryption_config',
        'retention_enforcement_jobs', 'archived_data_catalog',
        'dataset_versions', 'model_training_runs',
        'policy_definitions',
        'csat_surveys', 'sla_violations', 'knowledge_base_feedback',
        'workspace_templates', 'document_collaborators', 'approval_workflow_templates',
        'data_rooms', 'shared_links', 'data_export_packages',
        'auto_remediation_actions', 'anomaly_alerts', 'runbooks',
        'model_bias_tests', 'explainability_records', 'regulatory_approvals',
        'wallet_addresses', 'nft_metadata'
    ];
BEGIN
    FOREACH tbl IN ARRAY tables LOOP
        EXECUTE format('
            DROP TRIGGER IF EXISTS trg_%I_updated_at ON socialcandor_schema.%I;
            CREATE TRIGGER trg_%I_updated_at
                BEFORE UPDATE ON socialcandor_schema.%I
                FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
        ', tbl, tbl, tbl, tbl);
    END LOOP;
END $$;


