-- =================================================================================================
-- 1. USER TERMS ACCEPTANCE (user_terms_acceptance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_terms_acceptance (
    acceptance_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    acceptance_number VARCHAR(50) GENERATED ALWAYS AS (
        'TA-' || TO_CHAR(accepted_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_terms_acceptance_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    terms_version VARCHAR(50) NOT NULL,
    privacy_version VARCHAR(50) NOT NULL,
    accepted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ip_address INET,
    user_agent TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_terms_acceptance_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_terms_acceptance_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_terms_acceptance_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_terms_acceptance_user_version UNIQUE (user_id, terms_version, privacy_version)
);
COMMENT ON TABLE socialcandor_schema.user_terms_acceptance IS 'Tracks which versions of Terms and Privacy Policy a user has accepted.';
CREATE INDEX idx_terms_acceptance_user ON socialcandor_schema.user_terms_acceptance(user_id, accepted_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.user_terms_acceptance ENABLE ROW LEVEL SECURITY;
CREATE POLICY terms_acceptance_self_policy ON socialcandor_schema.user_terms_acceptance
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY terms_acceptance_admin_policy ON socialcandor_schema.user_terms_acceptance
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- Trigger
CREATE TRIGGER trg_user_terms_acceptance_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_terms_acceptance
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 2. USER REFERRALS & INVITES
-- =================================================================================================

-- Table: user_referral_codes
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_referral_codes (
    code_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    code_number VARCHAR(50) GENERATED ALWAYS AS (
        'REF-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_referral_codes_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    code VARCHAR(50) UNIQUE NOT NULL,
    description TEXT,
    max_uses INTEGER CHECK (max_uses >= 0),  -- NULL = unlimited
    uses_count INTEGER DEFAULT 0 CHECK (uses_count >= 0),
    reward_amount NUMERIC(10,2),
    reward_currency CHAR(3) DEFAULT 'USD',
    is_active BOOLEAN DEFAULT TRUE,
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_user_referral_codes_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_referral_codes_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_referral_codes_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_referral_codes_expiry CHECK (expires_at IS NULL OR expires_at > created_at)
);
COMMENT ON TABLE socialcandor_schema.user_referral_codes IS 'Unique referral codes generated by users.';
CREATE INDEX idx_user_referral_codes_user ON socialcandor_schema.user_referral_codes(user_id);
CREATE INDEX idx_user_referral_codes_code ON socialcandor_schema.user_referral_codes(code);

-- Table: user_invites
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_invites (
    invite_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    invite_number VARCHAR(50) GENERATED ALWAYS AS (
        'INV-' || TO_CHAR(sent_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_invites_seq')::TEXT, 6, '0')
    ) STORED,
    inviter_user_id UUID NOT NULL,
    invitee_email VARCHAR(255),
    invitee_phone VARCHAR(50),
    code_id UUID,  -- optional link to referral code
    status socialcandor_schema.referral_invite_status NOT NULL DEFAULT 'SENT',
    sent_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    accepted_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_user_invites_inviter FOREIGN KEY (inviter_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_invites_code FOREIGN KEY (code_id)
        REFERENCES socialcandor_schema.user_referral_codes(code_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_invites_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_invites_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_invite_contact CHECK (invitee_email IS NOT NULL OR invitee_phone IS NOT NULL)
);
COMMENT ON TABLE socialcandor_schema.user_invites IS 'Invitations sent by users to join the platform.';
CREATE INDEX idx_user_invites_inviter ON socialcandor_schema.user_invites(inviter_user_id);
CREATE INDEX idx_user_invites_status ON socialcandor_schema.user_invites(status);

-- Table: user_referrals (links inviter and new user)
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_referrals (
    referral_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    referral_number VARCHAR(50) GENERATED ALWAYS AS (
        'RF-' || TO_CHAR(referred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_referrals_seq')::TEXT, 6, '0')
    ) STORED,
    inviter_user_id UUID NOT NULL,
    invited_user_id UUID NOT NULL,
    invite_id UUID,
    code_id UUID,
    referred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reward_earned NUMERIC(10,2),
    reward_paid BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_user_referrals_inviter FOREIGN KEY (inviter_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_referrals_invited FOREIGN KEY (invited_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_referrals_invite FOREIGN KEY (invite_id)
        REFERENCES socialcandor_schema.user_invites(invite_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_referrals_code FOREIGN KEY (code_id)
        REFERENCES socialcandor_schema.user_referral_codes(code_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_referrals_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_referrals_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_user_referrals_invited UNIQUE (invited_user_id)
);
COMMENT ON TABLE socialcandor_schema.user_referrals IS 'Links inviter and invited user after successful registration.';
CREATE INDEX idx_user_referrals_inviter ON socialcandor_schema.user_referrals(inviter_user_id);

-- RLS for referral tables
ALTER TABLE socialcandor_schema.user_referral_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.user_referrals ENABLE ROW LEVEL SECURITY;

CREATE POLICY referral_codes_self_policy ON socialcandor_schema.user_referral_codes
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY invites_self_policy ON socialcandor_schema.user_invites
    FOR ALL USING (inviter_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY referrals_inviter_policy ON socialcandor_schema.user_referrals
    FOR SELECT USING (inviter_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY referrals_invited_policy ON socialcandor_schema.user_referrals
    FOR SELECT USING (invited_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY referral_admin_policy ON socialcandor_schema.user_referral_codes FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY invites_admin_policy ON socialcandor_schema.user_invites FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY referrals_admin_policy ON socialcandor_schema.user_referrals FOR ALL USING (socialcandor_schema.is_admin());

-- Triggers
CREATE TRIGGER trg_user_referral_codes_updated_at BEFORE UPDATE ON socialcandor_schema.user_referral_codes
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
CREATE TRIGGER trg_user_invites_updated_at BEFORE UPDATE ON socialcandor_schema.user_invites
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
CREATE TRIGGER trg_user_referrals_updated_at BEFORE UPDATE ON socialcandor_schema.user_referrals
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 3. SHOPPING CART (user_cart, cart_items)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_cart (
    cart_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    cart_number VARCHAR(50) GENERATED ALWAYS AS (
        'CART-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_cart_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_user_cart_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_cart_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_cart_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_user_cart_user UNIQUE (user_id)  -- one active cart per user
);
COMMENT ON TABLE socialcandor_schema.user_cart IS 'Shopping cart for a user.';

CREATE TABLE IF NOT EXISTS socialcandor_schema.cart_items (
    cart_item_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    cart_item_number VARCHAR(50) GENERATED ALWAYS AS (
        'CITEM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.cart_items_seq')::TEXT, 6, '0')
    ) STORED,
    cart_id UUID NOT NULL,
    listing_id UUID NOT NULL,  -- from marketplace_listings
    variant_id UUID,           -- optional link to product_variants
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_cart_items_cart FOREIGN KEY (cart_id)
        REFERENCES socialcandor_schema.user_cart(cart_id) ON DELETE CASCADE,
    CONSTRAINT fk_cart_items_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
    CONSTRAINT fk_cart_items_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_cart_items_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_cart_items_listing UNIQUE (cart_id, listing_id, variant_id)
);
COMMENT ON TABLE socialcandor_schema.cart_items IS 'Items in a shopping cart.';
CREATE INDEX idx_cart_items_cart ON socialcandor_schema.cart_items(cart_id);
CREATE INDEX idx_cart_items_listing ON socialcandor_schema.cart_items(listing_id);

-- RLS
ALTER TABLE socialcandor_schema.user_cart ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.cart_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY cart_self_policy ON socialcandor_schema.user_cart
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY cart_items_self_policy ON socialcandor_schema.cart_items
    FOR ALL USING (cart_id IN (SELECT cart_id FROM socialcandor_schema.user_cart WHERE user_id = current_setting('app.current_user_id')::UUID));
CREATE POLICY cart_admin_policy ON socialcandor_schema.user_cart FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY cart_items_admin_policy ON socialcandor_schema.cart_items FOR ALL USING (socialcandor_schema.is_admin());

-- Triggers
CREATE TRIGGER trg_user_cart_updated_at BEFORE UPDATE ON socialcandor_schema.user_cart
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
CREATE TRIGGER trg_cart_items_updated_at BEFORE UPDATE ON socialcandor_schema.cart_items
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 4. ORDER ITEMS (order_items)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.order_items (
    order_item_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    order_item_number VARCHAR(50) GENERATED ALWAYS AS (
        'OITEM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.order_items_seq')::TEXT, 6, '0')
    ) STORED,
    order_id UUID NOT NULL,  -- references marketplace_orders
    listing_id UUID NOT NULL,
    variant_id UUID,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price NUMERIC(15,2) NOT NULL CHECK (unit_price >= 0),
    total_price NUMERIC(15,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
    shipping_status VARCHAR(20) CHECK (shipping_status IN ('PENDING', 'SHIPPED', 'DELIVERED', 'RETURNED')),
    tracking_number VARCHAR(100),
    carrier VARCHAR(50),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE CASCADE,
    CONSTRAINT fk_order_items_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_items_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_order_items_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.order_items IS 'Line items within a marketplace order.';
CREATE INDEX idx_order_items_order ON socialcandor_schema.order_items(order_id);
CREATE INDEX idx_order_items_listing ON socialcandor_schema.order_items(listing_id);

-- RLS
ALTER TABLE socialcandor_schema.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_self_policy ON socialcandor_schema.order_items
    FOR SELECT USING (order_id IN (SELECT order_id FROM socialcandor_schema.marketplace_orders WHERE buyer_user_id = current_setting('app.current_user_id')::UUID));
CREATE POLICY order_items_seller_policy ON socialcandor_schema.order_items
    FOR SELECT USING (order_id IN (SELECT order_id FROM socialcandor_schema.marketplace_orders WHERE seller_profile_id IN (
        SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
    )));
CREATE POLICY order_items_admin_policy ON socialcandor_schema.order_items
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger
CREATE TRIGGER trg_order_items_updated_at BEFORE UPDATE ON socialcandor_schema.order_items
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 5. PRODUCT INVENTORY (product_inventory)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.product_inventory (
    inventory_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    inventory_number VARCHAR(50) GENERATED ALWAYS AS (
        'INV-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.product_inventory_seq')::TEXT, 6, '0')
    ) STORED,
    listing_id UUID NOT NULL,
    variant_id UUID,  -- if inventory is per variant
    quantity_available INTEGER NOT NULL DEFAULT 0 CHECK (quantity_available >= 0),
    reserved_quantity INTEGER NOT NULL DEFAULT 0 CHECK (reserved_quantity >= 0),
    reorder_threshold INTEGER CHECK (reorder_threshold >= 0),
    last_restocked_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_product_inventory_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
    CONSTRAINT fk_product_inventory_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_product_inventory_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_product_inventory UNIQUE (listing_id, variant_id)
);
COMMENT ON TABLE socialcandor_schema.product_inventory IS 'Stock levels for marketplace listings.';
CREATE INDEX idx_product_inventory_listing ON socialcandor_schema.product_inventory(listing_id);

-- RLS
ALTER TABLE socialcandor_schema.product_inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY inventory_seller_policy ON socialcandor_schema.product_inventory
    FOR ALL USING (listing_id IN (SELECT listing_id FROM socialcandor_schema.marketplace_listings WHERE seller_profile_id IN (
        SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
    )));
CREATE POLICY inventory_admin_policy ON socialcandor_schema.product_inventory
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger
CREATE TRIGGER trg_product_inventory_updated_at BEFORE UPDATE ON socialcandor_schema.product_inventory
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 6. PRODUCT VARIANTS (product_variants)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.product_variants (
    variant_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    variant_number VARCHAR(50) GENERATED ALWAYS AS (
        'VAR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.product_variants_seq')::TEXT, 6, '0')
    ) STORED,
    listing_id UUID NOT NULL,
    sku VARCHAR(100) UNIQUE,
    attributes JSONB NOT NULL,  -- e.g., {"size": "M", "color": "red"}
    price_adjustment NUMERIC(15,2) DEFAULT 0 CHECK (price_adjustment >= 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_product_variants_listing FOREIGN KEY (listing_id)
        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
    CONSTRAINT fk_product_variants_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_product_variants_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.product_variants IS 'Variants of a product (size, color, etc.).';
CREATE INDEX idx_product_variants_listing ON socialcandor_schema.product_variants(listing_id);

-- RLS
ALTER TABLE socialcandor_schema.product_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY variants_seller_policy ON socialcandor_schema.product_variants
    FOR ALL USING (listing_id IN (SELECT listing_id FROM socialcandor_schema.marketplace_listings WHERE seller_profile_id IN (
        SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
    )));
