-- 17. USER GIFT CARD BALANCE (user_gift_cards, gift_card_transactions)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_gift_cards (
    gift_card_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    gift_card_number VARCHAR(50) GENERATED ALWAYS AS (
        'GC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_gift_cards_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    code VARCHAR(100) UNIQUE NOT NULL,
    initial_balance NUMERIC(15,2) NOT NULL CHECK (initial_balance >= 0),
    current_balance NUMERIC(15,2) NOT NULL CHECK (current_balance >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    expires_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_user_gift_cards_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_gift_cards_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_gift_cards_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_gift_card_balance CHECK (current_balance <= initial_balance)
);
COMMENT ON TABLE socialcandor_schema.user_gift_cards IS 'Gift cards owned by users.';

CREATE TABLE IF NOT EXISTS socialcandor_schema.gift_card_transactions (
    transaction_id BIGSERIAL PRIMARY KEY,
    transaction_number VARCHAR(50) GENERATED ALWAYS AS (
        'GCT-' || TO_CHAR(transaction_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.gift_card_transactions_seq')::TEXT, 6, '0')
    ) STORED,
    gift_card_id UUID NOT NULL,
    amount NUMERIC(15,2) NOT NULL CHECK (amount > 0),  -- positive for addition, negative for deduction
    balance_after NUMERIC(15,2) NOT NULL,
    transaction_type VARCHAR(20) CHECK (transaction_type IN ('PURCHASE', 'REFUND', 'ADJUSTMENT', 'EXPIRY')),
    reference_id UUID,  -- e.g., order_id
    transaction_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_gift_card_transactions_gift_card FOREIGN KEY (gift_card_id)
        REFERENCES socialcandor_schema.user_gift_cards(gift_card_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.gift_card_transactions IS 'Transaction log for gift card balance changes.';
CREATE INDEX idx_gift_card_transactions_card ON socialcandor_schema.gift_card_transactions(gift_card_id);

-- RLS
ALTER TABLE socialcandor_schema.user_gift_cards ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.gift_card_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY gift_cards_self_policy ON socialcandor_schema.user_gift_cards
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY gift_cards_admin_policy ON socialcandor_schema.user_gift_cards
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY gift_card_transactions_self_policy ON socialcandor_schema.gift_card_transactions
    FOR SELECT USING (gift_card_id IN (SELECT gift_card_id FROM socialcandor_schema.user_gift_cards WHERE user_id = current_setting('app.current_user_id')::UUID));
CREATE POLICY gift_card_transactions_admin_policy ON socialcandor_schema.gift_card_transactions
    FOR ALL USING (socialcandor_schema.is_admin());

-- Triggers
CREATE TRIGGER trg_user_gift_cards_updated_at BEFORE UPDATE ON socialcandor_schema.user_gift_cards
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 18. USER CRYPTO TRANSACTIONS (crypto_transactions)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.crypto_transactions (
    tx_id BIGSERIAL PRIMARY KEY,
    tx_number VARCHAR(50) GENERATED ALWAYS AS (
        'CRYPTO-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.crypto_transactions_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    wallet_id UUID,  -- reference to wallet_addresses
    tx_hash VARCHAR(255) UNIQUE,
    from_address VARCHAR(255) NOT NULL,
    to_address VARCHAR(255) NOT NULL,
    amount NUMERIC(30,18) NOT NULL CHECK (amount > 0),
    blockchain VARCHAR(50) NOT NULL,
    status socialcandor_schema.crypto_transaction_status NOT NULL DEFAULT 'PENDING',
    confirmation_count INTEGER DEFAULT 0,
    block_number BIGINT,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_crypto_transactions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_crypto_transactions_wallet FOREIGN KEY (wallet_id)
        REFERENCES socialcandor_schema.wallet_addresses(wallet_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.crypto_transactions IS 'Cryptocurrency send/receive transactions.';
CREATE INDEX idx_crypto_transactions_user ON socialcandor_schema.crypto_transactions(user_id, timestamp DESC);
CREATE INDEX idx_crypto_transactions_hash ON socialcandor_schema.crypto_transactions(tx_hash);

-- RLS
ALTER TABLE socialcandor_schema.crypto_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY crypto_transactions_self_policy ON socialcandor_schema.crypto_transactions
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY crypto_transactions_admin_policy ON socialcandor_schema.crypto_transactions
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger
CREATE TRIGGER trg_crypto_transactions_updated_at BEFORE UPDATE ON socialcandor_schema.crypto_transactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- 19. USER NFT TRANSFERS (nft_transfers)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.nft_transfers (
    transfer_id BIGSERIAL PRIMARY KEY,
    transfer_number VARCHAR(50) GENERATED ALWAYS AS (
        'NFTT-' || TO_CHAR(transferred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.nft_transfers_seq')::TEXT, 6, '0')
    ) STORED,
    nft_id UUID NOT NULL,  -- references nft_metadata
    from_user_id UUID,
    to_user_id UUID NOT NULL,
    tx_hash VARCHAR(255),
    transferred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_nft_transfers_nft FOREIGN KEY (nft_id)
        REFERENCES socialcandor_schema.nft_metadata(nft_id) ON DELETE CASCADE,
    CONSTRAINT fk_nft_transfers_from_user FOREIGN KEY (from_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_nft_transfers_to_user FOREIGN KEY (to_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE
);
COMMENT ON TABLE socialcandor_schema.nft_transfers IS 'History of NFT ownership transfers.';
CREATE INDEX idx_nft_transfers_nft ON socialcandor_schema.nft_transfers(nft_id, transferred_at DESC);
CREATE INDEX idx_nft_transfers_to_user ON socialcandor_schema.nft_transfers(to_user_id);

-- RLS
ALTER TABLE socialcandor_schema.nft_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY nft_transfers_self_policy ON socialcandor_schema.nft_transfers
    FOR SELECT USING (from_user_id = current_setting('app.current_user_id')::UUID OR to_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY nft_transfers_admin_policy ON socialcandor_schema.nft_transfers
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- 20. USER DAO GOVERNANCE (dao_proposals, dao_votes, dao_delegations)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_proposals (
    proposal_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    proposal_number VARCHAR(50) GENERATED ALWAYS AS (
        'PROP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_proposals_seq')::TEXT, 6, '0')
    ) STORED,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    proposer_user_id UUID NOT NULL,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE NOT NULL,
    status socialcandor_schema.dao_proposal_status NOT NULL DEFAULT 'PENDING',
    voting_power_required BIGINT,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_dao_proposals_proposer FOREIGN KEY (proposer_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_dao_proposals_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dao_proposals_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_dao_proposal_dates CHECK (end_time > start_time)
);
COMMENT ON TABLE socialcandor_schema.dao_proposals IS 'Governance proposals in a DAO.';

CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_votes (
    vote_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    vote_number VARCHAR(50) GENERATED ALWAYS AS (
        'VOTE-' || TO_CHAR(voted_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_votes_seq')::TEXT, 6, '0')
    ) STORED,
    proposal_id UUID NOT NULL,
    voter_user_id UUID NOT NULL,
    vote_choice socialcandor_schema.dao_vote_choice NOT NULL,
    voting_power NUMERIC(20,8) NOT NULL,
    voted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Constraints
    CONSTRAINT fk_dao_votes_proposal FOREIGN KEY (proposal_id)
        REFERENCES socialcandor_schema.dao_proposals(proposal_id) ON DELETE CASCADE,
    CONSTRAINT fk_dao_votes_voter FOREIGN KEY (voter_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT uk_dao_votes UNIQUE (proposal_id, voter_user_id)
);
COMMENT ON TABLE socialcandor_schema.dao_votes IS 'Votes cast on DAO proposals.';
CREATE INDEX idx_dao_votes_proposal ON socialcandor_schema.dao_votes(proposal_id);

CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_delegations (
    delegation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    delegation_number VARCHAR(50) GENERATED ALWAYS AS (
        'DELEG-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_delegations_seq')::TEXT, 6, '0')
    ) STORED,
    delegator_user_id UUID NOT NULL,
    delegate_user_id UUID NOT NULL,
    from_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    to_date TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (to_date IS NULL OR to_date > CURRENT_TIMESTAMP) STORED,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_dao_delegations_delegator FOREIGN KEY (delegator_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_dao_delegations_delegate FOREIGN KEY (delegate_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_dao_delegations_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dao_delegations_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_dao_delegation_self CHECK (delegator_user_id != delegate_user_id),
    CONSTRAINT uk_dao_delegations_active UNIQUE (delegator_user_id) WHERE is_active = TRUE
);
COMMENT ON TABLE socialcandor_schema.dao_delegations IS 'Vote delegations in DAO governance.';
CREATE INDEX idx_dao_delegations_delegator ON socialcandor_schema.dao_delegations(delegator_user_id) WHERE is_active = TRUE;
CREATE INDEX idx_dao_delegations_delegate ON socialcandor_schema.dao_delegations(delegate_user_id) WHERE is_active = TRUE;

-- RLS
ALTER TABLE socialcandor_schema.dao_proposals ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.dao_votes ENABLE ROW LEVEL SECURITY;
ALTER TABLE socialcandor_schema.dao_delegations ENABLE ROW LEVEL SECURITY;

CREATE POLICY dao_proposals_self_policy ON socialcandor_schema.dao_proposals
    FOR SELECT USING (TRUE);  -- proposals are public
CREATE POLICY dao_proposals_admin_policy ON socialcandor_schema.dao_proposals
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE POLICY dao_votes_self_policy ON socialcandor_schema.dao_votes
    FOR SELECT USING (voter_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY dao_votes_admin_policy ON socialcandor_schema.dao_votes
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE POLICY dao_delegations_self_policy ON socialcandor_schema.dao_delegations
    FOR ALL USING (delegator_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY dao_delegations_admin_policy ON socialcandor_schema.dao_delegations
    FOR ALL USING (socialcandor_schema.is_admin());

-- Triggers
CREATE TRIGGER trg_dao_proposals_updated_at BEFORE UPDATE ON socialcandor_schema.dao_proposals
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
CREATE TRIGGER trg_dao_delegations_updated_at BEFORE UPDATE ON socialcandor_schema.dao_delegations
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- Critical Performance Indexes
CREATE INDEX CONCURRENTLY idx_users_active_status ON socialcandor_schema.users(user_id)
    WHERE status = 'ACTIVE';

CREATE INDEX CONCURRENTLY idx_users_last_login ON socialcandor_schema.users(last_login_at DESC)
    WHERE status = 'ACTIVE';

-- Feed Optimization (Covering Index)
CREATE INDEX CONCURRENTLY idx_posts_feed ON socialcandor_schema.posts(user_id, created_at DESC)
    INCLUDE (post_id, content_text, like_count, comment_count)
    WHERE visibility = 'PUBLIC';

-- Message Search Optimization
CREATE INDEX CONCURRENTLY idx_messages_conversation_time ON socialcandor_schema.conversations_messages
    (conversation_id, created_at DESC)
    INCLUDE (message_id, sender_user_id, content_text);

-- Notification Performance
CREATE INDEX CONCURRENTLY idx_notifications_unread ON socialcandor_schema.notifications
    (user_id, created_at DESC)
    WHERE read_at IS NULL;

-- Audit Log Partitioning Strategy
-- Create monthly partitions for audit_logs
CREATE TABLE socialcandor_schema.audit_logs_2025_04 PARTITION OF socialcandor_schema.audit_logs
    FOR VALUES FROM ('2025-04-01') TO ('2025-05-01');

    --================================================================================================
    -- ENUMS - Multi-Tenancy & Organization Management
    --================================================================================================

    -- Enum: MT01 - org_member_role
    -- Description: Defines the possible roles a user can hold within an organization
    -- Business Case: Enables granular permission control at the organization level, supporting
    --                hierarchical access patterns and delegation of authority
    -- Feature Reference: ORG03 (Organization Roles)
    --================================================================================================
    CREATE TYPE socialcandor_schema.org_member_role AS ENUM (
        'OWNER',              -- Full control, can delete org
        'ADMIN',              -- Manage members, settings, billing
        'MEMBER',             -- Standard member with access to org resources
        'BILLING_MANAGER',    -- Manage payment methods, view invoices
        'GUEST',              -- Limited access, usually external
        'AUDITOR',            -- Read-only access for compliance
        'DEVELOPER',          -- Access to API keys and integrations
        'SUPPORT'             -- Access to support tickets for org users
    );
    COMMENT ON TYPE socialcandor_schema.org_member_role IS 'Defines roles a user can hold within an organization, enabling granular permission control';

    -- Enum: MT02 - org_domain_verification_status
    -- Description: Status of domain ownership verification for SSO and email validation
    -- Business Case: Tracks the verification process of company domains for security
    -- Feature Reference: ORG05 (Domain Verification)
    --================================================================================================
    CREATE TYPE socialcandor_schema.org_domain_verification_status AS ENUM (
        'PENDING',            -- Verification initiated
        'VERIFIED',           -- Domain ownership confirmed
        'FAILED',             -- Verification failed
        'EXPIRED',            -- Verification token expired
        'REVOKED'             -- Domain removed/untrusted
    );
    COMMENT ON TYPE socialcandor_schema.org_domain_verification_status IS 'Status of domain ownership verification for SSO and email validation';

    -- Enum: MT03 - quota_resource_type
    -- Description: Types of resources that can be quota-limited per organization
    -- Business Case: Enables usage-based billing and resource governance
    -- Feature Reference: ORG07 (Resource Quotas)
    --================================================================================================
    CREATE TYPE socialcandor_schema.quota_resource_type AS ENUM (
        'SEATS',              -- Number of users
        'STORAGE',            -- Total storage in GB
        'API_CALLS',          -- Monthly API calls
        'POSTS_PER_MONTH',    -- Content creation limit
        'INTEGRATIONS',       -- Number of connected apps
        'CUSTOM_DOMAINS',     -- Custom domain count
        'SSO_SEATS',          -- SSO-enabled users
        'DATA_EXPORTS'        -- Monthly export allowance
    );
    COMMENT ON TYPE socialcandor_schema.quota_resource_type IS 'Types of resources that can be quota-limited per organization';

    --================================================================================================
    -- ENUMS - Security & Compliance
    --================================================================================================

    -- Enum: SC01 - encryption_key_purpose
    -- Description: Purpose of encryption keys in the system
    -- Business Case: Categorizes keys by their use case for proper lifecycle management
    -- Feature Reference: SEC21 (Key Management)
    --================================================================================================
    CREATE TYPE socialcandor_schema.encryption_key_purpose AS ENUM (
        'DATA_AT_REST',       -- Database/file encryption
        'DATA_IN_TRANSIT',    -- TLS/SSL
        'TOKEN_SIGNING',      -- JWT/API tokens
        'PAYMENT_DATA',       -- PCI-DSS compliant encryption
        'PII_DATA',           -- Personal information encryption
        'BACKUP_ENCRYPTION',  -- Backup encryption
        'HSM_ROOT'            -- Hardware Security Module root key
    );
    COMMENT ON TYPE socialcandor_schema.encryption_key_purpose IS 'Purpose of encryption keys in the system for lifecycle management';

    -- Enum: SC02 - key_rotation_reason
    -- Description: Reasons for initiating key rotation
    -- Business Case: Audit trail for key lifecycle changes
    -- Feature Reference: SEC22 (Key Rotation)
    --================================================================================================
    CREATE TYPE socialcandor_schema.key_rotation_reason AS ENUM (
        'SCHEDULED',          -- Regular rotation schedule
        'COMPROMISE',         -- Key potentially compromised
        'EMPLOYEE_DEPARTURE', -- Key owner left
        'REGULATORY',         -- Compliance requirement
        'VERSION_UPGRADE',    -- Algorithm upgrade
        'MANUAL'              -- Manual override
    );
    COMMENT ON TYPE socialcandor_schema.key_rotation_reason IS 'Reasons for initiating key rotation for audit purposes';

    -- Enum: SC03 - vulnerability_severity
    -- Description: Severity levels for security vulnerabilities
    -- Business Case: Prioritizes remediation efforts based on risk
    -- Feature Reference: SEC23 (Vulnerability Management)
    --================================================================================================
    CREATE TYPE socialcandor_schema.vulnerability_severity AS ENUM (
        'CRITICAL',           -- Immediate action required
        'HIGH',               -- Fix within 7 days
        'MEDIUM',             -- Fix within 30 days
        'LOW',                -- Fix within 90 days
        'INFO'                -- Informational only
    );
    COMMENT ON TYPE socialcandor_schema.vulnerability_severity IS 'Severity levels for security vulnerabilities to prioritize remediation';

    -- Enum: SC04 - training_completion_status
    -- Description: Status of security training completion
    -- Business Case: Tracks employee compliance with mandatory training
    -- Feature Reference: SEC24 (Security Training)
    --================================================================================================
    CREATE TYPE socialcandor_schema.training_completion_status AS ENUM (
        'NOT_STARTED',
        'IN_PROGRESS',
        'COMPLETED',
        'EXPIRED',
        'FAILED',
        'EXEMPT'
    );
    COMMENT ON TYPE socialcandor_schema.training_completion_status IS 'Status of security training completion for compliance tracking';

    --================================================================================================
    -- ENUMS - External Integrations
    --================================================================================================

    -- Enum: EI01 - integration_auth_type
    -- Description: Authentication methods for external integrations
    -- Business Case: Supports various OAuth flows and API key management
    -- Feature Reference: INT05 (Integration Authentication)
    --================================================================================================
    CREATE TYPE socialcandor_schema.integration_auth_type AS ENUM (
        'OAUTH2_CLIENT_CREDENTIALS',
        'OAUTH2_AUTHORIZATION_CODE',
        'API_KEY',
        'BASIC_AUTH',
        'JWT',
        'CUSTOM'
    );
    COMMENT ON TYPE socialcandor_schema.integration_auth_type IS 'Authentication methods for external integrations';

    -- Enum: EI02 - webhook_event_type
    -- Description: Platform events that can trigger webhooks
    -- Business Case: Enables event-driven architecture with granular subscriptions
    -- Feature Reference: INT06 (Webhook Events)
    --================================================================================================
    CREATE TYPE socialcandor_schema.webhook_event_type AS ENUM (
        'USER_CREATED',
        'USER_UPDATED',
        'USER_DELETED',
        'POST_CREATED',
        'POST_UPDATED',
        'POST_DELETED',
        'COMMENT_CREATED',
        'LIKE_CREATED',
        'SHARE_CREATED',
        'MESSAGE_SENT',
        'INVOICE_CREATED',
        'INVOICE_PAID',
        'ORDER_CREATED',
        'ORDER_SHIPPED',
        'ORDER_DELIVERED'
    );
    COMMENT ON TYPE socialcandor_schema.webhook_event_type IS 'Platform events that can trigger webhooks for external systems';

    --================================================================================================
    -- ENUMS - E-Commerce & Marketplace
    --================================================================================================

    -- Enum: EC01 - inventory_alert_type
    -- Description: Types of inventory alerts for stock management
    -- Business Case: Proactive inventory monitoring and replenishment
    -- Feature Reference: MKT03 (Inventory Management)
    --================================================================================================
    CREATE TYPE socialcandor_schema.inventory_alert_type AS ENUM (
        'LOW_STOCK',
        'OUT_OF_STOCK',
        'OVERSTOCK',
        'EXPIRY_WARNING',
        'REORDER_SUGGESTED',
        'DISCONTINUED'
    );
    COMMENT ON TYPE socialcandor_schema.inventory_alert_type IS 'Types of inventory alerts for proactive stock management';

    -- Enum: EC02 - gift_card_status
    -- Description: Status of gift cards in the system
    -- Business Case: Manages gift card lifecycle from activation to expiry
    -- Feature Reference: PAY06 (Gift Cards)
    --================================================================================================
    CREATE TYPE socialcandor_schema.gift_card_status AS ENUM (
        'ACTIVE',
        'PARTIALLY_USED',
        'EXPIRED',
        'DEPLETED',
        'CANCELLED',
        'PENDING_ACTIVATION'
    );
    COMMENT ON TYPE socialcandor_schema.gift_card_status IS 'Status of gift cards in the system for lifecycle management';

    --================================================================================================
    -- ENUMS - Gamification
    --================================================================================================

    -- Enum: GM01 - achievement_rarity
    -- Description: Rarity levels for user achievements
    -- Business Case: Creates engagement through rare/legendary achievements
    -- Feature Reference: GAM04 (Achievement System)
    --================================================================================================
    CREATE TYPE socialcandor_schema.achievement_rarity AS ENUM (
        'COMMON',             -- >50% of users
        'UNCOMMON',           -- 25-50% of users
        'RARE',               -- 10-25% of users
        'EPIC',               -- 1-10% of users
        'LEGENDARY',          -- <1% of users
        'SECRET'              -- Hidden achievement
    );
    COMMENT ON TYPE socialcandor_schema.achievement_rarity IS 'Rarity levels for user achievements to drive engagement';

    -- Enum: GM02 - challenge_difficulty
    -- Description: Difficulty levels for time-limited challenges
    -- Business Case: Allows progressive difficulty and targeted user segments
