    --================================================================================================
    -- Table: MT01 - org_hierarchy
    -- Description: Defines parent-child relationships between organizations, enabling hierarchical
    --              organization structures with depth tracking for efficient querying.
    -- Business Case: Enterprise organizations often have complex structures with subsidiaries,
    --                divisions, and departments. This table enables consolidated billing, unified
    --                reporting, and hierarchical access control across the organization tree.
    --                The depth column allows for efficient recursive queries without CTEs,
    --                while the materialized path enables fast ancestry/descendant lookups.
    --                This design supports unlimited nesting levels while maintaining query
    --                performance through strategic indexing.
    --
    -- Key Performance Indicators (KPIs):
    --   1. Hierarchy depth distribution - Average and maximum nesting levels across orgs
    --   2. Child org growth rate - Month-over-month increase in sub-organizations
    --   3. Hierarchy change frequency - Number of restructuring events per quarter
    --   4. Orphan detection rate - Percentage of orgs with invalid parent references
    --   5. Consolidation accuracy - Percentage of child org data correctly rolled up
    --
    -- Feature References:
    --   - ORG04 (Organizational Hierarchy)
    --   - ORG05 (Consolidated Billing)
    --   - ORG06 (Hierarchical Access Control)
    --   - ACC03 (Multi-tenant Accounting)
    --================================================================================================
    CREATE TABLE IF NOT EXISTS socialcandor_schema.org_hierarchy (
        -- Primary key
        hierarchy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

        -- Human-readable identifier
        hierarchy_number VARCHAR(50) GENERATED ALWAYS AS (
            'HIER-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_hierarchy_seq')::TEXT, 6, '0')
        ) STORED,

        -- References
        parent_org_id UUID NOT NULL,
        child_org_id UUID NOT NULL,

        -- Hierarchy attributes
        depth INTEGER NOT NULL CHECK (depth >= 1),           -- Distance from root (1 = direct child)
        path LTREE,                 -- Materialized path for ancestry queries
        is_direct BOOLEAN GENERATED ALWAYS AS (depth = 1) STORED,

        -- Relationship attributes
        relationship_type VARCHAR(50) CHECK (relationship_type IN (
            'SUBSIDIARY', 'DIVISION', 'DEPARTMENT', 'TEAM', 'PROJECT', 'PARTNER'
        )),
        ownership_percentage NUMERIC(5,2) CHECK (ownership_percentage >= 0 AND ownership_percentage <= 100),
        consolidation_method VARCHAR(20) CHECK (consolidation_method IN ('FULL', 'PROPORTIONAL', 'EQUITY', 'NONE')),

        -- Effective dating (for historical tracking)
        effective_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
        effective_to TIMESTAMP WITH TIME ZONE,
        is_active BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

        -- Audit columns
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID DEFAULT uuid_nil(),

        -- Constraints
        CONSTRAINT fk_org_hierarchy_parent FOREIGN KEY (parent_org_id)
            REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
        CONSTRAINT fk_org_hierarchy_child FOREIGN KEY (child_org_id)
            REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
        CONSTRAINT fk_org_hierarchy_created_by FOREIGN KEY (created_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
        CONSTRAINT fk_org_hierarchy_updated_by FOREIGN KEY (updated_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

        CONSTRAINT uk_org_hierarchy_active UNIQUE (parent_org_id, child_org_id, effective_from),
        CONSTRAINT chk_org_hierarchy_no_self CHECK (parent_org_id != child_org_id),
        CONSTRAINT chk_org_hierarchy_dates CHECK (effective_to IS NULL OR effective_to > effective_from)
    );

    -- Comments
    COMMENT ON TABLE socialcandor_schema.org_hierarchy IS 'Defines parent-child relationships between organizations with depth tracking for efficient hierarchical queries';
    COMMENT ON COLUMN socialcandor_schema.org_hierarchy.depth IS 'Distance from root organization (1 = direct child)';
    COMMENT ON COLUMN socialcandor_schema.org_hierarchy.path IS 'Materialized path using LTREE for fast ancestry/descendant queries';
    COMMENT ON COLUMN socialcandor_schema.org_hierarchy.ownership_percentage IS 'Ownership percentage for consolidation calculations';

    -- Indexes for performance
    CREATE INDEX idx_org_hierarchy_parent ON socialcandor_schema.org_hierarchy(parent_org_id, is_active) WHERE is_active = TRUE;
    CREATE INDEX idx_org_hierarchy_child ON socialcandor_schema.org_hierarchy(child_org_id, is_active) WHERE is_active = TRUE;
    CREATE INDEX idx_org_hierarchy_depth ON socialcandor_schema.org_hierarchy(depth);
    CREATE INDEX idx_org_hierarchy_path ON socialcandor_schema.org_hierarchy USING GIST(path);
    CREATE INDEX idx_org_hierarchy_effective ON socialcandor_schema.org_hierarchy(effective_from, effective_to) WHERE is_active = TRUE;

    -- Trigger for updated_at
    CREATE TRIGGER trg_org_hierarchy_updated_at
        BEFORE UPDATE ON socialcandor_schema.org_hierarchy
        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

        --================================================================================================
        -- Table: MT02 - org_members
        -- Description: Associates users with organizations and defines their role, department,
        --              and membership lifecycle. Supports complex organizational structures with
        --              users belonging to multiple organizations and departments.
        -- Business Case: Enterprise multi-tenancy requires fine-grained user-organization relationships
        --                with role-based access control. This table enables users to be members of
        --                multiple organizations (e.g., consultant working for multiple clients) while
        --                maintaining separate permissions and audit trails. The department field allows
        --                for organizational unit-based grouping, and the cost center mapping enables
        --                chargeback and showback for internal billing. Historical tracking of membership
        --                changes is critical for compliance audits and access reviews.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Member growth rate - New members added per organization per month
        --   2. Role distribution - Percentage of members in each role category
        --   3. Membership churn rate - Users leaving organizations per quarter
        --   4. Cross-org membership percentage - Users belonging to multiple organizations
        --   5. Department utilization - Distribution of members across departments
        --
        -- Feature References:
        --   - ORG07 (Organization Members)
        --   - ORG08 (Role-Based Access Control)
        --   - ORG09 (Department Management)
        --   - ACC04 (Cost Center Allocation)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.org_members (
            -- Primary key
            membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

            -- Human-readable identifier
            membership_number VARCHAR(50) GENERATED ALWAYS AS (
                'MEM-' || TO_CHAR(joined_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_members_seq')::TEXT, 6, '0')
            ) STORED,

            -- References
            organization_id UUID NOT NULL,
            user_id UUID NOT NULL,

            -- Role and permissions
            role socialcandor_schema.org_member_role NOT NULL DEFAULT 'MEMBER',
            custom_role_id UUID,       -- Reference to custom org-specific roles
            permissions JSONB DEFAULT '{}',                      -- Granular permission overrides

            -- Organizational structure
            department VARCHAR(100),
            job_title VARCHAR(200),
            manager_user_id UUID,      -- Reporting manager
            cost_center_id UUID,       -- For chargeback/showback

            -- Membership lifecycle
            joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
            left_at TIMESTAMP WITH TIME ZONE,
            is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,

            -- Invitation and approval workflow
            invited_by UUID,
            invited_at TIMESTAMP WITH TIME ZONE,
            approved_by UUID,
            approved_at TIMESTAMP WITH TIME ZONE,
            invitation_token VARCHAR(255),
            invitation_expires_at TIMESTAMP WITH TIME ZONE,

            -- Access and security
            mfa_required BOOLEAN DEFAULT FALSE,
            access_level VARCHAR(20) CHECK (access_level IN ('FULL', 'RESTRICTED', 'READ_ONLY', 'NO_ACCESS')),
            last_activity_at TIMESTAMP WITH TIME ZONE,

            -- Preferences
            notification_preferences JSONB DEFAULT '{}',
            display_settings JSONB DEFAULT '{}',

            -- Audit columns
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            created_by UUID NOT NULL,
            updated_by UUID DEFAULT uuid_nil(),

            -- Constraints
            CONSTRAINT fk_org_members_org FOREIGN KEY (organization_id)
                REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
            CONSTRAINT fk_org_members_user FOREIGN KEY (user_id)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
            CONSTRAINT fk_org_members_manager FOREIGN KEY (manager_user_id)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_org_members_invited_by FOREIGN KEY (invited_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_org_members_approved_by FOREIGN KEY (approved_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_org_members_created_by FOREIGN KEY (created_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
            CONSTRAINT fk_org_members_updated_by FOREIGN KEY (updated_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

            CONSTRAINT uk_org_members_active UNIQUE (organization_id, user_id) WHERE is_active = TRUE,
            CONSTRAINT chk_org_members_dates CHECK (left_at IS NULL OR left_at > joined_at),
            CONSTRAINT chk_org_members_invitation CHECK (
                (invited_by IS NOT NULL AND invited_at IS NOT NULL) OR
                (invited_by IS NULL AND invited_at IS NULL)
            )
        );

        -- Comments
        COMMENT ON TABLE socialcandor_schema.org_members IS 'Associates users with organizations, defining roles, departments, and membership lifecycle';
        COMMENT ON COLUMN socialcandor_schema.org_members.permissions IS 'Granular permission overrides beyond the assigned role';
        COMMENT ON COLUMN socialcandor_schema.org_members.cost_center_id IS 'Cost center for chargeback/showback of resource usage';

        -- Indexes for performance
        CREATE INDEX idx_org_members_org ON socialcandor_schema.org_members(organization_id, is_active) WHERE is_active = TRUE;
        CREATE INDEX idx_org_members_user ON socialcandor_schema.org_members(user_id, is_active) WHERE is_active = TRUE;
        CREATE INDEX idx_org_members_role ON socialcandor_schema.org_members(role) WHERE is_active = TRUE;
        CREATE INDEX idx_org_members_department ON socialcandor_schema.org_members(department) WHERE department IS NOT NULL;
        CREATE INDEX idx_org_members_manager ON socialcandor_schema.org_members(manager_user_id) WHERE manager_user_id IS NOT NULL;
        CREATE INDEX idx_org_members_joined ON socialcandor_schema.org_members(joined_at DESC);

        -- Trigger for updated_at
        CREATE TRIGGER trg_org_members_updated_at
            BEFORE UPDATE ON socialcandor_schema.org_members
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

            --================================================================================================
            -- Table: MT03 - org_settings
            -- Description: Stores per-organization configuration settings including branding, security
            --              policies, feature flags, and integration preferences. Supports multi-tenant
            --              customization without code changes.
            -- Business Case: Enterprise customers require tenant-specific configurations for branding
            --                (logos, colors, domain), security policies (password complexity, MFA requirements),
            --                feature availability (beta features, add-ons), and integration settings.
            --                Centralizing these in a JSONB field allows flexible schema evolution while
            --                maintaining query performance. Version tracking ensures auditability of
            --                configuration changes, and the environment-specific settings support
            --                dev/staging/prod parity. This design eliminates the need for code changes
            --                for tenant customizations, reducing deployment risk and enabling self-service.
            --
            -- Key Performance Indicators (KPIs):
            --   1. Configuration change frequency - Settings updates per organization per month
            --   2. Feature adoption rate - Percentage of organizations enabling premium features
            --   3. Branding customization rate - Organizations using custom themes
            --   4. Security policy compliance - Organizations meeting minimum security standards
            --   5. Configuration drift - Settings variance across environments
            --
            -- Feature References:
            --   - ORG10 (Organization Configuration)
            --   - ORG11 (White-labeling)
            --   - ORG12 (Feature Management)
            --   - SEC25 (Tenant Security Policies)
            --================================================================================================
            CREATE TABLE IF NOT EXISTS socialcandor_schema.org_settings (
                -- Primary key
                setting_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                -- Human-readable identifier
                setting_number VARCHAR(50) GENERATED ALWAYS AS (
                    'SET-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_settings_seq')::TEXT, 6, '0')
                ) STORED,

                -- Reference
                organization_id UUID NOT NULL UNIQUE,

                -- Core settings (structured for query performance)
                branding JSONB DEFAULT '{
                    "logo_url": null,
                    "favicon_url": null,
                    "primary_color": "#2563eb",
                    "secondary_color": "#4b5563",
                    "font_family": "Inter",
                    "custom_css": null,
                    "email_domain": null
                }',

                security JSONB DEFAULT '{
                    "mfa_required": false,
                    "password_min_length": 8,
                    "password_require_special": true,
                    "session_timeout_minutes": 60,
                    "max_login_attempts": 5,
                    "ip_whitelist_enabled": false,
                    "ip_whitelist": []
                }',

                features JSONB DEFAULT '{
                    "api_access": true,
                    "webhooks": false,
                    "sso": false,
                    "audit_logs": true,
                    "data_exports": true,
                    "advanced_analytics": false
                }',

                integrations JSONB DEFAULT '{
                    "slack_webhook": null,
                    "sentry_dsn": null,
                    "datadog_enabled": false
                }',

                -- Version control
                settings_version INTEGER NOT NULL DEFAULT 1,
                previous_settings JSONB,
                change_reason TEXT,

                -- Environment (for dev/staging/prod parity)
                environment VARCHAR(20) DEFAULT 'PRODUCTION' CHECK (
                    environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'SANDBOX')
                ),

                -- Effective dating
                effective_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                effective_to TIMESTAMP WITH TIME ZONE,
                is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

                -- Audit columns
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                created_by UUID NOT NULL,
                updated_by UUID DEFAULT uuid_nil(),

                -- Constraints
                CONSTRAINT fk_org_settings_org FOREIGN KEY (organization_id)
                    REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                CONSTRAINT fk_org_settings_created_by FOREIGN KEY (created_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                CONSTRAINT fk_org_settings_updated_by FOREIGN KEY (updated_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                CONSTRAINT chk_org_settings_dates CHECK (effective_to IS NULL OR effective_to > effective_from)
            );

            -- Comments
            COMMENT ON TABLE socialcandor_schema.org_settings IS 'Per-organization configuration settings with version tracking for auditability';
            COMMENT ON COLUMN socialcandor_schema.org_settings.branding IS 'Branding settings including logo, colors, and custom CSS';
            COMMENT ON COLUMN socialcandor_schema.org_settings.security IS 'Security policies including MFA requirements and password complexity';
            COMMENT ON COLUMN socialcandor_schema.org_settings.features IS 'Feature flags for per-tenant feature availability';
            COMMENT ON COLUMN socialcandor_schema.org_settings.settings_version IS 'Version number for tracking configuration changes';

            -- Indexes for performance
            CREATE INDEX idx_org_settings_org ON socialcandor_schema.org_settings(organization_id) WHERE is_current = TRUE;
            CREATE INDEX idx_org_settings_environment ON socialcandor_schema.org_settings(environment) WHERE is_current = TRUE;
            CREATE INDEX idx_org_settings_effective ON socialcandor_schema.org_settings(effective_from, effective_to) WHERE is_current = TRUE;

            -- GIN indexes for JSONB query performance
            CREATE INDEX idx_org_settings_branding ON socialcandor_schema.org_settings USING GIN (branding);
            CREATE INDEX idx_org_settings_security ON socialcandor_schema.org_settings USING GIN (security);
            CREATE INDEX idx_org_settings_features ON socialcandor_schema.org_settings USING GIN (features);

            -- Trigger for updated_at
            CREATE TRIGGER trg_org_settings_updated_at
                BEFORE UPDATE ON socialcandor_schema.org_settings
                FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


                --================================================================================================
              -- Table: MT04 - org_billing
              -- Description: Tracks consolidated billing for organizations, including invoices, payment
              --              history, and usage-based charges. Supports enterprise billing models with
              --              multiple payment methods and subscription management.
              -- Business Case: Enterprise customers require consolidated billing across all their
              --                sub-organizations and users. This table aggregates usage, calculates
              --                monthly invoices, and tracks payment status. The design supports various
              --                billing models: per-seat, usage-based, feature-based, and hybrid.
              --                Integration with external payment processors is handled through
              --                payment_intent_id and payment_method_id references. Historical tracking
              --                of billing periods enables accurate financial reporting and audits.
              --
              -- Key Performance Indicators (KPIs):
              --   1. Monthly Recurring Revenue (MRR) - Total monthly charges across organizations
              --   2. Average Revenue Per Organization (ARPO) - Revenue per org normalized
              --   3. Payment success rate - Percentage of successful payment attempts
              --   4. Dunning rate - Percentage of failed payments requiring follow-up
              --   5. Upgrade/downgrade velocity - Rate of plan changes per org
              --
              -- Feature References:
              --   - BIL05 (Organization Billing)
              --   - BIL06 (Consolidated Invoicing)
              --   - BIL07 (Usage-based Billing)
              --   - PAY07 (Payment Processing)
              --================================================================================================
              CREATE TABLE IF NOT EXISTS socialcandor_schema.org_billing (
                  -- Primary key
                  billing_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                  -- Human-readable identifier
                  billing_number VARCHAR(50) GENERATED ALWAYS AS (
                      'BILL-' || TO_CHAR(billing_period_start, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_billing_seq')::TEXT, 6, '0')
                  ) STORED,

                  -- References
                  organization_id UUID NOT NULL,
                  subscription_id UUID,        -- Link to subscription plan
                  invoice_id UUID,             -- Generated invoice

                  -- Billing period
                  billing_period_start DATE NOT NULL,
                  billing_period_end DATE NOT NULL,
                  due_date DATE NOT NULL,

                  -- Charges breakdown
                  base_amount NUMERIC(15,2) NOT NULL DEFAULT 0 CHECK (base_amount >= 0),
                  usage_amount NUMERIC(15,2) DEFAULT 0 CHECK (usage_amount >= 0),
                  addons_amount NUMERIC(15,2) DEFAULT 0 CHECK (addons_amount >= 0),
                  discount_amount NUMERIC(15,2) DEFAULT 0 CHECK (discount_amount >= 0),
                  tax_amount NUMERIC(15,2) DEFAULT 0 CHECK (tax_amount >= 0),
                  total_amount NUMERIC(15,2) GENERATED ALWAYS AS (
                      base_amount + usage_amount + addons_amount - discount_amount + tax_amount
                  ) STORED,

                  -- Currency
                  currency CHAR(3) NOT NULL DEFAULT 'USD',

                  -- Payment details
                  payment_status VARCHAR(30) CHECK (payment_status IN (
                      'PENDING', 'PROCESSING', 'PAID', 'PARTIALLY_PAID', 'OVERDUE', 'CANCELLED', 'REFUNDED'
                  )),
                  payment_method_id UUID,
                  payment_intent_id VARCHAR(255),
                  paid_at TIMESTAMP WITH TIME ZONE,

                  -- Usage details (denormalized for performance)
                  total_seats INTEGER DEFAULT 0 CHECK (total_seats >= 0),
                  total_api_calls BIGINT DEFAULT 0 CHECK (total_api_calls >= 0),
                  total_storage_gb NUMERIC(10,2) DEFAULT 0 CHECK (total_storage_gb >= 0),
                  usage_details JSONB DEFAULT '{}',

                  -- Discount and promo
                  promo_code_id UUID,
                  promo_discount_amount NUMERIC(15,2) DEFAULT 0,

                  -- Audit columns
                  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                  created_by UUID NOT NULL,
                  updated_by UUID DEFAULT uuid_nil(),

                  -- Constraints
                  CONSTRAINT fk_org_billing_org FOREIGN KEY (organization_id)
                      REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                  CONSTRAINT fk_org_billing_subscription FOREIGN KEY (subscription_id)
                      REFERENCES socialcandor_schema.user_subscriptions(subscription_id) ON DELETE SET NULL,
                  CONSTRAINT fk_org_billing_invoice FOREIGN KEY (invoice_id)
                      REFERENCES socialcandor_schema.invoices(invoice_id) ON DELETE SET NULL,
                  CONSTRAINT fk_org_billing_payment_method FOREIGN KEY (payment_method_id)
                      REFERENCES socialcandor_schema.payment_methods(payment_method_id) ON DELETE SET NULL,
                  CONSTRAINT fk_org_billing_promo_code FOREIGN KEY (promo_code_id)
                      REFERENCES socialcandor_schema.promo_codes(promo_id) ON DELETE SET NULL,
                  CONSTRAINT fk_org_billing_created_by FOREIGN KEY (created_by)
                      REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                  CONSTRAINT fk_org_billing_updated_by FOREIGN KEY (updated_by)
                      REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                  CONSTRAINT chk_org_billing_period CHECK (billing_period_end >= billing_period_start),
                  CONSTRAINT chk_org_billing_due CHECK (due_date >= billing_period_end)
              );

              -- Comments
              COMMENT ON TABLE socialcandor_schema.org_billing IS 'Consolidated billing records for organizations with usage-based charges';
              COMMENT ON COLUMN socialcandor_schema.org_billing.base_amount IS 'Base subscription amount before usage and addons';
              COMMENT ON COLUMN socialcandor_schema.org_billing.usage_amount IS 'Usage-based charges for the period';
              COMMENT ON COLUMN socialcandor_schema.org_billing.usage_details IS 'Breakdown of usage by category for transparency';

              -- Indexes for performance
              CREATE INDEX idx_org_billing_org ON socialcandor_schema.org_billing(organization_id, billing_period_start DESC);
              CREATE INDEX idx_org_billing_status ON socialcandor_schema.org_billing(payment_status, due_date) WHERE payment_status IN ('PENDING', 'OVERDUE');
              CREATE INDEX idx_org_billing_dates ON socialcandor_schema.org_billing(billing_period_start, billing_period_end);
              CREATE INDEX idx_org_billing_payment ON socialcandor_schema.org_billing(payment_method_id) WHERE payment_method_id IS NOT NULL;
              CREATE INDEX idx_org_billing_created ON socialcandor_schema.org_billing(created_at DESC);

              -- Trigger for updated_at
              CREATE TRIGGER trg_org_billing_updated_at
                  BEFORE UPDATE ON socialcandor_schema.org_billing
                  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                  --================================================================================================
                  -- Table: MT05 - org_domains
                  -- Description: Stores verified company domains for SSO, email validation, and domain-based
                  --              organization membership. Supports automatic user provisioning and authentication.
                  -- Business Case: Enterprise customers expect seamless authentication through their corporate
                  --                SSO (SAML/OIDC) and automatic organization membership based on email domain.
                  --                This table manages domain ownership verification through DNS TXT records,
                  --                tracks verification status, and links domains to identity providers.
                  --                The design supports multiple domains per organization (e.g., company.com,
                  --                company.co.uk) and enables domain-based routing for features like
                  --                auto-join, email notifications, and branded communications.
                  --
                  -- Key Performance Indicators (KPIs):
                  --   1. Domain verification success rate - Percentage of domains successfully verified
                  --   2. SSO adoption rate - Organizations using domain-based SSO
                  --   3. Auto-join rate - Users automatically added via domain verification
                  --   4. Domain verification time - Average time from request to verification
                  --   5. Domain churn rate - Domains removed or expired per month
                  --
                  -- Feature References:
                  --   - ORG13 (Domain Management)
                  --   - ORG14 (SSO Integration)
                  --   - AUTH06 (Domain-based Authentication)
                  --   - EMAIL03 (Domain Email Routing)
                  --================================================================================================
                  CREATE TABLE IF NOT EXISTS socialcandor_schema.org_domains (
                      -- Primary key
                      domain_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                      -- Human-readable identifier
                      domain_number VARCHAR(50) GENERATED ALWAYS AS (
                          'DOM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_domains_seq')::TEXT, 6, '0')
                      ) STORED,

                      -- References
                      organization_id UUID NOT NULL,

                      -- Domain details
                      domain_name VARCHAR(255) NOT NULL,
                      is_primary BOOLEAN DEFAULT FALSE,

                      -- Verification
                      verification_status socialcandor_schema.org_domain_verification_status NOT NULL DEFAULT 'PENDING',
                      verification_token VARCHAR(255),
                      verification_method VARCHAR(50) CHECK (verification_method IN ('DNS_TXT', 'DNS_CNAME', 'HTML_FILE', 'EMAIL')),
                      verified_at TIMESTAMP WITH TIME ZONE,
                      verification_attempts INTEGER DEFAULT 0 CHECK (verification_attempts >= 0),
                      last_verification_attempt TIMESTAMP WITH TIME ZONE,

                      -- SSO configuration
                      sso_enabled BOOLEAN DEFAULT FALSE,
                      sso_provider VARCHAR(50) CHECK (sso_provider IN ('SAML', 'OIDC', 'GOOGLE', 'MICROSOFT', 'CUSTOM')),
                      sso_metadata_url VARCHAR(500),
                      sso_entity_id VARCHAR(500),
                      sso_certificate TEXT,
                      sso_settings JSONB DEFAULT '{}',

                      -- Auto-join settings
                      auto_join_enabled BOOLEAN DEFAULT TRUE,
                      auto_join_role socialcandor_schema.org_member_role DEFAULT 'MEMBER',
                      auto_join_department VARCHAR(100),

                      -- Email settings
                      email_routing_enabled BOOLEAN DEFAULT FALSE,
                      email_provider VARCHAR(50),
                      mx_verified BOOLEAN DEFAULT FALSE,

                      -- Dates
                      requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      expires_at TIMESTAMP WITH TIME ZONE,
                      is_active BOOLEAN GENERATED ALWAYS AS (
                          expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP
                      ) STORED,

                      -- Audit columns
                      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      created_by UUID NOT NULL,
                      updated_by UUID DEFAULT uuid_nil(),

                      -- Constraints
                      CONSTRAINT fk_org_domains_org FOREIGN KEY (organization_id)
                          REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                      CONSTRAINT fk_org_domains_created_by FOREIGN KEY (created_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                      CONSTRAINT fk_org_domains_updated_by FOREIGN KEY (updated_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                      CONSTRAINT uk_org_domains_name UNIQUE (domain_name),
                      CONSTRAINT chk_org_domains_verification CHECK (
                          (verification_status = 'VERIFIED' AND verified_at IS NOT NULL) OR
                          (verification_status != 'VERIFIED' AND verified_at IS NULL)
                      )
                  );

                  -- Comments
                  COMMENT ON TABLE socialcandor_schema.org_domains IS 'Verified company domains for SSO, email validation, and automatic organization membership';
                  COMMENT ON COLUMN socialcandor_schema.org_domains.auto_join_role IS 'Default role for users automatically joining via domain verification';
                  COMMENT ON COLUMN socialcandor_schema.org_domains.sso_settings IS 'Provider-specific SSO configuration (SAML metadata, OIDC endpoints, etc.)';

                  -- Indexes for performance
                  CREATE INDEX idx_org_domains_org ON socialcandor_schema.org_domains(organization_id, is_primary) WHERE is_primary = TRUE;
                  CREATE INDEX idx_org_domains_domain ON socialcandor_schema.org_domains(domain_name);
                  CREATE INDEX idx_org_domains_status ON socialcandor_schema.org_domains(verification_status) WHERE verification_status != 'VERIFIED';
                  CREATE INDEX idx_org_domains_active ON socialcandor_schema.org_domains(is_active, expires_at) WHERE is_active = TRUE;
                  CREATE INDEX idx_org_domains_sso ON socialcandor_schema.org_domains(sso_enabled, sso_provider) WHERE sso_enabled = TRUE;

                  -- Trigger for updated_at
                  CREATE TRIGGER trg_org_domains_updated_at
                      BEFORE UPDATE ON socialcandor_schema.org_domains
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();
                      --================================================================================================
                    -- Table: MT06 - org_roles
                    -- Description: Defines custom roles with specific permission sets at the organization level,
                    --              extending the system-wide roles. Supports fine-grained access control.
                    -- Business Case: Organizations have unique permission requirements that cannot be satisfied
                    --                by system-wide roles alone. This table enables organization admins to define
                    --                custom roles with granular permissions (e.g., "Project Manager" with access
                    --                to specific projects, "Department Approver" with approval rights). The design
                    --                supports role hierarchies, permission inheritance, and auditability of role
                    --                changes. This approach scales to thousands of organizations while maintaining
                    --                performance through strategic indexing and JSONB permission storage.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Role creation rate - New custom roles created per organization per month
                    --   2. Permission complexity - Average number of permissions per custom role
                    --   3. Role reuse rate - Percentage of users assigned to custom roles vs. system roles
                    --   4. Role modification frequency - Changes to custom role definitions
                    --   5. Hierarchy depth - Maximum role inheritance levels
                    --
                    -- Feature References:
                    --   - ORG15 (Custom Roles)
                    --   - ORG16 (Permission Management)
                    --   - ORG17 (Role Hierarchies)
                    --   - ABAC04 (Organization ABAC)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.org_roles (
                        -- Primary key
                        role_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                        -- Human-readable identifier
                        role_number VARCHAR(50) GENERATED ALWAYS AS (
  'ROLE-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_roles_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        organization_id UUID NOT NULL,
                        parent_role_id UUID,       -- For role inheritance

                        -- Role identification
                        role_name VARCHAR(100) NOT NULL,
                        role_code VARCHAR(50) NOT NULL,
                        description TEXT,

                        -- Permission definitions
                        permissions JSONB NOT NULL DEFAULT '[]',             -- Array of permission objects
                        resource_scopes JSONB DEFAULT '{}',                  -- Scope limitations per resource

                        -- Role attributes
                        is_default BOOLEAN DEFAULT FALSE,
                        is_system_role BOOLEAN DEFAULT FALSE,                -- Cannot be modified
                        priority INTEGER DEFAULT 0 CHECK (priority >= 0),    -- For conflict resolution

                        -- Effective dating
                        effective_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        effective_to TIMESTAMP WITH TIME ZONE,
                        is_active BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

                        -- Audit columns
                        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        created_by UUID NOT NULL,
                        updated_by UUID DEFAULT uuid_nil(),

                        -- Constraints
                        CONSTRAINT fk_org_roles_org FOREIGN KEY (organization_id)
  REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                        CONSTRAINT fk_org_roles_parent FOREIGN KEY (parent_role_id)
  REFERENCES socialcandor_schema.org_roles(role_id) ON DELETE SET NULL,
                        CONSTRAINT fk_org_roles_created_by FOREIGN KEY (created_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                        CONSTRAINT fk_org_roles_updated_by FOREIGN KEY (updated_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                        CONSTRAINT uk_org_roles_code UNIQUE (organization_id, role_code, effective_from),
                        CONSTRAINT chk_org_roles_dates CHECK (effective_to IS NULL OR effective_to > effective_from)
                    );

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.org_roles IS 'Organization-specific custom roles extending system-wide roles for fine-grained access control';
                    COMMENT ON COLUMN socialcandor_schema.org_roles.permissions IS 'Array of permission objects defining what this role can do';
                    COMMENT ON COLUMN socialcandor_schema.org_roles.resource_scopes IS 'Resource-specific scope limitations (e.g., only Project X, Department Y)';

                    -- Indexes for performance
                    CREATE INDEX idx_org_roles_org ON socialcandor_schema.org_roles(organization_id, is_active) WHERE is_active = TRUE;
                    CREATE INDEX idx_org_roles_parent ON socialcandor_schema.org_roles(parent_role_id) WHERE parent_role_id IS NOT NULL;
                    CREATE INDEX idx_org_roles_code ON socialcandor_schema.org_roles(role_code) WHERE is_active = TRUE;
                    CREATE INDEX idx_org_roles_default ON socialcandor_schema.org_roles(organization_id, is_default) WHERE is_default = TRUE;
                    CREATE INDEX idx_org_roles_effective ON socialcandor_schema.org_roles(effective_from, effective_to) WHERE is_active = TRUE;

                    -- GIN index for permission queries
                    CREATE INDEX idx_org_roles_permissions ON socialcandor_schema.org_roles USING GIN (permissions);

                    -- Trigger for updated_at
                    CREATE TRIGGER trg_org_roles_updated_at
                        BEFORE UPDATE ON socialcandor_schema.org_roles
                        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                        --================================================================================================
                    -- Table: MT07 - org_audit_log
                    -- Description: Comprehensive audit trail of all organization-level activities including
                    --              membership changes, setting modifications, and permission updates.
                    -- Business Case: Enterprise compliance requirements (SOC2, ISO27001, GDPR) mandate detailed
                    --                audit trails of who did what, when, and from where at the organization level.
                    --                This table captures all critical activities with before/after state snapshots
                    --                for complete reconstructability. The design supports forensic investigations,
                    --                compliance reporting, and anomaly detection. Partitioning by month ensures
                    --                query performance even with billions of audit records. IP addresses and
                    --                user agents provide context for security investigations.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Audit coverage - Percentage of critical actions captured
                    --   2. Query performance - Time to retrieve audit history for an organization
                    --   3. Data retention compliance - Percentage of logs retained per policy
                    --   4. Anomaly detection rate - Suspicious patterns identified from audit logs
                    --   5. Storage efficiency - Compression ratio of audit data
                    --
                    -- Feature References:
                    --   - ORG18 (Organization Audit)
                    --   - COMP14 (Compliance Auditing)
                    --   - SEC26 (Security Monitoring)
                    --   - GDPR14 (Data Processing Records)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.org_audit_log (
                        -- Primary key (using BIGSERIAL for partitioning)
                        log_id BIGSERIAL,

                        -- Human-readable identifier
                        log_number VARCHAR(50) GENERATED ALWAYS AS (
  'AUD-' || TO_CHAR(occurred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_audit_log_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        organization_id UUID NOT NULL,
                        user_id UUID,              -- Actor (NULL for system)
                        target_user_id UUID,       -- Target user (for membership changes)

                        -- Action details
                        action_type VARCHAR(100) NOT NULL,
                        action_category VARCHAR(50) CHECK (action_category IN (
  'MEMBER', 'ROLE', 'SETTING', 'BILLING', 'DOMAIN', 'SECURITY', 'FEATURE', 'SYSTEM'
                        )),
                        action_status VARCHAR(20) CHECK (action_status IN ('SUCCESS', 'FAILURE', 'ATTEMPT')),

                        -- State tracking
                        before_state JSONB,
                        after_state JSONB,
                        changes JSONB,             -- Specific field changes

                        -- Context
                        occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        ip_address INET,
                        user_agent TEXT,
                        session_id UUID,
                        request_id UUID,           -- For request tracing

                        -- Additional metadata
                        metadata JSONB DEFAULT '{}',

                        -- Partition key
                        occurred_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,

                        -- Constraints
                        CONSTRAINT pk_org_audit_log PRIMARY KEY (log_id, occurred_date),
                        CONSTRAINT fk_org_audit_log_org FOREIGN KEY (organization_id)
  REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                        CONSTRAINT fk_org_audit_log_user FOREIGN KEY (user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                        CONSTRAINT fk_org_audit_log_target_user FOREIGN KEY (target_user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                    ) PARTITION BY RANGE (occurred_date);

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.org_audit_log IS 'Comprehensive audit trail of organization-level activities with state snapshots';
                    COMMENT ON COLUMN socialcandor_schema.org_audit_log.before_state IS 'JSON snapshot of state before the action';
                    COMMENT ON COLUMN socialcandor_schema.org_audit_log.after_state IS 'JSON snapshot of state after the action';
                    COMMENT ON COLUMN socialcandor_schema.org_audit_log.changes IS 'Specific fields that changed with old/new values';

                    -- Create partitions (example for current and next month)
                    DO $$
                    DECLARE
                        start_date DATE;
                        end_date DATE;
                        partition_name TEXT;
                    BEGIN
                        FOR i IN 0..2 LOOP
  start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
  end_date := start_date + '1 month'::INTERVAL;
  partition_name := 'org_audit_log_' || TO_CHAR(start_date, 'YYYY_MM');

  EXECUTE format('
      CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.org_audit_log
      FOR VALUES FROM (%L) TO (%L)',
      partition_name, start_date, end_date
  );
                        END LOOP;
                    END $$;

                    -- Indexes on parent (will be inherited by partitions)
                    CREATE INDEX idx_org_audit_log_org ON socialcandor_schema.org_audit_log(organization_id, occurred_at DESC);
                    CREATE INDEX idx_org_audit_log_user ON socialcandor_schema.org_audit_log(user_id, occurred_at DESC) WHERE user_id IS NOT NULL;
                    CREATE INDEX idx_org_audit_log_target_user ON socialcandor_schema.org_audit_log(target_user_id, occurred_at DESC) WHERE target_user_id IS NOT NULL;
                    CREATE INDEX idx_org_audit_log_category ON socialcandor_schema.org_audit_log(action_category, occurred_at DESC);
                    CREATE INDEX idx_org_audit_log_ip ON socialcandor_schema.org_audit_log(ip_address) WHERE ip_address IS NOT NULL;

                    --================================================================================================
                  -- Table: MT08 - org_quota_usage
                  -- Description: Tracks real-time usage of resource quotas per organization with threshold
                  --              monitoring and automated alerting. Enables usage-based billing and governance.
                  -- Business Case: Enterprise organizations need visibility into their resource consumption
                  --                and the ability to set limits to prevent unexpected costs. This table
                  --                provides real-time tracking of usage across multiple resource types,
                  --                with configurable thresholds for warnings and enforcement. The design
                  --                supports both hard limits (enforced at API level) and soft limits
                  --                (warnings only). Usage history enables trend analysis and capacity
                  --                planning. Integration with billing systems allows for usage-based
                  --                invoicing and chargeback.
                  --
                  -- Key Performance Indicators (KPIs):
                  --   1. Quota utilization rate - Percentage of allocated quota used per resource
                  --   2. Threshold breach frequency - Number of times warnings/critical limits hit
                  --   3. Quota enforcement effectiveness - Reduction in overage incidents
                  --   4. Usage growth rate - Month-over-month increase in resource consumption
                  --   5. Forecast accuracy - Predicted vs. actual usage
                  --
                  -- Feature References:
                  --   - ORG19 (Resource Quotas)
                  --   - ORG20 (Usage Monitoring)
                  --   - BIL08 (Usage-based Billing)
                  --   - CAP01 (Capacity Planning)
                  --================================================================================================
                  CREATE TABLE IF NOT EXISTS socialcandor_schema.org_quota_usage (
                      -- Primary key
                      usage_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                      -- Human-readable identifier
                      usage_number VARCHAR(50) GENERATED ALWAYS AS (
                          'QUOTA-' || TO_CHAR(usage_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.org_quota_usage_seq')::TEXT, 6, '0')
                      ) STORED,

                      -- References
                      organization_id UUID NOT NULL,
                      subscription_id UUID,      -- Link to current subscription

                      -- Quota definition
                      resource_type socialcandor_schema.quota_resource_type NOT NULL,
                      quota_limit INTEGER NOT NULL CHECK (quota_limit >= 0),  -- Maximum allowed (0 = unlimited)

                      -- Usage tracking
                      usage_date DATE NOT NULL,
                      usage_count INTEGER NOT NULL DEFAULT 0 CHECK (usage_count >= 0),
                      usage_details JSONB,        -- Breakdown of usage (e.g., by user)

                      -- Thresholds
                      warning_threshold INTEGER CHECK (warning_threshold >= 0),
                      critical_threshold INTEGER CHECK (critical_threshold >= 0),

                      -- Alerting
                      warning_triggered BOOLEAN DEFAULT FALSE,
                      critical_triggered BOOLEAN DEFAULT FALSE,
                      last_alert_sent_at TIMESTAMP WITH TIME ZONE,

                      -- Rolling periods
                      current_period_start DATE NOT NULL,
                      current_period_end DATE NOT NULL,
                      period_type VARCHAR(20) CHECK (period_type IN ('DAILY', 'MONTHLY', 'QUARTERLY', 'YEARLY')),

                      -- Audit columns
                      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      created_by UUID NOT NULL,
                      updated_by UUID DEFAULT uuid_nil(),

                      -- Constraints
                      CONSTRAINT fk_org_quota_usage_org FOREIGN KEY (organization_id)
                          REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
                      CONSTRAINT fk_org_quota_usage_subscription FOREIGN KEY (subscription_id)
                          REFERENCES socialcandor_schema.user_subscriptions(subscription_id) ON DELETE SET NULL,
                      CONSTRAINT fk_org_quota_usage_created_by FOREIGN KEY (created_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                      CONSTRAINT fk_org_quota_usage_updated_by FOREIGN KEY (updated_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                      CONSTRAINT uk_org_quota_usage UNIQUE (organization_id, resource_type, current_period_start),
                      CONSTRAINT chk_org_quota_period CHECK (current_period_end >= current_period_start),
                      CONSTRAINT chk_org_quota_thresholds CHECK (
                          warning_threshold IS NULL OR
                          (warning_threshold >= 0 AND warning_threshold <= quota_limit)
                      )
                  );

                  -- Comments
                  COMMENT ON TABLE socialcandor_schema.org_quota_usage IS 'Real-time tracking of resource quota usage per organization with threshold monitoring';
                  COMMENT ON COLUMN socialcandor_schema.org_quota_usage.usage_details IS 'Detailed breakdown of usage (e.g., which users consumed resources)';
                  COMMENT ON COLUMN socialcandor_schema.org_quota_usage.warning_triggered IS 'Whether warning threshold has been exceeded';
                  COMMENT ON COLUMN socialcandor_schema.org_quota_usage.critical_triggered IS 'Whether critical threshold has been exceeded';

                  -- Indexes for performance
                  CREATE INDEX idx_org_quota_usage_org ON socialcandor_schema.org_quota_usage(organization_id, resource_type, current_period_start DESC);
                  CREATE INDEX idx_org_quota_usage_period ON socialcandor_schema.org_quota_usage(current_period_start, current_period_end);
                  CREATE INDEX idx_org_quota_usage_alerts ON socialcandor_schema.org_quota_usage(
                      resource_type, warning_triggered, critical_triggered
                  ) WHERE warning_triggered = TRUE OR critical_triggered = TRUE;
                  CREATE INDEX idx_org_quota_usage_date ON socialcandor_schema.org_quota_usage(usage_date DESC);

                  -- Trigger for updated_at
                  CREATE TRIGGER trg_org_quota_usage_updated_at
                      BEFORE UPDATE ON socialcandor_schema.org_quota_usage
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                  -- Function to check quota and trigger alerts
                  CREATE OR REPLACE FUNCTION socialcandor_schema.check_quota_alert()
                  RETURNS TRIGGER AS $$
                  DECLARE
                      v_usage_percent NUMERIC;
                  BEGIN
                      IF NEW.quota_limit > 0 THEN
                          v_usage_percent := (NEW.usage_count::NUMERIC / NEW.quota_limit::NUMERIC) * 100;

                          -- Check warning threshold
                          IF NEW.warning_threshold IS NOT NULL AND v_usage_percent >= NEW.warning_threshold THEN
    NEW.warning_triggered := TRUE;
                          END IF;

                          -- Check critical threshold
                          IF NEW.critical_threshold IS NOT NULL AND v_usage_percent >= NEW.critical_threshold THEN
    NEW.critical_triggered := TRUE;
                          END IF;
                      END IF;

                      RETURN NEW;
                  END;
                  $$ LANGUAGE plpgsql;

                  CREATE TRIGGER trg_org_quota_usage_check
                      BEFORE INSERT OR UPDATE OF usage_count ON socialcandor_schema.org_quota_usage
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_quota_alert();

                      --================================================================================================
                    -- Table: SC01 - user_tokens
                    -- Description: Manages one-time security tokens for email verification, password reset,
                    --              magic link authentication, and account recovery. Includes expiration,
                    --              usage tracking, and audit trail.
                    -- Business Case: Secure account actions require time-limited, single-use tokens that cannot
                    --                be reused or replayed. This table centralizes token management across all
                    --                authentication flows, ensuring consistent security policies. The design
                    --                prevents token reuse (used_at), enforces expiration (expires_at), and
                    --                tracks IP/user agent for forensic analysis. Separate token types enable
                    --                different validity periods (e.g., password reset: 1 hour, email verification:
                    --                24 hours, magic link: 15 minutes). Token rotation and invalidation on
                    --                password changes prevent compromised tokens from being used.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Token usage rate - Percentage of issued tokens that are successfully used
                    --   2. Token expiration rate - Percentage of tokens that expire unused
                    --   3. Average time to use - Time between token issuance and consumption
                    --   4. Token reuse attempts - Count of attempts to reuse tokens
                    --   5. Fraud detection rate - Suspicious token usage patterns identified
                    --
                    -- Feature References:
                    --   - AUTH07 (Token-based Authentication)
                    --   - AUTH08 (Email Verification)
                    --   - AUTH09 (Password Reset)
                    --   - SEC27 (Session Management)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.user_tokens (
                        -- Primary key
                        token_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                        -- Human-readable identifier
                        token_number VARCHAR(50) GENERATED ALWAYS AS (
  'TOK-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_tokens_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        user_id UUID NOT NULL,

                        -- Token details
                        token_hash VARCHAR(255) NOT NULL UNIQUE,           -- Store hash, not raw token
                        token_type socialcandor_schema.user_token_type NOT NULL,

                        -- Expiration
                        expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
                        used_at TIMESTAMP WITH TIME ZONE,
                        is_valid BOOLEAN GENERATED ALWAYS AS (
  used_at IS NULL AND expires_at > CURRENT_TIMESTAMP
                        ) STORED,

                        -- Usage tracking
                        attempt_count INTEGER DEFAULT 0 CHECK (attempt_count >= 0),
                        last_attempt_at TIMESTAMP WITH TIME ZONE,

                        -- Context
                        created_ip INET,
                        created_user_agent TEXT,
                        used_ip INET,
                        used_user_agent TEXT,

                        -- Rotation tracking
                        replaced_by_token_id UUID,                          -- For token rotation
                        revoked_at TIMESTAMP WITH TIME ZONE,
                        revocation_reason VARCHAR(100),

                        -- Audit columns
                        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        created_by UUID NOT NULL,
                        updated_by UUID DEFAULT uuid_nil(),

                        -- Constraints
                        CONSTRAINT fk_user_tokens_user FOREIGN KEY (user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                        CONSTRAINT fk_user_tokens_replaced_by FOREIGN KEY (replaced_by_token_id)
  REFERENCES socialcandor_schema.user_tokens(token_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_tokens_created_by FOREIGN KEY (created_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                        CONSTRAINT fk_user_tokens_updated_by FOREIGN KEY (updated_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                        CONSTRAINT chk_user_tokens_expiry CHECK (expires_at > created_at),
                        CONSTRAINT chk_user_tokens_used CHECK (used_at IS NULL OR used_at >= created_at)
                    );

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.user_tokens IS 'One-time security tokens for email verification, password reset, and magic link authentication';
                    COMMENT ON COLUMN socialcandor_schema.user_tokens.token_hash IS 'SHA-256 hash of the token value (never store raw tokens)';
                    COMMENT ON COLUMN socialcandor_schema.user_tokens.attempt_count IS 'Number of validation attempts (for brute force detection)';

                    -- Indexes for performance
                    CREATE INDEX idx_user_tokens_hash ON socialcandor_schema.user_tokens(token_hash);
                    CREATE INDEX idx_user_tokens_user ON socialcandor_schema.user_tokens(user_id, token_type, created_at DESC);
                    CREATE INDEX idx_user_tokens_valid ON socialcandor_schema.user_tokens(expires_at) WHERE is_valid = TRUE;
                    CREATE INDEX idx_user_tokens_expired ON socialcandor_schema.user_tokens(expires_at) WHERE expires_at < CURRENT_TIMESTAMP;

                    -- Trigger for updated_at
                    CREATE TRIGGER trg_user_tokens_updated_at
                        BEFORE UPDATE ON socialcandor_schema.user_tokens
                        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                    -- Function to clean expired tokens (run as scheduled job)
                    CREATE OR REPLACE FUNCTION socialcandor_schema.clean_expired_tokens()
                    RETURNS INTEGER AS $$
                    DECLARE
                        v_deleted INTEGER;
                    BEGIN
                        DELETE FROM socialcandor_schema.user_tokens
                        WHERE expires_at < CURRENT_TIMESTAMP - INTERVAL '30 days'
                        RETURNING COUNT(*) INTO v_deleted;

                        RETURN v_deleted;
                    END;
                    $$ LANGUAGE plpgsql SECURITY DEFINER;

                    --================================================================================================
                    -- Table: SC02 - user_login_history
                    -- Description: Complete audit trail of all login attempts (success/failure) with device
                    --              fingerprinting, geolocation, and contextual data for security monitoring.
                    -- Business Case: Security monitoring and threat detection require comprehensive login
                    --                telemetry. This table captures every authentication attempt with enough
                    --                detail to detect anomalies: impossible travel (geolocation), brute force
                    --                attacks (rapid failures), credential stuffing (pattern analysis), and
                    --                account takeover (unusual device fingerprints). The design supports
                    --                integration with SIEM systems and enables real-time alerting. Historical
                    --                data retention policies can be implemented via partitioning and archival.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Login success rate - Percentage of successful vs. failed attempts
                    --   2. Unique IPs per user - Average number of distinct IPs per user
                    --   3. Impossible travel incidents - Logins from geographically impossible locations
                    --   4. Brute force detection - Accounts with >5 failed attempts in 5 minutes
                    --   5. Device churn - Rate of new device registrations per user
                    --
                    -- Feature References:
                    --   - SEC28 (Login Monitoring)
                    --   - SEC29 (Anomaly Detection)
                    --   - SEC30 (Threat Intelligence)
                    --   - AUD10 (Authentication Audit)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.user_login_history (
                        -- Primary key
                        login_id BIGSERIAL,

                        -- Human-readable identifier
                        login_number VARCHAR(50) GENERATED ALWAYS AS (
  'LOG-' || TO_CHAR(login_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_login_history_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        user_id UUID,
                        session_id UUID,

                        -- Login details
                        login_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        login_method VARCHAR(50) CHECK (login_method IN (
  'PASSWORD', 'MFA', 'SSO', 'MAGIC_LINK', 'API_KEY', 'OAUTH', 'CERTIFICATE'
                        )),

                        -- Outcome
                        successful BOOLEAN NOT NULL,
                        failure_reason VARCHAR(255),

                        -- Authentication factors
                        factor_1_used VARCHAR(50),                          -- Primary factor (password, token)
                        factor_2_used VARCHAR(50),                          -- Secondary factor (TOTP, SMS)

                        -- Device fingerprinting
                        device_id UUID,           -- Reference to user_devices
                        device_fingerprint VARCHAR(255),
                        device_type VARCHAR(50),
                        device_name VARCHAR(255),
                        browser VARCHAR(100),
                        browser_version VARCHAR(50),
                        os VARCHAR(100),
                        os_version VARCHAR(50),

                        -- Network and location
                        ip_address INET NOT NULL,
                        ip_country VARCHAR(3),
                        ip_city VARCHAR(100),
                        ip_latitude NUMERIC(10,8),
                        ip_longitude NUMERIC(11,8),
                        isp VARCHAR(255),
                        proxy_type VARCHAR(50),   -- VPN, TOR, etc.

                        -- User agent
                        user_agent TEXT,

                        -- Risk assessment
                        risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
                        risk_factors TEXT[],

                        -- Partition key
                        login_date DATE GENERATED ALWAYS AS (login_time::DATE) STORED,

                        -- Constraints
                        CONSTRAINT pk_user_login_history PRIMARY KEY (login_id, login_date),
                        CONSTRAINT fk_user_login_history_user FOREIGN KEY (user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_login_history_session FOREIGN KEY (session_id)
  REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_login_history_device FOREIGN KEY (device_id)
  REFERENCES socialcandor_schema.user_devices(device_id) ON DELETE SET NULL
                    ) PARTITION BY RANGE (login_date);

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.user_login_history IS 'Complete audit trail of all login attempts with device fingerprinting and geolocation';
                    COMMENT ON COLUMN socialcandor_schema.user_login_history.risk_score IS 'Calculated risk score for the login attempt (0-100)';
                    COMMENT ON COLUMN socialcandor_schema.user_login_history.risk_factors IS 'Array of risk factors identified (new device, new location, proxy, etc.)';

                    -- Create monthly partitions
                    DO $$
                    DECLARE
                        start_date DATE;
                        end_date DATE;
                        partition_name TEXT;
                    BEGIN
                        FOR i IN 0..11 LOOP
  start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
  end_date := start_date + '1 month'::INTERVAL;
  partition_name := 'user_login_history_' || TO_CHAR(start_date, 'YYYY_MM');

  EXECUTE format('
      CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.user_login_history
      FOR VALUES FROM (%L) TO (%L)',
      partition_name, start_date, end_date
  );
                        END LOOP;
                    END $$;

                    -- Indexes for performance
                    CREATE INDEX idx_user_login_history_user ON socialcandor_schema.user_login_history(user_id, login_time DESC) WHERE user_id IS NOT NULL;
                    CREATE INDEX idx_user_login_history_ip ON socialcandor_schema.user_login_history(ip_address, login_time DESC);
                    CREATE INDEX idx_user_login_history_success ON socialcandor_schema.user_login_history(successful, login_time DESC);
                    CREATE INDEX idx_user_login_history_device ON socialcandor_schema.user_login_history(device_fingerprint) WHERE device_fingerprint IS NOT NULL;
                    CREATE INDEX idx_user_login_history_risk ON socialcandor_schema.user_login_history(risk_score DESC) WHERE risk_score > 70;

                    --================================================================================================
                    -- Table: SC03 - user_password_history
                    -- Description: Stores historical password hashes to enforce password rotation policies
                    --              and prevent password reuse. Supports NIST SP 800-63B compliance.
                    -- Business Case: NIST guidelines and security best practices require that users cannot
                    --                reuse recent passwords. This table maintains a configurable history
                    --                length (typically 5-24 previous passwords) to enforce this policy.
                    --                When users change passwords, the new hash is checked against history
                    --                to prevent reuse. The design also tracks password age to enforce
                    --                rotation intervals. Historical data is critical for forensic
                    --                investigations when credentials are compromised.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Password reuse rate - Percentage of attempts to reuse previous passwords
                    --   2. Average password age - Time between password changes
                    --   3. Compliance rate - Percentage of users with password age < 90 days
                    --   4. Breach impact - Accounts requiring password reset after breach
                    --   5. Rotation enforcement effectiveness - Reduction in account takeover
                    --
                    -- Feature References:
                    --   - SEC31 (Password Policy)
                    --   - SEC32 (Credential Management)
                    --   - COMP15 (NIST Compliance)
                    --   - AUD11 (Credential Audit)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.user_password_history (
                        -- Primary key
                        history_id BIGSERIAL PRIMARY KEY,

                        -- Human-readable identifier
                        history_number VARCHAR(50) GENERATED ALWAYS AS (
  'PWH-' || TO_CHAR(changed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_password_history_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        user_id UUID NOT NULL,

                        -- Password data
                        password_hash VARCHAR(255) NOT NULL,
                        password_algorithm VARCHAR(50) DEFAULT 'bcrypt',   -- For algorithm migration
                        password_strength INTEGER CHECK (password_strength >= 0 AND password_strength <= 100),

                        -- Change context
                        changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        changed_by UUID,          -- User or admin
                        change_reason VARCHAR(100) CHECK (change_reason IN (
  'USER_INITIATED', 'ADMIN_RESET', 'FORCED_ROTATION', 'BREACH_RESPONSE', 'INITIAL_SETUP'
                        )),

                        -- Source information
                        ip_address INET,
                        user_agent TEXT,

                        -- Expiration
                        expires_at TIMESTAMP WITH TIME ZONE,                 -- When this password becomes expired
                        is_current BOOLEAN DEFAULT FALSE,

                        -- Audit columns
                        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        created_by UUID NOT NULL,
                        updated_by UUID DEFAULT uuid_nil(),

                        -- Constraints
                        CONSTRAINT fk_user_password_history_user FOREIGN KEY (user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                        CONSTRAINT fk_user_password_history_changed_by FOREIGN KEY (changed_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_password_history_created_by FOREIGN KEY (created_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                        CONSTRAINT fk_user_password_history_updated_by FOREIGN KEY (updated_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                        CONSTRAINT chk_user_password_history_expiry CHECK (expires_at IS NULL OR expires_at > changed_at)
                    );

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.user_password_history IS 'Historical password hashes to enforce password rotation and prevent reuse (NIST SP 800-63B compliance)';
                    COMMENT ON COLUMN socialcandor_schema.user_password_history.password_strength IS 'Strength score of the password at creation (0-100)';
                    COMMENT ON COLUMN socialcandor_schema.user_password_history.is_current IS 'Whether this is the user''s current password';

                    -- Indexes for performance
                    CREATE INDEX idx_user_password_history_user ON socialcandor_schema.user_password_history(user_id, changed_at DESC);
                    CREATE INDEX idx_user_password_history_current ON socialcandor_schema.user_password_history(user_id) WHERE is_current = TRUE;
                    CREATE INDEX idx_user_password_history_expires ON socialcandor_schema.user_password_history(expires_at) WHERE expires_at IS NOT NULL;

                    -- Trigger for updated_at
                    CREATE TRIGGER trg_user_password_history_updated_at
                        BEFORE UPDATE ON socialcandor_schema.user_password_history
                        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                    -- Function to check password reuse
                    CREATE OR REPLACE FUNCTION socialcandor_schema.check_password_reuse(
                        p_user_id UUID,
                        p_password_hash VARCHAR,
                        p_history_length INTEGER DEFAULT 5
                    )
                    RETURNS BOOLEAN AS $$
                    DECLARE
                        v_match_count INTEGER;
                    BEGIN
                        -- Check if password exists in recent history
                        SELECT COUNT(*) INTO v_match_count
                        FROM socialcandor_schema.user_password_history
                        WHERE user_id = p_user_id
                          AND password_hash = p_password_hash
                          AND changed_at > CURRENT_TIMESTAMP - INTERVAL '1 year'
                        ORDER BY changed_at DESC
                        LIMIT p_history_length;

                        RETURN v_match_count > 0;
                    END;
                    $$ LANGUAGE plpgsql SECURITY DEFINER;


                    --================================================================================================
                  -- Table: SC04 - user_mfa_backup_codes_usage
                  -- Description: Logs usage of MFA backup codes for account recovery, providing audit trail
                  --              and tracking code consumption. Enables monitoring of recovery attempts.
                  -- Business Case: Backup codes provide a recovery mechanism when primary MFA methods are
                  --                unavailable. This table tracks each code usage to prevent replay attacks
                  --                and detect suspicious patterns (e.g., multiple codes used in short period).
                  --                The design stores only hashes of codes for security, never plaintext.
                  --                Usage patterns can indicate account compromise attempts or legitimate
                  --                recovery scenarios. Integration with alerting systems enables real-time
                  --                notification of unusual recovery activity.
                  --
                  -- Key Performance Indicators (KPIs):
                  --   1. Backup code usage rate - Percentage of users using backup codes per month
                  --   2. Code exhaustion rate - Users running out of backup codes
                  --   3. Suspicious usage patterns - Multiple codes used from different IPs
                  --   4. Recovery success rate - Percentage of successful recoveries using backup codes
                  --   5. Time to replenish - How quickly users generate new codes after depletion
                  --
                  -- Feature References:
                  --   - SEC33 (MFA Backup Codes)
                  --   - SEC34 (Account Recovery)
                  --   - AUD12 (Recovery Audit)
                  --   - COMP16 (Recovery Compliance)
                  --================================================================================================
                  CREATE TABLE IF NOT EXISTS socialcandor_schema.user_mfa_backup_codes_usage (
                      -- Primary key
                      usage_id BIGSERIAL PRIMARY KEY,

                      -- Human-readable identifier
                      usage_number VARCHAR(50) GENERATED ALWAYS AS (
                          'MFAU-' || TO_CHAR(used_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_mfa_backup_codes_usage_seq')::TEXT, 6, '0')
                      ) STORED,

                      -- References
                      user_id UUID NOT NULL,

                      -- Code details
                      code_hash VARCHAR(255) NOT NULL,
                      code_index INTEGER CHECK (code_index >= 0 AND code_index <= 15),  -- Position in backup list

                      -- Usage context
                      used_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                      successful BOOLEAN NOT NULL,

                      -- Authentication context
                      session_id UUID,
                      ip_address INET,
                      user_agent TEXT,

                      -- Rate limiting
                      attempt_count INTEGER DEFAULT 1 CHECK (attempt_count >= 0),

                      -- Code status after use
                      code_depleted BOOLEAN DEFAULT TRUE,               -- Whether code is now invalid
                      remaining_codes INTEGER CHECK (remaining_codes >= 0),

                      -- Audit columns
                      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      created_by UUID NOT NULL,
                      updated_by UUID DEFAULT uuid_nil(),

                      -- Constraints
                      CONSTRAINT fk_mfa_backup_usage_user FOREIGN KEY (user_id)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                      CONSTRAINT fk_mfa_backup_usage_session FOREIGN KEY (session_id)
                          REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                      CONSTRAINT fk_mfa_backup_usage_created_by FOREIGN KEY (created_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                      CONSTRAINT fk_mfa_backup_usage_updated_by FOREIGN KEY (updated_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                  );

                  -- Comments
                  COMMENT ON TABLE socialcandor_schema.user_mfa_backup_codes_usage IS 'Logs usage of MFA backup codes for account recovery and audit';
                  COMMENT ON COLUMN socialcandor_schema.user_mfa_backup_codes_usage.code_hash IS 'SHA-256 hash of the backup code (never store plaintext)';
                  COMMENT ON COLUMN socialcandor_schema.user_mfa_backup_codes_usage.code_index IS 'Position in the backup code list (0-15 for standard 16 codes)';

                  -- Indexes for performance
                  CREATE INDEX idx_mfa_backup_usage_user ON socialcandor_schema.user_mfa_backup_codes_usage(user_id, used_at DESC);
                  CREATE INDEX idx_mfa_backup_usage_code ON socialcandor_schema.user_mfa_backup_codes_usage(code_hash);
                  CREATE INDEX idx_mfa_backup_usage_success ON socialcandor_schema.user_mfa_backup_codes_usage(successful, used_at DESC);

                  -- Trigger for updated_at
                  CREATE TRIGGER trg_user_mfa_backup_codes_usage_updated_at
                      BEFORE UPDATE ON socialcandor_schema.user_mfa_backup_codes_usage
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                  -- Function to detect suspicious backup code usage
                  CREATE OR REPLACE FUNCTION socialcandor_schema.detect_suspicious_backup_usage()
                  RETURNS TRIGGER AS $$
                  DECLARE
                      v_recent_attempts INTEGER;
                  BEGIN
                      -- Check for multiple failed attempts in last hour
                      SELECT COUNT(*) INTO v_recent_attempts
                      FROM socialcandor_schema.user_mfa_backup_codes_usage
                      WHERE user_id = NEW.user_id
                        AND used_at > CURRENT_TIMESTAMP - INTERVAL '1 hour'
                        AND successful = FALSE;

                      IF v_recent_attempts >= 5 THEN
                          -- Log security event
                          INSERT INTO socialcandor_schema.user_security_events (
    user_id, event_type, details, created_by
                          ) VALUES (
    NEW.user_id,
    'BACKUP_CODE_ATTACK_DETECTED',
    jsonb_build_object(
        'attempts', v_recent_attempts,
        'ip', NEW.ip_address
    ),
    (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
                          );
                      END IF;

                      RETURN NEW;
                  END;
                  $$ LANGUAGE plpgsql;

                  CREATE TRIGGER trg_mfa_backup_usage_suspicious
                      AFTER INSERT ON socialcandor_schema.user_mfa_backup_codes_usage
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.detect_suspicious_backup_usage();


                      --================================================================================================
                      -- Table: SC05 - user_security_events
                      -- Description: Comprehensive logging of security-sensitive events for SIEM integration,
                      --              threat detection, and forensic analysis. Supports real-time alerting.
                      -- Business Case: Modern security operations require centralized logging of all security-
                      --                relevant events: MFA changes, role assignments, permission modifications,
                      --                account locks, and suspicious activities. This table serves as the
                      --                foundation for security monitoring, enabling correlation across events
                      --                and users. The design supports industry-standard formats (CEF, LEEF) for
                      --                SIEM integration. Partitioning by month ensures query performance for
                      --                investigations while enabling efficient data retention policies.
                      --
                      -- Key Performance Indicators (KPIs):
                      --   1. Event volume - Number of security events per day
                      --   2. Mean Time to Detect (MTTD) - Time from event to alert generation
                      --   3. Mean Time to Respond (MTTR) - Time from alert to resolution
                      --   4. Event correlation rate - Percentage of events linked to incidents
                      --   5. False positive rate - Alerts that were not actionable
                      --
                      -- Feature References:
                      --   - SEC35 (Security Event Monitoring)
                      --   - SEC36 (SIEM Integration)
                      --   - INC03 (Incident Detection)
                      --   - COMP17 (Security Logging)
                      --================================================================================================
                      CREATE TABLE IF NOT EXISTS socialcandor_schema.user_security_events (
                          -- Primary key
                          event_id BIGSERIAL,

                          -- Human-readable identifier
                          event_number VARCHAR(50) GENERATED ALWAYS AS (
    'SEV-' || TO_CHAR(event_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_security_events_seq')::TEXT, 6, '0')
                          ) STORED,

                          -- References
                          user_id UUID,              -- Affected user
                          actor_user_id UUID,        -- User performing action
                          target_user_id UUID,       -- Target of action
                          session_id UUID,

                          -- Event classification
                          event_type socialcandor_schema.user_security_event_type NOT NULL,
                          event_category VARCHAR(50) CHECK (event_category IN (
    'AUTHENTICATION', 'AUTHORIZATION', 'ACCOUNT', 'CONFIGURATION', 'DATA_ACCESS'
                          )),
                          event_severity VARCHAR(20) CHECK (event_severity IN ('INFO', 'WARNING', 'ERROR', 'CRITICAL')),

                          -- Event details
                          event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                          description TEXT,

                          -- State changes
                          before_state JSONB,
                          after_state JSONB,
                          changes JSONB,

                          -- Context
                          ip_address INET,
                          user_agent TEXT,
                          device_id UUID,

                          -- Risk scoring
                          risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
                          risk_factors TEXT[],

                          -- Alerting
                          alert_generated BOOLEAN DEFAULT FALSE,
                          alert_sent_at TIMESTAMP WITH TIME ZONE,

                          -- Incident correlation
                          incident_id UUID,          -- Linked security incident

                          -- Partition key
                          event_date DATE GENERATED ALWAYS AS (event_time::DATE) STORED,

                          -- SIEM export
                          siem_exported BOOLEAN DEFAULT FALSE,
                          siem_exported_at TIMESTAMP WITH TIME ZONE,

                          -- Audit
                          created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

                          -- Constraints
                          CONSTRAINT pk_user_security_events PRIMARY KEY (event_id, event_date),
                          CONSTRAINT fk_security_events_user FOREIGN KEY (user_id)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                          CONSTRAINT fk_security_events_actor FOREIGN KEY (actor_user_id)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                          CONSTRAINT fk_security_events_target FOREIGN KEY (target_user_id)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                          CONSTRAINT fk_security_events_session FOREIGN KEY (session_id)
    REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                          CONSTRAINT fk_security_events_device FOREIGN KEY (device_id)
    REFERENCES socialcandor_schema.user_devices(device_id) ON DELETE SET NULL
                      ) PARTITION BY RANGE (event_date);

                      -- Comments
                      COMMENT ON TABLE socialcandor_schema.user_security_events IS 'Comprehensive logging of security-sensitive events for SIEM integration and threat detection';
                      COMMENT ON COLUMN socialcandor_schema.user_security_events.before_state IS 'JSON snapshot of affected resource before the event';
                      COMMENT ON COLUMN socialcandor_schema.user_security_events.after_state IS 'JSON snapshot of affected resource after the event';
                      COMMENT ON COLUMN socialcandor_schema.user_security_events.risk_factors IS 'Array of risk factors contributing to the risk score';

                      -- Create monthly partitions
                      DO $$
                      DECLARE
                          start_date DATE;
                          end_date DATE;
                          partition_name TEXT;
                      BEGIN
                          FOR i IN 0..11 LOOP
    start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
    end_date := start_date + '1 month'::INTERVAL;
    partition_name := 'user_security_events_' || TO_CHAR(start_date, 'YYYY_MM');

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.user_security_events
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );
                          END LOOP;
                      END $$;

                      -- Indexes for performance
                      CREATE INDEX idx_security_events_user ON socialcandor_schema.user_security_events(user_id, event_time DESC) WHERE user_id IS NOT NULL;
                      CREATE INDEX idx_security_events_type ON socialcandor_schema.user_security_events(event_type, event_time DESC);
                      CREATE INDEX idx_security_events_severity ON socialcandor_schema.user_security_events(event_severity, event_time DESC);
                      CREATE INDEX idx_security_events_risk ON socialcandor_schema.user_security_events(risk_score DESC) WHERE risk_score > 70;
                      CREATE INDEX idx_security_events_incident ON socialcandor_schema.user_security_events(incident_id) WHERE incident_id IS NOT NULL;
                      CREATE INDEX idx_security_events_siem ON socialcandor_schema.user_security_events(siem_exported, event_date) WHERE siem_exported = FALSE;

                      -- Trigger to generate alerts for high-risk events
                      CREATE OR REPLACE FUNCTION socialcandor_schema.security_event_alert_trigger()
                      RETURNS TRIGGER AS $$
                      BEGIN
                          -- Alert on critical events
                          IF NEW.event_severity = 'CRITICAL' OR NEW.risk_score >= 90 THEN
    NEW.alert_generated := TRUE;

    -- Insert into anomaly_alerts for processing
    INSERT INTO socialcandor_schema.anomaly_alerts (
        alert_name, severity, source_system, description, created_by
    ) VALUES (
        'Security Event: ' || NEW.event_type,
        'CRITICAL',
        'security_monitoring',
        NEW.description,
        (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
    );
                          END IF;

                          RETURN NEW;
                      END;
                      $$ LANGUAGE plpgsql;

                      CREATE TRIGGER trg_security_events_alert
                          BEFORE INSERT ON socialcandor_schema.user_security_events
                          FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.security_event_alert_trigger();


                          --================================================================================================
                          -- Table: SC06 - user_anonymization_queue
                          -- Description: Manages asynchronous processing of GDPR right-to-be-forgotten requests,
                          --              tracking the status and progress of data anonymization jobs.
                          -- Business Case: GDPR Article 17 requires complete erasure of personal data upon request.
                          --                However, immediate deletion can impact system performance and may need
                          --                to be coordinated across multiple services. This queue decouples the
                          --                request from execution, allowing retry logic, progress tracking, and
                          --                auditability. The design supports multi-step anonymization processes
                          --                (e.g., first anonymize user profiles, then posts, then logs) with
                          --                dependency tracking. Failed jobs are automatically retried with
                          --                exponential backoff, and administrative intervention is flagged.
                          --
                          -- Key Performance Indicators (KPIs):
                          --   1. Average completion time - Time from request to full anonymization
                          --   2. Queue backlog - Number of pending anonymization jobs
                          --   3. Success rate - Percentage of jobs completed successfully
                          --   4. Retry frequency - Average retries per failed job
                          --   5. Deadline compliance - Percentage completed within 30-day GDPR window
                          --
                          -- Feature References:
                          --   - GDPR15 (Right to Erasure)
                          --   - GDPR16 (Data Anonymization)
                          --   - BATCH02 (Batch Processing)
                          --   - AUD13 (Erasure Audit)
                          --================================================================================================
                          CREATE TABLE IF NOT EXISTS socialcandor_schema.user_anonymization_queue (
    -- Primary key
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'ANON-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_anonymization_queue_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    user_id UUID NOT NULL,
    request_id UUID,          -- Link to data_subject_requests

    -- Job configuration
    anonymization_scope TEXT[] NOT NULL,                -- Which data categories to anonymize
    retention_exceptions JSONB DEFAULT '[]',            -- Data to retain (legal hold)

    -- Job status
    status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
        'PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'CANCELLED', 'ON_HOLD'
    )),

    -- Timing
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    deadline TIMESTAMP WITH TIME ZONE,                  -- GDPR 30-day deadline

    -- Execution tracking
    current_step INTEGER DEFAULT 0,
    total_steps INTEGER DEFAULT 1,
    steps_completed JSONB DEFAULT '[]',

    -- Retry logic
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),
    max_retries INTEGER DEFAULT 3,
    last_error TEXT,
    last_retry_at TIMESTAMP WITH TIME ZONE,

    -- Processing statistics
    records_processed INTEGER DEFAULT 0,
    records_failed INTEGER DEFAULT 0,
    processing_log TEXT,

    -- Completion data
    anonymized_data_summary JSONB,                       -- What was anonymized/deleted
    verification_hash VARCHAR(255),                       -- For integrity verification

    -- Audit columns
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_anon_queue_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_anon_queue_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
    CONSTRAINT fk_anon_queue_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_anon_queue_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_anon_queue_deadline CHECK (deadline IS NULL OR deadline > created_at)
                          );

                          -- Comments
                          COMMENT ON TABLE socialcandor_schema.user_anonymization_queue IS 'Asynchronous processing queue for GDPR right-to-be-forgotten requests';
                          COMMENT ON COLUMN socialcandor_schema.user_anonymization_queue.anonymization_scope IS 'Array of data categories to anonymize (profile, posts, messages, etc.)';
                          COMMENT ON COLUMN socialcandor_schema.user_anonymization_queue.retention_exceptions IS 'JSON array of data to retain due to legal hold or other exceptions';

                          -- Indexes for performance
                          CREATE INDEX idx_anon_queue_user ON socialcandor_schema.user_anonymization_queue(user_id);
                          CREATE INDEX idx_anon_queue_status ON socialcandor_schema.user_anonymization_queue(status, created_at);
                          CREATE INDEX idx_anon_queue_deadline ON socialcandor_schema.user_anonymization_queue(deadline) WHERE status IN ('PENDING', 'PROCESSING');
                          CREATE INDEX idx_anon_queue_request ON socialcandor_schema.user_anonymization_queue(request_id) WHERE request_id IS NOT NULL;

                          -- Trigger for updated_at
                          CREATE TRIGGER trg_user_anonymization_queue_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_anonymization_queue
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                          -- Function to process anonymization jobs (called by scheduler)
                          CREATE OR REPLACE FUNCTION socialcandor_schema.process_anonymization_queue()
                          RETURNS INTEGER AS $$
                          DECLARE
    v_job RECORD;
    v_processed INTEGER := 0;
                          BEGIN
    FOR v_job IN
        SELECT * FROM socialcandor_schema.user_anonymization_queue
        WHERE status = 'PENDING'
          AND (deadline IS NULL OR deadline > CURRENT_TIMESTAMP)
        ORDER BY created_at
        LIMIT 10
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            UPDATE socialcandor_schema.user_anonymization_queue
            SET status = 'PROCESSING',
                started_at = CURRENT_TIMESTAMP
            WHERE job_id = v_job.job_id;

            -- Actual anonymization logic would be here
            -- This is a placeholder for the complex multi-table process

            UPDATE socialcandor_schema.user_anonymization_queue
            SET status = 'COMPLETED',
                completed_at = CURRENT_TIMESTAMP,
                records_processed = 1
            WHERE job_id = v_job.job_id;

            v_processed := v_processed + 1;
        EXCEPTION WHEN OTHERS THEN
            UPDATE socialcandor_schema.user_anonymization_queue
            SET status = 'FAILED',
                last_error = SQLERRM,
                retry_count = retry_count + 1,
                last_retry_at = CURRENT_TIMESTAMP
            WHERE job_id = v_job.job_id;
        END;
    END LOOP;

    RETURN v_processed;
                          END;
                          $$ LANGUAGE plpgsql SECURITY DEFINER;


                          --================================================================================================
                        -- Table: SC07 - user_export_files
                        -- Description: Stores generated data export files for data portability requests (GDPR Article 20)
                        --              and user-initiated data downloads. Tracks file metadata, expiration, and downloads.
                        -- Business Case: GDPR Article 20 grants users the right to receive their personal data in a
                        --                structured, commonly used, machine-readable format. This table manages the
                        --                generated export files, including metadata for compliance and user access.
                        --                Files are stored securely with expiration dates to limit exposure. Download
                        --                tracking provides auditability and helps identify suspicious access patterns.
                        --                Multiple format support (JSON, CSV, XML) accommodates different use cases.
                        --
                        -- Key Performance Indicators (KPIs):
                        --   1. Export request volume - Number of data export requests per month
                        --   2. Average file size - Typical size of exported user data
                        --   3. Download completion rate - Percentage of exports downloaded by users
                        --   4. Generation time - Average time to generate export files
                        --   5. Format popularity - Distribution of requested export formats
                        --
                        -- Feature References:
                        --   - GDPR17 (Data Portability)
                        --   - GDPR18 (Export Management)
                        --   - AUD14 (Export Audit)
                        --   - DPP02 (Data Portability)
                        --================================================================================================
                        CREATE TABLE IF NOT EXISTS socialcandor_schema.user_export_files (
  -- Primary key
  export_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

  -- Human-readable identifier
  export_number VARCHAR(50) GENERATED ALWAYS AS (
      'EXP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_export_files_seq')::TEXT, 6, '0')
  ) STORED,

  -- References
  user_id UUID NOT NULL,
  request_id UUID,          -- Link to data_subject_requests

  -- File metadata
  file_name VARCHAR(255) NOT NULL,
  file_path VARCHAR(500) NOT NULL,
  file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
  file_hash VARCHAR(64),     -- SHA-256 for integrity

  -- Format
  format VARCHAR(20) NOT NULL CHECK (format IN ('JSON', 'CSV', 'XML', 'PARQUET')),
  compression VARCHAR(20) CHECK (compression IN ('NONE', 'GZIP', 'ZIP')),

  -- Content summary
  data_categories TEXT[] NOT NULL,                     -- What data is included
  record_counts JSONB,       -- Counts by category
  date_range_start DATE,
  date_range_end DATE,

  -- Expiration
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,        -- Auto-delete after retention
  deleted_at TIMESTAMP WITH TIME ZONE,

  -- Download tracking
  download_count INTEGER DEFAULT 0 CHECK (download_count >= 0),
  last_downloaded_at TIMESTAMP WITH TIME ZONE,
  download_history JSONB DEFAULT '[]',                  -- Limited recent downloads

  -- Status
  status VARCHAR(30) DEFAULT 'PENDING' CHECK (status IN (
      'PENDING', 'GENERATING', 'AVAILABLE', 'EXPIRED', 'DELETED', 'FAILED'
  )),
  generation_log TEXT,

  -- Security
  access_token_hash VARCHAR(255),                        -- For one-time access links
  encryption_key_id UUID,      -- If file is encrypted

  -- Audit columns
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  created_by UUID NOT NULL,
  updated_by UUID DEFAULT uuid_nil(),

  -- Constraints
  CONSTRAINT fk_export_files_user FOREIGN KEY (user_id)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
  CONSTRAINT fk_export_files_request FOREIGN KEY (request_id)
      REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
  CONSTRAINT fk_export_files_encryption_key FOREIGN KEY (encryption_key_id)
      REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
  CONSTRAINT fk_export_files_created_by FOREIGN KEY (created_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_export_files_updated_by FOREIGN KEY (updated_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

  CONSTRAINT chk_export_files_expiry CHECK (expires_at > created_at),
  CONSTRAINT chk_export_files_dates CHECK (
      (date_range_start IS NULL AND date_range_end IS NULL) OR
      (date_range_end >= date_range_start)
  )
                        );

                        -- Comments
                        COMMENT ON TABLE socialcandor_schema.user_export_files IS 'Generated data export files for GDPR data portability requests';
                        COMMENT ON COLUMN socialcandor_schema.user_export_files.data_categories IS 'Array of data categories included in the export (profile, posts, messages, etc.)';
                        COMMENT ON COLUMN socialcandor_schema.user_export_files.record_counts IS 'JSON object with counts per data category';
                        COMMENT ON COLUMN socialcandor_schema.user_export_files.download_history IS 'JSON array of recent download events with IP and timestamp';

                        -- Indexes for performance
                        CREATE INDEX idx_export_files_user ON socialcandor_schema.user_export_files(user_id, created_at DESC);
                        CREATE INDEX idx_export_files_status ON socialcandor_schema.user_export_files(status, expires_at);
                        CREATE INDEX idx_export_files_request ON socialcandor_schema.user_export_files(request_id) WHERE request_id IS NOT NULL;
                        CREATE INDEX idx_export_files_expires ON socialcandor_schema.user_export_files(expires_at) WHERE status = 'AVAILABLE';

                        -- Trigger for updated_at
                        CREATE TRIGGER trg_user_export_files_updated_at
  BEFORE UPDATE ON socialcandor_schema.user_export_files
  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                        -- Function to clean expired export files
                        CREATE OR REPLACE FUNCTION socialcandor_schema.clean_expired_exports()
                        RETURNS INTEGER AS $$
                        DECLARE
  v_deleted INTEGER;
                        BEGIN
  UPDATE socialcandor_schema.user_export_files
  SET status = 'EXPIRED',
      deleted_at = CURRENT_TIMESTAMP
  WHERE expires_at < CURRENT_TIMESTAMP
    AND status = 'AVAILABLE'
  RETURNING COUNT(*) INTO v_deleted;

  RETURN v_deleted;
                        END;
                        $$ LANGUAGE plpgsql SECURITY DEFINER;


                        --================================================================================================
                        -- Table: SC08 - encryption_keys
                        -- Description: Centralized management of encryption keys with lifecycle states, versioning,
                        --              and audit trail. Supports envelope encryption and key rotation.
                        -- Business Case: Enterprise security requires centralized key management for data-at-rest
                        --                encryption, TLS certificates, and API signing. This table tracks the entire
                        --                key lifecycle: generation, activation, rotation, and destruction. Keys are
                        --                stored wrapped (encrypted with a master key) for additional security.
                        --                Versioning enables key rotation without data re-encryption. The design
                        --                supports multiple key purposes and algorithms, with expiration dates for
                        --                compliance with cryptographic standards (e.g., keys must be rotated annually).
                        --
                        -- Key Performance Indicators (KPIs):
                        --   1. Key age - Average age of active encryption keys
                        --   2. Rotation compliance - Percentage of keys rotated within policy timeframe
                        --   3. Key usage - Number of encryption operations per key
                        --   4. Key inventory - Total active keys by purpose
                        --   5. Compromise incidents - Keys marked as compromised
                        --
                        -- Feature References:
                        --   - SEC37 (Key Management)
                        --   - SEC38 (Envelope Encryption)
                        --   - SEC39 (Key Rotation)
                        --   - COMP18 (Cryptographic Compliance)
                        --================================================================================================
                        CREATE TABLE IF NOT EXISTS socialcandor_schema.encryption_keys (
  -- Primary key
  key_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

  -- Human-readable identifier
  key_number VARCHAR(50) GENERATED ALWAYS AS (
      'KEY-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.encryption_keys_seq')::TEXT, 6, '0')
  ) STORED,

  -- Key identification
  key_name VARCHAR(255) NOT NULL,
  key_alias VARCHAR(100) UNIQUE,
  key_version INTEGER NOT NULL DEFAULT 1,

  -- Key metadata
  key_purpose socialcandor_schema.encryption_key_purpose NOT NULL,
  key_algorithm VARCHAR(50) CHECK (key_algorithm IN (
      'AES-128-GCM', 'AES-256-GCM', 'RSA-2048', 'RSA-3072', 'RSA-4096', 'ECDSA-P256'
  )),
  key_size INTEGER CHECK (key_size IN (128, 192, 256, 2048, 3072, 4096)),

  -- Key material (wrapped)
  wrapped_key BYTEA NOT NULL, -- Encrypted with master key
  public_key BYTEA,           -- For asymmetric keys
  key_checksum VARCHAR(64),    -- For integrity verification

  -- Lifecycle
  key_state VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK (key_state IN (
      'PENDING', 'ACTIVE', 'DEACTIVATED', 'COMPROMISED', 'DESTROYED'
  )),
  activated_at TIMESTAMP WITH TIME ZONE,
  deactivated_at TIMESTAMP WITH TIME ZONE,
  expires_at TIMESTAMP WITH TIME ZONE,

  -- Rotation
  predecessor_key_id UUID,    -- Previous version
  successor_key_id UUID,      -- Next version
  rotation_schedule_days INTEGER CHECK (rotation_schedule_days >= 0),
  last_rotated_at TIMESTAMP WITH TIME ZONE,

  -- Usage tracking
  usage_count BIGINT DEFAULT 0,
  last_used_at TIMESTAMP WITH TIME ZONE,

  -- Ownership
  owner_team VARCHAR(100),
  owner_user_id UUID,

  -- Compliance
  compliance_standard VARCHAR(100),                      -- FIPS, PCI, etc.
  audit_notes TEXT,

  -- Audit columns
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  created_by UUID NOT NULL,
  updated_by UUID DEFAULT uuid_nil(),

  -- Constraints
  CONSTRAINT fk_encryption_keys_predecessor FOREIGN KEY (predecessor_key_id)
      REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
  CONSTRAINT fk_encryption_keys_successor FOREIGN KEY (successor_key_id)
      REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
  CONSTRAINT fk_encryption_keys_owner_user FOREIGN KEY (owner_user_id)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
  CONSTRAINT fk_encryption_keys_created_by FOREIGN KEY (created_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_encryption_keys_updated_by FOREIGN KEY (updated_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

  CONSTRAINT chk_encryption_keys_dates CHECK (
      (activated_at IS NULL OR activated_at >= created_at) AND
      (deactivated_at IS NULL OR deactivated_at >= activated_at) AND
      (expires_at IS NULL OR expires_at >= activated_at)
  )
                        );

                        -- Comments
                        COMMENT ON TABLE socialcandor_schema.encryption_keys IS 'Centralized management of encryption keys with lifecycle tracking and versioning';
                        COMMENT ON COLUMN socialcandor_schema.encryption_keys.wrapped_key IS 'Key material encrypted with a master key (never store plaintext keys)';
                        COMMENT ON COLUMN socialcandor_schema.encryption_keys.key_state IS 'Current state in the key lifecycle (pending, active, compromised, destroyed)';

                        -- Indexes for performance
                        CREATE INDEX idx_encryption_keys_name ON socialcandor_schema.encryption_keys(key_name, key_version);
                        CREATE INDEX idx_encryption_keys_alias ON socialcandor_schema.encryption_keys(key_alias);
                        CREATE INDEX idx_encryption_keys_state ON socialcandor_schema.encryption_keys(key_state, expires_at) WHERE key_state = 'ACTIVE';
                        CREATE INDEX idx_encryption_keys_purpose ON socialcandor_schema.encryption_keys(key_purpose) WHERE key_state = 'ACTIVE';

                        -- Trigger for updated_at
                        CREATE TRIGGER trg_encryption_keys_updated_at
  BEFORE UPDATE ON socialcandor_schema.encryption_keys
  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                        -- Function to check for expiring keys
                        CREATE OR REPLACE FUNCTION socialcandor_schema.check_expiring_keys()
                        RETURNS TRIGGER AS $$
                        BEGIN
  IF NEW.expires_at IS NOT NULL AND
     NEW.expires_at <= CURRENT_TIMESTAMP + INTERVAL '30 days' AND
     NEW.key_state = 'ACTIVE' THEN
      -- Log security event
      INSERT INTO socialcandor_schema.user_security_events (
          event_type, description, details, created_by
      ) VALUES (
          'KEY_EXPIRING',
          'Encryption key expiring soon: ' || NEW.key_name,
          jsonb_build_object('key_id', NEW.key_id, 'expires_at', NEW.expires_at),
          (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
      );
  END IF;

  RETURN NEW;
                        END;
                        $$ LANGUAGE plpgsql;

                        CREATE TRIGGER trg_encryption_keys_expiry
  AFTER INSERT OR UPDATE ON socialcandor_schema.encryption_keys
  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_expiring_keys();

  --================================================================================================
  -- Table: SC09 - key_rotation_jobs
  -- Description: Tracks scheduled and executed key rotation tasks, including status,
  --              success/failure metrics, and audit trail for compliance.
  -- Business Case: Automated key rotation is a security best practice and often required
  --                by compliance frameworks (PCI-DSS, SOC2). This table manages the rotation
  --                workflow: scheduling, execution, validation, and rollback if needed.
  --                The design supports different rotation strategies (periodic, on-demand,
  --                emergency) and tracks each step for auditability. Failed rotations can
  --                be automatically retried with configurable backoff. Integration with
  --                monitoring systems ensures timely alerts on rotation failures.
  --
  -- Key Performance Indicators (KPIs):
  --   1. Rotation success rate - Percentage of successful key rotations
  --   2. Average rotation time - Time from start to completion
  --   3. Rotation coverage - Percentage of keys rotated within policy window
  --   4. Failure reasons - Distribution of rotation failure causes
  --   5. Rollback frequency - Number of rotations requiring rollback
  --
  -- Feature References:
  --   - SEC40 (Key Rotation)
  --   - SEC41 (Automated Key Management)
  --   - COMP19 (Rotation Compliance)
  --   - AUD15 (Rotation Audit)
  --================================================================================================
  CREATE TABLE IF NOT EXISTS socialcandor_schema.key_rotation_jobs (
      -- Primary key
      job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

      -- Human-readable identifier
      job_number VARCHAR(50) GENERATED ALWAYS AS (
          'ROT-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.key_rotation_jobs_seq')::TEXT, 6, '0')
      ) STORED,

      -- References
      key_id UUID NOT NULL,
      new_key_id UUID,            -- New key created by rotation

      -- Job scheduling
      scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
      started_at TIMESTAMP WITH TIME ZONE,
      completed_at TIMESTAMP WITH TIME ZONE,

      -- Rotation details
      rotation_reason socialcandor_schema.key_rotation_reason NOT NULL,
      rotation_strategy VARCHAR(50) CHECK (rotation_strategy IN (
          'RE_KEY', 'RE_WRAP', 'RE_ENCRYPT', 'PARALLEL', 'BLUE_GREEN'
      )),

      -- Status
      status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
          'PENDING', 'IN_PROGRESS', 'COMPLETED', 'FAILED', 'ROLLED_BACK', 'CANCELLED'
      )),

      -- Execution tracking
      current_step INTEGER DEFAULT 0,
      total_steps INTEGER DEFAULT 1,
      steps_completed JSONB DEFAULT '[]',

      -- Retry logic
      retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),
      max_retries INTEGER DEFAULT 3,
      last_error TEXT,
      last_retry_at TIMESTAMP WITH TIME ZONE,

      -- Validation
      validation_performed BOOLEAN DEFAULT FALSE,
      validation_passed BOOLEAN,
      validation_results JSONB,

      -- Affected resources
      resources_affected INTEGER DEFAULT 0,
      resources_failed INTEGER DEFAULT 0,

      -- Rollback
      rollback_performed BOOLEAN DEFAULT FALSE,
      rollback_at TIMESTAMP WITH TIME ZONE,
      rollback_reason TEXT,

      -- Audit columns
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      created_by UUID NOT NULL,
      updated_by UUID DEFAULT uuid_nil(),

      -- Constraints
      CONSTRAINT fk_key_rotation_jobs_key FOREIGN KEY (key_id)
          REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE CASCADE,
      CONSTRAINT fk_key_rotation_jobs_new_key FOREIGN KEY (new_key_id)
          REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
      CONSTRAINT fk_key_rotation_jobs_created_by FOREIGN KEY (created_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
      CONSTRAINT fk_key_rotation_jobs_updated_by FOREIGN KEY (updated_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
  );

  -- Comments
  COMMENT ON TABLE socialcandor_schema.key_rotation_jobs IS 'Tracks scheduled and executed key rotation tasks with audit trail';
  COMMENT ON COLUMN socialcandor_schema.key_rotation_jobs.rotation_strategy IS 'Strategy used for rotation (re-key, re-wrap, re-encrypt, parallel, blue-green)';
  COMMENT ON COLUMN socialcandor_schema.key_rotation_jobs.steps_completed IS 'JSON array tracking progress through rotation steps';

  -- Indexes for performance
  CREATE INDEX idx_key_rotation_jobs_key ON socialcandor_schema.key_rotation_jobs(key_id, scheduled_at DESC);
  CREATE INDEX idx_key_rotation_jobs_status ON socialcandor_schema.key_rotation_jobs(status, scheduled_at);
  CREATE INDEX idx_key_rotation_jobs_scheduled ON socialcandor_schema.key_rotation_jobs(scheduled_at) WHERE status = 'PENDING';

  -- Trigger for updated_at
  CREATE TRIGGER trg_key_rotation_jobs_updated_at
      BEFORE UPDATE ON socialcandor_schema.key_rotation_jobs
      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

  -- Function to process pending key rotations
  CREATE OR REPLACE FUNCTION socialcandor_schema.process_key_rotations()
  RETURNS INTEGER AS $$
  DECLARE
      v_job RECORD;
      v_processed INTEGER := 0;
  BEGIN
      FOR v_job IN
          SELECT * FROM socialcandor_schema.key_rotation_jobs
          WHERE status = 'PENDING'
            AND scheduled_at <= CURRENT_TIMESTAMP
          ORDER BY scheduled_at
          LIMIT 5
          FOR UPDATE SKIP LOCKED
      LOOP
          BEGIN
              UPDATE socialcandor_schema.key_rotation_jobs
              SET status = 'IN_PROGRESS',
                  started_at = CURRENT_TIMESTAMP
              WHERE job_id = v_job.job_id;

              -- Actual rotation logic would be here
              -- This is a placeholder for the complex key rotation process

              UPDATE socialcandor_schema.key_rotation_jobs
              SET status = 'COMPLETED',
                  completed_at = CURRENT_TIMESTAMP,
                  validation_performed = TRUE,
                  validation_passed = TRUE
              WHERE job_id = v_job.job_id;

              v_processed := v_processed + 1;
          EXCEPTION WHEN OTHERS THEN
              UPDATE socialcandor_schema.key_rotation_jobs
              SET status = 'FAILED',
                  last_error = SQLERRM,
                  retry_count = retry_count + 1,
                  last_retry_at = CURRENT_TIMESTAMP
              WHERE job_id = v_job.job_id;
          END;
      END LOOP;

      RETURN v_processed;
  END;
  $$ LANGUAGE plpgsql SECURITY DEFINER;


  --================================================================================================
  -- Table: SC10 - data_encryption_config
  -- Description: Defines which columns/tables are encrypted, with which keys, and which
  --              encryption algorithms to use. Enables dynamic encryption configuration.
  -- Business Case: Different data types require different encryption strategies: PII needs
  --                strong encryption, while less sensitive data may use lighter methods.
  --                This configuration table allows security teams to define encryption
  --                policies without code changes, supporting compliance requirements like
  --                GDPR (pseudonymization) and PCI-DSS (cardholder data encryption). The
  --                design supports multiple encryption keys for different data categories,
  --                enabling key rotation without service interruption. Versioning tracks
  --                configuration changes for audit purposes.
  --
  -- Key Performance Indicators (KPIs):
  --   1. Encryption coverage - Percentage of sensitive columns encrypted
  --   2. Configuration change frequency - Updates to encryption policies
  --   3. Key distribution - Number of keys used across configurations
  --   4. Algorithm adoption - Usage distribution of encryption algorithms
  --   5. Compliance coverage - Percentage of required data encrypted per regulations
  --
  -- Feature References:
  --   - SEC42 (Data Encryption)
  --   - SEC43 (Column-level Encryption)
  --   - GDPR19 (Pseudonymization)
  --   - COMP20 (Encryption Compliance)
  --================================================================================================
  CREATE TABLE IF NOT EXISTS socialcandor_schema.data_encryption_config (
      -- Primary key
      config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

      -- Human-readable identifier
      config_number VARCHAR(50) GENERATED ALWAYS AS (
          'ENC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_encryption_config_seq')::TEXT, 6, '0')
      ) STORED,

      -- Target data
      schema_name VARCHAR(100) NOT NULL,
      table_name VARCHAR(100) NOT NULL,
      column_name VARCHAR(100) NOT NULL,

      -- Encryption configuration
      encryption_key_id UUID NOT NULL,
      encryption_algorithm VARCHAR(50) NOT NULL CHECK (encryption_algorithm IN (
          'AES-256-GCM', 'AES-256-CBC', 'AES-128-GCM', 'CHACHA20-POLY1305'
      )),

      -- Additional options
      initialization_vector_required BOOLEAN DEFAULT TRUE,
      authenticated_encryption BOOLEAN DEFAULT TRUE,
      key_derivation_function VARCHAR(50) CHECK (key_derivation_function IN ('PBKDF2', 'ARGON2', 'NONE')),

      -- Data classification
      data_classification VARCHAR(50) CHECK (data_classification IN (
          'PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED', 'SECRET'
      )),
      contains_pii BOOLEAN DEFAULT FALSE,
      contains_phi BOOLEAN DEFAULT FALSE,                   -- Protected Health Information
      contains_pci BOOLEAN DEFAULT FALSE,                    -- Payment Card Industry data

      -- Retention
      retention_period_days INTEGER,

      -- Version control
      config_version INTEGER NOT NULL DEFAULT 1,
      is_active BOOLEAN DEFAULT TRUE,
      superseded_by UUID,

      -- Audit columns
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      created_by UUID NOT NULL,
      updated_by UUID DEFAULT uuid_nil(),

      -- Constraints
      CONSTRAINT fk_encryption_config_key FOREIGN KEY (encryption_key_id)
          REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE RESTRICT,
      CONSTRAINT fk_encryption_config_superseded_by FOREIGN KEY (superseded_by)
          REFERENCES socialcandor_schema.data_encryption_config(config_id) ON DELETE SET NULL,
      CONSTRAINT fk_encryption_config_created_by FOREIGN KEY (created_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
      CONSTRAINT fk_encryption_config_updated_by FOREIGN KEY (updated_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

      CONSTRAINT uk_encryption_config UNIQUE (schema_name, table_name, column_name)
  );

  -- Comments
  COMMENT ON TABLE socialcandor_schema.data_encryption_config IS 'Configuration for column-level data encryption, defining which keys and algorithms to use';
  COMMENT ON COLUMN socialcandor_schema.data_encryption_config.data_classification IS 'Data sensitivity classification for determining encryption requirements';
  COMMENT ON COLUMN socialcandor_schema.data_encryption_config.initialization_vector_required IS 'Whether an initialization vector is required for this encryption scheme';

  -- Indexes for performance
  CREATE INDEX idx_encryption_config_target ON socialcandor_schema.data_encryption_config(schema_name, table_name, column_name);
  CREATE INDEX idx_encryption_config_key ON socialcandor_schema.data_encryption_config(encryption_key_id);
  CREATE INDEX idx_encryption_config_active ON socialcandor_schema.data_encryption_config(is_active) WHERE is_active = TRUE;
  CREATE INDEX idx_encryption_config_classification ON socialcandor_schema.data_encryption_config(data_classification) WHERE data_classification IN ('CONFIDENTIAL', 'RESTRICTED', 'SECRET');

  -- Trigger for updated_at
  CREATE TRIGGER trg_data_encryption_config_updated_at
      BEFORE UPDATE ON socialcandor_schema.data_encryption_config
      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


      --================================================================================================
      -- Table: SC11 - vulnerability_scans
      -- Description: Stores results of automated vulnerability scans, including findings by
      --              severity, remediation status, and compliance with security standards.
      -- Business Case: Regular vulnerability scanning is required for SOC2, ISO27001, and other
      --                compliance frameworks. This table centralizes scan results, enabling
      --                tracking of vulnerabilities over time, prioritization of remediation,
      --                and generation of compliance reports. The design supports multiple scan
      --                types (SAST, DAST, container, cloud) and integrates with ticketing
      --                systems for remediation workflows. Historical data helps identify trends
      --                and recurring issues, supporting continuous security improvement.
      --
      -- Key Performance Indicators (KPIs):
      --   1. Vulnerability density - Number of findings per scan
      --   2. Mean time to remediate - Average time from detection to fix
      --   3. Critical vulnerability count - Open critical/high findings
      --   4. Scan coverage - Percentage of assets scanned
      --   5. Remediation rate - Percentage of findings resolved within SLA
      --
      -- Feature References:
      --   - SEC44 (Vulnerability Management)
      --   - SEC45 (Security Scanning)
      --   - COMP21 (Compliance Scanning)
      --   - RISK02 (Security Risk)
      --================================================================================================
      CREATE TABLE IF NOT EXISTS socialcandor_schema.vulnerability_scans (
          -- Primary key
          scan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

          -- Human-readable identifier
          scan_number VARCHAR(50) GENERATED ALWAYS AS (
              'VULN-' || TO_CHAR(scan_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.vulnerability_scans_seq')::TEXT, 6, '0')
          ) STORED,

          -- Scan metadata
          scan_name VARCHAR(255) NOT NULL,
          scan_type VARCHAR(50) CHECK (scan_type IN (
              'SAST', 'DAST', 'CONTAINER', 'CLOUD', 'NETWORK', 'DEPENDENCY', 'SECRETS'
          )),
          scanner_name VARCHAR(100) NOT NULL,
          scanner_version VARCHAR(50),

          -- Scope
          asset_type VARCHAR(50) CHECK (asset_type IN (
              'APPLICATION', 'SERVICE', 'CONTAINER', 'HOST', 'REPOSITORY', 'CLOUD_ACCOUNT'
          )),
          asset_name VARCHAR(255),
          asset_version VARCHAR(50),

          -- Dates
          scan_date DATE NOT NULL,
          scan_start TIMESTAMP WITH TIME ZONE,
          scan_end TIMESTAMP WITH TIME ZONE,

          -- Summary statistics
          total_findings INTEGER DEFAULT 0,
          critical_count INTEGER DEFAULT 0,
          high_count INTEGER DEFAULT 0,
          medium_count INTEGER DEFAULT 0,
          low_count INTEGER DEFAULT 0,
          info_count INTEGER DEFAULT 0,

          -- Findings (stored separately for large scans, but summary JSON included)
          findings_summary JSONB,
          findings_url VARCHAR(500),  -- Link to detailed report

          -- Compliance
          compliance_standards TEXT[],                          -- e.g., {'PCI', 'HIPAA', 'GDPR'}
          compliance_status VARCHAR(50),

          -- Remediation tracking
          remediation_deadline DATE,
          remediation_status VARCHAR(50) CHECK (remediation_status IN (
              'NOT_STARTED', 'IN_PROGRESS', 'COMPLETED', 'ACCEPTED_RISK', 'FALSE_POSITIVE'
          )),
          remediation_notes TEXT,

          -- False positive analysis
          false_positive_count INTEGER DEFAULT 0,
          false_positive_details JSONB,

          -- Audit columns
          created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
          created_by UUID NOT NULL,
          updated_by UUID DEFAULT uuid_nil(),

          -- Constraints
          CONSTRAINT fk_vulnerability_scans_created_by FOREIGN KEY (created_by)
              REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
          CONSTRAINT fk_vulnerability_scans_updated_by FOREIGN KEY (updated_by)
              REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

          CONSTRAINT chk_vulnerability_scans_dates CHECK (scan_end IS NULL OR scan_end >= scan_start)
      );

      -- Comments
      COMMENT ON TABLE socialcandor_schema.vulnerability_scans IS 'Results of automated vulnerability scans with findings by severity';
      COMMENT ON COLUMN socialcandor_schema.vulnerability_scans.findings_summary IS 'JSON summary of findings by category and severity';
      COMMENT ON COLUMN socialcandor_schema.vulnerability_scans.false_positive_details IS 'Details of false positive findings for tuning';

      -- Indexes for performance
      CREATE INDEX idx_vulnerability_scans_date ON socialcandor_schema.vulnerability_scans(scan_date DESC);
      CREATE INDEX idx_vulnerability_scans_asset ON socialcandor_schema.vulnerability_scans(asset_type, asset_name);
      CREATE INDEX idx_vulnerability_scans_status ON socialcandor_schema.vulnerability_scans(remediation_status, remediation_deadline);
      CREATE INDEX idx_vulnerability_scans_type ON socialcandor_schema.vulnerability_scans(scan_type, scan_date DESC);

      -- Trigger for updated_at
      CREATE TRIGGER trg_vulnerability_scans_updated_at
          BEFORE UPDATE ON socialcandor_schema.vulnerability_scans
          FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



          --================================================================================================
          -- Table: SC12 - security_training_records
          -- Description: Tracks employee completion of security awareness training, including
          --              module completion, scores, and expiration for compliance reporting.
          -- Business Case: Security training is a cornerstone of human risk management and is
          --                required by frameworks like SOC2, ISO27001, and GDPR. This table
          --                tracks who has completed which training modules, when they expire,
          --                and whether they passed. The design supports different training
          --                frequencies (annual, quarterly) and mandatory vs. optional modules.
          --                Expiration tracking ensures timely retraining, and reporting
          --                capabilities support compliance audits and board-level reporting.
          --
          -- Key Performance Indicators (KPIs):
          --   1. Training completion rate - Percentage of employees up-to-date on training
          --   2. Average score - Mean assessment score across modules
          --   3. Expiration rate - Percentage of training expiring in next 30 days
          --   4. Module popularity - Most/least completed training modules
          --   5. Time to completion - Average days from assignment to completion
          --
          -- Feature References:
          --   - SEC46 (Security Awareness)
          --   - SEC47 (Training Management)
          --   - COMP22 (Training Compliance)
          --   - HR01 (Employee Management)
          --================================================================================================
          CREATE TABLE IF NOT EXISTS socialcandor_schema.security_training_records (
              -- Primary key
              record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

              -- Human-readable identifier
              record_number VARCHAR(50) GENERATED ALWAYS AS (
                  'TRAIN-' || TO_CHAR(assigned_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.security_training_records_seq')::TEXT, 6, '0')
              ) STORED,

              -- References
              user_id UUID NOT NULL,

              -- Training details
              training_module VARCHAR(255) NOT NULL,
              training_version VARCHAR(50),
              training_type VARCHAR(50) CHECK (training_type IN (
                  'INITIAL', 'ANNUAL', 'QUARTERLY', 'REMEDIAL', 'OPTIONAL'
              )),

              -- Assignment
              assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              assigned_by UUID,
              due_date DATE NOT NULL,

              -- Completion
              completed_at TIMESTAMP WITH TIME ZONE,
              completion_status socialcandor_schema.training_completion_status NOT NULL DEFAULT 'NOT_STARTED',

              -- Assessment
              score INTEGER CHECK (score >= 0 AND score <= 100),
              passed BOOLEAN,
              attempts INTEGER DEFAULT 1 CHECK (attempts >= 0),

              -- Content
              training_content_url VARCHAR(500),
              assessment_url VARCHAR(500),

              -- Expiration
              expires_at DATE,
              renewal_reminder_sent BOOLEAN DEFAULT FALSE,

              -- Evidence
              certificate_url VARCHAR(500),
              completion_evidence JSONB,

              -- Audit columns
              created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              created_by UUID NOT NULL,
              updated_by UUID DEFAULT uuid_nil(),

              -- Constraints
              CONSTRAINT fk_security_training_user FOREIGN KEY (user_id)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
              CONSTRAINT fk_security_training_assigned_by FOREIGN KEY (assigned_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
              CONSTRAINT fk_security_training_created_by FOREIGN KEY (created_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
              CONSTRAINT fk_security_training_updated_by FOREIGN KEY (updated_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

              CONSTRAINT chk_security_training_dates CHECK (
                  completed_at IS NULL OR completed_at >= assigned_at
              ),
              CONSTRAINT chk_security_training_expiry CHECK (
                  expires_at IS NULL OR expires_at >= due_date
              )
          );

          -- Comments
          COMMENT ON TABLE socialcandor_schema.security_training_records IS 'Tracks employee completion of security awareness training for compliance';
          COMMENT ON COLUMN socialcandor_schema.security_training_records.completion_evidence IS 'JSON evidence of completion (screenshots, logs, etc.)';
          COMMENT ON COLUMN socialcandor_schema.security_training_records.renewal_reminder_sent IS 'Whether reminder has been sent for expiring training';

          -- Indexes for performance
          CREATE INDEX idx_security_training_user ON socialcandor_schema.security_training_records(user_id, assigned_at DESC);
          CREATE INDEX idx_security_training_status ON socialcandor_schema.security_training_records(completion_status, due_date);
          CREATE INDEX idx_security_training_expires ON socialcandor_schema.security_training_records(expires_at) WHERE expires_at IS NOT NULL;
          CREATE INDEX idx_security_training_module ON socialcandor_schema.security_training_records(training_module, training_version);

          -- Trigger for updated_at
          CREATE TRIGGER trg_security_training_records_updated_at
              BEFORE UPDATE ON socialcandor_schema.security_training_records
              FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

          -- Function to send renewal reminders
          CREATE OR REPLACE FUNCTION socialcandor_schema.check_training_expirations()
          RETURNS INTEGER AS $$
          DECLARE
              v_count INTEGER := 0;
          BEGIN
              -- Mark records that need renewal reminders
              UPDATE socialcandor_schema.security_training_records
              SET renewal_reminder_sent = TRUE
              WHERE expires_at <= CURRENT_DATE + INTERVAL '30 days'
                AND expires_at > CURRENT_DATE
                AND renewal_reminder_sent = FALSE
                AND completion_status = 'COMPLETED'
              RETURNING COUNT(*) INTO v_count;

              RETURN v_count;
          END;
          $$ LANGUAGE plpgsql SECURITY DEFINER;



          --================================================================================================
          -- Table: EI01 - webhook_endpoints
          -- Description: Stores registered webhook endpoints for external systems, including
          --              configuration, secrets for signing, and event subscriptions.
          -- Business Case: Event-driven architecture requires reliable webhook delivery to
          --                partner systems. This table manages endpoint registration, including
          --                URL, secret for HMAC signing, and the specific events each endpoint
          --                subscribes to. The design supports per-endpoint retry policies,
          --                rate limiting, and circuit breakers to prevent flooding. Versioning
          --                enables gradual migration as APIs evolve. Audit fields track changes
          --                for compliance and troubleshooting.
          --
          -- Key Performance Indicators (KPIs):
          --   1. Endpoint count - Number of registered webhook endpoints
          --   2. Event subscription density - Average events per endpoint
          --   3. Endpoint churn - Rate of endpoint creation/deletion
          --   4. Configuration change frequency - Updates to endpoint settings
          --   5. Secret rotation compliance - Percentage of endpoints with recent secret rotation
          --
          -- Feature References:
          --   - INT07 (Webhook Management)
          --   - INT08 (Event Subscriptions)
          --   - INT09 (Webhook Security)
          --   - API09 (Integration API)
          --================================================================================================
          CREATE TABLE IF NOT EXISTS socialcandor_schema.webhook_endpoints (
              -- Primary key
              endpoint_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

              -- Human-readable identifier
              endpoint_number VARCHAR(50) GENERATED ALWAYS AS (
                  'WH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.webhook_endpoints_seq')::TEXT, 6, '0')
              ) STORED,

              -- Ownership
              owner_user_id UUID,
              owner_organization_id UUID,

              -- Endpoint details
              name VARCHAR(255) NOT NULL,
              description TEXT,
              url VARCHAR(500) NOT NULL,

              -- Security
              secret VARCHAR(255),        -- HMAC signing secret
              secret_rotation_at TIMESTAMP WITH TIME ZONE,
              signature_header VARCHAR(100) DEFAULT 'X-Signature',

              -- Event subscription
              subscribed_events socialcandor_schema.webhook_event_type[] NOT NULL DEFAULT '{}',
              event_filters JSONB DEFAULT '{}',                     -- Filtering criteria per event

              -- Delivery configuration
              format VARCHAR(20) DEFAULT 'JSON' CHECK (format IN ('JSON', 'XML', 'FORM_URLENCODED')),
              max_retries INTEGER DEFAULT 3 CHECK (max_retries >= 0 AND max_retries <= 10),
              retry_delay_seconds INTEGER DEFAULT 60 CHECK (retry_delay_seconds >= 0),
              timeout_seconds INTEGER DEFAULT 10 CHECK (timeout_seconds >= 5 AND timeout_seconds <= 60),

              -- Rate limiting
              rate_limit_per_minute INTEGER,
              rate_limit_per_hour INTEGER,

              -- Circuit breaker
              consecutive_failures INTEGER DEFAULT 0,
              circuit_breaker_trip_at TIMESTAMP WITH TIME ZONE,

              -- Status
              is_active BOOLEAN DEFAULT TRUE,
              is_verified BOOLEAN DEFAULT FALSE,                    -- Challenge-response verified
              verified_at TIMESTAMP WITH TIME ZONE,

              -- Versioning
              version INTEGER DEFAULT 1,
              deprecated_at TIMESTAMP WITH TIME ZONE,

              -- Audit columns
              created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              created_by UUID NOT NULL,
              updated_by UUID DEFAULT uuid_nil(),

              -- Constraints
              CONSTRAINT fk_webhook_endpoints_owner_user FOREIGN KEY (owner_user_id)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
              CONSTRAINT fk_webhook_endpoints_owner_org FOREIGN KEY (owner_organization_id)
                  REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
              CONSTRAINT fk_webhook_endpoints_created_by FOREIGN KEY (created_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
              CONSTRAINT fk_webhook_endpoints_updated_by FOREIGN KEY (updated_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

              CONSTRAINT chk_webhook_endpoints_owner CHECK (
                  owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL
              )
          );

          -- Comments
          COMMENT ON TABLE socialcandor_schema.webhook_endpoints IS 'Registered webhook endpoints for external systems with event subscriptions';
          COMMENT ON COLUMN socialcandor_schema.webhook_endpoints.secret IS 'HMAC signing secret for webhook payload verification (store securely)';
          COMMENT ON COLUMN socialcandor_schema.webhook_endpoints.event_filters IS 'JSON filters for event-specific criteria (e.g., only notify on high-value transactions)';
          COMMENT ON COLUMN socialcandor_schema.webhook_endpoints.circuit_breaker_trip_at IS 'When the circuit breaker tripped due to consecutive failures';

          -- Indexes for performance
          CREATE INDEX idx_webhook_endpoints_owner ON socialcandor_schema.webhook_endpoints(owner_user_id, owner_organization_id);
          CREATE INDEX idx_webhook_endpoints_active ON socialcandor_schema.webhook_endpoints(is_active, url) WHERE is_active = TRUE;
          CREATE INDEX idx_webhook_endpoints_events ON socialcandor_schema.webhook_endpoints USING GIN (subscribed_events);

          -- Trigger for updated_at
          CREATE TRIGGER trg_webhook_endpoints_updated_at
              BEFORE UPDATE ON socialcandor_schema.webhook_endpoints
              FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



              --================================================================================================
              -- Table: EI02 - webhook_delivery_logs
              -- Description: Comprehensive logging of webhook delivery attempts, including request/response
              --              payloads, status codes, and retry tracking for debugging and reliability.
              -- Business Case: Reliable webhook delivery requires visibility into every attempt:
              --                successes, failures, and retries. This table captures complete telemetry
              --                for each delivery, enabling troubleshooting, SLA monitoring, and
              --                performance analysis. The design supports payload storage (with
              --                truncation for large payloads) and response inspection. Partitioning
              --                by month ensures query performance for historical analysis while
              --                enabling efficient data retention policies.
              --
              -- Key Performance Indicators (KPIs):
              --   1. Delivery success rate - Percentage of successful deliveries
              --   2. Average latency - Time from event to successful delivery
              --   3. Retry rate - Percentage of deliveries requiring retries
              --   4. Failure distribution - Breakdown of failure reasons (timeout, 4xx, 5xx)
              --   5. Endpoint reliability - Per-endpoint uptime/latency metrics
              --
              -- Feature References:
              --   - INT10 (Webhook Delivery)
              --   - INT11 (Webhook Monitoring)
              --   - OBS05 (Integration Observability)
              --   - SLA03 (Webhook SLAs)
              --================================================================================================
              CREATE TABLE IF NOT EXISTS socialcandor_schema.webhook_delivery_logs (
                  -- Primary key
                  log_id BIGSERIAL,

                  -- Human-readable identifier
                  log_number VARCHAR(50) GENERATED ALWAYS AS (
                      'WHD-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.webhook_delivery_logs_seq')::TEXT, 6, '0')
                  ) STORED,

                  -- References
                  endpoint_id UUID NOT NULL,
                  event_id UUID,              -- Reference to source event

                  -- Event details
                  event_type socialcandor_schema.webhook_event_type NOT NULL,
                  event_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,

                  -- Payload
                  payload JSONB NOT NULL,
                  payload_size_bytes INTEGER CHECK (payload_size_bytes >= 0),
                  payload_hash VARCHAR(64),    -- For integrity verification

                  -- Delivery attempt
                  attempt_number INTEGER NOT NULL DEFAULT 1,
                  attempted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

                  -- Request details
                  request_url VARCHAR(500) NOT NULL,
                  request_headers JSONB,
                  request_method VARCHAR(10) DEFAULT 'POST',

                  -- Response details
                  response_status INTEGER,
                  response_headers JSONB,
                  response_body TEXT,
                  response_time_ms INTEGER CHECK (response_time_ms >= 0),

                  -- Outcome
                  success BOOLEAN NOT NULL,
                  error_type VARCHAR(100) CHECK (error_type IN (
                      'TIMEOUT', 'CONNECTION_ERROR', 'INVALID_RESPONSE', 'CLIENT_ERROR', 'SERVER_ERROR', 'OTHER'
                  )),
                  error_message TEXT,

                  -- Retry info
                  will_retry BOOLEAN DEFAULT FALSE,
                  next_retry_at TIMESTAMP WITH TIME ZONE,

                  -- Partition key
                  delivery_date DATE GENERATED ALWAYS AS (attempted_at::DATE) STORED,

                  -- Constraints
                  CONSTRAINT pk_webhook_delivery_logs PRIMARY KEY (log_id, delivery_date),
                  CONSTRAINT fk_webhook_delivery_logs_endpoint FOREIGN KEY (endpoint_id)
                      REFERENCES socialcandor_schema.webhook_endpoints(endpoint_id) ON DELETE CASCADE
              ) PARTITION BY RANGE (delivery_date);

              -- Comments
              COMMENT ON TABLE socialcandor_schema.webhook_delivery_logs IS 'Comprehensive logging of webhook delivery attempts with request/response details';
              COMMENT ON COLUMN socialcandor_schema.webhook_delivery_logs.payload_hash IS 'SHA-256 hash of payload for integrity verification';
              COMMENT ON COLUMN socialcandor_schema.webhook_delivery_logs.error_type IS 'Categorized error type for analysis and alerting';

              -- Create monthly partitions
              DO $$
              DECLARE
                  start_date DATE;
                  end_date DATE;
                  partition_name TEXT;
              BEGIN
                  FOR i IN 0..11 LOOP
                      start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
                      end_date := start_date + '1 month'::INTERVAL;
                      partition_name := 'webhook_delivery_logs_' || TO_CHAR(start_date, 'YYYY_MM');

                      EXECUTE format('
                          CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.webhook_delivery_logs
                          FOR VALUES FROM (%L) TO (%L)',
                          partition_name, start_date, end_date
                      );
                  END LOOP;
              END $$;

              -- Indexes for performance
              CREATE INDEX idx_webhook_logs_endpoint ON socialcandor_schema.webhook_delivery_logs(endpoint_id, attempted_at DESC);
              CREATE INDEX idx_webhook_logs_event ON socialcandor_schema.webhook_delivery_logs(event_type, attempted_at DESC);
              CREATE INDEX idx_webhook_logs_success ON socialcandor_schema.webhook_delivery_logs(success, attempted_at DESC) WHERE success = FALSE;
              CREATE INDEX idx_webhook_logs_retry ON socialcandor_schema.webhook_delivery_logs(next_retry_at) WHERE will_retry = TRUE;


              --================================================================================================
              -- Table: EI03 - integrations
              -- Description: Stores OAuth tokens and configuration for third-party service integrations,
              --              including refresh token management and connection status.
              -- Business Case: Modern platforms integrate with dozens of external services (CRM,
              --                marketing automation, analytics). This table manages the authentication
              --                credentials and configuration for each integration securely. OAuth
              --                tokens are encrypted at rest, with refresh tokens stored for automatic
              --                renewal. The design supports multiple accounts per user/organization
              --                and tracks token expiration to prevent service disruptions. Integration
              --                health monitoring and automatic re-authentication ensure reliability.
              --
              -- Key Performance Indicators (KPIs):
              --   1. Integration adoption - Number of active integrations per user/org
              --   2. Token refresh rate - Frequency of token renewal operations
              --   3. Integration failure rate - Percentage of integration operations failing
              --   4. Provider distribution - Most/least used integration providers
              --   5. Token age - Average age of active access tokens
              --
              -- Feature References:
              --   - INT12 (Third-party Integrations)
              --   - INT13 (OAuth Management)
              --   - INT14 (Integration Health)
              --   - API10 (Integration API)
              --================================================================================================
              CREATE TABLE IF NOT EXISTS socialcandor_schema.integrations (
                  -- Primary key
                  integration_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                  -- Human-readable identifier
                  integration_number VARCHAR(50) GENERATED ALWAYS AS (
                      'INT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.integrations_seq')::TEXT, 6, '0')
                  ) STORED,

                  -- Ownership
                  owner_user_id UUID,
                  owner_organization_id UUID,

                  -- Integration details
                  integration_type socialcandor_schema.integration_type NOT NULL,
                  provider_name VARCHAR(100) NOT NULL,
                  integration_name VARCHAR(255),
                  description TEXT,

                  -- Authentication
                  auth_type socialcandor_schema.integration_auth_type NOT NULL,
                  client_id VARCHAR(255),      -- For OAuth
                  encrypted_client_secret TEXT,                          -- Encrypted with master key

                  -- Tokens (encrypted)
                  access_token_encrypted TEXT,
                  refresh_token_encrypted TEXT,
                  token_type VARCHAR(50) DEFAULT 'Bearer',
                  expires_at TIMESTAMP WITH TIME ZONE,
                  scopes TEXT[],

                  -- Connection details
instance_url VARCHAR(500),    -- For multi-tenant services
api_version VARCHAR(20),
environment VARCHAR(20) CHECK (environment IN ('PRODUCTION', 'SANDBOX', 'DEVELOPMENT')),

-- Configuration
settings JSONB DEFAULT '{}',  -- Integration-specific config
metadata JSONB DEFAULT '{}',   -- Additional metadata

-- Status
is_active BOOLEAN DEFAULT TRUE,
is_healthy BOOLEAN DEFAULT TRUE,
health_check_at TIMESTAMP WITH TIME ZONE,
health_check_message TEXT,
last_sync_at TIMESTAMP WITH TIME ZONE,

-- Error tracking
consecutive_errors INTEGER DEFAULT 0,
last_error_at TIMESTAMP WITH TIME ZONE,
last_error_message TEXT,

-- Rate limiting
rate_limit_remaining INTEGER,
rate_limit_reset_at TIMESTAMP WITH TIME ZONE,

-- Audit columns
created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
created_by UUID NOT NULL,
updated_by UUID DEFAULT uuid_nil(),

-- Constraints
CONSTRAINT fk_integrations_owner_user FOREIGN KEY (owner_user_id)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
CONSTRAINT fk_integrations_owner_org FOREIGN KEY (owner_organization_id)
    REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
CONSTRAINT fk_integrations_created_by FOREIGN KEY (created_by)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
CONSTRAINT fk_integrations_updated_by FOREIGN KEY (updated_by)
    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

CONSTRAINT chk_integrations_owner CHECK (
    owner_user_id IS NOT NULL OR owner_organization_id IS NOT NULL
),
CONSTRAINT chk_integrations_tokens CHECK (
    (access_token_encrypted IS NOT NULL AND auth_type != 'NONE') OR
    (auth_type = 'NONE')
)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.integrations IS 'Manages OAuth tokens and configuration for third-party service integrations';
COMMENT ON COLUMN socialcandor_schema.integrations.encrypted_client_secret IS 'Client secret encrypted with master key (never store plaintext)';
COMMENT ON COLUMN socialcandor_schema.integrations.access_token_encrypted IS 'OAuth access token encrypted at rest';
COMMENT ON COLUMN socialcandor_schema.integrations.refresh_token_encrypted IS 'OAuth refresh token for automatic token renewal';

-- Indexes for performance
CREATE INDEX idx_integrations_owner ON socialcandor_schema.integrations(owner_user_id, owner_organization_id);
CREATE INDEX idx_integrations_provider ON socialcandor_schema.integrations(provider_name, integration_type);
CREATE INDEX idx_integrations_active ON socialcandor_schema.integrations(is_active, is_healthy) WHERE is_active = TRUE;
CREATE INDEX idx_integrations_expires ON socialcandor_schema.integrations(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_integrations_updated_at
BEFORE UPDATE ON socialcandor_schema.integrations
FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- Function to refresh expired tokens
CREATE OR REPLACE FUNCTION socialcandor_schema.refresh_expired_tokens()
RETURNS INTEGER AS $$
DECLARE
v_count INTEGER := 0;
v_integration RECORD;
BEGIN
FOR v_integration IN
    SELECT * FROM socialcandor_schema.integrations
    WHERE expires_at < CURRENT_TIMESTAMP + INTERVAL '1 hour'
      AND refresh_token_encrypted IS NOT NULL
      AND is_active = TRUE
    LIMIT 10
    FOR UPDATE SKIP LOCKED
LOOP
    -- Actual token refresh logic would be here
    -- This is a placeholder for provider-specific refresh flows

    UPDATE socialcandor_schema.integrations
    SET expires_at = CURRENT_TIMESTAMP + INTERVAL '1 hour',
        updated_at = CURRENT_TIMESTAMP
    WHERE integration_id = v_integration.integration_id;

    v_count := v_count + 1;
END LOOP;

RETURN v_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


--================================================================================================
-- Table: EI04 - api_changelog
-- Description: Documents API version changes, deprecations, and breaking changes for
--              developer communication and migration planning.
-- Business Case: API evolution is inevitable, but breaking changes must be communicated
--                clearly to developers. This table serves as the source of truth for API
--                version history, deprecation notices, and migration guides. The design
--                supports multiple API versions concurrently, with sunset dates to ensure
--                timely migration. Integration with developer portals enables automated
--                notification of affected consumers. Historical data helps analyze API
--                adoption patterns and plan future deprecations.
--
-- Key Performance Indicators (KPIs):
--   1. API version adoption - Usage distribution across API versions
--   2. Deprecation compliance - Percentage of consumers migrated before sunset
--   3. Breaking change frequency - Number of breaking changes per quarter
--   4. Migration time - Average time for consumers to upgrade versions
--   5. Documentation coverage - Percentage of changes documented
--
-- Feature References:
--   - API11 (API Versioning)
--   - API12 (Deprecation Management)
--   - DEV01 (Developer Experience)
--   - DOC01 (API Documentation)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_changelog (
    -- Primary key
    change_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    change_number VARCHAR(50) GENERATED ALWAYS AS (
        'APICHG-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.api_changelog_seq')::TEXT, 6, '0')
    ) STORED,

    -- API identification
    api_name VARCHAR(100) NOT NULL,
    api_version VARCHAR(20) NOT NULL,
    previous_version VARCHAR(20),
    next_version VARCHAR(20),

    -- Change details
    change_type VARCHAR(30) CHECK (change_type IN (
        'ADDITION', 'MODIFICATION', 'DEPRECATION', 'REMOVAL', 'SECURITY_FIX', 'BUG_FIX'
    )),
    change_date DATE NOT NULL,
    change_title VARCHAR(255) NOT NULL,
    change_description TEXT NOT NULL,

    -- Breaking change analysis
    is_breaking_change BOOLEAN DEFAULT FALSE,
    breaking_change_details TEXT,
    migration_impact VARCHAR(50) CHECK (migration_impact IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

    -- Affected endpoints
    endpoints_affected TEXT[],
    parameters_affected TEXT[],
    response_changes JSONB,

    -- Deprecation (if applicable)
    deprecation_date DATE,
    sunset_date DATE,
    sunset_message TEXT,

    -- Migration
    migration_guide_url VARCHAR(500),
    migration_examples JSONB,
    recommended_upgrade_path VARCHAR(50),

    -- Communication
    announced_at TIMESTAMP WITH TIME ZONE,
    announced_to TEXT[],       -- Affected consumers notified
    announcement_channel VARCHAR(50),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deprecated BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_api_changelog_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_api_changelog_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_api_changelog_dates CHECK (
        (deprecation_date IS NULL AND sunset_date IS NULL) OR
        (sunset_date >= deprecation_date)
    ),
    CONSTRAINT chk_api_changelog_versions CHECK (
        previous_version IS NULL OR previous_version < api_version
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_changelog IS 'Documents API version changes, deprecations, and breaking changes for developer communication';
COMMENT ON COLUMN socialcandor_schema.api_changelog.breaking_change_details IS 'Detailed explanation of breaking changes and their impact';
COMMENT ON COLUMN socialcandor_schema.api_changelog.announced_to IS 'Array of affected consumer IDs that have been notified';
COMMENT ON COLUMN socialcandor_schema.api_changelog.migration_examples IS 'JSON examples of before/after code for migration';

-- Indexes for performance
CREATE INDEX idx_api_changelog_api ON socialcandor_schema.api_changelog(api_name, api_version);
CREATE INDEX idx_api_changelog_date ON socialcandor_schema.api_changelog(change_date DESC);
CREATE INDEX idx_api_changelog_breaking ON socialcandor_schema.api_changelog(is_breaking_change, change_date) WHERE is_breaking_change = TRUE;
CREATE INDEX idx_api_changelog_deprecated ON socialcandor_schema.api_changelog(deprecation_date, sunset_date) WHERE is_deprecated = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_api_changelog_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_changelog
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



    --================================================================================================
    -- Table: DR01 - retention_enforcement_jobs
    -- Description: Tracks automated execution of data retention policies, including deletion
    --              of expired data and archival operations. Provides audit trail for compliance.
    -- Business Case: GDPR and other regulations require automated enforcement of retention
    --                policies. This table manages the execution of retention jobs, ensuring
    --                data is deleted or archived according to policy. The design supports
    --                staggered execution to avoid performance impact, with comprehensive
    --                logging of affected records. Failed jobs are automatically retried,
    --                and administrators are alerted to persistent failures. Historical
    --                data supports compliance audits and dispute resolution.
    --
    -- Key Performance Indicators (KPIs):
    --   1. Job success rate - Percentage of successful retention jobs
    --   2. Records processed - Volume of data deleted/archived per job
    --   3. Execution time - Average job duration
    --   4. Retry rate - Frequency of job failures requiring retry
    --   5. Compliance coverage - Percentage of data covered by active policies
    --
    -- Feature References:
    --   - RET04 (Retention Enforcement)
    --   - RET05 (Automated Deletion)
    --   - GDPR20 (Data Erasure)
    --   - COMP23 (Retention Compliance)
    --================================================================================================
    CREATE TABLE IF NOT EXISTS socialcandor_schema.retention_enforcement_jobs (
        -- Primary key
        job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

        -- Human-readable identifier
        job_number VARCHAR(50) GENERATED ALWAYS AS (
            'RET-' || TO_CHAR(scheduled_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.retention_enforcement_jobs_seq')::TEXT, 6, '0')
        ) STORED,

        -- References
        policy_id UUID NOT NULL,    -- Reference to data_retention_policies

        -- Job configuration
        job_type VARCHAR(30) CHECK (job_type IN ('DELETE', 'ARCHIVE', 'ANONYMIZE')),
        target_schema VARCHAR(100),
        target_table VARCHAR(100),
        filter_condition TEXT,       -- WHERE clause for selection

        -- Scheduling
        scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
        started_at TIMESTAMP WITH TIME ZONE,
        completed_at TIMESTAMP WITH TIME ZONE,

        -- Execution status
        status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
            'PENDING', 'RUNNING', 'COMPLETED', 'PARTIAL', 'FAILED', 'CANCELLED'
        )),

        -- Statistics
        rows_processed INTEGER DEFAULT 0,
        rows_affected INTEGER DEFAULT 0,
        rows_failed INTEGER DEFAULT 0,
        bytes_freed BIGINT DEFAULT 0,

        -- Performance
        execution_duration_ms INTEGER CHECK (execution_duration_ms >= 0),
        average_row_time_ms NUMERIC(10,4),

        -- Archival (if applicable)
        archive_location VARCHAR(500),
        archive_size_bytes BIGINT,
        archive_manifest_url VARCHAR(500),

        -- Error handling
        retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),
        max_retries INTEGER DEFAULT 3,
        last_error TEXT,
        last_error_row JSONB,

        -- Audit columns
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID DEFAULT uuid_nil(),

        -- Constraints
        CONSTRAINT fk_retention_jobs_policy FOREIGN KEY (policy_id)
            REFERENCES socialcandor_schema.data_retention_policies(policy_id) ON DELETE CASCADE,
        CONSTRAINT fk_retention_jobs_created_by FOREIGN KEY (created_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
        CONSTRAINT fk_retention_jobs_updated_by FOREIGN KEY (updated_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
    );

    -- Comments
    COMMENT ON TABLE socialcandor_schema.retention_enforcement_jobs IS 'Tracks automated execution of data retention policies for deletion/archival';
    COMMENT ON COLUMN socialcandor_schema.retention_enforcement_jobs.rows_affected IS 'Number of rows actually deleted/archived';
    COMMENT ON COLUMN socialcandor_schema.retention_enforcement_jobs.last_error_row IS 'JSON representation of the row that caused the last error';
    COMMENT ON COLUMN socialcandor_schema.retention_enforcement_jobs.archive_manifest_url IS 'URL to manifest file listing archived records';

    -- Indexes for performance
    CREATE INDEX idx_retention_jobs_policy ON socialcandor_schema.retention_enforcement_jobs(policy_id, scheduled_at DESC);
    CREATE INDEX idx_retention_jobs_status ON socialcandor_schema.retention_enforcement_jobs(status, scheduled_at) WHERE status IN ('PENDING', 'RUNNING');
    CREATE INDEX idx_retention_jobs_completed ON socialcandor_schema.retention_enforcement_jobs(completed_at DESC) WHERE status = 'COMPLETED';

    -- Trigger for updated_at
    CREATE TRIGGER trg_retention_enforcement_jobs_updated_at
        BEFORE UPDATE ON socialcandor_schema.retention_enforcement_jobs
        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

    -- Function to process pending retention jobs
    CREATE OR REPLACE FUNCTION socialcandor_schema.process_retention_jobs()
    RETURNS INTEGER AS $$
    DECLARE
        v_job RECORD;
        v_processed INTEGER := 0;
    BEGIN
        FOR v_job IN
            SELECT * FROM socialcandor_schema.retention_enforcement_jobs
            WHERE status = 'PENDING'
              AND scheduled_at <= CURRENT_TIMESTAMP
            ORDER BY scheduled_at
            LIMIT 5
            FOR UPDATE SKIP LOCKED
        LOOP
            BEGIN
                UPDATE socialcandor_schema.retention_enforcement_jobs
                SET status = 'RUNNING',
                    started_at = CURRENT_TIMESTAMP
                WHERE job_id = v_job.job_id;

                -- Actual retention enforcement logic would be here
                -- This is a placeholder for the deletion/archival process

                UPDATE socialcandor_schema.retention_enforcement_jobs
                SET status = 'COMPLETED',
                    completed_at = CURRENT_TIMESTAMP,
                    rows_processed = 1000,
                    rows_affected = 950
                WHERE job_id = v_job.job_id;

                v_processed := v_processed + 1;
            EXCEPTION WHEN OTHERS THEN
                UPDATE socialcandor_schema.retention_enforcement_jobs
                SET status = 'FAILED',
                    last_error = SQLERRM,
                    retry_count = retry_count + 1,
                    last_retry_at = CURRENT_TIMESTAMP
                WHERE job_id = v_job.job_id;
            END;
        END LOOP;

        RETURN v_processed;
    END;
    $$ LANGUAGE plpgsql SECURITY DEFINER;



    --================================================================================================
    -- Table: DR02 - archived_data_catalog
    -- Description: Metadata catalog of archived data, enabling discovery, retrieval, and
    --              legal hold management. Supports compliance with data subject access requests.
    -- Business Case: When data is archived (moved to cold storage), it must remain discoverable
    --                for legal holds, subject access requests, and internal investigations.
    --                This catalog maintains pointers to archived data with metadata for
    --                efficient retrieval. The design supports multiple storage tiers (S3,
    --                Glacier, etc.) and encryption tracking. Legal hold flags prevent
    --                deletion during litigation holds. Historical queries can be satisfied
    --                by locating relevant archived data without scanning all archives.
    --
    -- Key Performance Indicators (KPIs):
    --   1. Archive size - Total volume of archived data by tier
    --   2. Retrieval frequency - Number of archive retrievals per month
    --   3. Legal hold count - Number of records under active legal hold
    --   4. Archive age - Distribution of archive age by data type
    --   5. Retrieval time - Average time to locate and retrieve archived data
    --
    -- Feature References:
    --   - RET06 (Data Archival)
    --   - RET07 (Archive Management)
    --   - GDPR21 (Archived Data Access)
    --   - LEG01 (Legal Hold)
    --================================================================================================
    CREATE TABLE IF NOT EXISTS socialcandor_schema.archived_data_catalog (
        -- Primary key
        archive_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

        -- Human-readable identifier
        archive_number VARCHAR(50) GENERATED ALWAYS AS (
            'ARC-' || TO_CHAR(archived_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.archived_data_catalog_seq')::TEXT, 6, '0')
        ) STORED,

        -- Source information
        source_system VARCHAR(100),
        source_schema VARCHAR(100),
        source_table VARCHAR(100),
        source_columns TEXT[],       -- Which columns are archived

        -- Data identification
        record_identifier VARCHAR(500),                        -- Primary key or unique identifier
        record_metadata JSONB,       -- Key metadata for search

        -- Archive location
        storage_tier VARCHAR(50) CHECK (storage_tier IN (
            'HOT', 'COOL', 'COLD', 'GLACIER', 'DEEP_ARCHIVE'
        )),
        storage_provider VARCHAR(50) CHECK (storage_provider IN ('AWS_S3', 'GCS', 'AZURE', 'LOCAL')),
        bucket_name VARCHAR(255),
        object_key VARCHAR(500) NOT NULL,
        region VARCHAR(50),

        -- File information
        file_format VARCHAR(30) CHECK (file_format IN ('JSON', 'CSV', 'PARQUET', 'AVRO', 'ORC')),
        compression VARCHAR(20) CHECK (compression IN ('NONE', 'GZIP', 'SNAPPY', 'ZSTD')),
        file_size_bytes BIGINT CHECK (file_size_bytes >= 0),
        row_count INTEGER CHECK (row_count >= 0),

        -- Encryption
        encrypted BOOLEAN DEFAULT TRUE,
        encryption_key_id UUID,
        encryption_algorithm VARCHAR(50),

        -- Archival metadata
        archived_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
        archived_by UUID NOT NULL,
        archive_job_id UUID,         -- Link to retention_enforcement_jobs
        retention_policy_id UUID,

        -- Legal hold
        legal_hold BOOLEAN DEFAULT FALSE,
        legal_hold_until TIMESTAMP WITH TIME ZONE,
        legal_hold_reason TEXT,

        -- Expiration
        expires_at TIMESTAMP WITH TIME ZONE,
        deleted_at TIMESTAMP WITH TIME ZONE,

        -- Audit columns
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

        -- Constraints
        CONSTRAINT fk_archived_data_archived_by FOREIGN KEY (archived_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
        CONSTRAINT fk_archived_data_encryption_key FOREIGN KEY (encryption_key_id)
            REFERENCES socialcandor_schema.encryption_keys(key_id) ON DELETE SET NULL,
        CONSTRAINT fk_archived_data_job FOREIGN KEY (archive_job_id)
            REFERENCES socialcandor_schema.retention_enforcement_jobs(job_id) ON DELETE SET NULL,
        CONSTRAINT fk_archived_data_policy FOREIGN KEY (retention_policy_id)
            REFERENCES socialcandor_schema.data_retention_policies(policy_id) ON DELETE SET NULL,

        CONSTRAINT chk_archived_data_legal CHECK (
            (legal_hold = FALSE) OR (legal_hold_until IS NOT NULL)
        ),
        CONSTRAINT chk_archived_data_expiry CHECK (
            (expires_at IS NULL) OR (expires_at > archived_at)
        )
    );

    -- Comments
    COMMENT ON TABLE socialcandor_schema.archived_data_catalog IS 'Metadata catalog of archived data for discovery and retrieval';
    COMMENT ON COLUMN socialcandor_schema.archived_data_catalog.record_metadata IS 'Key metadata for searching (user_id, date range, etc.)';
    COMMENT ON COLUMN socialcandor_schema.archived_data_catalog.legal_hold IS 'Flag indicating record is under legal hold and cannot be deleted';
    COMMENT ON COLUMN socialcandor_schema.archived_data_catalog.object_key IS 'Storage object key/path for retrieval';

    -- Indexes for performance
    CREATE INDEX idx_archived_data_source ON socialcandor_schema.archived_data_catalog(source_schema, source_table, archived_at DESC);
    CREATE INDEX idx_archived_data_identifier ON socialcandor_schema.archived_data_catalog(record_identifier);
    CREATE INDEX idx_archived_data_tier ON socialcandor_schema.archived_data_catalog(storage_tier, expires_at);
    CREATE INDEX idx_archived_data_legal ON socialcandor_schema.archived_data_catalog(legal_hold, legal_hold_until) WHERE legal_hold = TRUE;
    CREATE INDEX idx_archived_data_metadata ON socialcandor_schema.archived_data_catalog USING GIN (record_metadata);

    -- GIN index for JSONB search
    CREATE INDEX idx_archived_data_metadata_gin ON socialcandor_schema.archived_data_catalog USING GIN (record_metadata);

    -- Trigger for updated_at
    CREATE TRIGGER trg_archived_data_catalog_updated_at
        BEFORE UPDATE ON socialcandor_schema.archived_data_catalog
        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



        --================================================================================================
        -- Table: DR03 - data_retention_exceptions
        -- Description: Manages exceptions to standard retention policies (e.g., legal hold,
        --              regulatory requirements, user-requested retention). Prevents automated deletion.
        -- Business Case: Standard retention policies cannot always be applied uniformly due to
        --                legal holds (litigation), regulatory requirements (different retention
        --                periods), or user requests (opt-out of deletion). This table manages
        --                these exceptions, overriding normal policy behavior. The design supports
        --                time-bound exceptions (e.g., legal hold until case closes) and
        --                reason tracking for auditability. Integration with retention enforcement
        --                jobs ensures exceptions are respected during automated deletion.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Exception count - Number of active retention exceptions
        --   2. Exception type distribution - Breakdown by reason (legal, regulatory, user)
        --   3. Exception duration - Average length of exceptions
        --   4. Policy override rate - Percentage of records under exception
        --   5. Expiring exceptions - Count of exceptions expiring in next 30 days
        --
        -- Feature References:
        --   - RET08 (Retention Exceptions)
        --   - RET09 (Legal Hold)
        --   - GDPR22 (Retention Override)
        --   - LEG02 (eDiscovery)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.data_retention_exceptions (
            -- Primary key
            exception_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

            -- Human-readable identifier
            exception_number VARCHAR(50) GENERATED ALWAYS AS (
                'RETEX-' || TO_CHAR(granted_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_retention_exceptions_seq')::TEXT, 6, '0')
            ) STORED,

            -- Target data
            target_type VARCHAR(50) NOT NULL CHECK (target_type IN (
                'USER', 'ORGANIZATION', 'RECORD', 'TABLE', 'CATEGORY'
            )),
            target_id VARCHAR(500) NOT NULL,                       -- ID of the target
            target_identifier VARCHAR(500),                         -- Human-readable identifier

            -- Exception details
            exception_type VARCHAR(50) NOT NULL CHECK (exception_type IN (
                'LEGAL_HOLD', 'REGULATORY', 'USER_REQUEST', 'INVESTIGATION', 'DISPUTE', 'OTHER'
            )),
            exception_reason TEXT NOT NULL,
            exception_scope TEXT[],       -- Which data categories are affected

            -- Duration
            granted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
            expires_at TIMESTAMP WITH TIME ZONE,
            is_permanent BOOLEAN DEFAULT FALSE,
            is_active BOOLEAN GENERATED ALWAYS AS (
                (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP) AND
                revoked_at IS NULL
            ) STORED,

            -- Grantor information
            granted_by UUID NOT NULL,
            granting_authority VARCHAR(255),                        -- Court order, regulatory body, etc.
            reference_number VARCHAR(255),                          -- Case number, request ID

            -- Supporting documentation
            documentation_urls TEXT[],
            notes TEXT,

            -- Revocation
            revoked_at TIMESTAMP WITH TIME ZONE,
            revoked_by UUID,
            revocation_reason TEXT,

            -- Audit columns
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            created_by UUID NOT NULL,
            updated_by UUID DEFAULT uuid_nil(),

            -- Constraints
            CONSTRAINT fk_retention_exceptions_granted_by FOREIGN KEY (granted_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
            CONSTRAINT fk_retention_exceptions_revoked_by FOREIGN KEY (revoked_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_retention_exceptions_created_by FOREIGN KEY (created_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
            CONSTRAINT fk_retention_exceptions_updated_by FOREIGN KEY (updated_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

            CONSTRAINT chk_retention_exceptions_dates CHECK (
                (expires_at IS NULL AND is_permanent = TRUE) OR
                (expires_at IS NOT NULL AND is_permanent = FALSE AND expires_at > granted_at)
            ),
            CONSTRAINT chk_retention_exceptions_revocation CHECK (
                (revoked_at IS NULL) OR (revoked_at >= granted_at)
            )
        );

        -- Comments
        COMMENT ON TABLE socialcandor_schema.data_retention_exceptions IS 'Manages exceptions to standard retention policies (legal hold, regulatory, user request)';
        COMMENT ON COLUMN socialcandor_schema.data_retention_exceptions.target_type IS 'Type of target (user, organization, specific record, table, data category)';
        COMMENT ON COLUMN socialcandor_schema.data_retention_exceptions.exception_scope IS 'Array of specific data categories affected by the exception';
        COMMENT ON COLUMN socialcandor_schema.data_retention_exceptions.granting_authority IS 'External authority granting the exception (court, regulator, etc.)';

        -- Indexes for performance
        CREATE INDEX idx_retention_exceptions_target ON socialcandor_schema.data_retention_exceptions(target_type, target_id) WHERE is_active = TRUE;
        CREATE INDEX idx_retention_exceptions_type ON socialcandor_schema.data_retention_exceptions(exception_type, expires_at);
        CREATE INDEX idx_retention_exceptions_active ON socialcandor_schema.data_retention_exceptions(is_active, expires_at) WHERE is_active = TRUE;
        CREATE INDEX idx_retention_exceptions_granted ON socialcandor_schema.data_retention_exceptions(granted_by) WHERE is_active = TRUE;

        -- Trigger for updated_at
        CREATE TRIGGER trg_data_retention_exceptions_updated_at
            BEFORE UPDATE ON socialcandor_schema.data_retention_exceptions
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

        -- Function to check for expiring exceptions
        CREATE OR REPLACE FUNCTION socialcandor_schema.check_expiring_exceptions()
        RETURNS INTEGER AS $$
        DECLARE
            v_count INTEGER := 0;
        BEGIN
            -- Count exceptions expiring in the next 30 days
            SELECT COUNT(*) INTO v_count
            FROM socialcandor_schema.data_retention_exceptions
            WHERE expires_at BETWEEN CURRENT_TIMESTAMP AND CURRENT_TIMESTAMP + INTERVAL '30 days'
              AND is_active = TRUE;

            -- Could send notifications here

            RETURN v_count;
        END;
        $$ LANGUAGE plpgsql SECURITY DEFINER;


        --================================================================================================
        -- Table: DR04 - data_deletion_audit
        -- Description: Comprehensive audit trail of all data deletions (soft and hard), including
        --              who deleted, when, why, and what data was affected. Supports compliance and
        --              forensic investigations.
        -- Business Case: GDPR Article 17 (Right to Erasure) requires proof of deletion upon request.
        --                This table provides an immutable audit trail of all deletion operations,
        --                whether initiated by users, automated retention policies, or administrators.
        --                The design captures before-state snapshots (for potential recovery) and
        --                metadata about the deletion context. For hard deletions, a cryptographic
        --                hash of the deleted data provides non-repudiation. This audit trail is
        --                essential for compliance certifications (SOC2, ISO27001) and legal disputes.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Deletion volume - Number of records deleted per day
        --   2. Deletion type distribution - Soft vs. hard delete ratio
        --   3. Deletion reason breakdown - User-initiated vs. policy vs. admin
        --   4. Recovery requests - Number of recovery attempts from audit
        --   5. Audit completeness - Percentage of deletions captured vs. estimated
        --
        -- Feature References:
        --   - RET10 (Deletion Audit)
        --   - GDPR23 (Erasure Proof)
        --   - AUD16 (Deletion Logging)
        --   - COMP24 (Audit Trail)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.data_deletion_audit (
            -- Primary key
            deletion_id BIGSERIAL,

            -- Human-readable identifier
            deletion_number VARCHAR(50) GENERATED ALWAYS AS (
                'DEL-' || TO_CHAR(deletion_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_deletion_audit_seq')::TEXT, 6, '0')
            ) STORED,

            -- Deletion metadata
            deletion_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
            deleted_by UUID NOT NULL,
            deletion_reason VARCHAR(100) CHECK (deletion_reason IN (
                'USER_REQUEST', 'RETENTION_POLICY', 'ADMIN_ACTION', 'GDPR_REQUEST', 'DATA_CLEANUP', 'SYSTEM'
            )),
            deletion_source VARCHAR(50) CHECK (deletion_source IN (
                'API', 'UI', 'BATCH_JOB', 'RETENTION_JOB', 'ANONYMIZATION_QUEUE'
            )),

            -- Target data
            target_type VARCHAR(50) NOT NULL CHECK (target_type IN (
                'USER', 'POST', 'COMMENT', 'MESSAGE', 'MEDIA', 'ACCOUNT', 'SESSION', 'LOG'
            )),
            target_id UUID NOT NULL,
            target_owner_id UUID,         -- User who owned the data

            -- Deletion type
            deletion_type VARCHAR(30) NOT NULL CHECK (deletion_type IN (
                'SOFT_DELETE', 'HARD_DELETE', 'ANONYMIZE', 'PSEUDONYMIZE'
            )),

            -- Data snapshot (for hard deletes, before state)
            before_snapshot JSONB,
            data_hash VARCHAR(64),        -- SHA-256 of deleted data

            -- Context
            ip_address INET,
            user_agent TEXT,
            session_id UUID,
            request_id UUID,               -- For request tracing

            -- Policy reference (if applicable)
            policy_id UUID,
            job_id UUID,

            -- Recovery information
            is_recoverable BOOLEAN DEFAULT FALSE,
            recovery_available_until TIMESTAMP WITH TIME ZONE,
            recovery_location VARCHAR(500),                          -- Backup location if recoverable

            -- Partition key
            deletion_date DATE GENERATED ALWAYS AS (deletion_time::DATE) STORED,

            -- Constraints
            CONSTRAINT pk_data_deletion_audit PRIMARY KEY (deletion_id, deletion_date),
            CONSTRAINT fk_data_deletion_audit_deleted_by FOREIGN KEY (deleted_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_data_deletion_audit_target_owner FOREIGN KEY (target_owner_id)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
            CONSTRAINT fk_data_deletion_audit_policy FOREIGN KEY (policy_id)
                REFERENCES socialcandor_schema.data_retention_policies(policy_id) ON DELETE SET NULL,
            CONSTRAINT fk_data_deletion_audit_job FOREIGN KEY (job_id)
                REFERENCES socialcandor_schema.retention_enforcement_jobs(job_id) ON DELETE SET NULL
        ) PARTITION BY RANGE (deletion_date);

        -- Comments
        COMMENT ON TABLE socialcandor_schema.data_deletion_audit IS 'Comprehensive audit trail of all data deletions for compliance and forensics';
        COMMENT ON COLUMN socialcandor_schema.data_deletion_audit.before_snapshot IS 'JSON snapshot of data before deletion (for potential recovery)';
        COMMENT ON COLUMN socialcandor_schema.data_deletion_audit.data_hash IS 'SHA-256 hash of deleted data for integrity verification';
        COMMENT ON COLUMN socialcandor_schema.data_deletion_audit.is_recoverable IS 'Whether the deleted data can be recovered from backup';

        -- Create monthly partitions
        DO $$
        DECLARE
            start_date DATE;
            end_date DATE;
            partition_name TEXT;
        BEGIN
            FOR i IN 0..11 LOOP
                start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
                end_date := start_date + '1 month'::INTERVAL;
                partition_name := 'data_deletion_audit_' || TO_CHAR(start_date, 'YYYY_MM');

                EXECUTE format('
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.data_deletion_audit
                    FOR VALUES FROM (%L) TO (%L)',
                    partition_name, start_date, end_date
                );
            END LOOP;
        END $$;

        -- Indexes for performance
        CREATE INDEX idx_deletion_audit_time ON socialcandor_schema.data_deletion_audit(deletion_time DESC);
        CREATE INDEX idx_deletion_audit_deleted_by ON socialcandor_schema.data_deletion_audit(deleted_by, deletion_time DESC);
        CREATE INDEX idx_deletion_audit_target ON socialcandor_schema.data_deletion_audit(target_type, target_id, deletion_time DESC);
        CREATE INDEX idx_deletion_audit_owner ON socialcandor_schema.data_deletion_audit(target_owner_id, deletion_time DESC) WHERE target_owner_id IS NOT NULL;
        CREATE INDEX idx_deletion_audit_reason ON socialcandor_schema.data_deletion_audit(deletion_reason, deletion_time DESC);

        --================================================================================================
        -- Table: DR05 - data_lineage
        -- Description: Documents the flow of data from source to destination, including transformations,
        --              dependencies, and impact analysis. Supports data governance and troubleshooting.
        -- Business Case: Understanding data lineage is critical for impact analysis (what breaks if
        --                a source changes), regulatory compliance (proving data provenance), and
        --                troubleshooting data quality issues. This table captures the complete data
        --                flow graph, including transformations, pipeline executions, and dependencies.
        --                The design supports multiple asset types (tables, columns, reports, models)
        --                and versioning for historical analysis. This enables data stewards to quickly
        --                identify downstream impacts of schema changes or upstream data issues.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Lineage coverage - Percentage of critical data assets with documented lineage
        --   2. Dependency depth - Average number of downstream dependencies per source
        --   3. Change impact time - Time to identify impacted assets for a proposed change
        --   4. Lineage accuracy - Percentage of lineage relationships verified
        --   5. Data quality root cause - Time to trace data quality issues to source
        --
        -- Feature References:
        --   - GOV09 (Data Lineage)
        --   - GOV10 (Impact Analysis)
        --   - DQ08 (Data Quality Tracing)
        --   - COMP25 (Provenance Tracking)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.data_lineage (
            -- Primary key
            lineage_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

            -- Human-readable identifier
            lineage_number VARCHAR(50) GENERATED ALWAYS AS (
                'LINE-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_lineage_seq')::TEXT, 6, '0')
            ) STORED,

            -- Source asset
            source_type VARCHAR(50) NOT NULL CHECK (source_type IN (
                'TABLE', 'COLUMN', 'VIEW', 'PIPELINE', 'REPORT', 'DASHBOARD', 'ML_MODEL', 'EXTERNAL'
            )),
            source_id UUID NOT NULL,
            source_version VARCHAR(50),    -- For versioned assets

            -- Target asset
            target_type VARCHAR(50) NOT NULL CHECK (target_type IN (
                'TABLE', 'COLUMN', 'VIEW', 'PIPELINE', 'REPORT', 'DASHBOARD', 'ML_MODEL', 'EXTERNAL'
            )),
            target_id UUID NOT NULL,
            target_version VARCHAR(50),

            -- Lineage metadata
            relationship_type VARCHAR(50) CHECK (relationship_type IN (
                'DIRECT', 'TRANSFORMED', 'AGGREGATED', 'FILTERED', 'JOINED', 'COPY'
            )),
            transformation_description TEXT,
            transformation_code TEXT,      -- SQL, Python, etc.

            -- Pipeline reference (if applicable)
            pipeline_id UUID,
            job_id UUID,
            execution_id UUID,

            -- Data quality impact
            quality_impact VARCHAR(50) CHECK (quality_impact IN ('HIGH', 'MEDIUM', 'LOW', 'NONE')),

            -- Cardinality
            source_rows_ratio NUMERIC(10,4),                          -- Source to target row ratio
            selectivity NUMERIC(10,4),      -- Filtering factor

            -- Effective dating
            valid_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
            valid_to TIMESTAMP WITH TIME ZONE,
            is_active BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL) STORED,

            -- Audit columns
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            created_by UUID NOT NULL,
            updated_by UUID DEFAULT uuid_nil(),

            -- Constraints
            CONSTRAINT fk_data_lineage_pipeline FOREIGN KEY (pipeline_id)
                REFERENCES socialcandor_schema.ingestion_pipelines(pipeline_id) ON DELETE SET NULL,
            CONSTRAINT fk_data_lineage_job FOREIGN KEY (job_id)
                REFERENCES socialcandor_schema.background_jobs(job_id) ON DELETE SET NULL,
            CONSTRAINT fk_data_lineage_created_by FOREIGN KEY (created_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
            CONSTRAINT fk_data_lineage_updated_by FOREIGN KEY (updated_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

            CONSTRAINT chk_data_lineage_dates CHECK (valid_to IS NULL OR valid_to > valid_from),
            CONSTRAINT chk_data_lineage_assets CHECK (source_id != target_id OR source_type != target_type)
        );

        -- Comments
        COMMENT ON TABLE socialcandor_schema.data_lineage IS 'Documents data flow from source to destination for impact analysis and governance';
        COMMENT ON COLUMN socialcandor_schema.data_lineage.transformation_code IS 'Code or description of transformation applied';
        COMMENT ON COLUMN socialcandor_schema.data_lineage.source_rows_ratio IS 'Ratio of source rows to target rows (for understanding transformation impact)';
        COMMENT ON COLUMN socialcandor_schema.data_lineage.selectivity IS 'Filtering factor (0-1) for selective transformations';

        -- Indexes for performance
        CREATE INDEX idx_data_lineage_source ON socialcandor_schema.data_lineage(source_type, source_id, valid_from DESC) WHERE is_active = TRUE;
        CREATE INDEX idx_data_lineage_target ON socialcandor_schema.data_lineage(target_type, target_id, valid_from DESC) WHERE is_active = TRUE;
        CREATE INDEX idx_data_lineage_pipeline ON socialcandor_schema.data_lineage(pipeline_id) WHERE pipeline_id IS NOT NULL;
        CREATE INDEX idx_data_lineage_relationship ON socialcandor_schema.data_lineage(relationship_type);

        -- Trigger for updated_at
        CREATE TRIGGER trg_data_lineage_updated_at
            BEFORE UPDATE ON socialcandor_schema.data_lineage
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

        -- Function to find downstream dependencies
        CREATE OR REPLACE FUNCTION socialcandor_schema.find_downstream_dependencies(
            p_source_type VARCHAR,
            p_source_id UUID,
            p_max_depth INTEGER DEFAULT 5
        )
        RETURNS TABLE (
            dependency_type VARCHAR,
            dependency_id UUID,
            dependency_name VARCHAR,
            depth INTEGER,
            path TEXT[]
        ) AS $$
        WITH RECURSIVE lineage_tree AS (
            -- Anchor: direct dependencies
            SELECT
                target_type AS dep_type,
                target_id AS dep_id,
                1 AS depth,
                ARRAY[source_id::TEXT || ':' || target_id::TEXT] AS path
            FROM socialcandor_schema.data_lineage
            WHERE source_type = p_source_type
              AND source_id = p_source_id
              AND is_active = TRUE

            UNION ALL

            -- Recursive: dependencies of dependencies
            SELECT
                dl.target_type,
                dl.target_id,
                lt.depth + 1,
                lt.path || (dl.source_id::TEXT || ':' || dl.target_id::TEXT)
            FROM socialcandor_schema.data_lineage dl
            INNER JOIN lineage_tree lt ON lt.dep_type = dl.source_type AND lt.dep_id = dl.source_id
            WHERE lt.depth < p_max_depth
              AND dl.is_active = TRUE
        )
        SELECT
            dep_type,
            dep_id,
            COALESCE(dep_id::TEXT, 'Unknown') AS dependency_name,
            depth,
            path
        FROM lineage_tree
        ORDER BY depth, dep_type;
        $$ LANGUAGE sql STABLE;

        --================================================================================================
        -- Table: EC01 - seller_profiles
        -- Description: Extended seller information for marketplace participants, including business
        --              verification, payment details, and performance metrics. Supports trust and safety.
        -- Business Case: Marketplace success depends on seller trust and reliability. This table
        --                stores comprehensive seller information beyond basic user profiles, including
        --                business verification documents, tax information, payout preferences, and
        --                performance metrics. The verification workflow ensures only legitimate
        --                businesses can sell, reducing fraud risk. Performance metrics (rating,
        --                response time, fulfillment rate) help buyers make informed decisions and
        --                enable platform governance (penalizing poor performers). The design supports
        --                multiple payout methods and automated reconciliation with payment processors.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Seller acquisition rate - New verified sellers per month
        --   2. Verification completion rate - Percentage of sellers completing verification
        --   3. Average seller rating - Mean rating across all sellers
        --   4. Payout success rate - Percentage of successful payouts to sellers
        --   5. Seller churn rate - Percentage of sellers leaving the platform
        --
        -- Feature References:
        --   - MPL07 (Seller Management)
        --   - MPL08 (Seller Verification)
        --   - PAY08 (Seller Payouts)
        --   - TRUST01 (Trust & Safety)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.seller_profiles (
            -- Primary key
            seller_profile_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

            -- Human-readable identifier
            seller_number VARCHAR(50) GENERATED ALWAYS AS (
                'SELL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.seller_profiles_seq')::TEXT, 6, '0')
            ) STORED,

            -- References
            user_id UUID NOT NULL UNIQUE,
            organization_id UUID,          -- If seller is an organization

            -- Business information
            business_name VARCHAR(255) NOT NULL,
            business_type VARCHAR(50) CHECK (business_type IN (
                'INDIVIDUAL', 'SOLE_PROPRIETORSHIP', 'LLC', 'CORPORATION', 'NONPROFIT', 'GOVERNMENT'
            )),
            business_description TEXT,
            business_logo_url VARCHAR(500),
            business_banner_url VARCHAR(500),
            business_website VARCHAR(255),
            business_phone VARCHAR(50),
            business_email VARCHAR(255),

            -- Legal and tax information
            tax_id VARCHAR(50),             -- Encrypted
            tax_id_type VARCHAR(20) CHECK (tax_id_type IN ('EIN', 'SSN', 'VAT', 'GST', 'OTHER')),
            business_registration_number VARCHAR(100),
            business_registration_country VARCHAR(3),
            business_registration_date DATE,

            -- Verification status
            verification_status VARCHAR(30) DEFAULT 'PENDING' CHECK (verification_status IN (
                'PENDING', 'DOCUMENTS_SUBMITTED', 'UNDER_REVIEW', 'VERIFIED', 'REJECTED', 'SUSPENDED'
            )),
            verification_documents JSONB DEFAULT '[]',                 -- URLs to uploaded documents
            verified_at TIMESTAMP WITH TIME ZONE,
            rejection_reason TEXT,

            -- Address
            business_address_line1 VARCHAR(255),
            business_address_line2 VARCHAR(255),
            business_city VARCHAR(100),
            business_state VARCHAR(100),
            business_postal_code VARCHAR(20),
            business_country VARCHAR(3),

            -- Payout configuration
            payout_method VARCHAR(30) CHECK (payout_method IN ('BANK_TRANSFER', 'PAYPAL', 'WALLET', 'CRYPTO')),
            payout_currency CHAR(3) DEFAULT 'USD',
            payout_schedule VARCHAR(30) CHECK (payout_schedule IN ('DAILY', 'WEEKLY', 'BI_WEEKLY', 'MONTHLY', 'MANUAL')),
            minimum_payout_amount NUMERIC(15,2) DEFAULT 10.00,
            payout_hold_period_days INTEGER DEFAULT 7,                  -- For dispute protection

            -- Bank details (encrypted)
            bank_account_encrypted TEXT,
            bank_routing_encrypted TEXT,
            bank_name VARCHAR(255),
            bank_country VARCHAR(3),
            bank_currency CHAR(3),

            -- PayPal/Stripe details
            paypal_email VARCHAR(255),
            stripe_account_id VARCHAR(255),

            -- Performance metrics
            seller_rating NUMERIC(3,2) DEFAULT 0 CHECK (seller_rating >= 0 AND seller_rating <= 5),
            total_reviews INTEGER DEFAULT 0,
            total_sales INTEGER DEFAULT 0,
            total_revenue NUMERIC(15,2) DEFAULT 0,
            average_response_time_hours NUMERIC(10,2),
            fulfillment_rate NUMERIC(5,2) CHECK (fulfillment_rate >= 0 AND fulfillment_rate <= 100),
            cancellation_rate NUMERIC(5,2) CHECK (cancellation_rate >= 0 AND cancellation_rate <= 100),

            -- Store policies
            return_policy TEXT,
            shipping_policy TEXT,
            refund_policy TEXT,
            custom_policies JSONB DEFAULT '{}',

            -- Status
            is_active BOOLEAN DEFAULT TRUE,
            suspended_at TIMESTAMP WITH TIME ZONE,
            suspension_reason TEXT,

            -- Audit columns
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            created_by UUID NOT NULL,
            updated_by UUID DEFAULT uuid_nil(),

            -- Constraints
            CONSTRAINT fk_seller_profiles_user FOREIGN KEY (user_id)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
            CONSTRAINT fk_seller_profiles_org FOREIGN KEY (organization_id)
                REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE SET NULL,
            CONSTRAINT fk_seller_profiles_created_by FOREIGN KEY (created_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
            CONSTRAINT fk_seller_profiles_updated_by FOREIGN KEY (updated_by)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

            CONSTRAINT chk_seller_payout CHECK (
                (payout_method = 'BANK_TRANSFER' AND bank_account_encrypted IS NOT NULL) OR
                (payout_method = 'PAYPAL' AND paypal_email IS NOT NULL) OR
                (payout_method != 'BANK_TRANSFER' AND payout_method != 'PAYPAL')
            )
        );

        -- Comments
        COMMENT ON TABLE socialcandor_schema.seller_profiles IS 'Extended seller information for marketplace participants with verification and performance tracking';
        COMMENT ON COLUMN socialcandor_schema.seller_profiles.tax_id IS 'Tax identifier (encrypted for security)';
        COMMENT ON COLUMN socialcandor_schema.seller_profiles.verification_documents IS 'JSON array of document URLs with metadata (type, upload date, verification status)';
        COMMENT ON COLUMN socialcandor_schema.seller_profiles.payout_hold_period_days IS 'Days to hold funds before payout for dispute protection';

        -- Indexes for performance
        CREATE INDEX idx_seller_profiles_user ON socialcandor_schema.seller_profiles(user_id);
        CREATE INDEX idx_seller_profiles_verification ON socialcandor_schema.seller_profiles(verification_status) WHERE verification_status != 'VERIFIED';
        CREATE INDEX idx_seller_profiles_active ON socialcandor_schema.seller_profiles(is_active, seller_rating DESC) WHERE is_active = TRUE;
        CREATE INDEX idx_seller_profiles_performance ON socialcandor_schema.seller_profiles(fulfillment_rate, cancellation_rate);

        -- Trigger for updated_at
        CREATE TRIGGER trg_seller_profiles_updated_at
            BEFORE UPDATE ON socialcandor_schema.seller_profiles
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

        -- RLS Policy
        ALTER TABLE socialcandor_schema.seller_profiles ENABLE ROW LEVEL SECURITY;
        CREATE POLICY seller_profiles_self_policy ON socialcandor_schema.seller_profiles
            FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
        CREATE POLICY seller_profiles_admin_policy ON socialcandor_schema.seller_profiles
            FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));


            --================================================================================================
            -- Table: EC02 - product_variants
            -- Description: Manages product variations (size, color, style) with SKU-level tracking,
            --              pricing adjustments, and inventory management. Supports complex product catalogs.
            -- Business Case: Modern e-commerce requires support for product variations (e.g., t-shirts in
            --                multiple sizes and colors). This table enables SKU-level tracking with
            --                variant-specific attributes, pricing, and inventory. The design supports
            --                unlimited variant attributes via JSONB, allowing flexible product schemas
            --                without schema changes. Price adjustments enable different pricing by variant
            --                (e.g., larger sizes cost more). Integration with inventory ensures accurate
            --                stock tracking at the variant level, preventing overselling.
            --
            -- Key Performance Indicators (KPIs):
            --   1. Variant density - Average variants per product
            --   2. Variant performance - Sales distribution across variants
            --   3. SKU coverage - Percentage of products with proper SKU assignment
            --   4. Price variation - Price range across variants for same product
            --   5. Inventory accuracy - Stock count accuracy at variant level
            --
            -- Feature References:
            --   - MPL09 (Product Variants)
            --   - MPL10 (SKU Management)
            --   - INV01 (Variant Inventory)
            --   - CAT01 (Product Catalog)
            --================================================================================================
            CREATE TABLE IF NOT EXISTS socialcandor_schema.product_variants (
                -- Primary key
                variant_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                -- Human-readable identifier
                variant_number VARCHAR(50) GENERATED ALWAYS AS (
                    'VAR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.product_variants_seq')::TEXT, 6, '0')
                ) STORED,

                -- References
                listing_id UUID NOT NULL,       -- Parent product/listing
                seller_profile_id UUID NOT NULL,

                -- Variant identification
                sku VARCHAR(100) UNIQUE NOT NULL,
                upc VARCHAR(20),                -- Universal Product Code
                ean VARCHAR(20),                -- European Article Number
                isbn VARCHAR(20),               -- For books

                -- Variant attributes (e.g., size: "M", color: "Red", material: "Cotton")
                attributes JSONB NOT NULL DEFAULT '{}',

                -- Pricing
                price_adjustment NUMERIC(15,2) DEFAULT 0 CHECK (price_adjustment >= 0),
                compare_at_price_adjustment NUMERIC(15,2),                -- For MSRP comparison
                cost_adjustment NUMERIC(15,2) DEFAULT 0,                  -- Seller cost

                -- Images
                image_urls TEXT[],               -- Variant-specific images
                thumbnail_url VARCHAR(500),

                -- Dimensions (for shipping)
                weight_kg NUMERIC(10,3),
                length_cm NUMERIC(10,2),
                width_cm NUMERIC(10,2),
                height_cm NUMERIC(10,2),

                -- Status
                is_active BOOLEAN DEFAULT TRUE,
                is_default BOOLEAN DEFAULT FALSE,                         -- Default variant for product
                available_from TIMESTAMP WITH TIME ZONE,
                available_to TIMESTAMP WITH TIME ZONE,
                discontinued_at TIMESTAMP WITH TIME ZONE,

                -- Audit columns
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                created_by UUID NOT NULL,
                updated_by UUID DEFAULT uuid_nil(),

                -- Constraints
                CONSTRAINT fk_product_variants_listing FOREIGN KEY (listing_id)
                    REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
                CONSTRAINT fk_product_variants_seller FOREIGN KEY (seller_profile_id)
                    REFERENCES socialcandor_schema.seller_profiles(seller_profile_id) ON DELETE CASCADE,
                CONSTRAINT fk_product_variants_created_by FOREIGN KEY (created_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                CONSTRAINT fk_product_variants_updated_by FOREIGN KEY (updated_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                CONSTRAINT chk_product_variants_dates CHECK (
                    (available_to IS NULL) OR (available_to > available_from)
                )
            );

            -- Comments
            COMMENT ON TABLE socialcandor_schema.product_variants IS 'Product variations with SKU-level tracking, pricing adjustments, and inventory management';
            COMMENT ON COLUMN socialcandor_schema.product_variants.attributes IS 'Variant attributes (size, color, material, etc.) as JSON key-value pairs';
            COMMENT ON COLUMN socialcandor_schema.product_variants.price_adjustment IS 'Price difference from base product price';
            COMMENT ON COLUMN socialcandor_schema.product_variants.is_default IS 'Whether this is the default variant shown in product listings';

            -- Indexes for performance
            CREATE INDEX idx_product_variants_listing ON socialcandor_schema.product_variants(listing_id, is_default) WHERE is_active = TRUE;
            CREATE INDEX idx_product_variants_seller ON socialcandor_schema.product_variants(seller_profile_id);
            CREATE INDEX idx_product_variants_sku ON socialcandor_schema.product_variants(sku);
            CREATE INDEX idx_product_variants_attributes ON socialcandor_schema.product_variants USING GIN (attributes);

            -- Trigger for updated_at
            CREATE TRIGGER trg_product_variants_updated_at
                BEFORE UPDATE ON socialcandor_schema.product_variants
                FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

            -- RLS Policy
            ALTER TABLE socialcandor_schema.product_variants ENABLE ROW LEVEL SECURITY;
            CREATE POLICY product_variants_seller_policy ON socialcandor_schema.product_variants
                FOR ALL USING (seller_profile_id IN (
                    SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
                ));
            CREATE POLICY product_variants_buyer_policy ON socialcandor_schema.product_variants
                FOR SELECT USING (is_active = TRUE);
            CREATE POLICY product_variants_admin_policy ON socialcandor_schema.product_variants
                FOR ALL USING (socialcandor_schema.is_admin());


                --================================================================================================
                -- Table: EC03 - product_inventory
                -- Description: Tracks real-time inventory levels for products and variants, including
                --              reserved stock, reorder points, and inventory alerts. Prevents overselling.
                -- Business Case: Accurate inventory tracking is critical for e-commerce to prevent overselling
                --                and manage customer expectations. This table maintains real-time stock levels
                --                with support for reserved inventory (items in carts but not yet purchased).
                --                The reorder threshold enables automated replenishment alerts. The design
                --                supports multiple locations/warehouses and tracks inventory movements for
                --                auditability. Integration with order system ensures atomic inventory updates
                --                to prevent race conditions during high-concurrency checkout.
                --
                -- Key Performance Indicators (KPIs):
                --   1. Inventory accuracy - Percentage of products with accurate stock counts
                --   2. Stockout rate - Percentage of time products are out of stock
                --   3. Inventory turnover - Rate of inventory sell-through
                --   4. Days of supply - Average days until stockout at current sales rate
                --   5. Overstock rate - Percentage of products with excess inventory
                --
                -- Feature References:
                --   - INV02 (Inventory Management)
                --   - INV03 (Real-time Stock)
                --   - INV04 (Inventory Alerts)
                --   - ORD01 (Order Fulfillment)
                --================================================================================================
                CREATE TABLE IF NOT EXISTS socialcandor_schema.product_inventory (
                    -- Primary key
                    inventory_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                    -- Human-readable identifier
                    inventory_number VARCHAR(50) GENERATED ALWAYS AS (
                        'INV-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.product_inventory_seq')::TEXT, 6, '0')
                    ) STORED,

                    -- References
                    listing_id UUID NOT NULL,
                    variant_id UUID,               -- NULL for product-level inventory

                    -- Location
                    warehouse_id UUID,             -- For multi-warehouse setups
                    location_code VARCHAR(50),     -- Aisle, bin, shelf

                    -- Stock levels
                    quantity_on_hand INTEGER NOT NULL DEFAULT 0 CHECK (quantity_on_hand >= 0),
                    quantity_reserved INTEGER NOT NULL DEFAULT 0 CHECK (quantity_reserved >= 0),
                    quantity_available INTEGER GENERATED ALWAYS AS (quantity_on_hand - quantity_reserved) STORED,
                    quantity_backordered INTEGER DEFAULT 0 CHECK (quantity_backordered >= 0),
                    quantity_in_transit INTEGER DEFAULT 0 CHECK (quantity_in_transit >= 0),

                    -- Thresholds
                    reorder_threshold INTEGER CHECK (reorder_threshold >= 0),
                    reorder_quantity INTEGER CHECK (reorder_quantity >= 0),
                    safety_stock INTEGER DEFAULT 0 CHECK (safety_stock >= 0),

                    -- Alerts
                    low_stock_alert_sent BOOLEAN DEFAULT FALSE,
                    out_of_stock_alert_sent BOOLEAN DEFAULT FALSE,
                    last_alert_at TIMESTAMP WITH TIME ZONE,

                    -- Dates
                    last_restocked_at TIMESTAMP WITH TIME ZONE,
                    next_expected_restock TIMESTAMP WITH TIME ZONE,

                    -- Status
                    is_tracked BOOLEAN DEFAULT TRUE,                         -- Whether inventory is tracked
                    is_sellable_when_out_of_stock BOOLEAN DEFAULT FALSE,     -- Allow backorders

                    -- Audit columns
                    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                    created_by UUID NOT NULL,
                    updated_by UUID DEFAULT uuid_nil(),

                    -- Constraints
                    CONSTRAINT fk_product_inventory_listing FOREIGN KEY (listing_id)
                        REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
                    CONSTRAINT fk_product_inventory_variant FOREIGN KEY (variant_id)
                        REFERENCES socialcandor_schema.product_variants(variant_id) ON DELETE CASCADE,
                    CONSTRAINT fk_product_inventory_created_by FOREIGN KEY (created_by)
                        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                    CONSTRAINT fk_product_inventory_updated_by FOREIGN KEY (updated_by)
                        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                    CONSTRAINT uk_product_inventory UNIQUE (listing_id, variant_id, warehouse_id)
                );

                -- Comments
                COMMENT ON TABLE socialcandor_schema.product_inventory IS 'Real-time inventory tracking with reserved stock and reorder thresholds';
                COMMENT ON COLUMN socialcandor_schema.product_inventory.quantity_on_hand IS 'Physical stock count';
                COMMENT ON COLUMN socialcandor_schema.product_inventory.quantity_reserved IS 'Stock in active carts/orders not yet fulfilled';
                COMMENT ON COLUMN socialcandor_schema.product_inventory.quantity_available IS 'Available for purchase (on_hand - reserved)';

                -- Indexes for performance
                CREATE INDEX idx_product_inventory_listing ON socialcandor_schema.product_inventory(listing_id, variant_id) WHERE is_tracked = TRUE;
                CREATE INDEX idx_product_inventory_low_stock ON socialcandor_schema.product_inventory(quantity_available)
                    WHERE quantity_available <= reorder_threshold AND reorder_threshold IS NOT NULL;
                CREATE INDEX idx_product_inventory_warehouse ON socialcandor_schema.product_inventory(warehouse_id) WHERE warehouse_id IS NOT NULL;

                -- Trigger for updated_at
                CREATE TRIGGER trg_product_inventory_updated_at
                    BEFORE UPDATE ON socialcandor_schema.product_inventory
                    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                -- Function to check inventory levels and send alerts
                CREATE OR REPLACE FUNCTION socialcandor_schema.check_inventory_levels()
                RETURNS TRIGGER AS $$
                BEGIN
                    -- Check for low stock
                    IF NEW.reorder_threshold IS NOT NULL
                       AND NEW.quantity_available <= NEW.reorder_threshold
                       AND NEW.low_stock_alert_sent = FALSE THEN
                        NEW.low_stock_alert_sent := TRUE;
                        NEW.last_alert_at := CURRENT_TIMESTAMP;

                        -- Insert alert (simplified - would integrate with notification system)
                        INSERT INTO socialcandor_schema.anomaly_alerts (
  alert_name, severity, source_system, description, created_by
                        ) VALUES (
  'Low Stock Alert',
  'WARNING',
  'inventory_management',
  format('Product %s is low on stock: %s remaining', NEW.listing_id, NEW.quantity_available),
  (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
                        );

                    -- Check for out of stock
                    ELSIF NEW.quantity_available = 0 AND NEW.out_of_stock_alert_sent = FALSE THEN
                        NEW.out_of_stock_alert_sent := TRUE;
                        NEW.last_alert_at := CURRENT_TIMESTAMP;

                        INSERT INTO socialcandor_schema.anomaly_alerts (
  alert_name, severity, source_system, description, created_by
                        ) VALUES (
  'Out of Stock Alert',
  'ERROR',
  'inventory_management',
  format('Product %s is out of stock', NEW.listing_id),
  (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
                        );
                    END IF;

                    RETURN NEW;
                END;
                $$ LANGUAGE plpgsql;

                CREATE TRIGGER trg_product_inventory_check
                    BEFORE INSERT OR UPDATE OF quantity_on_hand, quantity_reserved
                    ON socialcandor_schema.product_inventory
                    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_inventory_levels();

                -- RLS Policy
                ALTER TABLE socialcandor_schema.product_inventory ENABLE ROW LEVEL SECURITY;
                CREATE POLICY product_inventory_seller_policy ON socialcandor_schema.product_inventory
                    FOR ALL USING (listing_id IN (
                        SELECT listing_id FROM socialcandor_schema.marketplace_listings
                        WHERE seller_profile_id IN (
  SELECT seller_profile_id FROM socialcandor_schema.seller_profiles
  WHERE user_id = current_setting('app.current_user_id')::UUID
                        )
                    ));
                CREATE POLICY product_inventory_admin_policy ON socialcandor_schema.product_inventory
                    FOR ALL USING (socialcandor_schema.is_admin());


                    --================================================================================================
                    -- Table: EC04 - user_cart
                    -- Description: Manages shopping carts for users, supporting abandoned cart recovery and
                    --              cross-session persistence. Enables seamless shopping experience across devices.
                    -- Business Case: Shopping carts are the foundation of e-commerce conversion. This table
                    --                persists cart state across sessions and devices, enabling users to start
                    --                shopping on one device and complete on another. Abandoned cart tracking
                    --                enables recovery campaigns (email reminders, discounts) that can recover
                    --                10-15% of lost revenue. The design supports cart expiration to prevent
                    --                inventory blocking, with configurable timeouts. Multiple carts per user
                    --                are possible (e.g., wishlist vs. active cart) with a clear active flag.
                    --
                    -- Key Performance Indicators (KPIs):
                    --   1. Cart abandonment rate - Percentage of carts not converted to orders
                    --   2. Cart recovery rate - Percentage of abandoned carts recovered via campaigns
                    --   3. Average cart value - Mean value of items in cart
                    --   4. Cart to checkout ratio - Percentage of carts proceeding to checkout
                    --   5. Cart age - Average time from creation to checkout/abandonment
                    --
                    -- Feature References:
                    --   - ORD02 (Shopping Cart)
                    --   - ORD03 (Cart Persistence)
                    --   - MKT04 (Abandoned Cart Recovery)
                    --   - UX01 (User Experience)
                    --================================================================================================
                    CREATE TABLE IF NOT EXISTS socialcandor_schema.user_cart (
                        -- Primary key
                        cart_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                        -- Human-readable identifier
                        cart_number VARCHAR(50) GENERATED ALWAYS AS (
  'CART-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_cart_seq')::TEXT, 6, '0')
                        ) STORED,

                        -- References
                        user_id UUID NOT NULL,
                        session_id UUID,               -- For anonymous carts

                        -- Cart metadata
                        cart_name VARCHAR(100) DEFAULT 'Default Cart',
                        cart_type VARCHAR(30) DEFAULT 'SHOPPING' CHECK (cart_type IN (
  'SHOPPING', 'WISHLIST', 'SAVED_FOR_LATER', 'GIFT_REGISTRY'
                        )),

                        -- Status
                        is_active BOOLEAN DEFAULT TRUE,
                        is_converted BOOLEAN DEFAULT FALSE,                      -- Converted to order
                        converted_to_order_id UUID,

                        -- Expiration
                        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                        expires_at TIMESTAMP WITH TIME ZONE,                      -- Cart expiration
                        abandoned_at TIMESTAMP WITH TIME ZONE,                    -- When cart was abandoned

                        -- Recovery tracking
                        recovery_email_sent BOOLEAN DEFAULT FALSE,
                        recovery_email_sent_at TIMESTAMP WITH TIME ZONE,
                        recovery_discount_applied BOOLEAN DEFAULT FALSE,
                        recovery_discount_code VARCHAR(50),

                        -- Cart summary (denormalized for performance)
                        item_count INTEGER DEFAULT 0 CHECK (item_count >= 0),
                        subtotal NUMERIC(15,2) DEFAULT 0 CHECK (subtotal >= 0),
                        total_discount NUMERIC(15,2) DEFAULT 0 CHECK (total_discount >= 0),
                        total NUMERIC(15,2) DEFAULT 0 CHECK (total >= 0),
                        currency CHAR(3) DEFAULT 'USD',

                        -- Audit columns
                        created_by UUID NOT NULL,
                        updated_by UUID DEFAULT uuid_nil(),

                        -- Constraints
                        CONSTRAINT fk_user_cart_user FOREIGN KEY (user_id)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                        CONSTRAINT fk_user_cart_session FOREIGN KEY (session_id)
  REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_cart_converted_order FOREIGN KEY (converted_to_order_id)
  REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
                        CONSTRAINT fk_user_cart_created_by FOREIGN KEY (created_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                        CONSTRAINT fk_user_cart_updated_by FOREIGN KEY (updated_by)
  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                        CONSTRAINT chk_user_cart_expiry CHECK (expires_at IS NULL OR expires_at > created_at),
                        CONSTRAINT uk_user_cart_active UNIQUE (user_id, cart_type) WHERE is_active = TRUE AND cart_type = 'SHOPPING'
                    );

                    -- Comments
                    COMMENT ON TABLE socialcandor_schema.user_cart IS 'Shopping cart management with persistence across sessions and abandoned cart recovery';
                    COMMENT ON COLUMN socialcandor_schema.user_cart.session_id IS 'Session ID for anonymous carts before user login';
                    COMMENT ON COLUMN socialcandor_schema.user_cart.recovery_email_sent IS 'Whether abandoned cart recovery email has been sent';
                    COMMENT ON COLUMN socialcandor_schema.user_cart.recovery_discount_applied IS 'Whether a recovery discount was applied to encourage conversion';

                    -- Indexes for performance
                    CREATE INDEX idx_user_cart_user ON socialcandor_schema.user_cart(user_id, cart_type, is_active) WHERE is_active = TRUE;
                    CREATE INDEX idx_user_cart_session ON socialcandor_schema.user_cart(session_id) WHERE session_id IS NOT NULL AND is_active = TRUE;
                    CREATE INDEX idx_user_cart_abandoned ON socialcandor_schema.user_cart(abandoned_at) WHERE abandoned_at IS NOT NULL AND recovery_email_sent = FALSE;
                    CREATE INDEX idx_user_cart_expires ON socialcandor_schema.user_cart(expires_at) WHERE expires_at IS NOT NULL;

                    -- Trigger for updated_at
                    CREATE TRIGGER trg_user_cart_updated_at
                        BEFORE UPDATE ON socialcandor_schema.user_cart
                        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                    -- RLS Policy
                    ALTER TABLE socialcandor_schema.user_cart ENABLE ROW LEVEL SECURITY;
                    CREATE POLICY user_cart_self_policy ON socialcandor_schema.user_cart
                        FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
                    CREATE POLICY user_cart_admin_policy ON socialcandor_schema.user_cart
                        FOR ALL USING (socialcandor_schema.is_admin());


                        --================================================================================================
                        -- Table: EC05 - cart_items
                        -- Description: Line items in shopping carts, tracking product, quantity, price at time of addition,
                        --              and applied discounts. Supports cart modifications and price guarantees.
                        -- Business Case: Cart items represent the actual products users intend to purchase. This table
                        --                captures the product, quantity, and crucially, the price at the time of addition
                        --                (price guarantee). This prevents price disputes if the product price changes
                        --                while the item is in the cart. The design supports variant selection, custom
                        --                notes (gift messages), and item-level discounts. Real-time inventory checks
                        --                during addition prevent overselling. The schema enables complex cart operations
                        --                like bundle deals and multi-item promotions.
                        --
                        -- Key Performance Indicators (KPIs):
                        --   1. Items per cart - Average number of items in active carts
                        --   2. Cart abandonment by item - Products most frequently abandoned
                        --   3. Price change impact - Percentage of cart items affected by price changes
                        --   4. Variant selection - Distribution of variant choices
                        --   5. Cart modification rate - Frequency of cart updates before checkout
                        --
                        -- Feature References:
                        --   - ORD04 (Cart Items)
                        --   - ORD05 (Price Guarantee)
                        --   - INV05 (Inventory Reservation)
                        --   - PRO01 (Promotions)
                        --================================================================================================
                        CREATE TABLE IF NOT EXISTS socialcandor_schema.cart_items (
  -- Primary key
  cart_item_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

  -- Human-readable identifier
  cart_item_number VARCHAR(50) GENERATED ALWAYS AS (
      'CITM-' || TO_CHAR(added_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.cart_items_seq')::TEXT, 6, '0')
  ) STORED,

  -- References
  cart_id UUID NOT NULL,
  listing_id UUID NOT NULL,
  variant_id UUID,
  seller_profile_id UUID NOT NULL,

  -- Item details
  quantity INTEGER NOT NULL CHECK (quantity > 0 AND quantity <= 999),

  -- Pricing at time of addition (price guarantee)
  unit_price NUMERIC(15,2) NOT NULL CHECK (unit_price >= 0),
  compare_at_price NUMERIC(15,2), -- Original/MSRP for showing discount
  total_price NUMERIC(15,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
  currency CHAR(3) NOT NULL DEFAULT 'USD',

  -- Discounts
  discount_amount NUMERIC(15,2) DEFAULT 0 CHECK (discount_amount >= 0),
  discount_percentage NUMERIC(5,2) CHECK (discount_percentage >= 0 AND discount_percentage <= 100),
  discount_code_id UUID,
  final_price NUMERIC(15,2) GENERATED ALWAYS AS (total_price - discount_amount) STORED,

  -- Product snapshot (in case product details change)
  product_snapshot JSONB,          -- Name, image, description at time of addition

  -- Customization
  custom_notes TEXT,
  gift_wrap BOOLEAN DEFAULT FALSE,
  gift_message TEXT,

  -- Dates
  added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

  -- Inventory reservation
  inventory_reserved BOOLEAN DEFAULT TRUE,
  reservation_expires_at TIMESTAMP WITH TIME ZONE,

  -- Audit columns
  created_by UUID NOT NULL,
  updated_by UUID DEFAULT uuid_nil(),

  -- Constraints
  CONSTRAINT fk_cart_items_cart FOREIGN KEY (cart_id)
      REFERENCES socialcandor_schema.user_cart(cart_id) ON DELETE CASCADE,
  CONSTRAINT fk_cart_items_listing FOREIGN KEY (listing_id)
      REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE RESTRICT,
  CONSTRAINT fk_cart_items_variant FOREIGN KEY (variant_id)
      REFERENCES socialcandor_schema.product_variants(variant_id) ON DELETE RESTRICT,
  CONSTRAINT fk_cart_items_seller FOREIGN KEY (seller_profile_id)
      REFERENCES socialcandor_schema.seller_profiles(seller_profile_id) ON DELETE RESTRICT,
  CONSTRAINT fk_cart_items_discount FOREIGN KEY (discount_code_id)
      REFERENCES socialcandor_schema.promo_codes(promo_id) ON DELETE SET NULL,
  CONSTRAINT fk_cart_items_created_by FOREIGN KEY (created_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
  CONSTRAINT fk_cart_items_updated_by FOREIGN KEY (updated_by)
      REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

  CONSTRAINT uk_cart_item UNIQUE (cart_id, listing_id, variant_id)
                        );

                        -- Comments
                        COMMENT ON TABLE socialcandor_schema.cart_items IS 'Line items in shopping carts with price guarantee and inventory reservation';
                        COMMENT ON COLUMN socialcandor_schema.cart_items.unit_price IS 'Price at time of addition (price guarantee)';
                        COMMENT ON COLUMN socialcandor_schema.cart_items.product_snapshot IS 'Snapshot of product details at time of addition for historical accuracy';
                        COMMENT ON COLUMN socialcandor_schema.cart_items.inventory_reserved IS 'Whether inventory has been reserved for this item';

                        -- Indexes for performance
                        CREATE INDEX idx_cart_items_cart ON socialcandor_schema.cart_items(cart_id);
                        CREATE INDEX idx_cart_items_listing ON socialcandor_schema.cart_items(listing_id, variant_id);
                        CREATE INDEX idx_cart_items_seller ON socialcandor_schema.cart_items(seller_profile_id);
                        CREATE INDEX idx_cart_items_reservation ON socialcandor_schema.cart_items(reservation_expires_at) WHERE inventory_reserved = TRUE;

                        -- Trigger for updated_at
                        CREATE TRIGGER trg_cart_items_updated_at
  BEFORE UPDATE ON socialcandor_schema.cart_items
  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                        -- Function to reserve inventory when adding to cart
                        CREATE OR REPLACE FUNCTION socialcandor_schema.reserve_inventory_for_cart()
                        RETURNS TRIGGER AS $$
                        DECLARE
  v_available INTEGER;
                        BEGIN
  -- Check inventory availability
  IF NEW.variant_id IS NOT NULL THEN
      SELECT quantity_available INTO v_available
      FROM socialcandor_schema.product_inventory
      WHERE variant_id = NEW.variant_id;
  ELSE
      SELECT quantity_available INTO v_available
      FROM socialcandor_schema.product_inventory
      WHERE listing_id = NEW.listing_id AND variant_id IS NULL;
  END IF;

  -- If insufficient inventory, raise error
  IF v_available < NEW.quantity THEN
      RAISE EXCEPTION 'Insufficient inventory available for this product. Requested: %, Available: %',
          NEW.quantity, v_available;
  END IF;

  -- Update inventory to reserve stock
  IF NEW.variant_id IS NOT NULL THEN
      UPDATE socialcandor_schema.product_inventory
      SET quantity_reserved = quantity_reserved + NEW.quantity
      WHERE variant_id = NEW.variant_id;
  ELSE
      UPDATE socialcandor_schema.product_inventory
      SET quantity_reserved = quantity_reserved + NEW.quantity
      WHERE listing_id = NEW.listing_id AND variant_id IS NULL;
  END IF;

  -- Set reservation expiration (30 minutes by default)
  NEW.reservation_expires_at := CURRENT_TIMESTAMP + INTERVAL '30 minutes';

  RETURN NEW;
                        END;
                        $$ LANGUAGE plpgsql;

                        CREATE TRIGGER trg_cart_items_reserve
  BEFORE INSERT ON socialcandor_schema.cart_items
  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.reserve_inventory_for_cart();

                        -- RLS Policy
                        ALTER TABLE socialcandor_schema.cart_items ENABLE ROW LEVEL SECURITY;
                        CREATE POLICY cart_items_self_policy ON socialcandor_schema.cart_items
  FOR ALL USING (cart_id IN (
      SELECT cart_id FROM socialcandor_schema.user_cart WHERE user_id = current_setting('app.current_user_id')::UUID
  ));
                        CREATE POLICY cart_items_admin_policy ON socialcandor_schema.cart_items
  FOR ALL USING (socialcandor_schema.is_admin());


  --================================================================================================
  -- Table: EC06 - order_items
  -- Description: Line items within confirmed orders, capturing product details, pricing,
  --              fulfillment status, and refund tracking. Supports order management and accounting.
  -- Business Case: Once an order is placed, items move from cart to order_items for permanent
  --                record-keeping. This table captures the finalized transaction details,
  --                including the price at time of purchase (critical for accounting and disputes).
  --                Individual item fulfillment tracking enables partial shipments and returns.
  --                Refund tracking at the item level supports partial refunds and return processing.
  --                The design includes tax and shipping apportionment for accurate financials.
  --                Historical snapshots ensure order integrity even if products are later modified.
  --
  -- Key Performance Indicators (KPIs):
  --   1. Average items per order - Mean number of items in completed orders
  --   2. Fulfillment rate by item - Percentage of items successfully delivered
  --   3. Return rate by product - Products with highest return rates
  --   4. Average item price - Mean price of ordered items
  --   5. Item cancellation rate - Percentage of order items cancelled
  --
  -- Feature References:
  --   - ORD06 (Order Fulfillment)
  --   - ORD07 (Returns Management)
  --   - FIN03 (Revenue Recognition)
  --   - ACC05 (Order Accounting)
  --================================================================================================
  CREATE TABLE IF NOT EXISTS socialcandor_schema.order_items (
      -- Primary key
      order_item_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

      -- Human-readable identifier
      order_item_number VARCHAR(50) GENERATED ALWAYS AS (
          'OITM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.order_items_seq')::TEXT, 6, '0')
      ) STORED,

      -- References
      order_id UUID NOT NULL,
      listing_id UUID NOT NULL,
      variant_id UUID,
      seller_profile_id UUID NOT NULL,

      -- Order identification (denormalized for performance)
      order_number VARCHAR(50),
      buyer_user_id UUID,

      -- Item details at time of purchase (snapshot)
      sku VARCHAR(100),
      product_name VARCHAR(255) NOT NULL,
      product_description TEXT,
      product_image_url VARCHAR(500),
      variant_attributes JSONB,

      -- Quantity and pricing
      quantity INTEGER NOT NULL CHECK (quantity > 0),
      unit_price NUMERIC(15,2) NOT NULL CHECK (unit_price >= 0),
      subtotal NUMERIC(15,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
      discount_amount NUMERIC(15,2) DEFAULT 0 CHECK (discount_amount >= 0),
      tax_amount NUMERIC(15,2) DEFAULT 0 CHECK (tax_amount >= 0),
      shipping_amount NUMERIC(15,2) DEFAULT 0 CHECK (shipping_amount >= 0),
      total_amount NUMERIC(15,2) GENERATED ALWAYS AS (subtotal - discount_amount + tax_amount + shipping_amount) STORED,
      currency CHAR(3) NOT NULL,

      -- Cost and profit (for seller reporting)
      cost_amount NUMERIC(15,2) CHECK (cost_amount >= 0),
      profit_amount NUMERIC(15,2) GENERATED ALWAYS AS (subtotal - cost_amount) STORED,
      platform_fee NUMERIC(15,2) DEFAULT 0 CHECK (platform_fee >= 0),
      seller_payout_amount NUMERIC(15,2) GENERATED ALWAYS AS (subtotal - platform_fee) STORED,

      -- Fulfillment status
      fulfillment_status VARCHAR(30) DEFAULT 'PENDING' CHECK (fulfillment_status IN (
          'PENDING', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'RETURNED', 'REPLACED', 'CANCELLED'
      )),
      tracking_number VARCHAR(100),
      carrier VARCHAR(50),
      shipped_at TIMESTAMP WITH TIME ZONE,
      delivered_at TIMESTAMP WITH TIME ZONE,

      -- Return/Refund status
      return_status VARCHAR(30) CHECK (return_status IN (
          'NOT_RETURNED', 'REQUESTED', 'APPROVED', 'RECEIVED', 'REFUNDED', 'REJECTED'
      )),
      return_reason TEXT,
      return_requested_at TIMESTAMP WITH TIME ZONE,
      return_approved_at TIMESTAMP WITH TIME ZONE,
      refund_amount NUMERIC(15,2) CHECK (refund_amount >= 0),
      refunded_at TIMESTAMP WITH TIME ZONE,

      -- Gift options
      is_gift BOOLEAN DEFAULT FALSE,
      gift_message TEXT,

      -- Audit columns
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
      created_by UUID NOT NULL,
      updated_by UUID DEFAULT uuid_nil(),

      -- Constraints
      CONSTRAINT fk_order_items_order FOREIGN KEY (order_id)
          REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE CASCADE,
      CONSTRAINT fk_order_items_listing FOREIGN KEY (listing_id)
          REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE RESTRICT,
      CONSTRAINT fk_order_items_variant FOREIGN KEY (variant_id)
          REFERENCES socialcandor_schema.product_variants(variant_id) ON DELETE RESTRICT,
      CONSTRAINT fk_order_items_seller FOREIGN KEY (seller_profile_id)
          REFERENCES socialcandor_schema.seller_profiles(seller_profile_id) ON DELETE RESTRICT,
      CONSTRAINT fk_order_items_buyer FOREIGN KEY (buyer_user_id)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
      CONSTRAINT fk_order_items_created_by FOREIGN KEY (created_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
      CONSTRAINT fk_order_items_updated_by FOREIGN KEY (updated_by)
          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

      CONSTRAINT chk_order_items_refund CHECK (
          (refund_amount IS NULL) OR (refund_amount <= total_amount)
      )
  );

  -- Comments
  COMMENT ON TABLE socialcandor_schema.order_items IS 'Line items within orders with fulfillment tracking and accounting details';
  COMMENT ON COLUMN socialcandor_schema.order_items.product_name IS 'Snapshot of product name at time of purchase';
  COMMENT COLUMN socialcandor_schema.order_items.cost_amount IS 'Seller''s cost for the item (for profit calculation)';
  COMMENT ON COLUMN socialcandor_schema.order_items.platform_fee IS 'Platform fee for the item';
  COMMENT ON COLUMN socialcandor_schema.order_items.seller_payout_amount IS 'Amount payable to seller after fees';

  -- Indexes for performance
  CREATE INDEX idx_order_items_order ON socialcandor_schema.order_items(order_id);
  CREATE INDEX idx_order_items_seller ON socialcandor_schema.order_items(seller_profile_id, created_at DESC);
  CREATE INDEX idx_order_items_listing ON socialcandor_schema.order_items(listing_id, variant_id);
  CREATE INDEX idx_order_items_fulfillment ON socialcandor_schema.order_items(fulfillment_status, shipped_at)
      WHERE fulfillment_status IN ('PENDING', 'PROCESSING');
  CREATE INDEX idx_order_items_return ON socialcandor_schema.order_items(return_status) WHERE return_status != 'NOT_RETURNED';

  -- Trigger for updated_at
  CREATE TRIGGER trg_order_items_updated_at
      BEFORE UPDATE ON socialcandor_schema.order_items
      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

  -- RLS Policy
  ALTER TABLE socialcandor_schema.order_items ENABLE ROW LEVEL SECURITY;
  CREATE POLICY order_items_buyer_policy ON socialcandor_schema.order_items
      FOR SELECT USING (buyer_user_id = current_setting('app.current_user_id')::UUID);
  CREATE POLICY order_items_seller_policy ON socialcandor_schema.order_items
      FOR SELECT USING (seller_profile_id IN (
          SELECT seller_profile_id FROM socialcandor_schema.seller_profiles WHERE user_id = current_setting('app.current_user_id')::UUID
      ));
  CREATE POLICY order_items_admin_policy ON socialcandor_schema.order_items
      FOR ALL USING (socialcandor_schema.is_admin());

      --================================================================================================
      -- Table: EC07 - user_wishlist
      -- Description: Allows users to save products for future purchase, with price tracking
      --              and notification options. Supports re-engagement and gift registry features.
      -- Business Case: Wishlists are powerful engagement tools, allowing users to save items
      --                they're interested in but not ready to purchase. This drives return visits
      --                and enables targeted marketing (price drop alerts, back-in-stock notifications).
      --                The design supports multiple wishlist types (personal, gift registry, shared)
      --                and tracks price history for alerting. Integration with inventory enables
      --                stock alerts. Wishlists can be shared (with privacy controls) for gift-giving
      --                occasions, expanding social commerce capabilities.
      --
      -- Key Performance Indicators (KPIs):
      --   1. Wishlist adoption - Percentage of users with active wishlists
      --   2. Items per wishlist - Average number of saved items
      --   3. Conversion rate - Percentage of wishlist items eventually purchased
      --   4. Price drop alerts - Number of notifications sent per month
      --   5. Wishlist sharing rate - Percentage of wishlists shared with others
      --
      -- Feature References:
      --   - MPL11 (Wishlist)
      --   - MKT05 (Price Alerts)
      --   - SOC18 (Social Shopping)
      --   - NOTIFY04 (Wishlist Notifications)
      --================================================================================================
      CREATE TABLE IF NOT EXISTS socialcandor_schema.user_wishlist (
          -- Primary key
          wishlist_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

          -- Human-readable identifier
          wishlist_number VARCHAR(50) GENERATED ALWAYS AS (
              'WISH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_wishlist_seq')::TEXT, 6, '0')
          ) STORED,

          -- References
          user_id UUID NOT NULL,
          listing_id UUID NOT NULL,
          variant_id UUID,

          -- Wishlist metadata
          wishlist_name VARCHAR(100) DEFAULT 'My Wishlist',
          wishlist_type VARCHAR(30) DEFAULT 'PERSONAL' CHECK (wishlist_type IN (
              'PERSONAL', 'GIFT_REGISTRY', 'BABY_REGISTRY', 'WEDDING_REGISTRY', 'SHARED'
          )),

          -- Item details at time of saving
          added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
          price_at_add NUMERIC(15,2),     -- Price when added
          notes TEXT,                      -- User notes about the item

          -- Priority
          priority INTEGER DEFAULT 5 CHECK (priority >= 1 AND priority <= 10), -- 1=highest, 10=lowest
          desired_quantity INTEGER DEFAULT 1 CHECK (desired_quantity >= 1),
          purchased_quantity INTEGER DEFAULT 0 CHECK (purchased_quantity >= 0),

          -- Alerts
          alert_on_price_drop BOOLEAN DEFAULT FALSE,
          alert_on_back_in_stock BOOLEAN DEFAULT FALSE,
          price_drop_threshold NUMERIC(5,2),                        -- Percentage drop to trigger alert
          last_alert_sent_at TIMESTAMP WITH TIME ZONE,

          -- Sharing
          is_public BOOLEAN DEFAULT FALSE,
          share_token VARCHAR(255),        -- For unlisted sharing
          shared_with_emails TEXT[],       -- Shared with specific people

          -- Gift registry fields
          registry_event_date DATE,
          registry_event_name VARCHAR(255),

          -- Status
          is_active BOOLEAN DEFAULT TRUE,
          purchased_at TIMESTAMP WITH TIME ZONE,
          removed_at TIMESTAMP WITH TIME ZONE,

          -- Audit columns
          created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
          created_by UUID NOT NULL,
          updated_by UUID DEFAULT uuid_nil(),

          -- Constraints
          CONSTRAINT fk_user_wishlist_user FOREIGN KEY (user_id)
              REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
          CONSTRAINT fk_user_wishlist_listing FOREIGN KEY (listing_id)
              REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE CASCADE,
          CONSTRAINT fk_user_wishlist_variant FOREIGN KEY (variant_id)
              REFERENCES socialcandor_schema.product_variants(variant_id) ON DELETE CASCADE,
          CONSTRAINT fk_user_wishlist_created_by FOREIGN KEY (created_by)
              REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
          CONSTRAINT fk_user_wishlist_updated_by FOREIGN KEY (updated_by)
              REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

          CONSTRAINT uk_user_wishlist UNIQUE (user_id, listing_id, variant_id)
      );

      -- Comments
      COMMENT ON TABLE socialcandor_schema.user_wishlist IS 'User wishlists for saving products with price tracking and notifications';
      COMMENT ON COLUMN socialcandor_schema.user_wishlist.wishlist_type IS 'Type of wishlist (personal, gift registry, etc.)';
      COMMENT ON COLUMN socialcandor_schema.user_wishlist.price_at_add IS 'Price when item was added for tracking price drops';
      COMMENT ON COLUMN socialcandor_schema.user_wishlist.share_token IS 'Unique token for unlisted sharing of wishlist';

      -- Indexes for performance
      CREATE INDEX idx_user_wishlist_user ON socialcandor_schema.user_wishlist(user_id, wishlist_type);
      CREATE INDEX idx_user_wishlist_listing ON socialcandor_schema.user_wishlist(listing_id, variant_id);
      CREATE INDEX idx_user_wishlist_alerts ON socialcandor_schema.user_wishlist(
          alert_on_price_drop, alert_on_back_in_stock
      ) WHERE alert_on_price_drop = TRUE OR alert_on_back_in_stock = TRUE;
      CREATE INDEX idx_user_wishlist_share ON socialcandor_schema.user_wishlist(share_token) WHERE is_public = FALSE AND share_token IS NOT NULL;

      -- Trigger for updated_at
      CREATE TRIGGER trg_user_wishlist_updated_at
          BEFORE UPDATE ON socialcandor_schema.user_wishlist
          FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

      -- Function to check price drops
      CREATE OR REPLACE FUNCTION socialcandor_schema.check_wishlist_price_drops()
      RETURNS TRIGGER AS $$
      DECLARE
          v_current_price NUMERIC(15,2);
          v_price_drop_percent NUMERIC(5,2);
      BEGIN
          -- Get current price from listing
          SELECT price INTO v_current_price
          FROM socialcandor_schema.marketplace_listings
          WHERE listing_id = NEW.listing_id;

          -- Calculate price drop percentage if price has decreased
          IF v_current_price < NEW.price_at_add THEN
              v_price_drop_percent := ((NEW.price_at_add - v_current_price) / NEW.price_at_add) * 100;

              -- Check if price drop meets or exceeds threshold
              IF NEW.alert_on_price_drop AND
                 (NEW.price_drop_threshold IS NULL OR v_price_drop_percent >= NEW.price_drop_threshold) THEN
                  -- Insert notification (simplified - would use notification system)
                  INSERT INTO socialcandor_schema.notifications (
                      user_id, notification_type, title, message, created_by
                  ) VALUES (
                      NEW.user_id,
                      'PRICE_DROP_ALERT',
                      'Price Drop Alert!',
                      format('An item in your wishlist has dropped by %s%%', v_price_drop_percent),
                      (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
                  );

                  NEW.last_alert_sent_at := CURRENT_TIMESTAMP;
              END IF;
          END IF;

          RETURN NEW;
      END;
      $$ LANGUAGE plpgsql;

      -- RLS Policy
      ALTER TABLE socialcandor_schema.user_wishlist ENABLE ROW LEVEL SECURITY;
      CREATE POLICY user_wishlist_self_policy ON socialcandor_schema.user_wishlist
          FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
      CREATE POLICY user_wishlist_shared_policy ON socialcandor_schema.user_wishlist
          FOR SELECT USING (
              is_public = TRUE OR
              current_setting('app.current_user_email') = ANY(shared_with_emails) OR
              share_token = current_setting('app.current_share_token')
          );
      CREATE POLICY user_wishlist_admin_policy ON socialcandor_schema.user_wishlist
          FOR ALL USING (socialcandor_schema.is_admin());

          --================================================================================================
          -- Table: EC08 - user_gift_cards
          -- Description: Manages gift card issuance, balance tracking, and redemptions. Supports
          --              multiple currencies and expiration policies. Enables gifting and promotions.
          -- Business Case: Gift cards are a significant revenue stream and customer acquisition tool.
          --                This table tracks the entire gift card lifecycle: issuance (purchase),
          --                balance management, redemptions, and expiration. The design supports
          --                partial redemption across multiple orders, with real-time balance updates.
          --                Expiration policies comply with regional regulations (some jurisdictions
          --                prohibit expiration). Integration with order system enables seamless
          --                redemption at checkout. Gift cards can be purchased for others, with
          --                delivery via email or physical card.
          --
          -- Key Performance Indicators (KPIs):
          --   1. Gift card sales - Revenue from gift card purchases
          --   2. Redemption rate - Percentage of gift card value redeemed
          --   3. Breakage rate - Percentage of gift card value unredeemed (expired/lost)
          --   4. Average gift card value - Mean value of purchased gift cards
          --   5. Redemption velocity - Time from issuance to first redemption
          --
          -- Feature References:
          --   - PAY09 (Gift Cards)
          --   - PAY10 (Gift Card Redemption)
          --   - MKT06 (Gift Card Promotions)
          --   - ACC06 (Gift Card Liability)
          --================================================================================================
          CREATE TABLE IF NOT EXISTS socialcandor_schema.user_gift_cards (
              -- Primary key
              gift_card_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

              -- Human-readable identifier
              gift_card_number VARCHAR(50) GENERATED ALWAYS AS (
                  'GC-' || TO_CHAR(issued_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_gift_cards_seq')::TEXT, 6, '0')
              ) STORED,

              -- Gift card identification
              code VARCHAR(100) UNIQUE NOT NULL,
              pin VARCHAR(10),                -- For physical cards with PIN

              -- Owner (who purchased)
              purchaser_user_id UUID NOT NULL,

              -- Recipient (who can redeem)
              recipient_user_id UUID,         -- NULL if unassigned
              recipient_email VARCHAR(255),   -- For email delivery
              recipient_name VARCHAR(255),    -- For physical cards

              -- Gift card details
              design_id UUID,                 -- Card design template
              personal_message TEXT,
              delivery_method VARCHAR(30) CHECK (delivery_method IN ('EMAIL', 'PHYSICAL', 'DIGITAL_WALLET')),

              -- Value
              initial_balance NUMERIC(15,2) NOT NULL CHECK (initial_balance > 0),
              current_balance NUMERIC(15,2) NOT NULL CHECK (current_balance >= 0),
              currency CHAR(3) NOT NULL DEFAULT 'USD',

              -- Dates
              issued_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
              activated_at TIMESTAMP WITH TIME ZONE,
              expires_at TIMESTAMP WITH TIME ZONE,
              redeemed_at TIMESTAMP WITH TIME ZONE,                      -- When fully redeemed
              cancelled_at TIMESTAMP WITH TIME ZONE,

              -- Status
              status VARCHAR(30) DEFAULT 'ISSUED' CHECK (status IN (
                  'ISSUED', 'ACTIVE', 'PARTIALLY_REDEEMED', 'FULLY_REDEEMED', 'EXPIRED', 'CANCELLED'
              )),

              -- Restrictions
              restricted_to_categories TEXT[],                          -- Limit to specific product categories
              restricted_to_sellers UUID[],   -- Limit to specific sellers
              minimum_purchase_amount NUMERIC(15,2),                     -- Minimum order value to use

              -- Transaction tracking
              order_id UUID,                   -- Order that purchased this card
              transaction_id UUID,             -- Payment transaction

              -- Redemption summary
              total_redeemed NUMERIC(15,2) DEFAULT 0,
              redemption_count INTEGER DEFAULT 0,
              last_redemption_at TIMESTAMP WITH TIME ZONE,

              -- Audit columns
              created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
              created_by UUID NOT NULL,
              updated_by UUID DEFAULT uuid_nil(),

              -- Constraints
              CONSTRAINT fk_gift_cards_purchaser FOREIGN KEY (purchaser_user_id)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
              CONSTRAINT fk_gift_cards_recipient_user FOREIGN KEY (recipient_user_id)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
              CONSTRAINT fk_gift_cards_order FOREIGN KEY (order_id)
                  REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
              CONSTRAINT fk_gift_cards_transaction FOREIGN KEY (transaction_id)
                  REFERENCES socialcandor_schema.wallet_transactions(transaction_id) ON DELETE SET NULL,
              CONSTRAINT fk_gift_cards_created_by FOREIGN KEY (created_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
              CONSTRAINT fk_gift_cards_updated_by FOREIGN KEY (updated_by)
                  REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

              CONSTRAINT chk_gift_cards_balance CHECK (current_balance <= initial_balance),
              CONSTRAINT chk_gift_cards_dates CHECK (expires_at IS NULL OR expires_at > issued_at)
          );

          -- Comments
          COMMENT ON TABLE socialcandor_schema.user_gift_cards IS 'Gift card management with balance tracking and redemption';
          COMMENT ON COLUMN socialcandor_schema.user_gift_cards.code IS 'Unique gift card code for redemption';
          COMMENT ON COLUMN socialcandor_schema.user_gift_cards.recipient_user_id IS 'User ID if gift card is assigned to a registered user';
          COMMENT ON COLUMN socialcandor_schema.user_gift_cards.current_balance IS 'Remaining balance for partial redemptions';

          -- Indexes for performance
          CREATE INDEX idx_gift_cards_code ON socialcandor_schema.user_gift_cards(code);
          CREATE INDEX idx_gift_cards_recipient ON socialcandor_schema.user_gift_cards(recipient_user_id) WHERE recipient_user_id IS NOT NULL;
          CREATE INDEX idx_gift_cards_status ON socialcandor_schema.user_gift_cards(status, expires_at) WHERE status IN ('ACTIVE', 'PARTIALLY_REDEEMED');
          CREATE INDEX idx_gift_cards_purchaser ON socialcandor_schema.user_gift_cards(purchaser_user_id);

          -- Trigger for updated_at
          CREATE TRIGGER trg_user_gift_cards_updated_at
              BEFORE UPDATE ON socialcandor_schema.user_gift_cards
              FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

          -- RLS Policy
          ALTER TABLE socialcandor_schema.user_gift_cards ENABLE ROW LEVEL SECURITY;
          CREATE POLICY gift_cards_purchaser_policy ON socialcandor_schema.user_gift_cards
              FOR ALL USING (purchaser_user_id = current_setting('app.current_user_id')::UUID);
          CREATE POLICY gift_cards_recipient_policy ON socialcandor_schema.user_gift_cards
              FOR SELECT USING (recipient_user_id = current_setting('app.current_user_id')::UUID);
          CREATE POLICY gift_cards_admin_policy ON socialcandor_schema.user_gift_cards
              FOR ALL USING (socialcandor_schema.is_admin());


              --================================================================================================
              -- Table: EC09 - gift_card_transactions
              -- Description: Complete audit trail of gift card activity (issuance, redemptions, adjustments,
              --              expiration). Supports financial reconciliation and dispute resolution.
              -- Business Case: Gift cards represent financial liability and require meticulous tracking
              --                for accounting and audit purposes. This ledger records every transaction
              --                affecting gift card balances: initial issuance, redemptions (partial/full),
              --                refunds back to gift card, administrative adjustments, and expiration.
              --                The immutable transaction log enables reconciliation with payment processors,
              --                supports liability calculation for financial reporting, and provides evidence
              --                for dispute resolution. Each transaction references the source (order, refund,
              --                admin action) for complete traceability.
              --
              -- Key Performance Indicators (KPIs):
              --   1. Transaction volume - Number of gift card transactions per day
              --   2. Average redemption amount - Mean value of redemption transactions
              --   3. Adjustment frequency - Number of administrative adjustments
              --   4. Expiration rate - Value of expired gift cards per month
              --   5. Reconciliation accuracy - Percentage of transactions matching payment processor records
              --
              -- Feature References:
              --   - PAY11 (Gift Card Ledger)
              --   - ACC07 (Gift Card Liability)
              --   - AUD17 (Gift Card Audit)
              --   - REC01 (Reconciliation)
              --================================================================================================
              CREATE TABLE IF NOT EXISTS socialcandor_schema.gift_card_transactions (
                  -- Primary key
                  transaction_id BIGSERIAL PRIMARY KEY,

                  -- Human-readable identifier
                  transaction_number VARCHAR(50) GENERATED ALWAYS AS (
                      'GCT-' || TO_CHAR(transaction_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.gift_card_transactions_seq')::TEXT, 6, '0')
                  ) STORED,

                  -- References
                  gift_card_id UUID NOT NULL,
                  order_id UUID,                 -- Order where redeemed
                  refund_id UUID,                -- Refund transaction

                  -- Transaction details
                  transaction_type VARCHAR(30) NOT NULL CHECK (transaction_type IN (
                      'ISSUANCE', 'REDEMPTION', 'REFUND', 'ADJUSTMENT', 'EXPIRY', 'CANCELLATION'
                  )),
                  transaction_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

                  -- Amounts
                  amount NUMERIC(15,2) NOT NULL CHECK (amount != 0),
                  balance_before NUMERIC(15,2) NOT NULL,
                  balance_after NUMERIC(15,2) NOT NULL,
                  currency CHAR(3) NOT NULL,

                  -- Context
                  description TEXT,
                  reference_number VARCHAR(100),  -- External reference
                  metadata JSONB DEFAULT '{}',

                  -- Authorization
                  performed_by UUID NOT NULL,     -- User or system
                  ip_address INET,
                  user_agent TEXT,

                  -- Reconciliation
                  reconciled BOOLEAN DEFAULT FALSE,
                  reconciled_at TIMESTAMP WITH TIME ZONE,
                  reconciliation_notes TEXT,

                  -- Audit columns
                  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

                  -- Constraints
                  CONSTRAINT fk_gift_card_tx_gift_card FOREIGN KEY (gift_card_id)
                      REFERENCES socialcandor_schema.user_gift_cards(gift_card_id) ON DELETE RESTRICT,
                  CONSTRAINT fk_gift_card_tx_order FOREIGN KEY (order_id)
                      REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
                  CONSTRAINT fk_gift_card_tx_performed_by FOREIGN KEY (performed_by)
                      REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,

                  CONSTRAINT chk_gift_card_tx_balance CHECK (
                      (balance_before - amount = balance_after) OR
                      (balance_before + ABS(amount) = balance_after AND amount < 0) OR
                      (balance_before - ABS(amount) = balance_after AND amount > 0)
                  )
              );

              -- Comments
              COMMENT ON TABLE socialcandor_schema.gift_card_transactions IS 'Complete audit trail of gift card activity for financial reconciliation';
              COMMENT ON COLUMN socialcandor_schema.gift_card_transactions.transaction_type IS 'Type of transaction affecting gift card balance';
              COMMENT ON COLUMN socialcandor_schema.gift_card_transactions.balance_before IS 'Balance before transaction';
              COMMENT ON COLUMN socialcandor_schema.gift_card_transactions.balance_after IS 'Balance after transaction';
              COMMENT ON COLUMN socialcandor_schema.gift_card_transactions.reconciled IS 'Whether transaction has been reconciled with payment processor';

              -- Indexes for performance
              CREATE INDEX idx_gift_card_tx_gift_card ON socialcandor_schema.gift_card_transactions(gift_card_id, transaction_date DESC);
              CREATE INDEX idx_gift_card_tx_order ON socialcandor_schema.gift_card_transactions(order_id) WHERE order_id IS NOT NULL;
              CREATE INDEX idx_gift_card_tx_date ON socialcandor_schema.gift_card_transactions(transaction_date DESC);
              CREATE INDEX idx_gift_card_tx_reconciled ON socialcandor_schema.gift_card_transactions(reconciled, transaction_date) WHERE reconciled = FALSE;

              -- Trigger to update gift card balance
              CREATE OR REPLACE FUNCTION socialcandor_schema.update_gift_card_balance()
              RETURNS TRIGGER AS $$
              BEGIN
                  -- Update the gift card balance
                  UPDATE socialcandor_schema.user_gift_cards
                  SET current_balance = NEW.balance_after,
                      last_redemption_at = CASE
                          WHEN NEW.transaction_type IN ('REDEMPTION', 'REFUND') THEN NEW.transaction_date
                          ELSE last_redemption_at
                      END,
                      redemption_count = CASE
                          WHEN NEW.transaction_type = 'REDEMPTION' THEN redemption_count + 1
                          ELSE redemption_count
                      END,
                      total_redeemed = CASE
                          WHEN NEW.transaction_type = 'REDEMPTION' THEN total_redeemed + NEW.amount
                          WHEN NEW.transaction_type = 'REFUND' THEN total_redeemed - NEW.amount
                          ELSE total_redeemed
                      END,
                      status = CASE
                          WHEN NEW.balance_after = 0 THEN 'FULLY_REDEEMED'
                          WHEN NEW.balance_after < initial_balance THEN 'PARTIALLY_REDEEMED'
                          ELSE status
                      END
                  WHERE gift_card_id = NEW.gift_card_id;

                  RETURN NEW;
              END;
              $$ LANGUAGE plpgsql;

              CREATE TRIGGER trg_gift_card_tx_update_balance
                  AFTER INSERT ON socialcandor_schema.gift_card_transactions
                  FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_gift_card_balance();

              -- RLS Policy
              ALTER TABLE socialcandor_schema.gift_card_transactions ENABLE ROW LEVEL SECURITY;
              CREATE POLICY gift_card_tx_self_policy ON socialcandor_schema.gift_card_transactions
                  FOR SELECT USING (gift_card_id IN (
                      SELECT gift_card_id FROM socialcandor_schema.user_gift_cards
                      WHERE purchaser_user_id = current_setting('app.current_user_id')::UUID
                         OR recipient_user_id = current_setting('app.current_user_id')::UUID
                  ));
              CREATE POLICY gift_card_tx_admin_policy ON socialcandor_schema.gift_card_transactions
                  FOR ALL USING (socialcandor_schema.is_admin());



                  --================================================================================================
                  -- Table: GM01 - user_points_history
                  -- Description: Complete ledger of user point transactions (earn, spend, expire) for
                  --              gamification and loyalty programs. Tracks balance with reason codes.
                  -- Business Case: Points-based loyalty programs drive engagement and retention. This table
                  --                maintains an immutable ledger of all point transactions, enabling users
                  --                to earn points through various actions (posts, comments, referrals) and
                  --                spend them on rewards (discounts, features, merchandise). The design
                  --                supports multiple point types (experience, loyalty, currency) with
                  --                different expiration policies. Real-time balance tracking enables
                  --                immediate feedback and spending decisions. Reason codes support analytics
                  --                to understand which behaviors drive engagement.
                  --
                  -- Key Performance Indicators (KPIs):
                  --   1. Points earned per user - Average points earned per active user
                  --   2. Redemption rate - Percentage of points earned that are redeemed
                  --   3. Point decay rate - Points expiring unredeemed
                  --   4. Action effectiveness - Points earned per action type
                  --   5. Reward popularity - Most redeemed rewards by point cost
                  --
                  -- Feature References:
                  --   - GAM06 (Points System)
                  --   - GAM07 (Loyalty Program)
                  --   - GAM08 (Point Redemption)
                  --   - ENG04 (Engagement Metrics)
                  --================================================================================================
                  CREATE TABLE IF NOT EXISTS socialcandor_schema.user_points_history (
                      -- Primary key
                      transaction_id BIGSERIAL PRIMARY KEY,

                      -- Human-readable identifier
                      transaction_number VARCHAR(50) GENERATED ALWAYS AS (
                          'PTS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_points_history_seq')::TEXT, 6, '0')
                      ) STORED,

                      -- References
                      user_id UUID NOT NULL,

                      -- Point type (multiple currencies possible)
                      point_type VARCHAR(30) DEFAULT 'LOYALTY' CHECK (point_type IN (
                          'LOYALTY', 'EXPERIENCE', 'CURRENCY', 'REPUTATION', 'BONUS'
                      )),

                      -- Transaction details
                      transaction_type VARCHAR(30) NOT NULL CHECK (transaction_type IN (
                          'EARN', 'SPEND', 'EXPIRE', 'ADJUST', 'REFUND'
                      )),
                      amount INTEGER NOT NULL CHECK (amount != 0),
                      balance_before INTEGER NOT NULL CHECK (balance_before >= 0),
                      balance_after INTEGER NOT NULL CHECK (balance_after >= 0),

                      -- Reason (what action caused the transaction)
                      reason_code VARCHAR(100) NOT NULL,
                      reason_description TEXT,
                      reference_id UUID,              -- Link to source (post_id, order_id, etc.)
                      reference_type VARCHAR(50),     -- Type of reference

                      -- Expiration
                      earned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      expires_at TIMESTAMP WITH TIME ZONE,                      -- When points expire

                      -- Context
                      ip_address INET,
                      user_agent TEXT,

                      -- Metadata
                      metadata JSONB DEFAULT '{}',

                      -- Audit columns
                      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                      created_by UUID NOT NULL,
                      updated_by UUID DEFAULT uuid_nil(),

                      -- Constraints
                      CONSTRAINT fk_points_history_user FOREIGN KEY (user_id)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                      CONSTRAINT fk_points_history_created_by FOREIGN KEY (created_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                      CONSTRAINT fk_points_history_updated_by FOREIGN KEY (updated_by)
                          REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                      CONSTRAINT chk_points_history_balance CHECK (
                          balance_after = balance_before + amount
                      ),
                      CONSTRAINT chk_points_history_expiry CHECK (
                          expires_at IS NULL OR expires_at > earned_at
                      )
                  );

                  -- Comments
                  COMMENT ON TABLE socialcandor_schema.user_points_history IS 'Complete ledger of user point transactions for gamification and loyalty';
                  COMMENT ON COLUMN socialcandor_schema.user_points_history.point_type IS 'Type of points (multiple currencies possible)';
                  COMMENT ON COLUMN socialcandor_schema.user_points_history.reason_code IS 'Code indicating what action earned/spent points';
                  COMMENT ON COLUMN socialcandor_schema.user_points_history.reference_id IS 'ID of source object (post, order, etc.)';
                  COMMENT ON COLUMN socialcandor_schema.user_points_history.expires_at IS 'When these points expire (if applicable)';

                  -- Indexes for performance
                  CREATE INDEX idx_points_history_user ON socialcandor_schema.user_points_history(user_id, created_at DESC);
                  CREATE INDEX idx_points_history_type ON socialcandor_schema.user_points_history(point_type, transaction_type);
                  CREATE INDEX idx_points_history_reason ON socialcandor_schema.user_points_history(reason_code, created_at DESC);
                  CREATE INDEX idx_points_history_reference ON socialcandor_schema.user_points_history(reference_type, reference_id)
                      WHERE reference_id IS NOT NULL;
                  CREATE INDEX idx_points_history_expires ON socialcandor_schema.user_points_history(expires_at) WHERE expires_at IS NOT NULL;

                  -- Trigger for updated_at
                  CREATE TRIGGER trg_user_points_history_updated_at
                      BEFORE UPDATE ON socialcandor_schema.user_points_history
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                  -- Function to update user's point balance (denormalized on users table)
                  CREATE OR REPLACE FUNCTION socialcandor_schema.update_user_point_balance()
                  RETURNS TRIGGER AS $$
                  BEGIN
                      -- Update user's point balance (assuming point_balance column exists)
                      UPDATE socialcandor_schema.users
                      SET point_balance = point_balance + NEW.amount,
                          total_points_earned = total_points_earned + CASE
   WHEN NEW.amount > 0 THEN NEW.amount
   ELSE 0
                          END
                      WHERE user_id = NEW.user_id;

                      RETURN NEW;
                  END;
                  $$ LANGUAGE plpgsql;

                  CREATE TRIGGER trg_points_history_update_user
                      AFTER INSERT ON socialcandor_schema.user_points_history
                      FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_user_point_balance();

                  -- RLS Policy
                  ALTER TABLE socialcandor_schema.user_points_history ENABLE ROW LEVEL SECURITY;
                  CREATE POLICY points_history_self_policy ON socialcandor_schema.user_points_history
                      FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
                  CREATE POLICY points_history_admin_policy ON socialcandor_schema.user_points_history
                      FOR ALL USING (socialcandor_schema.is_admin());


                      --================================================================================================
                      -- Table: GM02 - user_achievements
                      -- Description: Tracks user progress and completion of achievements/badges. Supports
                      --              progressive achievement tiers and rarity classification.
                      -- Business Case: Achievements and badges are powerful engagement drivers, giving users
                      --                recognition for milestones and encouraging desired behaviors. This table
                      --                tracks both progress toward achievements (for multi-step achievements)
                      --                and completion status. Rarity classifications (common to legendary) add
                      --                prestige and social value. The design supports achievement unlocking
                      --                based on various criteria (counts, streaks, specific actions) and
                      --                provides data for leaderboards and social sharing. Integration with
                      --                notifications enables real-time celebration when achievements are earned.
                      --
                      -- Key Performance Indicators (KPIs):
                      --   1. Achievement completion rate - Percentage of users completing achievements
                      --   2. Average achievements per user - Mean number of earned achievements
                      --   3. Achievement rarity distribution - Percentage of users with rare achievements
                      --   4. Time to achievement - Average time to complete specific achievements
                      --   5. Achievement impact - Engagement lift after earning achievements
                      --
                      -- Feature References:
                      --   - GAM09 (Achievements)
                      --   - GAM10 (Badges)
                      --   - GAM11 (Progression)
                      --   - SOC19 (Social Recognition)
                      --================================================================================================
                      CREATE TABLE IF NOT EXISTS socialcandor_schema.user_achievements (
                          -- Primary key
                          achievement_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                          -- Human-readable identifier
                          achievement_number VARCHAR(50) GENERATED ALWAYS AS (
   'ACH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_achievements_seq')::TEXT, 6, '0')
                          ) STORED,

                          -- References
                          user_id UUID NOT NULL,

                          -- Achievement definition
                          achievement_code VARCHAR(100) NOT NULL,
                          achievement_name VARCHAR(255),
                          achievement_description TEXT,
                          achievement_category VARCHAR(50) CHECK (achievement_category IN (
   'CONTENT', 'SOCIAL', 'ENGAGEMENT', 'LOYALTY', 'SPECIAL', 'SECRET'
                          )),

                          -- Rarity
                          rarity socialcandor_schema.achievement_rarity DEFAULT 'COMMON',
                          points_value INTEGER DEFAULT 0, -- Points awarded for completion

                          -- Progress tracking
                          progress INTEGER DEFAULT 0,     -- Current progress (for multi-step)
                          target INTEGER,                 -- Target needed for completion
                          progress_percentage NUMERIC(5,2) GENERATED ALWAYS AS (
   CASE WHEN target > 0 THEN (progress::NUMERIC / target::NUMERIC) * 100 ELSE 0 END
                          ) STORED,

                          -- Completion
                          earned_at TIMESTAMP WITH TIME ZONE,
                          is_completed BOOLEAN GENERATED ALWAYS AS (earned_at IS NOT NULL) STORED,

                          -- Timing
                          first_progress_at TIMESTAMP WITH TIME ZONE,
                          last_progress_at TIMESTAMP WITH TIME ZONE,

                          -- Context
                          metadata JSONB DEFAULT '{}',     -- Additional achievement data

                          -- Display
                          badge_image_url VARCHAR(500),
                          badge_image_hover_url VARCHAR(500),

                          -- Social
                          shared_on_timeline BOOLEAN DEFAULT FALSE,
                          shared_at TIMESTAMP WITH TIME ZONE,

                          -- Audit columns
                          created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                          updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                          created_by UUID NOT NULL,
                          updated_by UUID DEFAULT uuid_nil(),

                          -- Constraints
                          CONSTRAINT fk_user_achievements_user FOREIGN KEY (user_id)
   REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                          CONSTRAINT fk_user_achievements_created_by FOREIGN KEY (created_by)
   REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                          CONSTRAINT fk_user_achievements_updated_by FOREIGN KEY (updated_by)
   REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                          CONSTRAINT uk_user_achievement UNIQUE (user_id, achievement_code)
                      );

                      -- Comments
                      COMMENT ON TABLE socialcandor_schema.user_achievements IS 'Tracks user progress and completion of achievements and badges';
                      COMMENT ON COLUMN socialcandor_schema.user_achievements.rarity IS 'Rarity level affecting display and prestige';
                      COMMENT ON COLUMN socialcandor_schema.user_achievements.progress IS 'Current progress toward achievement (for multi-step achievements)';
                      COMMENT ON COLUMN socialcandor_schema.user_achievements.target IS 'Target needed for completion';
                      COMMENT ON COLUMN socialcandor_schema.user_achievements.metadata IS 'Additional achievement data (e.g., specific counts, qualifying items)';

                      -- Indexes for performance
                      CREATE INDEX idx_user_achievements_user ON socialcandor_schema.user_achievements(user_id, is_completed);
                      CREATE INDEX idx_user_achievements_code ON socialcandor_schema.user_achievements(achievement_code, rarity);
                      CREATE INDEX idx_user_achievements_completed ON socialcandor_schema.user_achievements(earned_at DESC) WHERE is_completed = TRUE;
                      CREATE INDEX idx_user_achievements_progress ON socialcandor_schema.user_achievements(progress_percentage) WHERE is_completed = FALSE;

                      -- Trigger for updated_at
                      CREATE TRIGGER trg_user_achievements_updated_at
                          BEFORE UPDATE ON socialcandor_schema.user_achievements
                          FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                      -- Function to check achievement completion
                      CREATE OR REPLACE FUNCTION socialcandor_schema.check_achievement_completion()
                      RETURNS TRIGGER AS $$
                      BEGIN
                          -- Check if achievement just completed
                          IF NEW.progress >= NEW.target AND OLD.earned_at IS NULL AND NEW.target > 0 THEN
   NEW.earned_at := CURRENT_TIMESTAMP;

   -- Award points if applicable
   IF NEW.points_value > 0 THEN
       INSERT INTO socialcandor_schema.user_points_history (
           user_id, transaction_type, amount, balance_before, balance_after,
           reason_code, reference_id, created_by
       ) VALUES (
           NEW.user_id,
           'EARN',
           NEW.points_value,
           (SELECT COALESCE(point_balance, 0) FROM socialcandor_schema.users WHERE user_id = NEW.user_id),
           (SELECT COALESCE(point_balance, 0) + NEW.points_value FROM socialcandor_schema.users WHERE user_id = NEW.user_id),
           'ACHIEVEMENT_COMPLETED',
           NEW.achievement_id,
           NEW.created_by
       );
   END IF;

   -- Create notification
   INSERT INTO socialcandor_schema.notifications (
       user_id, notification_type, title, message, metadata, created_by
   ) VALUES (
       NEW.user_id,
       'ACHIEVEMENT_UNLOCKED',
       'Achievement Unlocked!',
       format('You earned the "%s" achievement', NEW.achievement_name),
       jsonb_build_object('achievement_code', NEW.achievement_code, 'rarity', NEW.rarity),
       NEW.created_by
   );
                          END IF;

                          RETURN NEW;
                      END;
                      $$ LANGUAGE plpgsql;

                      CREATE TRIGGER trg_user_achievements_completion
                          BEFORE UPDATE OF progress ON socialcandor_schema.user_achievements
                          FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_achievement_completion();

                      -- RLS Policy
                      ALTER TABLE socialcandor_schema.user_achievements ENABLE ROW LEVEL SECURITY;
                      CREATE POLICY user_achievements_self_policy ON socialcandor_schema.user_achievements
                          FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
                      CREATE POLICY user_achievements_public_policy ON socialcandor_schema.user_achievements
                          FOR SELECT USING (is_completed = TRUE AND rarity IN ('COMMON', 'UNCOMMON', 'RARE'));
                      CREATE POLICY user_achievements_admin_policy ON socialcandor_schema.user_achievements
                          FOR ALL USING (socialcandor_schema.is_admin());


                          --================================================================================================
                          -- Table: GM03 - user_challenges
                          -- Description: Defines time-limited challenges with specific goals, rewards, and participation
                          --              tracking. Supports seasonal events and engagement campaigns.
                          -- Business Case: Time-limited challenges create urgency and drive concentrated engagement
                          --                during specific periods (holidays, product launches, community events).
                          --                This table stores challenge definitions, including goals (e.g., "post 10 times"),
                          --                duration, and rewards. Challenges can be one-time or recurring, with different
                          --                difficulty levels to appeal to various user segments. The design supports
                          --                leaderboards for competitive challenges and team-based challenges for
                          --                community building. Integration with analytics enables measurement of
                          --                challenge effectiveness in driving key metrics.
                          --
                          -- Key Performance Indicators (KPIs):
                          --   1. Challenge participation rate - Percentage of users joining challenges
                          --   2. Challenge completion rate - Percentage of participants completing challenges
                          --   3. Engagement lift - Increase in target metrics during challenge period
                          --   4. Reward redemption rate - Percentage of earned rewards redeemed
                          --   5. Challenge ROI - Engagement gain per challenge
                          --
                          -- Feature References:
                          --   - GAM12 (Challenges)
                          --   - GAM13 (Seasonal Events)
                          --   - GAM14 (Leaderboards)
                          --   - MKT07 (Campaign Engagement)
                          --================================================================================================
                          CREATE TABLE IF NOT EXISTS socialcandor_schema.user_challenges (
   -- Primary key
   challenge_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

   -- Human-readable identifier
   challenge_number VARCHAR(50) GENERATED ALWAYS AS (
       'CHAL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_challenges_seq')::TEXT, 6, '0')
   ) STORED,

   -- Challenge identification
   challenge_code VARCHAR(100) UNIQUE NOT NULL,
   challenge_name VARCHAR(255) NOT NULL,
   challenge_description TEXT,
   challenge_summary VARCHAR(500),

   -- Categorization
   challenge_type VARCHAR(50) CHECK (challenge_type IN (
       'DAILY', 'WEEKLY', 'MONTHLY', 'SEASONAL', 'SPECIAL_EVENT', 'ONGOING'
   )),
   difficulty socialcandor_schema.challenge_difficulty DEFAULT 'BEGINNER',
   category VARCHAR(100),
   tags TEXT[],

   -- Goals/Criteria
   goal_type VARCHAR(50) NOT NULL CHECK (goal_type IN (
       'COUNT', 'STREAK', 'COMPLETION', 'SCORE', 'CUSTOM'
   )),
   goal_target INTEGER,            -- Target count/score
   goal_unit VARCHAR(50),          -- posts, comments, days, etc.
   goal_criteria JSONB,            -- Complex criteria if needed

   -- Duration
   start_date TIMESTAMP WITH TIME ZONE NOT NULL,
   end_date TIMESTAMP WITH TIME ZONE NOT NULL,
   registration_deadline TIMESTAMP WITH TIME ZONE,
   is_active BOOLEAN GENERATED ALWAYS AS (
       start_date <= CURRENT_TIMESTAMP AND
       end_date >= CURRENT_TIMESTAMP
   ) STORED,

   -- Rewards
   reward_points INTEGER DEFAULT 0,
   reward_badge_code VARCHAR(100),
   reward_experience INTEGER DEFAULT 0,
   reward_currency_amount NUMERIC(15,2),
   reward_description TEXT,

   -- Participation limits
   max_participants INTEGER,        -- NULL = unlimited
   current_participants INTEGER DEFAULT 0,
   min_participant_level INTEGER,   -- Minimum user level required

   -- Leaderboard
   has_leaderboard BOOLEAN DEFAULT FALSE,
   leaderboard_update_frequency VARCHAR(20) DEFAULT 'REALTIME',

   -- Team options
   is_team_challenge BOOLEAN DEFAULT FALSE,
   max_team_size INTEGER DEFAULT 1,

   -- Status
   status VARCHAR(30) DEFAULT 'DRAFT' CHECK (status IN (
       'DRAFT', 'PUBLISHED', 'ACTIVE', 'COMPLETED', 'CANCELLED', 'ARCHIVED'
   )),

   -- Visuals
   banner_image_url VARCHAR(500),
   icon_url VARCHAR(500),
   color_scheme VARCHAR(50),

   -- Audit columns
   created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
   updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
   created_by UUID NOT NULL,
   updated_by UUID DEFAULT uuid_nil(),

   -- Constraints
   CONSTRAINT fk_user_challenges_created_by FOREIGN KEY (created_by)
       REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
   CONSTRAINT fk_user_challenges_updated_by FOREIGN KEY (updated_by)
       REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

   CONSTRAINT chk_user_challenges_dates CHECK (end_date > start_date),
   CONSTRAINT chk_user_challenges_registration CHECK (
       registration_deadline IS NULL OR registration_deadline <= end_date
   )
                          );

                          -- Comments
                          COMMENT ON TABLE socialcandor_schema.user_challenges IS 'Defines time-limited challenges with goals, duration, and rewards';
                          COMMENT ON COLUMN socialcandor_schema.user_challenges.goal_criteria IS 'JSON defining complex goal criteria if simple count is insufficient';
                          COMMENT ON COLUMN socialcandor_schema.user_challenges.is_team_challenge IS 'Whether challenge is team-based vs individual';
                          COMMENT ON COLUMN socialcandor_schema.user_challenges.has_leaderboard IS 'Whether challenge includes a leaderboard';

                          -- Indexes for performance
                          CREATE INDEX idx_user_challenges_status ON socialcandor_schema.user_challenges(status, start_date, end_date);
                          CREATE INDEX idx_user_challenges_type ON socialcandor_schema.user_challenges(challenge_type, difficulty);
                          CREATE INDEX idx_user_challenges_active ON socialcandor_schema.user_challenges(is_active) WHERE is_active = TRUE;
                          CREATE INDEX idx_user_challenges_dates ON socialcandor_schema.user_challenges(start_date, end_date);

                          -- Trigger for updated_at
                          CREATE TRIGGER trg_user_challenges_updated_at
   BEFORE UPDATE ON socialcandor_schema.user_challenges
   FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                          -- RLS Policy
                          ALTER TABLE socialcandor_schema.user_challenges ENABLE ROW LEVEL SECURITY;
                          CREATE POLICY user_challenges_public_policy ON socialcandor_schema.user_challenges
   FOR SELECT USING (status IN ('PUBLISHED', 'ACTIVE', 'COMPLETED'));
                          CREATE POLICY user_challenges_admin_policy ON socialcandor_schema.user_challenges
   FOR ALL USING (socialcandor_schema.is_admin());

   --================================================================================================
   -- Table: GM04 - challenge_participants
   -- Description: Tracks user participation in challenges, including progress, completion,
   --              and rewards earned. Enables leaderboards and progress tracking.
   -- Business Case: Once a challenge is defined, this table tracks which users join and their
   --                progress toward goals. Real-time progress updates enable motivational
   --                feedback and leaderboard rankings. The design supports partial completion
   --                tracking (e.g., 5 of 10 posts) and milestone notifications. For team
   --                challenges, participants are grouped and team progress is aggregated.
   --                Completion tracking ensures rewards are granted only once per challenge.
   --                Historical data enables analysis of challenge effectiveness by user segment.
   --
   -- Key Performance Indicators (KPIs):
   --   1. Join rate - Percentage of eligible users joining challenges
   --   2. Progress rate - Average progress toward goals
   --   3. Completion rate - Percentage of participants completing challenges
   --   4. Reward claim rate - Percentage of earned rewards claimed
   --   5. Re-participation rate - Users joining multiple challenges
   --
   -- Feature References:
   --   - GAM15 (Challenge Participation)
   --   - GAM16 (Progress Tracking)
   --   - GAM17 (Leaderboards)
   --   - NOTIFY05 (Challenge Notifications)
   --================================================================================================
   CREATE TABLE IF NOT EXISTS socialcandor_schema.challenge_participants (
       -- Primary key
       participant_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

       -- Human-readable identifier
       participant_number VARCHAR(50) GENERATED ALWAYS AS (
           'CP-' || TO_CHAR(joined_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.challenge_participants_seq')::TEXT, 6, '0')
       ) STORED,

       -- References
       challenge_id UUID NOT NULL,
       user_id UUID NOT NULL,
       team_id UUID,                   -- For team challenges

       -- Participation details
       joined_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
       source VARCHAR(50) CHECK (source IN ('AUTO', 'MANUAL', 'INVITE', 'PROMOTION')),

       -- Progress tracking
       progress INTEGER DEFAULT 0,     -- Current progress toward goal
       target INTEGER,                 -- Individual target (if different from challenge)
       progress_percentage NUMERIC(5,2) GENERATED ALWAYS AS (
           CASE WHEN target > 0 THEN (progress::NUMERIC / target::NUMERIC) * 100 ELSE 0 END
       ) STORED,

       -- Status
       status VARCHAR(30) DEFAULT 'ACTIVE' CHECK (status IN (
           'ACTIVE', 'COMPLETED', 'FAILED', 'WITHDRAWN', 'DISQUALIFIED'
       )),
       completed_at TIMESTAMP WITH TIME ZONE,

       -- Streak tracking (for daily challenges)
       current_streak INTEGER DEFAULT 0,
       longest_streak INTEGER DEFAULT 0,
       last_activity_date DATE,

       -- Leaderboard
       leaderboard_score NUMERIC(10,2),
       leaderboard_rank INTEGER,

       -- Rewards
       rewards_earned JSONB DEFAULT '[]',                         -- List of rewards earned
       rewards_claimed BOOLEAN DEFAULT FALSE,
       rewards_claimed_at TIMESTAMP WITH TIME ZONE,

       -- Metadata
       metadata JSONB DEFAULT '{}',

       -- Audit columns
       created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
       updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
       created_by UUID NOT NULL,
       updated_by UUID DEFAULT uuid_nil(),

       -- Constraints
       CONSTRAINT fk_challenge_participants_challenge FOREIGN KEY (challenge_id)
           REFERENCES socialcandor_schema.user_challenges(challenge_id) ON DELETE CASCADE,
       CONSTRAINT fk_challenge_participants_user FOREIGN KEY (user_id)
           REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
       CONSTRAINT fk_challenge_participants_created_by FOREIGN KEY (created_by)
           REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
       CONSTRAINT fk_challenge_participants_updated_by FOREIGN KEY (updated_by)
           REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

       CONSTRAINT uk_challenge_participant UNIQUE (challenge_id, user_id),
       CONSTRAINT chk_challenge_participant_progress CHECK (progress >= 0)
   );

   -- Comments
   COMMENT ON TABLE socialcandor_schema.challenge_participants IS 'Tracks user participation and progress in challenges';
   COMMENT ON COLUMN socialcandor_schema.challenge_participants.team_id IS 'Team ID for team-based challenges';
   COMMENT ON COLUMN socialcandor_schema.challenge_participants.progress IS 'Current progress toward challenge goal';
   COMMENT ON COLUMN socialcandor_schema.challenge_participants.rewards_earned IS 'JSON array of rewards earned from challenge';
   COMMENT ON COLUMN socialcandor_schema.challenge_participants.leaderboard_score IS 'Score used for leaderboard ranking';

   -- Indexes for performance
   CREATE INDEX idx_challenge_participants_challenge ON socialcandor_schema.challenge_participants(challenge_id, status);
   CREATE INDEX idx_challenge_participants_user ON socialcandor_schema.challenge_participants(user_id, status);
   CREATE INDEX idx_challenge_participants_leaderboard ON socialcandor_schema.challenge_participants(challenge_id, leaderboard_score DESC)
       WHERE leaderboard_score IS NOT NULL;
   CREATE INDEX idx_challenge_participants_streak ON socialcandor_schema.challenge_participants(last_activity_date) WHERE status = 'ACTIVE';

   -- Trigger for updated_at
   CREATE TRIGGER trg_challenge_participants_updated_at
       BEFORE UPDATE ON socialcandor_schema.challenge_participants
       FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

   -- Function to check challenge completion
   CREATE OR REPLACE FUNCTION socialcandor_schema.check_challenge_completion()
   RETURNS TRIGGER AS $$
   DECLARE
       v_challenge RECORD;
       v_reward_text TEXT;
   BEGIN
       -- Get challenge details
       SELECT * INTO v_challenge
       FROM socialcandor_schema.user_challenges
       WHERE challenge_id = NEW.challenge_id;

       -- Check if challenge completed
       IF NEW.progress >= COALESCE(NEW.target, v_challenge.goal_target)
          AND OLD.status != 'COMPLETED' THEN

           NEW.status := 'COMPLETED';
           NEW.completed_at := CURRENT_TIMESTAMP;

           -- Prepare rewards
           NEW.rewards_earned := jsonb_build_object(
               'points', v_challenge.reward_points,
               'badge', v_challenge.reward_badge_code,
               'experience', v_challenge.reward_experience,
               'currency', v_challenge.reward_currency_amount
           );

           -- Award points
           IF v_challenge.reward_points > 0 THEN
               INSERT INTO socialcandor_schema.user_points_history (
                   user_id, transaction_type, amount, balance_before, balance_after,
                   reason_code, reference_id, created_by
               ) VALUES (
                   NEW.user_id,
                   'EARN',
                   v_challenge.reward_points,
                   (SELECT COALESCE(point_balance, 0) FROM socialcandor_schema.users WHERE user_id = NEW.user_id),
                   (SELECT COALESCE(point_balance, 0) + v_challenge.reward_points FROM socialcandor_schema.users WHERE user_id = NEW.user_id),
                   'CHALLENGE_COMPLETED',
                   NEW.challenge_id,
                   NEW.created_by
               );
           END IF;

           -- Award badge
           IF v_challenge.reward_badge_code IS NOT NULL THEN
               -- Insert or update user achievement
               INSERT INTO socialcandor_schema.user_achievements (
                   user_id, achievement_code, achievement_name,
                   progress, target, earned_at, created_by
               ) VALUES (
                   NEW.user_id,
                   v_challenge.reward_badge_code,
                   v_challenge.challenge_name || ' Badge',
                   1, 1, CURRENT_TIMESTAMP,
                   NEW.created_by
               )
               ON CONFLICT (user_id, achievement_code) DO UPDATE
               SET earned_at = CURRENT_TIMESTAMP,
                   progress = 1,
                   updated_at = CURRENT_TIMESTAMP;
           END IF;

           -- Create completion notification
           INSERT INTO socialcandor_schema.notifications (
               user_id, notification_type, title, message, metadata, created_by
           ) VALUES (
               NEW.user_id,
               'CHALLENGE_COMPLETED',
               'Challenge Complete!',
               format('You completed the "%s" challenge', v_challenge.challenge_name),
               jsonb_build_object('challenge_id', NEW.challenge_id, 'rewards', NEW.rewards_earned),
               NEW.created_by
           );
       END IF;

       RETURN NEW;
   END;
   $$ LANGUAGE plpgsql;

   CREATE TRIGGER trg_challenge_participants_completion
       BEFORE UPDATE OF progress ON socialcandor_schema.challenge_participants
       FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_challenge_completion();

   -- RLS Policy
   ALTER TABLE socialcandor_schema.challenge_participants ENABLE ROW LEVEL SECURITY;
   CREATE POLICY challenge_participants_self_policy ON socialcandor_schema.challenge_participants
       FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
   CREATE POLICY challenge_participants_public_policy ON socialcandor_schema.challenge_participants
       FOR SELECT USING (
           EXISTS (
               SELECT 1 FROM socialcandor_schema.user_challenges
               WHERE challenge_id = challenge_participants.challenge_id
               AND has_leaderboard = TRUE
           )
       );
   CREATE POLICY challenge_participants_admin_policy ON socialcandor_schema.challenge_participants
       FOR ALL USING (socialcandor_schema.is_admin());

       --================================================================================================
       -- Table: CS01 - csat_surveys
       -- Description: Post-ticket customer satisfaction surveys capturing feedback, ratings,
       --              and comments. Enables measurement of support quality and agent performance.
       -- Business Case: Customer Satisfaction (CSAT) scores are a critical metric for support
       --                organizations, directly impacting customer retention and lifetime value.
       --                This table captures survey responses after ticket resolution, including
       --                quantitative ratings (1-5 scale) and qualitative feedback. The design
       --                supports multi-question surveys, NPS-style questions, and free-text
       --                comments. Integration with ticketing system enables correlation of
       --                satisfaction with ticket characteristics (type, priority, resolution time).
       --                Historical data supports trend analysis and agent performance reviews.
       --
       -- Key Performance Indicators (KPIs):
       --   1. CSAT score - Average satisfaction rating across all surveys
       --   2. Response rate - Percentage of resolved tickets with survey responses
       --   3. NPS score - Net Promoter Score based on likelihood to recommend
       --   4. Agent-specific CSAT - Satisfaction ratings by support agent
       --   5. Trend analysis - CSAT changes over time by category
       --
       -- Feature References:
       --   - SUP07 (CSAT Management)
       --   - SUP08 (Quality Monitoring)
       --   - SUP09 (Agent Performance)
       --   - ANL12 (Support Analytics)
       --================================================================================================
       CREATE TABLE IF NOT EXISTS socialcandor_schema.csat_surveys (
           -- Primary key
           survey_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

           -- Human-readable identifier
           survey_number VARCHAR(50) GENERATED ALWAYS AS (
               'CSAT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.csat_surveys_seq')::TEXT, 6, '0')
           ) STORED,

           -- References
           ticket_id UUID NOT NULL,
           user_id UUID NOT NULL,
           agent_id UUID,                -- Support agent who handled ticket

           -- Survey metadata
           survey_type VARCHAR(30) DEFAULT 'POST_TICKET' CHECK (survey_type IN (
               'POST_TICKET', 'POST_CHAT', 'POST_CALL', 'PERIODIC', 'TRIGGERED'
           )),
           survey_channel VARCHAR(30) CHECK (survey_channel IN ('EMAIL', 'IN_APP', 'SMS', 'WEB_LINK')),

           -- Overall satisfaction
           overall_rating INTEGER CHECK (overall_rating >= 1 AND overall_rating <= 5),
           nps_score INTEGER CHECK (nps_score >= 0 AND nps_score <= 10),  -- 0-10 scale for NPS

           -- Multi-question responses (JSON for flexibility)
           question_responses JSONB DEFAULT '[]',                    -- Array of {question_id, rating, comment}

           -- Specific feedback areas
           resolution_satisfaction INTEGER CHECK (resolution_satisfaction >= 1 AND resolution_satisfaction <= 5),
           time_satisfaction INTEGER CHECK (time_satisfaction >= 1 AND time_satisfaction <= 5),
           agent_satisfaction INTEGER CHECK (agent_satisfaction >= 1 AND agent_satisfaction <= 5),

           -- Comments
           positive_comment TEXT,          -- What went well
           improvement_comment TEXT,       -- What could be improved
           additional_feedback TEXT,

           -- Follow-up
           follow_up_requested BOOLEAN DEFAULT FALSE,
           follow_up_contacted BOOLEAN DEFAULT FALSE,
           follow_up_notes TEXT,

           -- Survey timing
           sent_at TIMESTAMP WITH TIME ZONE NOT NULL,
           responded_at TIMESTAMP WITH TIME ZONE,
           response_time_minutes INTEGER GENERATED ALWAYS AS (
               EXTRACT(EPOCH FROM (responded_at - sent_at))/60
           ) STORED,

           -- Status
           status VARCHAR(30) DEFAULT 'SENT' CHECK (status IN (
               'SENT', 'VIEWED', 'PARTIAL', 'COMPLETED', 'EXPIRED'
           )),

           -- Audit columns
           created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
           updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
           created_by UUID NOT NULL,
           updated_by UUID DEFAULT uuid_nil(),

           -- Constraints
           CONSTRAINT fk_csat_surveys_ticket FOREIGN KEY (ticket_id)
               REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE CASCADE,
           CONSTRAINT fk_csat_surveys_user FOREIGN KEY (user_id)
               REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
           CONSTRAINT fk_csat_surveys_agent FOREIGN KEY (agent_id)
               REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
           CONSTRAINT fk_csat_surveys_created_by FOREIGN KEY (created_by)
               REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
           CONSTRAINT fk_csat_surveys_updated_by FOREIGN KEY (updated_by)
               REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

           CONSTRAINT uk_csat_surveys_ticket UNIQUE (ticket_id)
       );

       -- Comments
       COMMENT ON TABLE socialcandor_schema.csat_surveys IS 'Post-ticket customer satisfaction surveys for measuring support quality';
       COMMENT ON COLUMN socialcandor_schema.csat_surveys.question_responses IS 'JSON array of responses to multiple survey questions';
       COMMENT ON COLUMN socialcandor_schema.csat_surveys.nps_score IS 'Net Promoter Score on 0-10 scale';
       COMMENT ON COLUMN socialcandor_schema.csat_surveys.follow_up_requested IS 'Whether user requested follow-up contact';

       -- Indexes for performance
       CREATE INDEX idx_csat_surveys_ticket ON socialcandor_schema.csat_surveys(ticket_id);
       CREATE INDEX idx_csat_surveys_user ON socialcandor_schema.csat_surveys(user_id, responded_at DESC);
       CREATE INDEX idx_csat_surveys_agent ON socialcandor_schema.csat_surveys(agent_id, overall_rating) WHERE agent_id IS NOT NULL;
       CREATE INDEX idx_csat_surveys_rating ON socialcandor_schema.csat_surveys(overall_rating, created_at DESC);
       CREATE INDEX idx_csat_surveys_status ON socialcandor_schema.csat_surveys(status, sent_at) WHERE status = 'SENT';

       -- Trigger for updated_at
       CREATE TRIGGER trg_csat_surveys_updated_at
           BEFORE UPDATE ON socialcandor_schema.csat_surveys
           FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

       -- RLS Policy
       ALTER TABLE socialcandor_schema.csat_surveys ENABLE ROW LEVEL SECURITY;
       CREATE POLICY csat_surveys_self_policy ON socialcandor_schema.csat_surveys
           FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
       CREATE POLICY csat_surveys_agent_policy ON socialcandor_schema.csat_surveys
           FOR SELECT USING (agent_id = current_setting('app.current_user_id')::UUID);
       CREATE POLICY csat_surveys_admin_policy ON socialcandor_schema.csat_surveys
           FOR ALL USING (socialcandor_schema.is_admin());


           --================================================================================================
           -- Table: CS02 - sla_violations
           -- Description: Tracks when support SLAs (Service Level Agreements) are breached, including
           --              response time and resolution time violations. Enables accountability and reporting.
           -- Business Case: SLA compliance is a critical measure of support team performance and a
           --                contractual obligation for enterprise customers. This table records every
           --                SLA breach, capturing the type (response/resolution), severity, and impact.
           --                The data supports automated escalation, root cause analysis, and continuous
           --                improvement initiatives. Integration with ticketing system enables real-time
           --                alerts when SLAs are at risk. Historical violation data supports capacity
           --                planning and process improvements to reduce future breaches.
           --
           -- Key Performance Indicators (KPIs):
           --   1. SLA compliance rate - Percentage of tickets meeting SLA targets
           --   2. Average breach duration - Time between breach and resolution
           --   3. Breach by priority - Violation rate by ticket priority
           --   4. Escalation effectiveness - Percentage of breaches escalated appropriately
           --   5. Trend analysis - SLA compliance trend over time
           --
           -- Feature References:
           --   - SUP10 (SLA Management)
           --   - SUP11 (Escalation Management)
           --   - SUP12 (Performance Monitoring)
           --   - COMP26 (SLA Compliance)
           --================================================================================================
           CREATE TABLE IF NOT EXISTS socialcandor_schema.sla_violations (
               -- Primary key
               violation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

               -- Human-readable identifier
               violation_number VARCHAR(50) GENERATED ALWAYS AS (
                   'SLAV-' || TO_CHAR(violation_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.sla_violations_seq')::TEXT, 6, '0')
               ) STORED,

               -- References
               ticket_id UUID NOT NULL,
               sla_definition_id UUID,        -- Reference to SLA definition

               -- Violation details
               violation_type VARCHAR(30) NOT NULL CHECK (violation_type IN (
                   'RESPONSE_TIME', 'RESOLUTION_TIME', 'UPDATE_FREQUENCY', 'ACKNOWLEDGMENT'
               )),
               violation_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

               -- Targets and actuals
               target_minutes INTEGER NOT NULL,
               actual_minutes INTEGER NOT NULL,
               exceeded_by_minutes INTEGER GENERATED ALWAYS AS (actual_minutes - target_minutes) STORED,

               -- Severity
               severity VARCHAR(20) CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

               -- Ticket context (denormalized for performance)
               ticket_priority VARCHAR(20),
               ticket_category VARCHAR(50),
               ticket_created_at TIMESTAMP WITH TIME ZONE,

               -- Escalation
               escalated BOOLEAN DEFAULT FALSE,
               escalated_to UUID,              -- User escalated to
               escalated_at TIMESTAMP WITH TIME ZONE,
               escalation_notes TEXT,

               -- Notification
               notified BOOLEAN DEFAULT FALSE,
               notified_at TIMESTAMP WITH TIME ZONE,
               notification_recipients TEXT[],

               -- Resolution
               resolved_at TIMESTAMP WITH TIME ZONE,
               resolution_notes TEXT,

               -- Audit columns
               created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
               updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
               created_by UUID NOT NULL,
               updated_by UUID DEFAULT uuid_nil(),

               -- Constraints
               CONSTRAINT fk_sla_violations_ticket FOREIGN KEY (ticket_id)
                   REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE CASCADE,
               CONSTRAINT fk_sla_violations_sla FOREIGN KEY (sla_definition_id)
                   REFERENCES socialcandor_schema.sla_definitions(sla_id) ON DELETE SET NULL,
               CONSTRAINT fk_sla_violations_escalated_to FOREIGN KEY (escalated_to)
                   REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
               CONSTRAINT fk_sla_violations_created_by FOREIGN KEY (created_by)
                   REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
               CONSTRAINT fk_sla_violations_updated_by FOREIGN KEY (updated_by)
                   REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

               CONSTRAINT chk_sla_violations_minutes CHECK (actual_minutes >= target_minutes)
           );

           -- Comments
           COMMENT ON TABLE socialcandor_schema.sla_violations IS 'Tracks SLA breaches for support tickets with escalation and notification';
           COMMENT ON COLUMN socialcandor_schema.sla_violations.violation_type IS 'Type of SLA violated (response time, resolution time, etc.)';
           COMMENT ON COLUMN socialcandor_schema.sla_violations.escalated IS 'Whether the violation triggered escalation';
           COMMENT ON COLUMN socialcandor_schema.sla_violations.exceeded_by_minutes IS 'Minutes by which SLA was exceeded';

           -- Indexes for performance
           CREATE INDEX idx_sla_violations_ticket ON socialcandor_schema.sla_violations(ticket_id);
           CREATE INDEX idx_sla_violations_time ON socialcandor_schema.sla_violations(violation_time DESC);
           CREATE INDEX idx_sla_violations_type ON socialcandor_schema.sla_violations(violation_type, severity);
           CREATE INDEX idx_sla_violations_escalated ON socialcandor_schema.sla_violations(escalated, escalated_at) WHERE escalated = FALSE;
           CREATE INDEX idx_sla_violations_notified ON socialcandor_schema.sla_violations(notified, violation_time) WHERE notified = FALSE;

           -- Trigger for updated_at
           CREATE TRIGGER trg_sla_violations_updated_at
               BEFORE UPDATE ON socialcandor_schema.sla_violations
               FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

           -- Function to auto-escalate SLA violations
           CREATE OR REPLACE FUNCTION socialcandor_schema.escalate_sla_violation()
           RETURNS TRIGGER AS $$
           DECLARE
               v_escalation_user UUID;
           BEGIN
               -- Auto-escalate based on severity
               IF NEW.severity IN ('HIGH', 'CRITICAL') AND NEW.escalated = FALSE THEN
                   -- Find manager or senior support user (simplified)
                   SELECT user_id INTO v_escalation_user
                   FROM socialcandor_schema.users
                   WHERE role = 'SUPPORT_MANAGER'
                   LIMIT 1;

                   NEW.escalated := TRUE;
                   NEW.escalated_to := v_escalation_user;
                   NEW.escalated_at := CURRENT_TIMESTAMP;

                   -- Create notification for escalation
                   INSERT INTO socialcandor_schema.notifications (
                       user_id, notification_type, title, message, metadata, created_by
                   ) VALUES (
                       v_escalation_user,
                       'SLA_VIOLATION_ESCALATION',
                       'SLA Violation Escalated',
                       format('Ticket %s has violated SLA and requires attention', NEW.ticket_id),
                       jsonb_build_object('violation_id', NEW.violation_id, 'severity', NEW.severity),
                       NEW.created_by
                   );
               END IF;

               RETURN NEW;
           END;
           $$ LANGUAGE plpgsql;

           CREATE TRIGGER trg_sla_violations_escalate
               BEFORE INSERT ON socialcandor_schema.sla_violations
               FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.escalate_sla_violation();

           -- RLS Policy
           ALTER TABLE socialcandor_schema.sla_violations ENABLE ROW LEVEL SECURITY;
           CREATE POLICY sla_violations_admin_policy ON socialcandor_schema.sla_violations
               FOR ALL USING (socialcandor_schema.is_admin());
           CREATE POLICY sla_violations_manager_policy ON socialcandor_schema.sla_violations
               FOR SELECT USING (EXISTS (
                   SELECT 1 FROM socialcandor_schema.users
                   WHERE user_id = current_setting('app.current_user_id')::UUID
                   AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
               ));



               --================================================================================================
               -- Table: CS03 - ticket_attachments
               -- Description: Stores files attached to support tickets, including images, documents,
               --              and logs. Enables rich context for troubleshooting and resolution.
               -- Business Case: Support tickets often require attachments to diagnose issues: screenshots,
               --                log files, error reports, or documentation. This table manages these
               --                files with proper storage, size limits, and security. The design supports
               --                multiple attachments per ticket, with metadata like file type and size.
               --                Virus scanning integration ensures malicious files are blocked. File
               --                retention policies align with data protection regulations. Users can
               --                only access attachments from their own tickets, maintaining privacy.
               --
               -- Key Performance Indicators (KPIs):
               --   1. Attachment rate - Percentage of tickets with attachments
               --   2. Average attachment size - Mean size of uploaded files
               --   3. File type distribution - Most common attachment types
               --   4. Storage usage - Total storage consumed by attachments
               --   5. Virus scan results - Percentage of files passing security scans
               --
               -- Feature References:
               --   - SUP13 (Ticket Attachments)
               --   - SUP14 (File Management)
               --   - SEC48 (File Security)
               --   - STG01 (File Storage)
               --================================================================================================
               CREATE TABLE IF NOT EXISTS socialcandor_schema.ticket_attachments (
                   -- Primary key
                   attachment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                   -- Human-readable identifier
                   attachment_number VARCHAR(50) GENERATED ALWAYS AS (
                       'TATT-' || TO_CHAR(uploaded_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ticket_attachments_seq')::TEXT, 6, '0')
                   ) STORED,

                   -- References
                   ticket_id UUID NOT NULL,
                   user_id UUID NOT NULL,         -- User who uploaded

                   -- File metadata
                   file_name VARCHAR(255) NOT NULL,
                   file_extension VARCHAR(20),
                   file_size_bytes BIGINT CHECK (file_size_bytes > 0),
                   mime_type VARCHAR(100),

                   -- Storage
                   storage_provider VARCHAR(50) DEFAULT 'S3' CHECK (storage_provider IN ('S3', 'GCS', 'AZURE', 'LOCAL')),
                   storage_key VARCHAR(500) NOT NULL,
                   storage_bucket VARCHAR(255),
                   file_url VARCHAR(500),         -- Signed URL for access
                   file_hash VARCHAR(64),         -- SHA-256 for integrity

                   -- Content metadata
                   description TEXT,
                   is_image BOOLEAN GENERATED ALWAYS AS (
                       mime_type LIKE 'image/%'
                   ) STORED,
                   image_dimensions JSONB,         -- Width/height for images

                   -- Security
                   virus_scan_status VARCHAR(30) DEFAULT 'PENDING' CHECK (virus_scan_status IN (
                       'PENDING', 'SCANNING', 'CLEAN', 'INFECTED', 'ERROR'
                   )),
                   virus_scan_result TEXT,
                   scan_attempts INTEGER DEFAULT 0,

                   -- Dates
                   uploaded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                   expires_at TIMESTAMP WITH TIME ZONE,                      -- Auto-delete after retention

                   -- Audit columns
                   created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                   updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                   created_by UUID NOT NULL,
                   updated_by UUID DEFAULT uuid_nil(),

                   -- Constraints
                   CONSTRAINT fk_ticket_attachments_ticket FOREIGN KEY (ticket_id)
                       REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE CASCADE,
                   CONSTRAINT fk_ticket_attachments_user FOREIGN KEY (user_id)
                       REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                   CONSTRAINT fk_ticket_attachments_created_by FOREIGN KEY (created_by)
                       REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                   CONSTRAINT fk_ticket_attachments_updated_by FOREIGN KEY (updated_by)
                       REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                   CONSTRAINT chk_ticket_attachments_expiry CHECK (expires_at IS NULL OR expires_at > uploaded_at),
                   CONSTRAINT chk_ticket_attachments_size CHECK (file_size_bytes <= 104857600) -- 100MB max
               );

               -- Comments
               COMMENT ON TABLE socialcandor_schema.ticket_attachments IS 'Files attached to support tickets with security scanning';
               COMMENT ON COLUMN socialcandor_schema.ticket_attachments.file_hash IS 'SHA-256 hash for file integrity verification';
               COMMENT ON COLUMN socialcandor_schema.ticket_attachments.virus_scan_status IS 'Status of virus/malware scanning';
               COMMENT ON COLUMN socialcandor_schema.ticket_attachments.image_dimensions IS 'Width and height for image files';

               -- Indexes for performance
               CREATE INDEX idx_ticket_attachments_ticket ON socialcandor_schema.ticket_attachments(ticket_id);
               CREATE INDEX idx_ticket_attachments_user ON socialcandor_schema.ticket_attachments(user_id, uploaded_at DESC);
               CREATE INDEX idx_ticket_attachments_scan ON socialcandor_schema.ticket_attachments(virus_scan_status)
                   WHERE virus_scan_status != 'CLEAN';
               CREATE INDEX idx_ticket_attachments_expires ON socialcandor_schema.ticket_attachments(expires_at)
                   WHERE expires_at IS NOT NULL;

               -- Trigger for updated_at
               CREATE TRIGGER trg_ticket_attachments_updated_at
                   BEFORE UPDATE ON socialcandor_schema.ticket_attachments
                   FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

               -- RLS Policy
               ALTER TABLE socialcandor_schema.ticket_attachments ENABLE ROW LEVEL SECURITY;
               CREATE POLICY ticket_attachments_self_policy ON socialcandor_schema.ticket_attachments
                   FOR ALL USING (
                       user_id = current_setting('app.current_user_id')::UUID OR
                       ticket_id IN (
 SELECT ticket_id FROM socialcandor_schema.user_feedback_tickets
 WHERE user_id = current_setting('app.current_user_id')::UUID
                       )
                   );
               CREATE POLICY ticket_attachments_staff_policy ON socialcandor_schema.ticket_attachments
                   FOR SELECT USING (EXISTS (
                       SELECT 1 FROM socialcandor_schema.users
                       WHERE user_id = current_setting('app.current_user_id')::UUID
                       AND (is_admin = TRUE OR role LIKE 'SUPPORT%')
                   ));



                   --================================================================================================
                   -- Table: CS04 - knowledge_base_feedback
                   -- Description: User ratings and feedback on knowledge base articles, enabling content
                   --              quality improvement and identification of gaps.
                   -- Business Case: Knowledge base effectiveness depends on content quality and relevance.
                   --                This table captures user feedback on articles, including helpfulness votes,
                   --                comments, and suggestions for improvement. The data drives content
                   --                prioritization, identifies gaps where new articles are needed, and
                   --                highlights outdated information. Integration with analytics enables
                   --                correlation between article views and ticket deflection rates. Users can
                   --                provide feedback anonymously or with attribution, and staff can respond
                   --                to feedback to close the loop.
                   --
                   -- Key Performance Indicators (KPIs):
                   --   1. Helpfulness rate - Percentage of users finding articles helpful
                   --   2. Feedback volume - Number of feedback submissions per article
                   --   3. Article improvement rate - Articles updated based on feedback
                   --   4. Response rate - Percentage of feedback receiving staff response
                   --   5. Deflection correlation - Relationship between article quality and ticket volume
                   --
                   -- Feature References:
                   --   - KB04 (Article Feedback)
                   --   - KB05 (Content Quality)
                   --   - KB06 (Continuous Improvement)
                   --   - SUP15 (Self-Service Metrics)
                   --================================================================================================
                   CREATE TABLE IF NOT EXISTS socialcandor_schema.knowledge_base_feedback (
                       -- Primary key
                       feedback_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                       -- Human-readable identifier
                       feedback_number VARCHAR(50) GENERATED ALWAYS AS (
 'KBF-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.knowledge_base_feedback_seq')::TEXT, 6, '0')
                       ) STORED,

                       -- References
                       article_id UUID NOT NULL,
                       user_id UUID,                  -- NULL for anonymous feedback
                       session_id UUID,               -- For anonymous tracking

                       -- Feedback type
                       feedback_type VARCHAR(30) NOT NULL CHECK (feedback_type IN (
 'HELPFUL', 'NOT_HELPFUL', 'SUGGESTION', 'ERROR', 'OUTDATED', 'GENERAL'
                       )),

                       -- Rating
                       rating INTEGER CHECK (rating >= 1 AND rating <= 5),     -- Overall rating

                       -- Helpfulness
                       was_helpful BOOLEAN,
                       helpfulness_reason TEXT,

                       -- Specific feedback
                       comment TEXT NOT NULL,
                       suggestion TEXT,
                       reported_issue VARCHAR(255),

                       -- Context
                       page_url VARCHAR(500),
                       search_query TEXT,             -- What they were searching for
                       time_on_page_seconds INTEGER,

                       -- User metadata
                       user_agent TEXT,
                       ip_address INET,

                       -- Staff response
                       responded_by UUID,
                       responded_at TIMESTAMP WITH TIME ZONE,
                       response TEXT,
                       response_notified BOOLEAN DEFAULT FALSE,

                       -- Status
                       status VARCHAR(30) DEFAULT 'NEW' CHECK (status IN (
 'NEW', 'ACKNOWLEDGED', 'IN_REVIEW', 'ACTIONED', 'CLOSED'
                       )),

                       -- Audit columns
                       created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                       updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                       created_by UUID NOT NULL,
                       updated_by UUID DEFAULT uuid_nil(),

                       -- Constraints
                       CONSTRAINT fk_kb_feedback_article FOREIGN KEY (article_id)
 REFERENCES socialcandor_schema.knowledge_articles(article_id) ON DELETE CASCADE,
                       CONSTRAINT fk_kb_feedback_user FOREIGN KEY (user_id)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                       CONSTRAINT fk_kb_feedback_session FOREIGN KEY (session_id)
 REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                       CONSTRAINT fk_kb_feedback_responded_by FOREIGN KEY (responded_by)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                       CONSTRAINT fk_kb_feedback_created_by FOREIGN KEY (created_by)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                       CONSTRAINT fk_kb_feedback_updated_by FOREIGN KEY (updated_by)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                       CONSTRAINT uk_kb_feedback_user UNIQUE (article_id, user_id) WHERE user_id IS NOT NULL
                   );

                   -- Comments
                   COMMENT ON TABLE socialcandor_schema.knowledge_base_feedback IS 'User feedback on knowledge base articles for content improvement';
                   COMMENT ON COLUMN socialcandor_schema.knowledge_base_feedback.feedback_type IS 'Type of feedback (helpful, not helpful, suggestion, error, outdated)';
                   COMMENT ON COLUMN socialcandor_schema.knowledge_base_feedback.search_query IS 'Search query that led to this article (for context)';
                   COMMENT ON COLUMN socialcandor_schema.knowledge_base_feedback.response IS 'Staff response to feedback';

                   -- Indexes for performance
                   CREATE INDEX idx_kb_feedback_article ON socialcandor_schema.knowledge_base_feedback(article_id, created_at DESC);
                   CREATE INDEX idx_kb_feedback_user ON socialcandor_schema.knowledge_base_feedback(user_id) WHERE user_id IS NOT NULL;
                   CREATE INDEX idx_kb_feedback_type ON socialcandor_schema.knowledge_base_feedback(feedback_type, was_helpful);
                   CREATE INDEX idx_kb_feedback_status ON socialcandor_schema.knowledge_base_feedback(status, created_at) WHERE status = 'NEW';

                   -- Trigger for updated_at
                   CREATE TRIGGER trg_knowledge_base_feedback_updated_at
                       BEFORE UPDATE ON socialcandor_schema.knowledge_base_feedback
                       FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                   -- RLS Policy
                   ALTER TABLE socialcandor_schema.knowledge_base_feedback ENABLE ROW LEVEL SECURITY;
                   CREATE POLICY kb_feedback_self_policy ON socialcandor_schema.knowledge_base_feedback
                       FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
                   CREATE POLICY kb_feedback_anonymous_policy ON socialcandor_schema.knowledge_base_feedback
                       FOR SELECT USING (user_id IS NULL AND session_id = current_setting('app.current_session_id')::UUID);
                   CREATE POLICY kb_feedback_staff_policy ON socialcandor_schema.knowledge_base_feedback
                       FOR ALL USING (EXISTS (
 SELECT 1 FROM socialcandor_schema.users
 WHERE user_id = current_setting('app.current_user_id')::UUID
 AND (is_admin = TRUE OR role IN ('SUPPORT', 'KNOWLEDGE_MANAGER'))
                       ));



                       --================================================================================================
                       -- Table: CS05 - kb_article_views
                       -- Description: Detailed analytics on knowledge base article views, including time spent,
                       --              scroll depth, and exit actions. Enables content optimization and ROI measurement.
                       -- Business Case: Understanding how users interact with knowledge base content is essential
                       --                for optimizing article effectiveness and measuring ROI. This table captures
                       --                granular view data: which articles are viewed, for how long, how far users
                       --                scroll, and what they do after reading (open ticket, search, exit). The data
                       --                reveals content gaps (articles that don't resolve issues) and high-value
                       --                content that successfully deflects tickets. Integration with search logs
                       --                connects queries to viewed articles, improving search relevance.
                       --
                       -- Key Performance Indicators (KPIs):
                       --   1. Article views - Total and unique views per article
                       --   2. Average time on page - Mean reading time per article
                       --   3. Scroll depth - Percentage of article viewed on average
                       --   4. Bounce rate - Percentage viewing only one article
                       --   5. Deflection rate - Percentage of views not followed by ticket creation
                       --
                       -- Feature References:
                       --   - KB07 (Article Analytics)
                       --   - KB08 (Content Performance)
                       --   - KB09 (Search Analytics)
                       --   - ANL13 (Content ROI)
                       --================================================================================================
                       CREATE TABLE IF NOT EXISTS socialcandor_schema.kb_article_views (
 -- Primary key
 view_id BIGSERIAL PRIMARY KEY,

 -- Human-readable identifier
 view_number VARCHAR(50) GENERATED ALWAYS AS (
     'KBV-' || TO_CHAR(viewed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.kb_article_views_seq')::TEXT, 6, '0')
 ) STORED,

 -- References
 article_id UUID NOT NULL,
 user_id UUID,                  -- NULL for anonymous
 session_id UUID,

 -- View metadata
 viewed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 exit_time TIMESTAMP WITH TIME ZONE,
 time_spent_seconds INTEGER CHECK (time_spent_seconds >= 0),

 -- Engagement metrics
 scroll_depth_percent INTEGER CHECK (scroll_depth_percent >= 0 AND scroll_depth_percent <= 100),
 link_clicks INTEGER DEFAULT 0,
 copied_content BOOLEAN DEFAULT FALSE,
 printed BOOLEAN DEFAULT FALSE,

 -- Source
 referrer_type VARCHAR(30) CHECK (referrer_type IN (
     'SEARCH', 'INTERNAL_LINK', 'EXTERNAL', 'EMAIL', 'SOCIAL', 'DIRECT'
 )),
 referrer_url VARCHAR(500),
 search_query TEXT,

 -- Exit action
 exit_action VARCHAR(50) CHECK (exit_action IN (
     'CLOSE', 'SEARCH', 'VIEW_ANOTHER', 'CREATE_TICKET', 'EXTERNAL_LINK'
 )),
 next_article_id UUID,          -- Next article viewed in session

 -- Device
 device_type VARCHAR(50),
 browser VARCHAR(100),
 os VARCHAR(100),

 -- Location
 ip_country VARCHAR(3),

 -- Ticket deflection (did this view prevent a ticket?)
 ticket_created BOOLEAN DEFAULT FALSE,
 ticket_id UUID,
 ticket_created_after_seconds INTEGER,

 -- Partition key for time-based partitioning
 view_date DATE GENERATED ALWAYS AS (viewed_at::DATE) STORED,

 -- Constraints
 CONSTRAINT fk_kb_views_article FOREIGN KEY (article_id)
     REFERENCES socialcandor_schema.knowledge_articles(article_id) ON DELETE CASCADE,
 CONSTRAINT fk_kb_views_user FOREIGN KEY (user_id)
     REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
 CONSTRAINT fk_kb_views_session FOREIGN KEY (session_id)
     REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
 CONSTRAINT fk_kb_views_next_article FOREIGN KEY (next_article_id)
     REFERENCES socialcandor_schema.knowledge_articles(article_id) ON DELETE SET NULL,
 CONSTRAINT fk_kb_views_ticket FOREIGN KEY (ticket_id)
     REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE SET NULL
                       ) PARTITION BY RANGE (view_date);

                       -- Comments
                       COMMENT ON TABLE socialcandor_schema.kb_article_views IS 'Detailed analytics on knowledge base article views for content optimization';
                       COMMENT ON COLUMN socialcandor_schema.kb_article_views.scroll_depth_percent IS 'How far down the article the user scrolled (%)';
                       COMMENT ON COLUMN socialcandor_schema.kb_article_views.exit_action IS 'What the user did after viewing the article';
                       COMMENT ON COLUMN socialcandor_schema.kb_article_views.ticket_created IS 'Whether a support ticket was created after viewing';

                       -- Create monthly partitions
                       DO $$
                       DECLARE
 start_date DATE;
 end_date DATE;
 partition_name TEXT;
                       BEGIN
 FOR i IN 0..11 LOOP
     start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
     end_date := start_date + '1 month'::INTERVAL;
     partition_name := 'kb_article_views_' || TO_CHAR(start_date, 'YYYY_MM');

     EXECUTE format('
         CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.kb_article_views
         FOR VALUES FROM (%L) TO (%L)',
         partition_name, start_date, end_date
     );
 END LOOP;
                       END $$;

                       -- Indexes for performance
                       CREATE INDEX idx_kb_views_article ON socialcandor_schema.kb_article_views(article_id, viewed_at DESC);
                       CREATE INDEX idx_kb_views_user ON socialcandor_schema.kb_article_views(user_id, viewed_at DESC) WHERE user_id IS NOT NULL;
                       CREATE INDEX idx_kb_views_session ON socialcandor_schema.kb_article_views(session_id) WHERE session_id IS NOT NULL;
                       CREATE INDEX idx_kb_views_ticket ON socialcandor_schema.kb_article_views(ticket_created, viewed_at) WHERE ticket_created = TRUE;

                       -- RLS Policy
                       ALTER TABLE socialcandor_schema.kb_article_views ENABLE ROW LEVEL SECURITY;
                       CREATE POLICY kb_views_self_policy ON socialcandor_schema.kb_article_views
 FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
                       CREATE POLICY kb_views_analytics_policy ON socialcandor_schema.kb_article_views
 FOR SELECT USING (EXISTS (
     SELECT 1 FROM socialcandor_schema.users
     WHERE user_id = current_setting('app.current_user_id')::UUID
     AND (is_admin = TRUE OR role IN ('ANALYST', 'KNOWLEDGE_MANAGER'))
 ));


 --================================================================================================
 -- Table: CS06 - ticket_escalation_paths
 -- Description: Defines escalation rules and paths for support tickets based on priority,
 --              category, and SLA violations. Enables automated escalation workflows.
 -- Business Case: Complex support organizations need structured escalation paths to ensure
 --                tickets reach the right expertise quickly. This table defines escalation
 --                rules based on ticket attributes (priority, category, customer tier) and
 --                triggers (SLA breaches, user requests). The design supports multi-level
 --                escalation (Level 1 → Level 2 → Level 3 → Management) with configurable
 --                time thresholds. Integration with notification system ensures all parties
 --                are informed. Historical escalation data supports analysis of escalation
 --                effectiveness and identification of training needs.
 --
 -- Key Performance Indicators (KPIs):
 --   1. Escalation rate - Percentage of tickets escalated
 --   2. Escalation effectiveness - Percentage of escalated tickets resolved at each level
 --   3. Time to escalate - Average time before escalation triggers
 --   4. Re-escalation rate - Tickets escalated multiple times
 --   5. Escalation accuracy - Percentage of escalations to correct team/agent
 --
 -- Feature References:
 --   - SUP16 (Escalation Management)
 --   - SUP17 (Workflow Automation)
 --   - SUP18 (Routing Rules)
 --   - WF05 (Escalation Workflows)
 --================================================================================================
 CREATE TABLE IF NOT EXISTS socialcandor_schema.ticket_escalation_paths (
     -- Primary key
     path_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

     -- Human-readable identifier
     path_number VARCHAR(50) GENERATED ALWAYS AS (
         'ESC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ticket_escalation_paths_seq')::TEXT, 6, '0')
     ) STORED,

     -- Path identification
     path_name VARCHAR(255) NOT NULL,
     path_description TEXT,
     is_active BOOLEAN DEFAULT TRUE,

     -- Trigger conditions
     trigger_type VARCHAR(50) NOT NULL CHECK (trigger_type IN (
         'SLA_VIOLATION', 'USER_REQUEST', 'CATEGORY_CHANGE', 'PRIORITY_CHANGE', 'TIME_BASED', 'MANUAL'
     )),
     trigger_criteria JSONB NOT NULL,                         -- Conditions that trigger escalation

     -- Filtering (which tickets this path applies to)
     applicable_categories TEXT[],  -- Ticket categories
     applicable_priorities VARCHAR(20)[],                     -- Priorities
     minimum_customer_tier INTEGER, -- Customer tier threshold
     applicable_products UUID[],    -- Product IDs

     -- Escalation steps
     escalation_steps JSONB NOT NULL,                          -- Array of steps with level, team, timeouts

     -- Notification rules
     notify_requester BOOLEAN DEFAULT TRUE,
     notify_previous_owner BOOLEAN DEFAULT TRUE,
     additional_recipients TEXT[],

     -- Timeout settings
     max_escalation_time_minutes INTEGER,                     -- Total time before final escalation
     reminder_interval_minutes INTEGER,                        -- How often to send reminders

     -- Fallback
     fallback_team_id UUID,          -- Team to escalate if no match

     -- Audit columns
     created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
     updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
     created_by UUID NOT NULL,
     updated_by UUID DEFAULT uuid_nil(),

     -- Constraints
     CONSTRAINT fk_escalation_paths_created_by FOREIGN KEY (created_by)
         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
     CONSTRAINT fk_escalation_paths_updated_by FOREIGN KEY (updated_by)
         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

     CONSTRAINT chk_escalation_paths_timeout CHECK (
         reminder_interval_minutes IS NULL OR
         reminder_interval_minutes <= max_escalation_time_minutes
     )
 );

 -- Comments
 COMMENT ON TABLE socialcandor_schema.ticket_escalation_paths IS 'Defines escalation rules and paths for support tickets';
 COMMENT ON COLUMN socialcandor_schema.ticket_escalation_paths.trigger_criteria IS 'JSON conditions that trigger escalation';
 COMMENT ON COLUMN socialcandor_schema.ticket_escalation_paths.escalation_steps IS 'Array of escalation steps with level, team, and timeouts';
 COMMENT ON COLUMN socialcandor_schema.ticket_escalation_paths.fallback_team_id IS 'Team to escalate to if no matching step found';

 -- Indexes for performance
 CREATE INDEX idx_escalation_paths_active ON socialcandor_schema.ticket_escalation_paths(is_active) WHERE is_active = TRUE;
 CREATE INDEX idx_escalation_paths_trigger ON socialcandor_schema.ticket_escalation_paths(trigger_type);

 -- Trigger for updated_at
 CREATE TRIGGER trg_ticket_escalation_paths_updated_at
     BEFORE UPDATE ON socialcandor_schema.ticket_escalation_paths
     FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

 -- RLS Policy
 ALTER TABLE socialcandor_schema.ticket_escalation_paths ENABLE ROW LEVEL SECURITY;
 CREATE POLICY escalation_paths_admin_policy ON socialcandor_schema.ticket_escalation_paths
     FOR ALL USING (socialcandor_schema.is_admin());
 CREATE POLICY escalation_paths_manager_policy ON socialcandor_schema.ticket_escalation_paths
     FOR SELECT USING (EXISTS (
         SELECT 1 FROM socialcandor_schema.users
         WHERE user_id = current_setting('app.current_user_id')::UUID
         AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
     ));


     --================================================================================================
     -- Table: CS07 - support_sla_definitions
     -- Description: Defines Service Level Agreements for support tickets based on customer tier,
     --              ticket priority, and issue category. Enables automated SLA tracking and enforcement.
     -- Business Case: Different customer segments and issue types require different service levels.
     --                This table defines SLAs for response time, resolution time, and update frequency
     --                based on customer tier (Enterprise, Business, Basic) and ticket priority.
     --                The design supports multiple SLA targets per combination (e.g., 1-hour response
     --                for Critical Enterprise tickets, 4-hours for High Business). SLAs can have
     --                different business hours (24/7 vs. business hours) and escalation thresholds.
     --                Integration with ticketing system enables automatic SLA calculation and tracking.
     --
     -- Key Performance Indicators (KPIs):
     --   1. SLA coverage - Percentage of tickets covered by defined SLAs
     --   2. Target achievability - Percentage of time SLA targets are met
     --   3. SLA accuracy - Correct SLA assignment rate
     --   4. Business hours impact - SLA performance during vs. outside business hours
     --   5. Tier differentiation - Service level differences by customer tier
     --
     -- Feature References:
     --   - SUP19 (SLA Definitions)
     --   - SUP20 (Service Tiers)
     --   - SUP21 (Business Hours)
     --   - COMP27 (SLA Compliance)
     --================================================================================================
     CREATE TABLE IF NOT EXISTS socialcandor_schema.support_sla_definitions (
         -- Primary key
         sla_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

         -- Human-readable identifier
         sla_number VARCHAR(50) GENERATED ALWAYS AS (
             'SSLA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.support_sla_definitions_seq')::TEXT, 6, '0')
         ) STORED,

         -- SLA identification
         sla_name VARCHAR(255) NOT NULL,
         sla_description TEXT,
         sla_version VARCHAR(20) DEFAULT '1.0',

         -- Applicability
         customer_tiers TEXT[] NOT NULL,                          -- Tiers this SLA applies to
         priorities VARCHAR(20)[] NOT NULL,                       -- Priorities covered
         categories TEXT[],                                       -- Categories (NULL = all)
         products UUID[],                                         -- Products (NULL = all)

         -- Response time targets (in minutes)
         initial_response_target INTEGER NOT NULL CHECK (initial_response_target >= 0),
         next_response_target INTEGER,                            -- For follow-up responses
         resolution_target INTEGER NOT NULL CHECK (resolution_target >= 0),
         update_frequency_target INTEGER,                          -- How often to update

         -- Business hours
         business_hours_id UUID,                                  -- Reference to business hours definition
         use_calendar_days BOOLEAN DEFAULT FALSE,                 -- FALSE = business hours only

         -- Escalation thresholds
         escalation_thresholds JSONB DEFAULT '[]',                 -- Array of {level, time, team}

         -- Overage handling
         overage_action VARCHAR(50) CHECK (overage_action IN (
             'NOTIFY_ONLY', 'ESCALATE', 'PENALTY', 'MANUAL_REVIEW'
         )),

         -- Penalties (for contractual SLAs)
         penalty_percentage NUMERIC(5,2),                          -- Penalty for breach (% of monthly fee)
         penalty_cap_percentage NUMERIC(5,2),                      -- Maximum penalty

         -- Reporting
         include_in_reports BOOLEAN DEFAULT TRUE,
         report_name VARCHAR(255),

         -- Status
         is_active BOOLEAN DEFAULT TRUE,
         effective_from DATE NOT NULL,
         effective_to DATE,
         superseded_by UUID,

         -- Audit columns
         created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
         updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
         created_by UUID NOT NULL,
         updated_by UUID DEFAULT uuid_nil(),

         -- Constraints
         CONSTRAINT fk_support_sla_superseded FOREIGN KEY (superseded_by)
             REFERENCES socialcandor_schema.support_sla_definitions(sla_id) ON DELETE SET NULL,
         CONSTRAINT fk_support_sla_created_by FOREIGN KEY (created_by)
             REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
         CONSTRAINT fk_support_sla_updated_by FOREIGN KEY (updated_by)
             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

         CONSTRAINT chk_support_sla_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
         CONSTRAINT chk_support_sla_targets CHECK (
             initial_response_target <= resolution_target AND
             (next_response_target IS NULL OR next_response_target <= resolution_target)
         )
     );

     -- Comments
     COMMENT ON TABLE socialcandor_schema.support_sla_definitions IS 'Defines Service Level Agreements for support tickets based on customer tier and priority';
     COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.customer_tiers IS 'Array of customer tiers this SLA applies to (Enterprise, Business, Basic)';
     COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.business_hours_id IS 'Reference to business hours definition for SLA calculation';
     COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.escalation_thresholds IS 'JSON array defining escalation levels and timeouts';
     COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.penalty_percentage IS 'Penalty percentage for SLA breach (contractual)';

     -- Indexes for performance
     CREATE INDEX idx_support_sla_active ON socialcandor_schema.support_sla_definitions(is_active, effective_from, effective_to);
     CREATE INDEX idx_support_sla_tiers ON socialcandor_schema.support_sla_definitions USING GIN (customer_tiers);
     CREATE INDEX idx_support_sla_priorities ON socialcandor_schema.support_sla_definitions USING GIN (priorities);

     -- Trigger for updated_at
     CREATE TRIGGER trg_support_sla_definitions_updated_at
         BEFORE UPDATE ON socialcandor_schema.support_sla_definitions
         FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

     -- RLS Policy
     ALTER TABLE socialcandor_schema.support_sla_definitions ENABLE ROW LEVEL SECURITY;
     CREATE POLICY support_sla_admin_policy ON socialcandor_schema.support_sla_definitions
         FOR ALL USING (socialcandor_schema.is_admin());
     CREATE POLICY support_sla_manager_policy ON socialcandor_schema.support_sla_definitions
         FOR SELECT USING (EXISTS (
             SELECT 1 FROM socialcandor_schema.users
             WHERE user_id = current_setting('app.current_user_id')::UUID
             AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
         ));

         --================================================================================================
         -- Table: AA01 - retention_cohorts
         -- Description: Pre-computed user retention cohorts for fast analytics, storing retention
         --              rates by cohort date and period. Enables historical retention analysis.
         -- Business Case: Retention is a critical metric for any platform, but calculating it
         --                on-the-fly from raw event data becomes prohibitively expensive as data grows.
         --                This table pre-computes retention cohorts, storing the number of users
         --                who registered in a given period and their activity in subsequent periods.
         --                The design supports multiple period types (daily, weekly, monthly) and
         --                various retention definitions (any activity, core activity, paid activity).
         --                Pre-computed data enables interactive dashboards and trend analysis without
         --                impacting production database performance. Historical cohort data supports
         --                analysis of retention trends and the impact of product changes.
         --
         -- Key Performance Indicators (KPIs):
         --   1. Cohort retention rate - Percentage of users active in each subsequent period
         --   2. Cohort size - Number of users in each registration cohort
         --   3. Retention curve - Shape of retention over time
         --   4. Cohort comparison - Retention differences across cohorts
         --   5. Breakout analysis - Retention by user segment within cohorts
         --
         -- Feature References:
         --   - ANL14 (Retention Analysis)
         --   - ANL15 (Cohort Analysis)
         --   - ANL16 (User Lifecycle)
         --   - DASH04 (Retention Dashboards)
         --================================================================================================
         CREATE TABLE IF NOT EXISTS socialcandor_schema.retention_cohorts (
             -- Primary key
             cohort_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

             -- Human-readable identifier
             cohort_number VARCHAR(50) GENERATED ALWAYS AS (
                 'COH-' || TO_CHAR(computed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.retention_cohorts_seq')::TEXT, 6, '0')
             ) STORED,

             -- Cohort definition
             cohort_date DATE NOT NULL,                              -- Registration/action date
             cohort_period VARCHAR(20) NOT NULL CHECK (cohort_period IN ('DAY', 'WEEK', 'MONTH', 'QUARTER')),
             cohort_size INTEGER NOT NULL CHECK (cohort_size >= 0),

             -- Segment (for filtered cohorts)
             segment_id UUID,                                         -- User segment
             country VARCHAR(3),                                      -- Country filter
             acquisition_channel VARCHAR(50),                         -- How users were acquired

             -- Retention data (by period index)
             period_0 INTEGER,                                        -- Initial period (usually cohort_size)
             period_1 INTEGER,                                        -- Period 1 retained users
             period_2 INTEGER,
             period_3 INTEGER,
             period_4 INTEGER,
             period_5 INTEGER,
             period_6 INTEGER,
             period_7 INTEGER,
             period_8 INTEGER,
             period_9 INTEGER,
             period_10 INTEGER,
             period_11 INTEGER,
             period_12 INTEGER,

             -- Retention rates (calculated)
             retention_rate_1 NUMERIC(5,2) GENERATED ALWAYS AS
                 (CASE WHEN period_0 > 0 THEN (period_1::NUMERIC / period_0::NUMERIC) * 100 ELSE 0 END) STORED,
             retention_rate_2 NUMERIC(5,2) GENERATED ALWAYS AS
                 (CASE WHEN period_0 > 0 THEN (period_2::NUMERIC / period_0::NUMERIC) * 100 ELSE 0 END) STORED,
             retention_rate_3 NUMERIC(5,2) GENERATED ALWAYS AS
                 (CASE WHEN period_0 > 0 THEN (period_3::NUMERIC / period_0::NUMERIC) * 100 ELSE 0 END) STORED,
             retention_rate_6 NUMERIC(5,2) GENERATED ALWAYS AS
                 (CASE WHEN period_0 > 0 THEN (period_6::NUMERIC / period_0::NUMERIC) * 100 ELSE 0 END) STORED,
             retention_rate_12 NUMERIC(5,2) GENERATED ALWAYS AS
                 (CASE WHEN period_0 > 0 THEN (period_12::NUMERIC / period_0::NUMERIC) * 100 ELSE 0 END) STORED,

             -- Activity definition (what counts as "retained")
             activity_definition VARCHAR(50) DEFAULT 'ANY_ACTIVITY' CHECK (activity_definition IN (
                 'ANY_ACTIVITY', 'CORE_ACTIVITY', 'PAID_ACTIVITY', 'CONTENT_CREATION', 'ENGAGEMENT'
             )),

             -- Computation metadata
             computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
             data_freshness_date DATE,                                -- Most recent data included

             -- Audit columns
             created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
             updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
             created_by UUID NOT NULL,
             updated_by UUID DEFAULT uuid_nil(),

             -- Constraints
             CONSTRAINT fk_retention_cohorts_segment FOREIGN KEY (segment_id)
                 REFERENCES socialcandor_schema.user_segments(segment_id) ON DELETE SET NULL,
             CONSTRAINT fk_retention_cohorts_created_by FOREIGN KEY (created_by)
                 REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
             CONSTRAINT fk_retention_cohorts_updated_by FOREIGN KEY (updated_by)
                 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

             CONSTRAINT uk_retention_cohort UNIQUE (cohort_date, cohort_period, segment_id, country, acquisition_channel, activity_definition)
         );

         -- Comments
         COMMENT ON TABLE socialcandor_schema.retention_cohorts IS 'Pre-computed user retention cohorts for fast analytics and dashboarding';
         COMMENT ON COLUMN socialcandor_schema.retention_cohorts.cohort_size IS 'Number of users in the initial cohort';
         COMMENT ON COLUMN socialcandor_schema.retention_cohorts.period_1 IS 'Users active in first subsequent period';
         COMMENT ON COLUMN socialcandor_schema.retention_cohorts.activity_definition IS 'Definition of what counts as "retained" activity';
         COMMENT ON COLUMN socialcandor_schema.retention_cohorts.retention_rate_12 IS '12-month retention rate (for annual analysis)';

         -- Indexes for performance
         CREATE INDEX idx_retention_cohorts_date ON socialcandor_schema.retention_cohorts(cohort_date DESC, cohort_period);
         CREATE INDEX idx_retention_cohorts_segment ON socialcandor_schema.retention_cohorts(segment_id) WHERE segment_id IS NOT NULL;
         CREATE INDEX idx_retention_cohorts_computed ON socialcandor_schema.retention_cohorts(computed_at DESC);

         -- Trigger for updated_at
         CREATE TRIGGER trg_retention_cohorts_updated_at
             BEFORE UPDATE ON socialcandor_schema.retention_cohorts
             FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

         -- RLS Policy
         ALTER TABLE socialcandor_schema.retention_cohorts ENABLE ROW LEVEL SECURITY;
         CREATE POLICY retention_cohorts_analyst_policy ON socialcandor_schema.retention_cohorts
             FOR SELECT USING (EXISTS (
                 SELECT 1 FROM socialcandor_schema.users
                 WHERE user_id = current_setting('app.current_user_id')::UUID
                 AND (is_admin = TRUE OR role IN ('ANALYST', 'DATA_SCIENTIST', 'PRODUCT_MANAGER'))
             ));


             --================================================================================================
             -- Table: AA02 - funnel_steps
             -- Description: Defines steps within conversion funnels for user journey analysis,
             --              enabling tracking of drop-off points and conversion optimization.
             -- Business Case: Understanding where users drop off in key flows (signup, purchase, content creation)
             --                is essential for conversion rate optimization. This table stores funnel step
             --                definitions, including the event or condition that defines each step, the
             --                order of steps, and whether steps are optional or required. The design supports
             --                multi-step funnels with branching paths (e.g., different onboarding flows).
             --                Integration with event tracking enables automated funnel analysis and reporting.
             --                Historical funnel data helps measure the impact of UX changes on conversion.
             --
             -- Key Performance Indicators (KPIs):
             --   1. Step completion rate - Percentage of users completing each step
             --   2. Drop-off rate - Percentage leaving at each step
             --   3. Funnel conversion rate - Overall completion rate
             --   4. Time between steps - Average duration between funnel stages
             --   5. Segment comparison - Funnel performance by user segment
             --
             -- Feature References:
             --   - ANL17 (Funnel Analysis)
             --   - ANL18 (Conversion Optimization)
             --   - ANL19 (User Journey)
             --   - UX02 (UX Analytics)
             --================================================================================================
             CREATE TABLE IF NOT EXISTS socialcandor_schema.funnel_steps (
                 -- Primary key
                 step_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                 -- Human-readable identifier
                 step_number VARCHAR(50) GENERATED ALWAYS AS (
                     'FSTP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.funnel_steps_seq')::TEXT, 6, '0')
                 ) STORED,

                 -- References
                 funnel_id UUID NOT NULL,                                 -- Parent funnel definition

                 -- Step identification
                 step_name VARCHAR(255) NOT NULL,
                 step_description TEXT,
                 step_order INTEGER NOT NULL CHECK (step_order >= 0),

                 -- Step type
                 step_type VARCHAR(30) CHECK (step_type IN (
                     'PAGE_VIEW', 'EVENT', 'ACTION', 'TIME_DELAY', 'CONDITION', 'SPLIT'
                 )),

                 -- Event definition (what constitutes completing this step)
                 event_name VARCHAR(255),                                 -- Name of the event
                 event_conditions JSONB,                                   -- Additional conditions (e.g., page URL, button ID)

                 -- Timing
                 time_constraint_minutes INTEGER,                          -- Must complete within X minutes

                 -- Branching (for A/B tests or different paths)
                 branch_name VARCHAR(100),                                 -- For split tests
                 next_step_id UUID,                                        -- Next step (NULL for last step)
                 alternative_step_id UUID,                                 -- Alternative branch

                 -- Step metadata
                 is_required BOOLEAN DEFAULT TRUE,
                 is_repeatable BOOLEAN DEFAULT FALSE,                     -- Can step be completed multiple times
                 max_repeats INTEGER,

                 -- Weight for scoring
                 step_weight NUMERIC(5,2) DEFAULT 1.0,

                 -- UI metadata
                 ui_label VARCHAR(100),
                 ui_color VARCHAR(20),
                 ui_icon VARCHAR(50),

                 -- Audit columns
                 created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                 updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                 created_by UUID NOT NULL,
                 updated_by UUID DEFAULT uuid_nil(),

                 -- Constraints
                 CONSTRAINT fk_funnel_steps_funnel FOREIGN KEY (funnel_id)
                     REFERENCES socialcandor_schema.conversion_funnel_definitions(funnel_id) ON DELETE CASCADE,
                 CONSTRAINT fk_funnel_steps_next FOREIGN KEY (next_step_id)
                     REFERENCES socialcandor_schema.funnel_steps(step_id) ON DELETE SET NULL,
                 CONSTRAINT fk_funnel_steps_alternative FOREIGN KEY (alternative_step_id)
                     REFERENCES socialcandor_schema.funnel_steps(step_id) ON DELETE SET NULL,
                 CONSTRAINT fk_funnel_steps_created_by FOREIGN KEY (created_by)
                     REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                 CONSTRAINT fk_funnel_steps_updated_by FOREIGN KEY (updated_by)
                     REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                 CONSTRAINT uk_funnel_step_order UNIQUE (funnel_id, step_order),
                 CONSTRAINT chk_funnel_steps_branch CHECK (
                     (branch_name IS NULL AND alternative_step_id IS NULL) OR
                     (branch_name IS NOT NULL)
                 )
             );

             -- Comments
             COMMENT ON TABLE socialcandor_schema.funnel_steps IS 'Defines steps within conversion funnels for user journey analysis';
             COMMENT ON COLUMN socialcandor_schema.funnel_steps.event_conditions IS 'JSON conditions for event completion (e.g., specific page, button)';
             COMMENT ON COLUMN socialcandor_schema.funnel_steps.branch_name IS 'Branch identifier for A/B tests or alternative paths';
             COMMENT ON COLUMN socialcandor_schema.funnel_steps.is_repeatable IS 'Whether the step can be completed multiple times';

             -- Indexes for performance
             CREATE INDEX idx_funnel_steps_funnel ON socialcandor_schema.funnel_steps(funnel_id, step_order);
             CREATE INDEX idx_funnel_steps_next ON socialcandor_schema.funnel_steps(next_step_id) WHERE next_step_id IS NOT NULL;
             CREATE INDEX idx_funnel_steps_event ON socialcandor_schema.funnel_steps(event_name) WHERE event_name IS NOT NULL;

             -- Trigger for updated_at
             CREATE TRIGGER trg_funnel_steps_updated_at
                 BEFORE UPDATE ON socialcandor_schema.funnel_steps
                 FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

             -- RLS Policy
             ALTER TABLE socialcandor_schema.funnel_steps ENABLE ROW LEVEL SECURITY;
             CREATE POLICY funnel_steps_analyst_policy ON socialcandor_schema.funnel_steps
                 FOR SELECT USING (EXISTS (
                     SELECT 1 FROM socialcandor_schema.users
                     WHERE user_id = current_setting('app.current_user_id')::UUID
                     AND (is_admin = TRUE OR role IN ('ANALYST', 'PRODUCT_MANAGER', 'MARKETING'))
                 ));
             CREATE POLICY funnel_steps_admin_policy ON socialcandor_schema.funnel_steps
                 FOR ALL USING (socialcandor_schema.is_admin());


                 --================================================================================================
                 -- Table: AA03 - kpi_definitions
                 -- Description: Central repository for KPI definitions, including calculation logic,
                 --              targets, and owners. Ensures consistent KPI measurement across the organization.
                 -- Business Case: As organizations grow, different teams may calculate the same KPI differently,
                 --                leading to confusion and misaligned decisions. This table serves as the
                 --                single source of truth for KPI definitions, storing the exact calculation
                 --                logic (SQL or formula), data sources, refresh frequency, and target values.
                 --                It also tracks ownership, ensuring accountability for each metric. The design
                 --                supports KPI hierarchies (parent KPIs roll up to child KPIs) and versioning
                 --                for tracking changes over time. Integration with dashboard tools enables
                 --                automated KPI display and alerting when targets are missed.
                 --
                 -- Key Performance Indicators (KPIs):
                 --   1. KPI coverage - Percentage of business areas with defined KPIs
                 --   2. Data freshness - Time since last KPI calculation
                 --   3. Target achievement - Percentage of KPIs meeting targets
                 --   4. KPI usage - Number of dashboards/reports using each KPI
                 --   5. Definition stability - Frequency of KPI logic changes
                 --
                 -- Feature References:
                 --   - ANL20 (KPI Management)
                 --   - ANL21 (Metrics Governance)
                 --   - DASH05 (KPI Dashboards)
                 --   - GOV11 (Metrics Governance)
                 --================================================================================================
                 CREATE TABLE IF NOT EXISTS socialcandor_schema.kpi_definitions (
                     -- Primary key
                     kpi_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                     -- Human-readable identifier
                     kpi_number VARCHAR(50) GENERATED ALWAYS AS (
                         'KPI-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.kpi_definitions_seq')::TEXT, 6, '0')
                     ) STORED,

                     -- KPI identification
                     kpi_code VARCHAR(100) UNIQUE NOT NULL,
                     kpi_name VARCHAR(255) NOT NULL,
                     kpi_description TEXT,
                     kpi_category VARCHAR(50) CHECK (kpi_category IN (
                         'USER', 'CONTENT', 'REVENUE', 'ENGAGEMENT', 'RETENTION', 'ACQUISITION', 'SUPPORT', 'PERFORMANCE'
                     )),
                     kpi_subcategory VARCHAR(100),

                     -- Calculation
                     calculation_method VARCHAR(50) CHECK (calculation_method IN (
                         'SQL', 'FORMULA', 'API', 'MANUAL', 'ML_MODEL'
                     )),
                     calculation_logic TEXT NOT NULL,                         -- SQL query or formula
                     data_sources TEXT[],                                     -- Tables/APIs used

                     -- Units and scale
                     unit VARCHAR(50),                                        -- e.g., 'users', 'percentage', 'seconds', 'dollars'
                     decimal_places INTEGER DEFAULT 0,
                     higher_is_better BOOLEAN DEFAULT TRUE,                   -- Direction for good performance

                     -- Targets
                     target_value NUMERIC,
                     warning_threshold NUMERIC,
                     critical_threshold NUMERIC,
                     stretch_goal NUMERIC,

                     -- Time dimensions
                     frequency VARCHAR(20) CHECK (frequency IN (
                         'REAL_TIME', 'HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY'
                     )),
                     comparison_period VARCHAR(20) CHECK (comparison_period IN (
                         'PREVIOUS_PERIOD', 'YEAR_AGO', 'TARGET', 'BENCHMARK'
                     )),

                     -- Ownership
                     owner_team VARCHAR(100),
                     owner_user_id UUID,
                     data_steward_id UUID,

                     -- Hierarchy
                     parent_kpi_id UUID,
                     child_kpis UUID[],                                       -- For roll-up KPIs

                     -- Versioning
                     version INTEGER DEFAULT 1,
                     valid_from DATE NOT NULL DEFAULT CURRENT_DATE,
                     valid_to DATE,
                     is_current BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL) STORED,
                     change_reason TEXT,

                     -- Documentation
                     definition_doc_url VARCHAR(500),
                     example_query TEXT,
                     notes TEXT,

                     -- Status
                     is_active BOOLEAN DEFAULT TRUE,
                     is_deprecated BOOLEAN DEFAULT FALSE,

                     -- Audit columns
                     created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                     updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                     created_by UUID NOT NULL,
                     updated_by UUID DEFAULT uuid_nil(),

                     -- Constraints
                     CONSTRAINT fk_kpi_definitions_owner FOREIGN KEY (owner_user_id)
                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                     CONSTRAINT fk_kpi_definitions_steward FOREIGN KEY (data_steward_id)
                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                     CONSTRAINT fk_kpi_definitions_parent FOREIGN KEY (parent_kpi_id)
                         REFERENCES socialcandor_schema.kpi_definitions(kpi_id) ON DELETE SET NULL,
                     CONSTRAINT fk_kpi_definitions_created_by FOREIGN KEY (created_by)
                         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                     CONSTRAINT fk_kpi_definitions_updated_by FOREIGN KEY (updated_by)
                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                     CONSTRAINT chk_kpi_definitions_dates CHECK (valid_to IS NULL OR valid_to >= valid_from)
                 );

                 -- Comments
                 COMMENT ON TABLE socialcandor_schema.kpi_definitions IS 'Central repository for KPI definitions with calculation logic and targets';
                 COMMENT ON COLUMN socialcandor_schema.kpi_definitions.calculation_logic IS 'SQL query or formula for calculating the KPI';
                 COMMENT ON COLUMN socialcandor_schema.kpi_definitions.higher_is_better IS 'Direction for good performance (true = higher values are better)';
                 COMMENT ON COLUMN socialcandor_schema.kpi_definitions.child_kpis IS 'Array of child KPI IDs that roll up to this KPI';

                 -- Indexes for performance
                 CREATE INDEX idx_kpi_definitions_code ON socialcandor_schema.kpi_definitions(kpi_code);
                 CREATE INDEX idx_kpi_definitions_category ON socialcandor_schema.kpi_definitions(kpi_category, is_active);
                 CREATE INDEX idx_kpi_definitions_owner ON socialcandor_schema.kpi_definitions(owner_user_id) WHERE owner_user_id IS NOT NULL;
                 CREATE INDEX idx_kpi_definitions_parent ON socialcandor_schema.kpi_definitions(parent_kpi_id) WHERE parent_kpi_id IS NOT NULL;

                 -- Trigger for updated_at
                 CREATE TRIGGER trg_kpi_definitions_updated_at
                     BEFORE UPDATE ON socialcandor_schema.kpi_definitions
                     FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                 -- RLS Policy
                 ALTER TABLE socialcandor_schema.kpi_definitions ENABLE ROW LEVEL SECURITY;
                 CREATE POLICY kpi_definitions_read_policy ON socialcandor_schema.kpi_definitions
                     FOR SELECT USING (TRUE);
                 CREATE POLICY kpi_definitions_admin_policy ON socialcandor_schema.kpi_definitions
                     FOR ALL USING (socialcandor_schema.is_admin());
                 CREATE POLICY kpi_definitions_owner_policy ON socialcandor_schema.kpi_definitions
                     FOR UPDATE USING (owner_user_id = current_setting('app.current_user_id')::UUID);


                     --================================================================================================
                     -- Table: AA04 - data_quality_incidents
                     -- Description: Tracks data quality incidents, including detection, investigation,
                     --              resolution, and root cause analysis. Supports data reliability engineering.
                     -- Business Case: Data quality issues can have significant business impact, from incorrect
                     --                reporting to failed ML models. This table provides a structured way to
                     --                track incidents from detection to resolution, ensuring accountability
                     --                and enabling root cause analysis. The design captures severity, impact,
                     --                affected assets, and resolution steps. Integration with data quality checks
                     --                enables automatic incident creation. Historical incident data supports
                     --                trend analysis and helps identify recurring issues requiring systemic fixes.
                     --                This is essential for data reliability engineering and building trust in data.
                     --
                     -- Key Performance Indicators (KPIs):
                     --   1. Mean Time to Detect (MTTD) - Time from incident occurrence to detection
                     --   2. Mean Time to Resolve (MTTR) - Time from detection to resolution
                     --   3. Incident volume - Number of incidents by severity
                     --   4. Recurrence rate - Percentage of incidents with same root cause
                     --   5. Data reliability score - Percentage of time data is accurate/available
                     --
                     -- Feature References:
                     --   - DQ09 (Data Quality Incidents)
                     --   - DQ10 (Incident Management)
                     --   - DQ11 (Root Cause Analysis)
                     --   - OPS06 (Data Reliability)
                     --================================================================================================
                     CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_incidents (
                         -- Primary key
                         incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                         -- Human-readable identifier
                         incident_number VARCHAR(50) GENERATED ALWAYS AS (
                             'DQINC-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_quality_incidents_seq')::TEXT, 6, '0')
                         ) STORED,

                         -- Incident identification
                         incident_title VARCHAR(255) NOT NULL,
                         incident_description TEXT,

                         -- Severity and impact
                         severity VARCHAR(30) NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
                         business_impact TEXT,
                         data_impact TEXT,                                      -- Which data is affected

                         -- Affected assets
                         affected_systems TEXT[],                                -- Systems/databases affected
                         affected_tables TEXT[],                                 -- Specific tables
                         affected_datasets TEXT[],                               -- Datasets/reports affected
                         row_count_affected INTEGER,

                         -- Timing
                         occurred_at TIMESTAMP WITH TIME ZONE,                    -- When the issue first occurred
                         detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                         detected_by UUID,                                       -- Who/what detected it
                         detection_method VARCHAR(100),                          -- Automated check, user report, etc.

                         -- Investigation
                         assigned_to UUID,
                         investigation_notes TEXT,
                         root_cause TEXT,
                         root_cause_category VARCHAR(50) CHECK (root_cause_category IN (
                             'SYSTEM_ERROR', 'PROCESS_ERROR', 'HUMAN_ERROR', 'EXTERNAL_DATA', 'INFRASTRUCTURE', 'UNKNOWN'
                         )),

                         -- Resolution
                         resolved_at TIMESTAMP WITH TIME ZONE,
                         resolved_by UUID,
                         resolution_notes TEXT,
                         resolution_action VARCHAR(50) CHECK (resolution_action IN (
                             'FIXED', 'WORKAROUND', 'RECONCILED', 'ACCEPTED_RISK', 'FALSE_POSITIVE'
                         )),

                         -- Prevention
                         corrective_measures TEXT,
                         preventative_measures TEXT,
                         follow_up_required BOOLEAN DEFAULT FALSE,
                         follow_up_date DATE,

                         -- Status
                         status VARCHAR(30) DEFAULT 'OPEN' CHECK (status IN (
                             'OPEN', 'INVESTIGATING', 'MITIGATING', 'RESOLVED', 'CLOSED', 'FALSE_POSITIVE'
                         )),

                         -- Audit columns
                         created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                         updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                         created_by UUID NOT NULL,
                         updated_by UUID DEFAULT uuid_nil(),

                         -- Constraints
                         CONSTRAINT fk_dq_incidents_detected_by FOREIGN KEY (detected_by)
                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                         CONSTRAINT fk_dq_incidents_assigned_to FOREIGN KEY (assigned_to)
                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                         CONSTRAINT fk_dq_incidents_resolved_by FOREIGN KEY (resolved_by)
                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                         CONSTRAINT fk_dq_incidents_created_by FOREIGN KEY (created_by)
                             REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                         CONSTRAINT fk_dq_incidents_updated_by FOREIGN KEY (updated_by)
                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                         CONSTRAINT chk_dq_incidents_dates CHECK (
                             (resolved_at IS NULL) OR (resolved_at >= detected_at)
                         )
                     );

                     -- Comments
                     COMMENT ON TABLE socialcandor_schema.data_quality_incidents IS 'Tracks data quality incidents from detection to resolution';
                     COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.severity IS 'Impact severity of the incident';
                     COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.affected_tables IS 'Specific tables affected by the incident';
                     COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.root_cause_category IS 'Categorized root cause for trend analysis';
                     COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.resolution_action IS 'Action taken to resolve the incident';

                     -- Indexes for performance
                     CREATE INDEX idx_dq_incidents_status ON socialcandor_schema.data_quality_incidents(status, severity);
                     CREATE INDEX idx_dq_incidents_detected ON socialcandor_schema.data_quality_incidents(detected_at DESC);
                     CREATE INDEX idx_dq_incidents_assigned ON socialcandor_schema.data_quality_incidents(assigned_to, status) WHERE assigned_to IS NOT NULL;
                     CREATE INDEX idx_dq_incidents_category ON socialcandor_schema.data_quality_incidents(root_cause_category) WHERE root_cause_category IS NOT NULL;

                     -- Trigger for updated_at
                     CREATE TRIGGER trg_data_quality_incidents_updated_at
                         BEFORE UPDATE ON socialcandor_schema.data_quality_incidents
                         FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                     -- RLS Policy
                     ALTER TABLE socialcandor_schema.data_quality_incidents ENABLE ROW LEVEL SECURITY;
                     CREATE POLICY dq_incidents_data_team_policy ON socialcandor_schema.data_quality_incidents
                         FOR ALL USING (EXISTS (
                             SELECT 1 FROM socialcandor_schema.users
                             WHERE user_id = current_setting('app.current_user_id')::UUID
                             AND (is_admin = TRUE OR role IN ('DATA_ENGINEER', 'DATA_STEWARD', 'DATA_SCIENTIST'))
                         ));

                         --================================================================================================
                         -- Table: AA05 - data_contracts
                         -- Description: Formal agreements between data producers and consumers, specifying schema,
                         --              quality expectations, SLAs, and change management procedures.
                         -- Business Case: As data ecosystems grow, dependencies between teams become complex.
                         --                Data contracts provide a formal agreement between data producers and
                         --                consumers, specifying what data is provided, its format, quality guarantees,
                         --                and update frequency. This reduces integration failures and improves trust.
                         --                The table tracks contract versions, compliance status, and breach history.
                         --                When a producer plans to change a schema, affected consumers can be notified
                         --                automatically. This is a key enabler for data mesh architectures and
                         --                distributed data ownership.
                         --
                         -- Key Performance Indicators (KPIs):
                         --   1. Contract coverage - Percentage of data assets covered by contracts
                         --   2. Compliance rate - Percentage of contracts meeting SLAs
                         --   3. Breach frequency - Number of contract breaches per period
                         --   4. Change impact - Average number of consumers affected by schema changes
                         --   5. Contract age - Time since last contract review/update
                         --
                         -- Feature References:
                         --   - DQ12 (Data Contracts)
                         --   - DQ13 (Service Level Agreements)
                         --   - GOV12 (Data Governance)
                         --   - MESH01 (Data Mesh)
                         --================================================================================================
                         CREATE TABLE IF NOT EXISTS socialcandor_schema.data_contracts (
                             -- Primary key
                             contract_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                             -- Human-readable identifier
                             contract_number VARCHAR(50) GENERATED ALWAYS AS (
                                 'DC-' || TO_CHAR(effective_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_contracts_seq')::TEXT, 6, '0')
                             ) STORED,

                             -- Contract identification
                             contract_name VARCHAR(255) NOT NULL,
                             contract_version VARCHAR(20) DEFAULT '1.0',
                             contract_description TEXT,

                             -- Parties
                             producer_team VARCHAR(100) NOT NULL,
                             producer_contact UUID,
                             consumer_team VARCHAR(100) NOT NULL,
                             consumer_contact UUID,

                             -- Data asset
                             asset_type VARCHAR(50) NOT NULL CHECK (asset_type IN ('TABLE', 'VIEW', 'STREAM', 'API', 'FILE', 'DATASET')),
                             asset_location VARCHAR(500) NOT NULL,                   -- Schema.table, API endpoint, etc.
                             asset_description TEXT,

                             -- Schema definition
                             schema_definition JSONB NOT NULL,                        -- Columns, types, descriptions
                             sample_data_url VARCHAR(500),
                             data_dictionary_url VARCHAR(500),

                             -- Quality expectations
                             quality_requirements JSONB,                              -- Completeness, accuracy, freshness
                             freshness_sla_minutes INTEGER,                           -- Maximum data age
                             completeness_threshold NUMERIC(5,2),                     -- Minimum completeness percentage

                             -- Service Level Agreements
                             availability_sla_percent NUMERIC(5,2),                   -- Uptime percentage
                             latency_sla_seconds INTEGER,                              -- Maximum query latency
                             support_sla_hours INTEGER,                                -- Response time for issues

                             -- Change management
                             change_notice_days INTEGER DEFAULT 30,                    -- Days notice before breaking changes
                             review_frequency_days INTEGER DEFAULT 90,
                             last_review_date DATE,
                             next_review_date DATE GENERATED ALWAYS AS (
                                 last_review_date + (review_frequency_days || ' days')::INTERVAL
                             ) STORED,

                             -- Status
                             status VARCHAR(30) DEFAULT 'ACTIVE' CHECK (status IN (
                                 'DRAFT', 'ACTIVE', 'SUSPENDED', 'TERMINATED', 'ARCHIVED'
                             )),
                             effective_date DATE NOT NULL,
                             expiry_date DATE,

                             -- Compliance tracking
                             compliance_status VARCHAR(30) DEFAULT 'COMPLIANT' CHECK (compliance_status IN (
                                 'COMPLIANT', 'AT_RISK', 'BREACHED', 'NOT_MONITORED'
                             )),
                             breach_count INTEGER DEFAULT 0,
                             last_breach_at TIMESTAMP WITH TIME ZONE,
                             last_breach_reason TEXT,

                             -- Audit columns
                             created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                             updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                             created_by UUID NOT NULL,
                             updated_by UUID DEFAULT uuid_nil(),

                             -- Constraints
                             CONSTRAINT fk_data_contracts_producer FOREIGN KEY (producer_contact)
                                 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                             CONSTRAINT fk_data_contracts_consumer FOREIGN KEY (consumer_contact)
                                 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                             CONSTRAINT fk_data_contracts_created_by FOREIGN KEY (created_by)
                                 REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                             CONSTRAINT fk_data_contracts_updated_by FOREIGN KEY (updated_by)
                                 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                             CONSTRAINT chk_data_contracts_dates CHECK (expiry_date IS NULL OR expiry_date >= effective_date)
                         );

                         -- Comments
                         COMMENT ON TABLE socialcandor_schema.data_contracts IS 'Formal agreements between data producers and consumers with schema and quality expectations';
                         COMMENT ON COLUMN socialcandor_schema.data_contracts.schema_definition IS 'JSON schema defining columns, types, and constraints';
                         COMMENT ON COLUMN socialcandor_schema.data_contracts.quality_requirements IS 'JSON defining data quality expectations';
                         COMMENT ON COLUMN socialcandor_schema.data_contracts.change_notice_days IS 'Days notice required before breaking changes';
                         COMMENT ON COLUMN socialcandor_schema.data_contracts.compliance_status IS 'Current compliance status of the contract';

                         -- Indexes for performance
                         CREATE INDEX idx_data_contracts_producer ON socialcandor_schema.data_contracts(producer_team, status);
                         CREATE INDEX idx_data_contracts_consumer ON socialcandor_schema.data_contracts(consumer_team, status);
                         CREATE INDEX idx_data_contracts_status ON socialcandor_schema.data_contracts(status, compliance_status);
                         CREATE INDEX idx_data_contracts_review ON socialcandor_schema.data_contracts(next_review_date) WHERE status = 'ACTIVE';

                         -- Trigger for updated_at
                         CREATE TRIGGER trg_data_contracts_updated_at
                             BEFORE UPDATE ON socialcandor_schema.data_contracts
                             FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                         -- RLS Policy
                         ALTER TABLE socialcandor_schema.data_contracts ENABLE ROW LEVEL SECURITY;
                         CREATE POLICY data_contracts_team_policy ON socialcandor_schema.data_contracts
                             FOR ALL USING (
                                 producer_team = current_setting('app.current_team') OR
                                 consumer_team = current_setting('app.current_team') OR
                                 EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE)
                             );

                             --================================================================================================
                             -- Table: AA06 - cost_allocation
                             -- Description: Tracks infrastructure and operational costs attributed to teams, projects,
                             --              and features. Enables showback/chargeback and cost optimization.
                             -- Business Case: As cloud costs grow, organizations need visibility into who is spending what.
                             --                This table allocates costs (compute, storage, data transfer, API calls) to
                             --                business units, teams, projects, and features. The design supports multiple
                             --                allocation methods (direct attribution, proportional splits, fixed percentages)
                             --                and various cost dimensions (by service, region, environment). Historical
                             --                data enables trend analysis and anomaly detection. Integration with budgeting
                             --                systems enables tracking against forecasts. This is essential for FinOps
                             --                practices and maintaining cloud cost efficiency.
                             --
                             -- Key Performance Indicators (KPIs):
                             --   1. Cost per team - Total and trending costs by team
                             --   2. Cost per feature - Feature-level cost attribution
                             --   3. Unit economics - Cost per user, per transaction, per API call
                             --   4. Anomaly detection - Unexpected cost spikes
                             --   5. Forecast accuracy - Predicted vs. actual costs
                             --
                             -- Feature References:
                             --   - FIN04 (Cost Management)
                             --   - FIN05 (FinOps)
                             --   - FIN06 (Showback/Chargeback)
                             --   - OPS07 (Cloud Cost Optimization)
                             --================================================================================================
                             CREATE TABLE IF NOT EXISTS socialcandor_schema.cost_allocation (
                                 -- Primary key
                                 allocation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                 -- Human-readable identifier
                                 allocation_number VARCHAR(50) GENERATED ALWAYS AS (
                                     'COST-' || TO_CHAR(cost_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.cost_allocation_seq')::TEXT, 6, '0')
                                 ) STORED,

                                 -- Cost dimensions
                                 cost_date DATE NOT NULL,
                                 cost_center VARCHAR(100) NOT NULL,
                                 team VARCHAR(100),
                                 project VARCHAR(100),
                                 feature VARCHAR(100),
                                 environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT', 'TEST')),

                                 -- Resource details
                                 service_provider VARCHAR(50) NOT NULL CHECK (service_provider IN ('AWS', 'GCP', 'AZURE', 'INTERNAL', 'THIRD_PARTY')),
                                 service_name VARCHAR(100) NOT NULL,                    -- EC2, S3, BigQuery, etc.
                                 resource_id VARCHAR(255),                               -- Specific resource identifier

                                 -- Cost details
                                 cost_amount NUMERIC(15,6) NOT NULL CHECK (cost_amount >= 0),
                                 currency CHAR(3) NOT NULL DEFAULT 'USD',
                                 usage_quantity NUMERIC(15,6),
                                 usage_unit VARCHAR(50),                                 -- hours, GB, requests

                                 -- Allocation method
                                 allocation_method VARCHAR(50) CHECK (allocation_method IN (
                                     'DIRECT', 'PROPORTIONAL', 'FIXED_PERCENTAGE', 'USAGE_BASED', 'MANUAL'
                                 )),
                                 allocation_percentage NUMERIC(5,2),                     -- For proportional splits

                                 -- Tags and metadata
                                 resource_tags JSONB,                                     -- Original cloud provider tags
                                 custom_labels JSONB,                                     -- Business-specific labels

                                 -- Billing reference
                                 invoice_id UUID,
                                 line_item_id VARCHAR(255),                               -- Provider line item ID

                                 -- Budget tracking
                                 budget_id UUID,
                                 budget_variance NUMERIC(15,6),

                                 -- Audit columns
                                 created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                 updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                 created_by UUID NOT NULL,
                                 updated_by UUID DEFAULT uuid_nil(),

                                 -- Constraints
                                 CONSTRAINT fk_cost_allocation_created_by FOREIGN KEY (created_by)
                                     REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                 CONSTRAINT fk_cost_allocation_updated_by FOREIGN KEY (updated_by)
                                     REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                                 CONSTRAINT chk_cost_allocation_percentage CHECK (
                                     allocation_percentage IS NULL OR (allocation_percentage >= 0 AND allocation_percentage <= 100)
                                 )
                             );

                             -- Comments
                             COMMENT ON TABLE socialcandor_schema.cost_allocation IS 'Tracks infrastructure and operational costs attributed to teams, projects, and features';
                             COMMENT ON COLUMN socialcandor_schema.cost_allocation.cost_center IS 'Business cost center for accounting';
                             COMMENT ON COLUMN socialcandor_schema.cost_allocation.allocation_method IS 'Method used to allocate this cost';
                             COMMENT ON COLUMN socialcandor_schema.cost_allocation.resource_tags IS 'Original cloud provider tags for the resource';
                             COMMENT ON COLUMN socialcandor_schema.cost_allocation.budget_variance IS 'Difference from budget (negative = under budget, positive = over)';

                             -- Indexes for performance
                             CREATE INDEX idx_cost_allocation_date ON socialcandor_schema.cost_allocation(cost_date DESC);
                             CREATE INDEX idx_cost_allocation_team ON socialcandor_schema.cost_allocation(team, cost_center, cost_date);
                             CREATE INDEX idx_cost_allocation_project ON socialcandor_schema.cost_allocation(project, cost_date);
                             CREATE INDEX idx_cost_allocation_provider ON socialcandor_schema.cost_allocation(service_provider, service_name, cost_date);
                             CREATE INDEX idx_cost_allocation_tags ON socialcandor_schema.cost_allocation USING GIN (resource_tags);

                             -- Trigger for updated_at
                             CREATE TRIGGER trg_cost_allocation_updated_at
                                 BEFORE UPDATE ON socialcandor_schema.cost_allocation
                                 FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                             -- RLS Policy
                             ALTER TABLE socialcandor_schema.cost_allocation ENABLE ROW LEVEL SECURITY;
                             CREATE POLICY cost_allocation_finance_policy ON socialcandor_schema.cost_allocation
                                 FOR ALL USING (EXISTS (
                                     SELECT 1 FROM socialcandor_schema.users
                                     WHERE user_id = current_setting('app.current_user_id')::UUID
                                     AND (is_admin = TRUE OR role IN ('FINANCE', 'FIN_OPS', 'ACCOUNTING'))
                                 ));
                             CREATE POLICY cost_allocation_manager_policy ON socialcandor_schema.cost_allocation
                                 FOR SELECT USING (team = current_setting('app.current_team') OR project = current_setting('app.current_project'));



                                 --================================================================================================
                                 -- Table: ML01 - model_training_runs
                                 -- Description: Tracks machine learning model training runs, including hyperparameters,
                                 --              metrics, data versions, and artifacts. Enables experiment tracking and reproducibility.
                                 -- Business Case: Machine learning development involves numerous experiments with different
                                 --                parameters, data versions, and algorithms. This table provides a complete
                                 --                audit trail of all training runs, enabling data scientists to compare
                                 --                results, reproduce successful models, and avoid repeating failed experiments.
                                 --                The design captures all critical metadata: hyperparameters, evaluation metrics,
                                 --                training and validation data versions, code version (git commit), and output
                                 --                artifact locations. This is essential for ML governance, regulatory compliance,
                                 --                and team collaboration. Integration with model registry enables promotion of
                                 --                successful runs to staging/production.
                                 --
                                 -- Key Performance Indicators (KPIs):
                                 --   1. Experiment velocity - Number of training runs per week
                                 --   2. Success rate - Percentage of runs producing viable models
                                 --   3. Model performance - Accuracy, precision, recall over time
                                 --   4. Time to train - Average training duration
                                 --   5. Resource utilization - Compute resources per run
                                 --
                                 -- Feature References:
                                 --   - MLOP13 (Experiment Tracking)
                                 --   - MLOP14 (Training Management)
                                 --   - MLOP15 (Model Registry)
                                 --   - GOV13 (ML Governance)
                                 --================================================================================================
                                 CREATE TABLE IF NOT EXISTS socialcandor_schema.model_training_runs (
                                     -- Primary key
                                     run_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                     -- Human-readable identifier
                                     run_number VARCHAR(50) GENERATED ALWAYS AS (
                                         'MLRUN-' || TO_CHAR(start_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_training_runs_seq')::TEXT, 6, '0')
                                     ) STORED,

                                     -- Model reference
                                     model_id UUID NOT NULL,
                                     model_version_id UUID,                                   -- Version created from this run

                                     -- Run metadata
                                     run_name VARCHAR(255),
                                     run_description TEXT,
                                     run_status VARCHAR(30) DEFAULT 'PENDING' CHECK (run_status IN (
                                         'PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED', 'TIMEOUT'
                                     )),

                                     -- Code version
                                     git_commit_hash VARCHAR(64),
                                     git_branch VARCHAR(100),
                                     code_version VARCHAR(100),
                                     training_script_path VARCHAR(500),

                                     -- Data versions
                                     training_data_version_id UUID,                           -- Link to dataset_versions
                                     validation_data_version_id UUID,
                                     test_data_version_id UUID,

                                     -- Hyperparameters
                                     hyperparameters JSONB NOT NULL,

                                     -- Metrics (primary)
                                     accuracy NUMERIC(10,8),
                                     precision NUMERIC(10,8),
                                     recall NUMERIC(10,8),
                                     f1_score NUMERIC(10,8),
                                     auc_roc NUMERIC(10,8),
                                     loss NUMERIC(10,8),

                                     -- Additional metrics
                                     additional_metrics JSONB,                                 -- Other metrics (custom)

                                     -- Timing
                                     start_time TIMESTAMP WITH TIME ZONE NOT NULL,
                                     end_time TIMESTAMP WITH TIME ZONE,
                                     duration_seconds INTEGER GENERATED ALWAYS AS (
                                         EXTRACT(EPOCH FROM (end_time - start_time))
                                     ) STORED,

                                     -- Resources
                                     compute_type VARCHAR(100),                                -- GPU type, instance type
                                     compute_hours NUMERIC(10,2),
                                     cost_estimate NUMERIC(15,6),

                                     -- Artifacts
                                     model_artifact_url VARCHAR(500),
                                     metrics_artifact_url VARCHAR(500),
                                     logs_url VARCHAR(500),
                                     checkpoint_urls TEXT[],

                                     -- Environment
                                     environment VARCHAR(50) CHECK (environment IN ('DEV', 'TEST', 'STAGING', 'PRODUCTION')),
                                     framework_version VARCHAR(50),
                                     library_versions JSONB,

                                     -- Owner
                                     created_by UUID NOT NULL,
                                     owned_by_team VARCHAR(100),

                                     -- Audit columns
                                     created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                     updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                     updated_by UUID DEFAULT uuid_nil(),

                                     -- Constraints
                                     CONSTRAINT fk_model_training_runs_model FOREIGN KEY (model_id)
                                         REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
                                     CONSTRAINT fk_model_training_runs_version FOREIGN KEY (model_version_id)
                                         REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE SET NULL,
                                     CONSTRAINT fk_model_training_runs_training_data FOREIGN KEY (training_data_version_id)
                                         REFERENCES socialcandor_schema.dataset_versions(version_id) ON DELETE SET NULL,
                                     CONSTRAINT fk_model_training_runs_validation_data FOREIGN KEY (validation_data_version_id)
                                         REFERENCES socialcandor_schema.dataset_versions(version_id) ON DELETE SET NULL,
                                     CONSTRAINT fk_model_training_runs_test_data FOREIGN KEY (test_data_version_id)
                                         REFERENCES socialcandor_schema.dataset_versions(version_id) ON DELETE SET NULL,
                                     CONSTRAINT fk_model_training_runs_created_by FOREIGN KEY (created_by)
                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                     CONSTRAINT fk_model_training_runs_updated_by FOREIGN KEY (updated_by)
                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                                 );

                                 -- Comments
                                 COMMENT ON TABLE socialcandor_schema.model_training_runs IS 'Tracks machine learning model training runs with hyperparameters, metrics, and artifacts';
                                 COMMENT ON COLUMN socialcandor_schema.model_training_runs.hyperparameters IS 'JSON object of hyperparameter values used in the run';
                                 COMMENT ON COLUMN socialcandor_schema.model_training_runs.additional_metrics IS 'JSON object of additional evaluation metrics';
                                 COMMENT ON COLUMN socialcandor_schema.model_training_runs.model_artifact_url IS 'URL to the saved model file';
                                 COMMENT ON COLUMN socialcandor_schema.model_training_runs.library_versions IS 'Versions of key libraries used (tensorflow, pytorch, sklearn, etc.)';

                                 -- Indexes for performance
                                 CREATE INDEX idx_model_training_runs_model ON socialcandor_schema.model_training_runs(model_id, start_time DESC);
                                 CREATE INDEX idx_model_training_runs_status ON socialcandor_schema.model_training_runs(run_status, start_time);
                                 CREATE INDEX idx_model_training_runs_metrics ON socialcandor_schema.model_training_runs(accuracy DESC, f1_score DESC);
                                 CREATE INDEX idx_model_training_runs_created ON socialcandor_schema.model_training_runs(created_by, created_at DESC);

                                 -- Trigger for updated_at
                                 CREATE TRIGGER trg_model_training_runs_updated_at
                                     BEFORE UPDATE ON socialcandor_schema.model_training_runs
                                     FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                                 -- RLS Policy
                                 ALTER TABLE socialcandor_schema.model_training_runs ENABLE ROW LEVEL SECURITY;
                                 CREATE POLICY model_training_runs_self_policy ON socialcandor_schema.model_training_runs
                                     FOR ALL USING (created_by = current_setting('app.current_user_id')::UUID);
                                 CREATE POLICY model_training_runs_team_policy ON socialcandor_schema.model_training_runs
                                     FOR SELECT USING (owned_by_team = current_setting('app.current_team'));
                                 CREATE POLICY model_training_runs_admin_policy ON socialcandor_schema.model_training_runs
                                     FOR ALL USING (socialcandor_schema.is_admin());

                                     --================================================================================================
                                     -- Table: ML02 - model_predictions
                                     -- Description: Logs every prediction made by machine learning models, including input data,
                                     --              output predictions, confidence scores, and metadata. Enables monitoring,
                                     --              debugging, and audit trails.
                                     -- Business Case: For regulated industries and critical ML applications, every prediction
                                     --                must be logged for audit, debugging, and model improvement. This table
                                     --                stores prediction requests and responses, including input features,
                                     --                output predictions, confidence scores, and latency. The data enables
                                     --                monitoring for drift (when prediction distribution changes), debugging
                                     --                of incorrect predictions, and collection of ground truth for retraining.
                                     --                Partitioning by date ensures query performance even with billions of
                                     --                predictions. The design supports both batch and real-time predictions,
                                     --                with request/response hashing for integrity verification.
                                     --
                                     -- Key Performance Indicators (KPIs):
                                     --   1. Prediction volume - Number of predictions per model per day
                                     --   2. Average latency - Prediction response time
                                     --   3. Error rate - Percentage of failed predictions
                                     --   4. Confidence distribution - Average confidence scores over time
                                     --   5. Data drift - Changes in input distribution
                                     --
                                     -- Feature References:
                                     --   - MLOP16 (Prediction Logging)
                                     --   - MLOP17 (Model Monitoring)
                                     --   - MLOP18 (Drift Detection)
                                     --   - AUD18 (Prediction Audit)
                                     --================================================================================================
                                     CREATE TABLE IF NOT EXISTS socialcandor_schema.model_predictions (
                                         -- Primary key
                                         prediction_id BIGSERIAL,

                                         -- Human-readable identifier
                                         prediction_number VARCHAR(50) GENERATED ALWAYS AS (
                                             'MPRED-' || TO_CHAR(prediction_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_predictions_seq')::TEXT, 6, '0')
                                         ) STORED,

                                         -- Model references
                                         model_id UUID NOT NULL,
                                         model_version_id UUID NOT NULL,
                                         deployment_id UUID,                                      -- Which deployment served this

                                         -- Request context
                                         request_id UUID,                                         -- For tracing
                                         user_id UUID,                                            -- Who made the request
                                         session_id UUID,
                                         api_key_id UUID,
                                         client_ip INET,

                                         -- Prediction data
                                         input_data JSONB NOT NULL,
                                         input_hash VARCHAR(64),                                  -- SHA-256 of input for deduplication
                                         output_data JSONB NOT NULL,
                                         output_hash VARCHAR(64),

                                         -- Confidence/Probability
                                         confidence_scores JSONB,                                 -- Per-class probabilities
                                         top_prediction VARCHAR(255),
                                         top_confidence NUMERIC(10,8),

                                         -- Metadata
                                         prediction_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                         latency_ms INTEGER CHECK (latency_ms >= 0),
                                         model_version_used VARCHAR(50),

                                         -- Batch info
                                         batch_id UUID,                                           -- For batch predictions
                                         batch_position INTEGER,

                                         -- Ground truth (for feedback loop)
                                         ground_truth JSONB,
                                         ground_truth_received_at TIMESTAMP WITH TIME ZONE,
                                         was_correct BOOLEAN,

                                         -- Feature store snapshot (optional)
                                         feature_snapshot_id UUID,

                                         -- Partition key
                                         prediction_date DATE GENERATED ALWAYS AS (prediction_time::DATE) STORED,

                                         -- Constraints
                                         CONSTRAINT pk_model_predictions PRIMARY KEY (prediction_id, prediction_date),
                                         CONSTRAINT fk_model_predictions_model FOREIGN KEY (model_id)
                                             REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
                                         CONSTRAINT fk_model_predictions_version FOREIGN KEY (model_version_id)
                                             REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
                                         CONSTRAINT fk_model_predictions_user FOREIGN KEY (user_id)
                                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                                         CONSTRAINT fk_model_predictions_session FOREIGN KEY (session_id)
                                             REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
                                         CONSTRAINT fk_model_predictions_api_key FOREIGN KEY (api_key_id)
                                             REFERENCES socialcandor_schema.api_keys(api_key_id) ON DELETE SET NULL
                                     ) PARTITION BY RANGE (prediction_date);

                                     -- Comments
                                     COMMENT ON TABLE socialcandor_schema.model_predictions IS 'Logs every model prediction for monitoring, debugging, and audit';
                                     COMMENT ON COLUMN socialcandor_schema.model_predictions.input_hash IS 'SHA-256 hash of input for deduplication';
                                     COMMENT ON COLUMN socialcandor_schema.model_predictions.confidence_scores IS 'JSON object of confidence scores per class';
                                     COMMENT ON COLUMN socialcandor_schema.model_predictions.ground_truth IS 'Actual outcome (for feedback loop)';
                                     COMMENT ON COLUMN socialcandor_schema.model_predictions.was_correct IS 'Whether prediction matched ground truth';

                                     -- Create monthly partitions
                                     DO $$
                                     DECLARE
                                         start_date DATE;
                                         end_date DATE;
                                         partition_name TEXT;
                                     BEGIN
                                         FOR i IN 0..11 LOOP
                                             start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
                                             end_date := start_date + '1 month'::INTERVAL;
                                             partition_name := 'model_predictions_' || TO_CHAR(start_date, 'YYYY_MM');

                                             EXECUTE format('
                                                 CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.model_predictions
                                                 FOR VALUES FROM (%L) TO (%L)',
                                                 partition_name, start_date, end_date
                                             );
                                         END LOOP;
                                     END $$;

                                     -- Indexes for performance
                                     CREATE INDEX idx_model_predictions_model ON socialcandor_schema.model_predictions(model_id, prediction_time DESC);
                                     CREATE INDEX idx_model_predictions_version ON socialcandor_schema.model_predictions(model_version_id, prediction_time DESC);
                                     CREATE INDEX idx_model_predictions_user ON socialcandor_schema.model_predictions(user_id, prediction_time DESC) WHERE user_id IS NOT NULL;
                                     CREATE INDEX idx_model_predictions_input ON socialcandor_schema.model_predictions(input_hash) WHERE input_hash IS NOT NULL;
                                     CREATE INDEX idx_model_predictions_ground_truth ON socialcandor_schema.model_predictions(ground_truth_received_at)
                                         WHERE ground_truth IS NOT NULL;

                                     -- RLS Policy
                                     ALTER TABLE socialcandor_schema.model_predictions ENABLE ROW LEVEL SECURITY;
                                     CREATE POLICY model_predictions_admin_policy ON socialcandor_schema.model_predictions
                                         FOR ALL USING (socialcandor_schema.is_admin());
                                     CREATE POLICY model_predictions_ml_team_policy ON socialcandor_schema.model_predictions
                                         FOR SELECT USING (EXISTS (
                                             SELECT 1 FROM socialcandor_schema.users
                                             WHERE user_id = current_setting('app.current_user_id')::UUID
                                             AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER', 'RESEARCHER')
                                         ));

                                         --================================================================================================
                                         -- Table: ML03 - model_drift_metrics
                                         -- Description: Tracks model drift over time, including data drift, concept drift,
                                         --              and prediction drift. Enables automated alerts and retraining triggers.
                                         -- Business Case: Model performance degrades over time as data distributions change
                                         --                (data drift) or relationships change (concept drift). This table
                                         --                stores drift metrics computed at regular intervals, enabling proactive
                                         --                monitoring and automated retraining. The design supports multiple
                                         --                drift detection methods (PSI, KS-test, Earth Mover's Distance) and
                                         --                tracks drift by feature, by segment, and overall. When drift exceeds
                                         --                thresholds, alerts can be triggered and retraining pipelines initiated.
                                         --                Historical drift data helps identify patterns and plan model updates.
                                         --
                                         -- Key Performance Indicators (KPIs):
                                         --   1. Drift detection time - Time from drift onset to detection
                                         --   2. Drift magnitude - Severity of detected drift
                                         --   3. Features drifting - Most common drifting features
                                         --   4. Retraining trigger rate - Percentage of drift events triggering retraining
                                         --   5. Model stability - Time between significant drift events
                                         --
                                         -- Feature References:
                                         --   - MLOP19 (Drift Detection)
                                         --   - MLOP20 (Model Monitoring)
                                         --   - MLOP21 (Automated Retraining)
                                         --   - OBS08 (ML Observability)
                                         --================================================================================================
                                         CREATE TABLE IF NOT EXISTS socialcandor_schema.model_drift_metrics (
                                             -- Primary key
                                             metric_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                             -- Human-readable identifier
                                             metric_number VARCHAR(50) GENERATED ALWAYS AS (
                                                 'DRIFT-' || TO_CHAR(computation_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_drift_metrics_seq')::TEXT, 6, '0')
                                             ) STORED,

                                             -- Model references
                                             model_id UUID NOT NULL,
                                             model_version_id UUID,                                   -- Version being monitored
                                             baseline_version_id UUID,                                -- Version used as baseline

                                             -- Drift details
                                             drift_type VARCHAR(30) NOT NULL CHECK (drift_type IN (
                                                 'DATA_DRIFT', 'CONCEPT_DRIFT', 'PREDICTION_DRIFT', 'FEATURE_DRIFT'
                                             )),
                                             computation_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

                                             -- Overall metrics
                                             overall_drift_score NUMERIC(10,6) CHECK (overall_drift_score >= 0),
                                             drift_detected BOOLEAN DEFAULT FALSE,
                                             drift_severity VARCHAR(20) CHECK (drift_severity IN ('NONE', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

                                             -- Per-feature drift
                                             feature_drift JSONB,                                      -- Map of feature → drift score
                                             drifting_features TEXT[],                                 -- Features with significant drift

                                             -- Data statistics
                                             reference_stats JSONB,                                    -- Statistics from baseline period
                                             current_stats JSONB,                                      -- Statistics from current period
                                             sample_size INTEGER,

                                             -- Thresholds
                                             warning_threshold NUMERIC(10,6),
                                             critical_threshold NUMERIC(10,6),

                                             -- Alerting
                                             alert_sent BOOLEAN DEFAULT FALSE,
                                             alert_sent_at TIMESTAMP WITH TIME ZONE,

                                             -- Retraining
                                             retraining_triggered BOOLEAN DEFAULT FALSE,
                                             retraining_run_id UUID,                                   -- Training run triggered

                                             -- Partition key
                                             computation_date DATE GENERATED ALWAYS AS (computation_time::DATE) STORED,

                                             -- Constraints
                                             CONSTRAINT fk_model_drift_metrics_model FOREIGN KEY (model_id)
                                                 REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
                                             CONSTRAINT fk_model_drift_metrics_version FOREIGN KEY (model_version_id)
                                                 REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE SET NULL,
                                             CONSTRAINT fk_model_drift_metrics_baseline FOREIGN KEY (baseline_version_id)
                                                 REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE SET NULL,
                                             CONSTRAINT fk_model_drift_metrics_retraining FOREIGN KEY (retraining_run_id)
                                                 REFERENCES socialcandor_schema.model_training_runs(run_id) ON DELETE SET NULL
                                         ) PARTITION BY RANGE (computation_date);

                                         -- Comments
                                         COMMENT ON TABLE socialcandor_schema.model_drift_metrics IS 'Tracks model drift over time for proactive monitoring and retraining';
                                         COMMENT ON COLUMN socialcandor_schema.model_drift_metrics.drift_type IS 'Type of drift detected (data, concept, prediction, feature)';
                                         COMMENT ON COLUMN socialcandor_schema.model_drift_metrics.feature_drift IS 'JSON map of feature names to drift scores';
                                         COMMENT ON COLUMN socialcandor_schema.model_drift_metrics.reference_stats IS 'Statistical summary of baseline period';
                                         COMMENT ON COLUMN socialcandor_schema.model_drift_metrics.current_stats IS 'Statistical summary of current period';

                                         -- Create monthly partitions
                                         DO $$
                                         DECLARE
                                             start_date DATE;
                                             end_date DATE;
                                             partition_name TEXT;
                                         BEGIN
                                             FOR i IN 0..11 LOOP
                                                 start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
                                                 end_date := start_date + '1 month'::INTERVAL;
                                                 partition_name := 'model_drift_metrics_' || TO_CHAR(start_date, 'YYYY_MM');

                                                 EXECUTE format('
                                                     CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.model_drift_metrics
                                                     FOR VALUES FROM (%L) TO (%L)',
                                                     partition_name, start_date, end_date
                                                 );
                                             END LOOP;
                                         END $$;

                                         -- Indexes for performance
                                         CREATE INDEX idx_model_drift_metrics_model ON socialcandor_schema.model_drift_metrics(model_id, computation_time DESC);
                                         CREATE INDEX idx_model_drift_metrics_detected ON socialcandor_schema.model_drift_metrics(drift_detected, drift_severity);
                                         CREATE INDEX idx_model_drift_metrics_alert ON socialcandor_schema.model_drift_metrics(alert_sent, computation_time) WHERE alert_sent = FALSE;

                                         -- Trigger for alerting on drift
                                         CREATE OR REPLACE FUNCTION socialcandor_schema.drift_alert_trigger()
                                         RETURNS TRIGGER AS $$
                                         BEGIN
                                             -- Check if drift exceeds critical threshold
                                             IF NEW.drift_detected AND NEW.drift_severity IN ('HIGH', 'CRITICAL') AND NEW.alert_sent = FALSE THEN
                                                 NEW.alert_sent := TRUE;
                                                 NEW.alert_sent_at := CURRENT_TIMESTAMP;

                                                 -- Insert anomaly alert
                                                 INSERT INTO socialcandor_schema.anomaly_alerts (
                                                     alert_name, severity, source_system, description, metadata, created_by
                                                 ) VALUES (
                                                     'Model Drift Detected',
                                                     CASE WHEN NEW.drift_severity = 'CRITICAL' THEN 'CRITICAL' ELSE 'HIGH' END,
                                                     'model_monitoring',
                                                     format('Model %s has detected %s drift', NEW.model_id, NEW.drift_type),
                                                     jsonb_build_object('drift_score', NEW.overall_drift_score, 'drift_type', NEW.drift_type),
                                                     (SELECT user_id FROM socialcandor_schema.users WHERE username = 'system')
                                                 );

                                                 -- Optionally trigger retraining
                                                 IF NEW.overall_drift_score >= NEW.critical_threshold THEN
                                                     NEW.retraining_triggered := TRUE;
                                                     -- Retraining logic would be handled by separate process
                                                 END IF;
                                             END IF;

                                             RETURN NEW;
                                         END;
                                         $$ LANGUAGE plpgsql;

                                         CREATE TRIGGER trg_model_drift_metrics_alert
                                             BEFORE INSERT ON socialcandor_schema.model_drift_metrics
                                             FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.drift_alert_trigger();

                                         -- RLS Policy
                                         ALTER TABLE socialcandor_schema.model_drift_metrics ENABLE ROW LEVEL SECURITY;
                                         CREATE POLICY model_drift_metrics_ml_team_policy ON socialcandor_schema.model_drift_metrics
                                             FOR SELECT USING (EXISTS (
                                                 SELECT 1 FROM socialcandor_schema.users
                                                 WHERE user_id = current_setting('app.current_user_id')::UUID
                                                 AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER', 'ML_OPS')
                                             ));
                                         CREATE POLICY model_drift_metrics_admin_policy ON socialcandor_schema.model_drift_metrics
                                             FOR ALL USING (socialcandor_schema.is_admin());

                                             --================================================================================================
                                             -- Table: ML04 - feature_values
                                             -- Description: Feature store for machine learning, storing time-series feature values
                                             --              for training and inference. Enables feature reuse and consistent definitions.
                                             -- Business Case: In ML systems, the same features are often used across multiple models.
                                             --                A feature store centralizes feature computation and storage, ensuring
                                             --                consistency between training and inference. This table stores feature
                                             --                values keyed by entity (user, product, etc.) and timestamp, enabling
                                             --                point-in-time correct feature retrieval for training. The design supports
                                             --                both batch and real-time feature pipelines, with versioning for feature
                                             --                definitions. This is a foundational component for MLOps at scale.
                                             --
                                             -- Key Performance Indicators (KPIs):
                                             --   1. Feature coverage - Percentage of entities with complete feature data
                                             --   2. Feature freshness - Time since last feature update
                                             --   3. Feature latency - Time from event to feature availability
                                             --   4. Feature usage - Number of models using each feature
                                             --   5. Storage efficiency - Compression ratio of feature data
                                             --
                                             -- Feature References:
                                             --   - MLOP22 (Feature Store)
                                             --   - MLOP23 (Feature Engineering)
                                             --   - MLOP24 (Training Data)
                                             --   - MLOP25 (Online Features)
                                             --================================================================================================
                                             CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_values (
                                                 -- Primary key
                                                 value_id BIGSERIAL,

                                                 -- Feature identification
                                                 feature_id UUID NOT NULL,
                                                 feature_version INTEGER DEFAULT 1,

                                                 -- Entity (what the feature is about)
                                                 entity_type VARCHAR(50) NOT NULL CHECK (entity_type IN ('USER', 'POST', 'PRODUCT', 'SESSION', 'ORGANIZATION')),
                                                 entity_id VARCHAR(255) NOT NULL,

                                                 -- Feature value (one of these will be non-null based on feature type)
                                                 value_numeric NUMERIC,
                                                 value_string TEXT,
                                                 value_boolean BOOLEAN,
                                                 value_json JSONB,
                                                 value_timestamp TIMESTAMP WITH TIME ZONE,

                                                 -- Value metadata
                                                 value_created_at TIMESTAMP WITH TIME ZONE NOT NULL,      -- When the value was created
                                                 value_updated_at TIMESTAMP WITH TIME ZONE,               -- When the value was last updated

                                                 -- Feature timestamp (point-in-time validity)
                                                 feature_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,     -- When this value was true
                                                 valid_from TIMESTAMP WITH TIME ZONE NOT NULL,
                                                 valid_to TIMESTAMP WITH TIME ZONE,
                                                 is_current BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL) STORED,

                                                 -- Pipeline metadata
                                                 pipeline_id UUID,                                         -- Which pipeline generated this
                                                 job_id UUID,
                                                 data_source VARCHAR(255),                                 -- Source table/stream

                                                 -- Quality
                                                 quality_score NUMERIC(5,2) CHECK (quality_score >= 0 AND quality_score <= 100),
                                                 is_imputed BOOLEAN DEFAULT FALSE,
                                                 imputation_method VARCHAR(100),

                                                 -- Partition key
                                                 value_date DATE GENERATED ALWAYS AS (feature_timestamp::DATE) STORED,

                                                 -- Constraints
                                                 CONSTRAINT pk_feature_values PRIMARY KEY (value_id, value_date),
                                                 CONSTRAINT fk_feature_values_feature FOREIGN KEY (feature_id)
                                                     REFERENCES socialcandor_schema.feature_definitions(feature_id) ON DELETE CASCADE,
                                                 CONSTRAINT chk_feature_values_type CHECK (
                                                     (value_numeric IS NOT NULL)::INTEGER +
                                                     (value_string IS NOT NULL)::INTEGER +
                                                     (value_boolean IS NOT NULL)::INTEGER +
                                                     (value_json IS NOT NULL)::INTEGER +
                                                     (value_timestamp IS NOT NULL)::INTEGER = 1
                                                 ),
                                                 CONSTRAINT chk_feature_values_dates CHECK (valid_to IS NULL OR valid_to > valid_from)
                                             ) PARTITION BY RANGE (value_date);

                                             -- Comments
                                             COMMENT ON TABLE socialcandor_schema.feature_values IS 'Feature store for machine learning, storing time-series feature values';
                                             COMMENT ON COLUMN socialcandor_schema.feature_values.entity_type IS 'Type of entity the feature describes';
                                             COMMENT ON COLUMN socialcandor_schema.feature_values.entity_id IS 'Identifier of the entity';
                                             COMMENT ON COLUMN socialcandor_schema.feature_values.feature_timestamp IS 'Point in time when this feature value was true';
                                             COMMENT ON COLUMN socialcandor_schema.feature_values.valid_from IS 'Start of validity period (for slowly changing features)';
                                             COMMENT ON COLUMN socialcandor_schema.feature_values.valid_to IS 'End of validity period (NULL = current)';

                                             -- Create monthly partitions
                                             DO $$
                                             DECLARE
                                                 start_date DATE;
                                                 end_date DATE;
                                                 partition_name TEXT;
                                             BEGIN
                                                 FOR i IN 0..11 LOOP
                                                     start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
                                                     end_date := start_date + '1 month'::INTERVAL;
                                                     partition_name := 'feature_values_' || TO_CHAR(start_date, 'YYYY_MM');

                                                     EXECUTE format('
                                                         CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.feature_values
                                                         FOR VALUES FROM (%L) TO (%L)',
                                                         partition_name, start_date, end_date
                                                     );
                                                 END LOOP;
                                             END $$;

                                             -- Indexes for performance
                                             CREATE INDEX idx_feature_values_feature ON socialcandor_schema.feature_values(feature_id, feature_timestamp DESC);
                                             CREATE INDEX idx_feature_values_entity ON socialcandor_schema.feature_values(entity_type, entity_id, feature_timestamp DESC);
                                             CREATE INDEX idx_feature_values_current ON socialcandor_schema.feature_values(feature_id, entity_id) WHERE is_current = TRUE;
                                             CREATE INDEX idx_feature_values_quality ON socialcandor_schema.feature_values(quality_score) WHERE quality_score < 100;

                                             -- RLS Policy
                                             ALTER TABLE socialcandor_schema.feature_values ENABLE ROW LEVEL SECURITY;
                                             CREATE POLICY feature_values_ml_team_policy ON socialcandor_schema.feature_values
                                                 FOR SELECT USING (EXISTS (
                                                     SELECT 1 FROM socialcandor_schema.users
                                                     WHERE user_id = current_setting('app.current_user_id')::UUID
                                                     AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER', 'DATA_ENGINEER')
                                                 ));
                                             CREATE POLICY feature_values_admin_policy ON socialcandor_schema.feature_values
                                                 FOR ALL USING (socialcandor_schema.is_admin());

                                                 --================================================================================================
                                                 -- Table: ML05 - model_bias_tests
                                                 -- Description: Records fairness and bias testing results for machine learning models,
                                                 --              including disparate impact, demographic parity, and equal opportunity metrics.
                                                 -- Business Case: As AI systems increasingly impact people's lives, ensuring fairness and
                                                 --                mitigating bias is both an ethical imperative and a regulatory requirement
                                                 --                (EU AI Act, NYC Bias Audit Law). This table stores the results of bias
                                                 --                tests across protected attributes (race, gender, age, etc.), tracking
                                                 --                metrics like disparate impact ratio, demographic parity difference, and
                                                 --                equal opportunity difference. The design supports testing at multiple
                                                 --                thresholds and across different model versions. Historical data enables
                                                 --                tracking of fairness improvements and compliance reporting.
                                                 --
                                                 -- Key Performance Indicators (KPIs):
                                                 --   1. Bias detection rate - Percentage of models with identified bias
                                                 --   2. Fairness score - Composite fairness metric
                                                 --   3. Protected groups - Distribution of outcomes across protected attributes
                                                 --   4. Mitigation effectiveness - Improvement in fairness after interventions
                                                 --   5. Compliance coverage - Percentage of models tested for bias
                                                 --
                                                 -- Feature References:
                                                 --   - AIETH07 (Bias Testing)
                                                 --   - AIETH08 (Fairness Metrics)
                                                 --   - AIETH09 (Model Auditing)
                                                 --   - COMP28 (AI Compliance)
                                                 --================================================================================================
                                                 CREATE TABLE IF NOT EXISTS socialcandor_schema.model_bias_tests (
                                                     -- Primary key
                                                     test_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                                     -- Human-readable identifier
                                                     test_number VARCHAR(50) GENERATED ALWAYS AS (
                                                         'BIAS-' || TO_CHAR(test_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.model_bias_tests_seq')::TEXT, 6, '0')
                                                     ) STORED,

                                                     -- Model references
                                                     model_id UUID NOT NULL,
                                                     model_version_id UUID NOT NULL,
                                                     training_run_id UUID,                                    -- Run that produced this version

                                                     -- Test metadata
                                                     test_date DATE NOT NULL DEFAULT CURRENT_DATE,
                                                     tested_by UUID NOT NULL,
                                                     test_description TEXT,

                                                     -- Protected attributes tested
                                                     protected_attributes TEXT[] NOT NULL,                    -- e.g., ['gender', 'race', 'age']

                                                     -- Fairness metrics (overall)
                                                     disparate_impact_ratio NUMERIC(10,6),                    -- Should be > 0.8
                                                     demographic_parity_difference NUMERIC(10,6),             -- Should be < 0.1
                                                     equal_opportunity_difference NUMERIC(10,6),              -- Should be < 0.1

                                                     -- Per-attribute metrics
                                                     attribute_metrics JSONB NOT NULL,                         -- Detailed metrics per attribute

                                                     -- Test results
                                                     test_outcome VARCHAR(30) CHECK (test_outcome IN (
                                                         'PASS', 'FAIL', 'WARNING', 'INCONCLUSIVE'
                                                     )),
                                                     threshold_used NUMERIC(5,2),                              -- Threshold for pass/fail

                                                     -- Dataset used
                                                     test_dataset_id UUID,
                                                     test_dataset_size INTEGER,

                                                     -- Mitigation recommendations
                                                     detected_bias_types TEXT[],
                                                     mitigation_suggestions TEXT,

                                                     -- Report
                                                     report_url VARCHAR(500),
                                                     report_summary TEXT,

                                                     -- Review
                                                     reviewed_by UUID,
                                                     reviewed_at TIMESTAMP WITH TIME ZONE,
                                                     review_notes TEXT,

                                                     -- Audit columns
                                                     created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                     updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                     created_by UUID NOT NULL,
                                                     updated_by UUID DEFAULT uuid_nil(),

                                                     -- Constraints
                                                     CONSTRAINT fk_model_bias_tests_model FOREIGN KEY (model_id)
                                                         REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
                                                     CONSTRAINT fk_model_bias_tests_version FOREIGN KEY (model_version_id)
                                                         REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
                                                     CONSTRAINT fk_model_bias_tests_run FOREIGN KEY (training_run_id)
                                                         REFERENCES socialcandor_schema.model_training_runs(run_id) ON DELETE SET NULL,
                                                     CONSTRAINT fk_model_bias_tests_tested_by FOREIGN KEY (tested_by)
                                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                                     CONSTRAINT fk_model_bias_tests_reviewed_by FOREIGN KEY (reviewed_by)
                                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                                                     CONSTRAINT fk_model_bias_tests_created_by FOREIGN KEY (created_by)
                                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                                     CONSTRAINT fk_model_bias_tests_updated_by FOREIGN KEY (updated_by)
                                                         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                                                 );

                                                 -- Comments
                                                 COMMENT ON TABLE socialcandor_schema.model_bias_tests IS 'Records fairness and bias testing results for machine learning models';
                                                 COMMENT ON COLUMN socialcandor_schema.model_bias_tests.protected_attributes IS 'Array of protected attributes tested (gender, race, age, etc.)';
                                                 COMMENT ON COLUMN socialcandor_schema.model_bias_tests.disparate_impact_ratio IS 'Ratio of favorable outcomes for protected vs. reference group (should be > 0.8)';
                                                 COMMENT ON COLUMN socialcandor_schema.model_bias_tests.attribute_metrics IS 'JSON object with detailed metrics per protected attribute';
                                                 COMMENT ON COLUMN socialcandor_schema.model_bias_tests.detected_bias_types IS 'Types of bias detected in the model';

                                                 -- Indexes for performance
                                                 CREATE INDEX idx_model_bias_tests_model ON socialcandor_schema.model_bias_tests(model_id, model_version_id, test_date DESC);
                                                 CREATE INDEX idx_model_bias_tests_outcome ON socialcandor_schema.model_bias_tests(test_outcome, test_date);
                                                 CREATE INDEX idx_model_bias_tests_tested_by ON socialcandor_schema.model_bias_tests(tested_by) WHERE tested_by IS NOT NULL;

                                                 -- Trigger for updated_at
                                                 CREATE TRIGGER trg_model_bias_tests_updated_at
                                                     BEFORE UPDATE ON socialcandor_schema.model_bias_tests
                                                     FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                                                 -- RLS Policy
                                                 ALTER TABLE socialcandor_schema.model_bias_tests ENABLE ROW LEVEL SECURITY;
                                                 CREATE POLICY model_bias_tests_ai_ethics_policy ON socialcandor_schema.model_bias_tests
                                                     FOR ALL USING (EXISTS (
                                                         SELECT 1 FROM socialcandor_schema.users
                                                         WHERE user_id = current_setting('app.current_user_id')::UUID
                                                         AND role IN ('AI_ETHICS', 'DATA_SCIENTIST', 'ML_ENGINEER', 'COMPLIANCE')
                                                     ));


                                                     --================================================================================================
                                                     -- Table: ML06 - explainability_records
                                                     -- Description: Stores explanations for model predictions using techniques like SHAP,
                                                     --              LIME, or feature importance. Enables interpretability and regulatory compliance.
                                                     -- Business Case: With regulations like the EU AI Act requiring explanations for automated
                                                     --                decisions, and the growing need for model interpretability, this table
                                                     --                stores the "why" behind each prediction. Explanations can be global
                                                     --                (feature importance across the model) or local (why a specific prediction
                                                     --                was made). The design supports multiple explanation methods and formats,
                                                     --                including SHAP values, LIME explanations, counterfactuals, and feature
                                                     --                attribution. This data is critical for debugging, building trust with
                                                     --                users, and meeting regulatory requirements for "right to explanation."
                                                     --
                                                     -- Key Performance Indicators (KPIs):
                                                     --   1. Explanation coverage - Percentage of predictions with stored explanations
                                                     --   2. Explanation latency - Time to generate explanations
                                                     --   3. Explanation stability - Consistency of explanations for similar inputs
                                                     --   4. Feature importance stability - Top features over time
                                                     --   5. User satisfaction - Feedback on explanation quality
                                                     --
                                                     -- Feature References:
                                                     --   - AIETH10 (Explainability)
                                                     --   - AIETH11 (Interpretability)
                                                     --   - AIETH12 (Right to Explanation)
                                                     --   - MLOP26 (Model Interpretability)
                                                     --================================================================================================
                                                     CREATE TABLE IF NOT EXISTS socialcandor_schema.explainability_records (
                                                         -- Primary key
                                                         record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                                         -- Human-readable identifier
                                                         record_number VARCHAR(50) GENERATED ALWAYS AS (
                                                             'EXPL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.explainability_records_seq')::TEXT, 6, '0')
                                                         ) STORED,

                                                         -- Model references
                                                         model_id UUID NOT NULL,
                                                         model_version_id UUID NOT NULL,

                                                         -- Prediction reference (for local explanations)
                                                         prediction_id BIGINT,                                    -- Link to model_predictions
                                                         prediction_time TIMESTAMP WITH TIME ZONE,

                                                         -- Explanation type
                                                         explanation_type VARCHAR(30) NOT NULL CHECK (explanation_type IN (
                                                             'LOCAL', 'GLOBAL', 'COUNTERFACTUAL', 'ANCHOR'
                                                         )),
                                                         explanation_method VARCHAR(50) NOT NULL CHECK (explanation_method IN (
                                                             'SHAP', 'LIME', 'FEATURE_IMPORTANCE', 'TREE_INTERPRETER', 'ANCHOR', 'CEM', 'DICE'
                                                         )),

                                                         -- Explanation data
                                                         feature_importance JSONB,                                -- Map of feature → importance
                                                         shap_values JSONB,                                       -- SHAP values per feature
                                                         top_features TEXT[],                                     -- Top contributing features

                                                         -- For local explanations
                                                         input_snapshot JSONB,                                    -- Input that was explained
                                                         output_value VARCHAR(255),                               -- Prediction value
                                                         confidence_at_explanation NUMERIC(10,8),

                                                         -- For counterfactuals
                                                         counterfactuals JSONB,                                   -- Alternative inputs that would change prediction

                                                         -- Explanation quality
                                                         explanation_quality NUMERIC(5,2),                        -- Confidence in explanation
                                                         explanation_coverage NUMERIC(5,2),                       -- How much of prediction is explained

                                                         -- Visualizations
                                                         visualization_url VARCHAR(500),
                                                         plot_data JSONB,

                                                         -- User feedback
                                                         user_understood BOOLEAN,
                                                         user_feedback TEXT,

                                                         -- Computation metadata
                                                         computation_time_ms INTEGER,
                                                         computed_by UUID,

                                                         -- Audit columns
                                                         created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                         updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                         created_by UUID NOT NULL,
                                                         updated_by UUID DEFAULT uuid_nil(),

                                                         -- Constraints
                                                         CONSTRAINT fk_explainability_records_model FOREIGN KEY (model_id)
                                                             REFERENCES socialcandor_schema.ml_models(model_id) ON DELETE CASCADE,
                                                         CONSTRAINT fk_explainability_records_version FOREIGN KEY (model_version_id)
                                                             REFERENCES socialcandor_schema.model_versions(version_id) ON DELETE CASCADE,
                                                         CONSTRAINT fk_explainability_records_prediction FOREIGN KEY (prediction_id)
                                                             REFERENCES socialcandor_schema.model_predictions(prediction_id) ON DELETE CASCADE,
                                                         CONSTRAINT fk_explainability_records_computed_by FOREIGN KEY (computed_by)
                                                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                                                         CONSTRAINT fk_explainability_records_created_by FOREIGN KEY (created_by)
                                                             REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                                         CONSTRAINT fk_explainability_records_updated_by FOREIGN KEY (updated_by)
                                                             REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                                                     );

                                                     -- Comments
                                                     COMMENT ON TABLE socialcandor_schema.explainability_records IS 'Stores explanations for model predictions (SHAP, LIME, feature importance)';
                                                     COMMENT ON COLUMN socialcandor_schema.explainability_records.explanation_type IS 'Type of explanation (local, global, counterfactual)';
                                                     COMMENT ON COLUMN socialcandor_schema.explainability_records.feature_importance IS 'Map of feature names to importance scores';
                                                     COMMENT ON COLUMN socialcandor_schema.explainability_records.shap_values IS 'SHAP values per feature for local explanations';
                                                     COMMENT ON COLUMN socialcandor_schema.explainability_records.counterfactuals IS 'Alternative inputs that would change the prediction';

                                                     -- Indexes for performance
                                                     CREATE INDEX idx_explainability_records_model ON socialcandor_schema.explainability_records(model_id, model_version_id, created_at DESC);
                                                     CREATE INDEX idx_explainability_records_prediction ON socialcandor_schema.explainability_records(prediction_id) WHERE prediction_id IS NOT NULL;
                                                     CREATE INDEX idx_explainability_records_method ON socialcandor_schema.explainability_records(explanation_method, explanation_type);

                                                     -- Trigger for updated_at
                                                     CREATE TRIGGER trg_explainability_records_updated_at
                                                         BEFORE UPDATE ON socialcandor_schema.explainability_records
                                                         FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                                                     -- RLS Policy
                                                     ALTER TABLE socialcandor_schema.explainability_records ENABLE ROW LEVEL SECURITY;
                                                     CREATE POLICY explainability_records_ml_team_policy ON socialcandor_schema.explainability_records
                                                         FOR SELECT USING (EXISTS (
                                                             SELECT 1 FROM socialcandor_schema.users
                                                             WHERE user_id = current_setting('app.current_user_id')::UUID
                                                             AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER', 'AI_ETHICS')
                                                         ));
                                                     CREATE POLICY explainability_records_compliance_policy ON socialcandor_schema.explainability_records
                                                         FOR SELECT USING (EXISTS (
                                                             SELECT 1 FROM socialcandor_schema.users
                                                             WHERE user_id = current_setting('app.current_user_id')::UUID
                                                             AND role = 'COMPLIANCE'
                                                         ));
                                                     CREATE POLICY explainability_records_admin_policy ON socialcandor_schema.explainability_records
                                                         FOR ALL USING (socialcandor_schema.is_admin());


                                                         --================================================================================================
                                                         -- Table: WB01 - wallet_addresses
                                                         -- Description: Stores cryptocurrency wallet addresses for users across multiple blockchains,
                                                         --              with verification status and metadata. Enables Web3 authentication and payments.
                                                         -- Business Case: As platforms embrace Web3, users need to connect their crypto wallets
                                                         --                for authentication, NFT ownership verification, and cryptocurrency payments.
                                                         --                This table manages wallet addresses across multiple blockchains (Ethereum,
                                                         --                Polygon, Solana, Bitcoin), with verification through signature challenges.
                                                         --                The design supports multiple wallets per user (hot wallets, cold storage)
                                                         --                and tracks wallet activity for analytics. Verification ensures that users
                                                         --                actually own the wallets they claim, preventing spoofing.
                                                         --
                                                         -- Key Performance Indicators (KPIs):
                                                         --   1. Wallet adoption - Percentage of users with connected wallets
                                                         --   2. Wallet distribution - Blockchain network popularity
                                                         --   3. Verification rate - Percentage of wallets successfully verified
                                                         --   4. Multi-wallet usage - Users with multiple wallets
                                                         --   5. Wallet activity - Transactions per wallet
                                                         --
                                                         -- Feature References:
                                                         --   - WEB307 (Wallet Connection)
                                                         --   - WEB308 (Crypto Authentication)
                                                         --   - WEB309 (Multi-chain Support)
                                                         --   - PAY12 (Crypto Payments)
                                                         --================================================================================================
                                                         CREATE TABLE IF NOT EXISTS socialcandor_schema.wallet_addresses (
                                                             -- Primary key
                                                             wallet_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                                                             -- Human-readable identifier
                                                             wallet_number VARCHAR(50) GENERATED ALWAYS AS (
 'WALLET-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.wallet_addresses_seq')::TEXT, 6, '0')
                                                             ) STORED,

                                                             -- User reference
                                                             user_id UUID NOT NULL,

                                                             -- Wallet details
                                                             blockchain VARCHAR(50) NOT NULL CHECK (blockchain IN (
 'ETHEREUM', 'POLYGON', 'SOLANA', 'BITCOIN', 'ARBITRUM', 'OPTIMISM', 'AVALANCHE', 'BSC', 'BASE', 'OTHER'
                                                             )),
                                                             network VARCHAR(50) CHECK (network IN ('MAINNET', 'GOERLI', 'SEPOLIA', 'MUMBAI', 'DEVNET', 'TESTNET')),
                                                             address VARCHAR(255) NOT NULL,
                                                             address_checksum VARCHAR(255),                           -- Checksummed address (for Ethereum)

                                                             -- Wallet metadata
                                                             wallet_name VARCHAR(100),                                 -- User-defined name
                                                             wallet_type VARCHAR(30) CHECK (wallet_type IN ('EOA', 'CONTRACT', 'MULTISIG', 'SMART_WALLET')),
                                                             is_default BOOLEAN DEFAULT FALSE,

                                                             -- Verification
                                                             is_verified BOOLEAN DEFAULT FALSE,
                                                             verified_at TIMESTAMP WITH TIME ZONE,
                                                             verification_message TEXT,
                                                             verification_signature VARCHAR(500),
                                                             verification_method VARCHAR(50) CHECK (verification_method IN ('SIGNATURE', 'TRANSACTION', 'ENS')),

                                                             -- Activity
                                                             first_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                             last_active_at TIMESTAMP WITH TIME ZONE,
                                                             transaction_count INTEGER DEFAULT 0,
                                                             total_received NUMERIC(30,18),
                                                             total_sent NUMERIC(30,18),

                                                             -- ENS/NFT associations
                                                             ens_name VARCHAR(255),                                    -- Ethereum Name Service
                                                             primary_nft_id UUID,                                      -- Linked NFT profile picture

                                                             -- Status
                                                             is_active BOOLEAN DEFAULT TRUE,
                                                             deactivated_at TIMESTAMP WITH TIME ZONE,
                                                             deactivation_reason VARCHAR(100),

                                                             -- Audit columns
                                                             created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                             updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                                                             created_by UUID NOT NULL,
                                                             updated_by UUID DEFAULT uuid_nil(),

                                                             -- Constraints
                                                             CONSTRAINT fk_wallet_addresses_user FOREIGN KEY (user_id)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                                                             CONSTRAINT fk_wallet_addresses_created_by FOREIGN KEY (created_by)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                                                             CONSTRAINT fk_wallet_addresses_updated_by FOREIGN KEY (updated_by)
 REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                                                             CONSTRAINT uk_wallet_addresses UNIQUE (blockchain, network, address)
                                                         );

                                                         -- Comments
                                                         COMMENT ON TABLE socialcandor_schema.wallet_addresses IS 'Cryptocurrency wallet addresses for users across multiple blockchains';
                                                         COMMENT ON COLUMN socialcandor_schema.wallet_addresses.blockchain IS 'Blockchain network (Ethereum, Solana, Bitcoin, etc.)';
                                                         COMMENT ON COLUMN socialcandor_schema.wallet_addresses.address IS 'Wallet address (may be case-sensitive)';
                                                         COMMENT ON COLUMN socialcandor_schema.wallet_addresses.is_verified IS 'Whether wallet ownership has been verified';
                                                         COMMENT ON COLUMN socialcandor_schema.wallet_addresses.ens_name IS 'Ethereum Name Service domain (if applicable)';

                                                         -- Indexes for performance
                                                         CREATE INDEX idx_wallet_addresses_user ON socialcandor_schema.wallet_addresses(user_id, is_active) WHERE is_active = TRUE;
                                                         CREATE INDEX idx_wallet_addresses_address ON socialcandor_schema.wallet_addresses(address);
                                                         CREATE INDEX idx_wallet_addresses_blockchain ON socialcandor_schema.wallet_addresses(blockchain, network, is_verified);

                                                         -- Trigger for updated_at
                                                         CREATE TRIGGER trg_wallet_addresses_updated_at
                                                             BEFORE UPDATE ON socialcandor_schema.wallet_addresses
                                                             FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                                                         -- RLS Policy
                                                         ALTER TABLE socialcandor_schema.wallet_addresses ENABLE ROW LEVEL SECURITY;
                                                         CREATE POLICY wallet_addresses_self_policy ON socialcandor_schema.wallet_addresses
                                                             FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
                                                         CREATE POLICY wallet_addresses_admin_policy ON socialcandor_schema.wallet_addresses
                                                             FOR ALL USING (socialcandor_schema.is_admin());

                                                             --================================================================================================
                                                             -- Table: WB02 - crypto_transactions
                                                             -- Description: Logs cryptocurrency transactions (sends, receives, swaps) for users,
                                                             --              tracking on-chain confirmations and status. Enables crypto payments and analytics.
                                                             -- Business Case: For platforms accepting cryptocurrency payments or enabling crypto features,
                                                             --                tracking transaction status is critical. This table logs all crypto
                                                             --                transactions, including sends, receives, swaps, and contract interactions.
                                                             --                It tracks confirmation status, gas costs, and block information. The design
                                                             --                supports monitoring for payment confirmation (e.g., requiring 12 confirmations
                                                             --                for Bitcoin) and handles different blockchains with different confirmation
                                                             --                requirements. Integration with wallet system enables balance tracking and
                                                             --                payment verification.
                                                             --
                                                             -- Key Performance Indicators (KPIs):
                                                             --   1. Transaction volume - Number of crypto transactions per day
                                                             --   2. Transaction value - Total value transacted
                                                             --   3. Confirmation time - Average time to transaction finality
                                                             --   4. Gas costs - Average transaction fees
                                                             --   5. Success rate - Percentage of successful transactions
                                                             --
                                                             -- Feature References:
                                                             --   - WEB310 (Crypto Transactions)
                                                             --   - WEB311 (Payment Processing)
                                                             --   - WEB312 (On-chain Tracking)
                                                             --   - PAY13 (Crypto Payments)
                                                             --================================================================================================
                                                             CREATE TABLE IF NOT EXISTS socialcandor_schema.crypto_transactions (
 -- Primary key
 tx_id BIGSERIAL PRIMARY KEY,

 -- Human-readable identifier
 tx_number VARCHAR(50) GENERATED ALWAYS AS (
     'CRYPTO-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.crypto_transactions_seq')::TEXT, 6, '0')
 ) STORED,

 -- User references
 user_id UUID NOT NULL,
 wallet_id UUID,                                          -- Sending wallet (if known)

 -- Transaction details
 blockchain VARCHAR(50) NOT NULL,
 network VARCHAR(50),
 tx_hash VARCHAR(255) UNIQUE NOT NULL,
 block_number BIGINT,
 block_hash VARCHAR(255),
 timestamp TIMESTAMP WITH TIME ZONE NOT NULL,

 -- Participants
 from_address VARCHAR(255) NOT NULL,
 to_address VARCHAR(255) NOT NULL,

 -- Value
 amount NUMERIC(30,18) NOT NULL,
 token_address VARCHAR(255),                               -- NULL for native currency
 token_symbol VARCHAR(20),                                 -- e.g., 'ETH', 'MATIC'
 token_decimals INTEGER DEFAULT 18,

 -- Fees
 gas_price_gwei NUMERIC(30,10),
 gas_used INTEGER,
 gas_cost_native NUMERIC(30,18),
 gas_cost_usd NUMERIC(15,2),

 -- Status
 status VARCHAR(30) NOT NULL CHECK (status IN (
     'PENDING', 'CONFIRMING', 'CONFIRMED', 'FAILED', 'REPLACED'
 )),
 confirmations INTEGER DEFAULT 0,
 required_confirmations INTEGER DEFAULT 12,                -- Blockchain-specific
 is_final BOOLEAN DEFAULT FALSE,

 -- Transaction type
 tx_type VARCHAR(30) CHECK (tx_type IN (
     'SEND', 'RECEIVE', 'SWAP', 'CONTRACT_CALL', 'MINT', 'TRANSFER'
 )),

 -- Metadata
 memo TEXT,
 transaction_data JSONB,

 -- Platform reference
 order_id UUID,                                            -- Associated marketplace order
 payment_id UUID,                                          -- Associated payment

 -- Audit columns
 created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

 -- Constraints
 CONSTRAINT fk_crypto_transactions_user FOREIGN KEY (user_id)
     REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
 CONSTRAINT fk_crypto_transactions_wallet FOREIGN KEY (wallet_id)
     REFERENCES socialcandor_schema.wallet_addresses(wallet_id) ON DELETE SET NULL,
 CONSTRAINT fk_crypto_transactions_order FOREIGN KEY (order_id)
     REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL
                                                             );

                                                             -- Comments
                                                             COMMENT ON TABLE socialcandor_schema.crypto_transactions IS 'Logs cryptocurrency transactions with on-chain confirmations';
                                                             COMMENT ON COLUMN socialcandor_schema.crypto_transactions.tx_hash IS 'Transaction hash on the blockchain';
                                                             COMMENT ON COLUMN socialcandor_schema.crypto_transactions.token_address IS 'Contract address for tokens (NULL for native currency)';
                                                             COMMENT ON COLUMN socialcandor_schema.crypto_transactions.gas_cost_usd IS 'Estimated gas cost in USD at time of transaction';
                                                             COMMENT ON COLUMN socialcandor_schema.crypto_transactions.confirmations IS 'Number of block confirmations received';

                                                             -- Indexes for performance
                                                             CREATE INDEX idx_crypto_transactions_user ON socialcandor_schema.crypto_transactions(user_id, timestamp DESC);
                                                             CREATE INDEX idx_crypto_transactions_hash ON socialcandor_schema.crypto_transactions(tx_hash);
                                                             CREATE INDEX idx_crypto_transactions_address ON socialcandor_schema.crypto_transactions(from_address, to_address, timestamp);
                                                             CREATE INDEX idx_crypto_transactions_status ON socialcandor_schema.crypto_transactions(status, confirmations) WHERE status != 'CONFIRMED';

                                                             -- Trigger for updated_at
                                                             CREATE TRIGGER trg_crypto_transactions_updated_at
 BEFORE UPDATE ON socialcandor_schema.crypto_transactions
 FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                                                             -- RLS Policy
                                                             ALTER TABLE socialcandor_schema.crypto_transactions ENABLE ROW LEVEL SECURITY;
                                                             CREATE POLICY crypto_transactions_self_policy ON socialcandor_schema.crypto_transactions
 FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
                                                             CREATE POLICY crypto_transactions_admin_policy ON socialcandor_schema.crypto_transactions
 FOR ALL USING (socialcandor_schema.is_admin());

 --================================================================================================
 -- Table: WB03 - nft_metadata
 -- Description: Stores metadata for NFTs created, collected, or displayed on the platform,
 --              including images, attributes, and ownership history.
 -- Business Case: NFTs are becoming integral to social platforms for digital collectibles,
 --                profile pictures, and token-gated content. This table stores NFT metadata
 --                according to standards like ERC-721 and ERC-1155, including images,
 --                attributes, and external links. The design supports multiple blockchains
 --                and contract addresses. Tracking ownership enables features like NFT-gated
 --                communities, verified ownership badges, and digital collectible showcases.
 --                Integration with wallet system enables automatic detection of user-owned NFTs.
 --
 -- Key Performance Indicators (KPIs):
 --   1. NFT count - Number of NFTs tracked on platform
 --   2. Unique owners - Users with NFTs
 --   3. Collection size - NFTs per collection
 --   4. Trading volume - NFT transactions (if marketplace enabled)
 --   5. Display usage - NFTs used as profile pictures
 --
 -- Feature References:
 --   - WEB313 (NFT Support)
 --   - WEB314 (Digital Collectibles)
 --   - WEB315 (Token-gated Content)
 --   - SOC20 (NFT Profile Pictures)
 --================================================================================================
 CREATE TABLE IF NOT EXISTS socialcandor_schema.nft_metadata (
     -- Primary key
     nft_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

     -- Human-readable identifier
     nft_number VARCHAR(50) GENERATED ALWAYS AS (
         'NFT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.nft_metadata_seq')::TEXT, 6, '0')
     ) STORED,

     -- Contract information
     blockchain VARCHAR(50) NOT NULL,
     contract_address VARCHAR(255) NOT NULL,
     token_id VARCHAR(255) NOT NULL,
     token_standard VARCHAR(20) CHECK (token_standard IN ('ERC721', 'ERC1155', 'METAPLEX', 'OTHER')),

     -- Basic metadata
     name VARCHAR(500) NOT NULL,
     description TEXT,
     image_url VARCHAR(1000),
     image_thumbnail_url VARCHAR(1000),
     animation_url VARCHAR(1000),
     external_url VARCHAR(1000),

     -- Attributes (for traits)
     attributes JSONB,                                         -- Array of {trait_type, value}

     -- Collection
     collection_name VARCHAR(255),
     collection_slug VARCHAR(255),
     collection_image_url VARCHAR(1000),

     -- Ownership
     current_owner_user_id UUID,                               -- Platform user who owns it
     current_owner_address VARCHAR(255),                       -- Blockchain address of owner
     acquired_at TIMESTAMP WITH TIME ZONE,
     acquisition_price NUMERIC(30,18),
     acquisition_currency VARCHAR(20),

     -- Metadata freshness
     metadata_url VARCHAR(1000),                                -- Original metadata URL
     metadata_fetched_at TIMESTAMP WITH TIME ZONE,
     metadata_fetch_attempts INTEGER DEFAULT 0,
     metadata_error TEXT,

     -- Platform usage
     is_verified BOOLEAN DEFAULT FALSE,                        -- Verified by platform
     is_featured BOOLEAN DEFAULT FALSE,
     is_profile_picture_enabled BOOLEAN DEFAULT TRUE,

     -- Rarity
     rarity_score NUMERIC(10,6),
     rarity_rank INTEGER,
     total_supply INTEGER,                                      -- For ERC1155

     -- Last sale (if known)
     last_sale_price NUMERIC(30,18),
     last_sale_currency VARCHAR(20),
     last_sale_date TIMESTAMP WITH TIME ZONE,

     -- Audit columns
     created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
     updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
     created_by UUID NOT NULL,
     updated_by UUID DEFAULT uuid_nil(),

     -- Constraints
     CONSTRAINT fk_nft_metadata_owner FOREIGN KEY (current_owner_user_id)
         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
     CONSTRAINT fk_nft_metadata_created_by FOREIGN KEY (created_by)
         REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
     CONSTRAINT fk_nft_metadata_updated_by FOREIGN KEY (updated_by)
         REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

     CONSTRAINT uk_nft_metadata UNIQUE (blockchain, contract_address, token_id)
 );

 -- Comments
 COMMENT ON TABLE socialcandor_schema.nft_metadata IS 'Stores metadata for NFTs created, collected, or displayed on the platform';
 COMMENT ON COLUMN socialcandor_schema.nft_metadata.attributes IS 'JSON array of NFT traits/attributes';
 COMMENT ON COLUMN socialcandor_schema.nft_metadata.current_owner_user_id IS 'Platform user who owns this NFT';
 COMMENT ON COLUMN socialcandor_schema.nft_metadata.is_profile_picture_enabled IS 'Whether this NFT can be used as profile picture';
 COMMENT ON COLUMN socialcandor_schema.nft_metadata.rarity_score IS 'Computed rarity score within collection';

 -- Indexes for performance
 CREATE INDEX idx_nft_metadata_contract ON socialcandor_schema.nft_metadata(blockchain, contract_address, token_id);
 CREATE INDEX idx_nft_metadata_owner ON socialcandor_schema.nft_metadata(current_owner_user_id) WHERE current_owner_user_id IS NOT NULL;
 CREATE INDEX idx_nft_metadata_collection ON socialcandor_schema.nft_metadata(collection_slug, rarity_score DESC);
 CREATE INDEX idx_nft_metadata_attributes ON socialcandor_schema.nft_metadata USING GIN (attributes);

 -- Trigger for updated_at
 CREATE TRIGGER trg_nft_metadata_updated_at
     BEFORE UPDATE ON socialcandor_schema.nft_metadata
     FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

 -- RLS Policy
 ALTER TABLE socialcandor_schema.nft_metadata ENABLE ROW LEVEL SECURITY;
 CREATE POLICY nft_metadata_public_policy ON socialcandor_schema.nft_metadata
     FOR SELECT USING (TRUE);
 CREATE POLICY nft_metadata_owner_policy ON socialcandor_schema.nft_metadata
     FOR ALL USING (current_owner_user_id = current_setting('app.current_user_id')::UUID);
 CREATE POLICY nft_metadata_admin_policy ON socialcandor_schema.nft_metadata
     FOR ALL USING (socialcandor_schema.is_admin());


     --================================================================================================
     -- Table: WB04 - nft_transfers
     -- Description: Tracks NFT ownership transfers, including blockchain events and platform-initiated
     --              transfers. Provides complete provenance and ownership history.
     -- Business Case: For NFTs, provenance is critical - proving ownership history and authenticity.
     --                This table logs every transfer of an NFT, whether occurring on-chain or
     --                through platform marketplace features. The design captures both blockchain
     --                events (with transaction hashes) and internal transfers (gifts, purchases).
     --                This enables features like "provenance" displays, verification of current
     --                ownership, and analytics on NFT velocity. The data also supports royalty
     --                payments to original creators on secondary sales.
     --
     -- Key Performance Indicators (KPIs):
     --   1. Transfer volume - Number of NFT transfers per period
     --   2. Unique traders - Users buying/selling NFTs
     --   3. Average hold time - Time between transfers per NFT
     --   4. Most traded collections - Collections with highest transfer volume
     --   5. Royalty payments - Secondary sale royalties collected
     --
     -- Feature References:
     --   - WEB316 (NFT Transfers)
     --   - WEB317 (Provenance Tracking)
     --   - WEB318 (Royalty Management)
     --   - MPL12 (NFT Marketplace)
     --================================================================================================
     CREATE TABLE IF NOT EXISTS socialcandor_schema.nft_transfers (
         -- Primary key
         transfer_id BIGSERIAL PRIMARY KEY,

         -- Human-readable identifier
         transfer_number VARCHAR(50) GENERATED ALWAYS AS (
             'NFTT-' || TO_CHAR(transfer_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.nft_transfers_seq')::TEXT, 6, '0')
         ) STORED,

         -- NFT reference
         nft_id UUID NOT NULL,

         -- Transfer participants
         from_user_id UUID,                                        -- Platform user (NULL if external)
         from_address VARCHAR(255) NOT NULL,                       -- Blockchain address
         to_user_id UUID,                                          -- Platform user (NULL if external)
         to_address VARCHAR(255) NOT NULL,                         -- Blockchain address

         -- Transfer details
         transfer_type VARCHAR(30) CHECK (transfer_type IN (
           'MINT', 'TRANSFER', 'SALE', 'GIFT', 'BURN', 'BRIDGE'
)),
transfer_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

-- Blockchain data
blockchain VARCHAR(50) NOT NULL,
tx_hash VARCHAR(255),                                     -- NULL for internal transfers
block_number BIGINT,
log_index INTEGER,

-- Price (if applicable)
price NUMERIC(30,18),
currency VARCHAR(20),                                     -- 'ETH', 'MATIC', 'USD'
price_usd NUMERIC(15,2),

-- Platform context
order_id UUID,                                            -- If part of marketplace order
listing_id UUID,                                          -- If from marketplace listing

-- Royalties
royalty_amount NUMERIC(30,18),
royalty_recipient VARCHAR(255),
royalty_paid BOOLEAN DEFAULT FALSE,

-- Metadata
metadata JSONB DEFAULT '{}',

-- Audit columns
created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

-- Constraints
CONSTRAINT fk_nft_transfers_nft FOREIGN KEY (nft_id)
REFERENCES socialcandor_schema.nft_metadata(nft_id) ON DELETE CASCADE,
CONSTRAINT fk_nft_transfers_from_user FOREIGN KEY (from_user_id)
REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
CONSTRAINT fk_nft_transfers_to_user FOREIGN KEY (to_user_id)
REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
CONSTRAINT fk_nft_transfers_order FOREIGN KEY (order_id)
REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
CONSTRAINT fk_nft_transfers_listing FOREIGN KEY (listing_id)
REFERENCES socialcandor_schema.marketplace_listings(listing_id) ON DELETE SET NULL
);

-- Comments
COMMENT ON TABLE socialcandor_schema.nft_transfers IS 'Tracks NFT ownership transfers for provenance and analytics';
COMMENT ON COLUMN socialcandor_schema.nft_transfers.transfer_type IS 'Type of transfer (mint, transfer, sale, gift, burn, bridge)';
COMMENT ON COLUMN socialcandor_schema.nft_transfers.from_user_id IS 'Platform user sending (NULL if external address)';
COMMENT ON COLUMN socialcandor_schema.nft_transfers.to_user_id IS 'Platform user receiving (NULL if external address)';
COMMENT ON COLUMN socialcandor_schema.nft_transfers.price_usd IS 'Price in USD at time of transfer';

-- Indexes for performance
CREATE INDEX idx_nft_transfers_nft ON socialcandor_schema.nft_transfers(nft_id, transfer_date DESC);
CREATE INDEX idx_nft_transfers_from ON socialcandor_schema.nft_transfers(from_address, transfer_date DESC);
CREATE INDEX idx_nft_transfers_to ON socialcandor_schema.nft_transfers(to_address, transfer_date DESC);
CREATE INDEX idx_nft_transfers_users ON socialcandor_schema.nft_transfers(from_user_id, to_user_id, transfer_date)
WHERE from_user_id IS NOT NULL OR to_user_id IS NOT NULL;
CREATE INDEX idx_nft_transfers_tx ON socialcandor_schema.nft_transfers(tx_hash) WHERE tx_hash IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_nft_transfers_updated_at
BEFORE UPDATE ON socialcandor_schema.nft_transfers
FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- Function to update NFT current owner after transfer
CREATE OR REPLACE FUNCTION socialcandor_schema.update_nft_owner_after_transfer()
RETURNS TRIGGER AS $$
BEGIN
-- Update the NFT's current owner
UPDATE socialcandor_schema.nft_metadata
SET current_owner_user_id = NEW.to_user_id,
current_owner_address = NEW.to_address,
acquired_at = NEW.transfer_date,
updated_at = CURRENT_TIMESTAMP
WHERE nft_id = NEW.nft_id;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_nft_transfers_update_owner
AFTER INSERT ON socialcandor_schema.nft_transfers
FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_nft_owner_after_transfer();

-- RLS Policy
ALTER TABLE socialcandor_schema.nft_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY nft_transfers_public_policy ON socialcandor_schema.nft_transfers
FOR SELECT USING (TRUE);
CREATE POLICY nft_transfers_participant_policy ON socialcandor_schema.nft_transfers
FOR SELECT USING (
from_user_id = current_setting('app.current_user_id')::UUID OR
to_user_id = current_setting('app.current_user_id')::UUID
);
CREATE POLICY nft_transfers_admin_policy ON socialcandor_schema.nft_transfers
FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- Table: WB05 - smart_contract_interactions
-- Description: Logs interactions with smart contracts, including function calls, events,
--              and transaction results. Enables audit trail and debugging of dApp features.
-- Business Case: As platforms integrate with smart contracts (for NFTs, DeFi, DAOs),
--                tracking contract interactions is essential for debugging, user support,
--                and compliance. This table logs every contract interaction initiated through
--                the platform, including function calls, parameters, transaction hashes,
--                and results. The design supports both successful and failed transactions,
--                capturing error messages for troubleshooting. This data enables analytics
--                on feature usage, helps users track their contract interactions, and provides
--                a fallback for when blockchain explorers are insufficient.
--
-- Key Performance Indicators (KPIs):
--   1. Interaction volume - Number of contract interactions per day
--   2. Success rate - Percentage of successful transactions
--   3. Gas usage - Average gas costs by contract type
--   4. Feature adoption - Most-called functions
--   5. Error analysis - Most common transaction failures
--
-- Feature References:
--   - WEB319 (Contract Interactions)
--   - WEB320 (dApp Analytics)
--   - WEB321 (Transaction Monitoring)
--   - AUD19 (Contract Audit)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.smart_contract_interactions (
    -- Primary key
    interaction_id BIGSERIAL PRIMARY KEY,

    -- Human-readable identifier
    interaction_number VARCHAR(50) GENERATED ALWAYS AS (
        'SCINT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.smart_contract_interactions_seq')::TEXT, 6, '0')
    ) STORED,

    -- User reference
    user_id UUID NOT NULL,
    wallet_id UUID,                                          -- Wallet used for interaction

    -- Contract details
    blockchain VARCHAR(50) NOT NULL,
    contract_address VARCHAR(255) NOT NULL,
    contract_name VARCHAR(255),

    -- Function called
    function_name VARCHAR(255) NOT NULL,
    function_signature VARCHAR(255),
    parameters JSONB,
    parameter_count INTEGER,

    -- Transaction details
    tx_hash VARCHAR(255),
    tx_status VARCHAR(30) CHECK (tx_status IN ('PENDING', 'SUCCESS', 'FAILED', 'REVERTED')),
    block_number BIGINT,
    gas_used INTEGER,
    gas_price_gwei NUMERIC(30,10),
    tx_cost_native NUMERIC(30,18),
    tx_cost_usd NUMERIC(15,2),

    -- Results
    return_value JSONB,
    events_emitted JSONB,                                    -- Logs from the transaction
    error_message TEXT,
    revert_reason TEXT,

    -- Context
    interaction_type VARCHAR(50) CHECK (interaction_type IN (
        'READ', 'WRITE', 'DEPLOY', 'APPROVE', 'TRANSFER', 'SWAP', 'STAKE', 'VOTE'
    )),
    dapp_feature VARCHAR(100),                                -- Feature that triggered this

    -- Timing
    requested_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    confirmed_at TIMESTAMP WITH TIME ZONE,
    confirmation_time_seconds INTEGER,

    -- Platform reference
    nft_id UUID,                                              -- Associated NFT
    order_id UUID,                                            -- Associated order
    proposal_id UUID,                                         -- Associated DAO proposal

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_smart_contract_interactions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_smart_contract_interactions_wallet FOREIGN KEY (wallet_id)
        REFERENCES socialcandor_schema.wallet_addresses(wallet_id) ON DELETE SET NULL,
    CONSTRAINT fk_smart_contract_interactions_nft FOREIGN KEY (nft_id)
        REFERENCES socialcandor_schema.nft_metadata(nft_id) ON DELETE SET NULL,
    CONSTRAINT fk_smart_contract_interactions_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL
);

-- Comments
COMMENT ON TABLE socialcandor_schema.smart_contract_interactions IS 'Logs interactions with smart contracts for audit and debugging';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.function_name IS 'Name of the contract function called';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.parameters IS 'JSON array of function parameters';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.return_value IS 'Return value from the function call';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.events_emitted IS 'JSON array of events emitted by the transaction';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.dapp_feature IS 'Platform feature that initiated the interaction';

-- Indexes for performance
CREATE INDEX idx_smart_contract_interactions_user ON socialcandor_schema.smart_contract_interactions(user_id, requested_at DESC);
CREATE INDEX idx_smart_contract_interactions_contract ON socialcandor_schema.smart_contract_interactions(contract_address, function_name);
CREATE INDEX idx_smart_contract_interactions_tx ON socialcandor_schema.smart_contract_interactions(tx_hash) WHERE tx_hash IS NOT NULL;
CREATE INDEX idx_smart_contract_interactions_status ON socialcandor_schema.smart_contract_interactions(tx_status, requested_at);
CREATE INDEX idx_smart_contract_interactions_feature ON socialcandor_schema.smart_contract_interactions(dapp_feature, requested_at DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_smart_contract_interactions_updated_at
    BEFORE UPDATE ON socialcandor_schema.smart_contract_interactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.smart_contract_interactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY smart_contract_interactions_self_policy ON socialcandor_schema.smart_contract_interactions
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY smart_contract_interactions_admin_policy ON socialcandor_schema.smart_contract_interactions
    FOR ALL USING (socialcandor_schema.is_admin());


    --================================================================================================
    -- Table: DG01 - dao_proposals
    -- Description: Manages DAO governance proposals, including description, voting period,
    --              vote counts, and execution status. Enables decentralized decision-making.
    -- Business Case: As platforms embrace decentralized governance, DAOs require robust
    --                proposal tracking. This table stores all governance proposals, from
    --                treasury allocations to parameter changes. The design supports different
    --                proposal types with varying voting mechanisms (simple majority, quadratic,
    --                weighted by token holdings). It tracks the full lifecycle: creation,
    --                voting period, execution, and completion. Integration with blockchain
    --                enables on-chain execution of approved proposals. This is essential for
    --                community-governed platforms and token-based decision-making.
    --
    -- Key Performance Indicators (KPIs):
    --   1. Proposal volume - Number of proposals per period
    --   2. Voter participation - Percentage of eligible voters participating
    --   3. Approval rate - Percentage of proposals passing
    --   4. Time to decision - Average voting period
    --   5. Execution rate - Percentage of passed proposals executed
    --
    -- Feature References:
    --   - GOV14 (DAO Governance)
    --   - GOV15 (Proposal Management)
    --   - GOV16 (Voting Mechanisms)
    --   - WEB322 (On-chain Governance)
    --================================================================================================
    CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_proposals (
        -- Primary key
        proposal_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

        -- Human-readable identifier
        proposal_number VARCHAR(50) GENERATED ALWAYS AS (
            'PROP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_proposals_seq')::TEXT, 6, '0')
        ) STORED,

        -- Proposal identification
        title VARCHAR(255) NOT NULL,
        description TEXT NOT NULL,
        proposal_type VARCHAR(50) CHECK (proposal_type IN (
            'FUNDING', 'PARAMETER_CHANGE', 'MEMBERSHIP', 'STRATEGIC', 'CONTRACT_UPGRADE', 'TREASURY', 'INITIATIVE'
        )),

        -- Author
        proposer_user_id UUID NOT NULL,
        proposer_address VARCHAR(255),                            -- Blockchain address

        -- Timing
        created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        start_time TIMESTAMP WITH TIME ZONE NOT NULL,
        end_time TIMESTAMP WITH TIME ZONE NOT NULL,
        execution_time TIMESTAMP WITH TIME ZONE,

        -- Voting parameters
        voting_method VARCHAR(50) CHECK (voting_method IN (
            'SIMPLE_MAJORITY', 'SUPER_MAJORITY', 'QUADRATIC', 'WEIGHTED', 'CONSENSUS'
        )),
        quorum_percentage NUMERIC(5,2),                           -- Minimum participation required
        approval_threshold NUMERIC(5,2),                          -- Percentage needed to pass

        -- Vote counts
        votes_for BIGINT DEFAULT 0,
        votes_against BIGINT DEFAULT 0,
        votes_abstain BIGINT DEFAULT 0,
        total_votes BIGINT GENERATED ALWAYS AS (votes_for + votes_against + votes_abstain) STORED,

        -- Voting power
        total_voting_power NUMERIC(30,18),                        -- Total eligible voting power
        voting_power_for NUMERIC(30,18) DEFAULT 0,
        voting_power_against NUMERIC(30,18) DEFAULT 0,
        voting_power_abstain NUMERIC(30,18) DEFAULT 0,

        -- Status
        status VARCHAR(30) DEFAULT 'PENDING' CHECK (status IN (
            'PENDING', 'ACTIVE', 'PASSED', 'REJECTED', 'EXECUTED', 'FAILED', 'CANCELLED'
        )),

        -- Execution details
        execution_tx_hash VARCHAR(255),
        execution_contract VARCHAR(255),
        execution_function VARCHAR(255),
        execution_parameters JSONB,

        -- Metadata
        metadata JSONB DEFAULT '{}',
        discussion_url VARCHAR(500),
        snapshot_id VARCHAR(255),                                  -- Snapshot.org proposal ID

        -- Audit columns
        updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID DEFAULT uuid_nil(),

        -- Constraints
        CONSTRAINT fk_dao_proposals_proposer FOREIGN KEY (proposer_user_id)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
        CONSTRAINT fk_dao_proposals_created_by FOREIGN KEY (created_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
        CONSTRAINT fk_dao_proposals_updated_by FOREIGN KEY (updated_by)
            REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

        CONSTRAINT chk_dao_proposals_dates CHECK (end_time > start_time),
        CONSTRAINT chk_dao_proposals_threshold CHECK (
            approval_threshold IS NULL OR (approval_threshold >= 0 AND approval_threshold <= 100)
        )
    );

    -- Comments
    COMMENT ON TABLE socialcandor_schema.dao_proposals IS 'Manages DAO governance proposals with voting and execution tracking';
    COMMENT ON COLUMN socialcandor_schema.dao_proposals.voting_method IS 'Method used for voting (simple majority, quadratic, weighted, etc.)';
    COMMENT ON COLUMN socialcandor_schema.dao_proposals.quorum_percentage IS 'Minimum participation required for proposal to be valid';
    COMMENT ON COLUMN socialcandor_schema.dao_proposals.approval_threshold IS 'Percentage of votes needed to pass';
    COMMENT ON COLUMN socialcandor_schema.dao_proposals.voting_power_for IS 'Total voting power of FOR votes (for weighted voting)';

    -- Indexes for performance
    CREATE INDEX idx_dao_proposals_status ON socialcandor_schema.dao_proposals(status, end_time);
    CREATE INDEX idx_dao_proposals_proposer ON socialcandor_schema.dao_proposals(proposer_user_id, created_at DESC);
    CREATE INDEX idx_dao_proposals_type ON socialcandor_schema.dao_proposals(proposal_type, status);
    CREATE INDEX idx_dao_proposals_active ON socialcandor_schema.dao_proposals(start_time, end_time) WHERE status = 'ACTIVE';

    -- Trigger for updated_at
    CREATE TRIGGER trg_dao_proposals_updated_at
        BEFORE UPDATE ON socialcandor_schema.dao_proposals
        FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

    -- RLS Policy
    ALTER TABLE socialcandor_schema.dao_proposals ENABLE ROW LEVEL SECURITY;
    CREATE POLICY dao_proposals_public_policy ON socialcandor_schema.dao_proposals
        FOR SELECT USING (TRUE);
    CREATE POLICY dao_proposals_proposer_policy ON socialcandor_schema.dao_proposals
        FOR ALL USING (proposer_user_id = current_setting('app.current_user_id')::UUID);
    CREATE POLICY dao_proposals_admin_policy ON socialcandor_schema.dao_proposals
        FOR ALL USING (socialcandor_schema.is_admin());


        --================================================================================================
        -- Table: DG02 - dao_votes
        -- Description: Records individual votes cast on DAO proposals, including voter identity,
        --              choice, and voting power. Enables transparent governance and audit trails.
        -- Business Case: Transparent voting is fundamental to DAO governance. This table records
        --                every vote cast on proposals, capturing the voter, their choice (for,
        --                against, abstain), and the voting power used (based on token holdings,
        --                reputation, or other mechanisms). The design supports both on-chain and
        --                off-chain votes, with verification of voter eligibility at the time of
        --                voting. Historical vote data enables analysis of voter behavior, identification
        --                of governance participation trends, and audit of proposal outcomes.
        --
        -- Key Performance Indicators (KPIs):
        --   1. Voter turnout - Percentage of eligible voters participating
        --   2. Vote distribution - For/against/abstain percentages
        --   3. Voting power concentration - Gini coefficient of voting power
        --   4. Voter consistency - How often voters vote the same way
        --   5. Participation trends - Changes in voter participation over time
        --
        -- Feature References:
        --   - GOV17 (Vote Recording)
        --   - GOV18 (Voter Analytics)
        --   - GOV19 (Governance Participation)
        --   - WEB323 (On-chain Voting)
        --================================================================================================
        CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_votes (
            -- Primary key
            vote_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

            -- Human-readable identifier
            vote_number VARCHAR(50) GENERATED ALWAYS AS (
                'VOTE-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_votes_seq')::TEXT, 6, '0')
            ) STORED,

            -- References
            proposal_id UUID NOT NULL,
            voter_user_id UUID NOT NULL,
            voter_address VARCHAR(255),                                -- Blockchain address used

            -- Vote details
            vote_choice VARCHAR(20) NOT NULL CHECK (vote_choice IN ('FOR', 'AGAINST', 'ABSTAIN')),
            voting_power NUMERIC(30,18) NOT NULL,
            voting_weight NUMERIC(10,6) DEFAULT 1.0,                  -- For quadratic voting

            -- Vote timing
            voted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
            block_number BIGINT,                                       -- For on-chain votes
            tx_hash VARCHAR(255),                                      -- Transaction hash

            -- Verification
            is_verified BOOLEAN DEFAULT TRUE,
            verification_method VARCHAR(50) CHECK (verification_method IN ('SIGNATURE', 'TOKEN_BALANCE', 'REPUTATION')),

            -- Vote metadata
            reason TEXT,                                               -- Optional explanation
            metadata JSONB DEFAULT '{}',

            -- Snapshot of voter eligibility at time of vote
            eligible_balance NUMERIC(30,18),
            eligible_tokens TEXT[],                                    -- Token addresses used

            -- Audit columns
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

            -- Constraints
            CONSTRAINT fk_dao_votes_proposal FOREIGN KEY (proposal_id)
                REFERENCES socialcandor_schema.dao_proposals(proposal_id) ON DELETE CASCADE,
            CONSTRAINT fk_dao_votes_voter FOREIGN KEY (voter_user_id)
                REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,

            CONSTRAINT uk_dao_votes UNIQUE (proposal_id, voter_user_id)
        );

        -- Comments
        COMMENT ON TABLE socialcandor_schema.dao_votes IS 'Records individual votes cast on DAO proposals';
        COMMENT ON COLUMN socialcandor_schema.dao_votes.vote_choice IS 'Voter''s choice (FOR, AGAINST, ABSTAIN)';
        COMMENT ON COLUMN socialcandor_schema.dao_votes.voting_power IS 'Amount of voting power used';
        COMMENT ON COLUMN socialcandor_schema.dao_votes.voting_weight IS 'Weight multiplier (for quadratic voting)';
        COMMENT ON COLUMN socialcandor_schema.dao_votes.eligible_balance IS 'Token/reputation balance at time of voting';

        -- Indexes for performance
        CREATE INDEX idx_dao_votes_proposal ON socialcandor_schema.dao_votes(proposal_id, vote_choice);
        CREATE INDEX idx_dao_votes_voter ON socialcandor_schema.dao_votes(voter_user_id, voted_at DESC);
        CREATE INDEX idx_dao_votes_time ON socialcandor_schema.dao_votes(voted_at DESC);

        -- Trigger for updated_at
        CREATE TRIGGER trg_dao_votes_updated_at
            BEFORE UPDATE ON socialcandor_schema.dao_votes
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

        -- Function to update proposal vote counts
        CREATE OR REPLACE FUNCTION socialcandor_schema.update_proposal_vote_counts()
        RETURNS TRIGGER AS $$
        BEGIN
            -- Update the proposal's vote counts
            UPDATE socialcandor_schema.dao_proposals
            SET
                votes_for = CASE WHEN NEW.vote_choice = 'FOR' THEN votes_for + 1 ELSE votes_for END,
                votes_against = CASE WHEN NEW.vote_choice = 'AGAINST' THEN votes_against + 1 ELSE votes_against END,
                votes_abstain = CASE WHEN NEW.vote_choice = 'ABSTAIN' THEN votes_abstain + 1 ELSE votes_abstain END,
                voting_power_for = CASE WHEN NEW.vote_choice = 'FOR' THEN voting_power_for + NEW.voting_power ELSE voting_power_for END,
                voting_power_against = CASE WHEN NEW.vote_choice = 'AGAINST' THEN voting_power_against + NEW.voting_power ELSE voting_power_against END,
                voting_power_abstain = CASE WHEN NEW.vote_choice = 'ABSTAIN' THEN voting_power_abstain + NEW.voting_power ELSE voting_power_abstain END
            WHERE proposal_id = NEW.proposal_id;

            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;

        CREATE TRIGGER trg_dao_votes_update_proposal
            AFTER INSERT ON socialcandor_schema.dao_votes
            FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_proposal_vote_counts();

        -- RLS Policy
        ALTER TABLE socialcandor_schema.dao_votes ENABLE ROW LEVEL SECURITY;
        CREATE POLICY dao_votes_public_policy ON socialcandor_schema.dao_votes
            FOR SELECT USING (TRUE);
        CREATE POLICY dao_votes_self_policy ON socialcandor_schema.dao_votes
            FOR ALL USING (voter_user_id = current_setting('app.current_user_id')::UUID);
        CREATE POLICY dao_votes_admin_policy ON socialcandor_schema.dao_votes
            FOR ALL USING (socialcandor_schema.is_admin());


            --================================================================================================
            -- Table: DG03 - dao_delegations
            -- Description: Tracks vote delegations in DAO governance, where users delegate their voting
            --              power to representatives. Enables representative democracy in DAOs.
            -- Business Case: In many DAOs, token holders can delegate their voting power to trusted
            --                representatives who vote on their behalf. This table manages delegation
            --                relationships, including the delegator, delegate, and time period. The
            --                design supports multiple delegation models (direct delegation, algorithmic
            --                delegation, tiered delegation) and tracks delegation changes over time.
            --                This enables more inclusive governance by allowing passive token holders
            --                to participate through active delegates. Historical delegation data helps
            --                analyze power concentration and representative voting patterns.
            --
            -- Key Performance Indicators (KPIs):
            --   1. Delegation rate - Percentage of eligible voters delegating
            --   2. Delegate concentration - Number of delegates and voting power distribution
            --   3. Delegation churn - Rate of delegation changes
            --   4. Delegate participation - How often delegates actually vote
            --   5. Delegator satisfaction - Alignment between delegate and delegator preferences
            --
            -- Feature References:
            --   - GOV20 (Vote Delegation)
            --   - GOV21 (Representative Governance)
            --   - GOV22 (Delegation Analytics)
            --   - WEB324 (Delegated Voting)
            --================================================================================================
            CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_delegations (
                -- Primary key
                delegation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                -- Human-readable identifier
                delegation_number VARCHAR(50) GENERATED ALWAYS AS (
                    'DELEG-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_delegations_seq')::TEXT, 6, '0')
                ) STORED,

                -- Delegation parties
                delegator_user_id UUID NOT NULL,
                delegate_user_id UUID NOT NULL,

                -- Delegation details
                delegation_type VARCHAR(30) DEFAULT 'FULL' CHECK (delegation_type IN (
                    'FULL', 'PARTIAL', 'ISSUE_SPECIFIC', 'TIME_LIMITED'
                )),

                -- Voting power
                voting_power_delegated NUMERIC(30,18) NOT NULL,
                voting_power_source VARCHAR(50) CHECK (voting_power_source IN ('TOKENS', 'REPUTATION', 'MIXED')),

                -- Timing
                from_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                to_date TIMESTAMP WITH TIME ZONE,
                is_active BOOLEAN GENERATED ALWAYS AS (to_date IS NULL OR to_date > CURRENT_TIMESTAMP) STORED,

                -- Scope (for partial delegation)
                proposal_types TEXT[],                                    -- Which proposal types this delegation applies to
                specific_proposals UUID[],                                -- Delegate for specific proposals only

                -- Revocation
                revoked_at TIMESTAMP WITH TIME ZONE,
                revoked_reason TEXT,

                -- On-chain data
                tx_hash VARCHAR(255),                                     -- If delegation is on-chain
                contract_address VARCHAR(255),

                -- Metadata
                metadata JSONB DEFAULT '{}',

                -- Audit columns
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                created_by UUID NOT NULL,
                updated_by UUID DEFAULT uuid_nil(),

                -- Constraints
                CONSTRAINT fk_dao_delegations_delegator FOREIGN KEY (delegator_user_id)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                CONSTRAINT fk_dao_delegations_delegate FOREIGN KEY (delegate_user_id)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
                CONSTRAINT fk_dao_delegations_created_by FOREIGN KEY (created_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                CONSTRAINT fk_dao_delegations_updated_by FOREIGN KEY (updated_by)
                    REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

                CONSTRAINT chk_dao_delegations_self CHECK (delegator_user_id != delegate_user_id),
                CONSTRAINT chk_dao_delegations_dates CHECK (to_date IS NULL OR to_date > from_date),
                CONSTRAINT uk_dao_delegations_active UNIQUE (delegator_user_id) WHERE is_active = TRUE AND delegation_type = 'FULL'
            );

            -- Comments
            COMMENT ON TABLE socialcandor_schema.dao_delegations IS 'Tracks vote delegations in DAO governance for representative democracy';
            COMMENT ON COLUMN socialcandor_schema.dao_delegations.delegation_type IS 'Type of delegation (full, partial, issue-specific, time-limited)';
            COMMENT ON COLUMN socialcandor_schema.dao_delegations.voting_power_delegated IS 'Amount of voting power delegated';
            COMMENT ON COLUMN socialcandor_schema.dao_delegations.proposal_types IS 'Proposal types covered by this delegation (for partial delegation)';
            COMMENT ON COLUMN socialcandor_schema.dao_delegations.specific_proposals IS 'Specific proposal IDs delegated (for issue-specific delegation)';

            -- Indexes for performance
            CREATE INDEX idx_dao_delegations_delegator ON socialcandor_schema.dao_delegations(delegator_user_id, is_active) WHERE is_active = TRUE;
            CREATE INDEX idx_dao_delegations_delegate ON socialcandor_schema.dao_delegations(delegate_user_id, is_active) WHERE is_active = TRUE;
            CREATE INDEX idx_dao_delegations_dates ON socialcandor_schema.dao_delegations(from_date, to_date) WHERE is_active = TRUE;

            -- Trigger for updated_at
            CREATE TRIGGER trg_dao_delegations_updated_at
                BEFORE UPDATE ON socialcandor_schema.dao_delegations
                FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

            -- RLS Policy
            ALTER TABLE socialcandor_schema.dao_delegations ENABLE ROW LEVEL SECURITY;
            CREATE POLICY dao_delegations_delegator_policy ON socialcandor_schema.dao_delegations
                FOR ALL USING (delegator_user_id = current_setting('app.current_user_id')::UUID);
            CREATE POLICY dao_delegations_delegate_policy ON socialcandor_schema.dao_delegations
                FOR SELECT USING (delegate_user_id = current_setting('app.current_user_id')::UUID);
            CREATE POLICY dao_delegations_public_policy ON socialcandor_schema.dao_delegations
                FOR SELECT USING (is_active = TRUE);
            CREATE POLICY dao_delegations_admin_policy ON socialcandor_schema.dao_delegations
                FOR ALL USING (socialcandor_schema.is_admin());

                --================================================================================================
                -- Table: OB03 - runbooks
                -- Description: Documented step-by-step procedures for incident response, operational tasks,
                --              and disaster recovery. Enables consistent and efficient incident handling.
                -- Business Case: During incidents, having well-documented procedures is critical for quick
                --                resolution and consistent response. This table stores runbooks (also called
                --                playbooks) that guide responders through diagnosis, mitigation, and resolution
                --                steps. Each runbook is associated with specific incident types (database
                --                outage, high latency, security breach) and includes verification steps,
                --                rollback procedures, and post-incident tasks. The design supports versioning,
                --                ownership, and metrics on effectiveness. Integration with auto-remediation
                --                enables automated execution of runbook steps where possible.
                --
                -- Key Performance Indicators (KPIs):
                --   1. Runbook coverage - Percentage of incident types with runbooks
                --   2. Runbook usage - How often runbooks are accessed during incidents
                --   3. Time to resolution - Comparison of incidents with/without runbooks
                --   4. Runbook effectiveness - User ratings and feedback
                --   5. Runbook freshness - Time since last review/update
                --
                -- Feature References:
                --   - OBS15 (Runbooks)
                --   - OBS16 (Incident Response)
                --   - OBS17 (Operational Excellence)
                --   - SRE02 (Site Reliability Engineering)
                --================================================================================================
                CREATE TABLE IF NOT EXISTS socialcandor_schema.runbooks (
                    -- Primary key
                    runbook_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

                    -- Human-readable identifier
                    runbook_number VARCHAR(50) GENERATED ALWAYS AS (
                        'RB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.runbooks_seq')::TEXT, 6, '0')
                    ) STORED,

                    -- Runbook identification
                    runbook_name VARCHAR(255) NOT NULL,
                    runbook_description TEXT,
                    runbook_version VARCHAR(20) DEFAULT '1.0',

                    -- Categorization
                    incident_type VARCHAR(100) NOT NULL,                       -- Database outage, high latency, etc.
                    severity_applicable TEXT[],                                 -- Which severities this applies to
                    affected_services TEXT[],                                   -- Services this runbook covers

                    -- Runbook content
                    summary TEXT,
                    prerequisites TEXT,
                    steps JSONB NOT NULL,                                       -- Array of step objects with description, command, verification
                    verification_steps JSONB,
                    rollback_steps JSONB,
                    post_resolution_steps JSONB,

                    -- Estimated times
                    estimated_time_minutes INTEGER,
                    time_to_recover_metric INTEGER,                             -- Historical average time to recover

                    -- Owner
                    owner_team VARCHAR(100) NOT NULL,
                    owner_user_id UUID,
                    reviewers JSONB,                                            -- List of reviewers

                    -- Metrics
                    usage_count INTEGER DEFAULT 0,
                    average_rating NUMERIC(3,2) CHECK (average_rating >= 1 AND average_rating <= 5),
                    last_used_at TIMESTAMP WITH TIME ZONE,

                    -- Review cycle
                    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                    last_reviewed_at TIMESTAMP WITH TIME ZONE,
                    next_review_date DATE GENERATED ALWAYS AS (
                        last_reviewed_at::DATE + INTERVAL '90 days'
                    ) STORED,

                    -- Status
                    is_active BOOLEAN DEFAULT TRUE,
                    is_deprecated BOOLEAN DEFAULT FALSE,

                    -- Attachments
                    attachments JSONB DEFAULT '[]',                              -- URLs to diagrams, scripts

                    -- Audit columns
                    created_by UUID NOT NULL,
                    updated_by UUID DEFAULT uuid_nil(),

                    -- Constraints
                    CONSTRAINT fk_runbooks_owner FOREIGN KEY (owner_user_id)
                        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
                    CONSTRAINT fk_runbooks_created_by FOREIGN KEY (created_by)
                        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
                    CONSTRAINT fk_runbooks_updated_by FOREIGN KEY (updated_by)
                        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
                );

                -- Comments
                COMMENT ON TABLE socialcandor_schema.runbooks IS 'Documented procedures for incident response and operational tasks';
                COMMENT ON COLUMN socialcandor_schema.runbooks.incident_type IS 'Type of incident this runbook addresses';
                COMMENT ON COLUMN socialcandor_schema.runbooks.steps IS 'JSON array of step objects with description, command, verification';
                COMMENT ON COLUMN socialcandor_schema.runbooks.verification_steps IS 'Steps to verify that incident is resolved';
                COMMENT ON COLUMN socialcandor_schema.runbooks.rollback_steps IS 'Steps to rollback changes if needed';
                COMMENT ON COLUMN socialcandor_schema.runbooks.time_to_recover_metric IS 'Historical average time to recover using this runbook';

                -- Indexes for performance
                CREATE INDEX idx_runbooks_incident ON socialcandor_schema.runbooks(incident_type, is_active);
                CREATE INDEX idx_runbooks_owner ON socialcandor_schema.runbooks(owner_team, owner_user_id);
                CREATE INDEX idx_runbooks_review ON socialcandor_schema.runbooks(next_review_date) WHERE is_active = TRUE;

                -- Trigger for updated_at
                CREATE TRIGGER trg_runbooks_updated_at
                    BEFORE UPDATE ON socialcandor_schema.runbooks
                    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

                -- RLS Policy
                ALTER TABLE socialcandor_schema.runbooks ENABLE ROW LEVEL SECURITY;
                CREATE POLICY runbooks_read_policy ON socialcandor_schema.runbooks
                    FOR SELECT USING (TRUE);
                CREATE POLICY runbooks_write_policy ON socialcandor_schema.runbooks
                    FOR ALL USING (
                        owner_team = current_setting('app.current_team') OR
                        owner_user_id = current_setting('app.current_user_id')::UUID OR
                        socialcandor_schema.is_admin()
                    );



-- Partial Indexes for high impact
-- Active users only (reduces index size by ~60%)
CREATE INDEX CONCURRENTLY idx_users_active
ON socialcandor_schema.users(user_id)
WHERE status = 'ACTIVE';

