-- Notification delivery optimization
CREATE INDEX CONCURRENTLY idx_notifications_delivery_covering
ON socialcandor_schema.notifications(user_id, channel, created_at DESC)
INCLUDE (notification_id, title, message, delivery_status);

-- User profile queries
CREATE INDEX CONCURRENTLY idx_users_profile_covering
ON socialcandor_schema.users(user_id)
INCLUDE (username, display_name, avatar_url, verification_level, trust_score);

-- Wallet balance queries
CREATE INDEX CONCURRENTLY idx_wallets_balance_covering
ON socialcandor_schema.user_wallets(user_id)
INCLUDE (available_balance, pending_balance, currency_code, status);

