-- Create materialized views for denormalized counters
CREATE MATERIALIZED VIEW mv_post_engagement_stats AS
SELECT
    p.post_id,
    COUNT(DISTINCT pr.reaction_id) AS like_count,
    COUNT(DISTINCT pc.comment_id) AS comment_count,
    COUNT(DISTINCT s.share_id) AS share_count
FROM socialcandor_schema.posts p
LEFT JOIN socialcandor_schema.post_reactions pr ON p.post_id = pr.post_id
LEFT JOIN socialcandor_schema.posts_comments pc ON p.post_id = pc.post_id
LEFT JOIN socialcandor_schema.shares s ON p.post_id = s.post_id
GROUP BY p.post_id;

-- Refresh daily or on-demand
CREATE OR REPLACE FUNCTION refresh_post_stats()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_post_engagement_stats;
END;
$$ LANGUAGE plpgsql;

-- =================================================================================================
-- Phase 1: Security & Authentication Tables
-- Description: Implements 10 tables for enhanced security and authentication management,
--              including MFA, password reset, session tracking, device trust, OAuth tokens,
--              permission auditing, role hierarchies, and security policies.
-- Business Case: Strengthens platform security with granular authentication methods,
--                robust audit trails, and flexible policy enforcement.
-- =================================================================================================

-- =================================================================================================
-- ENUMS
-- =================================================================================================

-- Enum: auth_method_type
-- Description: Types of multi-factor authentication methods supported
-- Business Case: Categorize MFA methods for display and enforcement
-- Feature Reference: SEC50 (Multi-Factor Authentication)
CREATE TYPE socialcandor_schema.auth_method_type AS ENUM (
    'TOTP',           -- Time-based One-Time Password (Google Authenticator, etc.)
    'SMS',            -- SMS OTP
    'EMAIL',          -- Email OTP
    'WEBAUTHN',       -- WebAuthn / Passkeys
    'BACKUP_CODE',    -- Backup codes
    'PUSH',           -- Push notification
    'HARDWARE_TOKEN'  -- Physical hardware token
);
COMMENT ON TYPE socialcandor_schema.auth_method_type IS 'Supported multi-factor authentication methods';

-- Enum: question_type
-- Description: Types of security questions (predefined or custom)
-- Business Case: Standardize security questions while allowing custom ones
-- Feature Reference: SEC51 (Security Questions)
CREATE TYPE socialcandor_schema.question_type AS ENUM (
    'PREDEFINED',     -- System-provided question
    'CUSTOM'          -- User-defined question
);
COMMENT ON TYPE socialcandor_schema.question_type IS 'Types of security questions';

-- Enum: blacklist_reason
-- Description: Reasons for blacklisting a session
-- Business Case: Audit trail for session termination
-- Feature Reference: SEC52 (Session Management)
CREATE TYPE socialcandor_schema.blacklist_reason AS ENUM (
    'LOGOUT',         -- User-initiated logout
    'PASSWORD_CHANGE',-- Password changed, invalidate all sessions
    'MFA_CHANGE',     -- MFA settings changed
    'ADMIN_REVOKE',   -- Admin revoked session
    'TIMEOUT',        -- Session expired
    'SUSPICIOUS',     -- Suspicious activity detected
    'DEVICE_REMOVED'  -- Device untrusted
);
COMMENT ON TYPE socialcandor_schema.blacklist_reason IS 'Reasons for blacklisting a session';

-- Enum: login_outcome
-- Description: Outcome of a login attempt
-- Business Case: Detailed tracking for security analytics
-- Feature Reference: SEC53 (Login Monitoring)
CREATE TYPE socialcandor_schema.login_outcome AS ENUM (
    'SUCCESS',        -- Successful login
    'INVALID_CREDENTIALS', -- Wrong password/username
    'LOCKED_OUT',     -- Account temporarily locked
    'DISABLED',       -- Account disabled
    'MFA_FAILED',     -- MFA verification failed
    'EXPIRED_PASSWORD', -- Password expired
    'IP_BLOCKED',     -- IP blocked
    'RATE_LIMITED'    -- Too many attempts
);
COMMENT ON TYPE socialcandor_schema.login_outcome IS 'Outcome of a login attempt';

-- Enum: trust_level
-- Description: Level of trust for a device
-- Business Case: Graduated trust for risk-based authentication
-- Feature Reference: SEC54 (Device Trust)
CREATE TYPE socialcandor_schema.trust_level AS ENUM (
    'UNTRUSTED',      -- New device, needs verification
    'TRUSTED',        -- Verified device
    'HIGHLY_TRUSTED', -- Frequently used, low risk
    'ADMIN_TRUSTED'   -- Admin-marked trusted
);
COMMENT ON TYPE socialcandor_schema.trust_level IS 'Trust level for user devices';

-- Enum: token_status
-- Description: Status of API access tokens
-- Business Case: Track token lifecycle
-- Feature Reference: API12 (Token Management)
CREATE TYPE socialcandor_schema.token_status AS ENUM (
    'ACTIVE',         -- Can be used
    'EXPIRED',        -- Past expiration date
    'REVOKED',        -- Explicitly revoked
    'PENDING'         -- Awaiting approval (if required)
);
COMMENT ON TYPE socialcandor_schema.token_status IS 'Status of API access tokens';

-- Enum: permission_change_action
-- Description: Type of permission change recorded in audit logs
-- Business Case: Categorize audit events
-- Feature Reference: AUD20 (Permission Auditing)
CREATE TYPE socialcandor_schema.permission_change_action AS ENUM (
    'GRANT',          -- Permission granted
    'REVOKE',         -- Permission revoked
    'ROLE_ASSIGN',    -- Role assigned
    'ROLE_UNASSIGN',  -- Role removed
    'ROLE_CREATE',    -- Role created
    'ROLE_UPDATE',    -- Role modified
    'ROLE_DELETE',    -- Role deleted
    'PERM_CREATE',    -- Permission created
    'PERM_UPDATE',    -- Permission updated
    'PERM_DELETE'     -- Permission deleted
);
COMMENT ON TYPE socialcandor_schema.permission_change_action IS 'Actions recorded in permission audit logs';

-- Enum: policy_type
-- Description: Types of security policies
-- Business Case: Categorize policies for different security domains
-- Feature Reference: SEC55 (Security Policies)
CREATE TYPE socialcandor_schema.policy_type AS ENUM (
    'PASSWORD',       -- Password complexity, rotation
    'MFA',            -- MFA enforcement
    'SESSION',        -- Session timeouts, concurrent sessions
    'LOGIN',          -- Login throttling, lockout
    'DEVICE',         -- Device trust requirements
    'API',            -- API access controls
    'DATA_RETENTION', -- Data retention periods
    'AUDIT'           -- Audit logging requirements
);
COMMENT ON TYPE socialcandor_schema.policy_type IS 'Types of security policies';

-- Enum: policy_scope
-- Description: Scope of a security policy
-- Business Case: Apply policies at different levels (global, org, user)
-- Feature Reference: SEC55
CREATE TYPE socialcandor_schema.policy_scope AS ENUM (
    'GLOBAL',         -- Applies to entire platform
    'ORGANIZATION',   -- Applies to specific organization
    'ROLE',           -- Applies to users with specific role
    'USER'            -- Applies to individual user
);
COMMENT ON TYPE socialcandor_schema.policy_scope IS 'Scope of a security policy';

-- Enum: enforcement_level
-- Description: How strictly a policy is enforced
-- Business Case: Allow grace periods or warnings before strict enforcement
-- Feature Reference: SEC55
CREATE TYPE socialcandor_schema.enforcement_level AS ENUM (
    'STRICT',         -- Enforced, cannot be bypassed
    'WARNING',        -- Logs warning but allows action
    'REPORT_ONLY',    -- Only logs, no action
    'DISABLED'        -- Policy not enforced
);
COMMENT ON TYPE socialcandor_schema.enforcement_level IS 'Enforcement level for security policies';

