CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.user_security_question_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.password_reset_token_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.session_blacklist_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.login_attempt_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.device_trust_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.api_access_token_seq START 1000;
