CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.role_hierarchy_mapping_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.security_policy_seq START 1000;

-- =================================================================================================
-- Table 1: user_authentication_methods
-- Description: Stores multi-factor authentication methods per user, including encrypted secrets
--              and metadata. Supports TOTP, SMS, email OTP, WebAuthn, and backup codes.
-- Business Case: Multi-factor authentication is essential for account security. This table
--                manages all MFA methods a user has enabled, storing secrets securely (encrypted)
--                and tracking verification status. It enables users to have multiple backup methods
--                (e.g., authenticator app + SMS) and administrators to enforce MFA policies.
--                The design supports method-specific configuration (e.g., phone number for SMS,
--                public key for WebAuthn) and tracks last used time for inactivity checks.
--                Backup codes are stored as hashed values for one-time use.
-- KPIs:
--   1. MFA adoption rate - Percentage of users with at least one active MFA method
--   2. Method distribution - Popularity of each MFA method
--   3. MFA usage frequency - Average time between MFA verifications per user
--   4. Recovery code usage rate - Frequency of backup code usage
--   5. Method churn - Rate of MFA method addition/removal
-- Feature References: SEC50 (Multi-Factor Authentication), SEC56 (MFA Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_authentication_methods (
    method_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    method_number VARCHAR(50) GENERATED ALWAYS AS (
        'MFA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_auth_method_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    method_type socialcandor_schema.auth_method_type NOT NULL,
    -- Encrypted secrets and configuration
    encrypted_secret TEXT,                     -- TOTP secret, etc. (encrypted with master key)
    public_key TEXT,                           -- For WebAuthn
    credential_id TEXT,                         -- WebAuthn credential ID
    phone_number VARCHAR(20),                   -- For SMS
    email VARCHAR(255),                          -- For email OTP
    backup_codes TEXT[],                         -- Hashed backup codes (if applicable)
    -- Metadata
    method_name VARCHAR(100),                    -- User-defined name (e.g., "My Auth App")
    is_primary BOOLEAN DEFAULT FALSE,            -- Primary method for fallback
    is_active BOOLEAN DEFAULT TRUE,
    verified_at TIMESTAMP WITH TIME ZONE,        -- When method was verified
    last_used_at TIMESTAMP WITH TIME ZONE,
    failure_count INTEGER DEFAULT 0 CHECK (failure_count >= 0),
    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,         -- For temporary methods (e.g., SMS code)
    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    -- Constraints
    CONSTRAINT fk_user_auth_methods_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_auth_methods_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_auth_methods_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_auth_methods_deleted_by FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_user_auth_methods_data CHECK (
        (method_type = 'TOTP' AND encrypted_secret IS NOT NULL) OR
        (method_type = 'SMS' AND phone_number IS NOT NULL) OR
        (method_type = 'EMAIL' AND email IS NOT NULL) OR
        (method_type = 'WEBAUTHN' AND credential_id IS NOT NULL) OR
        (method_type IN ('BACKUP_CODE', 'PUSH', 'HARDWARE_TOKEN') OR true)
    ),
    CONSTRAINT chk_user_auth_methods_expiry CHECK (expires_at IS NULL OR expires_at > created_at)
);

COMMENT ON TABLE socialcandor_schema.user_authentication_methods IS 'Stores multi-factor authentication methods per user';
COMMENT ON COLUMN socialcandor_schema.user_authentication_methods.encrypted_secret IS 'Encrypted secret for TOTP or other methods';
COMMENT ON COLUMN socialcandor_schema.user_authentication_methods.backup_codes IS 'Array of hashed backup codes';
COMMENT ON COLUMN socialcandor_schema.user_authentication_methods.is_primary IS 'Whether this is the primary MFA method';

-- Indexes
CREATE INDEX idx_user_auth_methods_user ON socialcandor_schema.user_authentication_methods(user_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_user_auth_methods_type ON socialcandor_schema.user_authentication_methods(method_type);
CREATE INDEX idx_user_auth_methods_primary ON socialcandor_schema.user_authentication_methods(user_id, is_primary) WHERE is_primary = TRUE AND is_active = TRUE;
CREATE INDEX idx_user_auth_methods_credential ON socialcandor_schema.user_authentication_methods(credential_id) WHERE credential_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_user_authentication_methods_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_authentication_methods
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.user_authentication_methods ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_auth_methods_self_policy ON socialcandor_schema.user_authentication_methods
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_auth_methods_admin_policy ON socialcandor_schema.user_authentication_methods
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 2: user_security_questions
-- Description: Stores security questions and answers for backup authentication.
--              Supports predefined or custom questions with encrypted answers.
-- Business Case: Security questions provide a fallback authentication mechanism when
--                primary methods (password, MFA) are unavailable. This table stores
--                user-selected questions and hashed answers, ensuring that answers are
--                never stored in plaintext. The design allows multiple questions per user
--                (typically 3-5) with configurable minimum requirements. Answers are hashed
--                with a salt to prevent rainbow table attacks. This feature is especially
--                important for account recovery and complies with NIST 800-63B guidelines
--                for knowledge-based authentication.
-- KPIs:
--   1. Security question adoption - Percentage of users with questions set
--   2. Recovery success rate - Percentage of successful recoveries using questions
--   3. Question strength - Distribution of answer strength/complexity
--   4. Failed attempts - Number of incorrect answer attempts
--   5. Question change frequency - How often users update questions
-- Feature References: SEC51 (Security Questions), SEC57 (Account Recovery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_security_questions (
    question_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    question_number VARCHAR(50) GENERATED ALWAYS AS (
        'SQ-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_security_question_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    question_type socialcandor_schema.question_type NOT NULL,
    question_text TEXT NOT NULL,
    answer_hash VARCHAR(255) NOT NULL,           -- Hashed answer
    answer_salt VARCHAR(64),                      -- Salt for hashing
    answer_hint TEXT,                              -- Optional hint
    display_order INTEGER CHECK (display_order >= 0),
    is_active BOOLEAN DEFAULT TRUE,
    failed_attempts INTEGER DEFAULT 0 CHECK (failed_attempts >= 0),
    last_attempt_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    -- Constraints
    CONSTRAINT fk_user_security_questions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_security_questions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_security_questions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_security_questions_deleted_by FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_user_security_questions_order UNIQUE (user_id, display_order) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT chk_user_security_questions_text CHECK (LENGTH(question_text) > 0)
);

COMMENT ON TABLE socialcandor_schema.user_security_questions IS 'Stores security questions and hashed answers for backup authentication';
COMMENT ON COLUMN socialcandor_schema.user_security_questions.answer_hash IS 'Hashed answer using strong algorithm (bcrypt, argon2)';
COMMENT ON COLUMN socialcandor_schema.user_security_questions.answer_salt IS 'Salt used for hashing (if not using self-contained hash)';

-- Indexes
CREATE INDEX idx_user_security_questions_user ON socialcandor_schema.user_security_questions(user_id, is_active) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_user_security_questions_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_security_questions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.user_security_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_security_questions_self_policy ON socialcandor_schema.user_security_questions
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_security_questions_admin_policy ON socialcandor_schema.user_security_questions
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 3: password_reset_tokens
-- Description: Tracks password reset requests with secure tokens, expiration, and usage limits.
--              Supports rate limiting and audit trails.
-- Business Case: Password reset is a critical security workflow that must be protected against
--                abuse. This table manages reset tokens with strong random generation, expiration
--                (typically 15-60 minutes), and single-use semantics. It tracks the number of
--                attempts to prevent brute force. The design supports different reset methods
--                (email, SMS, security questions) and records metadata for forensic analysis.
--                Tokens are stored as hashed values to prevent exposure in database leaks.
--                Rate limiting at the user/IP level prevents enumeration attacks.
-- KPIs:
--   1. Reset request volume - Number of password resets per day
--   2. Success rate - Percentage of reset tokens successfully used
   3. Expiry rate - Percentage of tokens that expire unused
--   4. Abuse attempts - Number of invalid token attempts
--   5. Time to reset - Average time from request to completion
-- Feature References: SEC58 (Password Reset), SEC59 (Account Recovery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.password_reset_tokens (
    token_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    token_number VARCHAR(50) GENERATED ALWAYS AS (
        'PRT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.password_reset_token_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    token_hash VARCHAR(255) NOT NULL UNIQUE,     -- SHA-256 hash of the raw token
    token_type VARCHAR(30) DEFAULT 'EMAIL' CHECK (token_type IN ('EMAIL', 'SMS', 'SECURITY_QUESTIONS')),
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    used_at TIMESTAMP WITH TIME ZONE,
    is_valid BOOLEAN GENERATED ALWAYS AS (used_at IS NULL AND expires_at > CURRENT_TIMESTAMP) STORED,
    -- Rate limiting / abuse prevention
    attempt_count INTEGER DEFAULT 0 CHECK (attempt_count >= 0),
    last_attempt_at TIMESTAMP WITH TIME ZONE,
    created_ip INET,
    created_user_agent TEXT,
    used_ip INET,
    used_user_agent TEXT,
    -- Metadata
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_password_reset_tokens_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_password_reset_tokens_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_password_reset_tokens_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_password_reset_tokens_expiry CHECK (expires_at > created_at),
    CONSTRAINT chk_password_reset_tokens_used CHECK (used_at IS NULL OR used_at >= created_at)
);

COMMENT ON TABLE socialcandor_schema.password_reset_tokens IS 'Manages password reset tokens with expiration and usage tracking';
COMMENT ON COLUMN socialcandor_schema.password_reset_tokens.token_hash IS 'SHA-256 hash of the random token (never store plaintext)';
COMMENT ON COLUMN socialcandor_schema.password_reset_tokens.is_valid IS 'Whether token is still valid (unused and not expired)';

-- Indexes
CREATE INDEX idx_password_reset_tokens_user ON socialcandor_schema.password_reset_tokens(user_id, created_at DESC);
CREATE INDEX idx_password_reset_tokens_token ON socialcandor_schema.password_reset_tokens(token_hash);
CREATE INDEX idx_password_reset_tokens_valid ON socialcandor_schema.password_reset_tokens(expires_at) WHERE is_valid = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_password_reset_tokens_updated_at
    BEFORE UPDATE ON socialcandor_schema.password_reset_tokens
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.password_reset_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY password_reset_tokens_self_policy ON socialcandor_schema.password_reset_tokens
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY password_reset_tokens_admin_policy ON socialcandor_schema.password_reset_tokens
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 4: session_blacklist
-- Description: Tracks revoked or terminated sessions to prevent their use even before expiration.
--              Essential for immediate logout, password changes, and security events.
-- Business Case: When a user logs out, changes password, or an admin revokes a session,
--                the session token must be immediately invalidated. Simply relying on expiration
--                is insufficient. This table stores blacklisted session identifiers (usually the
--                session ID or a token hash) with a timestamp and reason. During authentication,
--                the system checks this blacklist before accepting a session. The blacklist can
--                be cleaned periodically of entries older than the maximum session lifetime.
--                This is a fundamental security control for session management.
-- KPIs:
--   1. Blacklist size - Number of active blacklisted sessions
--   2. Blacklist reasons - Distribution of revocation reasons
--   3. Cleanup efficiency - Time to purge expired blacklist entries
--   4. Session reuse attempts - Attempts to use blacklisted sessions
--   5. Average time from revocation to blacklist entry
-- Feature References: SEC52 (Session Management), SEC60 (Session Revocation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.session_blacklist (
    blacklist_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    blacklist_number VARCHAR(50) GENERATED ALWAYS AS (
        'SBL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.session_blacklist_seq')::TEXT, 6, '0')
    ) STORED,
    session_id UUID,                                   -- If session is stored in sessions table
    session_token_hash VARCHAR(255) NOT NULL,          -- Hash of the session token (for stateless tokens)
    user_id UUID,
    reason socialcandor_schema.blacklist_reason NOT NULL,
    blacklisted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,               -- When this blacklist entry expires (auto-cleanup)
    ip_address INET,
    user_agent TEXT,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_session_blacklist_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE CASCADE,
    CONSTRAINT fk_session_blacklist_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_session_blacklist_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_session_blacklist_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_session_blacklist_expiry CHECK (expires_at IS NULL OR expires_at > blacklisted_at)
);

COMMENT ON TABLE socialcandor_schema.session_blacklist IS 'Tracks revoked sessions for immediate invalidation';
COMMENT ON COLUMN socialcandor_schema.session_blacklist.session_token_hash IS 'Hash of the session token for stateless JWT sessions';

-- Indexes
CREATE INDEX idx_session_blacklist_token ON socialcandor_schema.session_blacklist(session_token_hash);
CREATE INDEX idx_session_blacklist_session ON socialcandor_schema.session_blacklist(session_id) WHERE session_id IS NOT NULL;
CREATE INDEX idx_session_blacklist_user ON socialcandor_schema.session_blacklist(user_id);
CREATE INDEX idx_session_blacklist_expires ON socialcandor_schema.session_blacklist(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_session_blacklist_updated_at
    BEFORE UPDATE ON socialcandor_schema.session_blacklist
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.session_blacklist ENABLE ROW LEVEL SECURITY;
CREATE POLICY session_blacklist_admin_policy ON socialcandor_schema.session_blacklist
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 5: login_attempt_logs
-- Description: Detailed log of every login attempt (success/failure) with rich context:
--              IP, user agent, device fingerprint, geolocation, and failure reason.
--              Supports security analytics, threat detection, and compliance.
-- Business Case: Comprehensive login logging is essential for detecting brute-force attacks,
--                account takeover attempts, and unusual access patterns. This table captures
--                every authentication event with enough detail to reconstruct the user's login
--                history, identify compromised accounts, and meet compliance requirements (SOC2,
--                GDPR). The data feeds SIEM systems and enables real-time alerting on suspicious
--                patterns (e.g., multiple failures from different IPs). Partitioning by date
--                ensures performance even with billions of records.
-- KPIs:
--   1. Login success rate - Percentage of successful logins
--   2. Failed attempt concentration - Users with high failure rates
--   3. Unique IPs per user - Average number of distinct IPs
--   4. Geolocation anomalies - Logins from impossible travel distances
--   5. Brute force detection - Number of IPs with >10 failures/hour
-- Feature References: SEC53 (Login Monitoring), SEC61 (Threat Detection)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.login_attempt_logs (
    log_id BIGSERIAL,
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'LA-' || TO_CHAR(attempted_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.login_attempt_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID,
    username_attempt VARCHAR(255),                 -- Username entered (if any)
    attempted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    outcome socialcandor_schema.login_outcome NOT NULL,
    -- Authentication factors used
    primary_method VARCHAR(30) CHECK (primary_method IN ('PASSWORD', 'MFA', 'SSO', 'MAGIC_LINK', 'API_KEY')),
    secondary_method VARCHAR(30),
    -- Network details
    ip_address INET NOT NULL,
    ip_country VARCHAR(3),
    ip_city VARCHAR(100),
    ip_latitude NUMERIC(10,8),
    ip_longitude NUMERIC(11,8),
    isp VARCHAR(255),
    proxy_type VARCHAR(50),                         -- VPN, TOR, etc.
    -- Device details
    user_agent TEXT,
    device_fingerprint VARCHAR(255),
    device_type VARCHAR(50),
    browser VARCHAR(100),
    os VARCHAR(100),
    -- Session (if successful)
    session_id UUID,
    -- Risk score (if calculated)
    risk_score NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
    risk_factors TEXT[],
    -- Partition key
    attempt_date DATE GENERATED ALWAYS AS (attempted_at::DATE) STORED,
    -- Constraints
    CONSTRAINT pk_login_attempt_logs PRIMARY KEY (log_id, attempt_date),
    CONSTRAINT fk_login_attempt_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_login_attempt_logs_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
) PARTITION BY RANGE (attempt_date);

COMMENT ON TABLE socialcandor_schema.login_attempt_logs IS 'Detailed log of login attempts for security monitoring and analytics';
COMMENT ON COLUMN socialcandor_schema.login_attempt_logs.username_attempt IS 'Username attempted (for failed attempts where user_id unknown)';
COMMENT ON COLUMN socialcandor_schema.login_attempt_logs.risk_score IS 'Calculated risk score for this attempt (0-100)';

-- Create monthly partitions (example for current and next 12 months)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'login_attempt_logs_' || TO_CHAR(start_date, 'YYYY_MM');
        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.login_attempt_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes (on parent, will be inherited)
CREATE INDEX idx_login_attempt_logs_user ON socialcandor_schema.login_attempt_logs(user_id, attempted_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_login_attempt_logs_ip ON socialcandor_schema.login_attempt_logs(ip_address, attempted_at DESC);
CREATE INDEX idx_login_attempt_logs_outcome ON socialcandor_schema.login_attempt_logs(outcome, attempted_at DESC);
CREATE INDEX idx_login_attempt_logs_risk ON socialcandor_schema.login_attempt_logs(risk_score DESC) WHERE risk_score > 70;

-- RLS Policies
ALTER TABLE socialcandor_schema.login_attempt_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY login_attempt_logs_self_policy ON socialcandor_schema.login_attempt_logs
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY login_attempt_logs_admin_policy ON socialcandor_schema.login_attempt_logs
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 6: device_trust_records
-- Description: Manages trusted devices for users, including trust level, verification history,
--              and device fingerprints. Enables risk-based authentication.
-- Business Case: Trusted devices improve user experience by reducing friction for known devices
--                while maintaining security. This table records devices that users have
--                successfully used before, with a trust level that can increase over time.
--                It stores device fingerprints (derived from browser/device characteristics)
--                to recognize returning devices. The design supports expiration of trust
--                after periods of inactivity and allows users to manage (rename, revoke) devices.
--                Integration with login logs enables automatic trust scoring based on usage
--                patterns. This is a key component of adaptive authentication.
-- KPIs:
--   1. Trusted device adoption - Average number of trusted devices per user
--   2. Trust level distribution - Percentage of devices at each trust level
--   3. Device churn - Rate of device addition/removal
--   4. Trusted login percentage - Logins from trusted vs. untrusted devices
--   5. Device activity - Last seen distribution
-- Feature References: SEC54 (Device Trust), SEC62 (Adaptive Authentication)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.device_trust_records (
    device_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    device_number VARCHAR(50) GENERATED ALWAYS AS (
        'DTR-' || TO_CHAR(first_seen_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.device_trust_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    device_fingerprint VARCHAR(255) NOT NULL,      -- Unique device identifier (hashed)
    device_name VARCHAR(100),                       -- User-assigned name (e.g., "Work Laptop")
    device_type VARCHAR(50),                         -- e.g., 'desktop', 'mobile', 'tablet'
    os VARCHAR(100),
    browser VARCHAR(100),
    trust_level socialcandor_schema.trust_level NOT NULL DEFAULT 'UNTRUSTED',
    first_seen_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    verified_at TIMESTAMP WITH TIME ZONE,            -- When device was verified (e.g., via MFA)
    verification_method VARCHAR(50),                 -- How device was verified
    is_current BOOLEAN DEFAULT TRUE,
    expires_at TIMESTAMP WITH TIME ZONE,              -- Optional expiration for trust
    total_logins INTEGER DEFAULT 0 CHECK (total_logins >= 0),
    failed_attempts INTEGER DEFAULT 0 CHECK (failed_attempts >= 0),
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    -- Constraints
    CONSTRAINT fk_device_trust_records_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_device_trust_records_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_device_trust_records_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_device_trust_records_deleted_by FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_device_trust_records_fingerprint UNIQUE (user_id, device_fingerprint) WHERE deleted_at IS NULL,
    CONSTRAINT chk_device_trust_records_expiry CHECK (expires_at IS NULL OR expires_at > first_seen_at)
);

COMMENT ON TABLE socialcandor_schema.device_trust_records IS 'Manages trusted devices for users with trust levels and verification history';
COMMENT ON COLUMN socialcandor_schema.device_trust_records.device_fingerprint IS 'Hashed unique device identifier';
COMMENT ON COLUMN socialcandor_schema.device_trust_records.trust_level IS 'Current trust level of the device';
COMMENT ON COLUMN socialcandor_schema.device_trust_records.is_current IS 'Whether this is the current active record for this device';

-- Indexes
CREATE INDEX idx_device_trust_records_user ON socialcandor_schema.device_trust_records(user_id, trust_level, last_seen_at DESC);
CREATE INDEX idx_device_trust_records_fingerprint ON socialcandor_schema.device_trust_records(device_fingerprint);
CREATE INDEX idx_device_trust_records_last_seen ON socialcandor_schema.device_trust_records(last_seen_at DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_device_trust_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.device_trust_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.device_trust_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_trust_records_self_policy ON socialcandor_schema.device_trust_records
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY device_trust_records_admin_policy ON socialcandor_schema.device_trust_records
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 7: api_access_tokens
-- Description: Manages OAuth2 tokens and personal access tokens for API authentication.
--              Supports token expiration, scopes, and revocation.
-- Business Case: API security requires robust token management. This table handles both
--                OAuth2 access tokens (for third-party apps) and personal access tokens
--                (for developers). It stores token hashes (never plaintext), expiration times,
--                associated scopes (permissions), and client information. The design supports
--                token revocation (explicit or via expiry) and refresh token rotation for OAuth2.
--                Integration with audit logs ensures tracking of token usage. This is essential
--                for platform API security and compliance with standards like OAuth2 and OIDC.
-- KPIs:
--   1. Token issuance rate - Number of new tokens per day
--   2. Active tokens - Number of valid tokens per user/client
--   3. Token usage - Average token lifetime and usage frequency
--   4. Revocation rate - Percentage of tokens revoked before expiry
--   5. Scope distribution - Most common permission scopes requested
-- Feature References: API12 (Token Management), SEC63 (API Security)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_access_tokens (
    token_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    token_number VARCHAR(50) GENERATED ALWAYS AS (
        'TOK-' || TO_CHAR(issued_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.api_access_token_seq')::TEXT, 6, '0')
    ) STORED,
    user_id UUID NOT NULL,
    client_id UUID,                                    -- For OAuth2 client (if applicable)
    token_hash VARCHAR(255) NOT NULL UNIQUE,           -- SHA-256 hash of the token
    refresh_token_hash VARCHAR(255) UNIQUE,             -- For OAuth2 refresh tokens
    token_type VARCHAR(30) NOT NULL CHECK (token_type IN ('BEARER', 'MAC', 'PERSONAL')),
    token_status socialcandor_schema.token_status NOT NULL DEFAULT 'ACTIVE',
    scopes TEXT[] DEFAULT '{}',                         -- Permissions granted
    issued_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    last_used_at TIMESTAMP WITH TIME ZONE,
    revoked_at TIMESTAMP WITH TIME ZONE,
    revocation_reason TEXT,
    -- Client metadata
    client_ip INET,
    user_agent TEXT,
    device_fingerprint VARCHAR(255),
    -- Rate limit override (if any)
    rate_limit_override INTEGER,
    -- Metadata
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_api_access_tokens_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_api_access_tokens_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_api_access_tokens_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_api_access_tokens_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_api_access_tokens_expiry CHECK (expires_at > issued_at),
    CONSTRAINT chk_api_access_tokens_refresh CHECK (
        (token_type = 'BEARER' AND refresh_token_hash IS NOT NULL) OR
        (token_type != 'BEARER' AND refresh_token_hash IS NULL)
    )
);

COMMENT ON TABLE socialcandor_schema.api_access_tokens IS 'Manages OAuth2 and personal access tokens for API authentication';
COMMENT ON COLUMN socialcandor_schema.api_access_tokens.token_hash IS 'SHA-256 hash of the access token (never store plaintext)';
COMMENT ON COLUMN socialcandor_schema.api_access_tokens.refresh_token_hash IS 'SHA-256 hash of refresh token for OAuth2';
COMMENT ON COLUMN socialcandor_schema.api_access_tokens.scopes IS 'Array of permission scopes granted to this token';

-- Indexes
CREATE INDEX idx_api_access_tokens_user ON socialcandor_schema.api_access_tokens(user_id, token_status, expires_at);
CREATE INDEX idx_api_access_tokens_hash ON socialcandor_schema.api_access_tokens(token_hash);
CREATE INDEX idx_api_access_tokens_refresh ON socialcandor_schema.api_access_tokens(refresh_token_hash) WHERE refresh_token_hash IS NOT NULL;
CREATE INDEX idx_api_access_tokens_expires ON socialcandor_schema.api_access_tokens(expires_at) WHERE token_status = 'ACTIVE';
CREATE INDEX idx_api_access_tokens_client ON socialcandor_schema.api_access_tokens(client_id) WHERE client_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_api_access_tokens_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_access_tokens
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_access_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY api_access_tokens_self_policy ON socialcandor_schema.api_access_tokens
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY api_access_tokens_admin_policy ON socialcandor_schema.api_access_tokens
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 8: permission_audit_logs
-- Description: Comprehensive audit trail of all permission and role changes, including before/after
--              snapshots, actor, timestamp, and reason. Supports compliance and forensic analysis.
-- Business Case: Changes to permissions and roles are security-sensitive events that must be
--                logged for audit purposes (SOC2, ISO27001, GDPR). This table records every
--                grant, revoke, role assignment, and role modification with complete context:
--                who made the change, when, from where, and what was changed (including before/after
--                snapshots). The data enables security investigations, compliance reporting, and
--                detection of privilege escalation attempts. It also supports answering questions
--                like "Who had access to this resource on a given date?" for forensic purposes.
-- KPIs:
--   1. Permission change volume - Number of changes per day
--   2. Most active changers - Users/admins making most changes
--   3. Privilege escalation attempts - Suspicious changes detected
--   4. Time to detect unauthorized changes - Average detection time
--   5. Audit completeness - Percentage of changes captured
-- Feature References: AUD20 (Permission Auditing), SEC64 (Privilege Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.permission_audit_logs (
    audit_id BIGSERIAL,
    audit_number VARCHAR(50) GENERATED ALWAYS AS (
        'PA-' || TO_CHAR(occurred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.permission_audit_log_seq')::TEXT, 6, '0')
    ) STORED,
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actor_user_id UUID NOT NULL,                       -- User who performed the action
    action socialcandor_schema.permission_change_action NOT NULL,
    -- Target of change
    target_user_id UUID,                                -- If action affects a user (grant/revoke)
    target_role_id UUID,                                -- If action affects a role
    target_permission_id UUID,                          -- If action affects a permission
    -- Context
    before_state JSONB,                                  -- Snapshot before change
    after_state JSONB,                                   -- Snapshot after change
    reason TEXT,                                         -- Optional reason (e.g., ticket reference)
    -- Network context
    ip_address INET,
    user_agent TEXT,
    session_id UUID,
    -- Metadata
    metadata JSONB DEFAULT '{}',
    -- Partition key
    occurred_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,
    -- Constraints
    CONSTRAINT pk_permission_audit_logs PRIMARY KEY (audit_id, occurred_date),
    CONSTRAINT fk_permission_audit_logs_actor FOREIGN KEY (actor_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_permission_audit_logs_target_user FOREIGN KEY (target_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_permission_audit_logs_target_role FOREIGN KEY (target_role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE SET NULL,
    CONSTRAINT fk_permission_audit_logs_target_permission FOREIGN KEY (target_permission_id)
        REFERENCES socialcandor_schema.permissions(permission_id) ON DELETE SET NULL
) PARTITION BY RANGE (occurred_date);

COMMENT ON TABLE socialcandor_schema.permission_audit_logs IS 'Audit trail of all permission and role changes';
COMMENT ON COLUMN socialcandor_schema.permission_audit_logs.before_state IS 'JSON snapshot of relevant state before change';
COMMENT ON COLUMN socialcandor_schema.permission_audit_logs.after_state IS 'JSON snapshot after change';

-- Create monthly partitions
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'permission_audit_logs_' || TO_CHAR(start_date, 'YYYY_MM');
        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.permission_audit_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes
CREATE INDEX idx_permission_audit_logs_actor ON socialcandor_schema.permission_audit_logs(actor_user_id, occurred_at DESC);
CREATE INDEX idx_permission_audit_logs_target_user ON socialcandor_schema.permission_audit_logs(target_user_id, occurred_at DESC) WHERE target_user_id IS NOT NULL;
CREATE INDEX idx_permission_audit_logs_target_role ON socialcandor_schema.permission_audit_logs(target_role_id, occurred_at DESC) WHERE target_role_id IS NOT NULL;
CREATE INDEX idx_permission_audit_logs_action ON socialcandor_schema.permission_audit_logs(action, occurred_at DESC);

-- RLS Policies
ALTER TABLE socialcandor_schema.permission_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY permission_audit_logs_admin_policy ON socialcandor_schema.permission_audit_logs
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 9: role_hierarchy_mappings
-- Description: Defines parent-child relationships between roles, enabling role inheritance.
--              Supports complex permission structures with depth tracking.
-- Business Case: Role-based access control often requires inheritance (e.g., Admin inherits
--                from Manager, which inherits from Employee). This table models such hierarchies,
--                allowing roles to inherit permissions from parent roles. The design supports
--                multiple inheritance (a role can have multiple parents) and tracks depth to
--                prevent cycles and optimize queries. This enables fine-grained permission
--                management while reducing redundancy. It also supports temporary assignments
--                (e.g., acting manager) with time-bound validity.
-- KPIs:
--   1. Hierarchy depth - Maximum depth of role inheritance
--   2. Role relationships - Average number of parents/children per role
--   3. Inheritance complexity - Number of roles with multiple parents
--   4. Cycle detection frequency - Number of attempted cycle creations
--   5. Permission coverage - Percentage of permissions inherited vs direct
-- Feature References: RBAC05 (Role Hierarchy), SEC65 (Inheritance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.role_hierarchy_mappings (
    mapping_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    mapping_number VARCHAR(50) GENERATED ALWAYS AS (
        'RHM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.role_hierarchy_mapping_seq')::TEXT, 6, '0')
    ) STORED,
    parent_role_id UUID NOT NULL,
    child_role_id UUID NOT NULL,
    -- Hierarchy attributes
    depth INTEGER NOT NULL CHECK (depth >= 1),        -- Direct parent = 1
    path LTREE,                                        -- Materialized path for ancestry queries
    is_direct BOOLEAN GENERATED ALWAYS AS (depth = 1) STORED,
    -- Time bounds (optional)
    valid_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_to TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL OR valid_to > CURRENT_TIMESTAMP) STORED,
    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    -- Constraints
    CONSTRAINT fk_role_hierarchy_parent FOREIGN KEY (parent_role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE CASCADE,
    CONSTRAINT fk_role_hierarchy_child FOREIGN KEY (child_role_id)
        REFERENCES socialcandor_schema.roles(role_id) ON DELETE CASCADE,
    CONSTRAINT fk_role_hierarchy_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_role_hierarchy_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_role_hierarchy_deleted_by FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_role_hierarchy_mapping UNIQUE (parent_role_id, child_role_id, valid_from),
    CONSTRAINT chk_role_hierarchy_self CHECK (parent_role_id != child_role_id),
    CONSTRAINT chk_role_hierarchy_dates CHECK (valid_to IS NULL OR valid_to > valid_from)
);

COMMENT ON TABLE socialcandor_schema.role_hierarchy_mappings IS 'Defines parent-child relationships between roles for permission inheritance';
COMMENT ON COLUMN socialcandor_schema.role_hierarchy_mappings.depth IS 'Distance from parent to child (1 = direct)';
COMMENT ON COLUMN socialcandor_schema.role_hierarchy_mappings.path IS 'Materialized path for fast ancestry queries';

-- Indexes
CREATE INDEX idx_role_hierarchy_parent ON socialcandor_schema.role_hierarchy_mappings(parent_role_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_role_hierarchy_child ON socialcandor_schema.role_hierarchy_mappings(child_role_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_role_hierarchy_path ON socialcandor_schema.role_hierarchy_mappings USING GIST(path);
CREATE INDEX idx_role_hierarchy_dates ON socialcandor_schema.role_hierarchy_mappings(valid_from, valid_to) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_role_hierarchy_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.role_hierarchy_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- Function to prevent cycles
CREATE OR REPLACE FUNCTION socialcandor_schema.check_role_hierarchy_cycle()
RETURNS TRIGGER AS $$
BEGIN
    -- Simple check: if child is already an ancestor of parent, reject
    IF EXISTS (
        WITH RECURSIVE ancestors AS (
            SELECT parent_role_id, child_role_id
            FROM socialcandor_schema.role_hierarchy_mappings
            WHERE child_role_id = NEW.parent_role_id AND is_active = TRUE
            UNION ALL
            SELECT rh.parent_role_id, rh.child_role_id
            FROM socialcandor_schema.role_hierarchy_mappings rh
            JOIN ancestors a ON rh.child_role_id = a.parent_role_id
            WHERE rh.is_active = TRUE
        )
        SELECT 1 FROM ancestors WHERE parent_role_id = NEW.child_role_id
    ) THEN
        RAISE EXCEPTION 'Cycle detected: adding this relationship would create a cycle in role hierarchy';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_role_hierarchy_mappings_cycle_check
    BEFORE INSERT OR UPDATE ON socialcandor_schema.role_hierarchy_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.check_role_hierarchy_cycle();

-- RLS Policies
ALTER TABLE socialcandor_schema.role_hierarchy_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_hierarchy_mappings_admin_policy ON socialcandor_schema.role_hierarchy_mappings
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table 10: security_policy_definitions
-- Description: Defines security policies (password complexity, MFA enforcement, session timeouts,
--              etc.) at global, organization, or user level, with versioning and enforcement levels.
-- Business Case: Centralized policy management is essential for consistent security posture
--                across the platform. This table stores policy definitions with parameters,
--                target scope (global, org, user), and enforcement level (strict, warning, etc.).
--                It supports versioning to track changes and allows gradual rollout of new policies.
--                The design enables dynamic policy evaluation at runtime (e.g., during login,
--                password change) without code changes. Integration with audit logs ensures
--                policy changes are tracked. This is crucial for compliance (SOC2, ISO27001)
--                and for meeting varying customer security requirements.
-- KPIs:
--   1. Policy coverage - Percentage of users covered by each policy type
--   2. Policy change frequency - Number of policy updates per month
--   3. Enforcement effectiveness - Reduction in security incidents after policy enforcement
--   4. Policy violations - Number of violations per policy
--   5. Policy granularity - Distribution of policies by scope
-- Feature References: SEC55 (Security Policies), SEC66 (Policy Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.security_policy_definitions (
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    policy_number VARCHAR(50) GENERATED ALWAYS AS (
        'POL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.security_policy_seq')::TEXT, 6, '0')
    ) STORED,
    policy_name VARCHAR(255) NOT NULL,
    policy_description TEXT,
    policy_type socialcandor_schema.policy_type NOT NULL,
    policy_scope socialcandor_schema.policy_scope NOT NULL,
    scope_id UUID,                                    -- organization_id, role_id, or user_id (depending on scope)
    -- Policy parameters (JSON, flexible)
    parameters JSONB NOT NULL,                         -- e.g., {"min_length":8, "require_special":true}
    enforcement_level socialcandor_schema.enforcement_level NOT NULL DEFAULT 'STRICT',
    -- Versioning
    version INTEGER NOT NULL DEFAULT 1,
    superseded_by UUID,
    effective_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    effective_to TIMESTAMP WITH TIME ZONE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID,
    -- Constraints
    CONSTRAINT fk_security_policy_superseded_by FOREIGN KEY (superseded_by)
        REFERENCES socialcandor_schema.security_policy_definitions(policy_id) ON DELETE SET NULL,
    CONSTRAINT fk_security_policy_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_security_policy_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_security_policy_deleted_by FOREIGN KEY (deleted_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_security_policy_dates CHECK (effective_to IS NULL OR effective_to > effective_from)
);

COMMENT ON TABLE socialcandor_schema.security_policy_definitions IS 'Defines security policies (password, MFA, session, etc.) with versioning and enforcement levels';
COMMENT ON COLUMN socialcandor_schema.security_policy_definitions.parameters IS 'Policy-specific parameters as JSON (e.g., password length, MFA requirements)';
COMMENT ON COLUMN socialcandor_schema.security_policy_definitions.scope_id IS 'ID of the scope entity (organization, role, user) depending on policy_scope';

-- Indexes
CREATE INDEX idx_security_policy_type ON socialcandor_schema.security_policy_definitions(policy_type, enforcement_level, is_current) WHERE is_current = TRUE;
CREATE INDEX idx_security_policy_scope ON socialcandor_schema.security_policy_definitions(policy_scope, scope_id, is_current) WHERE scope_id IS NOT NULL;
CREATE INDEX idx_security_policy_effective ON socialcandor_schema.security_policy_definitions(effective_from, effective_to) WHERE is_current = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_security_policy_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.security_policy_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.security_policy_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_policy_admin_policy ON socialcandor_schema.security_policy_definitions
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY security_policy_read_policy ON socialcandor_schema.security_policy_definitions
    FOR SELECT USING (TRUE);


