-- =================================================================================================
-- TABLE: CMP01 - data_processing_records
-- Description: Record of Processing Activities (RoPA) as required by GDPR Article 30.
--              Documents each processing operation, its purpose, categories of data,
--              recipients, and security measures.
-- Business Case: GDPR requires all organizations to maintain a detailed record of
--                processing activities. This table serves as the central inventory,
--                enabling compliance reporting, risk assessment, and demonstrating
--                accountability to supervisory authorities. It supports data mapping,
--                impact assessments, and breach analysis by providing a complete
--                picture of data flows. The design captures all mandatory Article 30
--                elements: controller information, purposes, data categories, data
--                subjects, recipients, transfers, retention periods, and security
--                measures. Versioning allows tracking of changes over time.
--
-- Key Performance Indicators (KPIs):
--   1. Processing activity coverage - Percentage of data flows documented
--   2. Review compliance - Percentage of records reviewed within policy period
--   3. Risk assessment completion - Percentage of activities with documented risk levels
--   4. Transfer tracking - Number of international transfers documented
--   5. Data subject coverage - Count of data subject categories per activity
--
-- Feature References: GDPR07 (Processing Activities), COMP03 (Data Inventory)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_processing_records (
    -- Primary key
    record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    record_number VARCHAR(50) GENERATED ALWAYS AS (
        'DPR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.processing_record_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic information
    activity_name VARCHAR(255) NOT NULL,
    activity_description TEXT,
    processing_category socialcandor_schema.processing_category NOT NULL,
    legal_basis socialcandor_schema.legal_basis NOT NULL,
    legal_basis_details TEXT,

    -- Controller information
    controller_name VARCHAR(255) NOT NULL,
    controller_representative VARCHAR(255),
    controller_contact VARCHAR(255),

    -- Data details
    data_categories TEXT[] NOT NULL,                           -- e.g., ['name', 'email', 'location']
    data_subject_categories socialcandor_schema.data_subject_category[] NOT NULL,
    data_retention_period_days INTEGER CHECK (data_retention_period_days >= 0),
    data_volume_estimate VARCHAR(100),

    -- Processing details
    purpose TEXT NOT NULL,
    processing_location TEXT[],
    sub_processors TEXT[],
    recipients TEXT[],                                         -- Categories of recipients

    -- International transfers
    international_transfers BOOLEAN DEFAULT FALSE,
    transfer_countries VARCHAR(3)[],
    transfer_safeguards TEXT,

    -- Security measures
    security_measures TEXT,
    pseudonymization_used BOOLEAN DEFAULT FALSE,
    encryption_used BOOLEAN DEFAULT FALSE,

    -- Risk assessment
    risk_level socialcandor_schema.pia_risk_level,
    risk_assessment_date DATE,
    dpia_reference UUID,                                       -- Link to privacy_impact_assessments

    -- Review dates
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE GENERATED ALWAYS AS (
        (last_reviewed_at + INTERVAL '1 year')::DATE
    ) STORED,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    superseded_by UUID,                                        -- For versioning

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_dpr_dpia FOREIGN KEY (dpia_reference)
        REFERENCES socialcandor_schema.privacy_impact_assessments(pia_id) ON DELETE SET NULL,
    CONSTRAINT fk_dpr_superseded_by FOREIGN KEY (superseded_by)
        REFERENCES socialcandor_schema.data_processing_records(record_id) ON DELETE SET NULL,
    CONSTRAINT fk_dpr_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dpr_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_dpr_transfers CHECK (
        (international_transfers = TRUE AND transfer_countries IS NOT NULL) OR
        (international_transfers = FALSE AND transfer_countries IS NULL)
    )
);

COMMENT ON TABLE socialcandor_schema.data_processing_records IS 'Record of Processing Activities (RoPA) as required by GDPR Article 30';
COMMENT ON COLUMN socialcandor_schema.data_processing_records.data_categories IS 'Array of data categories processed (e.g., name, email, location)';
COMMENT ON COLUMN socialcandor_schema.data_subject_categories IS 'Categories of data subjects affected';
COMMENT ON COLUMN socialcandor_schema.transfer_countries IS 'ISO country codes for international transfers';
COMMENT ON COLUMN socialcandor_schema.next_review_date IS 'Derived from last_reviewed_at + 1 year';

-- Indexes
CREATE INDEX idx_dpr_category ON socialcandor_schema.data_processing_records(processing_category);
CREATE INDEX idx_dpr_legal_basis ON socialcandor_schema.data_processing_records(legal_basis);
CREATE INDEX idx_dpr_review_date ON socialcandor_schema.data_processing_records(next_review_date) WHERE is_active = TRUE;
CREATE INDEX idx_dpr_data_subjects ON socialcandor_schema.data_processing_records USING GIN (data_subject_categories);
CREATE INDEX idx_dpr_data_categories ON socialcandor_schema.data_processing_records USING GIN (data_categories);

-- Trigger
CREATE TRIGGER trg_data_processing_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_processing_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.data_processing_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY dpr_admin_policy ON socialcandor_schema.data_processing_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY dpr_read_policy ON socialcandor_schema.data_processing_records
    FOR SELECT USING (TRUE);  -- Allow read for compliance team (role-based can be added later)

-- =================================================================================================
-- TABLE: CMP02 - consent_audit_logs
-- Description: Immutable log of all consent events (grant, revoke, update, expiry)
--              for compliance with GDPR Article 7(1) (demonstrating consent).
-- Business Case: GDPR requires that controllers be able to demonstrate that consent
--                was given. This table provides an unalterable audit trail of every
--                consent action, capturing the exact timestamp, IP address, user agent,
--                and the state before/after. It supports investigations, proves
--                consent withdrawal, and helps resolve disputes. The design separates
--                the current consent (in consent_records) from historical events,
--                ensuring immutability. Partitioning by month will keep performance
--                optimal as data grows.
--
-- Key Performance Indicators (KPIs):
--   1. Consent event volume - Number of consent actions per period
--   2. Withdrawal rate - Percentage of consents revoked
--   3. Geographic distribution - Consent events by country
--   4. Policy version adoption - Distribution of consent by policy version
--   5. Audit trail completeness - Percentage of consent changes logged
--
-- Feature References: GDPR06 (Consent Management), AUD20 (Consent Audit)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.consent_audit_logs (
    -- Primary key (BIGSERIAL for partitioning)
    log_id BIGSERIAL,

    -- Human-readable identifier
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'CAL-' || TO_CHAR(event_time, 'YYYYMMDD') || '-' || LPAD(log_id::TEXT, 6, '0')
    ) STORED,

    -- References
    user_id UUID NOT NULL,
    consent_id UUID,                                           -- Link to consent_records (if applicable)

    -- Event details
    event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    consent_type socialcandor_schema.consent_type NOT NULL,
    action socialcandor_schema.consent_action NOT NULL,
    policy_version VARCHAR(50),
    purpose TEXT,

    -- State tracking
    previous_state JSONB,                                      -- Snapshot of consent before change
    new_state JSONB,                                           -- Snapshot after change

    -- Context
    ip_address INET,
    user_agent TEXT,
    device_id UUID,

    -- Source
    source VARCHAR(50) CHECK (source IN ('WEB', 'API', 'ADMIN', 'SYSTEM', 'IMPORT')),

    -- Partition key
    event_date DATE GENERATED ALWAYS AS (event_time::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_consent_audit_logs PRIMARY KEY (log_id, event_date),
    CONSTRAINT fk_consent_audit_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_consent_audit_consent FOREIGN KEY (consent_id)
        REFERENCES socialcandor_schema.consent_records(consent_id) ON DELETE SET NULL,
    CONSTRAINT fk_consent_audit_device FOREIGN KEY (device_id)
        REFERENCES socialcandor_schema.user_devices(device_id) ON DELETE SET NULL
) PARTITION BY RANGE (event_date);

COMMENT ON TABLE socialcandor_schema.consent_audit_logs IS 'Immutable audit trail of all consent events (grant, revoke, update) for GDPR compliance';
COMMENT ON COLUMN socialcandor_schema.consent_audit_logs.previous_state IS 'JSON snapshot of consent record before the action';
COMMENT ON COLUMN socialcandor_schema.consent_audit_logs.new_state IS 'JSON snapshot after the action';

-- Create monthly partitions
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'consent_audit_logs_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.consent_audit_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes
CREATE INDEX idx_consent_audit_user ON socialcandor_schema.consent_audit_logs(user_id, event_time DESC);
CREATE INDEX idx_consent_audit_consent ON socialcandor_schema.consent_audit_logs(consent_id) WHERE consent_id IS NOT NULL;
CREATE INDEX idx_consent_audit_type ON socialcandor_schema.consent_audit_logs(consent_type, action);

-- RLS
ALTER TABLE socialcandor_schema.consent_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY consent_audit_self_policy ON socialcandor_schema.consent_audit_logs
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY consent_audit_admin_policy ON socialcandor_schema.consent_audit_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: CMP03 - privacy_request_workflows
-- Description: Tracks the end-to-end workflow of Data Subject Access Requests (DSAR),
--              including verification, scoping, data collection, review, and fulfillment.
-- Business Case: GDPR requires timely responses to DSARs (usually within one month).
--                This table provides a structured workflow to manage each request
--                from receipt to completion, with clear statuses, assignments, and
--                deadlines. It supports workload management, SLA tracking, and audit
--                of the handling process. Integration with data_subject_requests
--                (the original request) and user_anonymization_queue (for erasure)
--                ensures end-to-end traceability. The design includes escalation paths
--                for complex requests and notes for internal collaboration.
--
-- Key Performance Indicators (KPIs):
--   1. Average fulfillment time - Days from submission to completion
--   2. SLA compliance rate - Percentage completed within legal deadline
--   3. Backlog - Number of open requests by age
--   4. Escalation rate - Percentage requiring escalation
--   5. Request complexity - Distribution by request type and category
--
-- Feature References: GDPR01 (Data Subject Rights), WF06 (DSAR Workflow)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.privacy_request_workflows (
    -- Primary key
    workflow_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    workflow_number VARCHAR(50) GENERATED ALWAYS AS (
        'DSARW-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.privacy_request_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    request_id UUID NOT NULL UNIQUE,                           -- Link to data_subject_requests
    assigned_to UUID,                                          -- Privacy team member
    reviewed_by UUID,

    -- Workflow status
    status socialcandor_schema.dsar_workflow_status NOT NULL DEFAULT 'RECEIVED',
    previous_status socialcandor_schema.dsar_workflow_status,

    -- Dates
    received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    verified_at TIMESTAMP WITH TIME ZONE,
    scoping_completed_at TIMESTAMP WITH TIME ZONE,
    data_collection_completed_at TIMESTAMP WITH TIME ZONE,
    review_completed_at TIMESTAMP WITH TIME ZONE,
    fulfilled_at TIMESTAMP WITH TIME ZONE,
    deadline DATE NOT NULL,                                     -- Legal deadline (usually 30 days)
    extended_deadline DATE,                                     -- If extension used

    -- Escalation
    escalated BOOLEAN DEFAULT FALSE,
    escalated_at TIMESTAMP WITH TIME ZONE,
    escalated_to UUID,
    escalation_reason TEXT,

    -- Complexity scoring
    complexity_score INTEGER CHECK (complexity_score >= 1 AND complexity_score <= 10),
    data_volume_estimate VARCHAR(100),                          -- e.g., '100MB'
    affected_systems TEXT[],

    -- Verification details
    verification_method socialcandor_schema.verification_method,
    verification_notes TEXT,

    -- Fulfillment details
    fulfillment_method VARCHAR(50) CHECK (fulfillment_method IN ('DOWNLOAD', 'EMAIL', 'PORTAL', 'PHYSICAL_COPY')),
    data_package_url VARCHAR(500),
    delivery_confirmed BOOLEAN DEFAULT FALSE,
    delivery_confirmed_at TIMESTAMP WITH TIME ZONE,

    -- Rejection reason (if applicable)
    rejection_reason TEXT,
    rejection_notified_at TIMESTAMP WITH TIME ZONE,

    -- Internal notes
    internal_notes TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_privreq_workflow_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE CASCADE,
    CONSTRAINT fk_privreq_workflow_assigned FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_privreq_workflow_reviewed FOREIGN KEY (reviewed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_privreq_workflow_escalated_to FOREIGN KEY (escalated_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_privreq_workflow_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_privreq_workflow_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_privreq_workflow_dates CHECK (
        (extended_deadline IS NULL) OR (extended_deadline > deadline)
    ),
    CONSTRAINT chk_privreq_workflow_fulfillment CHECK (
        (fulfilled_at IS NULL AND status != 'COMPLETED') OR
        (fulfilled_at IS NOT NULL AND status = 'COMPLETED')
    )
);

COMMENT ON TABLE socialcandor_schema.privacy_request_workflows IS 'End-to-end workflow tracking for Data Subject Access Requests';
COMMENT ON COLUMN socialcandor_schema.privacy_request_workflows.complexity_score IS 'Subjective score (1-10) indicating request complexity';
COMMENT ON COLUMN socialcandor_schema.privacy_request_workflows.affected_systems IS 'Systems that needed to be searched for data';
COMMENT ON COLUMN socialcandor_schema.privacy_request_workflows.data_package_url IS 'URL to the packaged data for access requests';

-- Indexes
CREATE INDEX idx_privreq_workflow_status ON socialcandor_schema.privacy_request_workflows(status, deadline);
CREATE INDEX idx_privreq_workflow_assigned ON socialcandor_schema.privacy_request_workflows(assigned_to) WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_privreq_workflow_escalated ON socialcandor_schema.privacy_request_workflows(escalated, escalated_at) WHERE escalated = TRUE;

-- Trigger
CREATE TRIGGER trg_privacy_request_workflows_updated_at
    BEFORE UPDATE ON socialcandor_schema.privacy_request_workflows
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.privacy_request_workflows ENABLE ROW LEVEL SECURITY;
CREATE POLICY privreq_workflow_staff_policy ON socialcandor_schema.privacy_request_workflows
    FOR ALL USING (
        assigned_to = current_setting('app.current_user_id')::UUID OR
        EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE)
    );
CREATE POLICY privreq_workflow_self_policy ON socialcandor_schema.privacy_request_workflows
    FOR SELECT USING (request_id IN (SELECT request_id FROM socialcandor_schema.data_subject_requests WHERE user_id = current_setting('app.current_user_id')::UUID));

-- =================================================================================================
-- TABLE: CMP04 - data_retention_schedules
-- Description: Defines automated retention rules for data categories, specifying
--              retention periods and actions upon expiry. Supports GDPR Article 5(1)(e).
-- Business Case: Storage limitation requires that personal data be kept no longer
--                than necessary. This table implements that principle by defining
--                rules for each data category, table, or column. The rules are used
--                by automated jobs to delete, anonymize, or archive data when it
--                reaches the end of its life. The design supports multiple retention
--                triggers (creation date, last activity, event date) and exception
--                handling (e.g., legal holds). This ensures consistent enforcement
--                across the platform and reduces manual effort.
--
-- Key Performance Indicators (KPIs):
--   1. Rule coverage - Percentage of data covered by retention schedules
--   2. Enforcement success - Percentage of rules successfully applied
--   3. Data reduction - Volume of data deleted/archived per period
--   4. Exception rate - Number of legal holds or overrides
--   5. Compliance rate - Percentage of data meeting retention targets
--
-- Feature References: GDPR05 (Data Retention), RET01 (Retention Rules)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_retention_schedules (
    -- Primary key
    schedule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    schedule_number VARCHAR(50) GENERATED ALWAYS AS (
        'DRS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.retention_schedule_seq')::TEXT, 6, '0')
    ) STORED,

    -- Rule identification
    rule_name VARCHAR(255) NOT NULL,
    rule_description TEXT,
    rule_version VARCHAR(20) DEFAULT '1.0',

    -- Scope
    scope_type VARCHAR(50) CHECK (scope_type IN ('DATA_CATEGORY', 'TABLE', 'COLUMN', 'PROCESS', 'JURISDICTION')),
    scope_value VARCHAR(255) NOT NULL,                          -- e.g., 'USER_ACTIVITY_LOGS', 'PII', 'EU_USERS'

    -- Retention period
    retention_period_days INTEGER NOT NULL CHECK (retention_period_days >= 0),
    retention_basis VARCHAR(50) CHECK (retention_basis IN (
        'CREATION_DATE', 'LAST_ACTIVITY', 'EVENT_DATE', 'CONTRACT_END'
    )),

    -- Action on expiry
    action_on_expiry socialcandor_schema.retention_action NOT NULL,
    archive_location VARCHAR(500),                              -- For ARCHIVE action
    anonymization_technique socialcandor_schema.anonymization_technique,

    -- Exceptions
    allows_legal_hold BOOLEAN DEFAULT TRUE,
    requires_approval_for_override BOOLEAN DEFAULT FALSE,

    -- Effective dating
    effective_from DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL OR effective_to >= CURRENT_DATE) STORED,

    -- Review
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE GENERATED ALWAYS AS (
        (last_reviewed_at + INTERVAL '1 year')::DATE
    ) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_retention_schedule_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_retention_schedule_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_retention_schedule_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT uk_retention_schedule UNIQUE (scope_type, scope_value, effective_from)
);

COMMENT ON TABLE socialcandor_schema.data_retention_schedules IS 'Automated retention rules for data categories, specifying periods and expiry actions';
COMMENT ON COLUMN socialcandor_schema.data_retention_schedules.retention_basis IS 'What date triggers the retention period (creation, last activity, etc.)';
COMMENT ON COLUMN socialcandor_schema.data_retention_schedules.anonymization_technique IS 'Technique to use if action is ANONYMIZE';

-- Indexes
CREATE INDEX idx_retention_schedule_active ON socialcandor_schema.data_retention_schedules(is_active) WHERE is_active = TRUE;
CREATE INDEX idx_retention_schedule_scope ON socialcandor_schema.data_retention_schedules(scope_type, scope_value);
CREATE INDEX idx_retention_schedule_review ON socialcandor_schema.data_retention_schedules(next_review_date) WHERE is_active = TRUE;

-- Trigger
CREATE TRIGGER trg_data_retention_schedules_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_retention_schedules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.data_retention_schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY retention_schedule_admin_policy ON socialcandor_schema.data_retention_schedules
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY retention_schedule_read_policy ON socialcandor_schema.data_retention_schedules
    FOR SELECT USING (TRUE);

-- =================================================================================================
-- TABLE: CMP05 - breach_notification_logs
-- Description: Logs all notifications sent regarding a data breach, including
--              supervisory authorities, affected individuals, and other stakeholders.
-- Business Case: GDPR Article 33 and 34 require notification of data breaches to
--                supervisory authorities (within 72 hours) and affected individuals
--                (when high risk). This table provides a complete record of all
--                notifications sent, their content, delivery status, and timing.
--                It demonstrates compliance with notification obligations and
--                supports coordination with multiple authorities (if cross-border).
--                The design supports different recipient types and tracks delivery
--                confirmations, which is critical for regulatory audits.
--
-- Key Performance Indicators (KPIs):
--   1. Notification timeliness - Percentage sent within legal deadline
--   2. Authority coverage - All required authorities notified
--   3. Delivery success rate - Percentage successfully delivered
--   4. Response tracking - Follow-up communications
--   5. Notification completeness - All required information included
--
-- Feature References: GDPR02 (Breach Management), NOTIFY06 (Breach Notifications)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.breach_notification_logs (
    -- Primary key
    notification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    notification_number VARCHAR(50) GENERATED ALWAYS AS (
        'BNL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.breach_notification_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    breach_id UUID NOT NULL,                                   -- Link to data_breaches

    -- Recipient details
    recipient_type socialcandor_schema.notification_recipient_type NOT NULL,
    recipient_name VARCHAR(255),
    recipient_contact VARCHAR(255),                            -- Email, address, phone
    recipient_jurisdiction VARCHAR(3),                         -- For authorities

    -- Notification details
    notification_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    notification_method socialcandor_schema.notification_method NOT NULL,
    notification_content TEXT,
    attachment_urls TEXT[],

    -- Delivery tracking
    delivery_status socialcandor_schema.notification_status DEFAULT 'NOT_STARTED',
    delivered_at TIMESTAMP WITH TIME ZONE,
    delivery_attempts INTEGER DEFAULT 0,
    delivery_error TEXT,

    -- Response tracking
    response_received BOOLEAN DEFAULT FALSE,
    response_date TIMESTAMP WITH TIME ZONE,
    response_notes TEXT,

    -- Follow-up
    follow_up_required BOOLEAN DEFAULT FALSE,
    follow_up_date DATE,
    follow_up_notes TEXT,

    -- Compliance
    deadline_met BOOLEAN,                                      -- Whether sent within 72h
    deadline_date TIMESTAMP WITH TIME ZONE,                     -- When it should have been sent

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_breach_notification_breach FOREIGN KEY (breach_id)
        REFERENCES socialcandor_schema.data_breaches(breach_id) ON DELETE CASCADE,
    CONSTRAINT fk_breach_notification_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_breach_notification_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_breach_notification_dates CHECK (
        (delivered_at IS NULL) OR (delivered_at >= notification_date)
    )
);

COMMENT ON TABLE socialcandor_schema.breach_notification_logs IS 'Logs all notifications sent regarding data breaches to authorities and affected individuals';
COMMENT ON COLUMN socialcandor_schema.breach_notification_logs.deadline_met IS 'Whether notification was sent within regulatory deadline (72h)';
COMMENT ON COLUMN socialcandor_schema.breach_notification_logs.deadline_date IS 'Deadline by which notification should have been sent';

-- Indexes
CREATE INDEX idx_breach_notification_breach ON socialcandor_schema.breach_notification_logs(breach_id, notification_date DESC);
CREATE INDEX idx_breach_notification_recipient ON socialcandor_schema.breach_notification_logs(recipient_type, recipient_jurisdiction);
CREATE INDEX idx_breach_notification_status ON socialcandor_schema.breach_notification_logs(delivery_status) WHERE delivery_status NOT IN ('DELIVERED', 'NOT_REQUIRED');

-- Trigger
CREATE TRIGGER trg_breach_notification_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.breach_notification_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.breach_notification_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY breach_notification_admin_policy ON socialcandor_schema.breach_notification_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: CMP06 - privacy_impact_assessments (DPIA)
-- Description: Tracks Privacy Impact Assessments (DPIA) for high-risk processing activities
--              as required by GDPR Article 35.
-- Business Case: GDPR requires a DPIA for processing likely to result in high risk
--                to individuals' rights. This table documents each assessment,
--                including the processing activity, identified risks, mitigations,
--                and the DPO's opinion. It supports the accountability principle
--                and provides evidence to supervisory authorities. The design
--                captures the full lifecycle: screening, assessment, consultation,
--                approval, and review. Integration with processing records and
--                vendor assessments provides a comprehensive view of risk.
--
-- Key Performance Indicators (KPIs):
--   1. DPIA completion rate - Percentage of required assessments completed
--   2. Risk identification - Number of risks identified per assessment
--   3. Mitigation effectiveness - Residual risk levels after mitigation
--   4. Review compliance - Percentage reviewed within required period
--   5. Consultation rate - Percentage involving DPO or authority consultation
--
-- Feature References: GDPR03 (Privacy Impact Assessment), RISK03 (Risk Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.privacy_impact_assessments (
    -- Primary key
    pia_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    pia_number VARCHAR(50) GENERATED ALWAYS AS (
        'PIA-' || TO_CHAR(initiated_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.pia_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic information
    assessment_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Processing activity
    processing_record_id UUID,                                 -- Link to data_processing_records
    processing_description TEXT,
    legal_basis socialcandor_schema.legal_basis,

    -- Data involved
    data_categories TEXT[],
    data_subject_categories socialcandor_schema.data_subject_category[],
    data_volume_estimate VARCHAR(100),
    data_sources TEXT[],

    -- Risk assessment
    inherent_risk_level socialcandor_schema.pia_risk_level,
    identified_risks JSONB,                                    -- Array of risk objects
    risk_factors JSONB,

    -- Mitigations
    mitigation_measures TEXT,
    residual_risk_level socialcandor_schema.pia_risk_level,
    safeguards_implemented TEXT,

    -- Consultation
    dpo_consulted BOOLEAN DEFAULT FALSE,
    dpo_opinion TEXT,
    dpo_consultation_date DATE,
    authority_consulted BOOLEAN DEFAULT FALSE,
    authority_consultation_date DATE,
    authority_response TEXT,

    -- Status and dates
    status VARCHAR(30) DEFAULT 'DRAFT' CHECK (status IN (
        'DRAFT', 'SCREENING', 'IN_PROGRESS', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'OBSOLETE'
    )),
    initiated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    submitted_at TIMESTAMP WITH TIME ZONE,
    approved_at TIMESTAMP WITH TIME ZONE,
    review_date DATE,                                          -- Next scheduled review
    expiry_date DATE,

    -- Approvers
    assessed_by UUID NOT NULL,
    approved_by UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_pia_processing_record FOREIGN KEY (processing_record_id)
        REFERENCES socialcandor_schema.data_processing_records(record_id) ON DELETE SET NULL,
    CONSTRAINT fk_pia_assessed_by FOREIGN KEY (assessed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_pia_approved_by FOREIGN KEY (approved_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_pia_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_pia_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_pia_dates CHECK (expiry_date IS NULL OR expiry_date >= approved_at::DATE)
);

COMMENT ON TABLE socialcandor_schema.privacy_impact_assessments IS 'Privacy Impact Assessments (DPIA) for high-risk processing activities under GDPR Article 35';
COMMENT ON COLUMN socialcandor_schema.privacy_impact_assessments.identified_risks IS 'JSON array of identified risks with descriptions and likelihood';
COMMENT ON COLUMN socialcandor_schema.privacy_impact_assessments.risk_factors IS 'JSON of risk factors considered (e.g., novelty, scale, sensitivity)';
COMMENT ON COLUMN socialcandor_schema.privacy_impact_assessments.residual_risk_level IS 'Risk level after applying mitigations';

-- Indexes
CREATE INDEX idx_pia_processing ON socialcandor_schema.privacy_impact_assessments(processing_record_id) WHERE processing_record_id IS NOT NULL;
CREATE INDEX idx_pia_status ON socialcandor_schema.privacy_impact_assessments(status, review_date);
CREATE INDEX idx_pia_dates ON socialcandor_schema.privacy_impact_assessments(initiated_at, approved_at);
CREATE INDEX idx_pia_data_subjects ON socialcandor_schema.privacy_impact_assessments USING GIN (data_subject_categories);

-- Trigger
CREATE TRIGGER trg_privacy_impact_assessments_updated_at
    BEFORE UPDATE ON socialcandor_schema.privacy_impact_assessments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.privacy_impact_assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY pia_admin_policy ON socialcandor_schema.privacy_impact_assessments
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY pia_read_policy ON socialcandor_schema.privacy_impact_assessments
    FOR SELECT USING (TRUE);  -- Read-only for compliance team

-- =================================================================================================
-- TABLE: CMP07 - vendor_dpa_records
-- Description: Manages Data Processing Agreements (DPAs) with third-party vendors,
--              including signing, renewals, and termination. Supports GDPR Article 28.
-- Business Case: GDPR requires written agreements with all processors. This table
--                serves as a central repository for all DPAs, tracking their status,
--                key dates, and document locations. It enables proactive management
--                of renewals, ensures that all vendors are compliant, and provides
--                audit evidence. The design captures both standard clauses (SCCs)
--                and custom agreements, and links to vendor assessments for risk
--                management. Integration with vendor risk processes ensures that
--                only compliant vendors are engaged.
--
-- Key Performance Indicators (KPIs):
--   1. DPA coverage - Percentage of vendors with signed DPAs
--   2. Renewal compliance - Percentage renewed before expiry
--   3. Document completeness - Percentage with fully executed copies
--   4. Vendor risk correlation - Risk scores of vendors with DPAs
--   5. Time to sign - Average days from request to execution
--
-- Feature References: GDPR04 (Data Processing Agreements), VND02 (Vendor DPAs)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.vendor_dpa_records (
    -- Primary key
    dpa_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    dpa_number VARCHAR(50) GENERATED ALWAYS AS (
        'DPA-' || TO_CHAR(signed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dpa_seq')::TEXT, 6, '0')
    ) STORED,

    -- Vendor information
    vendor_name VARCHAR(255) NOT NULL,
    vendor_id UUID,                                           -- Link to vendor_assessments or organizations
    vendor_contact_name VARCHAR(255),
    vendor_contact_email VARCHAR(255),

    -- Agreement details
    agreement_type VARCHAR(50) CHECK (agreement_type IN ('STANDARD_SCC', 'CUSTOM', 'BCR', 'ADEQUACY')),
    agreement_version VARCHAR(50),
    description TEXT,

    -- Dates
    requested_at TIMESTAMP WITH TIME ZONE,
    sent_at TIMESTAMP WITH TIME ZONE,
    signed_at TIMESTAMP WITH TIME ZONE,
    effective_date DATE NOT NULL,
    expiration_date DATE,
    renewal_date DATE GENERATED ALWAYS AS (
        (expiration_date - INTERVAL '60 days')::DATE
    ) STORED,

    -- Documents
    agreement_document_url VARCHAR(500),
    signed_copy_url VARCHAR(500),
    supporting_docs TEXT[],

    -- Processing details
    processing_description TEXT,
    data_categories TEXT[],
    data_subject_categories socialcandor_schema.data_subject_category[],
    transfer_countries VARCHAR(3)[],

    -- Status
    status socialcandor_schema.dpa_status NOT NULL DEFAULT 'DRAFT',
    notes TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_vendor_dpa_vendor FOREIGN KEY (vendor_id)
        REFERENCES socialcandor_schema.vendor_assessments(assessment_id) ON DELETE SET NULL,
    CONSTRAINT fk_vendor_dpa_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_vendor_dpa_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_vendor_dpa_dates CHECK (expiration_date IS NULL OR expiration_date >= effective_date),
    CONSTRAINT chk_vendor_dpa_signing CHECK (
        (signed_at IS NULL AND status != 'SIGNED') OR
        (signed_at IS NOT NULL AND signed_at >= requested_at)
    )
);

COMMENT ON TABLE socialcandor_schema.vendor_dpa_records IS 'Manages Data Processing Agreements with third-party vendors under GDPR Article 28';
COMMENT ON COLUMN socialcandor_schema.vendor_dpa_records.renewal_date IS '60 days before expiration, for proactive renewal';
COMMENT ON COLUMN socialcandor_schema.vendor_dpa_records.agreement_type IS 'Type of agreement (standard clauses, custom, BCR, adequacy decision)';

-- Indexes
CREATE INDEX idx_vendor_dpa_vendor ON socialcandor_schema.vendor_dpa_records(vendor_name, status);
CREATE INDEX idx_vendor_dpa_dates ON socialcandor_schema.vendor_dpa_records(effective_date, expiration_date);
CREATE INDEX idx_vendor_dpa_renewal ON socialcandor_schema.vendor_dpa_records(renewal_date) WHERE status = 'ACTIVE';

-- Trigger
CREATE TRIGGER trg_vendor_dpa_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.vendor_dpa_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.vendor_dpa_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY vendor_dpa_admin_policy ON socialcandor_schema.vendor_dpa_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: CMP08 - cross_border_transfers
-- Description: Tracks international data transfers, including legal basis, safeguards,
--              and impact assessments. Supports GDPR Chapter V compliance.
-- Business Case: GDPR restricts transfers of personal data outside the EEA unless
--                adequate safeguards are in place. This table documents each transfer,
--                identifying the recipient country, legal mechanism (SCCs, BCR, adequacy),
--                and any supplementary measures. It supports transfer impact assessments
--                (required after Schrems II) and provides evidence for regulatory
--                audits. The design links to processing records, vendor agreements,
--                and risk assessments, giving a complete picture of transfer activity.
--
-- Key Performance Indicators (KPIs):
--   1. Transfer volume - Number of active transfers by country
--   2. Mechanism distribution - Usage of SCCs, BCRs, adequacy decisions
--   3. TIA completion - Percentage of transfers with completed impact assessments
--   4. Risk level - Distribution of transfer risks
--   5. Review compliance - Percentage reviewed within required period
--
-- Feature References: GDPR05 (International Transfers), RISK04 (Transfer Risk)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.cross_border_transfers (
    -- Primary key
    transfer_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    transfer_number VARCHAR(50) GENERATED ALWAYS AS (
        'XFR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.transfer_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    processing_record_id UUID,                                 -- Link to data_processing_records
    dpa_id UUID,                                               -- Link to vendor_dpa_records

    -- Transfer details
    transfer_name VARCHAR(255) NOT NULL,
    description TEXT,
    transfer_type VARCHAR(50) CHECK (transfer_type IN ('CONTROLLER_TO_PROCESSOR', 'PROCESSOR_TO_SUBPROCESSOR', 'CONTROLLER_TO_CONTROLLER')),

    -- Source and destination
    source_countries VARCHAR(3)[] NOT NULL,
    destination_countries VARCHAR(3)[] NOT NULL,
    destination_entity VARCHAR(255) NOT NULL,                  -- Company/organization name

    -- Legal basis and safeguards
    legal_basis socialcandor_schema.legal_basis,
    transfer_mechanism socialcandor_schema.transfer_mechanism NOT NULL,
    safeguards_description TEXT,
    supplementary_measures TEXT,

    -- Impact assessment
    tia_completed BOOLEAN DEFAULT FALSE,
    tia_date DATE,
    tia_conclusion TEXT,
    risk_level socialcandor_schema.risk_level,

    -- Dates
    start_date DATE NOT NULL,
    end_date DATE,
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE GENERATED ALWAYS AS (
        (last_reviewed_at + INTERVAL '1 year')::DATE
    ) STORED,

    -- Status
    status socialcandor_schema.transfer_status NOT NULL DEFAULT 'ACTIVE',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_cross_border_transfer_processing FOREIGN KEY (processing_record_id)
        REFERENCES socialcandor_schema.data_processing_records(record_id) ON DELETE SET NULL,
    CONSTRAINT fk_cross_border_transfer_dpa FOREIGN KEY (dpa_id)
        REFERENCES socialcandor_schema.vendor_dpa_records(dpa_id) ON DELETE SET NULL,
    CONSTRAINT fk_cross_border_transfer_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_cross_border_transfer_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_cross_border_transfer_dates CHECK (end_date IS NULL OR end_date >= start_date)
);

COMMENT ON TABLE socialcandor_schema.cross_border_transfers IS 'Tracks international data transfers and their legal basis under GDPR Chapter V';
COMMENT ON COLUMN socialcandor_schema.cross_border_transfers.tia_completed IS 'Whether a Transfer Impact Assessment has been completed';
COMMENT ON COLUMN socialcandor_schema.cross_border_transfers.supplementary_measures IS 'Additional measures to ensure adequate protection';

-- Indexes
CREATE INDEX idx_cross_border_transfer_dest ON socialcandor_schema.cross_border_transfers USING GIN (destination_countries);
CREATE INDEX idx_cross_border_transfer_mechanism ON socialcandor_schema.cross_border_transfers(transfer_mechanism, status);
CREATE INDEX idx_cross_border_transfer_review ON socialcandor_schema.cross_border_transfers(next_review_date) WHERE status = 'ACTIVE';

-- Trigger
CREATE TRIGGER trg_cross_border_transfers_updated_at
    BEFORE UPDATE ON socialcandor_schema.cross_border_transfers
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.cross_border_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY cross_border_transfer_admin_policy ON socialcandor_schema.cross_border_transfers
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: CMP09 - data_subject_verification
-- Description: Records identity verification attempts and outcomes for DSARs,
--              supporting GDPR Article 12(6) (reasonable measures to verify identity).
-- Business Case: Before fulfilling a DSAR, controllers must verify the identity of
--                the requester to prevent unauthorized disclosure. This table logs
--                all verification attempts, including method used, success/failure,
--                and evidence. It helps demonstrate that reasonable steps were taken,
--                and supports handling of failed verifications (e.g., requesting more
--                information). The design supports multiple verification methods and
--                tracks the number of attempts to prevent abuse.
--
-- Key Performance Indicators (KPIs):
--   1. Verification success rate - Percentage of successful verifications
--   2. Attempt distribution - Number of attempts per request
--   3. Method effectiveness - Success rates by verification method
--   4. Time to verify - Average time from request to verification
--   5. Failure reasons - Distribution of failure causes
--
-- Feature References: GDPR01 (Data Subject Rights), IDV01 (Identity Verification)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_subject_verification (
    -- Primary key
    verification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    verification_number VARCHAR(50) GENERATED ALWAYS AS (
        'VER-' || TO_CHAR(attempted_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.verification_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    request_id UUID NOT NULL,                                  -- Link to data_subject_requests
    user_id UUID,                                              -- User being verified (if known)

    -- Verification attempt
    attempted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    verification_method socialcandor_schema.verification_method NOT NULL,
    successful BOOLEAN NOT NULL,

    -- Evidence
    evidence_provided TEXT[],
    evidence_notes TEXT,

    -- Contact details used
    email_used VARCHAR(255),
    phone_used VARCHAR(50),
    id_document_hash VARCHAR(255),                             -- Hash of ID document (not the document itself)

    -- Failure tracking
    failure_reason TEXT,
    follow_up_required BOOLEAN DEFAULT FALSE,
    follow_up_notes TEXT,

    -- Attempt count (for rate limiting)
    attempt_number INTEGER DEFAULT 1 CHECK (attempt_number > 0),

    -- Metadata
    ip_address INET,
    user_agent TEXT,
    metadata JSONB DEFAULT '{}',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_subject_verification_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_subject_verification_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_subject_verification_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_subject_verification_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.data_subject_verification IS 'Records identity verification attempts and outcomes for DSARs';
COMMENT ON COLUMN socialcandor_schema.data_subject_verification.evidence_provided IS 'Array of evidence types provided (e.g., email confirmation, ID upload)';
COMMENT ON COLUMN socialcandor_schema.data_subject_verification.id_document_hash IS 'Hash of ID document for verification without storing the document';

-- Indexes
CREATE INDEX idx_data_subject_verification_request ON socialcandor_schema.data_subject_verification(request_id, attempted_at DESC);
CREATE INDEX idx_data_subject_verification_user ON socialcandor_schema.data_subject_verification(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_data_subject_verification_success ON socialcandor_schema.data_subject_verification(successful, attempt_number);

-- Trigger
CREATE TRIGGER trg_data_subject_verification_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_subject_verification
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.data_subject_verification ENABLE ROW LEVEL SECURITY;
CREATE POLICY data_subject_verification_staff_policy ON socialcandor_schema.data_subject_verification
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND (is_admin = TRUE OR role IN ('PRIVACY_TEAM', 'SUPPORT'))));
CREATE POLICY data_subject_verification_self_policy ON socialcandor_schema.data_subject_verification
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

-- =================================================================================================
-- TABLE: CMP10 - anonymization_job_logs
-- Description: Detailed execution logs for anonymization jobs, tracking progress,
--              records processed, and any errors. Supports audit and troubleshooting.
-- Business Case: Anonymization is a critical privacy operation, especially for
--                erasure requests and data minimization. This table provides a
--                complete audit trail of every anonymization job: which data was
--                targeted, which technique was used, how many records were affected,
--                and whether it succeeded. It enables verification that erasure
--                requests were fully processed, supports root cause analysis of
--                failures, and demonstrates compliance to regulators. The design
--                links to the original request (if any) and captures enough detail
--                to reconstruct the operation.
--
-- Key Performance Indicators (KPIs):
--   1. Job success rate - Percentage of jobs completed successfully
--   2. Records processed - Volume of data anonymized per period
--   3. Job duration - Average time to complete
--   4. Error rate - Percentage of jobs with errors
--   5. Retry frequency - Number of retries required
--
-- Feature References: PRV05 (Anonymization), GDPR10 (Right to Erasure)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.anonymization_job_logs (
    -- Primary key
    log_id BIGSERIAL PRIMARY KEY,

    -- Human-readable identifier
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'ANJ-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(log_id::TEXT, 6, '0')
    ) STORED,

    -- References
    job_id UUID,                                               -- Link to background_jobs or user_anonymization_queue
    request_id UUID,                                           -- Link to data_subject_requests (if applicable)

    -- Job metadata
    job_name VARCHAR(255) NOT NULL,
    job_description TEXT,
    anonymization_technique socialcandor_schema.anonymization_technique NOT NULL,

    -- Target data
    target_schema VARCHAR(100),
    target_table VARCHAR(100),
    target_columns TEXT[],
    filter_condition TEXT,

    -- Execution details
    started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    completed_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(30) CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'PARTIAL', 'FAILED', 'CANCELLED')),

    -- Statistics
    rows_processed INTEGER DEFAULT 0 CHECK (rows_processed >= 0),
    rows_affected INTEGER DEFAULT 0 CHECK (rows_affected >= 0),
    rows_failed INTEGER DEFAULT 0 CHECK (rows_failed >= 0),
    bytes_processed BIGINT,

    -- Performance
    execution_duration_ms INTEGER CHECK (execution_duration_ms >= 0),

    -- Error handling
    retry_count INTEGER DEFAULT 0,
    last_error TEXT,
    error_details JSONB,

    -- Output
    output_summary JSONB,
    output_location VARCHAR(500),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_anon_job_logs_job FOREIGN KEY (job_id)
        REFERENCES socialcandor_schema.background_jobs(job_id) ON DELETE SET NULL,
    CONSTRAINT fk_anon_job_logs_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
    CONSTRAINT fk_anon_job_logs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_anon_job_logs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_anon_job_logs_timing CHECK (completed_at IS NULL OR completed_at >= started_at)
);

COMMENT ON TABLE socialcandor_schema.anonymization_job_logs IS 'Detailed execution logs for anonymization jobs, supporting audit and troubleshooting';
COMMENT ON COLUMN socialcandor_schema.anonymization_job_logs.rows_processed IS 'Number of rows examined';
COMMENT ON COLUMN socialcandor_schema.anonymization_job_logs.rows_affected IS 'Number of rows actually modified';
COMMENT ON COLUMN socialcandor_schema.anonymization_job_logs.output_summary IS 'JSON summary of job results (e.g., counts per table)';

-- Indexes
CREATE INDEX idx_anon_job_logs_status ON socialcandor_schema.anonymization_job_logs(status, started_at DESC);
CREATE INDEX idx_anon_job_logs_request ON socialcandor_schema.anonymization_job_logs(request_id) WHERE request_id IS NOT NULL;
CREATE INDEX idx_anon_job_logs_job ON socialcandor_schema.anonymization_job_logs(job_id) WHERE job_id IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_anonymization_job_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.anonymization_job_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.anonymization_job_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY anon_job_logs_admin_policy ON socialcandor_schema.anonymization_job_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: CMP11 - pseudonymization_keys
-- Description: Manages keys used for pseudonymization, including key material,
--              rotation schedule, and access logging. Enables secure pseudonymization.
-- Business Case: Pseudonymization is a recommended safeguard under GDPR. This table
--                securely stores and manages the keys used to pseudonymize personal
--                data. Key material is stored encrypted (wrapped) and never in
--                plaintext. The design supports key rotation, versioning, and access
--                logging to ensure that re-identification is only possible when
--                necessary and authorized. Integration with data_encryption_config
--                links keys to the data they protect. This is critical for both
--                security and compliance, as loss of keys could result in irreversible
--                data loss or unauthorized re-identification.
--
-- Key Performance Indicators (KPIs):
--   1. Key inventory - Number of active pseudonymization keys
--   2. Rotation compliance - Percentage of keys rotated within policy
--   3. Key age - Distribution of key ages
--   4. Access attempts - Number of key access events (successful/failed)
--   5. Key lifecycle - Creation, rotation, retirement rates
--
-- Feature References: PRV05 (Pseudonymization), ENC02 (Key Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.pseudonymization_keys (
    -- Primary key
    key_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    key_number VARCHAR(50) GENERATED ALWAYS AS (
        'PSKEY-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.pseudonymization_key_seq')::TEXT, 6, '0')
    ) STORED,

    -- Key identification
    key_name VARCHAR(255) NOT NULL,
    key_version INTEGER NOT NULL DEFAULT 1,
    key_algorithm socialcandor_schema.key_algorithm NOT NULL,

    -- Key material (wrapped with master key)
    wrapped_key BYTEA NOT NULL,
    key_checksum VARCHAR(64),                                  -- For integrity verification

    -- Usage context
    purpose VARCHAR(255),                                       -- What this key is used for
    data_classification socialcandor_schema.data_classification,

    -- Lifecycle
    key_status socialcandor_schema.key_status NOT NULL DEFAULT 'ACTIVE',
    activated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Rotation
    predecessor_key_id UUID,                                   -- Previous version
    successor_key_id UUID,                                     -- Next version
    rotation_schedule_days INTEGER CHECK (rotation_schedule_days >= 0),

    -- Access logging
    access_count INTEGER DEFAULT 0,
    last_accessed_at TIMESTAMP WITH TIME ZONE,
    allowed_roles TEXT[],                                      -- Roles permitted to use this key

    -- Owner
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_pseudonymization_keys_predecessor FOREIGN KEY (predecessor_key_id)
        REFERENCES socialcandor_schema.pseudonymization_keys(key_id) ON DELETE SET NULL,
    CONSTRAINT fk_pseudonymization_keys_successor FOREIGN KEY (successor_key_id)
        REFERENCES socialcandor_schema.pseudonymization_keys(key_id) ON DELETE SET NULL,
    CONSTRAINT fk_pseudonymization_keys_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_pseudonymization_keys_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_pseudonymization_keys_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_pseudonymization_keys_dates CHECK (
        deactivated_at IS NULL OR deactivated_at >= activated_at
    ),
    CONSTRAINT uk_pseudonymization_keys_name_version UNIQUE (key_name, key_version)
);

COMMENT ON TABLE socialcandor_schema.pseudonymization_keys IS 'Manages keys used for pseudonymization, with encryption and lifecycle tracking';
COMMENT ON COLUMN socialcandor_schema.pseudonymization_keys.wrapped_key IS 'Key material encrypted with a master key (never stored plaintext)';
COMMENT ON COLUMN socialcandor_schema.pseudonymization_keys.allowed_roles IS 'Roles authorized to use this key for re-identification';
COMMENT ON COLUMN socialcandor_schema.pseudonymization_keys.access_count IS 'Number of times key has been accessed (for audit)';

-- Indexes
CREATE INDEX idx_pseudonymization_keys_status ON socialcandor_schema.pseudonymization_keys(key_status, expires_at);
CREATE INDEX idx_pseudonymization_keys_name ON socialcandor_schema.pseudonymization_keys(key_name, key_version);
CREATE INDEX idx_pseudonymization_keys_owner ON socialcandor_schema.pseudonymization_keys(owner_user_id) WHERE owner_user_id IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_pseudonymization_keys_updated_at
    BEFORE UPDATE ON socialcandor_schema.pseudonymization_keys
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.pseudonymization_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY pseudonymization_keys_admin_policy ON socialcandor_schema.pseudonymization_keys
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
-- Additional role-based policies can be added for allowed_roles

-- =================================================================================================
-- TABLE: CMP12 - privacy_training_records
-- Description: Tracks completion of privacy and data protection training by employees,
--              including module details, scores, and expiration. Supports GDPR Article 39.
-- Business Case: GDPR requires that staff handling personal data be adequately trained.
--                This table records who has completed which training, when it expires,
--                and whether they passed. It enables the organization to demonstrate
--                compliance with training obligations during audits. The design
--                supports recurring training (e.g., annual refreshers) and different
--                training tracks based on role. Integration with HR systems ensures
--                that new hires are automatically assigned required training.
--
-- Key Performance Indicators (KPIs):
--   1. Training completion rate - Percentage of employees up-to-date
--   2. Average score - Mean assessment scores
--   3. Expiration rate - Training expiring in next 30 days
--   4. Module popularity - Most/least completed modules
--   5. Role-specific compliance - Training rates by role/department
--
-- Feature References: GDPR08 (Staff Training), COMP04 (Compliance Training)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.privacy_training_records (
    -- Primary key
    record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    record_number VARCHAR(50) GENERATED ALWAYS AS (
        'PTR-' || TO_CHAR(assigned_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.training_record_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    user_id UUID NOT NULL,

    -- Training details
    training_module VARCHAR(255) NOT NULL,
    training_version VARCHAR(50),
    training_type VARCHAR(50) CHECK (training_type IN ('INITIAL', 'ANNUAL', 'REFRESHER', 'SPECIALIST')),

    -- Assignment
    assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    assigned_by UUID,
    due_date DATE NOT NULL,

    -- Completion
    completed_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(30) DEFAULT 'NOT_STARTED' CHECK (status IN ('NOT_STARTED', 'IN_PROGRESS', 'COMPLETED', 'EXPIRED', 'FAILED')),

    -- Assessment
    score INTEGER CHECK (score >= 0 AND score <= 100),
    passed BOOLEAN,
    attempts INTEGER DEFAULT 1 CHECK (attempts >= 0),

    -- Content
    training_content_url VARCHAR(500),
    certificate_url VARCHAR(500),

    -- Expiration
    expires_at DATE,
    renewal_reminder_sent BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_privacy_training_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_privacy_training_assigned_by FOREIGN KEY (assigned_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_privacy_training_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_privacy_training_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_privacy_training_dates CHECK (
        (completed_at IS NULL) OR (completed_at >= assigned_at)
    ),
    CONSTRAINT chk_privacy_training_expiry CHECK (expires_at IS NULL OR expires_at >= due_date)
);

COMMENT ON TABLE socialcandor_schema.privacy_training_records IS 'Tracks completion of privacy training by employees for GDPR compliance';
COMMENT ON COLUMN socialcandor_schema.privacy_training_records.training_type IS 'Type of training (initial, annual, refresher, specialist)';
COMMENT ON COLUMN socialcandor_schema.privacy_training_records.renewal_reminder_sent IS 'Whether reminder has been sent for expiring training';

-- Indexes
CREATE INDEX idx_privacy_training_user ON socialcandor_schema.privacy_training_records(user_id, status, due_date);
CREATE INDEX idx_privacy_training_status ON socialcandor_schema.privacy_training_records(status, due_date) WHERE status IN ('NOT_STARTED', 'IN_PROGRESS');
CREATE INDEX idx_privacy_training_expires ON socialcandor_schema.privacy_training_records(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_privacy_training_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.privacy_training_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.privacy_training_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY privacy_training_self_policy ON socialcandor_schema.privacy_training_records
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY privacy_training_hr_policy ON socialcandor_schema.privacy_training_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND role IN ('HR', 'COMPLIANCE', 'ADMIN')));

-- =================================================================================================
-- TABLE: CMP13 - compliance_audit_findings
-- Description: Tracks findings from internal and external compliance audits,
--              including severity, remediation status, and evidence.
-- Business Case: Audits (ISO 27001, SOC2, GDPR) produce findings that must be tracked
--                to closure. This table provides a central register of all audit
--                findings, regardless of source. Each finding includes a description,
--                severity, assigned owner, and due date. The status field tracks
--                progress from open to closed, with optional evidence of remediation.
--                Linking to remediation action plans ensures that findings are
--                addressed systematically. This supports continuous improvement and
--                provides auditors with evidence of issue management.
--
-- Key Performance Indicators (KPIs):
--   1. Finding volume - Number of findings per audit period
--   2. Severity distribution - Breakdown by severity level
--   3. Mean time to remediate - Average days from open to closed
--   4. Recurrence rate - Findings with same root cause reappearing
--   5. Audit pass rate - Percentage of audits with no critical findings
--
-- Feature References: COMP01 (Regulatory Compliance), AUD21 (Audit Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.compliance_audit_findings (
    -- Primary key
    finding_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    finding_number VARCHAR(50) GENERATED ALWAYS AS (
        'AF-' || TO_CHAR(identified_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.audit_finding_seq')::TEXT, 6, '0')
    ) STORED,

    -- Finding identification
    finding_title VARCHAR(255) NOT NULL,
    finding_description TEXT NOT NULL,

    -- Source
    audit_type VARCHAR(50) CHECK (audit_type IN ('INTERNAL', 'EXTERNAL', 'REGULATORY', 'CERTIFICATION')),
    audit_name VARCHAR(255),
    auditor VARCHAR(255),

    -- Dates
    identified_at TIMESTAMP WITH TIME ZONE NOT NULL,
    reported_at TIMESTAMP WITH TIME ZONE,

    -- Classification
    severity socialcandor_schema.audit_finding_severity NOT NULL,
    category VARCHAR(100),                                    -- e.g., 'Access Control', 'Data Retention', 'Consent'

    -- Affected areas
    affected_processes TEXT[],
    affected_systems TEXT[],
    affected_data_categories TEXT[],

    -- Remediation
    assigned_to UUID,
    due_date DATE,
    remediation_status VARCHAR(30) DEFAULT 'OPEN' CHECK (remediation_status IN (
        'OPEN', 'IN_PROGRESS', 'VERIFIED', 'CLOSED', 'ACCEPTED_RISK'
    )),
    resolution_notes TEXT,
    resolved_at TIMESTAMP WITH TIME ZONE,

    -- Evidence
    evidence_urls TEXT[],

    -- Root cause
    root_cause TEXT,
    recurrence_prevention TEXT,

    -- Linked remediation plan
    remediation_plan_id UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_audit_finding_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_audit_finding_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_audit_finding_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_audit_finding_dates CHECK (
        resolved_at IS NULL OR resolved_at >= identified_at
    )
);

COMMENT ON TABLE socialcandor_schema.compliance_audit_findings IS 'Tracks findings from internal and external compliance audits';
COMMENT ON COLUMN socialcandor_schema.compliance_audit_findings.recurrence_prevention IS 'Measures taken to prevent recurrence';

-- Indexes
CREATE INDEX idx_audit_finding_status ON socialcandor_schema.compliance_audit_findings(remediation_status, due_date);
CREATE INDEX idx_audit_finding_severity ON socialcandor_schema.compliance_audit_findings(severity);
CREATE INDEX idx_audit_finding_assigned ON socialcandor_schema.compliance_audit_findings(assigned_to) WHERE assigned_to IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_compliance_audit_findings_updated_at
    BEFORE UPDATE ON socialcandor_schema.compliance_audit_findings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.compliance_audit_findings ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_finding_staff_policy ON socialcandor_schema.compliance_audit_findings
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND role IN ('COMPLIANCE', 'AUDITOR', 'ADMIN')));
CREATE POLICY audit_finding_self_policy ON socialcandor_schema.compliance_audit_findings
    FOR SELECT USING (assigned_to = current_setting('app.current_user_id')::UUID);

-- =================================================================================================
-- TABLE: CMP14 - remediation_action_plans
-- Description: Defines action plans to address compliance audit findings, with steps,
--              owners, and deadlines. Tracks progress and effectiveness.
-- Business Case: Audit findings require structured remediation to ensure they are
--                properly addressed. This table breaks down each finding into actionable
--                steps, assigns owners, and sets deadlines. It enables project
--                management of compliance improvements and provides visibility into
--                progress. The design supports multiple actions per finding, dependencies,
--                and verification steps. Integration with findings ensures traceability,
--                and status tracking helps prioritize resources.
--
-- Key Performance Indicators (KPIs):
--   1. Plan completion rate - Percentage of plans completed on time
--   2. Action completion rate - Steps completed vs. planned
--   3. Time to implement - Average days from finding to plan completion
--   4. Dependency resolution - Impact of dependencies on timelines
--   5. Effectiveness rate - Percentage of plans that successfully remediate findings
--
-- Feature References: COMP01 (Regulatory Compliance), IMPROVE02 (Corrective Actions)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.remediation_action_plans (
    -- Primary key
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    plan_number VARCHAR(50) GENERATED ALWAYS AS (
        'RAP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.remediation_plan_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    finding_id UUID NOT NULL,                                  -- Link to compliance_audit_findings

    -- Plan details
    plan_name VARCHAR(255) NOT NULL,
    plan_description TEXT,

    -- Priority and impact
    priority socialcandor_schema.remediation_priority NOT NULL DEFAULT 'MEDIUM',
    estimated_effort_hours INTEGER CHECK (estimated_effort_hours >= 0),

    -- Dates
    created_date DATE NOT NULL DEFAULT CURRENT_DATE,
    target_completion_date DATE NOT NULL,
    actual_completion_date DATE,

    -- Status
    status VARCHAR(30) DEFAULT 'PLANNED' CHECK (status IN (
        'PLANNED', 'IN_PROGRESS', 'COMPLETED', 'VERIFIED', 'CANCELLED'
    )),

    -- Actions (JSON array of steps)
    actions JSONB NOT NULL,                                    -- Array of {step, description, owner, due_date, status}

    -- Resources
    assigned_to UUID,                                          -- Overall plan owner
    additional_assignees UUID[],                               -- Others involved

    -- Verification
    verification_required BOOLEAN DEFAULT TRUE,
    verified_by UUID,
    verified_at TIMESTAMP WITH TIME ZONE,
    verification_notes TEXT,

    -- Effectiveness
    effectiveness_rating INTEGER CHECK (effectiveness_rating >= 1 AND effectiveness_rating <= 5),
    lessons_learned TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_remediation_plan_finding FOREIGN KEY (finding_id)
        REFERENCES socialcandor_schema.compliance_audit_findings(finding_id) ON DELETE CASCADE,
    CONSTRAINT fk_remediation_plan_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_remediation_plan_verified_by FOREIGN KEY (verified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_remediation_plan_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_remediation_plan_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_remediation_plan_dates CHECK (
        actual_completion_date IS NULL OR actual_completion_date >= created_date
    )
);

COMMENT ON TABLE socialcandor_schema.remediation_action_plans IS 'Action plans to address compliance audit findings';
COMMENT ON COLUMN socialcandor_schema.remediation_action_plans.actions IS 'JSON array of remediation steps with owners and statuses';
COMMENT ON COLUMN socialcandor_schema.remediation_action_plans.effectiveness_rating IS 'Rating of how effective the plan was (1-5)';

-- Indexes
CREATE INDEX idx_remediation_plan_finding ON socialcandor_schema.remediation_action_plans(finding_id);
CREATE INDEX idx_remediation_plan_status ON socialcandor_schema.remediation_action_plans(status, target_completion_date);
CREATE INDEX idx_remediation_plan_assigned ON socialcandor_schema.remediation_action_plans(assigned_to) WHERE assigned_to IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_remediation_action_plans_updated_at
    BEFORE UPDATE ON socialcandor_schema.remediation_action_plans
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.remediation_action_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY remediation_plan_staff_policy ON socialcandor_schema.remediation_action_plans
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND role IN ('COMPLIANCE', 'AUDITOR', 'ADMIN')));
CREATE POLICY remediation_plan_owner_policy ON socialcandor_schema.remediation_action_plans
    FOR SELECT USING (assigned_to = current_setting('app.current_user_id')::UUID);

-- =================================================================================================
-- TABLE: CMP15 - regulatory_correspondence
-- Description: Logs all communications with regulatory authorities (DPAs, supervisory
--              authorities), including inquiries, responses, and reports.
-- Business Case: Organizations must maintain records of all interactions with data
--                protection authorities. This table provides a complete history of
--                correspondence, enabling timely responses, tracking of obligations,
--                and audit readiness. Each entry captures the authority, date, type,
--                direction (inbound/outbound), and content (or link to documents).
--                It supports case management by grouping related correspondence
--                (e.g., an investigation). The design ensures that nothing falls
--                through the cracks and demonstrates proactive regulatory engagement.
--
-- Key Performance Indicators (KPIs):
--   1. Response time - Average days to respond to authority inquiries
--   2. Inquiry volume - Number of regulatory contacts per period
--   3. Resolution rate - Percentage of cases closed
--   4. Authority distribution - Contacts by regulatory body
--   5. Document completeness - Percentage with supporting documents attached
--
-- Feature References: COMP02 (Regulatory Relations), GDPR09 (Authority Interaction)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.regulatory_correspondence (
    -- Primary key
    correspondence_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    correspondence_number VARCHAR(50) GENERATED ALWAYS AS (
        'RC-' || TO_CHAR(correspondence_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.regulatory_correspondence_seq')::TEXT, 6, '0')
    ) STORED,

    -- Authority information
    authority_name VARCHAR(255) NOT NULL,
    authority_country VARCHAR(3),
    authority_contact_person VARCHAR(255),
    authority_contact_email VARCHAR(255),
    authority_reference VARCHAR(255),                          -- Their case/file number

    -- Correspondence details
    correspondence_date TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    direction socialcandor_schema.correspondence_direction NOT NULL,
    correspondence_type socialcandor_schema.correspondence_type NOT NULL,
    subject VARCHAR(500) NOT NULL,
    content TEXT,

    -- Attachments
    attachment_urls TEXT[],

    -- Related entities
    related_breach_id UUID,                                    -- If about a breach
    related_processing_record_id UUID,                         -- If about a specific processing
    related_dsar_id UUID,                                      -- If about a complaint

    -- Tracking
    requires_response BOOLEAN DEFAULT FALSE,
    response_deadline DATE,
    response_sent_at TIMESTAMP WITH TIME ZONE,
    response_summary TEXT,

    -- Case management
    case_id VARCHAR(100),                                      -- Group multiple correspondences
    assigned_to UUID,
    status VARCHAR(30) DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESPONDED', 'CLOSED', 'ARCHIVED')),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_regulatory_correspondence_breach FOREIGN KEY (related_breach_id)
        REFERENCES socialcandor_schema.data_breaches(breach_id) ON DELETE SET NULL,
    CONSTRAINT fk_regulatory_correspondence_processing FOREIGN KEY (related_processing_record_id)
        REFERENCES socialcandor_schema.data_processing_records(record_id) ON DELETE SET NULL,
    CONSTRAINT fk_regulatory_correspondence_dsar FOREIGN KEY (related_dsar_id)
        REFERENCES socialcandor_schema.data_subject_requests(request_id) ON DELETE SET NULL,
    CONSTRAINT fk_regulatory_correspondence_assigned FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_regulatory_correspondence_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_regulatory_correspondence_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_regulatory_correspondence_response CHECK (
        (requires_response = FALSE) OR (response_deadline IS NOT NULL)
    )
);

COMMENT ON TABLE socialcandor_schema.regulatory_correspondence IS 'Logs all communications with regulatory authorities (DPAs, supervisory authorities)';
COMMENT ON COLUMN socialcandor_schema.regulatory_correspondence.authority_reference IS 'Reference number assigned by the authority';
COMMENT ON COLUMN socialcandor_schema.regulatory_correspondence.case_id IS 'Internal grouping ID for related correspondences';

-- Indexes
CREATE INDEX idx_regulatory_correspondence_authority ON socialcandor_schema.regulatory_correspondence(authority_name, correspondence_date DESC);
CREATE INDEX idx_regulatory_correspondence_type ON socialcandor_schema.regulatory_correspondence(correspondence_type, direction);
CREATE INDEX idx_regulatory_correspondence_dates ON socialcandor_schema.regulatory_correspondence(response_deadline) WHERE requires_response = TRUE AND response_sent_at IS NULL;
CREATE INDEX idx_regulatory_correspondence_case ON socialcandor_schema.regulatory_correspondence(case_id) WHERE case_id IS NOT NULL;

-- Trigger
CREATE TRIGGER trg_regulatory_correspondence_updated_at
    BEFORE UPDATE ON socialcandor_schema.regulatory_correspondence
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.regulatory_correspondence ENABLE ROW LEVEL SECURITY;
CREATE POLICY regulatory_correspondence_compliance_policy ON socialcandor_schema.regulatory_correspondence
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND role IN ('COMPLIANCE', 'LEGAL', 'ADMIN')));


-- =================================================================================================
-- ENUMS
-- =================================================================================================

-- Enum: DGE01 - data_quality_rule_type
-- Description: Types of data quality rules that can be defined for monitoring and validation.
-- Business Case: Categorizes rules for different quality dimensions (completeness, accuracy, etc.)
--                enabling targeted monitoring and reporting.
-- Feature Reference: DQ01 (Data Quality Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.data_quality_rule_type AS ENUM (
    'COMPLETENESS',      -- Checks for missing/null values
    'ACCURACY',          -- Validates correctness against reference data
    'CONSISTENCY',       -- Ensures data is consistent across systems
    'TIMELINESS',        -- Measures data freshness/latency
    'VALIDITY',          -- Validates format, pattern, range
    'UNIQUENESS',        -- Detects duplicates
    'INTEGRITY',         -- Checks referential integrity
    'CUSTOM'             -- User-defined logic
);
COMMENT ON TYPE socialcandor_schema.data_quality_rule_type IS 'Types of data quality rules for monitoring different dimensions.';

-- Enum: DGE02 - rule_severity
-- Description: Severity levels for data quality rule violations.
-- Business Case: Enables prioritization of remediation efforts based on business impact.
-- Feature Reference: DQ01
-- =================================================================================================
CREATE TYPE socialcandor_schema.rule_severity AS ENUM (
    'LOW',               -- Minimal impact, can be addressed later
    'MEDIUM',            -- Moderate impact, should be addressed soon
    'HIGH',              -- Significant impact, requires attention
    'CRITICAL'           -- Severe impact, immediate action required
);
COMMENT ON TYPE socialcandor_schema.rule_severity IS 'Severity levels for data quality rule violations.';

-- Enum: DGE03 - rule_execution_status
-- Description: Status of a data quality rule execution.
-- Business Case: Tracks the state of automated rule checks.
-- Feature Reference: DQ01
-- =================================================================================================
CREATE TYPE socialcandor_schema.rule_execution_status AS ENUM (
    'PENDING',           -- Execution scheduled but not started
    'RUNNING',           -- Currently being executed
    'SUCCESS',           -- Completed successfully
    'WARNING',           -- Completed with warnings (threshold breached)
    'FAILED',            -- Execution failed due to error
    'CANCELLED'          -- Execution was cancelled
);
COMMENT ON TYPE socialcandor_schema.rule_execution_status IS 'Status of a data quality rule execution.';

-- Enum: DGE04 - incident_status
-- Description: Lifecycle status of a data quality incident.
-- Business Case: Tracks incident from detection to resolution, enabling SLA monitoring.
-- Feature Reference: DQ02 (Data Quality Incident Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.incident_status AS ENUM (
    'OPEN',              -- Newly detected
    'INVESTIGATING',     -- Under investigation
    'MITIGATING',        -- Remediation in progress
    'RESOLVED',          -- Issue fixed
    'CLOSED',            -- Formally closed after verification
    'FALSE_POSITIVE'     -- Determined not to be an actual issue
);
COMMENT ON TYPE socialcandor_schema.incident_status IS 'Lifecycle status of a data quality incident.';

-- Enum: DGE05 - asset_type
-- Description: Types of data assets that can be governed.
-- Business Case: Enables polymorphic references in governance tables.
-- Feature Reference: GOV01 (Data Governance)
-- =================================================================================================
CREATE TYPE socialcandor_schema.asset_type AS ENUM (
    'TABLE',             -- Database table
    'COLUMN',            -- Database column
    'VIEW',              -- Database view
    'PIPELINE',          -- Data pipeline
    'REPORT',            -- Report or dashboard
    'DATASET',           -- File or external dataset
    'ML_MODEL',          -- Machine learning model
    'API'                -- API endpoint
);
COMMENT ON TYPE socialcandor_schema.asset_type IS 'Types of data assets that can be governed.';

-- Enum: DGE06 - term_status
-- Description: Status of a business glossary term.
-- Business Case: Tracks the lifecycle of business term definitions from draft to approval.
-- Feature Reference: GOV03 (Business Glossary)
-- =================================================================================================
CREATE TYPE socialcandor_schema.term_status AS ENUM (
    'DRAFT',             -- Initial draft, not yet approved
    'UNDER_REVIEW',      -- Submitted for review
    'APPROVED',          -- Formally approved for use
    'DEPRECATED',        -- No longer in active use
    'ARCHIVED'           -- Retired from glossary
);
COMMENT ON TYPE socialcandor_schema.term_status IS 'Status of a business glossary term.';

-- Enum: DGE07 - transformation_type
-- Description: Types of transformations in data lineage.
-- Business Case: Categorizes data movement operations for impact analysis.
-- Feature Reference: GOV06 (Data Lineage)
-- =================================================================================================
CREATE TYPE socialcandor_schema.transformation_type AS ENUM (
    'DIRECT',            -- Direct copy, no transformation
    'TRANSFORMED',       -- Modified via transformation logic
    'AGGREGATED',        -- Aggregated (sum, count, avg)
    'FILTERED',          -- Subset based on conditions
    'JOINED',            -- Combined with other data
    'CALCULATED'         -- Derived via calculation
);
COMMENT ON TYPE socialcandor_schema.transformation_type IS 'Types of transformations in data lineage.';

-- Enum: DGE08 - access_request_status
-- Description: Status of a data access request.
-- Business Case: Tracks the workflow of access requests from submission to approval/rejection.
-- Feature Reference: ACCESS02 (Data Access Workflow)
-- =================================================================================================
CREATE TYPE socialcandor_schema.access_request_status AS ENUM (
    'PENDING',           -- Awaiting approval
    'APPROVED',          -- Approved, access granted
    'REJECTED',          -- Rejected by approver
    'CANCELLED',         -- Cancelled by requester
    'EXPIRED',           -- Expired after inactivity
    'REVOKED'            -- Access revoked after being granted
);
COMMENT ON TYPE socialcandor_schema.access_request_status IS 'Status of a data access request.';

-- Enum: DGE09 - access_type
-- Description: Type of access requested/permitted.
-- Business Case: Granular access control (read, write, export, etc.).
-- Feature Reference: ACCESS02
-- =================================================================================================
CREATE TYPE socialcandor_schema.access_type AS ENUM (
    'READ',              -- Read-only access
    'WRITE',             -- Write/modify access
    'EXPORT',            -- Export/download access
    'DELETE',            -- Delete access
    'ADMIN'              -- Administrative access
);
COMMENT ON TYPE socialcandor_schema.access_type IS 'Type of access requested/permitted.';

-- Enum: DGE10 - contract_status
-- Description: Status of a data contract.
-- Business Case: Tracks the lifecycle of data agreements between producers and consumers.
-- Feature Reference: CONTRACT01 (Data Contracts)
-- =================================================================================================
CREATE TYPE socialcandor_schema.contract_status AS ENUM (
    'DRAFT',             -- In development
    'ACTIVE',            -- Currently in effect
    'SUSPENDED',         -- Temporarily inactive
    'EXPIRED',           -- Past its validity period
    'TERMINATED'         -- Permanently ended
);
COMMENT ON TYPE socialcandor_schema.contract_status IS 'Status of a data contract.';

-- Enum: DGE11 - assignment_role
-- Description: Role of a user in data stewardship assignments.
-- Business Case: Defines responsibilities (owner, steward, technical contact).
-- Feature Reference: GOV05 (Data Ownership)
-- =================================================================================================
CREATE TYPE socialcandor_schema.assignment_role AS ENUM (
    'DATA_OWNER',            -- Business owner accountable for data
    'DATA_STEWARD',          -- Day-to-day steward
    'TECHNICAL_STEWARD',     -- Technical contact for data systems
    'BUSINESS_STEWARD',      -- Business representative
    'DATA_CUSTODIAN'         -- Responsible for data storage/security
);
COMMENT ON TYPE socialcandor_schema.assignment_role IS 'Role of a user in data stewardship assignments.';


-- =================================================================================================
-- Table: DG01 - data_steward_assignments
-- Description: Maps users to stewardship roles for specific data assets, defining accountability.
-- Business Case: Establishes clear ownership and stewardship for data assets, which is fundamental
--                to any data governance program. This table records who is responsible for what data,
--                enabling proper oversight, issue escalation, and compliance. It supports both
--                individual assignments and team-based assignments. The design allows for multiple
--                stewards per asset with different roles (owner, steward, technical contact).
--                This is critical for GDPR compliance (identifying data owners) and for operational
--                data quality management. The assignments are time-bound to support rotations and
--                role changes while maintaining historical audit trails.
-- KPIs:
--   1. Stewardship coverage: % of critical data assets with assigned stewards
--   2. Assignment completeness: % of assets with at least one steward
--   3. Steward load: Average number of assets per steward
--   4. Assignment churn: Rate of steward reassignments per quarter
--   5. Response time: Time taken for stewards to acknowledge/act on data issues
-- Feature References: GOV05 (Data Ownership), DQ01 (Data Quality Management), GDPR01 (GDPR Compliance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_steward_assignments (
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    assignment_number VARCHAR(50) GENERATED ALWAYS AS (
        'STWD-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- References
    user_id UUID NOT NULL,
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,                           -- Polymorphic ID of the asset (table, column, etc.)
    asset_identifier VARCHAR(500),                     -- Human-readable identifier (e.g., schema.table.column)

    -- Assignment details
    role socialcandor_schema.assignment_role NOT NULL,
    is_primary BOOLEAN DEFAULT FALSE,                  -- Primary steward for the asset
    responsibility_description TEXT,

    -- Time bounds
    assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    assigned_by UUID NOT NULL,
    valid_from DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL OR valid_to >= CURRENT_DATE) STORED,

    -- Stewardship metadata
    acknowledgement_required BOOLEAN DEFAULT TRUE,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    notes TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_steward_assignments_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_steward_assignments_assigned_by FOREIGN KEY (assigned_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_steward_assignments_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_steward_assignments_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_steward_assignments_dates CHECK (valid_to IS NULL OR valid_to >= valid_from),
    CONSTRAINT uk_steward_assignments_active UNIQUE (user_id, asset_type, asset_id, role, valid_from) WHERE is_active = TRUE
);

COMMENT ON TABLE socialcandor_schema.data_steward_assignments IS 'Maps users to stewardship roles for specific data assets.';
COMMENT ON COLUMN socialcandor_schema.data_steward_assignments.asset_type IS 'Type of asset (table, column, pipeline, etc.)';
COMMENT ON COLUMN socialcandor_schema.data_steward_assignments.asset_id IS 'UUID of the asset in its respective catalog table';
COMMENT ON COLUMN socialcandor_schema.data_steward_assignments.role IS 'Role (owner, steward, technical contact)';
COMMENT ON COLUMN socialcandor_schema.data_steward_assignments.is_primary IS 'Indicates if this is the primary steward for the asset';

-- Indexes for performance
CREATE INDEX idx_steward_assignments_user ON socialcandor_schema.data_steward_assignments(user_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_steward_assignments_asset ON socialcandor_schema.data_steward_assignments(asset_type, asset_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_steward_assignments_role ON socialcandor_schema.data_steward_assignments(role) WHERE is_active = TRUE;
CREATE INDEX idx_steward_assignments_valid ON socialcandor_schema.data_steward_assignments(valid_from, valid_to) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_data_steward_assignments_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_steward_assignments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG02 - data_quality_rules
-- Description: Defines data quality rules for automated monitoring, including thresholds,
--              severity, and execution logic. Supports rule versioning and ownership.
-- Business Case: Data quality rules are the foundation of proactive data governance. This table
--                stores rule definitions that can be executed by schedulers or triggered by data
--                events. Rules can target tables, columns, or entire datasets, and can check
--                various quality dimensions (completeness, accuracy, etc.). The design includes
--                versioning to track rule evolution, ownership to assign accountability, and
--                thresholds to differentiate warnings from failures. Integration with alerting
--                systems enables real-time notifications when rules are violated. This is essential
--                for maintaining trust in data and meeting SLAs.
-- KPIs:
--   1. Rule coverage: % of critical assets covered by at least one rule
--   2. Rule effectiveness: % of data issues detected by rules before user reports
--   3. Rule execution success rate: % of rule runs completing without error
--   4. False positive rate: % of rule failures that are false alarms
--   5. Time to detect: average time from data creation to rule violation detection
-- Feature References: DQ01 (Data Quality Management), DQ03 (Automated Monitoring)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_rules (
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    rule_number VARCHAR(50) GENERATED ALWAYS AS (
        'DQR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Basic identification
    rule_name VARCHAR(255) NOT NULL,
    rule_description TEXT,
    rule_type socialcandor_schema.data_quality_rule_type NOT NULL,
    rule_version INTEGER NOT NULL DEFAULT 1,

    -- Ownership
    owner_user_id UUID,                                 -- The rule owner (steward)
    steward_team VARCHAR(100),

    -- Target definition
    target_asset_type socialcandor_schema.asset_type NOT NULL,
    target_asset_id UUID,                               -- ID of the asset (if known)
    target_schema VARCHAR(100),
    target_table VARCHAR(100),
    target_column VARCHAR(100),
    target_filter TEXT,                                  -- WHERE clause to limit scope

    -- Rule logic
    rule_expression TEXT NOT NULL,                       -- SQL expression or JSON condition
    expected_value TEXT,
    comparison_operator VARCHAR(20) CHECK (comparison_operator IN ('=', '!=', '>', '<', '>=', '<=', 'BETWEEN', 'IN', 'LIKE', 'NOT NULL', 'NULL')),

    -- Thresholds (percentage of records that can fail)
    warning_threshold_percent NUMERIC(5,2) CHECK (warning_threshold_percent >= 0 AND warning_threshold_percent <= 100),
    failure_threshold_percent NUMERIC(5,2) CHECK (failure_threshold_percent >= 0 AND failure_threshold_percent <= 100),
    severity socialcandor_schema.rule_severity DEFAULT 'MEDIUM',

    -- Execution settings
    execution_frequency VARCHAR(20) CHECK (execution_frequency IN ('REAL_TIME', 'HOURLY', 'DAILY', 'WEEKLY', 'MONTHLY', 'ON_DEMAND')),
    execution_timeout_seconds INTEGER CHECK (execution_timeout_seconds >= 0),
    is_active BOOLEAN DEFAULT TRUE,

    -- Notification settings
    notify_on_warning BOOLEAN DEFAULT FALSE,
    notify_on_failure BOOLEAN DEFAULT TRUE,
    notify_emails TEXT[],

    -- Metadata
    tags TEXT[],
    documentation_url VARCHAR(500),

    -- Versioning and deprecation
    deprecated_at TIMESTAMP WITH TIME ZONE,
    superseded_by_rule_id UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_quality_rules_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_rules_superseded FOREIGN KEY (superseded_by_rule_id)
        REFERENCES socialcandor_schema.data_quality_rules(rule_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_rules_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_quality_rules_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_quality_rules_threshold CHECK (
        warning_threshold_percent IS NULL OR failure_threshold_percent IS NULL OR
        warning_threshold_percent <= failure_threshold_percent
    )
);

COMMENT ON TABLE socialcandor_schema.data_quality_rules IS 'Defines data quality rules for automated monitoring, with versioning and ownership.';
COMMENT ON COLUMN socialcandor_schema.data_quality_rules.rule_expression IS 'SQL expression or JSON condition defining the rule logic.';
COMMENT ON COLUMN socialcandor_schema.data_quality_rules.target_filter IS 'WHERE clause to restrict the data evaluated by the rule.';
COMMENT ON COLUMN socialcandor_schema.data_quality_rules.warning_threshold_percent IS 'Percentage of records that can fail before a warning is raised.';
COMMENT ON COLUMN socialcandor_schema.data_quality_rules.failure_threshold_percent IS 'Percentage of records that can fail before the rule is considered failed.';

-- Indexes for performance
CREATE INDEX idx_data_quality_rules_owner ON socialcandor_schema.data_quality_rules(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX idx_data_quality_rules_target ON socialcandor_schema.data_quality_rules(target_asset_type, target_asset_id) WHERE is_active = TRUE;
CREATE INDEX idx_data_quality_rules_type ON socialcandor_schema.data_quality_rules(rule_type, severity);
CREATE INDEX idx_data_quality_rules_active ON socialcandor_schema.data_quality_rules(is_active) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_data_quality_rules_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_quality_rules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG03 - data_quality_metrics
-- Description: Stores the results of data quality rule executions, including counts,
--              percentages, and detailed violation data. Enables trend analysis and reporting.
-- Business Case: This table captures the outcome of each data quality check execution,
--                providing a historical record of data quality over time. Metrics include the
--                number of records checked, records passed/failed, and the actual percentage
--                of failures. This data feeds dashboards, enables root cause analysis, and
--                supports service level reporting. By storing execution metadata (execution time,
--                duration), we can also monitor the performance of the checks themselves.
--                Partitioning by month ensures query performance as data volume grows.
-- KPIs:
--   1. Rule pass rate: % of executions where failure_percent <= failure_threshold
--   2. Data quality score: Composite score derived from multiple rules
--   3. Trend analysis: Month-over-month change in failure rates
--   4. Rule execution performance: Average execution time per rule
--   5. Violation volume: Number of records violating rules over time
-- Feature References: DQ04 (Data Quality Monitoring), DQ05 (Data Quality Dashboards)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_metrics (
    metric_id BIGSERIAL,
    metric_number VARCHAR(50) GENERATED ALWAYS AS (
        'DQM-' || TO_CHAR(execution_time, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM execution_time)::INT::TEXT, 6, '0')
    ) STORED,

    -- References
    rule_id UUID NOT NULL,

    -- Execution metadata
    execution_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    execution_status socialcandor_schema.rule_execution_status NOT NULL,
    execution_duration_ms INTEGER CHECK (execution_duration_ms >= 0),

    -- Results
    records_checked INTEGER CHECK (records_checked >= 0),
    records_passed INTEGER CHECK (records_passed >= 0),
    records_failed INTEGER CHECK (records_failed >= 0),
    failure_percent NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN records_checked > 0 THEN (records_failed::NUMERIC / records_checked::NUMERIC) * 100 ELSE 0 END
    ) STORED,

    -- Detailed violation data (optional, can be large)
    violation_sample JSONB,                                 -- Sample of violating records
    violation_summary TEXT,                                 -- Human-readable summary

    -- Error handling
    error_message TEXT,
    error_stack TEXT,

    -- Context (snapshot of rule configuration at execution time)
    rule_snapshot JSONB,

    -- Partition key
    execution_date DATE GENERATED ALWAYS AS (execution_time::DATE) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT pk_data_quality_metrics PRIMARY KEY (metric_id, execution_date),
    CONSTRAINT fk_data_quality_metrics_rule FOREIGN KEY (rule_id)
        REFERENCES socialcandor_schema.data_quality_rules(rule_id) ON DELETE CASCADE
) PARTITION BY RANGE (execution_date);

COMMENT ON TABLE socialcandor_schema.data_quality_metrics IS 'Stores results of data quality rule executions for trend analysis and reporting.';
COMMENT ON COLUMN socialcandor_schema.data_quality_metrics.rule_snapshot IS 'Snapshot of the rule configuration at execution time for historical accuracy.';
COMMENT ON COLUMN socialcandor_schema.data_quality_metrics.violation_sample IS 'Sample of violating records for debugging (limit size).';

-- Create initial partitions for the next 12 months
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'data_quality_metrics_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.data_quality_metrics
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes for performance (on parent, will be inherited)
CREATE INDEX idx_data_quality_metrics_rule ON socialcandor_schema.data_quality_metrics(rule_id, execution_time DESC);
CREATE INDEX idx_data_quality_metrics_status ON socialcandor_schema.data_quality_metrics(execution_status, execution_time DESC);
CREATE INDEX idx_data_quality_metrics_failure ON socialcandor_schema.data_quality_metrics(execution_date, failure_percent) WHERE failure_percent > 0;


-- =================================================================================================
-- Table: DG04 - data_quality_incidents
-- Description: Tracks data quality incidents from detection through investigation, mitigation,
--              and closure. Enables root cause analysis and continuous improvement.
-- Business Case: When data quality rules are violated or issues are reported, an incident record
--                is created to manage the resolution process. This table captures the lifecycle
--                of each incident, including severity, affected assets, root cause, remediation
--                actions, and verification steps. It integrates with data quality metrics (linking
--                to the failing rule execution) and with stewardship assignments (assigning
--                responsibility). Historical incident data supports trend analysis and helps
--                identify systemic issues. This is essential for maintaining data reliability
--                and meeting SLAs.
-- KPIs:
--   1. Mean time to detect (MTTD): time from data creation to incident detection
--   2. Mean time to resolve (MTTR): time from detection to resolution
--   3. Incident volume: number of incidents by severity per period
--   4. Recurrence rate: % of incidents with same root cause within 30 days
--   5. Escalation rate: % of incidents escalated to higher severity
-- Feature References: DQ02 (Data Quality Incident Management), DQ06 (Root Cause Analysis)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_incidents (
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'DQI-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM detected_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- References
    rule_id UUID,                                       -- Rule that detected the issue (if automated)
    metric_id BIGINT,                                    -- Specific metric execution that triggered incident

    -- Incident details
    title VARCHAR(255) NOT NULL,
    description TEXT,
    severity socialcandor_schema.rule_severity NOT NULL,

    -- Affected assets
    affected_assets JSONB,                               -- List of assets impacted

    -- Timing
    occurred_at TIMESTAMP WITH TIME ZONE,                -- When the data issue first occurred
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    mitigated_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,

    -- Ownership
    assigned_to UUID,                                    -- Steward assigned to investigate
    reported_by UUID,                                    -- User who reported (if manual)

    -- Investigation
    root_cause TEXT,
    root_cause_category VARCHAR(100),
    investigation_notes TEXT,

    -- Remediation
    remediation_actions TEXT,
    verification_steps TEXT,
    resolution_notes TEXT,

    -- Status
    status socialcandor_schema.incident_status NOT NULL DEFAULT 'OPEN',

    -- Impact metrics
    impacted_records_count INTEGER CHECK (impacted_records_count >= 0),
    impacted_users_count INTEGER CHECK (impacted_users_count >= 0),
    business_impact TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_quality_incidents_rule FOREIGN KEY (rule_id)
        REFERENCES socialcandor_schema.data_quality_rules(rule_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_incidents_metric FOREIGN KEY (metric_id)
        REFERENCES socialcandor_schema.data_quality_metrics(metric_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_incidents_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_incidents_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_quality_incidents_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_quality_incidents_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_quality_incidents_timing CHECK (
        (acknowledged_at IS NULL OR acknowledged_at >= detected_at) AND
        (mitigated_at IS NULL OR mitigated_at >= COALESCE(acknowledged_at, detected_at)) AND
        (resolved_at IS NULL OR resolved_at >= mitigated_at) AND
        (closed_at IS NULL OR closed_at >= resolved_at)
    )
);

COMMENT ON TABLE socialcandor_schema.data_quality_incidents IS 'Tracks data quality incidents from detection to closure.';
COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.affected_assets IS 'JSON list of assets impacted (tables, reports, etc.)';
COMMENT ON COLUMN socialcandor_schema.data_quality_incidents.root_cause_category IS 'Categorised root cause for trend analysis.';

-- Indexes for performance
CREATE INDEX idx_data_quality_incidents_status ON socialcandor_schema.data_quality_incidents(status, severity, detected_at DESC);
CREATE INDEX idx_data_quality_incidents_assigned ON socialcandor_schema.data_quality_incidents(assigned_to, status) WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_data_quality_incidents_rule ON socialcandor_schema.data_quality_incidents(rule_id) WHERE rule_id IS NOT NULL;
CREATE INDEX idx_data_quality_incidents_detected ON socialcandor_schema.data_quality_incidents(detected_at DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_data_quality_incidents_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_quality_incidents
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG05 - data_lineage_mappings
-- Description: Documents the flow of data from sources to destinations, capturing transformations,
--              dependencies, and metadata. Enables impact analysis and traceability.
-- Business Case: Understanding data lineage is critical for impact analysis (what breaks if a source
--                changes), regulatory compliance (proving data provenance), and troubleshooting
--                data quality issues. This table captures the directed graph of data movement,
--                including transformations applied at each step. The design supports multiple asset
--                types (tables, columns, pipelines, reports) and versioning to track changes over
--                time. It also captures transformation logic (e.g., SQL) for reproducibility.
--                This enables data stewards to quickly identify downstream dependencies and
--                upstream sources, reducing the time to assess change impact.
-- KPIs:
--   1. Lineage coverage: % of critical data assets with documented lineage
--   2. Dependency depth: Average number of downstream dependencies per source
--   3. Change impact time: Time to identify impacted assets for a proposed change
--   4. Lineage accuracy: % of lineage relationships verified by data stewards
--   5. Lineage freshness: Time since last lineage update for key assets
-- Feature References: GOV06 (Data Lineage), DQ08 (Data Quality Tracing), IMPACT01 (Impact Analysis)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_lineage_mappings (
    mapping_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    mapping_number VARCHAR(50) GENERATED ALWAYS AS (
        'LIN-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Source asset
    source_type socialcandor_schema.asset_type NOT NULL,
    source_id UUID NOT NULL,
    source_version VARCHAR(50),                         -- For versioned assets
    source_identifier VARCHAR(500),                      -- Human-readable identifier

    -- Target asset
    target_type socialcandor_schema.asset_type NOT NULL,
    target_id UUID NOT NULL,
    target_version VARCHAR(50),
    target_identifier VARCHAR(500),

    -- Relationship details
    transformation_type socialcandor_schema.transformation_type NOT NULL,
    transformation_description TEXT,
    transformation_logic TEXT,                           -- SQL, Python, etc.

    -- Pipeline reference (if applicable)
    pipeline_id UUID,

    -- Cardinality
    source_rows_ratio NUMERIC(10,4),                     -- Source to target row ratio
    selectivity NUMERIC(10,4),                            -- Filtering factor (0-1)

    -- Effective dating
    valid_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_to TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL) STORED,

    -- Metadata
    confidence_score NUMERIC(5,2) CHECK (confidence_score >= 0 AND confidence_score <= 100),
    verified_by UUID,
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_lineage_mappings_pipeline FOREIGN KEY (pipeline_id)
        REFERENCES socialcandor_schema.ingestion_pipelines(pipeline_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_lineage_mappings_verified_by FOREIGN KEY (verified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_lineage_mappings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_lineage_mappings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_lineage_mappings_dates CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT chk_data_lineage_mappings_assets CHECK (
        (source_type != target_type) OR (source_id != target_id)
    ),
    CONSTRAINT uk_data_lineage_mappings UNIQUE (source_type, source_id, target_type, target_id, valid_from)
);

COMMENT ON TABLE socialcandor_schema.data_lineage_mappings IS 'Documents data flow from source to destination for impact analysis and traceability.';
COMMENT ON COLUMN socialcandor_schema.data_lineage_mappings.transformation_logic IS 'Code or logic describing the transformation.';
COMMENT ON COLUMN socialcandor_schema.data_lineage_mappings.confidence_score IS 'Confidence in the lineage mapping (0-100).';

-- Indexes for performance
CREATE INDEX idx_data_lineage_mappings_source ON socialcandor_schema.data_lineage_mappings(source_type, source_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_data_lineage_mappings_target ON socialcandor_schema.data_lineage_mappings(target_type, target_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_data_lineage_mappings_pipeline ON socialcandor_schema.data_lineage_mappings(pipeline_id) WHERE pipeline_id IS NOT NULL;
CREATE INDEX idx_data_lineage_mappings_verified ON socialcandor_schema.data_lineage_mappings(verified_by, verified_at) WHERE verified_by IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_data_lineage_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_lineage_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG06 - metadata_business_glossary
-- Description: Central repository for business terms and definitions, linking technical
--              assets to business concepts. Enables common understanding across the organization.
-- Business Case: A business glossary is essential for aligning technical data assets with business
--                concepts. This table stores business terms, their definitions, synonyms, and
--                relationships to other terms (parent-child, related). It also links terms to
--                technical assets (tables, columns) via references in other tables. The design
--                supports term status (draft, approved, deprecated) and ownership (steward).
--                This ensures that everyone in the organization uses consistent terminology,
--                reducing confusion and improving data discoverability. It is a cornerstone of
--                any data governance program.
-- KPIs:
--   1. Glossary coverage: % of technical assets linked to at least one business term
--   2. Term approval rate: % of terms in approved status
--   3. Term usage: Number of times terms are referenced in documentation or queries
--   4. Term churn: Rate of new term creation vs. deprecation
--   5. User satisfaction: Survey score on glossary usefulness
-- Feature References: GOV03 (Business Glossary), GOV04 (Data Catalog)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.metadata_business_glossary (
    term_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    term_number VARCHAR(50) GENERATED ALWAYS AS (
        'GLOS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Term identification
    term_name VARCHAR(255) NOT NULL,
    term_abbreviation VARCHAR(50),
    definition TEXT NOT NULL,
    business_context TEXT,
    examples TEXT,

    -- Categorization
    category VARCHAR(100),
    subcategory VARCHAR(100),
    tags TEXT[],

    -- Relationships
    parent_term_id UUID,
    related_terms UUID[],                               -- IDs of related terms

    -- Status and ownership
    status socialcandor_schema.term_status NOT NULL DEFAULT 'DRAFT',
    steward_id UUID,                                     -- Business steward responsible

    -- Synonyms
    synonyms TEXT[],
    antonyms TEXT[],

    -- Versioning
    version INTEGER DEFAULT 1,
    effective_from DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

    -- Approval workflow
    submitted_for_review_at TIMESTAMP WITH TIME ZONE,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_metadata_business_glossary_parent FOREIGN KEY (parent_term_id)
        REFERENCES socialcandor_schema.metadata_business_glossary(term_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_business_glossary_steward FOREIGN KEY (steward_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_business_glossary_approved_by FOREIGN KEY (approved_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_business_glossary_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_metadata_business_glossary_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_metadata_business_glossary_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT uk_metadata_business_glossary_name UNIQUE (term_name, effective_from)
);

COMMENT ON TABLE socialcandor_schema.metadata_business_glossary IS 'Central repository for business terms and definitions, linking technical assets to business concepts.';
COMMENT ON COLUMN socialcandor_schema.metadata_business_glossary.related_terms IS 'Array of term IDs that are related to this term.';
COMMENT ON COLUMN socialcandor_schema.metadata_business_glossary.synonyms IS 'Alternative terms with similar meaning.';

-- Indexes for performance
CREATE INDEX idx_metadata_business_glossary_name ON socialcandor_schema.metadata_business_glossary(term_name);
CREATE INDEX idx_metadata_business_glossary_status ON socialcandor_schema.metadata_business_glossary(status, is_current) WHERE is_current = TRUE;
CREATE INDEX idx_metadata_business_glossary_parent ON socialcandor_schema.metadata_business_glossary(parent_term_id) WHERE parent_term_id IS NOT NULL;
CREATE INDEX idx_metadata_business_glossary_steward ON socialcandor_schema.metadata_business_glossary(steward_id) WHERE steward_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_metadata_business_glossary_updated_at
    BEFORE UPDATE ON socialcandor_schema.metadata_business_glossary
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG07 - metadata_technical_catalog
-- Description: Technical metadata catalog for data assets (tables, columns, pipelines, reports)
--              including schema definitions, data types, and descriptions. Enables data discovery.
-- Business Case: A technical catalog provides a single source of truth for data asset metadata,
--                including schema information, data types, descriptions, and technical ownership.
--                This table stores information about tables, columns, views, pipelines, and reports.
--                It supports versioning to track schema evolution and includes foreign key
--                relationships to business glossary terms. This is the foundation for data
--                discovery, impact analysis, and data governance automation.
-- KPIs:
--   1. Catalog completeness: % of production tables with documented metadata
--   2. Metadata freshness: Time since last metadata update for active assets
--   3. Discovery usage: Number of catalog searches per week
--   4. Glossary linkage: % of columns linked to business terms
--   5. Schema drift detection: Number of schema changes detected vs. catalog
-- Feature References: GOV02 (Data Catalog), GOV04 (Data Discovery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.metadata_technical_catalog (
    catalog_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    catalog_number VARCHAR(50) GENERATED ALWAYS AS (
        'CAT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Asset identification
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,                               -- Could reference other tables (but we store directly)
    asset_name VARCHAR(255) NOT NULL,
    asset_schema VARCHAR(100),
    asset_database VARCHAR(100),
    asset_location VARCHAR(500),                           -- File path, API endpoint, etc.

    -- Technical details
    data_type VARCHAR(100),                                -- For columns: integer, varchar, etc.
    length INTEGER CHECK (length >= 0),
    precision INTEGER CHECK (precision >= 0),
    scale INTEGER CHECK (scale >= 0),
    is_nullable BOOLEAN,
    is_primary_key BOOLEAN DEFAULT FALSE,
    is_foreign_key BOOLEAN DEFAULT FALSE,
    foreign_key_reference VARCHAR(500),

    -- Descriptions
    technical_description TEXT,
    business_description TEXT,

    -- Business glossary linkage
    business_term_id UUID,                                 -- Link to business glossary

    -- Ownership
    technical_owner_id UUID,                               -- Technical contact
    data_steward_id UUID,                                  -- Data steward

    -- Source system
    source_system VARCHAR(100),
    source_system_version VARCHAR(50),

    -- Versioning
    version INTEGER DEFAULT 1,
    effective_from DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

    -- Metadata
    tags TEXT[],
    properties JSONB,                                      -- Additional properties

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_metadata_technical_catalog_business_term FOREIGN KEY (business_term_id)
        REFERENCES socialcandor_schema.metadata_business_glossary(term_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_technical_catalog_technical_owner FOREIGN KEY (technical_owner_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_technical_catalog_data_steward FOREIGN KEY (data_steward_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_metadata_technical_catalog_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_metadata_technical_catalog_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_metadata_technical_catalog_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT uk_metadata_technical_catalog UNIQUE (asset_type, asset_id, effective_from)
);

COMMENT ON TABLE socialcandor_schema.metadata_technical_catalog IS 'Technical metadata catalog for data assets, enabling discovery and governance.';
COMMENT ON COLUMN socialcandor_schema.metadata_technical_catalog.properties IS 'JSON object for additional technical properties.';

-- Indexes for performance
CREATE INDEX idx_metadata_technical_catalog_name ON socialcandor_schema.metadata_technical_catalog(asset_name);
CREATE INDEX idx_metadata_technical_catalog_type ON socialcandor_schema.metadata_technical_catalog(asset_type, asset_schema);
CREATE INDEX idx_metadata_technical_catalog_current ON socialcandor_schema.metadata_technical_catalog(is_current) WHERE is_current = TRUE;
CREATE INDEX idx_metadata_technical_catalog_business_term ON socialcandor_schema.metadata_technical_catalog(business_term_id) WHERE business_term_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_metadata_technical_catalog_updated_at
    BEFORE UPDATE ON socialcandor_schema.metadata_technical_catalog
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG08 - data_classification_records
-- Description: Assigns sensitivity classifications to data assets (tables, columns, datasets)
--              based on data_classification enum. Tracks justification and approval.
-- Business Case: Data classification is fundamental to security and compliance. This table records
--                the sensitivity level of each data asset, along with the justification and
--                approver. It supports classification at different granularities (table, column)
--                and tracks changes over time. This enables appropriate security controls
--                (encryption, access restrictions) and helps meet regulatory requirements like
--                GDPR (identifying PII) and PCI DSS (identifying cardholder data). The design
--                includes effective dating to support historical reporting and audits.
-- KPIs:
--   1. Classification coverage: % of assets with a classification assigned
--   2. PII detection: % of PII columns correctly identified
--   3. Classification accuracy: % of classifications verified by data stewards
--   4. Reclassification frequency: Number of classification changes per month
--   5. Time to classify: Time from asset creation to classification assignment
-- Feature References: GOV04 (Data Classification), SEC01 (Data Protection), GDPR01 (GDPR Compliance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_classification_records (
    classification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    classification_number VARCHAR(50) GENERATED ALWAYS AS (
        'CLS-' || TO_CHAR(classified_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM classified_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Asset reference
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,                               -- ID in the technical catalog or other table
    asset_identifier VARCHAR(500),                         -- Human-readable identifier (schema.table.column)

    -- Classification
    classification_level socialcandor_schema.data_classification NOT NULL,
    classification_justification TEXT,
    classification_source VARCHAR(100) CHECK (classification_source IN ('MANUAL', 'AUTOMATED', 'INFERRED', 'REGULATORY')),

    -- PII/PHI indicators
    contains_pii BOOLEAN DEFAULT FALSE,
    contains_phi BOOLEAN DEFAULT FALSE,
    contains_pci BOOLEAN DEFAULT FALSE,

    -- Dates
    classified_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    classified_by UUID NOT NULL,
    valid_from DATE NOT NULL DEFAULT CURRENT_DATE,
    valid_to DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (valid_to IS NULL OR valid_to >= CURRENT_DATE) STORED,

    -- Review cycle
    review_required BOOLEAN DEFAULT TRUE,
    review_frequency_days INTEGER DEFAULT 365,
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE GENERATED ALWAYS AS (last_reviewed_at::DATE + (review_frequency_days || ' days')::INTERVAL) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_classification_records_classified_by FOREIGN KEY (classified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_classification_records_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_classification_records_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_classification_records_dates CHECK (valid_to IS NULL OR valid_to >= valid_from),
    CONSTRAINT uk_data_classification_records UNIQUE (asset_type, asset_id, valid_from)
);

COMMENT ON TABLE socialcandor_schema.data_classification_records IS 'Assigns sensitivity classifications to data assets, tracking justification and approval.';
COMMENT ON COLUMN socialcandor_schema.data_classification_records.classification_source IS 'How the classification was determined (manual, automated, inferred).';

-- Indexes for performance
CREATE INDEX idx_data_classification_records_asset ON socialcandor_schema.data_classification_records(asset_type, asset_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_data_classification_records_level ON socialcandor_schema.data_classification_records(classification_level, next_review_date) WHERE is_active = TRUE;
CREATE INDEX idx_data_classification_records_pii ON socialcandor_schema.data_classification_records(contains_pii, contains_phi, contains_pci) WHERE contains_pii = TRUE OR contains_phi = TRUE OR contains_pci = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_data_classification_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_classification_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG09 - data_access_requests
-- Description: Manages user requests for access to data assets, including justification,
--              requested access type, and workflow status. Enables self-service data access.
-- Business Case: As data governance matures, a formal access request process is needed to ensure
--                that only authorized users can access sensitive data. This table captures requests
--                from users for access to specific assets, along with business justification and
--                requested access type (read, write, export). The workflow includes approval steps
--                (linked to data_access_approvals) and tracks status changes. Integration with
--                data classification ensures that requests for sensitive data are flagged for
--                additional scrutiny. This supports compliance with privacy regulations and
--                internal security policies.
-- KPIs:
--   1. Request volume: Number of access requests per month
--   2. Approval rate: % of requests approved vs. rejected
--   3. Time to approve: average time from request to decision
--   4. Self-service adoption: % of access requests initiated via self-service portal
--   5. Compliance rate: % of requests for sensitive data that receive proper justification
-- Feature References: ACCESS02 (Data Access Workflow), SEC06 (Access Control)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_access_requests (
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    request_number VARCHAR(50) GENERATED ALWAYS AS (
        'DAR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Requester
    requester_user_id UUID NOT NULL,
    requester_department VARCHAR(100),
    requester_justification TEXT NOT NULL,

    -- Requested access
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,                               -- Asset being requested
    asset_identifier VARCHAR(500),
    access_type socialcandor_schema.access_type NOT NULL,
    requested_expiry_date DATE,                            -- When access is no longer needed

    -- Risk assessment
    contains_sensitive_data BOOLEAN DEFAULT FALSE,
    risk_level VARCHAR(20) CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),

    -- Dates
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status socialcandor_schema.access_request_status NOT NULL DEFAULT 'PENDING',
    status_reason TEXT,                                    -- Reason for rejection/cancellation

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_access_requests_requester FOREIGN KEY (requester_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_access_requests_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_access_requests_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_access_requests_expiry CHECK (expires_at IS NULL OR expires_at > requested_at)
);

COMMENT ON TABLE socialcandor_schema.data_access_requests IS 'Manages user requests for access to data assets, enabling self-service workflow.';
COMMENT ON COLUMN socialcandor_schema.data_access_requests.requester_justification IS 'Business justification for the access request.';
COMMENT ON COLUMN socialcandor_schema.data_access_requests.contains_sensitive_data IS 'Flag indicating if the requested asset contains sensitive data (PII, PHI, etc.).';

-- Indexes for performance
CREATE INDEX idx_data_access_requests_requester ON socialcandor_schema.data_access_requests(requester_user_id, requested_at DESC);
CREATE INDEX idx_data_access_requests_status ON socialcandor_schema.data_access_requests(status, requested_at) WHERE status = 'PENDING';
CREATE INDEX idx_data_access_requests_asset ON socialcandor_schema.data_access_requests(asset_type, asset_id, status);
CREATE INDEX idx_data_access_requests_expiry ON socialcandor_schema.data_access_requests(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_data_access_requests_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_access_requests
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG10 - data_access_approvals
-- Description: Records approvals (or rejections) for data access requests, including
--              approver, decision, and conditions. Supports multi-level approval workflows.
-- Business Case: Access requests often require one or more approvals from data owners, stewards,
--                or security teams. This table captures each approval step, including the
--                approver's identity, decision (approve/reject), timestamp, and any conditions
--                (e.g., "approved for 30 days only"). The design supports sequential approvals
--                (e.g., manager then steward) by linking to the request and maintaining an
--                approval order. This provides a complete audit trail for compliance audits
--                and helps track the efficiency of the approval process.
-- KPIs:
--   1. Approval steps: Average number of approvals per request
--   2. Approver workload: Number of pending approvals per approver
--   3. Approval time by step: Time taken for each approval stage
--   4. Rejection rate by approver: % of requests rejected by each approver
--   5. Conditional approvals: % of approvals with conditions attached
-- Feature References: ACCESS02, SEC06
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_access_approvals (
    approval_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    approval_number VARCHAR(50) GENERATED ALWAYS AS (
        'DAA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- References
    request_id UUID NOT NULL,
    approver_user_id UUID NOT NULL,

    -- Approval details
    decision VARCHAR(20) NOT NULL CHECK (decision IN ('APPROVED', 'REJECTED', 'CONDITIONAL')),
    decision_reason TEXT,

    -- Conditions (if decision = 'CONDITIONAL')
    conditions TEXT,
    access_expiry_date DATE,                               -- Override requested expiry

    -- Workflow
    approval_order INTEGER DEFAULT 1,                       -- For sequential approvals
    is_final BOOLEAN DEFAULT FALSE,                         -- Whether this is the final approval needed

    -- Dates
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    responded_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_access_approvals_request FOREIGN KEY (request_id)
        REFERENCES socialcandor_schema.data_access_requests(request_id) ON DELETE CASCADE,
    CONSTRAINT fk_data_access_approvals_approver FOREIGN KEY (approver_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_access_approvals_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_access_approvals_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_access_approvals_dates CHECK (responded_at IS NULL OR responded_at >= submitted_at),
    CONSTRAINT uk_data_access_approvals UNIQUE (request_id, approval_order)
);

COMMENT ON TABLE socialcandor_schema.data_access_approvals IS 'Records approvals for data access requests, supporting multi-level workflows.';
COMMENT ON COLUMN socialcandor_schema.data_access_approvals.decision IS 'Approval decision (approved, rejected, conditional).';
COMMENT ON COLUMN socialcandor_schema.data_access_approvals.conditions IS 'Conditions attached to the approval (e.g., time limit, scope restrictions).';

-- Indexes for performance
CREATE INDEX idx_data_access_approvals_request ON socialcandor_schema.data_access_approvals(request_id);
CREATE INDEX idx_data_access_approvals_approver ON socialcandor_schema.data_access_approvals(approver_user_id, responded_at) WHERE responded_at IS NULL;
CREATE INDEX idx_data_access_approvals_pending ON socialcandor_schema.data_access_approvals(responded_at, approval_order) WHERE responded_at IS NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_data_access_approvals_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_access_approvals
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


-- =================================================================================================
-- Table: DG11 - data_usage_logs
-- Description: Audits access to data assets, capturing who accessed what, when, and from where.
--              Enables security monitoring and compliance reporting.
-- Business Case: For sensitive data, it is essential to track every access for security audits,
--                forensic investigations, and compliance with regulations like GDPR (right to access).
--                This table logs each data access event, including the user, asset, query, timestamp,
--                and context (IP, session). It can be populated by database audit logs, application
--                middleware, or data access gateways. The design supports different access types
--                (read, write, export) and captures the number of rows returned/affected for
--                volume analysis. Partitioning by month ensures query performance and enables
--                efficient data retention.
-- KPIs:
--   1. Access volume: Number of data accesses per day/week/month
--   2. Sensitive data access: % of accesses targeting classified data
--   3. Unusual access patterns: Number of anomalous access events flagged
--   4. Audit completeness: % of access events captured vs. total (if known)
--   5. Data breach detection: Time to detect unauthorized access
-- Feature References: AUD02 (Access Auditing), SEC08 (Security Monitoring)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_usage_logs (
    log_id BIGSERIAL,
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'DUL-' || TO_CHAR(access_time, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM access_time)::INT::TEXT, 6, '0')
    ) STORED,

    -- User context
    user_id UUID,
    session_id UUID,
    api_key_id UUID,

    -- Asset accessed
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,
    asset_identifier VARCHAR(500),

    -- Access details
    access_type socialcandor_schema.access_type NOT NULL,
    access_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    query_text TEXT,                                      -- SQL or API call (redacted if sensitive)
    rows_affected INTEGER CHECK (rows_affected >= 0),

    -- Source
    source_ip INET,
    user_agent TEXT,
    application_name VARCHAR(255),

    -- Classification of asset at time of access (snapshot)
    asset_classification socialcandor_schema.data_classification,
    contains_pii BOOLEAN DEFAULT FALSE,

    -- Outcome
    success BOOLEAN NOT NULL DEFAULT TRUE,
    error_message TEXT,

    -- Compliance
    is_anonymized BOOLEAN DEFAULT FALSE,                  -- Whether the log itself is anonymized after retention

    -- Partition key
    access_date DATE GENERATED ALWAYS AS (access_time::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_data_usage_logs PRIMARY KEY (log_id, access_date),
    CONSTRAINT fk_data_usage_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_usage_logs_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_usage_logs_api_key FOREIGN KEY (api_key_id)
        REFERENCES socialcandor_schema.api_keys(api_key_id) ON DELETE SET NULL
) PARTITION BY RANGE (access_date);

COMMENT ON TABLE socialcandor_schema.data_usage_logs IS 'Audits access to data assets for security monitoring and compliance.';
COMMENT ON COLUMN socialcandor_schema.data_usage_logs.query_text IS 'Full query text (may be redacted for sensitive data).';
COMMENT ON COLUMN socialcandor_schema.data_usage_logs.is_anonymized IS 'Indicates if the log has been anonymized for long-term retention.';

-- Create monthly partitions
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'data_usage_logs_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.data_usage_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes for performance
CREATE INDEX idx_data_usage_logs_user ON socialcandor_schema.data_usage_logs(user_id, access_time DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_data_usage_logs_asset ON socialcandor_schema.data_usage_logs(asset_type, asset_id, access_time DESC);
CREATE INDEX idx_data_usage_logs_ip ON socialcandor_schema.data_usage_logs(source_ip, access_time DESC) WHERE source_ip IS NOT NULL;
CREATE INDEX idx_data_usage_logs_classification ON socialcandor_schema.data_usage_logs(asset_classification, access_date) WHERE asset_classification IS NOT NULL;


-- =================================================================================================
-- Table: DG12 - data_contract_definitions
-- Description: Defines formal data contracts between producers and consumers, specifying schema,
--              quality expectations, SLAs, and change management policies.
-- Business Case: Data contracts are formal agreements between data producers and consumers that
--                define what data is provided, its structure, quality guarantees, and update
--                frequency. This table stores contract definitions, including schema, quality
--                SLAs (freshness, completeness), and change notice periods. It also tracks contract
--                versions and compliance status. This is a key enabler for data mesh architectures
--                and for building trust in data products. When a producer plans to change a schema,
--                affected consumers can be notified automatically based on the contract's change
--                notice period.
-- KPIs:
--   1. Contract coverage: % of critical data assets covered by contracts
--   2. Contract compliance: % of contracts meeting their SLAs
--   3. Breach frequency: Number of contract breaches per month
--   4. Change impact: Average number of consumers affected by schema changes
--   5. Contract age: Time since last contract review
-- Feature References: CONTRACT01 (Data Contracts), DQ07 (Data SLAs), MESH01 (Data Mesh)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_contract_definitions (
    contract_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    contract_number VARCHAR(50) GENERATED ALWAYS AS (
        'DCT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Contract identification
    contract_name VARCHAR(255) NOT NULL,
    contract_version VARCHAR(20) DEFAULT '1.0',
    contract_description TEXT,

    -- Parties
    producer_team VARCHAR(100) NOT NULL,
    producer_contact UUID,
    consumer_team VARCHAR(100) NOT NULL,
    consumer_contact UUID,

    -- Data asset
    asset_type socialcandor_schema.asset_type NOT NULL,
    asset_id UUID NOT NULL,
    asset_identifier VARCHAR(500),

    -- Schema definition
    schema_definition JSONB,                                -- Column names, types, descriptions
    sample_data_url VARCHAR(500),

    -- Quality SLAs
    freshness_sla_minutes INTEGER CHECK (freshness_sla_minutes >= 0),
    completeness_sla_percent NUMERIC(5,2) CHECK (completeness_sla_percent >= 0 AND completeness_sla_percent <= 100),
    accuracy_sla_percent NUMERIC(5,2) CHECK (accuracy_sla_percent >= 0 AND accuracy_sla_percent <= 100),

    -- Service Level Agreements
    availability_sla_percent NUMERIC(5,2) CHECK (availability_sla_percent >= 0 AND availability_sla_percent <= 100),
    latency_sla_seconds INTEGER CHECK (latency_sla_seconds >= 0),

    -- Change management
    change_notice_days INTEGER DEFAULT 30 CHECK (change_notice_days >= 0),
    review_frequency_days INTEGER DEFAULT 90,
    last_review_date DATE,
    next_review_date DATE GENERATED ALWAYS AS (last_review_date + (review_frequency_days || ' days')::INTERVAL) STORED,

    -- Status
    status socialcandor_schema.contract_status NOT NULL DEFAULT 'DRAFT',
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_active BOOLEAN GENERATED ALWAYS AS (
        status = 'ACTIVE' AND (effective_to IS NULL OR effective_to >= CURRENT_DATE)
    ) STORED,

    -- Compliance tracking
    compliance_status VARCHAR(30) DEFAULT 'COMPLIANT' CHECK (compliance_status IN ('COMPLIANT', 'AT_RISK', 'BREACHED')),
    breach_count INTEGER DEFAULT 0,
    last_breach_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_contract_definitions_producer FOREIGN KEY (producer_contact)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_contract_definitions_consumer FOREIGN KEY (consumer_contact)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_contract_definitions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_contract_definitions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_data_contract_definitions_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT chk_data_contract_definitions_sla CHECK (
        freshness_sla_minutes IS NOT NULL OR completeness_sla_percent IS NOT NULL
    )
);

COMMENT ON TABLE socialcandor_schema.data_contract_definitions IS 'Defines formal data contracts between producers and consumers with SLAs and change policies.';
COMMENT ON COLUMN socialcandor_schema.data_contract_definitions.schema_definition IS 'JSON schema defining the data structure (columns, types).';
COMMENT ON COLUMN socialcandor_schema.data_contract_definitions.compliance_status IS 'Current compliance status with the contract SLAs.';
COMMENT ON COLUMN socialcandor_schema.data_contract_definitions.change_notice_days IS 'Number of days notice required before making breaking changes.';

-- Indexes for performance
CREATE INDEX idx_data_contract_definitions_producer ON socialcandor_schema.data_contract_definitions(producer_team, status);
CREATE INDEX idx_data_contract_definitions_consumer ON socialcandor_schema.data_contract_definitions(consumer_team, status);
CREATE INDEX idx_data_contract_definitions_asset ON socialcandor_schema.data_contract_definitions(asset_type, asset_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_data_contract_definitions_review ON socialcandor_schema.data_contract_definitions(next_review_date) WHERE status = 'ACTIVE';

-- Trigger for updated_at
CREATE TRIGGER trg_data_contract_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_contract_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();


