CREATE OR REPLACE FUNCTION socialcandor_schema.is_admin() RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

