-- =================================================================================================
-- MATERIALIZED VIEW FOR IMPACT ANALYSIS
-- =================================================================================================

-- Materialized view to pre-aggregate data lineage impact: for each source, list all downstream targets
CREATE MATERIALIZED VIEW socialcandor_schema.mv_lineage_impact AS
WITH RECURSIVE lineage_tree AS (
    -- Base: direct dependencies
    SELECT
        source_type,
        source_id,
        target_type,
        target_id,
        transformation_type,
        1 AS depth,
        ARRAY[source_id] AS path
    FROM socialcandor_schema.data_lineage_mappings
    WHERE is_active = TRUE

    UNION ALL

    -- Recursive: dependencies of dependencies
    SELECT
        lt.source_type,
        lt.source_id,
        dl.target_type,
        dl.target_id,
        dl.transformation_type,
        lt.depth + 1,
        lt.path || dl.source_id
    FROM lineage_tree lt
    JOIN socialcandor_schema.data_lineage_mappings dl
        ON lt.target_type = dl.source_type
        AND lt.target_id = dl.source_id
        AND dl.is_active = TRUE
    WHERE lt.depth < 10  -- Limit depth to avoid infinite loops
)
SELECT
    source_type,
    source_id,
    target_type,
    target_id,
    MIN(depth) AS min_depth,
    MAX(depth) AS max_depth,
    COUNT(*) AS dependency_count,
    array_agg(DISTINCT transformation_type) AS transformation_types
FROM lineage_tree
GROUP BY source_type, source_id, target_type, target_id;

CREATE UNIQUE INDEX idx_mv_lineage_impact ON socialcandor_schema.mv_lineage_impact (source_type, source_id, target_type, target_id);
COMMENT ON MATERIALIZED VIEW socialcandor_schema.mv_lineage_impact IS 'Pre-aggregated data lineage impact showing all downstream dependencies.';



