-- -------------------------------------------------------------------------------------------------
-- Table: 1 - tenant_configurations
-- Description: Stores tenant‑specific configuration settings (branding, security policies, etc.)
--              in a flexible JSONB format. Supports versioning and environment segregation.
-- Business Case: Tenants require customisation of their experience without code changes.
--                Centralised configuration enables consistent management, auditability,
--                and gradual feature rollout across different environments (prod/staging).
--                Versioning tracks changes over time and supports rollbacks if needed.
--                JSONB allows arbitrary settings without schema changes, keeping the
--                platform extensible for future tenant needs.
-- KPIs:
--   1. Configuration change frequency – how often tenants update settings.
--   2. % of tenants with custom branding – adoption of white‑labelling.
--   3. Average number of overridden settings per tenant.
--   4. Configuration drift – settings mismatches between environments.
--   5. Time to propagate new settings to all tenants.
-- Feature References:
--   - ORG10 (Organization Configuration)
--   - ORG11 (White‑labeling)
--   - ORG12 (Feature Management)
--   - SEC25 (Tenant Security Policies)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_configurations (
    -- Primary key
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    config_number VARCHAR(50) GENERATED ALWAYS AS (
        'TNC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_config_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant reference (organization)
    organization_id UUID NOT NULL,

    -- Configuration metadata
    config_version INTEGER NOT NULL DEFAULT 1,
    environment VARCHAR(20) NOT NULL CHECK (environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'SANDBOX')),

    -- Actual settings (flexible JSON)
    settings JSONB NOT NULL DEFAULT '{}',

    -- Change reason (optional)
    change_reason TEXT,

    -- Effective dating (for versioning)
    effective_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    effective_to TIMESTAMP WITH TIME ZONE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_config_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_config_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_config_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_tenant_config_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT uk_tenant_config_org_version UNIQUE (organization_id, config_version, environment)
);

COMMENT ON TABLE socialcandor_schema.tenant_configurations IS 'Stores versioned configuration settings per tenant (branding, security, etc.) in JSONB.';
COMMENT ON COLUMN socialcandor_schema.tenant_configurations.settings IS 'JSON object containing all tenant‑specific settings.';
COMMENT ON COLUMN socialcandor_schema.tenant_configurations.config_version IS 'Version number for tracking changes.';
COMMENT ON COLUMN socialcandor_schema.tenant_configurations.is_current IS 'True if this configuration is the active one.';

-- Indexes
CREATE INDEX idx_tenant_config_org ON socialcandor_schema.tenant_configurations(organization_id, is_current) WHERE is_current = TRUE;
CREATE INDEX idx_tenant_config_env ON socialcandor_schema.tenant_configurations(environment, effective_from) WHERE is_current = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_configurations_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_configurations
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS policy (tenant isolation)
ALTER TABLE socialcandor_schema.tenant_configurations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_config_tenant_policy ON socialcandor_schema.tenant_configurations
    FOR ALL USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_config_admin_policy ON socialcandor_schema.tenant_configurations
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- -------------------------------------------------------------------------------------------------
-- Table: 2 - tenant_quotas
-- Description: Tracks resource usage and limits per tenant (users, storage, API calls, etc.)
--              with configurable thresholds for warnings and enforcement.
-- Business Case: Enforces fair usage based on subscription plans, prevents resource exhaustion,
--                and enables usage‑based billing. Real‑time monitoring alerts tenants before
--                they hit limits, reducing support incidents. Historical data helps capacity
--                planning and trend analysis.
-- KPIs:
--   1. Quota utilisation rate – average % of limit used.
--   2. Number of tenants exceeding quotas per month.
--   3. Average usage per tenant by resource type.
--   4. Quota enforcement incidents – times automatic actions were triggered.
--   5. Forecast accuracy – predicted vs. actual usage.
-- Feature References:
--   - ORG19 (Resource Quotas)
--   - ORG20 (Usage Monitoring)
--   - BIL08 (Usage‑based Billing)
--   - CAP01 (Capacity Planning)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_quotas (
    -- Primary key
    quota_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    quota_number VARCHAR(50) GENERATED ALWAYS AS (
        'TQT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_quotas_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant reference
    organization_id UUID NOT NULL,

    -- Resource definition
    resource_type VARCHAR(50) NOT NULL CHECK (resource_type IN (
        'SEATS', 'STORAGE_GB', 'API_CALLS', 'POSTS_MONTHLY', 'INTEGRATIONS', 'CUSTOM_DOMAINS', 'SSO_SEATS'
    )),

    -- Quota limits
    quota_limit BIGINT NOT NULL CHECK (quota_limit >= 0),
    usage_current BIGINT NOT NULL DEFAULT 0 CHECK (usage_current >= 0),
    usage_peak BIGINT DEFAULT 0 CHECK (usage_peak >= 0),

    -- Thresholds (percentages of limit)
    warning_threshold INTEGER CHECK (warning_threshold >= 0 AND warning_threshold <= 100),
    critical_threshold INTEGER CHECK (critical_threshold >= 0 AND critical_threshold <= 100),

    -- Alerting
    last_alert_at TIMESTAMP WITH TIME ZONE,
    warning_triggered BOOLEAN DEFAULT FALSE,
    critical_triggered BOOLEAN DEFAULT FALSE,

    -- Rolling period (e.g., for monthly quotas)
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    usage_reset_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_quotas_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_quotas_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_quotas_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_tenant_quotas_period CHECK (period_end >= period_start),
    CONSTRAINT chk_tenant_quotas_thresholds CHECK (
        (warning_threshold IS NULL AND critical_threshold IS NULL) OR
        (warning_threshold <= critical_threshold)
    ),
    CONSTRAINT uk_tenant_quotas_period UNIQUE (organization_id, resource_type, period_start)
);

COMMENT ON TABLE socialcandor_schema.tenant_quotas IS 'Tracks resource usage and limits per tenant, with warning/critical thresholds.';
COMMENT ON COLUMN socialcandor_schema.tenant_quotas.usage_current IS 'Current usage within the current period.';
COMMENT ON COLUMN socialcandor_schema.tenant_quotas.usage_peak IS 'Highest usage recorded (for capacity planning).';
COMMENT ON COLUMN socialcandor_schema.tenant_quotas.period_start IS 'Start of the current quota period (e.g., billing month).';

-- Indexes
CREATE INDEX idx_tenant_quotas_org ON socialcandor_schema.tenant_quotas(organization_id, resource_type, period_start DESC);
CREATE INDEX idx_tenant_quotas_threshold ON socialcandor_schema.tenant_quotas(resource_type, usage_current, quota_limit) WHERE warning_triggered = FALSE;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_quotas_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_quotas
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- Trigger to update alerts based on usage
CREATE OR REPLACE FUNCTION socialcandor_schema.update_quota_alerts()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.quota_limit > 0 THEN
        -- Warning threshold
        IF NEW.warning_threshold IS NOT NULL AND (NEW.usage_current * 100 / NEW.quota_limit) >= NEW.warning_threshold THEN
            NEW.warning_triggered := TRUE;
        ELSE
            NEW.warning_triggered := FALSE;
        END IF;
        -- Critical threshold
        IF NEW.critical_threshold IS NOT NULL AND (NEW.usage_current * 100 / NEW.quota_limit) >= NEW.critical_threshold THEN
            NEW.critical_triggered := TRUE;
        ELSE
            NEW.critical_triggered := FALSE;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_tenant_quotas_alerts
    BEFORE INSERT OR UPDATE OF usage_current, quota_limit ON socialcandor_schema.tenant_quotas
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_quota_alerts();

-- RLS
ALTER TABLE socialcandor_schema.tenant_quotas ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_quotas_tenant_policy ON socialcandor_schema.tenant_quotas
    FOR ALL USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_quotas_admin_policy ON socialcandor_schema.tenant_quotas
    FOR ALL USING (socialcandor_schema.is_admin());

-- -------------------------------------------------------------------------------------------------
-- Table: 3 - tenant_billing_accounts
-- Description: Aggregated billing information per tenant, including plan, payment methods,
--              invoices, and billing status. Supports consolidated invoicing for multi‑account tenants.
-- Business Case: Enterprises need a single billing relationship even when they have multiple
--                sub‑accounts. This table centralises billing details, automates invoice generation,
--                tracks payment status, and enables dunning workflows. Integration with payment
--                gateways ensures accurate financial records.
-- KPIs:
--   1. Monthly Recurring Revenue (MRR) per tenant.
--   2. Payment success rate.
--   3. Overdue invoice percentage.
--   4. Average days to payment.
--   5. Churn rate (billing account closures).
-- Feature References:
--   - BIL05 (Organization Billing)
--   - BIL06 (Consolidated Invoicing)
--   - BIL07 (Usage‑based Billing)
--   - PAY07 (Payment Processing)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_billing_accounts (
    -- Primary key
    billing_account_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    account_number VARCHAR(50) GENERATED ALWAYS AS (
        'TBA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_billing_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant (one‑to‑one)
    organization_id UUID NOT NULL UNIQUE,

    -- Subscription plan
    subscription_plan_id UUID,            -- Link to subscription_plans (if exists)
    plan_type socialcandor_schema.tenant_plan_type NOT NULL DEFAULT 'FREE',

    -- Billing status
    billing_status socialcandor_schema.tenant_billing_status NOT NULL DEFAULT 'TRIALING',

    -- Tax information
    tax_id VARCHAR(100),
    tax_id_type VARCHAR(20) CHECK (tax_id_type IN ('EIN', 'VAT', 'GST', 'OTHER')),

    -- Contact
    billing_email VARCHAR(255) NOT NULL,
    billing_phone VARCHAR(50),
    billing_address TEXT,

    -- Payment method (default)
    payment_method_id UUID,

    -- Currency
    currency CHAR(3) NOT NULL DEFAULT 'USD',

    -- Dates
    trial_ends_at DATE,
    next_billing_date DATE,
    last_invoice_date DATE,
    billing_cycle_start DATE,
    billing_cycle_end DATE,

    -- Dunning / delinquency
    dunning_count INTEGER DEFAULT 0 CHECK (dunning_count >= 0),
    last_dunning_at TIMESTAMP WITH TIME ZONE,
    suspension_date DATE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_billing_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_billing_plan FOREIGN KEY (subscription_plan_id)
        REFERENCES socialcandor_schema.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_billing_payment_method FOREIGN KEY (payment_method_id)
        REFERENCES socialcandor_schema.payment_methods(payment_method_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_billing_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_billing_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_tenant_billing_dates CHECK (trial_ends_at IS NULL OR trial_ends_at > CURRENT_DATE)
);

COMMENT ON TABLE socialcandor_schema.tenant_billing_accounts IS 'Consolidated billing accounts for tenants, tracking plan, payments, and status.';
COMMENT ON COLUMN socialcandor_schema.tenant_billing_accounts.billing_cycle_start IS 'Start of current billing cycle.';
COMMENT ON COLUMN socialcandor_schema.tenant_billing_accounts.billing_cycle_end IS 'End of current billing cycle.';

-- Indexes
CREATE INDEX idx_tenant_billing_status ON socialcandor_schema.tenant_billing_accounts(billing_status, next_billing_date) WHERE billing_status IN ('ACTIVE', 'TRIALING');
CREATE INDEX idx_tenant_billing_plan ON socialcandor_schema.tenant_billing_accounts(plan_type);
CREATE INDEX idx_tenant_billing_payment ON socialcandor_schema.tenant_billing_accounts(payment_method_id) WHERE payment_method_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_billing_accounts_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_billing_accounts
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.tenant_billing_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_billing_tenant_policy ON socialcandor_schema.tenant_billing_accounts
    FOR SELECT USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_billing_admin_policy ON socialcandor_schema.tenant_billing_accounts
    FOR ALL USING (socialcandor_schema.is_admin());

