-- Table: 4 - tenant_user_mappings
-- Description: Maps users to tenants (organizations) with roles, departments, and membership
--              lifecycle. Supports users belonging to multiple tenants.
-- Business Case: In a multi‑tenant platform, a user can be part of several organisations
--                (e.g., as employee of company A and consultant for company B). This table
--                manages those relationships, roles, and permissions. It enables tenant‑specific
--                access control, department‑level grouping, and manager hierarchies. Historical
--                tracking supports compliance audits and access reviews.
-- KPIs:
--   1. Number of users per tenant.
--   2. Average tenants per user.
--   3. Role distribution across tenants.
--   4. Active vs. inactive memberships.
--   5. Cross‑tenant collaboration rate.
-- Feature References:
--   - ORG07 (Organization Members)
--   - ORG08 (Role‑Based Access Control)
--   - ORG09 (Department Management)
--   - ACC04 (Cost Center Allocation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_user_mappings (
    -- Primary key
    mapping_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    mapping_number VARCHAR(50) GENERATED ALWAYS AS (
        'TUM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_user_mappings_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant and user
    organization_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Role and permissions
    role VARCHAR(50) NOT NULL CHECK (role IN ('OWNER', 'ADMIN', 'MEMBER', 'BILLING_MANAGER', 'GUEST', 'AUDITOR')),

    -- Organisational details
    department VARCHAR(100),
    job_title VARCHAR(200),
    manager_user_id UUID,           -- Reporting manager within the tenant

    -- Membership lifecycle
    joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    left_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,

    -- Invitation metadata
    invited_by UUID,
    invited_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,
    approved_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_user_mappings_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_user_mappings_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_user_mappings_manager FOREIGN KEY (manager_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_user_mappings_invited_by FOREIGN KEY (invited_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_user_mappings_approved_by FOREIGN KEY (approved_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_user_mappings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_user_mappings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_tenant_user_mappings_active UNIQUE (organization_id, user_id) WHERE is_active = TRUE,
    CONSTRAINT chk_tenant_user_mappings_dates CHECK (left_at IS NULL OR left_at > joined_at)
);

COMMENT ON TABLE socialcandor_schema.tenant_user_mappings IS 'Maps users to tenants with roles, department, and membership lifecycle.';
COMMENT ON COLUMN socialcandor_schema.tenant_user_mappings.manager_user_id IS 'User ID of the manager within the tenant.';

-- Indexes
CREATE INDEX idx_tenant_user_mappings_org ON socialcandor_schema.tenant_user_mappings(organization_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_tenant_user_mappings_user ON socialcandor_schema.tenant_user_mappings(user_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_tenant_user_mappings_role ON socialcandor_schema.tenant_user_mappings(role) WHERE is_active = TRUE;
CREATE INDEX idx_tenant_user_mappings_department ON socialcandor_schema.tenant_user_mappings(department) WHERE department IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_user_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_user_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.tenant_user_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_user_mappings_self_policy ON socialcandor_schema.tenant_user_mappings
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY tenant_user_mappings_tenant_policy ON socialcandor_schema.tenant_user_mappings
    FOR ALL USING (organization_id = current_setting('app.current_tenant_id')::UUID);
