    FOR ALL USING (socialcandor_schema.is_admin());

-- -------------------------------------------------------------------------------------------------
-- Table: 5 - tenant_feature_flags
-- Description: Per‑tenant toggles for enabling/disabling features gradually or for specific customers.
-- Business Case: Allows controlled rollout of features, canary testing, and per‑customer
--                customisation without code changes. Flags can be simple booleans or complex
--                JSON values (e.g., configuration for beta features). Supports experimentation
--                and A/B testing at the tenant level.
-- KPIs:
--   1. Feature adoption rate – % of tenants with a flag enabled.
--   2. Number of flags per tenant.
--   3. Flag change frequency.
--   4. Time from flag creation to enablement.
--   5. Impact on support tickets for flagged features.
-- Feature References:
--   - ORG12 (Feature Management)
--   - EXP01 (Experimentation)
--   - SYS05 (Feature Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_feature_flags (
    -- Primary key
    flag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    flag_number VARCHAR(50) GENERATED ALWAYS AS (
        'TFF-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_feature_flags_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant
    organization_id UUID NOT NULL,

    -- Feature identification
    flag_key VARCHAR(100) NOT NULL,
    flag_description TEXT,

    -- Value (can be boolean or complex JSON)
    flag_value JSONB NOT NULL DEFAULT 'true',
    enabled BOOLEAN GENERATED ALWAYS AS (
        CASE WHEN flag_value IS NOT NULL AND flag_value ? 'enabled'
             THEN (flag_value->>'enabled')::BOOLEAN
             ELSE flag_value::BOOLEAN
        END
    ) STORED,

    -- Gradual rollout (0-100%)
    rollout_percentage INTEGER CHECK (rollout_percentage >= 0 AND rollout_percentage <= 100),

    -- Time constraints
    valid_from TIMESTAMP WITH TIME ZONE,
    valid_to TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (
        (valid_from IS NULL OR valid_from <= CURRENT_TIMESTAMP) AND
        (valid_to IS NULL OR valid_to >= CURRENT_TIMESTAMP)
    ) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_feature_flags_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_feature_flags_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_feature_flags_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_tenant_feature_flags_dates CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT uk_tenant_feature_flags UNIQUE (organization_id, flag_key)
);

COMMENT ON TABLE socialcandor_schema.tenant_feature_flags IS 'Per‑tenant feature toggles with optional gradual rollout and time windows.';
COMMENT ON COLUMN socialcandor_schema.tenant_feature_flags.flag_value IS 'JSON value – can be boolean or object with nested config.';
COMMENT ON COLUMN socialcandor_schema.tenant_feature_flags.enabled IS 'Derived boolean indicating if the feature is considered enabled.';

-- Indexes
CREATE INDEX idx_tenant_feature_flags_org ON socialcandor_schema.tenant_feature_flags(organization_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_tenant_feature_flags_key ON socialcandor_schema.tenant_feature_flags(flag_key, rollout_percentage) WHERE rollout_percentage IS NOT NULL;
CREATE INDEX idx_tenant_feature_flags_dates ON socialcandor_schema.tenant_feature_flags(valid_from, valid_to) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_feature_flags_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_feature_flags
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.tenant_feature_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_feature_flags_tenant_policy ON socialcandor_schema.tenant_feature_flags
    FOR SELECT USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_feature_flags_admin_policy ON socialcandor_schema.tenant_feature_flags
    FOR ALL USING (socialcandor_schema.is_admin());

-- -------------------------------------------------------------------------------------------------
-- Table: 6 - tenant_domain_mappings
-- Description: Maps custom domains to tenants, including DNS verification and SSL certificate status.
-- Business Case: Tenants often want to use their own domain for branding (e.g., company.socialcandor.com)
--                or a fully custom domain (e.g., app.company.com). This table manages domain
--                ownership verification via DNS tokens, tracks SSL certificate issuance/renewal,
--                and supports primary domain designation. Proper domain mapping is critical for
--                white‑labelling, email routing, and SSO integration.
-- KPIs:
--   1. Number of custom domains per tenant.
--   2. Domain verification success rate.
--   3. SSL certificate expiry tracking – % renewed before expiry.
--   4. Time from domain addition to verified.
--   5. Domain churn rate.
-- Feature References:
--   - ORG13 (Domain Management)
--   - ORG14 (SSO Integration)
--   - AUTH06 (Domain‑based Authentication)
--   - EMAIL03 (Domain Email Routing)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_domain_mappings (
    -- Primary key
    domain_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    domain_number VARCHAR(50) GENERATED ALWAYS AS (
        'TDM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_domain_mappings_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant
    organization_id UUID NOT NULL,

    -- Domain details
    domain_name VARCHAR(255) NOT NULL,
    is_primary BOOLEAN DEFAULT FALSE,

    -- Verification
    verification_status socialcandor_schema.tenant_domain_verification_status NOT NULL DEFAULT 'PENDING',
    verification_token VARCHAR(255),
    verification_method VARCHAR(50) CHECK (verification_method IN ('DNS_TXT', 'DNS_CNAME', 'HTML_FILE', 'EMAIL')),
    verified_at TIMESTAMP WITH TIME ZONE,
    verification_attempts INTEGER DEFAULT 0 CHECK (verification_attempts >= 0),

    -- SSL/TLS
    ssl_status VARCHAR(30) CHECK (ssl_status IN ('PENDING', 'ISSUED', 'EXPIRED', 'FAILED')),
    ssl_issuer VARCHAR(255),
    ssl_expires_at DATE,
    ssl_last_renewed_at DATE,

    -- DNS records (for auto‑configuration)
    dns_records JSONB DEFAULT '[]',

    -- Effective dates
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Audit columns
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_domain_mappings_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_domain_mappings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_domain_mappings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_tenant_domain_mappings_domain UNIQUE (domain_name)
);

COMMENT ON TABLE socialcandor_schema.tenant_domain_mappings IS 'Custom domain mappings for tenants with DNS verification and SSL tracking.';
COMMENT ON COLUMN socialcandor_schema.tenant_domain_mappings.dns_records IS 'JSON array of DNS records to be configured for the domain.';

-- Indexes
CREATE INDEX idx_tenant_domain_mappings_org ON socialcandor_schema.tenant_domain_mappings(organization_id, is_primary) WHERE is_primary = TRUE;
CREATE INDEX idx_tenant_domain_mappings_verification ON socialcandor_schema.tenant_domain_mappings(verification_status) WHERE verification_status != 'VERIFIED';
CREATE INDEX idx_tenant_domain_mappings_ssl ON socialcandor_schema.tenant_domain_mappings(ssl_expires_at) WHERE ssl_status = 'ISSUED';

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_domain_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_domain_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.tenant_domain_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_domain_mappings_tenant_policy ON socialcandor_schema.tenant_domain_mappings
    FOR ALL USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_domain_mappings_admin_policy ON socialcandor_schema.tenant_domain_mappings
    FOR ALL USING (socialcandor_schema.is_admin());

-- -------------------------------------------------------------------------------------------------
-- Table: 7 - tenant_sso_configurations
-- Description: Stores Single Sign‑On (SSO) configurations per tenant, supporting various providers
--              (SAML, OIDC, Google, Microsoft) with metadata and attribute mappings.
-- Business Case: Enterprise tenants require SSO for secure and convenient authentication.
--                This table stores provider‑specific settings (entity ID, SSO URL, certificates,
--                attribute mappings) and enables tenants to configure their own identity providers.
--                It also tracks certificate expiry to avoid authentication outages.
-- KPIs:
--   1. Number of tenants with SSO enabled.
--   2. SSO usage rate – % of logins via SSO.
--   3. Authentication success rate.
--   4. Certificate expiry warnings – proactive alerts.
--   5. Average time to configure SSO.
-- Feature References:
--   - ORG14 (SSO Integration)
--   - AUTH07 (Token‑based Authentication)
--   - SEC27 (Session Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_sso_configurations (
    -- Primary key
    sso_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    sso_number VARCHAR(50) GENERATED ALWAYS AS (
        'TSSO-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_sso_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant (one‑to‑one)
    organization_id UUID NOT NULL UNIQUE,

    -- Provider
    provider socialcandor_schema.tenant_sso_provider NOT NULL,

    -- SAML / OIDC endpoints
    entity_id VARCHAR(500),
    sso_url VARCHAR(500),
    slo_url VARCHAR(500),              -- Single Logout URL
    metadata_url VARCHAR(500),
    certificate TEXT,                   -- X.509 certificate
    certificate_expires_at DATE,

    -- OIDC specific
    client_id VARCHAR(255),
    client_secret_encrypted TEXT,       -- Encrypted with master key
    authorization_endpoint VARCHAR(500),
    token_endpoint VARCHAR(500),
    userinfo_endpoint VARCHAR(500),
    jwks_uri VARCHAR(500),

    -- Attribute mappings (e.g., email -> email, first_name -> given_name)
    attribute_mappings JSONB DEFAULT '{}',

    -- Default role for new SSO users
    default_role VARCHAR(50),

    -- Status
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    config_version INTEGER DEFAULT 1,
    last_tested_at TIMESTAMP WITH TIME ZONE,
    last_test_result BOOLEAN,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_tenant_sso_configurations_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_sso_configurations_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_tenant_sso_configurations_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_tenant_sso_certificate CHECK (
        (certificate IS NOT NULL AND provider IN ('SAML', 'CUSTOM')) OR
        (certificate IS NULL AND provider NOT IN ('SAML', 'CUSTOM'))
    )
);

COMMENT ON TABLE socialcandor_schema.tenant_sso_configurations IS 'SSO configurations per tenant, supporting SAML, OIDC, and other providers.';
COMMENT ON COLUMN socialcandor_schema.tenant_sso_configurations.attribute_mappings IS 'JSON mapping of provider attributes to platform user fields.';
COMMENT ON COLUMN socialcandor_schema.tenant_sso_configurations.client_secret_encrypted IS 'Encrypted client secret for OIDC.';

-- Indexes
CREATE INDEX idx_tenant_sso_enabled ON socialcandor_schema.tenant_sso_configurations(enabled, provider) WHERE enabled = TRUE;
CREATE INDEX idx_tenant_sso_cert_expiry ON socialcandor_schema.tenant_sso_configurations(certificate_expires_at) WHERE certificate_expires_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_tenant_sso_configurations_updated_at
    BEFORE UPDATE ON socialcandor_schema.tenant_sso_configurations
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.tenant_sso_configurations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_sso_tenant_policy ON socialcandor_schema.tenant_sso_configurations
    FOR SELECT USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_sso_admin_policy ON socialcandor_schema.tenant_sso_configurations
    FOR ALL USING (socialcandor_schema.is_admin());

-- -------------------------------------------------------------------------------------------------
-- Table: 8 - tenant_audit_logs
-- Description: Tenant‑isolated audit trail of all significant actions within a tenant's context,
--              with before/after state snapshots. Partitioned by date for performance.
-- Business Case: Compliance frameworks (SOC2, GDPR) require detailed audit logs of who did what,
--                when, and from where. This table records actions like user membership changes,
--                configuration updates, billing events, and security settings modifications.
--                Partitioning by month ensures query performance and enables efficient data
--                retention policies. Snapshots allow reconstructing past states.
-- KPIs:
--   1. Audit log volume per tenant.
--   2. Query performance – time to retrieve history.
--   3. Retention compliance – % of logs retained per policy.
--   4. Anomaly detection rate – suspicious patterns identified.
--   5. Storage growth trend.
-- Feature References:
--   - ORG18 (Organization Audit)
--   - COMP14 (Compliance Auditing)
--   - SEC26 (Security Monitoring)
--   - GDPR14 (Data Processing Records)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.tenant_audit_logs (
    -- Primary key (BIGSERIAL for partitioning)
    log_id BIGSERIAL,

    -- Human‑readable identifier
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'TAUD-' || TO_CHAR(occurred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.tenant_audit_logs_seq')::TEXT, 6, '0')
    ) STORED,

    -- Tenant and actor
    organization_id UUID NOT NULL,
    user_id UUID,                -- Actor (NULL for system actions)
    session_id UUID,

    -- Action classification
    action_type VARCHAR(100) NOT NULL,
    action_category socialcandor_schema.tenant_audit_action_category NOT NULL,
    action_status VARCHAR(20) CHECK (action_status IN ('SUCCESS', 'FAILURE', 'ATTEMPT')),

    -- Target
    target_type VARCHAR(50),     -- e.g., 'USER', 'CONFIG', 'DOMAIN'
    target_id UUID,               -- ID of the affected resource

    -- State changes
    before_state JSONB,
    after_state JSONB,
    changes JSONB,                -- Specific field changes (optional)

    -- Context
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ip_address INET,
    user_agent TEXT,
    request_id UUID,              -- For request tracing

    -- Additional metadata
    metadata JSONB DEFAULT '{}',

    -- Partition key
    occurred_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_tenant_audit_logs PRIMARY KEY (log_id, occurred_date),
    CONSTRAINT fk_tenant_audit_logs_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_tenant_audit_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_tenant_audit_logs_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
) PARTITION BY RANGE (occurred_date);

COMMENT ON TABLE socialcandor_schema.tenant_audit_logs IS 'Tenant‑isolated audit log with before/after snapshots, partitioned by date.';
COMMENT ON COLUMN socialcandor_schema.tenant_audit_logs.before_state IS 'JSON snapshot of resource state before the action.';
COMMENT ON COLUMN socialcandor_schema.tenant_audit_logs.after_state IS 'JSON snapshot of resource state after the action.';
COMMENT ON COLUMN socialcandor_schema.tenant_audit_logs.changes IS 'Specific fields that changed (old/new).';

-- Create monthly partitions (example for current and next two months)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..2 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'tenant_audit_logs_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.tenant_audit_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes on parent (will be inherited by partitions)
CREATE INDEX idx_tenant_audit_logs_org ON socialcandor_schema.tenant_audit_logs(organization_id, occurred_at DESC);
CREATE INDEX idx_tenant_audit_logs_user ON socialcandor_schema.tenant_audit_logs(user_id, occurred_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_tenant_audit_logs_category ON socialcandor_schema.tenant_audit_logs(action_category, occurred_at DESC);
CREATE INDEX idx_tenant_audit_logs_target ON socialcandor_schema.tenant_audit_logs(target_type, target_id) WHERE target_id IS NOT NULL;

-- RLS
ALTER TABLE socialcandor_schema.tenant_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_audit_logs_tenant_policy ON socialcandor_schema.tenant_audit_logs
    FOR SELECT USING (organization_id = current_setting('app.current_tenant_id')::UUID);
CREATE POLICY tenant_audit_logs_admin_policy ON socialcandor_schema.tenant_audit_logs
    FOR ALL USING (socialcandor_schema.is_admin());



