-- Enum: 201 - analytics_event_type
-- Description: Defines the types of events tracked in the analytics_event_streams table.
-- Business Case: Enables consistent categorization of user actions for funnel analysis, cohort tracking,
--                and behavioral analytics. Supports filtering and aggregation by event type.
-- Feature Reference: ANL22 (Event Tracking)
-- =================================================================================================
CREATE TYPE socialcandor_schema.analytics_event_type AS ENUM (
    'PAGE_VIEW',
    'BUTTON_CLICK',
    'FORM_SUBMIT',
    'SEARCH',
    'LOGIN',
    'LOGOUT',
    'SIGNUP',
    'POST_CREATE',
    'POST_VIEW',
    'POST_LIKE',
    'POST_COMMENT',
    'POST_SHARE',
    'MESSAGE_SEND',
    'MESSAGE_READ',
    'NOTIFICATION_CLICK',
    'PURCHASE_START',
    'PURCHASE_COMPLETE',
    'CHECKOUT_STEP',
    'ADD_TO_CART',
    'REMOVE_FROM_CART',
    'APPLY_PROMO',
    'VIEW_PRODUCT',
    'VIEW_CATEGORY',
    'FOLLOW_USER',
    'UNFOLLOW_USER',
    'JOIN_GROUP',
    'LEAVE_GROUP',
    'EXPORT_DATA',
    'API_CALL'
);
COMMENT ON TYPE socialcandor_schema.analytics_event_type IS 'Types of events tracked for analytics and funnel analysis';

-- Enum: 202 - funnel_step_type
-- Description: Defines the types of steps within a conversion funnel.
-- Business Case: Categorizes funnel steps to differentiate between start, middle, and completion steps,
--                enabling clear visualization of user progression and drop-off points.
-- Feature Reference: ANL23 (Funnel Analysis)
-- =================================================================================================
CREATE TYPE socialcandor_schema.funnel_step_type AS ENUM (
    'ENTRY',
    'PROGRESS',
    'CONVERSION',
    'EXIT'
);
COMMENT ON TYPE socialcandor_schema.funnel_step_type IS 'Types of steps within a conversion funnel';

-- Enum: 203 - attribution_model_type
-- Description: Defines the attribution models used to assign credit to marketing touchpoints.
-- Business Case: Supports various industry-standard attribution models (first‑touch, last‑touch, linear,
--                time‑decay, U‑shaped) for accurate campaign performance measurement.
-- Feature Reference: ANL24 (Attribution Modeling)
-- =================================================================================================
CREATE TYPE socialcandor_schema.attribution_model_type AS ENUM (
    'FIRST_TOUCH',
    'LAST_TOUCH',
    'LINEAR',
    'TIME_DECAY',
    'U_SHAPED',
    'CUSTOM'
);
COMMENT ON TYPE socialcandor_schema.attribution_model_type IS 'Attribution models used to assign credit to marketing touchpoints';

-- Enum: 204 - report_format
-- Description: Defines the output formats available for scheduled reports.
-- Business Case: Allows users to choose preferred report formats (PDF, CSV, Excel, HTML) for consumption.
-- Feature Reference: RPT01 (Reporting)
-- =================================================================================================
CREATE TYPE socialcandor_schema.report_format AS ENUM (
    'PDF',
