-- =================================================================================================
-- TABLE: 201 - analytics_event_streams
-- Description: Real‑time event stream capturing user interactions and system events for analytics.
-- Business Case: Every user action generates an event that feeds into analytics, product insights,
--                funnel analysis, and machine learning pipelines. This table acts as the central
--                repository for all raw behavioural data. Its design supports high‑velocity inserts
--                (partitioned by date) and efficient querying of recent events. The data is used to
--                understand user journeys, detect anomalies, measure feature adoption, and train
--                recommendation models. By capturing detailed context (page, session, device), we can
--                perform deep segmentation and attribution analysis. This foundational table enables
--                data‑driven decisions across product, marketing, and engineering teams.
-- KPIs:
--   1. Event volume per day (by type)
--   2. Unique users per day
--   3. Average events per session
--   4. Peak event throughput (events/minute)
--   5. Data latency (time from event occurrence to table insertion)
-- Feature References: ANL22 (Event Tracking), ANL25 (Real‑time Analytics), PIP03 (Data Ingestion)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.analytics_event_streams (
    -- Primary key (using BIGSERIAL for high throughput, partitioned)
    event_id BIGSERIAL,

    -- Human‑readable identifier
    event_number VARCHAR(50) GENERATED ALWAYS AS (
        'EVT-' || TO_CHAR(event_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.analytics_event_stream_seq')::TEXT, 6, '0')
    ) STORED,

    -- Core event attributes
    event_type socialcandor_schema.analytics_event_type NOT NULL,
    event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_id UUID,                                      -- NULL for anonymous events
    session_id UUID,                                   -- Session identifier

    -- Contextual data
    page_url VARCHAR(500),
    page_referrer VARCHAR(500),
    user_agent TEXT,
    ip_address INET,

    -- Device and platform
    device_type VARCHAR(50) CHECK (device_type IN ('DESKTOP', 'MOBILE', 'TABLET', 'BOT', 'OTHER')),
    browser VARCHAR(100),
    browser_version VARCHAR(50),
    os VARCHAR(100),
    os_version VARCHAR(50),

    -- Additional properties (flexible)
    properties JSONB NOT NULL DEFAULT '{}',             -- Event‑specific data (e.g., product_id, button_id)

    -- Geo information (enriched later)
    geo_country VARCHAR(3),
    geo_city VARCHAR(100),

    -- Attribution data
    utm_source VARCHAR(255),
    utm_medium VARCHAR(255),
    utm_campaign VARCHAR(255),
    utm_term VARCHAR(255),
    utm_content VARCHAR(255),

    -- Processing metadata
    processed_at TIMESTAMP WITH TIME ZONE,               -- When the event was ingested
    processor_version VARCHAR(50),

    -- Partition key
    event_date DATE GENERATED ALWAYS AS (event_time::DATE) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT pk_analytics_event_streams PRIMARY KEY (event_id, event_date),
    CONSTRAINT fk_analytics_event_streams_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_analytics_event_streams_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_analytics_event_streams_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_analytics_event_streams_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_analytics_event_time_not_future CHECK (event_time <= CURRENT_TIMESTAMP + INTERVAL '1 minute')
) PARTITION BY RANGE (event_date);

COMMENT ON TABLE socialcandor_schema.analytics_event_streams IS 'Real‑time event stream capturing user interactions and system events for analytics';
COMMENT ON COLUMN socialcandor_schema.analytics_event_streams.properties IS 'JSON object containing event‑specific data (e.g., product_id, button_id, search_query)';

-- Create daily partitions for the next 90 days
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..90 LOOP
        start_date := CURRENT_DATE + (i || ' days')::INTERVAL;
        end_date := start_date + '1 day'::INTERVAL;
        partition_name := 'analytics_event_streams_' || TO_CHAR(start_date, 'YYYY_MM_DD');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.analytics_event_streams
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes
CREATE INDEX idx_analytics_events_user ON socialcandor_schema.analytics_event_streams(user_id, event_time DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_analytics_events_session ON socialcandor_schema.analytics_event_streams(session_id, event_time DESC) WHERE session_id IS NOT NULL;
CREATE INDEX idx_analytics_events_type ON socialcandor_schema.analytics_event_streams(event_type, event_time DESC);
CREATE INDEX idx_analytics_events_utm ON socialcandor_schema.analytics_event_streams(utm_campaign, utm_source, event_time DESC);
CREATE INDEX idx_analytics_events_properties ON socialcandor_schema.analytics_event_streams USING GIN (properties);

-- Trigger for updated_at
CREATE TRIGGER trg_analytics_event_streams_updated_at
    BEFORE UPDATE ON socialcandor_schema.analytics_event_streams
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.analytics_event_streams ENABLE ROW LEVEL SECURITY;
CREATE POLICY analytics_event_streams_admin_policy ON socialcandor_schema.analytics_event_streams
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));
CREATE POLICY analytics_event_streams_analyst_policy ON socialcandor_schema.analytics_event_streams
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST')
    ));
CREATE POLICY analytics_event_streams_self_policy ON socialcandor_schema.analytics_event_streams
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);


-- =================================================================================================
-- TABLE: 202 - analytics_aggregations_hourly
-- Description: Hourly pre‑aggregated metrics from raw event streams for fast dashboarding and reporting.
-- Business Case: Raw event streams are too large for interactive queries. This table stores hourly
--                roll‑ups of key metrics (event counts, unique users, page views, conversions) by
--                various dimensions (event type, country, device). It serves as the backbone for
--                real‑time dashboards, reducing query times from minutes to milliseconds. The design
--                supports incremental updates and historical trend analysis. By pre‑aggregating at
--                the hour level, we balance freshness and query performance. These aggregates feed
--                into daily aggregates and higher‑level reports.
-- KPIs:
--   1. Query performance improvement (latency vs. raw table)
--   2. Aggregation coverage (percentage of events rolled up)
--   3. Data freshness (time since last aggregation)
--   4. Storage efficiency (compression ratio)
--   5. Granularity alignment with business cycles
-- Feature References: ANL26 (Aggregated Metrics), DASH06 (Dashboard Performance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.analytics_aggregations_hourly (
    -- Primary key
    aggregation_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    aggregation_number VARCHAR(50) GENERATED ALWAYS AS (
        'AGG-H-' || TO_CHAR(aggregation_hour, 'YYYYMMDDHH24') || '-' || LPAD(nextval('socialcandor_schema.analytics_aggregations_hourly_seq')::TEXT, 6, '0')
    ) STORED,

    -- Time dimension
    aggregation_hour TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Dimensions
    event_type socialcandor_schema.analytics_event_type,
    device_type VARCHAR(50),
    geo_country VARCHAR(3),
    utm_campaign VARCHAR(255),

    -- Metrics
    event_count INTEGER NOT NULL DEFAULT 0 CHECK (event_count >= 0),
    unique_users INTEGER NOT NULL DEFAULT 0 CHECK (unique_users >= 0),
    unique_sessions INTEGER NOT NULL DEFAULT 0 CHECK (unique_sessions >= 0),

    -- Additional metrics (can be extended)
    page_view_count INTEGER DEFAULT 0 CHECK (page_view_count >= 0),
    conversion_count INTEGER DEFAULT 0 CHECK (conversion_count >= 0),

    -- Processing metadata
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    data_lag_minutes INTEGER CHECK (data_lag_minutes >= 0),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_analytics_agg_hourly_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_analytics_agg_hourly_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_aggregation_hour_trunc CHECK (EXTRACT(MINUTE FROM aggregation_hour) = 0),
    CONSTRAINT chk_data_lag_positive CHECK (data_lag_minutes >= 0),

    CONSTRAINT uk_analytics_agg_hourly UNIQUE (aggregation_hour, event_type, device_type, geo_country, utm_campaign)
);

COMMENT ON TABLE socialcandor_schema.analytics_aggregations_hourly IS 'Hourly pre‑aggregated metrics from raw event streams for fast dashboarding';
COMMENT ON COLUMN socialcandor_schema.analytics_aggregations_hourly.aggregation_hour IS 'Hour boundary (always at minute 00)';

-- Indexes
CREATE INDEX idx_analytics_agg_hourly_time ON socialcandor_schema.analytics_aggregations_hourly(aggregation_hour DESC);
CREATE INDEX idx_analytics_agg_hourly_event_type ON socialcandor_schema.analytics_aggregations_hourly(event_type, aggregation_hour DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_analytics_aggregations_hourly_updated_at
    BEFORE UPDATE ON socialcandor_schema.analytics_aggregations_hourly
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.analytics_aggregations_hourly ENABLE ROW LEVEL SECURITY;
CREATE POLICY analytics_agg_hourly_admin_policy ON socialcandor_schema.analytics_aggregations_hourly
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY analytics_agg_hourly_analyst_policy ON socialcandor_schema.analytics_aggregations_hourly
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST', 'PRODUCT_MANAGER')
    ));


-- =================================================================================================
-- TABLE: 203 - analytics_aggregations_daily
-- Description: Daily pre‑aggregated metrics for trend analysis and long‑term reporting.
-- Business Case: While hourly data supports intra‑day monitoring, daily aggregates are the foundation
--                for week‑over‑week, month‑over‑month, and year‑over‑year trend analysis. This table
--                consolidates hourly data into daily summaries, reducing storage and query complexity.
--                It powers executive dashboards, board reports, and business reviews. The design
--                includes year‑over‑year comparison columns and handles roll‑ups across multiple
--                dimensions. Data retention policies can be applied independently from raw events.
-- KPIs:
--   1. Daily active users (DAU)
--   2. New users per day
--   3. Retention rate (day N)
--   4. Average session duration
--   5. Conversion rate (e.g., signup to first action)
-- Feature References: ANL27 (Trend Analysis), DASH07 (Executive Dashboards)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.analytics_aggregations_daily (
    -- Primary key
    aggregation_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    aggregation_number VARCHAR(50) GENERATED ALWAYS AS (
        'AGG-D-' || TO_CHAR(aggregation_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.analytics_aggregations_daily_seq')::TEXT, 6, '0')
    ) STORED,

    -- Time dimension
    aggregation_date DATE NOT NULL,

    -- Dimensions (NULL means overall totals)
    event_type socialcandor_schema.analytics_event_type,
    device_type VARCHAR(50),
    geo_country VARCHAR(3),
    utm_campaign VARCHAR(255),

    -- User metrics
    dau INTEGER NOT NULL DEFAULT 0 CHECK (dau >= 0),                           -- Daily Active Users
    mau_rolling INTEGER,                                                        -- Rolling 30‑day active users
    new_users INTEGER DEFAULT 0 CHECK (new_users >= 0),
    retained_users INTEGER DEFAULT 0 CHECK (retained_users >= 0),

    -- Engagement metrics
    total_events INTEGER DEFAULT 0 CHECK (total_events >= 0),
    total_sessions INTEGER DEFAULT 0 CHECK (total_sessions >= 0),
    avg_session_duration_seconds NUMERIC(10,2) CHECK (avg_session_duration_seconds >= 0),
    bounce_rate NUMERIC(5,2) CHECK (bounce_rate >= 0 AND bounce_rate <= 100),

    -- Conversion metrics
    total_conversions INTEGER DEFAULT 0 CHECK (total_conversions >= 0),
    conversion_rate NUMERIC(5,2) CHECK (conversion_rate >= 0 AND conversion_rate <= 100),

    -- Business metrics
    revenue NUMERIC(15,2) DEFAULT 0 CHECK (revenue >= 0),

    -- Processing metadata
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    data_lag_hours INTEGER CHECK (data_lag_hours >= 0),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_analytics_agg_daily_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_analytics_agg_daily_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_analytics_agg_daily UNIQUE (aggregation_date, event_type, device_type, geo_country, utm_campaign)
);

COMMENT ON TABLE socialcandor_schema.analytics_aggregations_daily IS 'Daily pre‑aggregated metrics for trend analysis and long‑term reporting';
COMMENT ON COLUMN socialcandor_schema.analytics_aggregations_daily.dau IS 'Daily Active Users';
COMMENT ON COLUMN socialcandor_schema.analytics_aggregations_daily.mau_rolling IS 'Rolling 30‑day active users (denormalised for performance)';

-- Indexes
CREATE INDEX idx_analytics_agg_daily_date ON socialcandor_schema.analytics_aggregations_daily(aggregation_date DESC);
CREATE INDEX idx_analytics_agg_daily_event ON socialcandor_schema.analytics_aggregations_daily(event_type, aggregation_date DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_analytics_aggregations_daily_updated_at
    BEFORE UPDATE ON socialcandor_schema.analytics_aggregations_daily
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.analytics_aggregations_daily ENABLE ROW LEVEL SECURITY;
CREATE POLICY analytics_agg_daily_admin_policy ON socialcandor_schema.analytics_aggregations_daily
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY analytics_agg_daily_analyst_policy ON socialcandor_schema.analytics_aggregations_daily
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST', 'PRODUCT_MANAGER', 'EXECUTIVE')
    ));


-- =================================================================================================
-- TABLE: 204 - user_cohort_definitions
-- Description: Stores definitions of user cohorts for segmentation and comparative analysis.
-- Business Case: Cohorts are groups of users who share a common characteristic or time period
--                (e.g., users who signed up in January 2025, users who performed a specific action).
--                This table stores the metadata and logic for each cohort, enabling reusable
--                segment definitions for product managers, marketers, and analysts. Cohorts can be
--                static (fixed membership) or dynamic (refreshed based on criteria). They are used
--                for retention analysis, feature adoption studies, and targeted campaigns.
-- KPIs:
--   1. Number of active cohorts
--   2. Cohort refresh frequency
--   3. Cohort size distribution
--   4. Cohort usage in reports
--   5. Cohort creation trend
-- Feature References: ANL28 (Cohort Analysis), SEG03 (User Segmentation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_cohort_definitions (
    -- Primary key
    cohort_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    cohort_number VARCHAR(50) GENERATED ALWAYS AS (
        'COH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_cohort_definitions_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic info
    cohort_name VARCHAR(255) NOT NULL,
    cohort_description TEXT,
    cohort_type VARCHAR(30) CHECK (cohort_type IN ('TIME_BASED', 'BEHAVIORAL', 'ATTRIBUTE_BASED', 'HYBRID')),

    -- Definition logic (can be SQL, criteria, etc.)
    definition JSONB NOT NULL,                     -- Flexible definition (e.g., {"signup_date": {"start": "2025-01-01", "end": "2025-01-31"}})

    -- Refresh settings
    refresh_frequency VARCHAR(20) CHECK (refresh_frequency IN ('NEVER', 'DAILY', 'WEEKLY', 'MONTHLY')),
    last_refreshed_at TIMESTAMP WITH TIME ZONE,
    next_refresh_at TIMESTAMP WITH TIME ZONE,
    is_dynamic BOOLEAN DEFAULT FALSE,               -- TRUE = membership changes over time

    -- Ownership
    owner_user_id UUID,
    owner_team VARCHAR(100),

    -- Usage stats
    usage_count INTEGER DEFAULT 0 CHECK (usage_count >= 0),
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_public BOOLEAN DEFAULT FALSE,                 -- Shared across teams

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_user_cohort_definitions_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_cohort_definitions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_cohort_definitions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.user_cohort_definitions IS 'Stores definitions of user cohorts for segmentation and analysis';
COMMENT ON COLUMN socialcandor_schema.user_cohort_definitions.definition IS 'JSON object defining cohort inclusion criteria';

-- Indexes
CREATE INDEX idx_user_cohort_definitions_owner ON socialcandor_schema.user_cohort_definitions(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX idx_user_cohort_definitions_active ON socialcandor_schema.user_cohort_definitions(is_active, is_public);

-- Trigger for updated_at
CREATE TRIGGER trg_user_cohort_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_cohort_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.user_cohort_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_cohort_definitions_owner_policy ON socialcandor_schema.user_cohort_definitions
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY user_cohort_definitions_public_policy ON socialcandor_schema.user_cohort_definitions
    FOR SELECT USING (is_public = TRUE);


-- =================================================================================================
-- TABLE: 205 - user_cohort_memberships
-- Description: Tracks which users belong to which cohorts, with membership start and end dates.
-- Business Case: This table materialises cohort memberships for efficient querying. For static cohorts,
--                membership is fixed; for dynamic cohorts, it is periodically refreshed. Tracking
--                membership periods allows analysing user behaviour before, during, and after cohort
--                membership (e.g., users who joined a beta feature). This data powers cohort retention
--                tables and enables personalised marketing based on cohort affiliation.
-- KPIs:
--   1. Average cohort size
--   2. Churn rate from cohorts
--   3. Overlap between cohorts
--   4. Cohort membership duration
--   5. Refresh latency for dynamic cohorts
-- Feature References: ANL28 (Cohort Analysis), SEG04 (Segment Memberships)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_cohort_memberships (
    -- Primary key
    membership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    membership_number VARCHAR(50) GENERATED ALWAYS AS (
        'CM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_cohort_memberships_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    cohort_id UUID NOT NULL,
    user_id UUID NOT NULL,

    -- Membership period
    joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    left_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,

    -- Membership metadata
    source VARCHAR(50) CHECK (source IN ('INITIAL', 'REFRESH', 'MANUAL', 'IMPORT')),
    membership_version INTEGER DEFAULT 1,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_user_cohort_memberships_cohort FOREIGN KEY (cohort_id)
        REFERENCES socialcandor_schema.user_cohort_definitions(cohort_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_cohort_memberships_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_cohort_memberships_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_cohort_memberships_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_user_cohort_membership UNIQUE (cohort_id, user_id, joined_at)
);

COMMENT ON TABLE socialcandor_schema.user_cohort_memberships IS 'Tracks which users belong to which cohorts, with membership start and end dates';
COMMENT ON COLUMN socialcandor_schema.user_cohort_memberships.joined_at IS 'Timestamp when user became a member of the cohort';
COMMENT ON COLUMN socialcandor_schema.user_cohort_memberships.left_at IS 'Timestamp when user left the cohort (NULL if still active)';

-- Indexes
CREATE INDEX idx_user_cohort_memberships_cohort ON socialcandor_schema.user_cohort_memberships(cohort_id, is_active);
CREATE INDEX idx_user_cohort_memberships_user ON socialcandor_schema.user_cohort_memberships(user_id, is_active);

-- Trigger for updated_at
CREATE TRIGGER trg_user_cohort_memberships_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_cohort_memberships
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.user_cohort_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_cohort_memberships_self_policy ON socialcandor_schema.user_cohort_memberships
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_cohort_memberships_analyst_policy ON socialcandor_schema.user_cohort_memberships
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST')
    ));
CREATE POLICY user_cohort_memberships_admin_policy ON socialcandor_schema.user_cohort_memberships
    FOR ALL USING (socialcandor_schema.is_admin());


-- =================================================================================================
-- TABLE: 206 - conversion_funnel_events
-- Description: Tracks user progression through defined conversion funnels, capturing each step
--              and the time taken between steps.
-- Business Case: Understanding where users drop off in key flows (signup, purchase, content creation)
--                is critical for conversion rate optimisation. This table logs every funnel step
--                completion per user, enabling funnel analysis, abandonment rate calculation,
--                and identification of friction points. It supports multi‑step funnels with
--                optional steps and branching. The data feeds into funnel visualisations and
--                alerts when conversion rates drop below thresholds.
-- KPIs:
--   1. Step completion rate
--   2. Drop‑off rate per step
--   3. Average time between steps
--   4. Overall funnel conversion rate
--   5. Funnel performance by user segment
-- Feature References: ANL23 (Funnel Analysis), ANL29 (Conversion Optimization)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.conversion_funnel_events (
    -- Primary key
    funnel_event_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    funnel_event_number VARCHAR(50) GENERATED ALWAYS AS (
        'FNEV-' || TO_CHAR(occurred_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.conversion_funnel_events_seq')::TEXT, 6, '0')
    ) STORED,

    -- Funnel identification
    funnel_id UUID NOT NULL,                                -- References conversion_funnel_definitions
    funnel_name VARCHAR(255),

    -- User identification
    user_id UUID,
    session_id UUID,

    -- Step information
    step_id UUID,                                           -- References funnel_steps
    step_name VARCHAR(255),
    step_order INTEGER CHECK (step_order >= 0),
    step_type socialcandor_schema.funnel_step_type,

    -- Timing
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    time_since_previous_step_seconds INTEGER CHECK (time_since_previous_step_seconds >= 0),

    -- Conversion tracking
    converted BOOLEAN DEFAULT FALSE,                         -- Whether this step led to conversion
    conversion_value NUMERIC(15,2),

    -- Context
    properties JSONB DEFAULT '{}',

    -- Partition key
    event_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_conversion_funnel_events_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_conversion_funnel_events_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT chk_funnel_event_time_not_future CHECK (occurred_at <= CURRENT_TIMESTAMP + INTERVAL '1 minute')
);

COMMENT ON TABLE socialcandor_schema.conversion_funnel_events IS 'Tracks user progression through defined conversion funnels';
COMMENT ON COLUMN socialcandor_schema.conversion_funnel_events.time_since_previous_step_seconds IS 'Time elapsed since previous funnel step (NULL for first step)';
COMMENT ON COLUMN socialcandor_schema.conversion_funnel_events.converted IS 'Whether this step eventually led to conversion';

-- Indexes
CREATE INDEX idx_conversion_funnel_events_funnel ON socialcandor_schema.conversion_funnel_events(funnel_id, occurred_at DESC);
CREATE INDEX idx_conversion_funnel_events_user ON socialcandor_schema.conversion_funnel_events(user_id, occurred_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_conversion_funnel_events_step ON socialcandor_schema.conversion_funnel_events(step_id, occurred_at DESC);
CREATE INDEX idx_conversion_funnel_events_converted ON socialcandor_schema.conversion_funnel_events(converted, occurred_at DESC);

-- RLS Policies (similar to event streams)
ALTER TABLE socialcandor_schema.conversion_funnel_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversion_funnel_events_self_policy ON socialcandor_schema.conversion_funnel_events
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY conversion_funnel_events_analyst_policy ON socialcandor_schema.conversion_funnel_events
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'PRODUCT_MANAGER')
    ));
CREATE POLICY conversion_funnel_events_admin_policy ON socialcandor_schema.conversion_funnel_events
    FOR ALL USING (socialcandor_schema.is_admin());


-- =================================================================================================
-- TABLE: 207 - attribution_models
-- Description: Defines attribution models for marketing touchpoints, including configuration
--              parameters and active status.
-- Business Case: Attribution models determine how credit for conversions is distributed across
--                marketing channels (email, social, paid search, etc.). This table stores the
--                definitions of models like first‑touch, last‑touch, linear, time‑decay, and
--                custom weighted models. Each model can have parameters (e.g., half‑life for
--                time‑decay). This centralised definition ensures consistent attribution across
--                reports and enables A/B testing of different attribution methodologies.
-- KPIs:
--   1. Number of active attribution models
--   2. Model usage in reports
--   3. Attribution consistency across channels
--   4. Model parameter optimisation frequency
-- Feature References: ANL24 (Attribution Modeling), MKT08 (Marketing Analytics)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.attribution_models (
    -- Primary key
    model_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    model_number VARCHAR(50) GENERATED ALWAYS AS (
        'ATTR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.attribution_models_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic info
    model_name VARCHAR(255) NOT NULL,
    model_description TEXT,
    model_type socialcandor_schema.attribution_model_type NOT NULL,

    -- Configuration
    parameters JSONB,                                       -- e.g., {"decay_half_life_days": 7, "weights": [0.4,0.3,0.2,0.1]}

    -- Scope
    applies_to_channels TEXT[],                              -- Which marketing channels this model applies to
    applies_to_conversion_types TEXT[],                      -- e.g., ['purchase', 'signup']

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_default BOOLEAN DEFAULT FALSE,
    version INTEGER DEFAULT 1,

    -- Ownership
    owner_user_id UUID,
    owner_team VARCHAR(100),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_attribution_models_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_attribution_models_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_attribution_models_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.attribution_models IS 'Defines attribution models for marketing touchpoints, including configuration parameters';
COMMENT ON COLUMN socialcandor_schema.attribution_models.parameters IS 'Model‑specific parameters (e.g., half‑life for time‑decay)';
COMMENT ON COLUMN socialcandor_schema.attribution_models.applies_to_channels IS 'Marketing channels this model applies to (NULL = all)';

-- Indexes
CREATE INDEX idx_attribution_models_active ON socialcandor_schema.attribution_models(is_active, is_default) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_attribution_models_updated_at
    BEFORE UPDATE ON socialcandor_schema.attribution_models
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.attribution_models ENABLE ROW LEVEL SECURITY;
CREATE POLICY attribution_models_owner_policy ON socialcandor_schema.attribution_models
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY attribution_models_read_policy ON socialcandor_schema.attribution_models
    FOR SELECT USING (is_active = TRUE);


-- =================================================================================================
-- TABLE: 208 - attribution_results
-- Description: Stores the results of attribution calculations, mapping each conversion to the
--              credited touchpoints with their respective weights.
-- Business Case: After applying an attribution model, we need to persist the results for reporting
--                and analysis. This table stores which marketing touchpoints received credit for
--                each conversion, along with the credit share. It enables marketers to understand
--                the true impact of each channel and optimise spend. The data supports ROAS
--                calculations, budget allocation decisions, and marketing mix modelling.
-- KPIs:
--   1. Channel contribution percentage
--   2. ROAS per channel
--   3. Attribution stability over time
--   4. Model comparison (how different models allocate credit)
--   5. Number of touchpoints per conversion
-- Feature References: ANL24 (Attribution Modeling), MKT09 (Marketing ROI)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.attribution_results (
    -- Primary key
    result_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    result_number VARCHAR(50) GENERATED ALWAYS AS (
        'ATTRR-' || TO_CHAR(computed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.attribution_results_seq')::TEXT, 6, '0')
    ) STORED,

    -- Model reference
    model_id UUID NOT NULL,
    model_version INTEGER,

    -- Conversion reference
    conversion_id UUID,                                     -- Could link to orders, signups, etc.
    conversion_type VARCHAR(50) CHECK (conversion_type IN ('ORDER', 'SIGNUP', 'LEAD', 'CUSTOM_EVENT')),
    conversion_value NUMERIC(15,2),
    conversion_time TIMESTAMP WITH TIME ZONE NOT NULL,

    -- User who converted
    user_id UUID,

    -- Attributed touchpoints (denormalised for performance)
    touchpoint_id UUID,                                     -- Could link to analytics_event_streams
    touchpoint_time TIMESTAMP WITH TIME ZONE,
    channel VARCHAR(100),                                   -- e.g., 'email', 'facebook', 'google_ads'
    campaign VARCHAR(255),
    source VARCHAR(255),
    medium VARCHAR(255),

    -- Attribution credit
    credit_share NUMERIC(10,8) CHECK (credit_share >= 0 AND credit_share <= 1),
    credited_amount NUMERIC(15,2) GENERATED ALWAYS AS (conversion_value * credit_share) STORED,

    -- Attribution position
    touchpoint_position INTEGER,                             -- Position in the conversion path
    total_touchpoints INTEGER,                               -- Total touchpoints in the path

    -- Computation metadata
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    computation_batch_id UUID,                               -- For reprocessing

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_attribution_results_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.attribution_models(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_attribution_results_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_attribution_results_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_attribution_results_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.attribution_results IS 'Stores results of attribution calculations, mapping conversions to credited touchpoints';
COMMENT ON COLUMN socialcandor_schema.attribution_results.credit_share IS 'Proportion of conversion credit assigned to this touchpoint (0‑1)';
COMMENT ON COLUMN socialcandor_schema.attribution_results.credited_amount IS 'Monetary value credited to this touchpoint (conversion_value * credit_share)';

-- Indexes
CREATE INDEX idx_attribution_results_model ON socialcandor_schema.attribution_results(model_id, conversion_time DESC);
CREATE INDEX idx_attribution_results_conversion ON socialcandor_schema.attribution_results(conversion_id, conversion_type);
CREATE INDEX idx_attribution_results_user ON socialcandor_schema.attribution_results(user_id, conversion_time DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_attribution_results_channel ON socialcandor_schema.attribution_results(channel, conversion_time DESC);
CREATE INDEX idx_attribution_results_batch ON socialcandor_schema.attribution_results(computation_batch_id);

-- Trigger for updated_at
CREATE TRIGGER trg_attribution_results_updated_at
    BEFORE UPDATE ON socialcandor_schema.attribution_results
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.attribution_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY attribution_results_analyst_policy ON socialcandor_schema.attribution_results
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'MARKETING')
    ));
CREATE POLICY attribution_results_admin_policy ON socialcandor_schema.attribution_results
    FOR ALL USING (socialcandor_schema.is_admin());


-- =================================================================================================
-- TABLE: 209 - report_definitions
-- Description: Stores templates and configurations for reusable reports.
-- Business Case: Business users need consistent, parameterised reports without writing SQL each time.
--                This table stores report definitions, including SQL or query logic, parameters,
--                visualisation preferences, and access controls. Reports can be scheduled (see
--                report_schedules) or run on‑demand. The design supports multiple output formats
--                and destinations (email, Slack, S3). This empowers teams to build a self‑service
--                analytics culture, reducing dependency on data engineers.
-- KPIs:
--   1. Number of active report definitions
--   2. Report usage frequency
--   3. Average report execution time
--   4. User satisfaction with reports
--   5. Report creation trend
-- Feature References: RPT01 (Reporting), RPT03 (Self‑service Analytics)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.report_definitions (
    -- Primary key
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    report_number VARCHAR(50) GENERATED ALWAYS AS (
        'RPT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.report_definitions_seq')::TEXT, 6, '0')
    ) STORED,

    -- Basic info
    report_name VARCHAR(255) NOT NULL,
    report_description TEXT,
    report_category VARCHAR(100) CHECK (report_category IN ('MARKETING', 'SALES', 'PRODUCT', 'FINANCE', 'SUPPORT', 'EXECUTIVE')),

    -- Report logic
    query_type VARCHAR(30) CHECK (query_type IN ('SQL', 'PREDICATE', 'API_CALL')),
    query_text TEXT NOT NULL,                               -- SQL or query definition
    parameters JSONB DEFAULT '[]',                           -- List of parameters with names, types, defaults
    parameter_defaults JSONB,                                -- Default values for parameters

    -- Output configuration
    default_format socialcandor_schema.report_format DEFAULT 'CSV',
    available_formats socialcandor_schema.report_format[],
    visualisation_config JSONB,                              -- Chart types, colours, etc.

    -- Ownership
    owner_user_id UUID,
    owner_team VARCHAR(100),

    -- Access control
    is_public BOOLEAN DEFAULT FALSE,
    allowed_roles TEXT[],
    allowed_users UUID[],

    -- Performance
    estimated_execution_time_seconds INTEGER,
    last_executed_at TIMESTAMP WITH TIME ZONE,
    average_execution_time_seconds NUMERIC(10,2),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_report_definitions_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_report_definitions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_report_definitions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.report_definitions IS 'Stores templates and configurations for reusable reports';
COMMENT ON COLUMN socialcandor_schema.report_definitions.query_text IS 'SQL or query definition';
COMMENT ON COLUMN socialcandor_schema.report_definitions.parameters IS 'JSON array of parameter definitions (name, type, required, default)';
COMMENT ON COLUMN socialcandor_schema.report_definitions.visualisation_config IS 'Chart types, colours, axis settings';

-- Indexes
CREATE INDEX idx_report_definitions_owner ON socialcandor_schema.report_definitions(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX idx_report_definitions_category ON socialcandor_schema.report_definitions(report_category, is_active);

-- Trigger for updated_at
CREATE TRIGGER trg_report_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.report_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.report_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_definitions_owner_policy ON socialcandor_schema.report_definitions
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY report_definitions_public_policy ON socialcandor_schema.report_definitions
    FOR SELECT USING (is_public = TRUE OR current_setting('app.current_user_id')::UUID = ANY(allowed_users));


-- =================================================================================================
-- TABLE: 210 - report_schedules
-- Description: Manages automated report generation schedules, including frequency, recipients,
--              and delivery methods.
-- Business Case: Many reports need to be delivered regularly (daily sales, weekly user growth).
--                This table stores scheduling information linking to report definitions. It tracks
--                the next run time, last run status, and delivery destinations (email, Slack,
--                cloud storage). The design supports one‑time runs and recurring schedules with
--                custom intervals. Integration with a job scheduler enables reliable report delivery.
-- KPIs:
--   1. Number of active schedules
--   2. Schedule delivery success rate
--   3. Average report generation time
--   4. Recipient engagement (click rate on emailed reports)
--   5. Schedule adherence (on‑time delivery)
-- Feature References: RPT02 (Report Scheduling), RPT04 (Automated Delivery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.report_schedules (
    -- Primary key
    schedule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    schedule_number VARCHAR(50) GENERATED ALWAYS AS (
        'SCH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.report_schedules_seq')::TEXT, 6, '0')
    ) STORED,

    -- Report reference
    report_id UUID NOT NULL,

    -- Schedule definition
    schedule_name VARCHAR(255),
    frequency socialcandor_schema.report_frequency NOT NULL,
    interval_days INTEGER CHECK (interval_days >= 1),          -- For custom intervals
    time_of_day TIME,                                           -- For daily/weekly schedules
    day_of_week INTEGER CHECK (day_of_week BETWEEN 0 AND 6),   -- 0=Sunday
    day_of_month INTEGER CHECK (day_of_month BETWEEN 1 AND 31),

    -- Parameter values
    parameter_values JSONB,                                     -- Fixed values for report parameters

    -- Delivery
    formats socialcandor_schema.report_format[] DEFAULT '{CSV}',
    destinations JSONB NOT NULL,                                 -- Array of {type: 'email', address: '...'} or {type: 'slack', channel: '...'}

    -- Schedule control
    start_date DATE NOT NULL,
    end_date DATE,                                              -- NULL = indefinite
    last_run_at TIMESTAMP WITH TIME ZONE,
    next_run_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (
        CASE
            WHEN end_date IS NULL OR end_date >= CURRENT_DATE THEN
                -- Simplified; actual calculation would use frequency
                last_run_at + INTERVAL '1 day'
            ELSE NULL
        END
    ) STORED,

    -- Run tracking
    run_count INTEGER DEFAULT 0,
    last_run_status VARCHAR(30) CHECK (last_run_status IN ('SUCCESS', 'FAILED', 'SKIPPED')),
    last_run_error TEXT,

    -- Ownership
    owner_user_id UUID,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    paused_until TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_report_schedules_report FOREIGN KEY (report_id)
        REFERENCES socialcandor_schema.report_definitions(report_id) ON DELETE CASCADE,
    CONSTRAINT fk_report_schedules_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_report_schedules_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_report_schedules_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_report_schedule_dates CHECK (end_date IS NULL OR end_date >= start_date)
);

COMMENT ON TABLE socialcandor_schema.report_schedules IS 'Manages automated report generation schedules and delivery';
COMMENT ON COLUMN socialcandor_schema.report_schedules.destinations IS 'JSON array of delivery destinations (email, slack, s3)';
COMMENT ON COLUMN socialcandor_schema.report_schedules.parameter_values IS 'Fixed values for report parameters (overrides defaults)';

-- Indexes
CREATE INDEX idx_report_schedules_report ON socialcandor_schema.report_schedules(report_id);
CREATE INDEX idx_report_schedules_next_run ON socialcandor_schema.report_schedules(next_run_at) WHERE is_active = TRUE;
CREATE INDEX idx_report_schedules_owner ON socialcandor_schema.report_schedules(owner_user_id) WHERE owner_user_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_report_schedules_updated_at
    BEFORE UPDATE ON socialcandor_schema.report_schedules
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.report_schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_schedules_owner_policy ON socialcandor_schema.report_schedules
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID OR socialcandor_schema.is_admin());
CREATE POLICY report_schedules_report_owner_policy ON socialcandor_schema.report_schedules
    FOR SELECT USING (report_id IN (
        SELECT report_id FROM socialcandor_schema.report_definitions WHERE owner_user_id = current_setting('app.current_user_id')::UUID
    ));


-- =================================================================================================
-- MATERIALIZED VIEW: mv_daily_funnel_conversion
-- Description: Pre‑aggregated funnel conversion rates per day for fast dashboard loading.
-- Business Case: Funnel analysis is a core component of product analytics. This materialized view
--                pre‑computes the number of users entering, progressing, and converting through
--                each funnel step per day. It eliminates expensive joins and aggregations on the
--                raw event tables, enabling sub‑second dashboard queries. The view can be refreshed
--                daily (or on‑demand) and indexed for optimal performance.
-- KPIs: (Derived from underlying data)
-- Feature References: DASH08 (Funnel Dashboards), ANL23 (Funnel Analysis)
-- =================================================================================================
DROP MATERIALIZED VIEW IF EXISTS socialcandor_schema.mv_daily_funnel_conversion;

CREATE MATERIALIZED VIEW socialcandor_schema.mv_daily_funnel_conversion AS
WITH step_counts AS (
    SELECT
        DATE(occurred_at) AS event_date,
        funnel_id,
        step_id,
        step_name,
        step_order,
        COUNT(DISTINCT user_id) AS unique_users,
        COUNT(*) AS total_events,
        COUNT(DISTINCT CASE WHEN converted THEN user_id END) AS converted_users
    FROM socialcandor_schema.conversion_funnel_events
    WHERE user_id IS NOT NULL
    GROUP BY DATE(occurred_at), funnel_id, step_id, step_name, step_order
)
SELECT
    event_date,
    funnel_id,
    step_id,
    step_name,
    step_order,
    unique_users,
    total_events,
    converted_users,
    LAG(unique_users) OVER (PARTITION BY funnel_id, step_order ORDER BY event_date) AS previous_day_users,
    CASE
        WHEN LAG(unique_users) OVER (PARTITION BY funnel_id, step_order ORDER BY event_date) > 0
        THEN (unique_users::NUMERIC / LAG(unique_users) OVER (PARTITION BY funnel_id, step_order ORDER BY event_date)) * 100
        ELSE NULL
    END AS day_over_day_conversion_pct
FROM step_counts
ORDER BY event_date DESC, funnel_id, step_order;

COMMENT ON MATERIALIZED VIEW socialcandor_schema.mv_daily_funnel_conversion IS 'Daily funnel conversion rates pre‑aggregated for dashboards';

CREATE UNIQUE INDEX idx_mv_daily_funnel_conversion_unique
    ON socialcandor_schema.mv_daily_funnel_conversion (event_date, funnel_id, step_id);
CREATE INDEX idx_mv_daily_funnel_conversion_funnel
    ON socialcandor_schema.mv_daily_funnel_conversion (funnel_id, event_date DESC);

-- Function to refresh the materialized view (call via scheduler)
CREATE OR REPLACE FUNCTION socialcandor_schema.refresh_daily_funnel_mv()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY socialcandor_schema.mv_daily_funnel_conversion;
END;
$$ LANGUAGE plpgsql;



