-- Enum: ML01 - ml_model_status
-- Description: Lifecycle status of a machine learning model
-- Business Case: Track models from development through production to retirement
-- Feature Reference: MLOP01 (Model Lifecycle Management)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_model_status AS ENUM (
    'DRAFT',                -- Initial creation, not yet trained
    'TRAINING',             -- Model is being trained
    'READY',                -- Trained and ready for deployment
    'DEPLOYED',             -- Actively serving predictions
    'DEPRECATED',           -- No longer recommended for use
    'ARCHIVED'              -- Historical record, not used
);
COMMENT ON TYPE socialcandor_schema.ml_model_status IS 'Lifecycle status of a machine learning model';

-- Enum: ML02 - ml_model_framework
-- Description: ML frameworks used for model development
-- Business Case: Categorize models by framework for dependency management
-- Feature Reference: MLOP02 (Framework Management)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_model_framework AS ENUM (
    'TENSORFLOW',
    'PYTORCH',
    'SKLEARN',
    'XGBOOST',
    'LIGHTGBM',
    'KERAS',
    'CUSTOM'
);
COMMENT ON TYPE socialcandor_schema.ml_model_framework IS 'ML frameworks used for model development';

-- Enum: ML03 - ml_dataset_type
-- Description: Usage type of a dataset in ML lifecycle
-- Business Case: Differentiate datasets for training, validation, testing, etc.
-- Feature Reference: MLOP03 (Dataset Management)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_dataset_type AS ENUM (
    'TRAINING',
    'VALIDATION',
    'TEST',
    'PRODUCTION',
    'BACKTEST'
);
COMMENT ON TYPE socialcandor_schema.ml_dataset_type IS 'Usage type of a dataset in ML lifecycle';

-- Enum: ML04 - ml_feature_type
-- Description: Data type of a feature in the feature store
-- Business Case: Ensure correct handling of feature values in training and inference
-- Feature Reference: MLOP04 (Feature Store)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_feature_type AS ENUM (
    'NUMERIC',
    'CATEGORICAL',
    'TEXT',
    'BOOLEAN',
    'DATETIME',
    'ARRAY',
    'JSON'
);
COMMENT ON TYPE socialcandor_schema.ml_feature_type IS 'Data type of a feature in the feature store';

-- Enum: ML05 - ml_prediction_status
-- Description: Status of a prediction request
-- Business Case: Track success/failure of predictions for monitoring
-- Feature Reference: MLOP05 (Prediction Logging)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_prediction_status AS ENUM (
    'PENDING',
    'SUCCESS',
    'FAILED'
);
COMMENT ON TYPE socialcandor_schema.ml_prediction_status IS 'Status of a prediction request';

-- Enum: ML06 - ml_performance_metric_type
-- Description: Types of performance metrics for model evaluation
-- Business Case: Standardize metric names for cross-model comparison
-- Feature Reference: MLOP06 (Model Evaluation)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_performance_metric_type AS ENUM (
    'ACCURACY',
    'PRECISION',
    'RECALL',
    'F1',
    'AUC',
    'RMSE',
    'MAE',
    'MAPE',
    'LOGLOSS'
);
COMMENT ON TYPE socialcandor_schema.ml_performance_metric_type IS 'Types of performance metrics for model evaluation';

-- Enum: ML07 - ml_drift_severity
-- Description: Severity levels for model drift detection
-- Business Case: Prioritize model retraining based on drift severity
-- Feature Reference: MLOP07 (Drift Detection)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_drift_severity AS ENUM (
    'LOW',
    'MEDIUM',
    'HIGH',
    'CRITICAL'
);
COMMENT ON TYPE socialcandor_schema.ml_drift_severity IS 'Severity levels for model drift detection';

-- Enum: ML08 - ml_experiment_status
-- Description: Status of an ML experiment
-- Business Case: Track experiment lifecycle from planning to completion
-- Feature Reference: MLOP08 (Experiment Tracking)
--================================================================================================
CREATE TYPE socialcandor_schema.ml_experiment_status AS ENUM (
    'PLANNED',
    'RUNNING',
    'COMPLETED',
    'FAILED',
    'ARCHIVED'
);
COMMENT ON TYPE socialcandor_schema.ml_experiment_status IS 'Status of an ML experiment';

