--================================================================================================
-- TABLE: ML01 - ml_model_registry
-- Description: Central registry of all machine learning models, their metadata, and lifecycle status.
--              Tracks model ownership, framework, and high-level attributes.
-- Business Case: As the platform scales, managing numerous ML models becomes critical.
--                The model registry provides a single source of truth for model metadata,
--                enabling discovery, governance, and lifecycle management. It supports model
--                lineage (linking to training runs), version control, and deployment tracking.
--                This table ensures that models are properly documented, owned, and can be
--                audited for compliance. It also facilitates model reuse and collaboration
--                across data science teams.
-- KPIs:
--   1. Number of active models per business domain
--   2. Model lifecycle distribution (development vs. production)
--   3. Average time from training to deployment
--   4. Model ownership coverage (percentage with assigned owner)
--   5. Framework adoption trends
-- Feature Reference: MLOP09 (Model Registry)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_registry (
    model_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    model_number VARCHAR(50) GENERATED ALWAYS AS (
        'MOD-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_registry_seq')::TEXT, 6, '0')
    ) STORED,
    model_name VARCHAR(255) NOT NULL,
    model_description TEXT,
    model_version VARCHAR(50) NOT NULL,               -- semantic version (e.g., "1.0.0")
    model_status socialcandor_schema.ml_model_status NOT NULL DEFAULT 'DRAFT',
    model_framework socialcandor_schema.ml_model_framework,
    framework_version VARCHAR(50),
    task_type VARCHAR(100),                            -- classification, regression, etc.
    input_schema JSONB,                                 -- expected input format
    output_schema JSONB,                                -- expected output format
    owner_team VARCHAR(100),
    owner_user_id UUID,
    business_domain VARCHAR(100),                       -- e.g., 'recommendation', 'fraud'
    tags TEXT[],
    is_explainable BOOLEAN DEFAULT FALSE,
    requires_gpu BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_ml_model_registry_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_model_registry_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_model_registry_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_ml_model_registry_name_version UNIQUE (model_name, model_version)
);
COMMENT ON TABLE socialcandor_schema.ml_model_registry IS 'Central registry of machine learning models with lifecycle metadata';
COMMENT ON COLUMN socialcandor_schema.ml_model_registry.model_number IS 'Human-readable model identifier';
COMMENT ON COLUMN socialcandor_schema.ml_model_registry.input_schema IS 'JSON schema defining expected input format';
COMMENT ON COLUMN socialcandor_schema.ml_model_registry.output_schema IS 'JSON schema defining output format';
COMMENT ON COLUMN socialcandor_schema.ml_model_registry.tags IS 'Arbitrary tags for categorisation';

CREATE INDEX idx_ml_model_registry_status ON socialcandor_schema.ml_model_registry(model_status);
CREATE INDEX idx_ml_model_registry_owner ON socialcandor_schema.ml_model_registry(owner_user_id) WHERE owner_user_id IS NOT NULL;
CREATE INDEX idx_ml_model_registry_domain ON socialcandor_schema.ml_model_registry(business_domain);

CREATE TRIGGER trg_ml_model_registry_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_model_registry
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_model_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_model_registry_admin_policy ON socialcandor_schema.ml_model_registry
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_model_registry_owner_policy ON socialcandor_schema.ml_model_registry
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID);

--================================================================================================
-- TABLE: ML02 - ml_model_versions
-- Description: Tracks individual versions of models, including artifact location, metrics,
--              training metadata, and deployment status. Links to training runs and experiments.
-- Business Case: Models evolve over time with retraining, hyperparameter tuning, and data changes.
--                This table provides version control for models, enabling rollback, reproducibility,
--                and performance comparison across versions. It stores critical metadata such as
--                the trained artifact URL, evaluation metrics, training dataset references, and
--                git commit hash for code reproducibility. This granular tracking is essential for
--                model governance, audit trails, and regulatory compliance (e.g., AI Act).
-- KPIs:
--   1. Number of versions per model
--   2. Performance delta between versions
--   3. Version promotion rate (dev → staging → production)
--   4. Time between versions
--   5. Deployment success rate
-- Feature Reference: MLOP10 (Model Versioning)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_versions (
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    version_number VARCHAR(50) GENERATED ALWAYS AS (
        'VER-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_versions_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    version_tag VARCHAR(50),                               -- e.g., 'v1.0.0'
    version_description TEXT,
    artifact_url VARCHAR(500) NOT NULL,
    artifact_size_bytes BIGINT CHECK (artifact_size_bytes >= 0),
    model_card_url VARCHAR(500),                            -- documentation
    git_commit_hash VARCHAR(64),
    training_script_path VARCHAR(500),
    training_duration_seconds INTEGER CHECK (training_duration_seconds >= 0),
    evaluation_metrics JSONB,                                -- stored metrics snapshot
    is_active BOOLEAN DEFAULT TRUE,
    deployment_status VARCHAR(30) CHECK (deployment_status IN ('NOT_DEPLOYED', 'STAGING', 'PRODUCTION', 'ROLLED_BACK')),
    deployed_at TIMESTAMP WITH TIME ZONE,
    deployment_id UUID,                                      -- reference to deployment log
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_ml_model_versions_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_model_registry(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_versions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_model_versions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_ml_model_versions_model_tag UNIQUE (model_id, version_tag)
);
COMMENT ON TABLE socialcandor_schema.ml_model_versions IS 'Version tracking for ML models, including artifacts and metadata';
COMMENT ON COLUMN socialcandor_schema.ml_model_versions.artifact_url IS 'URL to the serialized model file';
COMMENT ON COLUMN socialcandor_schema.ml_model_versions.model_card_url IS 'Link to model documentation';
COMMENT ON COLUMN socialcandor_schema.ml_model_versions.evaluation_metrics IS 'JSON snapshot of model performance metrics';

CREATE INDEX idx_ml_model_versions_model ON socialcandor_schema.ml_model_versions(model_id, created_at DESC);
CREATE INDEX idx_ml_model_versions_deployment ON socialcandor_schema.ml_model_versions(deployment_status) WHERE deployment_status IS NOT NULL;
CREATE INDEX idx_ml_model_versions_active ON socialcandor_schema.ml_model_versions(model_id, is_active) WHERE is_active = TRUE;

CREATE TRIGGER trg_ml_model_versions_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_model_versions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_model_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_model_versions_admin_policy ON socialcandor_schema.ml_model_versions
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_model_versions_owner_policy ON socialcandor_schema.ml_model_versions
    FOR ALL USING (created_by = current_setting('app.current_user_id')::UUID);

--================================================================================================
-- TABLE: ML03 - ml_training_datasets
-- Description: Manages datasets used for training, validation, and testing of ML models.
--              Stores dataset metadata, location, statistics, and versioning.
-- Business Case: Reproducibility is a cornerstone of ML engineering. This table tracks all datasets
--                used in model training, ensuring that experiments can be reproduced and that data
--                lineage is maintained. It stores dataset versions, schemas, row counts, and quality
--                metrics. This enables data scientists to understand which data version produced which
--                model, and to debug performance regressions. It also supports compliance requirements
--                by documenting the data used for model training.
-- KPIs:
--   1. Dataset version count per source
--   2. Data quality metrics (completeness, accuracy)
--   3. Dataset freshness (time since last update)
--   4. Number of models using each dataset
--   5. Storage consumption by dataset
-- Feature Reference: MLOP11 (Dataset Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_training_datasets (
    dataset_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    dataset_number VARCHAR(50) GENERATED ALWAYS AS (
        'DS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_training_datasets_seq')::TEXT, 6, '0')
    ) STORED,
    dataset_name VARCHAR(255) NOT NULL,
    dataset_version VARCHAR(50) NOT NULL,
    dataset_type socialcandor_schema.ml_dataset_type NOT NULL,
    description TEXT,
    source_system VARCHAR(100),
    source_query TEXT,
    data_location VARCHAR(500) NOT NULL,
    file_format VARCHAR(30) CHECK (file_format IN ('CSV', 'PARQUET', 'AVRO', 'JSON', 'TFRecord')),
    row_count BIGINT CHECK (row_count >= 0),
    column_count INTEGER CHECK (column_count >= 0),
    schema_definition JSONB,                                 -- column names and types
    quality_metrics JSONB,                                   -- e.g., completeness %, anomaly count
    checksum VARCHAR(64),                                    -- for integrity
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_ml_training_datasets_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_training_datasets_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_ml_training_datasets_name_version UNIQUE (dataset_name, dataset_version)
);
COMMENT ON TABLE socialcandor_schema.ml_training_datasets IS 'Metadata for datasets used in ML training, validation, and testing';
COMMENT ON COLUMN socialcandor_schema.ml_training_datasets.source_query IS 'Query or script used to generate the dataset';
COMMENT ON COLUMN socialcandor_schema.ml_training_datasets.quality_metrics IS 'JSON object with data quality metrics';
COMMENT ON COLUMN socialcandor_schema.ml_training_datasets.checksum IS 'Hash of the dataset for integrity verification';

CREATE INDEX idx_ml_training_datasets_type ON socialcandor_schema.ml_training_datasets(dataset_type);
CREATE INDEX idx_ml_training_datasets_created ON socialcandor_schema.ml_training_datasets(created_at DESC);

CREATE TRIGGER trg_ml_training_datasets_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_training_datasets
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_training_datasets ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_training_datasets_admin_policy ON socialcandor_schema.ml_training_datasets
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_training_datasets_creator_policy ON socialcandor_schema.ml_training_datasets
    FOR ALL USING (created_by = current_setting('app.current_user_id')::UUID);

--================================================================================================
-- TABLE: ML04 - ml_feature_store
-- Description: Central catalog of feature definitions used across ML models. Defines feature
--              name, data type, source, and transformation logic.
-- Business Case: A feature store enables feature reuse, consistency between training and inference,
--                and reduces redundant engineering work. This table defines the schema of each feature,
--                its data type, source table, and any transformation logic. It serves as the single
--                source of truth for feature definitions, ensuring that the same feature computation
--                is used in both training and serving. This prevents training/serving skew and
--                accelerates model development.
-- KPIs:
--   1. Number of features defined
--   2. Feature reuse across models
--   3. Feature freshness (time since last update)
--   4. Ownership coverage
--   5. Documentation completeness
-- Feature Reference: MLOP12 (Feature Store)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_feature_store (
    feature_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    feature_number VARCHAR(50) GENERATED ALWAYS AS (
        'FTR-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_feature_store_seq')::TEXT, 6, '0')
    ) STORED,
    feature_name VARCHAR(255) NOT NULL UNIQUE,
    feature_description TEXT,
    feature_type socialcandor_schema.ml_feature_type NOT NULL,
    source_system VARCHAR(100),
    source_table VARCHAR(255),
    source_column VARCHAR(255),
    transformation_sql TEXT,
    is_pii BOOLEAN DEFAULT FALSE,
    is_derived BOOLEAN DEFAULT FALSE,
    owner_team VARCHAR(100),
    owner_user_id UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    CONSTRAINT fk_ml_feature_store_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_feature_store_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_feature_store_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ml_feature_store IS 'Catalog of feature definitions for ML models';
COMMENT ON COLUMN socialcandor_schema.ml_feature_store.transformation_sql IS 'SQL or logic to compute the feature';
COMMENT ON COLUMN socialcandor_schema.ml_feature_store.is_pii IS 'Whether the feature contains personal identifiable information';

CREATE INDEX idx_ml_feature_store_type ON socialcandor_schema.ml_feature_store(feature_type);
CREATE INDEX idx_ml_feature_store_owner ON socialcandor_schema.ml_feature_store(owner_user_id) WHERE owner_user_id IS NOT NULL;

CREATE TRIGGER trg_ml_feature_store_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_feature_store
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_feature_store ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_feature_store_admin_policy ON socialcandor_schema.ml_feature_store
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_feature_store_owner_policy ON socialcandor_schema.ml_feature_store
    FOR ALL USING (owner_user_id = current_setting('app.current_user_id')::UUID);

--================================================================================================
-- TABLE: ML05 - ml_feature_values
-- Description: Time-series storage of feature values for each entity, enabling point-in-time
--              correct feature retrieval for training and inference. Partitioned by timestamp.
-- Business Case: Feature values change over time, and models need the correct historical values
--                for training (to avoid lookahead bias). This table stores the actual values
--                for each feature at specific points in time, keyed by entity (user, product, etc.).
--                Partitioning by timestamp ensures query performance even with billions of rows.
--                The design supports both batch and real-time feature pipelines. This is the core
--                of the online feature store.
-- KPIs:
--   1. Feature coverage (percentage of entities with feature values)
--   2. Feature latency (time from event to feature availability)
--   3. Storage growth rate
--   4. Query performance (p99 latency for feature retrieval)
--   5. Freshness (age of latest feature values)
-- Feature Reference: MLOP13 (Feature Values)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_feature_values (
    value_id BIGSERIAL,
    value_number VARCHAR(50) GENERATED ALWAYS AS (
        'FV-' || TO_CHAR(timestamp, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_feature_values_seq')::TEXT, 6, '0')
    ) STORED,
    feature_id UUID NOT NULL,
    entity_type VARCHAR(50) NOT NULL CHECK (entity_type IN ('USER', 'POST', 'PRODUCT', 'SESSION', 'ORGANIZATION')),
    entity_id VARCHAR(255) NOT NULL,
    value_numeric NUMERIC,
    value_string TEXT,
    value_boolean BOOLEAN,
    value_json JSONB,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (value_id, timestamp),
    CONSTRAINT fk_ml_feature_values_feature FOREIGN KEY (feature_id)
        REFERENCES socialcandor_schema.ml_feature_store(feature_id) ON DELETE CASCADE,
    CONSTRAINT chk_ml_feature_value_type CHECK (
        (value_numeric IS NOT NULL)::INTEGER +
        (value_string IS NOT NULL)::INTEGER +
        (value_boolean IS NOT NULL)::INTEGER +
        (value_json IS NOT NULL)::INTEGER = 1
    )
) PARTITION BY RANGE (timestamp);
COMMENT ON TABLE socialcandor_schema.ml_feature_values IS 'Time-series feature values for ML training and inference';
COMMENT ON COLUMN socialcandor_schema.ml_feature_values.entity_type IS 'Type of entity the feature describes';
COMMENT ON COLUMN socialcandor_schema.ml_feature_values.entity_id IS 'Identifier of the entity';
COMMENT ON COLUMN socialcandor_schema.ml_feature_values.timestamp IS 'Point in time when this feature value was true';

-- Create initial partitions (last 12 months)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'ml_feature_values_' || TO_CHAR(start_date, 'YYYY_MM');
        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.ml_feature_values
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

CREATE INDEX idx_ml_feature_values_feature ON socialcandor_schema.ml_feature_values(feature_id, timestamp DESC);
CREATE INDEX idx_ml_feature_values_entity ON socialcandor_schema.ml_feature_values(entity_type, entity_id, timestamp DESC);

ALTER TABLE socialcandor_schema.ml_feature_values ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_feature_values_admin_policy ON socialcandor_schema.ml_feature_values
    FOR ALL USING (socialcandor_schema.is_admin());
-- Optionally allow read access to data scientists
CREATE POLICY ml_feature_values_analyst_policy ON socialcandor_schema.ml_feature_values
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('DATA_SCIENTIST', 'ANALYST')
    ));

--================================================================================================
-- TABLE: ML06 - ml_model_predictions
-- Description: Logs every prediction made by deployed models, including input data, output,
--              model version, latency, and metadata. Partitioned by prediction date.
-- Business Case: Comprehensive prediction logging is essential for monitoring model performance,
--                debugging, auditing, and building feedback loops. This table stores the full
--                context of each prediction request: input features, model output, confidence scores,
--                and metadata like latency and model version. The data enables drift detection,
--                performance analysis, and collection of ground truth for retraining. Partitioning
--                by date ensures query performance and manageability.
-- KPIs:
--   1. Prediction volume per model per day
--   2. Average latency p99
--   3. Error rate (failed predictions)
--   4. Model version distribution
--   5. Input drift detection (based on feature distributions)
-- Feature Reference: MLOP14 (Prediction Logging)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_predictions (
    prediction_id BIGSERIAL,
    prediction_number VARCHAR(50) GENERATED ALWAYS AS (
        'PRED-' || TO_CHAR(prediction_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_predictions_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    model_version_id UUID NOT NULL,
    prediction_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    request_id UUID,                                         -- For tracing
    input_data JSONB NOT NULL,
    output_data JSONB NOT NULL,
    confidence_scores JSONB,
    prediction_status socialcandor_schema.ml_prediction_status NOT NULL DEFAULT 'SUCCESS',
    error_message TEXT,
    latency_ms INTEGER CHECK (latency_ms >= 0),
    user_id UUID,                                            -- Optional: who made the request
    api_key_id UUID,
    deployment_environment VARCHAR(30) CHECK (deployment_environment IN ('PRODUCTION', 'STAGING', 'TEST')),
    model_version_used VARCHAR(50),                           -- snapshot for reproducibility
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (prediction_id, prediction_time),
    CONSTRAINT fk_ml_model_predictions_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_model_registry(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_predictions_version FOREIGN KEY (model_version_id)
        REFERENCES socialcandor_schema.ml_model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_predictions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
) PARTITION BY RANGE (prediction_time);
COMMENT ON TABLE socialcandor_schema.ml_model_predictions IS 'Logs of model predictions for monitoring and debugging';
COMMENT ON COLUMN socialcandor_schema.ml_model_predictions.input_data IS 'JSON containing input features';
COMMENT ON COLUMN socialcandor_schema.ml_model_predictions.output_data IS 'JSON containing model output';
COMMENT ON COLUMN socialcandor_schema.ml_model_predictions.confidence_scores IS 'Optional confidence scores per class';

-- Create initial partitions (last 12 months)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'ml_model_predictions_' || TO_CHAR(start_date, 'YYYY_MM');
        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.ml_model_predictions
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

CREATE INDEX idx_ml_model_predictions_model ON socialcandor_schema.ml_model_predictions(model_id, prediction_time DESC);
CREATE INDEX idx_ml_model_predictions_version ON socialcandor_schema.ml_model_predictions(model_version_id, prediction_time DESC);
CREATE INDEX idx_ml_model_predictions_user ON socialcandor_schema.ml_model_predictions(user_id, prediction_time DESC) WHERE user_id IS NOT NULL;

ALTER TABLE socialcandor_schema.ml_model_predictions ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_model_predictions_admin_policy ON socialcandor_schema.ml_model_predictions
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_model_predictions_analyst_policy ON socialcandor_schema.ml_model_predictions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('DATA_SCIENTIST', 'ANALYST')
    ));

--================================================================================================
-- TABLE: ML07 - ml_model_performance
-- Description: Stores computed performance metrics for model versions over time, enabling
--              tracking of model degradation and comparison across versions.
-- Business Case: Models must be continuously monitored for performance degradation. This table
--                stores evaluation metrics (accuracy, precision, recall, etc.) computed on
--                validation/test sets or on production data with ground truth. It allows data
--                scientists to compare versions, detect regressions, and trigger retraining.
--                Metrics can be computed periodically (daily/weekly) and stored with the
--                corresponding dataset used for evaluation. This table supports model governance
--                and regulatory requirements by providing a history of model performance.
-- KPIs:
--   1. Performance trend over time per model
--   2. Best performing version per model
--   3. Metric stability (variance over time)
--   4. Ground truth collection rate
--   5. Alert-triggering events (performance drops)
-- Feature Reference: MLOP15 (Model Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_performance (
    performance_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    performance_number VARCHAR(50) GENERATED ALWAYS AS (
        'PERF-' || TO_CHAR(evaluation_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_performance_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    model_version_id UUID NOT NULL,
    evaluation_date DATE NOT NULL DEFAULT CURRENT_DATE,
    dataset_id UUID,                                           -- dataset used for evaluation
    metric_name VARCHAR(100) NOT NULL,
    metric_value NUMERIC(15,6) NOT NULL CHECK (metric_value >= 0),
    metric_type socialcandor_schema.ml_performance_metric_type NOT NULL,
    slice_definition VARCHAR(500),                              -- data slice (e.g., 'country=US')
    sample_size INTEGER CHECK (sample_size >= 0),
    confidence_interval_lower NUMERIC(15,6),
    confidence_interval_upper NUMERIC(15,6),
    is_production_data BOOLEAN DEFAULT FALSE,                   -- evaluated on production data
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    CONSTRAINT fk_ml_model_performance_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_model_registry(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_performance_version FOREIGN KEY (model_version_id)
        REFERENCES socialcandor_schema.ml_model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_performance_dataset FOREIGN KEY (dataset_id)
        REFERENCES socialcandor_schema.ml_training_datasets(dataset_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_model_performance_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT
);
COMMENT ON TABLE socialcandor_schema.ml_model_performance IS 'Performance metrics for model versions over time';
COMMENT ON COLUMN socialcandor_schema.ml_model_performance.slice_definition IS 'Data slice (e.g., demographic segment) for which metric applies';
COMMENT ON COLUMN socialcandor_schema.ml_model_performance.is_production_data IS 'Whether metric computed on live production data';

CREATE INDEX idx_ml_model_performance_model ON socialcandor_schema.ml_model_performance(model_id, evaluation_date DESC);
CREATE INDEX idx_ml_model_performance_version ON socialcandor_schema.ml_model_performance(model_version_id, metric_name);
CREATE INDEX idx_ml_model_performance_date ON socialcandor_schema.ml_model_performance(evaluation_date DESC);

ALTER TABLE socialcandor_schema.ml_model_performance ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_model_performance_admin_policy ON socialcandor_schema.ml_model_performance
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_model_performance_analyst_policy ON socialcandor_schema.ml_model_performance
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('DATA_SCIENTIST', 'ANALYST')
    ));

--================================================================================================
-- TABLE: ML08 - ml_model_drift_alerts
-- Description: Stores alerts generated when model drift (data drift, concept drift) is detected,
--              including drift metrics, severity, and recommended actions.
-- Business Case: Models in production can degrade due to changes in input data distribution
--                (data drift) or relationships (concept drift). This table logs detected drift
--                events with severity scores, enabling proactive retraining. It stores drift
--                metrics per feature, overall drift score, and the threshold that was exceeded.
--                Alerts can be integrated with monitoring systems to notify the ML team.
--                This table is crucial for maintaining model reliability and avoiding silent
--                performance degradation.
-- KPIs:
--   1. Drift detection rate (alerts per month)
--   2. Mean time to detect drift
--   3. False positive rate (alerts not leading to retraining)
--   4. Drift severity distribution
--   5. Top drifting features
-- Feature Reference: MLOP16 (Drift Detection)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_model_drift_alerts (
    alert_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    alert_number VARCHAR(50) GENERATED ALWAYS AS (
        'DRIFT-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_model_drift_alerts_seq')::TEXT, 6, '0')
    ) STORED,
    model_id UUID NOT NULL,
    model_version_id UUID NOT NULL,
    alert_type VARCHAR(30) CHECK (alert_type IN ('DATA_DRIFT', 'CONCEPT_DRIFT', 'PREDICTION_DRIFT')),
    drift_score NUMERIC(10,6) NOT NULL,
    threshold NUMERIC(10,6) NOT NULL,
    severity socialcandor_schema.ml_drift_severity NOT NULL,
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    feature_drift JSONB,                                      -- per-feature drift scores
    alert_message TEXT,
    acknowledged_by UUID,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    remediation_action VARCHAR(500),                          -- e.g., 'RETRAIN', 'ROLLBACK', 'INVESTIGATE'
    resolved_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ml_model_drift_alerts_model FOREIGN KEY (model_id)
        REFERENCES socialcandor_schema.ml_model_registry(model_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_drift_alerts_version FOREIGN KEY (model_version_id)
        REFERENCES socialcandor_schema.ml_model_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_ml_model_drift_alerts_acknowledged_by FOREIGN KEY (acknowledged_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.ml_model_drift_alerts IS 'Alerts for model drift detection with severity and metadata';
COMMENT ON COLUMN socialcandor_schema.ml_model_drift_alerts.feature_drift IS 'JSON map of feature names to drift scores';

CREATE INDEX idx_ml_model_drift_alerts_model ON socialcandor_schema.ml_model_drift_alerts(model_id, detected_at DESC);
CREATE INDEX idx_ml_model_drift_alerts_severity ON socialcandor_schema.ml_model_drift_alerts(severity, acknowledged_at);

ALTER TABLE socialcandor_schema.ml_model_drift_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_model_drift_alerts_admin_policy ON socialcandor_schema.ml_model_drift_alerts
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ml_model_drift_alerts_ml_team_policy ON socialcandor_schema.ml_model_drift_alerts
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER')
    ));

--================================================================================================
-- TABLE: ML09 - ml_experiment_tracking
-- Description: Tracks ML experiments, including hyperparameters, metrics, and links to
--              training runs, datasets, and code versions. Enables reproducibility and comparison.
-- Business Case: Data scientists run many experiments with different hyperparameters, data
--                versions, and code branches. This table provides a structured way to log
--                each experiment, its configuration, and results. It links to model versions
--                (when an experiment produces a candidate model) and to training datasets.
--                This enables systematic comparison, prevents duplication of effort, and
--                supports reproducibility. The table also stores experiment notes and tags
--                for organisation.
-- KPIs:
--   1. Experiment count per project per month
--   2. Experiment success rate (proportion leading to a registered model)
--   3. Average experiment duration
--   4. Hyperparameter search space coverage
--   5. Experiment reproducibility (percentage that can be fully reproduced)
-- Feature Reference: MLOP17 (Experiment Tracking)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_experiment_tracking (
    experiment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    experiment_number VARCHAR(50) GENERATED ALWAYS AS (
        'EXP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_experiment_tracking_seq')::TEXT, 6, '0')
    ) STORED,
    experiment_name VARCHAR(255) NOT NULL,
    experiment_description TEXT,
    project_name VARCHAR(255),
    status socialcandor_schema.ml_experiment_status NOT NULL DEFAULT 'PLANNED',
    start_time TIMESTAMP WITH TIME ZONE,
    end_time TIMESTAMP WITH TIME ZONE,
    git_commit_hash VARCHAR(64),
    git_branch VARCHAR(255),
    code_path VARCHAR(500),
    training_script VARCHAR(500),
    hyperparameter_config_id UUID,                            -- link to hyperparameter config
    dataset_id UUID,                                          -- training dataset used
    validation_dataset_id UUID,
    test_dataset_id UUID,
    metrics_summary JSONB,                                    -- best metrics achieved
    notes TEXT,
    tags TEXT[],
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ml_experiment_tracking_hyperparam FOREIGN KEY (hyperparameter_config_id)
        REFERENCES socialcandor_schema.ml_hyperparameter_configs(config_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_experiment_tracking_dataset FOREIGN KEY (dataset_id)
        REFERENCES socialcandor_schema.ml_training_datasets(dataset_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_experiment_tracking_validation FOREIGN KEY (validation_dataset_id)
        REFERENCES socialcandor_schema.ml_training_datasets(dataset_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_experiment_tracking_test FOREIGN KEY (test_dataset_id)
        REFERENCES socialcandor_schema.ml_training_datasets(dataset_id) ON DELETE SET NULL,
    CONSTRAINT fk_ml_experiment_tracking_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_experiment_tracking_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_ml_experiment_dates CHECK (end_time IS NULL OR end_time >= start_time)
);
COMMENT ON TABLE socialcandor_schema.ml_experiment_tracking IS 'Tracks ML experiments with hyperparameters, datasets, and results';
COMMENT ON COLUMN socialcandor_schema.ml_experiment_tracking.metrics_summary IS 'Summary of best metrics from the experiment';

CREATE INDEX idx_ml_experiment_tracking_project ON socialcandor_schema.ml_experiment_tracking(project_name, created_at DESC);
CREATE INDEX idx_ml_experiment_tracking_status ON socialcandor_schema.ml_experiment_tracking(status);
CREATE INDEX idx_ml_experiment_tracking_created_by ON socialcandor_schema.ml_experiment_tracking(created_by);

CREATE TRIGGER trg_ml_experiment_tracking_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_experiment_tracking
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_experiment_tracking ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_experiment_tracking_self_policy ON socialcandor_schema.ml_experiment_tracking
    FOR ALL USING (created_by = current_setting('app.current_user_id')::UUID);
CREATE POLICY ml_experiment_tracking_admin_policy ON socialcandor_schema.ml_experiment_tracking
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: ML10 - ml_hyperparameter_configs
-- Description: Stores hyperparameter configurations used in ML experiments and training runs.
--              Enables reuse and comparison of hyperparameter sets.
-- Business Case: Hyperparameters are critical to model performance. This table stores
--                hyperparameter configurations as JSON, allowing them to be reused across
--                experiments and linked to training runs. It also stores metadata such as
--                the tuning method (grid search, random, bayesian) and the search space.
--                This facilitates reproducibility and comparison: data scientists can easily
--                see which hyperparameters produced the best model and reuse those settings.
-- KPIs:
--   1. Number of unique hyperparameter configurations
--   2. Configuration reuse rate
--   3. Hyperparameter search efficiency
--   4. Most common hyperparameter values
--   5. Configuration complexity (number of parameters)
-- Feature Reference: MLOP18 (Hyperparameter Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ml_hyperparameter_configs (
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    config_number VARCHAR(50) GENERATED ALWAYS AS (
        'HP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ml_hyperparameter_configs_seq')::TEXT, 6, '0')
    ) STORED,
    config_name VARCHAR(255),
    config_description TEXT,
    hyperparameters JSONB NOT NULL,                           -- key-value pairs of hyperparameters
    search_space JSONB,                                       -- definition of search space (for tuning)
    tuning_method VARCHAR(50) CHECK (tuning_method IN ('MANUAL', 'GRID_SEARCH', 'RANDOM_SEARCH', 'BAYESIAN', 'OPTUNA')),
    is_default BOOLEAN DEFAULT FALSE,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ml_hyperparameter_configs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ml_hyperparameter_configs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_ml_hyperparameter_configs_name UNIQUE (config_name)
);
COMMENT ON TABLE socialcandor_schema.ml_hyperparameter_configs IS 'Stores hyperparameter configurations for ML models';
COMMENT ON COLUMN socialcandor_schema.ml_hyperparameter_configs.hyperparameters IS 'JSON object of hyperparameter names and values';
COMMENT ON COLUMN socialcandor_schema.ml_hyperparameter_configs.search_space IS 'JSON definition of hyperparameter search space';

CREATE INDEX idx_ml_hyperparameter_configs_tuning ON socialcandor_schema.ml_hyperparameter_configs(tuning_method);
CREATE INDEX idx_ml_hyperparameter_configs_default ON socialcandor_schema.ml_hyperparameter_configs(is_default) WHERE is_default = TRUE;

CREATE TRIGGER trg_ml_hyperparameter_configs_updated_at
    BEFORE UPDATE ON socialcandor_schema.ml_hyperparameter_configs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

ALTER TABLE socialcandor_schema.ml_hyperparameter_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY ml_hyperparameter_configs_self_policy ON socialcandor_schema.ml_hyperparameter_configs
    FOR ALL USING (created_by = current_setting('app.current_user_id')::UUID);
CREATE POLICY ml_hyperparameter_configs_admin_policy ON socialcandor_schema.ml_hyperparameter_configs
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- MATERIALIZED VIEW: mv_model_performance_summary
-- Description: Pre‑aggregated view of model performance metrics for dashboarding.
--              Shows latest metrics per model and version.
--================================================================================================
DROP MATERIALIZED VIEW IF EXISTS socialcandor_schema.mv_model_performance_summary;

CREATE MATERIALIZED VIEW socialcandor_schema.mv_model_performance_summary AS
SELECT
    m.model_id,
    m.model_name,
    mv.version_tag,
    mv.deployment_status,
    p.metric_name,
    p.metric_value,
    p.evaluation_date,
    ROW_NUMBER() OVER (PARTITION BY m.model_id, p.metric_name ORDER BY p.evaluation_date DESC) AS rn
FROM socialcandor_schema.ml_model_registry m
JOIN socialcandor_schema.ml_model_versions mv ON m.model_id = mv.model_id AND mv.is_active = TRUE
JOIN socialcandor_schema.ml_model_performance p ON mv.version_id = p.model_version_id
WHERE p.is_production_data = TRUE
ORDER BY m.model_id, p.metric_name, p.evaluation_date DESC;

COMMENT ON MATERIALIZED VIEW socialcandor_schema.mv_model_performance_summary IS 'Pre‑aggregated model performance metrics for dashboards';

CREATE UNIQUE INDEX idx_mv_model_perf_summary ON socialcandor_schema.mv_model_performance_summary (model_id, metric_name, evaluation_date);



-- =================================================================================================
-- ENUMS
-- =================================================================================================

-- Enum: W3E01 - blockchain_network
-- Description: Supported blockchain networks for wallet connections and transactions.
-- Business Case: Enables multi-chain support and distinguishes between mainnet/testnet environments.
-- Feature Reference: WEB307 (Multi-chain Support)
-- =================================================================================================
CREATE TYPE socialcandor_schema.blockchain_network AS ENUM (
    'ETHEREUM_MAINNET',
    'ETHEREUM_GOERLI',
    'ETHEREUM_SEPOLIA',
    'POLYGON_MAINNET',
    'POLYGON_MUMBAI',
    'BSC_MAINNET',
    'BSC_TESTNET',
    'ARBITRUM_ONE',
    'ARBITRUM_GOERLI',
    'OPTIMISM_MAINNET',
    'OPTIMISM_GOERLI',
    'AVALANCHE_C_MAINNET',
    'AVALANCHE_FUJI',
    'SOLANA_MAINNET',
    'SOLANA_DEVNET',
    'BASE_MAINNET',
    'BASE_GOERLI',
    'OTHER'
);
COMMENT ON TYPE socialcandor_schema.blockchain_network IS 'Supported blockchain networks for wallet connections and transactions.';

-- Enum: W3E02 - wallet_type
-- Description: Type of blockchain wallet (externally owned account, contract, multi-sig).
-- Business Case: Helps differentiate wallet capabilities and validation requirements.
-- Feature Reference: WEB308 (Wallet Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.wallet_type AS ENUM (
    'EOA',                -- Externally Owned Account (standard)
    'CONTRACT',           -- Smart contract wallet
    'MULTISIG',           -- Multi-signature wallet (e.g., Gnosis Safe)
    'LEDGER',             -- Hardware wallet
    'SMART_WALLET'        -- Smart contract wallet (e.g., Argent)
);
COMMENT ON TYPE socialcandor_schema.wallet_type IS 'Type of blockchain wallet.';

-- Enum: W3E03 - verification_method
-- Description: Method used to verify wallet ownership.
-- Business Case: Ensures only genuine wallets are connected; supports signature verification.
-- Feature Reference: WEB309 (Wallet Verification)
-- =================================================================================================
CREATE TYPE socialcandor_schema.verification_method AS ENUM (
    'SIGNATURE',          -- Signed message with private key
    'TRANSACTION',        -- Sent a small transaction from wallet
    'ENS',                -- ENS domain verification
    'OAUTH',              -- OAuth via wallet provider
    'MANUAL'              -- Admin verified
);
COMMENT ON TYPE socialcandor_schema.verification_method IS 'Method used to verify wallet ownership.';

-- Enum: W3E04 - tx_status
-- Description: Status of a blockchain transaction.
-- Business Case: Tracks transaction lifecycle from pending to finality.
-- Feature Reference: WEB310 (Transaction Tracking)
-- =================================================================================================
CREATE TYPE socialcandor_schema.tx_status AS ENUM (
    'PENDING',            -- Broadcast but not yet confirmed
    'CONFIRMING',         -- Received some confirmations
    'CONFIRMED',          -- Sufficient confirmations
    'FAILED',             -- Transaction failed (reverted)
    'REPLACED',           -- Replaced by another transaction (higher gas)
    'DROPPED'             -- Dropped from mempool
);
COMMENT ON TYPE socialcandor_schema.tx_status IS 'Status of a blockchain transaction.';

-- Enum: W3E05 - token_standard
-- Description: Token standards for NFTs and fungible tokens.
-- Business Case: Supports different token implementations (ERC-721, ERC-1155, SPL).
-- Feature Reference: WEB311 (Token Standards)
-- =================================================================================================
CREATE TYPE socialcandor_schema.token_standard AS ENUM (
    'ERC20',
    'ERC721',
    'ERC1155',
    'ERC2981',            -- Royalty standard
    'SPL_TOKEN',          -- Solana token
    'SPL_NFT',            -- Solana NFT (Metaplex)
    'OTHER'
);
COMMENT ON TYPE socialcandor_schema.token_standard IS 'Token standards for NFTs and fungible tokens.';

-- Enum: W3E06 - vote_choice
-- Description: Choices in a DAO vote.
-- Business Case: Standardises vote options across proposals.
-- Feature Reference: GOV17 (Vote Recording)
-- =================================================================================================
CREATE TYPE socialcandor_schema.vote_choice AS ENUM (
    'FOR',
    'AGAINST',
    'ABSTAIN'
);
COMMENT ON TYPE socialcandor_schema.vote_choice IS 'Choices in a DAO vote.';

-- Enum: W3E07 - treasury_tx_type
-- Description: Types of treasury transactions.
-- Business Case: Categorises treasury movements for reporting.
-- Feature Reference: GOV23 (Treasury Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.treasury_tx_type AS ENUM (
    'DEPOSIT',
    'WITHDRAWAL',
    'TRANSFER',
    'SWAP',
    'STAKE',
    'UNSTAKE',
    'REWARD',
    'FEE'
);
COMMENT ON TYPE socialcandor_schema.treasury_tx_type IS 'Types of DAO treasury transactions.';

-- =================================================================================================
-- SEQUENCES (for human‑readable identifiers)
-- =================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.wallet_connection_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.crypto_tx_log_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.nft_ownership_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.nft_metadata_cache_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.contract_interaction_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.dao_vote_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.treasury_tx_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.token_balance_snapshot_seq START 1000;

-- =================================================================================================
-- TABLE: W3T01 - blockchain_wallet_connections
-- Description: Maps user accounts to blockchain wallet addresses across multiple networks.
-- Business Case: Enables users to connect their crypto wallets for authentication, NFT ownership
--                verification, and on-chain interactions. This table stores wallet metadata,
--                verification status, and sync information. It supports multiple wallets per user
--                (hot/cold) and allows users to designate a primary wallet for platform use.
--                Verified wallets enable features like NFT-gated content, token-based governance,
--                and cryptocurrency payments. The design includes signature-based verification to
--                prove wallet ownership, preventing address spoofing. Historical tracking of wallet
--                activity helps with fraud detection and user analytics.
-- KPIs:
--   1. Wallet connection rate – Percentage of users with at least one verified wallet.
--   2. Multi-wallet usage – Average number of wallets per connected user.
--   3. Verification success rate – Percentage of wallet verification attempts that succeed.
--   4. Wallet distribution – Breakdown by blockchain network.
--   5. Wallet activity – Number of transactions per wallet over time.
-- Feature References: WEB307 (Multi-chain Support), WEB308 (Wallet Management), WEB309 (Wallet Verification)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.blockchain_wallet_connections (
    -- Primary key
    connection_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    connection_number VARCHAR(50) GENERATED ALWAYS AS (
        'WAL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.wallet_connection_seq')::TEXT, 6, '0')
    ) STORED,

    -- User reference
    user_id UUID NOT NULL,

    -- Wallet details
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    wallet_address VARCHAR(255) NOT NULL,
    wallet_type socialcandor_schema.wallet_type DEFAULT 'EOA',

    -- Verification
    is_verified BOOLEAN DEFAULT FALSE,
    verification_method socialcandor_schema.verification_method,
    verification_signature VARCHAR(500),
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Wallet metadata
    wallet_label VARCHAR(100),                    -- User-defined label (e.g., "Hot Wallet", "Ledger")
    is_primary BOOLEAN DEFAULT FALSE,             -- Primary wallet for transactions
    wallet_balance NUMERIC(30,18) DEFAULT 0,      -- Cached native balance (optional)
    last_balance_sync TIMESTAMP WITH TIME ZONE,

    -- Activity tracking
    first_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_active_at TIMESTAMP WITH TIME ZONE,
    transaction_count INTEGER DEFAULT 0 CHECK (transaction_count >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    deactivation_reason VARCHAR(255),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_blockchain_wallet_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_blockchain_wallet_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_blockchain_wallet_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_blockchain_wallet_address UNIQUE (blockchain, wallet_address),
    CONSTRAINT uk_user_primary_wallet UNIQUE (user_id) WHERE is_primary = TRUE AND is_active = TRUE,
    CONSTRAINT chk_wallet_address_length CHECK (LENGTH(wallet_address) BETWEEN 25 AND 255)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.blockchain_wallet_connections IS 'Maps user accounts to blockchain wallet addresses across multiple networks.';
COMMENT ON COLUMN socialcandor_schema.blockchain_wallet_connections.wallet_address IS 'Blockchain address (case-sensitive, length varies by network).';
COMMENT ON COLUMN socialcandor_schema.blockchain_wallet_connections.verification_signature IS 'Signed message proving ownership (stored for audit).';
COMMENT ON COLUMN socialcandor_schema.blockchain_wallet_connections.is_primary IS 'Whether this is the user’s primary wallet for platform transactions.';

-- Indexes
CREATE INDEX idx_blockchain_wallet_user ON socialcandor_schema.blockchain_wallet_connections(user_id, is_active);
CREATE INDEX idx_blockchain_wallet_address ON socialcandor_schema.blockchain_wallet_connections(blockchain, wallet_address);
CREATE INDEX idx_blockchain_wallet_primary ON socialcandor_schema.blockchain_wallet_connections(user_id) WHERE is_primary = TRUE AND is_active = TRUE;
CREATE INDEX idx_blockchain_wallet_active ON socialcandor_schema.blockchain_wallet_connections(is_active, last_active_at) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_blockchain_wallet_updated_at
    BEFORE UPDATE ON socialcandor_schema.blockchain_wallet_connections
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.blockchain_wallet_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY blockchain_wallet_self_policy ON socialcandor_schema.blockchain_wallet_connections
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY blockchain_wallet_admin_policy ON socialcandor_schema.blockchain_wallet_connections
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T02 - crypto_transaction_logs
-- Description: Comprehensive log of all cryptocurrency transactions involving user wallets,
--              including incoming/outgoing transfers, swaps, and contract interactions.
-- Business Case: Provides a complete audit trail for crypto activities, essential for user
--                transaction history, payment verification, and financial reporting. The table
--                captures on-chain confirmations, gas costs, and token details. It supports
--                multiple blockchains and token standards. Transactions can be linked to
--                platform orders (e.g., purchase of goods) for reconciliation. The design
--                includes status tracking from pending to confirmed, enabling real‑time
--                feedback to users. This data also powers analytics on crypto adoption and
--                transaction volume.
-- KPIs:
--   1. Transaction volume – Number and total value of transactions per day/week.
--   2. Average confirmation time – Time from broadcast to finality by network.
--   3. Success rate – Percentage of transactions successfully confirmed.
--   4. Gas cost analysis – Average gas fees per network.
--   5. Token popularity – Most transacted tokens.
-- Feature References: WEB310 (Transaction Tracking), WEB311 (Token Standards), PAY13 (Crypto Payments)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.crypto_transaction_logs (
    -- Primary key
    log_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'CRTX-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.crypto_tx_log_seq')::TEXT, 6, '0')
    ) STORED,

    -- User reference (NULL if unknown or external)
    user_id UUID,
    wallet_id UUID,                              -- Reference to blockchain_wallet_connections

    -- Transaction identifiers
    tx_hash VARCHAR(255) NOT NULL UNIQUE,
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    network_specific_id VARCHAR(255),            -- e.g., Solana signature

    -- Participants
    from_address VARCHAR(255) NOT NULL,
    to_address VARCHAR(255) NOT NULL,

    -- Value and token
    amount NUMERIC(30,18) NOT NULL CHECK (amount > 0),
    token_address VARCHAR(255),                   -- NULL for native currency
    token_symbol VARCHAR(20),                      -- e.g., 'ETH', 'MATIC'
    token_decimals INTEGER DEFAULT 18 CHECK (token_decimals >= 0 AND token_decimals <= 18),
    token_standard socialcandor_schema.token_standard,

    -- Fee data
    gas_price_gwei NUMERIC(30,10) CHECK (gas_price_gwei >= 0),
    gas_used INTEGER CHECK (gas_used >= 0),
    gas_cost_native NUMERIC(30,18) GENERATED ALWAYS AS (gas_price_gwei * gas_used / 1e9) STORED,
    gas_cost_usd NUMERIC(15,2),                    -- Estimated at time of transaction

    -- Block data
    block_number BIGINT CHECK (block_number >= 0),
    block_hash VARCHAR(255),
    transaction_index INTEGER CHECK (transaction_index >= 0),
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Status
    status socialcandor_schema.tx_status NOT NULL DEFAULT 'PENDING',
    confirmations INTEGER DEFAULT 0 CHECK (confirmations >= 0),
    required_confirmations INTEGER DEFAULT 12 CHECK (required_confirmations >= 0), -- Network‑specific
    is_final BOOLEAN GENERATED ALWAYS AS (status = 'CONFIRMED' AND confirmations >= required_confirmations) STORED,

    -- Transaction type (optional classification)
    tx_type VARCHAR(50) CHECK (tx_type IN ('SEND', 'RECEIVE', 'SWAP', 'CONTRACT_CALL', 'MINT', 'BURN', 'APPROVE')),

    -- Platform link
    order_id UUID,                                 -- Associated marketplace order
    payment_id UUID,                               -- Associated payment

    -- Raw data
    raw_transaction JSONB,                          -- Full transaction data for debugging
    logs JSONB,                                      -- Event logs emitted

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_crypto_tx_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_crypto_tx_wallet FOREIGN KEY (wallet_id)
        REFERENCES socialcandor_schema.blockchain_wallet_connections(connection_id) ON DELETE SET NULL,
    CONSTRAINT fk_crypto_tx_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_crypto_tx_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_crypto_tx_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_crypto_tx_addresses CHECK (from_address != to_address),
    CONSTRAINT chk_crypto_tx_timestamp CHECK (timestamp <= CURRENT_TIMESTAMP)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.crypto_transaction_logs IS 'Complete log of cryptocurrency transactions involving user wallets.';
COMMENT ON COLUMN socialcandor_schema.crypto_transaction_logs.token_address IS 'Contract address of token; NULL for native currency.';
COMMENT ON COLUMN socialcandor_schema.crypto_transaction_logs.gas_cost_usd IS 'Estimated gas cost in USD at time of transaction.';
COMMENT ON COLUMN socialcandor_schema.crypto_transaction_logs.raw_transaction IS 'Full transaction JSON for debugging.';

-- Indexes
CREATE INDEX idx_crypto_tx_user ON socialcandor_schema.crypto_transaction_logs(user_id, timestamp DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_crypto_tx_wallet ON socialcandor_schema.crypto_transaction_logs(wallet_id, timestamp DESC) WHERE wallet_id IS NOT NULL;
CREATE INDEX idx_crypto_tx_addresses ON socialcandor_schema.crypto_transaction_logs(from_address, to_address, timestamp DESC);
CREATE INDEX idx_crypto_tx_hash ON socialcandor_schema.crypto_transaction_logs(tx_hash);
CREATE INDEX idx_crypto_tx_status ON socialcandor_schema.crypto_transaction_logs(status, confirmations) WHERE status != 'CONFIRMED';
CREATE INDEX idx_crypto_tx_block ON socialcandor_schema.crypto_transaction_logs(blockchain, block_number DESC) WHERE block_number IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_crypto_tx_updated_at
    BEFORE UPDATE ON socialcandor_schema.crypto_transaction_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.crypto_transaction_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY crypto_tx_self_policy ON socialcandor_schema.crypto_transaction_logs
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY crypto_tx_admin_policy ON socialcandor_schema.crypto_transaction_logs
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T03 - nft_ownership_records
-- Description: Tracks ownership of NFTs across supported blockchains, linking to platform users.
-- Business Case: Enables NFT‑gated features (content access, communities, profile pictures) by
--                verifying which NFTs a user owns. The table stores ownership snapshots synced
--                from blockchain indexers. It supports multiple tokens per contract and handles
--                transfers via event tracking. Ownership records are used to grant token‑based
--                permissions and to display user collections. The design includes `last_synced_at`
--                to manage refresh frequency and avoid excessive RPC calls.
-- KPIs:
--   1. NFT coverage – Number of distinct NFTs tracked.
--   2. Unique owners – Users with at least one NFT.
--   3. Sync freshness – Time since last ownership update.
--   4. Collection diversity – Most popular NFT collections among users.
--   5. Token‑gated feature usage – Number of accesses to gated content.
-- Feature References: WEB312 (NFT Ownership), WEB313 (Token‑gated Content)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.nft_ownership_records (
    -- Primary key
    ownership_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    ownership_number VARCHAR(50) GENERATED ALWAYS AS (
        'NFT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.nft_ownership_seq')::TEXT, 6, '0')
    ) STORED,

    -- User reference (NULL if owner not a platform user)
    user_id UUID,

    -- NFT identification
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    contract_address VARCHAR(255) NOT NULL,
    token_id VARCHAR(255) NOT NULL,
    token_standard socialcandor_schema.token_standard,

    -- Owner address (on‑chain)
    owner_address VARCHAR(255) NOT NULL,

    -- Quantity (for ERC1155)
    balance INTEGER DEFAULT 1 CHECK (balance >= 0),

    -- Acquisition metadata
    acquired_at TIMESTAMP WITH TIME ZONE,
    acquisition_tx_hash VARCHAR(255),

    -- Sync metadata
    last_synced_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    sync_attempts INTEGER DEFAULT 0 CHECK (sync_attempts >= 0),
    is_active BOOLEAN DEFAULT TRUE,              -- Whether this record is current (owner still owns)

    -- Constraints
    CONSTRAINT fk_nft_ownership_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_nft_ownership_acq_tx FOREIGN KEY (acquisition_tx_hash)
        REFERENCES socialcandor_schema.crypto_transaction_logs(tx_hash) ON DELETE SET NULL,

    CONSTRAINT uk_nft_ownership UNIQUE (blockchain, contract_address, token_id, owner_address, is_active)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.nft_ownership_records IS 'Tracks NFT ownership linking blockchain addresses to platform users.';
COMMENT ON COLUMN socialcandor_schema.nft_ownership_records.user_id IS 'Platform user who owns the NFT (NULL if not a user).';
COMMENT ON COLUMN socialcandor_schema.nft_ownership_records.balance IS 'Number of tokens owned (for ERC1155).';
COMMENT ON COLUMN socialcandor_schema.nft_ownership_records.is_active IS 'Indicates current ownership; set to FALSE after transfer.';

-- Indexes
CREATE INDEX idx_nft_ownership_user ON socialcandor_schema.nft_ownership_records(user_id, is_active) WHERE user_id IS NOT NULL;
CREATE INDEX idx_nft_ownership_contract ON socialcandor_schema.nft_ownership_records(blockchain, contract_address, token_id);
CREATE INDEX idx_nft_ownership_owner ON socialcandor_schema.nft_ownership_records(owner_address, is_active);
CREATE INDEX idx_nft_ownership_sync ON socialcandor_schema.nft_ownership_records(last_synced_at) WHERE is_active = TRUE;

-- RLS Policy
ALTER TABLE socialcandor_schema.nft_ownership_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY nft_ownership_self_policy ON socialcandor_schema.nft_ownership_records
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY nft_ownership_admin_policy ON socialcandor_schema.nft_ownership_records
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T04 - nft_metadata_cache
-- Description: Caches NFT metadata (name, description, image, attributes) to reduce external calls.
-- Business Case: NFT metadata is often stored on IPFS or external servers and can be slow or
--                unreliable. This cache stores frequently accessed metadata to improve UI
--                performance and reduce dependency on external services. It supports versioning
--                and tracks fetch attempts. Metadata can be refreshed periodically or on‑demand.
--                The design includes a `metadata_quality` flag to indicate whether the data is
--                complete (e.g., missing fields marked as incomplete).
-- KPIs:
--   1. Cache hit rate – Percentage of requests served from cache.
--   2. Fetch latency – Average time to retrieve metadata from source.
--   3. Cache freshness – Time since last successful fetch.
--   4. Error rate – Percentage of failed fetch attempts.
--   5. Storage efficiency – Compression ratio of stored metadata.
-- Feature References: WEB314 (NFT Metadata), WEB315 (Performance Optimization)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.nft_metadata_cache (
    -- Primary key
    cache_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    cache_number VARCHAR(50) GENERATED ALWAYS AS (
        'NFTC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.nft_metadata_cache_seq')::TEXT, 6, '0')
    ) STORED,

    -- NFT identification
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    contract_address VARCHAR(255) NOT NULL,
    token_id VARCHAR(255) NOT NULL,

    -- Metadata (cached)
    name VARCHAR(500),
    description TEXT,
    image_url VARCHAR(1000),
    animation_url VARCHAR(1000),
    external_url VARCHAR(1000),
    attributes JSONB,                              -- Array of traits
    collection_name VARCHAR(255),
    collection_slug VARCHAR(255),

    -- Fetch metadata
    metadata_uri VARCHAR(1000),                     -- Original URI (e.g., IPFS)
    fetched_at TIMESTAMP WITH TIME ZONE,
    fetch_attempts INTEGER DEFAULT 0 CHECK (fetch_attempts >= 0),
    last_error TEXT,
    is_complete BOOLEAN DEFAULT FALSE,              -- Whether all expected fields were fetched

    -- Cache control
    refresh_interval_hours INTEGER DEFAULT 24,
    next_refresh_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (
        fetched_at + (refresh_interval_hours || ' hours')::INTERVAL
    ) STORED,

    -- Constraints
    CONSTRAINT uk_nft_metadata UNIQUE (blockchain, contract_address, token_id)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.nft_metadata_cache IS 'Caches NFT metadata to improve performance and reliability.';
COMMENT ON COLUMN socialcandor_schema.nft_metadata_cache.attributes IS 'JSON array of trait objects (trait_type, value).';
COMMENT ON COLUMN socialcandor_schema.nft_metadata_cache.is_complete IS 'Indicates whether metadata fetch succeeded and all fields populated.';

-- Indexes
CREATE INDEX idx_nft_metadata_contract ON socialcandor_schema.nft_metadata_cache(blockchain, contract_address, token_id);
CREATE INDEX idx_nft_metadata_refresh ON socialcandor_schema.nft_metadata_cache(next_refresh_at) WHERE fetched_at IS NOT NULL;
CREATE INDEX idx_nft_metadata_collection ON socialcandor_schema.nft_metadata_cache(collection_slug);

-- RLS Policy
ALTER TABLE socialcandor_schema.nft_metadata_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY nft_metadata_public_policy ON socialcandor_schema.nft_metadata_cache
    FOR SELECT USING (TRUE);
CREATE POLICY nft_metadata_admin_policy ON socialcandor_schema.nft_metadata_cache
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T05 - smart_contract_interactions
-- Description: Logs user‑initiated interactions with smart contracts (e.g., minting, staking, voting).
-- Business Case: Provides an audit trail of all contract calls made through the platform,
--                essential for debugging, user support, and compliance. It captures function
--                parameters, transaction status, and results. This data helps users track their
--                contract activities and enables analytics on feature adoption (e.g., how many
--                users minted NFTs). The table also stores revert reasons for failed transactions
--                to assist troubleshooting.
-- KPIs:
--   1. Interaction volume – Number of contract calls per day.
--   2. Success rate – Percentage of successful transactions.
--   3. Gas usage – Average gas costs per contract type.
--   4. Feature adoption – Most‑called functions per contract.
--   5. Error analysis – Most common revert reasons.
-- Feature References: WEB316 (Contract Interactions), WEB317 (dApp Analytics)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.smart_contract_interactions (
    -- Primary key
    interaction_id BIGSERIAL PRIMARY KEY,

    -- Human‑readable identifier
    interaction_number VARCHAR(50) GENERATED ALWAYS AS (
        'SCI-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.contract_interaction_seq')::TEXT, 6, '0')
    ) STORED,

    -- User and wallet
    user_id UUID NOT NULL,
    wallet_id UUID,                               -- Reference to blockchain_wallet_connections

    -- Contract details
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    contract_address VARCHAR(255) NOT NULL,
    contract_name VARCHAR(255),

    -- Function call
    function_name VARCHAR(255) NOT NULL,
    function_signature VARCHAR(255),
    parameters JSONB,                              -- Array of parameter values
    parameter_count INTEGER CHECK (parameter_count >= 0),

    -- Transaction data
    tx_hash VARCHAR(255) UNIQUE,
    tx_status socialcandor_schema.tx_status NOT NULL DEFAULT 'PENDING',
    block_number BIGINT,
    gas_used INTEGER,
    gas_price_gwei NUMERIC(30,10),

    -- Results
    return_value JSONB,
    events_emitted JSONB,                          -- Logs emitted
    error_message TEXT,
    revert_reason TEXT,

    -- Timing
    requested_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    confirmed_at TIMESTAMP WITH TIME ZONE,
    confirmation_time_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (confirmed_at - requested_at))
    ) STORED,

    -- Context
    interaction_type VARCHAR(50) CHECK (interaction_type IN ('READ', 'WRITE', 'DEPLOY', 'APPROVE', 'TRANSFER', 'SWAP', 'STAKE', 'VOTE')),
    dapp_feature VARCHAR(100),                      -- Feature that triggered this interaction

    -- Platform links
    nft_id UUID,                                    -- Associated NFT (if any)
    order_id UUID,                                  -- Associated marketplace order
    proposal_id UUID,                               -- Associated DAO proposal

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_sci_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_sci_wallet FOREIGN KEY (wallet_id)
        REFERENCES socialcandor_schema.blockchain_wallet_connections(connection_id) ON DELETE SET NULL,
    CONSTRAINT fk_sci_nft FOREIGN KEY (nft_id)
        REFERENCES socialcandor_schema.nft_ownership_records(ownership_id) ON DELETE SET NULL,
    CONSTRAINT fk_sci_order FOREIGN KEY (order_id)
        REFERENCES socialcandor_schema.marketplace_orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_sci_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_sci_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_sci_timing CHECK (confirmed_at IS NULL OR confirmed_at >= requested_at)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.smart_contract_interactions IS 'Logs user‑initiated interactions with smart contracts.';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.parameters IS 'JSON array of function parameter values.';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.events_emitted IS 'JSON array of events emitted by the transaction.';
COMMENT ON COLUMN socialcandor_schema.smart_contract_interactions.revert_reason IS 'Error message for failed transactions.';

-- Indexes
CREATE INDEX idx_sci_user ON socialcandor_schema.smart_contract_interactions(user_id, requested_at DESC);
CREATE INDEX idx_sci_wallet ON socialcandor_schema.smart_contract_interactions(wallet_id, requested_at DESC) WHERE wallet_id IS NOT NULL;
CREATE INDEX idx_sci_contract ON socialcandor_schema.smart_contract_interactions(blockchain, contract_address, function_name);
CREATE INDEX idx_sci_tx_hash ON socialcandor_schema.smart_contract_interactions(tx_hash) WHERE tx_hash IS NOT NULL;
CREATE INDEX idx_sci_status ON socialcandor_schema.smart_contract_interactions(tx_status, requested_at) WHERE tx_status != 'CONFIRMED';
CREATE INDEX idx_sci_feature ON socialcandor_schema.smart_contract_interactions(dapp_feature, requested_at DESC) WHERE dapp_feature IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_sci_updated_at
    BEFORE UPDATE ON socialcandor_schema.smart_contract_interactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.smart_contract_interactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sci_self_policy ON socialcandor_schema.smart_contract_interactions
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY sci_admin_policy ON socialcandor_schema.smart_contract_interactions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T06 - dao_proposal_votes
-- Description: Records votes cast by users on DAO proposals, including voting power and transaction proof.
-- Business Case: Enables transparent and auditable on‑chain/off‑chain voting for DAO governance.
--                This table captures vote choices, voting power (e.g., token‑weighted), and links
--                to the underlying transaction or proposal. It supports both on‑chain votes
--                (with tx_hash) and off‑chain votes (with signature). The data is used to calculate
--                proposal outcomes, generate voter participation reports, and ensure governance
--                integrity. It also supports delegation tracking (via `delegated_from`).
-- KPIs:
--   1. Voter turnout – Percentage of eligible voters participating.
--   2. Vote distribution – For/Against/Abstain percentages.
--   3. Voting power concentration – Gini coefficient of voting power.
--   4. Proposal participation – Average votes per proposal.
--   5. Delegation usage – Percentage of votes cast via delegation.
-- Feature References: GOV17 (Vote Recording), GOV18 (Voter Analytics), GOV19 (Governance Participation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_proposal_votes (
    -- Primary key
    vote_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    vote_number VARCHAR(50) GENERATED ALWAYS AS (
        'DVOTE-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.dao_vote_seq')::TEXT, 6, '0')
    ) STORED,

    -- Voter
    voter_user_id UUID NOT NULL,
    voter_address VARCHAR(255),                    -- Blockchain address used (if on‑chain)

    -- Proposal reference (could be internal or external ID)
    proposal_id VARCHAR(255) NOT NULL,              -- External proposal ID (e.g., Snapshot ID)
    proposal_title VARCHAR(500),                    -- Denormalized for quick reference

    -- Vote details
    vote_choice socialcandor_schema.vote_choice NOT NULL,
    voting_power NUMERIC(30,18) NOT NULL CHECK (voting_power >= 0),
    voting_weight NUMERIC(10,6) DEFAULT 1.0 CHECK (voting_weight >= 0),

    -- Blockchain proof (if on‑chain)
    tx_hash VARCHAR(255),
    block_number BIGINT,
    blockchain socialcandor_schema.blockchain_network,

    -- Off‑chain proof (e.g., signed message)
    signature VARCHAR(500),

    -- Delegation
    delegated_from_user_id UUID,                    -- If vote was cast on behalf of another user
    delegation_id UUID,                              -- Reference to dao_delegations table (if exists)

    -- Timing
    voted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_dao_vote_voter FOREIGN KEY (voter_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_dao_vote_delegated_from FOREIGN KEY (delegated_from_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_dao_vote_tx FOREIGN KEY (tx_hash)
        REFERENCES socialcandor_schema.crypto_transaction_logs(tx_hash) ON DELETE SET NULL,
    CONSTRAINT fk_dao_vote_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dao_vote_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_dao_vote UNIQUE (proposal_id, voter_user_id, delegated_from_user_id)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.dao_proposal_votes IS 'Records votes cast by users on DAO proposals.';
COMMENT ON COLUMN socialcandor_schema.dao_proposal_votes.proposal_id IS 'Identifier of the proposal (could be external ID like Snapshot ID).';
COMMENT ON COLUMN socialcandor_schema.dao_proposal_votes.voting_power IS 'Amount of voting power used (token‑weighted).';
COMMENT ON COLUMN socialcandor_schema.dao_proposal_votes.delegated_from_user_id IS 'If the vote was cast on behalf of another user (delegation).';

-- Indexes
CREATE INDEX idx_dao_vote_proposal ON socialcandor_schema.dao_proposal_votes(proposal_id, vote_choice);
CREATE INDEX idx_dao_vote_voter ON socialcandor_schema.dao_proposal_votes(voter_user_id, voted_at DESC);
CREATE INDEX idx_dao_vote_tx ON socialcandor_schema.dao_proposal_votes(tx_hash) WHERE tx_hash IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_dao_vote_updated_at
    BEFORE UPDATE ON socialcandor_schema.dao_proposal_votes
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.dao_proposal_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY dao_vote_self_policy ON socialcandor_schema.dao_proposal_votes
    FOR SELECT USING (voter_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY dao_vote_admin_policy ON socialcandor_schema.dao_proposal_votes
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T07 - dao_treasury_transactions
-- Description: Records transactions from DAO treasuries (multi‑sig wallets), linked to proposals.
-- Business Case: Provides transparency and auditability for DAO treasury movements. This table
--                captures all outgoing transactions (e.g., grants, payments) and incoming funds.
--                It links transactions to the proposals that authorised them, enabling users to
--                verify that funds were used as voted. The table also stores multi‑sig confirmations
--                and execution status. This data powers treasury dashboards and financial reporting.
-- KPIs:
--   1. Treasury volume – Total value moved per period.
--   2. Proposal execution rate – Percentage of passed proposals that resulted in treasury txs.
--   3. Multi‑sig completion time – Average time from proposal passing to execution.
--   4. Expense categories – Breakdown by treasury_tx_type.
--   5. Remaining treasury balance – Snapshot of current holdings.
-- Feature References: GOV23 (Treasury Management), GOV24 (Multi‑sig Execution)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.dao_treasury_transactions (
    -- Primary key
    transaction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    transaction_number VARCHAR(50) GENERATED ALWAYS AS (
        'TREAS-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.treasury_tx_seq')::TEXT, 6, '0')
    ) STORED,

    -- Treasury identification
    treasury_name VARCHAR(255) NOT NULL,
    treasury_address VARCHAR(255) NOT NULL,
    blockchain socialcandor_schema.blockchain_network NOT NULL,

    -- Transaction details
    tx_type socialcandor_schema.treasury_tx_type NOT NULL,
    tx_hash VARCHAR(255) UNIQUE,
    from_address VARCHAR(255) NOT NULL,
    to_address VARCHAR(255) NOT NULL,
    amount NUMERIC(30,18) NOT NULL CHECK (amount > 0),
    token_address VARCHAR(255),                    -- NULL for native currency
    token_symbol VARCHAR(20),

    -- Proposal link
    proposal_id VARCHAR(255),                       -- Proposal that authorised this tx
    proposal_title VARCHAR(500),

    -- Multi‑sig details
    required_confirmations INTEGER CHECK (required_confirmations >= 1),
    current_confirmations INTEGER DEFAULT 0 CHECK (current_confirmations >= 0),
    confirmations JSONB,                             -- Array of signers who confirmed
    executed_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status VARCHAR(30) CHECK (status IN ('PENDING', 'EXECUTED', 'FAILED', 'CANCELLED')) DEFAULT 'PENDING',

    -- Timing
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_treasury_tx_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_treasury_tx_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_treasury_tx_addresses CHECK (from_address != to_address)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.dao_treasury_transactions IS 'Records transactions from DAO treasuries linked to proposals.';
COMMENT ON COLUMN socialcandor_schema.dao_treasury_transactions.treasury_name IS 'Name or identifier of the treasury (e.g., "Main DAO Treasury").';
COMMENT ON COLUMN socialcandor_schema.dao_treasury_transactions.confirmations IS 'JSON array of signer addresses who have confirmed.';

-- Indexes
CREATE INDEX idx_treasury_tx_address ON socialcandor_schema.dao_treasury_transactions(treasury_address, created_at DESC);
CREATE INDEX idx_treasury_tx_proposal ON socialcandor_schema.dao_treasury_transactions(proposal_id) WHERE proposal_id IS NOT NULL;
CREATE INDEX idx_treasury_tx_hash ON socialcandor_schema.dao_treasury_transactions(tx_hash) WHERE tx_hash IS NOT NULL;
CREATE INDEX idx_treasury_tx_status ON socialcandor_schema.dao_treasury_transactions(status, created_at) WHERE status = 'PENDING';

-- Trigger for updated_at
CREATE TRIGGER trg_treasury_tx_updated_at
    BEFORE UPDATE ON socialcandor_schema.dao_treasury_transactions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.dao_treasury_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY treasury_tx_public_policy ON socialcandor_schema.dao_treasury_transactions
    FOR SELECT USING (TRUE);   -- Treasury transactions are typically public
CREATE POLICY treasury_tx_admin_policy ON socialcandor_schema.dao_treasury_transactions
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));

-- =================================================================================================
-- TABLE: W3T08 - token_balance_snapshots
-- Description: Historical snapshots of token balances for users, used for governance voting,
--              airdrop eligibility, and analytics.
-- Business Case: Many governance and reward mechanisms require point‑in‑time token balances.
--                This table stores periodic snapshots of user token holdings across supported
--                blockchains. Snapshots can be taken at block heights or timestamps (e.g., daily).
--                The data enables calculation of voting power, airdrop distribution, and analysis
--                of token holding patterns. It also supports features like “balance‑based” access
--                control. Snapshots are immutable and indexed for fast historical queries.
-- KPIs:
--   1. Snapshot coverage – Percentage of users with at least one snapshot.
--   2. Balance distribution – Gini coefficient of token holdings.
--   3. Holder churn – Change in holder count over time.
--   4. Snapshot frequency – How often snapshots are taken.
--   5. Data accuracy – Consistency with on‑chain balances (sampling).
-- Feature References: GOV25 (Token‑based Governance), AID01 (Airdrop Management), ANL22 (Token Analytics)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.token_balance_snapshots (
    -- Primary key
    snapshot_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    snapshot_number VARCHAR(50) GENERATED ALWAYS AS (
        'SNAP-' || TO_CHAR(snapshot_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.token_balance_snapshot_seq')::TEXT, 6, '0')
    ) STORED,

    -- User reference
    user_id UUID NOT NULL,

    -- Token identification
    blockchain socialcandor_schema.blockchain_network NOT NULL,
    token_address VARCHAR(255) NOT NULL,            -- Contract address (or NULL for native)
    token_symbol VARCHAR(20),
    token_standard socialcandor_schema.token_standard,

    -- Snapshot details
    snapshot_date DATE NOT NULL,                    -- Date of snapshot (for daily snapshots)
    snapshot_block BIGINT,                           -- Block number at snapshot
    balance NUMERIC(30,18) NOT NULL CHECK (balance >= 0),
    balance_usd NUMERIC(15,2),                       -- Estimated USD value at snapshot time

    -- Source of snapshot
    snapshot_type VARCHAR(30) CHECK (snapshot_type IN ('DAILY', 'BLOCK', 'PROPOSAL', 'AIRDROP', 'MANUAL')),
    proposal_id VARCHAR(255),                         -- If snapshot taken for a specific proposal

    -- Metadata
    snapshot_metadata JSONB,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_token_snapshot_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_token_snapshot_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_token_snapshot_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_token_snapshot UNIQUE (user_id, blockchain, token_address, snapshot_date)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.token_balance_snapshots IS 'Historical snapshots of token balances for governance and analytics.';
COMMENT ON COLUMN socialcandor_schema.token_balance_snapshots.snapshot_date IS 'Date of the snapshot (for daily snapshots).';
COMMENT ON COLUMN socialcandor_schema.token_balance_snapshots.snapshot_block IS 'Block number at which snapshot was taken.';
COMMENT ON COLUMN socialcandor_schema.token_balance_snapshots.balance_usd IS 'Estimated USD value at snapshot time (optional).';

-- Indexes
CREATE INDEX idx_token_snapshot_user ON socialcandor_schema.token_balance_snapshots(user_id, snapshot_date DESC);
CREATE INDEX idx_token_snapshot_token ON socialcandor_schema.token_balance_snapshots(blockchain, token_address, snapshot_date);
CREATE INDEX idx_token_snapshot_proposal ON socialcandor_schema.token_balance_snapshots(proposal_id) WHERE proposal_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_token_snapshot_updated_at
    BEFORE UPDATE ON socialcandor_schema.token_balance_snapshots
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy
ALTER TABLE socialcandor_schema.token_balance_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY token_snapshot_self_policy ON socialcandor_schema.token_balance_snapshots
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY token_snapshot_admin_policy ON socialcandor_schema.token_balance_snapshots
    FOR ALL USING (EXISTS (SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID AND is_admin = TRUE));


--================================================================================================
-- ENUMS (new enums specific to support; existing enums from previous phases are reused)
--================================================================================================

-- Enum: support_escalation_level
-- Description: Defines escalation levels in support workflows
-- Business Case: Standardizes escalation stages (L1, L2, L3, management) for consistent routing
-- Feature Reference: SUP15 (Escalation Management)
--================================================================================================
CREATE TYPE socialcandor_schema.support_escalation_level AS ENUM (
    'L1',        -- Level 1 (frontline)
    'L2',        -- Level 2 (specialist)
    'L3',        -- Level 3 (expert)
    'MANAGER',   -- Management escalation
    'EXTERNAL'   -- External partner/third-party
);
COMMENT ON TYPE socialcandor_schema.support_escalation_level IS 'Defines escalation levels in support workflows';

-- Enum: support_assignment_type
-- Description: Types of ticket assignments (manual, automatic, round-robin, skill-based)
-- Business Case: Enables different assignment strategies based on team configuration
-- Feature Reference: SUP08 (Assignment Strategies)
--================================================================================================
CREATE TYPE socialcandor_schema.support_assignment_type AS ENUM (
    'MANUAL',           -- Manually assigned by supervisor
    'AUTOMATIC',        -- System assigned based on rules
    'ROUND_ROBIN',      -- Rotating assignment among available agents
    'SKILL_BASED',      -- Assigned based on agent skills
    'LOAD_BALANCED'     -- Assigned to least busy agent
);
COMMENT ON TYPE socialcandor_schema.support_assignment_type IS 'Types of ticket assignments for support teams';

--================================================================================================
-- SEQUENCES (for human‑readable identifiers)
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.support_ticket_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.knowledge_article_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.csat_survey_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.escalation_path_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.sla_definition_seq START 1000;

--================================================================================================
-- TABLE: ST01 - support_ticket_categories
-- Description: Defines categories for support tickets (e.g., Billing, Technical, Account)
-- Business Case: Categorization enables proper routing, trend analysis, and specialized handling.
--                Categories can be hierarchical (parent-child) and may have SLAs assigned.
--                This table supports both system-defined and custom categories per tenant.
-- KPIs:
--   1. Ticket distribution by category
--   2. Average resolution time per category
--   3. Category usage trend (volume over time)
--   4. Category‑specific CSAT scores
--   5. Number of active categories per tenant
-- Feature References: SUP01 (Ticket Categories), SUP02 (Categorization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_ticket_categories (
    -- Primary key
    category_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    category_code VARCHAR(50) GENERATED ALWAYS AS (
        'CAT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Category details
    category_name VARCHAR(100) NOT NULL,
    category_description TEXT,
    parent_category_id UUID,                      -- Self-reference for hierarchy
    category_level INTEGER DEFAULT 1 CHECK (category_level >= 1),

    -- Ownership / tenant
    owner_team VARCHAR(100),
    is_system_defined BOOLEAN DEFAULT FALSE,      -- System categories cannot be deleted

    -- Routing rules (JSON for flexibility)
    routing_rules JSONB DEFAULT '{}',              -- e.g., default agent, queue, priority

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deprecated BOOLEAN DEFAULT FALSE,
    deprecated_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_support_ticket_categories_parent FOREIGN KEY (parent_category_id)
        REFERENCES socialcandor_schema.support_ticket_categories(category_id) ON DELETE SET NULL,
    CONSTRAINT fk_support_ticket_categories_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_support_ticket_categories_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_support_ticket_category_name UNIQUE (category_name)  -- Simplified; may need tenant scope
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_ticket_categories IS 'Defines categories for support tickets with hierarchical support';
COMMENT ON COLUMN socialcandor_schema.support_ticket_categories.category_code IS 'Human‑readable unique code for the category';
COMMENT ON COLUMN socialcandor_schema.support_ticket_categories.routing_rules IS 'JSON defining default routing (agent, queue, priority)';
COMMENT ON COLUMN socialcandor_schema.support_ticket_categories.category_level IS 'Depth in category hierarchy (1 = top-level)';

-- Indexes
CREATE INDEX idx_support_ticket_categories_parent ON socialcandor_schema.support_ticket_categories(parent_category_id) WHERE parent_category_id IS NOT NULL;
CREATE INDEX idx_support_ticket_categories_active ON socialcandor_schema.support_ticket_categories(is_active, is_deprecated) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_support_ticket_categories_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_ticket_categories
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins only; agents can view)
ALTER TABLE socialcandor_schema.support_ticket_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_ticket_categories_admin_policy ON socialcandor_schema.support_ticket_categories
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY support_ticket_categories_view_policy ON socialcandor_schema.support_ticket_categories
    FOR SELECT USING (TRUE);

--================================================================================================
-- TABLE: ST02 - support_ticket_priorities
-- Description: Defines priority levels for support tickets (e.g., Critical, High, Medium, Low)
-- Business Case: Priorities determine response/resolution SLAs, escalation triggers, and
--                agent attention. This table allows dynamic priority definitions with
--                configurable response times, colors for UI, and ordering.
-- KPIs:
--   1. Ticket volume by priority
--   2. SLA compliance rate per priority
--   3. Average time in each priority (including re-prioritization)
--   4. Escalation rate by priority
--   5. Priority‑specific CSAT scores
-- Feature References: SUP03 (Priority Management), SUP04 (SLA Integration)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_ticket_priorities (
    -- Primary key
    priority_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    priority_code VARCHAR(50) GENERATED ALWAYS AS (
        'PRI-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Priority details
    priority_name VARCHAR(50) NOT NULL,
    priority_description TEXT,
    priority_level INTEGER NOT NULL CHECK (priority_level >= 1 AND priority_level <= 10), -- 1 = highest
    color_hex CHAR(7) CHECK (color_hex ~ '^#[0-9A-Fa-f]{6}$'),  -- For UI consistency

    -- SLA targets (in minutes)
    response_time_target INTEGER NOT NULL CHECK (response_time_target >= 0),
    resolution_time_target INTEGER NOT NULL CHECK (resolution_time_target >= 0),
    update_frequency_target INTEGER CHECK (update_frequency_target >= 0),  -- How often to update customer

    -- Business hours applicability
    business_hours_only BOOLEAN DEFAULT FALSE,      -- If TRUE, count only business hours

    -- Escalation thresholds
    escalation_threshold_minutes INTEGER CHECK (escalation_threshold_minutes >= 0),

    -- Order for display
    display_order INTEGER DEFAULT 0 CHECK (display_order >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_system_defined BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_support_ticket_priorities_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_support_ticket_priorities_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_support_ticket_priority_name UNIQUE (priority_name)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_ticket_priorities IS 'Defines priority levels with SLA targets and escalation rules';
COMMENT ON COLUMN socialcandor_schema.support_ticket_priorities.priority_level IS 'Numeric level (1 = highest) for ordering';
COMMENT ON COLUMN socialcandor_schema.support_ticket_priorities.color_hex IS 'Hex color code for UI representation';
COMMENT ON COLUMN socialcandor_schema.support_ticket_priorities.business_hours_only IS 'If TRUE, SLA calculation excludes non‑business hours';

-- Indexes
CREATE INDEX idx_support_ticket_priorities_level ON socialcandor_schema.support_ticket_priorities(priority_level) WHERE is_active = TRUE;
CREATE INDEX idx_support_ticket_priorities_active ON socialcandor_schema.support_ticket_priorities(is_active) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_support_ticket_priorities_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_ticket_priorities
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins only; all users can view)
ALTER TABLE socialcandor_schema.support_ticket_priorities ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_ticket_priorities_admin_policy ON socialcandor_schema.support_ticket_priorities
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY support_ticket_priorities_view_policy ON socialcandor_schema.support_ticket_priorities
    FOR SELECT USING (TRUE);

--================================================================================================
-- TABLE: ST03 - support_sla_definitions
-- Description: Defines Service Level Agreements (SLAs) for support tickets, combining
--              categories, priorities, and customer tiers to determine response and resolution
--              time commitments. Supports conditional rules and override capabilities.
-- Business Case: Different customer segments and issue types require differentiated service
--                levels. This table centralizes SLA definitions, enabling automated tracking,
--                escalation, and compliance reporting. The design supports multiple criteria
--                (category, priority, customer tier) and allows overriding at the ticket level.
-- KPIs:
--   1. SLA compliance rate (overall and by segment)
--   2. Average breach detection time
--   3. Number of active SLAs
--   4. Override frequency and reasons
--   5. Customer satisfaction correlation with SLA compliance
-- Feature References: SUP05 (SLA Management), SUP06 (SLA Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_sla_definitions (
    -- Primary key
    sla_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    sla_code VARCHAR(50) GENERATED ALWAYS AS (
        'SLA-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.sla_definition_seq')::TEXT, 6, '0')
    ) STORED,

    -- SLA identification
    sla_name VARCHAR(255) NOT NULL,
    sla_description TEXT,
    sla_version VARCHAR(20) DEFAULT '1.0',

    -- Applicability (which tickets this SLA applies to)
    applicable_categories UUID[],                 -- Array of category IDs (NULL = all)
    applicable_priorities UUID[],                  -- Array of priority IDs (NULL = all)
    applicable_customer_tiers TEXT[] DEFAULT '{}', -- e.g., 'BASIC', 'PREMIUM', 'ENTERPRISE'
    applicable_products UUID[],                     -- Array of product IDs (NULL = all)

    -- Time targets (in minutes)
    first_response_target INTEGER NOT NULL CHECK (first_response_target >= 0),
    subsequent_response_target INTEGER CHECK (subsequent_response_target >= 0), -- For follow-ups
    resolution_target INTEGER NOT NULL CHECK (resolution_target >= 0),
    update_frequency_target INTEGER CHECK (update_frequency_target >= 0),       -- Min time between updates

    -- Business hours
    business_hours_id UUID,                         -- Reference to business hours definition (could be separate table)
    use_calendar_days BOOLEAN DEFAULT FALSE,        -- FALSE = business hours only

    -- Escalation thresholds (array of {level, time, assignee})
    escalation_thresholds JSONB DEFAULT '[]',

    -- Overage handling
    overage_action VARCHAR(50) CHECK (overage_action IN ('NOTIFY_ONLY', 'ESCALATE', 'PENALTY', 'MANUAL_REVIEW')),

    -- Penalties (for contractual SLAs)
    penalty_percentage NUMERIC(5,2) CHECK (penalty_percentage >= 0 AND penalty_percentage <= 100),
    penalty_cap_percentage NUMERIC(5,2) CHECK (penalty_cap_percentage >= 0 AND penalty_cap_percentage <= 100),

    -- Effective dating
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL OR effective_to >= CURRENT_DATE) STORED,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    superseded_by UUID,                              -- Link to newer version

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_support_sla_superseded FOREIGN KEY (superseded_by)
        REFERENCES socialcandor_schema.support_sla_definitions(sla_id) ON DELETE SET NULL,
    CONSTRAINT fk_support_sla_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_support_sla_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_support_sla_dates CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_sla_definitions IS 'Defines Service Level Agreements for support tickets with multi‑criteria applicability';
COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.applicable_categories IS 'Array of category IDs this SLA applies to (NULL = all)';
COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.applicable_priorities IS 'Array of priority IDs this SLA applies to (NULL = all)';
COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.escalation_thresholds IS 'JSON array defining escalation levels, times, and target assignees';
COMMENT ON COLUMN socialcandor_schema.support_sla_definitions.business_hours_id IS 'Reference to business hours definition (placeholder)';

-- Indexes for performance
CREATE INDEX idx_support_sla_applicability ON socialcandor_schema.support_sla_definitions USING GIN (applicable_categories, applicable_priorities);
CREATE INDEX idx_support_sla_active ON socialcandor_schema.support_sla_definitions(is_active, effective_from, effective_to) WHERE is_active = TRUE;
CREATE INDEX idx_support_sla_superseded ON socialcandor_schema.support_sla_definitions(superseded_by) WHERE superseded_by IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_support_sla_definitions_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_sla_definitions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins and support managers only; agents can view)
ALTER TABLE socialcandor_schema.support_sla_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_sla_admin_policy ON socialcandor_schema.support_sla_definitions
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY support_sla_manager_policy ON socialcandor_schema.support_sla_definitions
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
    ));
CREATE POLICY support_sla_view_policy ON socialcandor_schema.support_sla_definitions
    FOR SELECT USING (TRUE);

--================================================================================================
-- TABLE: ST04 - support_agent_assignments
-- Description: Tracks assignment of tickets to support agents, including manual and automatic
--              assignments, with timestamps and assignment type. Enables load balancing and
--              performance tracking.
-- Business Case: Efficient ticket assignment is key to resolution speed. This table records
--                all assignments, re-assignments, and unassignments, providing audit trail for
--                agent performance and workload management. It supports round‑robin, skill‑based,
--                and manual assignment strategies. Historical data helps optimize assignment rules.
-- KPIs:
--   1. Average first assignment time
--   2. Number of re-assignments per ticket
--   3. Agent workload distribution
--   4. Assignment‑to‑first‑response time
--   5. Agent performance by assignment type
-- Feature References: SUP07 (Agent Assignment), SUP08 (Assignment Strategies)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_agent_assignments (
    -- Primary key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    assignment_number VARCHAR(50) GENERATED ALWAYS AS (
        'ASG-' || TO_CHAR(assigned_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM assigned_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- References
    ticket_id UUID NOT NULL,                         -- References user_feedback_tickets or support_ticketing
    agent_user_id UUID NOT NULL,                      -- Support agent (user with support role)
    assigned_by UUID,                                 -- Who performed the assignment (NULL if automatic)

    -- Assignment details
    assignment_type socialcandor_schema.support_assignment_type NOT NULL,
    is_primary BOOLEAN DEFAULT TRUE,                  -- Primary owner of the ticket
    assignment_order INTEGER DEFAULT 1,                -- In case of multiple assignments (e.g., CC)

    -- Timestamps
    assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unassigned_at TIMESTAMP WITH TIME ZONE,
    unassign_reason VARCHAR(100),

    -- Workload metrics (denormalized at assignment time)
    agent_current_load INTEGER,                        -- Number of open tickets at time of assignment

    -- Skill match (if skill‑based)
    skill_match_score NUMERIC(5,2) CHECK (skill_match_score >= 0 AND skill_match_score <= 100),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_agent_assignments_ticket FOREIGN KEY (ticket_id)
        REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE CASCADE,
    CONSTRAINT fk_agent_assignments_agent FOREIGN KEY (agent_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_agent_assignments_assigned_by FOREIGN KEY (assigned_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_agent_assignments_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_agent_assignments_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_agent_assignments_dates CHECK (unassigned_at IS NULL OR unassigned_at >= assigned_at)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_agent_assignments IS 'Tracks assignment of tickets to support agents with audit trail';
COMMENT ON COLUMN socialcandor_schema.support_agent_assignments.assignment_type IS 'Method used for assignment (manual, automatic, round‑robin, etc.)';
COMMENT ON COLUMN socialcandor_schema.support_agent_assignments.is_primary IS 'Whether this agent is the primary owner';
COMMENT ON COLUMN socialcandor_schema.support_agent_assignments.agent_current_load IS 'Snapshot of agent’s open ticket count at assignment time';
COMMENT ON COLUMN socialcandor_schema.support_agent_assignments.skill_match_score IS 'How well the agent’s skills match the ticket category';

-- Indexes for performance
CREATE INDEX idx_agent_assignments_ticket ON socialcandor_schema.support_agent_assignments(ticket_id, is_primary) WHERE is_primary = TRUE;
CREATE INDEX idx_agent_assignments_agent ON socialcandor_schema.support_agent_assignments(agent_user_id, assigned_at DESC);
CREATE INDEX idx_agent_assignments_active ON socialcandor_schema.support_agent_assignments(agent_user_id) WHERE unassigned_at IS NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_support_agent_assignments_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_agent_assignments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins and agents see relevant; users see their own tickets)
ALTER TABLE socialcandor_schema.support_agent_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY agent_assignments_agent_policy ON socialcandor_schema.support_agent_assignments
    FOR SELECT USING (agent_user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY agent_assignments_admin_policy ON socialcandor_schema.support_agent_assignments
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY agent_assignments_manager_policy ON socialcandor_schema.support_agent_assignments
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
    ));

--================================================================================================
-- TABLE: ST05 - support_knowledge_articles
-- Description: Stores knowledge base articles for self‑service support, including title,
--              content, metadata, and versioning. Articles can be categorized, tagged, and
--              associated with tickets for suggested solutions.
-- Business Case: A comprehensive knowledge base reduces ticket volume by empowering users
--                to find answers independently. This table supports full‑text search,
--                article versioning, and feedback collection. Integration with ticketing
--                enables suggested articles based on ticket category and keywords.
-- KPIs:
--   1. Article view count
--   2. Helpfulness rating (CSAT per article)
--   3. Ticket deflection rate (views that prevent ticket creation)
--   4. Most‑viewed categories
--   5. Article freshness (time since last update)
-- Feature References: SUP09 (Knowledge Base), SUP10 (Article Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_knowledge_articles (
    -- Primary key
    article_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    article_code VARCHAR(50) GENERATED ALWAYS AS (
        'KB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.knowledge_article_seq')::TEXT, 6, '0')
    ) STORED,

    -- Article identification
    title VARCHAR(500) NOT NULL,
    slug VARCHAR(500) UNIQUE NOT NULL,                 -- URL‑friendly version
    excerpt TEXT,                                       -- Short summary

    -- Content
    content TEXT NOT NULL,
    content_html TEXT,                                  -- Rendered version
    content_format VARCHAR(20) DEFAULT 'MARKDOWN' CHECK (content_format IN ('MARKDOWN', 'HTML', 'PLAIN')),

    -- Categorization
    primary_category_id UUID,                           -- Main category
    additional_categories UUID[],                        -- Multiple categories
    tags TEXT[],

    -- Metadata
    author_id UUID NOT NULL,                             -- Original author
    editor_id UUID,                                      -- Last editor
    version INTEGER DEFAULT 1,
    is_published BOOLEAN DEFAULT FALSE,
    published_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- SEO
    meta_description VARCHAR(320),
    meta_keywords TEXT[],
    canonical_url VARCHAR(500),

    -- Media
    featured_image_url VARCHAR(500),
    attachments JSONB DEFAULT '[]',                      -- URLs to related files

    -- Statistics
    view_count INTEGER DEFAULT 0 CHECK (view_count >= 0),
    helpful_count INTEGER DEFAULT 0 CHECK (helpful_count >= 0),
    not_helpful_count INTEGER DEFAULT 0 CHECK (not_helpful_count >= 0),
    average_rating NUMERIC(3,2) CHECK (average_rating >= 0 AND average_rating <= 5),

    -- Feedback
    feedback JSONB DEFAULT '[]',                          -- Recent user feedback (limited)

    -- Related tickets (for troubleshooting)
    related_ticket_ids UUID[],

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_knowledge_articles_primary_category FOREIGN KEY (primary_category_id)
        REFERENCES socialcandor_schema.support_knowledge_categories(category_id) ON DELETE SET NULL,
    CONSTRAINT fk_knowledge_articles_author FOREIGN KEY (author_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_knowledge_articles_editor FOREIGN KEY (editor_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_knowledge_articles_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_knowledge_articles_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_knowledge_articles_publish CHECK (published_at IS NULL OR published_at <= CURRENT_TIMESTAMP)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_knowledge_articles IS 'Knowledge base articles for self‑service support with versioning and feedback';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_articles.slug IS 'URL‑friendly unique identifier';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_articles.additional_categories IS 'Array of additional category IDs for multi‑categorization';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_articles.feedback IS 'Recent user feedback for trend analysis';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_articles.related_ticket_ids IS 'Tickets that were resolved by this article';

-- Indexes for performance
CREATE INDEX idx_knowledge_articles_slug ON socialcandor_schema.support_knowledge_articles(slug);
CREATE INDEX idx_knowledge_articles_category ON socialcandor_schema.support_knowledge_articles(primary_category_id) WHERE primary_category_id IS NOT NULL;
CREATE INDEX idx_knowledge_articles_published ON socialcandor_schema.support_knowledge_articles(published_at DESC) WHERE is_published = TRUE;
CREATE INDEX idx_knowledge_articles_tags ON socialcandor_schema.support_knowledge_articles USING GIN (tags);
CREATE INDEX idx_knowledge_articles_search ON socialcandor_schema.support_knowledge_articles USING GIN (to_tsvector('english', title || ' ' || excerpt || ' ' || content));

-- Trigger for updated_at
CREATE TRIGGER trg_support_knowledge_articles_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_knowledge_articles
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins and content editors manage; all users can read published)
ALTER TABLE socialcandor_schema.support_knowledge_articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_articles_read_policy ON socialcandor_schema.support_knowledge_articles
    FOR SELECT USING (is_published = TRUE);
CREATE POLICY knowledge_articles_author_policy ON socialcandor_schema.support_knowledge_articles
    FOR ALL USING (author_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY knowledge_articles_admin_policy ON socialcandor_schema.support_knowledge_articles
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY knowledge_articles_editor_policy ON socialcandor_schema.support_knowledge_articles
    FOR UPDATE USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('KNOWLEDGE_MANAGER', 'SUPPORT_MANAGER')
    ));

--================================================================================================
-- TABLE: ST06 - support_knowledge_categories
-- Description: Hierarchical categories for knowledge base articles, enabling organized browsing
--              and search filtering. Supports multi‑level taxonomies.
-- Business Case: Well‑structured categories help users find relevant articles quickly and
--                enable analytics on content gaps. Hierarchical design allows broad categories
--                (e.g., Billing) and sub‑categories (e.g., Invoicing, Refunds). The table
--                supports multiple languages through translation tables (not shown).
-- KPIs:
--   1. Number of articles per category
--   2. Category usage in search filters
--   3. Category view vs. article view ratio
--   4. Category depth distribution
--   5. Unpopulated categories (no articles)
-- Feature References: SUP11 (KB Categories), SUP12 (Content Organization)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_knowledge_categories (
    -- Primary key
    category_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    category_code VARCHAR(50) GENERATED ALWAYS AS (
        'KBCAT-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Category details
    name VARCHAR(255) NOT NULL,
    slug VARCHAR(255) UNIQUE NOT NULL,
    description TEXT,
    icon_url VARCHAR(500),
    color_hex CHAR(7) CHECK (color_hex ~ '^#[0-9A-Fa-f]{6}$'),

    -- Hierarchy
    parent_category_id UUID,
    category_level INTEGER DEFAULT 1 CHECK (category_level >= 1),
    path LTREE,                                          -- Materialized path for fast subtree queries

    -- Display
    display_order INTEGER DEFAULT 0,
    is_visible BOOLEAN DEFAULT TRUE,

    -- SEO
    meta_description VARCHAR(320),
    meta_keywords TEXT[],

    -- Statistics
    article_count INTEGER DEFAULT 0 CHECK (article_count >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deprecated BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_knowledge_categories_parent FOREIGN KEY (parent_category_id)
        REFERENCES socialcandor_schema.support_knowledge_categories(category_id) ON DELETE SET NULL,
    CONSTRAINT fk_knowledge_categories_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_knowledge_categories_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_knowledge_categories IS 'Hierarchical categories for knowledge base articles';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_categories.slug IS 'URL‑friendly unique identifier';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_categories.path IS 'LTREE materialized path for efficient hierarchical queries';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_categories.category_level IS 'Depth in hierarchy (1 = top‑level)';
COMMENT ON COLUMN socialcandor_schema.support_knowledge_categories.article_count IS 'Denormalized count of articles in this category';

-- Indexes for performance
CREATE INDEX idx_knowledge_categories_parent ON socialcandor_schema.support_knowledge_categories(parent_category_id) WHERE parent_category_id IS NOT NULL;
CREATE INDEX idx_knowledge_categories_path ON socialcandor_schema.support_knowledge_categories USING GIST(path);
CREATE INDEX idx_knowledge_categories_slug ON socialcandor_schema.support_knowledge_categories(slug);

-- Trigger for updated_at
CREATE TRIGGER trg_support_knowledge_categories_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_knowledge_categories
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins and content managers only; all users can view)
ALTER TABLE socialcandor_schema.support_knowledge_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_categories_admin_policy ON socialcandor_schema.support_knowledge_categories
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY knowledge_categories_editor_policy ON socialcandor_schema.support_knowledge_categories
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('KNOWLEDGE_MANAGER', 'SUPPORT_MANAGER')
    ));
CREATE POLICY knowledge_categories_view_policy ON socialcandor_schema.support_knowledge_categories
    FOR SELECT USING (is_visible = TRUE);

--================================================================================================
-- TABLE: ST07 - support_csat_surveys
-- Description: Captures customer satisfaction (CSAT) surveys sent after ticket resolution,
--              including ratings, feedback, and metadata for analysis.
-- Business Case: CSAT is a key metric for support quality and customer retention. This table
--                stores survey responses, enabling analysis of satisfaction by agent, category,
--                priority, and resolution time. It supports multiple question types (rating,
--                NPS, free text) and follows up on low ratings for improvement.
-- KPIs:
--   1. Average CSAT score (overall and by agent)
--   2. Survey response rate
--   3. NPS score distribution
--   4. Satisfaction trend over time
--   5. Correlation between resolution time and CSAT
-- Feature References: SUP13 (CSAT Surveys), SUP14 (Feedback Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_csat_surveys (
    -- Primary key
    survey_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    survey_number VARCHAR(50) GENERATED ALWAYS AS (
        'CSAT-' || TO_CHAR(sent_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.csat_survey_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    ticket_id UUID NOT NULL,
    user_id UUID NOT NULL,
    agent_id UUID,                                      -- Primary agent on ticket

    -- Survey metadata
    survey_type VARCHAR(30) DEFAULT 'POST_TICKET' CHECK (survey_type IN ('POST_TICKET', 'POST_CHAT', 'PERIODIC')),
    survey_channel VARCHAR(30) CHECK (survey_channel IN ('EMAIL', 'IN_APP', 'SMS', 'WEB_LINK')),

    -- Sent and response timestamps
    sent_at TIMESTAMP WITH TIME ZONE NOT NULL,
    responded_at TIMESTAMP WITH TIME ZONE,
    response_time_minutes INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (responded_at - sent_at)) / 60
    ) STORED,

    -- Core satisfaction metrics
    overall_rating INTEGER CHECK (overall_rating >= 1 AND overall_rating <= 5),  -- 1‑5 scale
    nps_score INTEGER CHECK (nps_score >= 0 AND nps_score <= 10),                 -- 0‑10 for NPS
    would_recommend BOOLEAN,                                                       -- Simplified binary

    -- Detailed feedback
    agent_rating INTEGER CHECK (agent_rating >= 1 AND agent_rating <= 5),
    resolution_rating INTEGER CHECK (resolution_rating >= 1 AND resolution_rating <= 5),
    time_rating INTEGER CHECK (time_rating >= 1 AND time_rating <= 5),

    -- Question‑specific responses (flexible)
    question_responses JSONB DEFAULT '[]',               -- Array of {question_id, rating, comment}

    -- Comments
    positive_comment TEXT,
    improvement_comment TEXT,
    additional_feedback TEXT,

    -- Follow‑up
    follow_up_requested BOOLEAN DEFAULT FALSE,
    follow_up_contacted BOOLEAN DEFAULT FALSE,
    follow_up_notes TEXT,

    -- Status
    status VARCHAR(30) DEFAULT 'SENT' CHECK (status IN ('SENT', 'VIEWED', 'PARTIAL', 'COMPLETED', 'EXPIRED')),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_csat_surveys_ticket FOREIGN KEY (ticket_id)
        REFERENCES socialcandor_schema.user_feedback_tickets(ticket_id) ON DELETE CASCADE,
    CONSTRAINT fk_csat_surveys_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_csat_surveys_agent FOREIGN KEY (agent_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_csat_surveys_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_csat_surveys_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_csat_surveys_ticket UNIQUE (ticket_id)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_csat_surveys IS 'Customer satisfaction surveys sent after ticket resolution';
COMMENT ON COLUMN socialcandor_schema.support_csat_surveys.nps_score IS 'Net Promoter Score on 0‑10 scale';
COMMENT ON COLUMN socialcandor_schema.support_csat_surveys.question_responses IS 'JSON array for multi‑question surveys';
COMMENT ON COLUMN socialcandor_schema.support_csat_surveys.response_time_minutes IS 'Time between survey send and response';

-- Indexes for performance
CREATE INDEX idx_csat_surveys_ticket ON socialcandor_schema.support_csat_surveys(ticket_id);
CREATE INDEX idx_csat_surveys_user ON socialcandor_schema.support_csat_surveys(user_id, responded_at DESC);
CREATE INDEX idx_csat_surveys_agent ON socialcandor_schema.support_csat_surveys(agent_id, overall_rating) WHERE agent_id IS NOT NULL;
CREATE INDEX idx_csat_surveys_rating ON socialcandor_schema.support_csat_surveys(overall_rating, created_at DESC);
CREATE INDEX idx_csat_surveys_status ON socialcandor_schema.support_csat_surveys(status, sent_at) WHERE status = 'SENT';

-- Trigger for updated_at
CREATE TRIGGER trg_support_csat_surveys_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_csat_surveys
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (users see their own; agents see their own; admins all)
ALTER TABLE socialcandor_schema.support_csat_surveys ENABLE ROW LEVEL SECURITY;
CREATE POLICY csat_surveys_self_policy ON socialcandor_schema.support_csat_surveys
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY csat_surveys_agent_policy ON socialcandor_schema.support_csat_surveys
    FOR SELECT USING (agent_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY csat_surveys_admin_policy ON socialcandor_schema.support_csat_surveys
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: ST08 - support_escalation_paths
-- Description: Defines escalation rules for support tickets based on criteria like priority,
--              category, customer tier, and time thresholds. Supports multi‑level escalation
--              to different teams or individuals.
-- Business Case: Automated escalation ensures timely resolution of critical issues and
--                prevents tickets from being forgotten. This table centralizes escalation
--                logic, enabling configuration without code changes. Escalation can be
--                time‑based (SLA breach) or event‑based (customer request, manual trigger).
--                The design supports branching paths and fallback assignments.
-- KPIs:
--   1. Escalation frequency (by level, by reason)
--   2. Time to first escalation
--   3. Escalation resolution rate (percentage resolved after escalation)
--   4. Over‑escalation rate (escalations that should not have happened)
--   5. Escalation path usage statistics
-- Feature References: SUP15 (Escalation Paths), SUP16 (Escalation Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.support_escalation_paths (
    -- Primary key
    path_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    path_code VARCHAR(50) GENERATED ALWAYS AS (
        'ESC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.escalation_path_seq')::TEXT, 6, '0')
    ) STORED,

    -- Path identification
    path_name VARCHAR(255) NOT NULL,
    path_description TEXT,
    path_version VARCHAR(20) DEFAULT '1.0',

    -- Trigger criteria
    trigger_type VARCHAR(50) NOT NULL CHECK (trigger_type IN (
        'SLA_VIOLATION',        -- Response/resolution time exceeded
        'TIME_ELAPSED',         -- Ticket age without update
        'USER_REQUEST',         -- Customer asked for escalation
        'CATEGORY_CHANGE',      -- Category changed to higher tier
        'PRIORITY_CHANGE',      -- Priority increased
        'MANUAL',                -- Manual escalation by agent/manager
        'REOPENED'               -- Ticket reopened after resolution
    )),
    trigger_criteria JSONB NOT NULL,            -- e.g., {"priority": ["P1", "P2"], "categories": [...]}

    -- Applicability filters
    applicable_categories UUID[],                -- NULL = all
    applicable_priorities UUID[],                 -- NULL = all
    applicable_customer_tiers TEXT[] DEFAULT '{}',
    minimum_ticket_age_minutes INTEGER CHECK (minimum_ticket_age_minutes >= 0),

    -- Escalation steps (ordered array)
    escalation_steps JSONB NOT NULL,             -- Array of {level, assign_to, notify, timeout_minutes}

    -- Notification rules
    notify_customer BOOLEAN DEFAULT FALSE,
    notify_previous_owner BOOLEAN DEFAULT TRUE,
    additional_notification_recipients TEXT[],

    -- Fallback
    fallback_team VARCHAR(100),                  -- Team to assign if no matching assignee
    fallback_user_id UUID,                        -- Individual to assign as fallback

    -- Cooldown (prevent repeated escalations)
    cooldown_minutes INTEGER DEFAULT 60 CHECK (cooldown_minutes >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_current BOOLEAN GENERATED ALWAYS AS (effective_to IS NULL OR effective_to >= CURRENT_DATE) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_escalation_paths_fallback_user FOREIGN KEY (fallback_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_escalation_paths_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_escalation_paths_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_escalation_paths_dates CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.support_escalation_paths IS 'Defines automated escalation rules for support tickets';
COMMENT ON COLUMN socialcandor_schema.support_escalation_paths.trigger_type IS 'Event that triggers the escalation path';
COMMENT ON COLUMN socialcandor_schema.support_escalation_paths.trigger_criteria IS 'JSON conditions for when to apply this path';
COMMENT ON COLUMN socialcandor_schema.support_escalation_paths.escalation_steps IS 'JSON array defining escalation levels, target assignees, and timeouts';
COMMENT ON COLUMN socialcandor_schema.support_escalation_paths.cooldown_minutes IS 'Time to wait before re‑triggering the same path';

-- Indexes for performance
CREATE INDEX idx_escalation_paths_active ON socialcandor_schema.support_escalation_paths(is_active, effective_from, effective_to) WHERE is_active = TRUE;
CREATE INDEX idx_escalation_paths_trigger ON socialcandor_schema.support_escalation_paths(trigger_type) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_support_escalation_paths_updated_at
    BEFORE UPDATE ON socialcandor_schema.support_escalation_paths
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policy (admins and support managers only)
ALTER TABLE socialcandor_schema.support_escalation_paths ENABLE ROW LEVEL SECURITY;
CREATE POLICY escalation_paths_admin_policy ON socialcandor_schema.support_escalation_paths
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY escalation_paths_manager_policy ON socialcandor_schema.support_escalation_paths
    FOR ALL USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('SUPPORT_MANAGER', 'SUPPORT_LEAD')
    ));

--================================================================================================
-- MATERIALIZED VIEW: mv_support_performance
-- Description: Pre‑aggregated view for support performance metrics, including ticket volume,
--              average response/resolution times, CSAT scores, and SLA compliance rates,
--              broken down by day, category, priority, and agent team.
-- Business Case: Provides fast access to support KPIs for dashboards and reporting, avoiding
--                expensive real‑time aggregations. Refreshed daily.
-- Feature References: SUP17 (Performance Reporting), SUP18 (Dashboards)
--================================================================================================
CREATE MATERIALIZED VIEW IF NOT EXISTS socialcandor_schema.mv_support_performance AS
WITH ticket_metrics AS (
    SELECT
        DATE_TRUNC('day', t.created_at)::DATE AS metric_date,
        t.category_id,
        t.priority_id,
        t.assigned_team,
        COUNT(t.ticket_id) AS tickets_created,
        AVG(EXTRACT(EPOCH FROM (t.first_response_at - t.created_at))/60)::NUMERIC(10,2) AS avg_first_response_minutes,
        AVG(EXTRACT(EPOCH FROM (t.resolved_at - t.created_at))/3600)::NUMERIC(10,2) AS avg_resolution_hours,
        SUM(CASE WHEN t.sla_compliant THEN 1 ELSE 0 END)::NUMERIC / COUNT(t.ticket_id)::NUMERIC * 100 AS sla_compliance_pct
    FROM socialcandor_schema.user_feedback_tickets t
    GROUP BY 1,2,3,4
),
csat_metrics AS (
    SELECT
        DATE_TRUNC('day', cs.responded_at)::DATE AS metric_date,
        cs.agent_id,
        AVG(cs.overall_rating) AS avg_csat,
        COUNT(cs.survey_id) AS survey_count
    FROM socialcandor_schema.support_csat_surveys cs
    WHERE cs.responded_at IS NOT NULL
    GROUP BY 1,2
)
SELECT
    COALESCE(t.metric_date, c.metric_date) AS metric_date,
    t.category_id,
    t.priority_id,
    t.assigned_team,
    t.tickets_created,
    t.avg_first_response_minutes,
    t.avg_resolution_hours,
    t.sla_compliance_pct,
    c.agent_id,
    c.avg_csat,
    c.survey_count
FROM ticket_metrics t
FULL OUTER JOIN csat_metrics c ON t.metric_date = c.metric_date AND t.assigned_team = c.agent_id;

COMMENT ON MATERIALIZED VIEW socialcandor_schema.mv_support_performance IS 'Daily aggregated support performance metrics for dashboards';

CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_support_performance
    ON socialcandor_schema.mv_support_performance(metric_date, category_id, priority_id, assigned_team, agent_id);



--================================================================================================
-- ENUMS
--================================================================================================

-- Enum: IAE01 - webhook_status
-- Description: Defines the lifecycle state of a webhook subscription.
-- Business Case: Enables control over webhook delivery (active, paused, disabled) for maintenance,
--                error handling, and user preferences.
-- KPIs: Active webhook count, paused vs active ratio, disable reason distribution.
-- Feature Reference: API01 (Webhook Management)
--================================================================================================
CREATE TYPE socialcandor_schema.webhook_status AS ENUM (
    'ACTIVE',      -- Webhook is active and delivering events
    'PAUSED',      -- Temporarily paused (e.g., due to failures)
    'DISABLED'     -- Permanently disabled by user/admin
);
COMMENT ON TYPE socialcandor_schema.webhook_status IS 'Lifecycle state of a webhook subscription.';

-- Enum: IAE02 - webhook_delivery_status
-- Description: Status of an individual webhook delivery attempt.
-- Business Case: Tracks delivery success/failure for monitoring and retry logic.
-- KPIs: Delivery success rate, retry rate, failure reason distribution.
-- Feature Reference: API02 (Webhook Delivery)
--================================================================================================
CREATE TYPE socialcandor_schema.webhook_delivery_status AS ENUM (
    'PENDING',      -- Queued for delivery
    'DELIVERED',    -- Successfully delivered
    'FAILED',       -- Failed after retries
    'RETRYING'      -- Failed but will be retried
);
COMMENT ON TYPE socialcandor_schema.webhook_delivery_status IS 'Status of an individual webhook delivery attempt.';

-- Enum: IAE03 - integration_credential_type
-- Description: Types of credentials stored for third‑party integrations.
-- Business Case: Differentiates between OAuth2, API keys, basic auth for secure handling.
-- KPIs: Credential type distribution, expiry rates.
-- Feature Reference: INT01 (Integration Credentials)
--================================================================================================
CREATE TYPE socialcandor_schema.integration_credential_type AS ENUM (
    'OAUTH2',           -- OAuth 2.0 tokens
    'API_KEY',          -- Simple API key
    'BASIC_AUTH',       -- Username/password (encrypted)
    'JWT',              -- JSON Web Token
    'CUSTOM'            -- Custom authentication
);
COMMENT ON TYPE socialcandor_schema.integration_credential_type IS 'Types of credentials stored for third‑party integrations.';

-- Enum: IAE04 - mapping_direction
-- Description: Direction of field mapping between platform and external system.
-- Business Case: Supports bidirectional synchronization (inbound/outbound).
-- KPIs: Mapping usage by direction, transformation complexity.
-- Feature Reference: INT02 (Field Mappings)
--================================================================================================
CREATE TYPE socialcandor_schema.mapping_direction AS ENUM (
    'INBOUND',      -- External → Platform
    'OUTBOUND'      -- Platform → External
);
COMMENT ON TYPE socialcandor_schema.mapping_direction IS 'Direction of field mapping between platform and external system.';

-- Enum: IAE05 - subscriber_type
-- Description: Type of entity subscribing to platform events.
-- Business Case: Enables flexible event routing to users, clients, or organizations.
-- KPIs: Subscriber distribution, event popularity.
-- Feature Reference: API03 (Event Subscriptions)
--================================================================================================
CREATE TYPE socialcandor_schema.subscriber_type AS ENUM (
    'USER',
    'CLIENT',
    'ORGANIZATION'
);
COMMENT ON TYPE socialcandor_schema.subscriber_type IS 'Type of entity subscribing to platform events.';

-- Enum: IAE06 - notification_channel
-- Description: Delivery channel for event notifications.
-- Business Case: Supports multi‑channel notifications (email, push, webhook, SMS).
-- KPIs: Channel success rates, user preferences.
-- Feature Reference: API04 (Notification Channels)
--================================================================================================
CREATE TYPE socialcandor_schema.notification_channel AS ENUM (
    'EMAIL',
    'PUSH',
    'WEBHOOK',
    'SMS'
);
COMMENT ON TYPE socialcandor_schema.notification_channel IS 'Delivery channel for event notifications.';

-- Enum: IAE07 - error_severity
-- Description: Severity level for API errors.
-- Business Case: Prioritizes error investigation and alerting.
-- KPIs: Error volume by severity, MTTR.
-- Feature Reference: OBS01 (Error Monitoring)
--================================================================================================
CREATE TYPE socialcandor_schema.error_severity AS ENUM (
    'INFO',         -- Informational, no action needed
    'WARNING',      -- Potential issue, investigate
    'ERROR',        -- Operation failed, needs attention
    'CRITICAL'      -- System impact, immediate action
);
COMMENT ON TYPE socialcandor_schema.error_severity IS 'Severity level for API errors.';

--================================================================================================
-- SEQUENCES (for human‑readable identifiers)
--================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.webhook_subscription_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.integration_credential_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.integration_mapping_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.event_subscription_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.schema_version_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.deprecation_notice_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.rate_limit_bucket_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.api_usage_analytics_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.api_error_log_seq START 1000;

--================================================================================================
-- TABLE: 1 - api_webhook_subscriptions
-- Description: Stores webhook subscriptions for external systems, including endpoint URL,
--              signing secret, subscribed events, and delivery configuration.
-- Business Case: Webhooks enable real‑time notifications to external systems about platform
--                events (user.created, post.published, etc.). This table manages the lifecycle
--                of each webhook endpoint, including activation, pausing for error backoff,
--                and permanent disabling. The design supports per‑endpoint retry policies,
--                rate limiting, and circuit breakers. By storing secrets for HMAC signing,
--                we ensure payload authenticity and prevent tampering. This is foundational for
--                building an event‑driven architecture and enabling third‑party integrations.
-- KPIs:
--   1. Webhook success rate – Percentage of successful deliveries.
--   2. Active webhook count – Number of active integrations.
--   3. Average latency – Time from event to delivery.
--   4. Retry rate – Percentage of deliveries requiring retries.
--   5. Failure reason distribution – Breakdown of failure causes.
-- Feature References: API01 (Webhook Management), API02 (Webhook Delivery), INT03 (Integrations)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_webhook_subscriptions (
    -- Primary key
    subscription_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    subscription_number VARCHAR(50) GENERATED ALWAYS AS (
        'WH-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.webhook_subscription_seq')::TEXT, 6, '0')
    ) STORED,

    -- Ownership (client or user)
    client_id UUID,                       -- OAuth2 client (for third‑party apps)
    user_id UUID,                          -- User who created the webhook

    -- Endpoint details
    url VARCHAR(500) NOT NULL,
    secret VARCHAR(255),                    -- HMAC signing secret (store hashed)
    description TEXT,

    -- Event subscription
    events TEXT[] NOT NULL,                 -- e.g., {'user.created', 'post.published'}
    event_filters JSONB,                     -- Optional filtering criteria per event

    -- Delivery configuration
    format VARCHAR(20) DEFAULT 'JSON' CHECK (format IN ('JSON', 'XML', 'FORM_URLENCODED')),
    max_retries INTEGER DEFAULT 3 CHECK (max_retries >= 0 AND max_retries <= 10),
    retry_delay_seconds INTEGER DEFAULT 60 CHECK (retry_delay_seconds >= 0),
    timeout_seconds INTEGER DEFAULT 10 CHECK (timeout_seconds >= 5 AND timeout_seconds <= 60),

    -- Rate limiting
    rate_limit_per_minute INTEGER,
    rate_limit_per_hour INTEGER,

    -- Circuit breaker
    consecutive_failures INTEGER DEFAULT 0 CHECK (consecutive_failures >= 0),
    circuit_breaker_trip_at TIMESTAMP WITH TIME ZONE,
    circuit_breaker_reset_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status socialcandor_schema.webhook_status NOT NULL DEFAULT 'ACTIVE',
    paused_reason TEXT,
    disabled_at TIMESTAMP WITH TIME ZONE,
    disabled_reason TEXT,

    -- Verification
    is_verified BOOLEAN DEFAULT FALSE,       -- Challenge-response verified
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Versioning
    version INTEGER DEFAULT 1,
    deprecated_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,                          -- User who created (if applicable)
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_webhook_subscriptions_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_webhook_subscriptions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_webhook_subscriptions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_webhook_subscriptions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_webhook_subscriptions_owner CHECK (
        (client_id IS NOT NULL) OR (user_id IS NOT NULL)
    ),
    CONSTRAINT chk_webhook_subscriptions_url CHECK (url ~* '^https?://[^\s/$.?#].[^\s]*$'),
    CONSTRAINT chk_webhook_subscriptions_events CHECK (array_length(events, 1) > 0)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_webhook_subscriptions IS 'Stores webhook subscriptions for external systems with delivery configuration.';
COMMENT ON COLUMN socialcandor_schema.api_webhook_subscriptions.secret IS 'HMAC signing secret (store hashed, never plaintext).';
COMMENT ON COLUMN socialcandor_schema.api_webhook_subscriptions.events IS 'Array of event types this webhook subscribes to.';
COMMENT ON COLUMN socialcandor_schema.api_webhook_subscriptions.event_filters IS 'JSON conditions for event filtering (e.g., only notify on high‑value transactions).';
COMMENT ON COLUMN socialcandor_schema.api_webhook_subscriptions.circuit_breaker_trip_at IS 'Timestamp when circuit breaker tripped due to consecutive failures.';

-- Indexes
CREATE INDEX idx_webhook_subscriptions_client ON socialcandor_schema.api_webhook_subscriptions(client_id) WHERE client_id IS NOT NULL;
CREATE INDEX idx_webhook_subscriptions_user ON socialcandor_schema.api_webhook_subscriptions(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_webhook_subscriptions_status ON socialcandor_schema.api_webhook_subscriptions(status, created_at) WHERE status = 'ACTIVE';
CREATE INDEX idx_webhook_subscriptions_events ON socialcandor_schema.api_webhook_subscriptions USING GIN (events);
CREATE INDEX idx_webhook_subscriptions_circuit ON socialcandor_schema.api_webhook_subscriptions(consecutive_failures, circuit_breaker_trip_at)
    WHERE consecutive_failures > 0 AND circuit_breaker_trip_at IS NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_api_webhook_subscriptions_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_webhook_subscriptions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_webhook_subscriptions ENABLE ROW LEVEL SECURITY;

CREATE POLICY webhook_subscriptions_user_policy ON socialcandor_schema.api_webhook_subscriptions
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY webhook_subscriptions_client_policy ON socialcandor_schema.api_webhook_subscriptions
    FOR ALL USING (client_id IN (
        SELECT client_id FROM socialcandor_schema.api_clients
        WHERE owner_user_id = current_setting('app.current_user_id')::UUID
    ));

CREATE POLICY webhook_subscriptions_admin_policy ON socialcandor_schema.api_webhook_subscriptions
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 2 - api_webhook_delivery_logs
-- Description: Logs every webhook delivery attempt, including request/response payloads,
--              status codes, and retry tracking. Enables monitoring, debugging, and SLA reporting.
-- Business Case: Reliable webhook delivery requires complete observability. This table captures
--                every attempt with enough detail to diagnose failures, measure latency, and
--                compute SLAs. Partitioning by month ensures query performance even with billions
--                of records. The data supports automated retry logic, circuit breaker decisions,
--                and alerts on persistent failures. Integration with analytics enables trend
--                analysis and capacity planning. This audit trail is also valuable for compliance
--                and dispute resolution.
-- KPIs:
--   1. Delivery success rate – Percentage of successful deliveries.
--   2. Average latency – Time from event to successful delivery.
--   3. Retry rate – Percentage of deliveries requiring retries.
--   4. Failure distribution – Breakdown by HTTP status, timeout, connection error.
--   5. Endpoint reliability – Per‑endpoint success rates and uptime.
-- Feature References: API02 (Webhook Delivery), API05 (Delivery Monitoring), OBS02 (Observability)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_webhook_delivery_logs (
    -- Primary key (using BIGSERIAL for partitioning)
    log_id BIGSERIAL,

    -- Human-readable identifier
    log_number VARCHAR(50) GENERATED ALWAYS AS (
        'WHD-' || TO_CHAR(attempted_at, 'YYYYMMDD') || '-' || LPAD(log_id::TEXT, 8, '0')
    ) STORED,

    -- References
    subscription_id UUID NOT NULL,
    event_id UUID,                                   -- Reference to source event (if any)

    -- Event details
    event_type VARCHAR(100) NOT NULL,
    event_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Payload
    payload JSONB NOT NULL,
    payload_size_bytes INTEGER CHECK (payload_size_bytes >= 0),
    payload_hash VARCHAR(64),                         -- SHA‑256 for integrity

    -- Delivery attempt
    attempt_number INTEGER NOT NULL DEFAULT 1 CHECK (attempt_number >= 1),
    attempted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Request details
    request_url VARCHAR(500) NOT NULL,
    request_headers JSONB,
    request_method VARCHAR(10) DEFAULT 'POST',

    -- Response details
    response_status INTEGER,
    response_headers JSONB,
    response_body TEXT,
    response_time_ms INTEGER CHECK (response_time_ms >= 0),

    -- Outcome
    success BOOLEAN NOT NULL,
    status socialcandor_schema.webhook_delivery_status NOT NULL,
    error_type VARCHAR(50) CHECK (error_type IN (
        'TIMEOUT', 'CONNECTION_ERROR', 'INVALID_RESPONSE', 'CLIENT_ERROR', 'SERVER_ERROR', 'OTHER'
    )),
    error_message TEXT,

    -- Retry info
    will_retry BOOLEAN DEFAULT FALSE,
    next_retry_at TIMESTAMP WITH TIME ZONE,

    -- Partition key
    delivery_date DATE GENERATED ALWAYS AS (attempted_at::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_webhook_delivery_logs PRIMARY KEY (log_id, delivery_date),
    CONSTRAINT fk_webhook_delivery_logs_subscription FOREIGN KEY (subscription_id)
        REFERENCES socialcandor_schema.api_webhook_subscriptions(subscription_id) ON DELETE CASCADE
) PARTITION BY RANGE (delivery_date);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_webhook_delivery_logs IS 'Logs every webhook delivery attempt with request/response details for monitoring and debugging.';
COMMENT ON COLUMN socialcandor_schema.api_webhook_delivery_logs.payload_hash IS 'SHA‑256 hash of payload for integrity verification.';
COMMENT ON COLUMN socialcandor_schema.api_webhook_delivery_logs.error_type IS 'Categorized error type for analysis and alerting.';
COMMENT ON COLUMN socialcandor_schema.api_webhook_delivery_logs.status IS 'Current status of this delivery attempt.';

-- Create monthly partitions for current and next 12 months
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'api_webhook_delivery_logs_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.api_webhook_delivery_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes on parent (will be inherited by partitions)
CREATE INDEX idx_webhook_delivery_logs_subscription ON socialcandor_schema.api_webhook_delivery_logs(subscription_id, attempted_at DESC);
CREATE INDEX idx_webhook_delivery_logs_event ON socialcandor_schema.api_webhook_delivery_logs(event_type, attempted_at DESC);
CREATE INDEX idx_webhook_delivery_logs_success ON socialcandor_schema.api_webhook_delivery_logs(success, attempted_at DESC) WHERE success = FALSE;
CREATE INDEX idx_webhook_delivery_logs_retry ON socialcandor_schema.api_webhook_delivery_logs(next_retry_at) WHERE will_retry = TRUE;

-- RLS Policies
ALTER TABLE socialcandor_schema.api_webhook_delivery_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY webhook_delivery_logs_subscriber_policy ON socialcandor_schema.api_webhook_delivery_logs
    FOR SELECT USING (
        subscription_id IN (
            SELECT subscription_id FROM socialcandor_schema.api_webhook_subscriptions
            WHERE user_id = current_setting('app.current_user_id')::UUID
               OR client_id IN (SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
        )
    );

CREATE POLICY webhook_delivery_logs_admin_policy ON socialcandor_schema.api_webhook_delivery_logs
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 3 - api_rate_limit_buckets
-- Description: Tracks rate limit usage per client, user, IP, or endpoint using a token bucket
--              algorithm. Enables enforcement of API usage limits and fair resource allocation.
-- Business Case: Rate limiting is essential for protecting API resources from abuse and ensuring
--                fair usage across clients. This table implements a token bucket per unique key
--                (e.g., client+endpoint, user+endpoint). Tokens are consumed per request and
--                refilled at a defined rate. The design supports dynamic limits based on
--                subscription tiers. Storing last refill timestamp allows precise calculation
--                of available tokens without relying on in‑memory state, making the system
--                scalable across multiple instances. This is critical for API monetization and
--                preventing denial‑of‑service.
-- KPIs:
--   1. Rate limit hits – Number of requests that hit rate limits.
--   2. Token refill rate – Effectiveness of bucket refills.
--   3. Throttled requests – Percentage of requests throttled.
--   4. Bucket utilization – Average tokens consumed per bucket.
--   5. Top throttled endpoints – Most frequently throttled API endpoints.
-- Feature References: API06 (Rate Limiting), API07 (API Security), MON03 (API Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_rate_limit_buckets (
    -- Primary key
    bucket_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    bucket_number VARCHAR(50) GENERATED ALWAYS AS (
        'RLB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.rate_limit_bucket_seq')::TEXT, 6, '0')
    ) STORED,

    -- Bucket identifier (composite key)
    bucket_key VARCHAR(500) NOT NULL UNIQUE,      -- e.g., "client:123:endpoint:/api/v1/posts"

    -- Scope (denormalized for querying)
    client_id UUID,
    user_id UUID,
    ip_address INET,
    endpoint VARCHAR(500),
    method VARCHAR(10) CHECK (method IN ('GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS', 'ALL')),

    -- Token bucket state
    tokens INTEGER NOT NULL DEFAULT 0 CHECK (tokens >= 0),      -- Current token count
    capacity INTEGER NOT NULL CHECK (capacity > 0),             -- Maximum tokens (bucket size)
    refill_rate INTEGER NOT NULL CHECK (refill_rate > 0),       -- Tokens added per refill_interval
    refill_interval_seconds INTEGER NOT NULL CHECK (refill_interval_seconds > 0), -- e.g., 60 for per minute

    -- Timing
    last_refill_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_rate_limit_buckets_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_rate_limit_buckets_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,

    CONSTRAINT chk_rate_limit_buckets_scope CHECK (
        (client_id IS NOT NULL) OR (user_id IS NOT NULL) OR (ip_address IS NOT NULL)
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_rate_limit_buckets IS 'Tracks rate limit usage per client, user, IP, or endpoint using a token bucket algorithm.';
COMMENT ON COLUMN socialcandor_schema.api_rate_limit_buckets.bucket_key IS 'Unique key identifying this bucket (e.g., client:123:endpoint:/v1/posts).';
COMMENT ON COLUMN socialcandor_schema.api_rate_limit_buckets.tokens IS 'Current token count (available requests).';
COMMENT ON COLUMN socialcandor_schema.api_rate_limit_buckets.capacity IS 'Maximum tokens (bucket size).';
COMMENT ON COLUMN socialcandor_schema.api_rate_limit_buckets.refill_rate IS 'Tokens added per refill_interval_seconds.';
COMMENT ON COLUMN socialcandor_schema.api_rate_limit_buckets.last_refill_at IS 'Last time tokens were refilled (for calculating current tokens).';

-- Indexes
CREATE INDEX idx_rate_limit_buckets_client ON socialcandor_schema.api_rate_limit_buckets(client_id) WHERE client_id IS NOT NULL;
CREATE INDEX idx_rate_limit_buckets_user ON socialcandor_schema.api_rate_limit_buckets(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_rate_limit_buckets_ip ON socialcandor_schema.api_rate_limit_buckets(ip_address) WHERE ip_address IS NOT NULL;
CREATE INDEX idx_rate_limit_buckets_endpoint ON socialcandor_schema.api_rate_limit_buckets(endpoint, method) WHERE endpoint IS NOT NULL;
CREATE INDEX idx_rate_limit_buckets_key ON socialcandor_schema.api_rate_limit_buckets(bucket_key);

-- Trigger for updated_at
CREATE TRIGGER trg_api_rate_limit_buckets_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_rate_limit_buckets
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_rate_limit_buckets ENABLE ROW LEVEL SECURITY;

CREATE POLICY rate_limit_buckets_admin_policy ON socialcandor_schema.api_rate_limit_buckets
    FOR ALL USING (socialcandor_schema.is_admin());

-- Note: Rate limit buckets are typically managed by system, not exposed to users directly.

--================================================================================================
-- TABLE: 4 - api_integration_credentials
-- Description: Securely stores credentials for third‑party integrations (OAuth tokens, API keys,
--              basic auth). Encrypts sensitive data and manages token refresh.
-- Business Case: Integrations with external services (CRM, marketing, analytics) require storing
--                credentials securely. This table holds encrypted access tokens, refresh tokens,
--                and metadata like expiry and scopes. The design supports multiple credential types
--                and automatic token refresh for OAuth2. By encrypting at rest and never logging
--                plaintext, we meet compliance requirements (SOC2, GDPR). Integration with a
--                background job system enables proactive token refresh before expiry. This is the
--                foundation for all third‑party integrations.
-- KPIs:
--   1. Integration count – Number of active integrations.
--   2. Token refresh success rate – Percentage of successful token refreshes.
--   3. Credential expiry rate – Tokens expiring within next 30 days.
--   4. Integration usage – Most used integration types.
--   5. Security compliance – Audit of encrypted storage.
-- Feature References: INT01 (Integration Credentials), INT04 (OAuth2 Management), SEC01 (Encryption)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_integration_credentials (
    -- Primary key
    credential_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    credential_number VARCHAR(50) GENERATED ALWAYS AS (
        'IC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.integration_credential_seq')::TEXT, 6, '0')
    ) STORED,

    -- Ownership
    client_id UUID,                           -- OAuth2 client (if integration is app‑level)
    user_id UUID,                              -- User who owns the integration
    organization_id UUID,                       -- Organization (for enterprise)

    -- Integration details
    integration_name VARCHAR(255) NOT NULL,
    integration_type VARCHAR(50) CHECK (integration_type IN ('CRM', 'MARKETING', 'PAYMENT', 'ANALYTICS', 'OTHER')),
    credential_type socialcandor_schema.integration_credential_type NOT NULL,

    -- Encrypted credentials
    encrypted_access_token TEXT,
    encrypted_refresh_token TEXT,
    access_token_expires_at TIMESTAMP WITH TIME ZONE,
    refresh_token_expires_at TIMESTAMP WITH TIME ZONE,
    scopes TEXT[],

    -- OAuth2 specific
    client_id_oauth VARCHAR(255),               -- OAuth client ID (if different from platform client)
    token_url VARCHAR(500),

    -- API key / basic auth
    api_key_label VARCHAR(100),
    encrypted_api_key TEXT,
    encrypted_username TEXT,
    encrypted_password TEXT,

    -- Metadata
    environment VARCHAR(20) CHECK (environment IN ('PRODUCTION', 'SANDBOX', 'DEVELOPMENT')),
    base_url VARCHAR(500),
    api_version VARCHAR(50),
    config JSONB DEFAULT '{}',

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    last_used_at TIMESTAMP WITH TIME ZONE,
    last_error TEXT,
    consecutive_errors INTEGER DEFAULT 0,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_integration_credentials_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_integration_credentials_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_integration_credentials_org FOREIGN KEY (organization_id)
        REFERENCES socialcandor_schema.organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_integration_credentials_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_integration_credentials_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_integration_credentials_owner CHECK (
        (client_id IS NOT NULL)::INT +
        (user_id IS NOT NULL)::INT +
        (organization_id IS NOT NULL)::INT = 1
    ),
    CONSTRAINT chk_integration_credentials_type CHECK (
        (credential_type = 'OAUTH2' AND encrypted_access_token IS NOT NULL) OR
        (credential_type = 'API_KEY' AND encrypted_api_key IS NOT NULL) OR
        (credential_type = 'BASIC_AUTH' AND encrypted_username IS NOT NULL AND encrypted_password IS NOT NULL) OR
        (credential_type = 'JWT' AND encrypted_access_token IS NOT NULL) OR
        (credential_type = 'CUSTOM')
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_integration_credentials IS 'Securely stores encrypted credentials for third‑party integrations.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.encrypted_access_token IS 'Encrypted OAuth2 access token or JWT.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.encrypted_refresh_token IS 'Encrypted OAuth2 refresh token.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.encrypted_api_key IS 'Encrypted API key.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.encrypted_username IS 'Encrypted username for basic auth.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.encrypted_password IS 'Encrypted password for basic auth.';
COMMENT ON COLUMN socialcandor_schema.api_integration_credentials.config IS 'Integration‑specific configuration (e.g., webhook URLs, custom settings).';

-- Indexes
CREATE INDEX idx_integration_credentials_client ON socialcandor_schema.api_integration_credentials(client_id) WHERE client_id IS NOT NULL;
CREATE INDEX idx_integration_credentials_user ON socialcandor_schema.api_integration_credentials(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_integration_credentials_org ON socialcandor_schema.api_integration_credentials(organization_id) WHERE organization_id IS NOT NULL;
CREATE INDEX idx_integration_credentials_type ON socialcandor_schema.api_integration_credentials(integration_type, is_active);
CREATE INDEX idx_integration_credentials_expiry ON socialcandor_schema.api_integration_credentials(access_token_expires_at)
    WHERE access_token_expires_at IS NOT NULL AND is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_api_integration_credentials_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_integration_credentials
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_integration_credentials ENABLE ROW LEVEL SECURITY;

CREATE POLICY integration_credentials_user_policy ON socialcandor_schema.api_integration_credentials
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY integration_credentials_client_policy ON socialcandor_schema.api_integration_credentials
    FOR ALL USING (client_id IN (
        SELECT client_id FROM socialcandor_schema.api_clients
        WHERE owner_user_id = current_setting('app.current_user_id')::UUID
    ));

CREATE POLICY integration_credentials_org_policy ON socialcandor_schema.api_integration_credentials
    FOR ALL USING (organization_id IN (
        SELECT organization_id FROM socialcandor_schema.org_members
        WHERE user_id = current_setting('app.current_user_id')::UUID
    ));

CREATE POLICY integration_credentials_admin_policy ON socialcandor_schema.api_integration_credentials
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 5 - api_integration_mappings
-- Description: Defines field mappings between platform data models and external system fields,
--              including transformations and direction (inbound/outbound).
-- Business Case: When integrating with external systems, data fields rarely match one‑to‑one.
--                This table stores mapping rules that define how platform fields map to external
--                fields, including transformations (e.g., concatenation, date formatting). The
--                direction indicates whether the mapping applies to data coming into the platform
--                (inbound) or going out (outbound). Mappings can be versioned and toggled active.
--                This design supports complex integrations without code changes, enabling rapid
--                onboarding of new partners. Transformations can be expressed as simple expressions
--                (e.g., JSON path, string templates) or reference custom scripts.
-- KPIs:
--   1. Mapping count – Number of active mappings per integration.
--   2. Mapping complexity – Distribution of transformation types.
--   3. Mapping error rate – Percentage of mapping failures.
--   4. Integration coverage – Percentage of fields mapped.
--   5. Mapping reuse – Mappings reused across multiple integrations.
-- Feature References: INT02 (Field Mappings), INT05 (Data Transformation), ETL01 (ETL)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_integration_mappings (
    -- Primary key
    mapping_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    mapping_number VARCHAR(50) GENERATED ALWAYS AS (
        'MAP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.integration_mapping_seq')::TEXT, 6, '0')
    ) STORED,

    -- Integration reference
    credential_id UUID NOT NULL,                     -- Links to integration credentials

    -- Mapping details
    direction socialcandor_schema.mapping_direction NOT NULL,
    source_field VARCHAR(500) NOT NULL,                -- Platform field (JSON path or column name)
    target_field VARCHAR(500) NOT NULL,                 -- External field (JSON path or field name)

    -- Transformation
    transformation_type VARCHAR(50) CHECK (transformation_type IN (
        'DIRECT', 'CONSTANT', 'CONCAT', 'DATE_FORMAT', 'NUMBER_FORMAT', 'LOOKUP', 'EXPRESSION', 'CUSTOM'
    )),
    transformation_expression TEXT,                      -- e.g., "CONCAT(first_name, ' ', last_name)"
    transformation_params JSONB,                         -- Parameters for transformation

    -- Data type handling
    source_data_type VARCHAR(50),
    target_data_type VARCHAR(50),
    default_value TEXT,

    -- Validation
    validation_rules JSONB,                              -- e.g., regex, min/max

    -- Versioning
    version INTEGER DEFAULT 1,
    is_active BOOLEAN DEFAULT TRUE,
    superseded_by UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_integration_mappings_credential FOREIGN KEY (credential_id)
        REFERENCES socialcandor_schema.api_integration_credentials(credential_id) ON DELETE CASCADE,
    CONSTRAINT fk_integration_mappings_superseded_by FOREIGN KEY (superseded_by)
        REFERENCES socialcandor_schema.api_integration_mappings(mapping_id) ON DELETE SET NULL,
    CONSTRAINT fk_integration_mappings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_integration_mappings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_integration_mappings UNIQUE (credential_id, direction, source_field, target_field, version)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_integration_mappings IS 'Defines field mappings between platform and external systems with transformations.';
COMMENT ON COLUMN socialcandor_schema.api_integration_mappings.direction IS 'Direction of mapping (inbound = external → platform, outbound = platform → external).';
COMMENT ON COLUMN socialcandor_schema.api_integration_mappings.transformation_type IS 'Type of transformation applied to the field.';
COMMENT ON COLUMN socialcandor_schema.api_integration_mappings.transformation_expression IS 'Expression defining the transformation (e.g., SQL‑like expression).';
COMMENT ON COLUMN socialcandor_schema.api_integration_mappings.validation_rules IS 'JSON rules for validating mapped values.';

-- Indexes
CREATE INDEX idx_integration_mappings_credential ON socialcandor_schema.api_integration_mappings(credential_id, is_active) WHERE is_active = TRUE;
CREATE INDEX idx_integration_mappings_direction ON socialcandor_schema.api_integration_mappings(direction, source_field, target_field);

-- Trigger for updated_at
CREATE TRIGGER trg_api_integration_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_integration_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_integration_mappings ENABLE ROW LEVEL SECURITY;

CREATE POLICY integration_mappings_owner_policy ON socialcandor_schema.api_integration_mappings
    FOR ALL USING (
        credential_id IN (
            SELECT credential_id FROM socialcandor_schema.api_integration_credentials
            WHERE user_id = current_setting('app.current_user_id')::UUID
               OR client_id IN (SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
               OR organization_id IN (SELECT organization_id FROM socialcandor_schema.org_members WHERE user_id = current_setting('app.current_user_id')::UUID)
        )
    );

CREATE POLICY integration_mappings_admin_policy ON socialcandor_schema.api_integration_mappings
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 6 - api_event_subscriptions
-- Description: Manages subscriptions to platform events for users, clients, or organizations.
--              Supports filtering and multi‑channel delivery (email, push, webhook).
-- Business Case: Users and applications need to be notified about events they care about (new
--                messages, content updates, system alerts). This table stores event subscriptions
--                with optional filters (e.g., only events from specific users). The design supports
--                multiple delivery channels per subscription, enabling users to receive emails,
--                push notifications, or webhooks for the same event type. This decouples event
--                production from consumption and enables powerful notification workflows.
-- KPIs:
--   1. Subscription count – Number of active subscriptions.
--   2. Event volume – Number of events generated per subscription.
--   3. Channel distribution – Preferred notification channels.
--   4. Filter usage – Percentage of subscriptions using filters.
--   5. Delivery success rate – Per‑channel success rates.
-- Feature References: API03 (Event Subscriptions), API04 (Notification Channels), NOTIFY01 (Notifications)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_event_subscriptions (
    -- Primary key
    subscription_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    subscription_number VARCHAR(50) GENERATED ALWAYS AS (
        'EVSUB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.event_subscription_seq')::TEXT, 6, '0')
    ) STORED,

    -- Subscriber
    subscriber_type socialcandor_schema.subscriber_type NOT NULL,
    subscriber_id UUID NOT NULL,                       -- user_id, client_id, or organization_id

    -- Subscription details
    event_name VARCHAR(255) NOT NULL,                    -- e.g., 'message.received', 'post.created'
    filter_criteria JSONB,                                -- Conditions for event matching

    -- Delivery configuration
    channels socialcandor_schema.notification_channel[] NOT NULL DEFAULT '{EMAIL}',
    webhook_url VARCHAR(500),                             -- If channel includes WEBHOOK
    email_template_id UUID,                                -- Optional template for email
    push_template_id UUID,                                 -- Optional template for push

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    paused_until TIMESTAMP WITH TIME ZONE,

    -- Metadata
    description TEXT,
    metadata JSONB DEFAULT '{}',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_event_subscriptions_webhook FOREIGN KEY (webhook_url) REFERENCES socialcandor_schema.api_webhook_subscriptions(url) ON DELETE SET NULL,
    -- (Note: webhook_url should reference subscription, but simplified; could add subscription_id later)
    CONSTRAINT fk_event_subscriptions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_event_subscriptions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_event_subscriptions_webhook CHECK (
        NOT ('WEBHOOK' = ANY(channels)) OR webhook_url IS NOT NULL
    ),
    CONSTRAINT chk_event_subscriptions_filters CHECK (
        filter_criteria IS NULL OR jsonb_typeof(filter_criteria) = 'object'
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_event_subscriptions IS 'Manages subscriptions to platform events with filtering and multi‑channel delivery.';
COMMENT ON COLUMN socialcandor_schema.api_event_subscriptions.subscriber_type IS 'Type of subscriber (user, client, organization).';
COMMENT ON COLUMN socialcandor_schema.api_event_subscriptions.event_name IS 'Name of the event to subscribe to.';
COMMENT ON COLUMN socialcandor_schema.api_event_subscriptions.filter_criteria IS 'JSON conditions for event matching (e.g., { "user_id": 123 }).';
COMMENT ON COLUMN socialcandor_schema.api_event_subscriptions.channels IS 'Array of delivery channels for this subscription.';

-- Indexes
CREATE INDEX idx_event_subscriptions_subscriber ON socialcandor_schema.api_event_subscriptions(subscriber_type, subscriber_id, is_active);
CREATE INDEX idx_event_subscriptions_event ON socialcandor_schema.api_event_subscriptions(event_name, is_active);
CREATE INDEX idx_event_subscriptions_webhook ON socialcandor_schema.api_event_subscriptions(webhook_url) WHERE webhook_url IS NOT NULL;
CREATE INDEX idx_event_subscriptions_active ON socialcandor_schema.api_event_subscriptions(is_active, paused_until) WHERE is_active = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_api_event_subscriptions_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_event_subscriptions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_event_subscriptions ENABLE ROW LEVEL SECURITY;

CREATE POLICY event_subscriptions_user_policy ON socialcandor_schema.api_event_subscriptions
    FOR ALL USING (subscriber_type = 'USER' AND subscriber_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY event_subscriptions_client_policy ON socialcandor_schema.api_event_subscriptions
    FOR ALL USING (
        subscriber_type = 'CLIENT' AND
        subscriber_id IN (SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
    );

CREATE POLICY event_subscriptions_org_policy ON socialcandor_schema.api_event_subscriptions
    FOR ALL USING (
        subscriber_type = 'ORGANIZATION' AND
        subscriber_id IN (SELECT organization_id FROM socialcandor_schema.org_members WHERE user_id = current_setting('app.current_user_id')::UUID)
    );

CREATE POLICY event_subscriptions_admin_policy ON socialcandor_schema.api_event_subscriptions
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 7 - api_schema_versions
-- Description: Tracks versions of API schemas (OpenAPI/Swagger) with release dates, deprecation
--              status, and changelogs. Enables API lifecycle management.
-- Business Case: API evolution requires careful version management to avoid breaking existing
--                clients. This table stores metadata about each API version, including the
--                OpenAPI specification (or a URL to it), release date, deprecation date, and
--                sunset date. It also tracks breaking changes and migration guides. This serves
--                as the source of truth for API documentation and client compatibility checks.
--                Integration with developer portal enables automatic documentation updates and
--                deprecation notifications. This is essential for maintaining a healthy API
--                ecosystem and reducing support burden.
-- KPIs:
--   1. Version count – Number of active API versions.
--   2. Version adoption – Usage distribution across versions.
--   3. Deprecation compliance – Percentage of clients migrated before sunset.
--   4. Breaking change frequency – Number of breaking changes per release.
--   5. Documentation coverage – Percentage of endpoints documented.
-- Feature References: API08 (Schema Versioning), API09 (Deprecation Management), DOC02 (API Docs)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_schema_versions (
    -- Primary key
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    version_number VARCHAR(50) GENERATED ALWAYS AS (
        'APIV-' || TO_CHAR(release_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.schema_version_seq')::TEXT, 6, '0')
    ) STORED,

    -- API identification
    api_name VARCHAR(100) NOT NULL,                    -- e.g., 'core', 'payments', 'messaging'
    version VARCHAR(20) NOT NULL,                       -- e.g., 'v1', 'v2', '2025-01-15'
    release_date DATE NOT NULL,
    description TEXT,

    -- Schema
    openapi_spec JSONB,                                  -- Full OpenAPI specification
    spec_url VARCHAR(500),                               -- URL to hosted spec
    spec_format VARCHAR(20) CHECK (spec_format IN ('JSON', 'YAML')),

    -- Lifecycle
    is_deprecated BOOLEAN DEFAULT FALSE,
    deprecation_date DATE,
    sunset_date DATE,
    deprecation_message TEXT,

    -- Changes
    is_breaking_change BOOLEAN DEFAULT FALSE,
    changelog TEXT,
    migration_guide TEXT,
    migration_guide_url VARCHAR(500),

    -- Compatibility
    previous_version_id UUID,
    next_version_id UUID,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_api_schema_versions_previous FOREIGN KEY (previous_version_id)
        REFERENCES socialcandor_schema.api_schema_versions(version_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_schema_versions_next FOREIGN KEY (next_version_id)
        REFERENCES socialcandor_schema.api_schema_versions(version_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_schema_versions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_api_schema_versions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_api_schema_versions UNIQUE (api_name, version),
    CONSTRAINT chk_api_schema_versions_dates CHECK (
        (deprecation_date IS NULL OR deprecation_date >= release_date) AND
        (sunset_date IS NULL OR sunset_date >= deprecation_date)
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_schema_versions IS 'Tracks versions of API schemas with lifecycle and deprecation information.';
COMMENT ON COLUMN socialcandor_schema.api_schema_versions.openapi_spec IS 'Full OpenAPI specification (JSON).';
COMMENT ON COLUMN socialcandor_schema.api_schema_versions.is_breaking_change IS 'Whether this version contains breaking changes.';
COMMENT ON COLUMN socialcandor_schema.api_schema_versions.deprecation_message IS 'Message to display to developers using deprecated versions.';

-- Indexes
CREATE INDEX idx_api_schema_versions_api ON socialcandor_schema.api_schema_versions(api_name, version);
CREATE INDEX idx_api_schema_versions_active ON socialcandor_schema.api_schema_versions(is_deprecated, sunset_date) WHERE is_deprecated = TRUE;

-- Trigger for updated_at
CREATE TRIGGER trg_api_schema_versions_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_schema_versions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_schema_versions ENABLE ROW LEVEL SECURITY;

CREATE POLICY api_schema_versions_public_policy ON socialcandor_schema.api_schema_versions
    FOR SELECT USING (TRUE);           -- Schema versions are public

CREATE POLICY api_schema_versions_admin_policy ON socialcandor_schema.api_schema_versions
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 8 - api_deprecation_notices
-- Description: Records deprecation notices sent to API consumers, tracking acknowledgment and
--              ensuring compliance with deprecation policies.
-- Business Case: When deprecating an API version, we must notify all affected clients and track
--                their acknowledgment for compliance (especially in regulated industries). This
--                table stores each notice sent, including the version being deprecated, the
--                recipient (client or user), and whether they have acknowledged. The design
--                supports multiple notices per client (e.g., initial notice, reminder, final
--                warning). This data is critical for proving that clients were given adequate
--                notice before a breaking change or sunset. It also helps identify non‑responsive
--                clients for follow‑up.
-- KPIs:
--   1. Notice delivery rate – Percentage of notices successfully delivered.
--   2. Acknowledgment rate – Percentage of recipients acknowledging within deadline.
--   3. Time to acknowledge – Average days between notice and acknowledgment.
--   4. Escalation rate – Notices requiring follow‑up reminders.
--   5. Sunset compliance – Percentage of clients migrated before sunset.
-- Feature References: API09 (Deprecation Management), API10 (Client Communication), COMP01 (Compliance)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_deprecation_notices (
    -- Primary key
    notice_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    notice_number VARCHAR(50) GENERATED ALWAYS AS (
        'DEPN-' || TO_CHAR(sent_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.deprecation_notice_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    version_id UUID NOT NULL,                         -- Deprecated version
    client_id UUID,                                    -- Client being notified
    user_id UUID,                                      -- User being notified (if individual)

    -- Notice details
    notice_type VARCHAR(30) CHECK (notice_type IN ('INITIAL', 'REMINDER', 'FINAL', 'ESCALATION')),
    sent_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    channel socialcandor_schema.notification_channel NOT NULL,

    -- Content
    subject VARCHAR(255),
    message TEXT,
    metadata JSONB DEFAULT '{}',

    -- Acknowledgment
    acknowledged BOOLEAN DEFAULT FALSE,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    acknowledgment_token VARCHAR(255),                  -- For verifying acknowledgment

    -- Compliance
    requires_acknowledgment BOOLEAN DEFAULT TRUE,
    acknowledgment_deadline DATE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID,

    -- Constraints
    CONSTRAINT fk_deprecation_notices_version FOREIGN KEY (version_id)
        REFERENCES socialcandor_schema.api_schema_versions(version_id) ON DELETE CASCADE,
    CONSTRAINT fk_deprecation_notices_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE CASCADE,
    CONSTRAINT fk_deprecation_notices_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_deprecation_notices_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_deprecation_notices_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_deprecation_notices_recipient CHECK (
        (client_id IS NOT NULL) OR (user_id IS NOT NULL)
    ),
    CONSTRAINT chk_deprecation_notices_deadline CHECK (
        acknowledgment_deadline IS NULL OR acknowledgment_deadline >= sent_at::DATE
    )
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_deprecation_notices IS 'Records deprecation notices sent to API consumers and tracks acknowledgment.';
COMMENT ON COLUMN socialcandor_schema.api_deprecation_notices.notice_type IS 'Type of notice (initial, reminder, final, escalation).';
COMMENT ON COLUMN socialcandor_schema.api_deprecation_notices.acknowledgment_token IS 'Unique token for verifying acknowledgment (prevents fraud).';
COMMENT ON COLUMN socialcandor_schema.api_deprecation_notices.acknowledgment_deadline IS 'Date by which acknowledgment is required.';

-- Indexes
CREATE INDEX idx_deprecation_notices_version ON socialcandor_schema.api_deprecation_notices(version_id, sent_at DESC);
CREATE INDEX idx_deprecation_notices_client ON socialcandor_schema.api_deprecation_notices(client_id) WHERE client_id IS NOT NULL;
CREATE INDEX idx_deprecation_notices_user ON socialcandor_schema.api_deprecation_notices(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_deprecation_notices_ack ON socialcandor_schema.api_deprecation_notices(acknowledged, acknowledgment_deadline) WHERE acknowledged = FALSE;

-- Trigger for updated_at
CREATE TRIGGER trg_api_deprecation_notices_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_deprecation_notices
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_deprecation_notices ENABLE ROW LEVEL SECURITY;

CREATE POLICY deprecation_notices_self_policy ON socialcandor_schema.api_deprecation_notices
    FOR SELECT USING (
        (client_id IS NOT NULL AND client_id IN (
            SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID
        )) OR
        user_id = current_setting('app.current_user_id')::UUID
    );

CREATE POLICY deprecation_notices_admin_policy ON socialcandor_schema.api_deprecation_notices
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 9 - api_usage_analytics
-- Description: Aggregated API usage data for analytics, billing, and capacity planning. Stores
--              counts, latency, and errors per endpoint, client, and time period.
-- Business Case: Understanding API usage patterns is essential for product decisions, capacity
--                planning, and billing. This table stores pre‑aggregated metrics (daily/hourly)
--                per endpoint, client, and user. The data supports dashboards, alerts on anomalies,
--                and chargeback/showback for multi‑tenant billing. By aggregating in this table,
--                we avoid expensive queries on raw logs. The design supports multiple time grains
--                (hour, day, month) and dimensions (client, user, endpoint). This is the foundation
--                for API analytics and business intelligence.
-- KPIs:
--   1. API call volume – Total requests per period.
--   2. Average latency – Mean response time.
--   3. Error rate – Percentage of failed requests.
--   4. Top endpoints – Most called API endpoints.
--   5. Client usage distribution – Usage by client tier.
-- Feature References: API11 (Usage Analytics), BIL01 (API Billing), ANL01 (Analytics)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_usage_analytics (
    -- Primary key
    analytics_id BIGSERIAL PRIMARY KEY,

    -- Human-readable identifier
    analytics_number VARCHAR(50) GENERATED ALWAYS AS (
        'APIA-' || TO_CHAR(analytics_date, 'YYYYMMDD') || '-' || LPAD(analytics_id::TEXT, 8, '0')
    ) STORED,

    -- Time dimension
    analytics_date DATE NOT NULL,
    analytics_hour INTEGER CHECK (analytics_hour >= 0 AND analytics_hour <= 23),
    time_grain VARCHAR(10) NOT NULL CHECK (time_grain IN ('HOUR', 'DAY', 'MONTH')),

    -- Dimensions
    client_id UUID,
    user_id UUID,
    endpoint VARCHAR(500),
    method VARCHAR(10),
    response_status_group VARCHAR(20),                     -- e.g., '2xx', '4xx', '5xx'

    -- Metrics
    request_count INTEGER NOT NULL DEFAULT 0 CHECK (request_count >= 0),
    success_count INTEGER DEFAULT 0 CHECK (success_count >= 0),
    error_count INTEGER DEFAULT 0 CHECK (error_count >= 0),
    total_response_time_ms BIGINT DEFAULT 0 CHECK (total_response_time_ms >= 0), -- Sum for avg calculation
    avg_response_time_ms NUMERIC(10,2) GENERATED ALWAYS AS (
        CASE WHEN request_count > 0 THEN total_response_time_ms::NUMERIC / request_count ELSE 0 END
    ) STORED,
    max_response_time_ms INTEGER DEFAULT 0 CHECK (max_response_time_ms >= 0),
    min_response_time_ms INTEGER DEFAULT 0 CHECK (min_response_time_ms >= 0),

    -- Data transfer
    total_request_bytes BIGINT DEFAULT 0 CHECK (total_request_bytes >= 0),
    total_response_bytes BIGINT DEFAULT 0 CHECK (total_response_bytes >= 0),

    -- Unique users (approximate)
    unique_users INTEGER DEFAULT 0 CHECK (unique_users >= 0),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_api_usage_analytics_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_usage_analytics_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_api_usage_analytics UNIQUE (analytics_date, analytics_hour, time_grain, client_id, user_id, endpoint, method, response_status_group)
);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_usage_analytics IS 'Aggregated API usage data for analytics, billing, and capacity planning.';
COMMENT ON COLUMN socialcandor_schema.api_usage_analytics.time_grain IS 'Aggregation level (hour, day, month).';
COMMENT ON COLUMN socialcandor_schema.api_usage_analytics.response_status_group IS 'Grouped HTTP status (2xx, 4xx, 5xx).';
COMMENT ON COLUMN socialcandor_schema.api_usage_analytics.total_response_time_ms IS 'Sum of response times for average calculation.';
COMMENT ON COLUMN socialcandor_schema.api_usage_analytics.unique_users IS 'Approximate count of unique users in this period.';

-- Indexes
CREATE INDEX idx_api_usage_analytics_date ON socialcandor_schema.api_usage_analytics(analytics_date DESC, time_grain);
CREATE INDEX idx_api_usage_analytics_client ON socialcandor_schema.api_usage_analytics(client_id, analytics_date DESC) WHERE client_id IS NOT NULL;
CREATE INDEX idx_api_usage_analytics_user ON socialcandor_schema.api_usage_analytics(user_id, analytics_date DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_api_usage_analytics_endpoint ON socialcandor_schema.api_usage_analytics(endpoint, analytics_date DESC) WHERE endpoint IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_api_usage_analytics_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_usage_analytics
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS Policies
ALTER TABLE socialcandor_schema.api_usage_analytics ENABLE ROW LEVEL SECURITY;

CREATE POLICY api_usage_analytics_self_policy ON socialcandor_schema.api_usage_analytics
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY api_usage_analytics_client_owner_policy ON socialcandor_schema.api_usage_analytics
    FOR SELECT USING (
        client_id IN (SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
    );

CREATE POLICY api_usage_analytics_admin_policy ON socialcandor_schema.api_usage_analytics
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: 10 - api_error_logs
-- Description: Detailed logs of API errors, including request/response, stack traces, and context
--              for debugging and alerting. Supports error analysis and SLA monitoring.
-- Business Case: When APIs fail, developers need rich context to diagnose and fix issues. This
--                table captures every error with full request/response details, stack traces,
--                headers, and metadata. The design supports error categorization by type and
--                severity, enabling alerting and prioritization. Partitioning by month keeps the
--                table manageable. Integration with incident management can automatically create
--                tickets for critical errors. This data is also valuable for trend analysis and
--                identifying problematic endpoints or clients.
-- KPIs:
--   1. Error rate – Percentage of API requests resulting in errors.
--   2. Error distribution – Breakdown by status code, error type.
--   3. Mean time to recovery – Time from error to resolution.
--   4. Top error endpoints – Most error‑prone endpoints.
--   5. Error recurrence – Frequency of repeated errors.
-- Feature References: OBS01 (Error Monitoring), OBS02 (Alerting), API12 (Error Handling)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_error_logs (
    -- Primary key
    error_id BIGSERIAL,

    -- Human-readable identifier
    error_number VARCHAR(50) GENERATED ALWAYS AS (
        'APIERR-' || TO_CHAR(occurred_at, 'YYYYMMDD') || '-' || LPAD(error_id::TEXT, 8, '0')
    ) STORED,

    -- Request identification
    request_id UUID,                                      -- For tracing across services
    client_id UUID,
    user_id UUID,
    api_key_id UUID,

    -- Request details
    endpoint VARCHAR(500) NOT NULL,
    method VARCHAR(10) NOT NULL,
    request_headers JSONB,
    request_body TEXT,
    request_params JSONB,
    ip_address INET,
    user_agent TEXT,

    -- Error details
    status_code INTEGER NOT NULL,
    error_type VARCHAR(100),                               -- e.g., 'ValidationError', 'DatabaseError'
    error_severity socialcandor_schema.error_severity NOT NULL DEFAULT 'ERROR',
    error_message TEXT NOT NULL,
    stack_trace TEXT,
    internal_error_code VARCHAR(100),

    -- Response details (what was sent to client)
    response_headers JSONB,
    response_body TEXT,
    response_size_bytes INTEGER CHECK (response_size_bytes >= 0),

    -- Context
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    duration_ms INTEGER CHECK (duration_ms >= 0),

    -- Resolution
    resolved BOOLEAN DEFAULT FALSE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolution_notes TEXT,

    -- Partition key
    error_date DATE GENERATED ALWAYS AS (occurred_at::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_api_error_logs PRIMARY KEY (error_id, error_date),
    CONSTRAINT fk_api_error_logs_client FOREIGN KEY (client_id)
        REFERENCES socialcandor_schema.api_clients(client_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_error_logs_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_error_logs_api_key FOREIGN KEY (api_key_id)
        REFERENCES socialcandor_schema.api_keys(api_key_id) ON DELETE SET NULL
) PARTITION BY RANGE (error_date);

-- Comments
COMMENT ON TABLE socialcandor_schema.api_error_logs IS 'Detailed logs of API errors for debugging and alerting.';
COMMENT ON COLUMN socialcandor_schema.api_error_logs.request_id IS 'Unique request identifier for tracing across services.';
COMMENT ON COLUMN socialcandor_schema.api_error_logs.error_type IS 'Categorized error type for analysis.';
COMMENT ON COLUMN socialcandor_schema.api_error_logs.error_severity IS 'Severity level for prioritization.';
COMMENT ON COLUMN socialcandor_schema.api_error_logs.internal_error_code IS 'Internal error code for support reference.';
COMMENT ON COLUMN socialcandor_schema.api_error_logs.resolved IS 'Whether the error has been resolved/acknowledged.';

-- Create monthly partitions
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'api_error_logs_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.api_error_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes
CREATE INDEX idx_api_error_logs_request ON socialcandor_schema.api_error_logs(request_id) WHERE request_id IS NOT NULL;
CREATE INDEX idx_api_error_logs_client ON socialcandor_schema.api_error_logs(client_id, occurred_at DESC) WHERE client_id IS NOT NULL;
CREATE INDEX idx_api_error_logs_user ON socialcandor_schema.api_error_logs(user_id, occurred_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_api_error_logs_status ON socialcandor_schema.api_error_logs(status_code, occurred_at DESC);
CREATE INDEX idx_api_error_logs_severity ON socialcandor_schema.api_error_logs(error_severity, occurred_at DESC) WHERE error_severity IN ('ERROR', 'CRITICAL');
CREATE INDEX idx_api_error_logs_resolved ON socialcandor_schema.api_error_logs(resolved, error_date) WHERE resolved = FALSE;

-- RLS Policies
ALTER TABLE socialcandor_schema.api_error_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY api_error_logs_self_policy ON socialcandor_schema.api_error_logs
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);

CREATE POLICY api_error_logs_client_owner_policy ON socialcandor_schema.api_error_logs
    FOR SELECT USING (
        client_id IN (SELECT client_id FROM socialcandor_schema.api_clients WHERE owner_user_id = current_setting('app.current_user_id')::UUID)
    );

CREATE POLICY api_error_logs_admin_policy ON socialcandor_schema.api_error_logs
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- FUNCTION: refresh_api_usage_analytics
-- Description: Stored procedure to aggregate raw API logs into api_usage_analytics.
--              Should be scheduled (e.g., hourly) to update the analytics table.
-- Business Case: Automates the ETL process from raw logs to aggregated analytics.
--================================================================================================
CREATE OR REPLACE FUNCTION socialcandor_schema.refresh_api_usage_analytics(
    p_date DATE DEFAULT CURRENT_DATE,
    p_hour INTEGER DEFAULT NULL
)
RETURNS INTEGER AS $$
DECLARE
    v_rows_inserted INTEGER := 0;
    v_start_time TIMESTAMP WITH TIME ZONE;
    v_end_time TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Set time range
    IF p_hour IS NOT NULL THEN
        v_start_time := (p_date + (p_hour || ' hours')::INTERVAL)::TIMESTAMP WITH TIME ZONE;
        v_end_time := v_start_time + INTERVAL '1 hour';
    ELSE
        v_start_time := p_date::TIMESTAMP WITH TIME ZONE;
        v_end_time := v_start_time + INTERVAL '1 day';
    END IF;

    -- Insert hourly aggregates from api_error_logs and other sources
    -- This is a simplified example; real implementation would join with api_webhook_delivery_logs etc.
    WITH hourly_aggregates AS (
        SELECT
            p_date AS analytics_date,
            p_hour AS analytics_hour,
            'HOUR'::VARCHAR AS time_grain,
            client_id,
            user_id,
            endpoint,
            method,
            CASE
                WHEN status_code BETWEEN 200 AND 299 THEN '2xx'
                WHEN status_code BETWEEN 400 AND 499 THEN '4xx'
                WHEN status_code BETWEEN 500 AND 599 THEN '5xx'
                ELSE 'other'
            END AS response_status_group,
            COUNT(*) AS request_count,
            COUNT(*) FILTER (WHERE status_code BETWEEN 200 AND 299) AS success_count,
            COUNT(*) FILTER (WHERE status_code >= 400) AS error_count,
            COALESCE(SUM(duration_ms), 0) AS total_response_time_ms,
            MAX(duration_ms) AS max_response_time_ms,
            MIN(duration_ms) AS min_response_time_ms,
            COUNT(DISTINCT user_id) AS unique_users
        FROM socialcandor_schema.api_error_logs
        WHERE occurred_at >= v_start_time AND occurred_at < v_end_time
        GROUP BY client_id, user_id, endpoint, method, response_status_group
    )
    INSERT INTO socialcandor_schema.api_usage_analytics (
        analytics_date, analytics_hour, time_grain,
        client_id, user_id, endpoint, method, response_status_group,
        request_count, success_count, error_count,
        total_response_time_ms, max_response_time_ms, min_response_time_ms,
        unique_users
    )
    SELECT
        analytics_date, analytics_hour, time_grain,
        client_id, user_id, endpoint, method, response_status_group,
        request_count, success_count, error_count,
        total_response_time_ms, max_response_time_ms, min_response_time_ms,
        unique_users
    FROM hourly_aggregates
    ON CONFLICT (analytics_date, analytics_hour, time_grain, client_id, user_id, endpoint, method, response_status_group)
    DO UPDATE SET
        request_count = EXCLUDED.request_count,
        success_count = EXCLUDED.success_count,
        error_count = EXCLUDED.error_count,
        total_response_time_ms = EXCLUDED.total_response_time_ms,
        max_response_time_ms = EXCLUDED.max_response_time_ms,
        min_response_time_ms = EXCLUDED.min_response_time_ms,
        unique_users = EXCLUDED.unique_users,
        updated_at = CURRENT_TIMESTAMP;

    GET DIAGNOSTICS v_rows_inserted = ROW_COUNT;
    RETURN v_rows_inserted;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION socialcandor_schema.refresh_api_usage_analytics IS 'Aggregates raw API logs into api_usage_analytics for reporting.';


