--================================================================================================
-- TABLE: OI01 - database_migration_history
-- Description: Tracks all database migrations applied to the schema, including version,
--              script name, execution time, and status. Enables auditability and rollback planning.
-- Business Case: As the platform evolves, multiple developers may apply schema changes.
--                This table records every migration run, providing a clear history of schema
--                evolution. It is essential for debugging migration failures, coordinating
--                changes across environments, and ensuring that all instances are in sync.
--                The status column allows quick identification of failed migrations,
--                and the checksum ensures script integrity.
-- KPIs:
--   1. Migration success rate – Percentage of successful migrations.
--   2. Average migration time – Time taken to apply migrations.
--   3. Number of migrations per release – Count of schema changes per version.
--   4. Rollback frequency – How often migrations are rolled back.
--   5. Schema drift – Number of environments with different migration histories.
-- Feature References: DEV02 (Database Change Management), OPS12 (Release Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.database_migration_history (
    -- Primary key
    migration_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    migration_number VARCHAR(50) GENERATED ALWAYS AS (
        'MIG-' || TO_CHAR(executed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.migration_history_seq')::TEXT, 6, '0')
    ) STORED,

    -- Migration metadata
    version VARCHAR(50) NOT NULL,                 -- e.g., '20250410.01'
    name VARCHAR(255) NOT NULL,                    -- Descriptive name
    script_name VARCHAR(255) NOT NULL,             -- Filename of the migration script
    checksum VARCHAR(64) NOT NULL,                  -- SHA-256 of script content

    -- Execution details
    executed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    execution_time_ms INTEGER CHECK (execution_time_ms >= 0),
    status socialcandor_schema.migration_status NOT NULL DEFAULT 'PENDING',
    error_message TEXT,

    -- Environment
    environment VARCHAR(50) CHECK (environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'DR')),

    -- Who applied it
    executed_by UUID,                               -- References users(user_id) if available
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_migration_executed_by FOREIGN KEY (executed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_migration_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_migration_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_migration_version UNIQUE (version, environment)
);

COMMENT ON TABLE socialcandor_schema.database_migration_history IS 'Tracks all database migrations applied to the schema.';
COMMENT ON COLUMN socialcandor_schema.database_migration_history.version IS 'Migration version (e.g., timestamp or semantic version).';
COMMENT ON COLUMN socialcandor_schema.database_migration_history.checksum IS 'SHA-256 hash of the migration script for integrity.';
COMMENT ON COLUMN socialcandor_schema.database_migration_history.execution_time_ms IS 'Duration of the migration in milliseconds.';

-- Indexes
CREATE INDEX idx_migration_history_version ON socialcandor_schema.database_migration_history(version, environment);
CREATE INDEX idx_migration_history_executed ON socialcandor_schema.database_migration_history(executed_at DESC);
CREATE INDEX idx_migration_history_status ON socialcandor_schema.database_migration_history(status) WHERE status != 'SUCCESS';

-- Trigger for updated_at
CREATE TRIGGER trg_database_migration_history_updated_at
    BEFORE UPDATE ON socialcandor_schema.database_migration_history
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin only)
ALTER TABLE socialcandor_schema.database_migration_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY migration_history_admin_policy ON socialcandor_schema.database_migration_history
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: OI02 - schema_version_control
-- Description: Stores the current schema version and applied deltas, complementing migration history.
--              Useful for tools that need a quick lookup of the active schema version.
-- Business Case: While migration history provides an audit log, this table gives a single source
--                of truth for the current schema version in each environment. It helps in
--                automation (CI/CD pipelines) and can be used by application code to verify
--                compatibility. The `is_dirty` flag indicates if any manual changes were detected
--                (schema drift).
-- KPIs:
--   1. Environments up‑to‑date – Percentage of environments on the latest version.
--   2. Schema drift detection – Number of environments flagged as dirty.
--   3. Version consistency – Variance across environments.
--   4. Time since last update – Age of current version.
--   5. Deployment frequency – Rate of version changes.
-- Feature References: DEV02 (Database Change Management), OPS13 (Configuration Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.schema_version_control (
    -- Primary key
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    version_number VARCHAR(50) GENERATED ALWAYS AS (
        'SCHV-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.schema_version_seq')::TEXT, 6, '0')
    ) STORED,

    -- Version details
    schema_version VARCHAR(50) NOT NULL,          -- Current version
    description TEXT,
    applied_migrations TEXT[],                     -- List of migration versions applied
    environment VARCHAR(50) NOT NULL CHECK (environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'DR')),

    -- State
    is_dirty BOOLEAN DEFAULT FALSE,                -- True if manual changes detected
    dirty_reason TEXT,
    last_known_good_version VARCHAR(50),

    -- Timestamps
    applied_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_schema_version_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_schema_version_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_schema_version_environment UNIQUE (environment)
);

COMMENT ON TABLE socialcandor_schema.schema_version_control IS 'Stores the current schema version per environment and detects drift.';
COMMENT ON COLUMN socialcandor_schema.schema_version_control.schema_version IS 'Current schema version identifier.';
COMMENT ON COLUMN socialcandor_schema.schema_version_control.is_dirty IS 'True if manual schema changes are detected (drift).';
COMMENT ON COLUMN socialcandor_schema.schema_version_control.last_known_good_version IS 'Last version known to be clean.';

-- Indexes
CREATE INDEX idx_schema_version_env ON socialcandor_schema.schema_version_control(environment);

-- Trigger for updated_at
CREATE TRIGGER trg_schema_version_control_updated_at
    BEFORE UPDATE ON socialcandor_schema.schema_version_control
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin only)
ALTER TABLE socialcandor_schema.schema_version_control ENABLE ROW LEVEL SECURITY;
CREATE POLICY schema_version_admin_policy ON socialcandor_schema.schema_version_control
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: OI03 - backup_job_logs
-- Description: Logs every backup job execution, including type (full, incremental), start/end time,
--              size, location, and status. Essential for disaster recovery readiness and SLA monitoring.
-- Business Case: Automated backups are critical for data durability and recovery. This table
--                provides a complete audit trail of backup operations, enabling verification that
--                backups are running as scheduled and are restorable. It helps in measuring
--                Recovery Point Objective (RPO) adherence, troubleshooting failures, and planning
--                storage capacity. Integration with monitoring systems alerts on failed backups.
-- KPIs:
--   1. Backup success rate – Percentage of successful backups.
--   2. Backup size trend – Growth of backup size over time.
--   3. Backup duration – Average time to complete a backup.
--   4. RPO adherence – Time since last successful backup.
--   5. Storage utilisation – Total backup storage consumed.
-- Feature References: BCP04 (Backup Management), OPS14 (Disaster Recovery)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.backup_job_logs (
    -- Primary key
    log_id BIGSERIAL PRIMARY KEY,

    -- Human-readable identifier
    job_number VARCHAR(50) GENERATED ALWAYS AS (
        'BKUP-' || TO_CHAR(start_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.backup_job_seq')::TEXT, 6, '0')
    ) STORED,

    -- Backup metadata
    job_name VARCHAR(255) NOT NULL,
    backup_type VARCHAR(30) CHECK (backup_type IN ('FULL', 'INCREMENTAL', 'DIFFERENTIAL', 'LOG')),
    status socialcandor_schema.backup_job_status NOT NULL DEFAULT 'PENDING',

    -- Timing
    scheduled_time TIMESTAMP WITH TIME ZONE,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (end_time - start_time))
    ) STORED,

    -- Backup details
    size_bytes BIGINT CHECK (size_bytes >= 0),
    location_url VARCHAR(500),
    verification_status VARCHAR(30) CHECK (verification_status IN ('PENDING', 'VERIFIED', 'FAILED')),
    verified_at TIMESTAMP WITH TIME ZONE,

    -- Error handling
    error_message TEXT,
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),

    -- Initiator
    triggered_by UUID,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_backup_job_triggered_by FOREIGN KEY (triggered_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_backup_job_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_backup_job_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_backup_job_timing CHECK (end_time IS NULL OR end_time >= start_time)
);

COMMENT ON TABLE socialcandor_schema.backup_job_logs IS 'Logs every backup job execution for audit and monitoring.';
COMMENT ON COLUMN socialcandor_schema.backup_job_logs.job_name IS 'Name or identifier of the backup job.';
COMMENT ON COLUMN socialcandor_schema.backup_job_logs.backup_type IS 'Type of backup performed.';
COMMENT ON COLUMN socialcandor_schema.backup_job_logs.verification_status IS 'Whether the backup was verified (e.g., by restore test).';

-- Indexes
CREATE INDEX idx_backup_job_logs_start ON socialcandor_schema.backup_job_logs(start_time DESC);
CREATE INDEX idx_backup_job_logs_status ON socialcandor_schema.backup_job_logs(status) WHERE status != 'COMPLETED';
CREATE INDEX idx_backup_job_logs_triggered ON socialcandor_schema.backup_job_logs(triggered_by) WHERE triggered_by IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_backup_job_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.backup_job_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin only)
ALTER TABLE socialcandor_schema.backup_job_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY backup_job_logs_admin_policy ON socialcandor_schema.backup_job_logs
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: OI04 - backup_restore_logs
-- Description: Logs all restore operations from backups, including what was restored, when,
--              and the outcome. Critical for disaster recovery testing and actual recovery events.
-- Business Case: Restores are as important as backups. This table records every restore attempt,
--                whether for disaster recovery, testing, or data recovery requests. It provides
--                evidence of recoverability, helps measure Recovery Time Objective (RTO), and
--                assists in post‑mortem analysis of restore failures. The data is essential for
--                compliance audits (e.g., SOC2, ISO27001) that require proof of backup restorability.
-- KPIs:
--   1. Restore success rate – Percentage of successful restores.
--   2. Average restore time – Time to complete a restore (RTO metric).
--   3. Data volume restored – Amount of data recovered.
--   4. Point‑in‑time recoverability – Can we restore to any point within RPO?
--   5. Test frequency – How often restores are tested.
-- Feature References: BCP05 (Restore Testing), OPS15 (Disaster Recovery Execution)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.backup_restore_logs (
    -- Primary key
    log_id BIGSERIAL PRIMARY KEY,

    -- Human-readable identifier
    restore_number VARCHAR(50) GENERATED ALWAYS AS (
        'RSTR-' || TO_CHAR(restore_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.restore_job_seq')::TEXT, 6, '0')
    ) STORED,

    -- Backup reference
    backup_log_id BIGINT,                           -- Link to backup_job_logs.log_id
    backup_location VARCHAR(500),

    -- Restore metadata
    restore_type VARCHAR(30) CHECK (restore_type IN ('FULL', 'PARTIAL', 'POINT_IN_TIME')),
    status socialcandor_schema.backup_job_status NOT NULL DEFAULT 'PENDING',

    -- Timing
    restore_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    start_time TIMESTAMP WITH TIME ZONE,
    end_time TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (end_time - start_time))
    ) STORED,

    -- Target
    target_database VARCHAR(255),
    target_environment VARCHAR(50) CHECK (target_environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'DR', 'TEST')),

    -- Size
    size_bytes BIGINT CHECK (size_bytes >= 0),

    -- Error handling
    error_message TEXT,
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),

    -- Verification
    verification_checksum VARCHAR(64),               -- SHA-256 of restored data
    verification_passed BOOLEAN,

    -- Initiator
    triggered_by UUID,
    reason TEXT,                                     -- Why restore was performed

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_restore_log_backup FOREIGN KEY (backup_log_id)
        REFERENCES socialcandor_schema.backup_job_logs(log_id) ON DELETE SET NULL,
    CONSTRAINT fk_restore_log_triggered_by FOREIGN KEY (triggered_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_restore_log_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_restore_log_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_restore_log_timing CHECK (end_time IS NULL OR end_time >= start_time)
);

COMMENT ON TABLE socialcandor_schema.backup_restore_logs IS 'Logs all restore operations from backups for audit and RTO tracking.';
COMMENT ON COLUMN socialcandor_schema.backup_restore_logs.backup_log_id IS 'Reference to the backup used for restore.';
COMMENT ON COLUMN socialcandor_schema.backup_restore_logs.verification_checksum IS 'Checksum of restored data to verify integrity.';

-- Indexes
CREATE INDEX idx_restore_logs_time ON socialcandor_schema.backup_restore_logs(restore_time DESC);
CREATE INDEX idx_restore_logs_status ON socialcandor_schema.backup_restore_logs(status) WHERE status != 'COMPLETED';
CREATE INDEX idx_restore_logs_backup ON socialcandor_schema.backup_restore_logs(backup_log_id) WHERE backup_log_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_backup_restore_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.backup_restore_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin only)
ALTER TABLE socialcandor_schema.backup_restore_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY restore_logs_admin_policy ON socialcandor_schema.backup_restore_logs
    FOR ALL USING (socialcandor_schema.is_admin());

--================================================================================================
-- TABLE: OI05 - health_check_configurations
-- Description: Defines automated health checks for various system components (services, databases,
--              APIs). Includes check type, endpoint, schedule, thresholds, and alerting rules.
-- Business Case: Proactive monitoring requires well‑defined health checks. This table centralises
--                configuration of checks that probe system health. It supports different check
--                types (HTTP, TCP, SQL query, custom script) and allows dynamic adjustment of
--                thresholds and intervals without code changes. The `is_active` flag enables
--                toggling checks on/off. The data feeds into health_check_results and alerting.
-- KPIs:
--   1. Check coverage – Percentage of critical services with defined health checks.
--   2. Check frequency – How often checks are executed.
--   3. Configuration change frequency – Updates to check parameters.
--   4. False positive rate – Checks that incorrectly reported unhealthy.
--   5. Mean time to detect (MTTD) – Time from failure to detection via health check.
-- Feature References: OPS09 (Health Monitoring), MON03 (Monitoring Configuration)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.health_check_configurations (
    -- Primary key
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    config_number VARCHAR(50) GENERATED ALWAYS AS (
        'HC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.health_check_config_seq')::TEXT, 6, '0')
    ) STORED,

    -- Check identification
    check_name VARCHAR(255) NOT NULL,
    check_description TEXT,
    check_type VARCHAR(30) NOT NULL CHECK (check_type IN ('HTTP', 'TCP', 'SQL', 'COMMAND', 'CUSTOM')),
    target VARCHAR(500) NOT NULL,                     -- URL, host:port, query, command

    -- Schedule
    interval_seconds INTEGER NOT NULL CHECK (interval_seconds >= 5),
    timeout_seconds INTEGER NOT NULL CHECK (timeout_seconds >= 1 AND timeout_seconds <= interval_seconds),
    retry_count INTEGER DEFAULT 0 CHECK (retry_count >= 0),

    -- Thresholds (for response time, success rate, etc.)
    success_criteria JSONB DEFAULT '{}',               -- e.g., {"http_status": 200, "contains": "OK"}
    warning_threshold NUMERIC,                          -- e.g., response time > 500ms
    critical_threshold NUMERIC,

    -- Alerting
    alert_on_warning BOOLEAN DEFAULT TRUE,
    alert_on_critical BOOLEAN DEFAULT TRUE,
    notification_channels TEXT[],                        -- e.g., ['email', 'slack', 'pagerduty']

    -- Ownership
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    version INTEGER DEFAULT 1,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_hc_config_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_hc_config_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_hc_config_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.health_check_configurations IS 'Defines automated health checks for system components.';
COMMENT ON COLUMN socialcandor_schema.health_check_configurations.check_type IS 'Type of health check (HTTP, TCP, SQL, command, custom).';
COMMENT ON COLUMN socialcandor_schema.health_check_configurations.target IS 'Target of the check (URL, host:port, query, etc.).';
COMMENT ON COLUMN socialcandor_schema.health_check_configurations.success_criteria IS 'JSON criteria defining a successful check.';

-- Indexes
CREATE INDEX idx_hc_config_active ON socialcandor_schema.health_check_configurations(is_active) WHERE is_active = TRUE;
CREATE INDEX idx_hc_config_type ON socialcandor_schema.health_check_configurations(check_type);
CREATE INDEX idx_hc_config_owner ON socialcandor_schema.health_check_configurations(owner_team, owner_user_id) WHERE owner_user_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER trg_health_check_configurations_updated_at
    BEFORE UPDATE ON socialcandor_schema.health_check_configurations
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin and ops team only)
ALTER TABLE socialcandor_schema.health_check_configurations ENABLE ROW LEVEL SECURITY;
CREATE POLICY hc_config_admin_policy ON socialcandor_schema.health_check_configurations
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY hc_config_ops_policy ON socialcandor_schema.health_check_configurations
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('OPS', 'SRE', 'PLATFORM_ENGINEER')
    ));

--================================================================================================
-- TABLE: OI06 - health_check_results
-- Description: Stores the results of each health check execution, including status, response time,
--              error details, and any captured metrics. Supports historical analysis and alerting.
-- Business Case: This table records every health check run, providing a complete history of
--                system health. It enables trend analysis (e.g., gradually increasing response times),
--                root cause investigation of outages, and SLA reporting. The data feeds dashboards
--                and alerting systems. Partitioning by date ensures query performance even with
--                high check frequency.
-- KPIs:
--   1. Uptime percentage – Based on health check results.
--   2. Average response time – Per check, over time.
--   3. Error rate – Percentage of failed checks.
--   4. Mean time to recovery – Duration from failure to success.
--   5. Check latency – Time taken to execute each check.
-- Feature References: OPS09 (Health Monitoring), SLA04 (SLA Monitoring)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.health_check_results (
    -- Primary key
    result_id BIGSERIAL,

    -- Human-readable identifier
    result_number VARCHAR(50) GENERATED ALWAYS AS (
        'HCR-' || TO_CHAR(check_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.health_check_config_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    config_id UUID NOT NULL,

    -- Check result
    check_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status socialcandor_schema.health_check_status NOT NULL,
    response_time_ms INTEGER CHECK (response_time_ms >= 0),

    -- Details
    response_payload TEXT,                            -- Raw response (truncated if large)
    error_message TEXT,
    metrics JSONB,                                     -- Any additional metrics (e.g., DB connections)

    -- For HTTP checks
    http_status INTEGER,
    http_headers JSONB,

    -- Partition key
    check_date DATE GENERATED ALWAYS AS (check_time::DATE) STORED,

    -- Constraints
    CONSTRAINT pk_health_check_results PRIMARY KEY (result_id, check_date),
    CONSTRAINT fk_hc_results_config FOREIGN KEY (config_id)
        REFERENCES socialcandor_schema.health_check_configurations(config_id) ON DELETE CASCADE
) PARTITION BY RANGE (check_date);

COMMENT ON TABLE socialcandor_schema.health_check_results IS 'Stores results of health check executions with partitioning for scalability.';
COMMENT ON COLUMN socialcandor_schema.health_check_results.response_payload IS 'Raw response (truncated if large) – for debugging.';
COMMENT ON COLUMN socialcandor_schema.health_check_results.metrics IS 'Additional metrics captured during the check.';

-- Create monthly partitions
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) - (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'health_check_results_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.health_check_results
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes on parent
CREATE INDEX idx_hc_results_config ON socialcandor_schema.health_check_results(config_id, check_time DESC);
CREATE INDEX idx_hc_results_status ON socialcandor_schema.health_check_results(status, check_time DESC) WHERE status != 'HEALTHY';
CREATE INDEX idx_hc_results_time ON socialcandor_schema.health_check_results(check_time DESC);

-- RLS (admin and ops)
ALTER TABLE socialcandor_schema.health_check_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY hc_results_admin_policy ON socialcandor_schema.health_check_results
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY hc_results_ops_policy ON socialcandor_schema.health_check_results
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('OPS', 'SRE', 'PLATFORM_ENGINEER')
    ));

--================================================================================================
-- TABLE: OI07 - incident_response_logs
-- Description: Comprehensive log of operational incidents, including detection, investigation,
--              mitigation, and resolution. Tracks severity, status, assignments, and root cause.
-- Business Case: Incident management is critical for maintaining service reliability. This table
--                provides a structured record of every incident, enabling post‑mortem analysis,
--                trend identification, and process improvement. It supports on‑call rotations by
--                tracking assignments and handoffs. Integration with health check results allows
--                automatic incident creation. The data feeds into reliability metrics like MTTA
--                (Mean Time to Acknowledge) and MTTR (Mean Time to Resolve).
-- KPIs:
--   1. Mean Time to Acknowledge (MTTA) – Time from detection to acknowledgment.
--   2. Mean Time to Resolve (MTTR) – Time from detection to resolution.
--   3. Incident volume – Number of incidents per period.
--   4. Severity distribution – Breakdown by SEV level.
--   5. Recurrence rate – Incidents with same root cause.
-- Feature References: OPS10 (Incident Management), SRE03 (Reliability Engineering)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.incident_response_logs (
    -- Primary key
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'INC-' || TO_CHAR(detected_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.incident_seq')::TEXT, 6, '0')
    ) STORED,

    -- Incident metadata
    title VARCHAR(255) NOT NULL,
    description TEXT,
    severity socialcandor_schema.incident_severity NOT NULL,
    status socialcandor_schema.incident_status NOT NULL DEFAULT 'DETECTED',

    -- Timing
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    mitigated_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,

    -- Ownership
    assigned_to UUID,
    reported_by UUID,

    -- Root cause and resolution
    root_cause TEXT,
    resolution_notes TEXT,
    action_items JSONB,                                 -- List of follow‑up tasks

    -- Impact
    affected_services TEXT[],
    affected_users_count INTEGER CHECK (affected_users_count >= 0),
    downtime_minutes INTEGER CHECK (downtime_minutes >= 0),

    -- Links
    related_health_check BIGINT,                         -- Reference to health_check_results.result_id
    related_incidents UUID[],                            -- For linking related incidents

    -- Post‑mortem
    post_mortem_url VARCHAR(500),
    lessons_learned TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_incident_assigned_to FOREIGN KEY (assigned_to)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_incident_reported_by FOREIGN KEY (reported_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_incident_related_health_check FOREIGN KEY (related_health_check)
        REFERENCES socialcandor_schema.health_check_results(result_id) ON DELETE SET NULL,
    CONSTRAINT fk_incident_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_incident_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_incident_timing CHECK (
        (acknowledged_at IS NULL OR acknowledged_at >= detected_at) AND
        (mitigated_at IS NULL OR mitigated_at >= acknowledged_at) AND
        (resolved_at IS NULL OR resolved_at >= mitigated_at) AND
        (closed_at IS NULL OR closed_at >= resolved_at)
    )
);

COMMENT ON TABLE socialcandor_schema.incident_response_logs IS 'Comprehensive log of operational incidents from detection to resolution.';
COMMENT ON COLUMN socialcandor_schema.incident_response_logs.affected_services IS 'Array of service names affected by the incident.';
COMMENT ON COLUMN socialcandor_schema.incident_response_logs.action_items IS 'JSON list of follow‑up tasks with owners and due dates.';
COMMENT ON COLUMN socialcandor_schema.incident_response_logs.downtime_minutes IS 'Estimated total downtime caused by the incident.';

-- Indexes
CREATE INDEX idx_incident_logs_detected ON socialcandor_schema.incident_response_logs(detected_at DESC);
CREATE INDEX idx_incident_logs_status ON socialcandor_schema.incident_response_logs(status, severity);
CREATE INDEX idx_incident_logs_assigned ON socialcandor_schema.incident_response_logs(assigned_to) WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_incident_logs_services ON socialcandor_schema.incident_response_logs USING GIN (affected_services);

-- Trigger for updated_at
CREATE TRIGGER trg_incident_response_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.incident_response_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin and ops)
ALTER TABLE socialcandor_schema.incident_response_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY incident_logs_admin_policy ON socialcandor_schema.incident_response_logs
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY incident_logs_ops_policy ON socialcandor_schema.incident_response_logs
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('OPS', 'SRE', 'ON_CALL')
    ));
CREATE POLICY incident_logs_assigned_policy ON socialcandor_schema.incident_response_logs
    FOR UPDATE USING (assigned_to = current_setting('app.current_user_id')::UUID);

--================================================================================================
-- TABLE: OI08 - capacity_planning_records
-- Description: Stores forecasts and actual usage for various infrastructure resources over time.
--              Helps predict future capacity needs and avoid shortages.
-- Business Case: Capacity planning is essential for cost optimisation and service reliability.
--                This table records predicted and actual usage of resources such as storage,
--                memory, CPU, database connections, and API calls. By analysing trends,
--                the platform can proactively scale resources, avoiding performance degradation
--                or outages. It also supports budgeting and chargeback by providing historical
--                usage data. The `forecast_date` and `resource_type` dimensions allow slicing
--                by time and resource.
-- KPIs:
--   1. Forecast accuracy – Difference between predicted and actual values.
--   2. Resource utilisation trend – Growth rate per resource.
--   3. Peak usage times – Patterns in resource demand.
--   4. Over‑provisioning cost – Excess capacity purchased.
--   5. Under‑provisioning incidents – Number of capacity‑related outages.
-- Feature References: OPS11 (Capacity Planning), FIN07 (Cost Forecasting)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.capacity_planning_records (
    -- Primary key
    record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    record_number VARCHAR(50) GENERATED ALWAYS AS (
        'CAP-' || TO_CHAR(forecast_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.capacity_planning_seq')::TEXT, 6, '0')
    ) STORED,

    -- Resource identification
    resource_type socialcandor_schema.capacity_resource_type NOT NULL,
    resource_name VARCHAR(255),                         -- e.g., 'postgresql_main', 'redis_cache'

    -- Forecast data
    forecast_date DATE NOT NULL,                         -- Date of the forecast (the point in time)
    forecast_value NUMERIC NOT NULL CHECK (forecast_value >= 0),
    actual_value NUMERIC CHECK (actual_value >= 0),
    unit VARCHAR(20) NOT NULL,                           -- e.g., 'GB', 'cores', 'requests'

    -- Confidence / range
    forecast_upper_bound NUMERIC,
    forecast_lower_bound NUMERIC,
    confidence_level NUMERIC(5,2) CHECK (confidence_level >= 0 AND confidence_level <= 100),

    -- Context
    forecast_model VARCHAR(100),                          -- e.g., 'linear_regression', 'time_series'
    data_source VARCHAR(255),

    -- Tags for grouping
    environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT')),
    cluster VARCHAR(100),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_capacity_planning_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_capacity_planning_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_capacity_forecast UNIQUE (resource_type, resource_name, forecast_date, environment)
);

COMMENT ON TABLE socialcandor_schema.capacity_planning_records IS 'Stores capacity forecasts and actual usage for infrastructure resources.';
COMMENT ON COLUMN socialcandor_schema.capacity_planning_records.forecast_value IS 'Predicted resource usage.';
COMMENT ON COLUMN socialcandor_schema.capacity_planning_records.actual_value IS 'Actual usage (to be filled later for accuracy tracking).';
COMMENT ON COLUMN socialcandor_schema.capacity_planning_records.forecast_upper_bound IS 'Upper bound of prediction interval.';
COMMENT ON COLUMN socialcandor_schema.capacity_planning_records.forecast_lower_bound IS 'Lower bound of prediction interval.';

-- Indexes
CREATE INDEX idx_capacity_planning_date ON socialcandor_schema.capacity_planning_records(forecast_date DESC);
CREATE INDEX idx_capacity_planning_resource ON socialcandor_schema.capacity_planning_records(resource_type, resource_name);

-- Trigger for updated_at
CREATE TRIGGER trg_capacity_planning_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.capacity_planning_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin and finance)
ALTER TABLE socialcandor_schema.capacity_planning_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY capacity_planning_admin_policy ON socialcandor_schema.capacity_planning_records
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY capacity_planning_ops_policy ON socialcandor_schema.capacity_planning_records
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('OPS', 'SRE', 'FIN_OPS')
    ));

--================================================================================================
-- TABLE: OI09 - cost_allocation_records
-- Description: Tracks infrastructure and operational costs attributed to teams, projects,
--              features, or cost centres. Supports showback/chargeback models.
-- Business Case: In cloud environments, understanding who spends what is crucial for cost
--                optimisation and internal billing. This table allocates costs from providers
--                (AWS, GCP, etc.) to internal entities using tags or proportional splits.
--                It enables teams to see their cloud spend, promotes accountability, and
--                helps identify waste. The data feeds into financial reporting and budgeting.
--                Historical records support trend analysis and anomaly detection.
-- KPIs:
--   1. Cost per team/project – Monthly spend by cost centre.
--   2. Unit cost – e.g., cost per API call, per GB stored.
--   3. Cost trend – Month‑over‑month change.
--   4. Anomaly detection – Unusual spikes in cost.
--   5. Allocation accuracy – Percentage of costs correctly attributed.
-- Feature References: FIN06 (Showback/Chargeback), OPS16 (Cloud Cost Management)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.cost_allocation_records (
    -- Primary key
    allocation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    allocation_number VARCHAR(50) GENERATED ALWAYS AS (
        'COST-' || TO_CHAR(cost_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.cost_allocation_seq')::TEXT, 6, '0')
    ) STORED,

    -- Cost dimensions
    cost_date DATE NOT NULL,
    cost_center VARCHAR(100) NOT NULL,
    team VARCHAR(100),
    project VARCHAR(100),
    feature VARCHAR(100),
    environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT', 'TEST')),

    -- Resource details
    service_provider VARCHAR(50) NOT NULL CHECK (service_provider IN ('AWS', 'GCP', 'AZURE', 'INTERNAL', 'OTHER')),
    service_name VARCHAR(100) NOT NULL,
    resource_id VARCHAR(255),

    -- Cost details
    amount NUMERIC(15,6) NOT NULL CHECK (amount >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    usage_quantity NUMERIC(15,6),
    usage_unit VARCHAR(50),

    -- Allocation method
    allocation_method VARCHAR(50) CHECK (allocation_method IN ('DIRECT', 'PROPORTIONAL', 'FIXED_PERCENTAGE', 'USAGE_BASED')),
    allocation_percentage NUMERIC(5,2) CHECK (allocation_percentage >= 0 AND allocation_percentage <= 100),

    -- Tags
    resource_tags JSONB,
    custom_labels JSONB,

    -- References
    invoice_id UUID,                                         -- Link to invoices table if exists

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_cost_allocation_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_cost_allocation_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.cost_allocation_records IS 'Tracks infrastructure costs attributed to teams, projects, and features.';
COMMENT ON COLUMN socialcandor_schema.cost_allocation_records.cost_center IS 'Business cost centre for accounting.';
COMMENT ON COLUMN socialcandor_schema.cost_allocation_records.allocation_method IS 'Method used to allocate this cost.';
COMMENT ON COLUMN socialcandor_schema.cost_allocation_records.resource_tags IS 'Original cloud provider tags.';

-- Indexes
CREATE INDEX idx_cost_allocation_date ON socialcandor_schema.cost_allocation_records(cost_date DESC);
CREATE INDEX idx_cost_allocation_team ON socialcandor_schema.cost_allocation_records(team, cost_center, cost_date);
CREATE INDEX idx_cost_allocation_project ON socialcandor_schema.cost_allocation_records(project, cost_date);
CREATE INDEX idx_cost_allocation_tags ON socialcandor_schema.cost_allocation_records USING GIN (resource_tags);

-- Trigger for updated_at
CREATE TRIGGER trg_cost_allocation_records_updated_at
    BEFORE UPDATE ON socialcandor_schema.cost_allocation_records
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (finance, admin, and team leads)
ALTER TABLE socialcandor_schema.cost_allocation_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY cost_allocation_admin_policy ON socialcandor_schema.cost_allocation_records
    FOR ALL USING (socialcandor_schema.is_admin());
