--================================================================================================
-- TABLE: OI10 - performance_benchmarks
-- Description: Stores baseline and historical performance metrics for key system operations,
--              such as API response times, database query times, and page load speeds.
-- Business Case: Performance regression can degrade user experience. This table records
--                benchmark results over time, allowing teams to track performance trends,
--                detect regressions, and validate optimisations. It can be populated by
--                automated performance tests (e.g., k6, JMeter) and monitoring tools.
--                By comparing current results against historical baselines, the platform
--                can alert when performance degrades beyond acceptable thresholds.
-- KPIs:
--   1. Response time trend – 95th percentile over time.
--   2. Throughput – Requests per second.
--   3. Error rate during benchmarks – Percentage of failed requests.
--   4. Baseline drift – Shift in performance from established baseline.
--   5. Optimisation impact – Improvement after code changes.
-- Feature References: PERF02 (Performance Testing), SRE04 (Service Level Indicators)
--================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.performance_benchmarks (
    -- Primary key
    benchmark_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    benchmark_number VARCHAR(50) GENERATED ALWAYS AS (
        'BENCH-' || TO_CHAR(test_date, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.performance_benchmark_seq')::TEXT, 6, '0')
    ) STORED,

    -- Benchmark identification
    benchmark_name VARCHAR(255) NOT NULL,
    benchmark_description TEXT,
    benchmark_type VARCHAR(50) CHECK (benchmark_type IN ('API', 'DATABASE', 'UI', 'LOAD', 'STRESS', 'ENDURANCE')),

    -- Test context
    test_date DATE NOT NULL,
    environment VARCHAR(50) CHECK (environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION', 'PERF_TEST')),
    version VARCHAR(100),                                 -- Application version under test

    -- Metrics
    metric_name VARCHAR(100) NOT NULL,                    -- e.g., 'response_time', 'throughput', 'error_rate'
    metric_value NUMERIC NOT NULL,
    unit VARCHAR(20) NOT NULL,                             -- e.g., 'ms', 'rps', '%'
    percentile VARCHAR(10),                                -- e.g., 'p50', 'p95', 'p99' (if applicable)

    -- Test configuration
    test_parameters JSONB,                                 -- e.g., concurrent users, duration
    test_tool VARCHAR(100),

    -- Results
    raw_results_url VARCHAR(500),                          -- Link to detailed report
    summary TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_perf_benchmark_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_perf_benchmark_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE socialcandor_schema.performance_benchmarks IS 'Stores baseline and historical performance metrics for system operations.';
COMMENT ON COLUMN socialcandor_schema.performance_benchmarks.percentile IS 'Percentile (p50, p95, p99) for the metric.';
COMMENT ON COLUMN socialcandor_schema.performance_benchmarks.test_parameters IS 'JSON configuration of the performance test.';

-- Indexes
CREATE INDEX idx_perf_benchmark_date ON socialcandor_schema.performance_benchmarks(test_date DESC);
CREATE INDEX idx_perf_benchmark_name ON socialcandor_schema.performance_benchmarks(benchmark_name, test_date DESC);
CREATE INDEX idx_perf_benchmark_metric ON socialcandor_schema.performance_benchmarks(metric_name, metric_value DESC);

-- Trigger for updated_at
CREATE TRIGGER trg_performance_benchmarks_updated_at
    BEFORE UPDATE ON socialcandor_schema.performance_benchmarks
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS (admin, performance team)
ALTER TABLE socialcandor_schema.performance_benchmarks ENABLE ROW LEVEL SECURITY;
CREATE POLICY perf_benchmark_admin_policy ON socialcandor_schema.performance_benchmarks
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY perf_benchmark_team_policy ON socialcandor_schema.performance_benchmarks
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('PERFORMANCE_ENGINEER', 'QA', 'DEVELOPER')
    ));



-- =================================================================================================
-- ENUMS
-- =================================================================================================

-- Enum: onboarding_step_status
-- Description: Possible statuses for a user's progress through an onboarding step.
-- Business Case: Enables tracking of each step's completion state, supporting progress
--                visualization and analytics on drop‑off points.
-- Feature Reference: ONB01 (Onboarding Workflow)
-- =================================================================================================
CREATE TYPE socialcandor_schema.onboarding_step_status AS ENUM (
    'PENDING',      -- Step not yet started
    'IN_PROGRESS',  -- Step started but not finished
    'COMPLETED',    -- Step successfully finished
    'SKIPPED'       -- Step explicitly skipped (e.g., optional step)
);
COMMENT ON TYPE socialcandor_schema.onboarding_step_status IS 'Status of a user''s progress through an onboarding step.';

-- Enum: lifecycle_stage_name
-- Description: Predefined names for user lifecycle stages.
-- Business Case: Standardizes the stages used across the platform for segmentation and targeting.
-- Feature Reference: LCM04 (Lifecycle Stages)
-- =================================================================================================
CREATE TYPE socialcandor_schema.lifecycle_stage_name AS ENUM (
    'NEW',              -- Recently registered, limited activity
    'ACTIVE',           -- Regular engaged user
    'AT_RISK',          -- Decreasing engagement, risk of churn
    'CHURNED',          -- Inactive beyond threshold
    'DORMANT',          -- Long‑term inactive, not yet churned
    'REACTIVATED'       -- Previously churned but now active again
);
COMMENT ON TYPE socialcandor_schema.lifecycle_stage_name IS 'Standard lifecycle stage names for user segmentation.';

-- Enum: experiment_status
-- Description: Lifecycle status of an A/B test experiment.
-- Business Case: Tracks experiment from creation to analysis, ensuring proper data collection.
-- Feature Reference: EXP03 (Experimentation)
-- =================================================================================================
CREATE TYPE socialcandor_schema.experiment_status AS ENUM (
    'DRAFT',        -- Being set up, not live
    'RUNNING',      -- Actively assigning users
    'PAUSED',       -- Temporarily stopped, assignments not affected
    'COMPLETED',    -- Data collection finished
    'CANCELLED',    -- Abandoned before completion
    'ARCHIVED'      -- Retained for historical reference
);
COMMENT ON TYPE socialcandor_schema.experiment_status IS 'Lifecycle status of an A/B test experiment.';

-- Enum: journey_status
-- Description: Status of a user journey (e.g., onboarding, purchase flow).
-- Business Case: Enables monitoring of funnel completion and drop‑off.
-- Feature Reference: JNY01 (User Journeys)
-- =================================================================================================
CREATE TYPE socialcandor_schema.journey_status AS ENUM (
    'IN_PROGRESS',
    'COMPLETED',
    'ABANDONED',
    'EXPIRED'
);
COMMENT ON TYPE socialcandor_schema.journey_status IS 'Status of a user journey instance.';

-- =================================================================================================
-- SEQUENCES (for human‑readable identifiers where needed)
-- =================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.ab_test_experiment_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.user_journey_mapping_seq START 1000;

-- =================================================================================================
-- TABLE: 1 - user_onboarding_steps
-- Description: Defines the steps that constitute the user onboarding workflow.
-- Business Case: Onboarding is critical for user activation and retention. This table allows
--                product teams to define and manage the sequence of steps (email verification,
--                profile completion, first post, etc.) that new users should complete.
--                Steps can be marked as required or optional, and their order can be adjusted
--                without code changes. This flexibility supports iterative improvements to the
--                onboarding flow based on A/B test results and user feedback.
-- KPIs:
--   1. Step completion rate – percentage of users completing each step.
--   2. Average time per step – how long users take to finish each step.
--   3. Drop‑off rate – users who abandon onboarding at a given step.
--   4. Step impact – correlation between step completion and long‑term retention.
--   5. Optional step uptake – how many users choose to complete optional steps.
-- Feature Reference: ONB01 (Onboarding Workflow)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_onboarding_steps (
    -- Primary key
    step_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Step identification
    step_code VARCHAR(50) NOT NULL UNIQUE,
    step_name VARCHAR(255) NOT NULL,
    step_description TEXT,
    step_order INTEGER NOT NULL CHECK (step_order >= 0),

    -- Configuration
    is_required BOOLEAN NOT NULL DEFAULT TRUE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_onboarding_steps_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_onboarding_steps_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_onboarding_step_order UNIQUE (step_order)
);
COMMENT ON TABLE socialcandor_schema.user_onboarding_steps IS 'Defines the steps that constitute the user onboarding workflow.';
COMMENT ON COLUMN socialcandor_schema.user_onboarding_steps.step_code IS 'Unique short code for the step, e.g., "email_verification".';
COMMENT ON COLUMN socialcandor_schema.user_onboarding_steps.is_required IS 'Whether the step is mandatory for onboarding completion.';

-- Indexes
CREATE INDEX idx_onboarding_steps_active ON socialcandor_schema.user_onboarding_steps(is_active) WHERE is_active = TRUE;

-- RLS
ALTER TABLE socialcandor_schema.user_onboarding_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY onboarding_steps_admin_policy ON socialcandor_schema.user_onboarding_steps
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger for updated_at
CREATE TRIGGER trg_user_onboarding_steps_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_onboarding_steps
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 2 - user_onboarding_progress
-- Description: Tracks each user's progress through the onboarding steps.
-- Business Case: This table records which onboarding steps each user has completed, when they
--                started/finished, and the current status. It enables real‑time progress
--                visualization in the UI, personalized nudges for incomplete steps, and funnel
--                analysis to identify where users drop off. The data supports A/B testing of
--                different onboarding flows and helps product managers measure the effectiveness
--                of changes. By linking to user activity, we can correlate completion rates
--                with long‑term engagement and revenue.
-- KPIs:
--   1. Onboarding completion rate – users who finish all required steps.
--   2. Time to complete onboarding – average days from registration to completion.
--   3. Step‑level drop‑off – percentage of users abandoning at each step.
--   4. Impact on retention – retention difference between completed vs. incomplete users.
--   5. Step duration – average time per step.
-- Feature Reference: ONB02 (Onboarding Progress)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_onboarding_progress (
    -- Primary key
    progress_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,
    step_id UUID NOT NULL,

    -- Progress details
    status socialcandor_schema.onboarding_step_status NOT NULL DEFAULT 'PENDING',
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Metadata (e.g., client info at time of completion)
    metadata JSONB DEFAULT '{}',

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_onboarding_progress_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_onboarding_progress_step FOREIGN KEY (step_id)
        REFERENCES socialcandor_schema.user_onboarding_steps(step_id) ON DELETE CASCADE,
    CONSTRAINT fk_onboarding_progress_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_onboarding_progress_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_onboarding_progress UNIQUE (user_id, step_id),
    CONSTRAINT chk_onboarding_progress_dates CHECK (
        (started_at IS NULL) OR (completed_at IS NULL) OR (completed_at >= started_at)
    ),
    CONSTRAINT chk_onboarding_progress_status_dates CHECK (
        (status = 'PENDING' AND started_at IS NULL AND completed_at IS NULL) OR
        (status = 'IN_PROGRESS' AND started_at IS NOT NULL AND completed_at IS NULL) OR
        (status IN ('COMPLETED', 'SKIPPED') AND started_at IS NOT NULL AND completed_at IS NOT NULL)
    )
);
COMMENT ON TABLE socialcandor_schema.user_onboarding_progress IS 'Tracks each user''s progress through the onboarding steps.';
COMMENT ON COLUMN socialcandor_schema.user_onboarding_progress.metadata IS 'Additional context (e.g., device, app version) when step was completed.';

-- Indexes
CREATE INDEX idx_onboarding_progress_user ON socialcandor_schema.user_onboarding_progress(user_id);
CREATE INDEX idx_onboarding_progress_step ON socialcandor_schema.user_onboarding_progress(step_id);
CREATE INDEX idx_onboarding_progress_status ON socialcandor_schema.user_onboarding_progress(status, user_id);

-- RLS
ALTER TABLE socialcandor_schema.user_onboarding_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY onboarding_progress_self_policy ON socialcandor_schema.user_onboarding_progress
    FOR ALL USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY onboarding_progress_admin_policy ON socialcandor_schema.user_onboarding_progress
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger for updated_at
CREATE TRIGGER trg_user_onboarding_progress_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_onboarding_progress
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 3 - user_lifecycle_stages
-- Description: Defines the lifecycle stages a user can occupy (new, active, at‑risk, churned, etc.).
-- Business Case: This reference table provides a structured taxonomy of user lifecycle stages,
--                each with optional engagement score thresholds. It enables consistent segmentation
--                across the platform for targeting, reporting, and automated actions (e.g., send
--                re‑engagement emails when a user moves to "at‑risk"). The thresholds can be
--                tuned based on historical data, supporting dynamic stage assignment.
-- KPIs:
--   1. Stage distribution – percentage of users in each stage.
--   2. Transition rates – movement between stages over time.
--   3. Churn prediction accuracy – how well stage thresholds predict actual churn.
--   4. Stage‑specific retention – retention rates by stage.
--   5. Time in stage – average duration users stay in each stage.
-- Feature Reference: LCM04 (Lifecycle Stages)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_lifecycle_stages (
    -- Primary key
    stage_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Stage identification
    stage_code VARCHAR(50) NOT NULL UNIQUE,
    stage_name socialcandor_schema.lifecycle_stage_name NOT NULL,
    description TEXT,

    -- Thresholds (optional, can be NULL if not score‑based)
    min_engagement_score INTEGER CHECK (min_engagement_score >= 0 AND min_engagement_score <= 1000),
    max_engagement_score INTEGER CHECK (max_engagement_score >= 0 AND max_engagement_score <= 1000),

    -- Order for presentation (e.g., in dropdowns)
    display_order INTEGER DEFAULT 0 CHECK (display_order >= 0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_lifecycle_stages_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_lifecycle_stages_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_lifecycle_stages_thresholds CHECK (
        (min_engagement_score IS NULL AND max_engagement_score IS NULL) OR
        (min_engagement_score <= max_engagement_score)
    )
);
COMMENT ON TABLE socialcandor_schema.user_lifecycle_stages IS 'Defines the lifecycle stages a user can occupy, with optional engagement score thresholds.';
COMMENT ON COLUMN socialcandor_schema.user_lifecycle_stages.min_engagement_score IS 'Minimum engagement score to enter this stage (inclusive).';
COMMENT ON COLUMN socialcandor_schema.user_lifecycle_stages.max_engagement_score IS 'Maximum engagement score for this stage (inclusive).';

-- Indexes
CREATE INDEX idx_lifecycle_stages_active ON socialcandor_schema.user_lifecycle_stages(is_active) WHERE is_active = TRUE;

-- RLS
ALTER TABLE socialcandor_schema.user_lifecycle_stages ENABLE ROW LEVEL SECURITY;
CREATE POLICY lifecycle_stages_admin_policy ON socialcandor_schema.user_lifecycle_stages
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger for updated_at
CREATE TRIGGER trg_user_lifecycle_stages_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_lifecycle_stages
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 4 - user_churn_predictions
-- Description: Stores machine learning model predictions of user churn probability.
-- Business Case: Proactive churn prevention requires predicting which users are likely to churn.
--                This table stores daily (or periodic) churn predictions for each user, along
--                with the model version and feature snapshot. Marketing and product teams can
--                use these scores to trigger targeted interventions (e.g., discounts, re‑engagement
--                emails). Over time, actual churn outcomes can be recorded to evaluate model
--                accuracy and retrain models. The data also supports cohort analysis of
--                high‑risk segments.
-- KPIs:
--   1. Prediction accuracy – precision/recall at various probability thresholds.
--   2. AUC – area under the ROC curve for the model.
--   3. Intervention effectiveness – difference in churn rate between treated and untreated high‑risk users.
--   4. Model drift – change in prediction distribution over time.
--   5. Coverage – percentage of users with predictions.
-- Feature Reference: MLP01 (Churn Prediction)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_churn_predictions (
    -- Primary key
    prediction_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- Prediction details
    prediction_date DATE NOT NULL DEFAULT CURRENT_DATE,
    churn_probability NUMERIC(5,4) NOT NULL CHECK (churn_probability >= 0 AND churn_probability <= 1),

    -- Model metadata
    model_version VARCHAR(50) NOT NULL,
    feature_snapshot_id UUID,           -- Could reference a feature store snapshot
    feature_importance JSONB,            -- Key features contributing to this prediction

    -- Actual outcome (filled later)
    actual_churn BOOLEAN,                -- NULL until observed
    actual_churn_date DATE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,            -- Usually a system user

    -- Constraints
    CONSTRAINT fk_churn_predictions_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_churn_predictions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,

    CONSTRAINT uk_churn_predictions UNIQUE (user_id, prediction_date)
);
COMMENT ON TABLE socialcandor_schema.user_churn_predictions IS 'Stores ML model predictions of user churn probability.';
COMMENT ON COLUMN socialcandor_schema.user_churn_predictions.churn_probability IS 'Predicted probability of churn (0-1).';
COMMENT ON COLUMN socialcandor_schema.user_churn_predictions.feature_snapshot_id IS 'ID of the feature snapshot used for this prediction.';
COMMENT ON COLUMN socialcandor_schema.user_churn_predictions.actual_churn IS 'Whether the user actually churned (filled after observation window).';

-- Indexes
CREATE INDEX idx_churn_predictions_user ON socialcandor_schema.user_churn_predictions(user_id, prediction_date DESC);
CREATE INDEX idx_churn_predictions_prob ON socialcandor_schema.user_churn_predictions(churn_probability DESC)
    WHERE actual_churn IS NULL;
CREATE INDEX idx_churn_predictions_date ON socialcandor_schema.user_churn_predictions(prediction_date);

-- RLS
ALTER TABLE socialcandor_schema.user_churn_predictions ENABLE ROW LEVEL SECURITY;
CREATE POLICY churn_predictions_admin_policy ON socialcandor_schema.user_churn_predictions
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY churn_predictions_ml_team_policy ON socialcandor_schema.user_churn_predictions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('DATA_SCIENTIST', 'ML_ENGINEER', 'ANALYST')
    ));

-- =================================================================================================
-- TABLE: 5 - user_lifetime_value
-- Description: Calculates and stores lifetime value (LTV) for users, updated periodically.
-- Business Case: LTV is a fundamental metric for understanding user profitability and guiding
--                acquisition spend. This table stores the computed LTV for each user, along with
--                confidence intervals and the method used. It can be updated daily or weekly via
--                batch jobs. Marketing teams use LTV to segment users (high‑value, low‑value) and
--                tailor campaigns. Product teams use it to evaluate feature impact on long‑term
--                revenue. The table also supports predictive LTV based on early activity.
-- KPIs:
--   1. Average LTV – overall and by cohort.
--   2. LTV/CAC ratio – return on acquisition spend.
--   3. LTV distribution – percentage of users in each LTV bucket.
--   4. LTV accuracy – difference between predicted and actual LTV over time.
--   5. Time to value – how long until a user reaches a certain LTV threshold.
-- Feature Reference: FIN07 (Lifetime Value)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_lifetime_value (
    -- Primary key
    ltv_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    user_id UUID NOT NULL,

    -- LTV details
    calculation_date DATE NOT NULL DEFAULT CURRENT_DATE,
    ltv_value NUMERIC(15,2) NOT NULL CHECK (ltv_value >= 0),
    currency CHAR(3) NOT NULL DEFAULT 'USD',

    -- Confidence interval (optional, for probabilistic models)
    confidence_interval_lower NUMERIC(15,2) CHECK (confidence_interval_lower >= 0),
    confidence_interval_upper NUMERIC(15,2) CHECK (confidence_interval_upper >= 0),

    -- Metadata
    calculation_method VARCHAR(100) NOT NULL,      -- e.g., 'historical', 'predictive_model_v3'
    parameters_used JSONB,                          -- e.g., discount rate, time horizon
    data_date_range_start DATE,
    data_date_range_end DATE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,                        -- Usually a system user

    -- Constraints
    CONSTRAINT fk_ltv_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ltv_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,

    CONSTRAINT uk_ltv_user_date UNIQUE (user_id, calculation_date),
    CONSTRAINT chk_ltv_interval CHECK (
        (confidence_interval_lower IS NULL AND confidence_interval_upper IS NULL) OR
        (confidence_interval_lower <= confidence_interval_upper)
    ),
    CONSTRAINT chk_ltv_dates CHECK (
        (data_date_range_start IS NULL AND data_date_range_end IS NULL) OR
        (data_date_range_end >= data_date_range_start)
    )
);
COMMENT ON TABLE socialcandor_schema.user_lifetime_value IS 'Stores calculated lifetime value for users, updated periodically.';
COMMENT ON COLUMN socialcandor_schema.user_lifetime_value.ltv_value IS 'Monetary value of the user over their lifetime.';
COMMENT ON COLUMN socialcandor_schema.user_lifetime_value.calculation_method IS 'Method used to calculate LTV (e.g., historical, predictive).';
COMMENT ON COLUMN socialcandor_schema.user_lifetime_value.parameters_used IS 'Parameters used in the calculation (discount rate, horizon, etc.).';

-- Indexes
CREATE INDEX idx_ltv_user ON socialcandor_schema.user_lifetime_value(user_id, calculation_date DESC);
CREATE INDEX idx_ltv_value ON socialcandor_schema.user_lifetime_value(ltv_value DESC) WHERE ltv_value > 0;
CREATE INDEX idx_ltv_date ON socialcandor_schema.user_lifetime_value(calculation_date);

-- RLS
ALTER TABLE socialcandor_schema.user_lifetime_value ENABLE ROW LEVEL SECURITY;
CREATE POLICY ltv_admin_policy ON socialcandor_schema.user_lifetime_value
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY ltv_analyst_policy ON socialcandor_schema.user_lifetime_value
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST', 'FINANCE')
    ));

-- =================================================================================================
-- TABLE: 6 - ab_test_experiments
-- Description: Defines A/B test experiments, including hypothesis, variants, and target audience.
-- Business Case: Systematic experimentation is essential for data‑driven product decisions.
--                This table stores metadata for each A/B test: what is being tested, the variants,
--                the target audience criteria, the primary metric, and scheduling. It acts as the
--                central registry for all experiments, enabling consistent assignment logic and
--                results analysis. The status field controls whether assignments are active,
--                ensuring that only running experiments assign users.
-- KPIs:
--   1. Experiment velocity – number of experiments run per quarter.
--   2. Success rate – percentage of experiments that achieve statistically significant improvement.
--   3. Average duration – time from start to completion.
--   4. Sample size – number of users exposed per variant.
--   5. Feature adoption – how often experiments lead to permanent feature rollouts.
-- Feature Reference: EXP03 (Experimentation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ab_test_experiments (
    -- Primary key
    experiment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    experiment_number VARCHAR(50) GENERATED ALWAYS AS (
        'EXP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.ab_test_experiment_seq')::TEXT, 6, '0')
    ) STORED,

    -- Experiment identification
    experiment_code VARCHAR(100) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    hypothesis TEXT,

    -- Configuration
    status socialcandor_schema.experiment_status NOT NULL DEFAULT 'DRAFT',
    start_date TIMESTAMP WITH TIME ZONE,
    end_date TIMESTAMP WITH TIME ZONE,

    -- Targeting
    target_audience_criteria JSONB,                    -- e.g., segment ID, user properties

    -- Variants: JSON array with each variant's name, description, and configuration
    variants JSONB NOT NULL CHECK (jsonb_typeof(variants) = 'array' AND jsonb_array_length(variants) >= 2),

    -- Metrics
    primary_metric VARCHAR(255) NOT NULL,               -- e.g., 'conversion_rate'
    secondary_metrics TEXT[],                           -- other metrics to track

    -- Allocation
    traffic_allocation_percent NUMERIC(5,2) DEFAULT 100.0 CHECK (traffic_allocation_percent >= 0 AND traffic_allocation_percent <= 100),

    -- Owner
    owner_user_id UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_ab_test_experiments_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ab_test_experiments_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ab_test_experiments_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_ab_test_dates CHECK (end_date IS NULL OR end_date > start_date)
);
COMMENT ON TABLE socialcandor_schema.ab_test_experiments IS 'Defines A/B test experiments, including hypothesis, variants, and target audience.';
COMMENT ON COLUMN socialcandor_schema.ab_test_experiments.variants IS 'JSON array of variants, each containing name, description, and configuration.';
COMMENT ON COLUMN socialcandor_schema.ab_test_experiments.primary_metric IS 'The key metric used to determine experiment success.';
COMMENT ON COLUMN socialcandor_schema.ab_test_experiments.traffic_allocation_percent IS 'Percentage of eligible traffic assigned to the experiment (0-100).';

-- Indexes
CREATE INDEX idx_ab_test_experiments_status ON socialcandor_schema.ab_test_experiments(status, start_date);
CREATE INDEX idx_ab_test_experiments_owner ON socialcandor_schema.ab_test_experiments(owner_user_id) WHERE owner_user_id IS NOT NULL;

-- RLS
ALTER TABLE socialcandor_schema.ab_test_experiments ENABLE ROW LEVEL SECURITY;
CREATE POLICY ab_test_experiments_read_policy ON socialcandor_schema.ab_test_experiments
    FOR SELECT USING (TRUE);
CREATE POLICY ab_test_experiments_write_policy ON socialcandor_schema.ab_test_experiments
    FOR ALL USING (
        owner_user_id = current_setting('app.current_user_id')::UUID OR
        socialcandor_schema.is_admin()
    );

-- Trigger for updated_at
CREATE TRIGGER trg_ab_test_experiments_updated_at
    BEFORE UPDATE ON socialcandor_schema.ab_test_experiments
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 7 - ab_test_assignments
-- Description: Records which user was assigned to which variant of an experiment.
-- Business Case: Accurate assignment tracking is critical for valid experiment results.
--                This table stores each user's variant assignment for every experiment they
--                are exposed to. It prevents double‑counting and allows for consistent
--                analysis. The unique constraint ensures a user is assigned only once per
--                experiment. The table also captures the assignment context (session, timestamp)
--                to support analysis of multiple exposures and session‑based metrics.
-- KPIs:
--   1. Assignment volume – number of users assigned per experiment.
--   2. Balance check – distribution of users across variants.
--   3. Exposure frequency – how many experiments a typical user is in.
--   4. Assignment consistency – users assigned to same variant across sessions.
--   5. Sample ratio mismatch – detection of assignment bias.
-- Feature Reference: EXP04 (Experiment Assignments)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ab_test_assignments (
    -- Primary key
    assignment_id BIGSERIAL PRIMARY KEY,

    -- References
    experiment_id UUID NOT NULL,
    user_id UUID NOT NULL,
    session_id UUID,                                     -- Optional: session at time of assignment

    -- Assignment details
    variant_name VARCHAR(100) NOT NULL,
    assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Metadata
    context JSONB DEFAULT '{}',                          -- e.g., device, app version

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_ab_test_assignments_experiment FOREIGN KEY (experiment_id)
        REFERENCES socialcandor_schema.ab_test_experiments(experiment_id) ON DELETE CASCADE,
    CONSTRAINT fk_ab_test_assignments_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ab_test_assignments_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,

    CONSTRAINT uk_ab_test_assignments UNIQUE (experiment_id, user_id)
);
COMMENT ON TABLE socialcandor_schema.ab_test_assignments IS 'Records which user was assigned to which variant of an experiment.';
COMMENT ON COLUMN socialcandor_schema.ab_test_assignments.variant_name IS 'Name of the variant assigned (must match a variant in the experiment definition).';
COMMENT ON COLUMN socialcandor_schema.ab_test_assignments.context IS 'Additional context at assignment time (device, location, etc.).';

-- Indexes
CREATE INDEX idx_ab_test_assignments_experiment ON socialcandor_schema.ab_test_assignments(experiment_id, variant_name);
CREATE INDEX idx_ab_test_assignments_user ON socialcandor_schema.ab_test_assignments(user_id, assigned_at DESC);
CREATE INDEX idx_ab_test_assignments_time ON socialcandor_schema.ab_test_assignments(assigned_at);

-- RLS
ALTER TABLE socialcandor_schema.ab_test_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY ab_test_assignments_self_policy ON socialcandor_schema.ab_test_assignments
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY ab_test_assignments_analyst_policy ON socialcandor_schema.ab_test_assignments
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'DATA_SCIENTIST', 'PRODUCT_MANAGER')
    ));
CREATE POLICY ab_test_assignments_admin_policy ON socialcandor_schema.ab_test_assignments
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- TABLE: 8 - ab_test_results
-- Description: Stores aggregated results of A/B test experiments, typically computed after the
--              experiment ends. Includes metrics per variant and statistical significance.
-- Business Case: After an experiment completes, the results need to be summarized for decision‑making.
--                This table holds the final metrics (conversion rates, averages, etc.) for each
--                variant, along with sample sizes, confidence intervals, and p‑values. It serves
--                as the authoritative source for experiment outcomes and can be used to drive
--                automated feature rollouts. Multiple result rows per experiment may exist for
--                different metrics or time windows (e.g., 7‑day, 30‑day).
-- KPIs:
--   1. Lift – percentage improvement of treatment over control.
--   2. Confidence level – statistical significance of the result.
--   3. Power – probability of detecting a true effect.
--   4. Win rate – number of experiments where treatment outperforms control.
--   5. Decision impact – how often results lead to product changes.
-- Feature Reference: EXP05 (Experiment Results)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.ab_test_results (
    -- Primary key
    result_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    experiment_id UUID NOT NULL,

    -- Result identification
    metric_name VARCHAR(255) NOT NULL,
    variant_name VARCHAR(100) NOT NULL,

    -- Aggregated data
    sample_size INTEGER NOT NULL CHECK (sample_size > 0),
    metric_value NUMERIC NOT NULL,                       -- e.g., mean conversion rate
    metric_standard_error NUMERIC,
    confidence_interval_lower NUMERIC,
    confidence_interval_upper NUMERIC,

    -- Statistical significance
    p_value NUMERIC(10,8),
    is_winner BOOLEAN DEFAULT FALSE,                     -- Whether this variant is statistically best

    -- Result period
    window_start TIMESTAMP WITH TIME ZONE,
    window_end TIMESTAMP WITH TIME ZONE,

    -- Computation metadata
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    computed_by UUID,                                    -- User or system that ran the analysis

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_ab_test_results_experiment FOREIGN KEY (experiment_id)
        REFERENCES socialcandor_schema.ab_test_experiments(experiment_id) ON DELETE CASCADE,
    CONSTRAINT fk_ab_test_results_computed_by FOREIGN KEY (computed_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ab_test_results_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ab_test_results_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT uk_ab_test_results UNIQUE (experiment_id, metric_name, variant_name, window_start, window_end),
    CONSTRAINT chk_ab_test_confidence CHECK (
        (confidence_interval_lower IS NULL AND confidence_interval_upper IS NULL) OR
        (confidence_interval_lower <= confidence_interval_upper)
    )
);
COMMENT ON TABLE socialcandor_schema.ab_test_results IS 'Stores aggregated results of A/B test experiments, including statistical significance.';
COMMENT ON COLUMN socialcandor_schema.ab_test_results.metric_value IS 'Value of the metric for this variant (e.g., mean conversion rate).';
COMMENT ON COLUMN socialcandor_schema.ab_test_results.p_value IS 'P‑value for comparison against control (lower is more significant).';
COMMENT ON COLUMN socialcandor_schema.ab_test_results.is_winner IS 'Indicates if this variant is the statistically best performer.';

-- Indexes
CREATE INDEX idx_ab_test_results_experiment ON socialcandor_schema.ab_test_results(experiment_id, metric_name);
CREATE INDEX idx_ab_test_results_winner ON socialcandor_schema.ab_test_results(is_winner) WHERE is_winner = TRUE;

-- RLS
ALTER TABLE socialcandor_schema.ab_test_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY ab_test_results_read_policy ON socialcandor_schema.ab_test_results
    FOR SELECT USING (TRUE);
CREATE POLICY ab_test_results_write_policy ON socialcandor_schema.ab_test_results
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger for updated_at
CREATE TRIGGER trg_ab_test_results_updated_at
    BEFORE UPDATE ON socialcandor_schema.ab_test_results
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 9 - feature_flag_evaluations
-- Description: Logs every evaluation of a feature flag, including the user, context, and result.
-- Business Case: Feature flags are powerful for controlled rollouts and experimentation, but
--                understanding their real‑world usage is essential. This table captures every
--                evaluation, enabling analysis of flag effectiveness, performance impact, and
--                detection of misconfigurations. It supports debugging (e.g., why a user got a
--                particular value) and auditing (who was exposed to which flag). The data can
--                also be used to measure adoption and to gradually ramp up flags.
-- KPIs:
--   1. Evaluation volume – number of times each flag is evaluated.
--   2. Exposure count – unique users exposed to a flag.
--   3. Performance impact – latency of flag evaluation.
--   4. Flag adoption – percentage of eligible users receiving a feature.
--   5. Rollout progress – how quickly a flag reaches 100% of users.
-- Feature Reference: FLG01 (Feature Flag Analytics)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_flag_evaluations (
    -- Primary key (BIGSERIAL for high‑volume)
    evaluation_id BIGSERIAL PRIMARY KEY,

    -- References
    flag_id UUID NOT NULL,                               -- From feature_flags table
    user_id UUID,
    session_id UUID,

    -- Evaluation details
    result BOOLEAN NOT NULL,                              -- Whether the flag was ON for this user
    variant VARCHAR(100),                                 -- For multivariate flags
    evaluated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Context
    context JSONB NOT NULL DEFAULT '{}',                   -- Environment, user attributes, etc.
    latency_ms INTEGER CHECK (latency_ms >= 0),

    -- Source
    source VARCHAR(50) CHECK (source IN ('SDK', 'API', 'ADMIN')),

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT fk_feature_flag_evaluations_flag FOREIGN KEY (flag_id)
        REFERENCES socialcandor_schema.feature_flags(flag_id) ON DELETE CASCADE,
    CONSTRAINT fk_feature_flag_evaluations_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flag_evaluations_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL
) PARTITION BY RANGE (evaluated_at);

COMMENT ON TABLE socialcandor_schema.feature_flag_evaluations IS 'Logs every evaluation of a feature flag, including user, context, and result.';
COMMENT ON COLUMN socialcandor_schema.feature_flag_evaluations.result IS 'Boolean result of the flag evaluation (true = enabled).';
COMMENT ON COLUMN socialcandor_schema.feature_flag_evaluations.variant IS 'Variant returned (for multivariate flags).';
COMMENT ON COLUMN socialcandor_schema.feature_flag_evaluations.context IS 'JSON object with evaluation context (user attributes, environment, etc.).';

-- Create monthly partitions (example for next 12 months)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..11 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'feature_flag_evaluations_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.feature_flag_evaluations
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes
CREATE INDEX idx_feature_flag_evaluations_flag ON socialcandor_schema.feature_flag_evaluations(flag_id, evaluated_at DESC);
CREATE INDEX idx_feature_flag_evaluations_user ON socialcandor_schema.feature_flag_evaluations(user_id, evaluated_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_feature_flag_evaluations_time ON socialcandor_schema.feature_flag_evaluations(evaluated_at DESC);

-- RLS
ALTER TABLE socialcandor_schema.feature_flag_evaluations ENABLE ROW LEVEL SECURITY;
CREATE POLICY feature_flag_evaluations_admin_policy ON socialcandor_schema.feature_flag_evaluations
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY feature_flag_evaluations_analyst_policy ON socialcandor_schema.feature_flag_evaluations
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'PRODUCT_MANAGER')
    ));

-- =================================================================================================
-- TABLE: 10 - user_journey_mappings
-- Description: Tracks user journeys through predefined flows (e.g., onboarding, purchase funnel).
-- Business Case: Understanding how users navigate through key flows is essential for optimizing
--                conversion. This table records each journey instance, the sequence of steps,
--                and the outcome (completed, abandoned). It enables funnel analysis, time‑to‑
--                completion metrics, and identification of friction points. The step sequence
--                can be stored as a JSON array, allowing flexible journey definitions without
--                schema changes. This data powers product analytics dashboards and feeds
--                machine learning models that predict journey completion.
-- KPIs:
--   1. Journey completion rate – percentage of journeys completed.
--   2. Average journey duration – time from start to completion/abandonment.
--   3. Step‑level conversion – drop‑off rates for each step.
--   4. Journey recurrence – how often users repeat a journey.
--   5. Segment performance – completion rates by user segment.
-- Feature Reference: JNY01 (User Journeys)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.user_journey_mappings (
    -- Primary key
    journey_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human-readable identifier
    journey_number VARCHAR(50) GENERATED ALWAYS AS (
        'JNY-' || TO_CHAR(started_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.user_journey_mapping_seq')::TEXT, 6, '0')
    ) STORED,

    -- References
    user_id UUID NOT NULL,
    session_id UUID,

    -- Journey identification
    journey_name VARCHAR(255) NOT NULL,                -- e.g., 'onboarding', 'checkout'
    journey_version VARCHAR(50),                        -- version of the journey definition

    -- Timing
    started_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE,
    abandoned_at TIMESTAMP WITH TIME ZONE,

    -- Status
    status socialcandor_schema.journey_status NOT NULL DEFAULT 'IN_PROGRESS',

    -- Steps (denormalized for performance)
    steps_sequence JSONB NOT NULL,                      -- Array of step identifiers in order
    current_step_index INTEGER DEFAULT 0 CHECK (current_step_index >= 0),

    -- Metrics
    total_steps INTEGER GENERATED ALWAYS AS (jsonb_array_length(steps_sequence)) STORED,
    completed_steps INTEGER DEFAULT 0 CHECK (completed_steps >= 0),

    -- Context
    entry_point VARCHAR(255),                            -- Where the journey started
    exit_point VARCHAR(255),                              -- Where it was abandoned
    metadata JSONB DEFAULT '{}',                          -- Additional context

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_user_journey_mappings_user FOREIGN KEY (user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_user_journey_mappings_session FOREIGN KEY (session_id)
        REFERENCES socialcandor_schema.users_sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_user_journey_mappings_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_user_journey_mappings_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_journey_status_dates CHECK (
        (status = 'IN_PROGRESS' AND completed_at IS NULL AND abandoned_at IS NULL) OR
        (status = 'COMPLETED' AND completed_at IS NOT NULL AND abandoned_at IS NULL) OR
        (status = 'ABANDONED' AND abandoned_at IS NOT NULL AND completed_at IS NULL) OR
        (status = 'EXPIRED' AND abandoned_at IS NOT NULL)
    ),
    CONSTRAINT chk_journey_completed_steps CHECK (completed_steps <= total_steps)
);
COMMENT ON TABLE socialcandor_schema.user_journey_mappings IS 'Tracks user journeys through predefined flows (e.g., onboarding, purchase funnel).';
COMMENT ON COLUMN socialcandor_schema.user_journey_mappings.journey_name IS 'Name of the journey (e.g., "onboarding", "checkout").';
COMMENT ON COLUMN socialcandor_schema.user_journey_mappings.steps_sequence IS 'JSON array of step identifiers in order.';
COMMENT ON COLUMN socialcandor_schema.user_journey_mappings.current_step_index IS 'Index of the current step (0‑based).';
COMMENT ON COLUMN socialcandor_schema.user_journey_mappings.entry_point IS 'How the user entered the journey (e.g., URL, notification).';

-- Indexes
CREATE INDEX idx_user_journey_mappings_user ON socialcandor_schema.user_journey_mappings(user_id, started_at DESC);
CREATE INDEX idx_user_journey_mappings_name ON socialcandor_schema.user_journey_mappings(journey_name, status, started_at);
CREATE INDEX idx_user_journey_mappings_status ON socialcandor_schema.user_journey_mappings(status, abandoned_at) WHERE status = 'ABANDONED';
CREATE INDEX idx_user_journey_mappings_session ON socialcandor_schema.user_journey_mappings(session_id) WHERE session_id IS NOT NULL;

-- RLS
ALTER TABLE socialcandor_schema.user_journey_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_journey_mappings_self_policy ON socialcandor_schema.user_journey_mappings
    FOR SELECT USING (user_id = current_setting('app.current_user_id')::UUID);
CREATE POLICY user_journey_mappings_analyst_policy ON socialcandor_schema.user_journey_mappings
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM socialcandor_schema.users
        WHERE user_id = current_setting('app.current_user_id')::UUID
        AND role IN ('ANALYST', 'PRODUCT_MANAGER')
    ));
CREATE POLICY user_journey_mappings_admin_policy ON socialcandor_schema.user_journey_mappings
    FOR ALL USING (socialcandor_schema.is_admin());

-- Trigger for updated_at
CREATE TRIGGER trg_user_journey_mappings_updated_at
    BEFORE UPDATE ON socialcandor_schema.user_journey_mappings
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- STORED PROCEDURE: update_onboarding_progress
-- Description: Updates a user's onboarding progress for a given step, handling status transitions
--              and timestamps automatically.
-- =================================================================================================
CREATE OR REPLACE FUNCTION socialcandor_schema.update_onboarding_progress(
    p_user_id UUID,
    p_step_code VARCHAR,
    p_new_status socialcandor_schema.onboarding_step_status,
    p_metadata JSONB DEFAULT '{}'
)
RETURNS UUID AS $$
DECLARE
    v_step_id UUID;
    v_progress_id UUID;
BEGIN
    -- Validate inputs
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'user_id cannot be null';
    END IF;

    -- Get step_id
    SELECT step_id INTO v_step_id
    FROM socialcandor_schema.user_onboarding_steps
    WHERE step_code = p_step_code AND is_active = TRUE;

    IF v_step_id IS NULL THEN
        RAISE EXCEPTION 'Invalid or inactive step code: %', p_step_code;
    END IF;

    -- Insert or update progress
    INSERT INTO socialcandor_schema.user_onboarding_progress (
        user_id, step_id, status, started_at, completed_at, metadata, created_by
    ) VALUES (
        p_user_id,
        v_step_id,
        p_new_status,
        CASE WHEN p_new_status IN ('IN_PROGRESS', 'COMPLETED', 'SKIPPED') THEN CURRENT_TIMESTAMP ELSE NULL END,
        CASE WHEN p_new_status IN ('COMPLETED', 'SKIPPED') THEN CURRENT_TIMESTAMP ELSE NULL END,
        p_metadata,
        p_user_id   -- assuming user is the creator for self‑actions
    )
    ON CONFLICT (user_id, step_id) DO UPDATE SET
        status = p_new_status,
        started_at = CASE
            WHEN p_new_status IN ('IN_PROGRESS', 'COMPLETED', 'SKIPPED') AND EXCLUDED.started_at IS NULL
                THEN CURRENT_TIMESTAMP
            ELSE user_onboarding_progress.started_at
        END,
        completed_at = CASE
            WHEN p_new_status IN ('COMPLETED', 'SKIPPED') THEN CURRENT_TIMESTAMP
            ELSE NULL
        END,
        metadata = user_onboarding_progress.metadata || p_metadata,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = p_user_id
    RETURNING progress_id INTO v_progress_id;

    RETURN v_progress_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION socialcandor_schema.update_onboarding_progress IS 'Updates a user''s onboarding progress for a given step, handling timestamps automatically.';


-- ============================================
-- CRITICAL: Composite indexes for common queries
-- ============================================

-- User feed queries (most frequent)
CREATE INDEX CONCURRENTLY idx_posts_feed_optimized
ON socialcandor_schema.posts(user_id, created_at DESC, visibility)
WHERE is_deleted = FALSE AND moderation_status = 'APPROVED';

-- Notification queries (high volume)
CREATE INDEX CONCURRENTLY idx_notifications_unread_priority
ON socialcandor_schema.notifications(user_id, priority, created_at DESC)
WHERE read_at IS NULL;

-- Conversation message retrieval
CREATE INDEX CONCURRENTLY idx_messages_conversation_time
ON socialcandor_schema.conversations_messages(conversation_id, created_at DESC)
INCLUDE (message_id, sender_user_id, content_text, message_type);

-- User session validation
CREATE INDEX CONCURRENTLY idx_sessions_active_token
ON socialcandor_schema.users_sessions(session_token, expires_at)
WHERE is_active = TRUE;

-- Wallet transaction history
CREATE INDEX CONCURRENTLY idx_wallet_tx_user_date
ON socialcandor_schema.wallet_transactions(user_id, created_at DESC)
INCLUDE (transaction_type, amount, status);

-- ============================================
-- PARTIAL INDEXES (for filtered queries)
-- ============================================

-- Active users only (60% smaller index)
CREATE INDEX CONCURRENTLY idx_users_active_country
ON socialcandor_schema.users(registration_country)
WHERE status = 'ACTIVE';

-- Pending moderation (critical for moderators)
CREATE INDEX CONCURRENTLY idx_posts_moderation_queue
ON socialcandor_schema.posts(created_at, moderation_status)
WHERE moderation_status IN ('PENDING', 'FLAGGED');

-- Failed login attempts (security monitoring)
CREATE INDEX CONCURRENTLY idx_users_failed_logins
ON socialcandor_schema.users(failed_login_attempts, account_locked_until)
WHERE failed_login_attempts > 0;

-- Expired tokens (cleanup jobs)
CREATE INDEX CONCURRENTLY idx_tokens_expired
ON socialcandor_schema.user_tokens(expires_at)
WHERE used_at IS NULL AND expires_at < CURRENT_TIMESTAMP;

-- ============================================
-- COVERING INDEXES (avoid table lookups)
-- ============================================

-- User profile queries (no table heap access)
CREATE INDEX CONCURRENTLY idx_users_profile_covering
ON socialcandor_schema.users(user_id)
INCLUDE (username, display_name, avatar_url, verification_level, trust_score);

-- Post engagement metrics
CREATE INDEX CONCURRENTLY idx_posts_engagement_covering
ON socialcandor_schema.posts(post_id, created_at DESC)
INCLUDE (like_count, comment_count, share_count, view_count, trending_score);

-- Wallet balance queries
CREATE INDEX CONCURRENTLY idx_wallets_balance_covering
ON socialcandor_schema.user_wallets(user_id)
INCLUDE (available_balance, pending_balance, currency_code, status);


-- ============================================
-- 1. Enable table partitioning for high-write tables
-- ============================================

-- Analytics events (partition by day)
CREATE TABLE socialcandor_schema.analytics_event_streams_2025_01
PARTITION OF socialcandor_schema.analytics_event_streams
FOR VALUES FROM ('2025-01-01') TO ('2025-02-01');

-- API error logs (partition by day)
CREATE TABLE socialcandor_schema.api_error_logs_2025_01
PARTITION OF socialcandor_schema.api_error_logs
FOR VALUES FROM ('2025-01-01') TO ('2025-02-01');

-- ============================================
-- 2. Use UNLOGGED tables for temporary data
-- ============================================

CREATE UNLOGGED TABLE socialcandor_schema.session_cache (
    session_id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    data JSONB,
    expires_at TIMESTAMP WITH TIME ZONE
);

-- ============================================
-- 3. Implement write queuing for bulk operations
-- ============================================

CREATE TABLE socialcandor_schema.write_queue (
    queue_id BIGSERIAL PRIMARY KEY,
    table_name VARCHAR(100) NOT NULL,
    operation VARCHAR(20) NOT NULL,
    payload JSONB NOT NULL,
    priority INTEGER DEFAULT 5,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(20) DEFAULT 'PENDING'
);



-- =================================================================================================
-- ENUMS
-- =================================================================================================

-- Enum: 1 - migration_status
-- Description: Status of database schema migrations
-- Business Case: Track the state of each migration script to ensure idempotent deployments and rollback capability.
-- Feature Reference: SYS09 (Schema Versioning)
-- =================================================================================================
CREATE TYPE socialcandor_schema.migration_status AS ENUM (
    'PENDING',      -- Migration created but not yet applied
    'APPLIED',      -- Successfully applied
    'FAILED',       -- Failed during application
    'ROLLED_BACK'   -- Rolled back after application
);
COMMENT ON TYPE socialcandor_schema.migration_status IS 'Status of database schema migrations';

-- Enum: 2 - rate_limit_type
-- Description: Types of rate limiting (time windows)
-- Business Case: Define different rate‑limit granularities for API protection
-- Feature Reference: API13 (Rate Limiting)
-- =================================================================================================
CREATE TYPE socialcandor_schema.rate_limit_type AS ENUM (
    'REQUESTS_PER_SECOND',
    'REQUESTS_PER_MINUTE',
    'REQUESTS_PER_HOUR',
    'REQUESTS_PER_DAY'
);
COMMENT ON TYPE socialcandor_schema.rate_limit_type IS 'Time‑window types for rate limiting';

-- Enum: 3 - rate_limit_scope
-- Description: Scope of rate limiting (who the limit applies to)
-- Business Case: Differentiate limits by user, IP, client, or globally
-- Feature Reference: API13
-- =================================================================================================
CREATE TYPE socialcandor_schema.rate_limit_scope AS ENUM (
    'GLOBAL',      -- Applies to all requests
    'USER',        -- Per authenticated user
    'IP',          -- Per IP address
    'API_KEY',     -- Per API key/client
    'ENDPOINT'     -- Per endpoint (regardless of caller)
);
COMMENT ON TYPE socialcandor_schema.rate_limit_scope IS 'Scope of rate limiting';

-- Enum: 4 - circuit_state
-- Description: States of a circuit breaker for service health
-- Business Case: Implement the circuit‑breaker pattern to prevent cascading failures
-- Feature Reference: SYS10 (Resilience Engineering)
-- =================================================================================================
CREATE TYPE socialcandor_schema.circuit_state AS ENUM (
    'CLOSED',       -- Normal operation, requests allowed
    'OPEN',         -- Failing, requests blocked
    'HALF_OPEN'     -- Testing if service recovered
);
COMMENT ON TYPE socialcandor_schema.circuit_state IS 'Circuit‑breaker states for service health';

-- Enum: 5 - health_status
-- Description: Health status of a service or component
-- Business Case: Real‑time monitoring and alerting
-- Feature Reference: SYS11 (Health Monitoring)
-- =================================================================================================
CREATE TYPE socialcandor_schema.health_status AS ENUM (
    'HEALTHY',      -- Operating normally
    'DEGRADED',     -- Operating with reduced capacity
    'UNHEALTHY',    -- Not functioning
    'OFFLINE'       -- Intentionally stopped
);
COMMENT ON TYPE socialcandor_schema.health_status IS 'Health status for service monitoring';

-- Enum: 6 - verification_status
-- Description: Outcome of a backup verification check
-- Business Case: Ensure backups are restorable and intact
-- Feature Reference: BCP04 (Backup Verification)
-- =================================================================================================
CREATE TYPE socialcandor_schema.verification_status AS ENUM (
    'PASSED',       -- Verification successful
    'FAILED',       -- Verification failed
    'WARNING',      -- Passed with warnings (e.g., partial checksum match)
    'SKIPPED'       -- Verification not performed
);
COMMENT ON TYPE socialcandor_schema.verification_status IS 'Outcome of backup verification checks';

-- Enum: 7 - postmortem_status
-- Description: Status of an incident postmortem document
-- Business Case: Manage the lifecycle of post‑incident analysis
-- Feature Reference: INC04 (Post‑Incident Review)
-- =================================================================================================
CREATE TYPE socialcandor_schema.postmortem_status AS ENUM (
    'DRAFT',        -- Being written
    'PUBLISHED',    -- Finalised and shared
    'ARCHIVED'      -- Older than retention period
);
COMMENT ON TYPE socialcandor_schema.postmortem_status IS 'Status of incident postmortem documents';

-- =================================================================================================
-- SEQUENCES (for human‑readable identifiers)
-- =================================================================================================
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.database_schema_versions_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.audit_log_archive_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.backup_verification_logs_seq START 1000;
CREATE SEQUENCE IF NOT EXISTS socialcandor_schema.incident_postmortems_seq START 1000;

-- =================================================================================================
-- TABLE: 1 - database_schema_versions
-- Description: Tracks every database migration script applied to the schema, including version,
--              description, checksum, and execution status. Enables idempotent deployments and rollbacks.
-- Business Case: As the platform evolves, multiple teams may deploy schema changes concurrently.
--                This table provides a single source of truth for which migrations have been applied,
--                in what order, and whether they succeeded. It prevents duplicate application and
--                supports automated rollback in case of failure. Compliance auditors can verify that
--                the schema matches the expected version. The table also stores the script content
--                (or a checksum) to detect unauthorised modifications. With created_by and timestamps,
--                we maintain an audit trail of who deployed what and when.
-- KPIs:
--   1. Deployment success rate – percentage of migrations applied without failure
--   2. Mean time to deploy – average time to apply a migration
--   3. Number of rollbacks – frequency of failed migrations that required rollback
--   4. Schema drift – number of unexpected changes detected by checksum mismatch
--   5. Deployment frequency – number of migrations per week
-- Feature References: SYS09 (Schema Versioning), DEP01 (Deployment Automation), AUD20 (Change Audit)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.database_schema_versions (
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    version_number VARCHAR(50) GENERATED ALWAYS AS (
        'VER-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.database_schema_versions_seq')::TEXT, 6, '0')
    ) STORED,

    -- Migration metadata
    version VARCHAR(50) NOT NULL,                    -- e.g., '2025.04.01.001'
    description TEXT NOT NULL,
    script_name VARCHAR(255) NOT NULL,
    script_checksum VARCHAR(64) NOT NULL,            -- SHA‑256 for integrity
    script_content TEXT,                              -- Optional: store the actual migration script

    -- Execution
    applied_by UUID NOT NULL,
    applied_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    execution_time_ms INTEGER CHECK (execution_time_ms >= 0),
    status socialcandor_schema.migration_status NOT NULL DEFAULT 'PENDING',

    -- Failure details
    error_message TEXT,
    rollback_script_name VARCHAR(255),
    rollback_applied_at TIMESTAMP WITH TIME ZONE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_schema_versions_applied_by FOREIGN KEY (applied_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_schema_versions_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_schema_versions_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_schema_versions_version UNIQUE (version)
);
COMMENT ON TABLE socialcandor_schema.database_schema_versions IS 'Tracks all database schema migrations with checksums and execution status';
COMMENT ON COLUMN socialcandor_schema.database_schema_versions.version IS 'Semantic version of the migration (e.g., YYYY.MM.DD.seq)';
COMMENT ON COLUMN socialcandor_schema.database_schema_versions.script_checksum IS 'SHA‑256 hash of the migration script for integrity';

CREATE INDEX idx_schema_versions_version ON socialcandor_schema.database_schema_versions(version);
CREATE INDEX idx_schema_versions_status ON socialcandor_schema.database_schema_versions(status, applied_at DESC);
CREATE INDEX idx_schema_versions_applied_by ON socialcandor_schema.database_schema_versions(applied_by) WHERE applied_by IS NOT NULL;

ALTER TABLE socialcandor_schema.database_schema_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY schema_versions_admin_policy ON socialcandor_schema.database_schema_versions
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_database_schema_versions_updated_at
    BEFORE UPDATE ON socialcandor_schema.database_schema_versions
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 2 - feature_flag_configs
-- Description: Runtime configuration for feature toggles, allowing gradual rollouts, percentage‑based
--              releases, and targeting specific user segments or environments.
-- Business Case: Feature flags enable safe, continuous delivery by decoupling deployment from release.
--                This table stores the definition of each flag: its key, description, default state,
--                rollout percentage, and optional targeting rules (e.g., user segment, environment).
--                The platform’s feature flag service queries this table at runtime to determine whether
--                a given feature should be active for a specific user. The design supports A/B testing
--                and canary releases without code changes. Audit columns track who changed the flag
--                and when, which is critical for debugging and compliance.
-- KPIs:
--   1. Flag usage – number of flags evaluated per second
--   2. Rollout success – percentage of flags promoted to 100% after canary
--   3. Time to enable – average time from flag creation to full rollout
--   4. Configuration drift – number of unexpected flag changes
--   5. Environment parity – difference in flag states between environments
-- Feature References: EXP03 (Feature Toggles), SYS12 (Configuration Management), DEP02 (Continuous Delivery)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.feature_flag_configs (
    flag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    flag_number VARCHAR(50) GENERATED ALWAYS AS (
        'FLAG-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Flag identification
    flag_key VARCHAR(100) UNIQUE NOT NULL,
    flag_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Basic state
    enabled BOOLEAN DEFAULT FALSE,
    rollout_percentage INTEGER CHECK (rollout_percentage >= 0 AND rollout_percentage <= 100),

    -- Targeting (using existing user_segments table)
    target_segment_id UUID,                     -- If NULL, apply to all
    target_environments TEXT[],                   -- e.g., ['production', 'staging']

    -- Overrides (user/org specific)
    enabled_for_user_ids UUID[],
    disabled_for_user_ids UUID[],
    enabled_for_org_ids UUID[],                   -- if organizations table exists

    -- Expiration / sunset
    expires_at TIMESTAMP WITH TIME ZONE,
    sunset_version VARCHAR(50),                   -- version after which flag is removed

    -- Owner
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    is_deprecated BOOLEAN DEFAULT FALSE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_feature_flag_configs_segment FOREIGN KEY (target_segment_id)
        REFERENCES socialcandor_schema.user_segments(segment_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flag_configs_owner_user FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flag_configs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_feature_flag_configs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,

    CONSTRAINT chk_feature_flag_configs_rollout CHECK (rollout_percentage >= 0 AND rollout_percentage <= 100)
);
COMMENT ON TABLE socialcandor_schema.feature_flag_configs IS 'Runtime configuration for feature toggles with targeting and gradual rollout';
COMMENT ON COLUMN socialcandor_schema.feature_flag_configs.flag_key IS 'Unique key used in code to check the flag';
COMMENT ON COLUMN socialcandor_schema.feature_flag_configs.rollout_percentage IS 'Percentage of users who see the feature when enabled';
COMMENT ON COLUMN socialcandor_schema.feature_flag_configs.sunset_version IS 'Version after which this flag can be safely removed';

CREATE INDEX idx_feature_flag_configs_key ON socialcandor_schema.feature_flag_configs(flag_key);
CREATE INDEX idx_feature_flag_configs_active ON socialcandor_schema.feature_flag_configs(is_active, expires_at) WHERE is_active = TRUE;
CREATE INDEX idx_feature_flag_configs_segment ON socialcandor_schema.feature_flag_configs(target_segment_id) WHERE target_segment_id IS NOT NULL;

ALTER TABLE socialcandor_schema.feature_flag_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY feature_flag_configs_admin_policy ON socialcandor_schema.feature_flag_configs
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_feature_flag_configs_updated_at
    BEFORE UPDATE ON socialcandor_schema.feature_flag_configs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 3 - rate_limit_configs
-- Description: Defines rate‑limiting rules for API endpoints, including limits per time window,
--              scope (user, IP, global), and HTTP methods. Enables fine‑grained traffic control.
-- Business Case: Rate limiting is essential to protect the platform from abuse, ensure fair usage,
--                and maintain service stability. This table allows dynamic configuration of limits
--                without code changes. Each rule specifies an endpoint pattern (e.g., '/api/v1/posts/*'),
--                the HTTP method (or ALL), the type of limit (requests per second/minute/hour/day),
--                the numeric limit, and the scope (per user, per IP, globally). The design supports
--                overriding limits for specific users or API keys through optional scope_id fields.
--                The is_active flag enables temporary suspension of a rule. Audit columns track changes
--                for security and compliance.
-- KPIs:
--   1. Rate limit violations – number of requests blocked per day
--   2. Top blocked endpoints – endpoints with most violations
--   3. Limit effectiveness – reduction in abusive traffic
--   4. Configuration coverage – percentage of endpoints with defined limits
--   5. Rule change frequency – number of updates to rate limits per month
-- Feature References: API13 (Rate Limiting), SEC49 (Traffic Shaping), OPS08 (Load Management)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.rate_limit_configs (
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    rule_number VARCHAR(50) GENERATED ALWAYS AS (
        'RL-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Rule identification
    rule_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Endpoint specification
    endpoint_pattern VARCHAR(500) NOT NULL,      -- e.g., '/api/v1/posts/*'
    http_method VARCHAR(10) CHECK (http_method IN ('GET','POST','PUT','DELETE','PATCH','HEAD','OPTIONS','ALL')),

    -- Limit definition
    limit_type socialcandor_schema.rate_limit_type NOT NULL,
    limit_value INTEGER NOT NULL CHECK (limit_value > 0),

    -- Scope
    scope socialcandor_schema.rate_limit_scope NOT NULL,
    scope_id UUID,                               -- For USER, IP, API_KEY; NULL for GLOBAL or ENDPOINT

    -- Optional overrides for specific users/clients
    applies_to_all BOOLEAN DEFAULT TRUE,         -- If FALSE, only applies to the specified scope_id

    -- Time window (for burst control)
    burst_multiplier NUMERIC(5,2) DEFAULT 1.0 CHECK (burst_multiplier >= 1.0),

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    priority INTEGER DEFAULT 0 CHECK (priority >= 0),   -- Higher priority rules evaluated first

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_rate_limit_configs_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_rate_limit_configs_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.rate_limit_configs IS 'Defines dynamic rate‑limiting rules for API endpoints with configurable scope and limits';
COMMENT ON COLUMN socialcandor_schema.rate_limit_configs.endpoint_pattern IS 'URL pattern supporting wildcards (e.g., /api/*)';
COMMENT ON COLUMN socialcandor_schema.rate_limit_configs.scope_id IS 'Identifier for the scope (user_id, ip_address, api_key_id) when scope is not GLOBAL/ENDPOINT';
COMMENT ON COLUMN socialcandor_schema.rate_limit_configs.burst_multiplier IS 'Allows temporary bursts above the limit (e.g., 2x for 10 seconds)';

CREATE INDEX idx_rate_limit_configs_endpoint ON socialcandor_schema.rate_limit_configs(endpoint_pattern, http_method) WHERE is_active = TRUE;
CREATE INDEX idx_rate_limit_configs_scope ON socialcandor_schema.rate_limit_configs(scope, scope_id) WHERE is_active = TRUE AND scope_id IS NOT NULL;
CREATE INDEX idx_rate_limit_configs_priority ON socialcandor_schema.rate_limit_configs(priority DESC) WHERE is_active = TRUE;

ALTER TABLE socialcandor_schema.rate_limit_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY rate_limit_configs_admin_policy ON socialcandor_schema.rate_limit_configs
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_rate_limit_configs_updated_at
    BEFORE UPDATE ON socialcandor_schema.rate_limit_configs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 4 - circuit_breaker_states
-- Description: Tracks the current state of circuit breakers for external services or internal components,
--              including failure counts, last failure time, and automatic transition logic.
-- Business Case: The circuit‑breaker pattern prevents repeated calls to failing services, allowing
--                them time to recover. This table stores the state per service/endpoint, along with
--                metrics needed for state transitions (failure count, last failure, timeout duration).
--                A background process or the application itself updates the state based on success/failure.
--                The design supports manual override (e.g., forced open). By persisting state, we can
--                share circuit‑breaker information across multiple instances of a service.
-- KPIs:
--   1. Circuit open events – number of times a circuit opened
--   2. Mean time to recover – average time a circuit stays open
--   3. Failure rate before opening – failure threshold that triggered open
--   4. Manual interventions – number of times an admin overrode the state
--   5. Service availability – percentage of time circuits are closed
-- Feature References: SYS10 (Resilience Engineering), OBS09 (Fault Tolerance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.circuit_breaker_states (
    breaker_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    breaker_number VARCHAR(50) GENERATED ALWAYS AS (
        'CB-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Service identification
    service_name VARCHAR(255) NOT NULL,
    service_endpoint VARCHAR(500),                -- optional, for finer granularity

    -- Circuit state
    state socialcandor_schema.circuit_state NOT NULL DEFAULT 'CLOSED',
    failure_count INTEGER DEFAULT 0 CHECK (failure_count >= 0),
    failure_threshold INTEGER DEFAULT 5 CHECK (failure_threshold >= 1),

    -- Timeouts
    timeout_seconds INTEGER DEFAULT 60 CHECK (timeout_seconds >= 0),           -- time before transitioning from OPEN to HALF_OPEN
    last_failure_time TIMESTAMP WITH TIME ZONE,
    last_success_time TIMESTAMP WITH TIME ZONE,
    opened_at TIMESTAMP WITH TIME ZONE,               -- when circuit opened
    half_open_at TIMESTAMP WITH TIME ZONE,            -- when it entered HALF_OPEN

    -- Manual override
    forced_state socialcandor_schema.circuit_state,   -- manually forced state (NULL = no override)
    forced_by UUID,
    forced_at TIMESTAMP WITH TIME ZONE,
    force_reason TEXT,

    -- Statistics
    total_failures BIGINT DEFAULT 0,
    total_successes BIGINT DEFAULT 0,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_circuit_breaker_forced_by FOREIGN KEY (forced_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_circuit_breaker_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_circuit_breaker_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_circuit_breaker_service UNIQUE (service_name, service_endpoint)
);
COMMENT ON TABLE socialcandor_schema.circuit_breaker_states IS 'Persistent state of circuit breakers for external services, enabling fault tolerance';
COMMENT ON COLUMN socialcandor_schema.circuit_breaker_states.state IS 'Current circuit state: CLOSED (normal), OPEN (failing), HALF_OPEN (testing recovery)';
COMMENT ON COLUMN socialcandor_schema.circuit_breaker_states.forced_state IS 'Manually overridden state (NULL if no override)';
COMMENT ON COLUMN socialcandor_schema.circuit_breaker_states.failure_threshold IS 'Number of consecutive failures before opening';

CREATE INDEX idx_circuit_breaker_service ON socialcandor_schema.circuit_breaker_states(service_name, service_endpoint);
CREATE INDEX idx_circuit_breaker_state ON socialcandor_schema.circuit_breaker_states(state, last_failure_time) WHERE state != 'CLOSED';

ALTER TABLE socialcandor_schema.circuit_breaker_states ENABLE ROW LEVEL SECURITY;
CREATE POLICY circuit_breaker_states_admin_policy ON socialcandor_schema.circuit_breaker_states
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_circuit_breaker_states_updated_at
    BEFORE UPDATE ON socialcandor_schema.circuit_breaker_states
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 5 - audit_log_archive
-- Description: Long‑term storage of audit log entries, moved from the main audit_logs table
--              according to retention policies. Preserves history for compliance and investigations.
-- Business Case: Regulatory frameworks (SOC2, GDPR, HIPAA) often require audit logs to be retained
--                for several years. However, keeping all logs in the main (partitioned) table can
--                become expensive and degrade performance. This archive table stores logs that have
--                exceeded the hot retention period but must still be accessible. The structure mirrors
--                the source audit_logs table, with additional archive metadata (archived_at, archive_reason).
--                The table is likely to be append‑only and can be stored on cheaper storage (e.g., slower disks).
--                Partitioning by month or year is still recommended for query efficiency.
-- KPIs:
--   1. Archive size – total storage occupied by archived logs
--   2. Retrieval frequency – number of archive queries per month
--   3. Archive lag – time between log creation and archival
--   4. Retention compliance – percentage of logs retained according to policy
--   5. Cost savings – storage cost difference vs. hot storage
-- Feature References: AUD21 (Audit Archiving), COMP29 (Long‑term Retention)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.audit_log_archive (
    archive_id BIGSERIAL,

    -- Human‑readable identifier
    archive_number VARCHAR(50) GENERATED ALWAYS AS (
        'ARCH-' || TO_CHAR(archived_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.audit_log_archive_seq')::TEXT, 6, '0')
    ) STORED,

    -- Original audit log fields (mirroring audit_logs)
    actor_user_id UUID,
    action VARCHAR(100) NOT NULL,
    target_type VARCHAR(50),
    target_id UUID,
    before_state JSONB,
    after_state JSONB,
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Additional context from original log
    ip_address INET,
    user_agent TEXT,
    session_id UUID,
    request_id UUID,
    metadata JSONB DEFAULT '{}',

    -- Archive metadata
    archived_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    archive_reason VARCHAR(100) CHECK (archive_reason IN ('RETENTION_POLICY', 'MANUAL', 'SYSTEM')),
    retention_period_days INTEGER,
    purge_at TIMESTAMP WITH TIME ZONE,                     -- when this archive entry can be permanently deleted

    -- Partition key (archived_at date for partitioning)
    archive_date DATE GENERATED ALWAYS AS (archived_at::DATE) STORED,

    CONSTRAINT pk_audit_log_archive PRIMARY KEY (archive_id, archive_date)
) PARTITION BY RANGE (archive_date);

COMMENT ON TABLE socialcandor_schema.audit_log_archive IS 'Long‑term archive of audit logs, moved from main table for compliance and cost efficiency';
COMMENT ON COLUMN socialcandor_schema.audit_log_archive.occurred_at IS 'Original timestamp of the audited event';
COMMENT ON COLUMN socialcandor_schema.audit_log_archive.purge_at IS 'Date after which this archive entry may be permanently deleted';

-- Create initial partitions (example for current month and next)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..2 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'audit_log_archive_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.audit_log_archive
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes on the parent (will be inherited)
CREATE INDEX idx_audit_log_archive_actor ON socialcandor_schema.audit_log_archive(actor_user_id, occurred_at DESC) WHERE actor_user_id IS NOT NULL;
CREATE INDEX idx_audit_log_archive_target ON socialcandor_schema.audit_log_archive(target_type, target_id, occurred_at DESC);
CREATE INDEX idx_audit_log_archive_occurred ON socialcandor_schema.audit_log_archive(occurred_at DESC);
CREATE INDEX idx_audit_log_archive_purge ON socialcandor_schema.audit_log_archive(purge_at) WHERE purge_at IS NOT NULL;

ALTER TABLE socialcandor_schema.audit_log_archive ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_log_archive_admin_policy ON socialcandor_schema.audit_log_archive
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- TABLE: 6 - data_retention_policies
-- Description: Defines rules for automated data cleanup: how long different categories of data
--              should be retained, and what action to take upon expiry (delete, anonymise, archive).
-- Business Case: GDPR, CCPA, and other privacy regulations mandate that personal data not be kept
--                longer than necessary. This table allows the platform to define retention periods
--                per data category (e.g., user logs, session data, payment info) and per jurisdiction.
--                A scheduled job reads these policies and applies the configured action. The design
--                supports exceptions (e.g., legal hold) via a separate table. By centralising policies,
--                we ensure consistent enforcement across all services. Audit columns track who created
--                or modified each policy, which is critical for compliance evidence.
-- KPIs:
--   1. Policy coverage – percentage of data assets covered by a retention policy
--   2. Deletion compliance – percentage of expired data correctly deleted
--   3. Exception rate – number of legal holds or overrides applied
--   4. Storage reduction – amount of data deleted by automated policies
--   5. Policy review frequency – time since last policy update
-- Feature References: GDPR05 (Data Retention), RET01 (Retention Policies), COMP30 (Data Minimisation)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_retention_policies (
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    policy_number VARCHAR(50) GENERATED ALWAYS AS (
        'RET-' || TO_CHAR(effective_date, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Policy identification
    policy_name VARCHAR(255) NOT NULL,
    policy_description TEXT,
    policy_version VARCHAR(20) DEFAULT '1.0',

    -- Scope (what data this applies to)
    scope_type VARCHAR(30) NOT NULL CHECK (scope_type IN ('GLOBAL', 'DATA_CATEGORY', 'TABLE', 'COLUMN', 'JURISDICTION', 'PROCESS')),
    scope_value VARCHAR(500) NOT NULL,            -- e.g., 'USER_ACTIVITY_LOGS', 'users', 'email', 'EU', 'PAYMENT_PROCESSING'

    -- Retention rule
    retention_period_days INTEGER NOT NULL CHECK (retention_period_days >= 0),
    retention_unit VARCHAR(20) DEFAULT 'DAYS' CHECK (retention_unit IN ('DAYS', 'MONTHS', 'YEARS')),
    retention_basis VARCHAR(100) CHECK (retention_basis IN ('LEGAL', 'CONTRACTUAL', 'OPERATIONAL', 'USER_PREFERENCE')),

    -- Action upon expiry
    action_on_expiry VARCHAR(30) NOT NULL CHECK (action_on_expiry IN ('DELETE', 'ANONYMIZE', 'ARCHIVE', 'REVIEW', 'NOTIFY')),
    archive_location VARCHAR(500),                  -- e.g., S3 bucket, cold storage path

    -- Legal basis (e.g., GDPR Article)
    legal_reference TEXT,
    regulatory_frameworks TEXT[],

    -- Exceptions (reference to exception table)
    allow_exceptions BOOLEAN DEFAULT TRUE,

    -- Effective dating
    effective_date DATE NOT NULL DEFAULT CURRENT_DATE,
    expiry_date DATE,                               -- when policy itself expires
    is_active BOOLEAN GENERATED ALWAYS AS (expiry_date IS NULL OR expiry_date >= CURRENT_DATE) STORED,

    -- Ownership
    owner_team VARCHAR(100),
    owner_user_id UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_data_retention_policies_owner FOREIGN KEY (owner_user_id)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_data_retention_policies_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_data_retention_policies_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_retention_policy_scope UNIQUE (scope_type, scope_value, effective_date)
);
COMMENT ON TABLE socialcandor_schema.data_retention_policies IS 'Defines how long different data categories are kept and what action to take after expiry';
COMMENT ON COLUMN socialcandor_schema.data_retention_policies.retention_basis IS 'Legal or operational reason for the retention period';
COMMENT ON COLUMN socialcandor_schema.data_retention_policies.action_on_expiry IS 'What to do with data when retention period expires';

CREATE INDEX idx_retention_policies_active ON socialcandor_schema.data_retention_policies(is_active) WHERE is_active = TRUE;
CREATE INDEX idx_retention_policies_scope ON socialcandor_schema.data_retention_policies(scope_type, scope_value) WHERE is_active = TRUE;
CREATE INDEX idx_retention_policies_expiry ON socialcandor_schema.data_retention_policies(expiry_date) WHERE expiry_date IS NOT NULL;

ALTER TABLE socialcandor_schema.data_retention_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY data_retention_policies_admin_policy ON socialcandor_schema.data_retention_policies
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_data_retention_policies_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_retention_policies
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 7 - backup_verification_logs
-- Description: Logs the results of backup integrity checks, ensuring that backups are restorable
--              and have not been corrupted. Tracks verification attempts, status, and details.
-- Business Case: Relying on backups without verifying them is a common cause of data loss. This table
--                records every verification run: which backup was tested, when, what method was used
--                (checksum, restore test), and the outcome. It also captures any discrepancies (size,
--                checksum mismatch) or errors. This data supports SLA reporting (backup recoverability)
--                and helps detect problems early. Automated verification jobs can insert records here,
--                and alerts can be triggered on failures. The table references the original backup log
--                (`backup_logs`) to correlate with backup metadata.
-- KPIs:
--   1. Verification coverage – percentage of backups that have been verified
--   2. Verification success rate – percentage of checks that passed
--   3. Mean time to detect corruption – time from backup creation to failure detection
--   4. Recovery confidence – number of verified restorable backups
--   5. Verification latency – time between backup completion and verification
-- Feature References: BCP04 (Backup Verification), OPS10 (Data Integrity), AUD22 (Backup Audit)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.backup_verification_logs (
    verification_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    verification_number VARCHAR(50) GENERATED ALWAYS AS (
        'VERIFY-' || TO_CHAR(verification_time, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.backup_verification_logs_seq')::TEXT, 6, '0')
    ) STORED,

    -- Backup reference
    backup_id UUID NOT NULL,                       -- References backup_logs

    -- Verification metadata
    verification_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    verified_by UUID,                               -- user or system that performed verification
    method VARCHAR(50) CHECK (method IN ('CHECKSUM', 'RESTORE_TEST', 'SAMPLE_RESTORE', 'FULL_RESTORE')),

    -- Results
    status socialcandor_schema.verification_status NOT NULL,
    checksum_match BOOLEAN,
    size_match BOOLEAN,
    restore_duration_seconds INTEGER CHECK (restore_duration_seconds >= 0),
    restored_rows INTEGER CHECK (restored_rows >= 0),

    -- Discrepancies
    expected_checksum VARCHAR(64),
    actual_checksum VARCHAR(64),
    expected_size_bytes BIGINT,
    actual_size_bytes BIGINT,
    error_message TEXT,
    details JSONB,                                   -- additional context

    -- Completion
    completed_at TIMESTAMP WITH TIME ZONE,
    next_verification_due DATE,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_backup_verification_backup FOREIGN KEY (backup_id)
        REFERENCES socialcandor_schema.backup_logs(log_id) ON DELETE CASCADE,
    CONSTRAINT fk_backup_verification_verified_by FOREIGN KEY (verified_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_backup_verification_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_backup_verification_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.backup_verification_logs IS 'Logs results of backup integrity checks, ensuring backups are restorable';
COMMENT ON COLUMN socialcandor_schema.backup_verification_logs.method IS 'Verification method used';
COMMENT ON COLUMN socialcandor_schema.backup_verification_logs.status IS 'Outcome of verification (PASSED, FAILED, WARNING, SKIPPED)';

CREATE INDEX idx_backup_verification_backup ON socialcandor_schema.backup_verification_logs(backup_id, verification_time DESC);
CREATE INDEX idx_backup_verification_status ON socialcandor_schema.backup_verification_logs(status, verification_time) WHERE status != 'PASSED';
CREATE INDEX idx_backup_verification_next ON socialcandor_schema.backup_verification_logs(next_verification_due) WHERE next_verification_due IS NOT NULL;

ALTER TABLE socialcandor_schema.backup_verification_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY backup_verification_logs_admin_policy ON socialcandor_schema.backup_verification_logs
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_backup_verification_logs_updated_at
    BEFORE UPDATE ON socialcandor_schema.backup_verification_logs
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 8 - disaster_recovery_plans
-- Description: Stores documented disaster recovery procedures, including RTO/RPO targets,
--              step‑by‑step recovery instructions, and test results. Supports business continuity.
-- Business Case: Disaster recovery planning is essential for regulatory compliance (SOC2, ISO27001)
--                and operational resilience. This table holds the authoritative version of each DR plan,
--                with versioning and approval tracking. Each plan covers a specific scenario (e.g.,
--                region failure, database corruption) and includes RTO (Recovery Time Objective) and
--                RPO (Recovery Point Objective) in minutes. The `steps` JSON field contains structured
--                recovery steps. Test results (date, outcome) are recorded to demonstrate effectiveness.
--                Plans have owners and must be reviewed periodically; the `next_review_date` field
--                triggers alerts when review is due.
-- KPIs:
--   1. Plan coverage – number of critical scenarios with documented plans
--   2. RTO attainment – percentage of drills meeting RTO
--   3. RPO attainment – percentage of drills meeting RPO
--   4. Plan freshness – number of plans reviewed within the last year
--   5. Test success rate – percentage of drills where plan worked as expected
-- Feature References: BCP05 (Disaster Recovery), BCP06 (DR Testing), COMP31 (Business Continuity)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.disaster_recovery_plans (
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    plan_number VARCHAR(50) GENERATED ALWAYS AS (
        'DRP-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::INT::TEXT, 6, '0')
    ) STORED,

    -- Plan identification
    plan_name VARCHAR(255) NOT NULL,
    plan_version VARCHAR(20) NOT NULL DEFAULT '1.0',
    description TEXT,
    scenario VARCHAR(100) CHECK (scenario IN (
        'REGION_FAILURE', 'DATABASE_CORRUPTION', 'POD_FAILURE', 'DATA_BREACH', 'RANSOMWARE', 'NETWORK_OUTAGE', 'OTHER'
    )),

    -- Objectives (in minutes)
    rto_minutes INTEGER NOT NULL CHECK (rto_minutes >= 0),
    rpo_minutes INTEGER NOT NULL CHECK (rpo_minutes >= 0),

    -- Plan details
    steps JSONB NOT NULL,                     -- Array of step objects {order, description, command, verification}
    prerequisites TEXT,
    responsible_team VARCHAR(100),
    documentation_url VARCHAR(500),

    -- Approval
    approved_by UUID,
    approved_at TIMESTAMP WITH TIME ZONE,
    approval_notes TEXT,

    -- Testing
    last_test_date DATE,
    last_test_result VARCHAR(20) CHECK (last_test_result IN ('PASS','FAIL','PARTIAL','NOT_TESTED')),
    next_test_date DATE,
    test_metrics JSONB,                        -- e.g., {actual_rto: 120, actual_rpo: 15}

    -- Status
    is_active BOOLEAN DEFAULT TRUE,
    review_frequency_days INTEGER DEFAULT 365 CHECK (review_frequency_days >= 0),
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_date DATE GENERATED ALWAYS AS (last_reviewed_at::DATE + review_frequency_days) STORED,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_drp_approved_by FOREIGN KEY (approved_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_drp_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_drp_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.disaster_recovery_plans IS 'Disaster recovery plans with RTO/RPO, steps, and test tracking';
COMMENT ON COLUMN socialcandor_schema.disaster_recovery_plans.rto_minutes IS 'Recovery Time Objective in minutes';
COMMENT ON COLUMN socialcandor_schema.disaster_recovery_plans.rpo_minutes IS 'Recovery Point Objective in minutes';
COMMENT ON COLUMN socialcandor_schema.disaster_recovery_plans.steps IS 'Structured recovery steps';

CREATE INDEX idx_drp_scenario ON socialcandor_schema.disaster_recovery_plans(scenario) WHERE is_active = TRUE;
CREATE INDEX idx_drp_next_test ON socialcandor_schema.disaster_recovery_plans(next_test_date) WHERE next_test_date IS NOT NULL;
CREATE INDEX idx_drp_review ON socialcandor_schema.disaster_recovery_plans(next_review_date) WHERE is_active = TRUE;

ALTER TABLE socialcandor_schema.disaster_recovery_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY drp_admin_policy ON socialcandor_schema.disaster_recovery_plans
    FOR ALL USING (socialcandor_schema.is_admin());

CREATE TRIGGER trg_disaster_recovery_plans_updated_at
    BEFORE UPDATE ON socialcandor_schema.disaster_recovery_plans
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- =================================================================================================
-- TABLE: 9 - service_health_checks
-- Description: Records the results of periodic health checks on internal and external services,
--              including response times, status, and error details. Enables real‑time monitoring.
-- Business Case: To maintain high availability, the platform must continuously monitor the health
--                of its components. This table stores the outcome of each health check: which service
--                was checked, the timestamp, the status (healthy, degraded, unhealthy), response time,
--                and any error message. A monitoring system can query recent records to compute
--                uptime percentages, detect anomalies, and trigger alerts. Historical data supports
--                trend analysis and capacity planning. The table can be partitioned by time for
--                performance and retention management.
-- KPIs:
--   1. Service uptime – percentage of time each service is healthy
--   2. Mean response time – average health check response time per service
--   3. Error rate – percentage of unhealthy checks
--   4. Detection lag – time between service failure and first unhealthy check
--   5. Check coverage – number of distinct services being monitored
-- Feature References: OBS11 (Health Monitoring), SRE03 (Service Level Indicators), ALERT02 (Alerting)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.service_health_checks (
    check_id BIGSERIAL,

    -- Human‑readable identifier
    check_number VARCHAR(50) GENERATED ALWAYS AS (
        'HC-' || TO_CHAR(check_time, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM check_time)::INT::TEXT, 6, '0')
    ) STORED,

    -- Service identification
    service_name VARCHAR(255) NOT NULL,
    service_instance VARCHAR(255),                     -- e.g., pod ID, region
    check_type VARCHAR(50) DEFAULT 'HTTP' CHECK (check_type IN ('HTTP', 'TCP', 'DATABASE', 'CUSTOM')),

    -- Check result
    check_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status socialcandor_schema.health_status NOT NULL,
    response_time_ms INTEGER CHECK (response_time_ms >= 0),
    status_code INTEGER,                               -- e.g., HTTP 200, 503
    response_size_bytes INTEGER,

    -- Additional details
    error_message TEXT,
    details JSONB,                                      -- e.g., {"cpu": 0.5, "memory": 0.7}

    -- Monitoring metadata
    monitored_by VARCHAR(100),                           -- monitoring system name
    alert_triggered BOOLEAN DEFAULT FALSE,
    acknowledged_at TIMESTAMP WITH TIME ZONE,

    -- Partition key
    check_date DATE GENERATED ALWAYS AS (check_time::DATE) STORED,

    CONSTRAINT pk_service_health_checks PRIMARY KEY (check_id, check_date)
) PARTITION BY RANGE (check_date);

COMMENT ON TABLE socialcandor_schema.service_health_checks IS 'Records of periodic health checks on services for real‑time monitoring';
COMMENT ON COLUMN socialcandor_schema.service_health_checks.status IS 'Health status determined by the check';
COMMENT ON COLUMN socialcandor_schema.service_health_checks.response_time_ms IS 'Response time in milliseconds';
COMMENT ON COLUMN socialcandor_schema.service_health_checks.details IS 'Additional metrics or diagnostic data';

-- Create initial partitions (example for current and next month)
DO $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
BEGIN
    FOR i IN 0..2 LOOP
        start_date := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;
        end_date := start_date + '1 month'::INTERVAL;
        partition_name := 'service_health_checks_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS socialcandor_schema.%I PARTITION OF socialcandor_schema.service_health_checks
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );
    END LOOP;
END $$;

-- Indexes on parent
CREATE INDEX idx_service_health_checks_service ON socialcandor_schema.service_health_checks(service_name, check_time DESC);
CREATE INDEX idx_service_health_checks_status ON socialcandor_schema.service_health_checks(status, check_time DESC) WHERE status != 'HEALTHY';
CREATE INDEX idx_service_health_checks_time ON socialcandor_schema.service_health_checks(check_time DESC);

ALTER TABLE socialcandor_schema.service_health_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_health_checks_admin_policy ON socialcandor_schema.service_health_checks
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- TABLE: 10 - incident_postmortems
-- Description: Captures detailed post‑incident analysis after a significant incident is resolved.
--              Includes root cause, timeline, action items, and lessons learned. Links to the incident.
-- Business Case: After an incident, a thorough postmortem is essential to prevent recurrence and
--                improve the system. This table stores the postmortem document, including structured
--                fields for root cause, timeline, contributing factors, and action items with owners
--                and due dates. The status field tracks whether the postmortem is still in draft,
--                published, or archived. Action items can be tracked to completion. By linking to the
--                incident (e.g., `incident_management`), we maintain a complete incident lifecycle.
--                This data supports learning, compliance, and reporting on incident trends.
-- KPIs:
--   1. Postmortem completion rate – percentage of incidents with a completed postmortem
--   2. Time to postmortem – average time from incident closure to postmortem publication
--   3. Action item closure rate – percentage of action items completed on time
--   4. Recurrence rate – number of incidents with similar root cause
--   5. Postmortem quality – e.g., percentage with clear root cause and action items
-- Feature References: INC04 (Post‑Incident Review), INC05 (Root Cause Analysis), IMPROVE02 (Continuous Improvement)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.incident_postmortems (
    postmortem_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Human‑readable identifier
    postmortem_number VARCHAR(50) GENERATED ALWAYS AS (
        'PM-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.incident_postmortems_seq')::TEXT, 6, '0')
    ) STORED,

    -- Incident reference
    incident_id UUID NOT NULL,                       -- References incident_management

    -- Basic information
    title VARCHAR(255) NOT NULL,
    summary TEXT,
    severity VARCHAR(20),                             -- denormalised from incident

    -- Analysis
    root_cause TEXT NOT NULL,
    contributing_factors TEXT[],
    timeline JSONB,                                   -- structured timeline of events
    impact_description TEXT,
    detection_method VARCHAR(100),

    -- Action items (could be separate table, but embedded for simplicity)
    action_items JSONB,                                -- array of {description, owner, due_date, status}

    -- Lessons learned
    what_went_well TEXT,
    what_went_wrong TEXT,
    lessons_learned TEXT,

    -- Follow‑up
    follow_up_required BOOLEAN DEFAULT FALSE,
    follow_up_date DATE,

    -- Status
    status socialcandor_schema.postmortem_status NOT NULL DEFAULT 'DRAFT',
    published_at TIMESTAMP WITH TIME ZONE,
    published_by UUID,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),

    -- Constraints
    CONSTRAINT fk_incident_postmortems_incident FOREIGN KEY (incident_id)
        REFERENCES socialcandor_schema.incident_management(incident_id) ON DELETE CASCADE,
    CONSTRAINT fk_incident_postmortems_published_by FOREIGN KEY (published_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_incident_postmortems_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_incident_postmortems_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL
);
COMMENT ON TABLE socialcandor_schema.incident_postmortems IS 'Detailed post‑incident analysis with root cause, timeline, and action items';
COMMENT ON COLUMN socialcandor_schema.incident_postmortems.timeline IS 'Structured timeline of key events during the incident';
COMMENT ON COLUMN socialcandor_schema.incident_postmortems.action_items IS 'JSON array of action items with owners and due dates';

CREATE INDEX idx_incident_postmortems_incident ON socialcandor_schema.incident_postmortems(incident_id);
CREATE INDEX idx_incident_postmortems_status ON socialcandor_schema.incident_postmortems(status, created_at DESC);
CREATE INDEX idx_incident_postmortems_followup ON socialcandor_schema.incident_postmortems(follow_up_date) WHERE follow_up_required = TRUE;

ALTER TABLE socialcandor_schema.incident_postmortems ENABLE ROW LEVEL SECURITY;
CREATE POLICY incident_postmortems_admin_policy ON socialcandor_schema.incident_postmortems
    FOR ALL USING (socialcandor_schema.is_admin());
CREATE POLICY incident_postmortems_reader_policy ON socialcandor_schema.incident_postmortems
    FOR SELECT USING (status = 'PUBLISHED' OR socialcandor_schema.is_admin());

CREATE TRIGGER trg_incident_postmortems_updated_at
    BEFORE UPDATE ON socialcandor_schema.incident_postmortems
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();



