-- Object: 201 - training_completion_status
-- Description: Defines the completion status of compliance training modules
-- Business Case: Enables precise tracking of employee training progress, including overdue status
--                and expiration, for regulatory compliance reporting (SOX, HIPAA, GDPR).
-- Feature Reference: COMP29 (Training Compliance)
-- =================================================================================================
CREATE TYPE socialcandor_schema.training_completion_status AS ENUM (
    'NOT_STARTED',      -- Training assigned but not started
    'IN_PROGRESS',      -- Training started but not completed
    'COMPLETED',        -- Successfully completed
    'OVERDUE',          -- Past due date without completion
    'EXPIRED'           -- Completed but certification expired
);
COMMENT ON TYPE socialcandor_schema.training_completion_status IS 'Defines the completion status of compliance training modules';

-- Object: 202 - vendor_risk_level
-- Description: Risk classification levels for third-party vendor assessments
-- Business Case: Enables standardized risk scoring and prioritization of vendor remediation efforts,
--                supporting third-party risk management frameworks (ISO 27001, NIST).
-- Feature Reference: VND02 (Vendor Risk Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.vendor_risk_level AS ENUM (
    'LOW',              -- Minimal risk, acceptable
    'MEDIUM',           -- Moderate risk, requires monitoring
    'HIGH',             -- Significant risk, requires mitigation
    'CRITICAL'          -- Severe risk, immediate action required
);
COMMENT ON TYPE socialcandor_schema.vendor_risk_level IS 'Risk classification levels for third-party vendor assessments';

-- Object: 203 - deprecation_status
-- Description: Status of API version deprecation
-- Business Case: Tracks the lifecycle of API versions from active through sunset,
--                enabling clear communication to developers and automated sunset enforcement.
-- Feature Reference: API13 (Deprecation Management)
-- =================================================================================================
CREATE TYPE socialcandor_schema.deprecation_status AS ENUM (
    'ACTIVE',           -- Currently supported
    'DEPRECATED',       -- Still functional but will be removed
    'SUNSET',           -- No longer available
    'PLANNED'           -- Deprecation scheduled
);
COMMENT ON TYPE socialcandor_schema.deprecation_status IS 'Status of API version deprecation';

