-- Enum: health_check_status
-- Description: Status of a service health check execution
-- Business Case: Track the state of automated health checks
-- Feature Reference: MON03 (Service Monitoring)
-- =================================================================================================
CREATE TYPE socialcandor_schema.health_check_status AS ENUM (
    'SUCCESS',
    'WARNING',
    'FAILURE',
    'TIMEOUT',
    'SKIPPED'
);
COMMENT ON TYPE socialcandor_schema.health_check_status IS 'Status of a service health check execution';

-- Enum: drp_status
-- Description: Status of a disaster recovery plan
-- Business Case: Track plan lifecycle from draft to archived
-- Feature Reference: BCP04 (Disaster Recovery)
-- =================================================================================================
CREATE TYPE socialcandor_schema.drp_status AS ENUM (
    'DRAFT',
    'ACTIVE',
    'TESTED',
    'OUTDATED',
    'ARCHIVED'
);
COMMENT ON TYPE socialcandor_schema.drp_status IS 'Status of a disaster recovery plan';

-- Enum: training_status
-- Description: Status of compliance training completion
-- Business Case: Track employee training progress and expiry
-- Feature Reference: COMP29 (Compliance Training)
-- =================================================================================================
CREATE TYPE socialcandor_schema.training_status AS ENUM (
    'NOT_STARTED',
    'IN_PROGRESS',
    'COMPLETED',
    'EXPIRED',
    'EXEMPT'
);
COMMENT ON TYPE socialcandor_schema.training_status IS 'Status of compliance training completion';

-- Enum: risk_level
-- Description: Risk level for vendor assessments (reuse existing if present)
-- Business Case: Standardised risk classification
-- Feature Reference: RISK03 (Vendor Risk)
-- =================================================================================================
-- (Assuming socialcandor_schema.risk_level already exists from earlier, but we define if not)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'risk_level' AND typnamespace = 'socialcandor_schema'::regnamespace) THEN
        CREATE TYPE socialcandor_schema.risk_level AS ENUM (
            'LOW',
            'MEDIUM',
            'HIGH',
            'CRITICAL'
        );
    END IF;
END $$;

-- Enum: assessment_status
-- Description: Status of a vendor risk assessment
-- Business Case: Track assessment lifecycle
-- Feature Reference: VND02 (Vendor Assessments)
-- =================================================================================================
CREATE TYPE socialcandor_schema.assessment_status AS ENUM (
    'PENDING',
    'IN_PROGRESS',
    'COMPLETED',
    'EXPIRED',
    'CANCELLED'
);
COMMENT ON TYPE socialcandor_schema.assessment_status IS 'Status of a vendor risk assessment';

-- Enum: deprecation_status
-- Description: Status of an API deprecation timeline
-- Business Case: Track deprecation stages
-- Feature Reference: API13 (API Deprecation)
-- =================================================================================================
CREATE TYPE socialcandor_schema.deprecation_status AS ENUM (
    'ANNOUNCED',
    'DEPRECATED',
    'SUNSET',
    'RETIRED'
);
COMMENT ON TYPE socialcandor_schema.deprecation_status IS 'Status of an API deprecation timeline';

