-- =================================================================================================
-- Table: data_quality_dashboards
-- Description: Stores pre‑computed data quality metrics for dashboards, aggregating scores per dataset.
-- Business Case: Data quality dashboards need fast access to aggregated metrics (completeness, accuracy,
--                freshness). This table caches those metrics, updated periodically, to avoid expensive
--                on‑the‑fly calculations. It tracks overall data quality scores per table or dataset,
--                along with trend indicators. Data stewards can monitor quality over time and be alerted
--                to degradation. The data feeds into executive dashboards and data governance reports.
-- KPIs:
--   1. Overall data quality score (by dataset)
--   2. Completeness percentage
--   3. Accuracy percentage
--   4. Freshness (time since last update)
--   5. Number of critical data issues
-- Feature References: DQ14 (Data Quality Dashboards), GOV23 (Data Governance Metrics), ANL26 (Data Health)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.data_quality_dashboards (
    dashboard_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    dashboard_number VARCHAR(50) GENERATED ALWAYS AS (
        'DQD-' || TO_CHAR(computed_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.data_quality_dashboards_seq')::TEXT, 6, '0')
    ) STORED,
    dataset_name VARCHAR(255) NOT NULL,                  -- e.g., 'users', 'posts', 'orders'
    schema_name VARCHAR(100),
    table_name VARCHAR(100),
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    overall_score NUMERIC(5,2) CHECK (overall_score >= 0 AND overall_score <= 100),
    completeness_score NUMERIC(5,2) CHECK (completeness_score >= 0 AND completeness_score <= 100),
    accuracy_score NUMERIC(5,2) CHECK (accuracy_score >= 0 AND accuracy_score <= 100),
    consistency_score NUMERIC(5,2) CHECK (consistency_score >= 0 AND consistency_score <= 100),
    timeliness_score NUMERIC(5,2) CHECK (timeliness_score >= 0 AND timeliness_score <= 100),
    uniqueness_score NUMERIC(5,2) CHECK (uniqueness_score >= 0 AND uniqueness_score <= 100),
    row_count INTEGER CHECK (row_count >= 0),
    critical_issues INTEGER DEFAULT 0,
    high_issues INTEGER DEFAULT 0,
    medium_issues INTEGER DEFAULT 0,
    low_issues INTEGER DEFAULT 0,
    metrics_details JSONB,                                -- Detailed per‑column scores
    previous_score NUMERIC(5,2),                          -- For trend calculation
    trend_direction VARCHAR(10) CHECK (trend_direction IN ('IMPROVING', 'STABLE', 'DEGRADING')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_dq_dashboards_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_dq_dashboards_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT uk_dq_dashboards_dataset UNIQUE (dataset_name, computed_at)
);

COMMENT ON TABLE socialcandor_schema.data_quality_dashboards IS 'Pre‑computed data quality metrics for dashboards';
COMMENT ON COLUMN socialcandor_schema.data_quality_dashboards.metrics_details IS 'JSON with detailed per‑column quality scores';

-- Indexes
CREATE INDEX idx_dq_dashboards_dataset ON socialcandor_schema.data_quality_dashboards(dataset_name, computed_at DESC);
CREATE INDEX idx_dq_dashboards_score ON socialcandor_schema.data_quality_dashboards(overall_score) WHERE overall_score < 80;

-- Trigger
CREATE TRIGGER trg_data_quality_dashboards_updated_at
    BEFORE UPDATE ON socialcandor_schema.data_quality_dashboards
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.data_quality_dashboards ENABLE ROW LEVEL SECURITY;
CREATE POLICY dq_dashboards_read_policy ON socialcandor_schema.data_quality_dashboards
    FOR SELECT USING (TRUE);
CREATE POLICY dq_dashboards_admin_policy ON socialcandor_schema.data_quality_dashboards
    FOR ALL USING (socialcandor_schema.is_admin());

-- =================================================================================================
-- Table: api_deprecation_timeline
-- Description: Tracks the deprecation and sunset schedule for API versions and endpoints.
-- Business Case: API deprecation must be communicated clearly to developers to allow migration.
--                This table records each deprecation event, including announcement date, sunset date,
--                migration guidance, and current status. It enables automated notifications to affected
--                clients and provides a public timeline for developers. The data supports API governance,
--                ensures compliance with deprecation policies, and reduces support burden by proactively
--                informing users.
-- KPIs:
--   1. Number of APIs deprecated per quarter
--   2. Average lead time from announcement to sunset
--   3. Percentage of deprecated APIs with migration guides
--   4. Client migration rate before sunset
--   5. Support tickets related to deprecated APIs
-- Feature References: API13 (API Deprecation), DEV02 (Developer Experience), GOV24 (API Governance)
-- =================================================================================================
CREATE TABLE IF NOT EXISTS socialcandor_schema.api_deprecation_timeline (
    timeline_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    timeline_number VARCHAR(50) GENERATED ALWAYS AS (
        'ADT-' || TO_CHAR(announced_at, 'YYYYMMDD') || '-' || LPAD(nextval('socialcandor_schema.api_deprecation_timeline_seq')::TEXT, 6, '0')
    ) STORED,
    api_name VARCHAR(255) NOT NULL,
    api_version VARCHAR(50) NOT NULL,
    endpoint VARCHAR(500),                               -- Can be NULL if whole version is deprecated
    deprecation_type VARCHAR(30) CHECK (deprecation_type IN ('VERSION', 'ENDPOINT', 'FIELD')),
    announced_at TIMESTAMP WITH TIME ZONE NOT NULL,
    deprecation_date DATE NOT NULL,                       -- When it becomes deprecated (but still works)
    sunset_date DATE NOT NULL,                            -- When it stops working
    migration_guide_url VARCHAR(500),
    breaking_changes TEXT,
    affected_clients TEXT[],                              -- List of client IDs or emails (optional)
    status socialcandor_schema.deprecation_status NOT NULL DEFAULT 'ANNOUNCED',
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID DEFAULT uuid_nil(),
    -- Constraints
    CONSTRAINT fk_api_deprecation_created_by FOREIGN KEY (created_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_api_deprecation_updated_by FOREIGN KEY (updated_by)
        REFERENCES socialcandor_schema.users(user_id) ON DELETE SET NULL,
    CONSTRAINT chk_api_deprecation_dates CHECK (sunset_date >= deprecation_date AND deprecation_date >= announced_at::DATE),
    CONSTRAINT uk_api_deprecation UNIQUE (api_name, api_version, endpoint)
);

COMMENT ON TABLE socialcandor_schema.api_deprecation_timeline IS 'Tracks the deprecation and sunset schedule for API versions and endpoints';
COMMENT ON COLUMN socialcandor_schema.api_deprecation_timeline.affected_clients IS 'List of client IDs that have been notified';

-- Indexes
CREATE INDEX idx_api_deprecation_api ON socialcandor_schema.api_deprecation_timeline(api_name, api_version, status);
CREATE INDEX idx_api_deprecation_dates ON socialcandor_schema.api_deprecation_timeline(sunset_date) WHERE status != 'RETIRED';

-- Trigger
CREATE TRIGGER trg_api_deprecation_timeline_updated_at
    BEFORE UPDATE ON socialcandor_schema.api_deprecation_timeline
    FOR EACH ROW EXECUTE FUNCTION socialcandor_schema.update_updated_at_column();

-- RLS
ALTER TABLE socialcandor_schema.api_deprecation_timeline ENABLE ROW LEVEL SECURITY;
CREATE POLICY api_deprecation_public_policy ON socialcandor_schema.api_deprecation_timeline
    FOR SELECT USING (TRUE);   -- Public read for developers
CREATE POLICY api_deprecation_admin_policy ON socialcandor_schema.api_deprecation_timeline
    FOR ALL USING (socialcandor_schema.is_admin());


