--Monitoring & Alerting Setup

-- Create monitoring views
CREATE VIEW socialcandor_schema.vw_database_health AS
SELECT
    current_database() as database_name,
    pg_database_size(current_database()) as database_size_bytes,
    (SELECT count(*) FROM pg_stat_activity WHERE state = 'active') as active_connections,
    (SELECT count(*) FROM pg_stat_activity WHERE wait_event_type IS NOT NULL) as waiting_connections,
    (SELECT count(*) FROM pg_locks WHERE NOT granted) as locked_queries,
    pg_postmaster_start_time() as server_start_time;

-- Create alerting function
CREATE OR REPLACE FUNCTION socialcandor_schema.check_critical_alerts()
RETURNS TABLE (alert_type VARCHAR, alert_message TEXT, severity VARCHAR) AS $$
BEGIN
    -- Long-running queries
    RETURN QUERY
    SELECT 'LONG_QUERY'::VARCHAR,
           format('Query running for %s minutes', EXTRACT(EPOCH FROM (NOW() - query_start))/60)::TEXT,
           'WARNING'::VARCHAR
    FROM pg_stat_activity
    WHERE state = 'active'
    AND NOW() - query_start > INTERVAL '10 minutes';

    -- Connection saturation
    RETURN QUERY
    SELECT 'CONNECTION_SATURATION'::VARCHAR,
           format('%s%% of max connections used',
                  (SELECT count(*) FROM pg_stat_activity)::NUMERIC /
                  (SELECT setting::NUMERIC FROM pg_settings WHERE name = 'max_connections') * 100)::TEXT,
           'CRITICAL'::VARCHAR
    WHERE (SELECT count(*) FROM pg_stat_activity)::NUMERIC /
          (SELECT setting::NUMERIC FROM pg_settings WHERE name = 'max_connections') > 0.8;
END;
$$ LANGUAGE plpgsql;

