    -- ====================================================================================
    -- ENUMS SECTION
    -- ====================================================================================

    -----------------------------------------------------------------------------------------------
    -- Enum: tenant_isolation_level
    -- Description: Defines the isolation strength between tenants in multi-tenant architecture
    -- Business Case: Enables fine-grained data isolation based on compliance requirements and trust levels
    -- Feature Reference: MT01 (Multi-tenant Isolation Framework)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE tenant_isolation_level AS ENUM (
        'STRICT',           -- Complete data separation, no cross-tenant access
        'SHARED_READ',      -- Can read shared reference data only
        'SHARED_WRITE',     -- Can write to shared data with restrictions
        'FEDERATED',        -- Query federation with tenant context
        'MIXED'             -- Hybrid model based on data classification
    );
    COMMENT ON TYPE tenant_isolation_level IS 'Defines the isolation strength between tenants in multi-tenant architecture';

    -----------------------------------------------------------------------------------------------
    -- Enum: rotation_status
    -- Description: Tracks the lifecycle status of a secret rotation operation
    -- Business Case: Ensures audit trail completeness for compliance requirements (SOC2, ISO27001)
    -- Feature Reference: SEC01 (Secret Management & Rotation)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE rotation_status AS ENUM (
        'SCHEDULED',        -- Rotation planned but not started
        'IN_PROGRESS',      -- Rotation actively executing
        'VERIFYING',        -- New secret being tested
        'COMPLETED',        -- Rotation successful
        'FAILED',           -- Rotation failed, needs intervention
        'ROLLED_BACK',      -- Reverted to previous secret
        'EXPIRED',          -- Secret expired before rotation
        'MANUAL_INTERVENTION' -- Requires human action
    );
    COMMENT ON TYPE rotation_status IS 'Tracks the lifecycle status of a secret rotation operation';

    -----------------------------------------------------------------------------------------------
    -- Enum: erasure_state
    -- Description: State machine for GDPR right-to-erasure workflow progression
    -- Business Case: Provides auditable compliance with Article 17 of GDPR
    -- Feature Reference: GDPR01 (Right to Erasure Implementation)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE erasure_state AS ENUM (
        'REQUEST_RECEIVED',     -- Initial request logged
        'VERIFYING_IDENTITY',   -- Validating requester identity
        'ASSESSING_SCOPE',      -- Determining data scope for erasure
        'CHECKING_LEGAL_HOLD',  -- Verifying legal holds
        'IN_PROGRESS',          -- Active erasure operations
        'PARTIAL_COMPLETION',   -- Some data couldn't be erased
        'COMPLETED',            -- Full erasure executed
        'REJECTED',             -- Request denied (legal basis)
        'EXPIRED',              -- Request timed out
        'AUDIT_REQUIRED'        -- Requires third-party audit
    );
    COMMENT ON TYPE erasure_state IS 'State machine for GDPR right-to-erasure workflow progression';

    -----------------------------------------------------------------------------------------------
    -- Enum: error_budget_status
    -- Description: Current health status of an SLO error budget
    -- Business Case: Enables automated alerting and incident response based on budget consumption
    -- Feature Reference: REL01 (Service Level Objectives Framework)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE error_budget_status AS ENUM (
        'HEALTHY',          -- Less than 50% budget consumed
        'WARNING',          -- 50-75% budget consumed
        'CRITICAL',         -- 75-90% budget consumed
        'EXHAUSTED',        -- 90-100% budget consumed
        'BURNING',          -- Exceeding burn rate threshold
        'RESETTING',        -- Budget reset in progress
        'PAUSED',           -- Temporarily not tracking
        'MAINTENANCE'       -- Exempt due to maintenance
    );
    COMMENT ON TYPE error_budget_status IS 'Current health status of an SLO error budget';

    -----------------------------------------------------------------------------------------------
    -- Enum: data_quality_severity
    -- Description: Impact level of data quality violations
    -- Business Case: Prioritizes remediation efforts based on business impact
    -- Feature Reference: DG01 (Data Quality Management Framework)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE data_quality_severity AS ENUM (
        'BLOCKER',      -- Prevents business operations
        'CRITICAL',     -- Major impact on decisions
        'HIGH',         -- Significant data issues
        'MEDIUM',       -- Moderate quality concerns
        'LOW',          -- Minor quality issues
        'INFO'          -- Informational only
    );
    COMMENT ON TYPE data_quality_severity IS 'Impact level of data quality violations';

    -----------------------------------------------------------------------------------------------
    -- Enum: invalidation_scope
    -- Description: Scope of cache invalidation operation
    -- Business Case: Optimizes cache purging by limiting scope to affected entities
    -- Feature Reference: PERF01 (Cache Management Strategy)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE invalidation_scope AS ENUM (
        'ENTITY',           -- Single entity invalidation
        'COLLECTION',       -- Entire collection/type
        'PATTERN',          -- Pattern-based invalidation
        'TENANT',           -- All data for a tenant
        'GLOBAL',           -- Global cache clear
        'WILDCARD'          -- Wildcard pattern match
    );
    COMMENT ON TYPE invalidation_scope IS 'Scope of cache invalidation operation';

    -----------------------------------------------------------------------------------------------
    -- Enum: throttle_action
    -- Description: Action taken when rate limit is exceeded
    -- Business Case: Provides granular control over request handling
    -- Feature Reference: SEC02 (Rate Limiting & Throttling)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE throttle_action AS ENUM (
        'BLOCK',            -- Request completely blocked
        'DELAY',            -- Request queued with delay
        'DEGRADE',          -- Partial response allowed
        'REJECT',           -- Request rejected with retry-after
        'CIRCUIT_OPEN',     -- Circuit breaker opened
        'REDIRECT'          -- Redirect to capacity reserve
    );
    COMMENT ON TYPE throttle_action IS 'Action taken when rate limit is exceeded';

    -----------------------------------------------------------------------------------------------
    -- Enum: lineage_confidence
    -- Description: Confidence level of automatically detected data lineage
    -- Business Case: Indicates reliability of automated lineage detection
    -- Feature Reference: DG02 (Data Lineage & Provenance)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE lineage_confidence AS ENUM (
        'CONFIRMED',        -- Verified by multiple sources
        'HIGH',             -- High confidence automated detection
        'MEDIUM',           -- Pattern-based inference
        'LOW',              -- Heuristic-based suggestion
        'PENDING_VERIFICATION' -- Awaiting human verification
    );
    COMMENT ON TYPE lineage_confidence IS 'Confidence level of automatically detected data lineage';

    -----------------------------------------------------------------------------------------------
    -- Enum: certification_status
    -- Description: Current status of compliance certification
    -- Business Case: Tracks certification lifecycle for audit readiness
    -- Feature Reference: COMP01 (Compliance Management)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE certification_status AS ENUM (
        'NOT_STARTED',      -- Not yet pursuing certification
        'IN_PROGRESS',      -- Active certification process
        'PRE_AUDIT',        -- Internal audit phase
        'FINAL_AUDIT',      -- External auditor review
        'CERTIFIED',        -- Certification achieved
        'EXPIRED',          -- Certification lapsed
        'REVOKED',          -- Certification withdrawn
        'SUSPENDED',        -- Temporarily invalid
        'REMEDIATION'       -- Addressing findings
    );
    COMMENT ON TYPE certification_status IS 'Current status of compliance certification';

    -----------------------------------------------------------------------------------------------
    -- Enum: routing_version_strategy
    -- Description: API version routing strategy
    -- Business Case: Enables graceful API evolution with backward compatibility
    -- Feature Reference: API01 (API Gateway Management)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE routing_version_strategy AS ENUM (
        'HEADER_BASED',     -- Version from custom header
        'URL_PATH',         -- Version in URL path
        'CONTENT_NEGOTIATION', -- Accept header versioning
        'QUERY_PARAM',      -- Version as query parameter
        'DEPRECATED',       -- Marked for removal
        'BETA'              -- Preview version
    );
    COMMENT ON TYPE routing_version_strategy IS 'API version routing strategy';

    -----------------------------------------------------------------------------------------------
    -- Enum: incident_severity
    -- Description: Severity levels for incident classification
    -- Business Case: Standardizes incident response based on business impact
    -- Feature Reference: OPS01 (Incident Management)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE incident_severity AS ENUM (
        'SEV0',     -- Complete service outage, data loss
        'SEV1',     -- Major functionality degraded
        'SEV2',     -- Minor functionality impacted
        'SEV3',     -- Cosmetic issues, non-critical
        'SEV4'      -- Informational, no user impact
    );
    COMMENT ON TYPE incident_severity IS 'Severity levels for incident classification';

    -----------------------------------------------------------------------------------------------
    -- Enum: consent_state
    -- Description: Current state of third-party data sharing consent
    -- Business Case: Ensures GDPR/CCPA compliance for data processing
    -- Feature Reference: PRIV01 (Consent Management)
    -----------------------------------------------------------------------------------------------
    CREATE TYPE consent_state AS ENUM (
        'GRANTED',          -- Explicit consent provided
        'WITHDRAWN',        -- Consent revoked
        'EXPIRED',          -- Consent time-limited expired
        'PENDING_VERIFICATION', -- Awaiting email/phone verification
        'LIMITED',          -- Partial consent with restrictions
        'NOT_REQUIRED',     -- No consent needed for processing
        'PARENTAL_CONSENT'  -- Minor requiring guardian consent
    );
    COMMENT ON TYPE consent_state IS 'Current state of third-party data sharing consent';


    -- ====================================================================================
    -- FOUNDATION & COMPLIANCE TABLES
    -- ====================================================================================

    -----------------------------------------------------------------------------------------------
    -- Serial No: 1
    -- Table Name: multi_tenant_policies
    -- Description: Explicit tenant isolation rules, data residency flags, cross-tenant sharing controls
    -- Business Case: Enables secure multi-tenant architecture with granular isolation policies based on
    --   regulatory requirements (GDPR, CCPA, HIPAA) and business trust levels. Each tenant can have
    --   customized isolation rules while maintaining platform-wide security standards. This table
    --   forms the foundation of our data access control layer, ensuring that data from different
    --   customers never unintentionally mixes while allowing controlled sharing where legally and
    --   commercially appropriate. For example, a parent company with multiple subsidiaries might need
    --   consolidated reporting while maintaining operational separation. The policies defined here
    --   are enforced at query time through Row Level Security (RLS) policies and API middleware,
    --   providing defense-in-depth against data leakage. Data residency flags enable compliance with
    --   regulations requiring data to remain within specific geographic boundaries (e.g., EU data
    --   cannot leave European servers). Cross-tenant sharing controls support business models where
    --   partners need limited access to each other's data, such as supply chain collaborations or
    --   multi-brand retail analytics. The policy evaluation engine caches these rules with TTL-based
    --   invalidation to minimize performance impact on critical paths.
    -- Key Performance Indicators (KPIs):
    --   1. Policy Evaluation Latency - Time to evaluate tenant permissions (p99 < 10ms)
    --   2. Cross-Tenant Sharing Requests - Number of authorized sharing operations per day
    --   3. Isolation Violation Incidents - Count of attempted/actual data leakage events
    --   4. Policy Coverage Ratio - Percentage of data assets with explicit isolation rules
    --   5. Compliance Audit Pass Rate - Success rate for data isolation audit requirements
    -- Feature References: MT01 (Multi-tenant Isolation), SEC03 (Data Access Control), COMP02 (Data Residency)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE multi_tenant_policies (
        -- Primary Key
        policy_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Tenant Identification
        tenant_id UUID NOT NULL,
        source_tenant_id UUID,
        target_tenant_id UUID,

        -- Policy Configuration
        isolation_level tenant_isolation_level NOT NULL DEFAULT 'STRICT',
        data_residency_required VARCHAR(3) NOT NULL DEFAULT 'US',  -- ISO 3166-1 alpha-3
        data_residency_actual VARCHAR(3),
        backup_residency VARCHAR(3),
        cross_tenant_sharing_enabled BOOLEAN DEFAULT FALSE,

        -- Sharing Controls (if enabled)
        shared_resource_types TEXT[] DEFAULT '{}',
        shared_operation_types TEXT[] DEFAULT '{}',
        sharing_ttl_days INTEGER CHECK (sharing_ttl_days IS NULL OR sharing_ttl_days BETWEEN 1 AND 365),
        sharing_approval_required BOOLEAN DEFAULT TRUE,
        sharing_audit_level VARCHAR(20) CHECK (sharing_audit_level IN ('NONE', 'SUMMARY', 'DETAILED', 'FULL')),

        -- Data Classification
        data_classification VARCHAR(50) CHECK (data_classification IN ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED', 'HIGHLY_RESTRICTED')),
        pii_contains BOOLEAN DEFAULT FALSE,
        phi_contains BOOLEAN DEFAULT FALSE,
        financial_data_contains BOOLEAN DEFAULT FALSE,

        -- Geographic Restrictions
        allowed_regions TEXT[] DEFAULT '{}',
        blocked_regions TEXT[] DEFAULT '{}',
        data_processing_location VARCHAR(100),

        -- Encryption Requirements
        encryption_at_rest_required BOOLEAN DEFAULT TRUE,
        encryption_in_transit_required BOOLEAN DEFAULT TRUE,
        encryption_algorithm VARCHAR(50) DEFAULT 'AES-256-GCM',
        key_rotation_days INTEGER DEFAULT 90,

        -- Audit & Compliance
        retention_days INTEGER DEFAULT 365,
        audit_logging_enabled BOOLEAN DEFAULT TRUE,
        compliance_framework TEXT[] DEFAULT '{}',

        -- Time-based Controls
        effective_from TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        effective_to TIMESTAMPTZ,
        is_active BOOLEAN DEFAULT TRUE,

        -- Metadata
        policy_version INTEGER DEFAULT 1,
        policy_priority INTEGER DEFAULT 5 CHECK (policy_priority BETWEEN 1 AND 10),
        policy_reason TEXT,

        -- Audit Trail
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID NOT NULL,

        -- Constraints
        CONSTRAINT valid_tenant_policy CHECK (
            (isolation_level = 'STRICT' AND cross_tenant_sharing_enabled = FALSE) OR
            (isolation_level IN ('SHARED_READ', 'SHARED_WRITE', 'FEDERATED', 'MIXED'))
        ),
        CONSTRAINT valid_sharing_config CHECK (
            cross_tenant_sharing_enabled = FALSE OR
            (cross_tenant_sharing_enabled = TRUE AND source_tenant_id IS NOT NULL AND target_tenant_id IS NOT NULL)
        ),
        CONSTRAINT valid_date_range CHECK (
            effective_to IS NULL OR effective_to > effective_from
        )
    );

    -- Indexes for multi_tenant_policies
    CREATE INDEX idx_mtp_tenant_active ON multi_tenant_policies(tenant_id, is_active) WHERE is_active = TRUE;
    CREATE INDEX idx_mtp_sharing_lookup ON multi_tenant_policies(source_tenant_id, target_tenant_id, is_active) WHERE cross_tenant_sharing_enabled = TRUE;
    CREATE INDEX idx_mtp_residency ON multi_tenant_policies(data_residency_required, tenant_id);
    CREATE INDEX idx_mtp_effective_range ON multi_tenant_policies(effective_from, effective_to) WHERE effective_to IS NOT NULL;
    CREATE INDEX idx_mtp_classification ON multi_tenant_policies(data_classification, pii_contains);

    -- Comments
    COMMENT ON TABLE multi_tenant_policies IS 'Explicit tenant isolation rules, data residency flags, and cross-tenant sharing controls';
    COMMENT ON COLUMN multi_tenant_policies.policy_id IS 'Unique identifier for the isolation policy';
    COMMENT ON COLUMN multi_tenant_policies.tenant_id IS 'Primary tenant this policy applies to';
    COMMENT ON COLUMN multi_tenant_policies.isolation_level IS 'STRICT=Complete separation, SHARED_READ=Can read reference data, SHARED_WRITE=Can write shared data, FEDERATED=Query federation, MIXED=Hybrid model';
    COMMENT ON COLUMN multi_tenant_policies.data_residency_required IS 'ISO 3166-1 alpha-3 country code where data must reside';
    COMMENT ON COLUMN multi_tenant_policies.cross_tenant_sharing_enabled IS 'Whether this tenant allows controlled data sharing with other tenants';

    -- RLS Policies
    ALTER TABLE multi_tenant_policies ENABLE ROW LEVEL SECURITY;

    CREATE POLICY mtp_superuser_access ON multi_tenant_policies
        FOR ALL USING (current_setting('app.user_role') = 'SUPER_ADMIN');

    CREATE POLICY mtp_tenant_self_access ON multi_tenant_policies
        FOR SELECT USING (tenant_id = current_setting('app.tenant_id')::UUID);

    -- Update Trigger
    CREATE OR REPLACE FUNCTION update_updated_at_column()
    RETURNS TRIGGER AS $$
    BEGIN
        NEW.updated_at = CURRENT_TIMESTAMP;
        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER update_mtp_updated_at
        BEFORE UPDATE ON multi_tenant_policies
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -----------------------------------------------------------------------------------------------
    -- Serial No: 2
    -- Table Name: secrets_rotation_logs
    -- Description: Audit trail for API key, OAuth token, & encryption key rotations
    -- Business Case: Provides complete auditable history of secret rotations for compliance with
    --   SOC2 (CC6.1), ISO27001 (A.9.4), and PCI-DSS (Requirement 8) which mandate regular credential
    --   rotation and audit trails. This table captures every rotation event including success/failure
    --   status, timing, responsible entity, and cryptographic verification hashes. The audit trail
    --   enables forensic analysis of potential security incidents, demonstrates compliance during
    --   audits, and helps identify rotation failures that could lead to credential exposure. Each
    --   rotation log includes before/after state tracking (without storing actual secrets, only
    --   salted hashes for verification), enabling detection of unauthorized secret usage. The table
    --   supports automated rotation systems by providing a reliable state machine for tracking
    --   multi-step rotation workflows, including the critical verification phase where new secrets
    --   are tested before decommissioning old ones. For secrets that failed rotation, the system
    --   tracks retry attempts and escalation paths to security teams. This table is immutable by
    --   design (append-only) to maintain audit integrity, with retention policies aligned to
    --   compliance requirements (typically 7 years for financial services, 3 years for SaaS).
    -- Key Performance Indicators (KPIs):
    --   1. Rotation Success Rate - Percentage of successful rotations (Target > 99.9%)
    --   2. Mean Time to Rotate - Average completion time for rotation workflows
    --   3. Rotation Coverage - Percentage of secrets rotated within policy timeframe
    --   4. Failed Rotation Incidents - Count of rotation failures requiring intervention
    --   5. Audit Trail Completeness - Percentage of rotations with complete before/after verification
    -- Feature References: SEC01 (Secret Management), COMP03 (Audit Trail), SEC04 (Credential Rotation)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE secrets_rotation_logs (
        -- Primary Key
        rotation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Secret Identification
        secret_type VARCHAR(50) NOT NULL CHECK (secret_type IN ('API_KEY', 'OAUTH_TOKEN', 'ENCRYPTION_KEY', 'JWT_SECRET', 'DATABASE_PASSWORD', 'SERVICE_ACCOUNT')),
        secret_id VARCHAR(255) NOT NULL,
        secret_name VARCHAR(255),
        secret_version INTEGER,

        -- Association Tracking
        tenant_id UUID,
        service_name VARCHAR(255),
        environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT', 'TESTING')),

        -- Rotation State
        rotation_status rotation_status NOT NULL DEFAULT 'SCHEDULED',
        previous_secret_hash VARCHAR(128),  -- SHA-512 hash of previous secret (not the secret itself)
        new_secret_hash VARCHAR(128),       -- SHA-512 hash of new secret
        verification_hash VARCHAR(128),     -- Hash for verification after rotation

        -- Timing Metrics
        scheduled_time TIMESTAMPTZ NOT NULL,
        started_at TIMESTAMPTZ,
        completed_at TIMESTAMPTZ,
        duration_seconds INTEGER,

        -- Performance Metrics
        verification_latency_ms INTEGER,
        propagation_delay_ms INTEGER,

        -- Rotation Details
        rotation_method VARCHAR(50) CHECK (rotation_method IN ('AUTOMATED_SCHEDULED', 'AUTOMATED_ON_EXPIRY', 'MANUAL', 'BREAK_GLASS', 'SYSTEM_UPGRADE')),
        rotation_initiator VARCHAR(255) NOT NULL,
        rotation_reason TEXT,

        -- Cryptographic Verification
        previous_secret_fingerprint VARCHAR(64),
        new_secret_fingerprint VARCHAR(64),
        signature_algorithm VARCHAR(50),

        -- Failure Handling
        failure_reason TEXT,
        failure_category VARCHAR(100),
        retry_count INTEGER DEFAULT 0,
        escalation_required BOOLEAN DEFAULT FALSE,
        escalated_to UUID,

        -- Security Context
        source_ip INET,
        user_agent TEXT,
        request_id UUID,
        correlation_id UUID,

        -- Compliance Tags
        compliance_frameworks TEXT[] DEFAULT '{}',
        requires_manual_review BOOLEAN DEFAULT FALSE,
        review_completed_at TIMESTAMPTZ,
        reviewed_by UUID,

        -- Audit Trail (Immutable - Only INSERT allowed via triggers)
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,

        -- Metadata
        tags TEXT[] DEFAULT '{}',
        notes TEXT,

        -- Constraints
        CONSTRAINT valid_rotation_timing CHECK (
            (rotation_status = 'SCHEDULED' AND started_at IS NULL) OR
            (rotation_status IN ('IN_PROGRESS', 'VERIFYING') AND started_at IS NOT NULL AND completed_at IS NULL) OR
            (rotation_status IN ('COMPLETED', 'FAILED', 'ROLLED_BACK', 'EXPIRED') AND started_at IS NOT NULL AND completed_at IS NOT NULL)
        ),
        CONSTRAINT valid_hashes CHECK (
            (rotation_status != 'COMPLETED') OR
            (rotation_status = 'COMPLETED' AND new_secret_hash IS NOT NULL)
        )
    );

    -- Indexes for secrets_rotation_logs
    CREATE INDEX idx_srl_secret_lookup ON secrets_rotation_logs(secret_type, secret_id, secret_version);
    CREATE INDEX idx_srl_status_timing ON secrets_rotation_logs(rotation_status, scheduled_time) WHERE rotation_status IN ('SCHEDULED', 'IN_PROGRESS', 'VERIFYING');
    CREATE INDEX idx_srl_tenant_service ON secrets_rotation_logs(tenant_id, service_name) WHERE tenant_id IS NOT NULL;
    CREATE INDEX idx_srl_completion_time ON secrets_rotation_logs(completed_at DESC) WHERE completed_at IS NOT NULL;
    CREATE INDEX idx_srl_correlation ON secrets_rotation_logs(correlation_id);
    CREATE INDEX idx_srl_failure_analysis ON secrets_rotation_logs(failure_category, retry_count) WHERE rotation_status = 'FAILED';

    -- Comments
    COMMENT ON TABLE secrets_rotation_logs IS 'Audit trail for API key, OAuth token, and encryption key rotations with complete workflow tracking';
    COMMENT ON COLUMN secrets_rotation_logs.rotation_id IS 'Unique identifier for each rotation event';
    COMMENT ON COLUMN secrets_rotation_logs.secret_type IS 'Type of secret being rotated: API_KEY, OAUTH_TOKEN, ENCRYPTION_KEY, etc.';
    COMMENT ON COLUMN secrets_rotation_logs.previous_secret_hash IS 'SHA-512 hash of previous secret (never store actual secrets)';
    COMMENT ON COLUMN secrets_rotation_logs.rotation_status IS 'Current state in rotation workflow: SCHEDULED, IN_PROGRESS, VERIFYING, COMPLETED, etc.';
    COMMENT ON COLUMN secrets_rotation_logs.duration_seconds IS 'Total time from start to completion in seconds';

    -- RLS Policies
    ALTER TABLE secrets_rotation_logs ENABLE ROW LEVEL SECURITY;

    CREATE POLICY srl_security_team_access ON secrets_rotation_logs
        FOR ALL USING (current_setting('app.user_role') IN ('SECURITY_ADMIN', 'SUPER_ADMIN'));

    CREATE POLICY srl_audit_readonly ON secrets_rotation_logs
        FOR SELECT USING (current_setting('app.user_role') = 'AUDITOR');

    CREATE POLICY srl_tenant_limited ON secrets_rotation_logs
        FOR SELECT USING (tenant_id = current_setting('app.tenant_id')::UUID);

    -- Audit Trigger (Prevent Updates/Deletes on Completed Rotations)
    CREATE OR REPLACE FUNCTION prevent_completed_rotation_modification()
    RETURNS TRIGGER AS $$
    BEGIN
        IF OLD.rotation_status IN ('COMPLETED', 'EXPIRED') THEN
            RAISE EXCEPTION 'Cannot modify completed or expired rotation records (Rotation ID: %)', OLD.rotation_id;
        END IF;
        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER protect_completed_rotations
        BEFORE UPDATE ON secrets_rotation_logs
        FOR EACH ROW
        EXECUTE FUNCTION prevent_completed_rotation_modification();

    CREATE TRIGGER update_srl_updated_at
        BEFORE UPDATE ON secrets_rotation_logs
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -----------------------------------------------------------------------------------------------
    -- Serial No: 3
    -- Table Name: gdpr_erasure_workflow
    -- Description: State machine for right-to-erasure, cascade tracking, legal hold overrides
    -- Business Case: Implements GDPR Article 17 "Right to Erasure" (Right to be Forgotten) with
    --   comprehensive workflow management that balances individual privacy rights against legal
    --   obligations for data retention. The table manages the complete lifecycle of erasure requests
    --   from initial submission through verification, scope assessment, execution, and certification.
    --   Critical features include legal hold detection that automatically pauses erasure when data
    --   is required for active legal proceedings, regulatory investigations, or unresolved disputes.
    --   Cascade tracking ensures referential integrity by identifying and handling dependent records
    --   across the data ecosystem - for example, erasing a user record triggers appropriate actions
    --   on their orders, support tickets, analytics events, and third-party data shares. The workflow
    --   supports partial erasure when some data cannot be removed due to legal requirements, with
    --   clear documentation of what was/hasn't been erased and why. Each state transition is
    --   timestamped and attributed, creating an auditable trail for regulators. The table integrates
    --   with data retention policies to apply automatic expiration rules, reducing manual requests.
    --   For organizations operating across multiple jurisdictions, the workflow respects varying
    --   interpretation of erasure rights (e.g., EU vs California vs Brazil) through configurable
    --   rule sets. Time limits for completion (typically 30 days under GDPR) are enforced with
    --   escalation paths for delayed requests.
    -- Key Performance Indicators (KPIs):
    --   1. Erasure Completion Time - Average time from request to completion (Target < 15 days)
    --   2. Legal Hold Rate - Percentage of requests blocked by active legal holds
    --   3. Cascade Success Rate - Percentage of dependent records properly handled
    --   4. Regulatory Compliance Rate - Percentage of requests meeting jurisdictional deadlines
    --   5. Partial Erasure Frequency - Rate of requests requiring partial erasure documentation
    -- Feature References: GDPR01 (Right to Erasure), COMP04 (Legal Hold Management), PRIV02 (Data Subject Rights)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE gdpr_erasure_workflow (
        -- Primary Key
        request_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Request Identification
        request_number VARCHAR(50) GENERATED ALWAYS AS (
            'ERASE-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(EXTRACT(EPOCH FROM created_at)::BIGINT::VARCHAR, 6, '0')
        ) STORED,

        -- Data Subject Information
        subject_type VARCHAR(50) NOT NULL CHECK (subject_type IN ('CUSTOMER', 'EMPLOYEE', 'VENDOR', 'PARTNER', 'FORMER_EMPLOYEE', 'MINOR')),
        subject_identifier VARCHAR(255) NOT NULL,  -- Email, user ID, or government ID
        subject_account_id UUID,
        subject_consent_id UUID,

        -- Request Details
        request_source VARCHAR(50) CHECK (request_source IN ('USER_PORTAL', 'EMAIL', 'SUPPORT_TICKET', 'REGULATOR', 'LEGAL_DEPARTMENT', 'AUTOMATED_EXPIRY')),
        request_channel VARCHAR(50),
        request_language CHAR(2),
        verification_method VARCHAR(50) CHECK (verification_method IN ('EMAIL_TOKEN', 'SMS_CODE', 'ID_DOCUMENT', 'NOTARIZED_LETTER', 'LEGAL_REPRESENTATIVE')),
        verification_completed_at TIMESTAMPTZ,
        verified_by UUID,

        -- Jurisdictional Context
        jurisdiction VARCHAR(3) NOT NULL,  -- ISO 3166-1 alpha-3
        applicable_laws TEXT[] DEFAULT '{GDPR}',
        data_subject_residence VARCHAR(3),

        -- Workflow State
        current_state erasure_state NOT NULL DEFAULT 'REQUEST_RECEIVED',
        previous_states erasure_state[] DEFAULT '{}',
        state_history JSONB DEFAULT '[]',

        -- Scope Definition
        data_categories_to_erase TEXT[] NOT NULL,
        data_categories_to_retain TEXT[] DEFAULT '{}',
        retention_justifications JSONB,  -- Legal basis for retaining specific data

        -- Cascade Management
        cascade_targets TEXT[] DEFAULT '{}',
        cascade_completed TEXT[] DEFAULT '{}',
        cascade_failed TEXT[] DEFAULT '{}',
        cascade_details JSONB,

        -- Legal Hold Detection
        legal_hold_detected BOOLEAN DEFAULT FALSE,
        legal_hold_ids UUID[],
        legal_hold_justification TEXT,
        legal_hold_end_date TIMESTAMPTZ,
        legal_hold_overridden BOOLEAN DEFAULT FALSE,
        legal_hold_override_authority UUID,

        -- Processing Timeline
        received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        verification_deadline TIMESTAMPTZ,
        completion_deadline TIMESTAMPTZ,  -- GDPR requires 30 days
        started_at TIMESTAMPTZ,
        completed_at TIMESTAMPTZ,
        escalation_at TIMESTAMPTZ,

        -- Erasure Execution
        execution_strategy VARCHAR(50) CHECK (execution_strategy IN ('PHYSICAL_DELETE', 'ANONYMIZATION', 'PSEUDONYMIZATION', 'BLOCKING', 'EXPORT_AND_DELETE')),
        records_erased_count BIGINT,
        records_retained_count BIGINT,
        erasure_log_reference VARCHAR(255),

        -- Third-Party Coordination
        third_party_notified TEXT[] DEFAULT '{}',
        third_party_confirmation TEXT[] DEFAULT '{}',
        data_processors_involved TEXT[] DEFAULT '{}',

        -- Certification & Audit
        completion_certificate TEXT,
        audit_required BOOLEAN DEFAULT FALSE,
        auditor_notes TEXT,
        regulator_notified BOOLEAN DEFAULT FALSE,
        notification_date TIMESTAMPTZ,

        -- Rejection Handling (if applicable)
        rejection_reason TEXT,
        rejection_appeal_deadline TIMESTAMPTZ,
        rejection_notification_sent BOOLEAN DEFAULT FALSE,

        -- Metadata
        priority INTEGER DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
        assigned_to UUID,
        team_notes TEXT,

        -- Audit Trail
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID NOT NULL,

        -- Constraints
        CONSTRAINT valid_erasure_timeline CHECK (
            completed_at IS NULL OR completed_at > received_at
        ),
        CONSTRAINT valid_legal_hold CHECK (
            (legal_hold_detected = FALSE) OR
            (legal_hold_detected = TRUE AND legal_hold_justification IS NOT NULL)
        ),
        CONSTRAINT valid_deadlines CHECK (
            completion_deadline IS NULL OR completion_deadline > received_at
        )
    );

    -- Indexes for gdpr_erasure_workflow
    CREATE INDEX idx_gdpr_subject_lookup ON gdpr_erasure_workflow(subject_identifier, subject_type);
    CREATE INDEX idx_gdpr_state_timing ON gdpr_erasure_workflow(current_state, completion_deadline) WHERE current_state NOT IN ('COMPLETED', 'REJECTED', 'EXPIRED');
    CREATE INDEX idx_gdpr_legal_hold ON gdpr_erasure_workflow(legal_hold_detected, legal_hold_end_date) WHERE legal_hold_detected = TRUE;
    CREATE INDEX idx_gdpr_jurisdiction ON gdpr_erasure_workflow(jurisdiction, applicable_laws);
    CREATE INDEX idx_gdpr_cascade_status ON gdpr_erasure_workflow(cascade_targets, cascade_completed);
    CREATE INDEX idx_gdpr_dates ON gdpr_erasure_workflow(received_at DESC, completion_deadline);

    -- Comments
    COMMENT ON TABLE gdpr_erasure_workflow IS 'State machine for GDPR right-to-erasure with cascade tracking and legal hold overrides';
    COMMENT ON COLUMN gdpr_erasure_workflow.request_id IS 'Unique identifier for each erasure request';
    COMMENT ON COLUMN gdpr_erasure_workflow.subject_identifier IS 'PII identifier - email, user ID, or government ID of the data subject';
    COMMENT ON COLUMN gdpr_erasure_workflow.current_state IS 'Current state in erasure workflow: REQUEST_RECEIVED, VERIFYING_IDENTITY, ASSESSING_SCOPE, etc.';
    COMMENT ON COLUMN gdpr_erasure_workflow.legal_hold_detected IS 'Whether data is under active legal hold preventing erasure';
    COMMENT ON COLUMN gdpr_erasure_workflow.completion_deadline IS 'GDPR requires completion within 30 days (Article 17)';

    -- RLS Policies
    ALTER TABLE gdpr_erasure_workflow ENABLE ROW LEVEL SECURITY;

    CREATE POLICY gdpr_privacy_team_access ON gdpr_erasure_workflow
        FOR ALL USING (current_setting('app.user_role') IN ('PRIVACY_OFFICER', 'DPO', 'SUPER_ADMIN', 'LEGAL_TEAM'));

    CREATE POLICY gdpr_auditor_readonly ON gdpr_erasure_workflow
        FOR SELECT USING (current_setting('app.user_role') = 'AUDITOR');

    CREATE POLICY gdpr_subject_self_service ON gdpr_erasure_workflow
        FOR SELECT USING (subject_identifier = current_setting('app.user_email'));

    -- State Transition Validation Trigger
    CREATE OR REPLACE FUNCTION validate_erasure_state_transition()
    RETURNS TRIGGER AS $$
    BEGIN
        -- Valid state transitions
        IF NOT (
            (OLD.current_state = 'REQUEST_RECEIVED' AND NEW.current_state IN ('VERIFYING_IDENTITY', 'REJECTED', 'EXPIRED')) OR
            (OLD.current_state = 'VERIFYING_IDENTITY' AND NEW.current_state IN ('ASSESSING_SCOPE', 'REJECTED')) OR
            (OLD.current_state = 'ASSESSING_SCOPE' AND NEW.current_state IN ('CHECKING_LEGAL_HOLD', 'REJECTED')) OR
            (OLD.current_state = 'CHECKING_LEGAL_HOLD' AND NEW.current_state IN ('IN_PROGRESS', 'AUDIT_REQUIRED', 'REJECTED')) OR
            (OLD.current_state = 'IN_PROGRESS' AND NEW.current_state IN ('PARTIAL_COMPLETION', 'COMPLETED', 'AUDIT_REQUIRED')) OR
            (OLD.current_state IN ('PARTIAL_COMPLETION', 'COMPLETED') AND NEW.current_state = 'AUDIT_REQUIRED')
        ) THEN
            RAISE EXCEPTION 'Invalid state transition from % to %', OLD.current_state, NEW.current_state;
        END IF;

        -- Record state history
        NEW.previous_states = OLD.previous_states || OLD.current_state;
        NEW.state_history = NEW.state_history || jsonb_build_object(
            'from_state', OLD.current_state,
            'to_state', NEW.current_state,
            'timestamp', CURRENT_TIMESTAMP,
            'changed_by', current_setting('app.current_user_id', TRUE)
        );

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER validate_gdpr_state_transition
        BEFORE UPDATE OF current_state ON gdpr_erasure_workflow
        FOR EACH ROW
        EXECUTE FUNCTION validate_erasure_state_transition();

    CREATE TRIGGER update_gdpr_updated_at
        BEFORE UPDATE ON gdpr_erasure_workflow
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -- ====================================================================================
    -- RELIABILITY & PERFORMANCE TABLES
    -- ====================================================================================

    -----------------------------------------------------------------------------------------------
    -- Serial No: 4
    -- Table Name: slo_error_budgets
    -- Description: Tracks SLO targets, burn rates, exhaustion alerts per service
    -- Business Case: Implements Google SRE methodology for managing service reliability through error
    --   budgets that quantify acceptable failure rates. The table tracks Service Level Objectives
    --   (SLOs) defined as success rate targets (e.g., 99.9% availability) and converts them into
    --   measurable error budgets (e.g., 0.1% error allowance over a compliance period). Burn rates
    --   measure how quickly the error budget is being consumed, enabling predictive alerts before
    --   budget exhaustion. When burn rates exceed predefined thresholds, the system triggers
    --   automated responses: reduced deployment velocity, increased testing rigor, or temporary
    --   feature degradation. The table supports multi-window SLO tracking (rolling 28 days, calendar
    --   month, trailing 7 days) to accommodate different business requirements. For example, an
    --   e-commerce platform might have stricter SLOs during Black Friday than normal operations.
    --   Integration with incident management means when error budgets are exhausted, standard
    --   change management processes are bypassed for reliability fixes. The table also supports
    --   budget reset policies for scheduled maintenance windows or after major incident remediation.
    --   Each service team can view their current budget status, consumption trends, and projected
    --   exhaustion dates, enabling data-driven decisions about feature releases versus reliability
    --   investments. For multi-tenant systems, budgets can be tracked per tenant to identify noisy
    --   neighbors impacting overall platform reliability.
    -- Key Performance Indicators (KPIs):
    --   1. Budget Consumption Rate - Percentage of error budget consumed (Target < 75% before reset)
    --   2. SLO Attainment Rate - Percentage of time periods meeting SLO targets (Target > 99.5%)
    --   3. Burn Rate Alerts - Number of high burn rate incidents per service per month
    --   4. Budget Reset Frequency - How often budgets are exhausted within compliance period
    --   5. Prediction Accuracy - Accuracy of projected exhaustion dates vs actual (Target > 90%)
    -- Feature References: REL01 (Service Level Objectives), REL02 (Error Budget Management), OPS02 (SRE Practices)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE slo_error_budgets (
        -- Primary Key
        budget_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Service Identification
        service_name VARCHAR(255) NOT NULL,
        service_owner_team VARCHAR(255),
        service_tier VARCHAR(50) CHECK (service_tier IN ('CRITICAL', 'HIGH', 'STANDARD', 'BEST_EFFORT')),
        environment VARCHAR(50) NOT NULL CHECK (environment IN ('PRODUCTION', 'STAGING', 'CANARY')),

        -- SLO Definition
        slo_name VARCHAR(255) NOT NULL,
        slo_type VARCHAR(50) CHECK (slo_type IN ('AVAILABILITY', 'LATENCY', 'THROUGHPUT', 'ERROR_RATE', 'DURABILITY')),
        slo_target_percentage NUMERIC(6,3) NOT NULL CHECK (slo_target_percentage >= 99.0 AND slo_target_percentage <= 100),
        error_budget_percentage NUMERIC(6,3) GENERATED ALWAYS AS (100 - slo_target_percentage) STORED,

        -- Compliance Window
        compliance_period_days INTEGER NOT NULL CHECK (compliance_period_days IN (7, 14, 28, 30, 90)),
        window_start_date DATE NOT NULL,
        window_end_date DATE GENERATED ALWAYS AS (window_start_date + compliance_period_days) STORED,

        -- Tracking Metrics
        total_requests BIGINT DEFAULT 0,
        error_requests BIGINT DEFAULT 0,
        success_requests BIGINT DEFAULT 0,
        current_error_rate_percentage NUMERIC(10,6) GENERATED ALWAYS AS (
            CASE WHEN total_requests > 0
            THEN (error_requests::NUMERIC / total_requests::NUMERIC) * 100
            ELSE 0 END
        ) STORED,

        -- Budget Consumption
        budget_consumed_percentage NUMERIC(10,6) GENERATED ALWAYS AS (
            CASE WHEN error_budget_percentage > 0
            THEN (current_error_rate_percentage / error_budget_percentage) * 100
            ELSE 0 END
        ) STORED,
        budget_remaining_percentage NUMERIC(10,6) GENERATED ALWAYS AS (
            100 - budget_consumed_percentage
        ) STORED,

        -- Burn Rate Analysis
        current_burn_rate NUMERIC(8,4) DEFAULT 0,  -- Multiple of acceptable burn rate
        burn_rate_window_minutes INTEGER DEFAULT 60,  -- Window for burn rate calculation
        projected_exhaustion_date DATE,

        -- Alert Thresholds
        warning_threshold INTEGER DEFAULT 50,  -- % consumed before warning alert
        critical_threshold INTEGER DEFAULT 75,  -- % consumed before critical alert
        exhaustion_threshold INTEGER DEFAULT 90,  -- % consumed before exhaustion alert

        -- Status
        budget_status error_budget_status NOT NULL DEFAULT 'HEALTHY',
        last_alert_sent_at TIMESTAMPTZ,
        last_alert_type VARCHAR(50),

        -- Response Actions
        auto_remediation_enabled BOOLEAN DEFAULT FALSE,
        deployment_freeze_active BOOLEAN DEFAULT FALSE,
        freeze_started_at TIMESTAMPTZ,
        mitigation_actions_taken TEXT[] DEFAULT '{}',

        -- Historical Tracking
        previous_budget_consumption NUMERIC(10,6),
        budget_reset_count INTEGER DEFAULT 0,
        last_reset_at TIMESTAMPTZ,

        -- Compliance & Reporting
        excludes_maintenance_windows BOOLEAN DEFAULT TRUE,
        maintenance_exempt_seconds BIGINT DEFAULT 0,
        mtbf_seconds BIGINT,  -- Mean Time Between Failures
        mttr_seconds BIGINT,  -- Mean Time To Repair

        -- Metadata
        slo_version INTEGER DEFAULT 1,
        documentation_url TEXT,
        notes TEXT,

        -- Audit Trail
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID NOT NULL,

        -- Constraints
        CONSTRAINT valid_burn_rate CHECK (current_burn_rate >= 0),
        CONSTRAINT valid_requests CHECK (total_requests = success_requests + error_requests),
        CONSTRAINT valid_thresholds CHECK (warning_threshold < critical_threshold AND critical_threshold < exhaustion_threshold),
        UNIQUE(service_name, slo_name, environment, window_start_date)
    );

    -- Indexes for slo_error_budgets
    CREATE INDEX idx_slo_service_active ON slo_error_budgets(service_name, environment, budget_status);
    CREATE INDEX idx_slo_exhaustion_projection ON slo_error_budgets(projected_exhaustion_date) WHERE projected_exhaustion_date IS NOT NULL;
    CREATE INDEX idx_slo_burn_rate ON slo_error_budgets(current_burn_rate DESC) WHERE current_burn_rate > 1.0;
    CREATE INDEX idx_slo_window ON slo_error_budgets(window_start_date, window_end_date);
    CREATE INDEX idx_slo_status_consumption ON slo_error_budgets(budget_status, budget_consumed_percentage);

    -- Comments
    COMMENT ON TABLE slo_error_budgets IS 'Tracks SLO targets, burn rates, and exhaustion alerts per service following Google SRE practices';
    COMMENT ON COLUMN slo_error_budgets.service_name IS 'Name of the service or microservice being tracked';
    COMMENT ON COLUMN slo_error_budgets.slo_target_percentage IS 'Target success rate (e.g., 99.9 for three nines availability)';
    COMMENT ON COLUMN slo_error_budgets.current_burn_rate IS 'Current rate of error budget consumption (1.0 = acceptable rate, >1.0 = consuming faster than allowed)';
    COMMENT ON COLUMN slo_error_budgets.budget_status IS 'HEALTHY(<50%), WARNING(50-75%), CRITICAL(75-90%), EXHAUSTED(90-100%)';
    COMMENT ON COLUMN slo_error_budgets.deployment_freeze_active IS 'Whether deployments are frozen due to budget exhaustion';

    -- RLS Policies
    ALTER TABLE slo_error_budgets ENABLE ROW LEVEL SECURITY;

    CREATE POLICY slo_admin_access ON slo_error_budgets
        FOR ALL USING (current_setting('app.user_role') IN ('SRE_ADMIN', 'PLATFORM_ENGINEER', 'SUPER_ADMIN'));

    CREATE POLICY slo_team_readonly ON slo_error_budgets
        FOR SELECT USING (service_owner_team = current_setting('app.user_team'));

    -- Budget Alert Trigger
    CREATE OR REPLACE FUNCTION check_budget_alerts()
    RETURNS TRIGGER AS $$
    BEGIN
        -- Check for threshold crossings
        IF NEW.budget_consumed_percentage >= NEW.exhaustion_threshold AND
           OLD.budget_consumed_percentage < NEW.exhaustion_threshold THEN
            NEW.last_alert_type = 'EXHAUSTION';
            NEW.last_alert_sent_at = CURRENT_TIMESTAMP;
            NEW.deployment_freeze_active = TRUE;
            NEW.freeze_started_at = CURRENT_TIMESTAMP;
        ELSIF NEW.budget_consumed_percentage >= NEW.critical_threshold AND
              OLD.budget_consumed_percentage < NEW.critical_threshold THEN
            NEW.last_alert_type = 'CRITICAL';
            NEW.last_alert_sent_at = CURRENT_TIMESTAMP;
        ELSIF NEW.budget_consumed_percentage >= NEW.warning_threshold AND
              OLD.budget_consumed_percentage < NEW.warning_threshold THEN
            NEW.last_alert_type = 'WARNING';
            NEW.last_alert_sent_at = CURRENT_TIMESTAMP;
        END IF;

        -- Update budget status based on consumption
        NEW.budget_status = CASE
            WHEN NEW.budget_consumed_percentage >= 90 THEN 'EXHAUSTED'::error_budget_status
            WHEN NEW.budget_consumed_percentage >= 75 THEN 'CRITICAL'::error_budget_status
            WHEN NEW.budget_consumed_percentage >= 50 THEN 'WARNING'::error_budget_status
            ELSE 'HEALTHY'::error_budget_status
        END;

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER check_slo_budget_alerts
        BEFORE UPDATE OF total_requests, error_requests ON slo_error_budgets
        FOR EACH ROW
        EXECUTE FUNCTION check_budget_alerts();

    CREATE TRIGGER update_slo_updated_at
        BEFORE UPDATE ON slo_error_budgets
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -----------------------------------------------------------------------------------------------
    -- Serial No: 5
    -- Table Name: cache_invalidation_events
    -- Description: Coordinates DB changes with Redis/CDN cache purge queues
    -- Business Case: Solves the distributed cache consistency problem where database updates must
    --   be reflected in multiple caching layers (Redis, CDN, application caches) without race
    --   conditions or stale data serving. The table acts as a reliable event bus for cache
    --   invalidation, ensuring that when data changes in the source of truth (database), all
    --   dependent cache entries are invalidated or updated. This is critical for systems where
    --   cache inconsistency could lead to incorrect business decisions, such as showing sold-out
    --   inventory as available or displaying stale pricing. The table supports transactional
    --   outbox pattern - database writes and invalidation events are committed in the same
    --   transaction, guaranteeing at-least-once invalidation delivery. Events are processed
    --   asynchronously by workers that handle different cache backends, with retry logic for
    --   transient failures. The system tracks invalidation scope (single entity vs entire
    --   collection vs pattern match) to minimize unnecessary cache purges. For CDN integrations,
    --   it manages purge requests with support for wildcard paths and cache tags. The table
    --   provides visibility into cache health through metrics like invalidation latency (time from
    --   DB change to cache purge), queue depth, and failure rates. For high-traffic systems, it
    --   supports batching and coalescing of multiple invalidations to prevent cache stampedes
    --   where many clients simultaneously request the same uncached data.
    -- Key Performance Indicators (KPIs):
    --   1. Invalidation Latency - Time from DB change to cache purge completion (p99 < 500ms)
    --   2. Cache Hit Rate After Invalidation - Cache effectiveness post-invalidation (Target > 95%)
    --   3. Stale Data Incidents - Number of events where stale data was served (Target 0)
    --   4. Queue Processing Rate - Events processed per second per worker
    --   5. Retry Success Rate - Percentage of failed invalidations successfully retried
    -- Feature References: PERF01 (Cache Management), PERF02 (Cache Consistency), REL03 (Eventual Consistency)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE cache_invalidation_events (
        -- Primary Key
        event_id BIGSERIAL PRIMARY KEY,
        event_uuid UUID DEFAULT gen_random_uuid() UNIQUE NOT NULL,

        -- Source Information
        source_system VARCHAR(100) NOT NULL,
        source_service VARCHAR(255) NOT NULL,
        source_instance VARCHAR(255),
        database_transaction_id BIGINT,

        -- Change Identification
        change_type VARCHAR(50) NOT NULL CHECK (change_type IN ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'BULK_UPDATE')),
        changed_table VARCHAR(255) NOT NULL,
        changed_entity_type VARCHAR(255) NOT NULL,
        changed_entity_ids TEXT[] NOT NULL,  -- Primary keys of changed entities

        -- Cache Target Specifications
        cache_type VARCHAR(50) NOT NULL CHECK (cache_type IN ('REDIS', 'CDN', 'MEMCACHED', 'IN_MEMORY', 'CLOUDFRONT', 'CLOUDFLARE', 'FASTLY')),
        cache_region VARCHAR(100),
        cache_cluster VARCHAR(255),

        -- Invalidation Scope
        invalidation_scope invalidation_scope NOT NULL DEFAULT 'ENTITY',
        cache_keys_to_invalidate TEXT[] DEFAULT '{}',
        cache_tags_to_invalidate TEXT[] DEFAULT '{}',
        pattern_to_invalidate TEXT,

        -- CDN Specific (when cache_type = 'CDN')
        cdn_distribution_id VARCHAR(255),
        cdn_paths_to_purge TEXT[] DEFAULT '{}',
        cdn_invalidation_id VARCHAR(255),

        -- Processing State
        processing_state VARCHAR(50) NOT NULL DEFAULT 'PENDING' CHECK (processing_state IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'SKIPPED', 'CANCELLED')),
        processing_attempts INTEGER DEFAULT 0,
        max_retry_attempts INTEGER DEFAULT 3,
        last_attempt_at TIMESTAMPTZ,
        next_retry_at TIMESTAMPTZ,

        -- Timing Metrics
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        queued_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
        started_at TIMESTAMPTZ,
        completed_at TIMESTAMPTZ,
        processing_duration_ms INTEGER,

        -- Performance Tracking
        invalidation_latency_ms INTEGER,  -- Time from create to complete
        backend_response_ms INTEGER,       -- Time for cache backend to respond
        batch_size INTEGER DEFAULT 1,

        -- Coalescing Support (combine multiple events)
        coalescing_group_id UUID,
        coalesced_events INTEGER DEFAULT 1,
        is_coalesced_master BOOLEAN DEFAULT FALSE,

        -- Error Handling
        error_code VARCHAR(100),
        error_message TEXT,
        error_stack TEXT,
        retry_strategy VARCHAR(50) DEFAULT 'EXPONENTIAL_BACKOFF',

        -- Ordering Guarantees
        sequence_number BIGSERIAL,
        partition_key VARCHAR(255) GENERATED ALWAYS AS (source_service) STORED,

        -- Observability
        trace_id UUID,
        span_id UUID,
        invalidation_worker_id VARCHAR(255),

        -- Metadata
        priority INTEGER DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
        requires_ordering BOOLEAN DEFAULT TRUE,
        notes TEXT,

        -- Constraints
        CONSTRAINT valid_cache_keys CHECK (
            (invalidation_scope != 'ENTITY') OR
            (invalidation_scope = 'ENTITY' AND array_length(cache_keys_to_invalidate, 1) > 0)
        ),
        CONSTRAINT valid_cdn_paths CHECK (
            (cache_type != 'CDN') OR
            (cache_type = 'CDN' AND array_length(cdn_paths_to_purge, 1) > 0)
        ),
        CONSTRAINT valid_retry_timing CHECK (
            (processing_state != 'FAILED') OR
            (processing_state = 'FAILED' AND next_retry_at IS NOT NULL)
        )
    );

    -- Indexes for cache_invalidation_events
    CREATE INDEX idx_cie_pending_processing ON cache_invalidation_events(processing_state, next_retry_at)
        WHERE processing_state IN ('PENDING', 'FAILED');
    CREATE INDEX idx_cie_entity_lookup ON cache_invalidation_events(changed_entity_type, changed_entity_ids);
    CREATE INDEX idx_cie_trace ON cache_invalidation_events(trace_id);
    CREATE INDEX idx_cie_created_at ON cache_invalidation_events(created_at DESC);
    CREATE INDEX idx_cie_coalescing ON cache_invalidation_events(coalescing_group_id) WHERE coalescing_group_id IS NOT NULL;
    CREATE INDEX idx_cie_sequence ON cache_invalidation_events(sequence_number);

    -- Comments
    COMMENT ON TABLE cache_invalidation_events IS 'Coordinates database changes with Redis/CDN cache purge queues for distributed cache consistency';
    COMMENT ON COLUMN cache_invalidation_events.event_id IS 'Auto-incrementing primary key for ordered processing';
    COMMENT ON COLUMN cache_invalidation_events.change_type IS 'Type of database change: INSERT, UPDATE, DELETE, BULK_UPDATE, TRUNCATE';
    COMMENT ON COLUMN cache_invalidation_events.invalidation_scope IS 'Scope of invalidation: ENTITY, COLLECTION, PATTERN, TENANT, GLOBAL, WILDCARD';
    COMMENT ON COLUMN cache_invalidation_events.processing_state IS 'Current state: PENDING, PROCESSING, COMPLETED, FAILED, SKIPPED, CANCELLED';
    COMMENT ON COLUMN cache_invalidation_events.coalescing_group_id IS 'Groups related events for batch processing optimization';

    -- RLS Policies
    ALTER TABLE cache_invalidation_events ENABLE ROW LEVEL SECURITY;

    CREATE POLICY cie_platform_access ON cache_invalidation_events
        FOR ALL USING (current_setting('app.user_role') IN ('PLATFORM_ENGINEER', 'SRE_ADMIN', 'SUPER_ADMIN'));

    CREATE POLICY cie_readonly_observability ON cache_invalidation_events
        FOR SELECT USING (current_setting('app.user_role') IN ('OBSERVABILITY_ENGINEER', 'DEVELOPER'));

    -- Coalescing Trigger (combine multiple invalidations for same entity in short time window)
    CREATE OR REPLACE FUNCTION coalesce_invalidation_events()
    RETURNS TRIGGER AS $$
    DECLARE
        existing_event_id BIGINT;
    BEGIN
        -- Look for existing pending event for same entity within last 5 seconds
        SELECT event_id INTO existing_event_id
        FROM cache_invalidation_events
        WHERE changed_entity_type = NEW.changed_entity_type
          AND changed_entity_ids = NEW.changed_entity_ids
          AND cache_type = NEW.cache_type
          AND processing_state = 'PENDING'
          AND created_at > (CURRENT_TIMESTAMP - INTERVAL '5 seconds')
        LIMIT 1;

        IF existing_event_id IS NOT NULL THEN
            -- Coalesce: update existing event rather than creating new one
            UPDATE cache_invalidation_events
            SET coalesced_events = coalesced_events + 1,
                updated_at = CURRENT_TIMESTAMP
            WHERE event_id = existing_event_id;

            -- Skip inserting new event
            RETURN NULL;
        END IF;

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER coalesce_pending_invalidations
        BEFORE INSERT ON cache_invalidation_events
        FOR EACH ROW
        EXECUTE FUNCTION coalesce_invalidation_events();

    CREATE TRIGGER update_cie_updated_at
        BEFORE UPDATE ON cache_invalidation_events
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -----------------------------------------------------------------------------------------------
    -- Serial No: 6
    -- Table Name: rate_limit_enforcement_log
    -- Description: Records blocked/throttled requests for security & billing analytics
    -- Business Case: Provides comprehensive logging of rate-limited requests for security
    --   monitoring, billing enforcement, and capacity planning. When API rate limits are exceeded,
    --   this table captures detailed information about the violating request, enabling security
    --   teams to identify potential DoS attacks or credential stuffing, billing teams to enforce
    --   usage-based pricing tiers, and engineering teams to optimize rate limit thresholds. The
    --   table supports different rate limiting strategies (token bucket, sliding window, fixed
    --   window, leaky bucket) and records the specific action taken (block, delay, degrade,
    --   circuit breaker). This data feeds security analytics dashboards that detect anomalous
    --   patterns like sudden traffic spikes from single IPs, multiple accounts from same IP,
    --   or requests coming from known malicious IP ranges. For multi-tenant SaaS platforms, it
    --   enables fair usage monitoring and identifies noisy neighbors that might impact other
    --   customers. The billing integration uses this log to track overage usage for pay-as-you-go
    --   pricing models, automatically generating invoices for customers who exceed their plan
    --   limits. The table also serves as input for automated rate limit tuning, with machine
    --   learning models analyzing historical patterns to suggest optimal thresholds that maximize
    --   throughput while protecting system stability. Data retention policies balance compliance
    --   needs against storage costs - typically 90 days for operational analytics and 7 years for
    --   security investigations.
    -- Key Performance Indicators (KPIs):
    --   1. Throttle Rate - Percentage of requests being throttled vs total requests
    --   2. Top Throttle Sources - IP addresses, API keys, or tenants with highest throttle counts
    --   3. Billing Overage Revenue - Revenue generated from rate limit overages
    --   4. False Positive Rate - Legitimate requests incorrectly throttled
    --   5. Attack Detection Accuracy - Rate of correctly identified malicious patterns
    -- Feature References: SEC02 (Rate Limiting), SEC05 (DDoS Protection), BILL01 (Usage-Based Billing)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE rate_limit_enforcement_log (
        -- Primary Key
        log_id BIGSERIAL PRIMARY KEY,
        log_uuid UUID DEFAULT gen_random_uuid() UNIQUE NOT NULL,

        -- Request Identification
        request_id UUID NOT NULL,
        trace_id UUID,
        correlation_id UUID,

        -- Rate Limit Context
        rate_limit_key VARCHAR(255) NOT NULL,  -- e.g., IP:192.168.1.1, API_KEY:abc123, TENANT:tenant_id
        rate_limit_type VARCHAR(50) NOT NULL CHECK (rate_limit_type IN ('IP', 'API_KEY', 'USER_ID', 'TENANT', 'ENDPOINT', 'GLOBAL', 'CUSTOM')),

        -- Limit Configuration at Time of Request
        configured_limit INTEGER NOT NULL,
        configured_window_seconds INTEGER NOT NULL,
        current_count INTEGER NOT NULL,  -- Requests in current window
        algorithm_type VARCHAR(50) CHECK (algorithm_type IN ('TOKEN_BUCKET', 'SLIDING_WINDOW', 'FIXED_WINDOW', 'LEAKY_BUCKET', 'SLIDING_LOG')),

        -- Action Taken
        throttle_action throttle_action NOT NULL,
        retry_after_seconds INTEGER,  -- For BLOCK/REJECT actions
        delay_applied_ms INTEGER,      -- For DELAY action
        degraded_response BOOLEAN DEFAULT FALSE,

        -- Request Details
        http_method VARCHAR(10) NOT NULL,
        endpoint_path VARCHAR(500) NOT NULL,
        endpoint_pattern VARCHAR(255),
        request_size_bytes INTEGER,
        response_status_code INTEGER,

        -- Client Identification
        client_ip INET NOT NULL,
        client_port INTEGER,
        user_agent TEXT,
        authorization_type VARCHAR(50),  -- Bearer, Basic, API-Key, etc.
        api_key_hash VARCHAR(128),
        oauth_client_id VARCHAR(255),

        -- Tenant Context
        tenant_id UUID,
        tenant_plan VARCHAR(50),
        tenant_tier VARCHAR(50),

        -- Request Classification
        request_priority VARCHAR(20) CHECK (request_priority IN ('CRITICAL', 'HIGH', 'NORMAL', 'LOW', 'BATCH')),
        request_source VARCHAR(50) CHECK (request_source IN ('CLIENT', 'WEBHOOK', 'INTERNAL_SERVICE', 'ADMIN_API', 'BATCH_JOB')),

        -- Security Detection
        threat_score NUMERIC(5,2),  -- 0-100, higher = more suspicious
        detection_rules_triggered TEXT[],
        known_attacker_ip BOOLEAN DEFAULT FALSE,
        known_bot_user_agent BOOLEAN DEFAULT FALSE,

        -- Billing Impact
        billing_recorded BOOLEAN DEFAULT FALSE,
        overage_units INTEGER DEFAULT 0,
        overage_cost_microcents BIGINT,  -- Store in microcents for precision
        billing_reference VARCHAR(255),

        -- Geographic Information
        geo_country_code CHAR(2),
        geo_city VARCHAR(100),
        geo_continent_code CHAR(2),
        asn_number INTEGER,  -- Autonomous System Number
        asn_organization VARCHAR(255),

        -- Rate Limit Bucket Snapshot (for debugging)
        bucket_snapshot JSONB,

        -- Performance Metrics
        rate_limit_check_latency_ms INTEGER NOT NULL,
        total_request_latency_ms INTEGER,

        -- Decision Engine
        decision_version VARCHAR(50),
        decision_engine VARCHAR(255),

        -- Observability
        log_ingestion_timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
        log_retention_days INTEGER DEFAULT 90,

        -- Metadata
        environment VARCHAR(50) NOT NULL CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT')),
        region VARCHAR(50),
        notes TEXT,

        -- Audit Trail (Append-only, no updates)
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

        -- Constraints
        CONSTRAINT valid_rate_limit_data CHECK (
            throttle_action != 'RETRY_AFTER' OR
            (throttle_action = 'RETRY_AFTER' AND retry_after_seconds IS NOT NULL)
        ),
        CONSTRAINT valid_threat_score CHECK (
            threat_score >= 0 AND threat_score <= 100
        ),
        CONSTRAINT valid_size CHECK (
            request_size_bytes >= 0
        )
    );

    -- Indexes for rate_limit_enforcement_log
    CREATE INDEX idx_rl_tenant_lookup ON rate_limit_enforcement_log(tenant_id, created_at DESC);
    CREATE INDEX idx_rl_threat_analysis ON rate_limit_enforcement_log(threat_score, known_attacker_ip) WHERE threat_score > 50;
    CREATE INDEX idx_rl_ip_timing ON rate_limit_enforcement_log(client_ip, created_at DESC);
    CREATE INDEX idx_rl_billing ON rate_limit_enforcement_log(billing_recorded, created_at) WHERE billing_recorded = FALSE;
    CREATE INDEX idx_rl_endpoint_analysis ON rate_limit_enforcement_log(endpoint_pattern, throttle_action, created_at);
    CREATE INDEX idx_rl_geo ON rate_limit_enforcement_log(geo_country_code, created_at);
    CREATE INDEX idx_rl_created_at ON rate_limit_enforcement_log(created_at DESC);

    -- Comments
    COMMENT ON TABLE rate_limit_enforcement_log IS 'Records blocked and throttled requests for security monitoring, billing analytics, and capacity planning';
    COMMENT ON COLUMN rate_limit_enforcement_log.request_id IS 'Unique identifier for the original request (for tracing)';
    COMMENT ON COLUMN rate_limit_enforcement_log.rate_limit_key IS 'The key used for rate limiting (e.g., IP address, API key, tenant ID)';
    COMMENT ON COLUMN rate_limit_enforcement_log.throttle_action IS 'Action taken: BLOCK, DELAY, DEGRADE, REJECT, CIRCUIT_OPEN, REDIRECT';
    COMMENT ON COLUMN rate_limit_enforcement_log.threat_score IS 'Security threat score (0-100) based on request patterns and intelligence feeds';
    COMMENT ON COLUMN rate_limit_enforcement_log.overage_cost_microcents IS 'Monetary value of overage in microcents (1 microcent = $0.00000001) for precise billing';

    -- RLS Policies
    ALTER TABLE rate_limit_enforcement_log ENABLE ROW LEVEL SECURITY;

    CREATE POLICY rl_security_team_access ON rate_limit_enforcement_log
        FOR ALL USING (current_setting('app.user_role') IN ('SECURITY_ADMIN', 'SUPER_ADMIN'));

    CREATE POLICY rl_billing_team_read ON rate_limit_enforcement_log
        FOR SELECT USING (current_setting('app.user_role') = 'BILLING_ADMIN');

    CREATE POLICY rl_tenant_self_read ON rate_limit_enforcement_log
        FOR SELECT USING (tenant_id = current_setting('app.tenant_id')::UUID);

    -- Partitioning by date for retention management (PostgreSQL 10+)
    -- Note: This creates a parent table - actual partitions should be created monthly
    -- CREATE TABLE rate_limit_enforcement_log_2024_01 PARTITION OF rate_limit_enforcement_log
    --     FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');

    -- Retention cleanup function
    CREATE OR REPLACE FUNCTION cleanup_old_rate_limit_logs()
    RETURNS void AS $$
    BEGIN
        DELETE FROM rate_limit_enforcement_log
        WHERE created_at < (CURRENT_TIMESTAMP - (log_retention_days || ' days')::INTERVAL);
    END;
    $$ LANGUAGE plpgsql;

    COMMENT ON FUNCTION cleanup_old_rate_limit_logs() IS 'Automated cleanup of rate limit logs based on retention policy';


    -- ====================================================================================
    -- GOVERNANCE & AUDIT TABLES
    -- ====================================================================================

    -----------------------------------------------------------------------------------------------
    -- Serial No: 7
    -- Table Name: data_quality_enforcement_jobs
    -- Description: Automated DQ rule execution, remediation scripts, SLA tracking
    -- Business Case: Operationalizes data quality management by automating the execution of
    --   quality rules, tracking compliance SLAs, and triggering remediation actions when violations
    --   occur. This table serves as the control plane for the enterprise data quality framework,
    --   ensuring that data entering or flowing through systems meets defined standards for
    --   accuracy, completeness, consistency, timeliness, and validity. Each job represents a
    --   scheduled or triggered execution of data quality rules against specific data assets,
    --   with detailed tracking of rule outcomes, violation counts, and severity levels. The
    --   remediation integration is critical - when quality issues are detected, the system can
    --   automatically execute pre-defined remediation scripts (e.g., standardize address formats,
    --   fill missing values from reference data, or quarantine suspect records). For violations
    --   requiring human review, it creates tickets in integrated ITSM systems. SLA tracking
    --   enforces business commitments around data quality - for example, "customer data must be
    --   99% complete within 24 hours of ingestion" - with breach notifications and escalation.
    --   The table supports incremental execution (only checking new/changed data since last run)
    --   to minimize compute costs for large datasets. Job history enables trend analysis, showing
    --   whether data quality is improving or degrading over time, and helps identify systemic
    --   issues in upstream systems. For regulated industries, the complete execution history
    --   serves as audit evidence for data governance compliance.
    -- Key Performance Indicators (KPIs):
    --   1. DQ Rule Pass Rate - Percentage of quality rules passing across all jobs
    --   2. Remediation Success Rate - Percentage of auto-remediation attempts that succeed
    --   3. Mean Time to Detect - Average time from data ingestion to violation detection
    --   4. Mean Time to Remediate - Average time from violation to resolution
    --   5. SLA Compliance Rate - Percentage of quality SLAs met within defined windows
    -- Feature References: DG01 (Data Quality Management), DG03 (Data Governance), OPS03 (Automated Remediation)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE data_quality_enforcement_jobs (
        -- Primary Key
        job_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
        execution_id UUID DEFAULT gen_random_uuid() UNIQUE NOT NULL,

        -- Job Identification
        job_name VARCHAR(255) NOT NULL,
        job_type VARCHAR(50) NOT NULL CHECK (job_type IN ('SCHEDULED', 'TRIGGERED', 'ON_DEMAND', 'STREAMING', 'BATCH')),
        data_domain VARCHAR(100) NOT NULL,  -- Customer, Product, Vendor, Financial, etc.

        -- Rule Configuration
        data_quality_ruleset_id UUID NOT NULL,
        rules_executed TEXT[] NOT NULL,
        rules_passed TEXT[],
        rules_failed TEXT[],

        -- Data Asset Identification
        target_table VARCHAR(255),
        target_schema VARCHAR(255),
        target_database VARCHAR(255),
        data_partition_expression VARCHAR(500),  -- For incremental processing
        row_count_processed BIGINT DEFAULT 0,
        column_count_evaluated INTEGER DEFAULT 0,

        -- Quality Metrics
        overall_score NUMERIC(5,2) CHECK (overall_score >= 0 AND overall_score <= 100),
        completeness_percentage NUMERIC(5,2),
        accuracy_percentage NUMERIC(5,2),
        consistency_percentage NUMERIC(5,2),
        timeliness_percentage NUMERIC(5,2),
        validity_percentage NUMERIC(5,2),
        uniqueness_percentage NUMERIC(5,2),

        -- Violation Tracking
        total_violations INTEGER DEFAULT 0,
        blocker_violations INTEGER DEFAULT 0,
        critical_violations INTEGER DEFAULT 0,
        high_violations INTEGER DEFAULT 0,
        medium_violations INTEGER DEFAULT 0,
        low_violations INTEGER DEFAULT 0,

        -- Remediation
        auto_remediation_attempted BOOLEAN DEFAULT FALSE,
        auto_remediation_successful BOOLEAN DEFAULT FALSE,
        auto_remediation_script TEXT,
        manual_remediation_required BOOLEAN DEFAULT FALSE,
        remediation_ticket_id VARCHAR(255),
        remediation_assigned_to UUID,
        remediation_completed_at TIMESTAMPTZ,

        -- SLA Tracking
        sla_completion_deadline TIMESTAMPTZ,
        sla_met BOOLEAN,
        sla_business_hours_only BOOLEAN DEFAULT TRUE,
        breach_notification_sent BOOLEAN DEFAULT FALSE,

        -- Execution Details
        execution_status VARCHAR(50) NOT NULL CHECK (execution_status IN ('SCHEDULED', 'RUNNING', 'COMPLETED', 'FAILED', 'PARTIAL', 'CANCELLED')),
        execution_mode VARCHAR(50) CHECK (execution_mode IN ('FULL_SCAN', 'INCREMENTAL', 'SAMPLE_BASED', 'CONTINUOUS')),
        started_at TIMESTAMPTZ,
        completed_at TIMESTAMPTZ,
        execution_duration_seconds INTEGER,

        -- Performance Metrics
        data_scan_time_ms BIGINT,
        rule_evaluation_time_ms BIGINT,
        remediation_time_ms BIGINT,
        total_compute_units DECIMAL(10,2),

        -- Resource Usage
        worker_nodes INTEGER,
        memory_usage_mb INTEGER,
        cpu_utilization_percentage NUMERIC(5,2),

        -- Notification Config
        notify_on_success BOOLEAN DEFAULT FALSE,
        notify_on_failure BOOLEAN DEFAULT TRUE,
        notify_emails TEXT[],
        notify_slack_channels TEXT[],

        -- Logging & Observability
        execution_log_url TEXT,
        error_details TEXT,
        sample_failed_records JSONB,  -- Sample of records that failed (no complete data)

        -- Metadata
        priority INTEGER DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
        created_by_trigger VARCHAR(255),
        notes TEXT,

        -- Audit Trail
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID NOT NULL,

        -- Constraints
        CONSTRAINT valid_execution_timing CHECK (
            (execution_status NOT IN ('COMPLETED', 'FAILED', 'PARTIAL')) OR
            (execution_status IN ('COMPLETED', 'FAILED', 'PARTIAL') AND started_at IS NOT NULL AND completed_at IS NOT NULL AND completed_at > started_at)
        ),
        CONSTRAINT valid_scores CHECK (
            (overall_score BETWEEN 0 AND 100) OR overall_score IS NULL
        )
    );

    -- Indexes for data_quality_enforcement_jobs
    CREATE INDEX idx_dqe_job_name ON data_quality_enforcement_jobs(job_name, created_at DESC);
    CREATE INDEX idx_dqe_sla_monitoring ON data_quality_enforcement_jobs(sla_completion_deadline, sla_met) WHERE sla_met = FALSE AND execution_status = 'COMPLETED';
    CREATE INDEX idx_dqe_remediation ON data_quality_enforcement_jobs(manual_remediation_required, remediation_completed_at) WHERE manual_remediation_required = TRUE;
    CREATE INDEX idx_dqe_data_domain ON data_quality_enforcement_jobs(data_domain, execution_status);
    CREATE INDEX idx_dqe_score ON data_quality_enforcement_jobs(overall_score DESC) WHERE overall_score IS NOT NULL;
    CREATE INDEX idx_dqe_ticket ON data_quality_enforcement_jobs(remediation_ticket_id) WHERE remediation_ticket_id IS NOT NULL;

    -- Comments
    COMMENT ON TABLE data_quality_enforcement_jobs IS 'Automated data quality rule execution with remediation scripts and SLA tracking';
    COMMENT ON COLUMN data_quality_enforcement_jobs.job_name IS 'Human-readable name of the data quality job';
    COMMENT ON COLUMN data_quality_enforcement_jobs.overall_score IS 'Aggregate data quality score (0-100) for this execution';
    COMMENT ON COLUMN data_quality_enforcement_jobs.auto_remediation_attempted IS 'Whether automated remediation was attempted on detected issues';
    COMMENT ON COLUMN data_quality_enforcement_jobs.sla_met IS 'Whether the execution completed within defined SLA timeframe';
    COMMENT ON COLUMN data_quality_enforcement_jobs.execution_mode IS 'FULL_SCAN, INCREMENTAL (changed data only), SAMPLE_BASED, or CONTINUOUS (streaming)';

    -- RLS Policies
    ALTER TABLE data_quality_enforcement_jobs ENABLE ROW LEVEL SECURITY;

    CREATE POLICY dqe_data_governance_access ON data_quality_enforcement_jobs
        FOR ALL USING (current_setting('app.user_role') IN ('DATA_GOVERNANCE', 'DATA_ENGINEER', 'SUPER_ADMIN'));

    CREATE POLICY dqe_team_read ON data_quality_enforcement_jobs
        FOR SELECT USING (data_domain IN (SELECT domain FROM user_data_domains WHERE user_id = current_setting('app.current_user_id')::UUID));

    -- Update trigger
    CREATE TRIGGER update_dqe_updated_at
        BEFORE UPDATE ON data_quality_enforcement_jobs
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


    -----------------------------------------------------------------------------------------------
    -- Serial No: 8
    -- Table Name: data_lineage_provenance
    -- Description: Automated column/table lineage tracking via SQL parsing + pipeline metadata
    -- Business Case: Provides complete end-to-end data lineage and provenance tracking for every
    --   data asset in the enterprise, enabling impact analysis, root cause identification, and
    --   regulatory compliance (BCBS 239, GDPR Article 30, CCPA). The table captures how data flows
    --   from source systems through transformation pipelines to downstream consumers, maintaining
    --   historical records of field-level transformations, joins, filters, and aggregations.
    --   Automated lineage detection uses SQL parsers that analyze transformation logic in ETL jobs,
    --   data warehouse queries, and streaming pipelines to infer dependencies. For complex systems
    --   where automated detection has uncertainty, the lineage_confidence field indicates confidence
    --   levels, with pending verification items requiring human confirmation. This lineage graph
    --   enables critical governance functions: when a source system changes, impacted downstream
    --   tables and reports can be identified; when data quality issues emerge, upstream sources
    --   can be traced; and when regulatory requests ask "where does this data come from?", answers
    --   are readily available. The table supports column-level lineage (tracking that 'customer_name'
    --   in the warehouse comes from CONCAT(first_name, last_name) in the source) and row-level
    --   provenance for GDPR compliance (showing which source records contributed to a given output).
    --   Integration with data catalogs provides business users visibility into data asset trustworthiness.
    --   The complete lineage history enables temporal queries - "what did the pipeline look like
    --   on this date?" - critical for auditing historical calculations.
    -- Key Performance Indicators (KPIs):
    --   1. Lineage Coverage - Percentage of tables/columns with documented lineage (Target 100%)
    --   2. Impact Analysis Speed - Time to identify downstream impacts of source changes (p95 < 5s)
    --   3. Automated Detection Accuracy - Percentage of automatically detected lineage confirmed correct
    --   4. Lineage freshness - Time between pipeline changes and lineage updates
    --   5. Regulatory Response Time - Time to provide data provenance for subject access requests
    -- Feature References: DG02 (Data Lineage), DG04 (Data Catalog), COMP05 (Regulatory Compliance)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE data_lineage_provenance (
        -- Primary Key
        lineage_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Asset Identification
        source_system VARCHAR(255) NOT NULL,
        source_database VARCHAR(255),
        source_schema VARCHAR(255),
        source_table VARCHAR(255) NOT NULL,
        source_column VARCHAR(255),
        source_primary_key VARCHAR(255),

        -- Target Identification
        target_system VARCHAR(255) NOT NULL,
        target_database VARCHAR(255),
        target_schema VARCHAR(255),
        target_table VARCHAR(255) NOT NULL,
        target_column VARCHAR(255),

        -- Transformation Details
        transformation_type VARCHAR(50) CHECK (transformation_type IN ('DIRECT_MAP', 'JOIN', 'AGGREGATE', 'FILTER', 'CALCULATED', 'CONCATENATION', 'SPLIT', 'LOOKUP', 'CUSTOM_LOGIC')),
        transformation_logic TEXT,  -- SQL expression or transformation description
        transformation_expression VARCHAR(5000),  -- Actual SQL/Code expression
        joined_tables TEXT[],  -- For JOIN transformation_type
        aggregation_functions TEXT[],  -- For AGGREGATE transformation_type
        filter_conditions TEXT[],  -- For FILTER transformation_type

        -- Pipeline Context (how lineage was discovered)
        pipeline_id VARCHAR(255),
        pipeline_name VARCHAR(255),
        pipeline_type VARCHAR(50) CHECK (pipeline_type IN ('ETL', 'ELT', 'STREAMING', 'BATCH', 'REPLICATION', 'CDC', 'VIEW')),
        pipeline_version VARCHAR(50),
        execution_frequency VARCHAR(50),

        -- Confidence & Verification
        lineage_confidence lineage_confidence NOT NULL DEFAULT 'MEDIUM',
        detection_method VARCHAR(50) CHECK (detection_method IN ('SQL_PARSER', 'CATALOG_METADATA', 'MANUAL_ENTRY', 'RUNTIME_TRACING', 'INFERRED_PATTERNS')),
        verified_by_human BOOLEAN DEFAULT FALSE,
        verified_at TIMESTAMPTZ,
        verified_by UUID,

        -- Lineage Graph (for complex dependencies)
        dependency_depth INTEGER DEFAULT 1,
        lineage_path TEXT[],
        is_circular_dependency BOOLEAN DEFAULT FALSE,

        -- Data Flow Characteristics
        is_one_to_one BOOLEAN DEFAULT TRUE,
        data_volume_estimate NUMERIC(20,2),  -- Rows per execution
        latency_seconds INTEGER,  -- Time from source to target
        is_incremental BOOLEAN DEFAULT FALSE,

        -- Quality Tags
        data_quality_score NUMERIC(5,2),
        freshness_score NUMERIC(5,2),
        trust_score NUMERIC(5,2) GENERATED ALWAYS AS (
            (CASE WHEN lineage_confidence = 'CONFIRMED' THEN 100
                  WHEN lineage_confidence = 'HIGH' THEN 80
                  WHEN lineage_confidence = 'MEDIUM' THEN 60
                  WHEN lineage_confidence = 'LOW' THEN 40
                  ELSE 20 END) * 0.4 +
            (COALESCE(data_quality_score, 0)) * 0.3 +
            (COALESCE(freshness_score, 0)) * 0.3
        ) STORED,

        -- Business Metadata
        business_criticality VARCHAR(20) CHECK (business_criticality IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW')),
        pii_classification VARCHAR(50) CHECK (pii_classification IN ('PII', 'PHI', 'FINANCIAL', 'NON_PII', 'RESTRICTED')),
        regulatory_classification TEXT[] DEFAULT '{}',

        -- Historical Tracking
        lineage_version INTEGER DEFAULT 1,
        valid_from TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        valid_to TIMESTAMPTZ,
        is_current BOOLEAN DEFAULT TRUE,
        superseded_by UUID,

        -- Metadata
        documentation TEXT,
        lineage_hash VARCHAR(64),  -- Hash of source+target+transformation for deduplication

        -- Audit Trail
        detected_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID,
        updated_by UUID,

        -- Constraints
        CONSTRAINT valid_lineage_asset CHECK (
            source_table IS NOT NULL AND target_table IS NOT NULL
        ),
        CONSTRAINT valid_temporal CHECK (
            valid_to IS NULL OR valid_to > valid_from
        ),
        CONSTRAINT valid_confidence CHECK (
            (lineage_confidence != 'PENDING_VERIFICATION') OR
            (lineage_confidence = 'PENDING_VERIFICATION' AND verified_by_human = FALSE)
        ),
        UNIQUE(source_system, source_database, source_schema, source_table, source_column,
               target_system, target_database, target_schema, target_table, target_column)
    );

    -- Indexes for data_lineage_provenance
    CREATE INDEX idx_dlp_source_lookup ON data_lineage_provenance(source_system, source_table, source_column);
    CREATE INDEX idx_dlp_target_lookup ON data_lineage_provenance(target_system, target_table, target_column);
    CREATE INDEX idx_dlp_current_active ON data_lineage_provenance(is_current, lineage_confidence) WHERE is_current = TRUE;
    CREATE INDEX idx_dlp_pipeline ON data_lineage_provenance(pipeline_id, pipeline_version);
    CREATE INDEX idx_dlp_trust_score ON data_lineage_provenance(trust_score DESC) WHERE is_current = TRUE;
    CREATE INDEX idx_dlp_regulatory ON data_lineage_provenance(regulatory_classification, pii_classification);
    CREATE INDEX idx_dlp_dependency ON data_lineage_provenance(dependency_depth, lineage_path);
    CREATE INDEX idx_dlp_hash ON data_lineage_provenance(lineage_hash);

    -- Comments
    COMMENT ON TABLE data_lineage_provenance IS 'Automated column and table lineage tracking via SQL parsing and pipeline metadata';
    COMMENT ON COLUMN data_lineage_provenance.source_system IS 'Source system containing the origin data';
    COMMENT ON COLUMN data_lineage_provenance.transformation_type IS 'Type of transformation: DIRECT_MAP, JOIN, AGGREGATE, FILTER, CALCULATED, etc.';
    COMMENT ON COLUMN data_lineage_provenance.lineage_confidence IS 'Confidence level: CONFIRMED (verified), HIGH/MEDIUM/LOW (auto-detected), PENDING_VERIFICATION';
    COMMENT ON COLUMN data_lineage_provenance.trust_score IS 'Aggregate trust score (0-100) based on lineage confidence, data quality, and freshness';
    COMMENT ON COLUMN data_lineage_provenance.is_current IS 'Whether this lineage record represents the current state (for temporal queries)';

    -- RLS Policies
    ALTER TABLE data_lineage_provenance ENABLE ROW LEVEL SECURITY;

    CREATE POLICY dlp_data_governance_full ON data_lineage_provenance
        FOR ALL USING (current_setting('app.user_role') IN ('DATA_GOVERNANCE', 'DATA_ARCHITECT', 'SUPER_ADMIN'));

    CREATE POLICY dlp_readonly_analyst ON data_lineage_provenance
        FOR SELECT USING (current_setting('app.user_role') IN ('DATA_ANALYST', 'DATA_SCIENTIST', 'BUSINESS_USER'));

    -- Trigger to handle versioning (when a lineage changes, old becomes historical)
    CREATE OR REPLACE FUNCTION version_lineage_records()
    RETURNS TRIGGER AS $$
    BEGIN
        -- Mark existing current record as historical
        UPDATE data_lineage_provenance
        SET is_current = FALSE,
            valid_to = CURRENT_TIMESTAMP
        WHERE source_system = NEW.source_system
          AND source_schema = NEW.source_schema
          AND source_table = NEW.source_table
          AND target_system = NEW.target_system
          AND target_table = NEW.target_table
          AND is_current = TRUE;

        -- Set new record as current
        NEW.is_current = TRUE;
        NEW.lineage_version = COALESCE(
            (SELECT MAX(lineage_version) + 1
             FROM data_lineage_provenance
             WHERE source_system = NEW.source_system
               AND target_system = NEW.target_system), 1);

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER version_dlp_records
        BEFORE INSERT ON data_lineage_provenance
        FOR EACH ROW
        EXECUTE FUNCTION version_lineage_records();

    CREATE TRIGGER update_dlp_updated_at
        BEFORE UPDATE ON data_lineage_provenance
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();

    -- Materialized View for common lineage queries (performance optimization)
    CREATE MATERIALIZED VIEW mv_data_lineage_summary AS
    SELECT
        target_table,
        COUNT(DISTINCT source_table) as source_table_count,
        COUNT(*) as lineage_record_count,
        AVG(trust_score) as avg_trust_score,
        MAX(detected_at) as last_lineage_update
    FROM data_lineage_provenance
    WHERE is_current = TRUE
    GROUP BY target_table
    WITH DATA;

    CREATE UNIQUE INDEX idx_mv_dls_target ON mv_data_lineage_summary(target_table);

    COMMENT ON MATERIALIZED VIEW mv_data_lineage_summary IS 'Pre-aggregated lineage summary for performance-critical queries';


    -----------------------------------------------------------------------------------------------
    -- Serial No: 9
    -- Table Name: compliance_certification_registry
    -- Description: Tracks SOC2, ISO27001, PCI-DSS audit cycles, evidence, expiry
    -- Business Case: Centralized management of compliance certifications across the organization,
    --   providing real-time visibility into certification status, audit readiness, and expiration
    --   risks. This table is critical for companies serving regulated industries (financial services,
    --   healthcare, government) where certification lapses can trigger contract violations, revenue
    --   loss, or regulatory penalties. It tracks the complete lifecycle of each certification:
    --   initial planning, pre-audit assessments, formal audit dates, findings remediation,
    --   certification issuance, and periodic renewals. For each certification, it maintains links
    --   to supporting evidence artifacts, control mappings, and responsible parties. The evidence
    --   tracking ensures audit-readiness by identifying gaps in documentation and automatically
    --   requesting updated evidence before expiration. Integration with monitoring systems provides
    --   continuous compliance checks - for example, verifying that encryption standards required by
    --   SOC2 remain in place between audits. Expiry tracking with graduated alerting (30/60/90 days
    --   before expiration) prevents accidental lapses and enables proactive renewal planning. The
    --   registry also tracks audit findings from each cycle, including severity ratings, remediation
    --   plans, and closure verification. For multi-cloud or multi-region deployments, it supports
    --   per-scope certifications (e.g., "SOC2 - US-East region only"). Audit reports and certificates
    --   are stored as references with checksums for integrity verification. Regulatory mapping
    --   capabilities allow filtering certifications applicable to specific regulations or customer
    --   requirements.
    -- Key Performance Indicators (KPIs):
    --   1. Certification Coverage - Percentage of required certifications active (Target 100%)
    --   2. Audit Cycle Compliance - Percentage of audits completed within required timeframe
    --   3. Finding Remediation Time - Average time to address audit findings (Target < 30 days)
    --   4. Evidence Freshness - Percentage of evidence artifacts renewed before expiry
    --   5. Customer Audit Response Time - Time to provide certification evidence to customers
    -- Feature References: COMP01 (Compliance Management), COMP06 (Audit Management), SEC06 (Security Certifications)
    -----------------------------------------------------------------------------------------------
    CREATE TABLE compliance_certification_registry (
        -- Primary Key
        certification_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

        -- Certification Identification
        certification_standard VARCHAR(50) NOT NULL CHECK (certification_standard IN ('SOC2_TYPE1', 'SOC2_TYPE2', 'ISO27001', 'ISO27017', 'ISO27018', 'PCI_DSS', 'HIPAA', 'GDPR', 'CCPA', 'FEDRAMP', 'CSA_STAR')),
        certification_version VARCHAR(20) NOT NULL,  -- e.g., '2018', '2021', '3.2.1'
        certification_scope VARCHAR(500),  -- What systems/processes are covered
        certification_scope_id UUID,  -- Link to specific system/resource scope

        -- Scope Boundaries
        applicable_regions TEXT[] DEFAULT '{}',
        applicable_services TEXT[] DEFAULT '{}',
        applicable_data_types TEXT[] DEFAULT '{}',
        excluded_from_scope TEXT,

        -- Status Tracking
        certification_status certification_status NOT NULL DEFAULT 'NOT_STARTED',
        previous_status certification_status,
        status_updated_at TIMESTAMPTZ,
        status_updated_by UUID,

        -- Dates & Deadlines
        planning_start_date DATE,
        pre_audit_start_date DATE,
        pre_audit_end_date DATE,
        formal_audit_start_date DATE,
        formal_audit_end_date DATE,
        certification_issued_date DATE,
        certification_expiry_date DATE NOT NULL,
        renewal_deadline_date DATE GENERATED ALWAYS AS (certification_expiry_date - INTERVAL '90 days') STORED,

        -- Audit Details
        audit_body_name VARCHAR(255),
        audit_body_contact VARCHAR(255),
        lead_auditor_name VARCHAR(255),
        audit_report_reference VARCHAR(255),
        audit_findings_summary TEXT,
        critical_findings_count INTEGER DEFAULT 0,
        high_findings_count INTEGER DEFAULT 0,
        medium_findings_count INTEGER DEFAULT 0,
        low_findings_count INTEGER DEFAULT 0,

        -- Evidence Management
        evidence_artifacts JSONB,  -- URLs to evidence documents with metadata
        evidence_checksums TEXT[],  -- SHA-256 for integrity verification
        evidence_expiry_dates JSONB,
        next_evidence_review_date DATE,
        evidence_automated_collection BOOLEAN DEFAULT FALSE,

        -- Controls Mapping
        controls_mapped JSONB,  -- Which controls are covered by this cert
        control_satisfaction_score NUMERIC(5,2),
        exception_controls TEXT[],

        -- Financial Impact
        audit_cost NUMERIC(12,2),
        remediation_cost NUMERIC(12,2),
        annual_sustainment_cost NUMERIC(12,2),
        cost_currency CHAR(3) DEFAULT 'USD',

        -- Customer & Contract Impact
        depends_on_customer_contracts TEXT[],
        certified_for_rfp_use BOOLEAN DEFAULT FALSE,
        public_certificate_available BOOLEAN DEFAULT FALSE,
        certificate_public_url TEXT,

        -- Continuous Monitoring
        continuous_compliance_score NUMERIC(5,2),
        last_continuous_check TIMESTAMPTZ,
        violation_count INTEGER DEFAULT 0,
        open_remediation_items INTEGER DEFAULT 0,

        -- Automated Alerts
        expiry_alert_days INTEGER[] DEFAULT '{90,60,30,14,7,1}',  -- Alert thresholds
        last_alert_sent_day INTEGER,
        alert_escalation_level INTEGER DEFAULT 0,

        -- Responsible Parties
        compliance_owner_id UUID,  -- Person responsible for certification
        technical_owner_id UUID,   -- Person responsible for technical controls
        executive_sponsor_id UUID, -- Executive oversight

        -- Remediation Tracking
        remediation_plan_url TEXT,
        remediation_completion_target DATE,
        remediation_completion_actual DATE,

        -- Integrations
        grc_system_id VARCHAR(255),
        ticketing_system_project VARCHAR(255),
        monitoring_integration JSONB,

        -- Metadata
        documentation_retention_years INTEGER DEFAULT 7,
        notes TEXT,
        tags TEXT[],

        -- Audit Trail
        created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
        created_by UUID NOT NULL,
        updated_by UUID NOT NULL,

        -- Constraints
        CONSTRAINT valid_certification_dates CHECK (
            certification_issued_date IS NULL OR
            (certification_issued_date < certification_expiry_date)
        ),
        CONSTRAINT valid_audit_timeline CHECK (
            (formal_audit_start_date IS NULL) OR
            (formal_audit_start_date IS NOT NULL AND formal_audit_end_date IS NOT NULL AND formal_audit_end_date > formal_audit_start_date)
        ),
        CONSTRAINT valid_scores CHECK (
            continuous_compliance_score >= 0 AND continuous_compliance_score <= 100
        )
    );

    -- Indexes for compliance_certification_registry
    CREATE INDEX idx_ccr_expiry_monitoring ON compliance_certification_registry(certification_expiry_date, certification_status)
        WHERE certification_status NOT IN ('EXPIRED', 'REVOKED');
    CREATE INDEX idx_ccr_standard_version ON compliance_certification_registry(certification_standard, certification_version);
    CREATE INDEX idx_ccr_audit_dates ON compliance_certification_registry(formal_audit_start_date, formal_audit_end_date);
    CREATE INDEX idx_ccr_customer_contract ON compliance_certification_registry(depends_on_customer_contracts);
    CREATE INDEX idx_ccr_owners ON compliance_certification_registry(compliance_owner_id, technical_owner_id);
    CREATE INDEX idx_ccr_evidence ON compliance_certification_registry(next_evidence_review_date) WHERE next_evidence_review_date IS NOT NULL;

    -- Comments
    COMMENT ON TABLE compliance_certification_registry IS 'Tracks SOC2, ISO27001, PCI-DSS audit cycles, evidence, and expiry dates';
    COMMENT ON COLUMN compliance_certification_registry.certification_standard IS 'Standard type: SOC2_TYPE1, SOC2_TYPE2, ISO27001, PCI_DSS, HIPAA, etc.';
    COMMENT ON COLUMN compliance_certification_registry.certification_status IS 'Current status: NOT_STARTED, IN_PROGRESS, PRE_AUDIT, FINAL_AUDIT, CERTIFIED, EXPIRED, etc.';
    COMMENT ON COLUMN compliance_certification_registry.continuous_compliance_score IS 'Automatically calculated compliance score (0-100) from continuous monitoring';
    COMMENT ON COLUMN compliance_certification_registry.evidence_artifacts IS 'JSONB containing references to evidence documents with metadata (path, type, expiry)';

    -- RLS Policies
    ALTER TABLE compliance_certification_registry ENABLE ROW LEVEL SECURITY;

    CREATE POLICY ccr_compliance_team_access ON compliance_certification_registry
        FOR ALL USING (current_setting('app.user_role') IN ('COMPLIANCE_OFFICER', 'SECURITY_MANAGER', 'SUPER_ADMIN'));

    CREATE POLICY ccr_auditor_readonly ON compliance_certification_registry
        FOR SELECT USING (current_setting('app.user_role') = 'EXTERNAL_AUDITOR');

    CREATE POLICY ccr_sales_readonly ON compliance_certification_registry
        FOR SELECT USING (current_setting('app.user_role') = 'SALES_ENGINEER' AND public_certificate_available = TRUE);

    -- Expiry Alert Trigger
    CREATE OR REPLACE FUNCTION check_certification_expiry()
    RETURNS TRIGGER AS $$
    DECLARE
        days_to_expiry INTEGER;
    BEGIN
        IF NEW.certification_status = 'CERTIFIED' AND NEW.certification_expiry_date IS NOT NULL THEN
            days_to_expiry := (NEW.certification_expiry_date - CURRENT_DATE);

            -- Check if we need to send alerts based on threshold days
            IF days_to_expiry <= 90 THEN
                -- Insert into notification queue (simplified - would be actual queue in production)
                INSERT INTO notification_queue (type, recipient, message, metadata)
                VALUES ('CERT_EXPIRY_WARNING',
                        (SELECT email FROM users WHERE user_id = NEW.compliance_owner_id),
                        format('Certification %s expires in %s days', NEW.certification_standard, days_to_expiry),
                        jsonb_build_object('certification_id', NEW.certification_id, 'days_to_expiry', days_to_expiry));
            END IF;
        END IF;

        RETURN NEW;
    END;
    $$ LANGUAGE plpgsql;

    CREATE TRIGGER check_ccr_expiry
        AFTER UPDATE OF certification_expiry_date, certification_status ON compliance_certification_registry
        FOR EACH ROW
        EXECUTE FUNCTION check_certification_expiry();

    CREATE TRIGGER update_ccr_updated_at
        BEFORE UPDATE ON compliance_certification_registry
        FOR EACH ROW
        EXECUTE FUNCTION update_updated_at_column();


