--3. Daily Business Dashboard

--Domain:---Business Intelligence & Executive Reporting  
--Database Object Name:---`mv_daily_business_dashboard`  
--Database Object Type:---Materialized View  
--Description:---Pre-aggregated daily business metrics for executive dashboards, including revenue, user activity, engagement, and operational KPIs. Combines data from subscriptions, invoices, payments, user activities, and content engagement into a single fast-loading dashboard view.  
--Business Case:---Critical for C-suite decision-making. The dashboard provides real-time visibility into business health, enabling rapid response to trends and issues. By pre-aggregating complex joins, the view loads in milliseconds even with millions of rows, supporting daily standups and board presentations.  
--KPIs / Outputs:--
--`metric_date` --Date of metrics
--`active_users` --Daily active users
--`new_subscriptions` --New subscriptions created
--`canceled_subscriptions` --Canceled subscriptions
--`revenue` --Total revenue
--`mrr` --Monthly recurring revenue
--`avg_invoice_value` --Average invoice value
--`content_engagement_rate` --Content engagement percentage
--`support_tickets_open` --Open support tickets

--Feature References:---BUS-01, REP-01, ANA-01  
--Tables Used:---`subscriptions`, `invoices`, `payments`, `user_activities`, `content_engagement`, `support_tickets`  
--Performance Optimization:--
--Unique index on `metric_date`
--Refreshed daily at 2 AM via pg_cron
--Covers last 365 days for year-over-year comparisons
--Indexed for fast date range queries


CREATE MATERIALIZED VIEW public.mv_daily_business_dashboard AS
WITH daily_metrics AS (
    SELECT 
        DATE(s.created_at) AS metric_date,
        COUNT(DISTINCT s.user_id) AS active_users,
        COUNT(*) FILTER (WHERE s.status = 'ACTIVE') AS new_subscriptions,
        COUNT(*) FILTER (WHERE s.status = 'CANCELED') AS canceled_subscriptions,
        SUM(CASE WHEN s.status = 'ACTIVE' THEN s.total_price ELSE 0 END) AS revenue
    FROM subscriptions s
    WHERE s.created_at > NOW() --INTERVAL '365 days'
    GROUP BY DATE(s.created_at)
),
invoice_metrics AS (
    SELECT 
        DATE(i.created_at) AS metric_date,
        SUM(i.total_amount) AS invoice_revenue,
        AVG(i.total_amount) AS avg_invoice_value,
        COUNT(*) AS invoice_count
    FROM invoices i
    WHERE i.created_at > NOW() --INTERVAL '365 days'
    GROUP BY DATE(i.created_at)
),
engagement_metrics AS (
    SELECT 
        DATE(created_at) AS metric_date,
        COUNT(DISTINCT user_id) AS engaged_users,
        COUNT(*) AS total_engagements
    FROM user_activities
    WHERE created_at > NOW() --INTERVAL '365 days'
    GROUP BY DATE(created_at)
)
SELECT 
    COALESCE(dm.metric_date, im.metric_date, em.metric_date) AS metric_date,
    COALESCE(dm.active_users, 0) AS active_users,
    COALESCE(dm.new_subscriptions, 0) AS new_subscriptions,
    COALESCE(dm.canceled_subscriptions, 0) AS canceled_subscriptions,
    COALESCE(dm.revenue, 0) + COALESCE(im.invoice_revenue, 0) AS revenue,
    COALESCE(im.avg_invoice_value, 0) AS avg_invoice_value,
    COALESCE(im.invoice_count, 0) AS invoice_count,
    COALESCE(em.engaged_users, 0) AS engaged_users,
    COALESCE(em.total_engagements, 0) AS total_engagements,
    CASE 
        WHEN COALESCE(em.engaged_users, 0) > 0 
        THEN ROUND(COALESCE(em.total_engagements, 0)::NUMERIC / em.engaged_users, 2)
        ELSE 0 
    END AS engagement_rate
FROM daily_metrics dm
FULL OUTER JOIN invoice_metrics im ON dm.metric_date = im.metric_date
FULL OUTER JOIN engagement_metrics em ON COALESCE(dm.metric_date, im.metric_date) = em.metric_date
ORDER BY metric_date DESC;

CREATE UNIQUE INDEX idx_mv_daily_business_date 
    ON public.mv_daily_business_dashboard (metric_date);
CREATE INDEX idx_mv_daily_business_revenue 
    ON public.mv_daily_business_dashboard (revenue DESC);


