--9. User Activity Dashboard

--Domain:---User Analytics & Engagement Tracking  
--Database Object Name:---`mv_user_activity_dashboard`  
--Database Object Type:---Materialized View  
--Description:---Daily user activity metrics including DAU, WAU, MAU, business hours vs. after-hours usage, and retention rates. Provides executive visibility into user engagement trends.  
--Business Case:---Essential for product and growth teams. Tracks user engagement trends, identifies usage patterns, and measures retention. Informs feature prioritization and marketing campaigns.  
--KPIs / Outputs:--
--`date` --Date of metrics
--`active_users` --Daily active users
--`business_hours_users` --Users active 9 AM --5 PM
--`after_hours_users` --Users active outside business hours
--`weekly_active_users` --Weekly active users
--`monthly_active_users` --Monthly active users
--`retention_rate` --Month-over-month retention rate

--Feature References:---ANA-01, ANA-02, ENG-01  
--Tables Used:---`users`, `user_activities`, `sessions`  
--Performance Optimization:--
--Unique index on `date`
--Refreshed daily at 6 AM
--Supports fast date range queries
--Enables trend analysis


CREATE MATERIALIZED VIEW public.mv_user_activity_dashboard AS
SELECT
    DATE(u.last_login) AS date,
    COUNT(DISTINCT u.user_id) AS active_users,
    COUNT(DISTINCT u.user_id) FILTER (
        WHERE EXTRACT(HOUR FROM u.last_login) BETWEEN 9 AND 17
    ) AS business_hours_users,
    COUNT(DISTINCT u.user_id) FILTER (
        WHERE EXTRACT(HOUR FROM u.last_login) NOT BETWEEN 9 AND 17
    ) AS after_hours_users,
    COUNT(DISTINCT u.user_id) FILTER (
        WHERE u.last_login > NOW() --INTERVAL '7 days'
    ) AS weekly_active_users,
    COUNT(DISTINCT u.user_id) FILTER (
        WHERE u.last_login > NOW() --INTERVAL '30 days'
    ) AS monthly_active_users,
    ROUND(
        100.0 * COUNT(DISTINCT u.user_id) FILTER (
            WHERE u.last_login > NOW() --INTERVAL '30 days'
        ) / NULLIF(COUNT(DISTINCT u.user_id), 0),
        2
    ) AS retention_rate
FROM users u
WHERE u.deleted_at IS NULL
GROUP BY DATE(u.last_login);

CREATE UNIQUE INDEX idx_mv_user_activity_date 
    ON public.mv_user_activity_dashboard (date);
CREATE INDEX idx_mv_user_activity_retention 
    ON public.mv_user_activity_dashboard (retention_rate DESC);


