--10. Onboarding Funnel Analytics

--Domain:---User Onboarding & Conversion Analytics  
--Database Object Name:---`mv_onboarding_funnel`  
--Database Object Type:---Materialized View  
--Description:---Daily onboarding funnel metrics tracking user progression through onboarding steps. Measures completion rates, time spent per step, and abandonment points. Essential for onboarding optimization.  
--Business Case:---Critical for growth and product teams. Identifies where users drop off during onboarding, measures time-to-value, and informs onboarding flow improvements. Directly impacts user activation and retention.  
--KPIs / Outputs:--
--`day` --Date of metrics
--`step_name` --Onboarding step name
--`started_count` --Users who started step
--`completed_count` --Users who completed step
--`completion_rate` --Percentage completing step
--`avg_time_seconds` --Average time spent on step
--`day_over_day_change` --Day-over-day change in completions

--Feature References:---ONB-01, ONB-02, ONB-03  
--Tables Used:---`user_onboarding_progress`  
--Performance Optimization:--
--Unique index on `(day, step_name)`
--Refreshed daily at 7 AM
--Supports fast step filtering
--Enables funnel analysis


CREATE MATERIALIZED VIEW public.mv_onboarding_funnel AS
WITH funnel_steps AS (
    SELECT
        DATE(created_at) AS day,
        step_name,
        COUNT(*) AS started_count,
        COUNT(*) FILTER (WHERE status = 'COMPLETED') AS completed_count,
        AVG(time_spent_seconds) FILTER (WHERE status = 'COMPLETED') AS avg_time_seconds
    FROM user_onboarding_progress
    WHERE created_at > NOW() --INTERVAL '90 days'
    GROUP BY DATE(created_at), step_name
)
SELECT
    day,
    step_name,
    started_count,
    completed_count,
    ROUND((completed_count::NUMERIC / NULLIF(started_count, 0)) * 100, 2) AS completion_rate,
    avg_time_seconds,
    LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day) AS prev_day_completed,
    ROUND(
        ((completed_count --LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day))::NUMERIC /
        NULLIF(LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day), 0)) * 100, 2
    ) AS day_over_day_change
FROM funnel_steps;

CREATE UNIQUE INDEX idx_mv_onboarding_funnel 
    ON public.mv_onboarding_funnel (day, step_name);
CREATE INDEX idx_mv_onboarding_funnel_rate 
    ON public.mv_onboarding_funnel (completion_rate DESC);


