--12. Sales Performance Rollup

--Domain:---Sales Analytics & Pipeline Management  
--Database Object Name:---`mv_sales_performance_rollup`  
--Database Object Type:---Materialized View  
--Description:---Daily aggregated sales performance metrics including lead counts, pipeline value, conversion rates, and deal velocity. Aggregated by sales rep, team, and region for performance tracking.  
--Business Case:---Critical for sales leadership and operations. Tracks sales team performance, identifies top performers, and measures pipeline health. Informs sales strategy and resource allocation.  
--KPIs / Outputs:--
--`metric_date` --Date of metrics
--`sales_rep_id` --Sales representative
--`team_name` --Sales team
--`region` --Geographic region
--`total_leads` --Total leads generated
--`qualified_leads` --Qualified leads
--`pipeline_value` --Total pipeline value
--`deals_closed` --Deals closed
--`revenue_closed` --Revenue from closed deals
--`avg_deal_size` --Average deal size
--`conversion_rate` --Lead-to-close conversion rate

--Feature References:---SALES-01, SALES-02, SALES-03  
--Tables Used:---`leads`, `opportunities`, `deals`, `sales_reps`  
--Performance Optimization:--
--Unique index on `(metric_date, sales_rep_id, team_name, region)`
--Refreshed daily at 9 AM
--Supports fast rep/team filtering
--Enables performance comparisons


CREATE MATERIALIZED VIEW public.mv_sales_performance_rollup AS
SELECT
    DATE(o.created_at) AS metric_date,
    sr.sales_rep_id,
    sr.team_name,
    sr.region,
    COUNT(DISTINCT l.lead_id) AS total_leads,
    COUNT(DISTINCT l.lead_id) FILTER (WHERE l.status = 'QUALIFIED') AS qualified_leads,
    SUM(o.value) AS pipeline_value,
    COUNT(DISTINCT d.deal_id) FILTER (WHERE d.status = 'CLOSED_WON') AS deals_closed,
    SUM(d.amount) FILTER (WHERE d.status = 'CLOSED_WON') AS revenue_closed,
    AVG(d.amount) FILTER (WHERE d.status = 'CLOSED_WON') AS avg_deal_size,
    ROUND(
        100.0 * COUNT(DISTINCT d.deal_id) FILTER (WHERE d.status = 'CLOSED_WON') / 
        NULLIF(COUNT(DISTINCT l.lead_id), 0),
        2
    ) AS conversion_rate
FROM opportunities o
LEFT JOIN leads l ON o.lead_id = l.lead_id
LEFT JOIN deals d ON o.opportunity_id = d.opportunity_id
LEFT JOIN sales_reps sr ON o.sales_rep_id = sr.sales_rep_id
WHERE o.created_at > NOW() --INTERVAL '90 days'
GROUP BY metric_date, sr.sales_rep_id, sr.team_name, sr.region;

CREATE UNIQUE INDEX idx_mv_sales_perf_rollup 
    ON public.mv_sales_performance_rollup (metric_date, sales_rep_id, team_name, region);
CREATE INDEX idx_mv_sales_perf_revenue 
    ON public.mv_sales_performance_rollup (revenue_closed DESC);


