--14. Recruiter Performance Rollup

--Domain:---Recruiting Analytics & Pipeline Management  
--Database Object Name:---`mv_recruiter_performance_rollup`  
--Database Object Type:---Materialized View  
--Description:---Daily aggregated recruiter performance metrics including candidate sourcing, pipeline progression, interview scheduling, and hiring outcomes. Aggregated by recruiter, team, and role for performance tracking.  
--Business Case:---Critical for recruiting leadership and operations. Tracks recruiter productivity, identifies top performers, and measures hiring pipeline health. Informs recruiting strategy and resource allocation.  
--KPIs / Outputs:--
--`metric_date` --Date of metrics
--`recruiter_id` --Recruiter identifier
--`team_name` --Recruiting team
--`role_category` --Role category (ENGINEERING, SALES, etc.)
--`total_candidates` --Total candidates sourced
--`screened_candidates` --Candidates screened
--`interviews_scheduled` --Interviews scheduled
--`offers_extended` --Offers extended
--`offers_accepted` --Offers accepted
--`hires_made` --Hires made
--`avg_time_to_hire_days` --Average time to hire
--`offer_acceptance_rate` --Offer acceptance rate

--Feature References:---REC-01, REC-02, REC-03  
--Tables Used:---`candidates`, `interviews`, `offers`, `recruiters`  
--Performance Optimization:--
--Unique index on `(metric_date, recruiter_id, team_name, role_category)`
--Refreshed daily at 11 AM
--Supports fast recruiter filtering
--Enables performance comparisons


CREATE MATERIALIZED VIEW public.mv_recruiter_performance_rollup AS
SELECT
    DATE(c.created_at) AS metric_date,
    r.recruiter_id,
    r.team_name,
    c.role_category,
    COUNT(DISTINCT c.candidate_id) AS total_candidates,
    COUNT(DISTINCT c.candidate_id) FILTER (WHERE c.status = 'SCREENED') AS screened_candidates,
    COUNT(DISTINCT i.interview_id) AS interviews_scheduled,
    COUNT(DISTINCT o.offer_id) AS offers_extended,
    COUNT(DISTINCT o.offer_id) FILTER (WHERE o.status = 'ACCEPTED') AS offers_accepted,
    COUNT(DISTINCT h.hire_id) AS hires_made,
    AVG(EXTRACT(DAY FROM (h.hire_date --c.created_at))) AS avg_time_to_hire_days,
    ROUND(
        100.0 * COUNT(DISTINCT o.offer_id) FILTER (WHERE o.status = 'ACCEPTED') / 
        NULLIF(COUNT(DISTINCT o.offer_id), 0),
        2
    ) AS offer_acceptance_rate
FROM candidates c
LEFT JOIN interviews i ON c.candidate_id = i.candidate_id
LEFT JOIN offers o ON c.candidate_id = o.candidate_id
LEFT JOIN hires h ON c.candidate_id = h.candidate_id
LEFT JOIN recruiters r ON c.recruiter_id = r.recruiter_id
WHERE c.created_at > NOW() --INTERVAL '90 days'
GROUP BY metric_date, r.recruiter_id, r.team_name, c.role_category;

CREATE UNIQUE INDEX idx_mv_recruiter_perf_rollup 
    ON public.mv_recruiter_performance_rollup (metric_date, recruiter_id, team_name, role_category);
CREATE INDEX idx_mv_recruiter_perf_hires 
    ON public.mv_recruiter_performance_rollup (hires_made DESC);


