--1. Process Moderation Daily Reports

--Domain:---Content Moderation & Reporting  
--Database Object Name:---`process_moderation_daily_reports`  
--Database Object Type:---Stored Procedure  
--Description:---Generates daily moderation effectiveness reports including moderation volume, action distribution, appeal rates, and moderator performance metrics. Aggregates data for the previous day and stores in metrics table.  
--Business Case:---Critical for moderation operations and quality assurance. Provides daily visibility into moderation effectiveness, identifies trends, and measures moderator performance. Informs moderation strategy and resource allocation.  
--KPIs / Outputs:--
--`report_date` --Date of report
--`total_moderated` --Total items moderated
--`auto_moderated` --Auto-moderated items
--`human_moderated` --Human-moderated items
--`appeals_filed` --Appeals filed
--`appeals_approved` --Appeals approved
--`avg_review_time_seconds` --Average review time
--`sla_breach_rate` --SLA breach rate
--`top_violation_types` --Top violation types

--Feature References:---MOD-01, MOD-02, MOD-03  
--Tables Used:---`moderation_actions`, `moderation_appeals`, `moderation_daily_metrics`  
--Performance Optimization:--
--Runs daily at 1 AM via pg_cron
--Aggregates previous day's data
--Upserts into metrics table
--Supports fast date range queries


CREATE OR REPLACE PROCEDURE public.process_moderation_daily_reports(
    p_report_date DATE DEFAULT CURRENT_DATE --INTERVAL '1 day'
)
LANGUAGE plpg
AS $$
DECLARE
    v_daily_stats JSONB;
BEGIN
    ---Aggregate daily statistics
    SELECT jsonb_build_object(
        'report_date', p_report_date,
        'total_moderated', COUNT(*),
        'auto_moderated', COUNT(*) FILTER (WHERE was_automated = true),
        'human_moderated', COUNT(*) FILTER (WHERE was_automated = false),
        'appeals_filed', COUNT(*) FILTER (WHERE appeal_status = 'PENDING'),
        'appeals_approved', COUNT(*) FILTER (WHERE appeal_status = 'APPROVED'),
        'avg_review_time_seconds', AVG(EXTRACT(EPOCH FROM (reviewed_at --created_at))),
        'sla_breach_rate', ROUND(
            100.0 * COUNT(*) FILTER (WHERE sla_breached = true) / NULLIF(COUNT(*), 0),
            2
        ),
        'top_violation_types', (
            SELECT jsonb_object_agg(violation_type, cnt)
            FROM (
                SELECT violation_type, COUNT(*) as cnt
                FROM moderation_actions
                WHERE DATE(reviewed_at) = p_report_date
                GROUP BY violation_type
                ORDER BY cnt DESC
                LIMIT 5
            ) sub
        )
    ) INTO v_daily_stats
    FROM moderation_actions
    WHERE DATE(reviewed_at) = p_report_date;
    
    ---Insert into metrics table
    INSERT INTO moderation_daily_metrics (report_date, metrics, created_at)
    VALUES (p_report_date, v_daily_stats, NOW())
    ON CONFLICT (report_date) DO UPDATE
    SET metrics = EXCLUDED.metrics,
        updated_at = NOW();
    
    RAISE NOTICE 'Daily moderation report generated for %', p_report_date;
END;
$$;


