--2. Apply Moderation Action

--Domain:---Content Moderation & Enforcement  
--Database Object Name:---`apply_moderation_action`  
--Database Object Type:---Stored Procedure  
--Description:---Applies moderation action to content (ALLOW, BLOCK, REMOVE, HIDE, FLAG_REVIEW, DEMOTE, WARN_USER, SUSPEND_USER, BAN_USER) with audit trail and user notification. Ensures atomic action application.  
--Business Case:---Essential for content moderation enforcement. Provides a standardized way to apply moderation actions with full audit trail and user notification. Improves moderation consistency and accountability.  
--KPIs / Outputs:--
--`success` --Whether action was successful
--`message` --Result message
--`content_updated` --Whether content was updated
--`user_notified` --Whether user was notified
--`action_applied` --Action applied
--`timestamp` --Action timestamp

--Feature References:---MOD-01, MOD-02, MOD-03  
--Tables Used:---`moderation_actions`, `content`, `users`, `user_notifications`  
--Performance Optimization:--
--Atomic transaction for consistency
--Audit trail for accountability
--User notification for transparency
--Supports fast action application


CREATE OR REPLACE FUNCTION public.apply_moderation_action(
    p_content_id UUID,
    p_content_type VARCHAR(50),
    p_action VARCHAR(50),
    p_moderator_id UUID,
    p_reason TEXT
)
RETURNS TABLE (
    success BOOLEAN,
    message TEXT,
    content_updated BOOLEAN,
    user_notified BOOLEAN,
    action_applied VARCHAR(50),
    timestamp TIMESTAMP WITH TIME ZONE
)
LANGUAGE plpg
AS $$
DECLARE
    v_content RECORD;
    v_user_id UUID;
    v_action_timestamp TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    ---Get content and user
    SELECT c.*, c.author_id INTO v_content, v_user_id
    FROM content c
    WHERE c.content_id = p_content_id
    AND c.content_type = p_content_type
    AND c.deleted_at IS NULL;
    
    IF v_content IS NULL THEN
        RETURN QUERY SELECT false, 'Content not found', false, false, p_action, v_action_timestamp;
        RETURN;
    END IF;
    
    ---Apply moderation action
    CASE p_action
        WHEN 'ALLOW' THEN
            UPDATE content SET status = 'APPROVED', moderated_at = v_action_timestamp
            WHERE content_id = p_content_id;
            
        WHEN 'BLOCK' THEN
            UPDATE content SET status = 'BLOCKED', moderated_at = v_action_timestamp
            WHERE content_id = p_content_id;
            
        WHEN 'REMOVE' THEN
            UPDATE content SET deleted_at = v_action_timestamp, moderation_reason = p_reason
            WHERE content_id = p_content_id;
            
        WHEN 'HIDE' THEN
            UPDATE content SET visibility = 'HIDDEN', moderated_at = v_action_timestamp
            WHERE content_id = p_content_id;
            
        WHEN 'FLAG_REVIEW' THEN
            UPDATE content SET status = 'FLAGGED', moderated_at = v_action_timestamp
            WHERE content_id = p_content_id;
            
        WHEN 'DEMOTE' THEN
            UPDATE content SET priority = priority --1, moderated_at = v_action_timestamp
            WHERE content_id = p_content_id;
            
        WHEN 'WARN_USER' THEN
            INSERT INTO user_warnings (user_id, warning_reason, warned_by, warned_at)
            VALUES (v_user_id, p_reason, p_moderator_id, v_action_timestamp);
            
        WHEN 'SUSPEND_USER' THEN
            UPDATE users SET suspended_at = v_action_timestamp, suspension_reason = p_reason
            WHERE user_id = v_user_id;
            
        WHEN 'BAN_USER' THEN
            UPDATE users SET banned_at = v_action_timestamp, ban_reason = p_reason
            WHERE user_id = v_user_id;
            
        ELSE
            RETURN QUERY SELECT false, 'Invalid action', false, false, p_action, v_action_timestamp;
            RETURN;
    END CASE;
    
    ---Log moderation action
    INSERT INTO moderation_actions (
        content_id, content_type, action, moderator_id, reason, actioned_at
    ) VALUES (
        p_content_id, p_content_type, p_action, p_moderator_id, p_reason, v_action_timestamp
    );
    
    ---Notify user
    INSERT INTO user_notifications (
        user_id, notification_type, message, created_at
    ) VALUES (
        v_user_id, 'MODERATION_ACTION', 
        FORMAT('Your content has been %s. Reason: %s', p_action, p_reason),
        v_action_timestamp
    );
    
    RETURN QUERY SELECT true, 'Action applied successfully', true, true, p_action, v_action_timestamp;
END;
$$;


