--5. Retry Failed Outbox Events

--Domain:---Event Delivery & Reliability  
--Database Object Name:---`retry_failed_outbox_events`  
--Database Object Type:---Stored Procedure  
--Description:---Retries failed outbox events with exponential backoff. Processes events in batches with configurable retry limits and backoff strategies. Ensures reliable event delivery.  
--Business Case:---Critical for event-driven architecture reliability. Ensures failed events are retried with appropriate backoff, preventing event loss and maintaining system consistency. Improves event delivery reliability.  
--KPIs / Outputs:--
--`events_processed` --Events processed
--`events_retried` --Events retried
--`events_failed` --Events failed
--`avg_retry_delay_ms` --Average retry delay
--`oldest_event_age_hours` --Oldest event age

--Feature References:---EVT-01, EVT-02, EVT-03  
--Tables Used:---`event_outbox`  
--Performance Optimization:--
--Batch processing for efficiency
--Exponential backoff for reliability
--SKIP LOCKED for concurrent processing
--Supports fast event filtering


CREATE OR REPLACE PROCEDURE public.retry_failed_outbox_events(
    p_max_retries INTEGER DEFAULT 3,
    p_batch_size INTEGER DEFAULT 100
)
LANGUAGE plpg
AS $$
DECLARE
    v_event RECORD;
    v_retry_delay INTEGER;
    v_updated_count INTEGER := 0;
BEGIN
    ---Input validation
    IF p_max_retries < 1 OR p_max_retries > 10 THEN
        RAISE EXCEPTION 'p_max_retries must be between 1 and 10, got %', p_max_retries;
    END IF;
    
    IF p_batch_size < 1 OR p_batch_size > 1000 THEN
        RAISE EXCEPTION 'p_batch_size must be between 1 and 1000, got %', p_batch_size;
    END IF;
    
    ---Process retryable events
    FOR v_event IN
        SELECT event_id, retry_count, backoff_base_ms, backoff_multiplier
        FROM event_outbox
        WHERE status = 'FAILED'
        AND retry_count < p_max_retries
        AND next_retry_at <= NOW()
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            ---Calculate exponential backoff
            v_retry_delay := v_event.backoff_base_ms * (v_event.backoff_multiplier ^ v_event.retry_count);
            
            ---Update for retry
            UPDATE event_outbox
            SET
                status = 'RETRY',
                retry_count = retry_count + 1,
                next_retry_at = NOW() + (v_retry_delay * INTERVAL '1 millisecond'),
                updated_at = NOW(),
                updated_by = 'SYSTEM_RETRY_HANDLER'
            WHERE event_id = v_event.event_id;
            
            v_updated_count := v_updated_count + 1;
            
            ---Log retry action
            RAISE NOTICE 'Event % scheduled for retry % at %',
                v_event.event_id, v_event.retry_count + 1, v_retry_delay;
        EXCEPTION WHEN OTHERS THEN
            ---Log error but continue processing other events
            RAISE WARNING 'Failed to retry event %: %', v_event.event_id, ERRM;
        END;
    END LOOP;
    
    RAISE NOTICE 'Scheduled % events for retry', v_updated_count;
END;
$$;


