--6. Check Rate Limit

--Domain:---API Rate Limiting & Throttling  
--Database Object Name:---`check_rate_limit`  
--Database Object Type:---Stored Procedure  
--Description:---Checks API rate limit for a client/endpoint combination. Atomically increments counter and returns remaining quota, retry-after time, and current usage. Supports sliding window algorithm.  
--Business Case:---Essential for API platform protection and fair usage. Provides atomic rate limit checking with sliding window algorithm, preventing API abuse and ensuring fair usage. Improves API platform stability.  
--KPIs / Outputs:--
--`is_allowed` --Whether request is allowed
--`remaining_quota` --Remaining quota
--`retry_after_seconds` --Retry-after time
--`current_usage` --Current usage
--`limit_reset_at` --Limit reset time

--Feature References:---API-01, API-02, API-03  
--Tables Used:---`api_rate_limits`, `api_rate_limit_counters`  
--Performance Optimization:--
--Atomic counter increment
--Sliding window algorithm
--SKIP LOCKED for concurrent processing
--Supports fast rate limit checking


CREATE OR REPLACE FUNCTION public.check_rate_limit(
    p_client_id VARCHAR(255),
    p_endpoint_pattern VARCHAR(500),
    p_tenant_id UUID DEFAULT NULL,
    p_request_count INTEGER DEFAULT 1
)
RETURNS TABLE (
    is_allowed BOOLEAN,
    remaining_quota INTEGER,
    retry_after_seconds INTEGER,
    current_usage INTEGER,
    limit_reset_at TIMESTAMP WITH TIME ZONE
)
LANGUAGE plpg
AS $$
DECLARE
    v_limit RECORD;
    v_window_end TIMESTAMP;
    v_usage INTEGER;
BEGIN
    ---Find applicable rate limit
    SELECT * INTO v_limit
    FROM api_rate_limits
    WHERE client_id = p_client_id
    AND endpoint_pattern = p_endpoint_pattern
    AND (tenant_id = p_tenant_id OR tenant_id IS NULL)
    AND is_active = true
    AND window_end_time > NOW()
    ORDER BY priority_level, tenant_id NULLS LAST
    LIMIT 1;
    
    ---If no limit defined, allow request
    IF v_limit IS NULL THEN
        RETURN QUERY SELECT true, 999999, 0, 0, NULL::TIMESTAMP WITH TIME ZONE;
        RETURN;
    END IF;
    
    ---Get current usage
    SELECT current_count INTO v_usage
    FROM api_rate_limit_counters
    WHERE limit_id = v_limit.limit_id
    FOR UPDATE;
    
    ---Check if within limits
    IF v_usage + p_request_count <= v_limit.max_requests THEN
        ---Allow and increment
        UPDATE api_rate_limit_counters
        SET current_count = current_count + p_request_count,
            total_requests_this_window = total_requests_this_window + p_request_count,
            last_request_at = NOW(),
            updated_at = NOW()
        WHERE limit_id = v_limit.limit_id;
        
        RETURN QUERY SELECT
            true,
            v_limit.max_requests --(v_usage + p_request_count),
            0,
            v_usage + p_request_count,
            v_limit.window_end_time;
    ELSE
        ---Block request
        UPDATE api_rate_limit_counters
        SET blocked_requests_this_window = blocked_requests_this_window + p_request_count
        WHERE limit_id = v_limit.limit_id;
        
        RETURN QUERY SELECT
            false,
            0,
            EXTRACT(EPOCH FROM (v_limit.window_end_time --NOW()))::INTEGER,
            v_usage,
            v_limit.window_end_time;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        ---On error, allow request but log (circuit breaker pattern)
        RAISE WARNING 'Rate limit check failed for client % endpoint %: %',
            p_client_id, p_endpoint_pattern, ERRM;
        RETURN QUERY SELECT true, 0, 0, 0, NULL::TIMESTAMP WITH TIME ZONE;
END;
$$;


