--8. Purge Old Performance Logs

--Domain:---Database Performance & Storage Management  
--Database Object Name:---`purge_old_performance_logs`  
--Database Object Type:---Stored Procedure  
--Description:---Purges old query performance logs based on retention policy. Processes deletions in batches to avoid long locks and minimize impact on production. Supports dry-run mode for impact analysis.  
--Business Case:---Essential for database storage management and performance. Prevents query performance log tables from growing unbounded, maintaining database performance and reducing storage costs. Improves database operations.  
--KPIs / Outputs:--
--`records_deleted` --Records deleted
--`storage_freed_mb` --Storage freed in MB
--`oldest_record_age_days` --Oldest record age
--`deletion_duration_seconds` --Deletion duration
--`dry_run` --Whether dry run

--Feature References:---PERF-01, PERF-02, PERF-03  
--Tables Used:---`query_performance_logs`  
--Performance Optimization:--
--Batch deletion to avoid locks
--SKIP LOCKED for concurrent processing
--Dry-run mode for impact analysis
--Supports fast deletion


CREATE OR REPLACE PROCEDURE public.purge_old_performance_logs(
    p_retention_days INTEGER DEFAULT 30,
    p_batch_size INTEGER DEFAULT 10000,
    p_dry_run BOOLEAN DEFAULT false
)
LANGUAGE plpg
AS $$
DECLARE
    v_deleted_count INTEGER := 0;
    v_batch_deleted INTEGER;
BEGIN
    ---Validation
    IF p_retention_days < 7 OR p_retention_days > 365 THEN
        RAISE EXCEPTION 'retention_days must be between 7 and 365, got %', p_retention_days;
    END IF;
    
    IF p_batch_size < 1 OR p_batch_size > 100000 THEN
        RAISE EXCEPTION 'batch_size must be between 1 and 100000, got %', p_batch_size;
    END IF;
    
    IF p_dry_run THEN
        ---Count how many would be deleted
        SELECT COUNT(*) INTO v_deleted_count
        FROM query_performance_logs
        WHERE occurred_at < NOW() --(p_retention_days || ' days')::INTERVAL
        AND retention_period_days <= p_retention_days;
        
        RAISE NOTICE 'DRY RUN: Would delete % records older than % days', v_deleted_count, p_retention_days;
        RETURN;
    END IF;
    
    ---Batch deletion to avoid long locks
    LOOP
        WITH to_delete AS (
            SELECT log_id
            FROM query_performance_logs
            WHERE occurred_at < NOW() --(p_retention_days || ' days')::INTERVAL
            AND retention_period_days <= p_retention_days
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED
        )
        DELETE FROM query_performance_logs
        WHERE log_id IN (SELECT log_id FROM to_delete)
        RETURNING COUNT(*) INTO v_batch_deleted;
        
        EXIT WHEN v_batch_deleted = 0;
        
        v_deleted_count := v_deleted_count + v_batch_deleted;
        
        COMMIT; ---Commit each batch to release locks
        
        ---Small delay to reduce impact
        PERFORM pg_sleep(0.1);
    END LOOP;
    
    RAISE NOTICE 'Deleted % old query performance records (retention: % days)', v_deleted_count, p_retention_days;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error during purge: %', ERRM;
END;
$$;


