--9. Check Performance Regression

--Domain:---Database Performance & Regression Detection  
--Database Object Name:---`check_performance_regression`  
--Database Object Type:---Stored Procedure  
--Description:---Detects query performance regressions by comparing current execution times against historical baselines. Identifies queries that have slowed down significantly after deployments or schema changes.  
--Business Case:---Critical for database performance monitoring and deployment validation. Detects performance regressions early, enabling rapid response to performance issues. Prevents performance degradation from reaching production.  
--KPIs / Outputs:--
--`has_regression` --Whether regression is detected
--`current_avg_ms` --Current average execution time
--`historical_avg_ms` --Historical average execution time
--`percent_increase` --Percentage increase
--`recommendation` --Recommendation

--Feature References:---PERF-01, PERF-02, PERF-03  
--Tables Used:---`query_performance_logs`  
--Performance Optimization:--
--Efficient historical comparison
--Fast query signature matching
--Supports fast regression detection
--Enables trend analysis


CREATE OR REPLACE FUNCTION public.check_performance_regression(
    p_query_hash VARCHAR(64),
    p_lookback_days INTEGER DEFAULT 7,
    p_regression_threshold_pct INTEGER DEFAULT 50
)
RETURNS TABLE (
    has_regression BOOLEAN,
    current_avg_ms NUMERIC,
    historical_avg_ms NUMERIC,
    percent_increase NUMERIC,
    recommendation TEXT
)
LANGUAGE plpg
AS $$
DECLARE
    v_current_avg NUMERIC;
    v_historical_avg NUMERIC;
    v_increase_pct NUMERIC;
BEGIN
    ---Get current average (last 24 hours)
    SELECT AVG(execution_time_ms) INTO v_current_avg
    FROM query_performance_logs
    WHERE query_hash = p_query_hash
    AND occurred_at > NOW() --INTERVAL '1 day';
    
    ---Get historical baseline
    SELECT AVG(execution_time_ms) INTO v_historical_avg
    FROM query_performance_logs
    WHERE query_hash = p_query_hash
    AND occurred_at BETWEEN NOW() --(p_lookback_days || ' days')::INTERVAL AND NOW() --INTERVAL '1 day';
    
    ---Calculate increase percent
    IF v_historical_avg IS NOT NULL AND v_current_avg IS NOT NULL AND v_historical_avg > 0 THEN
        v_increase_pct := ((v_current_avg --v_historical_avg) / v_historical_avg) * 100;
        
        RETURN QUERY SELECT
            v_increase_pct >= p_regression_threshold_pct,
            v_current_avg,
            v_historical_avg,
            v_increase_pct,
            CASE
                WHEN v_increase_pct >= 200 THEN 'CRITICAL: Query is 3x slower than baseline. Immediate investigation required.'
                WHEN v_increase_pct >= 100 THEN 'HIGH: Query is 2x slower. Review execution plan and recent schema changes.'
                WHEN v_increase_pct >= 50 THEN 'MEDIUM: Significant slowdown detected. Monitor and consider optimization.'
                WHEN v_increase_pct >= 25 THEN 'LOW: Mild regression. Continue monitoring.'
                ELSE 'No significant regression detected.'
            END;
    ELSE
        RETURN QUERY SELECT false, v_current_avg, v_historical_avg, 0::NUMERIC, 'Insufficient data for regression analysis';
    END IF;
END;
$$;


