--15. Send Push Notification

--Domain:---Mobile Features & Push Notifications  
--Database Object Name:---`send_push_notification`  
--Database Object Type:---Stored Procedure  
--Description:---Sends push notification to user's registered devices. Filters for active devices within notification window, respects quiet hours, and logs delivery attempts. Supports multiple notification types.  
--Business Case:---Critical for mobile user engagement and retention. Provides reliable push notification delivery with quiet hours and device filtering, improving user engagement and mobile experience. Maintains user trust.  
--KPIs / Outputs:--
--`notification_id` --Notification identifier
--`devices_targeted` --Devices targeted
--`devices_sent` --Devices sent to
--`devices_failed` --Devices failed
--`delivery_rate` --Delivery rate percentage

--Feature References:---MOB-01, MOB-02, MOB-03  
--Tables Used:---`mobile_device_tokens`, `push_notifications`, `push_notification_logs`  
--Performance Optimization:--
--Device filtering for efficiency
--Quiet hours respect
--Delivery logging
--Supports fast notification sending


CREATE OR REPLACE FUNCTION public.send_push_notification(
    p_user_id UUID,
    p_notification_type VARCHAR(100),
    p_title TEXT,
    p_body TEXT,
    p_data JSONB DEFAULT '{}'
)
RETURNS JSONB
LANGUAGE plpg
AS $$
DECLARE
    v_notification_id UUID := gen_random_uuid();
    v_device RECORD;
    v_sent_count INTEGER := 0;
    v_failed_count INTEGER := 0;
BEGIN
    ---Get active devices for user within notification window
    FOR v_device IN
        SELECT * FROM vw_active_device_tokens
        WHERE user_id = p_user_id
        AND in_notification_window = true
        ORDER BY is_primary_device DESC, last_activity_at DESC
    LOOP
        BEGIN
            ---Insert log entry as pending
            INSERT INTO push_notification_logs (
                notification_id, user_id, device_token_id,
                notification_type, title, body, data, status,
                sent_at
            ) VALUES (
                v_notification_id, p_user_id, v_device.token_id,
                p_notification_type, p_title, p_body, p_data, 'PENDING',
                NOW()
            );
            
            v_sent_count := v_sent_count + 1;
            
            ---Update device last notification timestamp
            UPDATE mobile_device_tokens
            SET last_notification_sent_at = NOW(),
                updated_at = NOW()
            WHERE token_id = v_device.token_id;
        EXCEPTION
            WHEN OTHERS THEN
                v_failed_count := v_failed_count + 1;
                RAISE WARNING 'Failed to queue notification for device %: %', v_device.token_id, ERRM;
        END;
    END LOOP;
    
    ---Return results
    RETURN jsonb_build_object(
        'notification_id', v_notification_id,
        'devices_targeted', v_sent_count + v_failed_count,
        'devices_sent', v_sent_count,
        'devices_failed', v_failed_count,
        'delivery_rate', ROUND(
            100.0 * v_sent_count / NULLIF(v_sent_count + v_failed_count, 0),
            2
        )
    );
END;
$$;


